//! Vendor rate-limit state applied to the account pool (issue #677).
//!
//! [`crate::account_limits`] decides what a response's unified headers mean;
//! this module applies those decisions to the pool's accounts, persists them,
//! and exposes manual pause/resume.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::time::{Duration, Instant};

use axum::http::HeaderMap;

use super::{AccountError, AccountRouter};
use crate::account_limits::{
    AccountLimitState, LimitScope, Pause, PauseKind, ThresholdDecision, WindowLimit, now_unix,
};

/// The longest a window reading waits to be saved; a cooldown or pause is
/// saved at once.
const LIMITS_SAVE_INTERVAL_SECS: u64 = 60;

/// One upstream response, as the pool needs to see it.
pub struct UpstreamObservation<'a> {
    pub account: &'a str,
    /// The requested model, for model-scoped cooldowns.
    pub model: Option<&'a str>,
    pub status: u16,
    pub headers: &'a HeaderMap,
    /// The (bounded) response body; only read for a rejection's message.
    pub body: &'a [u8],
    /// The parsed `Retry-After`, if any.
    pub retry_after: Option<Duration>,
}

/// What [`AccountRouter::observe_upstream`] did, for logging and metrics.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ObservedLimits {
    /// The whole account was cooled down.
    pub credential_cooldown: bool,
    /// Only this model key was cooled down.
    pub model_cooldown: Option<String>,
    /// A threshold pause began.
    pub paused: bool,
}

/// Pool-wide counts for `/metrics` and `router usage`. Aggregate only: the
/// metrics surface must not name accounts.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct LimitCounts {
    pub cooling_down: usize,
    pub paused: usize,
    pub model_cooldowns: usize,
}

impl LimitCounts {
    /// Pool gauges in Prometheus exposition format. Counts only: `/metrics`
    /// is unauthenticated and must not name accounts.
    #[must_use]
    pub fn render_prometheus(&self) -> String {
        let mut out = String::new();
        for (name, help, value) in [
            (
                "link_assistant_pool_accounts_cooling_down",
                "Pooled accounts currently cooling down.",
                self.cooling_down,
            ),
            (
                "link_assistant_pool_accounts_paused",
                "Pooled accounts paused manually or by ACCOUNT_PAUSE_AT_PERCENT.",
                self.paused,
            ),
            (
                "link_assistant_pool_model_cooldowns",
                "Model-scoped cooldowns active across the pool.",
                self.model_cooldowns,
            ),
        ] {
            let _ = writeln!(
                out,
                "# HELP {name} {help}\n# TYPE {name} gauge\n{name} {value}"
            );
        }
        out
    }
}

impl AccountRouter {
    /// Whether this pool was built with pre-first-byte failover on.
    #[must_use]
    pub fn failover_enabled(&self) -> bool {
        self.inner.failover && !crate::account_policy_scope::active()
    }

    fn account_index(&self, name: &str) -> Option<usize> {
        self.inner.accounts.iter().position(|a| a.name == name)
    }

    /// Load persisted vendor cooldowns and pauses, so a restart neither
    /// forgets a weekly limit nor resumes a manually paused account.
    pub(super) fn restore_limits(&self) {
        let Some(dir) = self.inner.state_dir.as_deref() else {
            return;
        };
        for (name, state) in crate::account_limits::load(dir, self.provider().as_str()) {
            let Some(index) = self.account_index(&name) else {
                continue;
            };
            *self.inner.accounts[index].limits() = state;
        }
    }

    pub(super) fn persist_limits(&self) {
        let Some(dir) = self.inner.state_dir.as_deref() else {
            return;
        };
        let now = now_unix();
        self.inner
            .limits_saved_unix
            .store(now, std::sync::atomic::Ordering::Relaxed);
        let accounts = self
            .inner
            .accounts
            .iter()
            .map(|account| {
                let mut state = account.limits().clone();
                state.expire(now);
                (account.name.clone(), state)
            })
            .collect::<BTreeMap<_, _>>();
        crate::account_limits::save(dir, self.provider().as_str(), &accounts);
    }

    /// Apply what one upstream response said about its account.
    ///
    /// - A `429` cools the account (or one model on it — see
    ///   [`crate::account_limits::classify_scope`]) until the longest rejected
    ///   window resets. Without a usable reset the existing
    ///   `Retry-After`/default cooldown applies. Authentication failures cool the
    ///   entire credential. A served response never cools its account from
    ///   window headers alone: an account drawing
    ///   on paid overage reports `rejected` on answers it still gives.
    /// - Utilization readings drive `ACCOUNT_PAUSE_AT_PERCENT`.
    ///
    /// Every response is observed, `count_tokens` included: it carries the
    /// same headers and is often the first to see a limit.
    pub fn observe_upstream(&self, observed: &UpstreamObservation<'_>) -> ObservedLimits {
        let Some(index) = self.account_index(observed.account) else {
            return ObservedLimits::default();
        };
        if self.inner.accounts[index].uses_unpooled_defaults() {
            return ObservedLimits::default();
        }
        let limits = crate::account_limits::parse_unified(observed.headers);
        let now = now_unix();
        let mut outcome = ObservedLimits::default();
        let relayed = crate::account_policy_scope::current().is_some_and(|s| {
            *s.last_action
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                == Some(crate::account_routing_policy::ErrorAction::Relay)
        });
        let rejected = matches!(observed.status, 401 | 403 | 429)
            && !relayed
            && !self.inner.accounts[index]
                .policy()
                .as_ref()
                .is_ok_and(|p| p.disable_cooling);
        {
            let mut state = self.inner.accounts[index].limits();
            state.expire(now);
            if !limits.windows.is_empty() {
                state.windows.clone_from(&limits.windows);
            }
        }
        if rejected {
            let fallback = observed
                .retry_after
                .map(crate::request_routing::bounded_retry_after)
                .map_or(self.inner.cooldown, |retry| retry.max(self.inner.cooldown))
                .min(self.inner.max_cooldown);
            let until = crate::account_limits::rejected_until(&limits, now)
                .unwrap_or_else(|| now.saturating_add(fallback.as_secs()))
                .min(now.saturating_add(self.inner.max_cooldown.as_secs()));
            let scope = if matches!(observed.status, 401 | 403) {
                LimitScope::Credential
            } else {
                crate::account_limits::classify_scope(&limits, observed.body, observed.model)
            };
            match scope {
                LimitScope::Model(key) => {
                    self.inner.accounts[index].limits().cool_model(&key, until);
                    self.record_error(index, &format!("upstream rate-limited model {key}"));
                    outcome.model_cooldown = Some(key);
                }
                LimitScope::Credential => {
                    let reason = format!("upstream returned {}", observed.status);
                    self.inner.accounts[index]
                        .limits()
                        .cool_credential(until, &reason);
                    self.record_error(index, &reason);
                    outcome.credential_cooldown = true;
                }
            }
            tracing::debug!(
                account = observed.account,
                model = observed.model,
                until,
                credential_cooldown = outcome.credential_cooldown,
                "observed upstream cooldown"
            );
        }
        outcome.paused = self.apply_threshold(index, &limits.windows, now);
        let readings_due = !limits.windows.is_empty()
            && now
                >= self
                    .inner
                    .limits_saved_unix
                    .load(std::sync::atomic::Ordering::Relaxed)
                    .saturating_add(LIMITS_SAVE_INTERVAL_SECS);
        if rejected || outcome.paused || readings_due {
            self.persist_limits();
        }
        outcome
    }

    /// Feed one account's windows from a usage probe (`router usage`) into the
    /// threshold pause. `used_percentage` arrives as a percent, `resets_at` as
    /// an RFC 3339 time.
    pub fn observe_usage_windows(&self, account: &str, windows: &[WindowLimit]) {
        let Some(index) = self.account_index(account) else {
            return;
        };
        if self.apply_threshold(index, windows, now_unix()) {
            self.persist_limits();
        }
    }

    /// Returns whether a threshold pause began or ended.
    fn apply_threshold(&self, index: usize, windows: &[WindowLimit], now: u64) -> bool {
        let Some(percent) = self.inner.pause_at_percent else {
            return false;
        };
        let mut state = self.inner.accounts[index].limits();
        match crate::account_limits::threshold_decision(windows, percent, now) {
            ThresholdDecision::Pause { until_unix, window } => {
                // A manual pause outranks a threshold one.
                if state
                    .pause
                    .as_ref()
                    .is_some_and(|pause| pause.kind == PauseKind::Manual)
                {
                    return false;
                }
                let changed = state
                    .pause
                    .as_ref()
                    .is_none_or(|pause| pause.until_unix != Some(until_unix));
                state.pause = Some(Pause {
                    kind: PauseKind::Threshold,
                    until_unix: Some(until_unix),
                    reason: format!("{window} window at or above {percent}%"),
                });
                changed
            }
            ThresholdDecision::Clear
                if state
                    .pause
                    .as_ref()
                    .is_some_and(|pause| pause.kind == PauseKind::Threshold) =>
            {
                state.pause = None;
                true
            }
            ThresholdDecision::Clear | ThresholdDecision::Ignore => false,
        }
    }

    /// Pause an account by hand. `until_unix` of `None` lasts until
    /// [`Self::resume`].
    pub fn pause(
        &self,
        account: &str,
        until_unix: Option<u64>,
        reason: &str,
    ) -> Result<(), AccountError> {
        let index = self
            .account_index(account)
            .ok_or_else(|| AccountError::UnknownAccount(account.to_string()))?;
        self.inner.accounts[index].limits().pause = Some(Pause {
            kind: PauseKind::Manual,
            until_unix,
            reason: reason.to_string(),
        });
        self.persist_limits();
        Ok(())
    }

    /// Lift a manual or threshold pause. Returns whether one was active.
    pub fn resume(&self, account: &str) -> Result<bool, AccountError> {
        let index = self
            .account_index(account)
            .ok_or_else(|| AccountError::UnknownAccount(account.to_string()))?;
        let was_paused = self.inner.accounts[index].limits().pause.take().is_some();
        self.persist_limits();
        Ok(was_paused)
    }

    /// The current vendor-limit state of every account, expired entries
    /// dropped.
    #[must_use]
    pub fn limit_states(&self) -> Vec<(String, AccountLimitState)> {
        let now = now_unix();
        self.inner
            .accounts
            .iter()
            .map(|account| {
                let mut state = account.limits().clone();
                state.expire(now);
                (account.name.clone(), state)
            })
            .collect()
    }

    /// Aggregate counts for metrics and the usage pool.
    #[must_use]
    pub fn limit_counts(&self) -> LimitCounts {
        let now = now_unix();
        let mut counts = LimitCounts::default();
        for account in &self.inner.accounts {
            let mut state = account.limits().clone();
            state.expire(now);
            let cooling = account
                .cooldown_until
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .is_some_and(|until| until > Instant::now());
            counts.cooling_down +=
                usize::from(cooling || state.cooldown_until_unix.is_some_and(|until| until > now));
            counts.paused += usize::from(state.paused_at(now));
            counts.model_cooldowns += state.model_cooldowns.len();
        }
        counts
    }
}

//! Mutable pool policy and cooldown controls.

use super::{
    AccountError, AccountRouter, Duration, Instant, Ordering, RoutingContext, SelectionStrategy,
};

impl SelectionStrategy {
    /// Canonical name accepted by the configuration and management API.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::RoundRobin => "round-robin",
            Self::Priority => "fill-first",
            Self::LeastUsed => "least-used",
            Self::WeightedRoundRobin => "weighted-round-robin",
        }
    }
}

impl AccountRouter {
    /// Current selection policy for unbound sessions.
    #[must_use]
    pub fn strategy(&self) -> SelectionStrategy {
        *self
            .inner
            .strategy
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    /// Change the policy for new sessions, preserving all existing bindings.
    pub fn set_strategy(&self, strategy: SelectionStrategy) -> SelectionStrategy {
        let mut current = self
            .inner
            .strategy
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        std::mem::replace(&mut *current, strategy)
    }

    pub(super) fn context_account(&self, context: &RoutingContext) -> Option<usize> {
        context
            .session_key
            .as_deref()
            .and_then(|session| self.bound_account(session))
            .or_else(|| {
                self.inner
                    .session_affinity_subagents
                    .then(|| {
                        context
                            .parent_session_key
                            .as_deref()
                            .and_then(|parent| self.bound_account(parent))
                    })
                    .flatten()
            })
    }

    /// Configured bounds for pre-first-byte retry rounds.
    #[must_use]
    pub fn retry_policy(&self) -> crate::pool_retry::RetryPolicy {
        self.inner.retry
    }

    /// Remove cooldowns without modifying usage counts, pauses or credentials.
    /// With `model`, only an exact model/family key is removed.
    pub fn reset_cooldowns(
        &self,
        account: Option<&str>,
        model: Option<&str>,
    ) -> Result<usize, AccountError> {
        if let Some(name) = account
            && !self
                .inner
                .accounts
                .iter()
                .any(|candidate| candidate.name == name)
        {
            return Err(AccountError::UnknownAccount(name.into()));
        }
        let mut cleared = 0;
        for candidate in &self.inner.accounts {
            if account.is_some_and(|name| candidate.name != name) {
                continue;
            }
            let mut timer = candidate
                .cooldown_until
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let mut state = candidate.limits();
            state.expire(crate::account_limits::now_unix());
            if let Some(model) = model {
                cleared += usize::from(
                    state
                        .model_cooldowns
                        .remove(&model.to_ascii_lowercase())
                        .is_some(),
                );
            } else {
                let active_timer = timer.is_some_and(|until| until > Instant::now());
                cleared += usize::from(state.cooldown_until_unix.is_some() || active_timer)
                    + state.model_cooldowns.len();
                *timer = None;
                drop(timer);
                state.cooldown_until_unix = None;
                state.cooldown_reason = None;
                state.model_cooldowns.clear();
            }
        }
        self.persist_limits();
        Ok(cleared)
    }

    /// Earliest eligible recovery, ignoring this round's tried credentials.
    /// Manual pauses and exhausted request caps have no timed recovery.
    pub(crate) fn retry_delay(&self, context: &RoutingContext) -> Option<Duration> {
        let now = crate::account_limits::now_unix();
        let scoped = crate::account_policy_scope::current();
        self.inner
            .accounts
            .iter()
            .filter_map(|account| {
                if context
                    .pinned_account
                    .as_deref()
                    .is_some_and(|pin| account.name != pin)
                    || account
                        .request_limit
                        .is_some_and(|limit| account.used.load(Ordering::Relaxed) >= limit)
                    || !account
                        .credential_state_with(
                            crate::operation_context::now().timestamp_millis(),
                            None,
                        )
                        .can_serve()
                {
                    return None;
                }
                let timer = account
                    .cooldown_until
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .and_then(|until| until.checked_duration_since(Instant::now()))
                    .unwrap_or_default();
                let model = scoped
                    .as_ref()
                    .map(|scope| scope.upstream_model.clone())
                    .or_else(|| {
                        context
                            .model
                            .as_deref()
                            .and_then(|model| self.upstream_model(&account.name, model))
                    });
                let state = account.limits();
                let mut until = state.cooldown_until_unix.unwrap_or(now);
                if let Some(pause) = &state.pause {
                    until = until.max(pause.until_unix?);
                }
                if let Some(model) = model.as_deref() {
                    for (key, deadline) in &state.model_cooldowns {
                        if crate::account_limits::model_key_matches(key, model) {
                            until = until.max(*deadline);
                        }
                    }
                }
                Some(timer.max(Duration::from_secs(until.saturating_sub(now))))
            })
            .min()
    }
}

//! Policy access, persistence and model eligibility for an account pool.
use super::{AccountRouter, RoutingContext, SelectionStrategy};
use crate::account_routing_policy::AccountRoutingPolicy;

impl AccountRouter {
    /// Keep the legacy single-account request defaults until a policy opts in.
    pub(crate) fn retain_unpooled_defaults(&mut self) {
        let inner = std::sync::Arc::get_mut(&mut self.inner).expect("new primary pool is unshared");
        debug_assert_eq!(inner.accounts.len(), 1);
        inner.accounts[0].implicit_primary = true;
    }

    /// Whether this pool needs opt-in request policy processing.
    #[must_use]
    pub fn has_routing_policy(&self) -> bool {
        self.inner.force_model_prefix
            || self.strategy() == SelectionStrategy::WeightedRoundRobin
            || self.inner.accounts.iter().any(|a| {
                a.policy()
                    .as_ref()
                    .ok()
                    .is_none_or(|p| *p != AccountRoutingPolicy::default())
            })
    }

    /// Return the policy for a named account. Malformed files are never silently defaulted.
    pub fn routing_policy(&self, account: &str) -> Result<AccountRoutingPolicy, String> {
        let account = self
            .inner
            .accounts
            .iter()
            .find(|a| a.name == account)
            .ok_or_else(|| format!("unknown account {account}"))?;
        account.policy().clone()
    }

    /// Validate, atomically persist and immediately install a complete replacement policy.
    pub fn set_routing_policy(
        &self,
        account: &str,
        policy: AccountRoutingPolicy,
    ) -> Result<(), String> {
        let account = self
            .inner
            .accounts
            .iter()
            .find(|a| a.name == account)
            .ok_or_else(|| format!("unknown account {account}"))?;
        // Selection takes weights before reading policies; updates use the same lock order.
        let mut weights = self
            .inner
            .weights
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if policy.prefix.as_ref().is_some_and(|prefix| {
            self.inner.accounts.iter().any(|other| {
                other.name != account.name
                    && other
                        .policy()
                        .as_ref()
                        .is_ok_and(|p| p.prefix.as_ref() == Some(prefix))
            })
        }) {
            return Err("model prefixes must be unique within the account pool".into());
        }
        let mut current = account
            .routing_policy
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        policy.save(&account.home)?;
        *current = Ok(policy);
        drop(current);
        weights.fill(0);
        drop(weights);
        Ok(())
    }

    pub(crate) fn inner_failover_enabled(&self) -> bool {
        self.inner.failover
    }

    pub(crate) fn serves_upstream_model(&self, name: &str, model: &str) -> bool {
        self.inner
            .accounts
            .iter()
            .find(|a| a.name == name)
            .is_some_and(|a| {
                a.serves(&RoutingContext {
                    model: Some(model.to_string()),
                    ..RoutingContext::default()
                })
            })
    }

    /// Whether unprefixed requests exclude accounts with a configured prefix.
    #[must_use]
    pub fn force_model_prefix(&self) -> bool {
        self.inner.force_model_prefix
    }

    /// Resolve one account's client-facing model, enforcing exclusive prefix routing.
    #[must_use]
    pub fn upstream_model(&self, account: &str, model: &str) -> Option<String> {
        let policy = self.routing_policy(account).ok()?;
        let selected_prefix = self.inner.accounts.iter().find_map(|a| {
            let policy = a.policy();
            let prefix = policy.as_ref().ok()?.prefix.clone()?;
            drop(policy);
            model.strip_prefix(&format!("{prefix}/")).map(|_| prefix)
        });
        if selected_prefix.as_ref().is_some_and(|prefix| {
            self.inner
                .accounts
                .iter()
                .filter(|a| {
                    a.policy()
                        .as_ref()
                        .is_ok_and(|p| p.prefix.as_ref() == Some(prefix))
                })
                .count()
                > 1
        }) {
            return None;
        }
        if selected_prefix
            .as_ref()
            .is_some_and(|prefix| policy.prefix.as_ref() != Some(prefix))
        {
            return None;
        }
        policy.resolve_model(model, self.inner.force_model_prefix)
    }

    pub(super) fn policy_serves(&self, index: usize, context: &RoutingContext) -> bool {
        let account = &self.inner.accounts[index];
        let Ok(policy) = account.policy().clone() else {
            return false;
        };
        if self.strategy() == SelectionStrategy::WeightedRoundRobin && policy.weight <= 0 {
            return false;
        }
        let scoped = crate::account_policy_scope::current();
        let model = scoped
            .as_ref()
            .and_then(|s| s.context.model.as_deref())
            .or(context.model.as_deref());
        model.is_none_or(|model| {
            self.upstream_model(&account.name, model)
                .is_some_and(|upstream| {
                    account.ignores_automatic_cooling()
                        || !account
                            .limits()
                            .blocks_model(&upstream, crate::account_limits::now_unix())
                })
        })
    }
}

//! Selection order and session affinity for the account pool.
use super::{
    AccountError, AccountRouter, AccountState, AffinityBinding, Instant, Ordering, RoutingContext,
    SelectionMode, SelectionStrategy,
};
use std::cmp::Ordering as CmpOrdering;

impl AccountRouter {
    pub(super) fn selection_plan(
        &self,
        context: &RoutingContext,
        allowed: &impl Fn(&str) -> bool,
    ) -> Result<(Vec<usize>, SelectionMode), AccountError> {
        if self.inner.accounts.is_empty() {
            return Err(AccountError::NoAccountsConfigured);
        }
        let scoped = crate::account_policy_scope::preselected(context);
        if let Some(pin) = context.pinned_account.as_deref().or(scoped.as_deref()) {
            let Some(index) = self.inner.accounts.iter().position(|a| a.name == pin) else {
                return Err(AccountError::UnknownPinnedAccount(pin.to_string()));
            };
            // A token-pinned account never falls back, failover or not.
            if context.exclude.iter().any(|tried| tried == pin) {
                return Err(AccountError::PinnedAccountUnavailable(pin.to_string()));
            }
            return Ok((vec![index], SelectionMode::Pinned));
        }
        if let Some(index) = self.context_account(context) {
            self.bind_session(context, index);
            if (!self.inner.failover && !self.has_routing_policy())
                || (self.inner.accounts[index].serves(context)
                    && self.policy_serves(index, context)
                    && allowed(&self.inner.accounts[index].name))
            {
                return Ok((vec![index], SelectionMode::Session));
            }
            // Failover: serve the session elsewhere for now, but keep (and
            // refresh) its binding so it returns once the account recovers.
            self.bind_session(context, index);
            return Ok((self.failover_order(Some(index)), SelectionMode::Detour));
        }
        if !context.exclude.is_empty() {
            return Ok((self.failover_order(None), SelectionMode::Automatic));
        }
        let mut indices: Vec<usize> = (0..self.inner.accounts.len()).collect();
        match self.strategy() {
            SelectionStrategy::RoundRobin => {
                let start = self.inner.cursor.fetch_add(1, Ordering::Relaxed) % indices.len();
                indices.rotate_left(start);
            }
            SelectionStrategy::WeightedRoundRobin => {
                indices.retain(|index| {
                    self.inner.accounts[*index].serves(context)
                        && self.policy_serves(*index, context)
                        && allowed(&self.inner.accounts[*index].name)
                });
                let mut current = self
                    .inner
                    .weights
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                for (index, value) in current.iter_mut().enumerate() {
                    if !indices.contains(&index) {
                        *value = 0;
                    }
                }
                let mut total = 0_i64;
                for index in &indices {
                    let weight = self.inner.accounts[*index]
                        .policy()
                        .as_ref()
                        .map_or(0, |p| i64::from(p.weight.max(0)));
                    current[*index] = current[*index].saturating_add(weight);
                    total = total.saturating_add(weight);
                }
                if let Some(position) = indices
                    .iter()
                    .enumerate()
                    .max_by_key(|(position, index)| {
                        (current[**index], std::cmp::Reverse(*position))
                    })
                    .map(|(position, _)| position)
                {
                    current[indices[position]] = current[indices[position]].saturating_sub(total);
                    indices.rotate_left(position);
                }
                drop(current);
            }
            SelectionStrategy::Priority => {}
            SelectionStrategy::LeastUsed => indices.sort_by(|left, right| {
                Self::compare_usage(&self.inner.accounts[*left], &self.inner.accounts[*right])
            }),
        }
        Ok((indices, SelectionMode::Automatic))
    }

    /// Failover candidates, rotated by a dedicated cursor so concurrent
    /// failovers from one account spread across the others instead of all
    /// landing on the next one in priority order.
    fn failover_order(&self, skip: Option<usize>) -> Vec<usize> {
        let mut indices: Vec<usize> = (0..self.inner.accounts.len())
            .filter(|index| Some(*index) != skip)
            .collect();
        if !indices.is_empty() {
            let start = self.inner.failover_cursor.fetch_add(1, Ordering::Relaxed) % indices.len();
            indices.rotate_left(start);
        }
        indices
    }

    /// The account a session is currently bound to, if any.
    #[must_use]
    pub fn session_account(&self, context: &RoutingContext) -> Option<String> {
        let index = self.context_account(context)?;
        Some(self.inner.accounts[index].name.clone())
    }

    pub(super) fn bind_selected(
        &self,
        context: &RoutingContext,
        mode: SelectionMode,
        index: usize,
    ) {
        if !matches!(mode, SelectionMode::Detour) {
            self.bind_session(context, index);
        }
    }

    fn compare_usage(left: &AccountState, right: &AccountState) -> CmpOrdering {
        let left_used = left.used.load(Ordering::Relaxed);
        let right_used = right.used.load(Ordering::Relaxed);
        match (left.request_limit, right.request_limit) {
            (Some(left_limit), Some(right_limit)) => left_used
                .saturating_mul(right_limit)
                .cmp(&right_used.saturating_mul(left_limit))
                .then_with(|| left_used.cmp(&right_used)),
            // Prefer measurable quota headroom; unknown quotas remain eligible
            // as a fallback instead of being treated as unlimited.
            (Some(_), None) => CmpOrdering::Less,
            (None, Some(_)) => CmpOrdering::Greater,
            (None, None) => left_used.cmp(&right_used),
        }
    }

    pub(super) fn bound_account(&self, session: &str) -> Option<usize> {
        if self.inner.session_affinity_ttl.is_zero() {
            return None;
        }
        let now = Instant::now();
        let mut affinities = self
            .inner
            .affinities
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        affinities.retain(|_, binding| binding.expires_at > now);
        affinities.get(session).map(|binding| binding.account_index)
    }

    pub(super) fn bind_session(&self, context: &RoutingContext, account_index: usize) {
        let Some(session) = context.session_key.as_ref() else {
            return;
        };
        if self.inner.session_affinity_ttl.is_zero() {
            return;
        }
        let mut affinities = self
            .inner
            .affinities
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        affinities.insert(
            session.clone(),
            AffinityBinding {
                account_index,
                expires_at: Instant::now() + self.inner.session_affinity_ttl,
            },
        );
    }

    pub(super) fn unavailable_error(mode: SelectionMode, account: &str) -> AccountError {
        match mode {
            SelectionMode::Pinned => AccountError::PinnedAccountUnavailable(account.to_string()),
            SelectionMode::Session => AccountError::SessionAccountUnavailable(account.to_string()),
            SelectionMode::Automatic | SelectionMode::Detour => AccountError::NoHealthyAccounts,
        }
    }
}

//! The `accounts` subcommand: report what each configured account can do.
//!
//! Split from `main.rs` to keep that file within the repository's 1000-line
//! limit, and kept in the library so the remote form renders through the same
//! printer — an operator reading a table has no way to tell which machine
//! answered, so the two must not be able to drift (issues #294, #306).

use std::process::ExitCode;

use crate::accounts::AccountRouter;
use crate::cli::AccountOp;

/// Render the account pool.
///
/// `credential` is printed beside `healthy` so an operator can see *why* an
/// account is unhealthy without running `doctor`, which was the contradiction
/// issue #242 reported: `accounts list` said `healthy true` while `doctor`
/// said EXPIRED and every request returned 401.
#[must_use]
pub fn run(
    router: &AccountRouter,
    refreshes: crate::translation_core::Maybe<&crate::refresh::TokenCache>,
    op: &AccountOp,
) -> ExitCode {
    match op {
        AccountOp::Policy { name, file, .. } => {
            let result = (|| {
                if let Some(path) = file {
                    router.set_routing_policy(name, read_policy(path)?)?;
                    println!("{LOCAL_NOTE}");
                }
                let policy = router.routing_policy(name)?;
                crate::operation_output::report(&policy);
                println!(
                    "{}",
                    serde_json::to_string_pretty(&policy).map_err(|e| e.to_string())?
                );
                Ok::<_, String>(())
            })();
            match result {
                Ok(()) => ExitCode::SUCCESS,
                Err(error) => {
                    eprintln!("error: {error}");
                    ExitCode::from(1)
                }
            }
        }
        AccountOp::List { json, .. } if *json => {
            let rows: Vec<serde_json::Value> = router
                .health_snapshot_with(refreshes)
                .into_iter()
                .map(|health| {
                    let mut value = serde_json::json!({
                        "name": health.name,
                        "healthy": health.healthy,
                        "credential": health.credential.label(),
                        "used": health.used,
                        "request_limit": health.request_limit,
                        "remaining_requests": health.remaining_requests,
                        "home": health.home.display().to_string(),
                        // Vendor rate-limit state (issue #677).
                        "cooldown_reason": health.limits.cooldown_reason,
                        "cooldown_until_unix": health.limits.cooldown_until_unix,
                        "model_cooldowns": health.limits.model_cooldowns,
                        "paused": health.limits.paused_at(crate::account_limits::now_unix()),
                        "pause": health.limits.pause,
                        "windows": health.limits.windows,
                    });
                    value.as_object_mut().expect("account object").extend(
                        crate::account_policy_management::fields(router, &health.name)
                            .as_object()
                            .unwrap()
                            .clone(),
                    );
                    value
                })
                .collect();
            println!(
                "{}",
                serde_json::to_string_pretty(&rows).unwrap_or_else(|_| "[]".to_string())
            );
            ExitCode::SUCCESS
        }
        AccountOp::List { .. } => {
            println!("{}", header());
            for health in router.health_snapshot_with(refreshes) {
                println!(
                    "{}",
                    row(&AccountRow {
                        name: &health.name,
                        healthy: Some(health.healthy),
                        credential: health.credential.label(),
                        used: Some(health.used as u64),
                        limit: health.request_limit.map(|value| value as u64),
                        remaining: health.remaining_requests.map(|value| value as u64),
                        home: health.home.display().to_string(),
                    })
                );
            }
            ExitCode::SUCCESS
        }
        AccountOp::Pause {
            name,
            reason,
            until,
            ..
        } => {
            let reason = reason.as_deref().unwrap_or(DEFAULT_PAUSE_REASON);
            match router.pause(name, *until, reason) {
                Ok(()) => {
                    println!("{}", pause_message(name, *until));
                    println!("{LOCAL_NOTE}");
                    ExitCode::SUCCESS
                }
                Err(error) => {
                    eprintln!("error: {error}");
                    ExitCode::from(1)
                }
            }
        }
        AccountOp::Resume { name, .. } => match router.resume(name) {
            Ok(was_paused) => {
                println!("{}", resume_message(name, was_paused));
                println!("{LOCAL_NOTE}");
                ExitCode::SUCCESS
            }
            Err(error) => {
                eprintln!("error: {error}");
                ExitCode::from(1)
            }
        },
    }
}

/// The reason recorded when the operator gives none; the management API uses
/// the same words.
const DEFAULT_PAUSE_REASON: &crate::translation_core::Str = "paused by an operator";

/// The local form edits the persisted pool state, not a running process.
const LOCAL_NOTE: &crate::translation_core::Str = "note: recorded in this machine's data directory; a router started \
     from it applies the change at startup. Pass --server <URL> to change a running router.";

fn pause_message(name: &crate::translation_core::Str, until: crate::translation_core::Maybe<u64>) -> crate::translation_core::Text {
    until.map_or_else(
        || crate::translation_core::format!("paused {name} until it is resumed"),
        |until| {
            let when =
                chrono::DateTime::from_timestamp(i64::try_from(until).unwrap_or(i64::MAX), 0)
                    .map_or_else(|| until.to_string(), |time| time.to_rfc3339());
            crate::translation_core::format!("paused {name} until {when}")
        },
    )
}

fn resume_message(name: &crate::translation_core::Str, was_paused: bool) -> crate::translation_core::Text {
    if was_paused {
        crate::translation_core::format!("resumed {name}")
    } else {
        crate::translation_core::format!("{name} was not paused")
    }
}

/// The account-name placeholder in the pause/resume route templates.
const NAME_PLACEHOLDER: &crate::translation_core::Str = concat!("{", "name", "}");

/// Percent-encode an account name for one URL path segment, so a name can
/// never reach a different route.
fn path_segment(name: &crate::translation_core::Str) -> String {
    use std::fmt::Write as _;

    let mut encoded = String::with_capacity(name.len());
    for byte in name.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            encoded.push(char::from(byte));
        } else {
            let _ = write!(encoded, "%{byte:02X}");
        }
    }
    encoded
}

/// Run an `accounts` operation against a selected router over its admin API
/// (issues #294, #677).
pub async fn run_remote(
    server: &crate::managed_server::ResolvedServer,
    op: &AccountOp,
) -> ExitCode {
    use crate::route_contract::{RouteId, route_template};

    if let AccountOp::Policy { name, file, .. } = op {
        let path =
            route_template(RouteId::AccountPolicy).replace(NAME_PLACEHOLDER, &path_segment(name));
        let result = if let Some(file) = file {
            match read_policy(file) {
                Ok(policy) => {
                    crate::auth_remote::post(
                        server,
                        &path,
                        serde_json::to_value(policy).expect("policy JSON"),
                    )
                    .await
                }
                Err(error) => Err(error),
            }
        } else {
            crate::auth_remote::get(server, &path).await
        };
        return match result {
            Ok(policy) => {
                crate::operation_output::record(policy.clone());
                println!(
                    "{}",
                    serde_json::to_string_pretty(&policy).expect("policy JSON")
                );
                ExitCode::SUCCESS
            }
            Err(error) => {
                eprintln!("error: {error}");
                ExitCode::from(1)
            }
        };
    }
    let (route, name, body) = match op {
        AccountOp::Policy { .. } => unreachable!("handled above"),
        AccountOp::List { .. } => return crate::auth_remote::accounts(server).await,
        AccountOp::Pause {
            name,
            reason,
            until,
            ..
        } => (
            RouteId::AccountPause,
            name,
            serde_json::json!({
                "reason": reason.as_deref().unwrap_or(DEFAULT_PAUSE_REASON),
                "until_unix": until,
            }),
        ),
        AccountOp::Resume { name, .. } => (RouteId::AccountResume, name, serde_json::json!({})),
    };
    let path = route_template(route).replace(NAME_PLACEHOLDER, &path_segment(name));
    match crate::auth_remote::post(server, &path, body).await {
        Ok(answer) => {
            println!("server: {} ({})", server.base_url, server.source);
            let message = match op {
                AccountOp::Pause { .. } => pause_message(
                    name,
                    answer.get("until_unix").and_then(serde_json::Value::as_u64),
                ),
                _ => resume_message(
                    name,
                    answer
                        .get("was_paused")
                        .and_then(serde_json::Value::as_bool)
                        .unwrap_or(true),
                ),
            };
            println!("{message}");
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

/// One account, from either the local pool or a remote router's JSON.
///
/// `None` means the answer is genuinely absent. That distinction is the point:
/// the remote formatter read every field with `as_str()`, so a JSON *number*
/// yielded the same `-` as a field the server never sent, and the table could
/// not show a figure at all (issue #306).
pub struct AccountRow<'a> {
    pub name: &'a str,
    pub healthy: Option<bool>,
    pub credential: &'a str,
    pub used: Option<u64>,
    pub limit: Option<u64>,
    pub remaining: Option<u64>,
    pub home: String,
}

/// The column titles, shared by both modes.
///
/// One printer for both paths, for the reason issue #294 gave for `tokens` and
/// `providers`: an operator reading a table has no way to tell which machine
/// answered, so the two must not be able to drift. The remote form rendered
/// three of these eight columns — dropping `healthy`, which is the one the
/// command exists to answer (issue #306).
#[must_use]
pub fn header() -> crate::translation_core::Text {
    crate::translation_core::format!(
        "{:<16}  {:<8}  {:<12}  {:<6}  {:<9}  {:<9}  home",
        "name", "healthy", "credential", "used", "limit", "remaining"
    )
}

/// One rendered row, in the columns [`header`] names.
#[must_use]
pub fn row(account: &AccountRow<'_>) -> crate::translation_core::Text {
    let optional =
        |value: Option<u64>| value.map_or_else(|| "-".to_string(), |value| value.to_string());
    crate::translation_core::format!(
        "{:<16}  {:<8}  {:<12}  {:<6}  {:<9}  {:<9}  {}",
        account.name,
        account
            .healthy
            .map_or_else(|| "-".to_string(), |healthy| healthy.to_string()),
        account.credential,
        optional(account.used),
        optional(account.limit),
        optional(account.remaining),
        account.home
    )
}

fn read_policy(
    path: &std::path::Path,
) -> crate::translation_core::Outcome<crate::account_routing_policy::AccountRoutingPolicy, String> {
    let bytes = std::fs::read(path).map_err(|e| e.to_string())?;
    let policy: crate::account_routing_policy::AccountRoutingPolicy =
        serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
    policy.validate()?;
    Ok(policy)
}

