//! HTTP surface of the admin UI: the bootstrap claim, credential rotation,
//! and read-only status, plus the router that serves them on the dedicated
//! admin port.
//!
//! Everything under `/api/management` except the three bootstrap routes requires
//! the admin credential. The bootstrap routes carry their own rules — see
//! [`crate::admin`] for the two-phase claim protocol.

// The handlers here are `async fn` to match axum's handler signature even when
// their bodies are synchronous. Mirrors the same allow in `crate::proxy`.
#![allow(clippy::unused_async)]

use std::sync::Arc;

use axum::Router;
use axum::extract::State;
use axum::http::{HeaderMap, StatusCode};
use axum::middleware::{from_fn, from_fn_with_state};
use axum::response::{IntoResponse, Response};

use crate::admin::{AdminClaim, ClaimError};
use crate::proxy::{AppState, error_response};
use crate::route_contract::{RouteId, route_template};

/// Build the admin-port router: the bootstrap/status API, the admin-only
/// management API, and the embedded React UI.
pub fn router(state: AppState) -> Router {
    let login_enabled = state.login_manager.is_enabled();
    router_with_features(state, login_enabled, true)
}

/// Build the admin UI listener with the same feature switches as the public
/// listener. Both listener shapes consume the same management-route builder.
pub fn router_with_config(state: AppState, config: &crate::config::Config) -> Router {
    state.admin.management_access().configure(config.management);
    router_with_features(state, config.login.enabled, config.enable_metrics)
}

fn router_with_features(state: AppState, login_enabled: bool, metrics_enabled: bool) -> Router {
    crate::server_router::management_routes(state.clone(), login_enabled, metrics_enabled)
        .fallback(crate::admin_ui::serve_asset)
        .layer(from_fn_with_state(
            (state.clone(), true),
            crate::management_middleware::gate,
        ))
        // Outermost, so the UI assets and the error responses of the auth
        // middleware are hardened too — see [`crate::security_headers`].
        .layer(from_fn(crate::security_headers::apply))
        .with_state(state)
}

fn bearer(headers: &HeaderMap) -> Option<&str> {
    headers
        .get("authorization")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
}

/// `GET /api/management/admin/status` — is admin claimed, and may bootstrap run?
pub async fn admin_status(State(state): State<AppState>) -> impl IntoResponse {
    (StatusCode::OK, axum::Json(state.admin.status())).into_response()
}

/// `POST /api/management/admin/bootstrap` — phase 1 of the claim.
///
/// Mints a candidate admin JWT. Bootstrap stays **open**: the token is minted
/// revoked, so it is not valid for anything until the client confirms it.
///
/// An optional `{"ttl_hours": n}` body lets the first administrator choose the
/// credential lifetime; it is clamped to
/// [`crate::admin::DEFAULT_CLAIM_TTL_HOURS`].
pub async fn bootstrap(
    State(state): State<AppState>,
    body: Option<axum::Json<TtlRequest>>,
) -> impl IntoResponse {
    let ttl_hours = body.and_then(|axum::Json(request)| request.ttl_hours);
    match state.admin.begin_with_ttl(ttl_hours) {
        Ok(candidate) => (
            StatusCode::OK,
            axum::Json(serde_json::json!({
                "claim_id": candidate.claim_id,
                "token": candidate.token,
                "expires_in_secs": candidate.expires_in_secs,
                "ttl_hours": candidate.ttl_hours,
                "confirm_url": route_template(RouteId::AdminBootstrapConfirm),
            })),
        )
            .into_response(),
        Err(e) => claim_error_response(e),
    }
}

/// `POST /api/management/admin/bootstrap/confirm` — phase 2 of the claim.
///
/// The request must be authenticated with the candidate token itself; that is
/// the proof the client stored it. Only this call closes bootstrap.
pub async fn bootstrap_confirm(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(req): axum::Json<ConfirmRequest>,
) -> impl IntoResponse {
    let Some(token) = bearer(&headers) else {
        return error_response(
            StatusCode::UNAUTHORIZED,
            "authentication_error",
            "confirm must present the candidate token as a Bearer credential",
        );
    };
    match state.admin.confirm(&req.claim_id, token) {
        Ok(()) => (
            StatusCode::OK,
            axum::Json(serde_json::json!({"claimed": true})),
        )
            .into_response(),
        Err(e) => claim_error_response(e),
    }
}

/// `POST /api/management/admin/rotate` — issue a replacement admin credential and retire
/// the current one. Requires the current credential.
pub async fn rotate_credential(
    State(state): State<AppState>,
    body: Option<axum::Json<TtlRequest>>,
) -> impl IntoResponse {
    let ttl_hours = body.and_then(|axum::Json(request)| request.ttl_hours);
    match state.admin.rotate_with_ttl(ttl_hours) {
        Ok(token) => {
            let status = state.admin.status();
            (
                StatusCode::OK,
                axum::Json(serde_json::json!({
                    "token": token,
                    "token_id": status.token_id,
                    "credential_kind": status.credential_kind,
                })),
            )
                .into_response()
        }
        Err(e) => claim_error_response(e),
    }
}

/// Optional body carrying an administrator-chosen credential lifetime.
#[derive(Debug, Default, serde::Deserialize, schemars::JsonSchema)]
pub struct TtlRequest {
    /// Requested lifetime in hours; clamped by the claim.
    #[serde(default)]
    pub ttl_hours: Option<i64>,
}

/// `GET /api/management/admin/summary` — `doctor`-style read-only view of what the router
/// is wired to. Requires the admin credential.
pub async fn admin_summary(State(state): State<AppState>) -> impl IntoResponse {
    let accounts = state
        .account_router
        .as_ref()
        .map_or(0, crate::accounts::AccountRouter::len);
    let credential = state
        .oauth_provider
        .discover_credential_path()
        .map(|path| path.display().to_string());
    let subscription = state.subscription_reader.as_ref().map(|reader| {
        serde_json::json!({
            "home": reader.home().display().to_string(),
            "credential_found": reader.discover_credential_path().is_some(),
        })
    });
    let admin_status = state.admin.status();
    (
        StatusCode::OK,
        axum::Json(serde_json::json!({
            "version": crate::VERSION,
            "upstream_provider": state.upstream_provider.as_str(),
            "upstream_base_url": state.upstream_base_url,
            "accounts": accounts,
            "claude_credential": credential,
            "subscription": subscription,
            "login_api_enabled": state.login_manager.is_enabled(),
            "admin": admin_status,
            "management_bans": state.admin.management_access().active_bans(),
            "emergency_auth": state.token_manager.emergency().status(),
        })),
    )
        .into_response()
}

/// Map a claim-protocol failure onto an HTTP response.
///
/// `409 Conflict` is used for "already claimed" so a client can tell a closed
/// bootstrap apart from a bad credential (`401`).
fn claim_error_response(error: ClaimError) -> Response {
    let (status, kind) = match error {
        ClaimError::AlreadyClaimed | ClaimError::ProvisionedByEnvironment => {
            (StatusCode::CONFLICT, "already_claimed")
        }
        ClaimError::NoCandidate | ClaimError::ClaimIdMismatch => {
            (StatusCode::BAD_REQUEST, "invalid_request_error")
        }
        ClaimError::TokenMismatch => (StatusCode::UNAUTHORIZED, "authentication_error"),
        ClaimError::Storage => (StatusCode::INTERNAL_SERVER_ERROR, "api_error"),
    };
    error_response(status, kind, &error.to_string())
}

/// Body of `POST /api/management/admin/bootstrap/confirm`.
#[derive(serde::Deserialize, schemars::JsonSchema)]
pub struct ConfirmRequest {
    /// The `claim_id` returned by the mint call.
    pub claim_id: String,
}

/// Convenience accessor used by `main` when starting the admin listener.
#[must_use]
pub fn admin_handle(state: &AppState) -> Arc<AdminClaim> {
    Arc::clone(&state.admin)
}

//! Authorisation decision for the administrative endpoints.
//!
//! Kept separate from [`crate::proxy`] so the rule can be exercised directly by
//! unit tests without standing up an [`crate::app_state::AppState`], and so the
//! HTTP layer holds nothing but header plumbing.

use crate::token::{TokenManager, constant_time_eq};

/// Decide whether a caller may touch the administrative endpoints.
///
/// Two credentials are accepted, in this order:
///
/// 1. an admin-scoped `la_sk_…` JWT (see [`crate::token::ADMIN_SCOPE`]) —
///    identified, expiring, revocable, and rotatable;
/// 2. the flat `TOKEN_ADMIN_KEY` bootstrap secret, compared in constant time.
///    It is kept because it is the only way to provision the *first* credential
///    in a deployment that configures everything externally.
///
/// When neither is presented the request is refused, unless the operator
/// explicitly opted out with `--allow-anonymous-admin`. That default is the
/// inverse of the historical behaviour, where an unconfigured admin key left
/// the token-administration endpoints wide open.
#[must_use]
pub fn admin_access_granted(
    manager: &TokenManager,
    provided: crate::translation_core::Maybe<&crate::translation_core::Str>,
    admin_key: crate::translation_core::Maybe<&crate::translation_core::Str>,
    allow_anonymous: bool,
) -> bool {
    if let Some(provided) = provided {
        if manager.validate_admin_token(provided).is_ok() {
            return true;
        }
        if let Some(required) = admin_key
            && constant_time_eq(provided, required)
        {
            return true;
        }
    }
    allow_anonymous
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::token::{IssueRequest, TokenError};

    fn manager() -> TokenManager {
        TokenManager::new("secret-for-admin-auth-tests")
    }

    /// Reproduces the issue: with no admin key configured, an unauthenticated
    /// request used to be authorised (`POST /api/management/tokens` answered `200`).
    #[test]
    fn unauthenticated_request_is_refused_when_no_credential_is_configured() {
        assert!(!admin_access_granted(&manager(), None, None, false));
    }

    #[test]
    fn unauthenticated_request_is_refused_when_an_admin_key_is_configured() {
        assert!(!admin_access_granted(
            &manager(),
            None,
            Some("s3cret"),
            false
        ));
    }

    #[test]
    fn anonymous_access_requires_an_explicit_opt_out() {
        assert!(admin_access_granted(&manager(), None, None, true));
    }

    #[test]
    fn admin_scoped_token_is_accepted() {
        let mgr = manager();
        let token = mgr
            .issue_admin_token(1, "ops")
            .expect("should issue admin token");
        assert!(admin_access_granted(&mgr, Some(&token), None, false));
    }

    #[test]
    fn ordinary_client_token_is_rejected() {
        let mgr = manager();
        let token = mgr.issue_token(1, "client").expect("should issue");
        assert!(matches!(
            mgr.validate_admin_token(&token),
            Err(TokenError::InsufficientScope)
        ));
        assert!(!admin_access_granted(&mgr, Some(&token), None, false));
    }

    #[test]
    fn revoked_admin_token_is_rejected() {
        let mgr = manager();
        let token = mgr.issue_admin_token(1, "ops").expect("should issue");
        let claims = mgr.validate_token(&token).expect("should validate");
        mgr.revoke_token(&claims.sub).expect("should revoke");
        assert!(!admin_access_granted(&mgr, Some(&token), None, false));
    }

    #[test]
    fn expired_admin_token_is_rejected() {
        let mgr = manager();
        let token = mgr
            .issue(&IssueRequest {
                ttl_hours: -1,
                label: "stale",
                scope: crate::token::ADMIN_SCOPE,
                ..IssueRequest::default()
            })
            .expect("should issue");
        assert!(!admin_access_granted(&mgr, Some(&token), None, false));
    }

    #[test]
    fn flat_admin_key_still_works_as_a_bootstrap_credential() {
        let mgr = manager();
        assert!(admin_access_granted(
            &mgr,
            Some("s3cret"),
            Some("s3cret"),
            false
        ));
        assert!(!admin_access_granted(
            &mgr,
            Some("wrong"),
            Some("s3cret"),
            false
        ));
    }
}

//! Configuration for the opt-in admin UI listener.
//!
//! Split out of [`crate::config`] to keep that module within the repository's
//! per-file line budget; the constructors are re-exported there, so callers can
//! keep using `config::admin_ui_config`.

use std::time::Duration;

use crate::config::{ConfigError, parse_u64_env};

/// Build the admin UI configuration from environment variables.
///
/// The listener is enabled only when `ADMIN_PORT` names a non-zero port, so
/// upgrading an existing deployment gains no new surface.
///
/// # Errors
///
/// Returns [`ConfigError::InvalidPort`] for an unparseable `ADMIN_PORT` and
/// [`ConfigError::InvalidAddress`] when host and port do not form an address.
pub fn admin_ui_from_env() -> crate::translation_core::Outcome<crate::admin::AdminUiConfig, ConfigError> {
    let port = crate::operation_context::var("ADMIN_PORT")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .map(|value| value.trim().parse::<u16>())
        .transpose()
        .map_err(|_| ConfigError::InvalidPort)?;
    let host =
        crate::operation_context::var("ADMIN_HOST").unwrap_or_else(|_| "127.0.0.1".to_string());
    let ttl = parse_u64_env(
        "ADMIN_CLAIM_TTL_SECS",
        crate::admin::DEFAULT_CANDIDATE_TTL_SECS,
    );
    admin_ui_config(port, &host, ttl)
}

/// Assemble an [`crate::admin::AdminUiConfig`] from explicit parts.
///
/// # Errors
///
/// Returns [`ConfigError::InvalidAddress`] when `host` and `port` do not parse
/// as a socket address.
pub fn admin_ui_config(
    port: crate::translation_core::Maybe<u16>,
    host: &crate::translation_core::Str,
    candidate_ttl_secs: u64,
) -> crate::translation_core::Outcome<crate::admin::AdminUiConfig, ConfigError> {
    let default = crate::admin::AdminUiConfig::default();
    let enabled = port.is_some_and(|value| value != 0);
    let listen_addr = match port.filter(|value| *value != 0) {
        Some(value) => crate::translation_core::format!("{host}:{value}")
            .parse()
            .map_err(|_| ConfigError::InvalidAddress)?,
        None => default.listen_addr,
    };
    Ok(crate::admin::AdminUiConfig {
        enabled,
        listen_addr,
        candidate_ttl: Duration::from_secs(candidate_ttl_secs),
    })
}

//! Recovery of administrative access from a locally-owned token store.
//!
//! An operator who loses the admin token cannot administer their own
//! deployment, even holding the store, the volume and the machine. Every verb
//! in the `tokens` family authenticates with the admin credential, so the
//! recovery path for the admin credential required the admin credential, and
//! the standing advice was to destroy the deployment and start over —
//! discarding every issued client token and the whole request log to recover
//! from having misplaced one string (issue #573).
//!
//! ## Why a replacement rather than the lost value
//!
//! The token is a JWT signed with `TOKEN_SECRET`; the store keeps only its
//! metadata — id, label, scope, expiry, revocation. The secret value is
//! therefore genuinely unrecoverable, and no amount of local access changes
//! that. What local access *does* allow is signing a new one: the same
//! operation the server performs at first boot, against the same store and the
//! same secret. The running deployment accepts the result immediately, because
//! validation is a signature check against that secret rather than a lookup of
//! a remembered string — so recovery needs no restart.
//!
//! ## Why local ownership is sufficient authority
//!
//! Reading the token store already means full control of the deployment: the
//! signing secret is reachable from the same place, and with it any token at
//! all can be minted. Gating recovery on that access therefore grants no
//! authority its caller did not already have — it only makes existing
//! authority usable. The boundary that matters is the one this must never
//! cross: recovery is not available over HTTP, exactly as `auth import` and
//! `auth clear` are not, because "prove you are on the machine" is the whole
//! check. [`crate::admin_recovery::refusal`] states that refusal and names the
//! deployment the caller had selected.
//!
//! ## What is preserved
//!
//! Everything except the lost administrator. Client tokens keep working — they
//! are signed with the same secret and this does not touch their records —
//! provider configuration and the request log are not read, and the store is
//! only appended to. `--revoke-others` additionally retires every other admin
//! token, for a credential believed to be in someone else's hands.

use std::sync::Arc;

use crate::storage::TokenStore;
use crate::token::TokenManager;

/// Label recorded on a token minted by recovery.
///
/// The store's own metadata is the audit trail: `TokenRecord` always persists a
/// label and an issue time, so a recovered administrator is visible in `tokens
/// list` for as long as the token exists, with no separate log to enable and
/// nothing to lose if the optional JSONL audit sink is off. The default is a
/// distinct constant rather than the bootstrap label so a recovery is never
/// mistaken for a first boot.
pub const RECOVERED_ADMIN_LABEL: &crate::translation_core::Str = "recovered-admin";

/// Outcome of a successful recovery.
///
/// `Debug` is implemented by hand: this carries a live admin credential, and a
/// derived one would print it into any log, panic or test failure that formats
/// the struct.
pub struct Recovery {
    /// The freshly signed admin token. Printed once, like the bootstrap one.
    pub token: String,
    /// Subject id of the token that was minted, for correlating with the store.
    pub token_id: String,
    /// Ids of admin tokens retired because `--revoke-others` was given.
    pub revoked: Vec<String>,
    /// Admin tokens that already existed and were left alone.
    ///
    /// Reported so the operator learns whether the lost credential is still
    /// live: recovery on its own *adds* an administrator, and a lost token that
    /// someone else holds keeps working until it is revoked or expires.
    pub retained_admins: usize,
}

impl std::fmt::Debug for Recovery {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("Recovery")
            .field("token", &"<redacted>")
            .field("token_id", &self.token_id)
            .field("revoked", &self.revoked)
            .field("retained_admins", &self.retained_admins)
            .finish()
    }
}

/// Mint a replacement administrative token against a local store.
///
/// `manager` must be built from the deployment's own `TOKEN_SECRET` and data
/// directory — the same pair the server uses — or the token will be signed with
/// the wrong key and rejected by the very deployment it was meant to recover.
pub fn recover(
    manager: &TokenManager,
    store: &Arc<dyn TokenStore>,
    ttl_hours: i64,
    label: &crate::translation_core::Str,
    revoke_others: bool,
) -> Result<Recovery, String> {
    if ttl_hours <= 0 {
        return Err(crate::translation_core::format!(
            "a recovered admin token needs a positive lifetime; --ttl-hours was {ttl_hours}"
        ));
    }
    // Counted before minting so the new administrator is not counted as one of
    // the ones that already existed.
    let existing_admins = admin_token_ids(store)?;
    let token = manager
        .issue_admin_token(ttl_hours, label)
        .map_err(|error| crate::translation_core::format!("could not sign a replacement admin token: {error}"))?;
    let token_id = crate::managed_server::token_subject(&token)
        .map_err(|error| crate::translation_core::format!("could not read the minted token's subject: {error}"))?;

    let mut revoked = Vec::new();
    if revoke_others {
        // Revoke by id rather than with `revoke_other_admin_tokens`, which
        // takes the keeper's id and would also retire anything minted between
        // the two calls. The set to retire is the one observed before minting.
        for id in &existing_admins {
            store
                .revoke(id)
                .map_err(|error| crate::translation_core::format!("minted {token_id} but could not revoke {id}: {error}"))?;
            revoked.push(id.clone());
        }
    }
    Ok(Recovery {
        token,
        token_id,
        retained_admins: if revoke_others {
            0
        } else {
            existing_admins.len()
        },
        revoked,
    })
}

/// Ids of unexpired, unrevoked admin tokens currently in the store.
fn admin_token_ids(store: &Arc<dyn TokenStore>) -> Result<Vec<String>, String> {
    let now = crate::operation_context::now().timestamp();
    let records = store
        .list()
        .map_err(|error| crate::translation_core::format!("could not read the token store: {error}"))?;
    Ok(records
        .into_iter()
        .filter(|record| {
            record.scope == crate::token::ADMIN_SCOPE && !record.revoked && record.expires_at > now
        })
        .map(|record| record.id)
        .collect())
}

/// Refusal issued when another router is the selected target.
///
/// Recovery reads this machine's store and signs with this machine's secret.
/// Performing it anyway while a different deployment is selected would answer
/// about the wrong deployment in a shape that looks correct — the failure mode
/// issue #291 was filed for — so it refuses and names the target instead.
#[must_use]
pub fn refusal(server: &crate::managed_server::ResolvedServer) -> crate::translation_core::Text {
    crate::translation_core::format!(
        "`tokens recover-admin` acts on the token store of the machine it runs on, and {} is \
         selected. Recovery is proof of local ownership, so no router performs it over HTTP: \
         run it on that deployment — `docker exec <container> router tokens recover-admin` for \
         a containerised one — or pass --local to recover this machine's store.",
        server.base_url
    )
}

//! Serving of the embedded admin UI bundle.
//!
//! The React app in `ui/` is built by Vite into `ui/dist` with stable asset
//! names (`assets/app.js`, `assets/app.css`) and embedded into the binary by
//! `rust-embed`, so the single-container deployment story holds: no separate
//! web server, no assets to mount.
//!
//! Unknown paths fall back to `index.html` so the client-side app owns its own
//! routing; unknown paths under `/api/` do not, because a JSON client should
//! get a `404`, not a page.

use axum::extract::Request;
use axum::http::{HeaderValue, StatusCode, header};
use axum::response::{IntoResponse, Response};
use rust_embed::RustEmbed;

/// The built admin UI bundle, embedded at compile time.
#[derive(RustEmbed)]
#[folder = "ui/dist"]
struct Assets;

/// Serve an embedded asset, falling back to `index.html` for app routes.
pub async fn serve_asset(request: Request) -> Response {
    let path = request.uri().path().trim_start_matches('/');
    if let Some(response) = asset_response(path) {
        return response;
    }
    if request.uri().path().starts_with("/api/") {
        return (StatusCode::NOT_FOUND, "not found").into_response();
    }
    asset_response("index.html").unwrap_or_else(|| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            "admin UI bundle is missing from this build",
        )
            .into_response()
    })
}

/// Look up one embedded file and wrap it in a response with its MIME type.
fn asset_response(path: &str) -> Option<Response> {
    let path = if path.is_empty() { "index.html" } else { path };
    let file = Assets::get(path)?;
    let mime = content_type(path);
    let mut response = file.data.into_owned().into_response();
    response
        .headers_mut()
        .insert(header::CONTENT_TYPE, HeaderValue::from_static(mime));
    // The bundle is versioned with the binary, and the operator may upgrade at
    // any time, so assets are revalidated rather than cached indefinitely.
    response.headers_mut().insert(
        header::CACHE_CONTROL,
        HeaderValue::from_static("no-cache, must-revalidate"),
    );
    Some(response)
}

/// Minimal extension-to-MIME map covering what Vite emits for this app.
fn content_type(path: &str) -> &'static str {
    match path.rsplit_once('.').map(|(_, ext)| ext) {
        Some("html") => "text/html; charset=utf-8",
        Some("js" | "mjs") => "text/javascript; charset=utf-8",
        Some("css") => "text/css; charset=utf-8",
        Some("json") => "application/json",
        Some("svg") => "image/svg+xml",
        Some("png") => "image/png",
        Some("ico") => "image/x-icon",
        Some("woff2") => "font/woff2",
        _ => "application/octet-stream",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn index_is_embedded() {
        assert!(Assets::get("index.html").is_some());
    }

    #[test]
    fn content_types_are_mapped() {
        assert_eq!(content_type("index.html"), "text/html; charset=utf-8");
        assert_eq!(
            content_type("assets/app.js"),
            "text/javascript; charset=utf-8"
        );
        assert_eq!(content_type("assets/app.css"), "text/css; charset=utf-8");
        assert_eq!(content_type("noext"), "application/octet-stream");
    }
}

//! Anthropic Messages surface over non-Anthropic upstreams.
//!
//! Claude Code (and every other client that speaks only the Anthropic dialect)
//! sends `POST /v1/messages`. Before this module existed, that surface could
//! only be served by the Anthropic upstream, so a Codex/Qwen/Gemini
//! subscription could not back Claude Code — the gap named by issue #45.
//!
//! The bridge is deliberately an *adapter*, not a second forwarder: it
//! translates the request into the `OpenAI` dialect the target provider already
//! understands, delegates to the existing per-provider forwarder (which owns
//! credential resolution, refresh, account selection, cooldowns and budget
//! enforcement), and translates the reply back into Anthropic shape.
//!
//! Streaming replies are translated incrementally by
//! [`crate::anthropic_stream::AnthropicStreamTranslator`].
//!
//! Translation is not subscription authority. Consumer-subscription bridges
//! are denied by default and run only after `client_policy` authorizes the
//! exact signed client/provider pair; issue #45's historical default is
//! superseded by issue #389. Ordinary API-key providers and the separately
//! policy-gated z.ai Coding Plan retain their own credential rules.

use axum::http::{HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use serde_json::{Value, json};

use crate::anthropic_stream::map_stop_reason;
use crate::app_state::AppState;
use crate::bridge_selection::{ModelSelectionRequired, SelectionFailure};
use crate::config::UpstreamProvider;
use crate::metrics::Surface;

/// Default `max_tokens` used when a bridged Anthropic request omits it.
/// The Anthropic Messages API requires the field; `OpenAI` upstreams do not.
pub(crate) const DEFAULT_MAX_TOKENS: u64 = 4096;

/// Whether the Anthropic surface must be bridged for this upstream provider.
///
/// `Anthropic` needs no translation, and `Gonka`/`Crater` keep the behaviour
/// they already had on this surface.
#[must_use]
pub const fn is_bridged(provider: UpstreamProvider) -> bool {
    matches!(
        provider,
        UpstreamProvider::Codex
            | UpstreamProvider::Qwen
            | UpstreamProvider::Gemini
            | UpstreamProvider::OpenAICompatible
            | UpstreamProvider::ZaiCodingPlan
    )
}

/// Resolve the upstream model id for a bridged request.
///
/// The client sends an Anthropic model name (`claude-…`), which means nothing
/// to a Codex or Qwen upstream. Resolution order:
///
/// 1. the operator's configured `--bridge-model`, when set;
/// 2. otherwise the account's **live catalog**, narrowed by the operator's
///    `--bridge-model-policy`.
///
/// No per-provider constant is consulted. When the live catalog cannot supply a
/// model the request fails with `model_selection_required` instead of being
/// routed to a name from the router's own source (issue #192).
///
/// For the generic OpenAI-compatible provider an empty string is returned so
/// that the provider's own `default_model` is applied by its forwarder.
///
/// # Errors
///
/// Returns [`ModelSelectionRequired`] when the provider's catalog has not been
/// discovered, its credential is unusable, or it advertises no models.
pub fn resolve_bridge_model(state: &AppState) -> Result<String, ModelSelectionRequired> {
    resolve_bridge_model_for_account(state, None)
}

pub(crate) fn resolve_bridge_model_for_account(
    state: &AppState,
    router_account: Option<&str>,
) -> Result<String, ModelSelectionRequired> {
    let Some(provider) = state.upstream_provider.subscription_provider() else {
        // Left empty on purpose: `forward_openai_compatible` substitutes the
        // provider record's `default_model` when `model` is absent or empty.
        return Ok(state.bridge_model.clone().unwrap_or_else(|| {
            state
                .openai_compatible
                .default_model
                .clone()
                .unwrap_or_default()
        }));
    };

    let status = router_account.map_or_else(
        || state.model_catalogs.status(provider),
        |account| state.model_catalogs.status_for(provider, account),
    );
    let fail = |reason| {
        Err(ModelSelectionRequired {
            provider: provider.as_str().to_string(),
            reason,
        })
    };
    if !status.discovered {
        return fail(SelectionFailure::NotDiscovered);
    }
    if !status.credential_healthy {
        return fail(SelectionFailure::CredentialUnavailable);
    }
    if let Some(scope) = crate::account_policy_scope::current()
        && router_account == crate::account_policy_scope::account().as_deref()
    {
        return catalog_contains_current_generation(&status, &scope.upstream_model)
            .then(|| scope.upstream_model.clone())
            .map_or_else(|| fail(SelectionFailure::ConfiguredModelUnavailable), Ok);
    }
    if let Some(model) = state
        .bridge_model
        .as_deref()
        .filter(|model| !model.is_empty())
    {
        return catalog_contains_current_generation(&status, model)
            .then(|| model.to_string())
            .map_or_else(|| fail(SelectionFailure::ConfiguredModelUnavailable), Ok);
    }
    let selected = state
        .bridge_model_policy
        .choose(status.routable_models())
        .map_or_else(|| fail(SelectionFailure::EmptyCatalog), Ok)?;
    if catalog_contains_current_generation(&status, &selected) {
        Ok(selected)
    } else {
        fail(SelectionFailure::CredentialUnavailable)
    }
}

fn catalog_contains_current_generation(
    status: &crate::model_catalog::CatalogStatus,
    model: &str,
) -> bool {
    let expected_account = status.account.as_deref();
    let Some(record) = status
        .records
        .iter()
        .find(|record| record.canonical_id == model)
    else {
        return false;
    };
    (!record.health_generation.is_empty())
        && expected_account.is_none_or(|account| record.account == account)
        && status.records.iter().all(|candidate| {
            candidate.health_generation == record.health_generation
                && expected_account.is_none_or(|account| candidate.account == account)
        })
}

pub use crate::bridge_request::anthropic_to_chat_request;

/// Translate an `OpenAI` Chat Completions **or** Responses JSON object into an
/// Anthropic `message` object.
///
/// The shape is detected from the payload because the bridged providers do not
/// all answer with the same one: Codex replies with a Responses object while
/// the others reply with a chat completion.
#[must_use]
pub fn openai_json_to_anthropic_message(payload: &Value, requested_model: &str) -> Value {
    try_openai_json_to_anthropic_message(payload, requested_model).unwrap_or_else(|message| {
        json!({
            "type": "error",
            "error": {"type": "api_error", "message": message},
        })
    })
}

/// Translate an upstream object without silently discarding response items.
pub fn try_openai_json_to_anthropic_message(
    payload: &Value,
    requested_model: &str,
) -> Result<Value, String> {
    if payload.get("object").and_then(Value::as_str) == Some("response")
        || payload.get("output").is_some()
    {
        responses_to_anthropic_message(payload, requested_model)
    } else {
        chat_completion_to_anthropic_message(payload, requested_model)
    }
}

fn chat_completion_to_anthropic_message(
    payload: &Value,
    _requested_model: &str,
) -> Result<Value, String> {
    let choice = payload
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|c| c.first())
        .cloned()
        .unwrap_or(Value::Null);
    let message = choice.get("message").unwrap_or(&Value::Null);

    let mut content: Vec<Value> = Vec::new();
    if let Some(text) = message.get("content").and_then(Value::as_str)
        && !text.is_empty()
    {
        let citations = crate::bridge_response::openai_annotations_to_anthropic(
            text,
            message.get("annotations"),
            true,
        )?;
        let mut block = json!({"type": "text", "text": text});
        if !citations.is_empty() {
            block["citations"] = Value::Array(citations);
        }
        content.push(block);
    }
    for call in message
        .get("tool_calls")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or_default()
    {
        content.push(tool_use_block(
            call.get("id").and_then(Value::as_str).unwrap_or_default(),
            call.get("function")
                .and_then(|f| f.get("name"))
                .and_then(Value::as_str)
                .unwrap_or_default(),
            call.get("function")
                .and_then(|f| f.get("arguments"))
                .and_then(Value::as_str)
                .unwrap_or("{}"),
        )?);
    }

    let stop_reason = choice
        .get("finish_reason")
        .and_then(Value::as_str)
        .map_or("end_turn", map_stop_reason);
    let usage = payload.get("usage");
    let mut translated = message_envelope(
        payload.get("id").and_then(Value::as_str),
        payload
            .get("model")
            .and_then(Value::as_str)
            .unwrap_or_default(),
        &content,
        stop_reason,
        usage_field(usage, &["prompt_tokens", "input_tokens"]),
        usage_field(usage, &["completion_tokens", "output_tokens"]),
    );
    translated["usage"] = crate::bridge_response::openai_usage_to_anthropic(usage);
    if let Some(tier) =
        crate::bridge_response::anthropic_service_tier_from_openai(payload.get("service_tier"))
    {
        translated["usage"]["service_tier"] = Value::String(tier.into());
    }
    Ok(translated)
}

fn responses_to_anthropic_message(
    payload: &Value,
    _requested_model: &str,
) -> Result<Value, String> {
    let mut content: Vec<Value> = Vec::new();
    let mut saw_tool_call = false;
    let mut web_search_requests = 0_u64;
    let output = payload
        .get("output")
        .and_then(Value::as_array)
        .ok_or_else(|| "Responses output must be an array".to_string())?;
    for item in output {
        let kind = item
            .get("type")
            .and_then(Value::as_str)
            .filter(|kind| !kind.is_empty())
            .ok_or_else(|| "Responses output item type must be a non-empty string".to_string())?;
        match kind {
            "message" => {
                let mut combined_text = String::new();
                let mut combined_citations = Vec::new();
                let parts = item
                    .get("content")
                    .and_then(Value::as_array)
                    .ok_or_else(|| "Responses message content must be an array".to_string())?;
                for part in parts {
                    let part_kind = part
                        .get("type")
                        .and_then(Value::as_str)
                        .filter(|kind| !kind.is_empty())
                        .ok_or_else(|| {
                            "Responses message content type must be a non-empty string".to_string()
                        })?;
                    let text = match part_kind {
                        "output_text" | "text" => part.get("text").and_then(Value::as_str),
                        "refusal" => part.get("refusal").and_then(Value::as_str),
                        other => {
                            return Err(format!(
                                "Responses message content type {other} cannot be represented by Anthropic"
                            ));
                        }
                    };
                    let Some(text) = text.filter(|text| !text.is_empty()) else {
                        continue;
                    };
                    let citations = crate::bridge_response::openai_annotations_to_anthropic(
                        text,
                        part.get("annotations"),
                        false,
                    )?;
                    combined_text.push_str(text);
                    combined_citations.extend(citations);
                }
                if !combined_text.is_empty() {
                    let mut block = json!({"type": "text", "text": combined_text});
                    if !combined_citations.is_empty() {
                        block["citations"] = Value::Array(combined_citations);
                    }
                    content.push(block);
                }
            }
            "function_call" => {
                saw_tool_call = true;
                content.push(tool_use_block(
                    item.get("call_id")
                        .or_else(|| item.get("id"))
                        .and_then(Value::as_str)
                        .unwrap_or_default(),
                    item.get("name").and_then(Value::as_str).unwrap_or_default(),
                    item.get("arguments")
                        .and_then(Value::as_str)
                        .unwrap_or("{}"),
                )?);
            }
            "web_search_call" => {
                let id = item.get("id").and_then(Value::as_str).unwrap_or_default();
                content.push(json!({
                    "type": "server_tool_use",
                    "id": id,
                    "name": "web_search",
                    "input": item.get("action").cloned().unwrap_or_else(|| json!({})),
                }));
                if item.get("status").and_then(Value::as_str) == Some("completed") {
                    web_search_requests = web_search_requests.saturating_add(1);
                    content.push(json!({
                        "type": "web_search_tool_result",
                        "tool_use_id": id,
                        "content": [],
                    }));
                }
            }
            other => return Err(unrepresentable_responses_output(other)),
        }
    }

    let stop_reason = if saw_tool_call {
        "tool_use"
    } else if payload.get("status").and_then(Value::as_str) == Some("incomplete") {
        "max_tokens"
    } else {
        "end_turn"
    };
    let usage = payload.get("usage");
    let mut message = message_envelope(
        payload.get("id").and_then(Value::as_str),
        payload
            .get("model")
            .and_then(Value::as_str)
            .unwrap_or_default(),
        &content,
        stop_reason,
        usage_field(usage, &["input_tokens", "prompt_tokens"]),
        usage_field(usage, &["output_tokens", "completion_tokens"]),
    );
    message["usage"] = crate::bridge_response::openai_usage_to_anthropic(usage);
    if let Some(tier) =
        crate::bridge_response::anthropic_service_tier_from_openai(payload.get("service_tier"))
    {
        message["usage"]["service_tier"] = Value::String(tier.into());
    }
    if web_search_requests > 0 {
        message["usage"]["server_tool_use"] = json!({
            "web_search_requests": web_search_requests,
            "web_fetch_requests": 0,
        });
    }
    Ok(message)
}

pub(crate) fn unrepresentable_responses_output(kind: &str) -> String {
    format!("Responses output item type {kind} cannot be represented by Anthropic")
}

fn tool_use_block(id: &str, name: &str, arguments: &str) -> Result<Value, String> {
    let input = serde_json::from_str::<Value>(arguments)
        .map_err(|_| "upstream function-call arguments must be valid JSON".to_string())?;
    Ok(json!({
        "type": "tool_use",
        "id": if id.is_empty() { format!("toolu_{}", uuid::Uuid::new_v4().simple()) } else { id.to_string() },
        "name": name,
        "input": input,
    }))
}

fn usage_field(usage: Option<&Value>, keys: &[&str]) -> u64 {
    usage
        .and_then(|u| keys.iter().find_map(|k| u.get(*k).and_then(Value::as_u64)))
        .unwrap_or(0)
}

fn message_envelope(
    id: Option<&str>,
    model: &str,
    content: &[Value],
    stop_reason: &str,
    input_tokens: u64,
    output_tokens: u64,
) -> Value {
    json!({
        "id": id.map_or_else(|| format!("msg_{}", uuid::Uuid::new_v4().simple()), String::from),
        "type": "message",
        "role": "assistant",
        "model": model,
        "content": content,
        "stop_reason": stop_reason,
        "stop_sequence": Value::Null,
        "usage": {"input_tokens": input_tokens, "output_tokens": output_tokens},
    })
}

fn enforce_anthropic_stop(message: &mut Value, sequences: &[String]) {
    let Some(content) = message.get_mut("content").and_then(Value::as_array_mut) else {
        return;
    };
    let mut matched = None;
    let mut keep = content.len();
    for (index, block) in content.iter_mut().enumerate() {
        let Some(text) = block.get_mut("text") else {
            continue;
        };
        let Some(mut visible) = text.as_str().map(str::to_string) else {
            continue;
        };
        if let Some(sequence) = crate::stop_sequences::truncate(&mut visible, sequences) {
            *text = Value::String(visible);
            matched = Some(sequence);
            keep = index + 1;
            break;
        }
    }
    content.truncate(keep);
    if let Some(sequence) = matched {
        message["stop_reason"] = Value::String("end_turn".into());
        message["stop_sequence"] = Value::String(sequence);
    }
}

fn unsupported_server_tool(body: &Value, provider: UpstreamProvider) -> Option<String> {
    provider.subscription_provider().and_then(|subscription| {
        crate::capabilities::unsupported_server_tool_type(subscription, body.get("tools"))
    })
}

pub(crate) fn untranslatable_anthropic_tool(body: &Value) -> Option<String> {
    if let Some(tools) = body.get("tools") {
        let Some(tools) = tools.as_array() else {
            return Some("tools must be an array".into());
        };
        for tool in tools {
            let kind = tool.get("type").and_then(Value::as_str);
            if kind.is_some_and(|kind| {
                kind.starts_with("web_search_") || kind.starts_with("web_fetch_")
            }) {
                continue;
            }
            if let Some(kind) = kind
                && kind != "custom"
            {
                return Some(format!("unsupported Anthropic tool type: {kind}"));
            }
            if tool.get("name").and_then(Value::as_str).is_none() {
                return Some("client tool is missing a string name".into());
            }
            if tool
                .get("input_schema")
                .is_some_and(|schema| !schema.is_object())
            {
                return Some("client tool input_schema must be an object".into());
            }
            if tool
                .get("strict")
                .is_some_and(|strict| !strict.is_boolean())
            {
                return Some("client tool strict must be a boolean".into());
            }
        }
    }
    if let Some(choice) = body.get("tool_choice") {
        let Some(kind) = choice.get("type").and_then(Value::as_str) else {
            return Some("tool_choice is missing a string type".into());
        };
        if !matches!(kind, "auto" | "any" | "none" | "tool") {
            return Some(format!("unsupported Anthropic tool_choice type: {kind}"));
        }
        if kind == "tool" && choice.get("name").and_then(Value::as_str).is_none() {
            return Some("tool_choice type=tool is missing a string name".into());
        }
    }
    None
}

/// Entry point for the Anthropic surface when the upstream is not Anthropic.
///
/// Bridged routes fail closed for token counting unless an exact compatible,
/// non-inference counter is available; everything else is forwarded.
pub async fn handle_anthropic_surface(
    state: &AppState,
    headers: &HeaderMap,
    path: &str,
    body: Value,
) -> Response {
    handle_anthropic_surface_routed(state, headers, path, body, None).await
}

pub(crate) async fn handle_anthropic_surface_routed(
    state: &AppState,
    headers: &HeaderMap,
    path: &str,
    body: Value,
    subscription: Option<&crate::model_routing::ValidatedSubscription>,
) -> Response {
    if state.upstream_provider == UpstreamProvider::ZaiCodingPlan {
        if path.ends_with("/count_tokens") {
            return crate::zai_coding_plan::count_tokens(state, headers, path, &body);
        }
        return crate::zai_coding_plan::forward(
            state,
            headers,
            body,
            path,
            crate::client_policy::ClientProtocol::AnthropicMessages,
            Surface::Anthropic,
        )
        .await;
    }
    if path.ends_with("/count_tokens") {
        // Answered locally, so no delegate forwarder validates the token for
        // us. Do it here: an expired or revoked token must not get an estimate
        // either. The request budget is deliberately *not* consumed, since
        // nothing is spent upstream.
        let claims = match count_tokens_claims(&state.token_manager, headers) {
            Ok(claims) => claims,
            Err(response) => return *response,
        };
        crate::audit::record_authorised_request(
            state,
            &claims,
            Surface::Anthropic,
            path,
            Some(&body),
        );
        return anthropic_error(
            StatusCode::SERVICE_UNAVAILABLE,
            b"exact token counting is unavailable for the selected route",
        );
    }
    forward_anthropic_messages_routed(state, headers, path, body, subscription).await
}

/// Validate the client token for a locally answered `count_tokens` request.
pub(crate) fn count_tokens_claims(
    token_manager: &crate::token::TokenManager,
    headers: &HeaderMap,
) -> Result<crate::token::TokenClaims, Box<Response>> {
    let Some(token) = crate::proxy::extract_client_token(headers) else {
        return Err(Box::new(anthropic_error(
            StatusCode::UNAUTHORIZED,
            crate::proxy::CREDENTIAL_CARRIER_HINT.as_bytes(),
        )));
    };
    token_manager
        .authenticate_incoming(token, headers)
        .map_err(|e| {
            let status = match &e {
                crate::token::TokenError::Revoked => StatusCode::FORBIDDEN,
                _ => StatusCode::UNAUTHORIZED,
            };
            Box::new(anthropic_error(status, e.client_message().as_bytes()))
        })
}

/// Serve `POST /v1/messages` from a non-Anthropic upstream.
///
/// Delegates to the provider's existing `OpenAI`-dialect forwarder and
/// translates both directions. Metrics are recorded by the delegate under
/// [`Surface::Anthropic`] so the bridged traffic is attributed to the surface
/// the client actually used.
pub async fn forward_anthropic_messages(
    state: &AppState,
    headers: &HeaderMap,
    anthropic_body: Value,
) -> Response {
    forward_anthropic_messages_routed(state, headers, "/v1/messages", anthropic_body, None).await
}

async fn forward_anthropic_messages_routed(
    state: &AppState,
    headers: &HeaderMap,
    path: &str,
    anthropic_body: Value,
    subscription: Option<&crate::model_routing::ValidatedSubscription>,
) -> Response {
    if anthropic_body
        .get("max_tokens")
        .and_then(Value::as_u64)
        .is_none_or(|limit| limit == 0)
    {
        // Keep authentication ahead of request validation even though the
        // delegated forwarder is not reached for a malformed Messages body.
        if let Err(response) = count_tokens_claims(&state.token_manager, headers) {
            return *response;
        }
        return anthropic_error(StatusCode::BAD_REQUEST, b"max_tokens is required");
    }
    if anthropic_body
        .get("messages")
        .and_then(Value::as_array)
        .is_none_or(Vec::is_empty)
    {
        if let Err(response) = count_tokens_claims(&state.token_manager, headers) {
            return *response;
        }
        return anthropic_error(
            StatusCode::BAD_REQUEST,
            b"messages must contain at least one message",
        );
    }
    if let Some(kind) = unsupported_server_tool(&anthropic_body, state.upstream_provider) {
        if let Err(response) = count_tokens_claims(&state.token_manager, headers) {
            return *response;
        }
        return anthropic_error(
            StatusCode::BAD_REQUEST,
            format!("Unsupported tool type for selected provider: {kind}").as_bytes(),
        );
    }
    if let Some(reason) = crate::capabilities::unhonourable_server_tool_request(
        anthropic_body.get("tools"),
        anthropic_body.get("tool_choice"),
    ) {
        if let Err(response) = count_tokens_claims(&state.token_manager, headers) {
            return *response;
        }
        return anthropic_error(StatusCode::BAD_REQUEST, reason.as_bytes());
    }
    if let Some(reason) = untranslatable_anthropic_tool(&anthropic_body) {
        if let Err(response) = count_tokens_claims(&state.token_manager, headers) {
            return *response;
        }
        return anthropic_error(StatusCode::BAD_REQUEST, reason.as_bytes());
    }
    let bridge_target = match state.upstream_provider {
        UpstreamProvider::Codex => crate::bridge_request::BridgeTarget::Responses,
        UpstreamProvider::Gemini => crate::bridge_request::BridgeTarget::Gemini,
        _ => crate::bridge_request::BridgeTarget::Chat,
    };
    if let Err(reason) =
        crate::bridge_request::validate_anthropic_request(&anthropic_body, bridge_target)
    {
        if let Err(response) = count_tokens_claims(&state.token_manager, headers) {
            return *response;
        }
        return anthropic_error(StatusCode::BAD_REQUEST, reason.as_bytes());
    }
    // Preserve the requested identity for the reply. A request that names no
    // model has none to echo; the resolved upstream model is reported
    // separately, so nothing is invented here (issue #192).
    let requested_model = anthropic_body
        .get("model")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let stream_requested = anthropic_body
        .get("stream")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let stop_sequences = crate::stop_sequences::from_value(anthropic_body.get("stop_sequences"));
    // No source-code fallback: when the live catalog cannot name a model the
    // request is refused rather than routed to a guess (issue #192).
    let bound_subscription;
    let subscription = if let Some(candidate) = subscription.filter(|item| item.uses_account_pool())
    {
        let claims = match count_tokens_claims(&state.token_manager, headers) {
            Ok(claims) => claims,
            Err(response) => return *response,
        };
        let pinned_account = match state.token_manager.account_for(&claims.sub) {
            Ok(account) => account,
            Err(error) => {
                return crate::proxy::error_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "api_error",
                    &format!("failed to resolve token account binding: {error}"),
                );
            }
        };
        let context = crate::request_routing::request_routing_context(
            headers,
            &anthropic_body,
            pinned_account,
        );
        bound_subscription = match candidate.bind_for_context(state, &context).await {
            Ok(subscription) => Some(subscription),
            Err(error) => {
                return crate::proxy::error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "account_unavailable",
                    &error,
                );
            }
        };
        bound_subscription.as_ref()
    } else {
        subscription
    };
    let upstream_model = match resolve_bridge_model_for_account(
        state,
        subscription.and_then(|item| item.account_name()),
    ) {
        Ok(model) => model,
        Err(error) => {
            return crate::proxy::error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                crate::bridge_selection::MODEL_SELECTION_REQUIRED,
                &error.to_string(),
            );
        }
    };
    let upstream = match state.upstream_provider {
        UpstreamProvider::Codex => {
            let responses_body = match crate::bridge_request::anthropic_to_responses_request(
                &anthropic_body,
                &upstream_model,
            ) {
                Ok(body) => body,
                Err(reason) => {
                    return anthropic_error(StatusCode::BAD_REQUEST, reason.as_bytes());
                }
            };
            crate::subscription_proxy::forward_subscription_openai_routed(
                state,
                headers,
                responses_body,
                &anthropic_body,
                "/v1/responses",
                Surface::Anthropic,
                crate::subscription_proxy::RoutedSubscriptionContext {
                    validated: subscription,
                    entitlement: None,
                    native_route: false,
                },
            )
            .await
        }
        UpstreamProvider::Qwen => {
            let chat_body = anthropic_to_chat_request(&anthropic_body, &upstream_model);
            crate::subscription_proxy::forward_subscription_openai_routed(
                state,
                headers,
                chat_body.clone(),
                &anthropic_body,
                "/v1/chat/completions",
                Surface::Anthropic,
                crate::subscription_proxy::RoutedSubscriptionContext {
                    validated: subscription,
                    entitlement: None,
                    native_route: false,
                },
            )
            .await
        }
        UpstreamProvider::Gemini => {
            let chat_body = anthropic_to_chat_request(&anthropic_body, &upstream_model);
            crate::gemini::forward_chat_completions_as_routed(
                state,
                headers,
                chat_body,
                &anthropic_body,
                Surface::Anthropic,
                subscription,
            )
            .await
        }
        _ => {
            let chat_body = anthropic_to_chat_request(&anthropic_body, &upstream_model);
            crate::provider_proxy::forward_provider_at_routed(
                state,
                headers,
                chat_body.clone(),
                &anthropic_body,
                crate::provider_proxy::ProviderForwardOptions {
                    path,
                    upstream_path: "/v1/chat/completions",
                    surface: Surface::Anthropic,
                    copy_anthropic_headers: false,
                    protocol: crate::client_policy::ClientProtocol::AnthropicMessages,
                    native_protocol: false,
                },
            )
            .await
        }
    };

    translate_upstream_response(
        upstream,
        &requested_model,
        &upstream_model,
        stream_requested,
        &stop_sequences,
    )
    .await
}

#[path = "anthropic_bridge_response.rs"]
mod response;
pub(crate) use response::translate_upstream_response;

/// Re-shape an upstream error body as an Anthropic error envelope.
#[path = "anthropic_bridge_error.rs"]
mod error;
use error::anthropic_error;

//! Response translation for the Anthropic bridge.

use axum::body::{Body, Bytes};
use axum::http::{HeaderMap, HeaderValue, StatusCode};
use axum::response::{IntoResponse, Response};
use futures_util::StreamExt as _;
use serde_json::Value;

use crate::anthropic_stream::AnthropicStreamTranslator;

use super::{anthropic_error, enforce_anthropic_stop, try_openai_json_to_anthropic_message};

/// Convert the `OpenAI`-dialect response produced by a delegate forwarder into
/// the Anthropic dialect.
pub async fn translate_upstream_response(
    upstream: Response,
    requested_model: &str,
    _upstream_model: &str,
    stream_requested: bool,
    stop_sequences: &[String],
) -> Response {
    let (parts, body) = upstream.into_parts();
    let status = parts.status;

    if !status.is_success() {
        let bytes = axum::body::to_bytes(body, 1024 * 1024)
            .await
            .unwrap_or_default();
        let mut response = anthropic_error(status, &bytes);
        *response.headers_mut() = parts.headers;
        response
            .headers_mut()
            .insert("content-type", HeaderValue::from_static("application/json"));
        return response;
    }

    if stream_requested {
        return anthropic_sse_response(
            body,
            requested_model,
            &parts.headers,
            stop_sequences.to_vec(),
        );
    }

    let bytes = match axum::body::to_bytes(body, 32 * 1024 * 1024).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return anthropic_error(
                StatusCode::BAD_GATEWAY,
                format!("failed to read upstream body: {error}").as_bytes(),
            );
        }
    };
    let Ok(payload) = serde_json::from_slice::<Value>(&bytes) else {
        return anthropic_error(
            StatusCode::BAD_GATEWAY,
            b"Upstream returned a malformed response",
        );
    };
    if let Err(error) = crate::bridge_response::validate_openai_response_citations(&payload) {
        return anthropic_error(
            StatusCode::BAD_GATEWAY,
            format!("upstream returned an unrepresentable citation: {error}").as_bytes(),
        );
    }
    let mut translated = match try_openai_json_to_anthropic_message(&payload, requested_model) {
        Ok(translated) => translated,
        Err(reason) => {
            return anthropic_error(
                StatusCode::BAD_GATEWAY,
                format!("upstream returned an unrepresentable response: {reason}").as_bytes(),
            );
        }
    };
    enforce_anthropic_stop(&mut translated, stop_sequences);
    let mut response = (StatusCode::OK, axum::Json(translated)).into_response();
    *response.headers_mut() = parts.headers;
    response
        .headers_mut()
        .insert("content-type", HeaderValue::from_static("application/json"));
    response
}

/// Wrap the upstream stream in an incremental Anthropic SSE translator.
fn anthropic_sse_response(
    body: Body,
    requested_model: &str,
    upstream: &HeaderMap,
    stop_sequences: Vec<String>,
) -> Response {
    let translator =
        AnthropicStreamTranslator::new(requested_model).with_stop_sequences(stop_sequences);
    let data = body.into_data_stream();
    let stream = futures_util::stream::unfold(
        (data, translator, false),
        |(mut data, mut translator, done)| async move {
            if done {
                return None;
            }
            loop {
                match data.next().await {
                    Some(Ok(chunk)) => {
                        let frames = translator.push(&chunk);
                        if frames.is_empty() {
                            continue;
                        }
                        return Some((
                            Ok::<Bytes, std::io::Error>(Bytes::from(frames.concat())),
                            (data, translator, false),
                        ));
                    }
                    Some(Err(error)) => {
                        // A mid-stream failure becomes one in-band error
                        // event, never a synthesized `message_stop` (#668).
                        let kind = crate::stream_termination::FailureKind::of(&error);
                        tracing::warn!(%error, ?kind, "bridged upstream stream failed");
                        let frames = translator.interrupt(kind);
                        return Some((Ok(Bytes::from(frames.concat())), (data, translator, true)));
                    }
                    None => {
                        let frames = translator.finish();
                        return Some((Ok(Bytes::from(frames.concat())), (data, translator, true)));
                    }
                }
            }
        },
    );

    let mut response = Response::new(Body::from_stream(stream));
    *response.status_mut() = StatusCode::OK;
    *response.headers_mut() = crate::proxy::relay_response_headers(upstream);
    response.headers_mut().insert(
        "content-type",
        HeaderValue::from_static("text/event-stream"),
    );
    response
        .headers_mut()
        .insert("cache-control", HeaderValue::from_static("no-cache"));
    response
}

use super::{IntoResponse, Response, StatusCode, Value, json};

pub(super) fn anthropic_error(status: StatusCode, body: &[u8]) -> Response {
    let text = serde_json::from_slice::<Value>(body).map_or_else(
        |_| String::from_utf8_lossy(body).to_string(),
        |value| {
            value
                .get("error")
                .and_then(|e| e.get("message"))
                .and_then(Value::as_str)
                .map_or_else(|| value.to_string(), String::from)
        },
    );
    let error_type = match status {
        StatusCode::UNAUTHORIZED | StatusCode::FORBIDDEN => "authentication_error",
        StatusCode::TOO_MANY_REQUESTS => "rate_limit_error",
        StatusCode::BAD_REQUEST => "invalid_request_error",
        _ => "api_error",
    };
    (
        status,
        axum::Json(json!({
            "type": "error",
            "error": {"type": error_type, "message": text},
        })),
    )
        .into_response()
}

//! Incremental `OpenAI` SSE to Anthropic SSE translation.
//!
//! This is the mirror image of [`crate::openai::OpenAIStreamTranslator`]: it
//! consumes the event stream produced by an `OpenAI`-dialect upstream (either
//! Chat Completions chunks or Responses events) and re-emits it using the
//! Anthropic Messages event vocabulary that Claude Code expects:
//!
//! `message_start`, `content_block_start`, `content_block_delta`,
//! `content_block_stop`, `message_delta`, `message_stop`.
//!
//! Both upstream shapes are recognised per event rather than configured up
//! front, because a single provider may emit either one depending on which
//! endpoint the request was routed to.

use std::collections::{BTreeMap, BTreeSet};

use serde_json::{Value, json};

use crate::openai::extract_sse_data;

pub use crate::stream_termination::INCOMPLETE_STREAM_MESSAGE;

/// Render one Anthropic SSE frame (named event plus JSON payload).
#[must_use]
pub fn anthropic_frame(event: &crate::translation_core::Str, payload: &crate::translation_core::Json) -> String {
    format!("event: {event}\ndata: {payload}\n\n")
}

/// Map an `OpenAI` `finish_reason` onto an Anthropic `stop_reason`.
#[must_use]
pub fn map_stop_reason(finish_reason: &crate::translation_core::Str) -> &'static crate::translation_core::Str {
    match finish_reason {
        "length" | "max_tokens" | "max_output_tokens" => "max_tokens",
        "tool_calls" | "function_call" | "tool_use" => "tool_use",
        _ => "end_turn",
    }
}

/// Incremental `OpenAI` SSE to Anthropic SSE translator.
///
/// Feed upstream bytes to [`AnthropicStreamTranslator::push`] and flush with
/// [`AnthropicStreamTranslator::finish`] when the upstream stream ends.
#[derive(Debug, Clone)]
pub struct AnthropicStreamTranslator {
    /// Client-requested model identity preserved in every response shape.
    model: String,
    id: String,
    buffer: Vec<u8>,
    started: bool,
    finished: bool,
    /// Whether the upstream sent a terminal signal (`[DONE]`, a chat
    /// `finish_reason`, or `response.completed`/`response.incomplete`).
    /// Without one, an ended upstream is a cut stream, not a finished turn.
    upstream_terminated: bool,
    /// Index of the content block currently open, if any.
    open_block: Option<usize>,
    /// Anthropic index of the text block, once opened.
    text_index: Option<usize>,
    /// Upstream tool-call index (chat) or output index (responses) mapped to
    /// the Anthropic content-block index.
    tool_indices: BTreeMap<i64, usize>,
    server_tool_indices: BTreeMap<i64, (usize, String)>,
    refusal_indices: BTreeSet<(u64, u64)>,
    next_index: usize,
    stop_reason: Option<String>,
    stop_sequence: Option<String>,
    stop_filter: crate::stop_sequences::StopSequenceFilter,
    input_tokens: u64,
    cached_input_tokens: u64,
    output_tokens: u64,
    service_tier: Option<String>,
    web_search_requests: u64,
    chat_text: String,
    response_text: BTreeMap<(u64, u64), String>,
}

impl AnthropicStreamTranslator {
    /// Create a translator for one bridged request.
    #[must_use]
    pub fn new(requested_model: &crate::translation_core::Str) -> Self {
        Self {
            model: requested_model.to_string(),
            id: format!("msg_{}", uuid::Uuid::new_v4().simple()),
            buffer: Vec::new(),
            started: false,
            finished: false,
            upstream_terminated: false,
            open_block: None,
            text_index: None,
            tool_indices: BTreeMap::new(),
            server_tool_indices: BTreeMap::new(),
            refusal_indices: BTreeSet::new(),
            next_index: 0,
            stop_reason: None,
            stop_sequence: None,
            stop_filter: crate::stop_sequences::StopSequenceFilter::default(),
            input_tokens: 0,
            cached_input_tokens: 0,
            output_tokens: 0,
            service_tier: None,
            web_search_requests: 0,
            chat_text: String::new(),
            response_text: BTreeMap::new(),
        }
    }

    /// Enforce Anthropic `stop_sequences` locally for translated backends.
    #[must_use]
    pub fn with_stop_sequences(mut self, sequences: Vec<String>) -> Self {
        self.stop_filter = crate::stop_sequences::StopSequenceFilter::new(sequences);
        self
    }

    /// Push raw upstream bytes and return zero or more Anthropic SSE frames.
    pub fn push(&mut self, chunk: &[u8]) -> Vec<String> {
        let mut frames = Vec::new();
        for block in crate::sse::push_blocks(&mut self.buffer, chunk) {
            frames.extend(self.translate_block(&block));
        }
        frames
    }

    /// Flush the stream when the upstream body ends.
    ///
    /// After a terminal upstream signal this emits the closing frames. When
    /// the upstream ended without one (issue #668) the turn is incomplete, so
    /// the client receives an Anthropic `error` event rather than a
    /// synthesized `message_stop` that would pass a cut answer off as
    /// complete.
    pub fn finish(&mut self) -> Vec<String> {
        if self.finished {
            return Vec::new();
        }
        let mut frames = self.ensure_started();
        let pending = self.stop_filter.finish();
        frames.extend(self.emit_text_delta(&pending));
        if self.upstream_terminated {
            frames.extend(self.close_stream());
        } else {
            frames.extend(self.fail_incomplete());
        }
        frames
    }

    /// End the stream after an upstream transport failure.
    ///
    /// Text already held back by the stop-sequence filter is flushed, then
    /// one Anthropic `error` event names the failure. A failure after the
    /// upstream's terminal signal closes the turn normally instead.
    pub fn interrupt(&mut self, kind: crate::stream_termination::FailureKind) -> Vec<String> {
        if self.finished || self.upstream_terminated {
            return self.finish();
        }
        let pending = self.stop_filter.finish();
        let mut frames = if pending.is_empty() {
            Vec::new()
        } else {
            let mut frames = self.ensure_started();
            frames.extend(self.emit_text_delta(&pending));
            frames
        };
        self.finished = true;
        let frame = crate::stream_termination::error_frame(
            crate::stream_termination::StreamDialect::Anthropic,
            kind,
        );
        frames.push(String::from_utf8_lossy(&frame).into_owned());
        frames
    }

    /// Whether the upstream stream ended with a terminal signal.
    #[must_use]
    pub const fn upstream_terminated(&self) -> bool {
        self.upstream_terminated
    }

    fn fail_incomplete(&mut self) -> Vec<String> {
        self.finished = true;
        let frame = crate::stream_termination::error_frame(
            crate::stream_termination::StreamDialect::Anthropic,
            crate::stream_termination::FailureKind::Truncated,
        );
        vec![String::from_utf8_lossy(&frame).into_owned()]
    }

    fn translate_block(&mut self, block: &crate::translation_core::Str) -> Vec<String> {
        let data = extract_sse_data(block);
        if data.is_empty() {
            return Vec::new();
        }
        if data == "[DONE]" {
            self.upstream_terminated = true;
            return self.finish();
        }
        let Ok(event) = serde_json::from_str::<Value>(&data) else {
            return Vec::new();
        };
        if let Some(kind) = crate::stream_termination::FailureKind::of_in_band(&event) {
            return self.interrupt(kind);
        }
        if event
            .get("type")
            .and_then(Value::as_str)
            .is_some_and(|t| t.starts_with("response.") || t == "error")
        {
            self.translate_response_event(&event)
        } else {
            self.translate_chat_event(&event)
        }
    }

    // ---- OpenAI Chat Completions chunks -------------------------------

    fn translate_chat_event(&mut self, event: &crate::translation_core::Json) -> Vec<String> {
        if self.finished {
            return Vec::new();
        }
        if let Some(model) = event.get("model").and_then(Value::as_str) {
            self.model = model.to_string();
        }
        self.absorb_usage(event.get("usage"));
        self.absorb_service_tier(event.get("service_tier"));
        let mut frames = self.ensure_started();

        let Some(choice) = event
            .get("choices")
            .and_then(Value::as_array)
            .and_then(|c| c.first())
        else {
            return frames;
        };
        if let Some(delta) = choice.get("delta") {
            if let Some(text) = delta.get("content").and_then(Value::as_str)
                && !text.is_empty()
            {
                self.chat_text.push_str(text);
                frames.extend(self.text_delta(text));
            }
            if let Some(annotations) = delta.get("annotations") {
                match crate::bridge_response::openai_annotations_to_anthropic(
                    &self.chat_text,
                    Some(annotations),
                    true,
                ) {
                    Ok(citations) => frames.extend(self.citation_deltas(citations)),
                    Err(error) => return self.fail_citation(&error),
                }
            }
            if let Some(calls) = delta.get("tool_calls").and_then(Value::as_array) {
                for call in calls {
                    frames.extend(self.tool_call_delta(call));
                }
            }
        }
        if let Some(reason) = choice.get("finish_reason").and_then(Value::as_str) {
            self.upstream_terminated = true;
            self.stop_reason = Some(map_stop_reason(reason).to_string());
        }
        frames
    }

    fn tool_call_delta(&mut self, call: &crate::translation_core::Json) -> Vec<String> {
        let key = call.get("index").and_then(Value::as_i64).unwrap_or(0);
        let mut frames = Vec::new();
        if !self.tool_indices.contains_key(&key) {
            let pending = self.stop_filter.finish();
            frames.extend(self.emit_text_delta(&pending));
            let id = call.get("id").and_then(Value::as_str).map_or_else(
                || format!("toolu_{}", uuid::Uuid::new_v4().simple()),
                String::from,
            );
            let name = call
                .get("function")
                .and_then(|f| f.get("name"))
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            frames.extend(self.close_open_block());
            let index = self.next_index;
            self.next_index += 1;
            self.tool_indices.insert(key, index);
            self.open_block = Some(index);
            frames.push(anthropic_frame(
                "content_block_start",
                &json!({
                    "type": "content_block_start",
                    "index": index,
                    "content_block": {"type": "tool_use", "id": id, "name": name, "input": {}},
                }),
            ));
        }
        let index = self.tool_indices[&key];
        if let Some(args) = call
            .get("function")
            .and_then(|f| f.get("arguments"))
            .and_then(Value::as_str)
            && !args.is_empty()
        {
            frames.push(anthropic_frame(
                "content_block_delta",
                &json!({
                    "type": "content_block_delta",
                    "index": index,
                    "delta": {"type": "input_json_delta", "partial_json": args},
                }),
            ));
        }
        frames
    }

    // ---- OpenAI Responses events --------------------------------------

    fn translate_response_event(&mut self, event: &crate::translation_core::Json) -> Vec<String> {
        if self.finished {
            return Vec::new();
        }
        let kind = event.get("type").and_then(Value::as_str).unwrap_or("");
        if let Some(model) = event
            .get("model")
            .or_else(|| event.pointer("/response/model"))
            .and_then(Value::as_str)
        {
            self.model = model.to_string();
        }
        self.absorb_usage(
            event
                .get("usage")
                .or_else(|| event.pointer("/response/usage")),
        );
        self.absorb_service_tier(
            event
                .get("service_tier")
                .or_else(|| event.pointer("/response/service_tier")),
        );
        let upstream_error = matches!(kind, "error" | "response.failed");
        let mut frames = if upstream_error {
            Vec::new()
        } else {
            self.ensure_started()
        };
        match kind {
            "response.output_text.delta" => {
                if let Some(text) = event.get("delta").and_then(Value::as_str)
                    && !text.is_empty()
                {
                    self.response_text
                        .entry(response_content_key(event))
                        .or_default()
                        .push_str(text);
                    frames.extend(self.text_delta(text));
                }
            }
            "response.output_text.annotation.added" => {
                let key = response_content_key(event);
                let text = self.response_text.get(&key).cloned().unwrap_or_default();
                let annotation = event.get("annotation").cloned().unwrap_or(Value::Null);
                match crate::bridge_response::openai_annotations_to_anthropic(
                    &text,
                    Some(&Value::Array(vec![annotation])),
                    false,
                ) {
                    Ok(citations) => frames.extend(self.citation_deltas(citations)),
                    Err(error) => return self.fail_citation(&error),
                }
            }
            "response.refusal.delta" => {
                self.refusal_indices.insert(response_content_key(event));
                if let Some(text) = event.get("delta").and_then(Value::as_str)
                    && !text.is_empty()
                {
                    frames.extend(self.text_delta(text));
                }
            }
            "response.refusal.done" => {
                if self.refusal_indices.insert(response_content_key(event))
                    && let Some(text) = event.get("refusal").and_then(Value::as_str)
                    && !text.is_empty()
                {
                    frames.extend(self.text_delta(text));
                }
            }
            "response.output_item.added" | "response.output_item.done" => {
                let item = event.get("item").unwrap_or(&Value::Null);
                let item_kind = item.get("type").and_then(Value::as_str).unwrap_or("");
                if item_kind == "function_call" {
                    let key = event
                        .get("output_index")
                        .and_then(Value::as_i64)
                        .unwrap_or(0);
                    frames.extend(self.tool_call_delta(&json!({
                        "index": key,
                        "id": item.get("call_id").or_else(|| item.get("id")).cloned().unwrap_or(Value::Null),
                        "function": {"name": item.get("name").cloned().unwrap_or(Value::Null)},
                    })));
                } else if item_kind == "web_search_call" {
                    let key = event
                        .get("output_index")
                        .and_then(Value::as_i64)
                        .unwrap_or(0);
                    if kind == "response.output_item.added" {
                        frames.extend(self.server_tool_start(key, item));
                    } else if item.get("status").and_then(Value::as_str) == Some("completed") {
                        frames.extend(self.server_tool_result(key, item));
                    }
                } else if item_kind != "message" {
                    return self.fail_output_item(item_kind);
                }
            }
            "response.function_call_arguments.delta" => {
                let key = event
                    .get("output_index")
                    .and_then(Value::as_i64)
                    .unwrap_or(0);
                if let Some(args) = event.get("delta").and_then(Value::as_str) {
                    frames.extend(self.tool_call_delta(&json!({
                        "index": key,
                        "function": {"arguments": args},
                    })));
                }
            }
            "error" | "response.failed" => {
                let error = crate::responses::response_failed_error(event)["error"].clone();
                self.finished = true;
                frames.push(anthropic_frame(
                    "error",
                    &json!({"type": "error", "error": error}),
                ));
            }
            "response.completed" | "response.incomplete" => {
                self.upstream_terminated = true;
                let response = event.get("response").unwrap_or(&Value::Null);
                self.absorb_usage(response.get("usage"));
                if self.stop_reason.is_none() {
                    self.stop_reason = Some(
                        if kind == "response.incomplete" {
                            "max_tokens"
                        } else if self.tool_indices.is_empty() {
                            "end_turn"
                        } else {
                            "tool_use"
                        }
                        .to_string(),
                    );
                }
                let pending = self.stop_filter.finish();
                frames.extend(self.emit_text_delta(&pending));
                frames.extend(self.close_stream());
            }
            _ => {}
        }
        frames
    }

    fn server_tool_start(&mut self, key: i64, item: &crate::translation_core::Json) -> Vec<String> {
        if self.server_tool_indices.contains_key(&key) {
            return Vec::new();
        }
        let mut frames = Vec::new();
        let pending = self.stop_filter.finish();
        frames.extend(self.emit_text_delta(&pending));
        frames.extend(self.close_open_block());
        let index = self.next_index;
        self.next_index += 1;
        let id = item.get("id").and_then(Value::as_str).map_or_else(
            || format!("srvtoolu_{}", uuid::Uuid::new_v4().simple()),
            str::to_string,
        );
        self.server_tool_indices.insert(key, (index, id.clone()));
        self.open_block = Some(index);
        frames.push(anthropic_frame(
            "content_block_start",
            &json!({
                "type": "content_block_start",
                "index": index,
                "content_block": {
                    "type": "server_tool_use",
                    "id": id,
                    "name": "web_search",
                    "input": item.get("action").cloned().unwrap_or_else(|| json!({})),
                },
            }),
        ));
        frames
    }

    fn server_tool_result(&mut self, key: i64, item: &crate::translation_core::Json) -> Vec<String> {
        let mut frames = Vec::new();
        if !self.server_tool_indices.contains_key(&key) {
            frames.extend(self.server_tool_start(key, item));
        }
        let Some((_, id)) = self.server_tool_indices.get(&key).cloned() else {
            return frames;
        };
        frames.extend(self.close_open_block());
        let index = self.next_index;
        self.next_index += 1;
        frames.push(anthropic_frame(
            "content_block_start",
            &json!({
                "type": "content_block_start",
                "index": index,
                "content_block": {
                    "type": "web_search_tool_result",
                    "tool_use_id": id,
                    "content": [],
                },
            }),
        ));
        frames.push(anthropic_frame(
            "content_block_stop",
            &json!({"type": "content_block_stop", "index": index}),
        ));
        self.web_search_requests = self.web_search_requests.saturating_add(1);
        frames
    }

    // ---- shared -------------------------------------------------------

    fn absorb_usage(&mut self, usage: crate::translation_core::Maybe<&crate::translation_core::Json>) {
        let Some(usage) = usage else { return };
        for key in ["input_tokens", "prompt_tokens"] {
            if let Some(v) = usage.get(key).and_then(Value::as_u64) {
                self.input_tokens = v;
            }
        }
        for key in ["output_tokens", "completion_tokens"] {
            if let Some(v) = usage.get(key).and_then(Value::as_u64) {
                self.output_tokens = v;
            }
        }
        self.cached_input_tokens = usage
            .pointer("/input_tokens_details/cached_tokens")
            .or_else(|| usage.pointer("/prompt_tokens_details/cached_tokens"))
            .and_then(Value::as_u64)
            .unwrap_or(self.cached_input_tokens)
            .min(self.input_tokens);
    }

    fn absorb_service_tier(&mut self, tier: crate::translation_core::Maybe<&crate::translation_core::Json>) {
        if let Some(tier) = crate::bridge_response::anthropic_service_tier_from_openai(tier) {
            self.service_tier = Some(tier.into());
        }
    }

    fn ensure_started(&mut self) -> Vec<String> {
        if self.started {
            return Vec::new();
        }
        self.started = true;
        let message = json!({
            "id": self.id,
            "type": "message",
            "role": "assistant",
            "model": self.model,
            "content": [],
            "stop_reason": Value::Null,
            "stop_sequence": Value::Null,
            "usage": {
                "input_tokens": self.input_tokens.saturating_sub(self.cached_input_tokens),
                "cache_creation_input_tokens": 0,
                "cache_read_input_tokens": self.cached_input_tokens,
                "output_tokens": 0
            },
        });
        vec![anthropic_frame(
            "message_start",
            &json!({
                "type": "message_start",
                "message": message,
            }),
        )]
    }

    fn text_delta(&mut self, text: &crate::translation_core::Str) -> Vec<String> {
        let (visible, matched) = self.stop_filter.push(text);
        let mut frames = self.emit_text_delta(&visible);
        if let Some(sequence) = matched {
            self.stop_reason = Some("end_turn".into());
            self.stop_sequence = Some(sequence);
            frames.extend(self.close_stream());
        }
        frames
    }

    fn emit_text_delta(&mut self, text: &crate::translation_core::Str) -> Vec<String> {
        if text.is_empty() {
            return Vec::new();
        }
        let mut frames = Vec::new();
        // Reuse the text block only while it is still the open one: Anthropic
        // allows a single open content block at a time, so text arriving after
        // a tool block starts a fresh text block instead.
        let index =
            if let (Some(index), true) = (self.text_index, self.open_block == self.text_index) {
                index
            } else {
                frames.extend(self.close_open_block());
                let index = self.next_index;
                self.next_index += 1;
                self.text_index = Some(index);
                self.open_block = Some(index);
                frames.push(anthropic_frame(
                    "content_block_start",
                    &json!({
                        "type": "content_block_start",
                        "index": index,
                        "content_block": {"type": "text", "text": ""},
                    }),
                ));
                index
            };
        frames.push(anthropic_frame(
            "content_block_delta",
            &json!({
                "type": "content_block_delta",
                "index": index,
                "delta": {"type": "text_delta", "text": text},
            }),
        ));
        frames
    }

    fn close_open_block(&mut self) -> Vec<String> {
        let Some(index) = self.open_block.take() else {
            return Vec::new();
        };
        vec![anthropic_frame(
            "content_block_stop",
            &json!({"type": "content_block_stop", "index": index}),
        )]
    }

    fn close_stream(&mut self) -> Vec<String> {
        if self.finished {
            return Vec::new();
        }
        self.finished = true;
        let mut frames = self.close_open_block();
        let stop_reason = self
            .stop_reason
            .clone()
            .unwrap_or_else(|| "end_turn".to_string());
        let mut usage = json!({
            "input_tokens": self.input_tokens.saturating_sub(self.cached_input_tokens),
            "cache_creation_input_tokens": 0,
            "cache_read_input_tokens": self.cached_input_tokens,
            "output_tokens": self.output_tokens,
        });
        if let Some(tier) = &self.service_tier {
            usage["service_tier"] = Value::String(tier.clone());
        }
        if self.web_search_requests > 0 {
            usage["server_tool_use"] = json!({
                "web_search_requests": self.web_search_requests,
                "web_fetch_requests": 0,
            });
        }
        frames.push(anthropic_frame(
            "message_delta",
            &json!({
                "type": "message_delta",
                "delta": {"stop_reason": stop_reason, "stop_sequence": self.stop_sequence},
                "usage": usage,
            }),
        ));
        frames.push(anthropic_frame(
            "message_stop",
            &json!({"type": "message_stop"}),
        ));
        frames
    }

    fn citation_deltas(&self, citations: Vec<crate::translation_core::Json>) -> Vec<String> {
        let Some(index) = self.open_block else {
            return Vec::new();
        };
        citations
            .into_iter()
            .map(|citation| {
                anthropic_frame(
                    "content_block_delta",
                    &json!({
                        "type": "content_block_delta",
                        "index": index,
                        "delta": {"type": "citations_delta", "citation": citation},
                    }),
                )
            })
            .collect()
    }

    fn fail_citation(&mut self, error: &crate::translation_core::Str) -> Vec<String> {
        self.finished = true;
        vec![anthropic_frame(
            "error",
            &json!({
                "type": "error",
                "error": {
                    "type": "api_error",
                    "message": format!("upstream returned an unrepresentable citation: {error}")
                }
            }),
        )]
    }

    fn fail_output_item(&mut self, kind: &crate::translation_core::Str) -> Vec<String> {
        self.finished = true;
        let reason = if kind.is_empty() {
            "Responses output item type must be a non-empty string".to_string()
        } else {
            crate::anthropic_bridge::unrepresentable_responses_output(kind)
        };
        vec![anthropic_frame(
            "error",
            &json!({
                "type": "error",
                "error": {"type": "api_error", "message": reason},
            }),
        )]
    }
}

fn response_content_key(event: &crate::translation_core::Json) -> (u64, u64) {
    (
        event
            .get("output_index")
            .and_then(crate::translation_core::Json::as_u64)
            .unwrap_or(0),
        event
            .get("content_index")
            .and_then(crate::translation_core::Json::as_u64)
            .unwrap_or(0),
    )
}

#[cfg(test)]
#[path = "anthropic_stream_termination_tests.rs"]
mod termination_tests;

#[cfg(test)]
mod tests {
    use super::*;

    fn joined(frames: &[String]) -> String {
        frames.join("")
    }

    #[test]
    fn translates_chat_chunks_to_anthropic_events() {
        let mut t = AnthropicStreamTranslator::new("claude-sonnet-4-5");
        let mut out = String::new();
        out.push_str(&joined(&t.push(
            b"data: {\"object\":\"chat.completion.chunk\",\"choices\":[{\"delta\":{\"role\":\"assistant\"}}]}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data: {\"object\":\"chat.completion.chunk\",\"choices\":[{\"delta\":{\"content\":\"Hel\"}}]}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data: {\"object\":\"chat.completion.chunk\",\"choices\":[{\"delta\":{\"content\":\"lo\"},\"finish_reason\":\"stop\"}]}\n\n",
        )));
        out.push_str(&joined(&t.push(b"data: [DONE]\n\n")));

        assert!(out.contains("event: message_start"));
        assert!(out.contains("\"model\":\"claude-sonnet-4-5\""));
        assert!(out.contains("event: content_block_start"));
        assert!(out.contains("\"text_delta\""));
        assert!(out.contains("\"text\":\"Hel\""));
        assert!(out.contains("\"text\":\"lo\""));
        assert!(out.contains("event: content_block_stop"));
        assert!(out.contains("\"stop_reason\":\"end_turn\""));
        assert!(out.contains("event: message_stop"));
    }

    #[test]
    fn streaming_bridge_preserves_served_model_without_private_metadata() {
        let mut translator = AnthropicStreamTranslator::new("claude/catalog-alias");
        let output = joined(&translator.push(
            b"data: {\"object\":\"chat.completion.chunk\",\"model\":\"future-upstream-model\",\"choices\":[{\"delta\":{\"content\":\"hi\"}}]}\n\n",
        ));

        assert!(output.contains("\"model\":\"future-upstream-model\""));
        assert!(!output.contains("x_router_"));
    }

    #[test]
    fn upstream_identity_error_does_not_invent_a_message_start_model() {
        let mut translator = AnthropicStreamTranslator::new("requested-but-unverified");
        let output = joined(&translator.push(
            b"event: error\ndata: {\"type\":\"error\",\"error\":{\"type\":\"served_model_unknown\",\"message\":\"missing\"}}\n\n",
        ));
        assert!(output.contains("event: error"), "{output}");
        assert!(!output.contains("event: message_start"), "{output}");
        assert!(!output.contains("requested-but-unverified"), "{output}");
    }

    #[test]
    fn translates_chat_tool_calls_to_tool_use_blocks() {
        let mut t = AnthropicStreamTranslator::new("claude-sonnet-4-5");
        let mut out = String::new();
        out.push_str(&joined(&t.push(
            b"data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,\"id\":\"call_1\",\"function\":{\"name\":\"get_time\",\"arguments\":\"\"}}]}}]}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,\"function\":{\"arguments\":\"{\\\"tz\\\":\"}}]}}]}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"tool_calls\"}]}\n\n",
        )));
        out.push_str(&joined(&t.finish()));

        assert!(out.contains("\"type\":\"tool_use\""));
        assert!(out.contains("\"name\":\"get_time\""));
        assert!(out.contains("\"id\":\"call_1\""));
        assert!(out.contains("\"input_json_delta\""));
        assert!(out.contains("\"stop_reason\":\"tool_use\""));
    }

    #[test]
    fn translates_responses_events_to_anthropic_events() {
        let mut t = AnthropicStreamTranslator::new("claude-opus-4-7");
        let mut out = String::new();
        out.push_str(&joined(&t.push(
            b"data: {\"type\":\"response.created\",\"response\":{\"id\":\"resp_1\"}}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data: {\"type\":\"response.output_text.delta\",\"delta\":\"hi\"}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data: {\"type\":\"response.completed\",\"response\":{\"usage\":{\"input_tokens\":11,\"output_tokens\":3}}}\n\n",
        )));

        assert!(out.contains("event: message_start"));
        assert!(out.contains("\"text\":\"hi\""));
        assert!(out.contains("\"output_tokens\":3"));
        assert!(out.contains("event: message_stop"));
    }

    #[test]
    fn incomplete_responses_stream_uses_max_tokens() {
        let mut t = AnthropicStreamTranslator::new("claude-opus-4-7");
        let out = joined(&t.push(b"data: {\"type\":\"response.incomplete\",\"response\":{}}\n\n"));

        assert!(out.contains("\"stop_reason\":\"max_tokens\""), "{out}");
        assert!(out.contains("event: message_stop"), "{out}");
    }

    #[test]
    fn failed_responses_stream_after_deltas_emits_anthropic_error() {
        let mut t = AnthropicStreamTranslator::new("claude-opus-4-7");
        let mut out = joined(&t.push(
            b"data: {\"type\":\"response.output_text.delta\",\"delta\":\"partial\"}\n\ndata: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"type\":\"function_call\",\"call_id\":\"call_1\",\"name\":\"lookup\"}}\n\ndata: {\"type\":\"response.function_call_arguments.delta\",\"output_index\":0,\"delta\":\"{}\"}\n\n",
        ));
        out.push_str(&joined(&t.push(b"data: {\"type\":\"response.failed\",\"response\":{\"error\":{\"message\":\"boom\",\"type\":\"server_error\",\"code\":\"upstream_failed\",\"param\":\"input\"}}}\n\ndata: [DONE]\n\n")));

        assert!(out.contains("partial"), "{out}");
        assert!(out.contains("event: error"), "{out}");
        assert!(out.contains("\"message\":\"boom\""), "{out}");
        assert!(out.contains("\"code\":\"upstream_failed\""), "{out}");
        assert!(!out.contains("\"stop_reason\":\""), "{out}");
        assert!(!out.contains("event: message_stop"), "{out}");
    }

    #[test]
    fn standalone_error_after_deltas_emits_anthropic_error() {
        let mut t = AnthropicStreamTranslator::new("claude-opus-4-7");
        let mut out = joined(&t.push(
            b"data: {\"type\":\"response.output_text.delta\",\"delta\":\"partial\"}\n\ndata: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"type\":\"function_call\",\"call_id\":\"call_1\",\"name\":\"lookup\"}}\n\ndata: {\"type\":\"response.function_call_arguments.delta\",\"output_index\":0,\"delta\":\"{}\"}\n\n",
        ));
        out.push_str(&joined(&t.push(b"data: {\"type\":\"error\",\"message\":\"standalone boom\",\"code\":\"server_error\",\"param\":\"input\",\"private_account\":\"secret\"}\n\ndata: {\"type\":\"response.completed\",\"response\":{}}\n\ndata: [DONE]\n\n")));

        assert!(out.contains("partial"), "{out}");
        assert!(out.contains("event: error"), "{out}");
        assert!(out.contains("\"message\":\"standalone boom\""), "{out}");
        assert!(out.contains("\"code\":\"server_error\""), "{out}");
        assert!(!out.contains("private_account"), "{out}");
        assert!(!out.contains("\"stop_reason\":\""), "{out}");
        assert!(!out.contains("event: message_stop"), "{out}");
    }

    #[test]
    fn streamed_refusal_is_displayed_in_source_order_without_duplication() {
        let mut t = AnthropicStreamTranslator::new("claude-opus-4-7");
        let out = joined(&t.push(b"data: {\"type\":\"response.output_text.delta\",\"output_index\":0,\"content_index\":0,\"delta\":\"before \"}\n\ndata: {\"type\":\"response.refusal.delta\",\"output_index\":0,\"content_index\":1,\"delta\":\"cannot comply\"}\n\ndata: {\"type\":\"response.refusal.done\",\"output_index\":0,\"content_index\":1,\"refusal\":\"cannot comply\"}\n\ndata: {\"type\":\"response.output_text.delta\",\"output_index\":1,\"content_index\":0,\"delta\":\" after\"}\n\ndata: {\"type\":\"response.completed\",\"response\":{}}\n\n"));

        let before = out.find("\"text\":\"before \"").unwrap();
        let refusal = out.find("\"text\":\"cannot comply\"").unwrap();
        let after = out.find("\"text\":\" after\"").unwrap();
        assert!(before < refusal && refusal < after, "{out}");
        assert_eq!(out.matches("\"text\":\"cannot comply\"").count(), 1);
        assert!(out.contains("\"stop_reason\":\"end_turn\""), "{out}");
    }

    #[test]
    fn responses_function_calls_become_tool_use() {
        let mut t = AnthropicStreamTranslator::new("claude-opus-4-7");
        let mut out = String::new();
        out.push_str(&joined(&t.push(
            b"data: {\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"type\":\"function_call\",\"call_id\":\"fc_1\",\"name\":\"lookup\"}}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data: {\"type\":\"response.function_call_arguments.delta\",\"output_index\":0,\"delta\":\"{\\\"q\\\":1}\"}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data: {\"type\":\"response.completed\",\"response\":{}}\n\n",
        )));

        assert!(out.contains("\"type\":\"tool_use\""));
        assert!(out.contains("\"name\":\"lookup\""));
        assert!(out.contains("\"input_json_delta\""));
        assert!(out.contains("\"stop_reason\":\"tool_use\""));
    }

    #[test]
    fn responses_web_search_stays_a_server_tool_and_reports_usage() {
        let mut t = AnthropicStreamTranslator::new("gpt-5.6-sol");
        let mut out = String::new();
        out.push_str(&joined(&t.push(
            b"data:{\"type\":\"response.output_item.added\",\"output_index\":0,\"item\":{\"type\":\"web_search_call\",\"id\":\"ws_1\",\"status\":\"in_progress\",\"action\":{\"query\":\"Rust\"}}}\n\n",
        )));
        out.push_str(&joined(&t.push(
            b"data:{\"type\":\"response.output_item.done\",\"output_index\":0,\"item\":{\"type\":\"web_search_call\",\"id\":\"ws_1\",\"status\":\"completed\"}}\n\n",
        )));
        out.push_str(&joined(
            &t.push(b"data:{\"type\":\"response.completed\",\"response\":{}}\n\n"),
        ));

        assert!(out.contains("\"type\":\"server_tool_use\""));
        assert!(out.contains("\"type\":\"web_search_tool_result\""));
        assert!(out.contains("\"web_search_requests\":1"));
        assert!(!out.contains("\"type\":\"tool_use\""));
    }

    #[test]
    fn provider_specific_responses_output_fails_the_stream_without_exposing_content() {
        for (item, marker, private_value) in [
            (
                json!({
                    "type": "reasoning",
                    "summary": [{"type": "summary_text", "text": "checked the constraints"}],
                    "encrypted_content": "private-reasoning-state"
                }),
                "reasoning",
                "private-reasoning-state",
            ),
            (
                json!({
                    "type": "custom_tool_call",
                    "call_id": "call_1",
                    "name": "apply_patch",
                    "input": "private-tool-input"
                }),
                "custom_tool_call",
                "private-tool-input",
            ),
        ] {
            let mut translator = AnthropicStreamTranslator::new("claude-test");
            let event = json!({
                "type": "response.output_item.added",
                "output_index": 0,
                "item": item,
            });
            let out = joined(&translator.push(format!("data: {event}\n\n").as_bytes()));

            assert!(out.contains("event: error"), "{marker}: {out}");
            assert!(out.contains(marker), "{marker}: {out}");
            assert!(!out.contains(private_value), "{marker}: {out}");
            assert!(translator.finish().is_empty(), "{marker}");
        }
    }

    #[test]
    fn anthropic_stop_sequence_is_enforced_across_sse_chunks() {
        let mut t =
            AnthropicStreamTranslator::new("gpt-5.6-sol").with_stop_sequences(vec!["<END>".into()]);
        let first = joined(
            &t.push(b"data:{\"type\":\"response.output_text.delta\",\"delta\":\"visible<E\"}\n\n"),
        );
        let second = joined(
            &t.push(b"data:{\"type\":\"response.output_text.delta\",\"delta\":\"ND>hidden\"}\n\n"),
        );
        let out = format!("{first}{second}");
        assert!(out.contains("visible"));
        assert!(!out.contains("\"text\":\"<END>\""));
        assert!(!out.contains("hidden"));
        assert!(out.contains("\"stop_sequence\":\"<END>\""));
        assert!(out.contains("event: message_stop"));
    }

    #[test]
    fn finish_is_idempotent_and_reports_a_cut_stream_as_an_error() {
        let mut t = AnthropicStreamTranslator::new("claude-sonnet-4-5");
        let first = joined(&t.finish());
        assert!(first.contains("event: message_start"));
        assert!(first.contains("event: error"), "{first}");
        assert!(first.contains(INCOMPLETE_STREAM_MESSAGE), "{first}");
        assert!(!first.contains("message_stop"), "{first}");
        assert!(t.finish().is_empty());
    }
}

use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};

/// Protocol-independent failure data. Rendering is selected only at the API
/// boundary, keeping diagnosis separate from vendor presentation.
#[derive(Clone, Copy, Debug)]
pub struct PresentedError<'a> {
    pub status: StatusCode,
    pub error_type: &'a str,
    pub message: &'a str,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ApiDialect {
    Anthropic,
    OpenAi,
    Gemini,
    GitHub,
}

#[must_use]
pub fn dialect_for_path(path: &str) -> ApiDialect {
    crate::route_contract::dialect_for_path(path).unwrap_or(ApiDialect::Anthropic)
}

impl PresentedError<'_> {
    pub fn render(self, dialect: ApiDialect) -> Response {
        let body = match dialect {
            ApiDialect::Anthropic => serde_json::json!({
                "type": "error",
                "error": {"type": self.error_type, "message": self.message}
            }),
            ApiDialect::OpenAi => serde_json::json!({
                "error": {"type": self.error_type, "message": self.message}
            }),
            ApiDialect::Gemini => serde_json::json!({
                "error": {
                    "code": self.status.as_u16(),
                    "message": self.message,
                    "status": google_status(self.status),
                }
            }),
            ApiDialect::GitHub => serde_json::json!({"message": self.message}),
        };
        (self.status, axum::Json(body)).into_response()
    }
}

const fn google_status(status: StatusCode) -> &'static str {
    match status.as_u16() {
        400 => "INVALID_ARGUMENT",
        401 => "UNAUTHENTICATED",
        403 => "PERMISSION_DENIED",
        404 => "NOT_FOUND",
        429 => "RESOURCE_EXHAUSTED",
        503 => "UNAVAILABLE",
        _ => "INTERNAL",
    }
}

/// Build the shared JSON error envelope used by all client API dialects.
pub fn error_response(status: StatusCode, error_type: &str, message: &str) -> Response {
    PresentedError {
        status,
        error_type,
        message,
    }
    .render(ApiDialect::Anthropic)
}

pub fn error_response_for_surface(
    surface: crate::metrics::Surface,
    status: StatusCode,
    error_type: &str,
    message: &str,
) -> Response {
    let dialect = match surface {
        crate::metrics::Surface::Anthropic => ApiDialect::Anthropic,
        crate::metrics::Surface::OpenAIChat | crate::metrics::Surface::OpenAIResponses => {
            ApiDialect::OpenAi
        }
    };
    PresentedError {
        status,
        error_type,
        message,
    }
    .render(dialect)
}

/// `OpenAI` error `type` for an upstream status.
///
/// Mirrors the mappings the Anthropic and Gemini surfaces already apply
/// (`anthropic_bridge::anthropic_error`, `gemini_bridge::openai_error_to_gemini`)
/// so one upstream failure is classified the same way on every surface.
const fn openai_error_type(status: u16) -> &'static str {
    match status {
        400 | 404 | 422 => "invalid_request_error",
        401 => "authentication_error",
        403 => "permission_error",
        429 => "rate_limit_error",
        _ => "api_error",
    }
}

/// The `code` an `OpenAI` client reads to classify a failure programmatically.
const fn openai_error_code(status: u16) -> Option<&'static str> {
    match status {
        401 => Some("invalid_api_key"),
        403 => Some("permission_denied"),
        404 => Some("model_not_found"),
        429 => Some("rate_limit_exceeded"),
        _ => None,
    }
}

/// Re-shape an upstream vendor error as an `OpenAI` error envelope.
///
/// The `OpenAI` surfaces used to relay the vendor's body verbatim, which had two
/// consequences (issue #213): a client written against the `OpenAI` SDK could not
/// classify the failure, because the vendor's `type` is not an `OpenAI` error
/// type; and the body carried fields describing the *router operator's*
/// subscription — `plan_type`, `eligible_promo`, `resets_at` — which say nothing
/// about the caller's request and, in a shared deployment, disclose the
/// operator's billing posture to every caller who triggers a `429`.
///
/// Only what the caller can act on is preserved: the status, the message, and
/// retry timing. The full upstream body is still captured by the request log
/// (`record_upstream_body`), so nothing is lost for diagnosis.
#[must_use]
pub fn openai_error_body(status: u16, upstream: &[u8]) -> serde_json::Value {
    let parsed = serde_json::from_slice::<serde_json::Value>(upstream).ok();
    let vendor_message = parsed.as_ref().and_then(|value| {
        value
            .pointer("/error/message")
            .or_else(|| value.pointer("/message"))
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
    });
    let message = vendor_message.unwrap_or_else(|| {
        let text = String::from_utf8_lossy(upstream);
        let text = text.trim();
        if text.is_empty() {
            "upstream request failed".to_string()
        } else {
            text.to_string()
        }
    });
    serde_json::json!({
        "error": {
            "message": message,
            "type": openai_error_type(status),
            "param": serde_json::Value::Null,
            "code": openai_error_code(status),
        }
    })
}

pub fn malformed_json_response(error: &str) -> Response {
    error_response(
        StatusCode::BAD_REQUEST,
        "invalid_request_error",
        &format!("Failed to parse request body as JSON: {error}"),
    )
}

pub fn malformed_json_response_for_surface(
    surface: crate::metrics::Surface,
    error: &str,
) -> Response {
    error_response_for_surface(
        surface,
        StatusCode::BAD_REQUEST,
        "invalid_request_error",
        &format!("Failed to parse request body as JSON: {error}"),
    )
}

pub fn malformed_json_response_for_dialect(dialect: ApiDialect, error: &str) -> Response {
    let message = format!("Failed to parse request body as JSON: {error}");
    PresentedError {
        status: StatusCode::BAD_REQUEST,
        error_type: "invalid_request_error",
        message: &message,
    }
    .render(dialect)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn one_error_renders_in_each_vendor_dialect() {
        for (dialect, required, forbidden) in [
            (ApiDialect::Anthropic, "\"type\":\"error\"", "\"code\":"),
            (ApiDialect::OpenAi, "\"error\":", "\"type\":\"error\""),
            (ApiDialect::Gemini, "INVALID_ARGUMENT", "documentation_url"),
            (ApiDialect::GitHub, "\"message\":\"bad\"", "\"error\":"),
        ] {
            let response = PresentedError {
                status: StatusCode::BAD_REQUEST,
                error_type: "invalid_request_error",
                message: "bad",
            }
            .render(dialect);
            let body = axum::body::to_bytes(response.into_body(), 4096)
                .await
                .unwrap();
            let body = String::from_utf8(body.to_vec()).unwrap();
            assert!(body.contains(required), "{dialect:?}: {body}");
            assert!(!body.contains(forbidden), "{dialect:?}: {body}");
        }
    }
}

//! Shared state used by HTTP route handlers.

use std::sync::Arc;

use log_lazy::LogLazy;
use reqwest::Client;

use crate::accounts::AccountRouter;
use crate::config::UpstreamProvider;
use crate::gonka::GonkaConfig;
use crate::oauth::OAuthProvider;
use crate::providers::{OpenAICompatibleConfig, ProviderStore};
use crate::token::TokenManager;

/// Shared application state accessible by all route handlers.
#[derive(Clone)]
pub struct AppState {
    /// HTTP client for upstream requests.
    pub client: Client,
    /// Token manager for validating custom tokens.
    pub token_manager: TokenManager,
    /// OAuth provider for obtaining upstream credentials (legacy single-account).
    pub oauth_provider: OAuthProvider,
    /// Multi-account router (when configured). When `None`, the legacy
    /// `oauth_provider` is used directly.
    pub account_router: Option<AccountRouter>,
    /// Subscription credential reader for vendor OAuth providers
    /// (Codex/Gemini/Qwen). `None` for non-subscription upstreams.
    pub subscription_reader: Option<crate::subscription::SubscriptionReader>,
    /// Optional subscription API base URL override.
    ///
    /// Production leaves this unset and uses the provider's canonical URL;
    /// integration tests use it to drive the real forwarding path against a
    /// local deterministic upstream.
    pub subscription_base_url: Option<String>,
    /// Credential readers for every discoverable vendor subscription.
    pub subscription_readers: Vec<crate::subscription::SubscriptionReader>,
    /// Last known live model catalogs, refreshed independently in the background.
    pub model_catalogs: Arc<crate::model_catalog::ModelCatalogCache>,
    /// In-memory cache of refreshed subscription tokens (Codex/Gemini/Qwen).
    pub subscription_cache: Arc<crate::refresh::TokenCache>,
    /// Base URL for the upstream Anthropic API.
    pub upstream_base_url: String,
    /// Selected upstream inference provider.
    pub upstream_provider: UpstreamProvider,
    /// Gonka provider configuration when selected.
    pub gonka: Option<GonkaConfig>,
    /// Upstream model used when an Anthropic-dialect request is bridged to a
    /// non-Anthropic upstream. `None` selects one from the live catalog using
    /// [`AppState::bridge_model_policy`].
    pub bridge_model: Option<String>,
    /// How a bridge model is chosen from the live catalog when
    /// [`AppState::bridge_model`] is unset.
    pub bridge_model_policy: crate::bridge_selection::BridgeModelPolicy,
    /// Crater `ForgeFed` task provider when selected.
    pub crater: Option<Arc<dyn crate::crater::TaskProvider>>,
    /// Boot-time generic OpenAI-compatible provider config.
    pub openai_compatible: OpenAICompatibleConfig,
    /// Persisted provider records with encrypted upstream secrets.
    pub provider_store: ProviderStore,
    /// Lazy logger for verbose output.
    pub logger: LogLazy,
    /// Maximum request body accepted by raw proxy surfaces.
    pub max_proxy_request_bytes: usize,
    /// Admin credential state: the optional deploy-time key plus the
    /// first-visitor claim of the admin UI (see [`crate::admin`]).
    pub admin: Arc<crate::admin::AdminClaim>,
    /// Optional flat bootstrap admin key (Bearer) accepted by the admin
    /// endpoints alongside admin-scoped `la_sk_…` tokens.
    pub admin_key: Option<String>,
    /// Whether the admin endpoints stay open to unauthenticated callers.
    /// Defaults to `false`; set only by an explicit `--allow-anonymous-admin`.
    pub allow_anonymous_admin: bool,
    /// Live metrics counter handle.
    pub metrics: Arc<crate::metrics::Metrics>,
    /// Append-only per-token audit log (disabled unless a path is configured).
    pub audit: Arc<crate::audit::AuditLog>,
    /// Redacted bounded log of complete HTTP exchanges.
    pub request_log: Arc<crate::request_log::RequestLog>,
    /// Public base URL for `ActivityPub` actor documents.
    pub activitypub_actor_base_url: String,
    /// Public key PEM advertised by the `ActivityPub` actor.
    pub activitypub_public_key_pem: String,
    /// Optional MPP charge settings for OpenAI-compatible endpoints.
    pub mpp: crate::mpp::MppConfig,
    /// Registry of in-flight interactive login sessions (`/api/management/login`).
    pub login_manager: crate::login::LoginManager,
    /// Optional GitHub credential proxy and destructive-operation policy.
    pub github: crate::github_proxy::GitHubProxyConfig,
}

impl AppState {
    /// Tell the token cache where every subscription credential lives, and
    /// which vendor client may rotate one it cannot.
    ///
    /// Called once before the first request is served, so a refresh on the
    /// serving path can re-read and write back the same file the catalog
    /// poller does. A rotation that only ever lives in memory is lost at
    /// restart and leaves a spent refresh token on disk (issue #239).
    ///
    /// `vendor_clis` names the operator-configured vendor binaries
    /// (`--claude-cli-bin` / `CLAUDE_CLI_BIN`, `--codex-cli-bin` /
    /// `CODEX_CLI_BIN`). Without one the last rung of the recovery ladder stays
    /// inert for that provider: running a vendor client is a side effect nobody
    /// should get without asking for it.
    ///
    /// Registered per provider rather than for Claude alone. A Codex credential
    /// is an OAuth chain with the same single-use rotation, so a deployment
    /// that could recover a Claude subscription automatically but needed an
    /// operator for Codex was drawing a line the credentials do not (#275).
    pub fn register_credential_recovery(&self, vendor_clis: &VendorClis<'_>) {
        self.subscription_cache.register_readers(
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
            &self.subscription_readers,
        );
        if let Some(router) = &self.account_router {
            router.register_credential_stores(&self.subscription_cache);
        }
        self.register_vendor_clis(vendor_clis);
    }

    /// Register durable data-directory recovery for every credential.
    pub fn register_credential_recovery_in(
        &self,
        data_dir: &std::path::Path,
        vendor_clis: &VendorClis<'_>,
    ) {
        self.subscription_cache.register_readers_in(
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
            &self.subscription_readers,
            data_dir,
        );
        if let Some(router) = &self.account_router {
            router.register_credential_stores_in(&self.subscription_cache, data_dir);
        }
        self.register_vendor_clis(vendor_clis);
    }

    fn register_vendor_clis(&self, vendor_clis: &VendorClis<'_>) {
        for reader in &self.subscription_readers {
            let Some(binary) = vendor_clis.binary_for(reader.provider()) else {
                continue;
            };
            let Some(cli) = crate::vendor_cli_refresh::VendorCli::for_provider(
                reader.provider(),
                binary,
                reader.home(),
            ) else {
                continue;
            };
            self.subscription_cache.register_vendor_cli(
                crate::credential_recovery_store::PRIMARY_ACCOUNT,
                Arc::new(cli),
            );
        }
    }
}

impl AppState {
    /// A minimal state for exercising handlers in-process.
    ///
    /// Every field is inert: no credentials, no upstreams, no listeners. A
    /// test overrides only what it is about, so the rest cannot quietly take
    /// part in the behaviour under test.
    #[cfg(test)]
    #[must_use]
    pub fn for_tests(data_dir: &std::path::Path) -> Self {
        use std::sync::Arc;
        Self {
            client: reqwest::Client::new(),
            token_manager: crate::token::TokenManager::new("test-secret"),
            oauth_provider: crate::oauth::OAuthProvider::new(&data_dir.to_string_lossy()),
            account_router: None,
            subscription_reader: None,
            subscription_base_url: None,
            subscription_readers: Vec::new(),
            model_catalogs: Arc::new(crate::model_catalog::ModelCatalogCache::new()),
            subscription_cache: Arc::new(crate::refresh::TokenCache::new()),
            upstream_base_url: "https://api.anthropic.com".to_string(),
            upstream_provider: crate::config::UpstreamProvider::Auto,
            gonka: None,
            bridge_model: None,
            bridge_model_policy: crate::bridge_selection::BridgeModelPolicy::default(),
            crater: None,
            openai_compatible: crate::config::default_openai_compatible_config(),
            provider_store: crate::providers::ProviderStore::open(data_dir, "test-secret")
                .expect("open a provider store"),
            logger: log_lazy::LogLazy::new(),
            admin: Arc::new(crate::admin::AdminClaim::load(
                None,
                data_dir,
                std::time::Duration::from_secs(60),
            )),
            admin_key: None,
            allow_anonymous_admin: false,
            metrics: Arc::new(crate::metrics::Metrics::default()),
            audit: Arc::new(crate::audit::AuditLog::to_path(None)),
            request_log: Arc::new(crate::request_log::RequestLog::new(
                data_dir.join("requests"),
                1024 * 1024,
            )),
            activitypub_actor_base_url: "https://router.example".to_string(),
            activitypub_public_key_pem: crate::config::default_activitypub_public_key_pem(),
            mpp: crate::config::default_mpp_config(),
            login_manager: crate::login::LoginManager::new(crate::login::LoginConfig::default()),
            github: crate::github_proxy::GitHubProxyConfig::default(),
            max_proxy_request_bytes: crate::config::DEFAULT_MAX_PROXY_REQUEST_BYTES,
        }
    }
}

/// The vendor client binaries an operator configured, per provider.
///
/// A struct rather than more parameters so adding a third provider does not
/// change every call site again.
#[derive(Debug, Default, Clone, Copy)]
pub struct VendorClis<'a> {
    pub claude: Option<&'a std::path::Path>,
    pub codex: Option<&'a std::path::Path>,
}

impl<'a> VendorClis<'a> {
    /// The binary configured for `provider`, if any.
    #[must_use]
    pub const fn binary_for(
        &self,
        provider: crate::subscription::SubscriptionProvider,
    ) -> Option<&'a std::path::Path> {
        match provider {
            crate::subscription::SubscriptionProvider::Claude => self.claude,
            crate::subscription::SubscriptionProvider::Codex => self.codex,
            crate::subscription::SubscriptionProvider::Gemini
            | crate::subscription::SubscriptionProvider::Qwen => None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn legacy_and_durable_registration_wrappers_share_the_same_readers() {
        let root = tempfile::tempdir().expect("state directory");
        let mut state = AppState::for_tests(root.path());
        state
            .subscription_readers
            .push(crate::subscription::SubscriptionReader::new(
                crate::subscription::SubscriptionProvider::Qwen,
                root.path().join("qwen"),
            ));

        state.register_credential_recovery(&VendorClis::default());
        assert!(
            state
                .subscription_cache
                .store_for_subscription(
                    crate::subscription::SubscriptionProvider::Qwen,
                    crate::credential_recovery_store::PRIMARY_ACCOUNT,
                )
                .is_some()
        );

        state.register_credential_recovery_in(root.path(), &VendorClis::default());
        assert!(
            state
                .subscription_cache
                .store_for_subscription(
                    crate::subscription::SubscriptionProvider::Qwen,
                    crate::credential_recovery_store::PRIMARY_ACCOUNT,
                )
                .is_some()
        );
    }

    #[test]
    fn registration_installs_only_supported_configured_vendor_clients() {
        let root = tempfile::tempdir().expect("state directory");
        let mut state = AppState::for_tests(root.path());
        for provider in [
            crate::subscription::SubscriptionProvider::Claude,
            crate::subscription::SubscriptionProvider::Codex,
            crate::subscription::SubscriptionProvider::Gemini,
            crate::subscription::SubscriptionProvider::Qwen,
        ] {
            state
                .subscription_readers
                .push(crate::subscription::SubscriptionReader::new(
                    provider,
                    root.path().join(provider.as_str()),
                ));
        }
        let claude = root.path().join("claude-cli");
        let codex = root.path().join("codex-cli");

        state.register_credential_recovery(&VendorClis {
            claude: Some(&claude),
            codex: Some(&codex),
        });

        for provider in [
            crate::subscription::SubscriptionProvider::Claude,
            crate::subscription::SubscriptionProvider::Codex,
        ] {
            assert!(
                state
                    .subscription_cache
                    .vendor_cli_for(provider, crate::credential_recovery_store::PRIMARY_ACCOUNT,)
                    .is_some(),
                "{provider} configured client was not registered"
            );
        }
        for provider in [
            crate::subscription::SubscriptionProvider::Gemini,
            crate::subscription::SubscriptionProvider::Qwen,
        ] {
            assert!(
                state
                    .subscription_cache
                    .vendor_cli_for(provider, crate::credential_recovery_store::PRIMARY_ACCOUNT,)
                    .is_none(),
                "{provider} must not invent an unsupported vendor probe"
            );
        }
    }
}

//! Append-only per-token audit log.
//!
//! Issue #45 asks for "each task a separate token … for
//! audit/monitoring/security/isolation". Per-token counters live in
//! [`crate::metrics`]; this module adds the durable half: one JSON object per
//! line (JSONL), appended as requests are authorised, so an operator can
//! reconstruct after the fact which task token did what.
//!
//! The log is **off by default** and only writes when a path is configured
//! (`--audit-log` / `AUDIT_LOG`). It records the token *id* (the JWT `sub`)
//! and its label — never the token string, never any upstream credential — so
//! the file is safe to ship to a log collector.
//!
//! # Why this one is still JSON
//!
//! Router-owned state is links notation, and the per-token request log moved
//! to it as well (issue #336). This file did not, deliberately: it is an
//! outbound stream whose reader is somebody else's log collector, and the
//! recipes this project publishes for it pipe it into `jq`. Changing its
//! format would break those readers to make a file this project never parses
//! look consistent. The decision is recorded here rather than left to be
//! inferred from which module the write lives in (issue #346).

use std::fs::OpenOptions;
use std::io::Write as _;
use std::path::PathBuf;

#[cfg(unix)]
use std::os::unix::fs::{OpenOptionsExt as _, PermissionsExt as _};

use serde::Serialize;

/// One audit record, serialised as a single JSON line.
#[derive(Debug, Clone, Serialize)]
pub struct AuditEvent {
    /// Lifecycle point for this record (`request_authorized` or
    /// `response_completed`).
    pub phase: String,
    /// RFC 3339 timestamp of the authorisation.
    pub time: String,
    /// Router token id (JWT `sub`) — not the token itself.
    pub token_id: String,
    /// Human label given when the token was issued.
    pub label: String,
    /// Upstream provider that served the request.
    pub provider: String,
    /// Exact provider account/principal selected for the exchange, when the
    /// route has an account dimension.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub provider_account: Option<String>,
    /// Exact upstream endpoint selected for the exchange, when known.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub provider_endpoint: Option<String>,
    /// Client-facing API surface (`anthropic`, `openai_chat`, …).
    pub surface: String,
    /// Request path as seen by the router.
    pub path: String,
    /// Signed managed-client adapter, when this was a bound token.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub client_kind: Option<String>,
    /// Exact risk-accepted matrix cell, when native entitlement was not used.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub subscription_override: Option<String>,
    /// Native client identity accepted through an operator-enabled proxy.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub proxied_client_override: Option<String>,
    /// Model requested by the client, when the body carried one.
    pub model: Option<String>,
    /// Canonical model sent upstream when it differs from the requested id.
    pub resolved_model: Option<String>,
    /// Evidence-backed semantics of the exact requested selector.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub selector_kind: Option<crate::model_contract::ModelSelectorKind>,
    /// Why the requested and served identities were accepted together.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub resolution_reason: Option<String>,
    /// Durable exact-selector authority applied before routing this request.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub model_policy: Option<crate::model_contract::ModelAccessPolicy>,
    /// Concrete identity reported by the upstream response, when this record
    /// represents a completed buffered exchange.
    pub served_model: Option<String>,
    /// Canonical descriptor shared with launch and model diagnostics. The
    /// legacy flat fields above remain for existing JSONL consumers.
    pub model_descriptor: crate::model_contract::ModelTruthDescriptor,
}

impl AuditEvent {
    fn refresh_model_descriptor(&mut self) {
        let policy = self.model_policy.as_ref();
        self.model_descriptor = crate::model_contract::ModelTruthDescriptor {
            requested_selector: self.model.clone(),
            selector_kind: self.selector_kind.unwrap_or_default(),
            route: crate::model_contract::ModelRouteScope {
                provider: (!self.provider.is_empty()).then(|| self.provider.clone()),
                account: self.provider_account.clone(),
                endpoint: self.provider_endpoint.clone(),
                protocols: if self.surface == "control_plane" {
                    Vec::new()
                } else {
                    vec![self.surface.clone()]
                },
            },
            upstream_request_model: self.resolved_model.clone().or_else(|| self.model.clone()),
            upstream_served_model: self.served_model.clone(),
            capabilities: serde_json::Value::Null,
            capability_provenance: serde_json::Value::Null,
            allow_substitution: policy.is_some_and(|policy| policy.allow_substitution),
            substitution_source: policy.and_then(|policy| policy.substitution_source.clone()),
        };
    }
}

/// Append-only JSONL audit sink.
///
/// Cloning is cheap; every call re-opens the file in append mode so an
/// external rotator (logrotate, `copytruncate`, …) can move it underneath a
/// running router without restarting the process.
#[derive(Debug, Clone, Default)]
pub struct AuditLog {
    path: Option<PathBuf>,
}

impl AuditLog {
    /// An audit log that discards everything (the default).
    #[must_use]
    pub const fn disabled() -> Self {
        Self { path: None }
    }

    /// An audit log appending to `path`. An empty path disables the log.
    #[must_use]
    pub fn to_path(path: Option<&str>) -> Self {
        Self {
            path: path.filter(|p| !p.is_empty()).map(PathBuf::from),
        }
    }

    /// Whether any record will actually be written.
    #[must_use]
    pub const fn is_enabled(&self) -> bool {
        self.path.is_some()
    }

    /// Configured destination, if any.
    #[must_use]
    pub fn path(&self) -> Option<&std::path::Path> {
        self.path.as_deref()
    }

    /// Record an IP ban without retaining any submitted credential.
    pub fn record_management_ban(&self, ban: &crate::management_access::ManagementBan, path: &str) {
        let Some(destination) = &self.path else {
            return;
        };
        let event = serde_json::json!({
            "phase": "management_auth_banned",
            "time": crate::operation_context::now().to_rfc3339(),
            "client_ip": ban.client_ip,
            "expires_at": ban.expires_at,
            "path": path,
        });
        if let Err(error) =
            open_append_only(destination).and_then(|mut file| writeln!(file, "{event}"))
        {
            tracing::warn!("management ban audit write failed: {error}");
        }
    }

    /// Record a runtime debug change without retaining credentials or bodies.
    pub fn record_logging_change(&self, debug: bool, reason: &str, ttl_secs: u64) {
        self.record_observability(&serde_json::json!({"phase": "logging_changed", "debug": debug, "reason": reason, "ttl_secs": ttl_secs}));
    }

    /// Record an operator's deletion of diagnostic captures.
    pub fn record_log_clear(&self) {
        self.record_observability(&serde_json::json!({"phase": "logs_cleared"}));
    }

    fn record_observability(&self, event: &serde_json::Value) {
        let mut event = event.clone();
        event["time"] = crate::operation_context::now().to_rfc3339().into();
        self.record_management(&event);
    }

    /// Append one event. Failures are logged and otherwise ignored: auditing
    /// must never take the proxy down.
    pub fn record(&self, event: &AuditEvent) {
        self.record_management(event);
    }

    pub(crate) fn record_management(&self, event: &impl Serialize) {
        let Some(path) = self.path.as_ref() else {
            return;
        };
        let Ok(line) = serde_json::to_string(event) else {
            return;
        };
        let write = open_append_only(path).and_then(|mut file| writeln!(file, "{line}"));
        if let Err(e) = write {
            tracing::warn!("audit log write failed ({}): {e}", path.display());
        }
    }
}

fn open_append_only(path: &std::path::Path) -> std::io::Result<std::fs::File> {
    let mut options = OpenOptions::new();
    options.create(true).append(true);
    #[cfg(unix)]
    options.mode(0o600);
    let file = options.open(path)?;
    #[cfg(unix)]
    file.set_permissions(std::fs::Permissions::from_mode(0o600))?;
    Ok(file)
}

/// Build an event for `claims` at the current wall-clock time.
#[must_use]
pub fn event(
    token_id: &str,
    label: &str,
    provider: &str,
    surface: &str,
    path: &str,
    model: Option<&str>,
) -> AuditEvent {
    let mut event = AuditEvent {
        phase: "request_authorized".to_string(),
        time: crate::operation_context::now().to_rfc3339(),
        token_id: token_id.to_string(),
        label: label.to_string(),
        provider: provider.to_string(),
        provider_account: None,
        provider_endpoint: None,
        surface: surface.to_string(),
        path: path.to_string(),
        client_kind: None,
        subscription_override: None,
        proxied_client_override: None,
        model: model.map(String::from),
        resolved_model: None,
        selector_kind: None,
        resolution_reason: None,
        model_policy: None,
        served_model: None,
        model_descriptor: crate::model_contract::ModelTruthDescriptor::default(),
    };
    event.refresh_model_descriptor();
    event
}

fn record_response_model(audit: &ResponseModelAudit, served_model: &str, phase: &str) {
    let state = &audit.state;
    if !state.audit.is_enabled() {
        return;
    }
    let mut event = event(
        &audit.claims.sub,
        &audit.claims.label,
        audit
            .provider
            .as_deref()
            .unwrap_or_else(|| state.upstream_provider.as_str()),
        surface_name(audit.surface),
        &audit.path,
        audit.requested_model.as_deref(),
    );
    event.phase = phase.to_string();
    event.resolved_model.clone_from(&audit.resolved_model);
    event.served_model = Some(served_model.to_string());
    event.model_policy = crate::proxy::model_policy_for_claims(state, &audit.claims).ok();
    event.provider_account.clone_from(&audit.provider_account);
    event.provider_endpoint.clone_from(&audit.provider_endpoint);
    event.selector_kind = Some(audit.selector_kind);
    event.resolution_reason = Some(resolution_reason(
        audit.requested_model.as_deref(),
        served_model,
        audit.selector_kind,
        event.model_policy.as_ref(),
    ));
    event.client_kind.clone_from(&audit.claims.client_kind);
    event.refresh_model_descriptor();
    state.audit.record(&event);
}

/// Owned audit context for a translated response.
///
/// A stream can prove identity before it completes, so the first validated
/// identity-bearing event is recorded as `response_model_verified` without
/// claiming terminal success.
#[derive(Clone)]
pub struct ResponseModelAudit {
    state: crate::app_state::AppState,
    claims: crate::token::TokenClaims,
    surface: crate::metrics::Surface,
    path: String,
    requested_model: Option<String>,
    resolved_model: Option<String>,
    provider: Option<String>,
    provider_account: Option<String>,
    provider_endpoint: Option<String>,
    selector_kind: crate::model_contract::ModelSelectorKind,
}

impl ResponseModelAudit {
    #[must_use]
    pub fn new(
        state: &crate::app_state::AppState,
        claims: &crate::token::TokenClaims,
        surface: crate::metrics::Surface,
        path: &str,
    ) -> Self {
        Self {
            state: state.clone(),
            claims: claims.clone(),
            surface,
            path: path.to_string(),
            requested_model: None,
            resolved_model: None,
            provider: None,
            provider_account: None,
            provider_endpoint: None,
            selector_kind: crate::model_contract::ModelSelectorKind::Unknown,
        }
    }

    #[must_use]
    pub fn with_provider(mut self, provider: Option<&str>) -> Self {
        self.provider = provider.map(str::to_string);
        self
    }

    #[must_use]
    pub fn with_models(
        mut self,
        requested_model: Option<&str>,
        resolved_model: Option<&str>,
    ) -> Self {
        self.requested_model = requested_model.map(str::to_string);
        self.resolved_model = resolved_model.map(str::to_string);
        self
    }

    #[must_use]
    pub fn with_provider_account(mut self, provider_account: Option<&str>) -> Self {
        self.provider_account = provider_account.map(str::to_string);
        self
    }

    #[must_use]
    pub fn with_provider_endpoint(mut self, provider_endpoint: Option<&str>) -> Self {
        self.provider_endpoint = provider_endpoint.map(str::to_string);
        self
    }

    #[must_use]
    pub const fn with_selector_kind(
        mut self,
        selector_kind: crate::model_contract::ModelSelectorKind,
    ) -> Self {
        self.selector_kind = selector_kind;
        self
    }

    /// Record a completed buffered response carrying all three model
    /// identities after the upstream has proved its concrete model.
    pub fn record_completed(&self, served_model: &str) {
        record_response_model(self, served_model, "response_completed");
    }

    /// Record the first concrete identity after the stream validator accepts
    /// it. Callers guard this so exactly one record is written per stream.
    pub fn record_verified(&self, served_model: &str) {
        record_response_model(self, served_model, "response_model_verified");
    }
}

fn resolution_reason(
    requested_model: Option<&str>,
    served_model: &str,
    selector_kind: crate::model_contract::ModelSelectorKind,
    policy: Option<&crate::model_contract::ModelAccessPolicy>,
) -> String {
    if requested_model == Some(served_model) {
        return "exact_match".to_string();
    }
    match selector_kind {
        crate::model_contract::ModelSelectorKind::ProviderDynamicAlias => {
            "provider_dynamic_alias".to_string()
        }
        crate::model_contract::ModelSelectorKind::OperatorAlias => "operator_alias".to_string(),
        crate::model_contract::ModelSelectorKind::Concrete
        | crate::model_contract::ModelSelectorKind::Unknown => policy
            .filter(|policy| policy.allow_substitution)
            .and_then(|policy| policy.substitution_source.clone())
            .unwrap_or_else(|| "unpinned_provider_selection".to_string()),
    }
}

/// Name used for a surface in audit records.
#[must_use]
pub const fn surface_name(surface: crate::metrics::Surface) -> &'static str {
    match surface {
        crate::metrics::Surface::Anthropic => "anthropic",
        crate::metrics::Surface::OpenAIChat => "openai_chat",
        crate::metrics::Surface::OpenAIResponses => "openai_responses",
    }
}

/// Record one authorised request against its router token.
///
/// This is the single place that keeps the two halves of issue #45's
/// "separate token per task" requirement in sync: the in-memory counter served
/// by `/metrics` and `/v1/usage`, and the optional durable JSONL trail. Call
/// it once per request, immediately after the token has been validated (and,
/// where applicable, its budget consumed).
pub fn record_authorised_request(
    state: &crate::app_state::AppState,
    claims: &crate::token::TokenClaims,
    surface: crate::metrics::Surface,
    path: &str,
    body: Option<&serde_json::Value>,
) {
    record_authorised_request_with_resolved_model(state, claims, surface, path, body, None);
}

/// Record a provider control-plane operation without treating it as inference.
///
/// `operation` must be a fixed public operation name, never a caller-supplied
/// resource id or request field. Private history, notes, paths, session ids,
/// account ids, and response data consequently never reach the audit stream.
pub fn record_control_plane_request(
    state: &crate::app_state::AppState,
    claims: &crate::token::TokenClaims,
    provider: &str,
    operation: &str,
) {
    state
        .metrics
        .record_token_request(&claims.sub, &claims.label);
    if !state.audit.is_enabled() {
        return;
    }
    let mut event = event(
        &claims.sub,
        &claims.label,
        provider,
        "control_plane",
        operation,
        None,
    );
    event.client_kind.clone_from(&claims.client_kind);
    event.refresh_model_descriptor();
    state.audit.record(&event);
}

/// Record an authorised request with both client and canonical model identity.
pub fn record_authorised_request_with_resolved_model(
    state: &crate::app_state::AppState,
    claims: &crate::token::TokenClaims,
    surface: crate::metrics::Surface,
    path: &str,
    body: Option<&serde_json::Value>,
    resolved_model: Option<&str>,
) {
    record_authorised_request_with_resolved_model_and_entitlement(
        state,
        claims,
        surface,
        path,
        body,
        resolved_model,
        None,
    );
}

/// Record an authorised subscription request including how its client
/// evidence was accepted.
pub(crate) fn record_authorised_request_with_resolved_model_and_entitlement(
    state: &crate::app_state::AppState,
    claims: &crate::token::TokenClaims,
    surface: crate::metrics::Surface,
    path: &str,
    body: Option<&serde_json::Value>,
    resolved_model: Option<&str>,
    entitlement: Option<crate::client_policy::EntitlementDecision>,
) {
    state
        .metrics
        .record_token_request(&claims.sub, &claims.label);
    if !state.audit.is_enabled() {
        return;
    }
    let model = body
        .and_then(|b| b.get("model"))
        .and_then(serde_json::Value::as_str);
    let mut event = event(
        &claims.sub,
        &claims.label,
        state.upstream_provider.as_str(),
        surface_name(surface),
        path,
        model,
    );
    event.resolved_model = resolved_model
        .filter(|resolved| Some(*resolved) != model)
        .map(str::to_string);
    event.model_policy = crate::proxy::model_policy_for_claims(state, claims).ok();
    event.client_kind.clone_from(&claims.client_kind);
    if entitlement == Some(crate::client_policy::EntitlementDecision::Proxied) {
        event
            .proxied_client_override
            .clone_from(&claims.client_kind);
    }
    if let (Some(client), Some(provider)) = (
        claims
            .client_kind
            .as_deref()
            .and_then(crate::clients::ClientKind::from_str_opt),
        state.upstream_provider.subscription_provider(),
    ) {
        let protocol = match surface {
            crate::metrics::Surface::Anthropic => {
                crate::client_policy::ClientProtocol::AnthropicMessages
            }
            crate::metrics::Surface::OpenAIChat => crate::client_policy::ClientProtocol::OpenAIChat,
            crate::metrics::Surface::OpenAIResponses => {
                crate::client_policy::ClientProtocol::OpenAIResponses
            }
        };
        if state
            .provider_store
            .subscription_entitlement_policy()
            .is_ok_and(|policy| {
                policy.decide(Some(client), provider, protocol)
                    == crate::client_policy::EntitlementDecision::Override
            })
        {
            event.subscription_override = Some(format!("{client}:{provider}"));
        }
    }
    if state.upstream_provider == crate::config::UpstreamProvider::ZaiCodingPlan
        && let Some(client) = claims
            .client_kind
            .as_deref()
            .and_then(crate::clients::ClientKind::from_str_opt)
        && crate::zai_coding_plan::resolve(state).is_ok_and(|provider| {
            provider.is_some_and(|provider| {
                crate::zai_coding_plan::ZaiCodingPlanPolicy::new(
                    provider.subscriber_id.as_deref().unwrap_or_default(),
                    provider.intermediary_risk_acknowledged,
                    &provider.unsupported_clients,
                )
                .is_ok_and(|policy| policy.is_unsupported_override(client))
            })
        })
    {
        event.subscription_override = Some(format!("{client}:z.ai-coding-plan"));
    }
    event.refresh_model_descriptor();
    state.audit.record(&event);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn disabled_log_writes_nothing() {
        let log = AuditLog::disabled();
        assert!(!log.is_enabled());
        // Must not panic or create files.
        log.record(&event(
            "id",
            "task-1",
            "codex",
            "anthropic",
            "/v1/messages",
            None,
        ));
    }

    #[test]
    fn empty_path_is_treated_as_disabled() {
        assert!(!AuditLog::to_path(Some("")).is_enabled());
        assert!(!AuditLog::to_path(None).is_enabled());
    }

    #[test]
    fn enabled_log_appends_one_json_line_per_event() {
        let dir = std::env::temp_dir().join(format!("la-audit-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).expect("temp dir");
        let file = dir.join("audit.jsonl");
        let log = AuditLog::to_path(file.to_str());
        assert!(log.is_enabled());

        log.record(&event(
            "tok-1",
            "task-a",
            "codex",
            "anthropic",
            "/v1/messages",
