        assert_eq!(saved["auth_mode"], "chatgpt");
        assert_eq!(saved["tokens"]["access_token"], "device-access-rotated");
        assert_eq!(saved["tokens"]["refresh_token"], "device-refresh-rotated");
        assert_eq!(state.polls.load(Ordering::SeqCst), 2);
