    }

    /// Native Codex exchanges before taking the primary refresh lock.
    #[tokio::test]
    async fn native_codex_install_contends_on_the_primary_refresh_lock() {
        let (issuer, state, server) = device_stub().await;
        let home = tempfile::tempdir().unwrap();
        let data = tempfile::tempdir().unwrap();
        let login = CodexDeviceLogin::begin(CodexAuthConfig {
            issuer,
            client_id: CODEX_CLIENT_ID.to_string(),
            port: 1455,
            codex_home: home.path().to_path_buf(),
            timeout: Duration::from_secs(3),
            bind_host: "127.0.0.1".to_string(),
        })
        .await
        .unwrap();
        let lock_path = crate::credential_recovery_store::credential_lock_path(
            data.path(),
            crate::subscription::SubscriptionProvider::Codex,
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
        );
        let holder = crate::durable_file::lock_exclusive_async(&lock_path, Duration::from_secs(1))
            .await
            .unwrap();
        let data_path = data.path().to_path_buf();
        let completion = tokio::spawn(login.complete_with_data_dir(data_path));
        for _ in 0..100 {
            if state.catalogs.load(Ordering::SeqCst) > 0 {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }

        assert_eq!(state.exchanges.load(Ordering::SeqCst), 2);
        assert_eq!(state.catalogs.load(Ordering::SeqCst), 1);
        assert!(
            !completion.is_finished(),
            "Codex install bypassed refresh lock"
        );
        assert!(!home.path().join("auth.json").exists());
        drop(holder);

        assert!(completion.await.unwrap().unwrap().is_file());
        server.abort();
    }

    #[tokio::test]
    async fn mismatched_state_is_rejected_and_listener_closes_after_valid_callback() {
        let (issuer, stub_state, server) = device_stub().await;
        let home = tempfile::tempdir().unwrap();
        let login = CodexLogin::bind(CodexAuthConfig {
            issuer,
            client_id: CODEX_CLIENT_ID.to_string(),
            port: 0,
            codex_home: home.path().to_path_buf(),
            timeout: Duration::from_secs(3),
            bind_host: "127.0.0.1".to_string(),
        })
        .await
        .unwrap();
        let port = login.port();
        let callback_server = login.server.abort_handle();
        let auth_url = login.authorization_url().to_string();
        let callback_state = auth_url
            .split("state=")
            .nth(1)
            .unwrap()
            .split('&')
            .next()
            .unwrap();
        let client = reqwest::Client::new();
        let wrong = client
            .get(format!(
                "http://127.0.0.1:{port}{CODEX_CALLBACK_PATH}?code=bad&state=wrong"
            ))
            .send()
            .await
            .unwrap();
        assert_eq!(wrong.status(), StatusCode::BAD_REQUEST);

        let completion = tokio::spawn(login.complete());
        let good = client
            .get(format!(
                "http://127.0.0.1:{port}{CODEX_CALLBACK_PATH}?code=good-code&state={callback_state}"
            ))
            .send()
            .await
            .unwrap();
        assert_eq!(good.status(), StatusCode::OK);
        let path = completion.await.unwrap().unwrap();
        let saved: serde_json::Value =
            serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
        assert_eq!(saved["tokens"]["access_token"], "device-access-rotated");
        let request = {
            let requests = stub_state.token_bodies.lock().unwrap();
            assert_eq!(requests.len(), 2);
            let request = requests[0].clone();
            drop(requests);
            request
        };
        assert!(request.contains("code=good-code"));
        assert!(request.contains("code_verifier="));
        server.abort();
        assert!(callback_server.is_finished());
    }

