//! Protected diagnostics that tell token authentication failures apart
//! (issue #644).
//!
//! After a rollback a live client's token stopped working, and the only
//! evidence was a generic `401 invalid token`. That one sentence covered a
//! token signed by another issuer secret, a record missing from the durable
//! store, an expired or revoked token, a budget or model-policy denial and a
//! legacy server without the run-lease endpoint. Each of those has a different
//! repair, so each is counted and remembered here under its own reason.
//!
//! Nothing here holds a token value: entries carry a truncated SHA-256
//! fingerprint and, when the payload could be read, the token id that the
//! operator already sees in `router tokens list`. The client-facing error text
//! is unchanged; the detail is served only on admin-protected endpoints.

use std::collections::{BTreeMap, VecDeque};
use std::fmt::Write as _;
use std::sync::Mutex;

use crate::token::TokenError;

/// How many recent failures are kept. Bounded so a flood of bad tokens cannot
/// grow memory.
pub const RECENT_CAPACITY: usize = 64;

/// Stable reason codes. Kept in one place so docs, metrics and tests agree.
pub mod reason {
    pub const MISSING_CREDENTIAL: &str = "missing_credential";
    pub const INVALID_PREFIX: &str = "invalid_prefix";
    pub const MALFORMED: &str = "malformed";
    pub const SIGNATURE_INVALID: &str = "signature_invalid";
    pub const ISSUER_SECRET_UNSET: &str = "issuer_secret_unset";
    pub const EXPIRED: &str = "expired";
    pub const REVOKED: &str = "revoked";
    pub const MISSING_RECORD: &str = "missing_record";
    pub const BINDING_MISMATCH: &str = "binding_mismatch";
    pub const REQUEST_BUDGET: &str = "request_budget";
    pub const TOKEN_BUDGET: &str = "token_budget";
    pub const RATE_LIMIT: &str = "rate_limit";
    pub const MODEL_POLICY: &str = "model_policy";
    pub const INSUFFICIENT_SCOPE: &str = "insufficient_scope";
    pub const RUN_LEASE_UNRENEWABLE: &str = "run_lease_unrenewable";
    pub const UNSUPPORTED_LEASE_ENDPOINT: &str = "unsupported_lease_endpoint";
    pub const STORAGE: &str = "storage";
    pub const NOT_FOUND: &str = "not_found";
}

impl TokenError {
    /// Stable diagnostic reason for this failure.
    #[must_use]
    pub const fn reason_code(&self) -> &'static str {
        match self {
            Self::InvalidPrefix => reason::INVALID_PREFIX,
            Self::Invalid(_) => reason::MALFORMED,
            Self::SignatureInvalid => reason::SIGNATURE_INVALID,
            Self::IssuerSecretUnset => reason::ISSUER_SECRET_UNSET,
            Self::Expired(_) => reason::EXPIRED,
            Self::Revoked => reason::REVOKED,
            Self::MissingRecord => reason::MISSING_RECORD,
            Self::BindingMismatch => reason::BINDING_MISMATCH,
            Self::NotFound(_) => reason::NOT_FOUND,
            Self::InsufficientScope => reason::INSUFFICIENT_SCOPE,
            Self::LimitExceeded(_) => reason::REQUEST_BUDGET,
            Self::TokenLimitExceeded(_) => reason::TOKEN_BUDGET,
            Self::RateLimitExceeded => reason::RATE_LIMIT,
            Self::Storage(_) => reason::STORAGE,
        }
    }
}

/// One remembered failure.
#[derive(Clone, Debug, serde::Serialize, schemars::JsonSchema)]
pub struct AuthFailure {
    /// Unix second of the failure.
    pub at: i64,
    /// Stable reason code, see [`reason`].
    pub reason: &'static str,
    /// Truncated SHA-256 of the presented token, if one was presented.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub fingerprint: Option<String>,
    /// Token id read from the (possibly unverified) payload.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub token_id: Option<String>,
}

/// Per-reason counters plus a bounded list of recent failures.
#[derive(Debug, Default)]
pub struct AuthDiagnostics {
    counts: Mutex<BTreeMap<&'static str, u64>>,
    recent: Mutex<VecDeque<AuthFailure>>,
}

/// Snapshot served by the protected diagnostics endpoint.
#[derive(Clone, Debug, serde::Serialize, schemars::JsonSchema)]
pub struct AuthDiagnosticsSnapshot {
    pub failures_by_reason: BTreeMap<&'static str, u64>,
    pub recent_failures: Vec<AuthFailure>,
}

impl AuthDiagnostics {
    /// Remember one failure. `token` is used only to derive a fingerprint and
    /// the payload's token id; it is never stored.
    pub fn record(&self, reason: &'static str, token: Option<&str>) {
        let fingerprint = token.map(crate::emergency_auth::token_fingerprint);
        let token_id = token.and_then(unverified_subject);
        tracing::debug!(
            reason,
            fingerprint = fingerprint.as_deref().unwrap_or("-"),
            token_id = token_id.as_deref().unwrap_or("-"),
            "Router token authentication failed"
        );
        if let Ok(mut counts) = self.counts.lock() {
            *counts.entry(reason).or_default() += 1;
        }
        if let Ok(mut recent) = self.recent.lock() {
            if recent.len() == RECENT_CAPACITY {
                recent.pop_front();
            }
            recent.push_back(AuthFailure {
                at: crate::operation_context::now().timestamp(),
                reason,
                fingerprint,
                token_id,
            });
        }
    }

    /// Record a [`TokenError`] under its reason code.
    pub fn record_error(&self, error: &TokenError, token: Option<&str>) {
        self.record(error.reason_code(), token);
    }

    /// Point-in-time copy for the protected endpoint.
    #[must_use]
    pub fn snapshot(&self) -> AuthDiagnosticsSnapshot {
        AuthDiagnosticsSnapshot {
            failures_by_reason: self
                .counts
                .lock()
                .map(|counts| counts.clone())
                .unwrap_or_default(),
            recent_failures: self
                .recent
                .lock()
                .map(|recent| recent.iter().rev().cloned().collect())
                .unwrap_or_default(),
        }
    }

    /// Prometheus counter lines, one per reason seen.
    #[must_use]
    pub fn render_prometheus(&self) -> String {
        let mut body = String::from(
            "# HELP link_assistant_auth_failures_total Router token authentication failures by reason.\n\
             # TYPE link_assistant_auth_failures_total counter\n",
        );
        let snapshot = self.snapshot();
        if snapshot.failures_by_reason.is_empty() {
            body.push_str("link_assistant_auth_failures_total 0\n");
        }
        for (reason, count) in &snapshot.failures_by_reason {
            let _ = writeln!(
                body,
                "link_assistant_auth_failures_total{{reason=\"{reason}\"}} {count}"
            );
        }
        body
    }
}

tokio::task_local! {
    /// Set once the current request's authentication outcome was counted.
    static OUTCOME_COUNTED: std::cell::Cell<bool>;
}

/// Run one HTTP request with its own "outcome counted" flag.
///
/// Some handlers authenticate the same credential more than once (the
/// aggregate catalog asks every provider in turn). Without a request scope a
/// single request was counted once per call, so the bypass and failure
/// counters overstated traffic threefold.
pub async fn scope_request<F: std::future::Future>(request: F) -> F::Output {
    OUTCOME_COUNTED
        .scope(std::cell::Cell::new(false), request)
        .await
}

/// Whether this is the first authentication outcome of the current request.
///
/// Outside a request scope (CLI, direct handler tests) every outcome counts.
#[must_use]
pub fn first_outcome_in_request() -> bool {
    OUTCOME_COUNTED
        .try_with(|counted| !counted.replace(true))
        .unwrap_or(true)
}

/// The `sub` of a JWT payload, read without verifying the signature. Only a
/// UUID-shaped id is kept, so an attacker-supplied payload cannot write
/// arbitrary text into the diagnostics.
fn unverified_subject(token: &str) -> Option<String> {
    use base64::Engine;
    let jwt = crate::token::token_jwt(token)?;
    let payload = jwt.split('.').nth(1)?;
    let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(payload.trim_end_matches('='))
        .ok()?;
    let value: serde_json::Value = serde_json::from_slice(&bytes).ok()?;
    let sub = value.get("sub")?.as_str()?;
    uuid::Uuid::parse_str(sub).ok().map(|id| id.to_string())
}

#[cfg(test)]
#[path = "auth_diagnostics_tests.rs"]
mod tests;

//! Authorize the subscription of the *selected* router, not a local directory.
//!
//! `server use` establishes which router the CLI is talking to, and `with`
//! honours it. `auth` is the other half of that workflow — it exists to give
//! that router a working subscription — but it wrote to a local home instead,
//! so the obvious sequence
//!
//! ```text
//! router server use <url> --token-stdin
//! router auth claude
//! router with claude
//! ```
//!
//! did not do what it reads as: the login printed success while the router it
//! targeted still had no usable credential, and the failure surfaced later as
//! an unrelated-looking 401 (issue #246).
//!
//! The login itself still happens in front of the operator — the browser step
//! cannot be delegated — but the credential is completed on, and stored by,
//! the router being targeted, through the admin login API it already exposes.

use std::process::ExitCode;
use std::time::Duration;

use crate::managed_server::ResolvedServer;

/// How long to wait for one HTTP call to the selected router.
const REQUEST_TIMEOUT: Duration = Duration::from_secs(30);

/// How often a device-flow login asks the router whether it was approved.
///
/// Short enough that approval feels immediate, long enough not to hammer the
/// router while a human is reading their browser.
#[cfg(not(test))]
const POLL_INTERVAL: Duration = Duration::from_secs(3);
#[cfg(test)]
const POLL_INTERVAL: Duration = Duration::from_millis(20);

/// The selected router, when one is configured and reachable.
///
/// `None` means "no selection" — the caller keeps its local behaviour. An
/// unreachable *selected* server is an error rather than a silent fallback:
/// falling back to a local directory is exactly the surprise this fixes.
pub async fn selected_server(force_managed: bool) -> crate::translation_core::Outcome<crate::translation_core::Maybe<ResolvedServer>, String> {
    if force_managed {
        // `--managed` asks for a disposable container, which is what the local
        // path already provides for `auth`.
        return Ok(None);
    }
    if !has_selection() {
        // Nothing was selected, but a router already listening here is a
        // better target than this machine's credential directory: authorizing
        // locally when a live router is one port away lands the subscription
        // somewhere the router in use cannot see (issue #250).
        return Ok(crate::managed_server::discovered_local_router().await);
    }
    crate::managed_server::resolve(None, None, None, None, false)
        .await
        .map(Some)
        .map_err(|error| format!("the selected server is not usable: {error}"))
}

/// The router an `auth` invocation acts on, given its explicit target flags.
///
/// `None` means "act locally". The precedence is the same one `with` follows,
/// stated in one place so `auth` cannot drift from it again (issues #246,
/// #250): an explicit `--local` or `--managed` keeps the local path, `--server`
/// names one router for a single command, and otherwise the selection — or a
/// router already listening here — is used.
pub async fn target_for(
    local: bool,
    managed: bool,
    server: crate::translation_core::Maybe<&crate::translation_core::Str>,
    management_server: crate::translation_core::Maybe<&crate::translation_core::Str>,
) -> crate::translation_core::Outcome<crate::translation_core::Maybe<ResolvedServer>, String> {
    if local || managed {
        return Ok(None);
    }
    if let Some(server) = server {
        return crate::managed_server::resolve(Some(server), management_server, None, None, false)
            .await
            .map(Some)
            .map_err(|error| format!("the named server is not usable: {error}"));
    }
    if management_server.is_some() {
        return crate::managed_server::resolve(None, management_server, None, None, false)
            .await
            .map(Some)
            .map_err(|error| format!("the selected server is not usable: {error}"));
    }
    selected_server(managed).await
}

/// Whether the operator has selected a server, without contacting it.
///
/// Only an explicit selection counts. The managed local container is started on
/// demand by `with`, and a plain `auth` must not boot one.
fn has_selection() -> bool {
    if crate::operation_context::var_os("LINK_ASSISTANT_ROUTER_URL")
        .is_some_and(|value| !value.is_empty())
        || crate::operation_context::var_os("ROUTER_URL").is_some_and(|value| !value.is_empty())
    {
        return true;
    }
    crate::managed_server::load_persisted()
        .ok()
        .flatten()
        .is_some()
}

/// Run a provider login against `server`, returning the process exit code.
pub async fn authorize(
    server: &ResolvedServer,
    provider: &crate::translation_core::Str,
    mode: crate::translation_core::Maybe<&crate::translation_core::Str>,
    code: crate::translation_core::Maybe<String>,
) -> ExitCode {
    match authorize_inner(server, provider, mode, code).await {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

async fn authorize_inner(
    server: &ResolvedServer,
    provider: &crate::translation_core::Str,
    mode: crate::translation_core::Maybe<&crate::translation_core::Str>,
    code: crate::translation_core::Maybe<String>,
) -> crate::translation_core::Outcome<(), String> {
    let client = server
        .management_client_with_timeout(REQUEST_TIMEOUT)
        .map_err(|error| format!("could not build an HTTP client: {error}"))?;

    let mut body = serde_json::json!({ "provider": provider });
    if let Some(mode) = mode {
        body["mode"] = serde_json::Value::String(mode.to_string());
    }
    let begun: serde_json::Value = send(
        &client,
        server,
        reqwest::Method::POST,
        crate::route_contract::route_template(crate::route_contract::RouteId::Login),
        Some(body),
    )
    .await?;

    let login_id = begun
        .get("login_id")
        .and_then(serde_json::Value::as_str)
        .ok_or("the router did not return a login id")?
        .to_string();

    println!("Authorizing {provider} on {}", server.base_url);
    if let Some(url) = begun.get("url").and_then(serde_json::Value::as_str) {
        println!("Open this URL:\n{url}");
    }
    if let Some(user_code) = begun.get("user_code").and_then(serde_json::Value::as_str) {
        println!("Enter this code: {user_code}");
    }

    // A device flow authorizes itself once the human approves it in the
    // browser; only a code flow has something to submit.
    if status_of(&begun) == "authorized" {
        finish(provider, server);
        return Ok(());
    }
    if status_of(&begun) == "awaiting_device" {
        return poll_until_authorized(&client, server, &login_id, provider).await;
    }

    let submitted = match code {
        Some(code) => code,
        None => read_code().await?,
    };
    let submitted = submitted.trim();
    if submitted.is_empty() {
        return Err(format!(
            "no authorization code was supplied; the pending login is still open on the router — \
             finish it with `router auth {provider} --flow code --code <CODE>`"
        ));
    }

    let completed: serde_json::Value = send(
        &client,
        server,
        reqwest::Method::POST,
        &crate::route_contract::route_template(crate::route_contract::RouteId::LoginCode)
            .replace("{id}", &login_id),
        Some(serde_json::json!({ "code": submitted })),
    )
    .await?;
    if status_of(&completed) != "authorized" {
        return Err(format!(
            "the router did not accept the code: it reports `{}`",
            status_of(&completed)
        ));
    }
    finish(provider, server);
    Ok(())
}

/// Wait for a device-flow login the human approves in their browser.
async fn poll_until_authorized(
    client: &reqwest::Client,
    server: &ResolvedServer,
    login_id: &crate::translation_core::Str,
    provider: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<(), String> {
    let deadline = std::time::Instant::now() + Duration::from_secs(10 * 60);
    while std::time::Instant::now() < deadline {
        tokio::time::sleep(POLL_INTERVAL).await;
        let view: serde_json::Value = send(
            client,
            server,
            reqwest::Method::GET,
            &crate::route_contract::route_template(crate::route_contract::RouteId::LoginSession)
                .replace("{id}", login_id),
            None,
        )
        .await?;
        match status_of(&view) {
            "authorized" => {
                finish(provider, server);
                return Ok(());
            }
            "failed" | "expired" | "cancelled" => {
                return Err(format!(
                    "the login ended as `{}` on the router",
                    status_of(&view)
                ));
            }
            _ => {}
        }
    }
    Err("the login was not approved in time".to_string())
}

fn finish(provider: &crate::translation_core::Str, server: &ResolvedServer) {
    println!(
        "{provider} authorization saved on {} ({})",
        server.base_url, server.source
    );
}

fn status_of(view: &crate::translation_core::Json) -> &crate::translation_core::Str {
    view.get("status")
        .and_then(crate::translation_core::Json::as_str)
        .unwrap_or("unknown")
}

/// Report each provider credential as the *selected router* sees it.
pub async fn status(server: &ResolvedServer) -> ExitCode {
    let client = match server.management_client_with_timeout(REQUEST_TIMEOUT) {
        Ok(client) => client,
        Err(error) => {
            eprintln!("error: could not build an HTTP client: {error}");
            return ExitCode::from(1);
        }
    };
    match send::<serde_json::Value>(
        &client,
        server,
        reqwest::Method::GET,
        crate::route_contract::route_template(crate::route_contract::RouteId::CredentialStatus),
        None,
    )
    .await
    {
        Ok(body) => {
            let credentials = match serde_json::from_value(body["credentials"].clone()) {
                Ok(credentials) => credentials,
                Err(error) => {
                    eprintln!("error: invalid remote credential report: {error}");
                    return ExitCode::from(1);
                }
            };
            crate::operation_output::report(crate::operation_reports::AuthStatusReport {
                server: Some(server.base_url.clone()),
                credentials,
                sources: Vec::new(),
                api_key_providers: Vec::new(),
                output: Vec::new(),
            });
            println!("server: {} ({})", server.base_url, server.source);
            if report_status_credentials(&body) {
                ExitCode::from(1)
            } else {
                ExitCode::SUCCESS
            }
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

fn report_status_credentials(body: &crate::translation_core::Json) -> bool {
    let entries = body
        .get("credentials")
        .and_then(serde_json::Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or_default();
    let mut refresh_failed = false;
    for entry in entries {
        let provider = entry
            .get("provider")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("-");
        let state = entry
            .get("state")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("unverified");
        let home = entry
            .get("home")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("-");
        println!("{provider:<8} {state:<10} {home}");
        refresh_failed |= state == "refresh-failed";
        if state == "refresh-failed"
            && let Some(detail) = entry.get("detail").and_then(serde_json::Value::as_str)
        {
            eprintln!("error: {provider} refresh failed: {detail}");
        }
    }
    refresh_failed
}

/// Where the selected router reads `provider`'s credential from.
///
/// `auth status` already asks the same endpoint for exactly this, so a command
/// that cannot act on the remote deployment can still name the directory the
/// credential would have to land in. An error that says only "not from here"
/// leaves the operator to guess the next step; one that names the path is the
/// instruction (issue #291).
///
/// `None` when the router cannot be reached or does not report homes — the
/// refusal is still correct without it, so this never turns into a hard
/// failure of its own.
pub async fn credential_home(server: &ResolvedServer, provider: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
    let client = server
        .management_client_with_timeout(REQUEST_TIMEOUT)
        .ok()?;
    let body: serde_json::Value = send(
        &client,
        server,
        reqwest::Method::GET,
        crate::route_contract::route_template(crate::route_contract::RouteId::Accounts),
        None,
    )
    .await
    .ok()?;
    home_in_accounts(&body, provider)
}

/// `accounts list` against the selected router (issue #294).
///
/// The endpoint reports a superset of what the local table prints, so this
/// renders the same columns from the same field names rather than growing a
/// second format an operator would have to reconcile.
pub async fn accounts(server: &ResolvedServer) -> ExitCode {
    match get(
        server,
        crate::route_contract::route_template(crate::route_contract::RouteId::Accounts),
    )
    .await
    {
        Ok(body) => {
            println!("server: {} ({})", server.base_url, server.source);
            report_credentials(&body);
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

/// `GET path` on the selected router, returning its JSON answer.
///
/// The admin credential is attached and the failure messages are shared with
/// every other remote command, so a refused credential reads the same however
/// the operator arrived at it.
///
/// # Errors
///
/// Returns an operator-readable message when the call cannot be made or the
/// router answers with a failure.
pub async fn get(server: &ResolvedServer, path: &crate::translation_core::Str) -> crate::translation_core::Outcome<crate::translation_core::Json, String> {
    let client = server
        .management_client_with_timeout(REQUEST_TIMEOUT)
        .map_err(|error| error.to_string())?;
    send(&client, server, reqwest::Method::GET, path, None).await
}

/// `POST path` with `body` on the selected router.
///
/// # Errors
///
/// Returns an operator-readable message when the call cannot be made or the
/// router answers with a failure.
pub async fn post(
    server: &ResolvedServer,
    path: &crate::translation_core::Str,
    body: crate::translation_core::Json,
) -> crate::translation_core::Outcome<crate::translation_core::Json, String> {
    let client = server
        .management_client_with_timeout(REQUEST_TIMEOUT)
        .map_err(|error| error.to_string())?;
    send(&client, server, reqwest::Method::POST, path, Some(body)).await
}

/// `POST path` while preserving a structured non-success response.
///
/// Batch operations use this to report the safe outcome of every completed
/// item instead of discarding earlier successes when a later item is rejected.
/// The response body must be valid JSON and is never included in parse or
/// transport errors.
pub async fn post_response(
    server: &ResolvedServer,
    path: &crate::translation_core::Str,
    body: crate::translation_core::Json,
) -> crate::translation_core::Outcome<(reqwest::StatusCode, crate::translation_core::Json), String> {
    let client = server
        .management_client_with_timeout(REQUEST_TIMEOUT)
        .map_err(|error| error.to_string())?;
    let url = format!("{}{path}", server.management_url.trim_end_matches('/'));
    let mut request = client.post(&url);
    if let Some(token) = server.token.as_deref() {
        request = request.bearer_auth(token);
    }
    let response = request
        .json(&body)
        .send()
        .await
        .map_err(|error| format!("could not reach {url}: {error}"))?;
    let status = response.status();
    let bytes = response
        .bytes()
        .await
        .map_err(|_| format!("could not read the reply from {url}"))?;
    let body = serde_json::from_slice(&bytes)
        .map_err(|_| format!("could not read the JSON reply from {url}"))?;
    Ok((status, body))
}

/// `DELETE path` on the selected router.
///
/// # Errors
///
/// Returns an operator-readable message when the call cannot be made or the
/// router answers with a failure.
pub async fn delete(server: &ResolvedServer, path: &crate::translation_core::Str) -> crate::translation_core::Outcome<crate::translation_core::Json, String> {
    let client = server
        .management_client_with_timeout(REQUEST_TIMEOUT)
        .map_err(|error| error.to_string())?;
    send(&client, server, reqwest::Method::DELETE, path, None).await
}

/// Why an import cannot act on a router other than the machine running it.
///
/// The lines an operator reads, built here rather than at the call site so the
/// wording is asserted directly. Import installs into the credential home of
/// the executing machine, and no endpoint accepts a credential document —
/// `/api/management/login` begins an interactive OAuth flow and `submit_code` takes a
/// short-lived code, neither of which adopts a credential that already exists.
///
/// `home` names the directory that router reads from, when it reports one:
/// "not from here" alone leaves the operator to guess the next step, and the
/// path is the instruction. It is omitted rather than guessed when the router
/// does not say (issue #291).
#[must_use]
pub fn remote_import_refusal(base_url: &crate::translation_core::Str, home: crate::translation_core::Maybe<&crate::translation_core::Str>) -> Vec<String> {
    let mut lines = vec![format!(
        "error: import installs a credential into the credential home of the machine running \
         it, so it cannot provision {base_url} from here."
    )];
    if let Some(home) = home {
        lines.push(format!("note: {base_url} reads its credential from {home}"));
    }
    lines.push(String::from(
        "note: that deployment accepts no credential over HTTP, so run `router auth import` \
         there, or authorize it from here with `router auth claude` / `router auth codex`, \
         which do act on the selected server.",
    ));
    lines.push(String::from(
        "note: pass --local to import into this machine's credential home.",
    ));
    lines
}

/// The home an `/api/management/accounts` body reports for `provider`, if it names one.
///
/// Split from the request so the shape-handling can be asserted without a
/// server: single-account deployments report under `credentials` and pooled
/// ones under `accounts`, and a router predating either simply omits both.
#[must_use]
pub fn home_in_accounts(body: &crate::translation_core::Json, provider: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
    ["credentials", "accounts"]
        .into_iter()
        .filter_map(|key| body.get(key).and_then(crate::translation_core::Json::as_array))
        .flatten()
        .find(|entry| {
            entry
                .get("name")
                .and_then(crate::translation_core::Json::as_str)
                .is_some_and(|name| name.eq_ignore_ascii_case(provider))
        })
        .and_then(|entry| entry.get("home").and_then(crate::translation_core::Json::as_str))
        .map(str::to_owned)
}

async fn send<T: serde::de::DeserializeOwned>(
    client: &reqwest::Client,
    server: &ResolvedServer,
    method: reqwest::Method,
    path: &str,
    body: Option<serde_json::Value>,
) -> Result<T, String> {
    let url = format!("{}{path}", server.management_url.trim_end_matches('/'));
    let mut request = client.request(method, &url);
    if let Some(token) = server.token.as_deref() {
        request = request.bearer_auth(token);
    }
    if let Some(body) = body {
        request = request.json(&body);
    }
    let response = request
        .send()
        .await
        .map_err(|error| format!("could not reach {url}: {error}"))?;
    let status = response.status();
    let text = response.text().await.unwrap_or_default();
    if !status.is_success() {
        // The most likely cause by far, and the one whose fix is not obvious.
        if status == reqwest::StatusCode::UNAUTHORIZED {
            return Err(format!(
                "the selected router refused an administrator credential ({status}). Re-select it \
                 with an admin token: `router server use {} --token-stdin`",
                server.base_url
            ));
        }
        return Err(format!("{url} returned {status}: {}", text.trim()));
    }
    serde_json::from_str(&text)
        .map_err(|error| format!("could not read the reply from {url}: {error}"))
}

/// Read one authorization code from standard input.
///
/// Duplicated from the local path rather than shared: the two prompts differ in
/// what they say about where the pending login lives, and the shared half is
/// one `read_line`.
async fn read_code() -> crate::translation_core::Outcome<String, String> {
    use std::io::BufRead as _;

    println!("Paste authorization code:");
    tokio::task::spawn_blocking(|| {
        let mut line = String::new();
        std::io::stdin()
            .lock()
            .read_line(&mut line)
            .map(|_| line)
            .map_err(|error| format!("could not read authorization code: {error}"))
    })
    .await
    .map_err(|error| format!("authorization prompt failed: {error}"))?
}

#[cfg(test)]
#[path = "auth_remote_tests.rs"]
mod tests;

/// Print what the router said about its credentials.
///
/// An empty `accounts` array means *no account pool*, which is the ordinary
/// state of a single-subscription deployment rather than a missing credential.
/// Printing "no accounts are configured on this router" for it described a
/// router serving live traffic as unauthorized, and pointed the operator at a
/// re-authentication it did not need (issue #281).
///
/// So the pool is reported when there is one, the per-provider credentials when
/// the router sends them, and the server's own `note` when it explains an empty
/// array — in that order. The last two are what an older router does not send,
/// and falling through to the original sentence keeps this readable against one.
fn report_credentials(body: &crate::translation_core::Json) {
    for line in credential_report(body) {
        println!("{line}");
    }
}

/// [`report_credentials`] as lines, so what it prints can be asserted.
fn credential_report(body: &crate::translation_core::Json) -> Vec<String> {
    let rows = |key: &str| {
        body.get(key)
            .and_then(serde_json::Value::as_array)
            .map(Vec::as_slice)
            .unwrap_or_default()
    };
    let accounts = rows("accounts");
    // `credentials` is the single-account answer; it is absent when a pool is
    // configured, and on a router predating it.
    let entries = if accounts.is_empty() {
        rows("credentials")
    } else {
        accounts
    };
    if !entries.is_empty() {
        let mut lines = vec![crate::accounts_cli::header()];
        lines.extend(entries.iter().map(|entry| {
            let text = |key: &str| {
                entry
                    .get(key)
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("-")
            };
            let number = |key: &str| entry.get(key).and_then(serde_json::Value::as_u64);
            crate::accounts_cli::row(&crate::accounts_cli::AccountRow {
                name: text("name"),
                healthy: entry.get("healthy").and_then(serde_json::Value::as_bool),
                credential: text("credential"),
                used: number("used"),
                limit: number("request_limit"),
                remaining: number("remaining_requests"),
                home: text("home").to_string(),
            })
        }));
        return lines;
    }
    // The server explains an empty array when it can; that explanation is the
    // answer, and discarding it is what produced the misleading sentence.
    if let Some(note) = body.get("note").and_then(serde_json::Value::as_str) {
        return vec![note.to_string()];
    }
    vec!["no accounts are configured on this router".to_string()]
}

//! Deadlines and process ownership for diagnostic commands.

use std::io::{Error, ErrorKind, Read, Result};
use std::process::{Command, ExitStatus, Output, Stdio};
use std::time::{Duration, Instant};

#[cfg(not(windows))]
struct Owned(std::process::Child);
#[cfg(windows)]
struct Owned(Box<dyn process_wrap::std::ChildWrapper>);

impl Owned {
    fn try_wait(&mut self) -> Result<crate::translation_core::Maybe<ExitStatus>> {
        #[cfg(not(windows))]
        return self.0.try_wait();
        #[cfg(windows)]
        // Keep the job for termination, but poll its leader directly. The
        // wrapper's polling consumes completion-port notifications that a
        // subsequent job wait may require, even after the leader has exited.
        self.0.inner_mut().try_wait()
    }

    fn spawn(command: &mut Command) -> Result<Self> {
        #[cfg(not(windows))]
        return command.spawn().map(Self);
        #[cfg(windows)]
        {
            use process_wrap::std::{CommandWrap, JobObject};
            let mut wrapped = CommandWrap::from(std::mem::replace(command, Command::new("")));
            let child = wrapped.wrap(JobObject).spawn();
            *command = wrapped.into_command();
            child.map(Self)
        }
    }

    #[cfg(not(windows))]
    const fn pipes(&mut self) -> (std::process::ChildStdout, std::process::ChildStderr) {
        (
            self.0.stdout.take().expect("piped stdout"),
            self.0.stderr.take().expect("piped stderr"),
        )
    }
    #[cfg(windows)]
    fn pipes(&mut self) -> (std::process::ChildStdout, std::process::ChildStderr) {
        (
            self.0.stdout().take().expect("piped stdout"),
            self.0.stderr().take().expect("piped stderr"),
        )
    }
}

impl Drop for Owned {
    fn drop(&mut self) {
        // A dedicated group includes wrappers and their vendor grandchildren.
        #[cfg(unix)]
        let _ = Command::new("/bin/kill")
            .args(["-KILL", "--", &format!("-{}", self.0.id())])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
        #[cfg(not(windows))]
        {
            let _ = self.0.kill();
            let _ = self.0.wait();
        }
        #[cfg(windows)]
        {
            // Terminate the whole job, then reap the leader without waiting
            // indefinitely for a possibly already consumed job notification.
            let _ = self.0.start_kill();
            let _ = self.0.inner_mut().wait();
        }
    }
}

fn drain(mut reader: impl Read) -> Result<Vec<u8>> {
    let mut saved = Vec::new();
    let mut bytes = [0; 8192];
    loop {
        let read = reader.read(&mut bytes)?;
        if read == 0 {
            return Ok(saved);
        }
        // Keep draining after the cap, so a noisy child never blocks its pipes.
        let remaining = (8 * 1024 * 1024_usize).saturating_sub(saved.len());
        saved.extend_from_slice(&bytes[..read.min(remaining)]);
    }
}

/// Run a diagnostic with a deadline, draining both pipes concurrently.
///
/// Terminate the owned Unix process group or Windows job on every exit path.
/// Retry transient executable write locks within the same execution deadline.
pub fn output(command: &mut Command, deadline: Duration) -> Result<Output> {
    let end = Instant::now() + deadline;
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt as _;
        command.process_group(0);
    }
    command.stdout(Stdio::piped()).stderr(Stdio::piped());
    let mut child = loop {
        match Owned::spawn(command) {
            Err(error) if error.kind() == ErrorKind::ExecutableFileBusy => {
                // Another thread may fork while a newly written executable is
                // still open. Its inherited writer closes only at exec, even
                // after our writer was dropped (rust-lang/rust#114554).
                let remaining = end.saturating_duration_since(Instant::now());
                if remaining.is_zero() {
                    return Err(Error::new(
                        ErrorKind::TimedOut,
                        "diagnostic deadline exceeded while executable is busy",
                    ));
                }
                tracing::debug!("retrying diagnostic launch while executable is open for writing");
                std::thread::sleep(remaining.min(Duration::from_millis(20)));
            }
            result => break result?,
        }
    };
    let (stdout, stderr) = child.pipes();
    let stdout = std::thread::spawn(move || drain(stdout));
    let stderr = std::thread::spawn(move || drain(stderr));
    let status = loop {
        if let Some(status) = child.try_wait()? {
            break Some(status);
        }
        if Instant::now() >= end {
            break None;
        }
        std::thread::sleep(Duration::from_millis(20));
    };
    drop(child);
    let stdout = stdout
        .join()
        .map_err(|_| std::io::Error::other("stdout reader failed"))??;
    let stderr = stderr
        .join()
        .map_err(|_| std::io::Error::other("stderr reader failed"))??;
    let status = status.ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::TimedOut, "diagnostic deadline exceeded")
    })?;
    Ok(Output {
        status,
        stdout,
        stderr,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    #[cfg(windows)]
    fn windows_fast_exit_retains_status_and_output_without_a_second_job_wait() {
        let start = Instant::now();
        for _ in 0..8 {
            let result = output(
                Command::new("cmd.exe").args(["/D", "/C", "echo complete & exit /B 17"]),
                Duration::from_secs(1),
            )
            .unwrap();
            assert_eq!(result.status.code(), Some(17));
            assert!(String::from_utf8_lossy(&result.stdout).contains("complete"));
        }
        assert!(start.elapsed() < Duration::from_secs(10));
    }

    #[test]
    #[cfg(windows)]
    fn windows_job_terminates_a_descendant_holding_the_pipes() {
        let start = Instant::now();
        let error = output(
            Command::new("powershell.exe").args([
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                "& cmd.exe /D /S /C 'ping -n 31 127.0.0.1 >nul'",
            ]),
            Duration::from_secs(2),
        )
        .unwrap_err();
        assert_eq!(error.kind(), std::io::ErrorKind::TimedOut);
        assert!(start.elapsed() < Duration::from_secs(6));
    }

    #[test]
    #[cfg(unix)]
    fn a_stalled_grandchild_cannot_keep_output_collection_alive() {
        let start = Instant::now();
        let error = output(
            Command::new("sh").args(["-c", "sleep 30 & wait"]),
            Duration::from_millis(100),
        )
        .unwrap_err();
        assert_eq!(error.kind(), std::io::ErrorKind::TimedOut);
        assert!(start.elapsed() < Duration::from_secs(2));
    }

    #[test]
    #[cfg(unix)]
    fn both_pipes_are_drained_before_waiting_for_exit() {
        let result = output(
            Command::new("sh").args([
                "-c",
                "head -c 100000 /dev/zero; head -c 100000 /dev/zero >&2",
            ]),
            Duration::from_secs(5),
        )
        .unwrap();
        assert!(result.status.success());
        assert_eq!(result.stdout.len(), 100_000);
        assert_eq!(result.stderr.len(), 100_000);
    }
}

