        return Err("prompt templates cannot be resolved by the selected provider bridge".into());
    }
    match body.get("include") {
        None | Some(crate::translation_core::Json::Null) => Ok(()),
        Some(crate::translation_core::Json::Array(values)) if values.is_empty() => Ok(()),
        Some(crate::translation_core::Json::Array(_)) => {
            Err("include selectors cannot be represented by the selected provider".into())
        }
        Some(_) => Err("include must be an array".into()),
    }
}

pub fn validate_openai_prompt_cache(body: &crate::translation_core::Json, anthropic_target: bool) -> crate::translation_core::Outcome<(), String> {
    for field in ["prompt_cache_key", "prompt_cache_retention"] {
        if body.get(field).is_some_and(|value| !value.is_null()) {
            return Err(crate::translation_core::format!(
                "{field} cannot be represented by the selected provider"
            ));
        }
    }
    if let Some(options) = body
        .get("prompt_cache_options")
        .filter(|value| !value.is_null())
    {
        if !anthropic_target {
            return Err(
                "prompt_cache_options cannot be represented by the selected provider".into(),
            );
        }
        let object = options
            .as_object()
            .ok_or_else(|| crate::translation_core::format!("{}", "prompt_cache_options must be an object"))?;
        if !object.is_empty()
            && (object.len() != 1 || object.get("mode").and_then(Value::as_str) != Some("explicit"))
        {
            return Err(
                "only prompt_cache_options mode=explicit without TTL can be represented by Anthropic"
                    .into(),
            );
        }
    }
    validate_openai_prompt_cache_breakpoints(body, anthropic_target)
}

/// Validate the current `OpenAI` content-level breakpoint shape. Responses
/// targets can preserve these fields directly, while provider bridges choose
/// whether the target has an exact semantic equivalent.
pub fn validate_openai_prompt_cache_breakpoints(
    body: &crate::translation_core::Json,
    target_supports_breakpoints: bool,
) -> crate::translation_core::Outcome<(), String> {
    let mut breakpoints = Vec::new();
    collect_named_values(body, "prompt_cache_breakpoint", &mut breakpoints);
    if breakpoints.len() > 4 {
        return Err("OpenAI supports at most four prompt cache breakpoints".into());
    }
    for breakpoint in breakpoints {
        if !target_supports_breakpoints {
            return Err(
                "prompt_cache_breakpoint cannot be represented by the selected provider".into(),
            );
        }
        let Some(object) = breakpoint.as_object() else {
            return Err("prompt_cache_breakpoint must be an object".into());
        };
        if object.len() != 1 || object.get("mode").and_then(crate::translation_core::Json::as_str) != Some("explicit") {
            return Err("only prompt_cache_breakpoint mode=explicit is supported".into());
        }
    }
    Ok(())
}

#[must_use]
pub fn codex_instruction_cache_breakpoint(body: &crate::translation_core::Json) -> crate::translation_core::Maybe<String> {
    for (index, message) in body
        .get("messages")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .enumerate()
    {
        if !matches!(
            message.get("role").and_then(Value::as_str),
            Some("system" | "developer")
        ) {
            continue;
        }
        let mut found = Vec::new();
        if let Some(content) = message.get("content") {
            collect_named_values(content, "prompt_cache_breakpoint", &mut found);
        }
        if !found.is_empty() {
            return Some(crate::translation_core::format!(
                "messages[{index}] prompt_cache_breakpoint cannot be preserved when Codex hoists system or developer content into instructions"
            ));
        }
    }
    None
}

fn collect_named_values<'a>(value: &'a Value, name: &str, found: &mut Vec<&'a Value>) {
    match value {
        Value::Object(object) => {
            for (key, child) in object {
                if key == name {
                    found.push(child);
                } else {
                    collect_named_values(child, name, found);
                }
            }
        }
        Value::Array(array) => {
            for child in array {
                collect_named_values(child, name, found);
            }
        }
        _ => {}
    }
}

pub fn validate_responses(request: &crate::responses::OpenAIResponseRequest) -> crate::translation_core::Outcome<(), String> {
    crate::safety_identifier::validate_openai(request.safety_identifier.as_deref())?;
    crate::safety_identifier::validate_openai_user(request.user.as_deref())?;
    if request
        .top_p
        .is_some_and(|top_p| !crate::translation_core::f64_inclusive_contains(0.0, 1.0, top_p))
    {
        return Err("top_p must be between 0 and 1".into());
    }
    if request.temperature.is_some() && request.top_p.is_some() {
        return Err("temperature and top_p cannot both be represented by Anthropic".into());
    }
    if request.background == Some(true) {
        return Err(
            "background responses cannot be created through an Anthropic bridge; use a synchronous request"
                .into(),
        );
    }
    if request.store == Some(true) {
        return Err(
            "stored responses cannot be created through an Anthropic bridge; use store=false"
                .into(),
        );
    }
    if request.metadata.as_ref().is_some_and(|metadata| {
        !metadata.is_null() && metadata.as_object().is_none_or(|v| !v.is_empty())
    }) {
        return Err("metadata cannot be represented by an Anthropic bridge".into());
    }
    if request.context_management.as_ref().is_some_and(|context| {
        !context.is_null() && context.as_array().is_none_or(|items| !items.is_empty())
    }) {
        return Err("context_management cannot be represented by an Anthropic bridge".into());
    }
    if request.top_logprobs.is_some_and(|count| count > 0) {
        return Err("top_logprobs cannot be represented by an Anthropic bridge".into());
    }
    if request
        .truncation
        .as_ref()
        .filter(|value| !value.is_null())
        .is_some_and(|value| value.as_str() != Some("disabled"))
    {
        return Err("only truncation=disabled can be represented by an Anthropic bridge".into());
    }
    if request
        .stream_options
        .as_ref()
        .filter(|value| !value.is_null())
        .is_some_and(|value| value.as_object().is_none_or(|options| !options.is_empty()))
    {
        return Err("non-empty stream_options cannot be represented by an Anthropic bridge".into());
    }
    if let Some(limit) = request.max_tool_calls {
        if limit == 0 {
            return Err("max_tool_calls must be greater than zero".into());
        }
        let server_tools = request
            .tools
            .as_ref()
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter(|tool| {
                matches!(
                    tool.get("type").and_then(Value::as_str),
                    Some("web_search" | "web_fetch")
                )
            })
            .count();
        if server_tools > 1 {
            return Err(
                "max_tool_calls cannot be enforced losslessly across multiple server tools".into(),
            );
        }
    }
    Ok(())
}

pub fn install_max_tool_calls(body: &mut Value, limit: Option<u32>) {
    let Some(limit) = limit else {
        return;
    };
    let Some(tools) = body.get_mut("tools").and_then(Value::as_array_mut) else {
        return;
    };
    let mut server_tools = tools.iter_mut().filter(|tool| {
        tool.get("type")
            .and_then(Value::as_str)
            .is_some_and(|kind| kind.starts_with("web_search_") || kind.starts_with("web_fetch_"))
    });
    if let Some(tool) = server_tools.next()
        && server_tools.next().is_none()
    {
        tool["max_uses"] = Value::from(limit);
    }
}

//! Fail-closed request translation between `Anthropic` and `OpenAI` dialects.

use base64::Engine as _;
use serde_json::{Value, json};

#[path = "bridge_request_tools.rs"]
mod tools;
pub use tools::system_text;
use tools::{
    anthropic_effort, anthropic_parallel_tool_calls, anthropic_response_format,
    translate_tool_choice, translate_tools,
};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BridgeTarget {
    Responses,
    Chat,
    Gemini,
}

/// Translate an `Anthropic` Messages request to `OpenAI` Chat Completions.
#[must_use]
pub fn anthropic_to_chat_request(body: &Value, upstream_model: &str) -> Value {
    let mut messages = Vec::new();
    if let Some(system) = body.get("system").and_then(system_text) {
        messages.push(json!({"role": "system", "content": system}));
    }
    for message in body
        .get("messages")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or_default()
    {
        let role = message
            .get("role")
            .and_then(Value::as_str)
            .unwrap_or("user");
        match message.get("content").unwrap_or(&Value::Null) {
            Value::String(text) => messages.push(json!({"role": role, "content": text})),
            Value::Array(blocks) => translate_chat_blocks(role, blocks, &mut messages),
            _ => {}
        }
    }

    let mut out = json!({
        "model": upstream_model,
        "messages": messages,
        "max_tokens": body
            .get("max_tokens")
            .and_then(Value::as_u64)
            .unwrap_or(crate::anthropic_bridge::DEFAULT_MAX_TOKENS),
    });
    for key in ["temperature", "top_p", "top_k"] {
        if let Some(value) = body.get(key) {
            out[key] = value.clone();
        }
    }
    if body.get("stream").and_then(Value::as_bool) == Some(true) {
        out["stream"] = Value::Bool(true);
    }
    if let Some(stops) = body.get("stop_sequences") {
        out["stop"] = stops.clone();
    }
    if let Some(tools) = body.get("tools").and_then(Value::as_array) {
        let mapped = translate_tools(tools);
        if !mapped.is_empty() {
            out["tools"] = Value::Array(mapped);
        }
    }
    if let Some(choice) = body.get("tool_choice").and_then(translate_tool_choice) {
        out["tool_choice"] = choice;
    }
    if let Ok(Some(effort)) = anthropic_effort(body) {
        out["reasoning_effort"] = Value::String(effort.into());
    }
    if let Ok(Some(identifier)) = crate::safety_identifier::anthropic_user_id(body) {
        out["safety_identifier"] = Value::String(identifier.into());
    }
    if let Ok(Some(format)) = anthropic_response_format(body) {
        out["response_format"] = format;
    }
    if let Ok(Some(parallel)) = anthropic_parallel_tool_calls(body) {
        out["parallel_tool_calls"] = Value::Bool(parallel);
    }
    out
}

/// Translate an `Anthropic` request directly to Responses input.
pub fn anthropic_to_responses_request(body: &Value, upstream_model: &str) -> Result<Value, String> {
    validate_anthropic_request(body, BridgeTarget::Responses)?;
    let mut skeleton = body.clone();
    skeleton["messages"] = Value::Array(Vec::new());
    let chat = anthropic_to_chat_request(&skeleton, upstream_model);
    let mut out = crate::responses::try_chat_completion_to_responses(&chat)?;
    out["input"] = Value::Array(anthropic_messages_to_responses(body)?);
    Ok(out)
}

/// Validate every Anthropic history block for a translated target.
pub fn validate_anthropic_request(body: &Value, target: BridgeTarget) -> Result<(), String> {
    anthropic_effort(body)?;
    anthropic_response_format(body)?;
    anthropic_parallel_tool_calls(body)?;
    crate::safety_identifier::anthropic_user_id(body)?;
    crate::bridge_controls::reject_anthropic_provider_controls(body)?;
    match body.get("top_k") {
        None | Some(Value::Null) => {}
        Some(value) if target == BridgeTarget::Gemini && value.as_u64().is_some() => {}
        Some(value) if value.as_u64().is_none() => {
            return Err("top_k must be a non-negative integer".into());
        }
        Some(_) => {
            return Err("top_k cannot be represented by the selected provider".into());
        }
    }
    if let Some(system) = body.get("system") {
        match system {
            Value::String(_) => {}
            Value::Array(blocks) => {
                for (index, block) in blocks.iter().enumerate() {
                    if block.get("type").and_then(Value::as_str) != Some("text")
                        || block.get("text").and_then(Value::as_str).is_none()
                    {
                        return Err(format!(
                            "system[{index}] cannot be represented by the selected provider"
                        ));
                    }
                }
            }
            _ => return Err("system must be a string or an array of text blocks".into()),
        }
    }
    let Some(messages) = body.get("messages").and_then(Value::as_array) else {
        return Err("messages must be an array".into());
    };
    for (message_index, message) in messages.iter().enumerate() {
        let Some(role) = message.get("role").and_then(Value::as_str) else {
            return Err(format!(
                "messages[{message_index}] is missing a string role"
            ));
        };
        if !matches!(role, "user" | "assistant") {
            return Err(format!(
                "messages[{message_index}] has unsupported role {role}"
            ));
        }
        match message.get("content") {
            Some(Value::String(_)) => {}
            Some(Value::Array(blocks)) => {
                let mut saw_follow_up = false;
                for (block_index, block) in blocks.iter().enumerate() {
                    let path = format!("messages[{message_index}].content[{block_index}]");
                    let kind = block
                        .get("type")
                        .and_then(Value::as_str)
                        .ok_or_else(|| format!("{path} is missing a string type"))?;
                    if kind == "tool_result" && saw_follow_up {
                        return Err(format!(
                            "{path} must precede follow-up text, image, or document content"
                        ));
                    }
                    if kind != "tool_result" {
                        saw_follow_up = true;
                    }
                    validate_anthropic_block(block, role, target, &path)?;
                }
            }
            _ => {
                return Err(format!(
                    "messages[{message_index}].content must be a string or array"
                ));
            }
        }
    }
    Ok(())
}

/// Return why a Responses history cannot cross into `Anthropic`.
#[must_use]
pub fn untranslatable_response_history(input: &Value) -> Option<String> {
    let items = match input {
        Value::String(_) => return None,
        Value::Array(items) => items,
        _ => return Some("input must be a string or array".into()),
    };
    for (index, item) in items.iter().enumerate() {
        if item.is_string() {
            continue;
        }
        let path = format!("input[{index}]");
        if let Some(role) = item.get("role").and_then(Value::as_str) {
            if !matches!(role, "system" | "developer" | "user" | "assistant") {
                return Some(format!("{path} has unsupported role {role}"));
            }
            let content = item.get("content").unwrap_or(&Value::Null);
            if let Err(reason) = responses_message_content_to_anthropic(content, role, &path) {
                return Some(reason);
            }
            continue;
        }
        match item.get("type").and_then(Value::as_str) {
            Some("function_call") => {
                if item
                    .get("call_id")
                    .or_else(|| item.get("id"))
                    .and_then(Value::as_str)
                    .is_none_or(str::is_empty)
                {
                    return Some(format!("{path} function_call is missing call_id"));
                }
                if nonempty(item, "name").is_none() {
                    return Some(format!("{path} function_call is missing name"));
                }
                let Some(arguments) = item.get("arguments").and_then(Value::as_str) else {
                    return Some(format!("{path} function_call is missing string arguments"));
                };
                if serde_json::from_str::<Value>(arguments)
                    .ok()
                    .is_none_or(|arguments| !arguments.is_object())
                {
                    return Some(format!(
                        "{path} function_call arguments must encode a JSON object"
                    ));
                }
            }
            Some("function_call_output") => {
                if nonempty(item, "call_id").is_none() {
                    return Some(format!("{path} function_call_output is missing call_id"));
                }
                if let Err(reason) =
                    responses_output_to_anthropic(item.get("output"), &format!("{path}.output"))
                {
                    return Some(reason);
                }
            }
            Some("reasoning") => {
                return Some(format!(
                    "{path} reasoning history is provider-specific; start a provider-compatible continuation"
                ));
            }
            Some("custom_tool_call" | "custom_tool_call_output") => {
                return Some(format!(
                    "{path} custom tool history is provider-specific; start a provider-compatible continuation"
                ));
            }
            Some(kind) => {
                return Some(format!(
                    "{path} item type {kind} cannot be represented by Anthropic"
                ));
            }
            None => return Some(format!("{path} is missing a string type or role")),
        }
    }
    None
}

/// Reject server-side Responses continuation handles on a stateless bridge.
#[must_use]
pub fn untranslatable_responses_state(body: &Value) -> Option<String> {
    let previous = body
        .get("previous_response_id")
        .is_some_and(|value| !value.is_null());
    let conversation = body
        .get("conversation")
        .is_some_and(|value| !value.is_null());
    match (previous, conversation) {
        (true, true) => Some(
            "previous_response_id and conversation are mutually exclusive and cannot be resolved by an Anthropic bridge; send self-contained input"
                .into(),
        ),
        (true, false) => Some(
            "previous_response_id cannot be resolved by an Anthropic bridge; send self-contained input"
                .into(),
        ),
        (false, true) => Some(
            "conversation cannot be resolved by an Anthropic bridge; send self-contained input"
                .into(),
        ),
        (false, false) => None,
    }
}

pub fn responses_message_content_to_anthropic(
    content: &Value,
    role: &str,
    path: &str,
) -> Result<Value, String> {
    match content {
        Value::String(text) => Ok(Value::String(text.clone())),
        Value::Array(parts) => parts
            .iter()
            .enumerate()
            .map(|(index, part)| {
                let part_path = format!("{path}.content[{index}]");
                match part.get("type").and_then(Value::as_str) {
                    Some("text" | "input_text" | "output_text") => {
                        let mut block = json!({
                            "type": "text",
                            "text": require_string(part, "text", &part_path)?,
                        });
                        if part.get("prompt_cache_breakpoint").is_some() {
                            block["cache_control"] = json!({"type": "ephemeral"});
                        }
                        Ok(block)
                    }
                    Some("input_image") if role == "user" => {
                        responses_image_to_anthropic(part, &part_path)
                    }
                    Some("input_file") if role == "user" => {
                        responses_file_to_anthropic(part, &part_path)
                    }
                    Some(kind) => Err(format!(
                        "{part_path} type {kind} cannot be represented for role {role}"
                    )),
                    None => Err(format!("{part_path} is missing a string type")),
                }
            })
            .collect::<Result<Vec<_>, _>>()
            .map(Value::Array),
        _ => Err(format!("{path}.content must be a string or array")),
    }
}

fn validate_anthropic_block(
    block: &Value,
    role: &str,
    target: BridgeTarget,
    path: &str,
) -> Result<(), String> {
    match block
        .get("type")
        .and_then(Value::as_str)
        .unwrap_or_default()
    {
        "text" => {
            require_string(block, "text", path)?;
        }
        "image" => {
            if role != "user" {
                return Err(format!("{path} image is only representable in a user turn"));
            }
            match target {
                BridgeTarget::Responses => {
                    image_to_responses(block, path)?;
                }
                BridgeTarget::Chat | BridgeTarget::Gemini => {
                    image_to_chat(block, path)?;
                }
            }
        }
        "document" => {
            if role != "user" {
                return Err(format!(
                    "{path} document is only representable in a user turn"
                ));
            }
            match target {
                BridgeTarget::Responses => {
                    document_to_responses(block, path)?;
                }
                BridgeTarget::Chat => {
                    document_to_chat(block, path)?;
                }
                BridgeTarget::Gemini => {
                    return Err(format!(
                        "{path} document cannot be represented by the selected provider"
                    ));
                }
            }
        }
        "tool_use" => {
            if role != "assistant" {
                return Err(format!("{path} tool_use must have the assistant role"));
            }
            require_nonempty_string(block, "id", path)?;
            require_nonempty_string(block, "name", path)?;
            if !block.get("input").is_some_and(Value::is_object) {
                return Err(format!("{path}.input must be an object"));
            }
        }
        "tool_result" => {
            if role != "user" {
                return Err(format!("{path} tool_result must have the user role"));
            }
            require_nonempty_string(block, "tool_use_id", path)?;
            if block.get("is_error").and_then(Value::as_bool) == Some(true) {
                return Err(format!(
                    "{path}.is_error=true cannot be represented by the selected provider"
                ));
            }
            match target {
                BridgeTarget::Responses => {
                    anthropic_tool_result_to_responses(block.get("content"), path)?;
                }
                BridgeTarget::Chat | BridgeTarget::Gemini => {
                    tool_result_to_chat(block.get("content"), path)?;
                }
            }
        }
        "server_tool_use" => {
            if role != "assistant" {
                return Err(format!(
                    "{path} server_tool_use must have the assistant role"
                ));
            }
            if target != BridgeTarget::Responses {
                return Err(format!(
                    "{path} server-tool history cannot be represented by the selected provider"
                ));
            }
            require_nonempty_string(block, "id", path)?;
            let name = require_nonempty_string(block, "name", path)?;
            if !matches!(name, "web_search" | "web_fetch") {
                return Err(format!("{path} has unsupported server tool name {name}"));
            }
            if !block.get("input").is_some_and(Value::is_object) {
                return Err(format!("{path}.input must be an object"));
            }
        }
        "web_search_tool_result" | "web_fetch_tool_result" => {
            if role != "assistant" {
                return Err(format!(
                    "{path} server-tool result must have the assistant role"
                ));
            }
            if target != BridgeTarget::Responses {
                return Err(format!(
                    "{path} server-tool result cannot be represented by the selected provider"
                ));
            }
            require_nonempty_string(block, "tool_use_id", path)?;
            if block.get("content").is_none_or(Value::is_null) {
                return Err(format!("{path}.content is required"));
            }
        }
        "thinking" | "redacted_thinking" => {
            return Err(format!(
                "{path} contains Anthropic thinking history that the selected provider cannot continue"
            ));
        }
        kind => {
            return Err(format!(
                "{path} block type {kind} cannot be represented by the selected provider"
            ));
        }
    }
    Ok(())
}

/// Map one Responses `function_call_output.output` to Anthropic content.
pub fn responses_output_to_anthropic(output: Option<&Value>, path: &str) -> Result<Value, String> {
    match output {
        Some(Value::String(text)) => Ok(Value::String(text.clone())),
        Some(Value::Array(parts)) => parts
            .iter()
            .enumerate()
            .map(|(index, part)| {
                responses_output_part_to_anthropic(part, &format!("{path}[{index}]"))
            })
            .collect::<Result<Vec<_>, _>>()
            .map(Value::Array),
        Some(_) => Err(format!("{path} must be a string or array")),
        None => Err(format!("{path} is required")),
    }
}

fn responses_output_part_to_anthropic(part: &Value, path: &str) -> Result<Value, String> {
    match part.get("type").and_then(Value::as_str) {
        Some("input_text") => {
            let mut block = json!({
                "type": "text",
                "text": require_string(part, "text", path)?,
            });
            copy_responses_cache_control(part, &mut block);
            Ok(block)
        }
        Some("input_image") => responses_image_to_anthropic(part, path),
        Some("input_file") => responses_file_to_anthropic(part, path),
        Some(kind) => Err(format!("{path} has unsupported output type {kind}")),
        None => Err(format!("{path} is missing a string type")),
    }
}

fn responses_image_to_anthropic(part: &Value, path: &str) -> Result<Value, String> {
    validate_default_detail(part, path)?;
    let image_url = nonempty(part, "image_url");
    let file_id = nonempty(part, "file_id");
    if usize::from(image_url.is_some()) + usize::from(file_id.is_some()) != 1 {
        return Err(format!(
            "{path} must contain exactly one non-empty image_url or file_id"
        ));
    }
    if file_id.is_some() {
        return Err(format!(
            "{path}.file_id belongs to the OpenAI provider and cannot be used by Anthropic"
        ));
    }
    let source = {
        let url = image_url.expect("one source was checked");
        if url.starts_with("data:") {
            let (media_type, data) = parse_data_url(url, path)?;
            if !matches!(
                media_type,
                "image/jpeg" | "image/png" | "image/gif" | "image/webp"
            ) {
                return Err(format!(
                    "{path} has unsupported image media type {media_type}"
                ));
            }
            json!({"type": "base64", "media_type": media_type, "data": data})
        } else {
            let parsed = url::Url::parse(url)
                .map_err(|_| format!("{path}.image_url must be an absolute URL"))?;
            if !matches!(parsed.scheme(), "http" | "https") {
                return Err(format!("{path}.image_url must use HTTP or HTTPS"));
            }
            json!({"type": "url", "url": url})
        }
    };
    let mut image = json!({"type": "image", "source": source});
    copy_responses_cache_control(part, &mut image);
    Ok(image)
}

fn responses_file_to_anthropic(part: &Value, path: &str) -> Result<Value, String> {
    validate_default_detail(part, path)?;
    let file_data = nonempty(part, "file_data");
    let file_id = nonempty(part, "file_id");
    let file_url = nonempty(part, "file_url");
    if [file_data, file_id, file_url].iter().flatten().count() != 1 {
        return Err(format!(
            "{path} must contain exactly one non-empty file_data, file_id, or file_url"
        ));
    }
    if file_id.is_some() {
        return Err(format!(
            "{path}.file_id belongs to the OpenAI provider and cannot be used by Anthropic"
        ));
    }
    let source = if let Some(file_url) = file_url {
        let parsed = url::Url::parse(file_url)
            .map_err(|_| format!("{path}.file_url must be an absolute URL"))?;
        if !parsed.path().to_ascii_lowercase().ends_with(".pdf") {
            return Err(format!(
                "{path}.file_url is not a PDF URL supported by Anthropic"
            ));
        }
        json!({"type": "url", "url": file_url})
    } else {
        let data_url = file_data.expect("one source was checked");
        let (media_type, data) = parse_data_url(data_url, path)?;
        match media_type {
            "application/pdf" => {
                json!({"type": "base64", "media_type": media_type, "data": data})
            }
            "text/plain" => {
                let bytes = base64::engine::general_purpose::STANDARD
                    .decode(data)
                    .map_err(|error| format!("{path}.file_data is invalid base64: {error}"))?;
                let text = String::from_utf8(bytes)
                    .map_err(|_| format!("{path}.file_data is not UTF-8 plain text"))?;
                json!({"type": "text", "media_type": media_type, "data": text})
            }
            _ => {
                return Err(format!(
                    "{path} has unsupported file media type {media_type}"
                ));
            }
        }
    };
    let mut document = json!({"type": "document", "source": source});
    if let Some(filename) = nonempty(part, "filename") {
        document["title"] = Value::String(filename.to_string());
    }
    copy_responses_cache_control(part, &mut document);
    Ok(document)
}

fn copy_responses_cache_control(source: &Value, target: &mut Value) {
    if source.get("prompt_cache_breakpoint").is_some() {
        target["cache_control"] = json!({"type":"ephemeral"});
    }
}

fn anthropic_tool_result_to_responses(
    content: Option<&Value>,
    path: &str,
) -> Result<Value, String> {
    match content {
        None => Ok(Value::String(String::new())),
        Some(Value::String(text)) => Ok(Value::String(text.clone())),
        Some(Value::Array(blocks)) => blocks
            .iter()
            .enumerate()
            .map(|(index, block)| {
                let part_path = format!("{path}.content[{index}]");
                match block.get("type").and_then(Value::as_str) {
                    Some("text") => Ok(json!({
                        "type": "input_text",
                        "text": require_string(block, "text", &part_path)?,
                    })),
                    Some("image") => image_to_responses(block, &part_path),
                    Some("document") => document_to_responses(block, &part_path),
                    Some(kind) => Err(format!(
                        "{part_path} block type {kind} cannot be represented in Responses output"
                    )),
                    None => Err(format!("{part_path} is missing a string type")),
                }
            })
            .collect::<Result<Vec<_>, _>>()
            .map(Value::Array),
        Some(_) => Err(format!("{path}.content must be a string or array")),
    }
}

fn image_to_responses(block: &Value, path: &str) -> Result<Value, String> {
    reject_present(block, &["transformations"], path)?;
    let source = block
        .get("source")
        .ok_or_else(|| format!("{path}.source is required"))?;
    match source.get("type").and_then(Value::as_str) {
        Some("url") => Ok(json!({
            "type": "input_image",
            "image_url": require_nonempty_string(source, "url", &format!("{path}.source"))?,
        })),
        Some("base64") => {
            let media = require_nonempty_string(source, "media_type", &format!("{path}.source"))?;
            if !matches!(
                media,
                "image/jpeg" | "image/png" | "image/gif" | "image/webp"
            ) {
                return Err(format!(
                    "{path}.source has unsupported image media type {media}"
                ));
            }
            let data = require_nonempty_string(source, "data", &format!("{path}.source"))?;
            Ok(json!({
                "type": "input_image",
                "image_url": format!("data:{media};base64,{data}"),
            }))
        }
        Some("file") => Ok(json!({
            "type": "input_image",
            "file_id": require_nonempty_string(source, "file_id", &format!("{path}.source"))?,
        })),
        Some(kind) => Err(format!("{path}.source type {kind} is unsupported")),
        None => Err(format!("{path}.source is missing a string type")),
    }
}

fn document_to_responses(block: &Value, path: &str) -> Result<Value, String> {
    reject_present(block, &["context", "citations"], path)?;
    let source = block
        .get("source")
        .ok_or_else(|| format!("{path}.source is required"))?;
    let mut file = match source.get("type").and_then(Value::as_str) {
        Some("base64") => {
            let media = require_nonempty_string(source, "media_type", &format!("{path}.source"))?;
            if media != "application/pdf" {
                return Err(format!(
                    "{path}.source has unsupported document media type {media}"
                ));
            }
            let data = require_nonempty_string(source, "data", &format!("{path}.source"))?;
            json!({"type": "input_file", "file_data": format!("data:{media};base64,{data}")})
        }
        Some("url") => {
            let url = require_nonempty_string(source, "url", &format!("{path}.source"))?;
            let parsed = url::Url::parse(url)
                .map_err(|_| format!("{path}.source.url must be an absolute URL"))?;
            if !matches!(parsed.scheme(), "http" | "https")
                || !parsed.path().to_ascii_lowercase().ends_with(".pdf")
            {
                return Err(format!("{path}.source.url must be an HTTP(S) PDF URL"));
            }
            json!({"type": "input_file", "file_url": url})
        }
        Some("text") => {
            let media = require_nonempty_string(source, "media_type", &format!("{path}.source"))?;
            if media != "text/plain" {
                return Err(format!(
                    "{path}.source has unsupported document media type {media}"
                ));
            }
            let data = require_string(source, "data", &format!("{path}.source"))?;
            let encoded = base64::engine::general_purpose::STANDARD.encode(data.as_bytes());
            json!({"type": "input_file", "file_data": format!("data:text/plain;base64,{encoded}")})
        }
        Some("file") => json!({
            "type": "input_file",
            "file_id": require_nonempty_string(source, "file_id", &format!("{path}.source"))?,
        }),
        Some("content") => {
            return Err(format!(
                "{path}.source type content has no lossless Responses input_file representation"
            ));
        }
        Some(kind) => return Err(format!("{path}.source type {kind} is unsupported")),
        None => return Err(format!("{path}.source is missing a string type")),
    };
    if let Some(title) = nonempty(block, "title") {
        file["filename"] = Value::String(title.to_string());
    }
    Ok(file)
}

fn image_to_chat(block: &Value, path: &str) -> Result<Value, String> {
    let image = image_to_responses(block, path)?;
    let Some(url) = image.get("image_url") else {
        return Err(format!(
            "{path} file-backed image cannot be represented in Chat Completions"
        ));
    };
    Ok(json!({"type": "image_url", "image_url": {"url": url}}))
}

fn document_to_chat(block: &Value, path: &str) -> Result<Value, String> {
    let file = document_to_responses(block, path)?;
    if file.get("file_url").is_some() {
        return Err(format!(
            "{path} URL document cannot be represented in Chat Completions"
        ));
    }
    let mut nested = serde_json::Map::new();
    for key in ["file_data", "file_id", "filename"] {
        if let Some(value) = file.get(key) {
            nested.insert(key.to_string(), value.clone());
        }
    }
    Ok(json!({"type": "file", "file": nested}))
}

fn tool_result_to_chat(content: Option<&Value>, path: &str) -> Result<Value, String> {
    match content {
        None => Ok(Value::String(String::new())),
        Some(Value::String(text)) => Ok(Value::String(text.clone())),
        Some(Value::Array(blocks)) => blocks
            .iter()
            .enumerate()
            .map(|(index, block)| {
                let part_path = format!("{path}.content[{index}]");
                if block.get("type").and_then(Value::as_str) != Some("text") {
                    return Err(format!(
                        "{part_path} cannot be represented in a Chat tool message"
                    ));
                }
                Ok(json!({
                    "type": "text",
                    "text": require_string(block, "text", &part_path)?,
                }))
            })
            .collect::<Result<Vec<_>, _>>()
            .map(Value::Array),
        Some(_) => Err(format!("{path}.content must be a string or array")),
    }
}

fn anthropic_messages_to_responses(body: &Value) -> Result<Vec<Value>, String> {
    let mut input = Vec::new();
    for (message_index, message) in body["messages"]
        .as_array()
        .expect("validated messages array")
        .iter()
        .enumerate()
    {
        let role = message["role"].as_str().expect("validated role");
        match &message["content"] {
            Value::String(text) => {
                input.push(responses_message(role, &[text_part(role, text)]));
            }
            Value::Array(blocks) => {
                let mut parts = Vec::new();
                for (block_index, block) in blocks.iter().enumerate() {
                    let path = format!("messages[{message_index}].content[{block_index}]");
                    match block["type"].as_str().expect("validated block type") {
                        "text" => parts.push(text_part(
                            role,
                            block["text"].as_str().expect("validated text"),
                        )),
                        "image" => parts.push(image_to_responses(block, &path)?),
                        "document" => parts.push(document_to_responses(block, &path)?),
                        "tool_use" => {
                            flush_parts(&mut input, role, &mut parts);
                            input.push(json!({
                                "type": "function_call",
                                "call_id": block["id"].as_str().expect("validated id"),
                                "name": block["name"].as_str().expect("validated name"),
                                "arguments": serde_json::to_string(&block["input"])
                                    .expect("JSON value serializes"),
                            }));
                        }
                        "tool_result" => {
                            flush_parts(&mut input, role, &mut parts);
                            input.push(json!({
                                "type": "function_call_output",
                                "call_id": block["tool_use_id"]
                                    .as_str()
                                    .expect("validated tool_use_id"),
                                "output": anthropic_tool_result_to_responses(
                                    block.get("content"),
                                    &path,
                                )?,
                            }));
                        }
                        "server_tool_use" => {
                            flush_parts(&mut input, role, &mut parts);
                            let name = block["name"].as_str().expect("validated name");
                            input.push(json!({
                                "type": if name == "web_search" {
                                    "web_search_call"
                                } else {
                                    "web_fetch_call"
                                },
                                "id": block["id"].as_str().expect("validated id"),
                                "status": "completed",
                                "action": block["input"].clone(),
                            }));
                        }
                        result_kind @ ("web_search_tool_result" | "web_fetch_tool_result") => {
                            let call_kind = if result_kind == "web_search_tool_result" {
                                "web_search_call"
                            } else {
                                "web_fetch_call"
                            };
                            let tool_use_id = block["tool_use_id"]
                                .as_str()
                                .expect("validated tool_use_id");
                            let Some(call) = input.iter_mut().rev().find(|item| {
                                item.get("type").and_then(Value::as_str) == Some(call_kind)
                                    && item.get("id").and_then(Value::as_str) == Some(tool_use_id)
                            }) else {
                                return Err(format!(
                                    "{path} has no preceding matching server_tool_use"
                                ));
                            };
                            call["status"] = Value::String("completed".into());
                            call["result"] = block["content"].clone();
                        }
                        _ => unreachable!("validated unsupported block"),
                    }
                }
                flush_parts(&mut input, role, &mut parts);
                if blocks.is_empty() {
                    input.push(responses_message(role, &[]));
                }
            }
            _ => unreachable!("validated message content"),
        }
    }
    Ok(input)
}

fn text_part(role: &str, text: &str) -> Value {
    let kind = if role == "assistant" {
        "output_text"
    } else {
        "input_text"
    };
    json!({"type": kind, "text": text})
}

fn responses_message(role: &str, content: &[Value]) -> Value {
    json!({"role": role, "content": content})
}

fn flush_parts(input: &mut Vec<Value>, role: &str, parts: &mut Vec<Value>) {
    if !parts.is_empty() {
        input.push(responses_message(role, parts));
        parts.clear();
    }
}

fn translate_chat_blocks(role: &str, blocks: &[Value], messages: &mut Vec<Value>) {
    let mut text = String::new();
    let mut parts = Vec::new();
    let mut tool_calls = Vec::new();
    let mut tool_results = Vec::new();
    for (index, block) in blocks.iter().enumerate() {
        let path = format!("content[{index}]");
        match block
            .get("type")
            .and_then(Value::as_str)
            .unwrap_or_default()
        {
            "text" => {
                let value = block
                    .get("text")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                text.push_str(value);
                parts.push(json!({"type": "text", "text": value}));
            }
            "image" => {
                if let Ok(part) = image_to_chat(block, &path) {
                    parts.push(part);
                }
            }
            "document" => {
                if let Ok(part) = document_to_chat(block, &path) {
                    parts.push(part);
                }
            }
            "tool_use" => tool_calls.push(json!({
                "id": block.get("id").and_then(Value::as_str).unwrap_or_default(),
                "type": "function",
                "function": {
                    "name": block.get("name").and_then(Value::as_str).unwrap_or_default(),
                    "arguments": serde_json::to_string(
                        block.get("input").unwrap_or(&Value::Null)
                    ).unwrap_or_else(|_| "{}".into()),
                }
            })),
            "tool_result" => tool_results.push(json!({
                "role": "tool",
                "tool_call_id": block
                    .get("tool_use_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default(),
                "content": tool_result_to_chat(block.get("content"), &path)
                    .unwrap_or(Value::Null),
            })),
            _ => {}
        }
    }

    // Anthropic requires tool results to lead the user turn.  OpenAI models
    // them as distinct messages, so emit every parallel result before the
    // follow-up user content while retaining their original order.
    messages.extend(tool_results);
    let complex_content = parts.iter().any(|part| part["type"] != "text");
    if !text.is_empty() || !tool_calls.is_empty() || complex_content || blocks.is_empty() {
        let content = if complex_content {
            Value::Array(parts)
        } else {
            Value::String(text)
        };
        let mut message = json!({"role": role, "content": content});
        if !tool_calls.is_empty() {
            message["tool_calls"] = Value::Array(tool_calls);
        }
        messages.push(message);
    }
}

fn validate_default_detail(part: &Value, path: &str) -> Result<(), String> {
    if part
        .get("detail")
        .filter(|value| !value.is_null())
        .and_then(Value::as_str)
        .is_some_and(|detail| detail != "auto")
    {
        return Err(format!(
            "{path}.detail cannot be represented by the selected Anthropic provider"
        ));
    }
    Ok(())
}

fn parse_data_url<'a>(url: &'a str, path: &str) -> Result<(&'a str, &'a str), String> {
    let Some(encoded) = url.strip_prefix("data:") else {
        return Err(format!("{path} must use a base64 data URL"));
    };
    let Some((media_type, data)) = encoded.split_once(";base64,") else {
        return Err(format!("{path} must use a base64 data URL"));
    };
    if media_type.is_empty() || data.is_empty() {
        return Err(format!("{path} contains an empty data URL"));
    }
    Ok((media_type, data))
}

fn reject_present(block: &Value, keys: &[&str], path: &str) -> Result<(), String> {
    if let Some(key) = keys
        .iter()
        .find(|key| block.get(**key).is_some_and(|value| !value.is_null()))
    {
        return Err(format!(
            "{path}.{key} cannot be represented by the selected provider"
        ));
    }
    Ok(())
}

fn nonempty<'a>(value: &'a Value, key: &str) -> Option<&'a str> {
    value
        .get(key)
        .and_then(Value::as_str)
        .filter(|text| !text.is_empty())
}

fn require_string<'a>(value: &'a Value, key: &str, path: &str) -> Result<&'a str, String> {
    value
        .get(key)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("{path}.{key} must be a string"))
}

fn require_nonempty_string<'a>(value: &'a Value, key: &str, path: &str) -> Result<&'a str, String> {
    nonempty(value, key).ok_or_else(|| format!("{path}.{key} must be a non-empty string"))
}

use serde_json::{Value, json};

pub fn system_text(system: &Value) -> Option<String> {
    match system {
        Value::String(text) if !text.is_empty() => Some(text.clone()),
        Value::Array(blocks) => {
            let text = blocks
                .iter()
                .filter_map(|block| block.get("text").and_then(Value::as_str))
                .collect::<Vec<_>>()
                .join("\n\n");
            (!text.is_empty()).then_some(text)
        }
        _ => None,
    }
}

pub(super) fn translate_tools(tools: &[Value]) -> Vec<Value> {
    tools
        .iter()
        .map(|tool| {
            if tool
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(|kind| kind.starts_with("web_search_"))
            {
                return json!({"type": "web_search"});
            }
            if tool
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(|kind| kind.starts_with("web_fetch_"))
            {
                return json!({"type": "web_fetch"});
            }
            let mut mapped = json!({
                "type": "function",
                "function": {
                    "name": tool.get("name").and_then(Value::as_str).unwrap_or_default(),
                    "description": tool.get("description").cloned()
                        .unwrap_or(Value::String(String::new())),
                    "parameters": tool.get("input_schema").cloned()
                        .unwrap_or_else(|| json!({"type": "object", "properties": {}})),
                }
            });
            if let Some(strict) = tool.get("strict") {
                mapped["function"]["strict"] = strict.clone();
            }
            mapped
        })
        .collect()
}

pub(super) fn translate_tool_choice(choice: &Value) -> Option<Value> {
    match choice.get("type").and_then(Value::as_str)? {
        "auto" => Some(json!("auto")),
        "any" => Some(json!("required")),
        "none" => Some(json!("none")),
        "tool" => Some(json!({
            "type": "function",
            "function": {"name": choice.get("name").and_then(Value::as_str)?},
        })),
        _ => None,
    }
}

pub(super) fn anthropic_effort(body: &Value) -> Result<Option<&'static str>, String> {
    let effort = match body.get("output_config") {
        None | Some(Value::Null) => None,
        Some(config) => {
            let config = config
                .as_object()
                .ok_or_else(|| "output_config must be an object".to_string())?;
            if let Some(field) = config
                .keys()
                .find(|field| !matches!(field.as_str(), "effort" | "format"))
            {
                return Err(format!("unsupported output_config field: {field}"));
            }
            match config.get("effort") {
                None | Some(Value::Null) => None,
                Some(effort) => {
                    let effort = effort
                        .as_str()
                        .ok_or_else(|| "output_config.effort must be a string".to_string())?;
                    Some(match effort {
                        "low" => "low",
                        "medium" => "medium",
                        "high" => "high",
                        "max" => "xhigh",
                        _ => return Err(format!("unsupported output_config.effort: {effort}")),
                    })
                }
            }
        }
    };
    if body.get("thinking").is_some_and(|value| !value.is_null()) {
        return crate::thinking::anthropic::translated_effort(body);
    }
    Ok(effort)
}

pub(super) fn anthropic_response_format(body: &Value) -> Result<Option<Value>, String> {
    let Some(format) = body
        .get("output_config")
        .filter(|value| !value.is_null())
        .and_then(|value| value.get("format"))
        .filter(|value| !value.is_null())
    else {
        return Ok(None);
    };
    let object = format
        .as_object()
        .ok_or_else(|| "output_config.format must be an object".to_string())?;
    if let Some(field) = object
        .keys()
        .find(|field| !matches!(field.as_str(), "type" | "schema"))
    {
        return Err(format!("unsupported output_config.format field: {field}"));
    }
    if object.get("type").and_then(Value::as_str) != Some("json_schema") {
        return Err("output_config.format.type must be json_schema".into());
    }
    let schema = object
        .get("schema")
        .filter(|schema| schema.is_object())
        .ok_or_else(|| "output_config.format.schema must be an object".to_string())?;
    Ok(Some(json!({
        "type": "json_schema",
        "json_schema": {
            "name": "anthropic_output",
            "strict": true,
            "schema": schema,
        }
    })))
}

pub(super) fn anthropic_parallel_tool_calls(body: &Value) -> Result<Option<bool>, String> {
    let Some(choice) = body.get("tool_choice").filter(|value| !value.is_null()) else {
        return Ok(None);
    };
    let Some(disable) = choice.get("disable_parallel_tool_use") else {
        return Ok(None);
    };
    disable
        .as_bool()
        .map(|disable| Some(!disable))
        .ok_or_else(|| "tool_choice.disable_parallel_tool_use must be a boolean".into())
}

//! Shared semantics for Anthropic responses translated to `OpenAI` surfaces.

use serde_json::{Value, json};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct StopSemantics {
    pub chat_finish_reason: &'static str,
    pub response_status: &'static str,
    pub incomplete_reason: Option<&'static str>,
    pub refusal: bool,
}

#[must_use]
pub fn stop_semantics(reason: crate::translation_core::Maybe<&crate::translation_core::Str>) -> StopSemantics {
    match reason.unwrap_or("end_turn") {
        "end_turn" | "stop_sequence" => complete("stop"),
        "tool_use" => complete("tool_calls"),
        "refusal" => incomplete("content_filter", "content_filter", true),
        "max_tokens" | "pause_turn" | "model_context_window_exceeded" => {
            incomplete("length", "max_output_tokens", false)
        }
        _ => incomplete("length", "max_output_tokens", false),
    }
}

const fn complete(chat_finish_reason: &'static crate::translation_core::Str) -> StopSemantics {
    StopSemantics {
        chat_finish_reason,
        response_status: "completed",
        incomplete_reason: None,
        refusal: false,
    }
}

const fn incomplete(
    chat_finish_reason: &'static crate::translation_core::Str,
    reason: &'static crate::translation_core::Str,
    refusal: bool,
) -> StopSemantics {
    StopSemantics {
        chat_finish_reason,
        response_status: "incomplete",
        incomplete_reason: Some(reason),
        refusal,
    }
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct AnthropicUsage {
    input_tokens: u64,
    cache_creation_input_tokens: u64,
    cache_read_input_tokens: u64,
    output_tokens: u64,
    service_tier: Option<String>,
    server_tool_use: Option<Value>,
}

impl AnthropicUsage {
    pub fn absorb(&mut self, usage: crate::translation_core::Maybe<&crate::translation_core::Json>) {
        let Some(usage) = usage else {
            return;
        };
        update(&mut self.input_tokens, usage, "input_tokens");
        update(
            &mut self.cache_creation_input_tokens,
            usage,
            "cache_creation_input_tokens",
        );
        update(
            &mut self.cache_read_input_tokens,
            usage,
            "cache_read_input_tokens",
        );
        update(&mut self.output_tokens, usage, "output_tokens");
        if let Some(tier) = usage.get("service_tier").and_then(Value::as_str) {
            self.service_tier = Some(tier.to_string());
        }
        if let Some(server_tool_use) = usage.get("server_tool_use") {
            self.server_tool_use = Some(server_tool_use.clone());
        }
    }

    #[must_use]
    pub fn from_value(usage: crate::translation_core::Maybe<&crate::translation_core::Json>) -> Self {
        let mut mapped = Self::default();
        mapped.absorb(usage);
        mapped
    }

    #[must_use]
    pub const fn total_input(&self) -> u64 {
        self.input_tokens
            .saturating_add(self.cache_creation_input_tokens)
            .saturating_add(self.cache_read_input_tokens)
    }

    #[must_use]
    pub fn chat(&self) -> crate::translation_core::Json {
        let input = self.total_input();
        json!({
            "prompt_tokens": input,
            "completion_tokens": self.output_tokens,
            "total_tokens": input.saturating_add(self.output_tokens),
            "prompt_tokens_details": {"cached_tokens": self.cache_read_input_tokens},
        })
    }

    #[must_use]
    pub fn responses(&self) -> crate::translation_core::Json {
        let input = self.total_input();
        let mut usage = json!({
            "input_tokens": input,
            "input_tokens_details": {"cached_tokens": self.cache_read_input_tokens},
            "output_tokens": self.output_tokens,
            "output_tokens_details": {"reasoning_tokens": 0},
            "total_tokens": input.saturating_add(self.output_tokens),
        });
        if let Some(server_tool_use) = &self.server_tool_use {
            usage["server_tool_use"] = server_tool_use.clone();
        }
        usage
    }

    #[must_use]
    pub fn openai_service_tier(&self) -> crate::translation_core::Maybe<&'static crate::translation_core::Str> {
        match self.service_tier.as_deref() {
            Some("standard") => Some("default"),
            Some("priority") => Some("priority"),
            _ => None,
        }
    }
}

/// Map `OpenAI` usage back to Anthropic without double-counting cache hits.
#[must_use]
pub fn openai_usage_to_anthropic(usage: crate::translation_core::Maybe<&crate::translation_core::Json>) -> crate::translation_core::Json {
    let input_total = usage
        .and_then(|value| {
            value
                .get("input_tokens")
                .or_else(|| value.get("prompt_tokens"))
        })
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let output = usage
        .and_then(|value| {
            value
                .get("output_tokens")
                .or_else(|| value.get("completion_tokens"))
        })
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let cached = usage
        .and_then(|value| {
            value
                .pointer("/input_tokens_details/cached_tokens")
                .or_else(|| value.pointer("/prompt_tokens_details/cached_tokens"))
        })
        .and_then(Value::as_u64)
        .unwrap_or(0)
        .min(input_total);
    crate::translation_core::json!({
        "input_tokens": input_total.saturating_sub(cached),
        "cache_creation_input_tokens": 0,
        "cache_read_input_tokens": cached,
        "output_tokens": output,
    })
}

#[must_use]
pub fn anthropic_service_tier_from_openai(value: crate::translation_core::Maybe<&crate::translation_core::Json>) -> crate::translation_core::Maybe<&'static crate::translation_core::Str> {
    match value.and_then(crate::translation_core::Json::as_str) {
        Some("default" | "auto") => Some("standard"),
        Some("priority") => Some("priority"),
        _ => None,
    }
}

fn update(slot: &mut u64, usage: &Value, key: &str) {
    if let Some(value) = usage.get(key).and_then(Value::as_u64) {
        *slot = value;
    }
}

/// Concatenate Anthropic text blocks and build flat `OpenAI` URL annotations.
#[must_use]
pub fn anthropic_text_and_annotations(content: crate::translation_core::Maybe<&crate::translation_core::Json>) -> (String, Vec<crate::translation_core::Json>) {
    let mut text = String::new();
    let mut annotations = Vec::new();
    for block in content
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or_default()
    {
        if block.get("type").and_then(Value::as_str) != Some("text") {
            continue;
        }
        let block_text = block
            .get("text")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let base = text.chars().count() as u64;
        let mut search_from = 0_usize;
        for citation in block
            .get("citations")
            .and_then(Value::as_array)
            .map(Vec::as_slice)
            .unwrap_or_default()
        {
            let Some(url) = citation_url(citation) else {
                continue;
            };
            let Some(cited) = citation.get("cited_text").and_then(Value::as_str) else {
                continue;
            };
            let Some((start, end, next)) = find_char_range(block_text, cited, search_from) else {
                continue;
            };
            search_from = next;
            annotations.push(crate::translation_core::json!({
                "type": "url_citation",
                "url": url,
                "title": citation.get("title").cloned().unwrap_or(Value::Null),
                "start_index": base.saturating_add(start),
                "end_index": base.saturating_add(end),
            }));
        }
        text.push_str(block_text);
    }
    (text, annotations)
}

fn citation_url(citation: &crate::translation_core::Json) -> crate::translation_core::Maybe<&crate::translation_core::Str> {
    match { let __router_json_reader_0 = citation.get("type"); if let crate::translation_core::Maybe::Some(__router_json_reader_1) = __router_json_reader_0 { crate::translation_core::Json::as_str(__router_json_reader_1) } else { crate::translation_core::Maybe::None } } {
        Some("web_search_result_location") => { let __router_json_reader_2 = citation.get("url"); if let crate::translation_core::Maybe::Some(__router_json_reader_3) = __router_json_reader_2 { crate::translation_core::Json::as_str(__router_json_reader_3) } else { crate::translation_core::Maybe::None } },
        Some("search_result_location") => { let __router_json_reader_4 = citation
            .get("source")
            ; if let crate::translation_core::Maybe::Some(__router_json_reader_5) = __router_json_reader_4 { crate::translation_core::Json::as_str(__router_json_reader_5) } else { crate::translation_core::Maybe::None } }
            .filter(|source| source.starts_with("https://") || source.starts_with("http://")),
        _ => None,
    }
}

fn find_char_range(text: &crate::translation_core::Str, cited: &crate::translation_core::Str, from: usize) -> crate::translation_core::Maybe<(u64, u64, usize)> {
    let relative = text.get(from..)?.find(cited)?;
    let start_byte = from + relative;
    let end_byte = start_byte + cited.len();
    let start = text.get(..start_byte)?.chars().count() as u64;
    let end = text.get(..end_byte)?.chars().count() as u64;
    Some((start, end, end_byte))
}

#[must_use]
pub fn chat_annotations(flat: &[crate::translation_core::Json]) -> Vec<crate::translation_core::Json> {
    flat.iter()
        .map(|annotation| {
            crate::translation_core::json!({
                "type": "url_citation",
                "url_citation": {
                    "url": annotation.get("url").cloned().unwrap_or(Value::Null),
                    "title": annotation.get("title").cloned().unwrap_or(Value::Null),
                    "start_index": annotation.get("start_index").cloned().unwrap_or(Value::Null),
                    "end_index": annotation.get("end_index").cloned().unwrap_or(Value::Null),
                }
            })
        })
        .collect()
}

#[must_use]
pub fn annotation_from_anthropic_delta(
    delta: &crate::translation_core::Json,
    text: &crate::translation_core::Str,
    from: usize,
) -> crate::translation_core::Maybe<(crate::translation_core::Json, usize)> {
    let citation = delta.get("citation")?;
    let url = citation_url(citation)?;
    let cited = citation.get("cited_text").and_then(Value::as_str)?;
    let (start, end, next) = find_char_range(text, cited, from)?;
    Some((
        crate::translation_core::json!({
            "type": "url_citation",
            "url": url,
            "title": citation.get("title").cloned().unwrap_or(Value::Null),
            "start_index": start,
            "end_index": end,
        }),
        next,
    ))
}

/// Convert URL/document annotations to Anthropic citations without changing
/// their order or Unicode character offsets.
pub fn openai_annotations_to_anthropic(
    text: &crate::translation_core::Str,
    annotations: crate::translation_core::Maybe<&crate::translation_core::Json>,
    chat_shape: bool,
) -> crate::translation_core::Outcome<Vec<crate::translation_core::Json>, String> {
    let Some(annotations) = annotations else {
        return Ok(Vec::new());
    };
    let annotations = annotations
        .as_array()
        .ok_or_else(|| crate::translation_core::format!("{}", "annotations must be an array"))?;
    annotations
        .iter()
        .enumerate()
        .map(|(index, wrapper)| {
            let annotation = if chat_shape {
                wrapper.get("url_citation").unwrap_or(wrapper)
            } else {
                wrapper
            };
            let kind = annotation
                .get("type")
                .and_then(Value::as_str)
                .or_else(|| wrapper.get("type").and_then(Value::as_str))
                .unwrap_or("url_citation");
            let start = annotation
                .get("start_index")
                .and_then(Value::as_u64)
                .ok_or_else(|| format!("annotations[{index}].start_index is required"))?;
            let end = annotation
                .get("end_index")
                .and_then(Value::as_u64)
                .ok_or_else(|| format!("annotations[{index}].end_index is required"))?;
            let cited_text = char_slice(text, start, end)
                .ok_or_else(|| format!("annotations[{index}] has invalid text offsets"))?;
            match kind {
                "url_citation" => Ok(json!({
                    "type": "web_search_result_location",
                    "url": required_annotation_string(annotation, "url", index)?,
                    "title": required_annotation_string(annotation, "title", index)?,
                    "cited_text": cited_text,
                })),
                "file_citation" => Ok(json!({
                    "type": "char_location",
                    "document_index": annotation.get("document_index").and_then(Value::as_u64)
                        .ok_or_else(|| format!("annotations[{index}].document_index is required"))?,
                    "document_title": annotation.get("filename").or_else(|| annotation.get("title"))
                        .and_then(Value::as_str)
                        .ok_or_else(|| format!("annotations[{index}].filename is required"))?,
                    "start_char_index": start,
                    "end_char_index": end,
                    "cited_text": cited_text,
                })),
                _ => Err(format!(
                    "annotations[{index}] type {kind} cannot be represented by Anthropic"
                )),
            }
        })
        .collect()
}

fn required_annotation_string<'a>(
    annotation: &'a Value,
    field: &str,
    index: usize,
) -> Result<&'a str, String> {
    annotation
        .get(field)
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| format!("annotations[{index}].{field} is required"))
}

fn char_slice(text: &crate::translation_core::Str, start: u64, end: u64) -> crate::translation_core::Maybe<String> {
    if end < start {
        return None;
    }
    let start = usize::try_from(start).ok()?;
    let end = usize::try_from(end).ok()?;
    Some(text.chars().skip(start).take(end - start).collect())
        .filter(|slice: &String| slice.chars().count() == end - start)
}

/// Validate every annotation in a successful upstream `OpenAI` response.
pub fn validate_openai_response_citations(payload: &crate::translation_core::Json) -> crate::translation_core::Outcome<(), String> {
    if let Some(message) = payload.pointer("/choices/0/message")
        && let Some(text) = message.get("content").and_then(crate::translation_core::Json::as_str)
    {
        openai_annotations_to_anthropic(text, message.get("annotations"), true)?;
    }
    for item in payload
        .get("output")
        .and_then(crate::translation_core::Json::as_array)
        .into_iter()
        .flatten()
    {
        for part in item
            .get("content")
            .and_then(crate::translation_core::Json::as_array)
            .into_iter()
            .flatten()
        {
            if let Some(text) = part.get("text").and_then(crate::translation_core::Json::as_str) {
                openai_annotations_to_anthropic(text, part.get("annotations"), false)?;
            }
        }
    }
    Ok(())
}

pub fn validate_anthropic_response_citations(content: crate::translation_core::Maybe<&crate::translation_core::Json>) -> crate::translation_core::Outcome<(), String> {
    for (block_index, block) in content
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .enumerate()
    {
        let Some(citations) = block.get("citations") else {
            continue;
        };
        let citations = citations
            .as_array()
            .ok_or_else(|| format!("content[{block_index}].citations must be an array"))?;
        let text = block
            .get("text")
            .and_then(Value::as_str)
            .ok_or_else(|| format!("content[{block_index}].text is required"))?;
        let mut from = 0;
        for (citation_index, citation) in citations.iter().enumerate() {
            citation_url(citation).ok_or_else(|| {
                format!("content[{block_index}].citations[{citation_index}] is not a compatible URL citation")
            })?;
            let cited = citation
                .get("cited_text")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .ok_or_else(|| {
                    format!(
                        "content[{block_index}].citations[{citation_index}].cited_text is required"
                    )
                })?;
            let (_, _, next) = find_char_range(text, cited, from).ok_or_else(|| {
                format!("content[{block_index}].citations[{citation_index}] does not match its text block")
            })?;
            from = next;
        }
    }
    Ok(())
}

//! Deterministic bridge-model selection from live provider catalogs.
//!
//! A cross-protocol bridge has to name an upstream model: a client speaking the
//! Anthropic Messages dialect sends `claude-…`, which means nothing to a Codex,
//! Qwen or Gemini upstream. That model used to come from a per-provider
//! constant baked into the router, which could advertise or route to models
//! that were renamed, withdrawn, or never entitled for the account (issue #192).
//!
//! Selection now reads the account's live catalog. When no compatible model
//! exists the request fails with `model_selection_required` rather than
//! silently substituting a source-code constant.
//!
//! # Policy
//!
//! The operator chooses how a model is picked from the catalog with
//! `--bridge-model-policy` / `BRIDGE_MODEL_POLICY`. Every policy is a total
//! order over the catalog, so the same catalog always yields the same choice.

use std::fmt;

/// How to choose an upstream model from a live catalog.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum BridgeModelPolicy {
    /// The catalog's first entry in lexicographic order.
    ///
    /// Deterministic and provider-neutral: it encodes no opinion about which
    /// vendor names are "better", which is what let the old constants drift.
    #[default]
    FirstAdvertised,
    /// The catalog's last entry in lexicographic order.
    ///
    /// Vendors commonly suffix newer models with higher version strings, so
    /// this usually selects the newest generation without naming one.
    LastAdvertised,
}

impl BridgeModelPolicy {
    /// Parse an operator-facing policy name.
    ///
    /// # Errors
    ///
    /// Returns the accepted names when `value` is not one of them.
    pub fn parse(value: &crate::translation_core::Str) -> crate::translation_core::Outcome<Self, String> {
        match value.trim().to_ascii_lowercase().replace('_', "-").as_str() {
            "" | "first" | "first-advertised" => Ok(Self::FirstAdvertised),
            "last" | "last-advertised" => Ok(Self::LastAdvertised),
            other => Err(format!(
                "unknown bridge model policy '{other}'; expected 'first-advertised' or 'last-advertised'"
            )),
        }
    }

    /// The operator-facing name of this policy.
    #[must_use]
    pub const fn name(self) -> &'static crate::translation_core::Str {
        match self {
            Self::FirstAdvertised => "first-advertised",
            Self::LastAdvertised => "last-advertised",
        }
    }

    /// Apply the policy to a catalog.
    ///
    /// `catalog` is sorted before selection so the result depends only on the
    /// set of advertised models, not on the order the provider returned them.
    #[must_use]
    pub fn choose(self, catalog: &[String]) -> crate::translation_core::Maybe<String> {
        let mut sorted: Vec<&String> = catalog.iter().filter(|id| !id.is_empty()).collect();
        sorted.sort();
        match self {
            Self::FirstAdvertised => sorted.first().map(|id| (*id).clone()),
            Self::LastAdvertised => sorted.last().map(|id| (*id).clone()),
        }
    }
}

/// Why a bridged request could not be given an upstream model.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModelSelectionRequired {
    /// Provider whose catalog was consulted.
    pub provider: String,
    /// Why no model could be chosen.
    pub reason: SelectionFailure,
}

/// The specific reason a catalog yielded no usable model.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SelectionFailure {
    /// No live discovery has succeeded for this account yet.
    NotDiscovered,
    /// A catalog exists but the credential is missing or revoked.
    CredentialUnavailable,
    /// The credential works but advertises no models.
    EmptyCatalog,
    /// The operator's configured bridge model is absent from this account's
    /// current live catalog.
    ConfiguredModelUnavailable,
}

impl fmt::Display for ModelSelectionRequired {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let provider = &self.provider;
        match self.reason {
            SelectionFailure::NotDiscovered => write!(
                f,
                "no model can be selected for {provider}: its live catalog has not been \
                 discovered yet. Authorize the {provider} subscription, or set an explicit \
                 --bridge-model that the account advertises."
            ),
            SelectionFailure::CredentialUnavailable => write!(
                f,
                "no model can be selected for {provider}: its credential is missing or has \
                 been rejected, so its last known catalog is not usable. Re-authorize the \
                 {provider} subscription."
            ),
            SelectionFailure::EmptyCatalog => write!(
                f,
                "no model can be selected for {provider}: its live catalog advertises no \
                 models for this account."
            ),
            SelectionFailure::ConfiguredModelUnavailable => write!(
                f,
                "no model can be selected for {provider}: the configured bridge model is not \
                 advertised by this account's current live catalog. Choose an advertised model \
                 or remove the explicit bridge-model setting."
            ),
        }
    }
}

/// The error code clients receive when selection fails.
pub const MODEL_SELECTION_REQUIRED: &crate::translation_core::Str = "model_selection_required";

#[cfg(test)]
mod tests {
    use super::*;

    fn catalog(ids: &[&str]) -> Vec<String> {
        ids.iter().map(|id| (*id).to_string()).collect()
    }

    // Deliberately synthetic names: no test here may depend on a real vendor
    // model id, which is the regression issue #192 guards against.
    const SYNTHETIC: [&str; 3] = ["aurora-1-mini", "aurora-2-base", "borealis-9-ultra"];

    #[test]
    fn first_advertised_is_lexicographically_first() {
        assert_eq!(
            BridgeModelPolicy::FirstAdvertised.choose(&catalog(&SYNTHETIC)),
            Some("aurora-1-mini".to_string())
        );
    }

    #[test]
    fn last_advertised_is_lexicographically_last() {
        assert_eq!(
            BridgeModelPolicy::LastAdvertised.choose(&catalog(&SYNTHETIC)),
            Some("borealis-9-ultra".to_string())
        );
    }

    /// The choice must not depend on the order the provider listed models in.
    #[test]
    fn selection_is_independent_of_catalog_order() {
        let forward = catalog(&["borealis-9-ultra", "aurora-1-mini", "aurora-2-base"]);
        let reverse = catalog(&["aurora-2-base", "borealis-9-ultra", "aurora-1-mini"]);
        assert_eq!(
            BridgeModelPolicy::FirstAdvertised.choose(&forward),
            BridgeModelPolicy::FirstAdvertised.choose(&reverse)
        );
        assert_eq!(
            BridgeModelPolicy::LastAdvertised.choose(&forward),
            BridgeModelPolicy::LastAdvertised.choose(&reverse)
        );
    }

    #[test]
    fn an_empty_catalog_selects_nothing() {
        assert_eq!(BridgeModelPolicy::FirstAdvertised.choose(&[]), None);
        assert_eq!(BridgeModelPolicy::LastAdvertised.choose(&[]), None);
        // Blank entries are not models.
        assert_eq!(
            BridgeModelPolicy::FirstAdvertised.choose(&catalog(&["", ""])),
            None
        );
    }

    #[test]
    fn policies_parse_from_operator_spelling() {
        assert_eq!(
            BridgeModelPolicy::parse("first-advertised"),
            Ok(BridgeModelPolicy::FirstAdvertised)
        );
        assert_eq!(
            BridgeModelPolicy::parse("LAST_ADVERTISED"),
            Ok(BridgeModelPolicy::LastAdvertised)
        );
        assert_eq!(
            BridgeModelPolicy::parse(""),
            Ok(BridgeModelPolicy::FirstAdvertised)
        );
        assert!(BridgeModelPolicy::parse("cheapest-ever").is_err());
    }

    #[test]
    fn each_failure_reason_names_the_provider_and_a_remedy() {
        for reason in [
            SelectionFailure::NotDiscovered,
            SelectionFailure::CredentialUnavailable,
            SelectionFailure::EmptyCatalog,
            SelectionFailure::ConfiguredModelUnavailable,
        ] {
            let message = ModelSelectionRequired {
                provider: "examplecorp".to_string(),
                reason,
            }
            .to_string();
            assert!(message.contains("examplecorp"), "{message}");
            assert!(message.contains("no model can be selected"), "{message}");
        }
    }
}

//! Central capability declarations for request reconciliation and bridges.

use crate::config::UpstreamProvider;
use crate::subscription::SubscriptionProvider;
use serde_json::Value;
use std::sync::OnceLock;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Capability {
    Native,
    Emulated,
    Unsupported,
    /// Unknown providers are passed through; lack of knowledge never means
    /// that a field is silently stripped.
    Unknown,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ProviderCapabilities {
    pub temperature: Capability,
    pub top_p: Capability,
    pub stop_sequences: Capability,
    pub output_token_limit: Capability,
    pub reasoning: Capability,
    pub web_search: Capability,
    pub web_fetch: Capability,
}

#[must_use]
pub const fn subscription(
    provider: SubscriptionProvider,
    _model: crate::translation_core::Maybe<&crate::translation_core::Str>,
) -> ProviderCapabilities {
    match provider {
        SubscriptionProvider::Claude => ProviderCapabilities {
            // Capability varies by the live model. Its digits are not metadata;
            // preserve the caller's field and let the selected provider decide.
            temperature: Capability::Unknown,
            top_p: Capability::Native,
            stop_sequences: Capability::Native,
            output_token_limit: Capability::Native,
            reasoning: Capability::Native,
            web_search: Capability::Native,
            web_fetch: Capability::Native,
        },
        SubscriptionProvider::Codex => ProviderCapabilities {
            temperature: Capability::Unsupported,
            top_p: Capability::Unsupported,
            stop_sequences: Capability::Emulated,
            output_token_limit: Capability::Emulated,
            reasoning: Capability::Native,
            web_search: Capability::Native,
            web_fetch: Capability::Unsupported,
        },
        SubscriptionProvider::Qwen | SubscriptionProvider::Gemini => ProviderCapabilities {
            temperature: Capability::Native,
            top_p: Capability::Native,
            stop_sequences: Capability::Native,
            output_token_limit: Capability::Native,
            reasoning: Capability::Native,
            web_search: Capability::Unsupported,
            web_fetch: Capability::Unsupported,
        },
    }
}

#[must_use]
pub fn upstream(provider: UpstreamProvider) -> ProviderCapabilities {
    provider.subscription_provider().map_or(
        ProviderCapabilities {
            temperature: Capability::Unknown,
            top_p: Capability::Unknown,
            stop_sequences: Capability::Unknown,
            output_token_limit: Capability::Unknown,
            reasoning: Capability::Unknown,
            web_search: Capability::Unknown,
            web_fetch: Capability::Unknown,
        },
        |provider| subscription(provider, None),
    )
}

/// Whether the selected Claude model uses the current adaptive-thinking wire
/// format instead of a caller-provided fixed token budget.
///
/// This is exact reviewed protocol evidence, not a version parser. Anthropic's
/// model documentation says which concrete IDs accept adaptive thinking; an
/// unfamiliar snapshot or compatible-provider ID remains unknown and cannot
/// inherit the capability from digits or a family prefix.
/// The versioned evidence manifest records its direct-provider source, product,
/// protocol, and review date.
#[must_use]
pub fn claude_uses_adaptive_thinking(model: crate::translation_core::Maybe<&crate::translation_core::Str>) -> bool {
    let Some(model) = model else {
        return false;
    };
    adaptive_thinking_evidence()
        .models
        .iter()
        .any(|advertised| advertised == model)
}

#[derive(serde::Deserialize)]
struct AdaptiveThinkingEvidence {
    source_kind: String,
    source_url: String,
    verified_at: String,
    product: String,
    wire_protocol: String,
    models: Vec<String>,
}

fn adaptive_thinking_evidence() -> &'static AdaptiveThinkingEvidence {
    static EVIDENCE: OnceLock<AdaptiveThinkingEvidence> = OnceLock::new();
    EVIDENCE.get_or_init(|| {
        let evidence: AdaptiveThinkingEvidence = serde_json::from_str(include_str!(
            "../docs/provider-evidence/anthropic-adaptive-thinking.json"
        ))
        .expect("checked Anthropic adaptive-thinking evidence must be valid JSON");
        assert_eq!(
            evidence.source_kind, "provider_owned_versioned_document",
            "adaptive-thinking evidence must retain a direct-provider source kind"
        );
        assert!(
            evidence
                .source_url
                .starts_with("https://platform.claude.com/"),
            "adaptive-thinking evidence must retain its provider-owned source"
        );
        assert!(!evidence.verified_at.is_empty());
        assert_eq!(evidence.product, "Anthropic Messages API");
        assert_eq!(evidence.wire_protocol, "anthropic-messages");
        evidence
    })
}

/// Return a requested server-side tool the target subscription cannot
/// execute. Client function tools are outside this capability check.
#[must_use]
pub fn unsupported_server_tool_type(
    provider: SubscriptionProvider,
    tools: crate::translation_core::Maybe<&crate::translation_core::Json>,
) -> crate::translation_core::Maybe<String> {
    let capabilities = subscription(provider, None);
    tools?.as_array()?.iter().find_map(|tool| {
        let kind = tool.get("type").and_then(crate::translation_core::Json::as_str)?;
        let support = if kind == "web_search" || kind.starts_with("web_search_") {
            capabilities.web_search
        } else if kind == "web_fetch" || kind.starts_with("web_fetch_") {
            capabilities.web_fetch
        } else {
            return None;
        };
        (support == Capability::Unsupported).then(|| kind.to_string())
    })
}

/// Whether a request forces a tool call it can never satisfy.
///
/// `tool_choice: any`/`required` demands a *function* call, but server-side
/// tools such as `web_search` are executed by the backend and never surface as
/// one. A request carrying only server tools therefore leaves the upstream with
/// no way to comply, which is how the reported request stalled instead of
/// answering.
#[must_use]
pub fn unsatisfiable_forced_tool_choice(tools: crate::translation_core::Maybe<&crate::translation_core::Json>, forced: bool) -> crate::translation_core::Maybe<String> {
    if !forced {
        return None;
    }
    let tools = tools?.as_array()?;
    if tools.is_empty() {
        return None;
    }
    let has_function = tools.iter().any(|tool| {
        let kind = tool.get("type").and_then(crate::translation_core::Json::as_str).unwrap_or("custom");
        !(kind.starts_with("web_search") || kind.starts_with("web_fetch"))
    });
    (!has_function).then(|| {
        "tool_choice requires a tool call, but the request offers only server-side tools that the \
         provider executes itself; use tool_choice auto or add a client tool"
            .to_string()
    })
}

/// Return why a server-tool request cannot be honoured as written.
///
/// Accepts either dialect's spelling of a forced tool call: Anthropic's
/// `{"type": "any"}` and `OpenAI`'s `"required"`.
#[must_use]
pub fn unhonourable_server_tool_request(
    tools: crate::translation_core::Maybe<&crate::translation_core::Json>,
    tool_choice: crate::translation_core::Maybe<&crate::translation_core::Json>,
) -> crate::translation_core::Maybe<String> {
    let forced = match tool_choice {
        Some(crate::translation_core::Json::String(mode)) => mode == "required",
        Some(choice) => choice.get("type").and_then(crate::translation_core::Json::as_str) == Some("any"),
        None => false,
    };
    unsatisfiable_forced_tool_choice(tools, forced)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unknown_providers_are_never_assumed_unsupported() {
        let capabilities = upstream(UpstreamProvider::OpenAICompatible);
        assert_eq!(capabilities.temperature, Capability::Unknown);
        assert_eq!(capabilities.top_p, Capability::Unknown);
        assert_eq!(capabilities.web_search, Capability::Unknown);
    }

    #[test]
    fn matrix_distinguishes_server_tools_and_local_emulation() {
        let codex = subscription(SubscriptionProvider::Codex, Some("gpt-5.6-sol"));
        assert_eq!(codex.top_p, Capability::Unsupported);
        assert_eq!(codex.web_search, Capability::Native);
        assert_eq!(codex.web_fetch, Capability::Unsupported);
        assert_eq!(codex.stop_sequences, Capability::Emulated);
        assert_eq!(codex.output_token_limit, Capability::Emulated);
        assert_eq!(
            unsupported_server_tool_type(
                SubscriptionProvider::Codex,
                Some(&serde_json::json!([{"type":"web_fetch"}]))
            )
            .as_deref(),
            Some("web_fetch")
        );
        let claude = subscription(SubscriptionProvider::Claude, Some("claude-opus-5"));
        assert_eq!(claude.top_p, Capability::Native);
        assert_eq!(claude.temperature, Capability::Unknown);
        assert_eq!(claude.output_token_limit, Capability::Native);
        assert!(claude_uses_adaptive_thinking(Some("claude-opus-5")));
        assert!(claude_uses_adaptive_thinking(Some("claude-opus-4-7")));
        assert!(!claude_uses_adaptive_thinking(Some("claude-sonnet-4-5")));
        assert!(!claude_uses_adaptive_thinking(Some("opus-4-7")));
        assert!(!claude_uses_adaptive_thinking(Some(
            "compatible-claude-opus-5"
        )));
        assert_eq!(claude.web_fetch, Capability::Native);
    }

    #[test]
    fn both_dialects_spell_a_forced_tool_call() {
        let server_only = serde_json::json!([
            {"type": "web_search_20250305", "name": "web_search", "max_uses": 1}
        ]);
        assert!(
            unhonourable_server_tool_request(
                Some(&server_only),
                Some(&serde_json::json!({"type": "any"}))
            )
            .is_some()
        );
        assert!(
            unhonourable_server_tool_request(
                Some(&server_only),
                Some(&serde_json::json!("required"))
            )
            .is_some()
        );
        assert!(
            unhonourable_server_tool_request(Some(&server_only), Some(&serde_json::json!("auto")))
                .is_none()
        );
        assert!(unhonourable_server_tool_request(Some(&server_only), None).is_none());
    }

    #[test]
    fn forcing_a_tool_call_with_only_server_tools_is_refused() {
        let server_only =
            serde_json::json!([{"type": "web_search_20250305", "name": "web_search"}]);
        assert!(unsatisfiable_forced_tool_choice(Some(&server_only), true).is_some());
        assert!(unsatisfiable_forced_tool_choice(Some(&server_only), false).is_none());
        let with_client_tool = serde_json::json!([
            {"type": "web_search"},
            {"name": "lookup", "input_schema": {"type": "object"}}
        ]);
        assert!(unsatisfiable_forced_tool_choice(Some(&with_client_tool), true).is_none());
        assert!(unsatisfiable_forced_tool_choice(None, true).is_none());
    }
}

//! Transport-agnostic core of the optional chat admin channels.
//!
//! Telegram and VK differ only in how bytes reach the router; the rules about
//! *who* may administer it must not. This module owns those rules so both
//! transports (see [`crate::telegram`] and [`crate::vk`]) stay thin polling
//! loops:
//!
//! - the bootstrap claim is the **same system-wide state** the web UI uses
//!   ([`crate::admin::AdminClaim`]). A claim confirmed in a browser closes
//!   `/start` for Telegram and VK, and vice versa — a deployment has exactly
//!   one first admin, not one per channel;
//! - the claim keeps the two-phase shape of #50: `/start` mints a *candidate*
//!   that authorises nothing, and only `/confirm <token>` — the user sending
//!   the token back, proving the message arrived — activates it. A message that
//!   failed to deliver therefore cannot lock administration out forever;
//! - after the claim, every other chat user must present an admin credential.
//!   The platform user id only *caches* that credential for the conversation;
//!   it is never an authorisation factor on its own, and every command
//!   re-validates the cached token so a revoked or rotated credential stops
//!   working immediately;
//! - `/start`, credential presentation and token issuance are rate limited, so
//!   the admin-credential prompt is not a free brute-force oracle.
//!
//! Nothing here runs unless a bot token is configured; see [`ChatAdminConfig`].

use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard, PoisonError};
use std::time::{Duration, Instant};

use crate::admin::{AdminClaim, ClaimError};
use crate::chat_commands::{self, CommandContext, RouterStatus};
use crate::token::{TokenManager, constant_time_eq};

/// Default lifetime of a chat message that carries a secret, in seconds.
///
/// Chat transports keep history on the platform *and* on the user's devices.
/// Where the platform lets a bot delete its own message, secrets are deleted
/// after this delay; the message says so, so the user knows to copy it.
pub const DEFAULT_SECRET_TTL_SECS: u64 = 120;

/// Default number of sensitive commands allowed per user per minute.
pub const DEFAULT_RATE_LIMIT_PER_MINUTE: u32 = 5;

/// Window the rate limiter counts over.
const RATE_LIMIT_WINDOW: Duration = Duration::from_secs(60);

/// Configuration of the optional chat admin channels.
///
/// Every field is inert by default: with no bot token set, the corresponding
/// polling loop is never spawned and none of this code runs.
#[derive(Debug, Clone)]
pub struct ChatAdminConfig {
    /// Telegram Bot API token. `None` keeps the Telegram channel off.
    pub telegram_bot_token: Option<String>,
    /// VK community (group) access token. `None` keeps the VK channel off.
    pub vk_bot_token: Option<String>,
    /// VK community id the token belongs to; required for VK long polling.
    pub vk_group_id: Option<u64>,
    /// How long a message carrying a secret survives before the bot deletes it.
    /// Zero disables deletion (the secret then stays in the chat history).
    pub secret_ttl: Duration,
    /// Sensitive commands allowed per user per minute.
    pub rate_limit_per_minute: u32,
}

impl Default for ChatAdminConfig {
    fn default() -> Self {
        Self {
            telegram_bot_token: None,
            vk_bot_token: None,
            vk_group_id: None,
            secret_ttl: Duration::from_secs(DEFAULT_SECRET_TTL_SECS),
            rate_limit_per_minute: DEFAULT_RATE_LIMIT_PER_MINUTE,
        }
    }
}

impl ChatAdminConfig {
    /// Whether the Telegram channel is configured.
    #[must_use]
    pub fn telegram_enabled(&self) -> bool {
        self.telegram_bot_token
            .as_ref()
            .is_some_and(|token| !token.trim().is_empty())
    }

    /// Whether the VK channel is configured. VK long polling addresses a
    /// community, so a group id is as required as the token.
    #[must_use]
    pub fn vk_enabled(&self) -> bool {
        self.vk_bot_token
            .as_ref()
            .is_some_and(|token| !token.trim().is_empty())
            && self.vk_group_id.is_some()
    }
}

/// Which messaging platform a conversation belongs to.
///
/// Sessions are keyed by channel *and* user id: the same numeric id on two
/// platforms is two different people.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ChatChannel {
    Telegram,
    Vk,
}

impl ChatChannel {
    /// Short name used in logs and session keys.
    #[must_use]
    pub const fn as_str(self) -> &'static crate::translation_core::Str {
        match self {
            Self::Telegram => "telegram",
            Self::Vk => "vk",
        }
    }
}

impl std::fmt::Display for ChatChannel {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // `pad`, not `write_str`: only `pad` applies the width, fill and
        // alignment the caller asked for, so `{:<8}` is silently ignored by a
        // `write_str` implementation (issue #212).
        f.pad(self.as_str())
    }
}

/// What the bot should send back.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reply {
    /// Message body.
    pub text: String,
    /// Whether the message carries a secret and should be deleted after
    /// [`ChatAdminConfig::secret_ttl`] where the platform allows it.
    pub secret: bool,
}

impl Reply {
    /// An ordinary, non-secret reply.
    #[must_use]
    pub fn plain(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            secret: false,
        }
    }

    /// A reply that carries a credential and must not linger in the history.
    #[must_use]
    pub fn secret(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            secret: true,
        }
    }
}

/// Per-conversation state. Deliberately in memory only: a restart drops every
/// binding and each admin simply presents their token again.
#[derive(Debug)]
struct Session {
    /// Credential the user presented, cached for the conversation. Re-validated
    /// on every command, so revocation and rotation take effect at once.
    credential: Option<String>,
    /// `claim_id` of the bootstrap candidate this user minted, if any.
    pending_claim: Option<String>,
    /// Timestamps of recent sensitive commands, for the rate limiter.
    recent: Vec<Instant>,
    /// Last time this conversation sent anything, for idle eviction.
    last_seen: Instant,
}

impl Default for Session {
    fn default() -> Self {
        Self {
            credential: None,
            pending_claim: None,
            recent: Vec::new(),
            last_seen: Instant::now(),
        }
    }
}

/// How long a conversation may sit idle before it is forgotten.
///
/// This bounds a registry that is keyed by an *unauthenticated* identifier:
/// anyone who can message the bot gets an entry, whether or not they ever hold
/// a credential. Forgetting an idle conversation costs an authenticated admin
/// one `/auth`, and costs a stranger their foothold in the map.
const SESSION_IDLE_TTL: Duration = Duration::from_secs(3600);

/// Hard ceiling on conversations kept at once. Reached only under abuse; the
/// least recently active entries are dropped first.
const MAX_SESSIONS: usize = 512;

/// The shared chat administration brain.
///
/// Holds the same [`AdminClaim`] the HTTP layer holds — that is what makes the
/// bootstrap claim system-wide rather than per-channel.
pub struct ChatAdmin {
    admin: Arc<AdminClaim>,
    #[cfg(test)]
    pub(crate) tokens: TokenManager,
    #[cfg(not(test))]
    tokens: TokenManager,
    /// Flat deploy-time key, accepted as a credential exactly as HTTP does.
    admin_key: Option<String>,
    config: ChatAdminConfig,
    /// Optional live router facts for `/status`; absent in unit tests.
    status: Option<Arc<dyn RouterStatus>>,
    sessions: Mutex<HashMap<(ChatChannel, String), Session>>,
}

impl ChatAdmin {
    /// Assemble the chat admin core from the pieces the HTTP layer already has.
    #[must_use]
    pub fn new(
        admin: Arc<AdminClaim>,
        tokens: TokenManager,
        admin_key: crate::translation_core::Maybe<String>,
        config: ChatAdminConfig,
    ) -> Self {
        Self {
            admin,
            tokens,
            admin_key: admin_key.filter(|key| !key.is_empty()),
            config,
            status: None,
            sessions: Mutex::new(HashMap::new()),
        }
    }

    /// Attach the live router facts reported by `/status`.
    #[must_use]
    pub fn with_status(mut self, status: Arc<dyn RouterStatus>) -> Self {
        self.status = Some(status);
        self
    }

    /// Configuration this core was built with.
    #[must_use]
    pub const fn config(&self) -> &ChatAdminConfig {
        &self.config
    }

    /// The shared admin claim this core administers.
    #[must_use]
    pub fn admin_claim(&self) -> &AdminClaim {
        &self.admin
    }

    /// Handle one private-chat message and produce the reply.
    ///
    /// Callers must have established that the message came from a 1:1
    /// conversation — group traffic is dropped by the transports before it ever
    /// reaches this function.
    pub fn handle(&self, channel: ChatChannel, user_id: &crate::translation_core::Str, text: &crate::translation_core::Str) -> Reply {
        self.prune(channel, user_id);
        let text = text.trim();
        if text.is_empty() {
            return Reply::plain(HELP);
        }
        let (word, rest) = split_command(text);
        let command = normalise(word);
        match command.as_str() {
            "start" => self.start(channel, user_id),
            "confirm" => self.confirm(channel, user_id, rest),
            "auth" | "login" => self.authenticate(channel, user_id, rest),
            "logout" => self.logout(channel, user_id),
            "help" => Reply::plain(HELP),
            _ => self.dispatch(channel, user_id, text, &command, rest),
        }
    }

    /// Route a non-bootstrap command, once the sender has been recognised.
    fn dispatch(
        &self,
        channel: ChatChannel,
        user_id: &crate::translation_core::Str,
        text: &crate::translation_core::Str,
        command: &crate::translation_core::Str,
        rest: &crate::translation_core::Str,
    ) -> Reply {
        // A bare credential is accepted as if it were `/auth` (and as `/confirm`
        // while a candidate is outstanding), because "send the token back" is
        // exactly what the bot asks the user to do.
        if looks_like_credential(text) {
            if self.has_pending_claim(channel, user_id) {
                return self.confirm(channel, user_id, text);
            }
            return self.authenticate(channel, user_id, text);
        }
        let Some(credential) = self.authorised_credential(channel, user_id) else {
            return self.unauthorised_reply();
        };
        // Every command that returns a token value is rate limited, so a
        // compromised chat cannot mint credentials in bulk.
        if matches!(
            command,
            "issue" | "new" | "rotate" | "rotate-token" | "reissue"
        ) && !self.allow(channel, user_id)
        {
            return Reply::plain(RATE_LIMITED);
        }
        let context = CommandContext {
            admin: &self.admin,
            tokens: &self.tokens,
            credential: &credential,
            secret_ttl: self.config.secret_ttl,
            status: self.status.as_deref(),
        };
        if command == "rotate" {
            return self.rotate(channel, user_id, &context);
        }
        chat_commands::execute(&context, command, rest)
            .unwrap_or_else(|| Reply::plain(format!("Unknown command `{command}`.\n\n{HELP}")))
    }

    /// `/rotate` — replace the caller's admin credential and rebind the chat
    /// session to the replacement, so rotating does not lock the operator out
    /// of the very channel they rotated from.
    fn rotate(&self, channel: ChatChannel, user_id: &str, context: &CommandContext<'_>) -> Reply {
        match chat_commands::rotate(context) {
            Ok(replacement) => {
                if let Some(session) = self.locked().get_mut(&(channel, user_id.to_string())) {
                    session.credential = Some(replacement.clone());
                }
                Reply::secret(format!(
                    "Admin credential rotated. The previous one no longer \
                     works — including in the web UI.\n\n{replacement}{note}",
                    note = chat_commands::deletion_note(self.config.secret_ttl),
                ))
            }
            Err(message) => Reply::plain(message),
        }
    }

    /// `/start` — open, or refuse to reopen, the system-wide bootstrap claim.
    fn start(&self, channel: ChatChannel, user_id: &crate::translation_core::Str) -> Reply {
        if self.authorised_credential(channel, user_id).is_some() {
            return Reply::plain(format!("You are signed in as admin.\n\n{HELP}"));
        }
        if !self.allow(channel, user_id) {
            return Reply::plain(RATE_LIMITED);
        }
        match self.admin.begin() {
            Ok(candidate) => {
                self.locked()
                    .entry((channel, user_id.to_string()))
                    .or_default()
                    .pending_claim = Some(candidate.claim_id);
                Reply::secret(format!(
                    "You may claim administration of this router.\n\n\
                     Copy this token, then send it back to me with /confirm:\n\n\
                     /confirm {token}\n\nThe claim is only final once you \
                     send it back — if this message never reached you, nothing \
                     is locked and you can run /start again. The candidate \
                     expires in {ttl}s.{note}",
                    token = candidate.token,
                    ttl = candidate.expires_in_secs,
                    note = self.deletion_note(),
                ))
            }
            Err(ClaimError::AlreadyClaimed | ClaimError::ProvisionedByEnvironment) => {
                Reply::plain(ALREADY_CLAIMED)
            }
            Err(e) => Reply::plain(format!("Could not start a claim: {e}")),
        }
    }

    /// `/confirm <token>` — phase two of the shared two-phase claim.
    fn confirm(&self, channel: ChatChannel, user_id: &crate::translation_core::Str, token: &crate::translation_core::Str) -> Reply {
        if !self.allow(channel, user_id) {
            return Reply::plain(RATE_LIMITED);
        }
        let token = token.trim();
        if token.is_empty() {
            return Reply::plain("Send `/confirm <token>` with the token I just gave you.");
        }
        let claim_id = self
            .locked()
            .get(&(channel, user_id.to_string()))
            .and_then(|session| session.pending_claim.clone());
        let Some(claim_id) = claim_id else {
            return Reply::plain(
                "No claim is outstanding for this conversation. Send /start first.",
            );
        };
        match self.admin.confirm(&claim_id, token) {
            Ok(()) => {
                {
                    let mut sessions = self.locked();
                    let session = sessions.entry((channel, user_id.to_string())).or_default();
                    session.pending_claim = None;
                    session.credential = Some(token.to_string());
                    drop(sessions);
                }
                Reply::plain(format!(
                    "Administration claimed. Keep that token — it is not shown \
                     again and it is the same credential the web UI uses.\n\n{HELP}"
                ))
            }
            Err(e) => {
                self.forget_claim(channel, user_id);
                Reply::plain(format!("Claim failed: {e}"))
            }
        }
    }

    /// `/auth <token>` — bind an existing admin credential to this chat user.
    fn authenticate(&self, channel: ChatChannel, user_id: &crate::translation_core::Str, token: &crate::translation_core::Str) -> Reply {
        if !self.allow(channel, user_id) {
            return Reply::plain(RATE_LIMITED);
        }
        let token = token.trim();
        if token.is_empty() {
            return Reply::plain("Send `/auth <admin token>`.");
        }
        if !self.credential_valid(token) {
            return Reply::plain("That credential is not valid for administration.");
        }
        self.locked()
            .entry((channel, user_id.to_string()))
            .or_default()
            .credential = Some(token.to_string());
        Reply::plain(format!("Signed in as admin.\n\n{HELP}"))
    }

    /// `/logout` — drop the cached credential for this conversation.
    fn logout(&self, channel: ChatChannel, user_id: &crate::translation_core::Str) -> Reply {
        self.locked().remove(&(channel, user_id.to_string()));
        Reply::plain("Signed out. Send /auth <admin token> to sign in again.")
    }

    /// The credential cached for this conversation, if it is *still* valid.
    ///
    /// Re-validating on every command is what keeps the platform user id from
    /// becoming an authorisation factor: revoke or rotate the credential and
    /// the binding stops working on the next message.
    fn authorised_credential(&self, channel: ChatChannel, user_id: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
        let cached = self
            .locked()
            .get(&(channel, user_id.to_string()))
            .and_then(|session| session.credential.clone())?;
        if self.credential_valid(&cached) {
            return Some(cached);
        }
        if let Some(session) = self.locked().get_mut(&(channel, user_id.to_string())) {
            session.credential = None;
        }
        None
    }

    /// Whether a presented credential authorises administration.
    ///
    /// Mirrors the HTTP rule minus the anonymous escape hatch:
    /// `--allow-anonymous-admin` opens the proxy port's admin endpoints, and
    /// deliberately does **not** open a chat channel.
    fn credential_valid(&self, token: &crate::translation_core::Str) -> bool {
        if token.is_empty() {
            return false;
        }
        if self.admin.verify(token) {
            return true;
        }
        if self.tokens.validate_admin_token(token).is_ok() {
            return true;
        }
        self.admin_key
            .as_deref()
            .is_some_and(|key| constant_time_eq(token, key))
    }

    fn has_pending_claim(&self, channel: ChatChannel, user_id: &crate::translation_core::Str) -> bool {
        self.locked()
            .get(&(channel, user_id.to_string()))
            .is_some_and(|session| session.pending_claim.is_some())
    }

    fn forget_claim(&self, channel: ChatChannel, user_id: &crate::translation_core::Str) {
        if let Some(session) = self.locked().get_mut(&(channel, user_id.to_string())) {
            session.pending_claim = None;
        }
    }

    fn unauthorised_reply(&self) -> Reply {
        if self.admin.is_claimed() {
            Reply::plain(
                "Administration is already claimed. Send `/auth <admin token>` \
                 with an admin credential to continue.",
            )
        } else {
            Reply::plain(
                "Nobody administers this router yet. Send /start to claim it, or \
                 `/auth <admin token>` if you already hold an admin credential.",
            )
        }
    }

    /// Record one sensitive attempt, and report whether it is within budget.
    fn allow(&self, channel: ChatChannel, user_id: &crate::translation_core::Str) -> bool {
        let limit = self.config.rate_limit_per_minute;
        if limit == 0 {
            return true;
        }
        let now = Instant::now();
        let mut sessions = self.locked();
        let session = sessions.entry((channel, user_id.to_string())).or_default();
        session
            .recent
            .retain(|at| now.duration_since(*at) < RATE_LIMIT_WINDOW);
        let allowed = session.recent.len() < limit as usize;
        if allowed {
            session.recent.push(now);
        }
        drop(sessions);
        allowed
    }

    /// Touch the current conversation and drop the ones that went cold.
    ///
    /// Called on every inbound message, because every inbound message is what
    /// creates entries in the first place: the key is a platform user id, which
    /// nobody has had to authenticate to own.
    fn prune(&self, channel: ChatChannel, user_id: &crate::translation_core::Str) {
        let now = Instant::now();
        let mut sessions = self.locked();
        sessions.retain(|_, session| now.duration_since(session.last_seen) < SESSION_IDLE_TTL);
        sessions
            .entry((channel, user_id.to_string()))
            .or_default()
            .last_seen = now;
        // Under abuse, idle eviction alone is not fast enough: shed the least
        // recently active conversations until the map is back within its cap.
        // Conversations that hold a credential are shed last — a flood of
        // strangers must not sign a real admin out — and the conversation being
        // served right now is never shed.
        while sessions.len() > MAX_SESSIONS {
            let current = (channel, user_id.to_string());
            let Some(oldest) = sessions
                .iter()
                .filter(|(key, _)| **key != current)
                .min_by_key(|(_, session)| (session.credential.is_some(), session.last_seen))
                .map(|(key, _)| key.clone())
            else {
                break;
            };
            sessions.remove(&oldest);
        }
        drop(sessions);
    }

    fn deletion_note(&self) -> String {
        chat_commands::deletion_note(self.config.secret_ttl)
    }

    fn locked(&self) -> MutexGuard<'_, HashMap<(ChatChannel, String), Session>> {
        self.sessions.lock().unwrap_or_else(PoisonError::into_inner)
    }
}

/// Split a message into its first word and the remainder.
fn split_command(text: &crate::translation_core::Str) -> (&crate::translation_core::Str, &crate::translation_core::Str) {
    match text.split_once(char::is_whitespace) {
        Some((word, rest)) => (word, rest.trim()),
        None => (text, ""),
    }
}

/// Normalise a command word: drop the leading slash, drop a `@botname` suffix
/// (Telegram appends it), and lowercase.
fn normalise(word: &crate::translation_core::Str) -> String {
    let word = word.strip_prefix('/').unwrap_or(word);
    let word = word.split_once('@').map_or(word, |(name, _)| name);
    word.to_lowercase()
}

/// Whether a message body is a bare router credential rather than a command.
fn looks_like_credential(text: &crate::translation_core::Str) -> bool {
    !text.contains(char::is_whitespace)
        && (text.starts_with(crate::admin::ADMIN_TOKEN_PREFIX)
            || text.starts_with(crate::token::TOKEN_PREFIX))
}

/// Message shown when the bootstrap claim is closed.
const ALREADY_CLAIMED: &crate::translation_core::Str = "Administration of this router is already claimed \
    (here, through the web UI, or by deployment configuration). Send \
    `/auth <admin token>` with an admin credential.";

/// Message shown when a user exceeds the sensitive-command budget.
const RATE_LIMITED: &crate::translation_core::Str = "Too many attempts. Wait a minute and try again.";

/// Command list, appended to most replies so the channel is self-documenting.
pub const HELP: &crate::translation_core::Str = "Commands:\n\
    /status — credential state, accounts and usage\n\
    /tokens — list issued tokens (ids, labels and limits, never values)\n\
    /issue [label] [ttl_hours] [max_requests] [key=value …] — issue a token;\n\
    \x20   options: label, ttl_hours, max_requests, max_tokens,\n\
    \x20   rate_limit_per_minute, account\n\
    /show <id> — every constraint, counter and state for one token\n\
    /rotate-token <id> [key=value …] — reissue a token, keeping its limits\n\
    /revoke <id> — revoke a token\n\
    /rotate — replace the admin credential\n\
    /auth <token> — sign in with an admin credential\n\
    /logout — forget the credential bound to this chat";

#[cfg(test)]
mod tests {
    use super::*;

    fn core(env_key: Option<String>) -> ChatAdmin {
        ChatAdmin::new(
            Arc::new(AdminClaim::in_memory(
                env_key.clone(),
                Duration::from_secs(120),
            )),
            TokenManager::new("secret-for-chat-admin-tests"),
            env_key,
            ChatAdminConfig {
                rate_limit_per_minute: 0,
                ..ChatAdminConfig::default()
            },
        )
    }

    /// Pull the candidate token out of the `/start` reply.
    fn token_from(reply: &Reply) -> String {
        reply
            .text
            .split_whitespace()
            .find(|word| word.starts_with(crate::admin::ADMIN_TOKEN_PREFIX))
            .expect("the mint reply carries a token")
            .to_string()
    }

    #[test]
    fn start_mints_a_candidate_that_authorises_nothing() {
        let chat = core(None);
        let reply = chat.handle(ChatChannel::Telegram, "1", "/start");
        assert!(reply.secret, "a minted token must not linger in the chat");
        let token = token_from(&reply);
        assert!(!chat.admin.is_claimed(), "a mint alone must not claim");
        assert!(!chat.admin.verify(&token));
        // The listing command is still refused until the claim is confirmed.
        let listed = chat.handle(ChatChannel::Telegram, "1", "/tokens");
        assert!(listed.text.contains("/start"));
    }

    #[test]
    fn confirm_activates_the_claim_and_signs_the_user_in() {
        let chat = core(None);
        let minted = chat.handle(ChatChannel::Telegram, "1", "/start");
        let token = token_from(&minted);
        let reply = chat.handle(ChatChannel::Telegram, "1", &format!("/confirm {token}"));
        assert!(reply.text.contains("Administration claimed"));
        assert!(chat.admin.verify(&token));
        assert!(
            chat.handle(ChatChannel::Telegram, "1", "/tokens")
                .text
                .contains("No tokens")
        );
    }

    #[test]
    fn a_bare_token_is_accepted_as_the_confirmation() {
        let chat = core(None);
        let token = token_from(&chat.handle(ChatChannel::Vk, "7", "/start"));
        let reply = chat.handle(ChatChannel::Vk, "7", &token);
        assert!(reply.text.contains("Administration claimed"));
    }

    #[test]
    fn an_unconfirmed_mint_leaves_the_router_claimable() {
        let chat = core(None);
        let _abandoned = chat.handle(ChatChannel::Telegram, "1", "/start");
        assert!(!chat.admin.is_claimed());
        let second = chat.handle(ChatChannel::Telegram, "2", "/start");
        let token = token_from(&second);
        chat.handle(ChatChannel::Telegram, "2", &format!("/confirm {token}"));
        assert!(chat.admin.verify(&token));
    }

    /// The point of the shared claim: closing it anywhere closes it everywhere.
    #[test]
    fn a_claim_made_in_the_web_ui_closes_start_for_chat() {
        let chat = core(None);
        let candidate = chat.admin.begin().expect("web UI mint");
        chat.admin
            .confirm(&candidate.claim_id, &candidate.token)
            .expect("web UI confirm");
        let reply = chat.handle(ChatChannel::Telegram, "1", "/start");
        assert!(reply.text.contains("already claimed"));
        assert!(!reply.secret);
    }

    #[test]
    fn a_claim_made_in_chat_closes_the_web_ui_bootstrap() {
        let chat = core(None);
        let token = token_from(&chat.handle(ChatChannel::Telegram, "1", "/start"));
        chat.handle(ChatChannel::Telegram, "1", &format!("/confirm {token}"));
        assert_eq!(chat.admin.begin().unwrap_err(), ClaimError::AlreadyClaimed);
        assert!(!chat.admin.status().bootstrap_open);
    }

    #[test]
    fn a_second_chat_user_must_present_a_credential() {
        let chat = core(None);
        let token = token_from(&chat.handle(ChatChannel::Telegram, "1", "/start"));
        chat.handle(ChatChannel::Telegram, "1", &format!("/confirm {token}"));

        assert!(
            chat.handle(ChatChannel::Telegram, "2", "/tokens")
                .text
                .contains("/auth")
        );
        assert!(
            chat.handle(ChatChannel::Telegram, "2", "/auth la_admin_nope")
                .text
                .contains("not valid")
        );
        assert!(
            chat.handle(ChatChannel::Telegram, "2", &format!("/auth {token}"))
                .text
                .contains("Signed in")
        );
        assert!(
            chat.handle(ChatChannel::Telegram, "2", "/tokens")
                .text
                .contains("No tokens")
        );
    }

    #[test]
    fn an_admin_scoped_jwt_is_accepted_as_a_credential() {
        let chat = core(None);
        let jwt = chat
            .tokens
            .issue_admin_token(1, "ops")
            .expect("issue admin jwt");
        assert!(
            chat.handle(ChatChannel::Telegram, "3", &format!("/auth {jwt}"))
                .text
                .contains("Signed in")
        );
        // An ordinary client token is not an admin credential.
        let client = chat.tokens.issue_token(1, "client").expect("issue");
        assert!(
            chat.handle(ChatChannel::Telegram, "4", &format!("/auth {client}"))
                .text
                .contains("not valid")
        );
    }

    /// The binding caches the credential; it never replaces it.
    #[test]
    fn revoking_the_credential_unbinds_the_chat_user() {
        let chat = core(None);
        let jwt = chat.tokens.issue_admin_token(1, "ops").expect("issue");
        chat.handle(ChatChannel::Telegram, "5", &format!("/auth {jwt}"));
        let claims = chat.tokens.validate_token(&jwt).expect("validate");
        chat.tokens.revoke_token(&claims.sub).expect("revoke");
        assert!(
            chat.handle(ChatChannel::Telegram, "5", "/tokens")
                .text
                .contains("/auth")
        );
    }

    #[test]
    fn sessions_do_not_leak_across_channels_or_users() {
        let chat = core(None);
        let jwt = chat.tokens.issue_admin_token(1, "ops").expect("issue");
        chat.handle(ChatChannel::Telegram, "9", &format!("/auth {jwt}"));
        assert!(
            chat.handle(ChatChannel::Vk, "9", "/tokens")
                .text
                .contains("/auth"),
            "the same numeric id on another platform is another person"
        );
    }

    #[test]
    fn logout_forgets_the_binding() {
        let chat = core(None);
        let jwt = chat.tokens.issue_admin_token(1, "ops").expect("issue");
        chat.handle(ChatChannel::Telegram, "6", &format!("/auth {jwt}"));
        chat.handle(ChatChannel::Telegram, "6", "/logout");
        assert!(
            chat.handle(ChatChannel::Telegram, "6", "/tokens")
                .text
                .contains("/auth")
        );
    }

    #[test]
    fn an_environment_provisioned_key_starts_claimed() {
        let chat = core(Some("env-key".into()));
        let reply = chat.handle(ChatChannel::Telegram, "1", "/start");
        assert!(reply.text.contains("already claimed"));
        assert!(
            chat.handle(ChatChannel::Telegram, "1", "/auth env-key")
                .text
                .contains("Signed in")
        );
    }

    #[test]
    fn sensitive_commands_are_rate_limited() {
        let chat = ChatAdmin::new(
            Arc::new(AdminClaim::in_memory(None, Duration::from_secs(120))),
            TokenManager::new("secret-for-rate-limit-tests"),
            None,
            ChatAdminConfig {
                rate_limit_per_minute: 2,
                ..ChatAdminConfig::default()
            },
        );
        assert!(
            !chat
                .handle(ChatChannel::Telegram, "1", "/auth la_admin_wrong")
                .text
                .contains("Too many")
        );
        assert!(
            !chat
                .handle(ChatChannel::Telegram, "1", "/auth la_admin_wrong")
                .text
                .contains("Too many")
        );
        assert!(
            chat.handle(ChatChannel::Telegram, "1", "/auth la_admin_wrong")
                .text
                .contains("Too many")
        );
        // The budget is per user, not global.
        assert!(
            !chat
                .handle(ChatChannel::Telegram, "2", "/auth la_admin_wrong")
                .text
                .contains("Too many")
        );
    }

    /// The session map is keyed by a platform user id, which costs an attacker
    /// nothing to vary. Without a ceiling, messaging the bot from many accounts
    /// would grow the router's memory without bound.
    #[test]
    fn a_flood_of_strangers_cannot_grow_the_session_map_without_bound() {
        let chat = core(None);
        for user in 0..(MAX_SESSIONS * 2) {
            chat.handle(ChatChannel::Telegram, &user.to_string(), "/help");
        }
        assert!(
            chat.locked().len() <= MAX_SESSIONS,
            "session map grew to {}",
            chat.locked().len()
        );
    }

    /// The conversation being served is never the one evicted, even when the
    /// cap is hit while it is being handled.
    #[test]
    fn the_active_conversation_survives_the_cap() {
        let chat = core(Some("env-key".into()));
        chat.handle(ChatChannel::Telegram, "admin", "/auth env-key");
        for user in 0..(MAX_SESSIONS * 2) {
            chat.handle(ChatChannel::Vk, &user.to_string(), "/help");
        }
        // The admin's own next message must still find its session present.
        chat.handle(ChatChannel::Telegram, "admin", "/help");
        assert!(
            chat.locked()
                .get(&(ChatChannel::Telegram, "admin".to_string()))
                .is_some()
        );
    }

    #[test]
    fn telegram_style_command_suffixes_are_understood() {
        assert_eq!(normalise("/start@router_admin_bot"), "start");
        assert_eq!(normalise("STATUS"), "status");
    }

    #[test]
    fn unknown_commands_get_the_help_text() {
        let chat = core(Some("env-key".into()));
        chat.handle(ChatChannel::Telegram, "1", "/auth env-key");
        let reply = chat.handle(ChatChannel::Telegram, "1", "/nonsense");
        assert!(reply.text.contains("Unknown command"));
    }

    #[test]
    fn channels_are_independently_configurable() {
        let mut config = ChatAdminConfig::default();
        assert!(!config.telegram_enabled() && !config.vk_enabled());
        config.telegram_bot_token = Some("123:abc".into());
        assert!(config.telegram_enabled() && !config.vk_enabled());
        config.vk_bot_token = Some("vk-token".into());
        assert!(
            !config.vk_enabled(),
            "VK long polling needs a group id as well as a token"
        );
        config.vk_group_id = Some(42);
        assert!(config.vk_enabled());
    }
}

//! The administrative commands reachable from a chat channel.
//!
//! Split out of [`crate::chat_admin`], which owns *who* may run them; this
//! module owns *what* they do. Every function here assumes the caller has
//! already been authorised.
//!
//! One rule shapes the output: **token values are never echoed back into a
//! chat**. `/tokens` prints ids, labels, expiry, usage and revocation state,
//! matching the web UI; a freshly issued value is sent once, in its own
//! message, marked as a secret so the transport can delete it.

use std::fmt::Write as _;
use std::time::Duration;

use chrono::{TimeZone, Utc};

use crate::admin::AdminClaim;
use crate::chat_admin::Reply;
use crate::storage::TokenRecord;
use crate::token::{ADMIN_SCOPE, IssueRequest, TokenManager};

/// Default TTL of a token issued from chat, in hours.
const DEFAULT_ISSUE_TTL_HOURS: i64 = 24;

/// Cap on how many token records one `/tokens` reply lists, so a long-lived
/// deployment does not produce a message the platform will reject.
const LIST_LIMIT: usize = 30;

/// Read-only facts about the running router, for `/status`.
///
/// A trait rather than a direct dependency on the HTTP state so the chat core
/// can be unit tested without standing up a router.
pub trait RouterStatus: Send + Sync {
    /// Lines describing upstream, accounts and usage.
    fn status_lines(&self) -> Vec<String>;
}

/// Everything an authorised command needs.
pub struct CommandContext<'a> {
    /// Shared admin claim — the same one the web UI uses.
    pub admin: &'a AdminClaim,
    /// Token store behind `/tokens`, `/issue` and `/revoke`.
    pub tokens: &'a TokenManager,
    /// The credential the caller presented, already validated.
    pub credential: &'a str,
    /// How long a secret message survives, for the accompanying warning.
    pub secret_ttl: Duration,
    /// Optional live router facts for `/status`.
    pub status: Option<&'a dyn RouterStatus>,
}

/// Run one authorised command. `None` means "not a command I know".
#[must_use]
pub fn execute(context: &CommandContext<'_>, command: &str, rest: &str) -> Option<Reply> {
    match command {
        "status" => Some(status(context)),
        "tokens" | "list" => Some(list(context)),
        "issue" | "new" => Some(issue(context, rest)),
        "show" => Some(show(context, rest)),
        "rotate-token" | "reissue" => Some(rotate_client_token(context, rest)),
        "revoke" => Some(revoke(context, rest)),
        _ => None,
    }
}

/// `/status` — credential state and, when wired, live router facts.
fn status(context: &CommandContext<'_>) -> Reply {
    let claim = context.admin.status();
    let mut lines = vec![
        format!("Version: {}", crate::VERSION),
        format!(
            "Admin credential: {}",
            if claim.provisioned_by_environment {
                "provisioned by environment".to_string()
            } else if claim.claimed {
                claim.claimed_at.map_or_else(
                    || "claimed".to_string(),
                    |at| format!("claimed at {}", format_unix(cast_secs(at))),
                )
            } else {
                "unclaimed".to_string()
            }
        ),
        format!("Bootstrap open: {}", yes_no(claim.bootstrap_open)),
    ];
    match context.tokens.list_tokens() {
        Ok(records) => {
            let active = records.iter().filter(|r| !r.revoked).count();
            lines.push(format!(
                "Tokens: {} total, {active} active, {} revoked",
                records.len(),
                records.len() - active
            ));
        }
        Err(e) => lines.push(format!("Tokens: unavailable ({e})")),
    }
    if let Some(source) = context.status {
        lines.extend(source.status_lines());
    }
    Reply::plain(lines.join("\n"))
}

/// `/tokens` — ids and labels only. Never values.
fn list(context: &CommandContext<'_>) -> Reply {
    match context.tokens.list_tokens() {
        Ok(records) if records.is_empty() => Reply::plain("No tokens have been issued."),
        Ok(records) => {
            let total = records.len();
            let shown: Vec<String> = records.iter().take(LIST_LIMIT).map(describe).collect();
            let mut text = shown.join("\n");
            if total > LIST_LIMIT {
                let _ = write!(
                    text,
                    "\n\n… and {} more (showing the first {LIST_LIMIT}).",
                    total - LIST_LIMIT
                );
            }
            Reply::plain(text)
        }
        Err(e) => Reply::plain(format!("Could not list tokens: {e}")),
    }
}

/// Lifecycle state of a token, shared by `/tokens` and `/show`.
fn token_state(record: &TokenRecord) -> &'static crate::translation_core::Str {
    if record.revoked {
        "revoked"
    } else if record.expires_at <= crate::operation_context::now().timestamp() {
        "expired"
    } else {
        "active"
    }
}

/// One line per token: id, label, expiry, every constraint, revocation.
/// Never the token value.
fn describe(record: &TokenRecord) -> String {
    let usage = record.max_requests.map_or_else(
        || format!("{}", record.used_requests),
        |max| format!("{}/{max}", record.used_requests),
    );
    let state = token_state(record);
    // Every supported constraint is visible here, so an operator can audit a
    // token from chat without reaching for the CLI (issue #194).
    let spend = record.max_tokens.map_or_else(
        || format!("{}", record.used_tokens),
        |max| format!("{}/{max}", record.used_tokens),
    );
    let rpm = record
        .rate_limit_per_minute
        .map_or_else(String::new, |rpm| format!(", {rpm}/min"));
    let account = record
        .account
        .as_deref()
        .map_or_else(String::new, |account| format!(", account `{account}`"));
    let label = if record.label.is_empty() {
        "(no label)"
    } else {
        &record.label
    };
    let scope = if record.scope == ADMIN_SCOPE {
        " [admin]"
    } else {
        ""
    };
    format!(
        "• {id} — {label}{scope}\n  {state}, expires {expires}, \
         requests {usage}, tokens {spend}{rpm}{account}",
        id = record.id,
        expires = format_unix(record.expires_at),
    )
}

/// Constraints parsed from a chat `/issue` or `/rotate-token` command.
///
/// Chat surfaces accept every control the CLI and HTTP APIs accept
/// (issue #194). Positional `<label> [ttl_hours] [max_requests]` is still
/// honoured for the documented short form; anything beyond that is given as
/// `key=value`, which stays readable as the option set grows.
#[derive(Debug, Default, PartialEq, Eq)]
pub(crate) struct IssueOptions {
    pub label: Option<String>,
    pub ttl_hours: Option<i64>,
    pub max_requests: Option<u64>,
    pub max_tokens: Option<u64>,
    pub rate_limit_per_minute: Option<u64>,
    pub account: Option<String>,
}

/// Keys accepted in the `key=value` form, with their documented aliases.
const ISSUE_KEYS: &[(&crate::translation_core::Str, &[&crate::translation_core::Str])] = &[
    ("label", &["label", "name"]),
    ("ttl_hours", &["ttl_hours", "ttl"]),
    ("max_requests", &["max_requests", "requests"]),
    ("max_tokens", &["max_tokens", "tokens"]),
    (
        "rate_limit_per_minute",
        &["rate_limit_per_minute", "rpm", "rate"],
    ),
    ("account", &["account", "pin"]),
];

fn canonical_issue_key(key: &crate::translation_core::Str) -> crate::translation_core::Maybe<&'static crate::translation_core::Str> {
    let key = key.to_ascii_lowercase();
    ISSUE_KEYS
        .iter()
        .find(|(_, aliases)| aliases.contains(&key.as_str()))
        .map(|(canonical, _)| *canonical)
}

/// Parse the shared `/issue` and `/rotate-token` argument grammar.
pub(crate) fn parse_issue_options(rest: &crate::translation_core::Str) -> crate::translation_core::Outcome<IssueOptions, String> {
    let mut options = IssueOptions::default();
    let mut positional = 0;
    for part in rest.split_whitespace() {
        if let Some((key, value)) = part.split_once('=') {
            let Some(canonical) = canonical_issue_key(key) else {
                let known: Vec<&str> = ISSUE_KEYS.iter().map(|(name, _)| *name).collect();
                return Err(format!(
                    "unknown option `{key}`. Supported: {}.",
                    known.join(", ")
                ));
            };
            if value.is_empty() {
                return Err(format!("{canonical} needs a value, as `{canonical}=…`."));
            }
            match canonical {
                "label" => options.label = Some(value.to_string()),
                "account" => options.account = Some(value.to_string()),
                "ttl_hours" => {
                    options.ttl_hours = Some(parse_number::<i64>(value, "ttl_hours")?);
                }
                "max_requests" => {
                    options.max_requests = Some(parse_number::<u64>(value, "max_requests")?);
                }
                "max_tokens" => {
                    options.max_tokens = Some(parse_number::<u64>(value, "max_tokens")?);
                }
                _ => {
                    options.rate_limit_per_minute =
                        Some(parse_number::<u64>(value, "rate_limit_per_minute")?);
                }
            }
            continue;
        }
        // Positional short form, kept for the documented command shape.
        match positional {
            0 => options.label = Some(part.to_string()),
            1 => options.ttl_hours = Some(parse_number::<i64>(part, "ttl_hours")?),
            2 => options.max_requests = Some(parse_number::<u64>(part, "max_requests")?),
            _ => {
                return Err(
                    "too many positional values. Use `key=value` for the remaining options."
                        .to_string(),
                );
            }
        }
        positional += 1;
    }
    Ok(options)
}

fn parse_number<T: std::str::FromStr>(value: &str, field: &str) -> Result<T, String> {
    value
        .parse::<T>()
        .map_err(|_| format!("{field} must be a whole number."))
}

/// Human-readable summary of the constraints attached to a token.
fn describe_constraints(request: &IssueRequest<'_>) -> String {
    let mut parts = vec![format!("valid {}h", request.ttl_hours)];
    if let Some(max) = request.max_requests {
        parts.push(format!("{max} requests"));
    }
    if let Some(max) = request.max_tokens {
        parts.push(format!("{max} tokens"));
    }
    if let Some(rpm) = request.rate_limit_per_minute {
        parts.push(format!("{rpm}/min"));
    }
    if let Some(account) = request.account {
        parts.push(format!("account `{account}`"));
    }
    parts.join(", ")
}

/// `/issue [label] [ttl_hours] [max_requests] [key=value …]` — mint a client token.
///
/// The value is returned once, in a message marked secret.
fn issue(context: &CommandContext<'_>, rest: &str) -> Reply {
    let options = match parse_issue_options(rest) {
        Ok(options) => options,
        Err(message) => return Reply::plain(message),
    };
    let label = options.label.as_deref().unwrap_or("chat-issued");
    let request = IssueRequest {
        ttl_hours: options.ttl_hours.unwrap_or(DEFAULT_ISSUE_TTL_HOURS),
        label,
        account: options.account.as_deref(),
        max_requests: options.max_requests,
        max_tokens: options.max_tokens,
        rate_limit_per_minute: options.rate_limit_per_minute,
        scope: "",
        github_repos: Vec::new(),
        sliding_window_seconds: None,
        client_kind: None,
        principal_id: None,
    };
    // Same bounds as the CLI and HTTP surfaces, rather than chat-only rules.
    if let Err(message) = request.validate() {
        return Reply::plain(message);
    }
    match context.tokens.issue(&request) {
        Ok(token) => Reply::secret(format!(
            "Token issued — label `{label}`, {constraints}.\n\n\
             {token}\n\nThis value is shown once and never appears in /tokens.{note}",
            constraints = describe_constraints(&request),
            note = deletion_note(context.secret_ttl),
        )),
        Err(e) => Reply::plain(format!("Could not issue a token: {e}")),
    }
}

/// `/rotate-token <id> [key=value …]` — reissue a client token.
///
/// Constraints are preserved unless explicitly overridden, and the old value is
/// revoked atomically by [`crate::token::TokenManager::rotate_token`].
fn rotate_client_token(context: &CommandContext<'_>, rest: &str) -> Reply {
    let (id, rest) = rest.split_once(char::is_whitespace).unwrap_or((rest, ""));
    if id.is_empty() {
        return Reply::plain("Usage: /rotate-token <id> [label=… ttl_hours=… max_tokens=…]");
    }
    let options = match parse_issue_options(rest) {
        Ok(options) => options,
        Err(message) => return Reply::plain(message),
    };
    let existing = match context.tokens.store().get(id) {
        Ok(Some(record)) => record,
        Ok(None) => return Reply::plain(format!("No token with id `{id}`.")),
        Err(error) => return Reply::plain(format!("Could not read token `{id}`: {error}")),
    };
    if existing.scope == crate::token::ADMIN_SCOPE {
        return Reply::plain("Use /rotate to rotate the admin credential.");
    }
    match context.tokens.rotate_token_with(
        id,
        &crate::token::RotateOverrides {
            label: options.label.as_deref(),
            ttl_hours: options.ttl_hours,
            max_requests: options.max_requests,
            max_tokens: options.max_tokens,
            rate_limit_per_minute: options.rate_limit_per_minute,
            account: options.account.as_deref(),
        },
    ) {
        Ok(token) => Reply::secret(format!(
            "Token `{id}` rotated; the previous value is revoked.\n\n\
             {token}\n\nThis value is shown once and never appears in /tokens.{note}",
            note = deletion_note(context.secret_ttl),
        )),
        Err(e) => Reply::plain(format!("Could not rotate the token: {e}")),
    }
}

/// `/show <id>` — every constraint, counter, and state for one token.
fn show(context: &CommandContext<'_>, rest: &str) -> Reply {
    let id = rest.trim();
    if id.is_empty() {
        return Reply::plain("Usage: /show <id>");
    }
    match context.tokens.store().get(id) {
        Ok(Some(record)) => Reply::plain(describe_full(&record)),
        Ok(None) => Reply::plain(format!("No token with id `{id}`.")),
        Err(error) => Reply::plain(format!("Could not read token `{id}`: {error}")),
    }
}

/// Full constraint and usage detail for one token, for `/show`.
fn describe_full(record: &crate::storage::TokenRecord) -> String {
    let limit = |used: u64, max: Option<u64>| {
        max.map_or_else(
            || format!("{used}/unlimited"),
            |max| format!("{used}/{max}"),
        )
    };
    format!(
        "`{id}` — {label}{scope}\n\
         state: {state}\n\
         issued: {issued}\n\
         expires: {expires}\n\
         requests: {requests}\n\
         tokens: {tokens} (reserved {reserved})\n\
         rate limit: {rpm}\n\
         account: {account}",
        id = record.id,
        label = record.label,
        scope = if record.scope.is_empty() {
            String::new()
        } else {
            format!(" [{}]", record.scope)
        },
        state = token_state(record),
        issued = format_unix(record.issued_at),
        expires = format_unix(record.expires_at),
        requests = limit(record.used_requests, record.max_requests),
        tokens = limit(record.used_tokens, record.max_tokens),
        reserved = record.reserved_tokens,
        rpm = record
            .rate_limit_per_minute
            .map_or_else(|| "unlimited".to_string(), |rpm| format!("{rpm}/min")),
        account = record.account.as_deref().unwrap_or("(any)"),
    )
}

/// `/revoke <id>` — revoke by token id (the id from `/tokens`, not a value).
fn revoke(context: &CommandContext<'_>, rest: &str) -> Reply {
    let id = rest.split_whitespace().next().unwrap_or_default();
    if id.is_empty() {
        return Reply::plain("Send `/revoke <id>` with an id from /tokens.");
    }
    match context.tokens.revoke_token(id) {
        Ok(()) => Reply::plain(format!("Revoked `{id}`.")),
        Err(e) => Reply::plain(format!("Could not revoke `{id}`: {e}")),
    }
}

/// `/rotate` — replace the admin credential the caller is using.
///
/// Two credential kinds can reach a chat channel and each rotates in its own
/// store: a claimed `la_admin_…` credential lives in the shared claim, an
/// admin-scoped `la_sk_…` JWT lives in the token store. The flat deploy-time
/// key belongs to the deployment and cannot rotate itself.
///
/// # Errors
///
/// Returns a human-readable message when the credential cannot be rotated.
pub fn rotate(context: &CommandContext<'_>) -> Result<String, String> {
    if context.admin.verify(context.credential) && !context.admin.provisioned_by_environment() {
        return context.admin.rotate().map_err(|e| e.to_string());
    }
    if let Ok(claims) = context.tokens.validate_admin_token(context.credential) {
        let ttl_hours = ((claims.exp - claims.iat) / 3600).max(1);
        return context
            .tokens
            .rotate_admin_token(&claims.sub, ttl_hours, &claims.label)
            .map_err(|e| e.to_string());
    }
    Err(
        "This credential is provisioned by the deployment and has nothing to rotate; \
         change TOKEN_ADMIN_KEY where the router is deployed."
            .to_string(),
    )
}

/// Warning appended to every message that carries a secret.
#[must_use]
pub fn deletion_note(secret_ttl: Duration) -> String {
    if secret_ttl.is_zero() {
        String::new()
    } else {
        format!(
            "\n\nI will delete this message in {}s where the platform allows \
             it — copy it now.",
            secret_ttl.as_secs()
        )
    }
}

/// The live router behind `/status`: upstream, account health, usage.
///
/// Deliberately read-only and free of secrets — it repeats what `doctor`,
/// `/api/management/accounts` and `/api/management/usage` already report.
impl RouterStatus for crate::app_state::AppState {
    fn status_lines(&self) -> Vec<String> {
        let usage = crate::metrics::usage_snapshot(&self.metrics);
        let mut lines = vec![
            format!(
                "Upstream: {} ({})",
                self.upstream_provider.as_str(),
                self.upstream_base_url
            ),
            format!(
                "Requests: {} total, {} errors, {} tokens issued, {} revoked",
                usage.requests_total, usage.errors_total, usage.tokens_issued, usage.tokens_revoked
            ),
        ];
        match self.account_router.as_ref() {
            Some(router) => {
                let health = router.health_snapshot_with(Some(&self.subscription_cache));
                let healthy = health.iter().filter(|account| account.healthy).count();
                lines.push(format!("Accounts: {healthy}/{} healthy", health.len()));
                lines.extend(
                    health
                        .iter()
                        .filter(|account| !account.healthy)
                        .map(|account| {
                            // A credential that was never tried has no
                            // `last_error`; its state is the reason (#242).
                            format!(
                                "  ⚠ {}: {}",
                                account.name,
                                account
                                    .last_error
                                    .as_deref()
                                    .unwrap_or_else(|| account.credential.label())
                            )
                        }),
                );
            }
            None => lines.push("Accounts: single-account mode".to_string()),
        }
        lines
    }
}

const fn yes_no(value: bool) -> &'static crate::translation_core::Str {
    if value { "yes" } else { "no" }
}

/// Unix seconds as a human-readable UTC timestamp.
fn format_unix(secs: i64) -> String {
    Utc.timestamp_opt(secs, 0).single().map_or_else(
        || secs.to_string(),
        |dt| dt.format("%Y-%m-%d %H:%M UTC").to_string(),
    )
}

/// Widen a `u64` timestamp for formatting, saturating rather than wrapping.
fn cast_secs(value: u64) -> i64 {
    i64::try_from(value).unwrap_or(i64::MAX)
}

#[cfg(test)]
mod tests {
    use std::sync::Arc;

    use super::*;
    use crate::chat_admin::{ChatAdmin, ChatAdminConfig, ChatChannel};

    fn chat() -> ChatAdmin {
        ChatAdmin::new(
            Arc::new(AdminClaim::in_memory(
                Some("env-key".into()),
                Duration::from_secs(60),
            )),
            TokenManager::new("secret-for-chat-command-tests"),
            Some("env-key".into()),
            ChatAdminConfig {
                rate_limit_per_minute: 0,
                ..ChatAdminConfig::default()
            },
        )
    }

    fn signed_in() -> ChatAdmin {
        let chat = chat();
        chat.handle(ChatChannel::Telegram, "1", "/auth env-key");
        chat
    }

    fn say(chat: &ChatAdmin, text: &str) -> Reply {
        chat.handle(ChatChannel::Telegram, "1", text)
    }

    #[test]
    fn issue_returns_the_value_once_and_marks_it_secret() {
        let chat = signed_in();
        let reply = say(&chat, "/issue ci 48 100");
        assert!(reply.secret);
        assert!(reply.text.contains("la_sk_"));
        assert!(reply.text.contains("48h"));
        assert!(reply.text.contains("100 requests"));
    }

    /// Every constraint the CLI and HTTP APIs accept is reachable from chat
    /// through `key=value` options (issue #194).
    #[test]
    fn issue_accepts_every_supported_constraint() {
        let chat = signed_in();
        let reply = say(
            &chat,
            "/issue ci ttl_hours=12 max_requests=5 max_tokens=9000 rpm=3 account=primary",
        );
        assert!(reply.secret, "{}", reply.text);
        assert!(reply.text.contains("12h"), "{}", reply.text);
        assert!(reply.text.contains("5 requests"), "{}", reply.text);
        assert!(reply.text.contains("9000 tokens"), "{}", reply.text);
        assert!(reply.text.contains("3/min"), "{}", reply.text);
        assert!(reply.text.contains("primary"), "{}", reply.text);
    }

    #[test]
    fn issue_reports_unknown_and_malformed_options() {
        let chat = signed_in();
        assert!(
            say(&chat, "/issue ci nonsense=1")
                .text
                .contains("unknown option")
        );
        assert!(
            say(&chat, "/issue ci max_tokens=lots")
                .text
                .contains("max_tokens must be a whole number")
        );
        // The shared bounds apply here exactly as they do on the CLI.
        assert!(
            say(&chat, "/issue ci ttl_hours=0")
                .text
                .contains("ttl_hours must be a positive")
        );
        assert!(
            say(&chat, "/issue ci max_tokens=0")
                .text
                .contains("max_tokens must be greater than zero")
        );
    }

    #[test]
    fn show_reports_every_constraint_for_one_token() {
        let chat = signed_in();
        say(&chat, "/issue audited 24 7 max_tokens=500 rpm=2");
        let id = chat
            .tokens
            .list_tokens()
            .expect("list")
            .into_iter()
            .find(|record| record.label == "audited")
            .expect("issued record")
            .id;

        let reply = say(&chat, &format!("/show {id}"));
        assert!(!reply.secret, "/show must never be a secret reply");
        assert!(reply.text.contains("requests: 0/7"), "{}", reply.text);
        assert!(reply.text.contains("tokens: 0/500"), "{}", reply.text);
        assert!(reply.text.contains("2/min"), "{}", reply.text);
        assert!(reply.text.contains("active"), "{}", reply.text);
        assert!(
            !reply.text.contains(crate::token::TOKEN_PREFIX),
            "/show must not echo a token value"
        );
    }

    #[test]
    fn rotating_a_client_token_preserves_its_constraints() {
        let chat = signed_in();
        say(&chat, "/issue rotating 24 7 max_tokens=500 rpm=2");
        let original = chat
            .tokens
            .list_tokens()
            .expect("list")
            .into_iter()
            .find(|record| record.label == "rotating")
            .expect("issued record");

        let reply = say(&chat, &format!("/rotate-token {}", original.id));
        assert!(reply.secret, "{}", reply.text);
        assert!(reply.text.contains("la_sk_"), "{}", reply.text);

        let records = chat.tokens.list_tokens().expect("list");
        let old = records
            .iter()
            .find(|record| record.id == original.id)
            .expect("old record");
        assert!(old.revoked, "the previous value must be revoked");

        let replacement = records
            .iter()
            .find(|record| record.label == "rotating" && !record.revoked)
            .expect("replacement record");
        assert_eq!(replacement.max_requests, Some(7));
        assert_eq!(replacement.max_tokens, Some(500));
        assert_eq!(replacement.rate_limit_per_minute, Some(2));
    }

    #[test]
    fn rotating_a_client_token_applies_explicit_overrides() {
        let chat = signed_in();
        say(&chat, "/issue changing 24 7 max_tokens=500");
        let original = chat
            .tokens
            .list_tokens()
            .expect("list")
            .into_iter()
            .find(|record| record.label == "changing")
            .expect("issued record");

        say(
            &chat,
            &format!("/rotate-token {} max_tokens=900", original.id),
        );
        let replacement = chat
            .tokens
            .list_tokens()
            .expect("list")
            .into_iter()
            .find(|record| record.label == "changing" && !record.revoked)
            .expect("replacement record");
        assert_eq!(replacement.max_tokens, Some(900), "override applies");
        assert_eq!(
            replacement.max_requests,
            Some(7),
            "unspecified constraints are preserved"
        );
    }

    #[test]
    fn listing_shows_every_constraint() {
        let chat = signed_in();
        say(&chat, "/issue listed 24 7 max_tokens=500 rpm=2");
        let reply = say(&chat, "/tokens");
        assert!(reply.text.contains("requests 0/7"), "{}", reply.text);
        assert!(reply.text.contains("tokens 0/500"), "{}", reply.text);
        assert!(reply.text.contains("2/min"), "{}", reply.text);
    }

    /// The central secrecy rule: listing never re-exposes a token value.
    #[test]
    fn listing_never_echoes_a_token_value() {
        let chat = signed_in();
        let issued = say(&chat, "/issue ci");
        let value = issued
            .text
            .split_whitespace()
            .find(|word| word.starts_with(crate::token::TOKEN_PREFIX))
            .expect("issued value");
        let listed = say(&chat, "/tokens");
        assert!(!listed.text.contains(value));
        assert!(!listed.secret);
        assert!(listed.text.contains("ci"));
        assert!(listed.text.contains("active"));
    }

    #[test]
    fn revoke_marks_the_token_revoked() {
        let chat = signed_in();
        say(&chat, "/issue doomed");
        let listed = say(&chat, "/tokens");
        let id = listed
            .text
            .lines()
            .find_map(|line| line.strip_prefix("• "))
            .and_then(|line| line.split(" — ").next())
            .expect("an id in the listing")
            .to_string();
        assert!(
            say(&chat, &format!("/revoke {id}"))
                .text
                .contains("Revoked")
        );
        assert!(say(&chat, "/tokens").text.contains("revoked"));
    }

    #[test]
    fn revoke_without_an_id_explains_itself() {
        assert!(say(&signed_in(), "/revoke").text.contains("/revoke <id>"));
    }

    #[test]
    fn issue_rejects_a_nonsense_ttl() {
        assert!(
            say(&signed_in(), "/issue ci abc")
                .text
                .contains("ttl_hours must be")
        );
    }

    #[test]
    fn status_reports_the_credential_state() {
        let reply = say(&signed_in(), "/status");
        assert!(reply.text.contains("provisioned by environment"));
        assert!(reply.text.contains("Bootstrap open: no"));
        assert!(!reply.secret);
    }

    #[test]
    fn an_environment_key_cannot_rotate_itself() {
        let reply = say(&signed_in(), "/rotate");
        assert!(reply.text.contains("provisioned by the deployment"));
    }

    #[test]
    fn rotating_a_claimed_credential_replaces_it() {
        let chat = ChatAdmin::new(
            Arc::new(AdminClaim::in_memory(None, Duration::from_secs(60))),
            TokenManager::new("secret-for-rotate-tests"),
            None,
            ChatAdminConfig {
                rate_limit_per_minute: 0,
                ..ChatAdminConfig::default()
            },
        );
        let minted = chat.handle(ChatChannel::Telegram, "1", "/start");
        let token = minted
            .text
            .split_whitespace()
            .find(|word| word.starts_with(crate::admin::ADMIN_TOKEN_PREFIX))
            .expect("candidate")
            .to_string();
        chat.handle(ChatChannel::Telegram, "1", &format!("/confirm {token}"));

        let rotated = chat.handle(ChatChannel::Telegram, "1", "/rotate");
        assert!(rotated.secret);
        let replacement = rotated
            .text
            .split_whitespace()
            .find(|word| word.starts_with(crate::admin::ADMIN_TOKEN_PREFIX))
            .expect("replacement");
        assert!(chat.admin_claim().verify(replacement));
        // The old credential stops working, and the session was rebound to the
        // replacement rather than being silently locked out.
        assert!(!chat.admin_claim().verify(&token));
        assert!(
            chat.handle(ChatChannel::Telegram, "1", "/tokens")
                .text
                .contains("No tokens")
        );
    }

    #[test]
    fn timestamps_render_as_utc() {
        assert_eq!(format_unix(0), "1970-01-01 00:00 UTC");
    }
}

//! Configuration for the optional chat admin channels.
//!
//! Kept out of [`crate::config`] for the same reason as
//! [`crate::admin_config`]: that module is at its line budget, and the
//! constructors are re-exported there so callers keep using `config::…`.
//!
//! The whole feature is off unless a bot token is present, so an upgrade adds
//! no new behaviour to an existing deployment.

use std::time::Duration;

use crate::chat_admin::{ChatAdminConfig, DEFAULT_RATE_LIMIT_PER_MINUTE, DEFAULT_SECRET_TTL_SECS};
use crate::config::{ConfigError, parse_u64_env};

/// Build the chat admin configuration from environment variables.
///
/// # Errors
///
/// Returns [`ConfigError::InvalidPort`] when `VK_GROUP_ID` is not a number —
/// the nearest existing variant for "a numeric setting did not parse".
pub fn chat_admin_from_env() -> crate::translation_core::Outcome<ChatAdminConfig, ConfigError> {
    let vk_group_id = crate::operation_context::var("VK_GROUP_ID")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .map(|value| value.parse::<u64>())
        .transpose()
        .map_err(|_| ConfigError::InvalidPort)?;
    Ok(chat_admin_config(
        crate::operation_context::var("TELEGRAM_BOT_TOKEN").ok(),
        crate::operation_context::var("VK_BOT_TOKEN").ok(),
        vk_group_id,
        parse_u64_env("CHAT_ADMIN_SECRET_TTL_SECS", DEFAULT_SECRET_TTL_SECS),
        parse_u64_env(
            "CHAT_ADMIN_RATE_LIMIT_PER_MINUTE",
            u64::from(DEFAULT_RATE_LIMIT_PER_MINUTE),
        ),
    ))
}

/// Assemble a [`ChatAdminConfig`] from explicit values.
///
/// Empty strings are normalised to `None`, so `TELEGRAM_BOT_TOKEN=` in a
/// compose file means "off" rather than "on with an empty token".
#[must_use]
pub fn chat_admin_config(
    telegram_bot_token: crate::translation_core::Maybe<String>,
    vk_bot_token: crate::translation_core::Maybe<String>,
    vk_group_id: crate::translation_core::Maybe<u64>,
    secret_ttl_secs: u64,
    rate_limit_per_minute: u64,
) -> ChatAdminConfig {
    ChatAdminConfig {
        telegram_bot_token: telegram_bot_token.filter(|value| !value.trim().is_empty()),
        vk_bot_token: vk_bot_token.filter(|value| !value.trim().is_empty()),
        vk_group_id,
        secret_ttl: Duration::from_secs(secret_ttl_secs),
        rate_limit_per_minute: u32::try_from(rate_limit_per_minute)
            .unwrap_or(DEFAULT_RATE_LIMIT_PER_MINUTE),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn no_tokens_means_no_channels() {
        let config = chat_admin_config(None, None, None, 120, 5);
        assert!(!config.telegram_enabled());
        assert!(!config.vk_enabled());
    }

    #[test]
    fn an_empty_token_is_not_a_configured_channel() {
        let config = chat_admin_config(Some(String::new()), Some("   ".into()), Some(1), 120, 5);
        assert!(!config.telegram_enabled());
        assert!(!config.vk_enabled());
    }

    #[test]
    fn each_channel_is_independent() {
        let telegram = chat_admin_config(Some("123:abc".into()), None, None, 120, 5);
        assert!(telegram.telegram_enabled() && !telegram.vk_enabled());
        let vk = chat_admin_config(None, Some("vk1".into()), Some(7), 120, 5);
        assert!(!vk.telegram_enabled() && vk.vk_enabled());
    }

    #[test]
    fn secrets_can_be_kept_by_setting_a_zero_ttl() {
        assert!(
            chat_admin_config(None, None, None, 0, 5)
                .secret_ttl
                .is_zero()
        );
    }
}

//! Stored Chat Completions collection and resource lifecycle.

use std::collections::HashSet;

use axum::body::{Body, Bytes};
use axum::extract::{OriginalUri, Path, Request, State};
use axum::http::{HeaderMap, StatusCode, Uri};
use axum::response::{IntoResponse, Response};

use crate::app_state::AppState;
use crate::response_affinity::{
    AffinityDestination, ResponseAffinity, ResponseNamespace, ResponseOwner,
};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Operation {
    Retrieve,
    Update,
    Delete,
    Messages,
}

impl Operation {
    fn suffix(self) -> &'static crate::translation_core::Str {
        if self == Self::Messages {
            "/messages"
        } else {
            ""
        }
    }
}

pub async fn list(
    State(state): State<AppState>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    let claims = match authenticate(&state, request.headers()) {
        Ok(claims) => claims,
        Err(response) => return response,
    };
    let owner = match owner(&claims) {
        Ok(owner) => owner,
        Err(response) => return response,
    };
    let Some(namespace) = ResponseNamespace::from_path(uri.path()) else {
        return not_found();
    };
    if state.upstream_provider != crate::config::UpstreamProvider::OpenAICompatible {
        return openai_error(
            StatusCode::CONFLICT,
            "invalid_request_error",
            "listing stored Chat Completions requires one explicitly selected native provider",
        );
    }
    let provider = match crate::provider_proxy::resolve_openai_compatible_provider(&state) {
        Ok(provider) => provider,
        Err(error) => return unavailable(&format!("provider lookup failed: {error}")),
    };
    if let Err(response) = authorize_provider(&claims, request.headers(), uri.path(), &provider) {
        return response;
    }
    let affinities = match state
        .provider_store
        .response_affinities()
        .list(namespace, &owner)
    {
        Ok(affinities) => affinities,
        Err(error) => return unavailable(&format!("resource affinity is unavailable: {error}")),
    };
    let allowed = affinities
        .iter()
        .filter_map(|affinity| match &affinity.destination {
            AffinityDestination::StoredProvider {
                name,
                provider_kind,
                base_url,
            } if name == &provider.name
                && provider_kind == &provider.kind
                && base_url == &provider.base_url =>
            {
                Some(affinity.response_id.clone())
            }
            _ => None,
        })
        .collect::<HashSet<_>>();
    let Some(api_key) = provider.api_key.as_deref() else {
        return unavailable("the selected provider credential is unavailable");
    };
    let path = uri.query().map_or_else(
        || "/v1/chat/completions".to_string(),
        |query| format!("/v1/chat/completions?{query}"),
    );
    let correlation_id = crate::request_log::correlation_id(request.headers());
    let client =
        match crate::upstream_client::guarded_provider_client(&state.client, &provider.base_url) {
            Ok(client) => client,
            Err(error) => return bad_gateway(&error.to_string()),
        };
    let upstream = client
        .get(crate::provider_proxy::join_openai_compatible_url(
            &provider.base_url,
            &path,
        ))
        .headers(crate::proxy::native_request_headers(
            request.headers(),
            api_key,
        ));
    let upstream = match state
        .request_log
        .send_upstream(&correlation_id, client, upstream)
        .await
    {
        Ok(response) => response,
        Err(error) => return bad_gateway(&format!("provider request failed: {error}")),
    };
    relay_list(&state, upstream, &allowed, &correlation_id).await
}

pub async fn retrieve(
    State(state): State<AppState>,
    Path(completion_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    forward(state, completion_id, uri, request, Operation::Retrieve).await
}

pub async fn update(
    State(state): State<AppState>,
    Path(completion_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    forward(state, completion_id, uri, request, Operation::Update).await
}

pub async fn delete(
    State(state): State<AppState>,
    Path(completion_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    forward(state, completion_id, uri, request, Operation::Delete).await
}

pub async fn messages(
    State(state): State<AppState>,
    Path(completion_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    forward(state, completion_id, uri, request, Operation::Messages).await
}

async fn forward(
    state: AppState,
    completion_id: String,
    uri: Uri,
    request: Request,
    operation: Operation,
) -> Response {
    let claims = match authenticate(&state, request.headers()) {
        Ok(claims) => claims,
        Err(response) => return response,
    };
    let owner = match owner(&claims) {
        Ok(owner) => owner,
        Err(response) => return response,
    };
    let Some(namespace) = ResponseNamespace::from_path(uri.path()) else {
        return not_found();
    };
    let affinity =
        match state
            .provider_store
            .response_affinities()
            .lookup(namespace, &completion_id, &owner)
        {
            Ok(Some(affinity)) => affinity,
            Ok(None) => return not_found(),
            Err(error) => {
                return unavailable(&format!("resource affinity is unavailable: {error}"));
            }
        };
    let AffinityDestination::StoredProvider {
        name,
        provider_kind,
        base_url,
    } = &affinity.destination
    else {
        return unavailable("the stored Chat Completion has no exact native lifecycle mapping");
    };
    let provider = match state.provider_store.resolve(name) {
        Ok(Some(provider)) if provider.kind == *provider_kind && provider.base_url == *base_url => {
            provider
        }
        Ok(None) => match (state.openai_compatible.provider_name == *name)
            .then(|| state.openai_compatible.resolve())
            .filter(|provider| provider.kind == *provider_kind && provider.base_url == *base_url)
        {
            Some(provider) => provider,
            None => return unavailable("the response's exact provider is unavailable"),
        },
        Ok(Some(_)) => return unavailable("the response's exact provider has changed"),
        Err(error) => return unavailable(&format!("provider lookup failed: {error}")),
    };
    if let Err(response) = authorize_provider(&claims, request.headers(), uri.path(), &provider) {
        return response;
    }
    let Some(api_key) = provider.api_key.as_deref() else {
        return unavailable("the response's provider credential is unavailable");
    };
    let (parts, body) = request.into_parts();
    let body = match axum::body::to_bytes(body, state.max_proxy_request_bytes).await {
        Ok(body) => body,
        Err(error) => {
            return openai_error(
                StatusCode::PAYLOAD_TOO_LARGE,
                "invalid_request_error",
                &format!("request body exceeds the proxy limit: {error}"),
            );
        }
    };
    let path = resource_path(&completion_id, operation, uri.query());
    let correlation_id = crate::request_log::correlation_id(&parts.headers);
    let client =
        match crate::upstream_client::guarded_provider_client(&state.client, &provider.base_url) {
            Ok(client) => client,
            Err(error) => return bad_gateway(&error.to_string()),
        };
    let upstream = client
        .request(
            reqwest::Method::from_bytes(parts.method.as_str().as_bytes())
                .expect("HTTP methods accepted by axum are valid for reqwest"),
            crate::provider_proxy::join_openai_compatible_url(&provider.base_url, &path),
        )
        .headers(crate::proxy::native_request_headers(
            &parts.headers,
            api_key,
        ))
        .body(body.clone());
    let upstream = match state
        .request_log
        .send_upstream(&correlation_id, client, upstream)
        .await
    {
        Ok(response) => response,
        Err(error) => return bad_gateway(&format!("provider request failed: {error}")),
    };
    relay_resource(
        &state,
        affinity,
        operation,
        upstream,
        body.len() as u64,
        &correlation_id,
    )
    .await
}

fn authorize_provider(
    claims: &crate::token::TokenClaims,
    headers: &HeaderMap,
    path: &crate::translation_core::Str,
    provider: &crate::providers::ResolvedProvider,
) -> crate::translation_core::Outcome<(), Response> {
    let (client, _) = crate::client_policy::bound_client(claims)
        .map_err(|error| openai_error(StatusCode::FORBIDDEN, "permission_error", &error))?;
    if provider.supports_client(client)
        && crate::client_policy::request_evidence(
            client,
            crate::client_policy::ClientProtocol::OpenAIChat,
            path,
            headers,
        )
    {
        Ok(())
    } else {
        Err(openai_error(
            StatusCode::FORBIDDEN,
            "permission_error",
            "the stored provider has no tested adapter for this signed client request",
        ))
    }
}

async fn relay_resource(
    state: &AppState,
    affinity: ResponseAffinity,
    operation: Operation,
    upstream: reqwest::Response,
    bytes_sent: u64,
    correlation_id: &crate::translation_core::Str,
) -> Response {
    let status = status(&upstream);
    let headers = crate::proxy::relay_response_headers(upstream.headers());
    let body = match upstream.bytes().await {
        Ok(body) => body,
        Err(error) => return bad_gateway(&format!("upstream body read failed: {error}")),
    };
    record(state, status, bytes_sent, &body, correlation_id);
    if matches!(status, StatusCode::NOT_FOUND | StatusCode::GONE) {
        let _ = state
            .provider_store
            .response_affinities()
            .remove_if_matches(&affinity);
        return not_found();
    }
    if operation == Operation::Delete
        && status.is_success()
        && let Err(error) = state
            .provider_store
            .response_affinities()
            .remove_if_matches(&affinity)
    {
        return unavailable(&format!("resource affinity is unavailable: {error}"));
    }
    response(status, headers, body)
}

async fn relay_list(
    state: &AppState,
    upstream: reqwest::Response,
    allowed: &HashSet<String>,
    correlation_id: &crate::translation_core::Str,
) -> Response {
    let status = status(&upstream);
    let headers = crate::proxy::relay_response_headers(upstream.headers());
    let body = match upstream.bytes().await {
        Ok(body) => body,
        Err(error) => return bad_gateway(&format!("upstream body read failed: {error}")),
    };
    record(state, status, 0, &body, correlation_id);
    if !status.is_success() {
        return response(status, headers, body);
    }
    let Ok(mut payload) = serde_json::from_slice::<serde_json::Value>(&body) else {
        return bad_gateway("provider returned an invalid Chat Completions list");
    };
    let Some(data) = payload
        .get_mut("data")
        .and_then(serde_json::Value::as_array_mut)
    else {
        return bad_gateway("provider returned an invalid Chat Completions list");
    };
    data.retain(|item| {
        item.get("id")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|id| allowed.contains(id))
    });
    let first = data
        .first()
        .and_then(|item| item.get("id"))
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let last = data
        .last()
        .and_then(|item| item.get("id"))
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    if let Some(object) = payload.as_object_mut() {
        object.insert("first_id".into(), first);
        object.insert("last_id".into(), last);
    }
    response(
        status,
        headers,
        Bytes::from(serde_json::to_vec(&payload).expect("JSON values always serialize")),
    )
}

fn record(state: &AppState, status: StatusCode, sent: u64, body: &[u8], correlation_id: &crate::translation_core::Str) {
    state.request_log.record_upstream_body(correlation_id, body);
    state
        .metrics
        .record_request(crate::metrics::Surface::OpenAIChat, status.as_u16(), None);
    state.metrics.record_bytes(sent, body.len() as u64);
}

fn resource_path(completion_id: &crate::translation_core::Str, operation: Operation, query: crate::translation_core::Maybe<&crate::translation_core::Str>) -> String {
    let query = query.map_or(String::new(), |query| format!("?{query}"));
    format!(
        "/v1/chat/completions/{}{}{query}",
        crate::responses_lifecycle::percent_encode_segment(completion_id),
        operation.suffix()
    )
}

fn authenticate(
    state: &AppState,
    headers: &HeaderMap,
) -> crate::translation_core::Outcome<crate::token::TokenClaims, Response> {
    crate::proxy::authenticate_client_error(state, headers)
        .map_err(|error| error.render(crate::api_error::ApiDialect::OpenAi))
}

fn owner(claims: &crate::token::TokenClaims) -> crate::translation_core::Outcome<ResponseOwner, Response> {
    ResponseOwner::from_claims(claims)
        .map_err(|error| openai_error(StatusCode::FORBIDDEN, "permission_error", &error))
}

fn status(response: &reqwest::Response) -> StatusCode {
    StatusCode::from_u16(response.status().as_u16()).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR)
}

fn response(status: StatusCode, headers: HeaderMap, body: Bytes) -> Response {
    let mut response = Response::new(Body::from(body));
    *response.status_mut() = status;
    *response.headers_mut() = headers;
    response
}

fn not_found() -> Response {
    let body = crate::translation_core::json!({
        "error": {
            "message": "Chat completion not found",
            "type": "invalid_request_error",
            "param": serde_json::Value::Null,
            "code": "chat_completion_not_found",
        }
    });
    (StatusCode::NOT_FOUND, axum::Json(body)).into_response()
}

fn unavailable(message: &crate::translation_core::Str) -> Response {
    openai_error(StatusCode::SERVICE_UNAVAILABLE, "api_error", message)
}

fn bad_gateway(message: &crate::translation_core::Str) -> Response {
    openai_error(StatusCode::BAD_GATEWAY, "api_error", message)
}

fn openai_error(status: StatusCode, error_type: &crate::translation_core::Str, message: &crate::translation_core::Str) -> Response {
    crate::api_error::PresentedError {
        status,
        error_type,
        message,
    }
    .render(crate::api_error::ApiDialect::OpenAi)
}

