//! `auth` and `tls` command definitions.
//!
//! Split from `cli.rs` to keep that file within the repository's 1000-line
//! limit.

use clap::Subcommand;

use super::{AuthFlow, CLAUDE_AUTH_FLOWS, CODEX_AUTH_FLOWS, auth_flow_parser};

/// A login this machine already holds that the router can adopt.
///
/// Not `SubscriptionProvider`: that enum is about subscriptions the proxy
/// serves models from, and GitHub is a credential the router presents upstream
/// rather than a subscription. Import spans both, so it needs a name for the
/// union (issue #278).
#[derive(Clone, Copy, Debug, Eq, PartialEq, clap::ValueEnum)]
pub enum ImportProvider {
    #[value(name = "claude", alias = "anthropic")]
    Claude,
    #[value(name = "codex", alias = "chatgpt")]
    Codex,
    #[value(name = "gemini", alias = "google")]
    Gemini,
    #[value(name = "qwen", alias = "qwen-code")]
    Qwen,
    #[value(name = "gh", alias = "github")]
    Gh,
}

impl ImportProvider {
    /// The built-in credential this name refers to, if any.
    ///
    /// `auth clear` takes a free-form name so it can also withdraw an API-key
    /// provider added through `providers add` (issue #561). The built-in names
    /// keep their exact spellings and aliases, so this resolves them before a
    /// name is looked up in the provider store.
    #[must_use]
    pub fn from_name(value: &str) -> Option<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "claude" | "anthropic" => Some(Self::Claude),
            "codex" | "chatgpt" => Some(Self::Codex),
            "gemini" | "google" => Some(Self::Gemini),
            "qwen" | "qwen-code" => Some(Self::Qwen),
            "gh" | "github" => Some(Self::Gh),
            _ => None,
        }
    }
}

/// Provider authorization operations.
#[derive(Debug, Subcommand)]
pub enum AuthOp {
    /// Adopt a login this machine already has, without a browser.
    ///
    /// Authorizing means "go get a new credential, interactively"; importing
    /// means "adopt one that already exists". They differ in prerequisites, in
    /// side effects, and in whether a human has to be present — which decides
    /// whether a headless deployment can be provisioned at all (issue #278).
    ///
    /// Runs on the deployment being provisioned: it installs into the
    /// credential home of the machine executing it, and no router accepts a
    /// credential over HTTP. With another router selected this refuses and
    /// names it, rather than answering about the local home (issue #291); use
    /// `auth claude` or `auth codex` to authorize a remote deployment.
    ///
    /// The per-provider flags on the authorize commands keep working.
    Import {
        /// Which login to adopt. Omit with `--all`.
        #[arg(
            value_enum,
            required_unless_present_any = ["all", "resume"],
            conflicts_with = "resume"
        )]
        provider: Option<ImportProvider>,
        /// Where to read it from. A named directory is read exactly as given.
        ///
        /// Omitted, it defaults to the vendor client's conventional directory —
        /// `~/.claude`, `~/.codex`, `~/.config/gh` — and there, on macOS for
        /// Claude, the login Keychain is consulted too and wins when it holds
        /// the newer credential. Naming a directory says *this* credential from
        /// *there*, so the machine-wide store is left out of it (issue #285).
        ///
        /// `$CLAUDE_CODE_HOME` and `$CODEX_HOME` are deliberately *not* the
        /// source: in a deployment they name this router's own credential
        /// directory — the destination — so reading the source through them
        /// would make every unqualified import refuse itself (issue #307). Pass
        /// the directory to read from another location.
        #[arg(requires = "provider", conflicts_with = "resume")]
        dir: Option<String>,
        /// Adopt every login this machine has.
        ///
        /// The case that motivates a verb: provisioning a deployment from a
        /// machine already logged in to several providers, without knowing each
        /// flag name and default path. Run it on that deployment — import
        /// writes the executing machine's credential home (issue #291).
        #[arg(long, conflicts_with_all = ["provider", "resume"])]
        all: bool,
        /// Install only if no recognized credential exists after taking the
        /// shared refresh/login lock.
        #[arg(long, conflicts_with = "all")]
        if_absent: bool,
        /// Assert support for non-destructive access-token validation and an
        /// atomic reference to one writable vendor-owned credential file.
        /// Older Router versions reject this spelling, allowing deployment
        /// tooling to fail closed before importing a credential.
        ///
        /// The internal field keeps its historical name for source
        /// compatibility; this flag never bypasses positive validation.
        #[arg(long = "safe-refresh-chain-import-v1")]
        force: bool,
        /// Require that the credential be *followed* rather than copied.
        ///
        /// A refresh token is a rotating series, not a value: whoever redeems a
        /// link invalidates it for every other holder. So a deployment holding
        /// its own copy and the vendor CLI beside it are two refreshers of one
        /// chain, and whichever loses the race is left with `invalid_grant` —
        /// which looks exactly like a revocation from the losing side (issue
        /// #574). Following installs a reference to the vendor client's own
        /// credential file instead, so both advance one chain: a rotation by
        /// either is seen by the other, with no re-import and no restart.
        ///
        /// This is already what an import does when it can. The flag makes it a
        /// requirement: if a reference cannot be established — the credential
        /// lives only in the platform keychain, names no writable source, or its
        /// directory cannot be written atomically — the import refuses and says
        /// which, rather than silently falling back to a copy that will drift.
        #[arg(long, conflicts_with = "snapshot")]
        follow: bool,
        /// Take a one-time copy instead of following the source.
        ///
        /// The historical behaviour for callers that want a credential frozen at
        /// import time, and a deployment that must not write to the source's
        /// directory at all. A copy drifts: the vendor client will rotate past
        /// it, so this is the shape that eventually needs a re-import.
        #[arg(long)]
        snapshot: bool,
        /// Emit one stable JSON result envelope instead of human-readable
        /// progress. Operational failures are represented in the envelope and
        /// still produce a non-zero exit status.
        #[arg(long)]
        json: bool,
        /// Retry one retained refresh-chain transaction by its opaque ID.
        ///
        /// Router resolves the private candidate directory; callers never need
        /// to discover or construct an internal filesystem path.
        #[arg(
            long,
            value_name = "TRANSACTION_ID",
            conflicts_with_all = ["provider", "dir", "all"]
        )]
        resume: Option<String>,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Remove a stored login from this deployment.
    ///
    /// Withdrawal is the most destructive thing this tool does and had no
    /// name: it was four flags, the widest of them attached to a command
    /// called `status`, so `auth --help` said nothing about it at all. The
    /// per-command `--clear` flags keep working (issue #305).
    ///
    /// Removes credentials on the machine it runs on. No router accepts a
    /// withdrawal over HTTP, so with another router selected this refuses and
    /// names it — silently rewriting "there" as "here" is unrecoverable for an
    /// OAuth credential, which then needs a fresh browser login on a machine
    /// that may not have a browser.
    Clear {
        /// Which login to remove: `claude`, `codex`, `gemini`, `qwen`, `gh`, or
        /// the name of a provider added through `providers add`. Omit with
        /// `--all`.
        ///
        /// A free-form name rather than a fixed enum: an API key stored by
        /// `providers add` authorizes this deployment against an upstream
        /// vendor exactly as an OAuth login does, and refusing to name one here
        /// left `auth` unable to withdraw a credential it reports (issue #561).
        #[arg(required_unless_present = "all")]
        provider: Option<String>,
        /// Remove every login this deployment holds.
        #[arg(long, conflicts_with = "provider")]
        all: bool,
        /// Confirm removing more than one credential without a prompt.
        #[arg(long)]
        yes: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Authorize an Anthropic Claude subscription.
    Claude {
        /// Supply the copied code without prompting on stdin.
        #[arg(long)]
        code: Option<String>,
        /// Force an OAuth flow instead of automatic selection.
        #[arg(long, value_parser = auth_flow_parser(&CLAUDE_AUTH_FLOWS), default_value = "auto")]
        flow: AuthFlow,
        /// Scope set to request: `full` (Claude Code `/login` equivalent) or
        /// `setup-token` for `user:inference` only. Defaults to what
        /// `LOGIN_CLI_ARGS` selects, then `full`.
        #[arg(long)]
        mode: Option<String>,
        /// Adopt an existing Claude login instead of authorizing.
        ///
        /// Reads the credential a vendor client already holds and installs it as
        /// this deployment's (issue #274). Default: `~/.claude`, where on macOS
        /// the login Keychain is consulted as well and wins when it is the live
        /// one. A directory named explicitly is read as given (issue #285).
        #[arg(long, value_name = "DIR", num_args = 0..=1, default_missing_value = "")]
        from_claude_home: Option<String>,
        /// Remove the stored credential instead of authorizing.
        #[arg(long, conflicts_with_all = ["code", "mode", "from_claude_home"])]
        clear: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Authorize an `OpenAI` Codex / `ChatGPT` subscription.
    Codex {
        /// Force an OAuth flow instead of automatic selection.
        #[arg(long, value_parser = auth_flow_parser(&CODEX_AUTH_FLOWS), default_value = "auto")]
        flow: AuthFlow,
        /// Local callback port registered for the Codex OAuth client.
        #[arg(long, default_value_t = 1455)]
        port: u16,
        /// Adopt an existing Codex login instead of authorizing.
        ///
        /// Default: `~/.codex` (issue #274).
        #[arg(long, value_name = "DIR", num_args = 0..=1, default_missing_value = "")]
        from_codex_home: Option<String>,
        /// Remove the stored credential instead of authorizing.
        #[arg(long, conflicts_with = "from_codex_home")]
        clear: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Store the GitHub credential the proxy presents upstream.
    ///
    /// The router mediates GitHub traffic on behalf of callers, so it needs an
    /// operator credential of its own. Reading it from a mounted `gh` config
    /// means a deployment can reuse an existing login instead of minting a
    /// separate token (issue #263).
    Gh {
        /// Read the credential from a mounted `gh` configuration directory
        /// (default: `$GH_CONFIG_DIR`, else `~/.config/gh`).
        #[arg(long, value_name = "DIR")]
        from_gh_config: Option<String>,
        /// Read the credential as one line from standard input instead.
        #[arg(long, conflicts_with = "from_gh_config")]
        token_stdin: bool,
        /// Report what is currently stored without changing it.
        #[arg(long, conflicts_with_all = ["from_gh_config", "token_stdin"])]
        status: bool,
        /// Remove the stored credential instead of storing one.
        #[arg(long, conflicts_with_all = ["from_gh_config", "token_stdin", "status"])]
        clear: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Report whether each provider credential is usable, expired, or absent.
    Status {
        /// Remove every stored credential, for decommissioning a deployment.
        ///
        /// Withdraws each provider's credential and the GitHub one in a single
        /// step, so an operator tearing down a test deployment does not have to
        /// know three separate paths (issue #268).
        /// `router auth clear --all` is the same operation with a name.
        #[arg(long = "clear-all")]
        clear_all: bool,
        /// Confirm removing more than one credential without a prompt.
        ///
        /// An OAuth login cannot be put back without a browser, and this is
        /// the widest blast radius in the tool — five credentials in one call,
        /// on a command called `status` (issue #305).
        #[arg(long, requires = "clear_all")]
        yes: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
}

/// What `auth gh` may do when a router other than this machine is selected.
///
/// A GitHub credential is read from the router's own data directory at startup
/// and no endpoint accepts one over HTTP, so there is nothing to store
/// remotely. Acting locally under a success message is what left a workstation
/// holding a token it never needed while the targeted deployment had none
/// (issue #283), so storing refuses and only the read-only query answers.
#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub enum RemoteGh {
    /// Report this machine's credential, saying whose it is.
    DescribeLocal,
    /// Refuse: the credential cannot reach the selected router from here.
    Refuse,
}

impl AuthOp {
    /// What this `auth gh` invocation may do against a selected router.
    ///
    /// `None` for anything that is not `auth gh`.
    #[must_use]
    pub const fn remote_gh(&self) -> Option<RemoteGh> {
        match self {
            Self::Gh { status: true, .. } => Some(RemoteGh::DescribeLocal),
            Self::Gh { .. } => Some(RemoteGh::Refuse),
            _ => None,
        }
    }
}

/// Whether an `auth import` invocation may act on the machine running it.
///
/// Import installs into the credential home of the executing machine, and no
/// router accepts a credential document over HTTP, so an import aimed at a
/// different deployment has nothing it can do. Deciding that here — beside the
/// flags it reads — keeps the rule unit-testable rather than reachable only by
/// spawning the binary against a live server (issue #291).
///
/// `None` for anything that is not an `import`: the per-provider
/// `--from-*-home` flags carry no target of their own.
#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub enum ImportTarget {
    /// Act here: `--local`, `--managed`, or no selection at all.
    Local,
    /// A different router was named or selected; resolve it and refuse.
    Remote,
}

impl AuthOp {
    /// Whether this `auth import` may install into the local credential home.
    ///
    /// Answers from the flags alone. A bare invocation is [`Self::may_be_remote`]
    /// because a *persisted* selection also counts as naming a target, which
    /// only resolution can determine.
    #[must_use]
    pub const fn import_target(&self) -> Option<ImportTarget> {
        match self {
            Self::Import { target, .. } => {
                if target.local || target.managed {
                    Some(ImportTarget::Local)
                } else {
                    Some(ImportTarget::Remote)
                }
            }
            _ => None,
        }
    }

    /// Whether this invocation must resolve a target before importing.
    ///
    /// `false` short-circuits resolution entirely, so `--local` never contacts
    /// a server and never fails because one is unreachable.
    #[must_use]
    pub const fn may_be_remote(&self) -> bool {
        matches!(self.import_target(), Some(ImportTarget::Remote))
    }
}

/// Which router an `auth` command acts on.
///
/// `auth` used to always write a local credential even when a server was
/// selected, so the obvious `server use` → `auth` → `with` sequence left the
/// targeted router unauthorized and failed later as a 401 (issue #246). The
/// default now follows the selection, exactly as `with` does; these make the
/// choice explicit when the default is not what is wanted.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct AuthTarget {
    /// Act on this machine even when a server is selected.
    #[arg(long, conflicts_with = "server")]
    pub local: bool,
    /// Act on this router instead of the selected one.
    #[arg(long, value_name = "URL", conflicts_with = "local")]
    pub server: Option<String>,
    /// Private management origin when it differs from the inference origin.
    #[arg(long, value_name = "URL", conflicts_with = "local")]
    pub management_server: Option<String>,
    /// Start a disposable managed container even if a router is already
    /// listening locally (issue #250).
    ///
    /// Accepted by the commands that can use one — `with`, `configure` and
    /// `auth`. The families that only read or change router state refuse it
    /// and name `--local`, because there it started nothing and quietly meant
    /// `--local` anyway (issue #315).
    #[arg(long, conflicts_with_all = ["local", "server", "management_server"])]
    pub managed: bool,
}

/// TLS subcommands.
///
/// The artefact `ca` prints is a trust anchor, so answering for the wrong
/// machine does not produce a wrong report — it produces trust in the wrong
/// key. `tls` therefore takes the same target flags as every other
/// state-touching family, and says so when it cannot answer for the target
/// (issue #308).
#[derive(Debug, Subcommand)]
pub enum TlsOp {
    /// Print the generated certificate in PEM form.
    ///
    /// A client that must trust a self-signed router reads it from here, so a
    /// private-network deployment can distribute trust without a CA (issue
    /// #263).
    Ca {
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Generate the self-signed certificate without starting the server.
    Generate {
        /// Names the certificate is valid for, comma-separated. A sidecar is
        /// reached by its network alias, so that name must be present.
        #[arg(long, value_name = "NAMES", default_value = "localhost")]
        dns: String,
        #[command(flatten)]
        target: AuthTarget,
    },
}

impl TlsOp {
    /// Which router this certificate operation acts on.
    #[must_use]
    pub const fn target(&self) -> &AuthTarget {
        match self {
            Self::Ca { target } | Self::Generate { target, .. } => target,
        }
    }
}

//! `clients` subcommands.
//!
//! Split from `cli.rs` to keep that file within the repository's 1000-line
//! limit.

use clap::{Args, Subcommand, ValueEnum};

use crate::clients::ClientKind;
use std::path::PathBuf;

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, ValueEnum)]
pub enum ProfileSelection {
    #[default]
    Normal,
    Router,
    Both,
}

#[derive(Debug, Args)]
pub struct ClientSelection {
    #[arg(value_enum, required_unless_present = "all")]
    pub client: Option<ClientKind>,
    #[arg(long, conflicts_with = "client")]
    pub all: bool,
    #[arg(long, value_enum, default_value_t = ProfileSelection::Normal)]
    pub profile: ProfileSelection,
}

#[derive(Debug, Subcommand)]
pub enum BackupOp {
    /// Copy selected local profiles into a verified, owner-only backup.
    Create {
        #[command(flatten)]
        selection: ClientSelection,
        #[arg(long, value_name = "DIR")]
        destination: Option<PathBuf>,
        /// Include local credential files; the backup remains unencrypted and must stay local.
        #[arg(long)]
        include_credentials: bool,
    },
    /// List complete backups in the default local backup directory.
    List {
        #[arg(long)]
        json: bool,
        #[arg(long, value_name = "DIR")]
        destination: Option<PathBuf>,
    },
    /// Verify every file, inventory entry, permission and a sample restore.
    Verify {
        id: String,
        #[arg(long, value_name = "DIR")]
        destination: Option<PathBuf>,
    },
    /// Restore a verified backup. Merge is the default.
    Restore {
        id: String,
        #[arg(long, value_enum)]
        client: Option<ClientKind>,
        #[arg(long, conflicts_with = "overwrite")]
        merge: bool,
        #[arg(long)]
        overwrite: bool,
        #[arg(long)]
        dry_run: bool,
        #[arg(long, requires = "overwrite")]
        yes: bool,
        #[arg(long, value_name = "DIR")]
        destination: Option<PathBuf>,
    },
}

#[derive(Debug, Args)]
pub struct MaintenanceArgs {
    #[command(flatten)]
    pub selection: ClientSelection,
    #[arg(long)]
    pub dry_run: bool,
    #[arg(long)]
    pub json: bool,
    #[arg(long, conflicts_with = "channel")]
    pub latest: bool,
    #[arg(long, conflicts_with = "latest")]
    pub channel: Option<String>,
    /// Required for a fresh install when no existing installation identifies a method.
    #[arg(long)]
    pub method: Option<String>,
    #[arg(long)]
    pub yes: bool,
}

#[derive(Debug, Subcommand)]
pub enum ClientOp {
    /// Create, inspect, verify and restore local client backups.
    Backup {
        #[command(subcommand)]
        op: BackupOp,
    },
    /// Reset preferences or, with --full, the selected local profile.
    Reset {
        #[command(flatten)]
        selection: ClientSelection,
        #[arg(long)]
        dry_run: bool,
        #[arg(long)]
        full: bool,
        #[arg(long, requires = "full")]
        yes: bool,
        #[arg(long)]
        json: bool,
    },
    /// Install a client using an explicitly selected vendor method.
    Install(MaintenanceArgs),
    /// Update an installed client using its detected method and channel.
    Update(MaintenanceArgs),
    /// Reinstall an installed client after a verified profile backup.
    Reinstall(MaintenanceArgs),
    /// List supported clients and their local installation/configuration state.
    List {
        /// Emit JSON instead of the table (issue #314).
        #[arg(long)]
        json: bool,
    },
    /// Merge this router into a client's user configuration.
    ///
    /// `router configure <client>` is the name for this, and the one that
    /// follows the server selection. `create` and `add` are accepted here too
    /// (issues #296, #314).
    #[command(alias = "create", alias = "add")]
    Setup {
        #[arg(value_enum)]
        client: ClientKind,
        /// Existing router token. Prefer `--token-stdin` or
        /// `LINK_ASSISTANT_ROUTER_TOKEN` over argv, which is visible in shell
        /// history and process listings.
        #[arg(long, hide_env_values = true, conflicts_with = "token_stdin")]
        token: Option<String>,
        /// Read an existing router token as one line from standard input.
        #[arg(long, conflicts_with = "token")]
        token_stdin: bool,
        /// Router URL reachable from the client.
        ///
        /// Spelled `--server` like everywhere else the router's own URL is
        /// named; `--base-url` means the *upstream's* URL in `providers add`,
        /// so one flag referred to two different machines depending on the
        /// family (issue #314). The old spelling is still accepted.
        #[arg(long = "server", alias = "base-url", value_name = "URL")]
        base_url: Option<String>,
        /// Private management origin when it differs from the client-facing
        /// inference origin.
        #[arg(long, value_name = "URL", requires = "base_url")]
        management_server: Option<String>,
        /// Lifetime of an automatically minted token.
        #[arg(long, default_value_t = 24)]
        ttl_hours: i64,
    },
    /// Show the effective client integration with secrets redacted.
    Show {
        #[arg(value_enum)]
        client: ClientKind,
        /// Accepted for symmetry with `list`: `show` already emits JSON, so
        /// this changes nothing (issue #314). A script should not have to know
        /// which verb of a family takes the flag.
        #[arg(long)]
        json: bool,
    },
    /// Remove only settings managed by this router.
    ///
    /// `delete` and `revoke` are accepted too (issue #314).
    #[command(alias = "delete", alias = "revoke")]
    Remove {
        #[arg(value_enum)]
        client: ClientKind,
        /// Also revoke a token that was supplied by the operator instead of
        /// minted by `clients setup`. Off by default because the same token
        /// is often shared with other machines.
        #[arg(long)]
        revoke_supplied: bool,
        /// Delete the local settings even when the managed token could not be
        /// revoked. The credential stays usable until it expires.
        #[arg(long)]
        force: bool,
    },
    /// Reconcile routing-critical client settings with the selected Router.
    Repair {
        /// One client to repair. Use --all to inspect or repair every client.
        #[arg(value_enum, required_unless_present = "all")]
        client: Option<ClientKind>,
        /// Inspect or repair every documented client independently.
        #[arg(long, conflicts_with = "client")]
        all: bool,
        /// Print the secret-free plan without network access or filesystem writes.
        #[arg(long)]
        dry_run: bool,
        /// Emit stable machine-readable output.
        #[arg(long)]
        json: bool,
        /// Restore an earlier repair snapshot after verifying no later edits exist.
        #[arg(
            long,
            value_name = "BACKUP_ID",
            requires = "client",
            conflicts_with_all = ["all", "dry_run"]
        )]
        rollback: Option<String>,
    },
    /// Make a real request using the client's configured URL and token variable.
    ///
    /// The probe is deliberately the cheapest the dialect accepts: a 64-token
    /// budget, reasoning at the lowest tier, and a two-word prompt. It still
    /// costs a request against the subscription, because proving the route
    /// works means using it (issues #275, #309).
    Doctor {
        #[arg(value_enum)]
        client: ClientKind,
    },
}

//! `router configure <client>` — the one name for permanent client setup.
//!
//! Pointing a client at the router permanently is the first thing an operator
//! does after standing a deployment up, and it had no single name. Two
//! commands wrote the same file and disagreed on almost everything else: the
//! address (`clients setup` used this CLI's own `--host`/`--port` default even
//! with a server selected), the credential (`with --global` stored none and
//! told the user to go set an environment variable), how to reverse it, and
//! which clients it worked for. `configure` exists in the codebase — it is
//! what both paths call — but was not a name a user could type (issue #296).

use clap::Args;

use super::AuthTarget;
use crate::clients::ClientKind;

/// Point a client at the router permanently.
#[derive(Clone, Debug, Args)]
pub struct ConfigureArgs {
    /// Client to configure. Omit when `--all` is given.
    #[arg(value_enum, required_unless_present = "all")]
    pub client: Option<ClientKind>,
    /// Configure every client this machine has that can be configured.
    ///
    /// Clients whose vendor gates prevent it are skipped and named in the
    /// summary rather than failing the run — a workstation being pointed at a
    /// deployment wants the ones that work.
    #[arg(long, conflicts_with = "client")]
    pub all: bool,
    /// Restore the exact configuration saved by a previous `configure`.
    ///
    /// The restore is hash-verified: an edit made after `configure` is
    /// preserved rather than overwritten.
    #[arg(long)]
    pub undo: bool,
    #[command(flatten)]
    pub target: AuthTarget,
    /// Existing router token to configure instead of minting one.
    ///
    /// Prefer `--token-stdin` or `LINK_ASSISTANT_ROUTER_TOKEN` over argv,
    /// which is visible in shell history and process listings.
    #[arg(long, hide_env_values = true, conflicts_with = "token_stdin")]
    pub token: Option<String>,
    /// Read an existing router token as one line from standard input.
    #[arg(long, conflicts_with = "token")]
    pub token_stdin: bool,
    /// Lifetime of an automatically minted token, in hours.
    ///
    /// A year by default, because this is the permanent path: a credential
    /// that lapses next week makes "configured" mean "configured until
    /// Tuesday". Re-run `configure` to renew it.
    #[arg(long, default_value_t = 8760)]
    pub ttl_hours: i64,
}

impl ConfigureArgs {
    /// The clients this invocation acts on.
    #[must_use]
    pub fn clients(&self) -> Vec<ClientKind> {
        self.client
            .map_or_else(|| ClientKind::ALL.to_vec(), |client| vec![client])
    }
}

//! `deploy` and `usage` command arguments.
//!
//! Split from `cli.rs` to keep that file within the repository's 1000-line
//! limit.

use clap::{Args, ValueEnum};

/// What a `router deploy` run should do.
#[derive(Clone, Debug, Args)]
pub struct DeployArgs {
    /// Restore a non-OAuth data checkpoint to a stopped local deployment.
    /// Existing records/files take precedence unless --replace-state is set.
    #[arg(long, value_name = "DIR", requires = "yes", conflicts_with_all = ["server", "staging", "mode", "status", "down", "force_update", "accept_access_loss", "claude_credentials", "build"])]
    pub restore_state: Option<std::path::PathBuf>,
    /// Replace covered data with the checkpoint after retaining a new backup.
    #[arg(long, requires = "restore_state")]
    pub replace_state: bool,
    /// Create or inspect an isolated local candidate namespace. Never shares
    /// primary data, OAuth ownership, tokens, ports or selected client profiles.
    #[arg(long, value_name = "NAME", conflicts_with_all = ["server", "mode", "claude_credentials", "force_update"])]
    pub staging: Option<String>,
    /// Read-only machine-readable staging verification (no paid probes).
    #[arg(long, requires = "staging", conflicts_with_all = ["down", "status"])]
    pub verify: bool,
    /// Machine-readable result: the staging report, or with `--server` a
    /// `link-assistant-router/deploy/v1` document with per-step and
    /// per-subprocess timings, provider-key and verification results.
    #[arg(long)]
    pub json: bool,
    /// SSH destination on which to converge the deployment.
    ///
    /// The destination uses OpenSSH's ordinary `user@host`/config-alias
    /// syntax. Credentials are discovered on that host and are never copied
    /// from the machine running this command.
    #[arg(long, value_name = "TARGET")]
    pub server: Option<String>,
    /// Report the current state without changing anything.
    ///
    /// The question "what is missing?" must be answerable without provisioning
    /// anything, so this makes no mutating call at all — a property its tests
    /// assert by comparing the container id and image digest across the run.
    #[arg(long, conflicts_with = "down")]
    pub status: bool,
    /// Remove what this command created, and nothing else.
    #[arg(long)]
    pub down: bool,
    /// Confirm a destructive action, for unattended use.
    ///
    /// Removing a deployment leaves its issued tokens and request log behind or
    /// loses them, so it is confirmed rather than assumed.
    #[arg(long)]
    pub yes: bool,
    /// Permit a local update that cannot preserve every identified run.
    ///
    /// The affected connection or run ids are printed before any serving
    /// object changes. This is deliberately local: remote deploy already owns
    /// a stable relay and has no legacy in-place container to migrate.
    #[arg(
        long,
        conflicts_with_all = ["server", "status", "down"],
    )]
    pub force_update: bool,
    /// Explicitly accept provider/catalog loss reported by candidate validation.
    /// Connection interruption permission alone does not authorize access loss.
    #[arg(long, conflicts_with_all = ["server", "staging", "status", "down"])]
    pub accept_access_loss: bool,
    /// Published host port.
    /// Defaults to 8080, or to `port` in `--config`.
    #[arg(long)]
    pub port: Option<u16>,
    /// Public TLS port exposing inference only.
    ///
    /// Management remains on the loopback-only `--port` listener. The remote
    /// verifier trusts the deployment's generated CA rather than disabling
    /// certificate validation.
    #[arg(long)]
    pub public_port: Option<u16>,
    /// Image to deploy. Must be a release tag or digest, never a moving ref.
    ///
    /// A moving reference lets the CLI and the container disagree about the API
    /// contract while both look correct, so one is refused with the reason.
    #[arg(long)]
    pub image: Option<String>,
    /// Build the image from this context when it is not present.
    ///
    /// With `--server`, this is a path on the target, never a directory copied
    /// over SSH. Without it, the target builds this Router's pinned release
    /// tag itself.
    #[arg(long, value_name = "DIR")]
    pub build: Option<String>,
    /// Root holding the deployment's credential and data directories.
    ///
    /// Two directories, not one: credentials remain isolated from mutable
    /// Router data and its request log.
    #[arg(long, value_name = "DIR")]
    pub root: Option<String>,
    /// Whether the backend uses this machine's Claude Code login.
    ///
    /// `share` mounts the Claude Code home (`$CLAUDE_CONFIG_DIR` or
    /// `~/.claude`) read-write, as its owner, so the host CLI and Router
    /// advance one rotating refresh chain. Nothing is copied. A login the
    /// container cannot share (macOS Keychain, empty, unreadable) is refused
    /// with the reason before anything changes. Without this flag an update
    /// keeps the mode the active deployment uses; a first deploy is isolated.
    #[arg(long, value_enum, conflicts_with_all = ["server", "down"])]
    pub claude_credentials: Option<ClaudeCredentials>,
    /// Where the local Router process runs (issue #626).
    ///
    /// `host` runs this Router binary on the host, on the same loopback port
    /// and with the same data directory as the container deployment, so it
    /// reads a Claude Code login kept in the macOS Keychain. The containers
    /// are stopped, not removed, and `--mode container` restores them. With
    /// `--status` the migration plan is printed without changing anything.
    /// Without this flag a deploy keeps the current mode.
    #[arg(long, value_enum, conflicts_with_all = ["server", "down"])]
    pub mode: Option<DeployMode>,
    /// Supervise the host deployment with a launchd agent or a systemd user
    /// unit that restarts the same binary on the same data directory and
    /// port (issue #684). The signing secret is read from a `0600` file
    /// through `TOKEN_SECRET_FILE`; it is never in the unit or in argv.
    #[arg(long, conflicts_with_all = ["server", "staging", "status", "down", "restore_state", "uninstall_service"])]
    pub install_service: bool,
    /// Disable and remove the service `--install-service` wrote, and its
    /// secret file. The running Router is stopped only if the service
    /// started it.
    #[arg(long, conflicts_with_all = ["server", "staging", "status", "down", "restore_state", "mode"])]
    pub uninstall_service: bool,
    /// Settings that can also come from `--config` (issues #679, #680, #683).
    #[command(flatten)]
    pub settings: super::DeploySettingsArgs,
}

impl DeployArgs {
    /// The published port: `--port`, else the default.
    #[must_use]
    pub fn port(&self) -> u16 {
        self.port.unwrap_or(crate::deploy::DEFAULT_PORT)
    }
}

/// Where a local deployment serves from.
#[derive(Clone, Copy, Debug, PartialEq, Eq, ValueEnum)]
pub enum DeployMode {
    /// Versioned backends behind a loopback relay container.
    Container,
    /// One Router process on the host, reading the host's own logins.
    Host,
}

/// How a local deployment's backend obtains the Anthropic credential.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, ValueEnum)]
pub enum ClaudeCredentials {
    /// Only the deployment's own `<root>/credentials`, mounted read-only.
    #[default]
    Isolated,
    /// The host's Claude Code home, shared read-write without copying.
    Share,
}

/// Which subscription's remaining limits to report.
#[derive(Debug, Args)]
pub struct UsageArgs {
    /// Public subscription provider name.
    #[arg(value_enum)]
    pub provider: Option<crate::subscription_usage::UsageProvider>,
    /// Emit the stable machine-readable Router response.
    #[arg(long)]
    pub json: bool,
    #[command(flatten)]
    pub target: super::AuthTarget,
}

//! `router deploy` settings shared with `--config` (issues #679, #680, #683).
//!
//! Every flag here has a key in the deploy configuration file; a flag given
//! on the command line wins over the file. Secret values are never flag
//! values: `--env` and `--provider-key` name a source (`env:VAR` or
//! `file:PATH`), read when the deployment runs.

use std::path::PathBuf;

use clap::Args;

use crate::deploy_config::ProviderKeyMode;

/// Deployment settings that can also come from `--config`.
#[derive(Clone, Debug, Default, Args)]
pub struct DeploySettingsArgs {
    /// Declarative deploy configuration (TOML). Flags override its keys.
    #[arg(long, value_name = "FILE")]
    pub config: Option<PathBuf>,
    /// Deploy to the `server` named in `--config` (`[remote]` or `[deploy]`).
    #[arg(long, conflicts_with_all = ["server", "staging", "mode"])]
    pub remote: bool,
    /// Instance name, so several deployments can share one host. Suffixes the
    /// relay, network and backend names and the default root.
    #[arg(long, value_name = "NAME")]
    pub instance: Option<String>,
    /// Pass a runtime variable to the backend: `NAME` (from this
    /// environment), `NAME=env:VAR` or `NAME=file:PATH`. Repeatable. Values
    /// never reach argv; a changed value reconciles the deployment.
    #[arg(long = "env", value_name = "NAME[=SOURCE]")]
    pub env: Vec<String>,
    /// SSH port for `--server`.
    #[arg(long, value_name = "PORT")]
    pub ssh_port: Option<u16>,
    /// SSH identity file for `--server` (with `IdentitiesOnly=yes`).
    #[arg(long, value_name = "FILE")]
    pub ssh_identity: Option<PathBuf>,
    /// Pinned `known_hosts` file: only its keys are trusted for `--server`.
    #[arg(long, value_name = "FILE")]
    pub ssh_known_hosts: Option<PathBuf>,
    /// SSH keepalive interval in seconds (`ServerAliveInterval`).
    #[arg(long, value_name = "SECONDS")]
    pub ssh_keepalive: Option<u32>,
    /// Overall remote session deadline in seconds. Exceeding it ends the
    /// session with exit code 12.
    #[arg(long, value_name = "SECONDS")]
    pub deadline: Option<u64>,
    /// Lifetime of the client token deploy issues.
    #[arg(long, value_name = "HOURS")]
    pub token_ttl_hours: Option<i64>,
    /// Request cap for the client token deploy issues.
    #[arg(long, value_name = "N")]
    pub token_max_requests: Option<u64>,
    /// Token (input plus output) cap for the client token deploy issues.
    #[arg(long, value_name = "N")]
    pub token_max_tokens: Option<u64>,
    /// Requests per minute for the client token deploy issues.
    #[arg(long, value_name = "N")]
    pub token_rate_limit: Option<u64>,
    /// Exact model the issued client token may request. Repeatable.
    #[arg(long, value_name = "MODEL")]
    pub token_allowed_model: Vec<String>,
    /// Provider key to verify in the candidate before cutover:
    /// `NAME=env:VAR` or `NAME=file:PATH`. Repeatable. `--server` only.
    #[arg(long, value_name = "NAME=SOURCE")]
    pub provider_key: Vec<String>,
    /// What to do with `--provider-key` keys after validation.
    #[arg(long, value_enum, value_name = "MODE")]
    pub provider_key_mode: Option<ProviderKeyMode>,
    /// Verification profile (TOML): clients, providers and exact models that
    /// must be proven before cutover. `--server` only.
    #[arg(long, value_name = "FILE")]
    pub verification_profile: Option<PathBuf>,
    /// Hand this machine's login for a subscription to the new deployment:
    /// `claude` (`anthropic`) or `codex` (`chatgpt`). Repeatable. The refresh
    /// chain is moved, not forked: the local source is marked handed over
    /// and the document travels on SSH stdin. `--server` only.
    #[arg(long = "seed-credential", value_name = "PROVIDER")]
    pub seed_credential: Vec<String>,
}

impl DeploySettingsArgs {
    /// Whether any setting from this group was given on the command line.
    #[must_use]
    pub const fn any(&self) -> bool {
        self.config.is_some()
            || self.remote
            || self.instance.is_some()
            || !self.env.is_empty()
            || self.ssh_port.is_some()
            || self.ssh_identity.is_some()
            || self.ssh_known_hosts.is_some()
            || self.ssh_keepalive.is_some()
            || self.deadline.is_some()
            || self.token_ttl_hours.is_some()
            || self.token_max_requests.is_some()
            || self.token_max_tokens.is_some()
            || self.token_rate_limit.is_some()
            || !self.token_allowed_model.is_empty()
            || !self.provider_key.is_empty()
            || self.provider_key_mode.is_some()
            || self.verification_profile.is_some()
            || !self.seed_credential.is_empty()
    }
}

//! Flags for the explicit, bounded emergency any-token mode (issue #645).

use super::value_parsers::parse_truthy;
use crate::emergency_auth::{DEFAULT_DURATION_MINUTES, EmergencyAuthConfig};

/// `--emergency-*` switches. Every one is off or at its safe default unless
/// given; none is read from a persisted deployment setting.
#[derive(clap::Args, Debug, Clone, Default)]
pub struct EmergencyArgs {
    /// EMERGENCY ONLY: accept any non-empty client token on client routes
    /// for a bounded time. Off by default; management routes keep normal
    /// admin authentication, no token record is read, written, rotated or
    /// revived, and every bypassed request is logged and counted. See
    /// `docs/security/emergency-auth.md`.
    #[arg(
        long,
        env = "EMERGENCY_ACCEPT_ANY_TOKEN",
        hide_env_values = true,
        num_args = 0..=1,
        default_value_t = false,
        default_missing_value = "true",
        value_parser = parse_truthy
    )]
    pub emergency_accept_any_token: bool,

    /// Acknowledge that emergency any-token mode is served on a non-loopback
    /// listener. Without it the router refuses to start in emergency mode
    /// unless every listener is bound to loopback.
    #[arg(
        long,
        env = "EMERGENCY_ALLOW_NON_LOOPBACK",
        num_args = 0..=1,
        default_value_t = false,
        default_missing_value = "true",
        value_parser = parse_truthy
    )]
    pub emergency_allow_non_loopback: bool,

    /// Minutes after which emergency any-token mode switches itself off
    /// (1..=1440).
    #[arg(
        long,
        env = "EMERGENCY_DURATION_MINUTES",
        default_value_t = DEFAULT_DURATION_MINUTES
    )]
    pub emergency_duration_minutes: u64,
}

impl EmergencyArgs {
    /// The resolved configuration.
    #[must_use]
    pub const fn config(&self) -> EmergencyAuthConfig {
        EmergencyAuthConfig {
            enabled: self.emergency_accept_any_token,
            allow_non_loopback: self.emergency_allow_non_loopback,
            duration_minutes: self.emergency_duration_minutes,
        }
    }
}

