    pub fn config(&self) -> Result<CatalogSourcesConfig, String> {
        let config = CatalogSourcesConfig {
            sources: self
                .sources
                .iter()
                .map(|source| source.trim())
                .filter(|source| !source.is_empty())
                .map(str::to_string)
