//! Account-pool failover, threshold pause, warmup and per-account connection
//! flags (issues #676, #677, #678).

use std::collections::BTreeMap;

use super::value_parsers::parse_truthy;
use crate::account_http::{
    AccountHttpPolicy, DEFAULT_ACCOUNT_CONNECTION_MAX_AGE_SECS,
    DEFAULT_ACCOUNT_POOL_IDLE_TIMEOUT_SECS, EgressProxy, parse_egress_proxies,
};
use crate::pool_failover::{
    DEFAULT_BUDGET_SECS, DEFAULT_MAX_ATTEMPTS, FailoverMode, PoolPolicy, parse_percent,
};

/// `--pool-failover*`, `--account-pause-at-percent` and `--intercept-warmup`.
/// Every one defaults to the historical behaviour.
#[derive(clap::Args, Debug, Clone)]
pub struct PoolArgs {
    /// Retry a pooled request on the next eligible account when the upstream
    /// answers 429, 529, a retryable 5xx, a transport error, or 401 after a
    /// failed refresh — only before the first response byte reaches the
    /// client. `off` (default) or `pre-first-byte`.
    #[arg(
        long,
        env = "POOL_FAILOVER",
        default_value = "off",
        value_parser = FailoverMode::parse,
        global = true
    )]
    pub pool_failover: Option<FailoverMode>,

    /// Upstream attempts per round under pool failover, the first included.
    #[arg(
        long,
        env = "POOL_FAILOVER_MAX_ATTEMPTS",
        default_value_t = DEFAULT_MAX_ATTEMPTS,
        value_parser = clap::value_parser!(u32).range(1..=16),
        global = true
    )]
    pub pool_failover_max_attempts: u32,

    /// Seconds after which pool failover stops trying further accounts.
    #[arg(
        long,
        env = "POOL_FAILOVER_BUDGET_SECS",
        default_value_t = DEFAULT_BUDGET_SECS,
        global = true
    )]
    pub pool_failover_budget_secs: u64,

    /// Additional credential retry rounds before any response body is relayed.
    #[arg(long, env = "POOL_RETRY_ROUNDS", default_value_t = 0, value_parser = clap::value_parser!(u32).range(0..=16), global = true)]
    pub pool_retry_rounds: u32,

    /// Distinct credentials per retry round; zero adds no credential cap.
    #[arg(
        long,
        env = "POOL_MAX_RETRY_CREDENTIALS",
        default_value_t = 0,
        global = true
    )]
    pub pool_max_retry_credentials: u32,

    /// Maximum seconds to wait for a cooldown between retry rounds.
    #[arg(
        long,
        env = "POOL_MAX_RETRY_INTERVAL_SECS",
        default_value_t = 30,
        global = true
    )]
    pub pool_max_retry_interval_secs: u64,

    /// Maximum observed cooldown, including vendor resets; bounded to eight days.
    #[arg(long, env = "ACCOUNT_MAX_COOLDOWN_SECS", default_value_t = crate::account_limits::MAX_VENDOR_COOLDOWN.as_secs(), global = true)]
    pub account_max_cooldown_secs: u64,

    /// Bind subagent sessions to their parent's account when it is known.
    #[arg(long, env = "SESSION_AFFINITY_SUBAGENTS", num_args = 0..=1, default_value_t = true, default_missing_value = "true", value_parser = parse_truthy, global = true)]
    pub session_affinity_subagents: bool,

    /// Pause a pooled account once a vendor rate-limit window reports this
    /// utilization percentage (1-100) or more; it resumes when the window
    /// resets. Unset never pauses.
    #[arg(
        long,
        env = "ACCOUNT_PAUSE_AT_PERCENT",
        value_parser = parse_percent,
        global = true
    )]
    pub account_pause_at_percent: Option<u8>,

    /// Answer Claude Code's "Warmup" probe locally with a synthetic message
    /// instead of spending subscription quota on it.
    #[arg(
        long,
        env = "INTERCEPT_WARMUP",
        num_args = 0..=1,
        default_value_t = false,
        default_missing_value = "true",
        value_parser = parse_truthy,
        global = true
    )]
    pub intercept_warmup: bool,

    /// Seconds an idle upstream connection of a pooled account stays open.
    /// Every account has its own connection pool. `0` keeps idle connections.
    #[arg(
        long,
        env = "ACCOUNT_POOL_IDLE_TIMEOUT_SECS",
        default_value_t = DEFAULT_ACCOUNT_POOL_IDLE_TIMEOUT_SECS,
        global = true
    )]
    pub account_pool_idle_timeout_secs: u64,

    /// Seconds after which a pooled account's upstream client is rotated, so
    /// no connection outlives it; in-flight requests finish on the old one.
    /// `0` never rotates.
    #[arg(
        long,
        env = "ACCOUNT_CONNECTION_MAX_AGE_SECS",
        default_value_t = DEFAULT_ACCOUNT_CONNECTION_MAX_AGE_SECS,
        global = true
    )]
    pub account_connection_max_age_secs: u64,

    /// Per-account egress proxies: comma-separated `ACCOUNT=SPEC`, where
    /// `ACCOUNT` is `primary`, `account-1`, ... and `SPEC` is `env:VAR` or
    /// `file:PATH` holding the proxy URL, or a password-less
    /// `http://`, `https://`, `socks5://` or `socks5h://` URL optionally
    /// followed by `;password-env=VAR` or `;password-file=PATH`. A URL
    /// carrying a password is refused so no secret reaches argv.
    #[arg(
        long,
        env = "ACCOUNT_EGRESS_PROXY",
        value_parser = parse_egress_proxies,
        global = true
    )]
    pub account_egress_proxy: Option<EgressProxies>,
}

/// Parsed `--account-egress-proxy`.
pub type EgressProxies = BTreeMap<String, EgressProxy>;

impl Default for PoolArgs {
    fn default() -> Self {
        Self {
            pool_failover: None,
            pool_failover_max_attempts: 0,
            pool_failover_budget_secs: 0,
            pool_retry_rounds: 0,
            pool_max_retry_credentials: 0,
            pool_max_retry_interval_secs: 30,
            account_max_cooldown_secs: crate::account_limits::MAX_VENDOR_COOLDOWN.as_secs(),
            session_affinity_subagents: true,
            account_pause_at_percent: None,
            intercept_warmup: false,
            account_pool_idle_timeout_secs: 0,
            account_connection_max_age_secs: 0,
            account_egress_proxy: None,
        }
    }
}

impl PoolArgs {
    /// The resolved policy.
    #[must_use]
    pub fn policy(&self) -> PoolPolicy {
        PoolPolicy {
            failover: self.pool_failover.unwrap_or_default(),
            max_attempts: self.pool_failover_max_attempts.max(1),
            budget: std::time::Duration::from_secs(self.pool_failover_budget_secs),
            pause_at_percent: self.account_pause_at_percent,
            intercept_warmup: self.intercept_warmup,
            retry: crate::pool_retry::RetryPolicy {
                rounds: self.pool_retry_rounds,
                max_credentials: self.pool_max_retry_credentials,
                max_interval: std::time::Duration::from_secs(self.pool_max_retry_interval_secs),
            },
            session_affinity_subagents: self.session_affinity_subagents,
            max_cooldown: std::time::Duration::from_secs(self.account_max_cooldown_secs)
                .min(crate::account_limits::MAX_VENDOR_COOLDOWN),
            account_http: AccountHttpPolicy::new(
                self.account_pool_idle_timeout_secs,
                self.account_connection_max_age_secs,
                self.account_egress_proxy.clone().unwrap_or_default(),
            ),
        }
    }
}

//! `tokens`, `accounts` and `providers` subcommands.
//!
//! Split from `cli.rs` to keep that file within the repository's 1000-line
//! limit.

use std::path::PathBuf;

use clap::Subcommand;

use super::AuthTarget;

#[derive(Debug, Subcommand)]
pub enum TokenOp {
    /// Issue a new token and print it to stdout.
    ///
    /// `create` and `add` are accepted too: creating something was `tokens
    /// issue`, `providers add` and `clients setup` — three verbs for one idea
    /// (issue #314).
    #[command(alias = "create", alias = "add")]
    Issue {
        #[arg(long, default_value_t = 24)]
        ttl_hours: i64,
        #[arg(long, default_value = "")]
        label: String,
        #[arg(long)]
        account: Option<String>,
        /// Cap on the number of upstream requests this token may make.
        /// Omit for an unlimited token.
        #[arg(long)]
        max_requests: Option<u64>,
        /// Cap on actual input plus output tokens reported by upstreams.
        /// Omit for unlimited spend.
        #[arg(long)]
        max_tokens: Option<u64>,
        /// Maximum requests admitted per one-minute window.
        #[arg(long)]
        rate_limit_per_minute: Option<u64>,
        /// Issue an administrative token (`scope: admin`) that unlocks the
        /// admin endpoints instead of only the inference proxy.
        #[arg(long)]
        admin: bool,
        /// Restrict this token's GitHub proxy access to `owner/repo`. Repeat
        /// for several repositories; omit for unrestricted access, which is
        /// the default and what every existing token keeps.
        #[arg(long = "github-repo", value_name = "OWNER/REPO")]
        github_repo: Vec<String>,
        /// Exact model id this token may request. Repeat for several; omit
        /// for the established unpinned behaviour.
        #[arg(long = "allowed-model", value_name = "MODEL")]
        allowed_model: Vec<String>,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Replace a token, preserving its controls, and revoke the old token.
    Rotate {
        /// Subject id (`sub`) of the token being replaced.
        id: String,
        #[arg(long, default_value_t = 24)]
        ttl_hours: i64,
        #[arg(long, default_value = "")]
        label: String,
        /// Replacement request cap; omitted keeps the existing one.
        #[arg(long)]
        max_requests: Option<u64>,
        /// Replacement token spend cap; omitted keeps the existing one.
        #[arg(long)]
        max_tokens: Option<u64>,
        /// Replacement per-minute request rate; omitted keeps the existing one.
        #[arg(long)]
        rate_limit_per_minute: Option<u64>,
        /// Replacement account pin; omitted keeps the existing one.
        #[arg(long)]
        account: Option<String>,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// List all known tokens.
    List {
        /// Emit JSON instead of the table.
        ///
        /// Every `list` printed a table unconditionally and every `show`
        /// printed JSON unconditionally, so neither could be asked for the
        /// other form — and `--json` existed on two subcommands only
        /// (issue #314).
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Revoke a token by id.
    ///
    /// `remove` and `delete` are accepted too: destroying something was
    /// `providers remove`, `clients remove`, `server remove`, `tokens revoke`
    /// and `tokens expire` (issue #314).
    #[command(alias = "remove", alias = "delete")]
    Revoke {
        id: String,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Revoke a token by id — an alias of `revoke`, kept for scripts.
    ///
    /// Both arms have always collapsed into the same call and printed
    /// `revoked <ID>`, while the help promised a distinct operation
    /// (issue #314). It is documented as the alias it is.
    Expire {
        id: String,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Show metadata for one token.
    Show {
        id: String,
        /// Accepted for symmetry with `list`: `show` already emits JSON, so
        /// this changes nothing (issue #314). A script should not have to know
        /// which verb of a family takes the flag.
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Mint a replacement administrative token from the local token store.
    ///
    /// The recovery path for a lost admin token. Every other verb in this
    /// family authenticates with the admin credential, so losing it left an
    /// operator who still owned the store, the volume and the machine with no
    /// way back in — and the standing advice was to destroy the deployment and
    /// discard every issued client token and the whole request log to recover
    /// from having misplaced one string (issue #573).
    ///
    /// The admin token is a signed JWT and the store keeps only its metadata,
    /// so the lost value cannot be re-read. What *can* be done is to sign a new
    /// one: this reads `TOKEN_SECRET` and the store directly, exactly as the
    /// server does at boot, and mints an admin token the running deployment
    /// already accepts — no restart, and issued client tokens, provider
    /// configuration and the request log are untouched.
    ///
    /// Gated on local ownership rather than on a credential. Reading the store
    /// is already equivalent to full control of the deployment, so this grants
    /// no authority its caller lacks; it only makes existing authority usable.
    /// For that reason it is never available over HTTP: with another router
    /// selected it refuses and names the machine it would have acted on, the
    /// same boundary `auth import` and `auth clear` draw.
    #[command(name = "recover-admin")]
    RecoverAdmin {
        /// Revoke every other admin token once the replacement is minted.
        ///
        /// For a credential believed to be in someone else's hands: recovery
        /// alone adds an administrator without removing the lost one.
        #[arg(long)]
        revoke_others: bool,
        #[arg(long, default_value_t = 24 * 365)]
        ttl_hours: i64,
        #[arg(long, default_value = "recovered-admin")]
        label: String,
        /// Emit the stable JSON envelope instead of human-readable output.
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Copy token records from another data root, deployment root, deploy
    /// checkpoint or token file into this store (issue #644).
    ///
    /// A rollback or data-root switch can leave a live token whose signature
    /// verifies but whose durable record is absent, so the router answers 401
    /// to a session that did nothing wrong. This brings the exact record back
    /// — same id, binding, scope, expiry, lease, budgets, usage and model
    /// policy — without rotating anything or touching the signing secret.
    ///
    /// By default only missing records are added and every existing record is
    /// left exactly as it is; records that differ are reported field by field.
    /// `--replace` overwrites those too, after saving the current records to
    /// `token-import-backups/`, and even then never revives a revoked record
    /// or lowers recorded usage. Local only: it needs the store itself.
    Import {
        /// Source: a data directory (`tokens.lino`/`tokens.bin`), a deployment
        /// root with `data/`, a checkpoint with `tokens.json`, or one file.
        #[arg(long, value_name = "PATH")]
        from: PathBuf,
        /// Import only this token id (repeatable).
        #[arg(long = "id", value_name = "ID")]
        ids: Vec<String>,
        /// Overwrite records that differ, after backing up the current ones.
        #[arg(long)]
        replace: bool,
        /// Report what would change without writing anything.
        #[arg(long)]
        dry_run: bool,
        /// Emit the report as JSON.
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
}

#[derive(Debug, Subcommand)]
pub enum AccountOp {
    /// List configured accounts and their health.
    List {
