#[derive(Debug, Subcommand)]
// Keeping `AuthTarget` flattened preserves clap's public flag layout. Boxing
// only the largest variant would leak an implementation detail into every
// constructor and test for a command enum created once per process.
#[allow(clippy::large_enum_variant)]
pub enum ProviderOp {
    /// List configured upstream providers.
    List {
        /// Emit JSON instead of the table (issue #314).
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Add or replace an API provider or policy-gated credential class.
    ///
    /// `create` and `issue` are accepted too (issue #314).
    #[command(alias = "create", alias = "issue")]
    Add {
        /// Name this provider is referred to by, in routing and in `providers
        /// show`. Adding an existing name replaces that record.
        #[arg(long)]
        name: String,
        /// Wire protocol the upstream speaks.
        #[arg(long, default_value = "openai-compatible")]
        kind: String,
        /// The upstream's own base URL — not the router's. `--server` names
        /// the router; this names the machine it forwards to (issue #314).
        #[arg(long)]
        base_url: String,
        /// Single model this provider serves, for an upstream that serves one.
        #[arg(long)]
        model: Option<String>,
        /// Comma-separated models this provider serves.
        #[arg(long, value_delimiter = ',')]
        models: Vec<String>,
        /// Canonical managed clients explicitly supported by this ordinary
        /// provider adapter. Repeat or comma-separate values.
        #[arg(long = "supported-client", value_delimiter = ',')]
        supported_clients: Vec<String>,
        /// Vendor API key, stored encrypted under the deployment's
        /// `TOKEN_SECRET`.
        ///
        /// Prefer `--api-key-stdin`: a key given here is visible in shell
        /// history and in `ps` (issue #314).
        #[arg(long, hide_env_values = true, conflicts_with = "api_key_stdin")]
        api_key: Option<String>,
        /// Read the vendor API key as one line from standard input.
        ///
        /// The one secret in this tool that could travel only through argv,
        /// while every other has had a stdin form and `clients setup --help`
        /// warns against argv for exactly this reason (issue #314).
        #[arg(long, conflicts_with = "api_key")]
        api_key_stdin: bool,
        /// Environment variable the *router process* reads the key from at
        /// request time, instead of storing one.
        #[arg(long)]
        api_key_env: Option<String>,
        /// Single subscriber allowed to spend a personal Coding Plan key.
        #[arg(long)]
        subscriber_id: Option<String>,
        /// Accept the documented account risk of intermediary personal proxying.
        #[arg(long)]
        acknowledge_intermediary_risk: bool,
        /// Individually risk-accept a known tool not listed by z.ai.
        #[arg(long, value_delimiter = ',')]
        acknowledge_unsupported_client: Vec<String>,
        /// Whether this provider takes part in routing. Disabled records are
        /// kept and ignored, so one can be parked without deleting it.
        #[arg(
            long,
            default_value_t = true,
            num_args = 0..=1,
            default_missing_value = "true"
        )]
        enabled: bool,
        /// Create only when the provider name is absent; never replace it.
        #[arg(long)]
        if_absent: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Show one provider with secret material redacted.
    Show {
        name: String,
        /// Accepted for symmetry with `list`: `show` already emits JSON, so
        /// this changes nothing (issue #314). A script should not have to know
        /// which verb of a family takes the flag.
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Remove one provider.
    ///
    /// `revoke` and `delete` are accepted too (issue #314).
    #[command(alias = "revoke", alias = "delete")]
    Remove {
        name: String,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Import providers from JSON, `.lenv`, or indented Links-style config.
    Import {
        path: PathBuf,
        #[command(flatten)]
        target: AuthTarget,
    },
}

//! Which router each subcommand acts on.
//!
//! Split from `cli.rs` to keep that file within the repository's 1000-line
//! limit. Every state-touching family answers the same question the same way,
//! which is the point of issue #294 — one rule rather than a table an operator
//! has to memorise.

use super::{AccountOp, AuthTarget, LogsOp, ProviderOp, TokenOp};

impl TokenOp {
    /// Which router this token operation acts on.
    #[must_use]
    pub const fn target(&self) -> &AuthTarget {
        match self {
            Self::Issue { target, .. }
            | Self::Rotate { target, .. }
            | Self::List { target, .. }
            | Self::Revoke { target, .. }
            | Self::Expire { target, .. }
            | Self::Show { target, .. }
            | Self::RecoverAdmin { target, .. }
            | Self::Import { target, .. } => target,
        }
    }
}

impl AccountOp {
    /// Which router this account operation acts on.
    #[must_use]
    pub const fn target(&self) -> &AuthTarget {
        match self {
            Self::List { target, .. }
            | Self::Policy { target, .. }
            | Self::Pause { target, .. }
            | Self::Resume { target, .. } => target,
        }
    }
}

impl ProviderOp {
    /// Which router this provider operation acts on.
    #[must_use]
    pub const fn target(&self) -> &AuthTarget {
        match self {
            Self::List { target, .. }
            | Self::Add { target, .. }
            | Self::Show { target, .. }
            | Self::Remove { target, .. }
            | Self::Import { target, .. } => target,
        }
    }
}

impl LogsOp {
    /// Which router this log query acts on.
    #[must_use]
    pub const fn target(&self) -> &AuthTarget {
        match self {
            Self::Summary { target, .. }
            | Self::Anomalies { target, .. }
            | Self::Show { target, .. } => target,
        }
    }
}

//! Small reusable value parsers for command-line and environment inputs.

/// Parse a boolean switch that may also arrive from the environment.
///
/// Clap's plain `bool` accepts only `true`/`false` from an env var, which makes
/// the `=1` spelling used throughout the deployment docs a hard startup error.
pub(super) fn parse_truthy(value: &str) -> Result<bool, String> {
    match value.trim().to_ascii_lowercase().as_str() {
        "1" | "true" | "yes" | "on" => Ok(true),
        "0" | "false" | "no" | "off" | "" => Ok(false),
        other => Err(format!(
            "expected a boolean (1/0, true/false), got '{other}'"
        )),
    }
}

/// Parse when an account pause lifts into Unix seconds (issue #677).
///
/// Accepts Unix seconds, an RFC 3339 time, or a delay from now written as a
/// number with an `s`, `m`, `h` or `d` suffix.
pub(super) fn parse_until(value: &str) -> Result<u64, String> {
    let value = value.trim();
    if let Ok(unix) = value.parse::<u64>() {
        return Ok(unix);
    }
    if let Ok(time) = chrono::DateTime::parse_from_rfc3339(value) {
        return u64::try_from(time.timestamp())
            .map_err(|_| format!("'{value}' is before the Unix epoch"));
    }
    let unit = value.chars().next_back().unwrap_or('?');
    let amount = value.strip_suffix(unit).unwrap_or_default();
    let scale = match unit {
        's' => 1,
        'm' => 60,
        'h' => 3600,
        'd' => 86_400,
        _ => 0,
    };
    match amount.parse::<u64>() {
        Ok(amount) if scale > 0 => {
            Ok(crate::account_limits::now_unix().saturating_add(amount.saturating_mul(scale)))
        }
        _ => Err(format!(
            "expected Unix seconds, an RFC 3339 time or a delay like 90m, 6h, 2d; got '{value}'"
        )),
    }
}

//! Temporary client launcher and managed-server CLI arguments.

use std::ffi::OsString;

use clap::{Args, Subcommand};

use crate::clients::ClientKind;

/// Insert the client-argument boundary, and say when a name changed hands.
///
/// One rule, holdable in the head: **everything after the client name belongs
/// to the client, verbatim.** Router options go before it.
///
/// What this replaces was a list of twelve names claimed back from the client
/// wherever they appeared, and the list was neither complete nor derivable
/// from anything a user could see: `--port`, `--host`, `--data-dir` and
/// `--managed` are router options and reached the client, while `--model`,
/// `--token`, `--server` and `--interactive` are router options and did not.
/// Both directions failed silently — `claude --model opus[1m]` was intercepted
/// and validated against the router's catalog, and `with claude --managed`
/// started nothing (issue #299).
///
/// The boundary is the first bare word that names a client, found by skipping
/// options and, for options that take one, their values — taken from the
/// parser itself rather than a hand-kept list, so a value that happens to
/// equal a client name (`--data-dir agent`) no longer shifts the split.
///
/// `--` is still accepted and still consumed, for anyone who prefers to write
/// the boundary out.
#[must_use]
pub fn protect_client_arguments(arguments: Vec<OsString>, nested: bool) -> Vec<OsString> {
    let start = if nested {
        arguments
            .iter()
            .position(|argument| argument == "with")
            .map_or(arguments.len(), |position| position + 1)
    } else {
        1
    };
    let options = wrapper_options();
    let clients: Vec<&str> = ClientKind::ALL
        .iter()
        .flat_map(|kind| [kind.canonical_name(), kind.legacy_name()])
        .collect();
    let mut position = start;
    while position < arguments.len() {
        let value = arguments[position].to_string_lossy().into_owned();
        if value == "--" {
            // An explicit boundary the user wrote: the client name follows it.
            position += 1;
            continue;
        }
        if value.starts_with('-') {
            let name = value
                .split_once('=')
                .map_or(value.as_str(), |(name, _)| name);
            let takes_a_value = !value.contains('=') && options.contains(&(name.to_string(), true));
            position += if takes_a_value { 2 } else { 1 };
            continue;
        }
        if !clients.contains(&value.as_str()) {
            position += 1;
            continue;
        }
        let mut normalized = arguments[..=position].to_vec();
        let forwarded = &arguments[position + 1..];
        if forwarded.is_empty() {
            return normalized;
        }
        let explicit = forwarded.first().is_some_and(|argument| argument == "--");
        let forwarded = if explicit { &forwarded[1..] } else { forwarded };
        if !explicit
            && matches!(value.as_str(), "claude" | "claude-code")
            && forwarded
                .first()
                .is_some_and(|argument| argument == "--reset-to-default-configuration")
        {
            let mut normalized = arguments[..position].to_vec();
            normalized.push("--reset-to-default-configuration".into());
            normalized.push(arguments[position].clone());
            if forwarded.len() > 1 {
                normalized.push("--".into());
                normalized.extend(forwarded[1..].iter().cloned());
            }
            return normalized;
        }
        // The forward itself is silent. Narrating a rule that behaved exactly
        // as documented turned a settled design decision (issue #299) into a
        // recurring interruption printed into the client's own terminal, once
        // per matching flag, with no way for a reader to say "yes, I know".
        // `with --help` documents the boundary, and `--` states it explicitly
        // for anyone who wants it stated (issue #330).
        normalized.push("--".into());
        normalized.extend(forwarded.iter().cloned());
        return normalized;
    }
    arguments
}

/// Every option `with` itself accepts, and whether it takes a value.
///
/// Read off the parser rather than written down beside it: a hand-kept copy is
/// what made the split undiscoverable and incomplete, and it drifts every time
/// an option is added (issue #299).
fn wrapper_options() -> std::collections::HashSet<(String, bool)> {
    use clap::CommandFactory as _;

    let mut options = std::collections::HashSet::new();
    let mut collect = |command: &clap::Command| {
        for argument in command.get_arguments() {
            // A flag declares zero values; anything else takes one. Clap
            // leaves `num_args` unset for both, so the switch is identified by
            // its `ArgAction`, which is what actually decides.
            let takes_a_value = argument.get_num_args().map_or_else(
                || {
                    !matches!(
                        argument.get_action(),
                        clap::ArgAction::SetTrue
                            | clap::ArgAction::SetFalse
                            | clap::ArgAction::Count
                            | clap::ArgAction::Help
                            | clap::ArgAction::Version
                    )
                },
                |range| range.takes_values(),
            );
            if let Some(long) = argument.get_long() {
                options.insert((format!("--{long}"), takes_a_value));
            }
            for alias in argument.get_all_aliases().unwrap_or_default() {
                options.insert((format!("--{alias}"), takes_a_value));
            }
            if let Some(short) = argument.get_short() {
                options.insert((format!("-{short}"), takes_a_value));
            }
        }
    };
    let root = crate::cli::Cli::command();
    collect(&root);
    if let Some(with) = root.find_subcommand("with") {
        collect(with);
    }
    options
}

/// Options shared by `router with` and the standalone `with-router` binary.
#[derive(Clone, Debug, Args)]
#[command(trailing_var_arg = true)]
pub struct WithArgs {
    /// Permanently configure the client instead of launching it temporarily.
    #[arg(long)]
    pub global: bool,
    /// Restore the exact configuration saved by a previous `--global` call.
    #[arg(long, requires = "global")]
    pub undo: bool,
    /// Force the client's non-interactive/one-shot mode.
    ///
    /// By default a bare positional is read as a prompt and starts a one-shot
    /// run, a flag is read as an option passed to a session, and streams that
    /// are not a terminal are one-shot. Reading *any* forwarded argument as a
    /// task turned `--resume`, `--continue` and `--verbose` into batch runs
    /// (issue #297).
    #[arg(long, conflicts_with = "interactive")]
    pub non_interactive: bool,
    /// Force the client's interactive mode.
    #[arg(long, conflicts_with = "non_interactive")]
    pub interactive: bool,
    /// Extend the client's normal user configuration for this launch.
    ///
    /// Claude uses a dedicated persistent Router-owned profile by default.
    /// This explicitly restores the older process-overlay behavior, without
    /// writing the user's Claude files. Other extensible clients already use
    /// their normal configuration and accept this for compatibility (#536).
    #[arg(long)]
    pub extend_global_config: bool,
    /// Give the client a configuration directory of its own.
    ///
    /// Claude uses a persistent profile owned by Router by default, so
    /// onboarding happens once and Router sessions remain resumable without
    /// inheriting the user's theme, permissions, MCP servers, credentials, or
    /// model cache. Other clients retain their existing profile behavior.
    ///
    /// `--extend-global-config` explicitly layers Claude routing onto the real
    /// profile instead. Nothing the user owns is written or modified.
    ///
    /// Isolation remains right for CI and clean-room reproductions, where
    /// passing a flag is normal and cheap.
    ///
    /// It is a no-op for `codex`, `gemini`, `opencode` and `agent`: those are
    /// routed through a file the router writes, so they never use the user's
    /// own directory with or without it. The run says so rather than accepting
    /// the flag silently (issue #312). What they get instead is a profile of
    /// their own that persists between runs, so sessions stay resumable
    /// (issue #298); `--isolated-config` makes that profile disposable.
    #[arg(long, conflicts_with = "extend_global_config")]
    pub isolated_config: bool,
    /// Replace only the persistent Router-owned Claude profile before launch.
    #[arg(long, conflicts_with_all = ["global", "undo", "isolated_config", "extend_global_config"])]
    pub reset_to_default_configuration: bool,
    /// Confirm a requested profile reset without an interactive prompt.
    #[arg(long, requires = "reset_to_default_configuration")]
    pub yes: bool,
    /// Start a disposable managed container even if a router is already
    /// listening locally.
    ///
    /// The default reuses a running local router (issue #250); CI and
    /// clean-room reproductions want a fresh instance on purpose.
    #[arg(long, conflicts_with_all = ["server", "management_server"])]
    pub managed: bool,
    /// Router origin. No local server is started when this is supplied.
    #[arg(long)]
    pub server: Option<String>,
    /// Private management origin when it differs from `--server`.
    #[arg(long, value_name = "URL", conflicts_with = "local")]
    pub management_server: Option<String>,
    /// Use the router running on this machine, not the selected one.
    ///
    /// `with` had `--server` and `--managed` but not `--local`, so it carried
    /// half the target vocabulary every other family has (issue #314).
    #[arg(long, conflicts_with_all = ["server", "management_server", "managed"])]
    pub local: bool,
    /// Router token. Prefer the environment or `--token-stdin` to shell history.
    #[arg(long, hide_env_values = true, conflicts_with = "token_stdin")]
    pub token: Option<String>,
    /// Read the router token as one line from standard input.
    #[arg(long, conflicts_with = "token")]
    pub token_stdin: bool,
    /// Model the client is launched with.
    ///
    /// Without this the client keeps the model its own configuration selects,
    /// and `with` changes only how that model is reached — the same rule
    /// `--global` follows. A router that picked one by catalog order replaced
    /// the user's choice silently, and the client's status line then presented
    /// the substitution as though the user had made it (issue #295).
    ///
    /// A client whose Router-written configuration requires an id —
    /// `opencode`, `qwen`, `agent` — must receive `--model` or the explicit
    /// `--pick-model` opt-in.
    #[arg(long)]
    pub model: Option<String>,
    /// Add another exact provider-advertised model to this run token.
    ///
    /// The selected `--model` is always included. Repeating this flag is the
    /// explicit opt-in that lets the client switch models during the run.
    #[arg(long = "allow-model")]
    pub allowed_models: Vec<String>,
    /// Accept a provider response whose concrete served model differs from
    /// the requested selector. The actual served id is still reported.
    #[arg(long)]
    pub allow_model_substitution: bool,
    /// Let the router choose a model from the target's live catalog.
    ///
    /// It reports what it picked and why. Without this no model is named and
    /// the client's own configuration decides.
    #[arg(long, conflicts_with = "model")]
    pub pick_model: bool,
    /// Label recorded on the router for this run's token.
    ///
    /// Each run mints a token on the target and the label is stored there. It
    /// defaults to the client name and a short suffix; it used to be the name
    /// of the directory the run was launched from, so a deployment
    /// accumulated a list of the projects its users work in (issue #316).
    /// Anything sent to a router someone else operates should be something you
    /// chose to send.
    #[arg(long)]
    pub label: Option<String>,
    /// Lifetime of an automatically minted per-run token, in hours.
    ///
    /// `--ttl-hours` is accepted too, so the name matches `tokens issue`,
    /// `tokens rotate` and `configure` (issue #314).
    ///
    /// Defaults to a day because this token is revoked when the client exits:
    /// the run already bounds its life, and the clock was a second bound that
    /// could only fire early. At one hour it routinely did — an interactive
    /// session that outlived the hour died mid-work with `401 Token has
    /// expired`, and the client answered with its own `/login` advice about
    /// an unrelated credential (issue #341).
    #[arg(long, alias = "ttl-hours", default_value_t = 24 * 7)]
    pub run_ttl_hours: i64,
    /// Keep a fixed expiry instead of extending it while the run is in use.
    ///
    /// By default the per-run token's expiry slides: every request served
    /// with it pushes the expiry to `now + --run-ttl-hours`, so a session
    /// that is still being used never hits the wall, and one abandoned for
    /// longer than the window still expires. That is what the bound is for --
    /// the run's own life already bounds the token, since it is revoked when
    /// the client exits, and a fixed clock could only ever fire early
    /// (issue #354).
    ///
    /// Pass this to keep the old behaviour: the expiry set at issue time is
    /// final, whatever the session is doing.
    #[arg(long)]
    pub fixed_run_ttl: bool,
    /// Optional request budget for an automatically minted per-run token.
    #[arg(long)]
    pub run_max_requests: Option<u64>,
    /// Client integration to launch or configure.
    #[arg(value_enum)]
    pub client: ClientKind,
    /// Arguments forwarded to the client. Use `--` to make the boundary explicit.
    #[arg(value_name = "CLIENT_ARGS", allow_hyphen_values = true)]
    pub client_args: Vec<OsString>,
}

/// Persistent and managed-local server operations.
#[derive(Debug, Subcommand)]
pub enum ServerOp {
    /// Persist a remote router URL and optional token, or clear that selection.
    Use {
        /// Remote router origin to persist.
        server: Option<String>,
        /// Private management origin when it differs from the inference origin.
        #[arg(long, value_name = "URL")]
        management_server: Option<String>,
        /// PEM CA bundle to trust for the selected inference origin.
        #[arg(long, value_name = "PATH")]
        ca_cert: Option<std::path::PathBuf>,
        /// PEM CA bundle to trust for a separate management origin.
        #[arg(long, value_name = "PATH", requires = "management_server")]
        management_ca_cert: Option<std::path::PathBuf>,
        /// Token to persist with owner-only permissions.
        #[arg(long, hide_env_values = true, conflicts_with = "token_stdin")]
        token: Option<String>,
        /// Read the token as one line from standard input.
        #[arg(long, conflicts_with = "token")]
        token_stdin: bool,
        /// Clear the persisted remote selection and return to automatic local mode.
        #[arg(long)]
        clear: bool,
        /// Default request budget for tokens minted for wrapper runs.
        #[arg(long)]
        run_max_requests: Option<u64>,
    },
    /// Show the selected server source and managed-container lifecycle.
    Status,
    /// Start the shared managed local container.
    Start,
    /// Reveal and claim the managed router's bootstrap administrator credential.
    Claim,
    /// Stop the shared managed local container without deleting its state.
    Stop,
    /// Remove the managed container and volume, destroying saved credentials.
    Remove {
        /// Confirm destructive removal without an interactive prompt.
        #[arg(long)]
        yes: bool,
    },
    /// Reap a crashed wrapper's managed-server reference.
    #[command(hide = true)]
    Reap { pid: u32 },
}

impl WithArgs {
    /// The permanent-setup request `--global` / `--undo` really is.
    ///
    /// `with --global` predates `configure` and stays as an accepted spelling,
    /// so it maps onto the same arguments rather than keeping a second
    /// implementation that can disagree with it (issue #296).
    #[must_use]
    pub fn as_configure(&self) -> crate::cli::ConfigureArgs {
        crate::cli::ConfigureArgs {
            client: Some(self.client),
            all: false,
            undo: self.undo,
            target: crate::cli::AuthTarget {
                local: self.local,
                server: self.server.clone(),
                management_server: self.management_server.clone(),
                managed: self.managed,
            },
            token: self.token.clone(),
            token_stdin: self.token_stdin,
            ttl_hours: 8760,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn split(arguments: &[&str], nested: bool) -> Vec<String> {
        protect_client_arguments(arguments.iter().map(OsString::from).collect(), nested)
            .iter()
            .map(|value| value.to_string_lossy().into_owned())
            .collect()
    }

    /// One rule: everything after the client name is the client's.
    ///
    /// What this replaces claimed twelve names back from the client wherever
    /// they appeared, by no principle a user could state — `--port` reached
    /// the client, `--model` was eaten and validated against the router's
    /// catalog (issue #299).
    #[test]
    fn everything_after_the_client_name_reaches_the_client() {
        for option in [
            "--global",
            "--undo",
            "--non-interactive",
            "--interactive",
            "--token-stdin",
            "--model",
            "--server",
            "--managed",
            "--isolated-config",
            "--port",
        ] {
            let split = split(&["router", "with", "codex", option, "value"], true);
            assert_eq!(
                split,
                ["router", "with", "codex", "--", option, "value"],
                "{option} after the client name must reach the client"
            );
        }
    }

    /// The model the client understands can be named without a boundary. The
    /// router intercepted it, validated `opus[1m]` against its own catalog and
    /// aborted a run the client would have accepted (issues #236, #299).
    #[test]
    fn a_client_model_reaches_the_client_and_a_router_model_does_not() {
        let split = split(
            &["with-router", "--model", "A", "qwen", "--model", "B"],
            false,
        );
        let boundary = split.iter().position(|value| value == "--").expect("--");
        assert!(split[..boundary].windows(2).any(|p| p == ["--model", "A"]));
        assert!(
            split[boundary + 1..]
                .windows(2)
                .any(|p| p == ["--model", "B"])
        );
    }

    /// A router option's value is skipped when looking for the boundary, so a
    /// value that happens to name a client no longer shifts the split.
    #[test]
    fn an_option_value_that_names_a_client_is_not_the_boundary() {
        for option in ["--model", "--data-dir", "--upstream-provider"] {
            let split = split(&["with-router", option, "codex", "qwen", "hello"], false);
            assert_eq!(
                split,
                ["with-router", option, "codex", "qwen", "--", "hello"],
                "{option}'s value must not be read as the client name"
            );
        }
    }

    /// An explicit boundary is accepted and consumed exactly once.
    #[test]
    fn an_explicit_boundary_is_not_doubled() {
        let split = split(&["with-router", "codex", "--", "--global", "hi"], false);
        assert_eq!(split, ["with-router", "codex", "--", "--global", "hi"]);
        assert_eq!(split.iter().filter(|value| *value == "--").count(), 1);
    }

    /// A client launched with nothing after it needs no boundary at all.
    #[test]
    fn a_bare_client_is_left_alone() {
        assert_eq!(
            split(&["with-router", "codex"], false),
            ["with-router", "codex"]
        );
    }

    /// The one documented post-client Router operation is deliberately
    /// normalized before clap sees the client boundary. Every other argument
    /// remains protected by issue #299's forwarding rule (issue #536).
    #[test]
    fn the_exact_claude_reset_operation_moves_before_the_client_boundary() {
        assert_eq!(
            split(
                &[
                    "router",
                    "with",
                    "claude",
                    "--reset-to-default-configuration",
                    "--resume",
                    "session-id",
                ],
                true,
            ),
            [
                "router",
                "with",
                "--reset-to-default-configuration",
                "claude",
                "--",
                "--resume",
                "session-id",
            ]
        );
        assert_eq!(
            split(
                &[
                    "router",
                    "with",
                    "codex",
                    "--reset-to-default-configuration"
                ],
                true,
            ),
            [
                "router",
                "with",
                "codex",
                "--",
                "--reset-to-default-configuration",
            ],
            "the exception must not claim the same client argument from another client"
        );
    }

    /// The option table comes from the parser, so it cannot drift from it.
    #[test]
    fn the_option_table_is_read_from_the_parser() {
        let options = wrapper_options();
        assert!(
            options.contains(&("--model".to_string(), true)),
            "--model takes a value"
        );
        assert!(
            options.contains(&("--global".to_string(), false)),
            "--global does not"
        );
        assert!(
            options.iter().any(|(name, _)| name == "--isolated-config"),
            "an option missing from a hand-kept list is the defect this prevents"
        );
    }
}

//! Shared fallible argument parser.
use super::{Cli, Command};

/// Parse the CLI, hiding options that cannot affect the subcommand shown.
///
/// `with` and `configure` return before the server configuration is built, so
/// server globals such as `--host`, `--port`, `--storage-policy` and
/// `--upstream-base-url` do not reach them. `--verbose` and `--data-dir`
/// do control their operational logging.
/// Clap lists a global under every subcommand, so `with --help` advertised
/// ineffective options as options of `with`, and `--port` written after
/// the client name went to the client
/// (issue #312). Listing options that cannot work is worse than omitting them.
///
/// Only the *help* changes. A global still parses wherever it always did, so
/// no existing invocation breaks.
pub fn try_parse_arguments(arguments: Vec<std::ffi::OsString>) -> Result<Cli, clap::Error> {
    use clap::FromArgMatches as _;

    let mut command = crate::contracts::command();
    // Globals are declared on the root and propagated into every subcommand
    // when the parser is built, so they can only be hidden before that — and
    // only for the invocations they cannot affect. `router tokens list --help`
    // still lists them, because there they work.
    if names_a_client_launcher(&arguments) {
        command = command.mut_args(|argument| {
            if argument.is_global_set()
                && !matches!(argument.get_id().as_str(), "verbose" | "data_dir")
            {
                argument.hide(true)
            } else {
                argument
            }
        });
    }
    // The usage strings that hide the globals are written with a `{name}`
    // placeholder, because clap does not interpolate one there. Substituting
    // the invoked name here keeps both properties at once: the error usage
    // line still omits globals that are not required (issue #312), and it
    // names the binary the reader actually ran rather than hardcoding `router`
    // under both installed names (issue #315).
    let invoked = arguments
        .first()
        .map(std::path::Path::new)
        .and_then(std::path::Path::file_stem)
        .map_or_else(
            || "router".to_string(),
            |name| name.to_string_lossy().into_owned(),
        );
    command = substitute_usage_name(command, &invoked);
    let matches = command.try_get_matches_from(arguments)?;
    let mut cli = Cli::from_arg_matches(&matches)?;
    // A propagated global default is not a deploy override of --config (#688).
    if let Some(Command::Deploy(deploy)) = &mut cli.command
        && matches
            .subcommand_matches("deploy")
            .and_then(|args| args.value_source("port"))
            == Some(clap::parser::ValueSource::DefaultValue)
    {
        deploy.port = None;
    }
    Ok(cli)
}

/// The subcommands whose usage line is written out, and what follows the name.
///
/// Written out because clap's generated *error* usage lists every configured
/// global as required (issue #312); the leading binary name is substituted at
/// parse time rather than hardcoded, so it is the one the reader invoked
/// (issue #315). One table, so the two rules cannot drift apart.
const OVERRIDDEN_USAGE: [(&[&str], &str); 14] = [
    (&["configure"], "configure [OPTIONS] <CLIENT>"),
    (&["clients", "setup"], "clients setup [OPTIONS] <CLIENT>"),
    (&["clients", "show"], "clients show [OPTIONS] <CLIENT>"),
    (&["clients", "remove"], "clients remove [OPTIONS] <CLIENT>"),
    (&["clients", "doctor"], "clients doctor [OPTIONS] <CLIENT>"),
    (&["tokens", "rotate"], "tokens rotate [OPTIONS] <ID>"),
    (&["tokens", "revoke"], "tokens revoke [OPTIONS] <ID>"),
    (&["tokens", "show"], "tokens show [OPTIONS] <ID>"),
    (
        &["providers", "add"],
        "providers add [OPTIONS] --name <NAME> --base-url <BASE_URL>",
    ),
    (&["providers", "show"], "providers show [OPTIONS] <NAME>"),
    (
        &["providers", "remove"],
        "providers remove [OPTIONS] <NAME>",
    ),
    (
        &["providers", "import"],
        "providers import [OPTIONS] <PATH>",
    ),
    (
        &["auth", "import"],
        "auth import [OPTIONS] [PROVIDER] [DIR]",
    ),
    (&["auth", "clear"], "auth clear [OPTIONS] [PROVIDER]"),
];

/// Write each overridden usage line with the name that was actually invoked.
fn substitute_usage_name(mut command: clap::Command, invoked: &str) -> clap::Command {
    for (path, usage) in OVERRIDDEN_USAGE {
        command = with_subcommand(command, path, &format!("{invoked} {usage}"));
    }
    command
}

/// Apply `usage` to the subcommand reached by `path`.
fn with_subcommand(command: clap::Command, path: &[&str], usage: &str) -> clap::Command {
    let Some((head, rest)) = path.split_first() else {
        return command.override_usage(usage.to_string());
    };
    command.mut_subcommand(head, |subcommand| with_subcommand(subcommand, rest, usage))
}

/// Whether this invocation is one that returns before the server config exists.
///
/// Read off argv rather than the parsed command, because the decision has to be
/// made before parsing. Only the first bare word is consulted, so a *value*
/// that happens to be `with` cannot flip it.
///
/// `tls` joins them because it reads and writes one certificate directory and
/// starts no server: `--port`, `--upstream-base-url` and `--routing-mode`
/// cannot change what it does, and listing twenty such options above the three
/// that matter is what issue #312 removed from `with` (issue #308).
fn names_a_client_launcher(arguments: &[std::ffi::OsString]) -> bool {
    arguments
        .iter()
        .skip(1)
        .map(|argument| argument.to_string_lossy().into_owned())
        .find(|argument| !argument.starts_with('-'))
        .is_some_and(|argument| argument == "with" || argument == "configure" || argument == "tls")
}

/// Parse human CLI arguments, retaining Clap's established help/error behavior.
#[must_use]
pub fn parse_arguments(arguments: Vec<std::ffi::OsString>) -> Cli {
    try_parse_arguments(arguments).unwrap_or_else(|error| error.exit())
}

//! Output and dispatch layer for the `clients` CLI command.

use std::path::Path;
use std::process::ExitCode;

use crate::cli::ClientOp;
use crate::client_repair_command::repair;
use crate::clients::{ClientKind, ClientManager, ManagedCredential, TokenSource};
use crate::config::Config;
use crate::storage::{build_token_store, build_token_store_read_only};
use crate::token::{IssueRequest, TokenManager};

/// Environment variable holding an existing router token for `clients setup`.
pub const CLIENT_TOKEN_ENV: &str = "LINK_ASSISTANT_ROUTER_TOKEN";
/// Compatibility alias shared with the client integrations themselves.
pub const CLIENT_TOKEN_ENV_ALIAS: &str = "LINK_ASSISTANT_TOKEN";

/// Run one local client-management operation.
pub async fn run(config: &Config, home: Option<&Path>, op: &ClientOp) -> ExitCode {
    let lifecycle = match op {
        ClientOp::Backup { op } => Some(crate::client_lifecycle::backup::run(home, op)),
        ClientOp::Reset {
            selection,
            dry_run,
            full,
            yes,
            json,
        } => Some(crate::client_lifecycle::reset::run(
            home, selection, *dry_run, *full, *yes, *json,
        )),
        ClientOp::Install(args) => Some(crate::client_lifecycle::maintenance::run(
            home, "install", args,
        )),
        ClientOp::Update(args) => Some(crate::client_lifecycle::maintenance::run(
            home, "update", args,
        )),
        ClientOp::Reinstall(args) => Some(crate::client_lifecycle::maintenance::run(
            home,
            "reinstall",
            args,
        )),
        _ => None,
    };
    if let Some(result) = lifecycle {
        return result;
    }
    let manager = match home {
        Some(home) => ClientManager::isolated(home),
        None => match ClientManager::from_env() {
            Ok(manager) => manager,
            Err(error) => return failed(error),
        },
    };
    match op {
        ClientOp::Backup { .. }
        | ClientOp::Reset { .. }
        | ClientOp::Install(_)
        | ClientOp::Update(_)
        | ClientOp::Reinstall(_) => unreachable!("lifecycle commands return before client setup"),
        ClientOp::List { json } => list(&manager, *json),
        ClientOp::Setup {
            client,
            token,
            token_stdin,
            base_url,
            management_server,
            ttl_hours,
        } => {
            let supplied = match resolve_supplied_token(token.clone(), *token_stdin) {
                Ok(token) => token,
                Err(error) => return failed(error),
            };
            setup(
                config,
                &manager,
                *client,
                supplied.as_deref(),
                base_url.as_deref(),
                management_server.as_deref(),
                *ttl_hours,
            )
            .await
        }
        ClientOp::Show { client, .. } => show(&manager, *client),
        ClientOp::Remove {
            client,
            revoke_supplied,
            force,
        } => remove(config, &manager, *client, *revoke_supplied, *force).await,
        ClientOp::Repair {
            client,
            all,
            dry_run,
            json,
            rollback,
        } => {
            repair(
                &manager,
                *client,
                *all,
                *dry_run,
                *json,
                rollback.as_deref(),
            )
            .await
        }
        ClientOp::Doctor { client } => {
            crate::client_launch::report_claude_native_services_limitation(*client);
            match manager.doctor(*client).await {
                Ok(message) => {
                    println!("ok: {message}");
                    ExitCode::SUCCESS
                }
                Err(error) => failed(error),
            }
        }
    }
}

/// Resolve an existing router token from argv, standard input, or the
/// environment, in that order. Returns `None` when setup should mint one.
fn resolve_supplied_token(
    token: Option<String>,
    token_stdin: bool,
) -> Result<Option<String>, Box<dyn std::error::Error + Send + Sync>> {
    if token_stdin {
        return crate::server_command::read_token().map(Some);
    }
    if let Some(token) = token {
        return Ok(Some(token));
    }
    Ok(crate::operation_context::var(CLIENT_TOKEN_ENV)
        .or_else(|_| crate::operation_context::var(CLIENT_TOKEN_ENV_ALIAS))
        .ok()
        .map(|token| token.trim().to_string())
        .filter(|token| !token.is_empty()))
}

/// Print one row per client, then say what could not be read.
///
/// A listing never ends early. Stopping at the first damaged file hid every
/// client after it, and named a *different* client than the one missing, so a
/// reader had no reason to suspect the table was incomplete (issue #304).
fn list(manager: &ClientManager, json: bool) -> ExitCode {
    let mut rows = Vec::new();
    if !json {
        println!(
            "{:<12}  {:<9}  {:<16}  {:<19}  config",
            "client", "installed", "ownership", "dialect"
        );
    }
    let mut unreadable = Vec::new();
    let mut failures = Vec::new();
    for client in ClientKind::ALL {
        match manager.status(client) {
            Ok(status) => {
                let ownership = if status.unreadable.is_some() {
                    "unreadable".to_string()
                } else {
                    status.ownership_state.to_string()
                };
                if json {
                    rows.push(status.clone());
                } else {
                    println!(
                        "{:<12}  {:<9}  {:<16}  {:<19}  {}",
                        status.client,
                        status.installed,
                        ownership,
                        status.dialect,
                        status.config_path.display()
                    );
                }
                if let Some(reason) = status.unreadable {
                    unreadable.push((client, reason));
                }
            }
            Err(error) => {
                if !json {
                    println!("{client:<12}  {:<9}  {:<16}  {:<19}  -", "?", "error", "?");
                }
                failures.push((client, error.to_string()));
            }
        }
    }
    if json {
        println!(
            "{}",
            serde_json::to_string_pretty(&rows).unwrap_or_else(|_| "[]".to_string())
        );
    }
    for (client, reason) in unreadable.iter().chain(&failures) {
        eprintln!("error: could not read {client}: {reason}");
    }
    if unreadable.is_empty() && failures.is_empty() {
        ExitCode::SUCCESS
    } else {
        ExitCode::from(1)
    }
}

pub(crate) async fn ensure_codex_bridge(
    manager: &ClientManager,
    client: ClientKind,
    base_url: &str,
) -> Result<Option<crate::codex_loopback_bridge::PersistentBridge>, String> {
    if client != ClientKind::Codex || !crate::codex_loopback_bridge::required(base_url)? {
        return Ok(None);
    }
    crate::codex_loopback_bridge::ensure_persistent(
        &manager.codex_loopback_bridge_state_path(),
        base_url,
    )
    .await
    .map(Some)
}

async fn setup(
    config: &Config,
    manager: &ClientManager,
    client: ClientKind,
    supplied_token: Option<&str>,
    base_url: Option<&str>,
    management_server: Option<&str>,
    ttl_hours: i64,
) -> ExitCode {
    if supplied_token.is_some_and(|token| !token.starts_with("la_sk_")) {
        eprintln!(
            "error: the supplied router token must begin with la_sk_ (checked --token, --token-stdin, then {CLIENT_TOKEN_ENV})"
        );
        return ExitCode::from(2);
    }
    crate::client_launch::report_claude_native_services_limitation(client);
    if let Some(management_server) = management_server {
        let Some(base_url) = base_url else {
            return failed("--management-server requires --server");
        };
        return setup_remote(
            manager,
            client,
            supplied_token,
            base_url,
            management_server,
            ttl_hours,
        )
        .await;
    }

    // `setup` mints from *this* deployment's token store, so the credential it
    // writes is only valid here. Defaulting the address to this CLI's own
    // `--host`/`--port` while another router was selected produced a client
    // pointed at a deployment that may not even be running, with no error
    // (issue #296). It cannot follow the selection either — a locally signed
    // token would be rejected there — so it says which command can.
    let base_url = match base_url {
        Some(base_url) => match crate::managed_server::canonical_server_origin(base_url) {
            Ok(base_url) => base_url,
            Err(error) => return failed(error),
        },
        None => match crate::managed_server::selected_server() {
            Ok(Some(selected)) => {
                eprintln!(
                    "error: `clients setup` configures the router it can mint a token for, which \
                     is this machine, but {selected} is selected."
                );
                eprintln!(
                    "note: run `router configure {client}` to point {} at the selected router, or \
                     pass --base-url to name an address for this one.",
                    client.display_name()
                );
                return ExitCode::from(1);
            }
            Ok(None) => local_client_base_url(config),
            Err(error) => return failed(error),
        },
    };
    if let Some(limitation) = client.setup_limitation() {
        return failed(limitation);
    }
    if client.token_env().is_none() {
        return failed(format!(
            "{} has no router token environment",
            client.display_name()
        ));
    }
    match manager.managed_target_matches(client, &base_url) {
        Ok(true)
            if manager
                .managed_token(client)
                .ok()
                .flatten()
                .as_deref()
                .is_some_and(|token| {
                    local_token_binding(config, token, client)
                        .is_ok_and(|binding| binding.is_some())
                }) =>
        {
            let bridge = match ensure_codex_bridge(manager, client, &base_url).await {
                Ok(bridge) => bridge,
                Err(error) => return failed(error),
            };
            let bridge_matches = bridge.as_ref().is_none_or(|bridge| {
                manager
                    .codex_backend_matches(bridge.backend_base_url())
                    .unwrap_or(false)
            });
            if bridge_matches {
                if client == ClientKind::Codex && bridge.is_none() {
                    let state = manager.codex_loopback_bridge_state_path();
                    if let Err(error) = crate::codex_loopback_bridge::stop_persistent(&state).await
                    {
                        return failed(error);
                    }
                }
                println!(
                    "{} is already configured in {}",
                    client.display_name(),
                    manager.config_path(client).display()
                );
                println!(
                    "credentials: {} (mode 0600)",
                    manager.environment_path(client).display()
                );
                if let Some(bridge) = bridge {
                    bridge.commit();
                }
                return ExitCode::SUCCESS;
            } else if let Some(bridge) = bridge {
                let _ = bridge.rollback().await;
            }
        }
        Ok(_) => {}
        Err(error) => return failed(error),
    }
    let (token, credential, verified_models) = match supplied_token {
        Some(token) => {
            let binding = match local_token_binding(config, token, client) {
                Ok(binding) => binding,
                Err(error) => return failed(error),
            };
            let (binding, verified_models) = if let Some(binding) = binding {
                (binding, None)
            } else {
                let binding = match decoded_token_binding(token, client) {
                    Ok(binding) => binding,
                    Err(error) => return failed(error),
                };
                let models = match manager.catalog(client, &base_url, token).await {
                    Ok(models) => models,
                    Err(error) => return failed(error),
                };
                (binding, Some(models))
            };
            (
                token.to_string(),
                ManagedCredential {
                    client: client.to_string(),
                    source: TokenSource::Supplied,
                    token_id: Some(binding.token_id),
                    label: None,
                    issued_at: None,
                    router: Some(base_url.clone()),
                    management_server: None,
                    principal_id: Some(binding.principal_id),
                    config_sha256: None,
                },
                verified_models,
            )
        }
        None => match issue_client_token(config, client, ttl_hours) {
            Ok((token, id)) => (
                token,
                ManagedCredential {
                    client: client.to_string(),
                    source: TokenSource::Minted,
                    token_id: Some(id),
                    label: Some(format!("client-{client}")),
                    issued_at: Some(crate::operation_context::now().timestamp()),
                    router: Some(base_url.clone()),
                    management_server: None,
                    principal_id: Some(
                        crate::credential_recovery_store::PRIMARY_ACCOUNT.to_string(),
                    ),
                    config_sha256: None,
                },
                None,
            ),
            Err(error) => return failed(error),
        },
    };
    let minted_id = (credential.source == TokenSource::Minted)
        .then(|| credential.token_id.clone())
        .flatten();
    let models = if let Some(models) = verified_models {
        crate::clients::usable_models(client, &models)
    } else if matches!(
        client,
        ClientKind::ClaudeCode | ClientKind::Opencode | ClientKind::QwenCode | ClientKind::Agent
    ) {
        match manager.catalog(client, &base_url, &token).await {
            // Filtered by the same rule `with` and `doctor` use, so a client
            // config cannot embed a model the launcher would refuse to start
            // it on (issue #301).
            Ok(models) => crate::clients::usable_models(client, &models),
            Err(error) => {
                return failed_after_local_candidate(config, minted_id.as_deref(), error);
            }
        }
    } else {
        Vec::new()
    };
    let bridge = match ensure_codex_bridge(manager, client, &base_url).await {
        Ok(bridge) => bridge,
        Err(error) => {
            return failed_after_local_candidate(config, minted_id.as_deref(), error);
        }
    };
    let codex_backend_base_url = bridge
        .as_ref()
        .map(crate::codex_loopback_bridge::PersistentBridge::backend_base_url);
    let result = match manager.apply_setup_transaction_with_codex_backend(
        client,
        &base_url,
        &token,
        &credential,
        &models,
        codex_backend_base_url,
    ) {
        Ok(result) => result,
        Err(error) => {
            let error = if let Some(bridge) = bridge {
                bridge.rollback().await.map_or_else(
                    |cleanup| {
                        format!("{error}; the unused Codex bridge could not be removed: {cleanup}")
                    },
                    |()| error.to_string(),
                )
            } else {
                error.to_string()
            };
            return failed_after_local_candidate(config, minted_id.as_deref(), error);
        }
    };
    if client == ClientKind::Codex && bridge.is_none() {
        let state = manager.codex_loopback_bridge_state_path();
        if let Err(error) = crate::codex_loopback_bridge::stop_persistent(&state).await {
            return failed(error);
        }
    }
    if let Some(bridge) = bridge {
        bridge.commit();
    }
    let environment_path = manager.environment_path(client);
    if client == ClientKind::GrokCli {
        // A token was minted and two files written, so the operation did
        // change this machine — `SetupResult` describes the client's *own*
        // config, which is a different question (issue #303).
        println!(
            "configured {} through its environment; its own config file was not changed",
            client.display_name()
        );
    } else if result.changed {
        println!(
            "configured {} in {}",
            client.display_name(),
            result.path.display()
        );
    } else {
        println!(
            "{} is already configured in {}",
            client.display_name(),
            result.path.display()
        );
    }
    if let Some(backup) = result.backup {
        println!("backup: {}", backup.display());
    }
    println!(
        "credentials: {} (mode 0600); run: source {}",
        environment_path.display(),
        shell_quote(&environment_path.display().to_string())
    );
    println!("The token is not stored in the client config or printed to the terminal.");
    ExitCode::SUCCESS
}

async fn setup_remote(
    manager: &ClientManager,
    client: ClientKind,
    supplied_token: Option<&str>,
    base_url: &str,
    management_server: &str,
    ttl_hours: i64,
) -> ExitCode {
    if let Some(limitation) = client.setup_limitation() {
        return failed(limitation);
    }
    if client.token_env().is_none() {
        return failed(format!(
            "{} has no router token environment",
            client.display_name()
        ));
    }
    let base_url = match crate::managed_server::canonical_server_origin(base_url) {
        Ok(base_url) => base_url,
        Err(error) => return failed(error),
    };
    if let Err(error) = crate::managed_server::canonical_server_origin(management_server) {
        return failed(error);
    }
    match manager.managed_target_matches(client, &base_url) {
        Ok(true)
            if let Some(token) = manager.managed_token(client).ok().flatten()
                && manager.catalog(client, &base_url, &token).await.is_ok() =>
        {
            let bridge = match ensure_codex_bridge(manager, client, &base_url).await {
                Ok(bridge) => bridge,
                Err(error) => return failed(error),
            };
            let bridge_matches = bridge.as_ref().is_none_or(|bridge| {
                manager
                    .codex_backend_matches(bridge.backend_base_url())
                    .unwrap_or(false)
            });
            if bridge_matches {
                if client == ClientKind::Codex && bridge.is_none() {
                    let state = manager.codex_loopback_bridge_state_path();
                    if let Err(error) = crate::codex_loopback_bridge::stop_persistent(&state).await
                    {
                        return failed(error);
                    }
                }
                println!(
                    "{} is already configured in {}",
                    client.display_name(),
                    manager.config_path(client).display()
                );
                println!(
                    "credentials: {} (mode 0600)",
                    manager.environment_path(client).display()
                );
                if let Some(bridge) = bridge {
                    bridge.commit();
                }
                return ExitCode::SUCCESS;
            }
            if let Some(bridge) = bridge {
                let _ = bridge.rollback().await;
            }
        }
        Ok(_) => {}
        Err(error) => return failed(error),
    }
    let server = match crate::managed_server::resolve(
        Some(&base_url),
        Some(management_server),
        supplied_token.map(str::to_string),
        None,
        false,
    )
    .await
    {
        Ok(server) => server,
        Err(error) => return failed(error),
    };
    let candidate = match crate::managed_server::prepare_persistent_credential(
        &server,
        client,
        &format!("client-{client}"),
        ttl_hours,
    )
    .await
    {
        Ok(candidate) => candidate,
        Err(error) => return failed(error),
    };
    let record = ManagedCredential {
        client: client.to_string(),
        source: if candidate.was_minted() {
            TokenSource::Minted
        } else {
            TokenSource::Supplied
        },
        token_id: candidate.id(),
        label: Some(format!("client-{client}")),
        issued_at: Some(crate::operation_context::now().timestamp()),
        router: Some(server.base_url.clone()),
        management_server: Some(server.management_url.clone()),
        principal_id: Some(candidate.principal_id().to_string()),
        config_sha256: None,
    };
    let models = crate::clients::usable_models(client, candidate.models());
    let bridge = match ensure_codex_bridge(manager, client, &server.base_url).await {
        Ok(bridge) => bridge,
        Err(error) => {
            return match crate::managed_server::cleanup_run_credential(candidate).await {
                Ok(()) => failed(error),
                Err(cleanup) => failed(format!(
                    "{error}; the unused minted credential could not be revoked: {cleanup}"
                )),
            };
        }
    };
    let codex_backend_base_url = bridge
        .as_ref()
        .map(crate::codex_loopback_bridge::PersistentBridge::backend_base_url);
    let result = manager.apply_setup_transaction_with_codex_backend(
        client,
        &server.base_url,
        &candidate.token,
        &record,
        &models,
        codex_backend_base_url,
    );
    let result = match result {
        Ok(result) => result,
        Err(error) => {
            let bridge_cleanup = if let Some(bridge) = bridge {
                bridge.rollback().await.err()
            } else {
                None
            };
            return match crate::managed_server::cleanup_run_credential(candidate).await {
                Ok(()) if bridge_cleanup.is_none() => failed(error),
                Ok(()) => failed(format!(
                    "{error}; the unused Codex bridge could not be removed: {}",
                    bridge_cleanup.expect("checked above")
                )),
                Err(cleanup) => failed(format!(
                    "{error}; the unused minted credential could not be revoked: {cleanup}{}",
                    bridge_cleanup.map_or_else(String::new, |bridge| format!(
                        "; the unused Codex bridge could not be removed: {bridge}"
                    ))
                )),
            };
        }
    };
    if client == ClientKind::Codex && bridge.is_none() {
        let state = manager.codex_loopback_bridge_state_path();
        if let Err(error) = crate::codex_loopback_bridge::stop_persistent(&state).await {
            return failed(error);
        }
    }
    if let Some(bridge) = bridge {
        bridge.commit();
    }
    let environment_path = manager.environment_path(client);
    if client == ClientKind::GrokCli {
        println!(
            "configured {} through its environment; its own config file was not changed",
            client.display_name()
        );
    } else if result.changed {
        println!(
            "configured {} in {}",
            client.display_name(),
            result.path.display()
        );
    } else {
        println!(
            "{} is already configured in {}",
            client.display_name(),
            result.path.display()
        );
    }
    if let Some(backup) = result.backup {
        println!("backup: {}", backup.display());
    }
    println!(
        "credentials: {} (mode 0600); run: source {}",
        environment_path.display(),
        shell_quote(&environment_path.display().to_string())
    );
    println!("The token is not stored in the client config or printed to the terminal.");
    ExitCode::SUCCESS
}

fn failed_after_local_candidate(
    config: &Config,
    minted_id: Option<&str>,
    error: impl std::fmt::Display,
) -> ExitCode {
    let error = error.to_string();
    if let Some(id) = minted_id
        && let Err(cleanup) = token_manager(config).and_then(|manager| {
            manager
                .revoke_token(id)
                .map_err(|error| Box::new(error) as Box<dyn std::error::Error>)
        })
    {
        return failed(format!(
            "{error}; the unused minted credential could not be revoked: {cleanup}"
        ));
    }
    failed(error)
}

fn show(manager: &ClientManager, client: ClientKind) -> ExitCode {
    match manager.status(client) {
        Ok(status) => {
            println!(
                "{}",
                serde_json::to_string_pretty(&status).unwrap_or_default()
            );
            ExitCode::SUCCESS
        }
        Err(error) => failed(error),
    }
}

/// Remove the local settings, revoking the credential they contain first.
///
/// Order matters: the token is revoked before the environment file that holds
/// it is deleted. Deleting first would leave a live credential that nobody can
/// name any more, which is exactly the regression from issue #190.
async fn remove(
    config: &Config,
    manager: &ClientManager,
    client: ClientKind,
    revoke_supplied: bool,
    force: bool,
) -> ExitCode {
    // `setup` and `doctor` check this; `remove` did not, so it reported
    // success on a file the router can never write (issue #303).
    if let Some(limitation) = client.setup_limitation() {
        return failed(limitation);
    }
    let credential = match manager.credential_metadata(client) {
        Ok(credential) => credential,
        Err(error) if force => {
            eprintln!("warning: {error}; continuing because --force was given");
            None
        }
        Err(error) => return failed(error),
    };
    let revoked = match revoke_managed_credential(config, credential.as_ref(), revoke_supplied)
        .await
    {
        Ok(revoked) => revoked,
        Err(error) => {
            if !force {
                eprintln!("error: {error}");
                eprintln!(
                    "the credential file was left in place; revoke the token with `link-assistant-router tokens revoke <ID>` against the router's DATA_DIR and rerun `link-assistant-router clients remove {client}`, or pass --force to delete the local settings anyway"
                );
                return ExitCode::from(1);
            }
            eprintln!("warning: {error}; continuing because --force was given");
            None
        }
    };
    match manager.remove(client) {
        Ok(result) => {
            if client == ClientKind::Codex {
                let state = manager.codex_loopback_bridge_state_path();
                if let Err(error) = crate::codex_loopback_bridge::stop_persistent(&state).await {
                    return failed(error);
                }
            }
            if result.changed {
                println!("removed router settings from {}", result.path.display());
            } else {
                println!(
                    "no managed router settings found in {}",
                    result.path.display()
                );
            }
            if let Some(backup) = result.backup {
                println!("backup: {}", backup.display());
            }
            if let Some(id) = revoked {
                println!("revoked managed token {id}");
            }
            ExitCode::SUCCESS
        }
        Err(error) => failed(error),
    }
}

/// Revoke the recorded token when removal owns it. Returns the revoked id.
async fn revoke_managed_credential(
    config: &Config,
    credential: Option<&ManagedCredential>,
    revoke_supplied: bool,
) -> Result<Option<String>, String> {
    let Some(credential) = credential else {
        return Ok(None);
    };
    let wanted = credential.revocable_by_default()
        || (revoke_supplied && credential.source == TokenSource::Supplied);
    if !wanted {
        return Ok(None);
    }
    let Some(id) = credential.token_id.as_deref() else {
        if revoke_supplied {
            return Err(format!(
                "the token configured for {} was supplied by the operator and this router does not recognise it, so it cannot be revoked here",
                credential.client
            ));
        }
        return Ok(None);
    };
    if let Some(management_server) = credential.management_server.as_deref() {
        let router = credential.router.as_deref().unwrap_or(management_server);
        let admin_token = remote_revocation_token(router).ok_or_else(|| {
            format!(
                "token {id} was issued through {management_server}, but no administrative credential for {router} is available; set LINK_ASSISTANT_ROUTER_TOKEN or select that router with `link-assistant-router server use {router} --token-stdin`"
            )
        })?;
        crate::managed_server::revoke(management_server, &admin_token, id)
            .await
            .map_err(|error| error.to_string())?;
    } else {
        token_manager(config)
            .map_err(|error| error.to_string())?
            .revoke_token(id)
            .map_err(|error| error.to_string())?;
    }
    Ok(Some(id.to_string()))
}

/// Find authority for a previously selected remote Router without persisting
/// it in per-client metadata. Environment credentials deliberately win.
fn remote_revocation_token(router: &str) -> Option<String> {
    crate::operation_context::var(CLIENT_TOKEN_ENV)
        .or_else(|_| crate::operation_context::var(CLIENT_TOKEN_ENV_ALIAS))
        .ok()
        .or_else(|| {
            crate::managed_server::load_persisted()
                .ok()
                .flatten()
                .filter(|persisted| {
                    crate::managed_server::canonical_server_origin(&persisted.server).ok()
                        == crate::managed_server::canonical_server_origin(router).ok()
                })
                .and_then(|persisted| persisted.token)
        })
}

#[path = "client_command_token.rs"]
mod token_support;
pub(crate) use token_support::failed;
use token_support::{
    decoded_token_binding, issue_client_token, local_client_base_url, local_token_binding,
    shell_quote, token_manager,
};

use super::{
    ClientKind, Config, ExitCode, IssueRequest, TokenManager, build_token_store,
    build_token_store_read_only,
};

/// Validate that a supplied local token is bound to exactly this adapter.
pub(super) struct LocalTokenBinding {
    pub(super) token_id: String,
    pub(super) principal_id: String,
}

fn exact_local_token_binding(
    claims: crate::token::TokenClaims,
    client: ClientKind,
) -> Result<LocalTokenBinding, Box<dyn std::error::Error>> {
    let client_name = claims
        .client_kind
        .as_deref()
        .ok_or("the supplied token has no managed-client binding")?;
    if client_name != client.canonical_name() {
        if ClientKind::ALL
            .iter()
            .any(|candidate| client_name == candidate.canonical_name())
        {
            return Err(format!(
                "the supplied token is bound to {client_name}, not {}",
                client.canonical_name()
            )
            .into());
        }
        return Err(
            "the supplied token has an unknown or non-canonical managed-client binding".into(),
        );
    }
    let principal_id = claims
        .principal_id
        .filter(|value| !value.trim().is_empty())
        .ok_or("the supplied token has no subscriber principal")?;
    Ok(LocalTokenBinding {
        token_id: claims.sub,
        principal_id,
    })
}

pub(super) fn local_token_binding(
    config: &Config,
    token: &str,
    client: ClientKind,
) -> Result<Option<LocalTokenBinding>, Box<dyn std::error::Error>> {
    crate::token_secret::ensure_real(&config.token_secret)?;
    let store = build_token_store_read_only(config.storage_policy, &config.data_dir)?;
    let manager = TokenManager::with_store(&config.token_secret, store);
    let Ok(claims) = manager.validate_token(token) else {
        // The supplied credential can belong to a remote Router with a
        // different signing key. Its catalog endpoint is the authority for
        // that credential; only locally verifiable tokens can be inspected or
        // revoked from this data directory.
        return Ok(None);
    };
    exact_local_token_binding(claims, client).map(Some)
}

/// Read the self-describing binding from a foreign token before asking its
/// issuing Router to authenticate it through the client's non-inference
/// catalog. The payload is not trusted until that catalog succeeds.
pub(super) fn decoded_token_binding(
    token: &str,
    client: ClientKind,
) -> Result<LocalTokenBinding, Box<dyn std::error::Error + Send + Sync>> {
    let (client_kind, principal_id) = crate::managed_server::token_client_binding(token)?;
    let client_kind = client_kind.ok_or("the supplied token has no managed-client binding")?;
    if client_kind != client.canonical_name() {
        return Err(format!(
            "the supplied token is bound to {client_kind}, not {}",
            client.canonical_name()
        )
        .into());
    }
    let principal_id = principal_id
        .filter(|value| !value.trim().is_empty())
        .ok_or("the supplied token has no subscriber principal")?;
    Ok(LocalTokenBinding {
        token_id: crate::managed_server::token_subject(token)?,
        principal_id,
    })
}

pub(super) fn token_manager(config: &Config) -> Result<TokenManager, Box<dyn std::error::Error>> {
    if !config.data_dir.exists() {
        std::fs::create_dir_all(&config.data_dir)?;
    }
    let store = build_token_store(config.storage_policy, &config.data_dir)?;
    crate::token_secret::ensure_real(&config.token_secret)?;
    Ok(TokenManager::with_store(&config.token_secret, store))
}

pub(super) fn issue_client_token(
    config: &Config,
    client: ClientKind,
    ttl_hours: i64,
) -> Result<(String, String), Box<dyn std::error::Error>> {
    let manager = token_manager(config)?;
    Ok(manager.issue_with_id(&IssueRequest {
        ttl_hours,
        label: &format!("client-{client}"),
        account: Some(crate::credential_recovery_store::PRIMARY_ACCOUNT),
        max_requests: None,
        max_tokens: None,
        rate_limit_per_minute: None,
        scope: "",
        github_repos: Vec::new(),
        sliding_window_seconds: None,
        client_kind: Some(client.canonical_name()),
        principal_id: Some(crate::credential_recovery_store::PRIMARY_ACCOUNT),
    })?)
}

pub(super) fn local_client_base_url(config: &Config) -> String {
    let host = match config.listen_addr.ip() {
        std::net::IpAddr::V4(ip) if ip.is_unspecified() => "127.0.0.1".to_string(),
        std::net::IpAddr::V6(ip) if ip.is_unspecified() => "[::1]".to_string(),
        ip => ip.to_string(),
    };
    format!("http://{host}:{}", config.listen_addr.port())
}

pub(super) fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

pub fn failed(error: impl std::fmt::Display) -> ExitCode {
    eprintln!(
        "error: {}",
        crate::login_url::redact_secrets(&error.to_string())
    );
    ExitCode::from(1)
}

#[cfg(test)]
mod binding_tests {
    use super::*;

    fn claims(client_kind: Option<&str>, principal_id: Option<&str>) -> crate::token::TokenClaims {
        crate::token::TokenClaims {
            sub: "token-id".into(),
            iat: 1,
            exp: i64::MAX,
            label: String::new(),
            scope: String::new(),
            github_repos: Vec::new(),
            client_kind: client_kind.map(str::to_string),
            principal_id: principal_id.map(str::to_string),
        }
    }

    #[test]
    fn adopted_local_tokens_require_the_exact_complete_binding() {
        let accepted =
            exact_local_token_binding(claims(Some("codex"), Some("primary")), ClientKind::Codex)
                .expect("canonical complete binding");
        assert_eq!(accepted.token_id, "token-id");
        assert_eq!(accepted.principal_id, "primary");

        for rejected in [
            claims(None, None),
            claims(None, Some("primary")),
            claims(Some("codex"), None),
            claims(Some("codex"), Some("  ")),
            claims(Some("claude-code"), Some("primary")),
            claims(Some("future-client"), Some("primary")),
            claims(Some("claude"), Some("primary")),
        ] {
            assert!(
                exact_local_token_binding(rejected, ClientKind::Codex).is_err(),
                "generic, partial, non-canonical and foreign bindings must fail closed"
            );
        }
    }
}

//! Exact, edit-aware backup and undo for `router with --global`.

use std::fs::{self, OpenOptions};
use std::io::Write as _;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};
use sha2::{Digest as _, Sha256};

use crate::clients::{ClientKind, ClientManager, RouterModel};

type AnyError = Box<dyn std::error::Error + Send + Sync>;

#[derive(Debug, Deserialize, Serialize)]
struct BackupState {
    config_existed: bool,
    #[serde(default)]
    config_mode: Option<u32>,
    config_hash_after_setup: String,
    marker_existed: bool,
    #[serde(default)]
    marker_mode: Option<u32>,
    #[serde(default)]
    marker_hash_after_setup: Option<String>,
    marker_path: Option<PathBuf>,
    setup_backup: Option<PathBuf>,
}

/// Existing `with --global` undo state is part of a repair transaction. A
/// repair must either advance its edit guard or restore it with everything
/// else, otherwise a later undo falsely reports the router's own repair as a
/// user edit.
pub(crate) fn undo_state_path(config_path: &Path) -> PathBuf {
    backup_paths(config_path).state
}

/// Files the reversible global configurator may create beside a client
/// configuration. Higher-level transactions include all of them in their
/// rollback allow-list.
pub(crate) fn transaction_paths(config_path: &Path) -> Vec<PathBuf> {
    let paths = backup_paths(config_path);
    vec![paths.config, paths.marker, paths.state]
}

pub(crate) fn update_post_configure_hash(
    config_path: &Path,
    marker_path: Option<&Path>,
) -> Result<(), AnyError> {
    let path = undo_state_path(config_path);
    let source = match fs::read(&path) {
        Ok(source) => source,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(error) => return Err(error.into()),
    };
    let mut state: BackupState = crate::lino_json::decode(&String::from_utf8_lossy(&source))?;
    state.config_hash_after_setup = digest(&fs::read(config_path).unwrap_or_default());
    state.marker_hash_after_setup = marker_path
        .and_then(|path| fs::read(path).ok())
        .map(|contents| digest(&contents));
    crate::durable_file::atomic_write_owner_only(
        &path,
        crate::lino_json::encode(&state)?.as_bytes(),
    )?;
    Ok(())
}

/// Write the router into the client's own configuration, reversibly.
///
/// Returns the path that was written. Nothing is printed here: the caller
/// knows whether a credential was stored alongside it, and reporting half the
/// outcome from inside was how `with --global` came to announce success while
/// telling the user to go set an environment variable themselves (issue #296).
pub(crate) fn apply_with_manager_and_codex_backend(
    manager: &ClientManager,
    client: ClientKind,
    base_url: &str,
    models: &[RouterModel],
    codex_backend_base_url: Option<&str>,
) -> Result<PathBuf, AnyError> {
    if matches!(client, ClientKind::Cursor | ClientKind::GeminiCli) {
        return Err(client
            .setup_limitation()
            .unwrap_or("client cannot be configured globally")
            .into());
    }
    let config_path = manager.config_path(client);
    let paths = backup_paths(&config_path);
    if paths.state.exists() {
        return Err(format!(
            "a global backup already exists for {client}; run `link-assistant-router with --global --undo {client}` first"
        )
        .into());
    }
    let marker_path = manager.ownership_marker_path(client);
    let config_existed = config_path.exists();
    let marker_existed = marker_path.as_ref().is_some_and(|path| path.exists());
    let config_mode = file_mode(&config_path);
    let marker_mode = marker_path.as_deref().and_then(file_mode);
    if config_existed {
        copy_private(&config_path, &paths.config)?;
    }
    if let Some(marker) = marker_path.as_ref().filter(|_| marker_existed) {
        copy_private(marker, &paths.marker)?;
    }
    let setup =
        match manager.setup_with_codex_backend(client, base_url, models, codex_backend_base_url) {
            Ok(result) => result,
            Err(error) => {
                rollback(
                    &paths,
                    &config_path,
                    config_existed,
                    config_mode,
                    marker_path.as_deref(),
                    marker_existed,
                    marker_mode,
                )?;
                remove_if_present(&paths.config)?;
                remove_if_present(&paths.marker)?;
                return Err(error.into());
            }
        };
    let configured_contents = fs::read(&config_path)?;
    let state = BackupState {
        config_existed,
        config_mode,
        config_hash_after_setup: digest(&configured_contents),
        marker_existed,
        marker_mode,
        marker_hash_after_setup: marker_path
            .as_deref()
            .and_then(|path| fs::read(path).ok())
            .map(|contents| digest(&contents)),
        marker_path,
        setup_backup: setup.backup,
    };
    // Links notation, readable, with the file name unchanged so a run in
    // progress under an earlier release still rolls back (issue #336).
    if let Err(error) = write_private(&paths.state, crate::lino_json::encode(&state)?.as_bytes()) {
        rollback(
            &paths,
            &config_path,
            config_existed,
            config_mode,
            state.marker_path.as_deref(),
            marker_existed,
            marker_mode,
        )?;
        if let Some(setup_backup) = state.setup_backup {
            remove_if_present(&setup_backup)?;
        }
        remove_if_present(&paths.config)?;
        remove_if_present(&paths.marker)?;
        return Err(format!("could not save global undo state: {error}").into());
    }
    Ok(config_path)
}

/// Restore the exact configuration a previous `apply` replaced.
///
/// Returns the restored path, or `None` when this client never had a
/// configuration file to save — `configure grok` stores only a credential.
pub fn undo(client: ClientKind) -> Result<Option<PathBuf>, AnyError> {
    let manager = ClientManager::from_env()?;
    undo_with_manager(&manager, client)
}

pub(crate) fn undo_with_manager(
    manager: &ClientManager,
    client: ClientKind,
) -> Result<Option<PathBuf>, AnyError> {
    let config_path = manager.config_path(client);
    let paths = backup_paths(&config_path);
    let source = match fs::read(&paths.state) {
        Ok(source) => source,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => {
            return Err(format!("could not read {}: {error}", paths.state.display()).into());
        }
    };
    // Either encoding: state written by an earlier release is JSON.
    let state: BackupState = crate::lino_json::decode(&String::from_utf8_lossy(&source))?;
    let current = fs::read(&config_path).unwrap_or_default();
    if digest(&current) != state.config_hash_after_setup {
        return Err(format!(
            "refusing to overwrite {} because it changed after it was configured; preserve your edits or restore the managed version before retrying",
            config_path.display()
        )
        .into());
    }
    if let Some(marker_path) = state.marker_path.as_ref() {
        if let Some(expected) = state.marker_hash_after_setup.as_deref() {
            let current = fs::read(marker_path).unwrap_or_default();
            if digest(&current) != expected {
                return Err(format!(
                    "refusing to overwrite {} because it changed after it was configured",
                    marker_path.display()
                )
                .into());
            }
        }
        if state.marker_existed {
            restore(&paths.marker, marker_path, state.marker_mode)?;
        } else {
            remove_if_present(marker_path)?;
        }
    }
    if state.config_existed {
        restore(&paths.config, &config_path, state.config_mode)?;
    } else {
        remove_if_present(&config_path)?;
    }
    if let Some(setup_backup) = state.setup_backup {
        remove_if_present(&setup_backup)?;
    }
    remove_if_present(&paths.config)?;
    remove_if_present(&paths.marker)?;
    remove_if_present(&paths.state)?;
    Ok(Some(config_path))
}

struct BackupPaths {
    config: PathBuf,
    marker: PathBuf,
    state: PathBuf,
}

fn backup_paths(config: &Path) -> BackupPaths {
    BackupPaths {
        config: append(config, ".with-router.bak"),
        marker: append(config, ".with-router-marker.bak"),
        state: append(config, ".with-router-state.json"),
    }
}

fn append(path: &Path, suffix: &str) -> PathBuf {
    let mut value = path.as_os_str().to_os_string();
    value.push(suffix);
    PathBuf::from(value)
}

fn restore(backup: &Path, destination: &Path, mode: Option<u32>) -> Result<(), AnyError> {
    let contents = fs::read(backup)?;
    remove_if_present(destination)?;
    write_private(destination, &contents)?;
    set_file_mode(destination, mode)?;
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn rollback(
    paths: &BackupPaths,
    config_path: &Path,
    config_existed: bool,
    config_mode: Option<u32>,
    marker_path: Option<&Path>,
    marker_existed: bool,
    marker_mode: Option<u32>,
) -> Result<(), AnyError> {
    if let Some(marker_path) = marker_path {
        if marker_existed {
            restore(&paths.marker, marker_path, marker_mode)?;
        } else {
            remove_if_present(marker_path)?;
        }
    }
    if config_existed {
        restore(&paths.config, config_path, config_mode)?;
    } else {
        remove_if_present(config_path)?;
    }
    Ok(())
}

fn copy_private(source: &Path, destination: &Path) -> Result<(), AnyError> {
    write_private(destination, &fs::read(source)?)
}

fn write_private(path: &Path, contents: &[u8]) -> Result<(), AnyError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut options = OpenOptions::new();
    options.create_new(true).write(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let mut file = options.open(path)?;
    file.write_all(contents)?;
    file.sync_all()?;
    Ok(())
}

fn remove_if_present(path: &Path) -> Result<(), std::io::Error> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error),
    }
}

fn digest(contents: &[u8]) -> String {
    hex::encode(Sha256::digest(contents))
}

#[cfg(unix)]
fn file_mode(path: &Path) -> Option<u32> {
    use std::os::unix::fs::PermissionsExt as _;

    fs::metadata(path)
        .ok()
        .map(|metadata| metadata.permissions().mode())
}

#[cfg(not(unix))]
fn file_mode(_path: &Path) -> Option<u32> {
    None
}

#[cfg(unix)]
fn set_file_mode(path: &Path, mode: Option<u32>) -> Result<(), std::io::Error> {
    use std::os::unix::fs::PermissionsExt as _;

    if let Some(mode) = mode {
        fs::set_permissions(path, fs::Permissions::from_mode(mode))?;
    }
    Ok(())
}

#[cfg(not(unix))]
fn set_file_mode(_path: &Path, _mode: Option<u32>) -> Result<(), std::io::Error> {
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn backup_paths_are_derived_from_the_config_path() {
        let paths = backup_paths(std::path::Path::new("/tmp/router/config.json"));
        // Both siblings live beside the config so a rollback is a local rename.
        assert!(
            paths
                .config
                .to_string_lossy()
                .starts_with("/tmp/router/config.json")
        );
        assert_ne!(paths.config, paths.marker);
        assert_ne!(paths.marker, paths.state);
    }

    #[test]
    fn append_adds_a_suffix_without_losing_the_stem() {
        let appended = append(std::path::Path::new("/tmp/a/config.json"), ".bak");
        assert_eq!(appended.to_string_lossy(), "/tmp/a/config.json.bak");
    }

    #[test]
    fn digest_is_stable_and_distinguishes_contents() {
        assert_eq!(digest(b"same"), digest(b"same"));
        assert_ne!(digest(b"same"), digest(b"other"));
        assert!(!digest(b"").is_empty());
    }

    #[test]
    fn removing_an_absent_path_succeeds() {
        let dir = tempfile::tempdir().expect("temp dir");
        // Idempotent: undo runs on machines where the file was never written.
        remove_if_present(&dir.path().join("nothing-here")).expect("absent path is fine");

        let present = dir.path().join("present");
        std::fs::write(&present, b"x").expect("write");
        remove_if_present(&present).expect("remove");
        assert!(!present.exists());
    }

    #[test]
    fn writing_privately_creates_a_readable_file() {
        let dir = tempfile::tempdir().expect("temp dir");
        let path = dir.path().join("secret.json");
        write_private(&path, b"{}").expect("write");
        assert_eq!(std::fs::read(&path).expect("read"), b"{}");
    }

    /// A restore puts back the exact bytes *and* the exact permissions. Losing
    /// the mode would silently widen access to a file that held a credential.
    #[test]
    fn a_restore_returns_the_bytes_and_the_mode() {
        let dir = tempfile::tempdir().expect("temp dir");
        let backup = dir.path().join("config.json.bak");
        let destination = dir.path().join("config.json");
        std::fs::write(&backup, b"{\"original\":true}").expect("seed backup");
        std::fs::write(&destination, b"{\"replaced\":true}").expect("seed destination");

        restore(&backup, &destination, Some(0o600)).expect("restore");

        assert_eq!(
            std::fs::read(&destination).expect("read"),
            b"{\"original\":true}"
        );
        // `file_mode` reports the raw `st_mode`, type bits included, and
        // answers `None` on platforms with no mode to report.
        #[cfg(unix)]
        assert_eq!(
            file_mode(&destination).map(|mode| mode & 0o777),
            Some(0o600)
        );
    }

    /// Undo of a client that had no configuration before `configure` ran must
    /// leave nothing behind, not an empty file the client would then read.
    #[test]
    fn a_rollback_removes_what_did_not_exist_before() {
        let dir = tempfile::tempdir().expect("temp dir");
        let config = dir.path().join("config.json");
        std::fs::write(&config, b"written by configure").expect("seed");
        let paths = backup_paths(&config);

        rollback(&paths, &config, false, None, None, false, None).expect("rollback");

        assert!(
            !config.exists(),
            "a config that did not exist must not remain"
        );
    }

    /// The other half: a configuration that *did* exist comes back byte for
    /// byte, and a marker file is rolled back alongside it.
    #[test]
    fn a_rollback_restores_what_existed_before() {
        let dir = tempfile::tempdir().expect("temp dir");
        let config = dir.path().join("config.json");
        let marker = dir.path().join("marker");
        let paths = backup_paths(&config);
        std::fs::write(&paths.config, b"the user's own config").expect("seed backup");
        std::fs::write(&paths.marker, b"the user's own marker").expect("seed marker backup");
        std::fs::write(&config, b"written by configure").expect("seed config");
        std::fs::write(&marker, b"written by configure").expect("seed marker");

        rollback(
            &paths,
            &config,
            true,
            Some(0o600),
            Some(&marker),
            true,
            Some(0o600),
        )
        .expect("rollback");

        assert_eq!(
            std::fs::read(&config).expect("read config"),
            b"the user's own config"
        );
        assert_eq!(
            std::fs::read(&marker).expect("read marker"),
            b"the user's own marker"
        );
    }

    /// A marker that did not exist before is removed rather than restored.
    #[test]
    fn a_rollback_removes_a_marker_that_did_not_exist_before() {
        let dir = tempfile::tempdir().expect("temp dir");
        let config = dir.path().join("config.json");
        let marker = dir.path().join("marker");
        let paths = backup_paths(&config);
        std::fs::write(&marker, b"written by configure").expect("seed marker");

        rollback(&paths, &config, false, None, Some(&marker), false, None).expect("rollback");

        assert!(!marker.exists());
    }

    /// Copying a configuration aside must not widen its permissions on the way.
    #[test]
    fn a_private_copy_keeps_the_contents_and_stays_private() {
        let dir = tempfile::tempdir().expect("temp dir");
        let source = dir.path().join("source.json");
        let destination = dir.path().join("nested/destination.json");
        std::fs::write(&source, b"{\"k\":1}").expect("seed");

        copy_private(&source, &destination).expect("copy");

        assert_eq!(std::fs::read(&destination).expect("read"), b"{\"k\":1}");
        #[cfg(unix)]
        assert_eq!(
            file_mode(&destination).map(|mode| mode & 0o777),
            Some(0o600),
            "a copy must not be world-readable"
        );
    }

    /// `file_mode` answers `None` for a path that is not there, which is what
    /// lets `apply` tell "no configuration yet" from "unreadable".
    #[test]
    fn the_mode_of_an_absent_file_is_unknown() {
        let dir = tempfile::tempdir().expect("temp dir");
        assert_eq!(file_mode(&dir.path().join("absent")), None);
    }

    /// Setting no mode is a no-op rather than an error: not every platform has
    /// one to set.
    #[test]
    fn setting_no_mode_leaves_the_file_alone() {
        let dir = tempfile::tempdir().expect("temp dir");
        let path = dir.path().join("f");
        std::fs::write(&path, b"x").expect("seed");
        set_file_mode(&path, None).expect("no mode is fine");
        assert_eq!(std::fs::read(&path).expect("read"), b"x");
    }
}

//! What the wrapped client is actually told to do.
//!
//! Two decisions are made here, and both used to be made by accident.
//!
//! **Which session the client starts.** A forwarded argument was read as "this
//! is a one-shot task", so `with claude --resume <id>` added `--print` and the
//! client was told to resume a session, answer once and exit — with no prompt
//! to answer. The client's own error was correct for what it had been asked to
//! do and mentioned neither `--print` nor the router (issue #297). A flag is
//! not a prompt: a bare positional is.
//!
//! **Which model and how hard it thinks.** `with` changes how the client
//! reaches the model. Which model it is, and the effort spent on an answer, are
//! the user's own settings, and replacing them for the duration of a run is a
//! much larger change than choosing a route (issue #295). Both are now left
//! alone unless the user asked, which is what `--global` already did.

use std::ffi::OsString;

use crate::cli::WithArgs;
use crate::clients::ClientKind;

/// The client's argv, plus anything worth telling the user about how it was
/// decided.
pub struct Launch {
    pub arguments: Vec<OsString>,
    /// Whether the client was told to answer once and exit.
    ///
    /// Carried out of here because the answer also decides whether the router
    /// may answer the client's own prompts on the user's behalf: a batch run
    /// cannot answer one, a person at a terminal can (issue #310).
    pub one_shot: bool,
    /// A mode that was inferred rather than stated, reported at the moment it
    /// is chosen. A wrong guess is otherwise invisible until it surfaces
    /// several lines into an error written by the client about itself.
    pub note: Option<&'static str>,
}

/// Whether this client cannot start at all without a model named for it.
///
/// These three are configured by a file that embeds the router's catalog, so
/// the id is part of the configuration the router must write for them to run.
/// That is the client's requirement rather than a preference being overridden,
/// which is why it survives the rule in issue #295.
#[must_use]
pub const fn requires_a_model(client: ClientKind) -> bool {
    matches!(
        client,
        ClientKind::Opencode | ClientKind::QwenCode | ClientKind::Agent
    )
}

/// Whether the run is a one-shot task rather than an interactive session.
///
/// `attached_to_a_terminal` is passed in so the rule is testable without a tty.
fn is_one_shot(args: &WithArgs, forwarded: &[OsString], attached_to_a_terminal: bool) -> bool {
    if args.non_interactive {
        return true;
    }
    if args.interactive {
        return false;
    }
    // A bare positional is a prompt; a flag is an option passed to a session.
    // Reading "any argument at all" as a task turned `--resume`, `--continue`,
    // `--verbose`, `--debug` and `--add-dir` into batch runs (issue #297).
    carries_a_prompt(args.client, forwarded) || !attached_to_a_terminal
}

fn carries_a_prompt(client: ClientKind, forwarded: &[OsString]) -> bool {
    forwarded.first().is_some_and(|argument| {
        !argument.to_string_lossy().starts_with('-')
            && !is_native_command(client, argument.to_string_lossy().as_ref())
    })
}

