//! Verified directory backups and merge-first profile restore.

use std::collections::BTreeSet;
use std::fs::{self, File};
use std::io::Read;
#[cfg(unix)]
use std::os::unix::fs::FileTypeExt as _;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use super::{
    Profile, Store, backup_root, clients, failed, lock_operations, owner_directory, profiles,
    refuse_active,
};
use crate::cli::{BackupOp, ProfileSelection};
use crate::clients::ClientKind;

mod restore;

#[derive(Clone, Debug, Serialize, Deserialize, schemars::JsonSchema)]
struct Entry {
    client: String,
    scope: String,
    store: String,
    path: String,
    kind: String,
    size: u64,
    sha256: Option<String>,
    link: Option<String>,
    #[serde(default)]
    backup_link: Option<String>,
    mode: Option<u32>,
}

#[derive(Clone, Debug, Serialize, Deserialize, schemars::JsonSchema)]
struct StoreRecord {
    client: String,
    scope: String,
    store: String,
    source: String,
}

#[derive(Debug, Serialize, Deserialize, schemars::JsonSchema)]
pub(crate) struct Manifest {
    version: u32,
    id: String,
    created: String,
    credentials_included: bool,
    stores: Vec<StoreRecord>,
    entries: Vec<Entry>,
    unavailable: Vec<String>,
    omitted_credentials: usize,
}

fn component(value: &str) -> bool {
    !value.is_empty()
        && !value.contains(['/', '\\', ':'])
        && Path::new(value).components().count() == 1
        && matches!(
            Path::new(value).components().next(),
            Some(std::path::Component::Normal(_))
        )
}

fn digest(path: &Path) -> Result<String, String> {
    let mut file =
        File::open(path).map_err(|error| format!("cannot read file for verification: {error}"))?;
    let mut hash = Sha256::new();
    let mut buffer = [0u8; 16 * 1024];
    loop {
        let count = file
            .read(&mut buffer)
            .map_err(|error| format!("cannot hash file: {error}"))?;
        if count == 0 {
            break;
        }
        hash.update(&buffer[..count]);
    }
    Ok(hex::encode(hash.finalize()))
}

pub(super) fn tree_digest(path: &Path) -> Result<String, String> {
    fn add(path: &Path, hash: &mut Sha256) -> Result<(), String> {
        let metadata = fs::symlink_metadata(path).map_err(|error| error.to_string())?;
        #[cfg(unix)]
        if metadata.file_type().is_socket() {
            return Ok(());
        }
        if let Some(mode) = mode(path)? {
            hash.update(mode.to_le_bytes());
        }
        if metadata.is_file() {
            hash.update(b"file");
            hash.update(digest(path)?.as_bytes());
        } else if metadata.file_type().is_symlink() {
            hash.update(b"link");
            hash.update(
                fs::read_link(path)
                    .map_err(|error| error.to_string())?
                    .as_os_str()
                    .as_encoded_bytes(),
            );
        } else if metadata.is_dir() {
            hash.update(b"dir");
            let mut entries = fs::read_dir(path)
                .map_err(|error| error.to_string())?
                .collect::<Result<Vec<_>, _>>()
                .map_err(|error| error.to_string())?;
            entries.sort_by_key(std::fs::DirEntry::file_name);
            for entry in entries {
                hash.update(entry.file_name().as_encoded_bytes());
                add(&entry.path(), hash)?;
            }
        } else {
            return Err("unsupported profile entry changed during operation".to_string());
        }
        Ok(())
    }
    let mut hash = Sha256::new();
    add(path, &mut hash)?;
    Ok(hex::encode(hash.finalize()))
}

fn mode(path: &Path) -> Result<Option<u32>, String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        Ok(Some(
            fs::symlink_metadata(path)
                .map_err(|error| error.to_string())?
                .permissions()
                .mode()
                & 0o7777,
        ))
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        Ok(None)
    }
}

fn set_mode(path: &Path, value: Option<u32>) -> Result<(), String> {
    #[cfg(unix)]
    if let Some(value) = value {
        use std::os::unix::fs::PermissionsExt as _;
        fs::set_permissions(path, fs::Permissions::from_mode(value))
            .map_err(|error| format!("cannot preserve file permissions: {error}"))?;
    }
    #[cfg(not(unix))]
    {
        let _ = (path, value);
    }
    Ok(())
}

fn is_credential(path: &Path) -> bool {
    let name = path
        .file_name()
        .map(|name| name.to_string_lossy().to_ascii_lowercase())
        .unwrap_or_default();
    name == ".claude.json"
        || name == "auth.json"
        || name == "oauth_creds.json"
        || name == ".credentials.json"
        || name == "credentials.json"
        || name == ".env"
        || name.contains("secret")
        || name.contains("token")
        || name.contains("keychain")
}

fn is_disposable(path: &Path) -> bool {
    path.components().any(|component| {
        let name = component.as_os_str().to_string_lossy();
        matches!(
            name.as_ref(),
            "cache" | "Cache" | "CachedData" | "node_modules"
        )
    })
}

fn copy_file(source: &Path, destination: &Path) -> Result<(), String> {
    reflink_copy::reflink_or_copy(source, destination)
        .map_err(|error| format!("cannot copy profile file: {error}"))?;
    set_mode(destination, mode(source)?)
}

fn copy_link(source: &Path, destination: &Path, root: &Path) -> Result<String, String> {
    let target = fs::read_link(source).map_err(|error| format!("cannot read symlink: {error}"))?;
    let resolved = if target.is_absolute() {
        target.clone()
    } else {
        source
            .parent()
            .ok_or("symlink has no parent")?
            .join(&target)
    };
    let canonical_root =
        fs::canonicalize(root).map_err(|error| format!("cannot resolve profile root: {error}"))?;
    let canonical_target = fs::canonicalize(resolved)
        .map_err(|_| "dangling symlink in profile; repair it before backup".to_string())?;
    if !canonical_target.starts_with(canonical_root) {
        return Err("symlink escapes the selected profile; backup refused".to_string());
    }
    #[cfg(unix)]
    std::os::unix::fs::symlink(&target, destination)
        .map_err(|error| format!("cannot preserve symlink: {error}"))?;
    #[cfg(windows)]
    {
        if canonical_target.is_dir() {
            std::os::windows::fs::symlink_dir(&target, destination)
        } else {
            std::os::windows::fs::symlink_file(&target, destination)
        }
        .map_err(|error| format!("cannot preserve symlink: {error}"))?;
    }
    Ok(target.to_string_lossy().into_owned())
}

#[allow(clippy::too_many_arguments)]
fn walk(
    source: &Path,
    root: &Path,
    destination: &Path,
    client: &str,
    scope: &str,
    store: &str,
    include_credentials: bool,
    entries: &mut Vec<Entry>,
    omitted: &mut usize,
    estimate_only: bool,
) -> Result<u64, String> {
    let metadata = fs::symlink_metadata(source)
        .map_err(|error| format!("cannot inspect profile entry: {error}"))?;
    let relative = source
        .strip_prefix(root)
        .map_err(|error| error.to_string())?;
    let relative_text = relative
        .to_str()
        .ok_or("non-UTF-8 profile path is unsupported")?
        .replace('\\', "/");
    if is_disposable(relative) {
        return Ok(0);
    }
    if metadata.is_file()
        && is_credential(if relative.as_os_str().is_empty() {
            source
        } else {
            relative
        })
        && !include_credentials
    {
        *omitted += 1;
        return Ok(0);
    }
    #[cfg(unix)]
    if metadata.file_type().is_socket() {
        return Ok(0);
    }
    if metadata.is_file()
        && (relative_text.ends_with("-wal")
            || relative_text.ends_with("-shm")
            || relative_text.ends_with("-journal"))
    {
        return Err(
            "live SQLite sidecar found; close the client or checkpoint its database before backup"
                .to_string(),
        );
    }
    let output = destination.join(relative);
    let kind = if metadata.is_dir() {
        "directory"
    } else if metadata.is_file() {
        "file"
    } else if metadata.file_type().is_symlink() {
        "symlink"
    } else {
        return Err("unsupported profile entry type; backup refused".to_string());
    };
    let mut entry = Entry {
        client: client.into(),
        scope: scope.into(),
        store: store.into(),
        path: relative_text,
        kind: kind.into(),
        size: if kind == "file" { metadata.len() } else { 0 },
        sha256: None,
        link: None,
        backup_link: None,
        mode: mode(source)?,
    };
    let entry_mode = entry.mode;
    if !estimate_only {
        if kind == "directory" {
            fs::create_dir_all(&output)
                .map_err(|error| format!("cannot create backup directory: {error}"))?;
        } else if kind == "file" {
            if let Some(parent) = output.parent() {
                fs::create_dir_all(parent).map_err(|error| error.to_string())?;
            }
            let before = digest(source)?;
            copy_file(source, &output)?;
            let after = digest(source)?;
            if before != after
                || digest(&output)? != after
                || fs::metadata(source)
                    .map_err(|error| error.to_string())?
                    .len()
                    != metadata.len()
            {
                return Err("profile changed while copying; close the client and retry".to_string());
            }
            entry.sha256 = Some(after);
        } else {
            if let Some(parent) = output.parent() {
                fs::create_dir_all(parent).map_err(|error| error.to_string())?;
            }
            let original = copy_link(source, &output, root)?;
            let mut archived = original.clone();
            let target = Path::new(&original);
            if target.is_absolute() {
                let target_relative = target
                    .strip_prefix(root)
                    .map_err(|_| "absolute symlink escapes the profile root".to_string())?;
                if target_relative
                    .components()
                    .any(|part| !matches!(part, std::path::Component::Normal(_)))
                {
                    return Err("unsafe absolute profile symlink".to_string());
                }
                let mut relative_link = PathBuf::new();
                for _ in relative
                    .parent()
                    .unwrap_or_else(|| Path::new(""))
                    .components()
                {
                    relative_link.push("..");
                }
                relative_link.push(target_relative);
                fs::remove_file(&output).map_err(|error| error.to_string())?;
                #[cfg(unix)]
                std::os::unix::fs::symlink(&relative_link, &output)
                    .map_err(|error| error.to_string())?;
                #[cfg(windows)]
                {
                    if fs::canonicalize(source)
                        .map_err(|error| error.to_string())?
                        .is_dir()
                    {
                        std::os::windows::fs::symlink_dir(&relative_link, &output)
                    } else {
                        std::os::windows::fs::symlink_file(&relative_link, &output)
                    }
                    .map_err(|error| error.to_string())?;
                }
                archived = relative_link.to_string_lossy().into_owned();
            }
            entry.link = Some(original);
            entry.backup_link = Some(archived);
        }
        entries.push(entry);
    }
    let mut total = if kind == "file" { metadata.len() } else { 0 };
    if kind == "directory" {
        let mut children = fs::read_dir(source)
            .map_err(|error| format!("cannot list profile directory: {error}"))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("cannot read profile directory: {error}"))?;
        children.sort_by_key(std::fs::DirEntry::file_name);
        for child in children {
            total += walk(
                &child.path(),
                root,
                destination,
                client,
                scope,
                store,
                include_credentials,
                entries,
                omitted,
                estimate_only,
            )?;
        }
        if !estimate_only {
            set_mode(&output, entry_mode)?;
        }
    }
    Ok(total)
}

pub fn create_unlocked(
    root: &Path,
    home: Option<&Path>,
    chosen: &[Profile],
    include_credentials: bool,
) -> Result<String, String> {
    owner_directory(root)?;
    let archive_root = fs::canonicalize(root)
        .map_err(|error| format!("cannot resolve backup destination: {error}"))?;
    let id = uuid::Uuid::new_v4().simple().to_string();
    let temporary = root.join(format!(".incomplete-{id}"));
    let final_path = root.join(&id);
    let mut manifest = Manifest {
        version: 1,
        id: id.clone(),
        created: crate::operation_context::now().to_rfc3339(),
        credentials_included: include_credentials,
        stores: Vec::new(),
        entries: Vec::new(),
        unavailable: Vec::new(),
        omitted_credentials: 0,
    };
    let mut total = 0u64;
    for profile in chosen {
        refuse_active(profile, home)?;
        for store in &profile.stores {
            if !store.path.exists() {
                manifest.unavailable.push(format!(
                    "{}:{}:{}",
                    profile.client, profile.scope, store.name
                ));
                continue;
            }
            if fs::symlink_metadata(&store.path)
                .map_err(|error| error.to_string())?
                .file_type()
                .is_symlink()
            {
                return Err(format!(
                    "{} {} profile root is a symlink; select its real path explicitly",
                    profile.client, profile.scope
                ));
            }
            let profile_root = fs::canonicalize(&store.path)
                .map_err(|error| format!("cannot resolve selected profile: {error}"))?;
            if archive_root.starts_with(&profile_root) {
                return Err(
                    "backup destination is inside a selected profile; choose another directory"
                        .to_string(),
                );
            }
            total += walk(
                &store.path,
                &store.path,
                Path::new(""),
                profile.client.canonical_name(),
                profile.scope,
                &store.name,
                include_credentials,
                &mut Vec::new(),
                &mut 0,
                true,
            )?;
        }
    }
    if chosen
        .iter()
        .all(|profile| profile.stores.iter().all(|store| !store.path.exists()))
    {
        return Err("no selected client profile store exists".to_string());
    }
    let free = fs2::available_space(root)
        .map_err(|error| format!("cannot check destination free space: {error}"))?;
    eprintln!("backup requires {total} bytes; destination has {free} bytes free");
    if free < total.saturating_add(1024 * 1024) {
        return Err("backup destination lacks free space; no backup was written".to_string());
    }
    owner_directory(&temporary)?;
    let result = (|| {
        for profile in chosen {
            for store in &profile.stores {
                if !store.path.exists() {
                    continue;
                }
                let client = profile.client.canonical_name();
                let destination = temporary
                    .join("data")
                    .join(client)
                    .join(profile.scope)
                    .join(&store.name);
                let before = tree_digest(&store.path)?;
                let before_entries = manifest.entries.len();
                walk(
                    &store.path,
                    &store.path,
                    &destination,
                    client,
                    profile.scope,
                    &store.name,
                    include_credentials,
                    &mut manifest.entries,
                    &mut manifest.omitted_credentials,
                    false,
                )?;
                if tree_digest(&store.path)? != before {
                    return Err("profile changed during backup; close the client and retry".into());
                }
                if manifest.entries.len() == before_entries {
                    continue;
                }
                manifest.stores.push(StoreRecord {
                    client: client.into(),
                    scope: profile.scope.into(),
                    store: store.name.clone(),
                    source: store.path.to_string_lossy().into_owned(),
                });
            }
        }
        if manifest.stores.is_empty() {
            return Err("selected profile stores disappeared during backup".to_string());
        }
        let bytes = serde_json::to_vec_pretty(&manifest).map_err(|error| error.to_string())?;
        crate::durable_file::atomic_write_owner_only(&temporary.join("manifest.json"), &bytes)
            .map_err(|error| format!("cannot save backup manifest: {error}"))?;
        crate::durable_file::atomic_write_owner_only(
            &temporary.join("manifest.sha256"),
            hex::encode(Sha256::digest(&bytes)).as_bytes(),
        )
        .map_err(|error| format!("cannot save backup checksum: {error}"))?;
        verify_path(&temporary)?;
        fs::rename(&temporary, &final_path)
            .map_err(|error| format!("cannot complete backup: {error}"))?;
        Ok::<(), String>(())
    })();
    if result.is_err() {
        let _ = fs::remove_dir_all(&temporary);
    }
    result?;
    for unavailable in &manifest.unavailable {
        eprintln!("unavailable profile store: {unavailable}");
    }
    if manifest.omitted_credentials > 0 {
        eprintln!(
            "omitted {} credential entries; --include-credentials creates an unencrypted private local backup",
            manifest.omitted_credentials
        );
    }
    Ok(id)
}

fn validate_id(id: &str) -> Result<(), String> {
    if id.len() == 32 && id.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        Ok(())
    } else {
        Err("invalid backup ID".to_string())
    }
}

fn load(root: &Path, id: &str) -> Result<(PathBuf, Manifest), String> {
    validate_id(id)?;
    let path = root.join(id);
    let manifest = verify_path(&path)?;
    if manifest.id != id {
        return Err("backup ID does not match its manifest".to_string());
    }
    Ok((path, manifest))
}

fn verify_path(path: &Path) -> Result<Manifest, String> {
    let bytes = fs::read(path.join("manifest.json"))
        .map_err(|_| "backup is incomplete or missing its manifest".to_string())?;
    let checksum = fs::read_to_string(path.join("manifest.sha256"))
        .map_err(|_| "backup is incomplete or missing its manifest checksum".to_string())?;
    if hex::encode(Sha256::digest(&bytes)) != checksum {
        return Err("backup manifest checksum mismatch".to_string());
    }
    let manifest: Manifest = serde_json::from_slice(&bytes)
        .map_err(|error| format!("invalid backup manifest: {error}"))?;
    if manifest.version != 1 {
        return Err("unsupported backup format".to_string());
    }
    let mut known = BTreeSet::new();
    for store in &manifest.stores {
        if ClientKind::from_str_opt(&store.client).is_none()
            || !matches!(store.scope.as_str(), "normal" | "router")
            || !component(&store.store)
            || !known.insert((&store.client, &store.scope, &store.store))
        {
            return Err("invalid backup store inventory".to_string());
        }
    }
    let mut expected = BTreeSet::new();
    for entry in &manifest.entries {
        if !known.contains(&(&entry.client, &entry.scope, &entry.store)) {
            return Err("backup entry refers to an unknown store".to_string());
        }
        let path_part = Path::new(&entry.path);
        if entry.path.contains(['\\', ':'])
            || path_part.is_absolute()
            || path_part
                .components()
                .any(|part| !matches!(part, std::path::Component::Normal(_)))
        {
            return Err("unsafe backup manifest path".to_string());
        }
        let entry_path = path
            .join("data")
            .join(&entry.client)
            .join(&entry.scope)
            .join(&entry.store)
            .join(path_part);
        let metadata = fs::symlink_metadata(&entry_path)
            .map_err(|_| "backup inventory is missing an entry".to_string())?;
        let kind = if metadata.is_file() {
            "file"
        } else if metadata.is_dir() {
            "directory"
        } else if metadata.file_type().is_symlink() {
            "symlink"
        } else {
            "unsupported"
        };
        if kind != entry.kind
            || (kind == "file" && metadata.len() != entry.size)
            || mode(&entry_path)? != entry.mode
        {
            return Err("backup inventory or permissions mismatch".to_string());
        }
        if kind == "file" && entry.sha256.as_deref() != Some(digest(&entry_path)?.as_str()) {
            return Err("backup file checksum mismatch".to_string());
        }
        if kind == "symlink"
            && fs::read_link(&entry_path)
                .map_err(|error| error.to_string())?
                .to_string_lossy()
                != entry
                    .backup_link
                    .as_deref()
                    .or(entry.link.as_deref())
                    .unwrap_or("")
        {
            return Err("backup symlink mismatch".to_string());
        }
        if kind == "symlink" {
            let resolved = fs::canonicalize(&entry_path)
                .map_err(|_| "backed-up symlink target is unavailable".to_string())?;
            let store_root = fs::canonicalize(
                path.join("data")
                    .join(&entry.client)
                    .join(&entry.scope)
                    .join(&entry.store),
            )
            .map_err(|error| error.to_string())?;
            if !resolved.starts_with(store_root) {
                return Err("backed-up symlink escapes its store".to_string());
            }
        }
        if !expected.insert(entry_path) {
            return Err("duplicate backup inventory entry".to_string());
        }
    }
    let data = path.join("data");
    if data.exists() {
        fn visit(path: &Path, found: &mut BTreeSet<PathBuf>) -> Result<(), String> {
            for item in fs::read_dir(path).map_err(|error| error.to_string())? {
                let item = item.map_err(|error| error.to_string())?;
                let item_path = item.path();
                found.insert(item_path.clone());
                if item
                    .file_type()
                    .map_err(|error| error.to_string())?
                    .is_dir()
                {
                    visit(&item_path, found)?;
                }
            }
            Ok(())
        }
        let mut found = BTreeSet::new();
        visit(&data, &mut found)?;
        found.retain(|path| {
            path.strip_prefix(&data)
                .map_or(true, |relative| relative.components().count() >= 3)
        });
        if found != expected {
            return Err("backup exact inventory mismatch".to_string());
        }
    }
    if let Some(sample) = manifest.entries.iter().find(|entry| entry.kind == "file") {
        let source = path
            .join("data")
            .join(&sample.client)
            .join(&sample.scope)
            .join(&sample.store)
            .join(&sample.path);
        let temporary = tempfile::tempdir().map_err(|error| error.to_string())?;
        let restored = temporary.path().join("sample");
        copy_file(&source, &restored)?;
        if digest(&restored)? != sample.sha256.as_deref().unwrap_or("") {
            return Err("sample restore checksum mismatch".to_string());
        }
    }
    Ok(manifest)
}

#[must_use]
pub fn run(home: Option<&Path>, op: &BackupOp) -> ExitCode {
    let result = match op {
        BackupOp::Create {
            selection,
            destination,
            include_credentials,
        } => {
            let root = backup_root(home, destination.as_deref());
            root.and_then(|root| {
                let _lock = lock_operations(&root)?;
                let mut chosen = Vec::new();
                for client in clients(selection) {
                    chosen.extend(profiles(home, client, selection.profile)?);
                }
                let id = create_unlocked(&root, home, &chosen, *include_credentials)?;
                println!("{id}");
                Ok(())
            })
        }
        BackupOp::List { json, destination } => {
            backup_root(home, destination.as_deref()).and_then(|root| {
                let mut rows = Vec::new();
                if root.exists() {
                    for item in fs::read_dir(&root).map_err(|error| error.to_string())? {
                        let item = item.map_err(|error| error.to_string())?;
                        let id = item.file_name().to_string_lossy().into_owned();
                        if validate_id(&id).is_ok() && item.path().join("manifest.sha256").exists()
                        {
                            rows.push(id);
                        }
                    }
                }
                rows.sort();
                if *json {
                    println!(
                        "{}",
                        serde_json::to_string(&rows).map_err(|error| error.to_string())?
                    );
                } else {
                    for row in rows {
                        println!("{row}");
                    }
                }
                Ok(())
            })
        }
        BackupOp::Verify { id, destination } => {
            backup_root(home, destination.as_deref()).and_then(|root| {
                crate::operation_output::report(
                    crate::operation_reports::BackupVerificationReport {
                        id: id.clone(),
                        verified: false,
                        output: Vec::new(),
                    },
                );
                load(&root, id)?;
                crate::operation_output::report(
                    crate::operation_reports::BackupVerificationReport {
                        id: id.clone(),
                        verified: true,
                        output: Vec::new(),
                    },
                );
                println!("verified {id}");
                Ok(())
            })
        }
        BackupOp::Restore {
            id,
            client,
            merge: _,
            overwrite,
            dry_run,
            yes,
            destination,
        } => backup_root(home, destination.as_deref())
            .and_then(|root| restore::run(&root, home, id, *client, *overwrite, *dry_run, *yes)),
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => failed(error),
    }
}

//! Transactional merge-first restore of a verified client backup.

use super::{
    ClientKind, Entry, Path, PathBuf, Profile, ProfileSelection, Sha256, Store, StoreRecord,
    copy_file, copy_link, create_unlocked, digest, fs, is_credential, load, lock_operations, mode,
    profiles, refuse_active, set_mode, tree_digest,
};
use sha2::Digest as _;

fn restore_link(
    _source: &Path,
    original_link: &str,
    destination: &Path,
    stage: &Path,
    original_root: &Path,
    live_root: &Path,
) -> Result<(), String> {
    let target = PathBuf::from(original_link);
    #[cfg(windows)]
    let original_target = target.clone();
    let replacement = if target.is_absolute() {
        let relative = target
            .strip_prefix(original_root)
            .map_err(|_| "absolute backed-up symlink escapes its original profile".to_string())?;
        if relative
            .components()
            .any(|part| !matches!(part, std::path::Component::Normal(_)))
        {
            return Err("unsafe absolute symlink target".to_string());
        }
        live_root.join(relative)
    } else {
        let parent = destination.parent().ok_or("symlink has no parent")?;
        let relative_parent = parent
            .strip_prefix(stage)
            .map_err(|_| "symlink escapes staged profile")?;
        let mut depth = relative_parent.components().count();
        for part in target.components() {
            match part {
                std::path::Component::ParentDir if depth > 0 => depth -= 1,
                std::path::Component::ParentDir => {
                    return Err("restored symlink would escape the profile".to_string());
                }
                std::path::Component::Normal(_) => depth += 1,
                std::path::Component::CurDir => (),
                _ => return Err("unsafe symlink target".to_string()),
            }
        }
        target
    };
    #[cfg(unix)]
    std::os::unix::fs::symlink(&replacement, destination).map_err(|error| error.to_string())?;
    #[cfg(windows)]
    {
        let archived_target = if original_target.is_absolute() {
            let link_relative = destination
                .strip_prefix(stage)
                .map_err(|_| "unsafe symlink location")?;
            let archive_root = _source
                .ancestors()
                .nth(link_relative.components().count())
                .ok_or("unsafe archive symlink location")?;
            archive_root.join(
                original_target
                    .strip_prefix(original_root)
                    .map_err(|_| "unsafe symlink target")?,
            )
        } else {
            _source
                .parent()
                .ok_or("symlink has no parent")?
                .join(&original_target)
        };
        if archived_target.is_dir() {
            std::os::windows::fs::symlink_dir(&replacement, destination)
        } else {
            std::os::windows::fs::symlink_file(&replacement, destination)
        }
        .map_err(|error| error.to_string())?;
    }
    Ok(())
}

fn copy_existing(source: &Path, destination: &Path, root: &Path) -> Result<(), String> {
    let metadata = fs::symlink_metadata(source).map_err(|error| error.to_string())?;
    if metadata.is_dir() {
        fs::create_dir(destination).map_err(|error| error.to_string())?;
        for item in fs::read_dir(source).map_err(|error| error.to_string())? {
            let item = item.map_err(|error| error.to_string())?;
            copy_existing(&item.path(), &destination.join(item.file_name()), root)?;
        }
        set_mode(destination, mode(source)?)?;
    } else if metadata.is_file() {
        let before = digest(source)?;
        copy_file(source, destination)?;
        if digest(source)? != before || digest(destination)? != before {
            return Err("live profile changed while staging restore".to_string());
        }
    } else if metadata.file_type().is_symlink() {
        copy_link(source, destination, root)?;
    } else {
        return Err("unsupported entry in live profile".to_string());
    }
    Ok(())
}

fn remove_any(path: &Path) -> Result<(), String> {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return Ok(());
    };
    if metadata.is_dir() {
        fs::remove_dir_all(path)
    } else {
        fs::remove_file(path)
    }
    .map_err(|error| error.to_string())
}

fn present(path: &Path) -> bool {
    fs::symlink_metadata(path).is_ok()
}

fn rollback_committed(committed: &[(PathBuf, PathBuf, bool)]) -> Vec<String> {
    let mut errors = Vec::new();
    for (target, previous, existed) in committed.iter().rev() {
        if let Err(error) = remove_any(target) {
            errors.push(format!("{}: {error}", target.display()));
            continue;
        }
        if *existed && let Err(error) = fs::rename(previous, target) {
            errors.push(format!("{}: {error}", target.display()));
        }
    }
    errors
}

fn restore_error(error: &std::io::Error, rollback_errors: &[String]) -> String {
    if rollback_errors.is_empty() {
        format!("restore rolled back after failure: {error}")
    } else {
        format!(
            "restore failed: {error}; rollback incomplete ({}); inspect the .router-restore-old-* paths and recovery backup",
            rollback_errors.join("; ")
        )
    }
}

fn entry_matches(path: &Path, entry: &Entry, original_root: &Path, live_root: &Path) -> bool {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return false;
    };
    match entry.kind.as_str() {
        "file" if metadata.is_file() => digest(path).ok().as_deref() == entry.sha256.as_deref(),
        "symlink" if metadata.file_type().is_symlink() => {
            let Some(link) = entry.link.as_deref() else {
                return false;
            };
            let target = Path::new(link);
            let expected = if target.is_absolute() {
                let Ok(relative) = target.strip_prefix(original_root) else {
                    return false;
                };
                live_root.join(relative)
            } else {
                target.to_path_buf()
            };
            fs::read_link(path).is_ok_and(|actual| actual == expected)
        }
        _ => false,
    }
}

fn conflict_suffix(entry: &Entry) -> Result<String, String> {
    if entry.kind == "file" {
        return Ok(entry.sha256.as_deref().ok_or("file has no digest")?[..8].into());
    }
    let link = entry.link.as_deref().ok_or("link has no target")?;
    Ok(hex::encode(Sha256::digest(link.as_bytes()))[..8].into())
}

fn validate_links(path: &Path, stage: &Path, live: &Path) -> Result<(), String> {
    let metadata = fs::symlink_metadata(path).map_err(|error| error.to_string())?;
    if metadata.file_type().is_symlink() {
        let target = fs::read_link(path).map_err(|error| error.to_string())?;
        let canonical_live = fs::canonicalize(live).ok();
        if target.is_absolute() {
            let within_live = target.starts_with(live)
                || canonical_live.as_ref().is_some_and(|root| {
                    fs::canonicalize(&target).is_ok_and(|resolved| resolved.starts_with(root))
                });
            if !within_live
                || target
                    .components()
                    .any(|part| matches!(part, std::path::Component::ParentDir))
            {
                return Err("staged absolute symlink escapes the selected profile".to_string());
            }
        } else {
            let resolved = fs::canonicalize(path)
                .map_err(|_| "staged symlink target is missing".to_string())?;
            let canonical_stage =
                fs::canonicalize(stage).map_err(|_| "staged profile is missing".to_string())?;
            if !resolved.starts_with(canonical_stage)
                && !canonical_live
                    .as_ref()
                    .is_some_and(|root| resolved.starts_with(root))
            {
                return Err("staged symlink escapes the selected profile".to_string());
            }
        }
    } else if metadata.is_dir() {
        for item in fs::read_dir(path).map_err(|error| error.to_string())? {
            validate_links(
                &item.map_err(|error| error.to_string())?.path(),
                stage,
                live,
            )?;
        }
    }
    Ok(())
}

pub(super) fn run(
    root: &Path,
    home: Option<&Path>,
    id: &str,
    filter: Option<ClientKind>,
    overwrite: bool,
    dry_run: bool,
    yes: bool,
) -> Result<(), String> {
    let _lock = if dry_run {
        None
    } else {
        Some(lock_operations(root)?)
    };
    let (backup_path, manifest) = load(root, id)?;
    let mut targets = Vec::<(StoreRecord, PathBuf)>::new();
    for record in &manifest.stores {
        if let Some(filter) = filter
            && record.client != filter.canonical_name()
        {
            continue;
        }
        let client = ClientKind::from_str_opt(&record.client).ok_or("unknown client in backup")?;
        let selection = if record.scope == "router" {
            ProfileSelection::Router
        } else {
            ProfileSelection::Normal
        };
        let current = profiles(home, client, selection)?;
        refuse_active(&current[0], home)?;
        let store = current[0]
            .stores
            .iter()
            .find(|store| store.name == record.store)
            .ok_or("profile store no longer exists in client inventory")?;
        if fs::symlink_metadata(&store.path).is_ok_and(|metadata| metadata.file_type().is_symlink())
        {
            return Err("live profile root is a symlink; restore refused".to_string());
        }
        targets.push((record.clone(), store.path.clone()));
    }
    if targets.is_empty() {
        return Err("backup contains no matching client profile".to_string());
    }
    let mut changes = Vec::new();
    for (record, target) in &targets {
        for entry in manifest.entries.iter().filter(|entry| {
            entry.client == record.client
                && entry.scope == record.scope
                && entry.store == record.store
                && entry.kind != "directory"
        }) {
            let candidate = target.join(&entry.path);
            if !entry_matches(&candidate, entry, Path::new(&record.source), target) {
                changes.push((candidate, entry));
            }
        }
    }
    if dry_run {
        for (path, entry) in &changes {
            let action = if present(path) {
                if overwrite { "overwrite" } else { "keep both" }
            } else {
                "add"
            };
            println!(
                "{action}: {}",
                if is_credential(if entry.path.is_empty() {
                    path
                } else {
                    Path::new(&entry.path)
                }) {
                    "<credential>".into()
                } else {
                    path.display().to_string()
                }
            );
        }
        return Ok(());
    }
    if overwrite && !yes {
        return Err("overwrite requires --yes after reviewing --dry-run".to_string());
    }
    if overwrite {
        let selected = targets
            .iter()
            .map(|(record, path)| Profile {
                client: ClientKind::from_str_opt(&record.client).expect("validated"),
                scope: if record.scope == "router" {
                    "router"
                } else {
                    "normal"
                },
                stores: vec![Store {
                    name: record.store.clone(),
                    path: path.clone(),
                }],
            })
            .collect::<Vec<_>>();
        let recovery = create_unlocked(root, home, &selected, true)?;
        eprintln!("verified recovery backup: {recovery}");
    }
    let stamps = targets
        .iter()
        .map(|(_, target)| {
            if present(target) {
                Ok((target.clone(), Some(tree_digest(target)?)))
            } else {
                Ok((target.clone(), None))
            }
        })
        .collect::<Result<Vec<_>, String>>()?;
    let mut stages = Vec::<(PathBuf, PathBuf, PathBuf)>::new();
    let tx = uuid::Uuid::new_v4().simple().to_string();
    let preparation = (|| {
        for (record, target) in &targets {
            let parent = target.parent().ok_or("profile store has no parent")?;
            fs::create_dir_all(parent).map_err(|error| error.to_string())?;
            let name = target
                .file_name()
                .ok_or("profile store has no name")?
                .to_string_lossy();
            let stage = parent.join(format!(".{name}.router-restore-stage-{tx}"));
            let previous = parent.join(format!(".{name}.router-restore-old-{tx}"));
            stages.push((target.clone(), stage.clone(), previous));
            let root_is_file = manifest.entries.iter().any(|entry| {
                entry.client == record.client
                    && entry.scope == record.scope
                    && entry.store == record.store
                    && entry.path.is_empty()
                    && entry.kind == "file"
            });
            if target.exists() {
                copy_existing(target, &stage, target)?;
            } else if !root_is_file {
                fs::create_dir(&stage).map_err(|error| error.to_string())?;
            }
            for entry in manifest.entries.iter().filter(|entry| {
                entry.client == record.client
                    && entry.scope == record.scope
                    && entry.store == record.store
            }) {
                let source = backup_path
                    .join("data")
                    .join(&entry.client)
                    .join(&entry.scope)
                    .join(&entry.store)
                    .join(&entry.path);
                let destination = stage.join(&entry.path);
                if entry.kind == "directory" {
                    fs::create_dir_all(&destination).map_err(|error| error.to_string())?;
                    continue;
                }
                if entry.path.is_empty()
                    && present(&destination)
                    && !overwrite
                    && !entry_matches(&destination, entry, Path::new(&record.source), target)
                {
                    return Err(
                        "root file conflict: review --dry-run and use --overwrite to replace it"
                            .to_string(),
                    );
                }
                if let Some(parent) = destination.parent() {
                    fs::create_dir_all(parent).map_err(|error| error.to_string())?;
                }
                let mut chosen = destination.clone();
                if present(&destination) {
                    if entry_matches(&destination, entry, Path::new(&record.source), target) {
                        continue;
                    }
                    if !overwrite && !entry.path.is_empty() {
                        chosen = destination.with_file_name(format!(
                            "{}.router-conflict-{}",
                            destination
                                .file_name()
                                .ok_or("bad filename")?
                                .to_string_lossy(),
                            conflict_suffix(entry)?
                        ));
                        if present(&chosen) {
                            if entry_matches(&chosen, entry, Path::new(&record.source), target) {
                                continue;
                            }
                            return Err(format!(
                                "restore conflict path already exists with different content: {}",
                                chosen.display()
                            ));
                        }
                    } else {
                        remove_any(&destination)?;
                    }
                }
                if entry.kind == "file" {
                    copy_file(&source, &chosen)?;
                } else {
                    restore_link(
                        &source,
                        entry
                            .link
                            .as_deref()
                            .ok_or("missing original symlink target")?,
                        &chosen,
                        &stage,
                        Path::new(&record.source),
                        target,
                    )?;
                }
            }
            validate_links(&stage, &stage, target)?;
        }
        Ok::<(), String>(())
    })();
    if let Err(error) = preparation {
        for (_, stage, _) in &stages {
            let _ = remove_any(stage);
        }
        return Err(error);
    }
    for (target, stamp) in &stamps {
        let current = if present(target) {
            Some(tree_digest(target)?)
        } else {
            None
        };
        if current != *stamp {
            for (_, stage, _) in &stages {
                let _ = remove_any(stage);
            }
            return Err(
                "live profile changed while staging restore; no profile was replaced".to_string(),
            );
        }
    }
    let mut committed = Vec::<(PathBuf, PathBuf, bool)>::new();
    for (target, stage, previous) in &stages {
        let existed = present(target);
        if existed && let Err(error) = fs::rename(target, previous) {
            return Err(restore_error(&error, &rollback_committed(&committed)));
        }
        if let Err(error) = fs::rename(stage, target) {
            let mut rollback_errors = Vec::new();
            if existed && let Err(rollback_error) = fs::rename(previous, target) {
                rollback_errors.push(format!("{}: {rollback_error}", target.display()));
            }
            rollback_errors.extend(rollback_committed(&committed));
            return Err(restore_error(&error, &rollback_errors));
        }
        committed.push((target.clone(), previous.clone(), existed));
    }
    for (_, previous, existed) in committed {
        if existed {
            remove_any(&previous)?;
        }
    }
    println!("restored {id}");
    Ok(())
}

//! Conservative local binary maintenance with explicit unsupported results.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{ExitCode, Stdio};

use serde::Serialize;

use super::active::refuse_active_client;
use super::{backup_root, clients, lock_operations, profiles};
use crate::cli::MaintenanceArgs;
use crate::clients::ClientKind;

#[derive(Serialize, schemars::JsonSchema)]
pub(crate) struct Plan {
    client: String,
    operation: String,
    status: String,
    method: String,
    channel: Option<String>,
    binary: Option<String>,
    version_before: Option<String>,
    command: Vec<String>,
    reason: Option<String>,
    preserved_profiles: Vec<String>,
    backup_id: Option<String>,
    version_after: Option<String>,
}

fn binary(name: &str) -> Option<PathBuf> {
    let path = crate::operation_context::var_os("PATH")?;
    for directory in std::env::split_paths(&path) {
        let candidate = directory.join(name);
        if candidate.is_file() {
            return Some(candidate);
        }
        #[cfg(windows)]
        {
            for extension in ["exe", "cmd", "bat"] {
                let candidate = directory.join(format!("{name}.{extension}"));
                if candidate.is_file() {
                    return Some(candidate);
                }
            }
        }
    }
    None
}

fn version(path: &Path) -> Option<String> {
    let output = crate::operation_context::process_output(
        crate::operation_context::command(path)
            .arg("--version")
            .stderr(Stdio::null()),
    )
    .ok()?;
    if !output.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&output.stdout).trim().to_owned();
    (!text.is_empty()).then_some(text)
}

fn npm_root() -> Option<PathBuf> {
    let output = crate::operation_context::process_output(
        crate::operation_context::command(binary("npm")?)
            .args(["root", "-g"])
            .stderr(Stdio::null()),
    )
    .ok()?;
    output
        .status
        .success()
        .then(|| PathBuf::from(String::from_utf8_lossy(&output.stdout).trim()))
}

const fn package(client: ClientKind) -> Option<&'static str> {
    match client {
        ClientKind::Codex => Some("@openai/codex"),
        ClientKind::ClaudeCode => Some("@anthropic-ai/claude-code"),
        ClientKind::GeminiCli => Some("@google/gemini-cli"),
        ClientKind::Opencode => Some("opencode-ai"),
        ClientKind::QwenCode => Some("@qwen-code/qwen-code"),
        ClientKind::Cursor | ClientKind::GrokCli | ClientKind::Agent => None,
    }
}

fn valid_channel(client: ClientKind, channel: &str) -> bool {
    match client {
        ClientKind::GeminiCli => matches!(channel, "latest" | "preview" | "nightly"),
        _ => channel == "latest",
    }
}

fn detected_channel(
    home: Option<&Path>,
    client: ClientKind,
    method: &str,
    path: Option<&Path>,
) -> Option<String> {
    if method == "brew" && client == ClientKind::ClaudeCode {
        let path = path?.to_string_lossy();
        return Some(
            if path.contains("claude-code@latest") {
                "latest"
            } else {
                "stable"
            }
            .into(),
        );
    }
    if method == "native" && client == ClientKind::ClaudeCode {
        let configured = profiles(home, client, crate::cli::ProfileSelection::Normal)
            .ok()
            .and_then(|profiles| profiles.into_iter().next())
            .and_then(|profile| {
                profile
                    .stores
                    .first()
                    .map(|store| store.path.join("settings.json"))
            })
            .and_then(|settings| fs::read(settings).ok())
            .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
            .and_then(|value| value["autoUpdatesChannel"].as_str().map(str::to_owned));
        return Some(configured.unwrap_or_else(|| "latest".into()));
    }
    if method == "native"
        && matches!(
            client,
            ClientKind::Cursor | ClientKind::Opencode | ClientKind::QwenCode
        )
    {
        return Some("latest".into());
    }
    None
}

fn method_for(client: ClientKind, path: &Path) -> String {
    let resolved = fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    let text = resolved.to_string_lossy().replace('\\', "/");
    let raw = path.to_string_lossy().replace('\\', "/");
    if let Some(root) = npm_root() {
        let root = fs::canonicalize(&root).unwrap_or(root);
        if resolved.starts_with(&root) {
            return "npm".into();
        }
        #[cfg(windows)]
        if path.parent() == root.parent() {
            return "npm".into();
        }
    }
    if text.contains("/Cellar/") || text.contains("/Caskroom/") {
        return "brew".into();
    }
    if client == ClientKind::ClaudeCode
        && (text.contains("/.local/share/claude/") || raw.ends_with("/.local/bin/claude"))
    {
        return "native".into();
    }
    if client == ClientKind::Cursor && raw.ends_with("/.local/bin/cursor-agent") {
        return "native".into();
    }
    if client == ClientKind::Opencode && text.contains("/.opencode/bin/") {
        return "native".into();
    }
    if client == ClientKind::QwenCode && raw.ends_with("/.local/bin/qwen") {
        return "native".into();
    }
    "unknown".into()
}

fn command_for(
    client: ClientKind,
    operation: &str,
    method: &str,
    channel: Option<&str>,
    path: Option<&Path>,
) -> Result<Vec<String>, String> {
    match method {
        "npm" => {
            let package =
                package(client).ok_or("no verified vendor npm package for this client")?;
            let channel =
                channel.ok_or("npm channel is unknown; select --latest or --channel explicitly")?;
            if !valid_channel(client, channel) {
                return Err("vendor does not document this npm channel".into());
            }
            let mut command = vec![
                "npm".into(),
                "install".into(),
                "-g".into(),
                format!("{package}@{channel}"),
            ];
            if operation == "reinstall" {
                command.push("--force".into());
            }
            Ok(command)
        }
        "native" if client == ClientKind::ClaudeCode => {
            let path = path.ok_or("Claude binary is missing")?;
            if channel.is_some_and(|channel| !matches!(channel, "stable" | "latest")) {
                return Err("Claude native channel must be stable or latest".into());
            }
            let mut command = vec![path.to_string_lossy().into_owned()];
            if operation == "update" {
                if channel.is_some() {
                    return Err("Claude native update follows its configured channel; use reinstall for a new channel".into());
                }
                command.push("update".into());
            } else {
                command.push("install".into());
                if let Some(channel) = channel {
                    command.push(channel.into());
                }
            }
            Ok(command)
        }
        "native" if client == ClientKind::Cursor && operation == "update" && channel.is_none() => {
            Ok(vec![
                path.ok_or("Cursor binary is missing")?
                    .to_string_lossy()
                    .into_owned(),
                "update".into(),
            ])
        }
        "native"
            if client == ClientKind::Opencode && operation == "update" && channel.is_none() =>
        {
            Ok(vec![
                path.ok_or("OpenCode binary is missing")?
                    .to_string_lossy()
                    .into_owned(),
                "upgrade".into(),
            ])
        }
        "native"
            if client == ClientKind::QwenCode && operation == "update" && channel.is_none() =>
        {
            Ok(vec![
                path.ok_or("Qwen binary is missing")?
                    .to_string_lossy()
                    .into_owned(),
                "update".into(),
            ])
        }
        "brew" if channel.is_none() || operation == "install" => {
            if operation == "install"
                && client != ClientKind::ClaudeCode
                && !matches!(channel, None | Some("latest"))
            {
                return Err("this Homebrew formula has no documented alternate channel".into());
            }
            let formula = match client {
                ClientKind::ClaudeCode => {
                    if operation == "install" {
                        if channel == Some("latest") {
                            "claude-code@latest"
                        } else if channel == Some("stable") {
                            "claude-code"
                        } else {
                            return Err("choose --channel stable or --latest for a fresh Claude Homebrew install".into());
                        }
                    } else if path
                        .is_some_and(|path| path.to_string_lossy().contains("claude-code@latest"))
                    {
                        "claude-code@latest"
                    } else {
                        "claude-code"
                    }
                }
                ClientKind::GeminiCli => "gemini-cli",
                ClientKind::Opencode => "opencode",
                ClientKind::QwenCode => "qwen-code",
                _ => return Err("Homebrew formula is not verified for this client".into()),
            };
            let mut command = vec!["brew".into()];
            command.push(
                if operation == "reinstall" {
                    "reinstall"
                } else if operation == "install" {
                    "install"
                } else {
                    "upgrade"
                }
                .into(),
            );
            command.push(formula.into());
            Ok(command)
        }
        "unknown" => Err(
            "install method could not be proved from the selected binary; no command will run"
                .into(),
        ),
        _ => Err("vendor does not document this operation for the detected method/channel".into()),
    }
}

fn plan(home: Option<&Path>, operation: &str, client: ClientKind, args: &MaintenanceArgs) -> Plan {
    let found = binary(client.command());
    let version_before = found.as_deref().and_then(version);
    let method = if operation == "install" && found.is_none() {
        args.method.clone().unwrap_or_else(|| "unknown".into())
    } else {
        found
            .as_deref()
            .map_or_else(|| "unknown".into(), |path| method_for(client, path))
    };
    let requested_channel = args
        .channel
        .clone()
        .or_else(|| args.latest.then(|| "latest".into()));
    let channel = requested_channel
        .clone()
        .or_else(|| detected_channel(home, client, &method, found.as_deref()));
    let preserved_profiles = match args.selection.profile {
        crate::cli::ProfileSelection::Both => vec!["normal".into(), "router (if present)".into()],
        crate::cli::ProfileSelection::Normal => vec!["normal".into()],
        crate::cli::ProfileSelection::Router => vec!["router (if present)".into()],
    };
    let mut result = Plan {
        client: client.canonical_name().into(),
        operation: operation.into(),
        status: "planned".into(),
        method: method.clone(),
        channel: channel.clone(),
        binary: found
            .as_ref()
            .map(|path| path.to_string_lossy().into_owned()),
        version_before,
        command: Vec::new(),
        reason: None,
        preserved_profiles,
        backup_id: None,
        version_after: None,
    };
    if args.method.is_some() && operation != "install" {
        result.status = "unsupported".into();
        result.reason = Some(
            "--method is only for a fresh install; existing methods are detected from the binary"
                .into(),
        );
        return result;
    }
    if operation == "install" && found.is_some() {
        result.status = "unsupported".into();
        result.reason = Some("already installed; use update or reinstall".into());
        return result;
    }
    if operation != "install" && found.is_none() {
        result.status = "unsupported".into();
        result.reason = Some("binary is not installed or not on PATH".into());
        return result;
    }
    if method == "unknown" && operation == "install" {
        result.reason = Some(
            "fresh install requires --method; supported method: npm for documented npm packages"
                .into(),
        );
        result.status = "unsupported".into();
        return result;
    }
    if let Err(error) = refuse_active_client(client, home) {
        result.status = "blocked".into();
        result.reason = Some(error);
        return result;
    }
    if operation == "reinstall" {
        let scopes = [
            crate::cli::ProfileSelection::Normal,
            crate::cli::ProfileSelection::Router,
        ];
        for scope in scopes {
            if let Ok(profiles) = profiles(home, client, scope) {
                for profile in profiles {
                    if profile.stores.iter().any(|store| store.path.exists()) {
                        result.preserved_profiles.push(profile.scope.into());
                    }
                }
            }
        }
    }
    let command_channel =
        if operation == "reinstall" && method == "native" && client == ClientKind::ClaudeCode {
            channel.as_deref()
        } else {
            requested_channel.as_deref()
        };
    match command_for(
        client,
        operation,
        &method,
        command_channel,
        found.as_deref(),
    ) {
        Ok(command) => {
            if command.first().is_some_and(|executable| {
                !Path::new(executable).is_absolute() && binary(executable).is_none()
            }) {
                result.status = "unsupported".into();
                result.reason = Some(format!("required installer {} is not on PATH", command[0]));
            } else {
                result.command = command;
            }
        }
        Err(error) => {
            result.status = "unsupported".into();
            result.reason = Some(error);
        }
    }
    if client == ClientKind::ClaudeCode
        && crate::operation_context::var_os("DISABLE_UPDATES").is_some()
    {
        result.status = "blocked".into();
        result.reason = Some("DISABLE_UPDATES is set; unset it for this operation".into());
    }
    result
}

pub fn run(home: Option<&Path>, operation: &str, args: &MaintenanceArgs) -> ExitCode {
    let root = match backup_root(home, None) {
        Ok(root) => root,
        Err(error) => return super::failed(error),
    };
    let _lock = if args.dry_run {
        None
    } else {
        match lock_operations(&root) {
            Ok(lock) => Some(lock),
            Err(error) => return super::failed(error),
        }
    };
    let mut plans = clients(&args.selection)
        .into_iter()
        .map(|client| plan(home, operation, client, args))
        .collect::<Vec<_>>();
    if !args.dry_run {
        for plan in &mut plans {
            if plan.status != "planned" {
                continue;
            }
            let client = ClientKind::from_str_opt(&plan.client).expect("known client");
            if operation == "reinstall" && !args.yes {
                plan.status = "blocked".into();
                plan.reason = Some("reinstall requires --yes after reviewing --dry-run".into());
                continue;
            }
            if operation == "reinstall" {
                let mut selected = Vec::new();
                for scope in [
                    crate::cli::ProfileSelection::Normal,
                    crate::cli::ProfileSelection::Router,
                ] {
                    if let Ok(profiles) = profiles(home, client, scope) {
                        selected.extend(profiles.into_iter().filter(|profile| {
                            profile.stores.iter().any(|store| store.path.exists())
                        }));
                    }
                }
                if selected.is_empty() {
                    plan.status = "blocked".into();
                    plan.reason =
                        Some("no profile is available for verified recovery backup".into());
                    continue;
                }
                match super::backup::create_unlocked(&root, home, &selected, true) {
                    Ok(id) => plan.backup_id = Some(id),
                    Err(error) => {
                        plan.status = "blocked".into();
                        plan.reason = Some(format!("pre-reinstall backup failed: {error}"));
                        continue;
                    }
                }
            }
            let executable = &plan.command[0];
            let executable = binary(executable).unwrap_or_else(|| PathBuf::from(executable));
            let status = crate::operation_context::process_output(
                crate::operation_context::command(&executable).args(&plan.command[1..]),
            )
            .map(|output| output.status);
            if !status.is_ok_and(|status| status.success()) {
                let after = binary(client.command());
                let after_version = after.as_deref().and_then(version);
                let changed = after
                    .as_ref()
                    .map(|path| path.to_string_lossy().into_owned())
                    != plan.binary
                    || after_version != plan.version_before;
                plan.status = if changed { "partial" } else { "failed" }.into();
                plan.version_after = after_version;
                plan.reason = Some(if changed {
                    "vendor command failed after changing the binary; inspect the installation before retrying"
                } else {
                    "vendor installer/updater failed; the previous binary appears unchanged"
                }.into());
                continue;
            }
            let after = binary(client.command());
            let after_version = after.as_deref().and_then(version);
            if after.is_none() || after_version.is_none() {
                plan.status = "failed".into();
                plan.reason = Some(
                    "installer exited successfully, but binary path/version verification failed"
                        .into(),
                );
                continue;
            }
            plan.binary = after.map(|path| path.to_string_lossy().into_owned());
            plan.version_after = after_version;
            plan.status = if operation == "update" && plan.version_after == plan.version_before {
                "current"
            } else {
                "completed"
            }
            .into();
        }
    }
    if args.json {
        println!(
            "{}",
            serde_json::to_string_pretty(&plans).unwrap_or_default()
        );
    } else {
        for plan in &plans {
            println!(
                "{} {}: {} ({})",
                plan.client, plan.operation, plan.status, plan.method
            );
            if args.dry_run && !plan.command.is_empty() {
                println!("  command: {}", plan.command.join(" "));
            }
            if let Some(reason) = &plan.reason {
                eprintln!("  {reason}");
            }
            if let Some(id) = &plan.backup_id {
                println!("  verified backup: {id}");
            }
        }
    }
    if plans
        .iter()
        .all(|plan| matches!(plan.status.as_str(), "planned" | "completed" | "current"))
    {
        ExitCode::SUCCESS
    } else {
        ExitCode::from(1)
    }
}

//! Settings-only and explicit full profile reset.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use super::{Profile, backup_root, clients, failed, lock_operations, profiles, refuse_active};
use crate::cli::{ClientSelection, ProfileSelection};
use crate::clients::ClientKind;

fn settings_paths(profile: &Profile) -> Vec<PathBuf> {
    let mut paths = Vec::new();
    for store in &profile.stores {
        let root = &store.path;
        let names: &[&str] = match profile.client {
            ClientKind::Codex => &["config.toml"],
            ClientKind::ClaudeCode => &["settings.json", "settings.local.json"],
            ClientKind::Cursor => &["cli-config.json"],
            // Router runs Gemini with `GEMINI_CLI_HOME` naming the store, and
            // Gemini reads `<GEMINI_CLI_HOME>/.gemini/settings.json` (#611).
            ClientKind::GeminiCli if profile.scope == "router" => &[".gemini/settings.json"],
            ClientKind::GeminiCli | ClientKind::QwenCode => &["settings.json"],
            ClientKind::GrokCli => &["user-settings.json"],
            ClientKind::Opencode => {
                if store.name == "config" {
                    &["opencode.json", "config.json"]
                } else {
                    &[]
                }
            }
            ClientKind::Agent => {
                if store.name == "config" {
                    &["opencode.json"]
                } else {
                    &[]
                }
            }
        };
        for name in names {
            paths.push(root.join(name));
        }
    }
    paths
}

fn validate_setting(path: &Path) -> Result<(), String> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(|error| error.to_string())?
        .file_type()
        .is_symlink()
    {
        return Err("settings symlink must be removed manually before reset".to_string());
    }
    let text =
        fs::read_to_string(path).map_err(|error| format!("cannot read settings: {error}"))?;
    if path
        .extension()
        .is_some_and(|extension| extension == "toml")
    {
        text.parse::<toml_edit::DocumentMut>()
            .map_err(|error| format!("malformed settings: {error}"))?;
    } else {
        serde_json::from_str::<serde_json::Value>(&text)
            .map_err(|error| format!("malformed settings: {error}"))?;
    }
    Ok(())
}

fn ambient(client: ClientKind) -> Vec<&'static str> {
    let names: &[&str] = match client {
        ClientKind::ClaudeCode => &[
            "ANTHROPIC_BASE_URL",
            "ANTHROPIC_API_KEY",
            "ANTHROPIC_MODEL",
            "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC",
            "DISABLE_AUTOUPDATER",
        ],
        ClientKind::Codex => &["CODEX_HOME", "OPENAI_API_KEY", "OPENAI_BASE_URL"],
        ClientKind::GeminiCli => &[
            "GEMINI_API_KEY",
            "GOOGLE_GEMINI_BASE_URL",
            "GEMINI_CLI_HOME",
        ],
        ClientKind::QwenCode => &["QWEN_HOME", "OPENAI_BASE_URL", "OPENAI_API_KEY"],
        ClientKind::GrokCli => &["GROK_API_KEY", "GROK_BASE_URL"],
        ClientKind::Opencode => &["OPENCODE_CONFIG", "OPENCODE_CONFIG_DIR", "XDG_CONFIG_HOME"],
        ClientKind::Cursor => &["CURSOR_CONFIG_DIR", "CURSOR_API_ENDPOINT"],
        ClientKind::Agent => &["XDG_CONFIG_HOME", "OPENAI_API_KEY"],
    };
    names
        .iter()
        .copied()
        .filter(|name| crate::operation_context::var_os(name).is_some())
        .collect()
}

fn run_one(
    root: &Path,
    home: Option<&Path>,
    profile: &Profile,
    dry_run: bool,
    full: bool,
    yes: bool,
) -> Result<serde_json::Value, String> {
    refuse_active(profile, home)?;
    let selected = profile
        .stores
        .iter()
        .filter(|store| store.path.exists())
        .collect::<Vec<_>>();
    if selected.is_empty() {
        return Err(format!(
            "{} {} profile is unavailable",
            profile.client, profile.scope
        ));
    }
    let settings = settings_paths(profile);
    for path in &settings {
        validate_setting(path)?;
    }
    let overrides = ambient(profile.client);
    let targets = if full {
        selected
            .iter()
            .map(|store| store.path.to_string_lossy().into_owned())
            .collect::<Vec<_>>()
    } else {
        settings
            .iter()
            .filter(|path| path.exists())
            .map(|path| path.to_string_lossy().into_owned())
            .collect::<Vec<_>>()
    };
    let categories = if full {
        vec![
            "settings",
            "sessions",
            "projects",
            "history",
            "checkpoints",
            "memory",
            "local credentials",
        ]
    } else {
        vec!["settings", "Router integration"]
    };
    // Nothing to reset is reported as such, not as a reset, and the checked
    // locations are named (issue #611). The verified backup is still taken.
    let unchanged = targets.is_empty();
    let report = |status: &str, backup: Option<&str>| {
        let mut row = serde_json::json!({ "client": profile.client.canonical_name(),
            "profile": profile.scope, "mode": if full { "full" } else { "settings" },
            "targets": targets, "categories": categories, "ambient_overrides": overrides,
            "status": if unchanged { "unchanged" } else { status } });
        if let Some(backup) = backup {
            row["backup_id"] = backup.into();
        }
        if unchanged {
            row["checked"] = settings.iter().map(|path| path.to_string_lossy()).collect();
        }
        row
    };
    if dry_run {
        return Ok(report("planned", None));
    }
    if full && !yes {
        return Err("full reset requires --yes after reviewing --dry-run".to_string());
    }
    if full {
        eprintln!(
            "full local reset of {} {} removes settings, sessions, projects, history, checkpoints, memory and local credentials; remote tokens are not revoked",
            profile.client, profile.scope
        );
        for target in &targets {
            eprintln!("  selected profile store: {target}");
        }
    }
    let guarded = if full {
        selected
            .iter()
            .map(|store| store.path.clone())
            .collect::<Vec<_>>()
    } else {
        settings
            .iter()
            .filter(|path| path.exists())
            .cloned()
            .collect::<Vec<_>>()
    };
    let stamps = guarded
        .iter()
        .map(|path| Ok((path.clone(), super::backup::tree_digest(path)?)))
        .collect::<Result<Vec<_>, String>>()?;
    let backup = super::backup::create_unlocked(root, home, std::slice::from_ref(profile), full)?;
    for (path, stamp) in &stamps {
        if super::backup::tree_digest(path)? != *stamp {
            return Err(format!(
                "profile changed after the reset preview; nothing was reset; recovery backup {backup}"
            ));
        }
    }
    let tx = uuid::Uuid::new_v4().simple().to_string();
    let mut moved = Vec::<(PathBuf, PathBuf)>::new();
    let result = (|| {
        if full {
            for store in &selected {
                let old = store
                    .path
                    .with_file_name(format!(".router-reset-{tx}-{}", store.name));
                fs::rename(&store.path, &old)
                    .map_err(|error| format!("cannot stage full reset: {error}"))?;
                moved.push((store.path.clone(), old));
                if moved.last().is_some_and(|(_, old)| old.is_dir()) {
                    if let Err(error) = fs::create_dir(&store.path) {
                        return Err(format!("cannot create fresh profile: {error}"));
                    }
                    super::owner_directory(&store.path)?;
                }
            }
        } else {
            for path in settings.iter().filter(|path| path.exists()) {
                let old = path.with_file_name(format!(
                    ".router-reset-{tx}-{}",
                    path.file_name()
                        .ok_or("settings has no filename")?
                        .to_string_lossy()
                ));
                fs::rename(path, &old)
                    .map_err(|error| format!("cannot stage settings reset: {error}"))?;
                moved.push((path.clone(), old));
            }
        }
        Ok::<(), String>(())
    })();
    if let Err(error) = result {
        let mut rollback_errors = Vec::new();
        for (path, old) in moved.iter().rev() {
            if full
                && path.exists()
                && let Err(rollback_error) = fs::remove_dir_all(path)
            {
                rollback_errors.push(format!("{}: {rollback_error}", path.display()));
                continue;
            }
            if let Err(rollback_error) = fs::rename(old, path) {
                rollback_errors.push(format!("{}: {rollback_error}", path.display()));
            }
        }
        if !rollback_errors.is_empty() {
            return Err(format!(
                "reset failed: {error}; rollback incomplete ({}); recovery backup {backup}",
                rollback_errors.join("; ")
            ));
        }
        return Err(format!(
            "reset rolled back: {error}; recovery backup {backup}"
        ));
    }
    for (_, old) in moved {
        if old.is_dir() {
            fs::remove_dir_all(old).map_err(|error| error.to_string())?;
        } else {
            fs::remove_file(old).map_err(|error| error.to_string())?;
        }
    }
    Ok(report("reset", Some(&backup)))
}

#[must_use]
#[allow(clippy::fn_params_excessive_bools)]
pub fn run(
    home: Option<&Path>,
    selection: &ClientSelection,
    dry_run: bool,
    full: bool,
    yes: bool,
    json: bool,
) -> ExitCode {
    let root = match backup_root(home, None) {
        Ok(root) => root,
        Err(error) => return failed(error),
    };
    let _lock = if dry_run {
        None
    } else {
        match lock_operations(&root) {
            Ok(lock) => Some(lock),
            Err(error) => return failed(error),
        }
    };
    let mut rows = Vec::new();
    let mut failures = 0;
    for client in clients(selection) {
        let scopes: &[ProfileSelection] = match selection.profile {
            ProfileSelection::Both => &[ProfileSelection::Normal, ProfileSelection::Router],
            ProfileSelection::Normal => &[ProfileSelection::Normal],
            ProfileSelection::Router => &[ProfileSelection::Router],
        };
        for scope in scopes {
            let result = profiles(home, client, *scope).and_then(|profiles| {
                let profile = profiles
                    .into_iter()
                    .next()
                    .ok_or("profile is unavailable")?;
                run_one(&root, home, &profile, dry_run, full, yes)
            });
            match result {
                Ok(row) => rows.push(row),
                Err(error) => {
                    failures += 1;
                    rows.push(serde_json::json!({
                    "client": client.canonical_name(), "profile": format!("{scope:?}").to_ascii_lowercase(),
                    "status": "error", "reason": error }));
                }
            }
        }
    }
    if json {
        println!(
            "{}",
            serde_json::to_string_pretty(&rows).unwrap_or_default()
        );
    } else {
        for row in &rows {
            let client = row["client"].as_str().unwrap_or("?");
            let profile = row["profile"].as_str().unwrap_or("?");
            let status = row["status"].as_str().unwrap_or("?");
            println!("{client} {profile}: {status}");
            if let Some(targets) = row["targets"].as_array() {
                for target in targets {
                    println!("  target: {}", target.as_str().unwrap_or("?"));
                }
            }
            if let Some(checked) = row["checked"].as_array() {
                for path in checked {
                    println!("  no settings at: {}", path.as_str().unwrap_or("?"));
                }
            }
            if let Some(id) = row["backup_id"].as_str() {
                println!("  verified backup: {id}");
            }
            if let Some(reason) = row["reason"].as_str() {
                eprintln!("error: {client} {profile}: {reason}");
            }
            if let Some(overrides) = row["ambient_overrides"].as_array() {
                for name in overrides {
                    eprintln!(
                        "note: {} remains set in the parent environment; unset it before expecting defaults",
                        name.as_str().unwrap_or("override")
                    );
                }
            }
        }
    }
    if failures == 0 {
        ExitCode::SUCCESS
    } else {
        ExitCode::from(1)
    }
}

/// Compatibility for `router with --reset-to-default-configuration claude`.
/// That flag now resets settings in the active Router-owned profile and leaves
/// resumable sessions in place.
pub fn reset_router_claude_for_with() -> Result<Option<String>, String> {
    let root = backup_root(None, None)?;
    let _lock = lock_operations(&root)?;
    let profile = profiles(None, ClientKind::ClaudeCode, ProfileSelection::Router)?
        .into_iter()
        .next()
        .ok_or("Router-owned Claude profile unavailable")?;
    if profile.stores.iter().all(|store| !store.path.exists()) {
        return Ok(None);
    }
    let row = run_one(&root, None, &profile, false, false, true)?;
    Ok(row["backup_id"].as_str().map(str::to_owned))
}

//! Client-bound authorization for consumer subscription credentials.
//!
//! A compatible wire protocol is not permission to spend a consumer
//! subscription. This module keeps the reviewed client/provider matrix, exact
//! risk-accepted overrides, and real-client request evidence in one place so
//! discovery and dispatch cannot drift apart (issue #389).

use std::collections::HashSet;

use axum::http::HeaderMap;
use axum::http::StatusCode;
use axum::response::Response;

use crate::clients::ClientKind;
use crate::subscription::SubscriptionProvider;

/// Dedicated trusted-proxy evidence header. Unlike the ordinary client marker,
/// its presence forces the opt-in proxy contract and never native passthrough.
pub const PROXIED_CLIENT_EVIDENCE_HEADER: &str = "x-link-assistant-proxied-client";
/// The only reviewed trusted-proxy identity value.
pub const PROXIED_CODEX_EVIDENCE_VALUE: &str = "codex";

/// Client-facing protocol used by one request.
#[derive(
    Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd, serde::Deserialize, serde::Serialize,
)]
#[serde(rename_all = "snake_case")]
pub enum ClientProtocol {
    /// Authenticated model discovery before a client launches.
    Catalog,
    /// `Anthropic Messages` or token-counting surface.
    AnthropicMessages,
    /// `OpenAI Chat Completions` surface.
    OpenAIChat,
    /// `OpenAI Responses` surface.
    OpenAIResponses,
    /// Gemini's native `generateContent` surface.
    GeminiNative,
}

/// Why an entitlement matrix cell is usable.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EntitlementDecision {
    /// The provider's documented native client.
    Native,
    /// A native client identity accepted through an explicitly trusted proxy.
    Proxied,
    /// One exact client/provider bridge was risk-accepted.
    Override,
    /// No reviewed entitlement exists.
    Denied,
}

/// Exact immutable managed-client identity carried by a Router token.
pub fn bound_client(claims: &crate::token::TokenClaims) -> Result<(ClientKind, &str), String> {
    if claims.is_admin() {
        return Err("administrative credentials do not imply consumer-subscription access".into());
    }
    let client_name = claims
        .client_kind
        .as_deref()
        .ok_or("the token has no managed-client binding")?;
    let client = ClientKind::from_str_opt(client_name)
        .ok_or("the token contains an unknown managed-client binding")?;
    if client_name != client.canonical_name() {
        return Err("the token's managed-client binding is not canonical".into());
    }
    let principal = claims
        .principal_id
        .as_deref()
        .filter(|principal| !principal.trim().is_empty())
        .ok_or("the token has no subscriber principal")?;
    Ok((client, principal))
}

/// Validate the signed binding, reviewed matrix cell, and request fixture
/// evidence as one indivisible authorization decision.
pub fn authorize_subscription(
    policy: &SubscriptionEntitlementPolicy,
    claims: &crate::token::TokenClaims,
    provider: SubscriptionProvider,
    protocol: ClientProtocol,
    path: &str,
    headers: &HeaderMap,
) -> Result<EntitlementDecision, String> {
    let (client, _) = bound_client(claims)?;
    let evidence = policy.request_evidence(client, protocol, path, headers);
    if evidence == RequestEvidence::Denied {
        return Err(format!(
            "request evidence does not match the token's {} client binding",
            client.canonical_name()
        ));
    }
    if evidence == RequestEvidence::Proxied && provider != SubscriptionProvider::Codex {
        return Err(format!(
            "proxied {} request evidence is limited to the Codex consumer subscription",
            client.canonical_name()
        ));
    }
    let entitlement = policy.decide(Some(client), provider, protocol);
    match entitlement {
        EntitlementDecision::Denied => Err(format!(
            "{} is not entitled to use the {provider} consumer subscription",
            client.display_name()
        )),
        EntitlementDecision::Native if evidence == RequestEvidence::Proxied => {
            Ok(EntitlementDecision::Proxied)
        }
        decision => Ok(decision),
    }
}

/// Apply the active deployment policy and render a stable pre-upstream denial.
pub fn enforce_subscription(
    state: &crate::app_state::AppState,
    headers: &HeaderMap,
    provider: SubscriptionProvider,
    protocol: ClientProtocol,
    path: &str,
) -> Result<EntitlementDecision, Response> {
    let claims = crate::proxy::authenticate_client(state, headers).map_err(|response| *response)?;
    enforce_subscription_for_claims(state, &claims, headers, provider, protocol, path)
}

/// Variant for catalog handlers that have already authenticated the caller.
pub fn enforce_subscription_for_claims(
    state: &crate::app_state::AppState,
    claims: &crate::token::TokenClaims,
    headers: &HeaderMap,
    provider: SubscriptionProvider,
    protocol: ClientProtocol,
    path: &str,
) -> Result<EntitlementDecision, Response> {
    let policy = state
        .provider_store
        .subscription_entitlement_policy()
        .map_err(|error| {
            crate::proxy::error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &format!("could not read subscription entitlement policy: {error}"),
            )
        })?;
    authorize_subscription(&policy, claims, provider, protocol, path, headers).map_err(|message| {
        crate::proxy::error_response(StatusCode::FORBIDDEN, "permission_error", &message)
    })
}

/// Subscription providers that may participate in model selection for this
/// already-authenticated request.
///
/// The final dispatch check remains mandatory. This earlier projection only
/// keeps a provider hidden from the client's catalog from influencing
/// ambiguity or automatic owner selection.
pub fn entitled_subscription_providers_for_claims(
    state: &crate::app_state::AppState,
    claims: &crate::token::TokenClaims,
    headers: &HeaderMap,
    protocol: ClientProtocol,
    path: &str,
) -> Result<Vec<SubscriptionProvider>, Response> {
    let policy = state
        .provider_store
        .subscription_entitlement_policy()
        .map_err(|error| {
            crate::proxy::error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &format!("could not read subscription entitlement policy: {error}"),
            )
        })?;
    Ok(SubscriptionProvider::ALL
        .into_iter()
        .filter(|provider| {
            authorize_subscription(&policy, claims, *provider, protocol, path, headers).is_ok()
        })
        .collect())
}

/// One exact risk-accepted bridge cell.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct SubscriptionOverride {
    pub client: ClientKind,
    pub provider: SubscriptionProvider,
}

impl std::fmt::Display for SubscriptionOverride {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "{}:{}", self.client, self.provider)
    }
}

/// Reviewed consumer-subscription entitlement policy.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct SubscriptionEntitlementPolicy {
    overrides: HashSet<SubscriptionOverride>,
    proxied_clients: HashSet<ClientKind>,
}

impl SubscriptionEntitlementPolicy {
    /// Parse exact `client:provider` overrides.
    ///
    /// Wildcards, unidentified/generic clients, and providers whose native
    /// consumer terms have not yet been recorded are rejected rather than
    /// retained as dormant future authority.
    pub fn parse<I, S>(values: I) -> Result<Self, String>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let mut overrides = HashSet::new();
        for value in values {
            let value = value.as_ref();
            let (client, provider) = value.split_once(':').ok_or_else(|| {
                format!("subscription bridge override must be CLIENT:PROVIDER; got '{value}'")
            })?;
            if client.contains('*') || provider.contains('*') {
                return Err("subscription bridge overrides cannot contain wildcards".to_string());
            }
            let client = ClientKind::from_str_opt(client)
                .ok_or_else(|| format!("unknown Router client in override '{value}'"))?;
            let provider = SubscriptionProvider::from_str_opt(provider)
                .ok_or_else(|| format!("unknown subscription provider in override '{value}'"))?;
            if matches!(client, ClientKind::Agent | ClientKind::Cursor) {
                return Err(format!(
                    "{client} has no fixture-tested subscription adapter and cannot be overridden"
                ));
            }
            if matches!(
                provider,
                SubscriptionProvider::Gemini | SubscriptionProvider::Qwen
            ) {
                return Err(format!(
                    "{provider} consumer-subscription terms are pending review; no override may enable it"
                ));
            }
            overrides.insert(SubscriptionOverride { client, provider });
        }
        Ok(Self {
            overrides,
            proxied_clients: HashSet::new(),
        })
    }

    /// Add explicitly trusted proxy identities to this policy.
    ///
    /// Only Codex is supported because its proxy contract is deliberately
    /// narrow: the signed token remains Codex-bound and the override applies
    /// only to the canonical Responses route. Canonical catalog discovery
    /// already has native signed-client evidence and needs no override.
    pub fn with_proxied_clients<I, S>(mut self, values: I) -> Result<Self, String>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        for value in values {
            let value = value.as_ref().trim();
            if value.contains('*') {
                return Err("proxied client overrides cannot contain wildcards".to_string());
            }
            let client = ClientKind::from_str_opt(value)
                .ok_or_else(|| format!("unknown Router client in proxied override '{value}'"))?;
            if client != ClientKind::Codex {
                return Err(format!(
                    "{client} has no reviewed proxied-client request contract"
                ));
            }
            self.proxied_clients.insert(client);
        }
        Ok(self)
    }

    /// Decide one client/provider/protocol cell without consulting model names.
    #[must_use]
    pub fn decide(
        &self,
        client: Option<ClientKind>,
        provider: SubscriptionProvider,
        protocol: ClientProtocol,
    ) -> EntitlementDecision {
        let Some(client) = client else {
            return EntitlementDecision::Denied;
        };
        if !protocol_matches_client(client, protocol) {
            return EntitlementDecision::Denied;
        }
        if matches!(
            (client, provider),
            (ClientKind::ClaudeCode, SubscriptionProvider::Claude)
                | (ClientKind::Codex, SubscriptionProvider::Codex)
        ) || (protocol == ClientProtocol::Catalog
            && matches!(
                (client, provider),
                (ClientKind::GeminiCli, SubscriptionProvider::Gemini)
                    | (ClientKind::QwenCode, SubscriptionProvider::Qwen)
            ))
        {
            return EntitlementDecision::Native;
        }
        if self
            .overrides
            .contains(&SubscriptionOverride { client, provider })
        {
            EntitlementDecision::Override
        } else {
            EntitlementDecision::Denied
        }
    }

    /// Sorted exact overrides for warnings and administrative diagnostics.
    #[must_use]
    pub fn overrides(&self) -> Vec<SubscriptionOverride> {
        let mut values = self.overrides.iter().copied().collect::<Vec<_>>();
        values.sort_by_key(ToString::to_string);
        values
    }

    /// Sorted proxy identities enabled by the operator.
    #[must_use]
    pub fn proxied_clients(&self) -> Vec<ClientKind> {
        let mut values = self.proxied_clients.iter().copied().collect::<Vec<_>>();
        values.sort_by_key(|client| client.canonical_name());
        values
    }

    /// Match the exact operator-enabled proxy contract when its dedicated
    /// marker is present; otherwise preserve the native request evidence.
    /// Caller-controlled headers are never authority by themselves;
    /// [`authorize_subscription`] separately validates the signed binding.
    #[must_use]
    pub fn request_evidence(
        &self,
        client: ClientKind,
        protocol: ClientProtocol,
        path: &str,
        headers: &HeaderMap,
    ) -> RequestEvidence {
        if header_present(headers, PROXIED_CLIENT_EVIDENCE_HEADER) {
            return if self.proxied_clients.contains(&client)
                && proxied_request_evidence(client, protocol, path, headers)
            {
                RequestEvidence::Proxied
            } else {
                RequestEvidence::Denied
            };
        }
        if request_evidence(client, protocol, path, headers) {
            RequestEvidence::Native
        } else {
            RequestEvidence::Denied
        }
    }
}

/// How a request matched the client fingerprint policy.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RequestEvidence {
    /// It matches the real client's recorded request fixture.
    Native,
    /// It matches an operator-enabled trusted proxy contract.
    Proxied,
    /// It matches neither contract.
    Denied,
}

/// Whether a protocol is native to the claimed Router adapter.
#[must_use]
pub const fn protocol_matches_client(client: ClientKind, protocol: ClientProtocol) -> bool {
    match protocol {
        ClientProtocol::Catalog => !matches!(client, ClientKind::Cursor | ClientKind::Agent),
        ClientProtocol::AnthropicMessages => matches!(client, ClientKind::ClaudeCode),
        ClientProtocol::OpenAIResponses => matches!(client, ClientKind::Codex),
        ClientProtocol::OpenAIChat => matches!(
            client,
            ClientKind::Opencode | ClientKind::GrokCli | ClientKind::QwenCode
        ),
        ClientProtocol::GeminiNative => matches!(client, ClientKind::GeminiCli),
    }
}

fn header_present(headers: &HeaderMap, name: &str) -> bool {
    headers
        .get(name)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| !value.is_empty())
}

fn header_starts_with(headers: &HeaderMap, name: &str, prefix: &str) -> bool {
    headers
        .get(name)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.to_ascii_lowercase().starts_with(prefix))
}

fn header_equals(headers: &HeaderMap, name: &str, expected: &str) -> bool {
    headers
        .get(name)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value == expected)
}

/// Router-generated doctor requests use one exact internal marker instead of
/// forging any supported client's public fingerprint. The signed token still
/// supplies the client identity; this only proves that Router itself created
/// the deliberately narrow reachability probe. The marker is removed by
/// `native_request_headers` before provider dispatch.
fn doctor_request_evidence(
    client: ClientKind,
    protocol: ClientProtocol,
    path: &str,
    headers: &HeaderMap,
) -> bool {
    if !header_equals(
        headers,
        crate::clients::doctor::DOCTOR_EVIDENCE_HEADER,
        crate::clients::doctor::DOCTOR_EVIDENCE_VALUE,
    ) || !credential_carrier_matches(client, headers)
    {
        return false;
    }
    match client {
        ClientKind::ClaudeCode => {
            protocol == ClientProtocol::AnthropicMessages && path.ends_with("/v1/messages")
        }
        ClientKind::Codex => {
            protocol == ClientProtocol::OpenAIResponses && path.ends_with("/v1/responses")
        }
        ClientKind::QwenCode | ClientKind::Opencode | ClientKind::GrokCli | ClientKind::Agent => {
            protocol == ClientProtocol::OpenAIChat && path.ends_with("/v1/chat/completions")
        }
        ClientKind::Cursor | ClientKind::GeminiCli => false,
    }
}

/// Match the stable request evidence recorded in `tests/fixtures/clients`.
///
/// This is defense against accidental/unsupported routing, not cryptographic
/// process attestation. The signed client claim remains the authority; these
/// caller-controlled headers cannot grant anything without it.
#[must_use]
pub fn request_evidence(
    client: ClientKind,
    protocol: ClientProtocol,
    path: &str,
    headers: &HeaderMap,
) -> bool {
    if header_present(headers, crate::clients::doctor::DOCTOR_EVIDENCE_HEADER) {
        return doctor_request_evidence(client, protocol, path, headers);
    }
    if !protocol_matches_client(client, protocol) {
        return false;
    }
    if protocol == ClientProtocol::Catalog {
        let claimed = headers
            .get("x-link-assistant-client")
            .and_then(|value| value.to_str().ok())
            .and_then(ClientKind::from_str_opt);
        return claimed.is_none_or(|claimed| claimed == client)
            && path_belongs_to_client(client, path)
            && credential_carrier_matches(client, headers);
    }
    match client {
        ClientKind::ClaudeCode => {
            (path.ends_with("/v1/messages") || path.ends_with("/v1/messages/count_tokens"))
                && credential_carrier_matches(client, headers)
                && header_present(headers, "anthropic-version")
                && header_starts_with(headers, "user-agent", "claude")
        }
        ClientKind::Codex => {
            (path.contains("/v1/responses") || path.contains("/v1/conversations"))
                && header_present(headers, "authorization")
                && header_starts_with(headers, "user-agent", "codex")
                && (header_present(headers, "x-openai-internal-codex-responses-lite")
                    || header_present(headers, "x-codex-turn-metadata"))
        }
        ClientKind::GeminiCli => {
            path.contains("/api/services/gemini/")
                && header_present(headers, "x-goog-api-key")
                && (header_present(headers, "x-goog-api-client")
                    || header_present(headers, "x-gemini-api-privileged-user-id"))
        }
        ClientKind::QwenCode => {
            path.ends_with("/v1/chat/completions")
                && header_present(headers, "authorization")
                && header_present(headers, "x-stainless-package-version")
        }
        ClientKind::Opencode => {
            header_present(headers, "authorization")
                && header_starts_with(headers, "user-agent", "opencode/")
                && header_present(headers, "x-session-id")
        }
        ClientKind::GrokCli => {
            header_present(headers, "authorization")
                && header_starts_with(headers, "user-agent", "grok")
        }
        ClientKind::Cursor | ClientKind::Agent => false,
    }
}

fn proxied_request_evidence(
    client: ClientKind,
    protocol: ClientProtocol,
    path: &str,
    headers: &HeaderMap,
) -> bool {
    client == ClientKind::Codex
        && header_present(headers, "authorization")
        && header_equals(
            headers,
            PROXIED_CLIENT_EVIDENCE_HEADER,
            PROXIED_CODEX_EVIDENCE_VALUE,
        )
        && protocol == ClientProtocol::OpenAIResponses
        && path == "/api/services/codex/v1/responses"
}

fn credential_carrier_matches(client: ClientKind, headers: &HeaderMap) -> bool {
    match client {
        // Current Claude Code releases carry their gateway credential as a
        // Bearer token. Keep the older x-api-key spelling compatible, and use
        // this one rule for both discovery and inference (issue #414).
        ClientKind::ClaudeCode => {
            header_present(headers, "authorization") || header_present(headers, "x-api-key")
        }
        ClientKind::GeminiCli => header_present(headers, "x-goog-api-key"),
        _ => header_present(headers, "authorization"),
    }
}

fn path_belongs_to_client(client: ClientKind, path: &str) -> bool {
    if path == "/api/models" || path == "/api/usage" || path.starts_with("/api/usage/") {
        return !matches!(client, ClientKind::Cursor | ClientKind::Agent);
    }
    match client {
        ClientKind::Codex => path.starts_with("/api/services/codex/v1/models"),
        ClientKind::GeminiCli => {
            path == "/api/services/gemini/v1beta/models"
                || path.starts_with("/api/services/gemini/v1beta/models/")
        }
        ClientKind::QwenCode => path.starts_with("/api/services/qwen/v1/models"),
        ClientKind::ClaudeCode => path.starts_with("/api/services/anthropic/v1/models"),
        ClientKind::Opencode | ClientKind::GrokCli => {
            path.starts_with("/api/services/openai/v1/models")
        }
        ClientKind::Cursor | ClientKind::Agent => false,
    }
}

//! Repair implementation for the `clients` command.

use std::fmt::Write as _;
use std::process::ExitCode;

use crate::client_command::{ensure_codex_bridge, failed};
use crate::clients::{
    ClientKind, ClientManager, ManagedCredential, OwnershipState, RepairResult, TokenSource,
};

pub async fn repair(
    manager: &ClientManager,
    client: crate::translation_core::Maybe<ClientKind>,
    all: bool,
    dry_run: bool,
    json: bool,
    rollback: crate::translation_core::Maybe<&crate::translation_core::Str>,
) -> ExitCode {
    let clients = if all {
        ClientKind::ALL.to_vec()
    } else if let Some(client) = client {
        vec![client]
    } else {
        return failed("choose one client or pass --all");
    };
    if rollback.is_none() && clients.contains(&ClientKind::ClaudeCode) {
        crate::client_launch::report_claude_native_services_limitation(ClientKind::ClaudeCode);
    }

    if let Some(id) = rollback {
        let result = manager.rollback_repair(clients[0], id);
        return print_repair_result(result, json, "rolled back");
    }

    if dry_run {
        let mut plans = Vec::new();
        let mut errors = Vec::new();
        for client in clients {
            match manager.repair_plan(client) {
                Ok(plan) => plans.push(plan),
                Err(error) => errors.push(serde_json::json!({
                    "client": client.canonical_name(),
                    "error": error.to_string(),
                })),
            }
        }
        if json {
            println!(
                "{}",
                serde_json::to_string_pretty(&serde_json::json!({
                    "dry_run": true,
                    "plans": plans,
                    "errors": errors,
                }))
                .unwrap_or_default()
            );
        } else {
            for plan in &plans {
                println!(
                    "{}: {}; action={}{}",
                    plan.client,
                    plan.state,
                    plan.action,
                    if plan.conflicts.is_empty() {
                        String::new()
                    } else {
                        crate::translation_core::format!("; conflicts={}", plan.conflicts.join(","))
                    }
                );
            }
            for error in &errors {
                eprintln!("error: {error}");
            }
        }
        return if errors.is_empty() {
            ExitCode::SUCCESS
        } else {
            ExitCode::from(1)
        };
    }

    let mut results = Vec::new();
    let mut errors = Vec::new();
    for client in clients {
        match repair_one(manager, client).await {
            Ok(result) => results.push(result),
            Err(error) => errors.push(serde_json::json!({
                "client": client.canonical_name(),
                "error": crate::login_url::redact_secrets(&error.to_string()),
            })),
        }
    }
    if json {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "results": results,
                "errors": errors,
            }))
            .unwrap_or_default()
        );
    } else {
        for result in &results {
            if result.changed {
                println!(
                    "repaired {} (backup {})",
                    result.client,
                    result.backup_id.as_deref().unwrap_or("none")
                );
                if result.restart_required {
                    println!(
                        "restart Claude Code to refresh its gateway catalog; its cache was left intact"
                    );
                }
            } else {
                println!("{} is already managed and intact", result.client);
            }
        }
        for error in &errors {
            eprintln!("error: {error}");
        }
    }
    if errors.is_empty() {
        ExitCode::SUCCESS
    } else {
        ExitCode::from(1)
    }
}

fn print_repair_result(
    result: crate::translation_core::Outcome<RepairResult, crate::clients::ClientError>,
    json: bool,
    verb: &crate::translation_core::Str,
) -> ExitCode {
    match result {
        Ok(result) => {
            if json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&result).unwrap_or_default()
                );
            } else {
                println!("{verb} {} using repair snapshot", result.client);
            }
            ExitCode::SUCCESS
        }
        Err(error) => failed(error),
    }
}

async fn repair_one(
    manager: &ClientManager,
    client: ClientKind,
) -> Result<RepairResult, Box<dyn std::error::Error + Send + Sync>> {
    let analysis = manager.analyze(client)?;
    let old_metadata = manager.credential_metadata(client).ok().flatten();
    let bridge = if let Some(base_url) = old_metadata
        .as_ref()
        .and_then(|metadata| metadata.router.as_deref())
    {
        ensure_codex_bridge(manager, client, base_url).await?
    } else {
        None
    };
    let codex_backend_base_url = bridge
        .as_ref()
        .map(|bridge| bridge.backend_base_url().to_string());
    let bridge_matches = bridge.as_ref().is_none_or(|bridge| {
        manager
            .codex_backend_matches(bridge.backend_base_url())
            .unwrap_or(false)
    });
    if analysis.state == OwnershipState::ManagedIntact && bridge_matches {
        if client == ClientKind::Codex && bridge.is_none() {
            crate::codex_loopback_bridge::stop_persistent(
                &manager.codex_loopback_bridge_state_path(),
            )
            .await?;
        }
        if let Some(bridge) = bridge {
            bridge.commit();
        }
        return Ok(RepairResult {
            client,
            before: analysis.state,
            after: analysis.state,
            changed: false,
            restart_required: false,
            backup_id: None,
        });
    }
    if let Some(limitation) = client.setup_limitation() {
        return Err(limitation.into());
    }

    // A drifted managed installation keeps its existing credential. Foreign,
    // incomplete and unconfigured installations acquire and validate a
    // candidate first; no client file is touched until that succeeds.
    if matches!(
        analysis.state,
        OwnershipState::ManagedDrifted | OwnershipState::ManagedIntact
    ) && let (Some(token), Some(metadata)) = (
        manager.managed_token(client)?,
        manager.credential_metadata(client)?,
    ) && let Some(base_url) = metadata.router.as_deref()
    {
        let models = manager.catalog(client, base_url, &token).await?;
        let usable = crate::clients::usable_models(client, &models);
        let result = manager.apply_repair_with_codex_backend(
            client,
            base_url,
            &token,
            &metadata,
            &usable,
            codex_backend_base_url.as_deref(),
        )?;
        if let Err(error) = manager.catalog(client, base_url, &token).await {
            if let Some(id) = result.backup_id.as_deref() {
                manager.rollback_repair(client, id)?;
            }
            return Err(crate::translation_core::format!("post-repair catalog validation failed: {error}").into());
        }
        if client == ClientKind::Codex && bridge.is_none() {
            crate::codex_loopback_bridge::stop_persistent(
                &manager.codex_loopback_bridge_state_path(),
            )
            .await?;
        }
        if let Some(bridge) = bridge {
            bridge.commit();
        }
        return Ok(result);
    }

    drop(bridge);
    let server = crate::managed_server::resolve(None, None, None, None, false).await?;
    let candidate = crate::managed_server::prepare_repair_credential(
        &server,
        client,
        &crate::translation_core::format!("client-repair-{client}"),
        24,
    )
    .await?;
    debug_assert!(candidate.was_minted());
    let metadata = ManagedCredential {
        client: client.to_string(),
        source: TokenSource::Minted,
        token_id: candidate.id(),
        label: candidate
            .was_minted()
            .then(|| crate::translation_core::format!("client-repair-{client}")),
        issued_at: candidate
            .was_minted()
            .then(|| crate::operation_context::now().timestamp()),
        router: Some(server.base_url.clone()),
        management_server: Some(server.management_url.clone()),
        principal_id: candidate
            .was_minted()
            .then(|| candidate.principal_id().to_string()),
        config_sha256: None,
    };
    let models = crate::clients::usable_models(client, candidate.models());
    let bridge = ensure_codex_bridge(manager, client, &server.base_url).await?;
    let codex_backend_base_url = bridge
        .as_ref()
        .map(crate::codex_loopback_bridge::PersistentBridge::backend_base_url);
    let applied = manager.apply_repair_with_codex_backend(
        client,
        &server.base_url,
        &candidate.token,
        &metadata,
        &models,
        codex_backend_base_url,
    );
    let result = match applied {
        Ok(result) => result,
        Err(error) => {
            let bridge_cleanup = if let Some(bridge) = bridge {
                bridge.rollback().await.err()
            } else {
                None
            };
            return match crate::managed_server::cleanup_run_credential(candidate).await {
                Ok(()) if bridge_cleanup.is_none() => Err(error.into()),
                Ok(()) => Err(crate::translation_core::format!(
                    "{error}; the unused Codex bridge could not be removed: {}",
                    bridge_cleanup.expect("checked above")
                )
                .into()),
                Err(cleanup) => Err(crate::translation_core::format!(
                    "{error}; the unused minted repair credential could not be revoked: {cleanup}{}",
                    bridge_cleanup.map_or_else(String::new, |bridge| crate::translation_core::format!(
                        "; the unused Codex bridge could not be removed: {bridge}"
                    ))
                )
                .into()),
            };
        }
    };
    let inference_client = server.inference_client()?;
    if let Err(error) = manager
        .catalog_with_client(
            &inference_client,
            client,
            &server.base_url,
            &candidate.token,
        )
        .await
    {
        let rollback = result
            .backup_id
            .as_deref()
            .map_or(Ok(()), |id| manager.rollback_repair(client, id).map(|_| ()));
        let cleanup = crate::managed_server::cleanup_run_credential(candidate).await;
        let mut message = crate::translation_core::format!("post-repair catalog validation failed: {error}");
        if let Err(rollback) = rollback {
            let _ = write!(message, "; automatic rollback also failed: {rollback}");
        }
        if let Err(cleanup) = cleanup {
            let _ = write!(
                message,
                "; the unused minted repair credential could not be revoked: {cleanup}"
            );
        }
        return Err(message.into());
    }
    if client == ClientKind::Codex && bridge.is_none() {
        crate::codex_loopback_bridge::stop_persistent(&manager.codex_loopback_bridge_state_path())
            .await?;
    }
    if let Some(bridge) = bridge {
        bridge.commit();
    }
    if candidate.was_minted()
        && let (Some(old), Some(old_id), Some(new_id), Some(admin_token)) = (
            old_metadata.as_ref(),
            old_metadata
                .as_ref()
                .filter(|old| old.source == TokenSource::Minted)
                .and_then(|old| old.token_id.as_deref()),
            metadata.token_id.as_deref(),
            server.token.as_deref(),
        )
        && old_id != new_id
        && old.router.as_deref() == Some(server.base_url.as_str())
        && let Err(error) =
            crate::managed_server::revoke(&server.management_url, admin_token, old_id).await
    {
        eprintln!(
            "warning: repaired {client}, but the replaced Router-owned token could not be revoked: {}",
            crate::login_url::redact_secrets(&error.to_string())
        );
    }
    // The candidate intentionally remains live: it is now the credential
    // named by the private environment and secret-free metadata files.
    Ok(result)
}

