    #[test]
    fn reported_origins_drop_credentials_and_request_details() {
        assert_eq!(
            sanitize_origin("https://operator:secret@router.example:8443/private?q=token#fragment")
                .as_deref(),
            Some("https://router.example:8443")
        );
        assert_eq!(
            sanitize_origin("http://router.example:80/api/services/openai").as_deref(),
            Some("http://router.example")
        );
        assert_eq!(sanitize_origin("file:///private/config"), None);
    }
}

//! Authenticated router model discovery for client configuration.

use std::time::Duration;

use serde::{Deserialize, Serialize};

use super::{ClientError, ClientKind, ClientManager, compact_body, normalize_base_url};

/// One model advertised by the configured router.
#[derive(Clone, Debug, Default, Deserialize, Eq, PartialEq)]
pub struct RouterModel {
    pub id: String,
    #[serde(default)]
    pub owned_by: String,
    /// Selector semantics supplied for this exact live row. Unknown is the
    /// fail-closed default; the spelling itself never classifies an alias.
    #[serde(default)]
    pub selector_kind: crate::model_contract::ModelSelectorKind,
    /// Field-level evidence and exact route scope projected by Router.
    #[serde(default)]
    pub capability_provenance: serde_json::Value,
    /// The model's live default, if the provider supplied one.
    #[serde(default)]
    pub default_reasoning_level: Option<String>,
    /// When the provider says this model was created, if it said at all.
    ///
    /// The vendor's own recency signal, projected from the `created` field of
    /// its catalog entry. Read so Router can pick the *current* model when it
    /// must supply one itself, rather than treating catalog position as a
    /// ranking — which pinned the oldest model a deployment could serve
    /// (issue #563).
    #[serde(default)]
    pub provider_created_at: Option<i64>,
    /// `None` means the provider did not supply capability metadata. An empty
    /// list is different: it authoritatively says this model has no selectable
    /// reasoning effort.
    #[serde(default)]
    pub supported_reasoning_levels: Option<Vec<RouterReasoningLevel>>,
    /// Client-specific identities backed by reviewed provider protocol
    /// contracts. An empty object means no safe identity was advertised.
    #[serde(default)]
    pub client_capabilities: RouterClientCapabilities,
    /// Why Router cannot serve this listed row right now — an exhausted z.ai
    /// Coding Plan keeps its rows listed (issue #657). `None` when servable.
    #[serde(default)]
    pub router_unavailable_reason: Option<String>,
}

impl RouterModel {
    /// Whether Router can serve this row right now.
    #[must_use]
    pub const fn is_servable(&self) -> bool {
        self.router_unavailable_reason.is_none()
    }
}

/// Whether one exact client-facing model spelling is authorized by the live
/// catalog.
///
/// Claude Code appends `[1m]` to an Anthropic model id when the user selects
/// its supported one-million-token context variant. Router catalogs advertise
/// the base id, but the suffixed value must still reach Claude unchanged so the
/// client can preserve that selection. This exception is deliberately limited
/// to an exact Anthropic-owned base; compatible models owned by another
/// provider do not acquire a context variant merely because Claude can use
/// their wire protocol.
pub fn model_is_authorized(client: ClientKind, models: &[RouterModel], requested: &str) -> bool {
    if client == ClientKind::ClaudeCode && requested.ends_with("[1m]") {
        return claude_context_variant_is_authorized(models, requested);
    }
    if models.iter().any(|model| model.id == requested) {
        return true;
    }
    false
}

/// Whether Claude's context-variant spelling has an exact Anthropic base in
/// the live catalog.
pub fn claude_context_variant_is_authorized(models: &[RouterModel], requested: &str) -> bool {
    let Some(base) = requested
        .strip_suffix("[1m]")
        .filter(|base| !base.is_empty())
    else {
        return false;
    };
    models
        .iter()
        .any(|model| model.id == base && model.owned_by == super::ANTHROPIC_MODEL_OWNER)
}

#[derive(Clone, Debug, Default, Deserialize, Eq, PartialEq)]
pub struct RouterClientCapabilities {
    #[serde(default)]
    pub claude: Option<ClaudeModelCapabilities>,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq)]
pub struct ClaudeModelCapabilities {
    pub behaves_as: String,
    pub source: String,
}

/// One reasoning option retained verbatim from a live Codex catalog.
///
/// Strings are intentionally not an enum: Codex accepts provider-defined
/// future values, and Router must forward rather than freeze that vocabulary.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct RouterReasoningLevel {
    pub effort: String,
    #[serde(default)]
    pub description: String,
}

#[derive(Deserialize)]
struct RouterCatalog {
    data: Vec<serde_json::Value>,
}

/// Parse every row of a catalog's `data` array, naming the first row that
/// does not fit [`RouterModel`].
///
/// A row is never dropped silently: skipping it turned one unparsable z.ai
/// row into "no models authorized for this client token", which hid the
/// real contract mismatch behind an authorization error (issue #620).
pub fn parse_router_models(data: &[serde_json::Value]) -> Result<Vec<RouterModel>, String> {
    data.iter()
        .enumerate()
        .map(|(index, row)| {
            serde_json::from_value::<RouterModel>(row.clone()).map_err(|error| {
                let id = row
                    .get("id")
                    .and_then(serde_json::Value::as_str)
                    .map_or_else(String::new, |id| format!(" (`{id}`)"));
                format!(
                    "router model catalog row {index}{id} does not match this Router \
                     version's catalog contract: {error}; update Router on this machine or \
                     on the server so both speak the same contract"
                )
            })
        })
        .collect()
}

impl ClientManager {
    /// Read the authenticated model catalog used by setup and doctor.
    pub(crate) async fn catalog(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
    ) -> Result<Vec<RouterModel>, ClientError> {
        self.catalog_with_client(&reqwest::Client::new(), client, base_url, token)
            .await
    }

    /// Read the catalog with the trust configured for this Router origin.
    pub(crate) async fn catalog_with_client(
        &self,
        http: &reqwest::Client,
        client: ClientKind,
        base_url: &str,
        token: &str,
    ) -> Result<Vec<RouterModel>, ClientError> {
        let base_url = normalize_base_url(base_url)?;
        let url = models_url(client, &base_url);
        let request = http
            .get(&url)
            .header("x-link-assistant-client", client.canonical_name());
        let request = match client {
            ClientKind::GeminiCli => request.header("x-goog-api-key", token),
            _ => request.bearer_auth(token),
        };
        let response = request
            .timeout(Duration::from_secs(15))
            .send()
            .await
            .map_err(|error| {
                ClientError::message(format!("router catalog is not reachable at {url}: {error}"))
            })?;
        let code = response.status();
        let response_body = response.text().await.unwrap_or_default();
        if !code.is_success() {
            return Err(ClientError::message(format!(
                "router catalog request failed at {url} ({code}): {}",
                compact_body(&response_body)
            )));
        }
        let catalog: RouterCatalog = serde_json::from_str(&response_body).map_err(|error| {
            ClientError::message(format!("router returned an invalid model catalog: {error}"))
        })?;
        let mut models = parse_router_models(&catalog.data)
            .map_err(ClientError::message)?
            .into_iter()
            .filter(|model| !model.id.trim().is_empty())
            .collect::<Vec<_>>();
        models.sort_by(|left, right| {
            left.id
                .cmp(&right.id)
                .then_with(|| left.owned_by.cmp(&right.owned_by))
        });
        models.dedup_by(|left, right| left.id == right.id && left.owned_by == right.owned_by);
        if models.is_empty() {
            return Err(ClientError::message(
                "router catalog contains no models from healthy subscriptions",
            ));
        }
        Ok(models)
    }
}

fn models_url(_client: ClientKind, base_url: &str) -> String {
    let base_url = base_url.trim_end_matches('/');
    let origin = [
        "/api/services/anthropic",
        "/api/services/openai/v1",
        "/api/services/codex/v1",
        "/api/services/qwen/v1",
        "/api/services/gemini",
        // Read an old client config only to locate its origin. Requests still
        // use the canonical route below; no removed server alias is revived.
        "/api/gemini",
        "/api/qwen/v1",
        "/api/codex/v1",
        "/v1",
    ]
    .into_iter()
    .find_map(|suffix| base_url.strip_suffix(suffix))
    .unwrap_or(base_url);
    format!(
        "{origin}{}",
        crate::route_contract::route_template(crate::route_contract::RouteId::AggregateModels)
    )
}

pub(super) fn doctor_model(
    client: ClientKind,
    catalog: &[RouterModel],
) -> Result<&str, ClientError> {
    select_model(client, catalog).ok_or_else(|| ClientError::message(unavailable(client, catalog)))
}

/// The model that suits `client` best, from what the router advertises.
///
/// One rule, used by `with`, `clients setup` and `clients doctor`. They used
/// to answer this differently — first entry of a declared owner, any owner at
/// all, and no filter whatsoever — so `clients setup opencode` could write a
/// model into a client config that `with opencode` would then refuse to launch
/// on (issue #301).
///
/// No preferred model *name*: the first catalog entry of the best available
/// owner is used, so nothing here can point at a withdrawn or unentitled
/// vendor id (issue #192).
#[must_use]
pub fn select_model(client: ClientKind, catalog: &[RouterModel]) -> Option<&str> {
    let integration = client.integration();
    for owner in integration.model_owners {
        if let Some(model) = catalog.iter().find(|model| &model.owned_by == owner) {
            return Some(model.id.as_str());
        }
    }
    if integration.strict_owner && !catalog.iter().all(|model| model.owned_by.is_empty()) {
        // Substituting is defensible only when the catalog does not say who
        // owns its models: then the router cannot tell, and a usable model
        // beats refusing. When every entry names a *different* owner it does
        // know, and substituting one launched Claude Code against an `OpenAI`
        // model — so the client blamed its own model name rather than the
        // lapsed subscription (issue #225).
        return None;
    }
    catalog.first().map(|model| model.id.as_str())
}

const FRESH_ZAI_PREFERRED_MODEL: &str = "glm-5.3";

/// Dynamic Claude Code main/subagent target for a z.ai-backed catalog.
///
/// Native Anthropic discovery remains in charge whenever the live catalog has
/// an Anthropic model. With z.ai-only compatible access, Claude Code cannot
/// resolve its built-in Default and subagent fallback itself, so the smallest
/// supported pair of pins targets one exact currently advertised z.ai model.
/// An explicit z.ai model wins at both real boundaries. `router with` also
/// points the Default row's family variables here when no Anthropic row exists
/// (issue #630); its picker hides the built-in family rows in that case.
#[must_use]
pub fn claude_gateway_model(catalog: &[RouterModel], explicit: Option<&str>) -> Option<String> {
    if let Some(explicit) = explicit
        && catalog
            .iter()
            .any(|model| model.id == explicit && model.owned_by == super::ZAI_MODEL_OWNER)
    {
        return Some(explicit.to_string());
    }
    if catalog
        .iter()
        .any(|model| model.owned_by == super::ANTHROPIC_MODEL_OWNER)
    {
        return None;
    }
    // Prefer the flagship only when this token's live healthy catalog offers
    // it. Newer Flash release dates do not change a fresh profile's default.
    // A withdrawn/unhealthy flagship is absent here, so the deterministic
    // provider-recency fallback below remains available (#634).
    if let Some(flagship) = catalog.iter().find(|model| {
        model.owned_by == super::ZAI_MODEL_OWNER
            && model.id == FRESH_ZAI_PREFERRED_MODEL
            && model.is_servable()
    }) {
        return Some(flagship.id.clone());
    }
    // Catalog order is the provider's listing, not a ranking. Taking the first
    // entry pinned whichever model the vendor happened to list first — in
    // practice the *oldest* of ten, while the picker's last row was the newest
    // (issue #563). The vendor's own `created` timestamp is the signal that
    // actually answers "which of these is current"; the id is the tie-break, so
    // the result never depends on array position.
    catalog
        .iter()
        .filter(|model| model.owned_by == super::ZAI_MODEL_OWNER)
        .max_by(|left, right| {
            // A row Router cannot serve is never preferred over one it can.
            left.is_servable()
                .cmp(&right.is_servable())
                .then_with(|| left.provider_created_at.cmp(&right.provider_created_at))
                .then_with(|| left.id.cmp(&right.id))
        })
        .map(|model| model.id.clone())
}

/// Every model `client` could be launched on, best owners first.
///
/// What a client config embeds must be what `with` would launch it on, or the
/// two disagree about the same question (issue #301).
#[must_use]
pub fn usable_models(client: ClientKind, catalog: &[RouterModel]) -> Vec<RouterModel> {
    let integration = client.integration();
    if integration.model_owners.is_empty() {
        return catalog.to_vec();
    }
    let mut preferred: Vec<RouterModel> = Vec::new();
    for owner in integration.model_owners {
        preferred.extend(
            catalog
                .iter()
                .filter(|model| &model.owned_by == owner)
                .cloned(),
        );
    }
    if preferred.is_empty() && !integration.strict_owner {
        return catalog.to_vec();
    }
    preferred
}

/// Whether Codex may use the Responses WebSocket transport for this launch.
///
/// z.ai's Codex adapter serves HTTP/SSE Responses but cannot preserve Codex's
/// WebSocket session semantics. An exact selection decides when present; with
/// no selection, a mixed picker must remain on the transport every visible
/// model can serve (issue #578).
#[must_use]
pub fn codex_supports_websockets(models: &[RouterModel], selected_model: Option<&str>) -> bool {
    if let Some(selected) = selected_model {
        return models
            .iter()
            .find(|model| model.id == selected)
            .is_some_and(|model| model.owned_by != super::ZAI_MODEL_OWNER);
    }
    !usable_models(ClientKind::Codex, models)
        .iter()
        .any(|model| model.owned_by == super::ZAI_MODEL_OWNER)
}

/// Why nothing in the catalog suits this client, and what to do about it.
///
/// Names the owners that *are* advertised and points at `--model`, because the
/// message named the mismatch and left the reader to guess that an explicit
/// model is still allowed (issue #301).
#[must_use]
pub fn unavailable(client: ClientKind, catalog: &[RouterModel]) -> String {
    let mut advertised: Vec<&str> = catalog
        .iter()
        .map(|model| model.owned_by.as_str())
        .filter(|owner| !owner.is_empty())
        .collect();
    advertised.sort_unstable();
    advertised.dedup();
    let holdings = if advertised.is_empty() {
        "the catalog is empty".to_string()
    } else {
        format!("it advertises only {} models", advertised.join(", "))
    };
    let wanted = client.integration().model_owners.join(", ");
    format!(
        "the router advertises no model for {} ({wanted} models): {holdings}. Authorize a \
         matching subscription on the router host, or pass --model explicitly to use one of \
         the models it does advertise",
        client.integration().name
    )
}

use super::{
    ClientError, ClientKind, ClientManager, DocumentMut, PathBuf, Value, atomic_write, fs,
    read_or_empty,
};

impl ClientManager {
    /// Remove a process-wide Codex catalog override before managed repair.
    ///
    /// `model_catalog_json` replaces Codex's complete catalog, so leaving a
    /// foreign value beside the managed provider lets that file choose models
    /// the Router never advertised. Repair snapshots this file before calling
    /// the helper, which makes the removal transactional and byte-exact on
    /// rollback.
    pub(super) fn remove_codex_catalog_constraint(&self) -> Result<(), ClientError> {
        let path = self.config_path(ClientKind::Codex);
        let source = read_or_empty(&path)?;
        if source.trim().is_empty() {
            return Ok(());
        }
        let mut document = source.parse::<DocumentMut>().map_err(|error| {
            ClientError::message(format!("invalid TOML in {}: {error}", path.display()))
        })?;
        if document
            .as_table_mut()
            .remove("model_catalog_json")
            .is_some()
        {
            atomic_write(&path, document.to_string().as_bytes())?;
        }
        Ok(())
    }

    /// Validate the foreign catalog before a repair transaction snapshots or
    /// edits Codex configuration. Missing, non-regular, symlinked, or invalid
    /// catalogs are not safe evidence of the constraint being repaired.
    pub(super) fn validate_codex_catalog_constraint(&self) -> Result<(), ClientError> {
        let config_path = self.config_path(ClientKind::Codex);
        let source = read_or_empty(&config_path)?;
        if source.trim().is_empty() {
            return Ok(());
        }
        let document = source.parse::<DocumentMut>().map_err(|error| {
            ClientError::message(format!(
                "invalid TOML in {}: {error}",
                config_path.display()
            ))
        })?;
        let Some(value) = document.get("model_catalog_json") else {
            return Ok(());
        };
        let path = value.as_str().ok_or_else(|| {
            ClientError::message("Codex model_catalog_json must be a file path string")
        })?;
        let path = PathBuf::from(path);
        let metadata = fs::symlink_metadata(&path).map_err(|error| {
            ClientError::message(format!(
                "cannot validate Codex model_catalog_json {}: {error}",
                path.display()
            ))
        })?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err(ClientError::message(format!(
                "refusing Codex model_catalog_json {} because it is {}",
                path.display(),
                if metadata.file_type().is_symlink() {
                    "a symlink"
                } else {
                    "not a regular file"
                }
            )));
        }
        let catalog: Value = serde_json::from_slice(&fs::read(&path)?).map_err(|error| {
            ClientError::message(format!(
                "invalid JSON in Codex model_catalog_json {}: {error}",
                path.display()
            ))
        })?;
        if !catalog.get("models").is_some_and(Value::is_array) {
            return Err(ClientError::message(format!(
                "Codex model_catalog_json {} must contain a models array",
                path.display()
            )));
        }
        Ok(())
    }
}

//! Codex loopback bridge state and configuration inspection.

use super::{
    CODEX_PROVIDER, ClientError, ClientKind, ClientManager, DocumentMut, Item, OWNERSHIP_MARKER,
    PathBuf, SetupResult, Table, fs, read_codex_marker, read_or_empty, unchanged, value,
    write_codex_marker, write_if_changed,
};

impl ClientManager {
    /// Owner-only state for the persistent bridge accepted by Codex's origin policy.
    #[must_use]
    pub fn codex_loopback_bridge_state_path(&self) -> PathBuf {
        self.managed_path(ClientKind::Codex, "loopback-bridge.json")
    }

    pub(crate) fn codex_backend_matches(&self, expected: &str) -> Result<bool, ClientError> {
        let path = self.config_path(ClientKind::Codex);
        let source = read_or_empty(&path)?;
        if source.trim().is_empty() {
            return Ok(false);
        }
        let document = source.parse::<DocumentMut>().map_err(|error| {
            ClientError::message(format!("invalid TOML in {}: {error}", path.display()))
        })?;
        Ok(document.get("chatgpt_base_url").and_then(Item::as_str) == Some(expected))
    }
    pub(super) fn setup_codex(
        &self,
        base_url: &str,
        backend_base_url: Option<&str>,
        supports_websockets: bool,
    ) -> Result<SetupResult, ClientError> {
        let path = self.config_path(ClientKind::Codex);
        let source = read_or_empty(&path)?;
        let marker = self.codex_home.join(OWNERSHIP_MARKER);
        let existing_marker = marker
            .exists()
            .then(|| read_codex_marker(&marker))
            .transpose()?;
        let mut document = if source.trim().is_empty() {
            DocumentMut::new()
        } else {
            source.parse::<DocumentMut>().map_err(|error| {
                ClientError::message(format!("invalid TOML in {}: {error}", path.display()))
            })?
        };
        let previous_provider = document
            .get("model_provider")
            .and_then(Item::as_str)
            .map(str::to_string);
        let previous_chatgpt_base_url = document
            .get("chatgpt_base_url")
            .and_then(Item::as_str)
            .map(str::to_string);
        let previous_realtime_ws_base_url = document
            .get("experimental_realtime_ws_base_url")
            .and_then(Item::as_str)
            .map(str::to_string);
        let previous_realtime_call_base_url = document
            .get("experimental_realtime_webrtc_call_base_url")
            .and_then(Item::as_str)
            .map(str::to_string);
        document["model_provider"] = value(CODEX_PROVIDER);
        if document.get("model_providers").is_none() {
            document["model_providers"] = Item::Table(Table::new());
        }
        let providers = document["model_providers"]
            .as_table_like_mut()
            .ok_or_else(|| ClientError::message("model_providers must be a TOML table"))?;
        if providers.get(CODEX_PROVIDER).is_none() {
            providers.insert(CODEX_PROVIDER, Item::Table(Table::new()));
        }
        let provider = providers
            .get_mut(CODEX_PROVIDER)
            .and_then(Item::as_table_like_mut)
            .ok_or_else(|| {
                ClientError::message("model_providers.link-assistant must be a TOML table")
            })?;
        provider.insert("name", value("OpenAI"));
        provider.insert("base_url", value(base_url));
        provider.remove("env_key");
        provider.insert("wire_api", value("responses"));
        provider.insert("requires_openai_auth", value(true));
        provider.insert("supports_websockets", value(supports_websockets));
        provider.insert("supports_standalone_web_search", value(true));
        let backend_base = backend_base_url.map_or_else(
            || base_url.strip_suffix("/v1").unwrap_or(base_url).to_string() + "/backend-api",
            str::to_string,
        );
        document["chatgpt_base_url"] = value(&backend_base);
        document["experimental_realtime_ws_base_url"] = value(base_url);
        document["experimental_realtime_webrtc_call_base_url"] = value(base_url);
        let result = write_if_changed(&path, &source, &document.to_string())?;
        if let Some(existing) = existing_marker {
            let original_backend = if previous_chatgpt_base_url.as_deref()
                == existing.managed_chatgpt_base_url.as_deref()
            {
                existing.previous_chatgpt_base_url
            } else {
                previous_chatgpt_base_url
            };
            let original_ws = if previous_realtime_ws_base_url.as_deref()
                == existing.managed_realtime_base_url.as_deref()
            {
                existing.previous_realtime_ws_base_url
            } else {
                previous_realtime_ws_base_url
            };
            let original_call = if previous_realtime_call_base_url.as_deref()
                == existing.managed_realtime_base_url.as_deref()
            {
                existing.previous_realtime_call_base_url
            } else {
                previous_realtime_call_base_url
            };
            write_codex_marker(
                &marker,
                existing.previous_provider.as_deref(),
                &backend_base,
                original_backend.as_deref(),
                base_url,
                original_ws.as_deref(),
                original_call.as_deref(),
            )?;
        } else {
            let previous_provider = previous_provider.filter(|value| value != CODEX_PROVIDER);
            write_codex_marker(
                &marker,
                previous_provider.as_deref(),
                &backend_base,
                previous_chatgpt_base_url.as_deref(),
                base_url,
                previous_realtime_ws_base_url.as_deref(),
                previous_realtime_call_base_url.as_deref(),
            )?;
        }
        Ok(result)
    }

    pub(super) fn remove_codex(&self) -> Result<SetupResult, ClientError> {
        let path = self.config_path(ClientKind::Codex);
        let source = read_or_empty(&path)?;
        if source.trim().is_empty() {
            return Ok(unchanged(path));
        }
        let marker_path = self.codex_home.join(OWNERSHIP_MARKER);
        if !marker_path.exists() {
            return Ok(unchanged(path));
        }
        let mut document = source.parse::<DocumentMut>().map_err(|error| {
            ClientError::message(format!("invalid TOML in {}: {error}", path.display()))
        })?;
        let marker = read_codex_marker(&marker_path)?;
        if document.get("model_provider").and_then(Item::as_str) == Some(CODEX_PROVIDER) {
            if let Some(previous_provider) = marker.previous_provider {
                document["model_provider"] = value(previous_provider);
            } else {
                document.as_table_mut().remove("model_provider");
            }
        }
        if let Some(providers) = document
            .get_mut("model_providers")
            .and_then(Item::as_table_like_mut)
        {
            providers.remove(CODEX_PROVIDER);
        }
        if document.get("chatgpt_base_url").and_then(Item::as_str)
            == marker.managed_chatgpt_base_url.as_deref()
        {
            if let Some(previous) = marker.previous_chatgpt_base_url {
                document["chatgpt_base_url"] = value(previous);
            } else {
                document.as_table_mut().remove("chatgpt_base_url");
            }
        }
        restore_owned_value(
            &mut document,
            "experimental_realtime_ws_base_url",
            marker.managed_realtime_base_url.as_deref(),
            marker.previous_realtime_ws_base_url,
        );
        restore_owned_value(
            &mut document,
            "experimental_realtime_webrtc_call_base_url",
            marker.managed_realtime_base_url.as_deref(),
            marker.previous_realtime_call_base_url,
        );
        let result = write_if_changed(&path, &source, &document.to_string())?;
        if marker_path.exists() {
            fs::remove_file(marker_path)?;
        }
        Ok(result)
    }
}

fn restore_owned_value(
    document: &mut DocumentMut,
    key: &str,
    managed: Option<&str>,
    previous: Option<String>,
) {
    if document.get(key).and_then(Item::as_str) != managed {
        return;
    }
    if let Some(previous) = previous {
        document[key] = value(previous);
    } else {
        document.as_table_mut().remove(key);
    }
}

//! Metadata describing the router credential a managed client setup installed.
//!
//! `clients setup` writes a shell environment file holding a bearer token, so
//! `clients remove` has to know whether that token was minted by the setup
//! itself. Without this record the local file disappears while the credential
//! stays valid for anyone who copied it — the regression from issue #190.

use std::fs;
use std::path::Path;

use serde::{Deserialize, Serialize};

use super::{ClientError, files::atomic_write};

/// Where the token written into the managed environment file came from.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum TokenSource {
    /// `clients setup` minted the token itself, so it owns its lifetime.
    Minted,
    /// The operator supplied the token; removal leaves it alone by default.
    Supplied,
}

/// Secret-free description of one managed client credential.
///
/// The token itself is deliberately absent: only the store record id is kept,
/// which is enough to revoke and useless to an attacker.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct ManagedCredential {
    pub client: String,
    pub source: TokenSource,
    /// Token record id (`sub`), when it is known for this credential.
    #[serde(default)]
    pub token_id: Option<String>,
    #[serde(default)]
    pub label: Option<String>,
    #[serde(default)]
    pub issued_at: Option<i64>,
    /// The router this credential was minted by, when it is known.
    ///
    /// Recorded so a credential can still be named — and therefore revoked —
    /// after the command that minted it has gone, which a local-only token id
    /// cannot do once the target is another deployment.
    #[serde(default)]
    pub router: Option<String>,
    /// Management origin that issued this credential, when it differs from
    /// the local token store used by legacy `clients setup` calls.
    ///
    /// This is deliberately only an origin. Administrative credentials are
    /// never copied into client metadata.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub management_server: Option<String>,
    /// Non-secret subscriber identity carried by the signed client token.
    #[serde(default)]
    pub principal_id: Option<String>,
    /// Hash of the complete client config after setup. This contains no
    /// configuration bytes or credentials; it only distinguishes a genuinely
    /// identical second setup from a file the user changed afterward.
    #[serde(default)]
    pub config_sha256: Option<String>,
}

impl ManagedCredential {
    /// Whether `clients remove` must revoke this credential before deleting it.
    #[must_use]
    pub fn revocable_by_default(&self) -> bool {
        self.source == TokenSource::Minted && self.token_id.is_some()
    }
}

/// Persist the credential record next to the managed environment file.
pub fn write(path: &Path, credential: &ManagedCredential) -> Result<(), ClientError> {
    let parent = path
        .parent()
        .ok_or_else(|| ClientError::message("credential metadata has no parent directory"))?;
    fs::create_dir_all(parent)?;
    let rendered = format!("{}\n", serde_json::to_string_pretty(credential)?);
    atomic_write(path, rendered.as_bytes())?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        fs::set_permissions(path, fs::Permissions::from_mode(0o600))?;
    }
    Ok(())
}

/// Read the credential record, tolerating a missing or unreadable file.
///
/// A corrupt record is reported as an error rather than silently ignored: the
/// caller uses it to decide whether a live credential still needs revoking.
pub fn read(path: &Path) -> Result<Option<ManagedCredential>, ClientError> {
    let source = super::files::read_or_empty(path)?;
    if source.trim().is_empty() {
        return Ok(None);
    }
    let credential: ManagedCredential = serde_json::from_str(&source).map_err(|error| {
        ClientError::message(format!(
            "could not parse managed credential metadata {}: {error}",
            path.display()
        ))
    })?;
    Ok(Some(credential))
}

/// Delete the credential record if it exists.
pub fn remove(path: &Path) -> Result<(), ClientError> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(ClientError::message(format!(
            "could not remove {}: {error}",
            path.display()
        ))),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn minted_records_are_revocable_and_supplied_ones_are_not() {
        let minted = ManagedCredential {
            client: "codex".into(),
            source: TokenSource::Minted,
            token_id: Some("id".into()),
            label: None,
            issued_at: None,
            router: None,
            management_server: None,
            principal_id: Some("primary".into()),
            config_sha256: None,
        };
        assert!(minted.revocable_by_default());
        let supplied = ManagedCredential {
            source: TokenSource::Supplied,
            ..minted
        };
        assert!(!supplied.revocable_by_default());
    }

    #[test]
    fn records_round_trip_through_disk_without_the_token() {
        let directory = tempfile::tempdir().expect("temp dir");
        let path = directory.path().join("codex.json");
        let credential = ManagedCredential {
            client: "codex".into(),
            source: TokenSource::Minted,
            token_id: Some("token-id".into()),
            label: Some("client-codex".into()),
            issued_at: Some(7),
            router: Some("http://router.test".into()),
            management_server: Some("http://admin.router.test".into()),
            principal_id: Some("primary".into()),
            config_sha256: Some("configuration-hash".into()),
        };
        write(&path, &credential).expect("write metadata");
        let contents = fs::read_to_string(&path).expect("read metadata");
        assert!(!contents.contains("la_sk_"));
        let read_back = read(&path).expect("read metadata").expect("record exists");
        assert_eq!(read_back.token_id.as_deref(), Some("token-id"));
        assert_eq!(read_back.source, TokenSource::Minted);
        assert_eq!(
            read_back.management_server.as_deref(),
            Some("http://admin.router.test")
        );
        remove(&path).expect("remove metadata");
        assert!(read(&path).expect("missing metadata is fine").is_none());
    }
}

//! The `clients doctor` reachability probe.
//!
//! Split from `clients.rs` to keep that file within the repository's 1000-line
//! limit.

use std::time::Duration;

use serde_json::json;

use super::files::read_environment_value;
use super::{
    ClientError, ClientKind, ClientManager, DOCTOR_MAX_TOKENS, OwnershipState, compact_body,
    doctor_model,
};

pub const DOCTOR_EVIDENCE_HEADER: &str = "x-link-assistant-client-check";
pub const DOCTOR_EVIDENCE_VALUE: &str = "reachability";

impl ClientManager {
    /// Exercise the same URL and token variable configured for the client.
    pub async fn doctor(&self, client: ClientKind) -> Result<String, ClientError> {
        let client_status = self.status(client)?;
        crate::operation_output::report(crate::operation_reports::ClientDoctorReport {
            client: serde_json::from_value(serde_json::to_value(&client_status)?)?,
            reachable: false,
            url: client_status.base_url.clone(),
            http_status: None,
            model: None,
            output: Vec::new(),
        });
        if let Some(limitation) = client.setup_limitation() {
            return Err(ClientError::message(limitation));
        }
        if client == ClientKind::ClaudeCode {
            require_claude_gateway_version()?;
        }
        let ownership = self.analyze(client)?;
        if ownership.state != OwnershipState::ManagedIntact {
            return Err(ClientError::message(format!(
                "{} routing ownership is {}{}; run `clients repair {client} --dry-run` to inspect it, then `clients repair {client}`",
                client.display_name(),
                ownership.state,
                if ownership.conflicts.is_empty() {
                    String::new()
                } else {
                    format!(" (conflicts: {})", ownership.conflicts.join(", "))
                }
            )));
        }
        let status = self.status(client)?;
        let base_url = status.base_url.ok_or_else(|| {
            ClientError::message(format!(
                "{} is not configured; run `clients setup {client}`",
                client.display_name()
            ))
        })?;
        let token_env = client
            .token_env()
            .ok_or_else(|| ClientError::message("client has no router token environment"))?;
        let token = self
            .environment_var(token_env)
            .or_else(|| {
                read_environment_value(&self.environment_path(client), token_env)
                    .ok()
                    .flatten()
            })
            .ok_or_else(|| {
                ClientError::message(format!(
                    "{token_env} is unset and no managed credential exists; run `clients setup {client}`"
                ))
            })?;
        let catalog = self.catalog(client, &base_url, &token).await?;
        let model = doctor_model(client, &catalog)?;
        let endpoint = format!(
            "{}{}",
            base_url.trim_end_matches('/'),
            client.integration().endpoint_suffix
        );
        let (url, body) = probe_request(client, &endpoint, model);
        let request = reqwest::Client::new()
            .post(&url)
            .headers(probe_headers(client, &token)?)
            .json(&body);
        let response = request
            .timeout(Duration::from_secs(30))
            .send()
            .await
            .map_err(|error| {
                ClientError::message(format!("router is not reachable at {url}: {error}"))
            })?;
        let code = response.status();
        crate::operation_output::report(crate::operation_reports::ClientDoctorReport {
            client: serde_json::from_value(serde_json::to_value(&client_status)?)?,
            reachable: true,
            url: Some(url.clone()),
            http_status: Some(code.as_u16()),
            model: Some(model.to_owned()),
            output: Vec::new(),
        });
        let response_body = response.text().await.unwrap_or_default();
        if code.is_success() {
            return Ok(format!(
                "{} reached {url} successfully ({code})",
                client.display_name()
            ));
        }
        if code.as_u16() == 401 || code.as_u16() == 403 {
            return Err(ClientError::message(format!(
                "router rejected {token_env} ({code}); the token is invalid, expired, or revoked"
            )));
        }
        if code.as_u16() == 503 {
            return Err(ClientError::message(format!(
                "router reached, but its upstream credential is unavailable ({code}): {}",
                compact_body(&response_body)
            )));
        }
        if code.as_u16() == 404 {
            return Err(ClientError::message(format!(
                "router reached, but catalog model '{model}' is unavailable ({code}): {}",
                compact_body(&response_body)
            )));
        }
        Err(ClientError::message(format!(
            "router request failed at {url} ({code}): {}",
            compact_body(&response_body)
        )))
    }
}

/// Minimal Router-owned probe headers. Client fingerprints are deliberately
/// absent: the exact internal marker is accepted only with the signed client
/// binding and is stripped before any native provider request.
pub fn probe_headers(
    client: ClientKind,
    token: &str,
) -> Result<reqwest::header::HeaderMap, ClientError> {
    use reqwest::header::{AUTHORIZATION, HeaderMap, HeaderValue};

    let mut headers = HeaderMap::new();
    let credential = if client == ClientKind::GeminiCli {
        HeaderValue::from_str(token)
    } else {
        HeaderValue::from_str(&format!("Bearer {token}"))
    }
    .map_err(|_| ClientError::message("managed client credential is not a valid HTTP header"))?;
    if client == ClientKind::GeminiCli {
        headers.insert("x-goog-api-key", credential);
    } else {
        headers.insert(AUTHORIZATION, credential);
    }
    if client == ClientKind::ClaudeCode {
        headers.insert("anthropic-version", HeaderValue::from_static("2023-06-01"));
    }
    headers.insert(
        DOCTOR_EVIDENCE_HEADER,
        HeaderValue::from_static(DOCTOR_EVIDENCE_VALUE),
    );
    Ok(headers)
}

const MINIMUM_CLAUDE_GATEWAY_VERSION: (u64, u64, u64) = (2, 1, 255);

/// Claude Code 2.1.255 includes current gateway alias resolution as well as
/// the original discovery support introduced in 2.1.129.
///
/// There is deliberately no upper bound. The pinned real-client fixture is a
/// tested baseline, not a maximum: rejecting a newer release by number alone
/// blocked clients that launch and route correctly (issue #609). The
/// credential boundary does not depend on this gate either — Router only ever
/// hands the child its own token and base URL, and Claude.ai operations that
/// need a split-auth mechanism are refused per operation by
/// `unsupported_native_command` whatever the version (issue #520).
fn claude_gateway_version_supported(output: &str) -> bool {
    output
        .split(|character: char| !(character.is_ascii_digit() || character == '.'))
        .find_map(|part| {
            let mut pieces = part.split('.');
            Some((
                pieces.next()?.parse::<u64>().ok()?,
                pieces.next()?.parse::<u64>().ok()?,
                pieces.next()?.parse::<u64>().ok()?,
            ))
        })
        .is_some_and(|version| version >= MINIMUM_CLAUDE_GATEWAY_VERSION)
}

/// Fail with an actionable diagnostic when an installed Claude is too old.
#[allow(clippy::redundant_pub_crate)]
pub(crate) fn require_claude_gateway_version() -> Result<(), ClientError> {
    let Ok(output) = crate::operation_context::process_output(
        crate::operation_context::command("claude").arg("--version"),
    ) else {
        return Ok(());
    };
    let version = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    if output.status.success() && claude_gateway_version_supported(&version) {
        return Ok(());
    }
    Err(ClientError::message(format!(
        "Claude Code 2.1.255 or newer is required for Router gateway model discovery and alias resolution; installed version reports '{}'. Update Claude Code, then restart Claude to refresh ~/.claude/cache/gateway-models.json",
        version.trim()
    )))
}

/// The URL and body `doctor` probes with.
///
/// A connectivity check is answered by a 200 with any body. Probing at the
/// ceiling — 24576 output tokens, adaptive thinking at `high`, or `xhigh`
/// reasoning — bought the deepest reasoning the account can produce to find out
/// whether a URL answers, on a command whose name, help and output all say
/// "reachability" (issue #309). #173 removed the hardcoded model *name* and left
/// the price; this is the price.
///
/// Pure, so the price is assertable without spending it.
pub fn probe_request(
    client: ClientKind,
    base_url: &str,
    model: &str,
) -> (String, serde_json::Value) {
    let base = base_url.trim_end_matches('/');
    match client {
        ClientKind::Codex => (
            format!("{base}/responses"),
            json!({
                "model": model,
                "input": "Reply OK",
                "max_output_tokens": DOCTOR_MAX_TOKENS,
                "reasoning": {"effort": "low"}
            }),
        ),
        ClientKind::ClaudeCode => (
            format!("{base}/v1/messages"),
            json!({
                "model": model,
                "max_tokens": DOCTOR_MAX_TOKENS,
                "messages": [{"role":"user", "content":"Reply OK"}]
            }),
        ),
        ClientKind::GrokCli | ClientKind::Opencode | ClientKind::QwenCode | ClientKind::Agent => (
            format!("{base}/chat/completions"),
            json!({
                "model": model,
                "max_tokens": DOCTOR_MAX_TOKENS,
                "reasoning_effort": "low",
                "messages": [{"role":"user", "content":"Reply OK"}]
            }),
        ),
        ClientKind::Cursor | ClientKind::GeminiCli => unreachable!(),
    }
}

#[cfg(test)]
mod tests {
    use super::{DOCTOR_MAX_TOKENS, claude_gateway_version_supported, probe_request};
    use crate::clients::ClientKind;

    /// The probe asks for the cheapest answer that proves a URL responds, for
    /// every client it can probe (issue #309).
    #[test]
    fn every_probe_asks_at_the_floor_not_the_ceiling() {
        assert_eq!(DOCTOR_MAX_TOKENS, 64, "a reachability check is not a task");
        for client in ClientKind::ALL {
            if matches!(client, ClientKind::Cursor | ClientKind::GeminiCli) {
                continue;
            }
            let (url, body) = probe_request(client, "https://router.example/", "a-model");
            assert!(
                !url.contains("//chat") && !url.contains("//v1") && !url.contains("//responses"),
                "{client}: a trailing slash must not double: {url}"
            );
            assert_eq!(body["model"], "a-model", "{client} probes the given model");
            let budget = body
                .get("max_tokens")
                .or_else(|| body.get("max_output_tokens"))
                .and_then(serde_json::Value::as_u64)
                .unwrap_or_else(|| panic!("{client} must bound its output"));
            assert_eq!(
                budget,
                u64::from(DOCTOR_MAX_TOKENS),
                "{client} must probe at the floor"
            );
            let effort = body
                .get("reasoning_effort")
                .or_else(|| body.pointer("/reasoning/effort"));
            if let Some(effort) = effort {
                assert_eq!(effort, "low", "{client} must not buy deep reasoning");
            }
        }
    }

    #[test]
    fn gateway_discovery_requires_current_claude_alias_support() {
        assert!(!claude_gateway_version_supported("2.1.252 (Claude Code)"));
        assert!(claude_gateway_version_supported("2.1.255 (Claude Code)"));
        assert!(claude_gateway_version_supported("2.1.263 (Claude Code)"));
        assert!(claude_gateway_version_supported("2.1.265 (Claude Code)"));
        assert!(!claude_gateway_version_supported("unknown"));
    }

    /// The pinned fixture is a tested baseline, not a ceiling: a newer client
    /// must reach the operation that needs a capability instead of being
    /// refused by number alone (issue #609).
    #[test]
    fn newer_claude_releases_are_not_rejected_by_version_alone() {
        for version in [
            "2.1.266 (Claude Code)",
            "2.1.283 (Claude Code)",
            "Claude Code v2.2.0",
            "3.0.0 (Claude Code)",
        ] {
            assert!(
                claude_gateway_version_supported(version),
                "{version} must not be rejected solely for being newer than the fixture"
            );
        }
    }
}

//! File primitives shared by the client integrations: safe reads, atomic
//! writes with timestamped backups, and the ownership markers that let
//! `remove` stay surgical.

use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::UNIX_EPOCH;

use serde_json::{Value, json};

use super::{ClientError, ClientKind, ClientManager, SetupResult};

pub(super) struct CodexMarker {
    pub(super) previous_provider: Option<String>,
    pub(super) managed_chatgpt_base_url: Option<String>,
    pub(super) previous_chatgpt_base_url: Option<String>,
    pub(super) managed_realtime_base_url: Option<String>,
    pub(super) previous_realtime_ws_base_url: Option<String>,
    pub(super) previous_realtime_call_base_url: Option<String>,
}

impl ClientManager {
    /// Store the client's shell exports without exposing the token on stdout.
    pub(crate) fn write_environment(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
    ) -> Result<PathBuf, ClientError> {
        let token_env = client
            .token_env()
            .ok_or_else(|| ClientError::message("client has no router token environment"))?;
        let directory = self.config_home.join("link-assistant-router/clients");
        fs::create_dir_all(&directory)?;
        let path = self.environment_path(client);
        let mut contents = String::new();
        if let Some(base_url_env) = client.base_url_env() {
            let endpoint = format!(
                "{}{}",
                base_url.trim_end_matches('/'),
                client.integration().endpoint_suffix
            );
            writeln!(
                &mut contents,
                "export {base_url_env}={}",
                super::util::shell_quote(&endpoint)
            )
            .expect("writing to a String cannot fail");
        }
        writeln!(
            &mut contents,
            "export {token_env}={}",
            super::util::shell_quote(token)
        )
        .expect("writing to a String cannot fail");
        if client == ClientKind::Codex {
            let alias = crate::token::codex_token_alias(token).ok_or_else(|| {
                ClientError::message(
                    "Codex control-plane setup requires a Router-issued la_sk_ token",
                )
            })?;
            writeln!(
                &mut contents,
                "export CODEX_ACCESS_TOKEN={}",
                super::util::shell_quote(&alias)
            )
            .expect("writing to a String cannot fail");
            writeln!(
                &mut contents,
                "export CODEX_CONNECTORS_TOKEN={}",
                super::util::shell_quote(&alias)
            )
            .expect("writing to a String cannot fail");
            writeln!(
                &mut contents,
                "export CODEX_AUTHAPI_BASE_URL={}",
                super::util::shell_quote(&format!(
                    "{}/api/services/codex",
                    base_url.trim_end_matches('/')
                ))
            )
            .expect("writing to a String cannot fail");
        }
        if client == ClientKind::ClaudeCode {
            writeln!(
                &mut contents,
                "export CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY=1"
            )
            .expect("writing to a String cannot fail");
        }
        atomic_write(&path, contents.as_bytes())?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            fs::set_permissions(&path, fs::Permissions::from_mode(0o600))?;
        }
        Ok(path)
    }
}

pub(super) type ClaudeEnvOwnership = Vec<(String, Option<String>, Option<String>)>;

pub(super) fn read_or_empty(path: &Path) -> Result<String, ClientError> {
    match fs::read_to_string(path) {
        Ok(source) => Ok(source),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(String::new()),
        Err(error) => Err(ClientError::message(format!(
            "could not read {}: {error}",
            path.display()
        ))),
    }
}

pub(super) fn read_environment_value(
    path: &Path,
    name: &str,
) -> Result<Option<String>, ClientError> {
    let source = read_or_empty(path)?;
    let prefix = format!("export {name}=");
    Ok(source.lines().find_map(|line| {
        let raw = line.strip_prefix(&prefix)?.trim();
        Some(
            raw.strip_prefix('\'')
                .and_then(|value| value.strip_suffix('\''))
                .unwrap_or(raw)
                .replace("'\\''", "'"),
        )
    }))
}

pub(super) fn write_if_changed(
    path: &Path,
    before: &str,
    after: &str,
) -> Result<SetupResult, ClientError> {
    if before == after {
        return Ok(unchanged(path.to_path_buf()));
    }
    let parent = path.parent().ok_or_else(|| {
        ClientError::message(format!("{} has no parent directory", path.display()))
    })?;
    fs::create_dir_all(parent)?;
    let backup = path.exists().then(|| backup_file(path)).transpose()?;
    atomic_write(path, after.as_bytes())?;
    Ok(SetupResult {
        path: path.to_path_buf(),
        backup,
        changed: true,
    })
}

pub(super) const fn unchanged(path: PathBuf) -> SetupResult {
    SetupResult {
        path,
        backup: None,
        changed: false,
    }
}

pub(super) fn backup_file(path: &Path) -> Result<PathBuf, ClientError> {
    let stamp = crate::operation_context::system_time()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| ClientError::message("config file name is not valid UTF-8"))?;
    // A frozen or low-resolution clock must not overwrite a prior safety copy.
    let nonce = uuid::Uuid::new_v4().simple();
    let backup = path.with_file_name(format!(
        "{file_name}.link-assistant-router.{stamp}.{nonce}.bak"
    ));
    // Client configs can contain vendor credentials. A process umask must not
    // decide whether the timestamped safety copy is world-readable.
    atomic_write(&backup, &fs::read(path)?)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        fs::set_permissions(&backup, fs::Permissions::from_mode(0o600))?;
    }
    Ok(backup)
}

pub(super) fn atomic_write(path: &Path, contents: &[u8]) -> Result<(), ClientError> {
    crate::durable_file::atomic_write_owner_only(path, contents).map_err(Into::into)
}

/// Record what the router wrote, and what it replaced.
///
/// `previous_anthropic_base_url` is what makes removal reversible. Without it
/// `clients remove claude` deleted the key rather than restoring it, so a user
/// already pointing Claude Code at a proxy of their own lost that setting
/// permanently — while the neighbouring Codex integration, which does record
/// its predecessor, put it back (issue #302).
pub(super) fn write_claude_marker(
    path: &Path,
    base_url: &str,
    previous: Option<&str>,
    gateway_env: &ClaudeEnvOwnership,
    user_model_keys: &[&str],
) -> Result<(), ClientError> {
    let gateway_env = gateway_env
        .iter()
        .map(|(key, managed, previous)| {
            (
                key.clone(),
                json!({"managed": managed, "previous": previous}),
            )
        })
        .collect::<serde_json::Map<_, _>>();
    let rendered = format!(
        "{}\n",
        serde_json::to_string_pretty(&json!({
            "anthropic_base_url": base_url,
            "previous_anthropic_base_url": previous,
            "gateway_env": gateway_env,
            "user_model_keys": user_model_keys,
        }))?
    );
    if read_or_empty(path)? != rendered {
        let parent = path
            .parent()
            .ok_or_else(|| ClientError::message("missing marker parent"))?;
        fs::create_dir_all(parent)?;
        atomic_write(path, rendered.as_bytes())?;
    }
    Ok(())
}

/// The URL the router wrote, and the one it replaced.
///
/// A marker written before issue #302 has no `previous_anthropic_base_url`,
/// which reads as `None` — the same answer as "there was nothing there", and
/// the same removal behaviour those markers already had.
pub(super) fn claude_marker(
    path: &Path,
) -> Result<Option<(String, Option<String>, ClaudeEnvOwnership)>, ClientError> {
    let source = read_or_empty(path)?;
    if source.trim().is_empty() {
        return Ok(None);
    }
    let marker: Value = serde_json::from_str(&source)?;
    let Some(managed) = marker
        .get("anthropic_base_url")
        .and_then(Value::as_str)
        .map(str::to_string)
    else {
        return Ok(None);
    };
    let previous = marker
        .get("previous_anthropic_base_url")
        .and_then(Value::as_str)
        .map(str::to_string);
    let gateway_env = marker
        .get("gateway_env")
        .and_then(Value::as_object)
        .into_iter()
        .flatten()
        .filter_map(|(key, ownership)| {
            let managed = match ownership.get("managed") {
                Some(Value::String(value)) => Some(value.clone()),
                Some(Value::Null) | None => None,
                _ => return None,
            };
            let previous = ownership
                .get("previous")
                .and_then(Value::as_str)
                .map(str::to_string);
            Some((key.clone(), managed, previous))
        })
        .collect();
    Ok(Some((managed, previous, gateway_env)))
}

/// Model overrides deliberately left under user ownership. Missing fields are
/// legacy markers; malformed or unknown keys must not hide a damaged marker.
pub(super) fn claude_user_model_keys(path: &Path) -> Result<Vec<String>, ClientError> {
    let source = read_or_empty(path)?;
    if source.trim().is_empty() {
        return Ok(Vec::new());
    }
    let marker: Value = serde_json::from_str(&source)?;
    let Some(keys) = marker.get("user_model_keys") else {
        return Ok(Vec::new());
    };
    let keys = keys
        .as_array()
        .ok_or_else(|| ClientError::message("invalid user model ownership"))?;
    let mut result = Vec::new();
    for key in keys {
        let key = key
            .as_str()
            .filter(|key| super::CLAUDE_MODEL_ENV.contains(key))
            .ok_or_else(|| ClientError::message("invalid user model ownership"))?;
        if result.iter().any(|existing| existing == key) {
            return Err(ClientError::message("duplicate user model ownership"));
        }
        result.push(key.to_string());
    }
    Ok(result)
}

pub(super) fn write_codex_marker(
    path: &Path,
    previous_provider: Option<&str>,
    managed_chatgpt_base_url: &str,
    previous_chatgpt_base_url: Option<&str>,
    managed_realtime_base_url: &str,
    previous_realtime_ws_base_url: Option<&str>,
    previous_realtime_call_base_url: Option<&str>,
) -> Result<(), ClientError> {
    let rendered = format!(
        "{}\n",
        serde_json::to_string_pretty(&json!({
            "previous_model_provider": previous_provider,
            "managed_chatgpt_base_url": managed_chatgpt_base_url,
            "previous_chatgpt_base_url": previous_chatgpt_base_url,
            "managed_realtime_base_url": managed_realtime_base_url,
            "previous_realtime_ws_base_url": previous_realtime_ws_base_url,
            "previous_realtime_call_base_url": previous_realtime_call_base_url
        }))?
    );
    let parent = path
        .parent()
        .ok_or_else(|| ClientError::message("missing marker parent"))?;
    fs::create_dir_all(parent)?;
    atomic_write(path, rendered.as_bytes())
}

pub(super) fn read_codex_marker(path: &Path) -> Result<CodexMarker, ClientError> {
    let source = read_or_empty(path)?;
    if source.trim().is_empty() {
        return Ok(CodexMarker {
            previous_provider: None,
            managed_chatgpt_base_url: None,
            previous_chatgpt_base_url: None,
            managed_realtime_base_url: None,
            previous_realtime_ws_base_url: None,
            previous_realtime_call_base_url: None,
        });
    }
    let marker: Value = serde_json::from_str(&source)?;
    Ok(CodexMarker {
        previous_provider: marker
            .get("previous_model_provider")
            .and_then(Value::as_str)
            .map(str::to_string),
        managed_chatgpt_base_url: marker
            .get("managed_chatgpt_base_url")
            .and_then(Value::as_str)
            .map(str::to_string),
        previous_chatgpt_base_url: marker
            .get("previous_chatgpt_base_url")
            .and_then(Value::as_str)
            .map(str::to_string),
        managed_realtime_base_url: marker
            .get("managed_realtime_base_url")
            .and_then(Value::as_str)
            .map(str::to_string),
        previous_realtime_ws_base_url: marker
            .get("previous_realtime_ws_base_url")
            .and_then(Value::as_str)
            .map(str::to_string),
        previous_realtime_call_base_url: marker
            .get("previous_realtime_call_base_url")
            .and_then(Value::as_str)
            .map(str::to_string),
    })
}

//! Merge-safe JSON configuration for OpenCode-shaped clients and Qwen Code.

use std::fs;
use std::path::Path;

use serde_json::{Value, json};

use super::{
    ClientError, ClientKind, ClientManager, OWNERSHIP_MARKER, ROUTER_PROVIDER, ROUTER_TOKEN_ENV,
    RouterModel, SetupResult, atomic_write, read_or_empty, unchanged, write_if_changed,
};

impl ClientManager {
    pub(super) fn setup_json_provider(
        &self,
        client: ClientKind,
        base_url: &str,
        models: &[RouterModel],
    ) -> Result<SetupResult, ClientError> {
        let path = self.config_path(client);
        let source = read_or_empty(&path)?;
        let mut document = parse_json_object(&path, &source)?;
        let marker = path
            .parent()
            .expect("client config always has a parent")
            .join(OWNERSHIP_MARKER);
        let marker_source = read_or_empty(&marker)?;
        let mut ownership = if marker_source.trim().is_empty() {
            None
        } else {
            Some(parse_json_object(&marker, &marker_source)?)
        };
        let previous_managed_ids = ownership
            .as_ref()
            .and_then(|marker| marker.get("managed_model_ids"))
            .and_then(Value::as_array)
            .map(|ids| ids.iter().filter_map(Value::as_str).collect::<Vec<_>>())
            .unwrap_or_default();
        let root = document
            .as_object_mut()
            .expect("parse_json_object always returns an object");
        let providers = root.entry("provider").or_insert_with(|| json!({}));
        let providers = providers.as_object_mut().ok_or_else(|| {
            ClientError::message(format!("{}.provider must be a JSON object", path.display()))
        })?;
        let previous = providers.get(ROUTER_PROVIDER).cloned();
        let managed =
            router_json_provider(base_url, models, previous.as_ref(), &previous_managed_ids)?;
        if providers.get(ROUTER_PROVIDER) == Some(&managed)
            && ownership
                .as_ref()
                .and_then(|marker| marker.get("managed_provider"))
                == Some(&managed)
        {
            return Ok(unchanged(path));
        }
        providers.insert(ROUTER_PROVIDER.into(), managed.clone());
        let rendered = render_json(&document)?;
        let result = write_if_changed(&path, &source, &rendered)?;
        let managed_model_ids = models
            .iter()
            .map(|model| Value::String(model.id.clone()))
            .collect::<Vec<_>>();
        if let Some(ownership) = ownership.as_mut() {
            let ownership = ownership
                .as_object_mut()
                .expect("parse_json_object always returns an object");
            ownership.insert("managed_provider".into(), managed);
            ownership.insert("managed_model_ids".into(), Value::Array(managed_model_ids));
            write_json_marker(&marker, &Value::Object(ownership.clone()))?;
        } else {
            write_json_marker(
                &marker,
                &json!({
                    "had_previous_provider": previous.is_some(),
                    "previous_provider": previous,
                    "managed_provider": managed,
                    "managed_model_ids": managed_model_ids
                }),
            )?;
        }
        Ok(result)
    }

    pub(super) fn setup_qwen(
        &self,
        base_url: &str,
        catalog: &[RouterModel],
    ) -> Result<SetupResult, ClientError> {
        let path = self.config_path(ClientKind::QwenCode);
        let source = read_or_empty(&path)?;
        let mut document = parse_json_object(&path, &source)?;
        let marker = self.qwen_home.join(OWNERSHIP_MARKER);
        let marker_source = read_or_empty(&marker)?;
        let mut ownership = if marker_source.trim().is_empty() {
            None
        } else {
            Some(parse_json_object(&marker, &marker_source)?)
        };
        let models = qwen_models_mut(&mut document, &path)?;
        if catalog.is_empty() {
            return Err(ClientError::message(
                "router catalog contains no models from healthy subscriptions",
            ));
        }
        let previous = ownership
            .as_ref()
            .and_then(|marker| marker.get("managed_models"))
            .and_then(Value::as_array)
            .cloned()
            .or_else(|| {
                ownership
                    .as_ref()
                    .and_then(|marker| marker.get("managed_model"))
                    .cloned()
                    .map(|model| vec![model])
            })
            .unwrap_or_default();
        let managed = catalog
            .iter()
            .map(|model| qwen_router_model(base_url, &model.id))
            .collect::<Vec<_>>();
        let current = models
            .iter()
            .filter(|model| qwen_model_is_managed(model) || previous.contains(model))
            .cloned()
            .collect::<Vec<_>>();
        if current == managed
            && ownership
                .as_ref()
                .and_then(|marker| marker.get("managed_models"))
                .and_then(Value::as_array)
                == Some(&managed)
        {
            return Ok(unchanged(path));
        }
        models.retain(|model| !qwen_model_is_managed(model) && !previous.contains(model));
        models.extend(managed.iter().cloned());
        let result = write_if_changed(&path, &source, &render_json(&document)?)?;
        if let Some(ownership) = ownership.as_mut() {
            let ownership = ownership
                .as_object_mut()
                .expect("parse_json_object always returns an object");
            ownership.remove("managed_model");
            ownership.insert("managed_models".into(), Value::Array(managed));
            write_json_marker(&marker, &Value::Object(ownership.clone()))?;
        } else {
            write_json_marker(&marker, &json!({"managed_models": managed}))?;
        }
        Ok(result)
    }

    pub(super) fn remove_json_provider(
        &self,
        client: ClientKind,
    ) -> Result<SetupResult, ClientError> {
        let path = self.config_path(client);
        let source = read_or_empty(&path)?;
        if source.trim().is_empty() {
            return Ok(unchanged(path));
        }
        let marker_path = path
            .parent()
            .expect("client config always has a parent")
            .join(OWNERSHIP_MARKER);
        let marker_source = read_or_empty(&marker_path)?;
        if marker_source.trim().is_empty() {
            return Ok(unchanged(path));
        }
        let marker: Value = serde_json::from_str(&marker_source)?;
        let managed = marker.get("managed_provider").ok_or_else(|| {
            ClientError::message(format!(
                "invalid ownership marker {}",
                marker_path.display()
            ))
        })?;
        let mut document = parse_json_object(&path, &source)?;
        let providers = document.get_mut("provider").and_then(Value::as_object_mut);
        let Some(providers) = providers else {
            fs::remove_file(marker_path)?;
            return Ok(unchanged(path));
        };
        if providers.get(ROUTER_PROVIDER) != Some(managed) {
            fs::remove_file(marker_path)?;
            return Ok(unchanged(path));
        }
        if marker
            .get("had_previous_provider")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            let previous = marker.get("previous_provider").cloned().ok_or_else(|| {
                ClientError::message(format!(
                    "invalid ownership marker {}",
                    marker_path.display()
                ))
            })?;
            providers.insert(ROUTER_PROVIDER.into(), previous);
        } else {
            providers.remove(ROUTER_PROVIDER);
        }
        let result = write_if_changed(&path, &source, &render_json(&document)?)?;
        fs::remove_file(marker_path)?;
        Ok(result)
    }

    pub(super) fn remove_qwen(&self) -> Result<SetupResult, ClientError> {
        let path = self.config_path(ClientKind::QwenCode);
        let source = read_or_empty(&path)?;
        if source.trim().is_empty() {
            return Ok(unchanged(path));
        }
        let marker_path = self.qwen_home.join(OWNERSHIP_MARKER);
        let marker_source = read_or_empty(&marker_path)?;
        if marker_source.trim().is_empty() {
            return Ok(unchanged(path));
        }
        let marker: Value = serde_json::from_str(&marker_source)?;
        let managed = marker
            .get("managed_models")
            .and_then(Value::as_array)
            .cloned()
            .or_else(|| {
                marker
                    .get("managed_model")
                    .cloned()
                    .map(|model| vec![model])
            })
            .ok_or_else(|| {
                ClientError::message(format!(
                    "invalid ownership marker {}",
                    marker_path.display()
                ))
            })?;
        let mut document = parse_json_object(&path, &source)?;
        let models = qwen_models_mut(&mut document, &path)?;
        let before = models.len();
        models.retain(|model| !managed.contains(model));
        if models.len() == before {
            fs::remove_file(marker_path)?;
            return Ok(unchanged(path));
        }
        let result = write_if_changed(&path, &source, &render_json(&document)?)?;
        fs::remove_file(marker_path)?;
        Ok(result)
    }
}

fn parse_json_object(path: &Path, source: &str) -> Result<Value, ClientError> {
    let document = if source.trim().is_empty() {
        json!({})
    } else {
        serde_json::from_str(source).map_err(|error| {
            ClientError::message(format!("invalid JSON in {}: {error}", path.display()))
        })?
    };
    if !document.is_object() {
        return Err(ClientError::message(format!(
            "{} must contain a JSON object",
            path.display()
        )));
    }
    Ok(document)
}

fn render_json(document: &Value) -> Result<String, ClientError> {
    Ok(format!("{}\n", serde_json::to_string_pretty(document)?))
}

fn router_json_provider(
    base_url: &str,
    catalog: &[RouterModel],
    existing: Option<&Value>,
    previous_managed_ids: &[&str],
) -> Result<Value, ClientError> {
    if catalog.is_empty() {
        return Err(ClientError::message(
            "router catalog contains no models from healthy subscriptions",
        ));
    }
    let mut provider = existing.cloned().unwrap_or_else(|| json!({}));
    let provider = provider
        .as_object_mut()
        .ok_or_else(|| ClientError::message("provider.link-assistant must be a JSON object"))?;
    provider.insert("npm".into(), json!("@ai-sdk/openai-compatible"));
    provider.insert("name".into(), json!("Link.Assistant.Router"));
    provider.insert(
        "options".into(),
        json!({
            "baseURL": base_url,
            "apiKey": format!("{{env:{ROUTER_TOKEN_ENV}}}")
        }),
    );
    let configured_models = provider.entry("models").or_insert_with(|| json!({}));
    let configured_models = configured_models.as_object_mut().ok_or_else(|| {
        ClientError::message("provider.link-assistant.models must be a JSON object")
    })?;
    for previous_id in previous_managed_ids {
        if !catalog.iter().any(|model| model.id == *previous_id) {
            configured_models.remove(*previous_id);
        }
    }
    for model in catalog {
        configured_models
            .entry(model.id.clone())
            .or_insert_with(|| json!({"name": format!("Router ({})", model.id)}));
    }
    Ok(Value::Object(provider.clone()))
}

fn qwen_router_model(base_url: &str, model: &str) -> Value {
    json!({
        "id": model,
        "name": "Link.Assistant.Router",
        "baseUrl": base_url,
        "envKey": ROUTER_TOKEN_ENV
    })
}

fn qwen_model_is_managed(model: &Value) -> bool {
    model.get("envKey").and_then(Value::as_str) == Some(ROUTER_TOKEN_ENV)
        && model
            .get("name")
            .and_then(Value::as_str)
            .is_some_and(|name| name.starts_with("Link.Assistant.Router"))
}

fn qwen_models_mut<'a>(
    document: &'a mut Value,
    path: &Path,
) -> Result<&'a mut Vec<Value>, ClientError> {
    let root = document
        .as_object_mut()
        .expect("parse_json_object always returns an object");
    let providers = root.entry("modelProviders").or_insert_with(|| json!({}));
    let providers = providers.as_object_mut().ok_or_else(|| {
        ClientError::message(format!(
            "{}.modelProviders must be a JSON object",
            path.display()
        ))
    })?;
    let openai = providers.entry("openai").or_insert_with(|| json!([]));
    if openai.is_array() {
        return Ok(openai
            .as_array_mut()
            .expect("array value checked immediately above"));
    }
    openai
        .as_object_mut()
        .and_then(|provider| provider.get_mut("models"))
        .and_then(Value::as_array_mut)
        .ok_or_else(|| {
            ClientError::message(format!(
                "{}.modelProviders.openai must be an array (or a legacy object with a models array)",
                path.display()
            ))
        })
}

fn write_json_marker(path: &Path, marker: &Value) -> Result<(), ClientError> {
    let parent = path
        .parent()
        .ok_or_else(|| ClientError::message("missing marker parent"))?;
    fs::create_dir_all(parent)?;
    atomic_write(path, render_json(marker)?.as_bytes())
}

pub(super) fn read_json_provider_base_url(path: &Path) -> Result<Option<String>, ClientError> {
    let source = read_or_empty(path)?;
    if source.trim().is_empty() {
        return Ok(None);
    }
    let document = parse_json_object(path, &source)?;
    let provider = document
        .get("provider")
        .and_then(|providers| providers.get(ROUTER_PROVIDER));
    let Some(provider) = provider else {
        return Ok(None);
    };
    let configured = provider.get("npm").and_then(Value::as_str)
        == Some("@ai-sdk/openai-compatible")
        && provider
            .get("options")
            .and_then(|options| options.get("apiKey"))
            .and_then(Value::as_str)
            == Some("{env:LINK_ASSISTANT_TOKEN}");
    Ok(configured
        .then(|| {
            provider
                .get("options")
                .and_then(|options| options.get("baseURL"))
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .flatten())
}

pub(super) fn read_qwen_base_url(path: &Path) -> Result<Option<String>, ClientError> {
    let source = read_or_empty(path)?;
    if source.trim().is_empty() {
        return Ok(None);
    }
    let mut document = parse_json_object(path, &source)?;
    let models = qwen_models_mut(&mut document, path)?;
    Ok(models.iter().find_map(|model| {
        qwen_model_is_managed(model)
            .then(|| {
                model
                    .get("baseUrl")
                    .and_then(Value::as_str)
                    .map(str::to_string)
            })
            .flatten()
    }))
}

//! Transactional, edit-aware client configuration repair.

use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};
use sha2::{Digest as _, Sha256};

use super::{
    ClientConfigAnalysis, ClientError, ClientKind, ClientManager, ManagedCredential,
    OwnershipState, RouterModel, SetupResult,
};

#[cfg(test)]
thread_local! {
    static FAIL_AFTER_WRITE: std::cell::Cell<Option<&'static str>> = const { std::cell::Cell::new(None) };
}

#[cfg(test)]
fn transaction_checkpoint(stage: &'static str) -> Result<(), ClientError> {
    if FAIL_AFTER_WRITE.get() == Some(stage) {
        return Err(ClientError::message(format!(
            "injected transaction failure after {stage}"
        )));
    }
    Ok(())
}

#[cfg(not(test))]
#[inline]
#[allow(clippy::unnecessary_wraps)]
const fn transaction_checkpoint(_stage: &'static str) -> Result<(), ClientError> {
    Ok(())
}

/// A secret-free repair preview. Constructing it performs no writes or I/O to
/// the selected Router.
#[derive(Clone, Debug, Serialize, schemars::JsonSchema)]
pub struct RepairPlan {
    pub client: ClientKind,
    pub state: OwnershipState,
    pub conflicts: Vec<String>,
    pub changes: Vec<PathBuf>,
    pub action: &'static str,
}

/// Result of a committed local repair transaction.
#[derive(Clone, Debug, Serialize, schemars::JsonSchema)]
pub struct RepairResult {
    pub client: ClientKind,
    pub before: OwnershipState,
    pub after: OwnershipState,
    pub changed: bool,
    pub restart_required: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub backup_id: Option<String>,
}

#[derive(Clone, Debug, Deserialize, Serialize, schemars::JsonSchema)]
struct SnapshotManifest {
    version: u8,
    id: String,
    client: String,
    entries: Vec<SnapshotEntry>,
}

#[derive(Clone, Debug, Deserialize, Serialize, schemars::JsonSchema)]
struct SnapshotEntry {
    path: PathBuf,
    existed: bool,
    #[serde(default)]
    mode: Option<u32>,
    #[serde(default)]
    before_sha256: Option<String>,
    #[serde(default)]
    after_sha256: Option<String>,
    #[serde(default)]
    backup: Option<String>,
}

impl ClientManager {
    /// Whether the complete managed configuration already targets this public
    /// router origin. This check intentionally does not read or return the
    /// credential value, so callers can avoid minting a replacement before
    /// deciding that an identical setup is a no-op.
    pub(crate) fn managed_target_matches(
        &self,
        client: ClientKind,
        base_url: &str,
    ) -> Result<bool, ClientError> {
        if self.analyze(client)?.state != OwnershipState::ManagedIntact {
            return Ok(false);
        }
        let Some(metadata) = self.credential_metadata(client)? else {
            return Ok(false);
        };
        let Some(recorded) = metadata.router else {
            return Ok(false);
        };
        let requested = crate::managed_server::canonical_server_origin(base_url)
            .map_err(|error| ClientError::message(error.to_string()))?;
        let recorded = crate::managed_server::canonical_server_origin(&recorded)
            .map_err(|error| ClientError::message(error.to_string()))?;
        let current_hash = config_digest(&self.config_path(client))?;
        Ok(requested == recorded && metadata.config_sha256.as_deref() == Some(&current_hash))
    }

    /// Describe the exact local files repair is allowed to reconcile.
    pub fn repair_plan(&self, client: ClientKind) -> Result<RepairPlan, ClientError> {
        let analysis = self.analyze(client)?;
        Ok(RepairPlan {
            client,
            state: analysis.state,
            conflicts: analysis.conflicts,
            changes: self.repair_paths(client),
            action: if analysis.state == OwnershipState::ManagedIntact {
                "none"
            } else if client.setup_limitation().is_some() {
                "unsupported"
            } else {
                "reconcile"
            },
        })
    }

    /// Reconcile all managed files as one recoverable transaction.
    #[allow(dead_code)]
    pub(crate) fn apply_repair(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
        credential: &ManagedCredential,
        models: &[RouterModel],
    ) -> Result<RepairResult, ClientError> {
        self.apply_repair_with_codex_backend(client, base_url, token, credential, models, None)
    }

    pub(crate) fn apply_repair_with_codex_backend(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
        credential: &ManagedCredential,
        models: &[RouterModel],
        codex_backend_base_url: Option<&str>,
    ) -> Result<RepairResult, ClientError> {
        crate::durable_file::with_exclusive_lock(&self.repair_lock_path(client), || {
            self.apply_repair_locked(
                client,
                base_url,
                token,
                credential,
                models,
                codex_backend_base_url,
            )
        })
    }

    /// Merge ordinary persistent setup as one transaction while preserving
    /// its permissive merge semantics and user-facing backup.
    #[allow(dead_code)]
    pub(crate) fn apply_setup_transaction(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
        credential: &ManagedCredential,
        models: &[RouterModel],
    ) -> Result<SetupResult, ClientError> {
        self.apply_setup_transaction_with_codex_backend(
            client, base_url, token, credential, models, None,
        )
    }

    pub(crate) fn apply_setup_transaction_with_codex_backend(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
        credential: &ManagedCredential,
        models: &[RouterModel],
        codex_backend_base_url: Option<&str>,
    ) -> Result<SetupResult, ClientError> {
        crate::durable_file::with_exclusive_lock(&self.repair_lock_path(client), || {
            let before = self.analyze(client)?;
            let snapshot = self.capture_snapshot(client, &before)?;
            let mut setup_backup = None;
            let result: Result<SetupResult, ClientError> = (|| {
                snapshot.verify_before()?;
                let setup = self.setup_with_codex_backend(
                    client,
                    base_url,
                    models,
                    codex_backend_base_url,
                )?;
                setup_backup.clone_from(&setup.backup);
                transaction_checkpoint("config")?;
                snapshot.verify_before_path(&self.environment_path(client))?;
                self.write_environment(client, base_url, token)?;
                transaction_checkpoint("environment")?;
                snapshot.verify_before_path(&self.credential_metadata_path(client))?;
                let mut credential = credential.clone();
                credential.config_sha256 = Some(config_digest(&self.config_path(client))?);
                self.write_credential_metadata(client, &credential)?;
                transaction_checkpoint("metadata")?;
                crate::client_global::update_post_configure_hash(
                    &self.config_path(client),
                    self.ownership_marker_path(client).as_deref(),
                )
                .map_err(|error| ClientError::message(error.to_string()))?;
                transaction_checkpoint("undo-state")?;
                Ok(setup)
            })();
            match result {
                Ok(setup) => {
                    if let Err(error) = fs::remove_dir_all(&snapshot.root) {
                        tracing::warn!(
                            path = %snapshot.root.display(),
                            %error,
                            "setup committed but its owner-only transaction snapshot remains"
                        );
                    }
                    Ok(setup)
                }
                Err(error) => {
                    let backup_error = setup_backup
                        .as_deref()
                        .map(remove_if_present)
                        .transpose()
                        .err();
                    let rollback_error = snapshot.restore(false).err();
                    let cleanup_error = fs::remove_dir_all(&snapshot.root).err();
                    let mut message = error.to_string();
                    if let Some(backup) = backup_error {
                        let _ = write!(message, "; setup-backup cleanup also failed: {backup}");
                    }
                    if let Some(rollback) = rollback_error {
                        let _ = write!(message, "; automatic rollback also failed: {rollback}");
                    }
                    if let Some(cleanup) = cleanup_error {
                        let _ = write!(message, "; snapshot cleanup also failed: {cleanup}");
                    }
                    Err(ClientError::message(message))
                }
            }
        })
    }

    /// Apply the reversible global client configuration and its credential
    /// files as one transaction. A failure after the public config write
    /// restores every prior byte and mode and removes the newly-created undo
    /// artifacts.
    #[allow(dead_code)]
    pub(crate) fn apply_configure_transaction(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
        credential: &ManagedCredential,
        models: &[RouterModel],
    ) -> Result<PathBuf, ClientError> {
        self.apply_configure_transaction_with_codex_backend(
            client, base_url, token, credential, models, None,
        )
    }

    pub(crate) fn apply_configure_transaction_with_codex_backend(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
        credential: &ManagedCredential,
        models: &[RouterModel],
        codex_backend_base_url: Option<&str>,
    ) -> Result<PathBuf, ClientError> {
        crate::durable_file::with_exclusive_lock(&self.repair_lock_path(client), || {
            let before = self.analyze(client)?;
            let snapshot = self.capture_snapshot(client, &before)?;
            let mut global_applied = false;
            let result: Result<PathBuf, ClientError> = (|| {
                snapshot.verify_before()?;
                let path = crate::client_global::apply_with_manager_and_codex_backend(
                    self,
                    client,
                    base_url,
                    models,
                    codex_backend_base_url,
                )
                .map_err(|error| ClientError::message(error.to_string()))?;
                global_applied = true;
                transaction_checkpoint("config")?;
                self.write_environment(client, base_url, token)?;
                transaction_checkpoint("environment")?;
                let mut credential = credential.clone();
                credential.config_sha256 = Some(config_digest(&self.config_path(client))?);
                self.write_credential_metadata(client, &credential)?;
                transaction_checkpoint("metadata")?;
                Ok(path)
            })();
            let path = match result {
                Ok(path) => path,
                Err(error) => {
                    let undo_error = global_applied
                        .then(|| crate::client_global::undo_with_manager(self, client))
                        .transpose()
                        .err();
                    let rollback_error = snapshot.restore(false).err();
                    let cleanup_error = fs::remove_dir_all(&snapshot.root).err();
                    let mut message = error.to_string();
                    if let Some(undo) = undo_error {
                        let _ = write!(message, "; global undo also failed: {undo}");
                    }
                    if let Some(rollback) = rollback_error {
                        let _ = write!(message, "; automatic rollback also failed: {rollback}");
                    }
                    if let Some(cleanup) = cleanup_error {
                        let _ = write!(message, "; snapshot cleanup also failed: {cleanup}");
                    }
                    return Err(ClientError::message(message));
                }
            };
            if let Err(error) = fs::remove_dir_all(&snapshot.root) {
                tracing::warn!(
                    path = %snapshot.root.display(),
                    %error,
                    "configuration committed but its owner-only transaction snapshot remains"
                );
            }
            Ok(path)
        })
    }

    fn apply_repair_locked(
        &self,
        client: ClientKind,
        base_url: &str,
        token: &str,
        credential: &ManagedCredential,
        models: &[RouterModel],
        codex_backend_base_url: Option<&str>,
    ) -> Result<RepairResult, ClientError> {
        let before = self.analyze(client)?;
        let same_credential = client.token_env().is_some_and(|key| {
            super::read_environment_value(&self.environment_path(client), key)
                .ok()
                .flatten()
                .as_deref()
                == Some(token)
        });
        let same_codex_backend = codex_backend_base_url.is_none_or(|expected| {
            client != ClientKind::Codex || self.codex_backend_matches(expected).unwrap_or(false)
        });
        if before.state == OwnershipState::ManagedIntact
            && self.managed_target_matches(client, base_url)?
            && same_credential
            && same_codex_backend
        {
            return Ok(RepairResult {
                client,
                before: before.state,
                after: before.state,
                changed: false,
                restart_required: false,
                backup_id: None,
            });
        }
        if let Some(limitation) = client.setup_limitation() {
            return Err(ClientError::message(limitation));
        }

        if client == ClientKind::Codex {
            self.validate_codex_catalog_constraint()?;
        }

        let mut snapshot = self.capture_snapshot(client, &before)?;
        let id = snapshot.manifest.id.clone();
        let result = (|| {
            // A corrupt marker cannot safely be interpreted by the surgical
            // setup writers. Its exact bytes are already in the snapshot.
            if before.state == OwnershipState::Ambiguous
                && before
                    .conflicts
                    .iter()
                    .any(|conflict| conflict == "ownership-marker:invalid")
                && let Some(path) = self.ownership_marker_path(client)
            {
                snapshot.verify_before_path(&path)?;
                remove_if_present(&path)?;
            }
            snapshot.verify_before_path(&self.config_path(client))?;
            if client == ClientKind::Codex {
                self.remove_codex_catalog_constraint()?;
            }
            if let Some(path) = self.ownership_marker_path(client)
                && !before
                    .conflicts
                    .iter()
                    .any(|conflict| conflict == "ownership-marker:invalid")
            {
                snapshot.verify_before_path(&path)?;
            }
            let setup =
                self.setup_with_codex_backend(client, base_url, models, codex_backend_base_url)?;
            if let Some(path) = setup.backup.as_deref() {
                remove_if_present(path)?;
            }
            transaction_checkpoint("config")?;
            snapshot.verify_before_path(&self.environment_path(client))?;
            self.write_environment(client, base_url, token)?;
            transaction_checkpoint("environment")?;
            snapshot.verify_before_path(&self.credential_metadata_path(client))?;
            let mut credential = credential.clone();
            credential.config_sha256 = Some(config_digest(&self.config_path(client))?);
            self.write_credential_metadata(client, &credential)?;
            transaction_checkpoint("metadata")?;
            snapshot.verify_before_path(&crate::client_global::undo_state_path(
                &self.config_path(client),
            ))?;
            crate::client_global::update_post_configure_hash(
                &self.config_path(client),
                self.ownership_marker_path(client).as_deref(),
            )
            .map_err(|error| ClientError::message(error.to_string()))?;
            transaction_checkpoint("undo-state")?;
            let after = self.analyze(client)?;
            if after.state != OwnershipState::ManagedIntact {
                return Err(ClientError::message(format!(
                    "repair did not produce an intact managed configuration; remaining conflicts: {}",
                    after.conflicts.join(", ")
                )));
            }
            snapshot.record_after()?;
            snapshot.write()?;
            Ok(RepairResult {
                client,
                before: before.state,
                after: after.state,
                changed: true,
                restart_required: client == ClientKind::ClaudeCode,
                backup_id: Some(id),
            })
        })();
        if let Err(error) = result {
            if let Err(rollback_error) = snapshot.restore(false) {
                return Err(ClientError::message(format!(
                    "{error}; automatic rollback also failed: {rollback_error}"
                )));
            }
            return Err(error);
        }
        result
    }

    /// Restore a named snapshot only if none of its repaired files changed.
    pub fn rollback_repair(
        &self,
        client: ClientKind,
        id: &str,
    ) -> Result<RepairResult, ClientError> {
        crate::durable_file::with_exclusive_lock(&self.repair_lock_path(client), || {
            self.rollback_repair_locked(client, id)
        })
    }

    fn rollback_repair_locked(
        &self,
        client: ClientKind,
        id: &str,
    ) -> Result<RepairResult, ClientError> {
        validate_id(id)?;
        let root = self.repair_root().join(id);
        let source = fs::read(root.join("manifest.json")).map_err(|error| {
            ClientError::message(format!("could not read repair snapshot {id}: {error}"))
        })?;
        let manifest: SnapshotManifest = serde_json::from_slice(&source)?;
        if manifest.id != id || manifest.client != client.canonical_name() {
            return Err(ClientError::message(
                "repair snapshot does not belong to the requested client",
            ));
        }
        let before = self.analyze(client)?.state;
        let snapshot = Snapshot { root, manifest };
        snapshot.restore(true)?;
        let after = self.analyze(client)?.state;
        Ok(RepairResult {
            client,
            before,
            after,
            changed: true,
            restart_required: client == ClientKind::ClaudeCode,
            backup_id: Some(id.to_string()),
        })
    }

    fn repair_root(&self) -> PathBuf {
        self.config_home.join("link-assistant-router/repairs")
    }

    fn repair_lock_path(&self, client: ClientKind) -> PathBuf {
        self.config_home
            .join("link-assistant-router/clients")
            .join(format!("{}.repair.lock", client.canonical_name()))
    }

    fn repair_paths(&self, client: ClientKind) -> Vec<PathBuf> {
        let mut paths = vec![
            self.config_path(client),
            self.environment_path(client),
            self.credential_metadata_path(client),
        ];
        if let Some(marker) = self.ownership_marker_path(client) {
            paths.push(marker);
        }
        paths.extend(crate::client_global::transaction_paths(
            &self.config_path(client),
        ));
        paths.sort();
        paths.dedup();
        paths
    }

    fn capture_snapshot(
        &self,
        client: ClientKind,
        analysis: &ClientConfigAnalysis,
    ) -> Result<Snapshot, ClientError> {
        // Refuse paths whose type could redirect the transaction outside its
        // fixed allow-list. The observation and capture hashes also make a
        // pre-analysis edit visible before any managed write occurs.
        for observed in &analysis.observed {
            if observed.exists && observed.kind != "file" {
                return Err(ClientError::message(format!(
                    "refusing to repair {} because it is a {}",
                    observed.path.display(),
                    observed.kind
                )));
            }
            let current = current_state(&observed.path)?;
            if current.0 != observed.exists || current.1 != observed.sha256 {
                return Err(ClientError::message(format!(
                    "{} changed after analysis; retry repair",
                    observed.path.display()
                )));
            }
        }
        let id = uuid::Uuid::new_v4().simple().to_string();
        let root = self.repair_root().join(&id);
        fs::create_dir_all(&root)?;
        set_mode(&root, 0o700)?;
        let mut entries = Vec::new();
        for (index, path) in self.repair_paths(client).into_iter().enumerate() {
            entries.push(capture_entry(&root, index, path)?);
        }
        let snapshot = Snapshot {
            root,
            manifest: SnapshotManifest {
                version: 1,
                id,
                client: client.canonical_name().to_string(),
                entries,
            },
        };
        snapshot.verify_before()?;
        snapshot.write()?;
        Ok(snapshot)
    }
}

struct Snapshot {
    root: PathBuf,
    manifest: SnapshotManifest,
}

impl Snapshot {
    fn write(&self) -> Result<(), ClientError> {
        let rendered = format!("{}\n", serde_json::to_string_pretty(&self.manifest)?);
        crate::durable_file::atomic_write_owner_only(
            &self.root.join("manifest.json"),
            rendered.as_bytes(),
        )?;
        set_mode(&self.root.join("manifest.json"), 0o600)
    }

    fn verify_before(&self) -> Result<(), ClientError> {
        for entry in &self.manifest.entries {
            let current = current_state(&entry.path)?;
            if current.0 != entry.existed || current.1 != entry.before_sha256 {
                return Err(ClientError::message(format!(
                    "{} changed while repair was being prepared; retry",
                    entry.path.display()
                )));
            }
        }
        Ok(())
    }

    fn verify_before_path(&self, path: &Path) -> Result<(), ClientError> {
        let entry = self
            .manifest
            .entries
            .iter()
            .find(|entry| entry.path == path)
            .ok_or_else(|| {
                ClientError::message("repair path is outside the captured allow-list")
            })?;
        let current = current_state(path)?;
        if current.0 != entry.existed || current.1 != entry.before_sha256 {
            return Err(ClientError::message(format!(
                "{} changed immediately before replacement; retry repair",
                path.display()
            )));
        }
        Ok(())
    }

    fn record_after(&mut self) -> Result<(), ClientError> {
        for entry in &mut self.manifest.entries {
            let current = current_state(&entry.path)?;
            entry.after_sha256 = current.1;
        }
        Ok(())
    }

    fn restore(&self, detect_conflicts: bool) -> Result<(), ClientError> {
        if detect_conflicts {
            for entry in &self.manifest.entries {
                let current = current_state(&entry.path)?;
                if current.0 != entry.after_sha256.is_some() || current.1 != entry.after_sha256 {
                    return Err(ClientError::message(format!(
                        "refusing rollback because {} changed after repair",
                        entry.path.display()
                    )));
                }
            }
        }
        for entry in self.manifest.entries.iter().rev() {
            if entry.existed {
                let backup = entry.backup.as_deref().ok_or_else(|| {
                    ClientError::message("repair snapshot is missing a backup name")
                })?;
                let bytes = fs::read(self.root.join(backup))?;
                crate::durable_file::atomic_write_owner_only(&entry.path, &bytes)?;
                set_optional_mode(&entry.path, entry.mode)?;
            } else {
                remove_if_present(&entry.path)?;
            }
        }
        Ok(())
    }
}

fn capture_entry(root: &Path, index: usize, path: PathBuf) -> Result<SnapshotEntry, ClientError> {
    let (exists, hash) = current_state(&path)?;
    let mode = file_mode(&path);
    let backup = if exists {
        let name = format!("{index}.backup");
        crate::durable_file::atomic_write_owner_only(&root.join(&name), &fs::read(&path)?)?;
        set_mode(&root.join(&name), 0o600)?;
        Some(name)
    } else {
        None
    };
    Ok(SnapshotEntry {
        path,
        existed: exists,
        mode,
        before_sha256: hash,
        after_sha256: None,
        backup,
    })
}

fn current_state(path: &Path) -> Result<(bool, Option<String>), ClientError> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if !metadata.file_type().is_symlink() && metadata.is_file() => {
            let bytes = fs::read(path)?;
            Ok((true, Some(hex::encode(Sha256::digest(bytes)))))
        }
        Ok(metadata) => Err(ClientError::message(format!(
            "refusing to access {} because it is {}",
            path.display(),
            if metadata.file_type().is_symlink() {
                "a symlink"
            } else {
                "not a regular file"
            }
        ))),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok((false, None)),
        Err(error) => Err(error.into()),
    }
}

fn config_digest(path: &Path) -> Result<String, ClientError> {
    match fs::read(path) {
        Ok(bytes) => Ok(hex::encode(Sha256::digest(bytes))),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            Ok(hex::encode(Sha256::digest([])))
        }
        Err(error) => Err(error.into()),
    }
}

fn validate_id(id: &str) -> Result<(), ClientError> {
    if id.is_empty()
        || !id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-')
    {
        return Err(ClientError::message("invalid repair backup id"));
    }
    Ok(())
}

fn remove_if_present(path: &Path) -> Result<(), ClientError> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error.into()),
    }
}

#[cfg(unix)]
fn file_mode(path: &Path) -> Option<u32> {
    use std::os::unix::fs::PermissionsExt as _;
    fs::metadata(path)
        .ok()
        .map(|metadata| metadata.permissions().mode() & 0o7777)
}

#[cfg(not(unix))]
fn file_mode(_path: &Path) -> Option<u32> {
    None
}

#[cfg(unix)]
fn set_mode(path: &Path, mode: u32) -> Result<(), ClientError> {
    use std::os::unix::fs::PermissionsExt as _;
    fs::set_permissions(path, fs::Permissions::from_mode(mode))?;
    Ok(())
}

#[cfg(not(unix))]
fn set_mode(_path: &Path, _mode: u32) -> Result<(), ClientError> {
    Ok(())
}

fn set_optional_mode(path: &Path, mode: Option<u32>) -> Result<(), ClientError> {
    if let Some(mode) = mode {
        set_mode(path, mode)?;
    }
    Ok(())
}

