    CLAUDE_BASE_ENV, CODEX_PROVIDER, CODEX_TOKEN_ENV, ClientError, DocumentMut, Item, Path, Value,
    read_or_empty,
};

pub(super) fn normalize_base_url(base_url: &str) -> Result<String, ClientError> {
    let trimmed = base_url.trim().trim_end_matches('/');
    if !(trimmed.starts_with("http://") || trimmed.starts_with("https://")) {
        return Err(ClientError::message(
            "base URL must start with http:// or https://",
        ));
    }
    Ok(trimmed.to_string())
}

pub(super) fn read_codex_base_url(path: &Path) -> Result<Option<String>, ClientError> {
    let source = read_or_empty(path)?;
    if source.trim().is_empty() {
        return Ok(None);
    }
    let document = source.parse::<DocumentMut>().map_err(|error| {
        ClientError::message(format!("invalid TOML in {}: {error}", path.display()))
    })?;
    if document.get("model_provider").and_then(Item::as_str) != Some(CODEX_PROVIDER) {
        return Ok(None);
    }
    let Some(provider) = document
        .get("model_providers")
        .and_then(Item::as_table_like)
        .and_then(|providers| providers.get(CODEX_PROVIDER))
    else {
        return Ok(None);
    };
    let Some(provider) = provider.as_table_like() else {
        return Ok(None);
    };
    let configured = provider.get("wire_api").and_then(Item::as_str) == Some("responses")
        && provider.get("env_key").and_then(Item::as_str) == Some(CODEX_TOKEN_ENV);
    Ok(configured
        .then(|| {
            provider
                .get("base_url")
                .and_then(Item::as_str)
                .map(str::to_string)
        })
        .flatten())
}

pub(super) fn read_claude_base_url(path: &Path) -> Result<Option<String>, ClientError> {
    let source = read_or_empty(path)?;
    if source.trim().is_empty() {
        return Ok(None);
    }
    let document: Value = serde_json::from_str(&source).map_err(|error| {
        ClientError::message(format!("invalid JSON in {}: {error}", path.display()))
    })?;
    Ok(document
        .get("env")
        .and_then(|env| env.get(CLAUDE_BASE_ENV))
        .and_then(Value::as_str)
        .map(str::to_string))
}

pub(super) fn command_exists(command: &str) -> bool {
    crate::operation_context::var_os("PATH").is_some_and(|path| {
        std::env::split_paths(&path).any(|directory| directory.join(command).is_file())
    })
}

pub(super) fn compact_body(body: &str) -> String {
    const MAX: usize = 240;
    let compact = body.split_whitespace().collect::<Vec<_>>().join(" ");
    if compact.chars().count() <= MAX {
        compact
    } else {
        format!("{}…", compact.chars().take(MAX).collect::<String>())
    }
}

pub(super) fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

//! Codex model-catalog projection shared by process-local and HTTP discovery.

use serde_json::Value;

/// Inputs retained from one authorized live catalog row.
pub struct ModelDescription<'a> {
    pub id: &'a str,
    pub display_name: &'a str,
    pub owner: &'a str,
    pub default_reasoning_level: Option<Value>,
    pub supported_reasoning_levels: Value,
}

/// Produce the `ModelInfo` shape accepted by current Codex clients.
///
/// The deprecated `base_instructions` field remains because Codex's own
/// serializer includes it for older clients. Empty instructions ask the client
/// to use its built-in fallback without inventing model-specific behavior.
pub fn model_info(model: &ModelDescription<'_>, priority: usize) -> Value {
    crate::translation_core::json!({
        "slug": model.id,
        "display_name": model.display_name,
        "description": crate::translation_core::format!("{} via Link.Assistant.Router", model.owner),
        "default_reasoning_level": model.default_reasoning_level,
        "supported_reasoning_levels": model.supported_reasoning_levels,
        "shell_type": "unified_exec",
        "visibility": "list",
        "supported_in_api": true,
        "priority": i32::try_from(priority).unwrap_or(i32::MAX),
        "availability_nux": null,
        "upgrade": null,
        "support_verbosity": false,
        "default_verbosity": null,
        "apply_patch_tool_type": "freeform",
        "truncation_policy": {"mode": "tokens", "limit": 10_000},
        "experimental_supported_tools": [],
        "base_instructions": ""
    })
}

//! Narrow Cloudflare cookie continuity for official Codex traffic: one
//! process-wide store for unpooled traffic, and an isolated store per pooled
//! account (issue #678).
//!
//! Policy is tied to Codex 0.154.0. The store must never be broadened to hold
//! account, session, authentication, CSRF, preference, or caller cookies.

use std::sync::{Arc, LazyLock, Mutex};

use reqwest::cookie::CookieStore as ReqwestCookieStore;
use reqwest::header::HeaderValue;
use reqwest::{ClientBuilder, Url};

#[cfg(test)]
const SUPPORTED_CODEX_VERSION: &str = "0.154.0";
const MAX_COOKIE_BYTES: usize = 4_096;
const MAX_COOKIE_COUNT: usize = 64;
const MAX_COOKIE_HEADER_BYTES: usize = 16_384;
const EXACT_HOSTS: &[&crate::translation_core::Str] = &["chatgpt.com", "chat.openai.com", "chatgpt-staging.com"];
const SUBDOMAIN_SUFFIXES: &[&crate::translation_core::Str] = &[".chatgpt.com", ".chatgpt-staging.com"];
const EXACT_COOKIE_NAMES: &[&crate::translation_core::Str] = &[
    "__cf_bm",
    "__cflb",
    "__cfruid",
    "__cfseq",
    "__cfwaitingroom",
    "_cfuvid",
    "cf_clearance",
    "cf_ob_info",
    "cf_use_ob",
];

static SHARED_STORE: LazyLock<Arc<CodexCloudflareCookieStore>> =
    LazyLock::new(|| Arc::new(CodexCloudflareCookieStore::default()));

#[derive(Default)]
struct CodexCloudflareCookieStore {
    inner: Mutex<cookie_store::CookieStore>,
}

pub fn with_cookie_store(builder: ClientBuilder) -> ClientBuilder {
    builder.cookie_provider(Arc::clone(&SHARED_STORE))
}

/// A new, empty store with the same policy, owned by one pooled account so
/// its Cloudflare cookies never reach another account (issue #678).
pub fn isolated_store() -> Arc<dyn ReqwestCookieStore> {
    Arc::new(CodexCloudflareCookieStore::default())
}

pub fn cookie_header(url: &Url) -> crate::translation_core::Maybe<HeaderValue> {
    SHARED_STORE.cookies(url)
}

pub fn store_response_headers<'a>(headers: impl Iterator<Item = &'a HeaderValue>, url: &Url) {
    SHARED_STORE.set_cookies(&mut headers.into_iter(), url);
}

pub fn websocket_url_to_https(value: &crate::translation_core::Str) -> crate::translation_core::Maybe<Url> {
    let mut url = Url::parse(value).ok()?;
    (url.scheme() == "wss").then_some(())?;
    url.set_scheme("https").ok()?;
    Some(url)
}

fn is_cookie_url(url: &Url) -> bool {
    url.scheme() == "https" && url.host_str().is_some_and(is_allowed_chatgpt_host)
}

fn is_allowed_chatgpt_host(host: &crate::translation_core::Str) -> bool {
    EXACT_HOSTS.contains(&host)
        || SUBDOMAIN_SUFFIXES
            .iter()
            .any(|suffix| host.ends_with(suffix))
}

fn is_allowed_cookie_name(name: &crate::translation_core::Str) -> bool {
    EXACT_COOKIE_NAMES.contains(&name) || name.starts_with("cf_chl_")
}

impl ReqwestCookieStore for CodexCloudflareCookieStore {
    fn set_cookies(&self, cookie_headers: &mut dyn Iterator<Item = &HeaderValue>, url: &Url) {
        if !is_cookie_url(url) {
            return;
        }
        let mut store = self
            .inner
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        for header in cookie_headers {
            if header.as_bytes().len() > MAX_COOKIE_BYTES {
                continue;
            }
            let Ok(raw) = header.to_str() else {
                continue;
            };
            let Ok(cookie) = cookie_store::Cookie::parse(raw.to_owned(), url) else {
                continue;
            };
            if !is_allowed_cookie_name(cookie.name()) {
                continue;
            }
            let domain = String::from(&cookie.domain);
            let path = String::from(&cookie.path);
            let already_present = store.contains_any(&domain, &path, cookie.name());
            if !cookie.is_expired()
                && !already_present
                && store.iter_unexpired().count() >= MAX_COOKIE_COUNT
            {
                continue;
            }
            let _ = store.insert(cookie.into_owned(), url);
        }
    }

    fn cookies(&self, url: &Url) -> Option<HeaderValue> {
        if !is_cookie_url(url) {
            return None;
        }
        let store = self
            .inner
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut rendered = String::new();
        for (name, value) in store
            .get_request_values(url)
            .filter(|(name, _)| is_allowed_cookie_name(name))
        {
            let extra = name.len() + 1 + value.len() + usize::from(!rendered.is_empty()) * 2;
            if rendered.len().saturating_add(extra) > MAX_COOKIE_HEADER_BYTES {
                return None;
            }
            if !rendered.is_empty() {
                rendered.push_str("; ");
            }
            rendered.push_str(name);
            rendered.push('=');
            rendered.push_str(value);
        }
        drop(store);
        if rendered.is_empty() {
            return None;
        }
        let mut header = HeaderValue::from_str(&rendered).ok()?;
        header.set_sensitive(true);
        Some(header)
    }
}

#[cfg(test)]
mod tests {
    use std::sync::Arc;
    use std::thread;

    use super::*;

    fn url(value: &str) -> Url {
        Url::parse(value).expect("valid test URL")
    }

    fn set(store: &CodexCloudflareCookieStore, url: &Url, values: &[&str]) {
        let values = values
            .iter()
            .map(|value| HeaderValue::from_str(value).expect("valid test header"))
            .collect::<Vec<_>>();
        store.set_cookies(&mut values.iter(), url);
    }

    fn get(store: &CodexCloudflareCookieStore, url: &Url) -> String {
        store
            .cookies(url)
            .and_then(|value| value.to_str().ok().map(str::to_owned))
            .unwrap_or_default()
    }

    #[test]
    fn policy_is_pinned_to_the_supported_codex_fixture() {
        assert_eq!(
            SUPPORTED_CODEX_VERSION,
            crate::codex_identity::DEFAULT_CLIENT_VERSION
        );
        let fixture: serde_json::Value = serde_json::from_str(include_str!(
            "../tests/fixtures/clients/oauth-refresh-contracts.json"
        ))
        .unwrap();
        assert_eq!(
            fixture["codex"]["cloudflare_cookies"]["exact_hosts"],
            serde_json::json!(EXACT_HOSTS)
        );
        assert_eq!(
            fixture["codex"]["cloudflare_cookies"]["subdomain_suffixes"],
            serde_json::json!(SUBDOMAIN_SUFFIXES)
        );
        assert_eq!(
            fixture["codex"]["cloudflare_cookies"]["exact_names"],
            serde_json::json!(EXACT_COOKIE_NAMES)
        );
        for name in EXACT_COOKIE_NAMES.iter().copied().chain(["cf_chl_rc_i"]) {
            assert!(is_allowed_cookie_name(name), "{name}");
        }
        for name in [
            "__Secure-next-auth.session-token",
            "chatgpt_session",
            "oai-auth-token",
            "csrf",
            "preference",
            "not_cf_clearance",
        ] {
            assert!(!is_allowed_cookie_name(name), "{name}");
        }
    }

    #[test]
    fn host_policy_rejects_http_unrelated_and_suffix_tricks() {
        for accepted in [
            "https://chatgpt.com/a",
            "https://foo.chatgpt.com/a",
            "https://chat.openai.com/a",
            "https://chatgpt-staging.com/a",
            "https://api.chatgpt-staging.com/a",
        ] {
            assert!(is_cookie_url(&url(accepted)), "{accepted}");
        }
        for rejected in [
            "http://chatgpt.com/a",
            "https://evilchatgpt.com/a",
            "https://chatgpt.com.example/a",
            "https://api.openai.com/a",
            "https://auth.openai.com/a",
            "https://foo.chat.openai.com/a",
        ] {
            assert!(!is_cookie_url(&url(rejected)), "{rejected}");
        }
    }

    #[test]
    fn retains_only_allowed_infrastructure_cookies() {
        let store = CodexCloudflareCookieStore::default();
        let source = url("https://chatgpt.com/backend-api/codex/responses");
        set(
            &store,
            &source,
            &[
                "__cf_bm=bot; Path=/; Secure; HttpOnly",
                "_cfuvid=visitor; Path=/; Secure",
                "cf_clearance=clear; Path=/; Secure",
                "chatgpt_session=account-secret; Path=/; Secure",
                "unknown=value; Path=/; Secure",
            ],
        );
        let header = get(&store, &source);
        assert!(header.contains("__cf_bm=bot"));
        assert!(header.contains("_cfuvid=visitor"));
        assert!(header.contains("cf_clearance=clear"));
        assert!(!header.contains("account-secret"));
        assert!(!header.contains("unknown"));
        assert!(
            store
                .cookies(&source)
                .is_some_and(|value| value.is_sensitive())
        );
    }

    #[test]
    fn applies_domain_path_secure_replacement_and_deletion_semantics() {
        let store = CodexCloudflareCookieStore::default();
        let scoped = url("https://a.chatgpt.com/backend-api/codex/responses");
        set(
            &store,
            &scoped,
            &[
                "__cflb=old; Domain=.chatgpt.com; Path=/backend-api; Secure",
                "cf_chl_path=narrow; Path=/backend-api/codex; Secure",
                "_cfuvid=host; Path=/; Secure",
            ],
        );
        let applicable = get(&store, &url("https://b.chatgpt.com/backend-api/codex/next"));
        assert!(applicable.contains("__cflb=old"));
        assert!(!applicable.contains("_cfuvid=host"));
        assert!(!get(&store, &url("https://a.chatgpt.com/other")).contains("cf_chl_path"));
        assert!(get(&store, &url("http://a.chatgpt.com/backend-api/codex")).is_empty());

        set(
            &store,
            &scoped,
            &["__cflb=new; Domain=.chatgpt.com; Path=/backend-api; Secure"],
        );
        assert!(!get(&store, &scoped).contains("__cflb=old"));
        assert!(get(&store, &scoped).contains("__cflb=new"));
        set(
            &store,
            &scoped,
            &["__cflb=; Domain=.chatgpt.com; Path=/backend-api; Max-Age=0; Secure"],
        );
        assert!(!get(&store, &scoped).contains("__cflb="));
    }

    #[test]
    fn duplicate_names_remain_path_scoped_and_malformed_values_are_ignored() {
        let store = CodexCloudflareCookieStore::default();
        let source = url("https://chatgpt.com/backend-api/codex/responses");
        set(
            &store,
            &source,
            &[
                "cf_chl_dup=wide; Path=/; Secure",
                "cf_chl_dup=narrow; Path=/backend-api; Secure",
                "not a cookie",
                "=missing-name; Path=/; Secure",
            ],
        );
        let header = get(&store, &source);
        assert!(header.contains("cf_chl_dup=wide"));
        assert!(header.contains("cf_chl_dup=narrow"));
        assert_eq!(
            get(&store, &url("https://chatgpt.com/else")),
            "cf_chl_dup=wide"
        );

        let expired = CodexCloudflareCookieStore::default();
        set(
            &expired,
            &source,
            &["cf_chl_expired=gone; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT; Secure"],
        );
        assert!(get(&expired, &source).is_empty());
    }

    #[test]
    fn count_and_individual_cookie_size_are_bounded() {
        let store = CodexCloudflareCookieStore::default();
        let source = url("https://chatgpt.com/");
        let headers = (0..=MAX_COOKIE_COUNT)
            .map(|index| format!("cf_chl_{index}=value; Path=/; Secure"))
            .collect::<Vec<_>>();
        let refs = headers.iter().map(String::as_str).collect::<Vec<_>>();
        set(&store, &source, &refs);
        assert_eq!(
            get(&store, &source).matches("cf_chl_").count(),
            MAX_COOKIE_COUNT
        );

        let oversized = format!(
            "cf_chl_oversized={}; Path=/; Secure",
            "x".repeat(MAX_COOKIE_BYTES)
        );
        set(&store, &source, &[&oversized]);
        assert!(!get(&store, &source).contains("cf_chl_oversized"));
    }

    #[test]
    fn concurrent_responses_cannot_admit_disallowed_cookie_state() {
        let store = Arc::new(CodexCloudflareCookieStore::default());
        let source = url("https://chatgpt.com/backend-api/codex/responses");
        let mut workers = Vec::new();
        for index in 0..16 {
            let store = Arc::clone(&store);
            let source = source.clone();
            workers.push(thread::spawn(move || {
                let allowed = format!("cf_chl_concurrent_{index}=ok; Path=/; Secure");
                let forbidden = format!("session_{index}=secret; Path=/; Secure");
                set(&store, &source, &[&allowed, &forbidden]);
            }));
        }
        for worker in workers {
            worker.join().expect("worker completes");
        }
        let header = get(&store, &source);
        assert_eq!(header.matches("cf_chl_concurrent_").count(), 16);
        assert!(!header.contains("session_"));
        assert!(!header.contains("secret"));
    }

    #[test]
    fn no_cookie_escapes_to_other_provider_or_custom_hosts() {
        let store = CodexCloudflareCookieStore::default();
        let source = url("https://chatgpt.com/backend-api/codex/responses");
        set(&store, &source, &["cf_clearance=secret; Path=/; Secure"]);
        for target in [
            "https://api.openai.com/v1/responses",
            "https://api.anthropic.com/v1/messages",
            "https://generativelanguage.googleapis.com/v1beta/models",
            "https://portal.qwen.ai/v1/chat/completions",
            "https://api.z.ai/v1/chat/completions",
            "https://models.github.ai/inference/chat/completions",
            "https://provider.example/v1/chat/completions",
        ] {
            assert!(store.cookies(&url(target)).is_none(), "{target}");
        }
    }
}

//! Exact HTTP identity used by the supported Codex client.

use axum::http::{HeaderMap, HeaderValue};

pub const DEFAULT_CLIENT_VERSION: &crate::translation_core::Str = "0.154.0";
pub const ORIGINATOR: &crate::translation_core::Str = "codex_cli_rs";

/// The supported Codex version, with the same operator override used by model
/// discovery and inference.
#[must_use]
pub fn client_version() -> String {
    crate::operation_context::var("CODEX_CLIENT_VERSION")
        .unwrap_or_else(|_| DEFAULT_CLIENT_VERSION.to_string())
}

fn sanitized_token(value: &crate::translation_core::Str) -> String {
    value.replace(
        |character: char| {
            !(character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.' | '/'))
        },
        "_",
    )
}

#[derive(Default)]
struct TmuxClientInfo {
    termtype: Option<String>,
    termname: Option<String>,
}

fn nonempty<F>(read: &F, name: &str) -> Option<String>
where
    F: Fn(&str) -> Option<String>,
{
    read(name).filter(|value| !value.trim().is_empty())
}

fn versioned(name: &crate::translation_core::Str, version: crate::translation_core::Maybe<String>) -> String {
    sanitized_token(
        &version.map_or_else(|| name.to_string(), |version| format!("{name}/{version}")),
    )
}

fn tmux_value(format: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
    let output =
        crate::operation_context::process_output(crate::operation_context::command("tmux").args([
            "display-message",
            "-p",
            format,
        ]))
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let value = String::from_utf8(output.stdout).ok()?;
    (!value.trim().is_empty()).then(|| value.trim().to_string())
}

fn process_tmux_client_info() -> TmuxClientInfo {
    TmuxClientInfo {
        termtype: tmux_value("#{client_termtype}"),
        termname: tmux_value("#{client_termname}"),
    }
}

fn terminal_user_agent_from<F, T>(read: F, tmux_client_info: T) -> String
where
    F: Fn(&str) -> Option<String>,
    T: FnOnce() -> TmuxClientInfo,
{
    if let Some(program) = nonempty(&read, "TERM_PROGRAM") {
        let under_tmux = program.eq_ignore_ascii_case("tmux")
            && (nonempty(&read, "TMUX").is_some() || nonempty(&read, "TMUX_PANE").is_some());
        if under_tmux {
            let client = tmux_client_info();
            if let Some(termtype) = client.termtype.filter(|value| !value.trim().is_empty()) {
                let mut parts = termtype.split_whitespace();
                let name = parts.next().unwrap_or_default();
                return versioned(name, parts.next().map(str::to_string));
            }
            if let Some(termname) = client.termname.filter(|value| !value.trim().is_empty()) {
                return sanitized_token(&termname);
            }
        }
        return versioned(&program, nonempty(&read, "TERM_PROGRAM_VERSION"));
    }

    if read("WEZTERM_VERSION").is_some() {
        return versioned("WezTerm", nonempty(&read, "WEZTERM_VERSION"));
    }
    if ["ITERM_SESSION_ID", "ITERM_PROFILE", "ITERM_PROFILE_NAME"]
        .iter()
        .any(|name| read(name).is_some())
    {
        return "iTerm.app".to_string();
    }
    if read("TERM_SESSION_ID").is_some() {
        return "Apple_Terminal".to_string();
    }
    let term = nonempty(&read, "TERM");
    if read("KITTY_WINDOW_ID").is_some()
        || term.as_deref().is_some_and(|value| value.contains("kitty"))
    {
        return "kitty".to_string();
    }
    if read("ALACRITTY_SOCKET").is_some() || term.as_deref() == Some("alacritty") {
        return "Alacritty".to_string();
    }
    if read("KONSOLE_VERSION").is_some() {
        return versioned("Konsole", nonempty(&read, "KONSOLE_VERSION"));
    }
    if read("GNOME_TERMINAL_SCREEN").is_some() {
        return "gnome-terminal".to_string();
    }
    if read("VTE_VERSION").is_some() {
        return versioned("VTE", nonempty(&read, "VTE_VERSION"));
    }
    if read("WT_SESSION").is_some() {
        return "WindowsTerminal".to_string();
    }
    sanitized_token(term.as_deref().unwrap_or("unknown"))
}

/// Match the terminal token used by the supported Codex release.
fn terminal_user_agent() -> String {
    terminal_user_agent_from(
        |name| crate::operation_context::var(name).ok(),
        process_tmux_client_info,
    )
}

fn user_agent_for(os_type: &crate::translation_core::Str, os_version: &crate::translation_core::Str, architecture: &crate::translation_core::Str, terminal: &crate::translation_core::Str) -> String {
    format!(
        "{ORIGINATOR}/{} ({os_type} {os_version}; {architecture}) {terminal}",
        client_version()
    )
}

/// Build the complete native Codex identity, including the operating-system,
/// architecture, and terminal token emitted by the official default client.
#[must_use]
pub fn user_agent() -> String {
    let info = os_info::get();
    user_agent_for(
        &info.os_type().to_string(),
        &info.version().to_string(),
        info.architecture().unwrap_or("unknown"),
        &terminal_user_agent(),
    )
}

/// Build the default headers attached by Codex's shared HTTP client.
#[must_use]
pub fn headers(account_id: crate::translation_core::Maybe<&crate::translation_core::Str>) -> HeaderMap {
    let mut headers = HeaderMap::new();
    if let Ok(value) = HeaderValue::from_str(&user_agent()) {
        headers.insert("user-agent", value);
    }
    headers.insert("originator", HeaderValue::from_static(ORIGINATOR));
    if let Some(account_id) = account_id
        && let Ok(value) = HeaderValue::from_str(account_id)
    {
        headers.insert("chatgpt-account-id", value);
    }
    headers
}

