//! Loopback transport accepted by Codex's remote-control origin policy.

use std::collections::HashSet;
use std::io::Read as _;
use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::time::Duration;

use axum::body::{Body, Bytes};
use axum::extract::ws::{CloseFrame, Message, WebSocket, WebSocketUpgrade};
use axum::extract::{FromRequestParts as _, Request, State};
use axum::http::{HeaderMap, HeaderName, Method, StatusCode};
use axum::response::{IntoResponse as _, Response};
use futures_util::{SinkExt as _, StreamExt as _};
use tokio::sync::oneshot;
use tokio_tungstenite::tungstenite;
use tokio_tungstenite::tungstenite::client::IntoClientRequest as _;

const BACKEND_PATH: &str = "/api/services/codex/backend-api";
const MAX_HTTP_BODY_BYTES: usize = 8 * 1024 * 1024;
const MAX_WEBSOCKET_MESSAGE_BYTES: usize = 16 * 1024 * 1024;
const CONNECT_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(15);
const STATE_VERSION: u8 = 1;
const HEALTH_HEADER: &str = "x-link-assistant-router-codex-bridge";
const DAEMON_MARKER_ENV: &str = "LINK_ASSISTANT_ROUTER_INTERNAL_CODEX_BRIDGE";
const DAEMON_UPSTREAM_ENV: &str = "LINK_ASSISTANT_ROUTER_INTERNAL_CODEX_BRIDGE_UPSTREAM";
const DAEMON_STATE_ENV: &str = "LINK_ASSISTANT_ROUTER_INTERNAL_CODEX_BRIDGE_STATE";
const DAEMON_NONCE_ENV: &str = "LINK_ASSISTANT_ROUTER_INTERNAL_CODEX_BRIDGE_NONCE";
const DAEMON_LISTEN_ENV: &str = "LINK_ASSISTANT_ROUTER_INTERNAL_CODEX_BRIDGE_LISTEN";
const START_TIMEOUT: Duration = Duration::from_secs(5);
const STOP_TIMEOUT: Duration = Duration::from_secs(3);
const POLL_INTERVAL: Duration = Duration::from_millis(25);
#[cfg(any(windows, test))]
const WINDOWS_RUNTIME_ENV: [&str; 4] = ["SystemRoot", "WINDIR", "TEMP", "TMP"];

#[derive(Clone)]
struct BridgeState {
    upstream_origin: String,
    health_path: String,
    client: reqwest::Client,
}

pub struct EphemeralBridge {
    backend_base_url: String,
    #[cfg(test)]
    health_url: String,
    shutdown: Option<oneshot::Sender<()>>,
    task: tokio::task::JoinHandle<()>,
}

#[derive(Clone, Debug, Eq, PartialEq, serde::Deserialize, serde::Serialize)]
struct PersistentState {
    version: u8,
    pid: u32,
    upstream_origin: String,
    loopback_origin: String,
    nonce: String,
}

pub struct PersistentBridge {
    backend_base_url: String,
    state_path: PathBuf,
    state: PersistentState,
    started: bool,
    _lock: crate::durable_file::FileLockGuard,
}

impl PersistentBridge {
    #[must_use]
    pub fn backend_base_url(&self) -> &str {
        &self.backend_base_url
    }

    pub fn commit(mut self) {
        self.started = false;
    }

    pub async fn rollback(mut self) -> Result<(), String> {
        if self.started {
            stop_state(&self.state_path, &self.state).await?;
            self.started = false;
        }
        Ok(())
    }
}

impl Drop for PersistentBridge {
    fn drop(&mut self) {
        if self.started {
            let _ = signal_terminate(self.state.pid);
        }
    }
}

pub struct DaemonRequest {
    upstream_origin: String,
    state_path: PathBuf,
    nonce: String,
    listen: std::net::SocketAddr,
}

impl EphemeralBridge {
    #[must_use]
    pub fn backend_base_url(&self) -> &str {
        &self.backend_base_url
    }

    #[cfg(test)]
    #[must_use]
    pub fn health_url(&self) -> &str {
        &self.health_url
    }
}

impl Drop for EphemeralBridge {
    fn drop(&mut self) {
        if let Some(shutdown) = self.shutdown.take() {
            let _ = shutdown.send(());
        }
        self.task.abort();
    }
}

pub fn required(router_origin: &str) -> Result<bool, String> {
    let url = reqwest::Url::parse(router_origin)
        .map_err(|error| format!("invalid Router URL: {error}"))?;
    if !matches!(url.scheme(), "http" | "https") || url.host_str().is_none() {
        return Err("Router URL must be an HTTP or HTTPS origin".into());
    }
    let loopback = match url.host() {
        Some(url::Host::Domain(host)) => host.eq_ignore_ascii_case("localhost"),
        Some(url::Host::Ipv4(address)) => address.is_loopback(),
        Some(url::Host::Ipv6(address)) => address.is_loopback(),
        None => false,
    };
    Ok(!loopback)
}

pub async fn start_ephemeral(upstream_origin: &str) -> Result<EphemeralBridge, String> {
    let upstream_origin = canonical_origin(upstream_origin)?;
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .map_err(|error| format!("could not bind the Codex loopback bridge: {error}"))?;
    let address = listener
        .local_addr()
        .map_err(|error| format!("could not read the Codex loopback bridge address: {error}"))?;
    let nonce = uuid::Uuid::new_v4().simple().to_string();
    let health_path = format!("/__link_assistant_router/codex_bridge/{nonce}");
    #[cfg(test)]
    let health_url = format!("http://{address}{health_path}");
    let state = BridgeState {
        upstream_origin,
        health_path,
        client: reqwest::Client::new(),
    };
    let app = axum::Router::new()
        .fallback(bridge_request)
        .with_state(state);
    let (shutdown, receiver) = oneshot::channel();
    let task = tokio::spawn(async move {
        let _ = axum::serve(listener, app)
            .with_graceful_shutdown(async move {
                let _ = receiver.await;
            })
            .await;
    });
    let origin = format!("http://{address}");
    Ok(EphemeralBridge {
        backend_base_url: format!("{origin}{BACKEND_PATH}"),
        #[cfg(test)]
        health_url,
        shutdown: Some(shutdown),
        task,
    })
}

/// Recognize only the complete environment passed to an owned bridge child.
pub fn daemon_request_from_env() -> Result<Option<DaemonRequest>, String> {
    if crate::operation_context::var_os(DAEMON_MARKER_ENV).is_none() {
        return Ok(None);
    }
    let upstream_origin = required_daemon_env(DAEMON_UPSTREAM_ENV)?;
    let state_path = PathBuf::from(required_daemon_env(DAEMON_STATE_ENV)?);
    if !state_path.is_absolute() {
        return Err("Codex bridge state path must be absolute".into());
    }
    let nonce = required_daemon_env(DAEMON_NONCE_ENV)?;
    validate_nonce(&nonce)?;
    let listen = required_daemon_env(DAEMON_LISTEN_ENV)?
        .parse::<std::net::SocketAddr>()
        .map_err(|_| "Codex bridge listen address is invalid")?;
    if listen.ip() != std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST) {
        return Err("Codex bridge must listen on 127.0.0.1".into());
    }
    Ok(Some(DaemonRequest {
        upstream_origin,
        state_path,
        nonce,
        listen,
    }))
}

fn required_daemon_env(name: &str) -> Result<String, String> {
    crate::operation_context::var(name)
        .ok()
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "incomplete Codex bridge startup request".to_string())
}

fn validate_nonce(nonce: &str) -> Result<(), String> {
    if nonce.len() == 32 && nonce.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        Ok(())
    } else {
        Err("Codex bridge ownership nonce is invalid".into())
    }
}

/// Serve one persistent child process created by [`ensure_persistent`].
pub async fn run_persistent_daemon(request: DaemonRequest) -> Result<(), String> {
    let upstream_origin = canonical_origin(&request.upstream_origin)?;
    let listener = tokio::net::TcpListener::bind(request.listen)
        .await
        .map_err(|error| format!("could not bind the persistent Codex bridge: {error}"))?;
    let address = listener
        .local_addr()
        .map_err(|error| format!("could not read the persistent Codex bridge address: {error}"))?;
    let loopback_origin = format!("http://{address}");
    let health_path = health_path(&request.nonce);
    let state = PersistentState {
        version: STATE_VERSION,
        pid: std::process::id(),
        upstream_origin: upstream_origin.clone(),
        loopback_origin,
        nonce: request.nonce,
    };
    write_state(&request.state_path, &state)?;
    let app = axum::Router::new()
        .fallback(bridge_request)
        .with_state(BridgeState {
            upstream_origin,
            health_path,
            client: reqwest::Client::new(),
        });
    let result = axum::serve(listener, app)
        .with_graceful_shutdown(daemon_shutdown())
        .await
        .map_err(|error| format!("persistent Codex bridge failed: {error}"));
    remove_matching_state(&request.state_path, &state)?;
    result
}

async fn daemon_shutdown() {
    #[cfg(unix)]
    {
        let terminate = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate());
        if let Ok(mut terminate) = terminate {
            tokio::select! {
                _ = tokio::signal::ctrl_c() => {}
                _ = terminate.recv() => {}
            }
            return;
        }
        let _ = tokio::signal::ctrl_c().await;
    }
    #[cfg(not(unix))]
    // The owned Windows child can run without a console, where registering a
    // Ctrl-C handler may fail immediately. Its owner stops it with `taskkill`.
    std::future::pending::<()>().await;
}

/// Start or reuse the owner-marked bridge for persistent Codex configuration.
pub async fn ensure_persistent(
    state_path: &Path,
    upstream_origin: &str,
) -> Result<PersistentBridge, String> {
    let upstream_origin = canonical_origin(upstream_origin)?;
    let lock = crate::durable_file::lock_exclusive_async(
        &append_suffix(state_path, ".lock"),
        START_TIMEOUT,
    )
    .await
    .map_err(|error| format!("could not lock Codex bridge state: {error}"))?;
    let previous = read_state(state_path).ok().flatten();
    if let Some(state) = previous.as_ref()
        && valid_state(state)
        && state.upstream_origin == upstream_origin
        && healthy(state).await
    {
        return Ok(persistent_handle(state_path, state.clone(), false, lock));
    }
    let preferred = previous
        .as_ref()
        .filter(|state| valid_state(state) && state.upstream_origin == upstream_origin)
        .and_then(|state| listen_address(&state.loopback_origin));
    if let Some(state) = previous.as_ref()
        && valid_state(state)
        && healthy(state).await
    {
        stop_state(state_path, state).await?;
    } else {
        remove_matching_or_invalid_state(state_path, previous.as_ref())?;
    }
    let state = match spawn_daemon(state_path, &upstream_origin, preferred).await {
        Ok(state) => state,
        Err(first) if preferred.is_some() => spawn_daemon(state_path, &upstream_origin, None)
            .await
            .map_err(|second| format!("{first}; retry on a new loopback port failed: {second}"))?,
        Err(error) => return Err(error),
    };
    Ok(persistent_handle(state_path, state, true, lock))
}

fn persistent_handle(
    state_path: &Path,
    state: PersistentState,
    started: bool,
    lock: crate::durable_file::FileLockGuard,
) -> PersistentBridge {
    PersistentBridge {
        backend_base_url: format!("{}{BACKEND_PATH}", state.loopback_origin),
        state_path: state_path.to_path_buf(),
        state,
        started,
        _lock: lock,
    }
}

/// Stop only the bridge proved by the private state nonce.
pub async fn stop_persistent(state_path: &Path) -> Result<(), String> {
    let lock = crate::durable_file::lock_exclusive_async(
        &append_suffix(state_path, ".lock"),
        STOP_TIMEOUT,
    )
    .await
    .map_err(|error| format!("could not lock Codex bridge state: {error}"))?;
    if let Some(state) = read_state(state_path)? {
        if valid_state(&state) && healthy(&state).await {
            stop_state(state_path, &state).await?;
        } else {
            remove_matching_or_invalid_state(state_path, Some(&state))?;
        }
    }
    drop(lock);
    Ok(())
}

async fn spawn_daemon(
    state_path: &Path,
    upstream_origin: &str,
    preferred: Option<std::net::SocketAddr>,
) -> Result<PersistentState, String> {
    remove_file_if_present(state_path)?;
    let nonce = uuid::Uuid::new_v4().simple().to_string();
    let executable = std::env::current_exe()
        .map_err(|error| format!("could not locate the Router executable: {error}"))?;
    let mut command = crate::operation_context::command(executable);
    // A custom Windows environment block must retain its system root, and the
    // standard/runtime temporary-directory APIs need TEMP or TMP. Keep only
    // those OS values rather than inheriting credentials into the daemon.
    let runtime_environment = windows_runtime_environment();
    command
        .env_clear()
        .env("DATA_DIR", crate::logging::data_dir())
        .env(DAEMON_MARKER_ENV, "1")
        .env(DAEMON_UPSTREAM_ENV, upstream_origin)
        .env(DAEMON_STATE_ENV, state_path)
        .env(DAEMON_NONCE_ENV, &nonce)
        .env(
            DAEMON_LISTEN_ENV,
            preferred
                .unwrap_or_else(|| "127.0.0.1:0".parse().expect("literal address"))
                .to_string(),
        )
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::piped());
    command.envs(runtime_environment);
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt as _;
        command.process_group(0);
    }
    let mut child = crate::operation_context::spawn_process(&mut command)
        .map_err(|error| format!("could not start the Codex bridge: {error}"))?;
    let mut child_stderr = child.stderr.take();
    let deadline = tokio::time::Instant::now() + START_TIMEOUT;
    loop {
        if let Some(state) = read_state(state_path)?
            && state.nonce == nonce
            && state.pid == child.id()
            && valid_state(&state)
            && healthy(&state).await
        {
            return Ok(state);
        }
        if let Some(status) = child
            .try_wait()
            .map_err(|error| format!("could not inspect the Codex bridge: {error}"))?
        {
            remove_file_if_present(state_path)?;
            let mut detail = String::new();
            if let Some(stderr) = child_stderr.as_mut() {
                let _ = stderr.read_to_string(&mut detail);
            }
            return Err(daemon_exit_message(status, &detail));
        }
        if tokio::time::Instant::now() >= deadline {
            let _ = child.kill();
            let _ = child.wait();
            remove_file_if_present(state_path)?;
            return Err("Codex bridge did not become ready in time".into());
        }
        tokio::time::sleep(POLL_INTERVAL).await;
    }
}

#[cfg(windows)]
fn windows_runtime_environment() -> Vec<(&'static str, std::ffi::OsString)> {
    select_windows_runtime_environment(|name| crate::operation_context::var_os(name))
}

#[cfg(not(windows))]
const fn windows_runtime_environment() -> Vec<(&'static str, std::ffi::OsString)> {
    Vec::new()
}

#[cfg(any(windows, test))]
pub(crate) fn select_windows_runtime_environment(
    mut get: impl FnMut(&str) -> Option<std::ffi::OsString>,
) -> Vec<(&'static str, std::ffi::OsString)> {
    WINDOWS_RUNTIME_ENV
        .into_iter()
        .filter_map(|name| get(name).map(|value| (name, value)))
        .collect()
}

fn daemon_exit_message(status: std::process::ExitStatus, stderr: &str) -> String {
    format_daemon_exit(&status.to_string(), stderr)
}

pub(crate) fn format_daemon_exit(status: &str, stderr: &str) -> String {
    let detail = stderr.split_whitespace().collect::<Vec<_>>().join(" ");
    if detail.is_empty() {
        format!("Codex bridge exited before becoming ready ({status})")
    } else {
        format!(
            "Codex bridge exited before becoming ready ({status}): {}",
            truncate_diagnostic(&detail, 512)
        )
    }
}

fn truncate_diagnostic(value: &str, limit: usize) -> &str {
    if value.len() <= limit {
        return value;
    }
    let mut boundary = limit;
    while !value.is_char_boundary(boundary) {
        boundary -= 1;
    }
    &value[..boundary]
}

async fn stop_state(state_path: &Path, state: &PersistentState) -> Result<(), String> {
    signal_terminate(state.pid)?;
    let deadline = tokio::time::Instant::now() + STOP_TIMEOUT;
    while healthy(state).await {
        if tokio::time::Instant::now() >= deadline {
            return Err("owned Codex bridge did not stop in time".into());
        }
        tokio::time::sleep(POLL_INTERVAL).await;
    }
    remove_matching_state(state_path, state)
}

#[cfg(unix)]
fn signal_terminate(pid: u32) -> Result<(), String> {
    let status = crate::operation_context::process_output(
        crate::operation_context::command("/bin/kill").args(["-TERM", &pid.to_string()]),
    )
    .map(|output| output.status)
    .map_err(|error| format!("could not stop the owned Codex bridge: {error}"))?;
    if status.success() {
        Ok(())
    } else {
        Err("could not stop the owned Codex bridge".into())
    }
}

#[cfg(windows)]
fn signal_terminate(pid: u32) -> Result<(), String> {
    let arguments = windows_terminate_arguments(pid);
    let status = crate::operation_context::process_output(
        crate::operation_context::command("taskkill").args(arguments),
    )
    .map(|output| output.status)
    .map_err(|error| format!("could not stop the owned Codex bridge: {error}"))?;
    if status.success() {
        Ok(())
    } else {
        Err("could not stop the owned Codex bridge".into())
    }
}

#[cfg(any(windows, test))]
pub(crate) fn windows_terminate_arguments(pid: u32) -> [String; 4] {
    ["/PID".into(), pid.to_string(), "/T".into(), "/F".into()]
}

async fn healthy(state: &PersistentState) -> bool {
    let response = reqwest::Client::builder()
        .timeout(Duration::from_millis(300))
        .build()
        .ok();
    let Some(response) = response else {
        return false;
    };
    response
        .get(format!(
            "{}{}",
            state.loopback_origin,
            health_path(&state.nonce)
        ))
        .send()
        .await
        .ok()
        .filter(|response| response.status().is_success())
        .and_then(|response| response.headers().get(HEALTH_HEADER).cloned())
        .is_some_and(|value| value.as_bytes() == state.nonce.as_bytes())
}

fn health_path(nonce: &str) -> String {
    format!("/__link_assistant_router/codex_bridge/{nonce}")
}

fn valid_state(state: &PersistentState) -> bool {
    state.version == STATE_VERSION
        && state.pid != 0
        && validate_nonce(&state.nonce).is_ok()
        && canonical_origin(&state.upstream_origin).as_deref() == Ok(&state.upstream_origin)
        && listen_address(&state.loopback_origin).is_some()
}

fn listen_address(origin: &str) -> Option<std::net::SocketAddr> {
    let url = reqwest::Url::parse(origin).ok()?;
    if url.scheme() != "http" || url.path() != "/" || url.query().is_some() {
        return None;
    }
    let address = std::net::SocketAddr::new(url.host()?.to_string().parse().ok()?, url.port()?);
    (address.ip() == std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST)).then_some(address)
}

fn read_state(path: &Path) -> Result<Option<PersistentState>, String> {
    let contents = match std::fs::read(path) {
        Ok(contents) => contents,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(format!("could not read Codex bridge state: {error}")),
    };
    serde_json::from_slice(&contents)
        .map(Some)
        .map_err(|_| "Codex bridge state is invalid".to_string())
}

fn write_state(path: &Path, state: &PersistentState) -> Result<(), String> {
    let contents = serde_json::to_vec(state)
        .map_err(|error| format!("could not encode Codex bridge state: {error}"))?;
    crate::durable_file::atomic_write_owner_only(path, &contents)
        .map_err(|error| format!("could not write Codex bridge state: {error}"))
}

fn remove_matching_state(path: &Path, expected: &PersistentState) -> Result<(), String> {
    match read_state(path) {
        Ok(Some(current)) if &current == expected => remove_file_if_present(path),
        Ok(_) | Err(_) => Ok(()),
    }
}

fn remove_matching_or_invalid_state(
    path: &Path,
    expected: Option<&PersistentState>,
) -> Result<(), String> {
    match read_state(path) {
        Ok(Some(current)) if expected.is_none_or(|expected| expected == &current) => {
            remove_file_if_present(path)
        }
        Ok(None | Some(_)) => Ok(()),
        Err(_) => remove_file_if_present(path),
    }
}

fn remove_file_if_present(path: &Path) -> Result<(), String> {
    match std::fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(format!("could not remove Codex bridge state: {error}")),
    }
}

fn append_suffix(path: &Path, suffix: &str) -> PathBuf {
    let mut value = path.as_os_str().to_os_string();
    value.push(suffix);
    PathBuf::from(value)
}

fn canonical_origin(value: &str) -> Result<String, String> {
    let mut url =
        reqwest::Url::parse(value).map_err(|error| format!("invalid Router URL: {error}"))?;
    if !matches!(url.scheme(), "http" | "https") || url.host_str().is_none() {
        return Err("Router URL must be an HTTP or HTTPS origin".into());
    }
    if url.query().is_some() || url.fragment().is_some() {
        return Err("Router URL must not contain a query or fragment".into());
    }
    let path = url.path().trim_end_matches('/').to_string();
    url.set_path(&path);
    Ok(url.to_string().trim_end_matches('/').to_string())
}

async fn bridge_request(State(state): State<BridgeState>, request: Request) -> Response {
    let method = request.method().clone();
    let uri = request.uri().clone();
    if method == Method::GET && uri.path() == state.health_path {
        let nonce = state
            .health_path
            .rsplit('/')
            .next()
            .expect("health path has a nonce");
        return (StatusCode::OK, [(HEALTH_HEADER, nonce)], "ok").into_response();
    }
    if !uri.path().starts_with(&format!("{BACKEND_PATH}/")) {
        return StatusCode::NOT_FOUND.into_response();
    }
    let headers = request.headers().clone();
    let target = bridge_target(&state, &headers, &uri);
    if is_websocket(&headers) {
        return upgrade_websocket(request, target).await;
    }
    let Ok(body) = axum::body::to_bytes(request.into_body(), MAX_HTTP_BODY_BYTES).await else {
        return StatusCode::PAYLOAD_TOO_LARGE.into_response();
    };
    relay_http(&method, body, target).await
}

struct BridgeTarget {
    client: reqwest::Client,
    url: String,
    headers: HeaderMap,
}

fn bridge_target(state: &BridgeState, incoming: &HeaderMap, uri: &axum::http::Uri) -> BridgeTarget {
    let mut url = format!("{}{}", state.upstream_origin, uri.path());
    if let Some(query) = uri.query() {
        url.push('?');
        url.push_str(query);
    }
    BridgeTarget {
        client: state.client.clone(),
        url,
        headers: request_headers(incoming),
    }
}

async fn relay_http(method: &Method, body: Bytes, target: BridgeTarget) -> Response {
    let upstream = target
        .client
        .request(
            reqwest::Method::from_bytes(method.as_str().as_bytes()).expect("valid HTTP method"),
            target.url,
        )
        .headers(target.headers)
        .body(body)
        .send()
        .await;
    let Ok(upstream) = upstream else {
        return StatusCode::BAD_GATEWAY.into_response();
    };
    let status = StatusCode::from_u16(upstream.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let headers = crate::proxy::relay_response_headers(upstream.headers());
    let stream = upstream.bytes_stream();
    let mut response = Response::new(Body::from_stream(stream));
    *response.status_mut() = status;
    *response.headers_mut() = headers;
    response
}

fn request_headers(incoming: &HeaderMap) -> HeaderMap {
    let connection_headers: HashSet<HeaderName> = incoming
        .get_all("connection")
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(','))
        .filter_map(|name| HeaderName::from_bytes(name.trim().as_bytes()).ok())
        .collect();
    let mut headers = HeaderMap::new();
    for (name, value) in incoming {
        if !transport_header(name.as_str()) && !connection_headers.contains(name) {
            headers.append(name.clone(), value.clone());
        }
    }
    headers
}

fn transport_header(name: &str) -> bool {
    matches!(
        name,
        "host"
            | "connection"
            | "proxy-connection"
            | "keep-alive"
            | "transfer-encoding"
            | "upgrade"
            | "te"
            | "trailer"
            | "content-length"
            | "accept-encoding"
            | "forwarded"
            | "x-forwarded-for"
            | "x-forwarded-host"
            | "x-forwarded-proto"
            | "x-real-ip"
            | "sec-websocket-key"
            | "sec-websocket-version"
            | "sec-websocket-extensions"
            | "sec-websocket-accept"
    )
}

fn is_websocket(headers: &HeaderMap) -> bool {
    headers
        .get("upgrade")
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.eq_ignore_ascii_case("websocket"))
}

async fn upgrade_websocket(request: Request, target: BridgeTarget) -> Response {
    let (mut parts, _) = request.into_parts();
    let upgrade = match WebSocketUpgrade::from_request_parts(&mut parts, &()).await {
        Ok(upgrade) => upgrade,
        Err(rejection) => return rejection.into_response(),
    };
    upgrade
        .max_message_size(MAX_WEBSOCKET_MESSAGE_BYTES)
        .max_frame_size(MAX_WEBSOCKET_MESSAGE_BYTES)
        .on_upgrade(move |downstream| websocket_session(downstream, target))
}

async fn websocket_session(mut downstream: WebSocket, target: BridgeTarget) {
    let Ok(mut request) = websocket_url(&target.url)
        .and_then(|url| url.into_client_request().map_err(|error| error.to_string()))
    else {
        close(&mut downstream, 1011, "invalid Router WebSocket URL").await;
        return;
    };
    for (name, value) in target.headers {
        if let Some(name) = name {
            request.headers_mut().append(name, value);
        }
    }
    let config = tungstenite::protocol::WebSocketConfig::default()
        .max_message_size(Some(MAX_WEBSOCKET_MESSAGE_BYTES))
        .max_frame_size(Some(MAX_WEBSOCKET_MESSAGE_BYTES))
        .max_write_buffer_size(MAX_WEBSOCKET_MESSAGE_BYTES.saturating_mul(2));
    let connected = tokio::time::timeout(
        CONNECT_TIMEOUT,
        tokio_tungstenite::connect_async_with_config(request, Some(config), false),
    )
    .await;
    let Ok(Ok((mut upstream, _))) = connected else {
        close(&mut downstream, 1011, "Router WebSocket connection failed").await;
        return;
    };
    loop {
        tokio::select! {
            message = downstream.next() => {
                let Some(Ok(message)) = message else {
                    let _ = upstream.close(None).await;
                    break;
                };
                let closes = matches!(message, Message::Close(_));
                if upstream.send(downstream_message(message)).await.is_err() || closes {
                    break;
                }
            }
            message = upstream.next() => {
                let Some(Ok(message)) = message else {
                    close(&mut downstream, 1011, "Router WebSocket disconnected").await;
                    break;
                };
                let closes = matches!(message, tungstenite::Message::Close(_));
                if downstream.send(upstream_message(message)).await.is_err() || closes {
                    break;
                }
            }
        }
    }
}

fn downstream_message(message: Message) -> tungstenite::Message {
    match message {
        Message::Text(text) => tungstenite::Message::Text(text.to_string().into()),
        Message::Binary(bytes) => tungstenite::Message::Binary(bytes.to_vec().into()),
        Message::Ping(bytes) => tungstenite::Message::Ping(bytes.to_vec().into()),
        Message::Pong(bytes) => tungstenite::Message::Pong(bytes.to_vec().into()),
        Message::Close(frame) => {
            tungstenite::Message::Close(frame.map(|frame| tungstenite::protocol::CloseFrame {
                code: frame.code.into(),
                reason: frame.reason.to_string().into(),
            }))
        }
    }
}

fn upstream_message(message: tungstenite::Message) -> Message {
    match message {
        tungstenite::Message::Text(text) => Message::Text(text.to_string().into()),
        tungstenite::Message::Binary(bytes) => Message::Binary(bytes.to_vec().into()),
        tungstenite::Message::Ping(bytes) => Message::Ping(bytes.to_vec().into()),
        tungstenite::Message::Pong(bytes) => Message::Pong(bytes.to_vec().into()),
        tungstenite::Message::Close(frame) => Message::Close(frame.map(|frame| CloseFrame {
            code: frame.code.into(),
            reason: frame.reason.to_string().into(),
        })),
        tungstenite::Message::Frame(_) => Message::Close(Some(CloseFrame {
            code: 1011,
            reason: "unexpected raw Router frame".into(),
        })),
    }
}

async fn close(socket: &mut WebSocket, code: u16, reason: &'static str) {
    let _ = socket
        .send(Message::Close(Some(CloseFrame {
            code,
            reason: reason.into(),
        })))
        .await;
}

fn websocket_url(url: &str) -> Result<String, String> {
    let mut url = reqwest::Url::parse(url).map_err(|error| error.to_string())?;
    let scheme = match url.scheme() {
        "https" => "wss",
        "http" => "ws",
        _ => return Err("unsupported WebSocket scheme".into()),
    };
    url.set_scheme(scheme)
        .map_err(|()| "could not set WebSocket scheme".to_string())?;
    Ok(url.to_string())
}

//! Private continuation state for Codex remote control.

use std::fmt;
use std::fs;
use std::path::{Path, PathBuf};

use axum::body::{Body, Bytes};
use axum::extract::Request;
use axum::http::{HeaderMap, HeaderValue, Method, StatusCode};
use axum::response::Response;
use futures_util::StreamExt as _;
use serde::{Deserialize, Serialize};
use sha2::{Digest as _, Sha256};

use crate::app_state::AppState;
use crate::subscription::SubscriptionProvider;

pub const CONTINUATION_PREFIX: &crate::translation_core::Str = "la_rc_";
const FILE_NAME: &crate::translation_core::Str = "codex-remote-control.lino";
const STORE_VERSION: u32 = 1;
const MAX_RECORDS: usize = 1_000;

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct EnrollmentIdentity {
    pub principal_id: String,
    pub account_name: String,
    pub server_id: String,
    pub environment_id: String,
    pub installation_id: String,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct EnrollmentRecord {
    pub identity: EnrollmentIdentity,
    pub upstream_token: String,
    pub upstream_base_url: String,
    pub expires_at: i64,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct BoundEnrollment {
    pub token_hash: String,
    pub record: EnrollmentRecord,
}

#[derive(Debug)]
pub enum StoreError {
    Io(std::io::Error),
    Decode(serde_json::Error),
    Crypto(String),
    Invalid,
    StaleRotation,
}

impl fmt::Display for StoreError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(error) => write!(formatter, "remote-control storage failed: {error}"),
            Self::Decode(error) => write!(formatter, "remote-control state is invalid: {error}"),
            Self::Crypto(error) => {
                write!(formatter, "remote-control state cannot be opened: {error}")
            }
            Self::Invalid => formatter.write_str("remote-control state is invalid"),
            Self::StaleRotation => {
                formatter.write_str("remote-control enrollment changed during refresh")
            }
        }
    }
}

impl std::error::Error for StoreError {}

impl From<std::io::Error> for StoreError {
    fn from(error: std::io::Error) -> Self {
        Self::Io(error)
    }
}

impl From<serde_json::Error> for StoreError {
    fn from(error: serde_json::Error) -> Self {
        Self::Decode(error)
    }
}

#[derive(Debug, Serialize, Deserialize)]
struct StoredEnrollment {
    token_hash: String,
    sealed_record: String,
}

#[derive(Debug, Serialize, Deserialize)]
struct StoreFile {
    version: u32,
    records: Vec<StoredEnrollment>,
}

#[derive(Clone, Debug)]
pub struct CodexRemoteControlStore {
    path: PathBuf,
    lock_path: PathBuf,
    token_secret: String,
}

impl CodexRemoteControlStore {
    pub fn open(data_dir: &Path, token_secret: &crate::translation_core::Str) -> crate::translation_core::Outcome<Self, StoreError> {
        fs::create_dir_all(data_dir)?;
        let path = data_dir.join(FILE_NAME);
        let store = Self {
            lock_path: path.with_extension("lock"),
            path,
            token_secret: token_secret.to_string(),
        };
        crate::durable_file::with_exclusive_lock(&store.lock_path, || {
            crate::durable_file::recover_transactional_write(&store.path)?;
            let _ = store.load()?;
            Ok::<_, StoreError>(())
        })?;
        Ok(store)
    }

    pub fn issue(&self, record: &EnrollmentRecord) -> crate::translation_core::Outcome<String, StoreError> {
        validate_record(record)?;
        crate::durable_file::with_exclusive_lock(&self.lock_path, || {
            crate::durable_file::recover_transactional_write(&self.path)?;
            let mut file = self.load()?;
            self.remove_slot(&mut file, &record.identity)?;
            let token = new_continuation();
            file.records.push(self.seal(&token, record)?);
            if file.records.len() > MAX_RECORDS {
                file.records.remove(0);
            }
            self.flush(&file)?;
            Ok(token)
        })
    }

    pub fn resolve(&self, token: &crate::translation_core::Str, now: i64) -> crate::translation_core::Outcome<crate::translation_core::Maybe<EnrollmentRecord>, StoreError> {
        let Some(hash) = continuation_hash(token) else {
            return Ok(None);
        };
        crate::durable_file::with_exclusive_lock(&self.lock_path, || {
            crate::durable_file::recover_transactional_write(&self.path)?;
            let file = self.load()?;
            let Some(stored) = file
                .records
                .iter()
                .find(|stored| crate::token::constant_time_eq(&stored.token_hash, &hash))
            else {
                return Ok(None);
            };
            let record = self.unseal(stored)?;
            Ok((record.expires_at > now).then_some(record))
        })
    }

    pub fn find(
        &self,
        principal_id: &crate::translation_core::Str,
        account_name: &crate::translation_core::Str,
        server_id: &crate::translation_core::Str,
        installation_id: &crate::translation_core::Str,
    ) -> crate::translation_core::Outcome<crate::translation_core::Maybe<BoundEnrollment>, StoreError> {
        crate::durable_file::with_exclusive_lock(&self.lock_path, || {
            crate::durable_file::recover_transactional_write(&self.path)?;
            let file = self.load()?;
            for stored in &file.records {
                let record = self.unseal(stored)?;
                let identity = &record.identity;
                if identity.principal_id == principal_id
                    && identity.account_name == account_name
                    && identity.server_id == server_id
                    && identity.installation_id == installation_id
                {
                    return Ok(Some(BoundEnrollment {
                        token_hash: stored.token_hash.clone(),
                        record,
                    }));
                }
            }
            Ok(None)
        })
    }

    pub fn rotate(
        &self,
        expected_token_hash: &crate::translation_core::Str,
        record: &EnrollmentRecord,
    ) -> crate::translation_core::Outcome<String, StoreError> {
        validate_record(record)?;
        crate::durable_file::with_exclusive_lock(&self.lock_path, || {
            crate::durable_file::recover_transactional_write(&self.path)?;
            let mut file = self.load()?;
            let Some(index) = file.records.iter().position(|stored| {
                crate::token::constant_time_eq(&stored.token_hash, expected_token_hash)
            }) else {
                return Err(StoreError::StaleRotation);
            };
            if self.unseal(&file.records[index])?.identity != record.identity {
                return Err(StoreError::StaleRotation);
            }
            let token = new_continuation();
            file.records[index] = self.seal(&token, record)?;
            self.flush(&file)?;
            Ok(token)
        })
    }

    pub fn owns_environment(
        &self,
        principal_id: &crate::translation_core::Str,
        account_name: &crate::translation_core::Str,
        environment_id: &crate::translation_core::Str,
    ) -> crate::translation_core::Outcome<bool, StoreError> {
        crate::durable_file::with_exclusive_lock(&self.lock_path, || {
            crate::durable_file::recover_transactional_write(&self.path)?;
            let file = self.load()?;
            for stored in &file.records {
                let identity = self.unseal(stored)?.identity;
                if identity.principal_id == principal_id
                    && identity.account_name == account_name
                    && identity.environment_id == environment_id
                {
                    return Ok(true);
                }
            }
            Ok(false)
        })
    }

    fn remove_slot(
        &self,
        file: &mut StoreFile,
        identity: &EnrollmentIdentity,
    ) -> Result<(), StoreError> {
        let mut kept = Vec::with_capacity(file.records.len());
        for stored in file.records.drain(..) {
            let current = self.unseal(&stored)?.identity;
            if current.principal_id != identity.principal_id
                || current.account_name != identity.account_name
                || current.installation_id != identity.installation_id
            {
                kept.push(stored);
            }
        }
        file.records = kept;
        Ok(())
    }

    fn seal(&self, token: &crate::translation_core::Str, record: &EnrollmentRecord) -> crate::translation_core::Outcome<StoredEnrollment, StoreError> {
        let plaintext = serde_json::to_string(record)?;
        let sealed_record = crate::providers::seal_secret(&plaintext, &self.token_secret)
            .map_err(|error| StoreError::Crypto(error.to_string()))?;
        Ok(StoredEnrollment {
            token_hash: continuation_hash(token).ok_or(StoreError::Invalid)?,
            sealed_record,
        })
    }

    fn unseal(&self, stored: &StoredEnrollment) -> crate::translation_core::Outcome<EnrollmentRecord, StoreError> {
        let plaintext = crate::providers::open_secret(&stored.sealed_record, &self.token_secret)
            .map_err(|error| StoreError::Crypto(error.to_string()))?;
        let record = serde_json::from_str(&plaintext)?;
        validate_record(&record)?;
        Ok(record)
    }

    fn load(&self) -> crate::translation_core::Outcome<StoreFile, StoreError> {
        if !self.path.exists() {
            return Ok(StoreFile {
                version: STORE_VERSION,
                records: Vec::new(),
            });
        }
        let file: StoreFile = crate::lino_json::decode(&fs::read_to_string(&self.path)?)?;
        if file.version != STORE_VERSION {
            return Err(StoreError::Invalid);
        }
        Ok(file)
    }

    fn flush(&self, file: &StoreFile) -> crate::translation_core::Outcome<(), StoreError> {
        let encoded = crate::lino_json::encode(file)?;
        crate::durable_file::transactional_write_owner_only(&self.path, encoded.as_bytes())?;
        Ok(())
    }
}

fn new_continuation() -> String {
    format!(
        "{CONTINUATION_PREFIX}{}{}",
        uuid::Uuid::new_v4().simple(),
        uuid::Uuid::new_v4().simple()
    )
}

fn continuation_hash(token: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
    token.strip_prefix(CONTINUATION_PREFIX)?;
    Some(hex::encode(Sha256::digest(token.as_bytes())))
}

fn validate_record(record: &EnrollmentRecord) -> crate::translation_core::Outcome<(), StoreError> {
    let identity = &record.identity;
    let values = [
        identity.principal_id.as_str(),
        identity.account_name.as_str(),
        identity.server_id.as_str(),
        identity.environment_id.as_str(),
        identity.installation_id.as_str(),
        record.upstream_token.as_str(),
        record.upstream_base_url.as_str(),
    ];
    if values
        .iter()
        .any(|value| value.is_empty() || value.len() > 8_192)
        || record.expires_at <= 0
    {
        return Err(StoreError::Invalid);
    }
    Ok(())
}

const ROOT: &crate::translation_core::Str = "/api/services/codex/backend-api/wham/remote/control/";
const SERVER: &crate::translation_core::Str = "/api/services/codex/backend-api/wham/remote/control/server";
const ENROLL: &crate::translation_core::Str = "/api/services/codex/backend-api/wham/remote/control/server/enroll";
const REFRESH: &crate::translation_core::Str = "/api/services/codex/backend-api/wham/remote/control/server/refresh";
const REFRESH_UPSTREAM: &crate::translation_core::Str = "/wham/remote/control/server/refresh";
const PAIR: &crate::translation_core::Str = "/api/services/codex/backend-api/wham/remote/control/server/pair";
const PAIR_STATUS: &crate::translation_core::Str = "/api/services/codex/backend-api/wham/remote/control/server/pair/status";
const ENVIRONMENTS: &crate::translation_core::Str = "/api/services/codex/backend-api/wham/remote/control/environments/";

#[derive(Debug, Eq, PartialEq)]
enum Operation {
    WebSocket,
    Enroll,
    Refresh,
    Pair,
    PairStatus,
    List { environment_id: String },
    Revoke { environment_id: String },
}

pub fn is_remote_control_path(path: &crate::translation_core::Str) -> bool {
    path.starts_with(ROOT)
}

fn operation(method: &Method, path: &crate::translation_core::Str) -> crate::translation_core::Maybe<Operation> {
    match (method, path) {
        (&Method::GET, SERVER) => Some(Operation::WebSocket),
        (&Method::POST, ENROLL) => Some(Operation::Enroll),
        (&Method::POST, REFRESH) => Some(Operation::Refresh),
        (&Method::POST, PAIR) => Some(Operation::Pair),
        (&Method::POST, PAIR_STATUS) => Some(Operation::PairStatus),
        _ => dynamic_operation(method, path),
    }
}

/// Whether the route authenticates a Router-issued continuation itself.
///
/// The ordinary inference middleware cannot validate `la_rc_` credentials;
/// these handlers resolve their encrypted, identity-bound state before ever
/// reading a request body.
pub fn authenticates_continuation(method: &Method, path: &crate::translation_core::Str) -> bool {
    matches!(
        operation(method, path),
        Some(Operation::WebSocket | Operation::Pair | Operation::PairStatus)
    )
}

fn dynamic_operation(method: &Method, path: &crate::translation_core::Str) -> crate::translation_core::Maybe<Operation> {
    let tail = path.strip_prefix(ENVIRONMENTS)?;
    let segments = tail.split('/').collect::<Vec<_>>();
    match (method, segments.as_slice()) {
        (&Method::GET, [environment, "clients"]) => Some(Operation::List {
            environment_id: decode_path_segment(environment)?,
        }),
        (&Method::DELETE, [environment, "clients", client])
            if decode_path_segment(client).is_some() =>
        {
            Some(Operation::Revoke {
                environment_id: decode_path_segment(environment)?,
            })
        }
        _ => None,
    }
}

pub async fn forward(state: AppState, request: Request) -> Response {
    let method = request.method().clone();
    let uri = request.uri().clone();
    let Some(operation) = operation(&method, uri.path()) else {
        return api_error(StatusCode::NOT_FOUND, "not_found_error", "route not found");
    };
    match operation {
        Operation::Pair | Operation::PairStatus | Operation::WebSocket => {
            Box::pin(continuation_request(state, request, operation)).await
        }
        Operation::Enroll
        | Operation::Refresh
        | Operation::List { .. }
        | Operation::Revoke { .. } => primary_request(state, request, operation).await,
    }
}

async fn primary_request(state: AppState, request: Request, operation: Operation) -> Response {
    let method = request.method().clone();
    let uri = request.uri().clone();
    let headers = request.headers().clone();
    let Some(primary) = bearer(&headers) else {
        return authentication_error("Codex remote control requires Router authentication");
    };
    if !crate::proxy::codex_carrier_accepted(&state, Some(primary)) {
        return authentication_error(
            "Codex remote-control enrollment requires the paired Router-issued at- token",
        );
    }
    let claims = match crate::proxy::authenticate_client_error(&state, &headers) {
        Ok(claims) => claims,
        Err(error) => return error.render(crate::api_error::ApiDialect::OpenAi),
    };
    let Ok((client, principal)) = crate::client_policy::bound_client(&claims) else {
        return permission_error("Codex remote control requires a managed Codex client token");
    };
    if client != crate::clients::ClientKind::Codex {
        return permission_error("Codex remote control requires a managed Codex client token");
    }
    let principal = principal.to_string();
    let Ok(body) = axum::body::to_bytes(request.into_body(), state.max_proxy_request_bytes).await
    else {
        return api_error(
            StatusCode::PAYLOAD_TOO_LARGE,
            "invalid_request_error",
            "request body exceeds the remote-control proxy limit",
        );
    };
    let selected = match crate::native_service::selected_subscription(
        &state,
        &headers,
        &claims,
        SubscriptionProvider::Codex,
        Some(&body),
    )
    .await
    {
        Ok(selected) => selected,
        Err(response) => return response,
    };
    let root = codex_backend_root(&state, &selected);
    let target = primary_target(&state, &headers, &selected, &service_uri(&uri));

    match operation {
        Operation::Enroll => {
            enroll(state, claims, principal, selected.name, root, body, target).await
        }
        Operation::Refresh => refresh(state, principal, selected.name, root, body, target).await,
        Operation::List { environment_id } | Operation::Revoke { environment_id } => {
            match state
                .provider_store
                .codex_remote_control()
                .owns_environment(&principal, &selected.name, &environment_id)
            {
                Ok(true) => crate::native_service::relay_http(&state, &method, body, target).await,
                Ok(false) => permission_error(
                    "the remote-control environment is not owned by this Router principal",
                ),
                Err(_) => unavailable("remote-control ownership state is unavailable"),
            }
        }
        Operation::Pair | Operation::PairStatus | Operation::WebSocket => unreachable!(),
    }
}

fn service_uri(uri: &axum::http::Uri) -> String {
    let path = uri
        .path()
        .strip_prefix("/api/services/codex/backend-api")
        .unwrap_or_else(|| uri.path());
    uri_path_and_query(path, uri.query().unwrap_or_default())
}

fn uri_path_and_query(path: &crate::translation_core::Str, query: &crate::translation_core::Str) -> String {
    if query.is_empty() {
        path.to_string()
    } else {
        format!("{path}?{query}")
    }
}

fn codex_backend_root(
    state: &AppState,
    selected: &crate::accounts::SelectedSubscriptionAccount,
) -> String {
    let base = state
        .subscription_base_url
        .clone()
        .unwrap_or_else(|| selected.token.base_url(SubscriptionProvider::Codex));
    base.strip_suffix("/codex")
        .unwrap_or(&base)
        .trim_end_matches('/')
        .to_string()
}

fn primary_target(
    state: &AppState,
    incoming: &HeaderMap,
    selected: &crate::accounts::SelectedSubscriptionAccount,
    uri: &crate::translation_core::Str,
) -> crate::native_service::Target {
    let root = codex_backend_root(state, selected);
    let mut headers = crate::proxy::native_request_headers(incoming, &selected.token.access_token);
    if let Some(account_id) = selected.token.account_id.as_deref()
        && let Ok(value) = HeaderValue::from_str(account_id)
    {
        headers.insert("chatgpt-account-id", value);
    }
    crate::native_service::Target {
        client: crate::upstream_client::subscription_client(
            &state.client,
            SubscriptionProvider::Codex,
            state.subscription_base_url.is_some(),
        )
        .clone(),
        url: format!("{root}{uri}"),
        headers,
    }
}

async fn enroll(
    state: AppState,
    claims: crate::token::TokenClaims,
    principal: String,
    account_name: String,
    upstream_root: String,
    body: Bytes,
    target: crate::native_service::Target,
) -> Response {
    let Some(installation_id) = json_string(&body, "installation_id") else {
        return invalid_request("remote-control enrollment requires installation_id");
    };
    let response = match send_buffered(&state, Method::POST, body, target).await {
        Ok(response) => response,
        Err(response) => return response,
    };
    if !response.status.is_success() {
        return response.into_response();
    }
    let (mut json, server_id, environment_id, upstream_token, expires_at) =
        match enrollment_response(&response.body) {
            Ok(parsed) => parsed,
            Err(response) => return response,
        };
    let record = EnrollmentRecord {
        identity: EnrollmentIdentity {
            principal_id: principal,
            account_name,
            server_id,
            environment_id,
            installation_id,
        },
        upstream_token,
        upstream_base_url: upstream_root,
        expires_at,
    };
    let Ok(continuation) = state.provider_store.codex_remote_control().issue(&record) else {
        return unavailable("remote-control continuation state could not be stored");
    };
    json["remote_control_token"] = crate::translation_core::Json::String(continuation);
    crate::audit::record_control_plane_request(
        &state,
        &claims,
        "codex",
        "codex.remote_control.enroll",
    );
    response.with_json(&json)
}

async fn refresh(
    state: AppState,
    principal: String,
    account_name: String,
    upstream_root: String,
    body: Bytes,
    mut target: crate::native_service::Target,
) -> Response {
    let Some(server_id) = json_string(&body, "server_id") else {
        return invalid_request("remote-control refresh requires server_id");
    };
    let Some(installation_id) = json_string(&body, "installation_id") else {
        return invalid_request("remote-control refresh requires installation_id");
    };
    let current = match state.provider_store.codex_remote_control().find(
        &principal,
        &account_name,
        &server_id,
        &installation_id,
    ) {
        Ok(Some(current)) => current,
        Ok(None) => {
            return permission_error(
                "the remote-control enrollment is not owned by this Router principal",
            );
        }
        Err(_) => return unavailable("remote-control continuation state is unavailable"),
    };
    target.url = format!("{}{REFRESH_UPSTREAM}", current.record.upstream_base_url);
    let response = match send_buffered(&state, Method::POST, body, target).await {
        Ok(response) => response,
        Err(response) => return response,
    };
    if !response.status.is_success() {
        return response.into_response();
    }
    let (mut json, returned_server, returned_environment, upstream_token, expires_at) =
        match enrollment_response(&response.body) {
            Ok(parsed) => parsed,
            Err(response) => return response,
        };
    if returned_server != current.record.identity.server_id
        || returned_environment != current.record.identity.environment_id
        || upstream_root != current.record.upstream_base_url
    {
        return unavailable("remote-control refresh returned inconsistent enrollment identity");
    }
    let record = EnrollmentRecord {
        identity: current.record.identity,
        upstream_token,
        upstream_base_url: current.record.upstream_base_url,
        expires_at,
    };
    let continuation = match state
        .provider_store
        .codex_remote_control()
        .rotate(&current.token_hash, &record)
    {
        Ok(token) => token,
        Err(StoreError::StaleRotation) => {
            return unavailable("remote-control enrollment changed during refresh");
        }
        Err(_) => return unavailable("remote-control continuation state could not be stored"),
    };
    json["remote_control_token"] = serde_json::Value::String(continuation);
    response.with_json(&json)
}

async fn continuation_request(state: AppState, request: Request, operation: Operation) -> Response {
    let headers = request.headers().clone();
    let Some(token) = bearer(&headers).filter(|token| token.starts_with(CONTINUATION_PREFIX))
    else {
        return authentication_error("a valid Router remote-control continuation is required");
    };
    let record = match state
        .provider_store
        .codex_remote_control()
        .resolve(token, crate::operation_context::now().timestamp())
    {
        Ok(Some(record)) => record,
        Ok(None) => {
            return authentication_error("the remote-control continuation is invalid or expired");
        }
        Err(_) => return unavailable("remote-control continuation state is unavailable"),
    };
    if operation == Operation::WebSocket && !websocket_identity_matches(&headers, &record.identity)
    {
        return permission_error("the remote-control connection does not match this enrollment");
    }
    let uri = request.uri().clone();
    let target = continuation_target(&state, &headers, &record, &uri);
    if operation == Operation::WebSocket {
        if !is_websocket(&headers) {
            return invalid_request(
                "the remote-control server endpoint requires a WebSocket upgrade",
            );
        }
        return crate::native_service::upgrade_websocket(state, request, target, None).await;
    }
    let Ok(body) = axum::body::to_bytes(request.into_body(), state.max_proxy_request_bytes).await
    else {
        return api_error(
            StatusCode::PAYLOAD_TOO_LARGE,
            "invalid_request_error",
            "request body exceeds the remote-control proxy limit",
        );
    };
    if operation == Operation::Pair {
        let response = match send_buffered(&state, Method::POST, body, target).await {
            Ok(response) => response,
            Err(response) => return response,
        };
        if response.status.is_success() && !pair_identity_matches(&response.body, &record.identity)
        {
            return unavailable("remote-control pairing returned inconsistent enrollment identity");
        }
        return response.into_response();
    }
    crate::native_service::relay_http(&state, &Method::POST, body, target).await
}

fn continuation_target(
    state: &AppState,
    incoming: &HeaderMap,
    record: &EnrollmentRecord,
    uri: &axum::http::Uri,
) -> crate::native_service::Target {
    let path = uri
        .path()
        .strip_prefix("/api/services/codex/backend-api")
        .unwrap_or_else(|| uri.path());
    let path = uri_path_and_query(path, uri.query().unwrap_or_default());
    crate::native_service::Target {
        client: crate::upstream_client::subscription_client(
            &state.client,
            SubscriptionProvider::Codex,
            state.subscription_base_url.is_some(),
        )
        .clone(),
        url: format!("{}{path}", record.upstream_base_url),
        headers: crate::proxy::native_request_headers(incoming, &record.upstream_token),
    }
}

struct BufferedResponse {
    status: StatusCode,
    headers: HeaderMap,
    body: Bytes,
}

impl BufferedResponse {
    fn into_response(self) -> Response {
        let mut response = Response::new(Body::from(self.body));
        *response.status_mut() = self.status;
        *response.headers_mut() = self.headers;
        response
    }

    fn with_json(self, json: &crate::translation_core::Json) -> Response {
        let mut response = Response::new(Body::from(json.to_string()));
        *response.status_mut() = self.status;
        *response.headers_mut() = self.headers;
        response
    }
}

async fn send_buffered(
    state: &AppState,
    method: Method,
    body: Bytes,
    target: crate::native_service::Target,
) -> crate::translation_core::Outcome<BufferedResponse, Response> {
    let upstream = target
        .client
        .request(
            reqwest::Method::from_bytes(method.as_str().as_bytes()).expect("valid HTTP method"),
            target.url,
        )
        .headers(target.headers)
        .body(body.clone())
        .send()
        .await
        .map_err(|_| unavailable("remote-control upstream request failed"))?;
    let status = StatusCode::from_u16(upstream.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let headers = crate::proxy::relay_response_headers(upstream.headers());
    let mut stream = upstream.bytes_stream();
    let mut response_body = Vec::new();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|_| unavailable("remote-control upstream response failed"))?;
        if response_body.len().saturating_add(chunk.len()) > state.max_proxy_request_bytes {
            return Err(unavailable(
                "remote-control upstream response exceeds the proxy limit",
            ));
        }
        response_body.extend_from_slice(&chunk);
    }
    state
        .metrics
        .record_bytes(body.len() as u64, response_body.len() as u64);
    Ok(BufferedResponse {
        status,
        headers,
        body: Bytes::from(response_body),
    })
}

fn enrollment_response(
    body: &[u8],
) -> crate::translation_core::Outcome<(crate::translation_core::Json, String, String, String, i64), Response> {
    let json: serde_json::Value = serde_json::from_slice(body)
        .map_err(|_| unavailable("remote-control enrollment response is malformed"))?;
    let string = |name| {
        json.get(name)
            .and_then(crate::translation_core::Json::as_str)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
            .ok_or_else(|| unavailable("remote-control enrollment response is malformed"))
    };
    let server_id = string("server_id")?;
    let environment_id = string("environment_id")?;
    let upstream_token = string("remote_control_token")?;
    let expires = string("expires_at")?;
    let expires_at = chrono::DateTime::parse_from_rfc3339(&expires)
        .map_err(|_| unavailable("remote-control enrollment response has an invalid expiry"))?
        .timestamp();
    if expires_at <= crate::operation_context::now().timestamp() {
        return Err(unavailable(
            "remote-control enrollment response is already expired",
        ));
    }
    Ok((json, server_id, environment_id, upstream_token, expires_at))
}

fn json_string(body: &[u8], name: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
    serde_json::from_slice::<serde_json::Value>(body)
        .ok()?
        .get(name)?
        .as_str()
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn pair_identity_matches(body: &[u8], identity: &EnrollmentIdentity) -> bool {
    let Ok(json) = serde_json::from_slice::<serde_json::Value>(body) else {
        return false;
    };
    json.get("server_id").and_then(crate::translation_core::Json::as_str) == Some(identity.server_id.as_str())
        && json
            .get("environment_id")
            .and_then(crate::translation_core::Json::as_str)
            == Some(identity.environment_id.as_str())
}

fn websocket_identity_matches(headers: &HeaderMap, identity: &EnrollmentIdentity) -> bool {
    header(headers, "x-codex-server-id") == crate::translation_core::Maybe::Some(identity.server_id.as_str())
        && header(headers, "x-codex-installation-id") == crate::translation_core::Maybe::Some(identity.installation_id.as_str())
}

fn header<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {
    let mut values = headers.get_all(name).iter();
    let value = values.next()?.to_str().ok()?;
    values.next().is_none().then_some(value)
}

fn bearer(headers: &HeaderMap) -> crate::translation_core::Maybe<&crate::translation_core::Str> {
    let value = header(headers, "authorization")?;
    let (scheme, token) = value.split_once(' ')?;
    (scheme.eq_ignore_ascii_case("bearer") && !token.is_empty()).then_some(token)
}

fn is_websocket(headers: &HeaderMap) -> bool {
    header(headers, "upgrade").is_some_and(|value| value.eq_ignore_ascii_case("websocket"))
}

fn decode_path_segment(segment: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
    if segment.is_empty() {
        return None;
    }
    let bytes = segment.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' {
            let high = hex_digit(*bytes.get(index + 1)?)?;
            let low = hex_digit(*bytes.get(index + 2)?)?;
            decoded.push((high << 4) | low);
            index += 3;
        } else {
            decoded.push(bytes[index]);
            index += 1;
        }
    }
    String::from_utf8(decoded)
        .ok()
        .filter(|value| !value.chars().any(char::is_control))
}

const fn hex_digit(byte: u8) -> crate::translation_core::Maybe<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn invalid_request(message: &crate::translation_core::Str) -> Response {
    api_error(StatusCode::BAD_REQUEST, "invalid_request_error", message)
}

fn authentication_error(message: &crate::translation_core::Str) -> Response {
    api_error(StatusCode::UNAUTHORIZED, "authentication_error", message)
}

fn permission_error(message: &crate::translation_core::Str) -> Response {
    api_error(StatusCode::FORBIDDEN, "permission_error", message)
}

fn unavailable(message: &crate::translation_core::Str) -> Response {
    api_error(StatusCode::SERVICE_UNAVAILABLE, "api_error", message)
}

fn api_error(status: StatusCode, error_type: &crate::translation_core::Str, message: &crate::translation_core::Str) -> Response {
    crate::api_error::PresentedError {
        status,
        error_type,
        message,
    }
    .render(crate::api_error::ApiDialect::OpenAi)
}

//! Configuration module for Link.Assistant.Router.
//!
//! Loads configuration from CLI arguments, environment variables, and `.lenv`
//! files via `lino-arguments` (a `clap` drop-in). The struct returned here is
//! the canonical runtime config used by the rest of the crate.

// `Config` and `BuildArgs` carry one bool per documented feature toggle
// (`enable_openai_api`, `enable_anthropic_api`, ...). Collapsing them into
// enums would diverge from the CLI/env variable names that ship as public API.
#![allow(clippy::struct_excessive_bools)]

use std::net::{IpAddr, SocketAddr, ToSocketAddrs as _};
use std::path::PathBuf;
use std::str::FromStr;
use std::time::Duration;

use crate::accounts::SelectionStrategy;
use crate::subscription::SubscriptionProvider;

/// Deliberate request-body ceiling for proxied traffic. This is independent
/// of the smaller amount retained in the diagnostic request log.
pub const DEFAULT_MAX_PROXY_REQUEST_BYTES: usize = 64 * 1024 * 1024;

/// Supported upstream inference providers.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum UpstreamProvider {
    /// Automatically route requests across every healthy vendor subscription.
    #[default]
    Auto,
    /// Anthropic via Claude MAX OAuth credentials.
    Anthropic,
    /// Gonka OpenAI-compatible inference provider.
    Gonka,
    /// Crater `ForgeFed` task provider.
    Crater,
    /// `OpenAI` Codex / `ChatGPT` subscription via `~/.codex` OAuth credentials.
    Codex,
    /// Google Gemini Code Assist subscription via `~/.gemini` OAuth credentials.
    Gemini,
    /// Alibaba Qwen subscription via `~/.qwen` OAuth credentials (`DashScope`).
    Qwen,
    /// Generic OpenAI-compatible inference provider, including `LiteLLM` proxy.
    OpenAICompatible,
    /// Policy-gated personal z.ai GLM Coding Plan credential.
    ZaiCodingPlan,
}

impl UpstreamProvider {
    /// Parse a provider from a free-form string.
    #[must_use]
    pub fn from_str_opt(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "auto" | "all" => Some(Self::Auto),
            "anthropic" | "claude" => Some(Self::Anthropic),
            "gonka" => Some(Self::Gonka),
            "crater" | "forgefed" => Some(Self::Crater),
            "codex" | "chatgpt" | "openai-codex" => Some(Self::Codex),
            "gemini" | "google" | "code-assist" => Some(Self::Gemini),
            "qwen" | "qwen-code" | "dashscope" => Some(Self::Qwen),
            "openai" | "openai-compatible" | "openai_like" | "litellm" => {
                Some(Self::OpenAICompatible)
            }
            "z.ai-coding-plan" | "zai-coding-plan" => Some(Self::ZaiCodingPlan),
            _ => None,
        }
    }

    /// The subscription provider backing this upstream, when it is one of the
    /// vendor-subscription providers (Claude/Codex/Gemini/Qwen).
    #[must_use]
    pub const fn subscription_provider(self) -> Option<crate::subscription::SubscriptionProvider> {
        use crate::subscription::SubscriptionProvider as S;
        match self {
            Self::Anthropic => Some(S::Claude),
            Self::Codex => Some(S::Codex),
            Self::Gemini => Some(S::Gemini),
            Self::Qwen => Some(S::Qwen),
            Self::Auto
            | Self::Gonka
            | Self::Crater
            | Self::OpenAICompatible
            | Self::ZaiCodingPlan => None,
        }
    }

    /// Canonical lowercase name, used in logs, metrics, and audit records.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::Anthropic => "anthropic",
            Self::Gonka => "gonka",
            Self::Crater => "crater",
            Self::Codex => "codex",
            Self::Gemini => "gemini",
            Self::Qwen => "qwen",
            Self::OpenAICompatible => "openai-compatible",
            Self::ZaiCodingPlan => "z.ai-coding-plan",
        }
    }
}

/// Supported upstream API formats accepted by the router.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ApiFormat {
    /// Anthropic Messages API (`/v1/messages`).
    Anthropic,
    /// Amazon Bedrock `InvokeModel` API (`/invoke`).
    Bedrock,
    /// Google Vertex AI rawPredict API (`:rawPredict`).
    Vertex,
}

impl ApiFormat {
    /// Parse a format from a free-form string.
    #[must_use]
    pub fn from_str_opt(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "anthropic" | "messages" => Some(Self::Anthropic),
            "bedrock" | "invoke" => Some(Self::Bedrock),
            "vertex" | "rawpredict" => Some(Self::Vertex),
            _ => None,
        }
    }
}

/// Routing mode controlling how upstream requests are handled.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum RoutingMode {
    /// Forward HTTP requests directly to Anthropic / Bedrock / Vertex.
    #[default]
    Direct,
    /// Drive a local Claude Code CLI subprocess for tool-heavy compatibility.
    Cli,
    /// Try `Direct` first and fall back to `Cli` for routes that need it.
    Hybrid,
}

impl RoutingMode {
    /// Parse a mode from a free-form string.
    #[must_use]
    pub fn from_str_opt(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "direct" => Some(Self::Direct),
            "cli" | "subprocess" => Some(Self::Cli),
            "hybrid" | "auto" => Some(Self::Hybrid),
            _ => None,
        }
    }
}

impl FromStr for RoutingMode {
    type Err = ConfigError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Self::from_str_opt(s).ok_or(ConfigError::InvalidRoutingMode)
    }
}

/// Storage policy for token persistence.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum StoragePolicy {
    /// Use only the in-memory store (no persistence; tests / ephemeral runs).
    Memory,
    /// Persist to a Lino-encoded text file.
    Text,
    /// Persist to a binary file (length-prefixed records, link-cli compatible
    /// when the `clink` adapter is enabled).
    Binary,
    /// Dual-write to both text and binary (default per issue #7).
    #[default]
    Both,
}

impl StoragePolicy {
    /// Parse a policy from a free-form string.
    #[must_use]
    pub fn from_str_opt(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "memory" | "mem" | "none" => Some(Self::Memory),
            "text" | "lino" => Some(Self::Text),
            "binary" | "bin" | "link-cli" | "linkcli" | "clink" => Some(Self::Binary),
            "both" | "dual" => Some(Self::Both),
            _ => None,
        }
    }
}

/// Router configuration — assembled from CLI args, env vars, and `.lenv`.
#[derive(Clone)]
pub struct Config {
    /// Address and port to bind the server to.
