        || name.ends_with("_private_key")
        || name.ends_with("_bot_token")
        || matches!(
            name,
            "token"
                | "admin_key"
                | "provider_key"
                | "env"
                | "admin_token"
                | "token_secret"
                | "token_admin_key"
                | "api_key"
                | "openai_api_key"
                | "openai_compatible_api_key"
                | "github_token"
                | "anthropic_api_key"
                | "refresh_token"
                | "access_token"
        )
}

mod generated;
/// Offline CLI and HTTP contract validators.
pub mod validation;

//! Offline validation shared by downstream callers and contract tests.
use serde_json::Value;
use std::collections::BTreeMap;
use std::sync::{Arc, LazyLock, Mutex};

static VALIDATORS: LazyLock<Mutex<BTreeMap<String, Arc<jsonschema::Validator>>>> =
    LazyLock::new(|| Mutex::new(BTreeMap::new()));

fn validate(key: &crate::translation_core::Str, schema: &crate::translation_core::Json, document: &crate::translation_core::Json) -> crate::translation_core::Outcome<(), String> {
    let validator = {
        let mut validators = VALIDATORS.lock().map_err(|_| "contract cache poisoned")?;
        if let Some(validator) = validators.get(key) {
            validator.clone()
        } else {
            let validator =
                Arc::new(jsonschema::draft202012::new(schema).map_err(|error| error.to_string())?);
            validators.insert(key.into(), validator.clone());
            validator
        }
    };
    validator
        .validate(document)
        .map_err(|error| error.to_string())
}

/// Validate the complete versioned CLI result, including operation-owned fields.
pub fn operation(name: &crate::translation_core::Str, document: &crate::translation_core::Json) -> crate::translation_core::Outcome<(), String> {
    let (_, schema) = super::generated::CLI_SCHEMAS
        .iter()
        .find(|(operation, _)| *operation == name)
        .ok_or_else(|| crate::translation_core::format!("undocumented operation {name}"))?;
    let schema = serde_json::from_str(schema).map_err(|error| error.to_string())?;
    validate(name, &schema, document)
}

/// Validate an HTTP JSON response against the served route's published schema.
/// Vendor-defined model payloads deliberately permit native extensions.
pub fn http(
    method: &axum::http::Method,
    path: &crate::translation_core::Str,
    status: u16,
    document: &crate::translation_core::Json,
) -> crate::translation_core::Outcome<(), String> {
    let route = crate::route_contract::route_for_path(method, path)
        .ok_or_else(|| crate::translation_core::format!("undocumented HTTP route {method} {path}"))?;
    let spec: Value =
        serde_json::from_str(super::generated::HTTP).map_err(|error| error.to_string())?;
    let template = route.template.replace("{*", "{");
    let mut operation = &spec["paths"][&template][method.as_str().to_lowercase()];
    if method == axum::http::Method::CONNECT {
        operation = &spec["x-router-any-methods"][&template]["connect"];
    } else if operation.is_null() && route.method == crate::route_contract::RouteMethod::Any {
        operation = spec["x-router-any-methods"][&template]["$ref"]
            .as_str()
            .and_then(|reference| reference.strip_prefix('#'))
            .and_then(|pointer| spec.pointer(pointer))
            .ok_or_else(|| crate::translation_core::format!("undocumented catch-all response {method} {path}"))?;
    }
    let response = if status < 400 {
        &operation["responses"]["200"]
    } else {
        &operation["responses"]["default"]
    };
    let mut schema = response["content"]["application/json"]["schema"].clone();
    if schema.is_null() {
        return Err(crate::translation_core::format!(
            "undocumented JSON response {method} {path} ({status})"
        ));
    }
    schema["components"] = spec["components"].clone();
    validate(
        &crate::translation_core::format!("http:{method}:{template}:{}", status < 400),
        &schema,
        document,
    )
}

/// Validate and decode a CLI payload while keeping the caller's exit handling.
/// Pre-versioned reports are accepted for interoperating with older deployments.
pub fn cli_payload<T: serde::de::DeserializeOwned>(bytes: &[u8]) -> Result<T, String> {
    let value: Value = serde_json::from_slice(bytes).map_err(|error| error.to_string())?;
    let data = if let Some(name) = value.get("operation").and_then(Value::as_str) {
        operation(name, &value)?;
        value["data"].clone()
    } else {
        value
    };
    serde_json::from_value(data).map_err(|error| error.to_string())
}

/// Test/diagnostic middleware validating JSON before a client receives it.
/// Streaming bodies retain their native framing and are tested separately.
pub async fn response_contract(
    request: axum::extract::Request,
    next: axum::middleware::Next,
) -> axum::response::Response {
    let method = request.method().clone();
    let path = request.uri().path().to_owned();
    let response = next.run(request).await;
    // Explicit test-only handlers are not part of the served Router surface.
    if method == axum::http::Method::HEAD
        || method == axum::http::Method::CONNECT && response.status().is_success()
        || path.starts_with("/test/")
        || response.status().as_u16() == 404
            && crate::route_contract::route_for_path(&method, &path).is_none()
        || !response
            .headers()
            .get(axum::http::header::CONTENT_TYPE)
            .is_some_and(|value| value.as_bytes().starts_with(b"application/json"))
    {
        return response;
    }
    let (parts, body) = response.into_parts();
    let bytes = axum::body::to_bytes(body, 16 * 1024 * 1024)
        .await
        .expect("bounded contract response");
    let document: Value = serde_json::from_slice(&bytes).expect("HTTP JSON contract");
    http(&method, &path, parts.status.as_u16(), &document)
        .unwrap_or_else(|error| panic!("HTTP contract {method} {path}: {error}"));
    axum::response::Response::from_parts(parts, axum::body::Body::from(bytes))
}

//! Opt-in recording of client-to-Router conversations, and strict replay of one.
//!
//! # Why this exists
//!
//! Before this, the only end-to-end evidence that a whole client conversation
//! still behaved the same after a Router upgrade was an integration test
//! against a live model: it spent real subscription tokens, needed a credential,
//! and therefore could not run in CI. Everything cheaper was a unit test against
//! Router's own code, which is exactly the layer that kept passing while
//! presentation defaults, capability advertisement, model pinning and tool-loop
//! translation each regressed in a real multi-turn exchange (issue #566).
//!
//! # The two modes
//!
//! * **Record** (`CONVERSATION_RECORD=<path>`) appends every client exchange —
//!   request and response, streamed events in the order the client received
//!   them — to a links-notation file. It observes the response stream that is
//!   already flowing to the client and issues no request of its own, so a
//!   recorded run costs exactly what the same run costs unrecorded.
//! * **Replay** (`CONVERSATION_REPLAY=<path>`) answers from that file instead of
//!   a provider, and *only* if the incoming request matches the recorded request
//!   at that position. A request that does not match fails the replay naming the
//!   turn and the difference, which is what makes a recording a test of the
//!   whole ordered exchange rather than a fixture that answers anything.
//!
//! Neither is on unless its variable is set, and both announce themselves in the
//! run's output: a mode that silently rewrites what a deployment answers with
//! must not be inferable only from a file appearing on disk.
//!
//! # Where it sits
//!
//! Replay is layered *outside* every other middleware, so a replayed turn never
//! reaches routing, provider selection, credential loading or the upstream
//! client. That is what lets a machine with no subscription at all run a replay:
//! there is nothing left in the path that could want a credential.
//!
//! # Secrets
//!
//! Redaction happens on the way in, not on the way out, reusing the request
//! log's [`crate::request_log::redacted_headers`] and
//! [`crate::request_log::redacted_body`]. A recording is meant to be committed
//! next to the test that uses it, so the bytes that reach the file must already
//! be safe; redacting at read time would leave the credential on disk.

mod matching;
mod store;

use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use axum::body::Body;
use axum::extract::{Request, State};
use axum::http::{HeaderMap, HeaderName, HeaderValue, StatusCode};
use axum::middleware::Next;
use axum::response::Response;
use futures_util::StreamExt as _;
use serde_json::{Value, json};

use crate::request_log::{redacted_body, redacted_headers};

pub use store::{LoadError, Provenance, Recording, Turn};

/// Environment variable that turns recording on and says where to write.
pub const RECORD_ENV: &crate::translation_core::Str = "CONVERSATION_RECORD";
/// Environment variable that turns replay on and says what to replay.
pub const REPLAY_ENV: &crate::translation_core::Str = "CONVERSATION_REPLAY";

/// Response header naming the turn a replayed answer came from.
///
/// A replay test that passes should still be able to prove *what* it exercised;
/// without this the only evidence is that some 200 came back.
pub const REPLAY_TURN_HEADER: &crate::translation_core::Str = "x-router-replay-turn";

/// Headers a replayed response must not repeat from the recording.
///
/// The recorded body is re-framed by this server, so the recorded framing would
/// contradict the bytes actually sent — a stale `content-length` truncates the
/// answer and a recorded `transfer-encoding` collides with the one Axum writes.
const REFRAMED_HEADERS: &[&crate::translation_core::Str] = &["content-length", "transfer-encoding", "connection", "date"];

/// Whether either mode is on, and with which file.
#[derive(Clone, Debug)]
pub enum Mode {
    /// Neither variable is set: the live path is untouched.
    Off,
    /// Append every client exchange to this file.
    Record(PathBuf),
    /// Answer from this file, failing on the first request that does not match.
    Replay(PathBuf),
}

impl Mode {
    /// Read the mode from the environment.
    ///
    /// Recording wins if both are set, because a run that both recorded and
    /// replayed would overwrite its own evidence with a copy of itself.
    #[must_use]
    pub fn from_env() -> Self {
        Self::from_values(
            crate::operation_context::var(RECORD_ENV).ok().as_deref(),
            crate::operation_context::var(REPLAY_ENV).ok().as_deref(),
        )
    }

    /// Resolve the mode from the two variables' values.
    #[must_use]
    pub fn from_values(record: crate::translation_core::Maybe<&crate::translation_core::Str>, replay: crate::translation_core::Maybe<&crate::translation_core::Str>) -> Self {
        let record = record.map(str::trim).filter(|value| !value.is_empty());
        let replay = replay.map(str::trim).filter(|value| !value.is_empty());
        match (record, replay) {
            (Some(path), _) => Self::Record(PathBuf::from(path)),
            (None, Some(path)) => Self::Replay(PathBuf::from(path)),
            (None, None) => Self::Off,
        }
    }

    /// Whether this mode answers from a recording.
    #[must_use]
    pub const fn is_replay(&self) -> bool {
        matches!(self, Self::Replay(_))
    }

    /// The line announcing this mode in the run's output, if it is on.
    ///
    /// Issue #566 requires the mode to be visible rather than silent: a
    /// deployment answering from a file instead of a provider is a fact an
    /// operator reading the log must be told, not one they have to deduce.
    #[must_use]
    pub fn announcement(&self) -> crate::translation_core::Maybe<String> {
        match self {
            Self::Off => None,
            Self::Record(path) => Some(format!(
                "Conversation recording enabled: appending client exchanges as links notation to {}",
                path.display()
            )),
            Self::Replay(path) => Some(format!(
                "Conversation replay enabled: answering from {} with no upstream call; \
                 a request that does not match the recording fails the turn",
                path.display()
            )),
        }
    }
}

/// Live state of one recording or replay, shared by every request.
#[derive(Debug)]
pub struct Session {
    /// Where the recording lives.
    path: PathBuf,
    /// Turns to serve, empty while recording.
    turns: Vec<Turn>,
    /// Position in the conversation, shared across concurrent requests.
    ///
    /// A conversation is sequential by nature, but nothing stops a client from
    /// having two requests in flight; a single counter keeps the file's order
    /// authoritative instead of letting arrival order decide it.
    position: Mutex<usize>,
    /// Whether the header line has been written yet, while recording.
    header_written: Mutex<bool>,
    /// What produced the recording being written, or the one being replayed.
    provenance: Provenance,
    /// Whether this session replays rather than records.
    replaying: bool,
}

impl Session {
    /// Open a recording session, writing nothing until the first exchange.
    #[must_use]
    pub const fn recording(path: PathBuf, provenance: Provenance) -> Self {
        Self {
            path,
            turns: Vec::new(),
            position: Mutex::new(0),
            header_written: Mutex::new(false),
            provenance,
            replaying: false,
        }
    }

    /// Load a recording for replay.
    ///
    /// # Errors
    /// Propagates [`LoadError`] when the file is unreadable or has no header.
    pub fn replaying(path: PathBuf) -> crate::translation_core::Outcome<Self, LoadError> {
        let recording = store::load(&path)?;
        Ok(Self {
            path,
            turns: recording.turns,
            position: Mutex::new(0),
            header_written: Mutex::new(true),
            provenance: recording.provenance,
            replaying: true,
        })
    }

    /// Build the session a [`Mode`] calls for.
    ///
    /// # Errors
    /// Propagates a replay load failure; recording cannot fail here because the
    /// file is created on the first exchange.
    pub fn from_mode(mode: &Mode, provider: &crate::translation_core::Str) -> crate::translation_core::Outcome<crate::translation_core::Maybe<Self>, LoadError> {
        match mode {
            Mode::Off => Ok(None),
            Mode::Record(path) => Ok(Some(Self::recording(
                path.clone(),
                Provenance {
                    router_version: crate::VERSION.to_string(),
                    provider: provider.to_string(),
                },
            ))),
            Mode::Replay(path) => Self::replaying(path.clone()).map(Some),
        }
    }

    /// What produced this recording.
    #[must_use]
    pub const fn provenance(&self) -> &Provenance {
        &self.provenance
    }

    /// How many turns a replay has to serve.
    #[must_use]
    pub const fn turn_count(&self) -> usize {
        self.turns.len()
    }

    /// Take the next position to serve or write, one-based.
    fn take_position(&self) -> usize {
        let mut position = self.position.lock().unwrap_or_else(|error| {
            // A poisoned counter would otherwise abort the process; the
            // recording is evidence, not a critical path.
            self.position.clear_poison();
            error.into_inner()
        });
        *position += 1;
        *position
    }

    /// Append one exchange to the recording file.
    fn write_turn(&self, turn: &Turn) {
        let mut written = self.header_written.lock().unwrap_or_else(|error| {
            self.header_written.clear_poison();
            error.into_inner()
        });
        if !*written {
            if let Err(error) =
                store::append_line(&self.path, &store::header_line(&self.provenance))
            {
                tracing::warn!("conversation recording header could not be written: {error}");
                return;
            }
            *written = true;
        }
        drop(written);
        if let Err(error) = store::append_line(&self.path, &store::turn_line(turn)) {
            tracing::warn!("conversation recording turn could not be written: {error}");
        }
    }
}

/// The recorded shape of one client request.
///
/// Redacted here, at record time, so the value that reaches the file and the
/// value replay compares against are the same thing: a matcher that compared
/// unredacted requests against redacted recordings would fail every replay on
/// the credential alone.
///
/// The URI is redacted by [`crate::request_log::safe_http_uri`], which strips a
/// credential passed as a query parameter — `?key=…` is how Gemini authenticates
/// — and reduces a byte-transparent native vendor route to its static template.
/// Both sides of a replay comparison go through it, so the reduction costs the
/// match nothing while keeping the recording committable.
fn recorded_request(
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    headers: &HeaderMap,
    body: &[u8],
    declared_body: bool,
) -> crate::translation_core::Json {
    crate::translation_core::json!({
        "method": method.as_str(),
        "uri": crate::request_log::safe_http_uri(method, uri),
        "headers": redacted_headers(headers),
        // A bodiless GET records `null` rather than `""`, so the absence of a
        // body is not confused with an empty one on replay.
        "body": if declared_body || !body.is_empty() { redacted_body(body) } else { Value::Null },
    })
}

/// Whether the client's headers claim a body accompanied the request.
fn declares_a_body(headers: &HeaderMap) -> bool {
    headers
        .get("content-length")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse::<u64>().ok())
        .is_some_and(|length| length > 0)
        || headers
            .get("transfer-encoding")
            .and_then(|value| value.to_str().ok())
            .is_some_and(|value| value.to_ascii_lowercase().contains("chunked"))
}

/// Largest client request body a recording will hold, per exchange (10 MiB).
///
/// The same bound the request log applies, for the same reason: a recording
/// must not let one caller make the router buffer without limit.
const MAX_RECORDED_BODY: usize = 10 * 1024 * 1024;

/// Wrap `app` in record-or-replay, or return it untouched when no mode is on.
///
/// The layer is *absent* rather than inert when both variables are unset: issue
/// #566 requires the live path to behave exactly as it did before this existed,
/// and a middleware that runs and decides to do nothing still buffers the
/// request body it needs in order to compare one.
///
/// Outermost, deliberately. A replayed turn must not reach routing, provider
/// selection, credential loading or the upstream client — that is what lets a
/// machine holding no subscription at all serve a replay.
pub fn layer(app: axum::Router, session: crate::translation_core::Maybe<Arc<Session>>) -> axum::Router {
    match session {
        None => app,
        Some(session) => app.layer(axum::middleware::from_fn_with_state(
            session,
            record_or_replay,
        )),
    }
}

/// Middleware that records or replays the client exchange.
pub async fn record_or_replay(
    State(session): State<Arc<Session>>,
    request: Request,
    next: Next,
) -> Response {
    let (parts, body) = request.into_parts();
    let declared_body = declares_a_body(&parts.headers);
    let Ok(bytes) = axum::body::to_bytes(body, MAX_RECORDED_BODY).await else {
        return crate::api_error::error_response(
            StatusCode::PAYLOAD_TOO_LARGE,
            "invalid_request_error",
            "request body exceeds the bounded conversation recording limit",
        );
    };
    let recorded = recorded_request(
        &parts.method,
        &parts.uri,
        &parts.headers,
        &bytes,
        declared_body,
    );
    let position = session.take_position();
    if session.replaying {
        return replay_turn(&session, position, &recorded);
    }
    let request = Request::from_parts(parts, Body::from(bytes));
    record_turn(session, position, recorded, next.run(request).await)
}

/// Serve turn `position` from the recording, or fail naming the divergence.
fn replay_turn(session: &Arc<Session>, position: usize, incoming: &crate::translation_core::Json) -> Response {
    let Some(turn) = session.turns.get(position - 1) else {
        return replay_failure(&format!(
            "replay exhausted: the recording {} holds {} turn(s) and the client asked for turn {}",
            session.path.display(),
            session.turns.len(),
            position
        ));
    };
    if let Some(difference) = matching::describe_difference(&turn.request, incoming) {
        return replay_failure(&format!(
            "replay mismatch at turn {position} of {} (recorded by Router {} against provider {}): \
             {difference}",
            session.path.display(),
            session.provenance.router_version,
            session.provenance.provider
        ));
    }
    served_response(turn, position)
}

/// Rebuild the client-visible response of one recorded turn.
fn served_response(turn: &Turn, position: usize) -> Response {
    let status = StatusCode::from_u16(turn.status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let mut response = Response::builder().status(status);
    for (name, value) in &turn.headers {
        if REFRAMED_HEADERS.contains(&name.to_ascii_lowercase().as_str()) {
            continue;
        }
        if let (Ok(name), Ok(value)) = (
            HeaderName::try_from(name.as_str()),
            HeaderValue::from_str(value),
        ) {
            response = response.header(name, value);
        }
    }
    if let Ok(value) = HeaderValue::from_str(&position.to_string()) {
        response = response.header(REPLAY_TURN_HEADER, value);
    }
    // Concatenated, not re-chunked: the recording preserves event order, and an
    // SSE client reassembles frames from the byte stream regardless of where the
    // transport split them. Emitting each recorded event as its own frame would
    // assert a chunk boundary the original may not have had.
    let body = turn.events.concat();
    response
        .body(Body::from(body))
        .unwrap_or_else(|_| replay_failure(&format!("turn {position} could not be rebuilt")))
}

/// How a failed replay reaches the client.
///
/// A distinct status, not a plausible answer: a replay is a test, and the one
/// outcome worse than failing is passing with an invented response. The message
/// is the whole diagnosis, so it goes in the body *and* the router's log.
fn replay_failure(message: &crate::translation_core::Str) -> Response {
    tracing::error!("{message}");
    crate::api_error::error_response(
        StatusCode::BAD_GATEWAY,
        "conversation_replay_mismatch",
        message,
    )
}

/// Wrap the live response so the exchange lands in the recording.
///
/// The chunks are observed as they already flow to the client; nothing is
/// buffered to completion and no second request is made, which is what keeps a
/// recorded run's upstream traffic identical to an unrecorded one's.
fn record_turn(
    session: Arc<Session>,
    position: usize,
    request: crate::translation_core::Json,
    response: Response,
) -> Response {
    let (parts, body) = response.into_parts();
    let status = parts.status.as_u16();
    let headers = redacted_headers(&parts.headers)
        .into_iter()
        .collect::<Vec<_>>();
    // An absent content type is *not* treated as a stream here, which is where
    // this parts company with `request_log::is_streaming_media_type`: that
    // function answers about an upstream response known to be an inference turn,
    // while this layer sees every route on the listener.
    let streamed = parts
        .headers
        .get("content-type")
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| crate::request_log::is_streaming_media_type(Some(value)));
    let bytes = Arc::new(Mutex::new(Vec::new()));
    let collected = Arc::clone(&bytes);
    let finish = TurnRecorder {
        session,
        turn: Some(Turn {
            index: position,
            request,
            status,
            headers,
            events: Vec::new(),
        }),
        bytes,
        streamed,
    };
    let stream = body.into_data_stream().map(move |chunk| {
        // Holding the recorder inside the stream closure is what makes the turn
        // land when the stream ends *or* when the client disconnects mid-answer:
        // dropping the stream drops the recorder, which writes what it has.
        let _write_the_turn_when_the_stream_ends = &finish;
        if let Ok(bytes) = &chunk
            && let Ok(mut collected) = collected.lock()
        {
            collected.extend_from_slice(bytes);
        }
        chunk
    });
    Response::from_parts(parts, Body::from_stream(stream))
}

/// Split a recorded response body into the events the client saw.
///
/// The transport's chunk boundaries are *not* the event boundaries — a chunk may
/// end mid-frame and may even split a multi-byte scalar, which is why
/// `sse::push_blocks` exists — so the body is accumulated and cut on SSE frame
/// separators. That keeps the order the issue asks the recording to prove while
/// leaving each event a complete, readable, diffable line in the file (#566).
fn split_events(body: &[u8], streamed: bool) -> Vec<String> {
    if !streamed {
        return if body.is_empty() {
            Vec::new()
        } else {
            vec![String::from_utf8_lossy(body).into_owned()]
        };
    }
    let mut buffer = Vec::new();
    let mut events = crate::sse::push_blocks(&mut buffer, body)
        .into_iter()
        // The separator is dropped by the splitter and re-added here, so
        // concatenating the recorded events reproduces the original bytes.
        .map(|block| format!("{block}\n\n"))
        .collect::<Vec<_>>();
    if !buffer.is_empty() {
        // A stream cut mid-frame: the tail is kept as its own event rather than
        // discarded, so a recording of a truncated answer still replays as one.
        events.push(String::from_utf8_lossy(&buffer).into_owned());
    }
    events
}

/// Writes one turn once the response body has finished streaming.
struct TurnRecorder {
    session: Arc<Session>,
    turn: Option<Turn>,
    bytes: Arc<Mutex<Vec<u8>>>,
    streamed: bool,
}

impl Drop for TurnRecorder {
    fn drop(&mut self) {
        let Some(mut turn) = self.turn.take() else {
            return;
        };
        if let Ok(bytes) = self.bytes.lock() {
            turn.events = split_events(&bytes, self.streamed);
        }
        self.session.write_turn(&turn);
    }
}

#[cfg(test)]
#[path = "conversation_record_tests.rs"]
mod tests;

//! What "the same request" means on replay, and how a difference is named.
//!
//! Issue #566 makes strictness the point: a replay that answered any request
//! with the next recorded response would be a fixture server, and would pass
//! while a router change quietly dropped a field, reordered a tool result or
//! rewrote a system message. So the comparison is exact over everything the
//! recording holds — and when it fails it has to say *which* turn and *what*
//! differed, because "mismatch at turn 2" is the generic report the issue
//! explicitly rejects.
//!
//! Split from `conversation_record.rs` for the 1000-line limit.

use serde_json::Value;

/// Headers that legitimately differ between a recording and its replay.
///
/// These are transport bookkeeping, not conversation content: the framing of
/// the same body may differ, the host is whatever port the replay bound, and
/// the token in `authorization` is already redacted to a mask that a freshly
/// minted token would not reproduce. Comparing them would make every replay
/// fail for reasons that have nothing to do with the exchange under test.
const IGNORED_HEADERS: &[&crate::translation_core::Str] = &[
    "authorization",
    "content-length",
    "host",
    "proxy-authorization",
    "user-agent",
    "x-api-key",
    "x-request-id",
    "date",
    "cookie",
];

/// Fields of a recorded request that are compared.
///
/// `uri` and `method` identify the endpoint; `body` is the conversation. The
/// header map is compared separately so the report can name the header.
const COMPARED_FIELDS: &[&crate::translation_core::Str] = &["method", "uri"];

/// Whether a header name takes part in matching.
#[must_use]
pub fn header_is_compared(name: &crate::translation_core::Str) -> bool {
    !IGNORED_HEADERS.contains(&name.to_ascii_lowercase().as_str())
}

/// The first way `incoming` differs from `recorded`, described in English.
///
/// `None` means the two requests match. The description names a path into the
/// body — `body.messages[1].content[0].text` — so the turn that failed points
/// at the field that moved rather than at the whole request.
#[must_use]
pub fn describe_difference(recorded: &crate::translation_core::Json, incoming: &crate::translation_core::Json) -> crate::translation_core::Maybe<String> {
    for field in COMPARED_FIELDS {
        let expected = recorded.get(*field);
        let actual = incoming.get(*field);
        if expected != actual {
            return Some(format!(
                "{field}: recorded {}, received {}",
                render(expected),
                render(actual)
            ));
        }
    }
    if let Some(difference) = header_difference(recorded, incoming) {
        return Some(difference);
    }
    compare(
        "body",
        recorded.get("body").unwrap_or(&Value::Null),
        incoming.get("body").unwrap_or(&Value::Null),
    )
}

/// The first compared header that differs.
fn header_difference(recorded: &crate::translation_core::Json, incoming: &crate::translation_core::Json) -> crate::translation_core::Maybe<String> {
    let expected = recorded.get("headers").and_then(Value::as_object)?;
    let actual = incoming.get("headers").and_then(Value::as_object);
    for (name, value) in expected {
        if !header_is_compared(name) {
            continue;
        }
        let received = actual.and_then(|actual| actual.get(name));
        if received != Some(value) {
            return Some(format!(
                "header {name}: recorded {}, received {}",
                render(Some(value)),
                render(received)
            ));
        }
    }
    // A header the client added is as much a divergence as one it dropped: an
    // extra beta flag changes what the upstream is being asked for.
    let actual = actual?;
    actual
        .iter()
        .filter(|(name, _)| header_is_compared(name))
        .find(|(name, _)| !expected.contains_key(name.as_str()))
        .map(|(name, value)| {
            format!(
                "header {name}: absent from the recording, received {}",
                render(Some(value))
            )
        })
}

/// Walk two values in parallel and describe the first divergence at `path`.
fn compare(path: &crate::translation_core::Str, recorded: &crate::translation_core::Json, incoming: &crate::translation_core::Json) -> crate::translation_core::Maybe<String> {
    match (recorded, incoming) {
        (Value::Object(expected), Value::Object(actual)) => {
            for (key, value) in expected {
                let Some(received) = actual.get(key) else {
                    return Some(format!("{path}.{key} is missing from the request"));
                };
                if let Some(difference) = compare(&format!("{path}.{key}"), value, received) {
                    return Some(difference);
                }
            }
            actual
                .keys()
                .find(|key| !expected.contains_key(key.as_str()))
                .map(|key| format!("{path}.{key} is not in the recording"))
        }
        (Value::Array(expected), Value::Array(actual)) => {
            if expected.len() != actual.len() {
                return Some(format!(
                    "{path} has {} element(s), the recording has {}",
                    actual.len(),
                    expected.len()
                ));
            }
            expected
                .iter()
                .zip(actual)
                .enumerate()
                .find_map(|(index, (expected, actual))| {
                    compare(&format!("{path}[{index}]"), expected, actual)
                })
        }
        _ if recorded == incoming => None,
        _ => Some(format!(
            "{path}: recorded {}, received {}",
            render(Some(recorded)),
            render(Some(incoming))
        )),
    }
}

/// How long a value may be before a report abbreviates it.
///
/// A mismatch report goes to a test log and a terminal; a full system prompt
/// pasted into it buries the one field that moved.
const RENDERED_LIMIT: usize = 120;

/// Render a value for a mismatch report, abbreviated but never elided entirely.
fn render(value: crate::translation_core::Maybe<&crate::translation_core::Json>) -> String {
    let Some(value) = value else {
        return "nothing".to_string();
    };
    let text = match value {
        Value::String(text) => text.clone(),
        other => other.to_string(),
    };
    if text.chars().count() <= RENDERED_LIMIT {
        return format!("{text:?}");
    }
    let head: String = text.chars().take(RENDERED_LIMIT).collect();
    format!("{head:?}… ({} characters)", text.chars().count())
}

//! The recording file: links notation on disk, turns in memory.
//!
//! One record per line, written with [`crate::lino_json::encode_line`] and read
//! with [`crate::lino_json::decode_line`] — the same shape and the same codec
//! the per-token request log already uses, because a recording is appended to
//! while a conversation is still running and must survive a router that exits
//! mid-turn (issue #566). A partially written last line is dropped on read
//! rather than making the whole recording unloadable.
//!
//! Split from `conversation_record.rs` to keep both files inside the
//! repository's 1000-line limit.

use std::io::Write as _;
use std::path::{Path, PathBuf};

use serde_json::{Value, json};

/// First line of every recording: what produced it.
///
/// Issue #566 asks a recording to state its router version and its provider so
/// that a replay which no longer matches can be told apart from a recording
/// made against a different contract. Without it the only diagnosis available
/// for a failing replay is "something changed", which is the failure mode the
/// strict matching exists to avoid.
pub const HEADER_PHASE: &crate::translation_core::Str = "recording";
/// Phase marking one complete client exchange.
pub const TURN_PHASE: &crate::translation_core::Str = "turn";

/// What produced a recording.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Provenance {
    /// Router version that recorded the conversation.
    pub router_version: String,
    /// Upstream provider that answered it.
    pub provider: String,
}

/// One complete client-to-Router exchange.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Turn {
    /// One-based position in the conversation, as named in a mismatch report.
    pub index: usize,
    /// The redacted client request, matched against on replay.
    pub request: Value,
    /// The response status the client saw.
    pub status: u16,
    /// Response headers, redacted, replayed verbatim apart from framing.
    pub headers: Vec<(String, String)>,
    /// Response body chunks in the order the client received them.
    ///
    /// A streamed answer is a sequence of SSE events and their order is part of
    /// what the recording proves; collapsing them into one blob would let a
    /// reordering regression replay clean (issue #566).
    pub events: Vec<String>,
}

/// A recording loaded from disk, ready to replay.
#[derive(Clone, Debug)]
pub struct Recording {
    /// What produced it.
    pub provenance: Provenance,
    /// Its turns, in order.
    pub turns: Vec<Turn>,
}

/// Why a recording could not be loaded.
#[derive(Debug)]
pub enum LoadError {
    /// The file could not be read.
    Unreadable(std::io::Error),
    /// The file holds no `recording` header line.
    MissingHeader,
}

impl std::fmt::Display for LoadError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Unreadable(error) => write!(formatter, "recording could not be read: {error}"),
            Self::MissingHeader => formatter
                .write_str("recording has no header line stating the router version and provider"),
        }
    }
}

impl std::error::Error for LoadError {}

/// Encode the header line for a new recording.
#[must_use]
pub fn header_line(provenance: &Provenance) -> String {
    encode(&json!({
        "phase": HEADER_PHASE,
        "router_version": provenance.router_version,
        "provider": provenance.provider,
    }))
}

/// Encode one turn as a single line of links notation.
#[must_use]
pub fn turn_line(turn: &Turn) -> String {
    encode(&json!({
        "phase": TURN_PHASE,
        "turn": turn.index,
        "request": turn.request,
        "response": {
            "status": turn.status,
            "headers": turn
                .headers
                .iter()
                .map(|(name, value)| json!([name, value]))
                .collect::<Vec<_>>(),
            "events": turn.events,
        },
    }))
}

/// Encode one record, falling back to nothing a reader would misread.
///
/// `encode_line` fails only when a value cannot become JSON, which cannot
/// happen for the `json!` literals above; an empty line is skipped on read, so
/// even that impossible case cannot corrupt the file.
fn encode(value: &crate::translation_core::Json) -> String {
    crate::lino_json::encode_line(value).unwrap_or_default()
}

/// Append one already-encoded line to the recording file.
///
/// # Errors
/// Propagates any failure to create the parent directory or append the line.
pub fn append_line(path: &Path, line: &crate::translation_core::Str) -> std::io::Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)?;
    }
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)?;
    file.write_all(line.as_bytes())?;
    file.write_all(b"\n")
}

/// Read a recording back from disk.
///
/// # Errors
/// Returns [`LoadError`] when the file cannot be read or carries no header.
pub fn load(path: &PathBuf) -> crate::translation_core::Outcome<Recording, LoadError> {
    let text = std::fs::read_to_string(path).map_err(LoadError::Unreadable)?;
    let mut provenance = None;
    let mut turns = Vec::new();
    for line in text.lines() {
        // A line this reader cannot decode is a torn tail from a router that
        // exited mid-write, not a reason to discard the turns before it.
        let Some(record) = crate::lino_json::decode_line(line) else {
            continue;
        };
        match record.get("phase").and_then(crate::translation_core::Json::as_str) {
            Some(HEADER_PHASE) => provenance = Some(read_provenance(&record)),
            Some(TURN_PHASE) => {
                if let Some(turn) = read_turn(&record, turns.len() + 1) {
                    turns.push(turn);
                }
            }
            _ => {}
        }
    }
    provenance
        .map(|provenance| Recording { provenance, turns })
        .ok_or(LoadError::MissingHeader)
}

fn read_provenance(record: &crate::translation_core::Json) -> Provenance {
    Provenance {
        router_version: string_field(record, "router_version"),
        provider: string_field(record, "provider"),
    }
}

fn string_field(record: &crate::translation_core::Json, name: &crate::translation_core::Str) -> String {
    record
        .get(name)
        .and_then(crate::translation_core::Json::as_str)
        .unwrap_or("unknown")
        .to_string()
}

/// Read one turn, renumbering it by position.
///
/// The recorded `turn` field is informational: replay counts positions itself,
/// so a hand-edited recording with a wrong number still replays in file order
/// rather than silently skipping or repeating an exchange.
fn read_turn(record: &crate::translation_core::Json, position: usize) -> crate::translation_core::Maybe<Turn> {
    let request = record.get("request")?.clone();
    let response = record.get("response")?;
    let status = u16::try_from(response.get("status")?.as_u64()?).ok()?;
    let headers = response
        .get("headers")
        .and_then(crate::translation_core::Json::as_array)
        .map(|pairs| {
            pairs
                .iter()
                .filter_map(|pair| {
                    let pair = pair.as_array()?;
                    Some((
                        pair.first()?.as_str()?.to_string(),
                        pair.get(1)?.as_str()?.to_string(),
                    ))
                })
                .collect()
        })
        .unwrap_or_default();
    let events = response
        .get("events")
        .and_then(crate::translation_core::Json::as_array)
        .map(|events| {
            events
                .iter()
                .filter_map(|event| event.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();
    Some(Turn {
        index: position,
        request,
        status,
        headers,
        events,
    })
}

//! Authenticated native `OpenAI` Conversations and conversation-items lifecycle.

use axum::body::{Body, Bytes};
use axum::extract::{OriginalUri, Path, Request, State};
use axum::http::{HeaderMap, Method, StatusCode, Uri};
use axum::response::{IntoResponse, Response};
use futures_util::StreamExt;

use crate::app_state::AppState;
use crate::response_affinity::{
    AffinityDestination, ResponseAffinity, ResponseNamespace, ResponseOwner,
};

struct Forwarded {
    status: StatusCode,
    headers: HeaderMap,
    body: Bytes,
}

pub async fn create(
    State(state): State<AppState>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    let (claims, owner) = match authenticate(&state, request.headers()) {
        Ok(authenticated) => authenticated,
        Err(response) => return response,
    };
    let Some((conversation_namespace, _)) = ResponseNamespace::conversations_from_path(uri.path())
    else {
        return conversation_not_found();
    };
    if conversation_namespace == ResponseNamespace::QwenConversations {
        return unsupported();
    }
    let destination = match crate::resource_capture::destination_for_claims(&state, &claims).await {
        Ok(destination) if destination_matches(conversation_namespace, &destination) => destination,
        Ok(_) => return unsupported(),
        Err(response) => return response,
    };
    let (parts, body) = request.into_parts();
    let body = match bounded_request_body(&state, body).await {
        Ok(body) => body,
        Err(response) => return response,
    };
    let upstream_path = with_query("/v1/conversations", &uri);
    let forwarded = match forward(
        &state,
        &claims,
        &parts.method,
        &parts.headers,
        &body,
        uri.path(),
        &upstream_path,
        &destination,
    )
    .await
    {
        Ok(forwarded) => forwarded,
        Err(response) => return response,
    };
    if forwarded.status.is_success() {
        let Some(conversation_id) = root_id(&forwarded.body) else {
            return upstream_error("conversation create response did not contain an id");
        };
        if let Err(error) = state.provider_store.response_affinities().record(
            conversation_namespace,
            &conversation_id,
            owner,
            destination,
        ) {
            return affinity_error(&error);
        }
    }
    native_response(forwarded)
}

pub async fn conversation(
    State(state): State<AppState>,
    Path(conversation_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    let (claims, owner) = match authenticate(&state, request.headers()) {
        Ok(authenticated) => authenticated,
        Err(response) => return response,
    };
    let Some((conversation_namespace, item_namespace)) =
        ResponseNamespace::conversations_from_path(uri.path())
    else {
        return conversation_not_found();
    };
    if conversation_namespace == ResponseNamespace::QwenConversations {
        return unsupported();
    }
    let affinity = match lookup(
        &state,
        conversation_namespace,
        &conversation_id,
        &owner,
        conversation_not_found,
    ) {
        Ok(affinity) => affinity,
        Err(response) => return response,
    };
    if !matches!(
        request.method(),
        &Method::GET | &Method::PATCH | &Method::DELETE
    ) {
        return method_not_allowed();
    }
    let (parts, body) = request.into_parts();
    let body = match bounded_request_body(&state, body).await {
        Ok(body) => body,
        Err(response) => return response,
    };
    let path = format!(
        "/v1/conversations/{}",
        crate::responses_lifecycle::percent_encode_segment(&conversation_id)
    );
    let forwarded = match forward(
        &state,
        &claims,
        &parts.method,
        &parts.headers,
        &body,
        uri.path(),
        &with_query(&path, &uri),
        &affinity.destination,
    )
    .await
    {
        Ok(forwarded) => forwarded,
        Err(response) => return response,
    };
    if matches!(forwarded.status, StatusCode::NOT_FOUND | StatusCode::GONE) {
        let _ = remove_conversation(&state, &affinity, item_namespace);
        return conversation_not_found();
    }
    if parts.method == Method::DELETE
        && forwarded.status.is_success()
        && let Err(response) = remove_conversation(&state, &affinity, item_namespace)
    {
        return response;
    }
    native_response(forwarded)
}

pub async fn items(
    State(state): State<AppState>,
    Path(conversation_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    let (claims, owner) = match authenticate(&state, request.headers()) {
        Ok(authenticated) => authenticated,
        Err(response) => return response,
    };
    let Some((conversation_namespace, item_namespace)) =
        ResponseNamespace::conversations_from_path(uri.path())
    else {
        return conversation_not_found();
    };
    if conversation_namespace == ResponseNamespace::QwenConversations {
        return unsupported();
    }
    let affinity = match lookup(
        &state,
        conversation_namespace,
        &conversation_id,
        &owner,
        conversation_not_found,
    ) {
        Ok(affinity) => affinity,
        Err(response) => return response,
    };
    if !matches!(request.method(), &Method::GET | &Method::POST) {
        return method_not_allowed();
    }
    let (parts, body) = request.into_parts();
    let body = match bounded_request_body(&state, body).await {
        Ok(body) => body,
        Err(response) => return response,
    };
    let path = format!(
        "/v1/conversations/{}/items",
        crate::responses_lifecycle::percent_encode_segment(&conversation_id)
    );
    let forwarded = match forward(
        &state,
        &claims,
        &parts.method,
        &parts.headers,
        &body,
        uri.path(),
        &with_query(&path, &uri),
        &affinity.destination,
    )
    .await
    {
        Ok(forwarded) => forwarded,
        Err(response) => return response,
    };
    if matches!(forwarded.status, StatusCode::NOT_FOUND | StatusCode::GONE) {
        let _ = remove_conversation(&state, &affinity, item_namespace);
        return conversation_not_found();
    }
    if forwarded.status.is_success() {
        for item_id in list_ids(&forwarded.body) {
            if let Err(error) = state.provider_store.response_affinities().record_child(
                item_namespace,
                &item_id,
                &conversation_id,
                owner.clone(),
                affinity.destination.clone(),
            ) {
                return affinity_error(&error);
            }
        }
    }
    native_response(forwarded)
}

pub async fn item(
    State(state): State<AppState>,
    Path((conversation_id, item_id)): Path<(String, String)>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    let (claims, owner) = match authenticate(&state, request.headers()) {
        Ok(authenticated) => authenticated,
        Err(response) => return response,
    };
    let Some((conversation_namespace, item_namespace)) =
        ResponseNamespace::conversations_from_path(uri.path())
    else {
        return item_not_found();
    };
    if conversation_namespace == ResponseNamespace::QwenConversations {
        return unsupported();
    }
    let conversation = match lookup(
        &state,
        conversation_namespace,
        &conversation_id,
        &owner,
        conversation_not_found,
    ) {
        Ok(affinity) => affinity,
        Err(response) => return response,
    };
    let item = match lookup(&state, item_namespace, &item_id, &owner, item_not_found) {
        Ok(affinity)
            if affinity.parent_id.as_deref() == Some(conversation_id.as_str())
                && affinity.destination == conversation.destination =>
        {
            affinity
        }
        Ok(_) => return item_not_found(),
        Err(response) => return response,
    };
    if !matches!(request.method(), &Method::GET | &Method::DELETE) {
        return method_not_allowed();
    }
    let (parts, body) = request.into_parts();
    let body = match bounded_request_body(&state, body).await {
        Ok(body) => body,
        Err(response) => return response,
    };
    let path = format!(
        "/v1/conversations/{}/items/{}",
        crate::responses_lifecycle::percent_encode_segment(&conversation_id),
        crate::responses_lifecycle::percent_encode_segment(&item_id)
    );
    let forwarded = match forward(
        &state,
        &claims,
        &parts.method,
        &parts.headers,
        &body,
        uri.path(),
        &with_query(&path, &uri),
        &item.destination,
    )
    .await
    {
        Ok(forwarded) => forwarded,
        Err(response) => return response,
    };
    if matches!(forwarded.status, StatusCode::NOT_FOUND | StatusCode::GONE) {
        let _ = state
            .provider_store
            .response_affinities()
            .remove_if_matches(&item);
        return item_not_found();
    }
    if parts.method == Method::DELETE
        && forwarded.status.is_success()
        && let Err(error) = state
            .provider_store
            .response_affinities()
            .remove_if_matches(&item)
    {
        return affinity_error(&error);
    }
    native_response(forwarded)
}

fn authenticate(
    state: &AppState,
    headers: &HeaderMap,
) -> crate::translation_core::Outcome<(crate::token::TokenClaims, ResponseOwner), Response> {
    let claims = crate::proxy::authenticate_client_error(state, headers)
        .map_err(|error| error.render(crate::api_error::ApiDialect::OpenAi))?;
    let owner = ResponseOwner::from_claims(&claims)
        .map_err(|error| openai_error(StatusCode::FORBIDDEN, "permission_error", &error))?;
    Ok((claims, owner))
}

const fn destination_matches(
    namespace: ResponseNamespace,
    destination: &AffinityDestination,
) -> bool {
    matches!(
        (namespace, destination),
        (
            ResponseNamespace::OpenAiConversations,
            AffinityDestination::StoredProvider {
                provider_kind: crate::providers::ProviderKind::OpenAICompatible,
                ..
            }
        ) | (
            ResponseNamespace::CodexConversations,
            AffinityDestination::Subscription {
                provider: crate::subscription::SubscriptionProvider::Codex,
                ..
            }
        )
    )
}

fn lookup(
    state: &AppState,
    namespace: ResponseNamespace,
    id: &str,
    owner: &ResponseOwner,
    missing: fn() -> Response,
) -> Result<ResponseAffinity, Response> {
    match state
        .provider_store
        .response_affinities()
        .lookup(namespace, id, owner)
    {
        Ok(Some(affinity)) => Ok(affinity),
        Ok(None) => Err(missing()),
        Err(error) => Err(affinity_error(&error)),
    }
}

#[allow(clippy::too_many_arguments)]
async fn forward(
    state: &AppState,
    claims: &crate::token::TokenClaims,
    method: &Method,
    headers: &HeaderMap,
    body: &Bytes,
    client_path: &crate::translation_core::Str,
    upstream_path: &crate::translation_core::Str,
    destination: &AffinityDestination,
) -> crate::translation_core::Outcome<Forwarded, Response> {
    let correlation_id = crate::request_log::correlation_id(headers);
    let (upstream, account) = match destination {
        AffinityDestination::StoredProvider {
            name,
            provider_kind,
            base_url,
        } => (
            crate::responses_lifecycle::forward_stored_provider(
                state,
                claims,
                method,
                headers,
                body,
                client_path,
                upstream_path,
                name,
                *provider_kind,
                base_url,
                &correlation_id,
            )
            .await?,
            None,
        ),
        AffinityDestination::Subscription {
            provider,
            account,
            upstream_account_id,
            base_url,
        } => (
            crate::responses_lifecycle::forward_subscription(
                state,
                claims,
                method,
                headers,
                body,
                client_path,
                upstream_path,
                *provider,
                account,
                upstream_account_id.as_deref(),
                base_url,
                &correlation_id,
            )
            .await?,
            Some(account.as_str()),
        ),
    };
    read_upstream(state, upstream, account, body.len() as u64, &correlation_id).await
}

async fn read_upstream(
    state: &AppState,
    upstream: reqwest::Response,
    account: crate::translation_core::Maybe<&crate::translation_core::Str>,
    bytes_sent: u64,
    correlation_id: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<Forwarded, Response> {
    let status = StatusCode::from_u16(upstream.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let headers = crate::proxy::relay_response_headers(upstream.headers());
    let mut stream = upstream.bytes_stream();
    let mut body = Vec::new();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk
            .map_err(|error| upstream_error(&format!("upstream body read failed: {error}")))?;
        if body.len().saturating_add(chunk.len()) > state.max_proxy_request_bytes {
            return Err(upstream_error("upstream response exceeds the proxy limit"));
        }
        body.extend_from_slice(&chunk);
    }
    state
        .request_log
        .record_upstream_body(correlation_id, &body);
    state.metrics.record_request(
        crate::metrics::Surface::OpenAIResponses,
        status.as_u16(),
        account,
    );
    state.metrics.record_bytes(bytes_sent, body.len() as u64);
    Ok(Forwarded {
        status,
        headers,
        body: Bytes::from(body),
    })
}

async fn bounded_request_body(state: &AppState, body: Body) -> crate::translation_core::Outcome<Bytes, Response> {
    axum::body::to_bytes(body, state.max_proxy_request_bytes)
        .await
        .map_err(|error| {
            openai_error(
                StatusCode::PAYLOAD_TOO_LARGE,
                "invalid_request_error",
                &format!("request body exceeds the proxy limit: {error}"),
            )
        })
}

fn remove_conversation(
    state: &AppState,
    affinity: &ResponseAffinity,
    item_namespace: ResponseNamespace,
) -> crate::translation_core::Outcome<(), Response> {
    let store = state.provider_store.response_affinities();
    store
        .remove_children(
            item_namespace,
            &affinity.response_id,
            &affinity.owner,
            &affinity.destination,
        )
        .map_err(|error| affinity_error(&error))?;
    store
        .remove_if_matches(affinity)
        .map_err(|error| affinity_error(&error))?;
    Ok(())
}

fn root_id(body: &[u8]) -> crate::translation_core::Maybe<String> {
    serde_json::from_slice::<serde_json::Value>(body)
        .ok()?
        .get("id")?
        .as_str()
        .filter(|id| !id.is_empty())
        .map(str::to_string)
}

fn list_ids(body: &[u8]) -> Vec<String> {
    serde_json::from_slice::<serde_json::Value>(body)
        .ok()
        .and_then(|value| {
            value
                .get("data")
                .and_then(crate::translation_core::Json::as_array)
                .cloned()
        })
        .unwrap_or_default()
        .into_iter()
        .filter_map(|item| {
            item.get("id")
                .and_then(crate::translation_core::Json::as_str)
                .map(str::to_string)
        })
        .filter(|id| !id.is_empty())
        .collect()
}

fn with_query(path: &crate::translation_core::Str, uri: &Uri) -> String {
    uri.query()
        .map_or_else(|| path.to_string(), |query| format!("{path}?{query}"))
}

fn native_response(forwarded: Forwarded) -> Response {
    let mut response = Response::new(Body::from(forwarded.body));
    *response.status_mut() = forwarded.status;
    *response.headers_mut() = forwarded.headers;
    response
}

fn conversation_not_found() -> Response {
    resource_not_found("Conversation", "conversation_not_found")
}

fn item_not_found() -> Response {
    resource_not_found("Conversation item", "conversation_item_not_found")
}

fn resource_not_found(message: &crate::translation_core::Str, code: &crate::translation_core::Str) -> Response {
    (
        StatusCode::NOT_FOUND,
        axum::Json(crate::translation_core::json!({
            "error": {
                "message": format!("{message} not found"),
                "type": "invalid_request_error",
                "param": serde_json::Value::Null,
                "code": code,
            }
        })),
    )
        .into_response()
}

fn unsupported() -> Response {
    openai_error(
        StatusCode::BAD_REQUEST,
        "invalid_request_error",
        "the selected service does not support native Conversations resources",
    )
}

fn method_not_allowed() -> Response {
    openai_error(
        StatusCode::METHOD_NOT_ALLOWED,
        "invalid_request_error",
        "the requested Conversations operation is not supported",
    )
}

fn affinity_error(error: &impl std::fmt::Display) -> Response {
    openai_error(
        StatusCode::SERVICE_UNAVAILABLE,
        "api_error",
        &format!("resource affinity is unavailable: {error}"),
    )
}

fn upstream_error(message: &crate::translation_core::Str) -> Response {
    openai_error(StatusCode::BAD_GATEWAY, "api_error", message)
}

fn openai_error(status: StatusCode, error_type: &crate::translation_core::Str, message: &crate::translation_core::Str) -> Response {
    crate::api_error::PresentedError {
        status,
        error_type,
        message,
    }
    .render(crate::api_error::ApiDialect::OpenAi)
}

