//! Durable fallback storage for refreshed subscription credentials.
//!
//! Vendor credential stores keep ownership of their JSON documents. This
//! decorator only serializes refreshes that could not reach that primary store
//! and reconciles them later, once the primary is writable again.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use sha2::{Digest as _, Sha256};

use crate::credential_store::CredentialStore;
use crate::subscription::{SubscriptionProvider, SubscriptionToken};

const RECOVERY_VERSION: u8 = 1;
const RECOVERY_DIRECTORY: &crate::translation_core::Str = "refresh-recovery";

/// Account name used by the configured, non-pooled credential homes.
pub const PRIMARY_ACCOUNT: &crate::translation_core::Str = "primary";

/// Maximum time a Router-owned writer waits for another credential transaction.
pub const CREDENTIAL_LOCK_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(5);

/// One provider/account lock shared by refresh, import, and native login.
///
/// The account is hashed so an email address or other operator-chosen account
/// label never appears in a filename.
#[must_use]
pub fn credential_lock_path(
    data_dir: impl AsRef<Path>,
    provider: SubscriptionProvider,
    account: impl AsRef<str>,
) -> PathBuf {
    let account_digest = hex::encode(Sha256::digest(account.as_ref().as_bytes()));
    data_dir
        .as_ref()
        .join(RECOVERY_DIRECTORY)
        .join(format!("{}-{account_digest}.lock", provider.as_str()))
}

fn recovery_record_path(
    data_dir: impl AsRef<Path>,
    provider: SubscriptionProvider,
    account: impl AsRef<str>,
) -> PathBuf {
    let account_digest = hex::encode(Sha256::digest(account.as_ref().as_bytes()));
    data_dir
        .as_ref()
        .join(RECOVERY_DIRECTORY)
        .join(format!("{}-{account_digest}.json", provider.as_str()))
}

#[derive(Debug, serde::Serialize, serde::Deserialize)]
struct RecoveryRecord {
    version: u8,
    provider: SubscriptionProvider,
    baseline_fingerprint: Option<String>,
    token: SubscriptionToken,
}

/// Return the matching durable recovery record while its transaction lock is
/// held. Invalid metadata and unreadable contents are storage uncertainty, so
/// both are surfaced rather than treated as absence and overwritten.
pub(crate) fn valid_recovery_record_path(
    data_dir: impl AsRef<Path>,
    provider: SubscriptionProvider,
    account: impl AsRef<str>,
) -> Result<Option<PathBuf>, String> {
    let path = recovery_record_path(data_dir, provider, account);
    let bytes = match std::fs::read(&path) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(_) => {
            return Err(format!(
                "the {provider} credential recovery record is unusable"
            ));
        }
    };
    let record = serde_json::from_slice::<RecoveryRecord>(&bytes)
        .map_err(|_| format!("the {provider} credential recovery record is unusable"))?;
    if record.version != RECOVERY_VERSION || record.provider != provider {
        return Err(format!(
            "the {provider} credential recovery record is unusable"
        ));
    }
    Ok(Some(path))
}

/// A credential store that falls back to the router's writable data directory.
#[derive(Debug)]
pub struct RecoverableCredentialStore {
    provider: SubscriptionProvider,
    primary: Arc<dyn CredentialStore>,
    recovery_path: PathBuf,
    lock_path: PathBuf,
}

impl RecoverableCredentialStore {
    /// Wrap `primary` with a recovery record and lock scoped to one account.
    #[must_use]
    pub fn new(
        provider: SubscriptionProvider,
        account: impl AsRef<str>,
        primary: Arc<dyn CredentialStore>,
        data_dir: impl AsRef<Path>,
    ) -> Self {
        Self {
            provider,
            primary,
            recovery_path: recovery_record_path(&data_dir, provider, &account),
            lock_path: credential_lock_path(data_dir, provider, account),
        }
    }

    fn fingerprint(token: &SubscriptionToken) -> String {
        hex::encode(crate::refresh::credential_fingerprint(token))
    }

    fn read_recovery(&self) -> crate::translation_core::Outcome<crate::translation_core::Maybe<RecoveryRecord>, String> {
        let bytes = match std::fs::read(&self.recovery_path) {
            Ok(bytes) => bytes,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(_) => return Err(self.unusable_recovery()),
        };
        let record = serde_json::from_slice::<RecoveryRecord>(&bytes)
            .map_err(|_| self.unusable_recovery())?;
        if record.version != RECOVERY_VERSION || record.provider != self.provider {
            return Err(self.unusable_recovery());
        }
        Ok(Some(record))
    }

    fn unusable_recovery(&self) -> String {
        format!(
            "the {} credential recovery record is unusable",
            self.provider
        )
    }

    fn write_recovery(
        &self,
        baseline_fingerprint: crate::translation_core::Maybe<String>,
        token: &SubscriptionToken,
    ) -> crate::translation_core::Outcome<(), String> {
        let record = RecoveryRecord {
            version: RECOVERY_VERSION,
            provider: self.provider,
            baseline_fingerprint,
            token: token.clone(),
        };
        let serialized = serde_json::to_vec(&record)
            .map_err(|error| format!("could not serialize OAuth recovery record: {error}"))?;
        crate::durable_file::atomic_write_owner_only(&self.recovery_path, &serialized).map_err(
            |error| {
                format!(
                    "could not persist OAuth recovery record at {}: {error}",
                    self.recovery_path.display()
                )
            },
        )
    }

    fn remove_recovery(&self) -> std::io::Result<()> {
        match std::fs::remove_file(&self.recovery_path) {
            Ok(()) => {
                let directory = self
                    .recovery_path
                    .parent()
                    .ok_or_else(|| std::io::Error::other("recovery path has no parent"))?;
                crate::durable_file::sync_directory(directory)
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(error),
        }
    }
}

impl CredentialStore for RecoverableCredentialStore {
    fn reload(&self) -> Option<SubscriptionToken> {
        self.try_reload().ok().flatten()
    }

    fn try_reload(&self) -> Result<Option<SubscriptionToken>, String> {
        let primary = self.primary.try_reload()?;
        let Some(record) = self.read_recovery()? else {
            return Ok(primary);
        };
        let primary_fingerprint = primary.as_ref().map(Self::fingerprint);
        let recovered_fingerprint = Self::fingerprint(&record.token);

        if primary_fingerprint.as_deref() == Some(recovered_fingerprint.as_str()) {
            self.remove_recovery()
                .map_err(|_| self.unusable_recovery())?;
            return Ok(primary);
        }

        if primary_fingerprint.is_some()
            && primary_fingerprint != record.baseline_fingerprint
            && primary_fingerprint.as_deref() != Some(recovered_fingerprint.as_str())
        {
            self.remove_recovery()
                .map_err(|_| self.unusable_recovery())?;
            return Ok(primary);
        }

        if self.primary.persist(&record.token).is_ok() {
            self.remove_recovery()
                .map_err(|_| self.unusable_recovery())?;
        }
        Ok(Some(record.token))
    }

    fn persist(&self, token: &SubscriptionToken) -> Result<(), String> {
        let baseline_fingerprint = self.primary.try_reload()?.as_ref().map(Self::fingerprint);
        match self.primary.persist(token) {
            Ok(()) => {
                let _ = self.remove_recovery();
                Ok(())
            }
            Err(primary_error) => {
                self.write_recovery(baseline_fingerprint, token)
                    .map_err(|recovery_error| {
                        format!(
                            "{primary_error}; recovery persistence also failed: {recovery_error}"
                        )
                    })
            }
        }
    }

    fn prepare_refresh(&self, token: &SubscriptionToken) -> Result<(), String> {
        self.primary.prepare_refresh(token)
    }

    fn lock_path(&self) -> Option<PathBuf> {
        Some(self.lock_path.clone())
    }

    fn describe(&self) -> String {
        self.primary.describe()
    }
}

#[cfg(test)]
mod tests {
    use std::path::{Path, PathBuf};
    use std::sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    };

    use crate::credential_store::CredentialStore;
    use crate::subscription::{SubscriptionProvider, SubscriptionReader, SubscriptionToken};

    use super::{RecoverableCredentialStore, credential_lock_path};

    const ACCOUNT: &str = "team@example.com";
    const ACCOUNT_SHA256: &str = "a96e3689637c79fb389b70f6a2ff545458d0796e44c61722e8a569b58fcecf85";

    struct VendorCase {
        provider: SubscriptionProvider,
        filename: &'static str,
        document: &'static str,
        vendor_field: &'static str,
        vendor_value: serde_json::Value,
    }

    fn vendor_cases() -> Vec<VendorCase> {
        vec![
            VendorCase {
                provider: SubscriptionProvider::Claude,
                filename: ".credentials.json",
                document: r#"{"claudeAiOauth":{"accessToken":"old-access","refreshToken":"old-refresh","expiresAt":1,"subscriptionType":"max","scopes":["user:inference"]}}"#,
                vendor_field: "/claudeAiOauth/subscriptionType",
                vendor_value: serde_json::json!("max"),
            },
            VendorCase {
                provider: SubscriptionProvider::Codex,
                filename: "auth.json",
                document: r#"{"auth_mode":"chatgpt","tokens":{"id_token":"id-1","access_token":"old-access","refresh_token":"old-refresh","account_id":"acct_1"},"last_refresh":"2026-08-11T11:31:03Z"}"#,
                vendor_field: "/tokens/id_token",
                vendor_value: serde_json::json!("id-1"),
            },
            VendorCase {
                provider: SubscriptionProvider::Gemini,
                filename: "oauth_creds.json",
                document: r#"{"access_token":"old-access","refresh_token":"old-refresh","expiry_date":1,"token_type":"Bearer","scope":"cloud-platform"}"#,
                vendor_field: "/scope",
                vendor_value: serde_json::json!("cloud-platform"),
            },
            VendorCase {
                provider: SubscriptionProvider::Qwen,
                filename: "oauth_creds.json",
                document: r#"{"access_token":"old-access","refresh_token":"old-refresh","expiry_date":1,"token_type":"Bearer","resource_url":"portal.qwen.ai","scope":"openid"}"#,
                vendor_field: "/scope",
                vendor_value: serde_json::json!("openid"),
            },
        ]
    }

    fn token(provider: SubscriptionProvider, access: &str, refresh: &str) -> SubscriptionToken {
        SubscriptionToken {
            access_token: access.into(),
            refresh_token: Some(refresh.into()),
            expires_at_ms: Some(9_000),
            account_id: (provider == SubscriptionProvider::Codex).then(|| "acct_1".into()),
            resource_url: (provider == SubscriptionProvider::Qwen).then(|| "portal.qwen.ai".into()),
        }
    }

    #[derive(Debug)]
    struct SwitchableStore {
        reader: SubscriptionReader,
        fail_writes: AtomicBool,
    }

    impl SwitchableStore {
        fn new(reader: SubscriptionReader, fail_writes: bool) -> Self {
            Self {
                reader,
                fail_writes: AtomicBool::new(fail_writes),
            }
        }

        fn allow_writes(&self) {
            self.fail_writes.store(false, Ordering::SeqCst);
        }
    }

    impl CredentialStore for SwitchableStore {
        fn reload(&self) -> Option<SubscriptionToken> {
            CredentialStore::reload(&self.reader)
        }

        fn persist(&self, token: &SubscriptionToken) -> Result<(), String> {
            if self.fail_writes.load(Ordering::SeqCst) {
                Err("primary credential store is read-only".into())
            } else {
                CredentialStore::persist(&self.reader, token)
            }
        }

        fn lock_path(&self) -> Option<PathBuf> {
            CredentialStore::lock_path(&self.reader)
        }

        fn describe(&self) -> String {
            CredentialStore::describe(&self.reader)
        }
    }

    fn primary(case: &VendorCase, home: &Path, fail_writes: bool) -> Arc<SwitchableStore> {
        std::fs::write(home.join(case.filename), case.document).expect("seed vendor credential");
        Arc::new(SwitchableStore::new(
            SubscriptionReader::new(case.provider, home),
            fail_writes,
        ))
    }

    #[test]
    fn failed_primary_write_leaves_an_owner_only_recovery_that_survives_restart() {
        for case in vendor_cases() {
            let home = tempfile::tempdir().expect("credential home");
            let data = tempfile::tempdir().expect("data dir");
            let primary = primary(&case, home.path(), true);
            let store = RecoverableCredentialStore::new(
                case.provider,
                ACCOUNT,
                Arc::clone(&primary) as Arc<dyn CredentialStore>,
                data.path(),
            );
            let fresh = token(case.provider, "secret-access", "secret-refresh");

            store.persist(&fresh).expect("recovery write is durable");

            assert!(store.recovery_path.exists(), "{}", case.provider);
            let expected_name = format!("{}-{ACCOUNT_SHA256}.json", case.provider.as_str());
            assert_eq!(
                store
                    .recovery_path
                    .file_name()
                    .and_then(|name| name.to_str()),
                Some(expected_name.as_str())
            );
            assert!(!expected_name.contains(ACCOUNT));
            assert!(!expected_name.contains("secret"));
            let expected_lock_name = format!("{}-{ACCOUNT_SHA256}.lock", case.provider.as_str());
            let recovery_lock = store.lock_path().expect("recovery lock");
            assert_eq!(recovery_lock, store.lock_path);
            assert_eq!(
                recovery_lock,
                credential_lock_path(data.path(), case.provider, ACCOUNT)
            );
            assert_eq!(
                recovery_lock.file_name().and_then(|name| name.to_str()),
                Some(expected_lock_name.as_str())
            );
            assert_ne!(recovery_lock, primary.lock_path().expect("primary lock"));
            assert_eq!(store.describe(), primary.describe());
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                let mode = std::fs::metadata(&store.recovery_path)
                    .expect("recovery metadata")
                    .permissions()
                    .mode()
                    & 0o777;
                assert_eq!(mode, 0o600, "{}", case.provider);
            }
            assert_eq!(store.reload(), Some(fresh.clone()), "{}", case.provider);

            let restarted = RecoverableCredentialStore::new(
                case.provider,
                ACCOUNT,
                Arc::clone(&primary) as Arc<dyn CredentialStore>,
                data.path(),
            );
            assert_eq!(restarted.reload(), Some(fresh), "{}", case.provider);
        }
    }

    #[test]
    fn writable_reload_reconciles_recovery_without_losing_vendor_fields() {
        for case in vendor_cases() {
            let home = tempfile::tempdir().expect("credential home");
            let data = tempfile::tempdir().expect("data dir");
            let primary = primary(&case, home.path(), true);
            let store = RecoverableCredentialStore::new(
                case.provider,
                ACCOUNT,
                Arc::clone(&primary) as Arc<dyn CredentialStore>,
                data.path(),
            );
            let fresh = token(case.provider, "fresh-access", "fresh-refresh");
            store.persist(&fresh).expect("fallback persistence");
            primary.allow_writes();

            let restarted = RecoverableCredentialStore::new(
                case.provider,
                ACCOUNT,
                Arc::clone(&primary) as Arc<dyn CredentialStore>,
                data.path(),
            );
            assert_eq!(restarted.reload(), Some(fresh), "{}", case.provider);
            assert!(
                !restarted.recovery_path.exists(),
                "completed recovery remains for {}",
                case.provider
            );

            let document: serde_json::Value = serde_json::from_slice(
                &std::fs::read(home.path().join(case.filename)).expect("vendor document"),
            )
            .expect("valid vendor JSON");
            assert_eq!(
                document.pointer(case.vendor_field),
                Some(&case.vendor_value),
                "{}",
                case.provider
            );
        }
    }

    #[test]
    fn a_changed_primary_invalidates_stale_recovery() {
        let case = vendor_cases().remove(1);
        let home = tempfile::tempdir().expect("credential home");
        let data = tempfile::tempdir().expect("data dir");
        let primary = primary(&case, home.path(), true);
        let store = RecoverableCredentialStore::new(
            case.provider,
            ACCOUNT,
            Arc::clone(&primary) as Arc<dyn CredentialStore>,
            data.path(),
        );
        store
            .persist(&token(
                case.provider,
                "recovered-access",
                "recovered-refresh",
            ))
            .expect("fallback persistence");
        primary.allow_writes();
        let operator_token = token(case.provider, "operator-access", "operator-refresh");
        primary
            .persist(&operator_token)
            .expect("operator replaces primary chain");

        let reloaded = store.reload().expect("changed primary wins");
        assert_eq!(reloaded.access_token, operator_token.access_token);
        assert_eq!(reloaded.refresh_token, operator_token.refresh_token);
        assert_eq!(reloaded.account_id, operator_token.account_id);
        assert!(!store.recovery_path.exists());
    }

    #[test]
    fn invalid_recovery_metadata_is_never_adopted() {
        for field in ["version", "provider"] {
            let case = vendor_cases().remove(1);
            let home = tempfile::tempdir().expect("credential home");
            let data = tempfile::tempdir().expect("data dir");
            let primary = primary(&case, home.path(), true);
            let baseline = primary.reload().expect("baseline");
            let store = RecoverableCredentialStore::new(
                case.provider,
                ACCOUNT,
                Arc::clone(&primary) as Arc<dyn CredentialStore>,
                data.path(),
            );
            store
                .persist(&token(
                    case.provider,
                    "recovered-access",
                    "recovered-refresh",
                ))
                .expect("fallback persistence");
            let mut record: serde_json::Value = serde_json::from_slice(
                &std::fs::read(&store.recovery_path).expect("recovery record"),
            )
            .expect("valid recovery JSON");
            record[field] = if field == "version" {
                serde_json::json!(99)
            } else {
                serde_json::json!("gemini")
            };
            std::fs::write(
                &store.recovery_path,
                serde_json::to_vec(&record).expect("serialize altered record"),
            )
            .expect("alter recovery record");

            let error = store
                .try_reload()
                .expect_err("invalid recovery fails closed");
            assert_eq!(
                error,
                format!(
                    "the {} credential recovery record is unusable",
                    case.provider
                )
            );
            assert!(!error.contains(ACCOUNT));
            assert!(!error.contains(&data.path().display().to_string()));
            assert_eq!(store.reload(), None, "invalid {field}");
            assert_eq!(primary.reload(), Some(baseline), "primary remains intact");
        }
    }

    #[test]
    fn persist_errors_only_when_primary_and_recovery_are_both_unwritable() {
        let case = vendor_cases().remove(0);
        let home = tempfile::tempdir().expect("credential home");
        let data = tempfile::tempdir().expect("data parent");
        let not_a_directory = data.path().join("file");
        std::fs::write(&not_a_directory, b"occupied").expect("blocking file");
        let primary = primary(&case, home.path(), true);
        let store = RecoverableCredentialStore::new(
            case.provider,
            ACCOUNT,
            primary as Arc<dyn CredentialStore>,
            &not_a_directory,
        );
        let fresh = token(case.provider, "do-not-leak-access", "do-not-leak-refresh");

        let error = store.persist(&fresh).expect_err("neither store is durable");

        assert!(error.contains("primary credential store is read-only"));
        assert!(!error.contains("do-not-leak-access"));
        assert!(!error.contains("do-not-leak-refresh"));
    }
}

//! Whether a deployment *follows* a vendor credential home or holds a copy.
//!
//! A refresh token is not a value but a rotating series, and whoever redeems a
//! link invalidates it for every other holder. So two independent refreshers of
//! one credential is the bug: the vendor CLI rotates on its own cadence, a
//! deployment holding a copy rotates on its own, and whichever loses the race is
//! left with `invalid_grant` — indistinguishable, from the loser's side, from a
//! revocation (issue #574).
//!
//! ## What already exists
//!
//! Router's storage layer solved the mechanics before this module: a credential
//! document may carry a `_link_assistant_router.credential_source` pointer at
//! the vendor client's own file, and then
//! [`crate::subscription::SubscriptionReader`] reads *through* it under a lock
//! and writes a rotated token back to the vendor's file rather than to a private
//! copy. That is one chain with one refresher, reported as
//! [`crate::platform_keychain::Origin::AdoptedFile`], and `auth import` builds
//! such a reference by default.
//!
//! What was missing was the operator's view of it. Two stores, one possibly
//! stale, and no command that said which one was real: an operator could not
//! tell "following, current" from "a copy taken at time T", and a followed source
//! that had been removed surfaced as a path-bearing read error rather than as
//! "the home you were following is gone".
//!
//! This module answers that question from the pointer document alone, so it
//! still answers when the source is missing or unreadable — which is exactly the
//! case an operator most needs named.
//!
//! Secrets never appear here: the report carries states and paths only, and the
//! pointer document it reads holds no token at all.

use std::path::{Path, PathBuf};

use crate::subscription::{SubscriptionProvider, SubscriptionReader};

/// Key under which Router records its own metadata in a credential document.
///
/// Duplicated from `subscription::external` rather than shared, because that
/// module's copy is private to the parsing path and this one is only ever read.
const ROUTER_METADATA_KEY: &str = "_link_assistant_router";
const CREDENTIAL_SOURCE_KEY: &str = "credential_source";
const REFRESH_OWNER_KEY: &str = "refresh_owner";
const EXTERNAL_REFRESH_OWNER: &str = "external";

/// How a deployment holds one provider's credential.
#[derive(
    Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize, schemars::JsonSchema,
)]
#[serde(tag = "kind", rename_all = "kebab-case")]
pub enum CredentialSource {
    /// Nothing is installed for this provider.
    Absent,
    /// Router's own credential file, which Router alone rotates.
    ///
    /// The ordinary case for a credential obtained by `auth claude` here: there
    /// is no second holder, so there is no chain to share.
    Owned,
    /// A reference to a vendor client's file that both processes advance.
    ///
    /// One chain, one refresher: whichever process refreshes writes the
    /// successor where the other will read it.
    Followed {
        /// The vendor file being followed.
        source: PathBuf,
        /// Whether that file is currently readable.
        ///
        /// A followed home that has been removed must be named as such: falling
        /// back to a stale copy is what makes a deployment drift into
        /// `invalid_grant` while the CLI beside it stays healthy.
        present: bool,
    },
    /// A credential owned elsewhere that Router must not rotate.
    ///
    /// Marked `refresh_owner: external` without identifying a writable source,
    /// so Router can read it but must never spend the refresh token.
    ExternallyOwned,
}

impl CredentialSource {
    /// Stable spelling for tables, JSON and assertions.
    #[must_use]
    pub const fn as_str(&self) -> &'static str {
        match self {
            Self::Absent => "absent",
            Self::Owned => "copy",
            Self::Followed { present: true, .. } => "following",
            Self::Followed { present: false, .. } => "source-gone",
            Self::ExternallyOwned => "external",
        }
    }

    /// Whether this deployment is the party that rotates the credential.
    ///
    /// The property the issue turns on. A followed credential *is* rotated by
    /// Router — it writes the successor into the vendor's own file, so there is
    /// still exactly one refresher of one chain.
    #[must_use]
    pub const fn router_may_refresh(&self) -> bool {
        matches!(self, Self::Owned | Self::Followed { present: true, .. })
    }

    /// One sentence an operator can act on.
    #[must_use]
    pub fn explain(&self) -> String {
        match self {
            Self::Absent => "no credential installed".to_string(),
            Self::Owned => "a copy Router owns and rotates; a vendor client logged in elsewhere \
                 holds a different chain and the two can spend each other's tokens"
                .to_string(),
            Self::Followed {
                source,
                present: true,
            } => format!(
                "following {}; Router and the vendor client advance one chain, so a rotation by \
                 either is seen by the other",
                source.display()
            ),
            Self::Followed {
                source,
                present: false,
            } => format!(
                "following {}, which is missing or unreadable; this deployment has no usable \
                 credential for the provider rather than a stale copy of one — restore that home, \
                 or re-import to take a copy",
                source.display()
            ),
            Self::ExternallyOwned => {
                "owned externally and readable but not rotatable by Router; the owning client \
                 must refresh it"
                    .to_string()
            }
        }
    }
}

/// One provider's holding, for `auth status`.
#[derive(
    Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize, schemars::JsonSchema,
)]
pub struct SourceReport {
    pub provider: SubscriptionProvider,
    pub source: CredentialSource,
}

/// Describe how `reader`'s home holds its credential.
///
/// Reads the document Router installed, *not* the credential it may point at, so
/// a followed source that has vanished is still described as a followed source.
#[must_use]
pub fn describe(reader: &SubscriptionReader) -> CredentialSource {
    let Some(document) = first_readable_document(reader) else {
        return CredentialSource::Absent;
    };
    describe_document(&document)
}

/// Describe a credential document's ownership without touching the filesystem,
/// except to decide whether a referenced source is presently readable.
#[must_use]
pub fn describe_document(document: &str) -> CredentialSource {
    let Ok(value) = serde_json::from_str::<serde_json::Value>(document) else {
        // Unparsable is not "absent": something is installed, Router simply
        // cannot read it. Owned is the conservative report — it never claims a
        // sharing guarantee this document does not establish.
        return CredentialSource::Owned;
    };
    if let Some(source) = pointer_at(&value, CREDENTIAL_SOURCE_KEY) {
        let present = source.is_file();
        return CredentialSource::Followed { source, present };
    }
    if value
        .pointer(&format!("/{ROUTER_METADATA_KEY}/{REFRESH_OWNER_KEY}"))
        .and_then(serde_json::Value::as_str)
        == Some(EXTERNAL_REFRESH_OWNER)
    {
        return CredentialSource::ExternallyOwned;
    }
    CredentialSource::Owned
}

/// The `credential_source` path recorded in a document, if any.
fn pointer_at(value: &serde_json::Value, key: &str) -> Option<PathBuf> {
    value
        .pointer(&format!("/{ROUTER_METADATA_KEY}/{key}"))
        .and_then(serde_json::Value::as_str)
        .filter(|path| !path.is_empty())
        .map(PathBuf::from)
}

/// The first credential document present in this home.
fn first_readable_document(reader: &SubscriptionReader) -> Option<String> {
    reader
        .credential_paths()
        .into_iter()
        .find(|path| path.is_file())
        .and_then(|path| std::fs::read_to_string(path).ok())
}

/// Build a reference document that follows `source`.
///
/// `auth import --follow` installs this instead of a copy. The document holds no
/// token: every read resolves the pointer, which is what makes a rotation by the
/// vendor client visible without a re-import or a restart.
pub fn follow_document(source: &Path) -> Result<String, String> {
    // The receipt id records which operation installed the reference, matching
    // what import writes, so the two documents are the same shape.
    crate::subscription::reference_external_credential(source, "follow")
}

/// Report every provider's holding, for the status table.
#[must_use]
pub fn report(readers: &[SubscriptionReader]) -> Vec<SourceReport> {
    readers
        .iter()
        .map(|reader| SourceReport {
            provider: reader.provider(),
            source: describe(reader),
        })
        .collect()
}

//! Shared local/remote subscription credential acceptance checks.

use serde::{Deserialize, Serialize};

use crate::credential_recovery_store::PRIMARY_ACCOUNT;
use crate::model_catalog::{CatalogAcceptance, classify_catalog_acceptance};
use crate::refresh::TokenCache;
use crate::subscription::{SubscriptionProvider, SubscriptionReader};

/// Stable provider-verified credential state used by CLI and management APIs.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "kebab-case")]
pub enum CredentialAcceptanceState {
    Usable,
    Rejected,
    Unverified,
    RefreshFailed,
    Absent,
}

impl CredentialAcceptanceState {
    /// Stable human/JSON spelling.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Usable => "usable",
            Self::Rejected => "rejected",
            Self::Unverified => "unverified",
            Self::RefreshFailed => "refresh-failed",
            Self::Absent => "absent",
        }
    }
}

/// One provider's accepted state and exact local credential root.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, schemars::JsonSchema)]
pub struct CredentialAcceptanceReport {
    pub provider: SubscriptionProvider,
    pub home: String,
    pub state: CredentialAcceptanceState,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
}

/// Refresh when required, then make one non-inference catalog acceptance probe.
pub async fn evaluate(
    client: &reqwest::Client,
    token_cache: &TokenCache,
    readers: &[SubscriptionReader],
    catalog_base_override: Option<(SubscriptionProvider, &str)>,
) -> Vec<CredentialAcceptanceReport> {
    let now = crate::operation_context::now().timestamp_millis();
    let mut reports = Vec::with_capacity(readers.len());
    for reader in readers {
        let provider = reader.provider();
        let (state, detail) = match token_cache
            .load_authoritative(provider, PRIMARY_ACCOUNT)
            .await
        {
            Ok(None) => (CredentialAcceptanceState::Absent, None),
            Err(_) => (
                CredentialAcceptanceState::RefreshFailed,
                Some("credential recovery state could not be loaded".to_string()),
            ),
            Ok(Some(_)) => {
                match token_cache
                    .get_fresh_registered(client, provider, PRIMARY_ACCOUNT, now)
                    .await
                {
                    Ok(token) if token_cache.last_refresh_error(provider).is_none() => {
                        let base = catalog_base_override
                            .and_then(|(selected, base)| (selected == provider).then_some(base));
                        let catalog = crate::model_catalog::fetch_provider_catalog(
                            client, provider, &token, base,
                        )
                        .await;
                        let state = match classify_catalog_acceptance(&catalog) {
                            CatalogAcceptance::Accepted => CredentialAcceptanceState::Usable,
                            CatalogAcceptance::MissingSubscription
                            | CatalogAcceptance::CredentialRejected => {
                                CredentialAcceptanceState::Rejected
                            }
                            CatalogAcceptance::Unverified => CredentialAcceptanceState::Unverified,
                        };
                        (state, None)
                    }
                    _ => (
                        CredentialAcceptanceState::RefreshFailed,
                        Some(token_cache.last_refresh_error(provider).unwrap_or_else(|| {
                            "refresh failed before the credential could be checked".to_string()
                        })),
                    ),
                }
            }
        };
        reports.push(CredentialAcceptanceReport {
            provider,
            home: reader.home().display().to_string(),
            state,
            detail,
        });
    }
    reports
}

#[cfg(test)]
mod tests {
