//! Per-instance names for local deployment objects (issue #679).
//!
//! Two deployments on one host used to share the relay container name, the
//! Docker network and the backend prefix, so the second `router deploy`
//! refused (or, with a different root, could not even name) its own relay.
//! An instance name suffixes every such object. Without one the names are the
//! historical ones, so an existing deployment is found exactly as before.
//!
//! Library operations select an instance within their operation context. Native
//! CLI commands keep the historical once-per-process selection.

use std::fmt;
use std::ops::Deref;
use std::sync::OnceLock;

static INSTANCE: OnceLock<String> = OnceLock::new();

/// Longest accepted instance name; Docker names and DNS labels stay short.
pub const MAX_INSTANCE_LEN: usize = 32;

/// Validate an instance name: lowercase letters, digits and inner hyphens.
///
/// # Errors
///
/// Returns an operator-readable reason when the name cannot be part of a
/// container name, network name, DNS label and directory name at once.
pub fn validate(name: &str) -> Result<(), String> {
    let valid = !name.is_empty()
        && name.len() <= MAX_INSTANCE_LEN
        && !name.starts_with('-')
        && !name.ends_with('-')
        && name
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-');
    if valid {
        Ok(())
    } else {
        Err(format!(
            "instance name `{name}` must be 1-{MAX_INSTANCE_LEN} lowercase letters, digits or inner hyphens"
        ))
    }
}

/// Select this process's instance. Must run before any name is read.
///
/// # Errors
///
/// Refuses an invalid name, or a second, different selection.
pub fn select(name: &str) -> Result<(), String> {
    validate(name)?;
    if let Some(context) = crate::operation_context::current() {
        *context
            .deployment_instance
            .lock()
            .expect("deployment instance lock") = Some(name.into());
        return Ok(());
    }
    let selected = INSTANCE.get_or_init(|| name.to_string());
    if selected == name {
        Ok(())
    } else {
        Err(format!(
            "deployment instance is already `{selected}`; one command manages one instance"
        ))
    }
}

/// The selected instance, if any.
#[must_use]
pub fn selected() -> Option<&'static str> {
    INSTANCE.get().map(String::as_str)
}

/// Owned selection from the current operation, or the native CLI selection.
#[must_use]
pub fn selected_name() -> Option<String> {
    crate::operation_context::current().map_or_else(
        || selected().map(str::to_owned),
        |context| {
            context
                .deployment_instance
                .lock()
                .expect("deployment instance lock")
                .clone()
        },
    )
}

/// The historical name with the instance suffix, when one is selected.
#[must_use]
pub fn qualify(base: &str) -> String {
    selected_name().map_or_else(|| base.to_string(), |instance| format!("{base}-{instance}"))
}

/// DNS-safe backend name retaining the full unique deployment nonce.
///
/// A named instance is represented by a digest so the accepted 32-character
/// instance plus the UUID never exceeds DNS's 63-octet label limit (#714).
/// Existing backend references in deployment state remain usable.
pub fn backend_name(nonce: uuid::Uuid) -> Result<String, String> {
    backend_name_in(selected_name().as_deref(), nonce)
}

fn backend_name_in(instance: Option<&str>, nonce: uuid::Uuid) -> Result<String, String> {
    use sha2::Digest as _;
    let prefix = crate::deploy::BACKEND_PREFIX;
    let name = if let Some(instance) = instance {
        validate(instance)?;
        let digest = sha2::Sha256::digest(instance.as_bytes());
        format!("{prefix}{}-{}", hex::encode(&digest[..4]), nonce.simple())
    } else {
        // Preserve the historical unnamed prefix, including its separator.
        format!("{prefix}-{}", nonce.simple())
    };
    if name.len() > 63 {
        return Err("generated deployment backend exceeds the 63-byte DNS label limit".into());
    }
    Ok(name)
}

/// A deployment object name that carries the selected instance.
pub struct InstanceName {
    base: &'static str,
    /// Appended after the instance, so a prefix stays a prefix.
    trailer: &'static str,
    resolved: OnceLock<String>,
}

impl InstanceName {
    /// A name used as-is (`router-deploy-relay` -> `router-deploy-relay-a`).
    #[must_use]
    pub const fn new(base: &'static str) -> Self {
        Self {
            base,
            trailer: "",
            resolved: OnceLock::new(),
        }
    }

    /// A prefix that keeps its trailing separator
    /// (`router-deploy-backend-` -> `router-deploy-backend-a-`).
    #[must_use]
    pub const fn prefix(base: &'static str) -> Self {
        Self {
            base,
            trailer: "-",
            resolved: OnceLock::new(),
        }
    }

    /// Name resolved within the active operation; never cached process-wide.
    #[must_use]
    pub fn value(&self) -> String {
        format!("{}{}", qualify(self.base), self.trailer)
    }

    /// The resolved name for native CLI callers.
    #[must_use]
    pub fn as_str(&self) -> &str {
        self.resolved
            .get_or_init(|| format!("{}{}", qualify(self.base), self.trailer))
    }
}

impl Deref for InstanceName {
    type Target = str;

    fn deref(&self) -> &str {
        self.as_str()
    }
}

impl AsRef<str> for InstanceName {
    fn as_ref(&self) -> &str {
        self.as_str()
    }
}

impl fmt::Display for InstanceName {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.value())
    }
}

impl fmt::Debug for InstanceName {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(&self.value(), formatter)
    }
}

impl PartialEq<str> for InstanceName {
    fn eq(&self, other: &str) -> bool {
        self.as_str() == other
    }
}

impl PartialEq<&str> for InstanceName {
    fn eq(&self, other: &&str) -> bool {
        self.as_str() == *other
    }
}

impl PartialEq<String> for InstanceName {
    fn eq(&self, other: &String) -> bool {
        self.as_str() == other
    }
}

impl PartialEq<InstanceName> for String {
    fn eq(&self, other: &InstanceName) -> bool {
        self == other.as_str()
    }
}

impl PartialEq<InstanceName> for &str {
    fn eq(&self, other: &InstanceName) -> bool {
        *self == other.as_str()
    }
}

#[cfg(test)]
mod dns_tests {
    use super::*;

    #[test]
    fn every_accepted_instance_length_retains_a_full_nonce_within_dns_bounds() {
        let nonce = uuid::Uuid::new_v4();
        let mut names = std::collections::HashSet::new();
        for length in 1..=MAX_INSTANCE_LEN {
            let instance = "a".repeat(length);
            let name = backend_name_in(Some(&instance), nonce).unwrap();
            assert!(name.len() <= 63, "{name}");
            assert!(name.ends_with(&nonce.simple().to_string()));
            assert!(names.insert(name));
        }
        assert_ne!(
            backend_name_in(Some("instance-a"), nonce).unwrap(),
            backend_name_in(Some("instance-b"), nonce).unwrap()
        );
        assert_ne!(
            backend_name_in(Some("instance-a"), nonce).unwrap(),
            backend_name_in(Some("instance-a"), uuid::Uuid::new_v4()).unwrap()
        );
        assert!(backend_name_in(Some(&"a".repeat(33)), nonce).is_err());
        assert!(backend_name_in(None, nonce).unwrap().len() <= 63);
    }
}

//! The registry of local deployment roots (issue #684).
//!
//! A deployment started with `--root DIR` keeps its data, and so its recorded
//! provider exhaustion and account limits, in `DIR/data`. `router doctor`
//! inspected only its own data directory and the default root, so such a
//! deployment was invisible to it. Every successful local or host deploy now
//! records its root here, and doctor inspects each one it finds, or names the
//! one it could not see.
//!
//! The registry lives under `$HOME`, not `DATA_DIR`, so a doctor run with a
//! different data directory still finds every deployment of this user. It
//! holds paths, modes and ports only: never a secret.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

/// The registry's file name inside the per-user directory.
pub const FILE: &str = "deployments.json";

/// One registered deployment.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize, schemars::JsonSchema)]
pub struct Entry {
    /// The absolute deployment root.
    pub root: PathBuf,
    /// `container` or `host`.
    pub mode: String,
    /// The loopback port it serves on.
    pub port: u16,
    /// The `--instance` it was deployed as, when any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub instance: Option<String>,
    /// Unix seconds of the last successful deploy.
    pub registered_at: i64,
}

impl Entry {
    /// The data directory the deployment's Router writes to.
    #[must_use]
    pub fn data_dir(&self) -> PathBuf {
        self.root.join("data")
    }
}

#[derive(Debug, Default, Deserialize, Serialize)]
struct Document {
    #[serde(default)]
    deployments: Vec<Entry>,
}

/// The registry path for this user: `$HOME/.link-assistant-router/deployments.json`,
/// or under `fallback` (the data directory) when `HOME` is unset.
#[must_use]
pub fn path(fallback: &Path) -> PathBuf {
    crate::operation_context::var_os("HOME")
        .filter(|home| !home.is_empty())
        .map_or_else(
            || fallback.join(FILE),
            |home| {
                PathBuf::from(home)
                    .join(".link-assistant-router")
                    .join(FILE)
            },
        )
}

/// Every registered deployment; an absent or unreadable registry is empty.
#[must_use]
pub fn read(path: &Path) -> Vec<Entry> {
    std::fs::read(path)
        .ok()
        .and_then(|bytes| serde_json::from_slice::<Document>(&bytes).ok())
        .map(|document| document.deployments)
        .unwrap_or_default()
}

fn write(path: &Path, deployments: Vec<Entry>) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|error| format!("could not create {}: {error}", parent.display()))?;
    }
    let bytes = serde_json::to_vec_pretty(&Document { deployments })
        .map_err(|error| format!("could not encode the deployment registry: {error}"))?;
    crate::durable_file::atomic_write_owner_only(path, &bytes)
        .map_err(|error| crate::durable_file::describe_write_failure(path, &error))
}

/// Record `entry`, replacing an earlier record of the same root.
///
/// # Errors
///
/// When the registry cannot be written.
pub fn register(path: &Path, entry: Entry) -> Result<(), String> {
    let mut deployments: Vec<Entry> = read(path)
        .into_iter()
        .filter(|existing| existing.root != entry.root)
        .collect();
    deployments.push(entry);
    write(path, deployments)
}

/// Forget `root`, after its deployment was removed.
///
/// # Errors
///
/// When the registry cannot be written.
pub fn unregister(path: &Path, root: &Path) -> Result<(), String> {
    let deployments = read(path);
    if !deployments.iter().any(|entry| entry.root == root) {
        return Ok(());
    }
    write(
        path,
        deployments
            .into_iter()
            .filter(|entry| entry.root != root)
            .collect(),
    )
}

/// What doctor should inspect: the data directory of every registered root
/// that still exists, and a note for every one it cannot see.
#[must_use]
pub fn doctor_targets(path: &Path) -> (Vec<PathBuf>, String) {
    let mut directories = Vec::new();
    let mut notes = String::new();
    for entry in read(path) {
        if entry.root.is_dir() {
            directories.push(entry.data_dir());
        } else {
            let _ = writeln!(
                notes,
                "deployment registry    : could not see {} ({} on port {}); it was moved or \
                 removed without `router deploy --down`",
                entry.root.display(),
                entry.mode,
                entry.port
            );
        }
    }
    (directories, notes)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn entry(root: &Path, port: u16) -> Entry {
        Entry {
            root: root.to_path_buf(),
            mode: "host".to_string(),
            port,
            instance: None,
            registered_at: 1,
        }
    }

    #[test]
    fn a_root_is_registered_once_and_forgotten_on_down() {
        let directory = tempfile::tempdir().unwrap();
        let registry = directory.path().join("nested").join(FILE);
        let root = directory.path().join("custom");
        std::fs::create_dir_all(&root).unwrap();

        register(&registry, entry(&root, 8080)).unwrap();
        register(&registry, entry(&root, 9090)).unwrap();
        let entries = read(&registry);
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].port, 9090);

        let (directories, notes) = doctor_targets(&registry);
        assert_eq!(directories, vec![root.join("data")]);
        assert!(notes.is_empty());

        unregister(&registry, &root).unwrap();
        assert!(read(&registry).is_empty());
    }

    #[test]
    fn a_missing_root_is_named_rather_than_silently_skipped() {
        let directory = tempfile::tempdir().unwrap();
        let registry = directory.path().join(FILE);
        let gone = directory.path().join("gone");
        register(&registry, entry(&gone, 8080)).unwrap();

        let (directories, notes) = doctor_targets(&registry);
        assert!(directories.is_empty());
        assert!(notes.contains("could not see"), "{notes}");
        assert!(notes.contains(&gone.display().to_string()), "{notes}");
    }

    #[test]
    fn a_corrupt_registry_reads_as_empty_and_is_rewritten() {
        let directory = tempfile::tempdir().unwrap();
        let registry = directory.path().join(FILE);
        std::fs::write(&registry, "not json").unwrap();
        assert!(read(&registry).is_empty());
        register(&registry, entry(directory.path(), 1)).unwrap();
        assert_eq!(read(&registry).len(), 1);
    }
}

//! The container runtime boundary, so converge logic is testable without Docker.
//!
//! Every step in [`crate::deploy`] reaches the outside world only through
//! [`ContainerRuntime`]. That keeps the interesting part — the order of checks,
//! what counts as converged, which failures are the deployment's fault —
//! exercisable in milliseconds against a fake, while the real implementation
//! stays a thin, auditable shell around `docker`.
//!
//! The split matters for correctness, not just speed: the properties worth
//! pinning are things like "a second run performs no actions" and "a stopped
//! container is restored", which need many runs from many starting states. A
//! suite that can only express them against a real daemon expresses few of them.

use std::time::Duration;

/// What a container is doing, as far as the runtime can tell.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ContainerState {
    /// No container by that name.
    Absent,
    /// Exists and is running. Not the same as answering — see
    /// [`ContainerRuntime::health`].
    Running,
    /// Exists and is not running.
    Stopped,
}

impl ContainerState {
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Absent => "absent",
            Self::Running => "running",
            Self::Stopped => "stopped",
        }
    }
}

/// How a container should be created.
#[derive(Debug, Clone)]
pub struct RunSpec {
    pub name: String,
    pub image: String,
    /// Host port published to the container's listener.
    pub port: u16,
    /// `(host, container, read_only)` mounts.
    ///
    /// The credential mount is read-only and the data directory is separate,
    /// because the request log cannot live on a read-only mount — a lesson the
    /// issue records as a real failure (#570).
    pub mounts: Vec<(String, String, bool)>,
    /// Environment passed to the container. Values are never logged.
    pub env: Vec<(String, String)>,
    pub label: String,
}

/// Everything the deployment needs from a container runtime.
pub trait ContainerRuntime: Send + Sync {
    /// Fail if the runtime is unusable, with an operator-readable reason.
    fn available(&self) -> Result<String, String>;

    /// State of one container by name.
    fn state(&self, name: &str) -> Result<ContainerState, String>;

    /// Create and start a container.
    fn run(&self, spec: &RunSpec) -> Result<(), String>;

    /// Start an existing, stopped container.
    fn start(&self, name: &str) -> Result<(), String>;

    /// Remove a container, running or not.
    fn remove(&self, name: &str) -> Result<(), String>;

    /// Whether an image exists locally.
    fn image_present(&self, image: &str) -> Result<bool, String>;

    /// Build `image` from `context`, at an immutable ref.
    fn build(&self, image: &str, context: &str) -> Result<(), String>;

    /// Fetch `image` from its registry.
    ///
    /// The default image is a *remote* reference, so a machine that has never
    /// built one locally can only get it this way. Without a pull, the default
    /// path of the default command fails on a clean machine.
    fn pull(&self, image: &str) -> Result<(), String>;

    /// The configured image reference a container was created from.
    ///
    /// This deliberately reads `.Config.Image`, not Docker's resolved image id:
    /// convergence compares the requested immutable reference with the launch
    /// specification the operator previously asked Docker to retain.
    fn container_image(&self, name: &str) -> Result<Option<String>, String>;

    /// `GET /api/health` against the published port, following the rule that a
    /// container can be `Up` and not answer.
    fn health(&self, port: u16) -> bool;

    /// Names of containers holding `port`, so a stray instance is found before
    /// traffic silently goes to an old version.
    fn listeners_on(&self, port: u16) -> Result<Vec<String>, String>;

    /// Run a command inside the container, for the token and status steps.
    fn exec(&self, name: &str, arguments: &[&str]) -> Result<String, String>;
}

/// The real runtime: a thin shell around the `docker` CLI.
#[derive(Debug, Default)]
pub struct Docker;

impl Docker {
    fn docker(arguments: &[&str]) -> Result<String, String> {
        let output = crate::operation_context::process_output(
            crate::operation_context::command("docker").args(arguments),
        );
        let output = match output {
            Ok(output) => output,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return Err("Docker is not installed".to_string());
            }
            Err(error) => return Err(error.to_string()),
        };
        if output.status.success() {
            return Ok(String::from_utf8_lossy(&output.stdout).trim().to_string());
        }
        Err(compact(&String::from_utf8_lossy(&output.stderr)))
    }
}

/// Collapse a multi-line command error into one readable line.
fn compact(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Turn a failed `docker info` into an instruction an operator can act on.
///
/// Three different problems arrive as one failure — no binary, no permission, no
/// daemon — and each has a different remedy, so they are distinguished rather
/// than all reported as "Docker is broken".
fn explain_unavailable(error: String) -> String {
    let lowered = error.to_ascii_lowercase();
    if lowered.contains("permission denied") {
        "permission denied while connecting to Docker; add this user to the Docker group"
            .to_string()
    } else if lowered.contains("not installed") {
        error
    } else {
        format!("the Docker daemon is not running or unreachable: {error}")
    }
}

/// Read a container's state out of `docker inspect`'s answer.
///
/// A missing container is [`ContainerState::Absent`] rather than an error: it is
/// the ordinary starting state of a first deployment, and treating it as a
/// failure meant the container that should then have been created never was
/// (issue #333).
fn interpret_state(answer: Result<String, String>) -> Result<ContainerState, String> {
    match answer {
        Ok(rendered) if rendered.trim() == "running" => Ok(ContainerState::Running),
        Ok(_) => Ok(ContainerState::Stopped),
        Err(error) if is_absent(&error) => Ok(ContainerState::Absent),
        Err(error) => Err(error),
    }
}

/// Container names from a `docker ps --format {{.Names}}` listing.
fn parse_names(rendered: &str) -> Vec<String> {
    rendered
        .lines()
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(str::to_string)
        .collect()
}

/// The `docker run` argument list for `spec`.
///
/// Separated from spawning the process because this is where the properties that
/// matter live, and they are the ones worth asserting directly: the credential
/// mount carries `:ro`, the data mount does not, and a secret's *value* never
/// becomes an argument — only its name, with the value handed to the child
/// through its environment, so it cannot appear in `ps` or a shell history
/// (issue #572).
fn run_arguments(spec: &RunSpec) -> Vec<String> {
    let mut arguments: Vec<String> = vec![
        "run".into(),
        "-d".into(),
        "--name".into(),
        spec.name.clone(),
        "--label".into(),
        spec.label.clone(),
        "-p".into(),
        format!("127.0.0.1:{}:8080", spec.port),
    ];
    for (host, container, read_only) in &spec.mounts {
        arguments.push("-v".into());
        arguments.push(if *read_only {
            format!("{host}:{container}:ro")
        } else {
            format!("{host}:{container}")
        });
    }
    for (key, _) in &spec.env {
        arguments.push("-e".into());
        arguments.push(key.clone());
    }
    arguments.push(spec.image.clone());
    arguments.push("serve".into());
    arguments
}

impl ContainerRuntime for Docker {
    fn available(&self) -> Result<String, String> {
        Self::docker(&["info", "--format", "{{.ServerVersion}}"]).map_err(explain_unavailable)
    }

    fn state(&self, name: &str) -> Result<ContainerState, String> {
        interpret_state(Self::docker(&[
            "inspect",
            "--format",
            "{{if .State.Running}}running{{else}}stopped{{end}}",
            name,
        ]))
    }

    fn run(&self, spec: &RunSpec) -> Result<(), String> {
        let mut command = crate::operation_context::command("docker");
        command.args(run_arguments(spec));
        for (key, value) in &spec.env {
            command.env(key, value);
        }
        let output = crate::operation_context::process_output(&mut command)
            .map_err(|error| error.to_string())?;
        if output.status.success() {
            Ok(())
        } else {
            Err(compact(&String::from_utf8_lossy(&output.stderr)))
        }
    }

    fn start(&self, name: &str) -> Result<(), String> {
        Self::docker(&["start", name]).map(|_| ())
    }

    fn remove(&self, name: &str) -> Result<(), String> {
        Self::docker(&["rm", "-f", name]).map(|_| ())
    }

    fn image_present(&self, image: &str) -> Result<bool, String> {
        match Self::docker(&["image", "inspect", "--format", "{{.Id}}", image]) {
            Ok(id) => Ok(!id.is_empty()),
            Err(error) if is_absent(&error) => Ok(false),
            Err(error) => Err(error),
        }
    }

    fn build(&self, image: &str, context: &str) -> Result<(), String> {
        Self::docker(&["build", "-t", image, context]).map(|_| ())
    }

    fn pull(&self, image: &str) -> Result<(), String> {
        Self::docker(&["pull", image]).map(|_| ())
    }

    fn container_image(&self, name: &str) -> Result<Option<String>, String> {
        match Self::docker(&["inspect", "--format", "{{.Config.Image}}", name]) {
            Ok(reference) => Ok(Some(reference)),
            Err(error) if is_absent(&error) => Ok(None),
            Err(error) => Err(error),
        }
    }

    fn health(&self, port: u16) -> bool {
        use std::io::{Read as _, Write as _};

        let Ok(mut stream) = std::net::TcpStream::connect(("127.0.0.1", port)) else {
            return false;
        };
        let _ = stream.set_read_timeout(Some(Duration::from_secs(2)));
        let _ = stream.set_write_timeout(Some(Duration::from_secs(2)));
        if stream
            .write_all(b"GET /api/health HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n")
            .is_err()
        {
            return false;
        }
        let mut response = String::new();
        stream.read_to_string(&mut response).is_ok() && response.starts_with("HTTP/1.1 200")
    }

    fn listeners_on(&self, port: u16) -> Result<Vec<String>, String> {
        let rendered = Self::docker(&[
            "ps",
            "--filter",
            &format!("publish={port}"),
            "--format",
            "{{.Names}}",
        ])?;
        Ok(parse_names(&rendered))
    }

    fn exec(&self, name: &str, arguments: &[&str]) -> Result<String, String> {
        let mut full = vec!["exec", name];
        full.extend_from_slice(arguments);
        Self::docker(&full)
    }
}

/// Whether a Docker error means "that object does not exist".
///
/// Matched case-insensitively because Docker and Docker Desktop disagree on the
/// capitalisation, and reading "does not exist yet" as a hard failure meant the
/// container that should then have been created never was (issue #333).
fn is_absent(error: &str) -> bool {
    let lowered = error.to_ascii_lowercase();
    lowered.contains("no such object")
        || lowered.contains("no such container")
        || lowered.contains("no such image")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn docker_absence_messages_are_recognised_in_either_spelling() {
        // Docker Desktop lowercases this; the capitalised form is Docker's own.
        assert!(is_absent("Error: No such object: router-deploy"));
        assert!(is_absent("error: no such container: router-deploy"));
        assert!(is_absent("No such image: ghcr.io/x:1"));
        // A daemon that is down is *not* an absent container: treating it as one
        // would report a deployment as "needs creating" while nothing can run.
        assert!(!is_absent("Cannot connect to the Docker daemon"));
    }

    #[test]
    fn multiline_command_errors_collapse_to_one_line() {
        assert_eq!(
            compact("failed:\n  because\n  reasons"),
            "failed: because reasons"
        );
    }

    fn spec() -> RunSpec {
        RunSpec {
            name: "router-deploy".into(),
            image: "ghcr.io/link-assistant/router:1.9.0".into(),
            port: 18080,
            mounts: vec![
                ("/host/creds".into(), "/data/claude".into(), true),
                ("/host/data".into(), "/data/router".into(), false),
            ],
            env: vec![
                ("TOKEN_SECRET".into(), "a-real-signing-secret".into()),
                ("STORAGE_POLICY".into(), "text".into()),
            ],
            label: "com.link-assistant.router.deploy=1".into(),
        }
    }

    #[test]
    fn the_credential_mount_is_read_only_and_the_data_mount_is_not() {
        let arguments = run_arguments(&spec());

        // The request log cannot live on a read-only mount, so the two are
        // separate and only one carries `:ro`.
        assert!(
            arguments.contains(&"/host/creds:/data/claude:ro".to_string()),
            "{arguments:?}"
        );
        assert!(
            arguments.contains(&"/host/data:/data/router".to_string()),
            "{arguments:?}"
        );
        assert!(
            !arguments.contains(&"/host/data:/data/router:ro".to_string()),
            "the data mount stays writable: {arguments:?}"
        );
    }

    #[test]
    fn a_secret_value_never_becomes_a_command_line_argument() {
        let spec = spec();
        let arguments = run_arguments(&spec);

        // Argv is visible in `ps` and in shell history. Only the variable's name
        // is passed; the value reaches the child through its environment.
        assert!(
            arguments.contains(&"TOKEN_SECRET".to_string()),
            "the name is passed: {arguments:?}"
        );
        assert!(
            !arguments
                .iter()
                .any(|argument| argument.contains("a-real-signing-secret")),
            "the value is not: {arguments:?}"
        );
        // And it is still handed over, so the container can actually sign.
        assert!(
            spec.env
                .iter()
                .any(|(key, value)| key == "TOKEN_SECRET" && value == "a-real-signing-secret")
        );
    }

    #[test]
    fn the_port_is_published_on_loopback_only() {
        let arguments = run_arguments(&spec());

        // A local deployment must not be reachable from the network merely
        // because it was started: it holds a subscription credential.
        assert!(
            arguments.contains(&"127.0.0.1:18080:8080".to_string()),
            "{arguments:?}"
        );
    }

    #[test]
    fn the_container_is_labelled_and_named_and_serves() {
        let arguments = run_arguments(&spec());

        // The label is what proves a container is this command's to manage, so
        // `--down` cannot remove somebody else's.
        assert!(arguments.contains(&"com.link-assistant.router.deploy=1".to_string()));
        assert!(arguments.contains(&"router-deploy".to_string()));
        assert_eq!(
            arguments.last().map(String::as_str),
            Some("serve"),
            "the image's command comes last: {arguments:?}"
        );
        assert_eq!(
            arguments.first().map(String::as_str),
            Some("run"),
            "{arguments:?}"
        );
    }

    /// Serve one canned HTTP response on an ephemeral port, then stop.
    ///
    /// The health probe is real HTTP against a real socket, so it is testable
    /// without Docker — and worth testing, because "is this deployment ready"
    /// must mean a `200` from `/api/health` rather than anything that answers.
    fn serve_once(status_line: &'static str) -> u16 {
        use std::io::{Read as _, Write as _};

        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind");
        let port = listener.local_addr().expect("address").port();
        std::thread::spawn(move || {
            if let Ok((mut stream, _)) = listener.accept() {
                let mut scratch = [0_u8; 1024];
                let _ = stream.read(&mut scratch);
                let _ = stream.write_all(status_line.as_bytes());
            }
        });
        port
    }

    #[test]
    fn health_is_a_200_from_the_health_route_and_nothing_else() {
        let runtime = Docker;

        assert!(
            runtime.health(serve_once("HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok")),
            "a 200 is healthy"
        );
        // A listener that answers but not with success is not readiness: a
        // container can be Up, bound, and still failing every request.
        assert!(
            !runtime.health(serve_once(
                "HTTP/1.1 503 Service Unavailable\r\nContent-Length: 0\r\n\r\n"
            )),
            "a 503 is not healthy"
        );
    }

    #[test]
    fn a_port_nobody_listens_on_is_not_healthy() {
        // Bind and drop, so the port is almost certainly free and nothing is
        // accepting: the probe must answer false rather than block or panic.
        let port = std::net::TcpListener::bind("127.0.0.1:0")
            .expect("bind")
            .local_addr()
            .expect("address")
            .port();

        assert!(!Docker.health(port));
    }

    #[test]
    fn an_unusable_runtime_is_explained_by_its_actual_cause() {
        // Three problems, three remedies. Reporting them all as "Docker is
        // broken" would leave an operator guessing which one they have.
        assert!(
            explain_unavailable("Got permission denied while trying to connect".into())
                .contains("Docker group")
        );
        assert_eq!(
            explain_unavailable("Docker is not installed".into()),
            "Docker is not installed",
            "the precise message is kept rather than wrapped"
        );
        let down = explain_unavailable("Cannot connect to the Docker daemon".into());
        assert!(down.contains("not running or unreachable"), "{down}");
        assert!(
            down.contains("Cannot connect"),
            "the daemon's own words survive: {down}"
        );
    }

    #[test]
    fn a_missing_container_reads_as_absent_rather_than_as_an_error() {
        // The ordinary starting state of a first deployment. Reading it as a
        // failure meant the container that should then have been created never
        // was (issue #333).
        assert_eq!(
            interpret_state(Err("Error: No such object: router-deploy".into())),
            Ok(ContainerState::Absent)
        );
        assert_eq!(
            interpret_state(Ok("running".into())),
            Ok(ContainerState::Running)
        );
        assert_eq!(
            interpret_state(Ok("stopped".into())),
            Ok(ContainerState::Stopped)
        );
        // Trailing whitespace from the format string must not read as stopped.
        assert_eq!(
            interpret_state(Ok("running\n".into())),
            Ok(ContainerState::Running)
        );
        // A genuinely broken daemon stays an error: it is not an absent
        // container, and creating one would not fix it.
        assert!(interpret_state(Err("daemon went away".into())).is_err());
    }

    #[test]
    fn a_listing_yields_one_name_per_line_and_ignores_blanks() {
        assert_eq!(
            parse_names("router-deploy\nsomething-else\n"),
            vec!["router-deploy".to_string(), "something-else".to_string()]
        );
        // An empty listing means nothing else holds the port, which must not
        // read as one container with an empty name.
        assert!(parse_names("").is_empty());
        assert!(parse_names("\n  \n").is_empty());
    }

    #[test]
    fn container_states_have_stable_spellings() {
        // Reported to operators and asserted on by tests, so they are contract.
        assert_eq!(ContainerState::Absent.as_str(), "absent");
        assert_eq!(ContainerState::Running.as_str(), "running");
        assert_eq!(ContainerState::Stopped.as_str(), "stopped");
    }
}

//! The converge step: check the desired state, then act only if it does not hold.
//!
//! Every deployment step answers three questions in order — what did I check,
//! what did I find, and what did I do — because a deployment that fails has to
//! name the step rather than produce a stack trace (issues #570, #572).
//!
//! ## Why converge rather than run
//!
//! A step that acts unconditionally cannot be re-run: it restarts a healthy
//! container, re-mints a token that was fine, and gives an operator no way to
//! ask "what is missing?" without changing something. A step that checks first
//! is idempotent by construction, which is what makes the whole command usable
//! as a test fixture — a test can call it unconditionally, and a converged
//! deployment performs no actions at all.
//!
//! ## Why a skip is not a pass
//!
//! A step that quietly does nothing is indistinguishable from a step that
//! succeeded, and that ambiguity hid a real failure: a deployment with a
//! withdrawn subscription reported itself healthy while being impossible to
//! update. So [`Outcome::Skipped`] carries the reason, and it is printed.

use std::fmt;
use std::time::Duration;

/// What one step did.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Outcome {
    /// The desired state already held; nothing was done.
    ///
    /// A converged deployment is a run made entirely of these.
    AlreadyConverged(String),
    /// The step changed something to reach the desired state.
    Acted(String),
    /// The step could not run, and this is why.
    ///
    /// Never silent: an unmet prerequisite an operator did not ask about is the
    /// difference between "healthy" and "healthy but unable to serve".
    Skipped(String),
}

impl Outcome {
    /// Short tag used in reports and assertions.
    #[must_use]
    pub const fn tag(&self) -> &'static str {
        match self {
            Self::AlreadyConverged(_) => "already",
            Self::Acted(_) => "acted",
            Self::Skipped(_) => "skipped",
        }
    }

    /// What the step observed or did.
    #[must_use]
    pub fn detail(&self) -> &str {
        match self {
            Self::AlreadyConverged(detail) | Self::Acted(detail) | Self::Skipped(detail) => detail,
        }
    }

    /// Whether this outcome changed the deployment.
    ///
    /// The property `--status` relies on: a report must be able to prove it
    /// touched nothing.
    #[must_use]
    pub const fn changed_anything(&self) -> bool {
        matches!(self, Self::Acted(_))
    }
}

/// A step that failed, with everything needed to act on it.
///
/// The shape exists because an exception is not actionable. `expected` and
/// `found` are separate fields so a test can assert on the *shape* of a failure
/// report rather than on a message, and `purpose` explains what the check
/// protects — for the operator who did not write the step.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Failure {
    /// The step's name, so the failure names a step rather than a stack frame.
    pub step: &'static str,
    /// One sentence on what this check is for.
    pub purpose: &'static str,
    /// The state the step required.
    pub expected: String,
    /// The state it actually observed.
    pub found: String,
}

impl fmt::Display for Failure {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "step {} failed\n  expected: {}\n  found:    {}\n  why:      {}",
            self.step, self.expected, self.found, self.purpose
        )
    }
}

/// One step's result, with the time it took.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StepReport {
    pub step: &'static str,
    pub outcome: Result<Outcome, Failure>,
    pub took: Duration,
}

impl StepReport {
    /// The line an operator reads for this step.
    #[must_use]
    pub fn line(&self) -> String {
        let millis = self.took.as_millis();
        match &self.outcome {
            Ok(outcome) => format!(
                "{:<22} {:<8} {} ({millis} ms)",
                self.step,
                outcome.tag(),
                outcome.detail()
            ),
            Err(failure) => format!("{:<22} {:<8} {}", self.step, "failed", failure.expected),
        }
    }

    #[must_use]
    pub const fn failed(&self) -> bool {
        self.outcome.is_err()
    }
}

/// Everything a converge run did, in order.
///
/// Timing is per step because "deployment is slow" is unactionable: it took
/// per-step totals to learn that a cutover spent almost all of its wall clock in
/// one build and seconds everywhere else (issue #572).
#[derive(Debug, Default)]
pub struct Report {
    pub steps: Vec<StepReport>,
}

impl Report {
    /// Record one step, timing it.
    ///
    /// Steps run in order and stop at the first failure: a deployment that
    /// continues past a failed prerequisite produces a second, confusing failure
    /// whose cause is the first one.
    pub fn run(
        &mut self,
        step: &'static str,
        action: impl FnOnce() -> Result<Outcome, Failure>,
    ) -> bool {
        let started = std::time::Instant::now();
        let outcome = action();
        let failed = outcome.is_err();
        self.steps.push(StepReport {
            step,
            outcome,
            took: started.elapsed(),
        });
        !failed
    }

    /// Whether the run converged without failing.
    #[must_use]
    pub fn converged(&self) -> bool {
        self.steps.iter().all(|step| !step.failed())
    }

    /// Whether anything at all was changed.
    #[must_use]
    pub fn changed_anything(&self) -> bool {
        self.steps
            .iter()
            .filter_map(|step| step.outcome.as_ref().ok())
            .any(Outcome::changed_anything)
    }

    /// The failure that stopped the run, if one did.
    #[must_use]
    pub fn failure(&self) -> Option<&Failure> {
        self.steps
            .iter()
            .find_map(|step| step.outcome.as_ref().err())
    }

    /// Steps that skipped, with their reasons.
    #[must_use]
    pub fn skips(&self) -> Vec<(&'static str, &str)> {
        self.steps
            .iter()
            .filter_map(|step| match step.outcome.as_ref().ok()? {
                Outcome::Skipped(reason) => Some((step.step, reason.as_str())),
                _ => None,
            })
            .collect()
    }

    /// Total wall clock across every step.
    #[must_use]
    pub fn total(&self) -> Duration {
        self.steps.iter().map(|step| step.took).sum()
    }

    /// Print the report an operator reads.
    pub fn print(&self) {
        for step in &self.steps {
            println!("{}", step.line());
        }
        if let Some(failure) = self.failure() {
            eprintln!("\n{failure}");
        }
        // Skips are repeated at the end: in a long run the one line that
        // explains why nothing was provisioned scrolls past.
        let skips = self.skips();
        if !skips.is_empty() {
            println!("\nskipped:");
            for (step, reason) in skips {
                println!("  {step}: {reason}");
            }
        }
        println!("\ntotal {} ms", self.total().as_millis());
    }
}

//! Deployment operation APIs share the CLI implementation and result schema.
use crate::cli::{Command, DeployArgs, DeployMode};
use crate::operation_context::OperationContext;
use crate::operations::{OperationError, OperationResult};

/// Inspectable local deployment plan; creating a plan performs no process calls.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LocalPlan {
    /// Effective deployment filesystem root.
    pub root: std::path::PathBuf,
    /// Immutable image reference.
    pub image: String,
    /// Stable front-door port.
    pub port: u16,
    /// Host or container deployment mode.
    pub mode: String,
}

/// A rejected plan, before any deployment mutation or process execution.
#[derive(Debug, Clone)]
pub struct PlanError(pub String);
impl std::fmt::Display for PlanError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(&self.0)
    }
}
impl std::error::Error for PlanError {}

/// Resolve a local plan without applying it.
/// ```no_run
/// # async fn example() -> Result<(), Box<dyn std::error::Error>> {
/// use link_assistant_router::{deploy::local, cli::{Command, try_parse_arguments}, operation_context::OperationContext};
/// let cli = try_parse_arguments(vec!["router".into(), "deploy".into(), "--image".into(), "router:v1.0.0".into()])?;
/// let Some(Command::Deploy(args)) = cli.command else { unreachable!() };
/// let plan = local::plan(&OperationContext::default(), &args)?;
/// assert_eq!(plan.port, 8080);
/// # Ok(()) }
/// ```
pub fn plan(context: &OperationContext, arguments: &DeployArgs) -> Result<LocalPlan, PlanError> {
    context
        .scope(|| {
            let (args, _, remote) = crate::deploy_cli::resolve(arguments)?;
            if remote {
                return Err("local plan received a remote target".into());
            }
            let data = context
                .data_dir
                .clone()
                .unwrap_or_else(crate::config::default_data_dir);
            let root = args.root.as_ref().map_or_else(
                || {
                    let name = args.settings.instance.as_deref().map_or_else(
                        || Ok("deploy".to_owned()),
                        |name| {
                            crate::deploy::instance::validate(name)?;
                            Ok::<_, String>(format!("deploy-{name}"))
                        },
                    )?;
                    Ok(data.join(name))
                },
                |root| crate::deploy_config::expand_home(root),
            )?;
            let root = if root.is_absolute() {
                root
            } else {
                context.working_directory.join(root)
            };
            let image = args
                .image
                .clone()
                .unwrap_or_else(|| format!("ghcr.io/link-assistant/router:{}", crate::VERSION));
            crate::deploy::immutable_ref(&image)?;
            Ok(LocalPlan {
                root,
                image,
                port: args.port(),
                mode: if args.mode == Some(DeployMode::Host) {
                    "host"
                } else {
                    "container"
                }
                .into(),
            })
        })
        .map_err(PlanError)
}

/// Apply a deployment with typed options and dependencies.
/// ```no_run
/// # async fn example(args: link_assistant_router::cli::DeployArgs) -> Result<(), Box<dyn std::error::Error>> {
/// use link_assistant_router::{deploy::local, operation_context::OperationContext};
/// let result = local::apply(OperationContext::default(), args).await?;
/// assert!(result.success);
/// # Ok(()) }
/// ```
pub async fn apply(
    context: OperationContext,
    arguments: DeployArgs,
) -> Result<OperationResult, OperationError> {
    crate::operations::request(context, Command::Deploy(arguments)).await
}

/// Inspect deployment status using the same report as `deploy --status --json`.
/// ```no_run
/// # async fn example(args: link_assistant_router::cli::DeployArgs) -> Result<(), Box<dyn std::error::Error>> {
/// let report = link_assistant_router::deploy::local::status(Default::default(), args).await?;
/// assert_eq!(report.operation, "deploy");
/// # Ok(()) }
/// ```
pub async fn status(
    context: OperationContext,
    mut arguments: DeployArgs,
) -> Result<OperationResult, OperationError> {
    arguments.status = true;
    apply(context, arguments).await
}

/// Deploy directly as a supervised or unsupervised host process.
/// ```no_run
/// # async fn example(args: link_assistant_router::cli::DeployArgs) -> Result<(), Box<dyn std::error::Error>> {
/// link_assistant_router::deploy::host::apply(Default::default(), args).await?;
/// # Ok(()) }
/// ```
pub async fn host(
    context: OperationContext,
    mut arguments: DeployArgs,
) -> Result<OperationResult, OperationError> {
    arguments.mode = Some(DeployMode::Host);
    apply(context, arguments).await
}

/// Apply remote SSH settings through the existing bounded remote coordinator.
/// ```no_run
/// # async fn example(args: link_assistant_router::cli::DeployArgs) -> Result<(), Box<dyn std::error::Error>> {
/// link_assistant_router::deploy::remote::apply(Default::default(), args).await?;
/// # Ok(()) }
/// ```
pub async fn remote(
    context: OperationContext,
    mut arguments: DeployArgs,
) -> Result<OperationResult, OperationError> {
    arguments.settings.remote = true;
    apply(context, arguments).await
}

/// Rehearse a deployment in an isolated staging namespace.
/// ```no_run
/// # async fn example(args: link_assistant_router::cli::DeployArgs) -> Result<(), Box<dyn std::error::Error>> {
/// link_assistant_router::deploy::staging::apply(Default::default(), "rehearsal", args).await?;
/// # Ok(()) }
/// ```
pub async fn staging(
    context: OperationContext,
    namespace: &str,
    mut arguments: DeployArgs,
) -> Result<OperationResult, OperationError> {
    arguments.staging = Some(namespace.into());
    apply(context, arguments).await
}

/// Restore a checkpoint after the coordinator proves all writers have stopped.
/// ```no_run
/// # async fn example(args: link_assistant_router::cli::DeployArgs) -> Result<(), Box<dyn std::error::Error>> {
/// link_assistant_router::deploy::checkpoint::restore(Default::default(), args, "/tmp/checkpoint".as_ref(), false).await?;
/// # Ok(()) }
/// ```
pub async fn restore(
    context: OperationContext,
    mut arguments: DeployArgs,
    snapshot: &std::path::Path,
    replace: bool,
) -> Result<OperationResult, OperationError> {
    arguments.restore_state = Some(snapshot.into());
    arguments.replace_state = replace;
    apply(context, arguments).await
}

/// Inspect a host deployment using the host runtime.
pub async fn host_status(
    context: OperationContext,
    mut arguments: DeployArgs,
) -> Result<OperationResult, OperationError> {
    arguments.status = true;
    host(context, arguments).await
}
/// Inspect a remote deployment using the SSH coordinator.
pub async fn remote_status(
    context: OperationContext,
    mut arguments: DeployArgs,
) -> Result<OperationResult, OperationError> {
    arguments.status = true;
    remote(context, arguments).await
}

//! Declarative `router deploy --config <file>` (issues #679, #680, #683).
//!
//! Downstreams wrapped `router deploy` in their own scripts only because a few
//! settings could not be expressed through it: runtime environment for the
//! backend, an instance name so deployments can share a host, SSH transport
//! options, limits for the tokens deploy issues, provider keys to rotate in
//! the candidate, and what verification must prove before cutover. This
//! module reads all of them from one TOML file. Command-line flags override
//! the file, key by key.
//!
//! Secret values never appear in the file or in argv: the file and the flags
//! name a source (`env:VAR` or `file:PATH`), and the value is read from it at
//! run time. A [`ResolvedDeploy`] holds the values and redacts them from its
//! `Debug` output.

use std::collections::BTreeMap;
use std::fmt;
use std::path::{Path, PathBuf};

use serde::Serialize;
use toml_edit::{DocumentMut, Item, TableLike};

#[path = "deploy_config_hmac.rs"]
mod hmac;
#[path = "deploy_config_merge.rs"]
mod merge;
#[path = "deploy_config_paths.rs"]
mod paths;

pub use hmac::{env_fingerprint, hmac_sha256_hex, value_fingerprint};
pub use merge::{Merged, merge};
pub use paths::expand_home;

/// Names the backend owns itself, or which select its security posture.
///
/// Passing them through would let a config file silently replace the
/// deployment's own signing secret, data directory or listener layout.
const RESERVED_ENV: &[&str] = &[
    "TOKEN_SECRET",
    "DATA_DIR",
    "STORAGE_POLICY",
    "HOME",
    "PATH",
    "USER",
    "SHELL",
    "PWD",
    "IFS",
    "CLAUDE_CODE_HOME",
    "CLAUDE_CONFIG_DIR",
    "LISTENERS",
    "ROUTER_HOST",
    "ROUTER_PORT",
    "NODE_EXTRA_CA_CERTS",
];
/// Prefixes reserved for the deployment machinery and its verifier.
const RESERVED_ENV_PREFIXES: &[&str] = &["ROUTER_DEPLOY_", "TLS_", "VERIFY_", "PRESERVATION_"];

/// Where a secret value comes from. The value itself never travels in argv.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SecretSource {
    /// The caller's environment variable of this name.
    Env(String),
    /// The contents of this file, minus one trailing newline.
    File(PathBuf),
}

impl SecretSource {
    /// Parse `env:VAR` or `file:PATH`. A bare `env` means `env:<default_env>`.
    ///
    /// # Errors
    ///
    /// Refuses anything else, so a literal value can never be mistaken for a
    /// source and end up in a shell history or a process listing.
    pub fn parse(
        spec: &str,
        default_env: Option<&str>,
        base: Option<&Path>,
    ) -> Result<Self, String> {
        if spec == "env" {
            return default_env
                .map(|name| Self::Env(name.to_string()))
                .ok_or_else(|| "`env` needs a variable name here: use env:VAR".to_string());
        }
        if let Some(name) = spec.strip_prefix("env:") {
            validate_variable(name)?;
            return Ok(Self::Env(name.to_string()));
        }
        if let Some(path) = spec.strip_prefix("file:") {
            if path.is_empty() {
                return Err("file: needs a path".to_string());
            }
            let path = PathBuf::from(path);
            let path = match base {
                Some(base) if path.is_relative() => base.join(path),
                _ => path,
            };
            return Ok(Self::File(path));
        }
        Err(
            "a value source must be env:VAR or file:PATH; literal values are refused so they \
             never reach argv or a config file"
                .to_string(),
        )
    }

    /// Read the value from its source.
    ///
    /// # Errors
    ///
    /// Names the source (never a value) when it is missing or unreadable.
    pub fn read(&self) -> Result<String, String> {
        let value = match self {
            Self::Env(name) => crate::operation_context::var(name)
                .map_err(|_| format!("environment variable {name} is not set or not UTF-8"))?,
            Self::File(path) => {
                let mut text = std::fs::read_to_string(path)
                    .map_err(|error| format!("could not read {}: {error}", path.display()))?;
                if text.ends_with('\n') {
                    text.pop();
                    if text.ends_with('\r') {
                        text.pop();
                    }
                }
                text
            }
        };
        if value.contains(['\n', '\r', '\0']) {
            return Err(format!(
                "the value from {} contains a newline or NUL byte",
                self.describe()
            ));
        }
        Ok(value)
    }

    /// The source, for messages. Never the value.
    #[must_use]
    pub fn describe(&self) -> String {
        match self {
            Self::Env(name) => format!("env:{name}"),
            Self::File(path) => format!("file:{}", path.display()),
        }
    }
}

fn validate_variable(name: &str) -> Result<(), String> {
    let mut bytes = name.bytes();
    let valid = bytes
        .next()
        .is_some_and(|first| first.is_ascii_uppercase() || first == b'_')
        && bytes.all(|byte| byte.is_ascii_uppercase() || byte.is_ascii_digit() || byte == b'_');
    if valid {
        Ok(())
    } else {
        Err(format!(
            "`{name}` is not an environment variable name ([A-Z_][A-Z0-9_]*)"
        ))
    }
}

/// Validate a runtime environment name passed through to the backend.
///
/// # Errors
///
/// Refuses malformed names and names the deployment owns itself.
pub fn validate_env_name(name: &str) -> Result<(), String> {
    validate_variable(name)?;
    if RESERVED_ENV.contains(&name)
        || RESERVED_ENV_PREFIXES
            .iter()
            .any(|prefix| name.starts_with(prefix))
    {
        return Err(format!(
            "`{name}` is set by the deployment itself and cannot be passed through"
        ));
    }
    Ok(())
}

/// One runtime environment variable passed through by name.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EnvSpec {
    /// The name the backend sees.
    pub name: String,
    /// Where its value comes from.
    pub source: SecretSource,
}

impl EnvSpec {
    /// Parse `NAME` (from the caller's `NAME`) or `NAME=env:VAR|file:PATH`.
    ///
    /// # Errors
    ///
    /// Refuses reserved or malformed names and literal values.
    pub fn parse(flag: &str, base: Option<&Path>) -> Result<Self, String> {
        let (name, spec) = flag.split_once('=').unwrap_or((flag, "env"));
        validate_env_name(name)?;
        Ok(Self {
            name: name.to_string(),
            source: SecretSource::parse(spec, Some(name), base)
                .map_err(|error| format!("--env {name}: {error}"))?,
        })
    }
}

/// SSH transport settings for `--server`.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct SshSettings {
    /// `ssh -p`.
    pub port: Option<u16>,
    /// `ssh -i`, with `IdentitiesOnly=yes`.
    pub identity_file: Option<PathBuf>,
    /// Pinned `known_hosts` lines; only these keys are trusted.
    pub known_hosts: Vec<String>,
    /// A pinned `known_hosts` file; only its keys are trusted.
    pub known_hosts_file: Option<PathBuf>,
    /// `ServerAliveInterval`, in seconds.
    pub keepalive_secs: Option<u32>,
    /// Overall session deadline, in seconds.
    pub deadline_secs: Option<u64>,
}

/// Limits for the client token a deployment issues.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize)]
pub struct TokenPolicy {
    /// Lifetime of the issued token.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ttl_hours: Option<i64>,
    /// Cap on upstream requests.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub max_requests: Option<u64>,
    /// Cap on input plus output tokens.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub max_tokens: Option<u64>,
    /// Requests admitted per minute.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rate_limit_per_minute: Option<u64>,
    /// Exact model ids the token may request; empty means any.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub allowed_models: Vec<String>,
}

impl TokenPolicy {
    /// Whether any limit is configured.
    #[must_use]
    pub fn is_limited(&self) -> bool {
        self != &Self::default()
    }

    /// `router tokens issue` arguments expressing this policy.
    #[must_use]
    pub fn issue_arguments(&self) -> Vec<String> {
        let mut arguments = Vec::new();
        let numeric = [
            ("--ttl-hours", self.ttl_hours.map(|value| value.to_string())),
            (
                "--max-requests",
                self.max_requests.map(|value| value.to_string()),
            ),
            (
                "--max-tokens",
                self.max_tokens.map(|value| value.to_string()),
            ),
            (
                "--rate-limit-per-minute",
                self.rate_limit_per_minute.map(|value| value.to_string()),
            ),
        ];
        for (flag, value) in numeric {
            if let Some(value) = value {
                arguments.extend([flag.to_string(), value]);
            }
        }
        for model in &self.allowed_models {
            arguments.extend(["--allowed-model".to_string(), model.clone()]);
        }
        arguments
    }
}

/// What `--provider-key` does with a key for a provider.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, clap::ValueEnum)]
#[serde(rename_all = "kebab-case")]
pub enum ProviderKeyMode {
    /// Validate only; the stored key is never changed (today's behaviour).
    #[default]
    Keep,
    /// Add the provider only when the target has none of that name.
    IfAbsent,
    /// Replace the stored key, only after the new one validated.
    Replace,
}

impl ProviderKeyMode {
    /// The stable spelling used in config, the agent and JSON.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Keep => "keep",
            Self::IfAbsent => "if-absent",
            Self::Replace => "replace",
        }
    }

    fn parse(text: &str) -> Result<Self, String> {
        match text {
            "keep" => Ok(Self::Keep),
            "if-absent" => Ok(Self::IfAbsent),
            "replace" => Ok(Self::Replace),
            other => Err(format!(
                "provider key mode `{other}` must be keep, if-absent or replace"
            )),
        }
    }
}

/// Provider fields used when a key adds a provider the target lacks.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize)]
pub struct ProviderTemplate {
    /// `providers add --kind`.
    pub kind: String,
    /// `providers add --base-url`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub base_url: Option<String>,
    /// `providers add --model`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_model: Option<String>,
    /// `providers add --models`.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub models: Vec<String>,
    /// `providers add --supported-client`.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub supported_clients: Vec<String>,
}

/// One `--provider-key NAME=SOURCE`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProviderKeySpec {
    /// Provider name on the target.
    pub name: String,
    /// Where the key comes from.
    pub source: SecretSource,
    /// Per-key mode; falls back to `--provider-key-mode`.
    pub mode: Option<ProviderKeyMode>,
    /// Fields for adding a provider the target does not have yet.
    pub template: Option<ProviderTemplate>,
}

impl ProviderKeySpec {
    /// Parse `NAME=env:VAR|file:PATH`.
    ///
    /// # Errors
    ///
    /// Refuses a missing name or a literal value.
    pub fn parse(flag: &str, base: Option<&Path>) -> Result<Self, String> {
        let (name, spec) = flag
            .split_once('=')
            .ok_or("--provider-key needs NAME=env:VAR or NAME=file:PATH")?;
        validate_provider_name(name)?;
        Ok(Self {
            name: name.to_string(),
            source: SecretSource::parse(spec, None, base)
                .map_err(|error| format!("--provider-key {name}: {error}"))?,
            mode: None,
            template: None,
        })
    }
}

fn validate_provider_name(name: &str) -> Result<(), String> {
    let valid = !name.is_empty()
        && name.len() <= 64
        && name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'));
    if valid {
        Ok(())
    } else {
        Err(format!(
            "provider name `{name}` must be letters, digits, `-`, `_` or `.`"
        ))
    }
}

/// What deploy verification must prove before cutover (issue #683).
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize)]
pub struct VerificationProfile {
    /// Client kinds that must be proven (catalog, scoping, live answer).
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub clients: Vec<String>,
    /// Providers that must be proven with a live request.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub providers: Vec<String>,
    /// One exact verification model per provider and client:
    /// `models[provider][client] = model`.
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    pub models: BTreeMap<String, BTreeMap<String, String>>,
    /// Launch `router with <client>` against a stub client inside the
    /// candidate, so the generated launch is proven, not only the HTTP API.
    pub require_client_launch: bool,
    /// Count "quota exhausted" as proven only with upstream evidence (an
    /// `upstream_request` entry or correlation id in the request log).
    pub quota_requires_upstream_evidence: bool,
    /// Check that Claude thinking is displayed as configured: the generated
    /// `--settings` and, when a model is set, one live thinking request.
    pub check_thinking_display: bool,
}

/// `[deploy]`, `[local]` or `[remote]` keys that mirror command-line flags.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct DeploySection {
    /// `--server`.
    pub server: Option<String>,
    /// `--instance`.
    pub instance: Option<String>,
    /// `--port`.
    pub port: Option<u16>,
    /// `--public-port`.
    pub public_port: Option<u16>,
    /// `--image`.
    pub image: Option<String>,
    /// `--build`.
    pub build: Option<String>,
    /// `--root`.
    pub root: Option<String>,
    /// `--mode` (`container` or `host`).
    pub mode: Option<String>,
    /// `--claude-credentials` (`isolated` or `share`).
    pub claude_credentials: Option<String>,
    /// `--seed-credential`, repeated (remote only).
    pub seed_credentials: Vec<String>,
}

impl DeploySection {
    fn overlay(&mut self, other: &Self) {
        macro_rules! take {
            ($($field:ident),*) => {$(
                if other.$field.is_some() { self.$field.clone_from(&other.$field); }
            )*};
        }
        take!(
            server,
            instance,
            port,
            public_port,
            image,
            build,
            root,
            mode,
            claude_credentials
        );
        if !other.seed_credentials.is_empty() {
            self.seed_credentials.clone_from(&other.seed_credentials);
        }
    }
}

/// A parsed deploy configuration file.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct DeployConfig {
    /// `[deploy]`.
    pub deploy: DeploySection,
    /// `[local]`: overrides `[deploy]` for local (container or host) runs.
    pub local: DeploySection,
    /// `[remote]`: overrides `[deploy]` for `--server` runs.
    pub remote: DeploySection,
    /// `[env]`.
    pub env: Vec<EnvSpec>,
    /// `[ssh]`.
    pub ssh: SshSettings,
    /// `[tokens]`.
    pub tokens: TokenPolicy,
    /// `[provider_keys.NAME]`.
    pub provider_keys: Vec<ProviderKeySpec>,
    /// `[verification]`.
    pub verification: Option<VerificationProfile>,
}

impl DeployConfig {
    /// The `[deploy]` keys with the target's overlay applied.
    #[must_use]
    pub fn section_for(&self, remote: bool) -> DeploySection {
        let mut section = self.deploy.clone();
        section.overlay(if remote { &self.remote } else { &self.local });
        section
    }

    /// Read and parse a config file. Relative paths in it are resolved
    /// against the file's directory.
    ///
    /// # Errors
    ///
    /// Names the file and the offending key.
    pub fn load(path: &Path) -> Result<Self, String> {
        let text = std::fs::read_to_string(path)
            .map_err(|error| format!("could not read {}: {error}", path.display()))?;
        Self::parse(&text, path.parent()).map_err(|error| format!("{}: {error}", path.display()))
    }

    /// Parse config text.
    ///
    /// # Errors
    ///
    /// Refuses unknown sections and keys, so a typo is never silently ignored.
    pub fn parse(text: &str, base: Option<&Path>) -> Result<Self, String> {
        let document = text
            .parse::<DocumentMut>()
            .map_err(|error| format!("invalid TOML: {error}"))?;
        let mut config = Self::default();
        for (key, item) in document.iter() {
            let table = item
                .as_table_like()
                .ok_or_else(|| format!("`{key}` must be a table"))?;
            match key {
                "deploy" => config.deploy = parse_section(table, key, base)?,
                "local" => config.local = parse_section(table, key, base)?,
                "remote" => config.remote = parse_section(table, key, base)?,
                "env" => config.env = parse_env_table(table, base)?,
                "ssh" => config.ssh = parse_ssh(table, base)?,
                "tokens" => config.tokens = parse_tokens(table)?,
                "provider_keys" => config.provider_keys = parse_provider_keys(table, base)?,
                "verification" => config.verification = Some(parse_verification(table)?),
                other => return Err(format!("unknown section [{other}]")),
            }
        }
        Ok(config)
    }
}

/// Parse a verification profile file: either a `[verification]` table or
/// the same keys at the top level.
///
/// # Errors
///
/// Refuses unknown keys and malformed values.
pub fn parse_verification_profile(text: &str) -> Result<VerificationProfile, String> {
    let document = text
        .parse::<DocumentMut>()
        .map_err(|error| format!("invalid TOML: {error}"))?;
    let table = document
        .get("verification")
        .and_then(Item::as_table_like)
        .unwrap_or_else(|| document.as_table());
    parse_verification(table)
}

/// Load a verification profile file.
///
/// # Errors
///
/// Names the file and the offending key.
pub fn load_verification_profile(path: &Path) -> Result<VerificationProfile, String> {
    let text = std::fs::read_to_string(path)
        .map_err(|error| format!("could not read {}: {error}", path.display()))?;
    parse_verification_profile(&text).map_err(|error| format!("{}: {error}", path.display()))
}

fn check_keys(table: &dyn TableLike, section: &str, allowed: &[&str]) -> Result<(), String> {
    for (key, _) in table.iter() {
        if !allowed.contains(&key) {
            return Err(format!("unknown key `{key}` in [{section}]"));
        }
    }
    Ok(())
}

fn string(table: &dyn TableLike, section: &str, key: &str) -> Result<Option<String>, String> {
    table.get(key).map_or(Ok(None), |item| {
        item.as_str()
            .map(|value| Some(value.to_string()))
            .ok_or_else(|| format!("[{section}] {key} must be a string"))
    })
}

fn integer<T: TryFrom<i64>>(
    table: &dyn TableLike,
    section: &str,
    key: &str,
) -> Result<Option<T>, String> {
    table.get(key).map_or(Ok(None), |item| {
        item.as_integer()
            .and_then(|value| T::try_from(value).ok())
            .map(Some)
            .ok_or_else(|| format!("[{section}] {key} must be an integer in range"))
    })
}

fn boolean(table: &dyn TableLike, section: &str, key: &str) -> Result<bool, String> {
    table.get(key).map_or(Ok(false), |item| {
        item.as_bool()
            .ok_or_else(|| format!("[{section}] {key} must be true or false"))
    })
}

fn strings(table: &dyn TableLike, section: &str, key: &str) -> Result<Vec<String>, String> {
    let Some(item) = table.get(key) else {
        return Ok(Vec::new());
    };
    if let Some(single) = item.as_str() {
        return Ok(vec![single.to_string()]);
    }
    item.as_array()
        .ok_or_else(|| format!("[{section}] {key} must be a string or an array of strings"))?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(str::to_string)
                .ok_or_else(|| format!("[{section}] {key} must contain only strings"))
        })
        .collect()
}

fn path(
    table: &dyn TableLike,
    section: &str,
    key: &str,
    base: Option<&Path>,
) -> Result<Option<PathBuf>, String> {
    string(table, section, key)?
        .map(|value| paths::config_path(&value, base, key == "root"))
        .transpose()
}

fn parse_section(
    table: &dyn TableLike,
    section: &str,
    base: Option<&Path>,
) -> Result<DeploySection, String> {
    check_keys(
        table,
        section,
        &[
            "server",
            "instance",
            "port",
            "public_port",
            "image",
            "build",
            "root",
            "mode",
            "claude_credentials",
            "seed_credentials",
        ],
    )?;
    let instance = string(table, section, "instance")?;
    if let Some(instance) = &instance {
        crate::deploy::instance::validate(instance)?;
    }
    let root = path(table, section, "root", base)?.map(|root| root.display().to_string());
    Ok(DeploySection {
        server: string(table, section, "server")?,
        instance,
        port: integer(table, section, "port")?,
        public_port: integer(table, section, "public_port")?,
        image: string(table, section, "image")?,
        // A build context is a path on the target for remote deploys, so it
        // is never resolved against the local config directory.
        build: string(table, section, "build")?,
        root,
        mode: string(table, section, "mode")?,
        claude_credentials: string(table, section, "claude_credentials")?,
        seed_credentials: strings(table, section, "seed_credentials")?,
    })
}

fn parse_env_table(table: &dyn TableLike, base: Option<&Path>) -> Result<Vec<EnvSpec>, String> {
    table
        .iter()
        .map(|(name, item)| {
            let spec = item.as_str().ok_or_else(|| {
                format!("[env] {name} must be \"env\", \"env:VAR\" or \"file:PATH\"")
            })?;
            EnvSpec::parse(&format!("{name}={spec}"), base)
        })
        .collect()
}

fn parse_ssh(table: &dyn TableLike, base: Option<&Path>) -> Result<SshSettings, String> {
    const SECTION: &str = "ssh";
    check_keys(
        table,
        SECTION,
        &[
            "port",
            "identity_file",
            "known_hosts",
            "known_hosts_file",
            "keepalive_secs",
            "deadline_secs",
        ],
    )?;
    let known_hosts = strings(table, SECTION, "known_hosts")?;
    validate_known_hosts(&known_hosts)?;
    Ok(SshSettings {
        port: integer(table, SECTION, "port")?,
        identity_file: path(table, SECTION, "identity_file", base)?,
        known_hosts,
        known_hosts_file: path(table, SECTION, "known_hosts_file", base)?,
        keepalive_secs: integer(table, SECTION, "keepalive_secs")?,
        deadline_secs: integer(table, SECTION, "deadline_secs")?,
    })
}

/// Validate pinned `known_hosts` lines: `host keytype base64-key`.
///
/// # Errors
///
/// Refuses lines that could not pin a key (which OpenSSH would ignore,
/// turning a pin into a silent connection failure).
pub fn validate_known_hosts(lines: &[String]) -> Result<(), String> {
    for line in lines {
        let fields: Vec<&str> = line.split_whitespace().collect();
        let offset = usize::from(fields.first().is_some_and(|first| first.starts_with('@')));
        if line.contains(['\n', '\r', '\0']) || fields.len() < 3 + offset {
            return Err("a pinned known_hosts entry must be `HOST KEYTYPE BASE64KEY`".to_string());
        }
    }
    Ok(())
}

fn parse_tokens(table: &dyn TableLike) -> Result<TokenPolicy, String> {
    const SECTION: &str = "tokens";
    check_keys(
        table,
        SECTION,
        &[
            "ttl_hours",
            "max_requests",
            "max_tokens",
            "rate_limit_per_minute",
            "allowed_models",
        ],
    )?;
    Ok(TokenPolicy {
        ttl_hours: integer(table, SECTION, "ttl_hours")?,
        max_requests: integer(table, SECTION, "max_requests")?,
        max_tokens: integer(table, SECTION, "max_tokens")?,
        rate_limit_per_minute: integer(table, SECTION, "rate_limit_per_minute")?,
        allowed_models: strings(table, SECTION, "allowed_models")?,
    })
}

fn parse_provider_keys(
    table: &dyn TableLike,
    base: Option<&Path>,
) -> Result<Vec<ProviderKeySpec>, String> {
    let mut keys = Vec::new();
    for (name, item) in table.iter() {
        let section = format!("provider_keys.{name}");
        let entry = item
            .as_table_like()
            .ok_or_else(|| format!("[{section}] must be a table"))?;
        check_keys(
            entry,
            &section,
            &[
                "source",
                "mode",
                "kind",
                "base_url",
                "default_model",
                "models",
                "supported_clients",
            ],
        )?;
        let source = string(entry, &section, "source")?
            .ok_or_else(|| format!("[{section}] source is required (env:VAR or file:PATH)"))?;
        let mut spec = ProviderKeySpec::parse(&format!("{name}={source}"), base)?;
        spec.mode = string(entry, &section, "mode")?
            .as_deref()
            .map(ProviderKeyMode::parse)
            .transpose()?;
        spec.template = match string(entry, &section, "kind")? {
            Some(kind) => Some(ProviderTemplate {
                kind,
                base_url: string(entry, &section, "base_url")?,
                default_model: string(entry, &section, "default_model")?,
                models: strings(entry, &section, "models")?,
                supported_clients: strings(entry, &section, "supported_clients")?,
            }),
            None if ["base_url", "default_model", "models", "supported_clients"]
                .iter()
                .any(|key| entry.contains_key(key)) =>
            {
                return Err(format!(
                    "[{section}] provider fields need `kind` to describe a provider to add"
                ));
            }
            None => None,
        };
        keys.push(spec);
    }
    Ok(keys)
}

/// Client kinds the deploy verifier knows how to prove.
pub const VERIFIABLE_CLIENTS: &[&str] = &["claude", "codex", "qwen-code", "gemini", "opencode"];

fn parse_verification(table: &dyn TableLike) -> Result<VerificationProfile, String> {
    const SECTION: &str = "verification";
    check_keys(
        table,
        SECTION,
        &[
            "clients",
            "providers",
            "models",
            "require_client_launch",
            "quota_requires_upstream_evidence",
            "check_thinking_display",
        ],
    )?;
    let clients = strings(table, SECTION, "clients")?;
    for client in &clients {
        if !VERIFIABLE_CLIENTS.contains(&client.as_str()) {
            return Err(format!(
                "[verification] client `{client}` must be one of {}",
                VERIFIABLE_CLIENTS.join(", ")
            ));
        }
    }
    let providers = strings(table, SECTION, "providers")?;
    for provider in &providers {
        validate_provider_name(provider)?;
    }
    let mut models = BTreeMap::new();
    if let Some(item) = table.get("models") {
        let by_provider = item
            .as_table_like()
            .ok_or("[verification.models] must be a table of providers")?;
        for (provider, item) in by_provider.iter() {
            validate_provider_name(provider)?;
            let by_client = item.as_table_like().ok_or_else(|| {
                format!("[verification.models.{provider}] must map client kinds to models")
            })?;
            let mut chosen = BTreeMap::new();
            for (client, model) in by_client.iter() {
                if !VERIFIABLE_CLIENTS.contains(&client) {
                    return Err(format!(
                        "[verification.models.{provider}] unknown client `{client}`"
                    ));
                }
                let model = model
                    .as_str()
                    .filter(|model| !model.trim().is_empty())
                    .ok_or_else(|| {
                        format!("[verification.models.{provider}] {client} must be a model id")
                    })?;
                chosen.insert(client.to_string(), model.to_string());
            }
            models.insert(provider.to_string(), chosen);
        }
    }
    Ok(VerificationProfile {
        clients,
        providers,
        models,
        require_client_launch: boolean(table, SECTION, "require_client_launch")?,
        quota_requires_upstream_evidence: boolean(
            table,
            SECTION,
            "quota_requires_upstream_evidence",
        )?,
        check_thinking_display: boolean(table, SECTION, "check_thinking_display")?,
    })
}

/// A provider key with its value read.
#[derive(Clone, PartialEq, Eq)]
pub struct ResolvedProviderKey {
    /// Provider name on the target.
    pub name: String,
    /// What to do with it.
    pub mode: ProviderKeyMode,
    /// The key. Never printed.
    pub value: String,
    /// Fields for adding a provider the target lacks.
    pub template: Option<ProviderTemplate>,
}

impl fmt::Debug for ResolvedProviderKey {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ResolvedProviderKey")
            .field("name", &self.name)
            .field("mode", &self.mode)
            .field("value", &"<redacted>")
            .field("template", &self.template)
            .finish()
    }
}

/// Every setting after merging the file with the flags, values read.
#[derive(Clone, Default, PartialEq, Eq)]
pub struct ResolvedDeploy {
    /// Instance name, when one is selected.
    pub instance: Option<String>,
    /// Runtime environment, sorted by name. Values are never printed.
    pub env: Vec<(String, String)>,
    /// SSH transport.
    pub ssh: SshSettings,
    /// Issued-token limits.
    pub tokens: TokenPolicy,
    /// Provider keys to add or rotate in the candidate.
    pub provider_keys: Vec<ResolvedProviderKey>,
    /// What verification must prove.
    pub verification: Option<VerificationProfile>,
}

impl ResolvedDeploy {
    /// Whether the remote agent needs the extra settings payload.
    #[must_use]
    pub const fn needs_payload(&self) -> bool {
        !self.env.is_empty() || !self.provider_keys.is_empty() || self.verification.is_some()
    }
}

impl fmt::Debug for ResolvedDeploy {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ResolvedDeploy")
            .field("instance", &self.instance)
            .field(
                "env",
                &self.env.iter().map(|(name, _)| name).collect::<Vec<_>>(),
            )
            .field("ssh", &self.ssh)
            .field("tokens", &self.tokens)
            .field("provider_keys", &self.provider_keys)
            .field("verification", &self.verification)
            .finish()
    }
}

//! Keyed fingerprints for deploy settings that must never be printed.
//!
//! A runtime environment value or a provider key changes the launch
//! specification, so a deployment must notice the change and reconcile, yet
//! neither may appear in a container label, a log or the JSON report. Both
//! are identified by HMAC-SHA256 keyed by the deployment's `TOKEN_SECRET`,
//! truncated to 128 bits: equal inputs give equal fingerprints, and nobody
//! without the signing secret can test a guess against one.

use base64::Engine as _;
use jsonwebtoken::{Algorithm, EncodingKey};

const ENV_CONTEXT: &[u8] = b"link-assistant-router/deploy/runtime-env-fingerprint/v1\0";
const VALUE_CONTEXT: &[u8] = b"link-assistant-router/deploy/provider-key-fingerprint/v1\0";

/// HMAC-SHA256 of `message` keyed by `key`, hex encoded.
#[must_use]
pub fn hmac_sha256_hex(key: &[u8], message: &[u8]) -> String {
    let signature =
        jsonwebtoken::crypto::sign(message, &EncodingKey::from_secret(key), Algorithm::HS256)
            .expect("HMAC-SHA256 accepts any key");
    let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(signature)
        .expect("jsonwebtoken returns base64url");
    hex::encode(bytes)
}

fn truncated(key: &str, message: &[u8]) -> String {
    let digest = hmac_sha256_hex(key.as_bytes(), message);
    format!("hmac-sha256:{}", &digest[..32])
}

/// Fingerprint of a runtime environment, `None` when it is empty.
///
/// Order-independent: the entries are sorted by name first. `None` for an
/// empty environment keeps the launch specification of a deployment without
/// passthrough exactly what it was before passthrough existed.
#[must_use]
pub fn env_fingerprint(token_secret: &str, entries: &[(String, String)]) -> Option<String> {
    if entries.is_empty() {
        return None;
    }
    let mut sorted: Vec<&(String, String)> = entries.iter().collect();
    sorted.sort_by(|left, right| left.0.cmp(&right.0));
    let mut message = ENV_CONTEXT.to_vec();
    for (name, value) in sorted {
        message.extend_from_slice(name.as_bytes());
        message.push(0);
        message.extend_from_slice(value.as_bytes());
        message.push(0);
    }
    Some(truncated(token_secret, &message))
}

/// Fingerprint of one provider key, reported instead of the key.
#[must_use]
pub fn value_fingerprint(token_secret: &str, value: &str) -> String {
    let mut message = VALUE_CONTEXT.to_vec();
    message.extend_from_slice(value.as_bytes());
    truncated(token_secret, &message)
}

//! Merge `--config` with command-line flags, then read secret values.
//!
//! Merging and reading are separate steps: `--status` and `--down` need the
//! instance, root and SSH settings but must not fail because a runtime
//! variable a deploy would pass is unset on the operator's machine.

use std::path::{Path, PathBuf};

use super::{
    DeployConfig, DeploySection, EnvSpec, ProviderKeyMode, ProviderKeySpec, ResolvedDeploy,
    ResolvedProviderKey, SshSettings, TokenPolicy, VerificationProfile, load_verification_profile,
    validate_known_hosts,
};
use crate::cli::DeploySettingsArgs;

/// The file and the flags merged; secret values not read yet.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Merged {
    /// `[deploy]` with the target's `[local]`/`[remote]` overlay.
    pub section: DeploySection,
    /// Selected instance.
    pub instance: Option<String>,
    /// Runtime environment sources, unique by name.
    pub env: Vec<EnvSpec>,
    /// SSH transport.
    pub ssh: SshSettings,
    /// Issued-token limits.
    pub tokens: TokenPolicy,
    /// Provider key sources, unique by name.
    pub provider_keys: Vec<ProviderKeySpec>,
    /// Default mode for keys without their own.
    pub provider_key_mode: ProviderKeyMode,
    /// Verification profile.
    pub verification: Option<VerificationProfile>,
    /// Logins to hand over to a remote deployment (issue #681).
    pub seed_credentials: Vec<crate::deploy_seed::SeedProvider>,
}

fn upsert<T>(items: &mut Vec<T>, item: T, name: impl Fn(&T) -> &str) {
    let key = name(&item).to_string();
    if let Some(existing) = items.iter_mut().find(|existing| name(existing) == key) {
        *existing = item;
    } else {
        items.push(item);
    }
}

/// Merge the config file named by `--config` (if any) with the flags.
///
/// # Errors
///
/// Reports an unreadable or invalid file, or an invalid flag value.
pub fn merge(args: &DeploySettingsArgs, remote: bool) -> Result<Merged, String> {
    let file = args
        .config
        .as_deref()
        .map(DeployConfig::load)
        .transpose()?
        .unwrap_or_default();
    let section = file.section_for(remote);
    let cwd = crate::operation_context::current_dir().ok();
    let base: Option<&Path> = cwd.as_deref();

    let instance = args.instance.clone().or_else(|| section.instance.clone());
    if let Some(instance) = &instance {
        crate::deploy::instance::validate(instance)?;
    }

    let mut env = file.env;
    for flag in &args.env {
        upsert(&mut env, EnvSpec::parse(flag, base)?, |spec| &spec.name);
    }
    env.sort_by(|left, right| left.name.cmp(&right.name));

    let mut ssh = file.ssh;
    let pin = |value: &Option<PathBuf>, slot: &mut Option<PathBuf>| {
        if value.is_some() {
            slot.clone_from(value);
        }
    };
    if args.ssh_port.is_some() {
        ssh.port = args.ssh_port;
    }
    pin(&args.ssh_identity, &mut ssh.identity_file);
    if args.ssh_known_hosts.is_some() {
        // A pin given on the command line replaces the file's pins outright:
        // merging two trust sets would trust keys neither source chose alone.
        ssh.known_hosts.clear();
        pin(&args.ssh_known_hosts, &mut ssh.known_hosts_file);
    }
    if args.ssh_keepalive.is_some() {
        ssh.keepalive_secs = args.ssh_keepalive;
    }
    if args.deadline.is_some() {
        ssh.deadline_secs = args.deadline;
    }
    if ssh.deadline_secs == Some(0) || ssh.keepalive_secs == Some(0) {
        return Err("SSH deadline and keepalive must be at least one second".to_string());
    }

    let mut tokens = file.tokens;
    if args.token_ttl_hours.is_some() {
        tokens.ttl_hours = args.token_ttl_hours;
    }
    if args.token_max_requests.is_some() {
        tokens.max_requests = args.token_max_requests;
    }
    if args.token_max_tokens.is_some() {
        tokens.max_tokens = args.token_max_tokens;
    }
    if args.token_rate_limit.is_some() {
        tokens.rate_limit_per_minute = args.token_rate_limit;
    }
    if !args.token_allowed_model.is_empty() {
        tokens.allowed_models.clone_from(&args.token_allowed_model);
    }
    if tokens.ttl_hours.is_some_and(|hours| hours <= 0) {
        return Err("the issued token's ttl_hours must be positive".to_string());
    }

    let mut provider_keys = file.provider_keys;
    for flag in &args.provider_key {
        let mut spec = ProviderKeySpec::parse(flag, base)?;
        // A flag replaces the key source but keeps the file's provider
        // template and per-key mode for the same provider.
        if let Some(existing) = provider_keys.iter().find(|key| key.name == spec.name) {
            spec.mode = existing.mode;
            spec.template.clone_from(&existing.template);
        }
        upsert(&mut provider_keys, spec, |spec| &spec.name);
    }

    let verification = match &args.verification_profile {
        Some(path) => Some(load_verification_profile(path)?),
        None => file.verification,
    };

    let seed_credentials =
        crate::deploy_seed::parse_providers(if args.seed_credential.is_empty() {
            &section.seed_credentials
        } else {
            &args.seed_credential
        })?;

    Ok(Merged {
        section,
        instance,
        env,
        ssh,
        tokens,
        provider_keys,
        provider_key_mode: args.provider_key_mode.unwrap_or_default(),
        verification,
        seed_credentials,
    })
}

impl Merged {
    /// Read every secret value. Errors name the source, never a value.
    ///
    /// # Errors
    ///
    /// Reports an unset variable, an unreadable file, or a value with a
    /// newline or NUL byte.
    pub fn read_values(&self) -> Result<ResolvedDeploy, String> {
        let env = self
            .env
            .iter()
            .map(|spec| {
                spec.source
                    .read()
                    .map(|value| (spec.name.clone(), value))
                    .map_err(|error| format!("--env {}: {error}", spec.name))
            })
            .collect::<Result<Vec<_>, _>>()?;
        let provider_keys = self
            .provider_keys
            .iter()
            .map(|spec| {
                let value = spec
                    .source
                    .read()
                    .map_err(|error| format!("--provider-key {}: {error}", spec.name))?;
                if value.trim().is_empty() {
                    return Err(format!("--provider-key {}: the key is empty", spec.name));
                }
                Ok(ResolvedProviderKey {
                    name: spec.name.clone(),
                    mode: spec.mode.unwrap_or(self.provider_key_mode),
                    value,
                    template: spec.template.clone(),
                })
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(ResolvedDeploy {
            instance: self.instance.clone(),
            env,
            ssh: self.ssh.clone(),
            tokens: self.tokens.clone(),
            provider_keys,
            verification: self.verification.clone(),
        })
    }

    /// The pinned `known_hosts` text, if any pin is configured.
    ///
    /// # Errors
    ///
    /// Reports an unreadable pin file or malformed pinned lines.
    pub fn known_hosts(&self) -> Result<Option<String>, String> {
        let mut lines = self.ssh.known_hosts.clone();
        if let Some(path) = &self.ssh.known_hosts_file {
            let text = std::fs::read_to_string(path)
                .map_err(|error| format!("could not read {}: {error}", path.display()))?;
            lines.extend(
                text.lines()
                    .map(str::trim)
                    .filter(|line| !line.is_empty() && !line.starts_with('#'))
                    .map(str::to_string),
            );
            if lines.is_empty() {
                return Err(format!("{} pins no host key", path.display()));
            }
        }
        if lines.is_empty() {
            return Ok(None);
        }
        validate_known_hosts(&lines)?;
        Ok(Some(lines.join("\n") + "\n"))
    }
}

//! Deployment paths: config-relative paths and target-specific home expansion.

use std::path::{Path, PathBuf};

/// Expand the current user's `~` or `~/` without evaluating shell expressions.
pub fn expand_home(value: &str) -> Result<PathBuf, String> {
    let home = crate::operation_context::var_os("HOME")
        .or_else(|| crate::operation_context::var_os("USERPROFILE"));
    expand_with_home(value, home.as_deref().map(Path::new))
}

fn expand_with_home(value: &str, home: Option<&Path>) -> Result<PathBuf, String> {
    if !value.starts_with('~') {
        return Ok(PathBuf::from(value));
    }
    let relative = if value == "~" {
        ""
    } else {
        value.strip_prefix("~/").ok_or_else(|| {
            "deployment paths support only `~` or `~/`, not another user's home; use an absolute path".to_string()
        })?
    };
    let home = home.filter(|home| home.is_absolute()).ok_or_else(|| {
        "could not expand `~`: HOME (or USERPROFILE) must name an absolute home directory"
            .to_string()
    })?;
    Ok(home.join(relative))
}

/// Resolve an ordinary config path against its file's directory.
///
/// A deployment root's home belongs to the selected target. Preserve that
/// prefix until local dispatch or the SSH agent expands the appropriate home.
pub fn config_path(value: &str, base: Option<&Path>, target_home: bool) -> Result<PathBuf, String> {
    if target_home && (value == "~" || value.starts_with("~/")) {
        return Ok(PathBuf::from(value));
    }
    let path = expand_home(value)?;
    Ok(match base {
        Some(base) if path.is_relative() => base.join(path),
        _ => path,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn home_expansion_is_explicit_and_does_not_execute_shell_text() {
        let home = std::env::temp_dir().join("router-home");
        assert_eq!(expand_with_home("~", Some(&home)).unwrap(), home);
        assert_eq!(
            expand_with_home("~/Data", Some(&home)).unwrap(),
            home.join("Data")
        );
        assert!(expand_with_home("~/Data", None).is_err());
        assert!(expand_with_home("~other/Data", Some(&home)).is_err());
        assert_eq!(
            expand_with_home("$HOME/$(command)", Some(&home)).unwrap(),
            PathBuf::from("$HOME/$(command)")
        );
    }

    #[test]
    fn a_target_home_is_deferred_but_other_relative_roots_use_the_config_directory() {
        let base = std::env::temp_dir().join("config");
        assert_eq!(
            config_path("~/data", Some(&base), true).unwrap(),
            PathBuf::from("~/data")
        );
        assert_eq!(
            config_path("data", Some(&base), true).unwrap(),
            base.join("data")
        );
    }
}

//! Connection-preserving front door for remote deployments.
//!
//! A remote update cannot replace the container holding the published port:
//! doing so necessarily leaves a bind gap and kills in-flight responses.  The
//! deployment therefore leaves this deliberately small TCP relay on the real
//! ports.  Every accepted connection reads the current backend from an atomic
//! state file.  Existing connections retain the backend they already selected,
//! so replacing that file is the cutover and draining the old connection count
//! is the shutdown barrier.

use std::collections::BTreeMap;
use std::future::Future;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use tokio::io::copy_bidirectional;
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::Mutex;

/// Environment which elects the binary into relay mode before CLI parsing.
pub const STATE_ENV: &crate::translation_core::Str = "ROUTER_DEPLOY_RELAY_STATE";
/// Semicolon-separated `LISTEN_ADDRESS,BACKEND_PORT` relay bindings.
pub const LISTENERS_ENV: &crate::translation_core::Str = "ROUTER_DEPLOY_RELAY_LISTENERS";

#[derive(Clone, Debug, Eq, PartialEq)]
struct Binding {
    listen: String,
    backend_port: u16,
}

fn parse_bindings(raw: &crate::translation_core::Str) -> crate::translation_core::Outcome<Vec<Binding>, String> {
    let bindings = raw
        .split(';')
        .filter(|part| !part.trim().is_empty())
        .map(|part| {
            let (listen, port) = part
                .rsplit_once(',')
                .ok_or_else(|| format!("invalid relay listener {part:?}; expected ADDR,PORT"))?;
            listen
                .parse::<std::net::SocketAddr>()
                .map_err(|_| format!("invalid relay address {listen:?}"))?;
            let backend_port = port
                .parse::<u16>()
                .map_err(|_| format!("invalid relay backend port {port:?}"))?;
            Ok(Binding {
                listen: listen.to_string(),
                backend_port,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    if bindings.is_empty() {
        return Err("the deployment relay has no listeners".to_string());
    }
    Ok(bindings)
}

fn valid_backend(value: &crate::translation_core::Str) -> bool {
    !value.is_empty()
        && value.len() <= 128
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
}

fn read_backend(state: &Path) -> crate::translation_core::Outcome<String, String> {
    let backend = std::fs::read_to_string(state)
        .map_err(|error| format!("could not read relay state {}: {error}", state.display()))?;
    let backend = backend.trim();
    if !valid_backend(backend) {
        return Err(format!(
            "relay state {} contains an invalid backend name",
            state.display()
        ));
    }
    Ok(backend.to_string())
}

#[derive(Debug)]
struct Connections {
    directory: PathBuf,
    counts: BTreeMap<String, u64>,
}

impl Connections {
    fn new(state: &Path) -> crate::translation_core::Outcome<Self, String> {
        let parent = state
            .parent()
            .ok_or_else(|| "relay state has no parent directory".to_string())?;
        let directory = parent.join("connections");
        std::fs::create_dir_all(&directory).map_err(|error| {
            format!(
                "could not create relay connection directory {}: {error}",
                directory.display()
            )
        })?;
        // A relay process cannot inherit TCP streams across a restart. Reset
        // only validated counter files so an interrupted old process cannot
        // leave a deployment waiting forever for connections which no longer
        // exist.
        for entry in std::fs::read_dir(&directory).map_err(|error| {
            format!(
                "could not read relay connection directory {}: {error}",
                directory.display()
            )
        })? {
            let entry = entry.map_err(|error| {
                format!(
                    "could not read a relay connection entry in {}: {error}",
                    directory.display()
                )
            })?;
            let name = entry.file_name();
            let Some(name) = name.to_str().filter(|name| valid_backend(name)) else {
                continue;
            };
            if entry
                .file_type()
                .map_err(|error| format!("could not inspect relay counter {name}: {error}"))?
                .is_file()
            {
                let path = entry.path();
                crate::durable_file::atomic_write_owner_only(&path, b"0")
                    .map_err(|error| crate::durable_file::describe_write_failure(&path, &error))?;
            }
        }
        Ok(Self {
            directory,
            counts: BTreeMap::new(),
        })
    }

    fn change(&mut self, backend: &crate::translation_core::Str, change: i8) -> crate::translation_core::Outcome<(), String> {
        let value = self.counts.entry(backend.to_string()).or_default();
        let previous = *value;
        if change > 0 {
            *value = value.saturating_add(1);
        } else {
            *value = value.saturating_sub(1);
        }
        let path = self.directory.join(backend);
        if let Err(error) =
            crate::durable_file::atomic_write_owner_only(&path, value.to_string().as_bytes())
        {
            *value = previous;
            return Err(crate::durable_file::describe_write_failure(&path, &error));
        }
        Ok(())
    }
}

async fn relay_connection_with_connector<Connect, Connecting>(
    mut client: TcpStream,
    state: &Path,
    backend_port: u16,
    connections: Arc<Mutex<Connections>>,
    connect: Connect,
) -> Result<(), String>
where
    Connect: FnOnce(String, u16) -> Connecting,
    Connecting: Future<Output = std::io::Result<TcpStream>>,
{
    let backend = read_backend(state)?;
    // Publish the connection before attempting the upstream connect.  Otherwise
    // cutover could observe zero old connections and remove the backend while a
    // just-accepted stream was still connecting to it.
    connections.lock().await.change(&backend, 1)?;
    let result = async {
        let mut upstream = connect(backend.clone(), backend_port)
            .await
            .map_err(|error| format!("could not connect to {backend}:{backend_port}: {error}"))?;
        copy_bidirectional(&mut client, &mut upstream)
            .await
            .map(|_| ())
            .map_err(|error| format!("relay stream failed: {error}"))
    }
    .await;
    let decrement = connections.lock().await.change(&backend, -1);
    if let Err(error) = decrement {
        tracing::error!("{error}");
    }
    result
}

async fn relay_connection(
    client: TcpStream,
    state: &Path,
    backend_port: u16,
    connections: Arc<Mutex<Connections>>,
) -> crate::translation_core::Outcome<(), String> {
    relay_connection_with_connector(
        client,
        state,
        backend_port,
        connections,
        |backend, port| async move { TcpStream::connect((backend, port)).await },
    )
    .await
}

async fn serve_binding(
    binding: Binding,
    state: PathBuf,
    connections: Arc<Mutex<Connections>>,
) -> crate::translation_core::Outcome<(), String> {
    let listener = TcpListener::bind(&binding.listen)
        .await
        .map_err(|error| format!("could not bind relay listener {}: {error}", binding.listen))?;
    tracing::info!(
        "Deployment relay listening on {} for backend port {}",
        binding.listen,
        binding.backend_port
    );
    loop {
        let (client, _) = listener
            .accept()
            .await
            .map_err(|error| format!("deployment relay accept failed: {error}"))?;
        let state = state.clone();
        let connections = Arc::clone(&connections);
        let port = binding.backend_port;
        tokio::spawn(async move {
            if let Err(error) = relay_connection(client, &state, port, connections).await {
                tracing::warn!("{error}");
            }
        });
    }
}

/// Run relay mode when its opt-in environment is present.
///
/// `Ok(None)` means this is an ordinary Router invocation.
pub async fn run_from_env() -> crate::translation_core::Outcome<crate::translation_core::Maybe<()>, String> {
    let Some(state) = crate::operation_context::var_os(STATE_ENV) else {
        return Ok(None);
    };
    let state = PathBuf::from(state);
    // Fail before binding a public port if the state is missing or malformed.
    read_backend(&state)?;
    let raw = crate::operation_context::var(LISTENERS_ENV)
        .map_err(|_| format!("{LISTENERS_ENV} is required in deployment relay mode"))?;
    let bindings = parse_bindings(&raw)?;
    let connections = Arc::new(Mutex::new(Connections::new(&state)?));
    let servers = bindings
        .into_iter()
        .map(|binding| serve_binding(binding, state.clone(), Arc::clone(&connections)));
    futures_util::future::try_join_all(servers).await?;
    Ok(Some(()))
}

