}

async fn catalog_report_with_token_url(
    readers: Vec<SubscriptionReader>,
    data_dir: crate::translation_core::Maybe<&std::path::Path>,
    token_url: crate::translation_core::Maybe<(SubscriptionProvider, &crate::translation_core::Str)>,
) -> (bool, Vec<crate::operation_reports::ProviderHealth>) {
    let client = reqwest::Client::new();
    let token_cache = data_dir.map_or_else(
        || {
            let cache = crate::refresh::TokenCache::new();
            cache.register_readers(crate::credential_recovery_store::PRIMARY_ACCOUNT, &readers);
            cache
        },
        |data_dir| crate::refresh::TokenCache::registered_for(&readers, data_dir),
    );
    let now_ms = crate::operation_context::now().timestamp_millis();
    let mut catalog_error = false;
    let mut providers = Vec::new();
    for reader in readers {
        let provider = reader.provider();
        let mut report = crate::operation_reports::ProviderHealth {
            provider,
            credential_root: reader.home().display().to_string(),
            state: "absent".into(),
            models: Vec::new(),
            detail: None,
        };
        let label = format!("{provider} subscription");
        let path = reader
            .discover_credential_path()
            .unwrap_or_else(|| reader.home().to_path_buf());
        let origin = reader
            .read_token_from()
            .map_or(crate::platform_keychain::Origin::File, |(_, origin)| origin);
        let disk_token = match token_cache
            .load_authoritative(provider, crate::credential_recovery_store::PRIMARY_ACCOUNT)
            .await
        {
            Ok(Some(token)) => token,
            Ok(None) => {
                println!("{label:<23}: {} (MISSING)", reader.home().display());
                providers.push(report);
                continue;
            }
            Err(_) => {
                println!("{label:<23}: {provider} credential store (found, NO TOKEN)");
                println!(
                    "{:<23}: ERROR (credential is unreadable)",
                    format!("{provider} catalog")
                );
                catalog_error = true;
                report.state = "unreadable".into();
                report.detail = Some("credential is unreadable".into());
                providers.push(report);
                continue;
            }
        };
        let was_expired = disk_token.is_expired(now_ms);
        let refreshed = match token_url {
            Some((override_provider, url)) if override_provider == provider => {
                token_cache
                    .get_fresh_registered_at(
                        &client,
                        url,
                        provider,
                        crate::credential_recovery_store::PRIMARY_ACCOUNT,
                        now_ms,
                    )
                    .await
            }
            _ => {
                token_cache
                    .get_fresh_registered(
                        &client,
                        provider,
                        crate::credential_recovery_store::PRIMARY_ACCOUNT,
                        now_ms,
                    )
                    .await
            }
        };
        let Ok(token) = refreshed else {
            let location = credential_location(provider, origin, &path);
            let detail = token_cache
                .last_refresh_error_for(provider, crate::credential_recovery_store::PRIMARY_ACCOUNT)
                .unwrap_or_else(|| "refresh failed before the credential could be checked".into());
            println!(
                "{label:<23}: {location} (found, refresh FAILED, store: {})",
                origin.label()
            );
            println!("{:<23}: ERROR ({detail})", format!("{provider} refresh"));
            println!(
                "{:<23}: ERROR (credential refresh failed before catalog probe)",
                format!("{provider} catalog")
            );
            catalog_error = true;
            report.state = "refresh-failed".into();
            report.detail = Some(detail);
            providers.push(report);
            continue;
        };
        if let Some(detail) = token_cache
            .last_refresh_error_for(provider, crate::credential_recovery_store::PRIMARY_ACCOUNT)
        {
            let location = credential_location(provider, origin, &path);
            println!(
                "{label:<23}: {location} (found, refresh FAILED, store: {})",
                origin.label()
            );
            println!("{:<23}: ERROR ({detail})", format!("{provider} refresh"));
            println!(
                "{:<23}: ERROR (credential refresh failed before catalog probe)",
                format!("{provider} catalog")
            );
            catalog_error = true;
            report.state = "refresh-failed".into();
            report.detail = Some(detail);
            providers.push(report);
            continue;
        }
        // `expiresAt` is a hint, so a still-expired token is probed rather than
        // declared dead: the catalog endpoint is what actually knows.
        let still_expired = token.is_expired(now_ms);
        let catalog = fetch_provider_catalog(&client, provider, &token, None).await;
        let acceptance = classify_catalog_acceptance(&catalog);
        let rejected = matches!(
            acceptance,
            CatalogAcceptance::MissingSubscription | CatalogAcceptance::CredentialRejected
        );
        let status = credential_status(was_expired, still_expired, rejected);
        let location = credential_location(provider, origin, &path);
        println!(
            "{label:<23}: {location} ({status}, store: {})",
            origin.label()
        );
        report.state = match acceptance {
            CatalogAcceptance::Accepted => "usable",
            CatalogAcceptance::MissingSubscription => "missing-subscription",
            CatalogAcceptance::CredentialRejected => "rejected",
            CatalogAcceptance::Unverified => "unverified",
        }
        .into();
        match &catalog {
            Ok(models) => report.models.clone_from(models),
            Err(error) => report.detail = Some(error.clone()),
        }
        providers.push(report);
        match (acceptance, catalog) {
            (CatalogAcceptance::Accepted, Ok(models)) => println!(
                "{:<23}: OK ({} live model(s))",
                format!("{provider} catalog"),
                models.len()
            ),
            (CatalogAcceptance::MissingSubscription, Ok(_)) => {
                println!(
                    "{:<23}: ERROR (no live models; active subscription was not proven)",
                    format!("{provider} catalog")
                );
                catalog_error = true;
            }
            (_, Err(error)) => {
                println!("{:<23}: ERROR ({error})", format!("{provider} catalog"));
                catalog_error = true;
            }
            _ => unreachable!("catalog classification matches its result"),
        }
    }
    (catalog_error, providers)
}

/// Data-directory-backed variant of [`subscription_catalog_diagnostics`].
pub async fn subscription_catalog_diagnostics_in(
    active_provider: SubscriptionProvider,
    claude_home: &crate::translation_core::Str,
