        assert!(!full[1].contains("(default)"), "{full:?}");

        let narrow = login_mode_report(&config("claude", &["setup-token"]));
        assert!(!narrow[0].contains("(default)"), "{narrow:?}");
        assert!(narrow[1].contains("(default)"), "{narrow:?}");
    }

    /// An operator-supplied backend that is absent is reported as unavailable
    /// rather than failing later with an HTTP 502.
    #[test]
    fn a_missing_external_command_is_reported_unavailable() {
        let report = login_mode_report(&config("definitely-not-on-path-98765", &[])).join("\n");
        assert!(report.contains("UNAVAILABLE"), "{report}");
        assert!(report.contains("definitely-not-on-path-98765"), "{report}");
    }

    /// An absolute path that exists resolves; one that does not is reported.
    #[test]
    fn an_absolute_command_path_is_probed_directly() {
        let existing = std::env::current_exe().expect("test binary path");
        let report = login_mode_report(&config(&existing.to_string_lossy(), &[])).join("\n");
        assert!(report.contains("via "), "{report}");
        assert!(!report.contains("UNAVAILABLE"), "{report}");

        let missing = login_mode_report(&config("/nonexistent/router/login-cli", &[])).join("\n");
        assert!(missing.contains("UNAVAILABLE"), "{missing}");
    }

    #[test]
    fn resolve_in_path_finds_a_real_executable() {
        // `sh` exists on every platform this test runs on.
        assert!(
            resolve_in_path("sh").is_some() || cfg!(windows),
            "sh should be resolvable"
        );
        assert!(resolve_in_path("definitely-not-on-path-98765").is_none());
    }

    /// A keychain credential is described by its entry, not by a file path it
    /// does not have -- naming the store is the diagnosability fix in #249.
    #[test]
    fn a_keychain_credential_is_described_by_its_entry() {
        let location = credential_location(
            SubscriptionProvider::Claude,
            crate::platform_keychain::Origin::Keychain,
            std::path::Path::new("/Users/someone/.claude/.credentials.json"),
        );

        if cfg!(target_os = "macos") {
            assert_eq!(location, "keychain \"Claude Code-credentials\"");
        } else {
            assert_eq!(location, "platform keychain");
        }
        assert!(
            !location.contains(".credentials.json"),
            "a keychain credential must not be reported as a file: {location}"
        );
    }

    /// A provider with no named store still reports a store rather than a path
    /// it did not read, so the line never claims the wrong origin.
    #[test]
    fn a_storeless_provider_reports_a_generic_store() {
        let location = credential_location(
            SubscriptionProvider::Gemini,
            crate::platform_keychain::Origin::Keychain,
            std::path::Path::new("/home/someone/.gemini/oauth_creds.json"),
        );

        assert_eq!(location, "platform keychain");
    }

    /// A file credential keeps reporting its path, which is what every
    /// non-macOS platform and every other provider sees.
    #[test]
    fn a_file_credential_is_described_by_its_path() {
        let location = credential_location(
            SubscriptionProvider::Codex,
            crate::platform_keychain::Origin::File,
            std::path::Path::new("/home/someone/.codex/auth.json"),
        );

        assert_eq!(location, "/home/someone/.codex/auth.json");
    }

    /// A credential that refreshed successfully must say so, rather than being
    /// reported by the expiry that sent it to be refreshed.
    #[test]
    fn a_refreshed_credential_reads_as_ok() {
        assert_eq!(
            credential_status(true, false, false),
            "found, token OK (refreshed durably)"
        );
        assert_eq!(credential_status(false, false, false), "found, token OK");
    }

    /// The case from issue #249: expired on disk and refused upstream.
    #[test]
    fn an_expired_and_refused_credential_says_both() {
        let status = credential_status(true, true, true);

        assert!(status.contains("EXPIRED"), "{status}");
        assert!(status.contains("REJECTED"), "{status}");
    }

    /// An expiry is a hint, so a token the upstream still accepts must not be
    /// reported as dead -- this is what stops `doctor` condemning a credential
    /// the vendor client is happily using.
    #[test]
    fn an_expired_but_accepted_credential_is_not_condemned() {
        let status = credential_status(true, true, false);

        assert!(status.contains("ACCEPTED upstream"), "{status}");
        assert!(!status.contains("REJECTED"), "{status}");
    }

    /// A refusal after a successful refresh is distinct from one before it:
    /// the first means the chain is dead, the second that it never worked.
    #[test]
    fn a_refusal_names_whether_a_refresh_preceded_it() {
        assert_eq!(
            credential_status(true, false, true),
            "found, token REJECTED after refresh"
        );
        assert_eq!(
            credential_status(false, false, true),
            "found, token REJECTED"
        );
    }

    /// The privacy property is checkable without reading the source.
    ///
    /// Verifying what reached the vendor previously meant hand-parsing
    /// `requests.jsonl`, so an operator who checked the egress IP concluded
    /// they were private while the client's machine identity travelled on
    /// (issue #332).
    #[test]
    fn the_report_names_what_is_forwarded_and_what_is_not() {
        let report = forwarded_header_report().join("\n");
        // What travels.
        for forwarded in crate::proxy::forwarded_client_headers() {
            assert!(
                report.contains(forwarded),
                "the report must name {forwarded}: {report}"
            );
        }
        assert!(report.contains("preserved from signed client"), "{report}");
        // And what does not, named explicitly rather than left to inference.
        for dropped in ["Router authentication", "cookies", "hop-by-hop", "framing"] {
            assert!(
                report.contains(dropped),
                "the report must say {dropped} is dropped: {report}"
            );
        }
    }
}

//! Read-only release diagnostics. Never installs or updates the running server.
use futures_util::StreamExt as _;
use serde_json::{Value, json};

const RELEASE_API: &crate::translation_core::Str = "https://api.github.com/repos/link-assistant/router/releases/latest";

/// Check the latest stable GitHub release without sending Router credentials.
pub async fn latest_version(client: &reqwest::Client) -> crate::translation_core::Outcome<crate::translation_core::Json, String> {
    fetch(client, RELEASE_API).await
}

async fn fetch(client: &reqwest::Client, endpoint: &crate::translation_core::Str) -> crate::translation_core::Outcome<crate::translation_core::Json, String> {
    let response = client
        .get(endpoint)
        .header(
            "user-agent",
            format!("link-assistant-router/{}", crate::VERSION),
        )
        .header("accept", "application/vnd.github+json")
        .timeout(std::time::Duration::from_secs(10))
        .send()
        .await
        .and_then(reqwest::Response::error_for_status)
        .map_err(|e| e.to_string())?;
    let mut stream = response.bytes_stream();
    let mut body = Vec::new();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|e| e.to_string())?;
        if body.len().saturating_add(chunk.len()) > 64 * 1024 {
            return Err("release response exceeds limit".into());
        }
        body.extend_from_slice(&chunk);
    }
    let release: Value = serde_json::from_slice(&body).map_err(|e| e.to_string())?;
    let tag = release["tag_name"].as_str().ok_or("release tag missing")?;
    let latest = tag.strip_prefix('v').unwrap_or(tag);
    let latest_parts = parts(latest).ok_or("invalid stable release version")?;
    let current_parts = parts(crate::VERSION).ok_or("invalid current version")?;
    Ok(
        json!({"current_version": crate::VERSION, "latest_version": latest,
        "update_available": latest_parts > current_parts,
        "release_url": format!("https://github.com/link-assistant/router/releases/tag/{tag}")}),
    )
}

fn parts(version: &str) -> Option<[u64; 3]> {
    let parts = version
        .split('.')
        .map(str::parse)
        .collect::<Result<Vec<u64>, _>>()
        .ok()?;
    parts.try_into().ok()
}

#[cfg(test)]
mod tests {
    use super::*;
    #[tokio::test]
    async fn version_check_uses_http_status_and_validates_the_release_tag() {
        for (status, body, expected) in [
            (200, r#"{"tag_name":"v999.0.0"}"#, true),
            (200, r#"{"tag_name":"v0.1.0"}"#, true),
            (200, r#"{"tag_name":"invalid"}"#, false),
            (502, "failed", false),
        ] {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            let url = format!("http://{}", listener.local_addr().unwrap());
            let app = axum::Router::new().route(
                "/",
                axum::routing::get(move || async move {
                    (axum::http::StatusCode::from_u16(status).unwrap(), body)
                }),
            );
            let server = tokio::spawn(async move {
                axum::serve(listener, app).await.unwrap();
            });
            let result = fetch(&reqwest::Client::new(), &url).await;
            assert_eq!(result.is_ok(), expected, "{result:?}");
            if let Ok(result) = result {
                assert_eq!(result["update_available"], body.contains("999"));
            }
            server.abort();
            let _ = server.await;
        }
    }
}

//! Owner-only, crash-durable file replacement and inter-process locking.

use std::fs::{self, OpenOptions, TryLockError};
use std::io::{self, Write};
use std::path::Path;

const ROLLBACK_SUFFIX: &crate::translation_core::Str = ".router-rollback";
const COMMIT_SUFFIX: &crate::translation_core::Str = ".router-commit";

fn sibling_with_suffix(path: &Path, suffix: &crate::translation_core::Str) -> io::Result<std::path::PathBuf> {
    let name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| io::Error::other("durable file name is not valid UTF-8"))?;
    Ok(path.with_file_name(format!(".{name}{suffix}")))
}

#[cfg(test)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum FaultPoint {
    AfterRename,
    RemoveRollback,
    SyncAfterRollbackRemoval,
    RemoveCommit,
    SyncAfterCommitRemoval,
    Unlock,
}

#[cfg(test)]
#[derive(Debug)]
struct InjectedFault {
    path: std::path::PathBuf,
    point: FaultPoint,
}

#[cfg(test)]
fn fault_slot() -> &'static std::sync::Mutex<Option<InjectedFault>> {
    static SLOT: std::sync::OnceLock<std::sync::Mutex<Option<InjectedFault>>> =
        std::sync::OnceLock::new();
    SLOT.get_or_init(|| std::sync::Mutex::new(None))
}

#[cfg(test)]
fn fault_serial() -> &'static std::sync::Mutex<()> {
    static SERIAL: std::sync::OnceLock<std::sync::Mutex<()>> = std::sync::OnceLock::new();
    SERIAL.get_or_init(|| std::sync::Mutex::new(()))
}

#[cfg(test)]
pub(crate) struct FaultGuard {
    _serial: std::sync::MutexGuard<'static, ()>,
}

#[cfg(test)]
impl Drop for FaultGuard {
    fn drop(&mut self) {
        *fault_slot()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
    }
}

#[cfg(test)]
pub(crate) fn inject_fault(path: &Path, point: FaultPoint) -> FaultGuard {
    let serial = fault_serial()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    *fault_slot()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(InjectedFault {
        path: path.to_path_buf(),
        point,
    });
    FaultGuard { _serial: serial }
}

#[cfg(test)]
fn fail_if_injected(path: &Path, point: FaultPoint) -> io::Result<()> {
    let mut slot = fault_slot()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let injected = slot
        .as_ref()
        .is_some_and(|fault| fault.path == path && fault.point == point);
    if injected {
        *slot = None;
    }
    drop(slot);
    if injected {
        return Err(io::Error::other(format!(
            "injected durable-file failure at {point:?}"
        )));
    }
    Ok(())
}

/// Describe a credential-write failure in terms an operator can act on.
///
/// A read-only mount is the common case — the deployment docs tell you to mount
/// the credential directory `:ro` — and it otherwise surfaces as a bare
/// `Read-only file system (os error 30)`, which does not say what to change
/// (issue #205).
#[must_use]
pub fn describe_write_failure(path: &Path, error: &io::Error) -> String {
    if error.kind() == io::ErrorKind::ReadOnlyFilesystem {
        return format!(
            "cannot write {}: the credential directory is mounted read-only. \
             Re-run without `:ro` to authorize, then restore it — serving and \
             token renewal do not need write access.",
            path.display()
        );
    }
    format!("could not create {}: {error}", path.display())
}

/// Replace `path` atomically, syncing both the file and its containing
/// directory so the rename survives power loss.
pub fn atomic_write_owner_only(path: &Path, contents: &[u8]) -> io::Result<()> {
    let parent = path
        .parent()
        .ok_or_else(|| io::Error::other("durable path has no parent directory"))?;
    fs::create_dir_all(parent)?;
    let name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| io::Error::other("durable file name is not valid UTF-8"))?;
    let temporary = parent.join(format!(
        ".{name}.{}.{}.tmp",
        std::process::id(),
        uuid::Uuid::new_v4()
    ));
    let result = (|| {
        let mut options = OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;
            options.mode(0o600);
        }
        let mut file = options.open(&temporary)?;
        file.write_all(contents)?;
        file.sync_all()?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            file.set_permissions(fs::Permissions::from_mode(0o600))?;
        }
        drop(file);
        fs::rename(&temporary, path)?;
        #[cfg(test)]
        fail_if_injected(path, FaultPoint::AfterRename)?;
        sync_directory(parent)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

/// Recover an interrupted transactional replacement of `path`.
///
/// A surviving commit marker makes the current primary authoritative. A
/// rollback document without that marker means the replacement had not
/// committed, so the prior bytes are restored before callers read the file.
pub fn recover_transactional_write(path: &Path) -> io::Result<()> {
    let rollback = sibling_with_suffix(path, ROLLBACK_SUFFIX)?;
    let commit = sibling_with_suffix(path, COMMIT_SUFFIX)?;
    if commit.exists() {
        return cleanup_committed_transaction(path, &rollback, &commit);
    }
    let rollback_document = match fs::read(&rollback) {
        Ok(prior) => prior,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(()),
        Err(error) => return Err(error),
    };
    match rollback_document.split_first() {
        Some((0, _)) => match fs::remove_file(path) {
            Ok(()) => {}
            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
            Err(error) => return Err(error),
        },
        Some((1, prior)) => atomic_write_owner_only(path, prior)?,
        _ => return Err(io::Error::other("invalid transactional rollback document")),
    }
    fs::remove_file(&rollback)?;
    if let Some(parent) = path.parent() {
        sync_directory(parent)?;
    }
    Ok(())
}

fn remove_file_if_present(path: &Path) -> io::Result<()> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error),
    }
}

/// Remove committed transaction sidecars without ever making the rollback
/// document authoritative again.
///
/// The rollback is removed and that removal is made durable before the commit
/// marker can be removed. Every failure before that point therefore leaves the
/// commit marker in place, so another recovery pass still keeps the new
/// primary. A failure syncing the final marker removal is safe too: either the
/// marker reappears after a crash and cleanup repeats, or both sidecars stay
/// absent and the primary remains authoritative.
fn cleanup_committed_transaction(path: &Path, rollback: &Path, commit: &Path) -> io::Result<()> {
    #[cfg(test)]
    fail_if_injected(path, FaultPoint::RemoveRollback)?;
    remove_file_if_present(rollback)?;
    if let Some(parent) = path.parent() {
        #[cfg(test)]
        fail_if_injected(path, FaultPoint::SyncAfterRollbackRemoval)?;
        sync_directory(parent)?;
    }

    #[cfg(test)]
    fail_if_injected(path, FaultPoint::RemoveCommit)?;
    remove_file_if_present(commit)?;
    if let Some(parent) = path.parent() {
        #[cfg(test)]
        fail_if_injected(path, FaultPoint::SyncAfterCommitRemoval)?;
        sync_directory(parent)?;
    }
    Ok(())
}

/// Replace `path` as a recoverable transaction.
///
/// The prior bytes are made durable before the new primary is written. A
/// durable commit marker is then the boundary between rollback and commit, so
/// a crash or a late directory-sync error never leaves callers guessing which
/// document is authoritative.
pub fn transactional_write_owner_only(path: &Path, contents: &[u8]) -> io::Result<()> {
    recover_transactional_write(path)?;
    let rollback = sibling_with_suffix(path, ROLLBACK_SUFFIX)?;
    let commit = sibling_with_suffix(path, COMMIT_SUFFIX)?;
    let rollback_document = match fs::read(path) {
        Ok(prior) => {
            let mut rollback = Vec::with_capacity(prior.len() + 1);
            rollback.push(1);
            rollback.extend(prior);
            rollback
        }
        Err(error) if error.kind() == io::ErrorKind::NotFound => vec![0],
        Err(error) => return Err(error),
    };
    atomic_write_owner_only(&rollback, &rollback_document)?;
    if let Err(error) = atomic_write_owner_only(path, contents) {
        return match recover_transactional_write(path) {
            Ok(()) => Err(error),
            Err(recovery) => Err(io::Error::other(format!(
                "replacement failed ({error}); rollback remains recoverable but immediate restore failed ({recovery})"
            ))),
        };
    }
    if let Err(error) = atomic_write_owner_only(&commit, b"committed\n") {
        // The marker may already have been renamed before its directory sync
        // failed. It did not cross the durable commit boundary, so remove it
        // before invoking ordinary rollback recovery.
        let _ = fs::remove_file(&commit);
        if let Some(parent) = path.parent() {
            let _ = sync_directory(parent);
        }
        return match recover_transactional_write(path) {
            Ok(()) => Err(error),
            Err(recovery) => Err(io::Error::other(format!(
                "commit failed ({error}); rollback remains recoverable but immediate restore failed ({recovery})"
            ))),
        };
    }

    // Once the marker is durable, cleanup is not part of the commit result.
    // A restart seeing it keeps the new primary and finishes the same cleanup.
    let _ = cleanup_committed_transaction(path, &rollback, &commit);
    Ok(())
}

/// Execute a state mutation while holding an owner-only advisory lock shared
/// by every router process using the same data directory.
pub fn with_exclusive_lock<T, E>(
    path: &Path,
    operation: impl FnOnce() -> Result<T, E>,
) -> Result<T, E>
where
    E: From<io::Error>,
{
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(E::from)?;
    }
    let mut options = OpenOptions::new();
    options.read(true).write(true).create(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let lock = options.open(path).map_err(E::from)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        lock.set_permissions(fs::Permissions::from_mode(0o600))
            .map_err(E::from)?;
    }
    lock.lock().map_err(E::from)?;
    let result = operation();
    let unlock = lock.unlock();
    #[cfg(test)]
    let unlock = unlock.and_then(|()| fail_if_injected(path, FaultPoint::Unlock));
    match (result, unlock) {
        (Err(error), _) => Err(error),
        // Closing the descriptor releases the lock as well. A late explicit
        // unlock failure cannot undo a completed durable operation and must
        // not turn its public result into an ambiguous failure.
        (Ok(value), _) => Ok(value),
    }
}

/// Execute a read while holding a *shared* advisory lock on the same file.
///
/// A listing is a read, and a read that takes the exclusive lock serialises
/// itself against the request path: `try_consume_request` runs per proxied
/// request and wants the same lock, so one slow listing queues live traffic
/// behind it (issue #351). A shared lock lets concurrent readers proceed
/// together and still excludes writers.
pub fn with_shared_lock<T, E>(path: &Path, operation: impl FnOnce() -> Result<T, E>) -> Result<T, E>
where
    E: From<io::Error>,
{
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(E::from)?;
    }
    let mut options = OpenOptions::new();
    options.read(true).write(true).create(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let lock = options.open(path).map_err(E::from)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        lock.set_permissions(fs::Permissions::from_mode(0o600))
            .map_err(E::from)?;
    }
    lock.lock_shared().map_err(E::from)?;
    let result = operation();
    let unlock = lock.unlock();
    match (result, unlock) {
        (Err(error), _) => Err(error),
        (Ok(_), Err(error)) => Err(E::from(error)),
        (Ok(value), Ok(())) => Ok(value),
    }
}

/// An exclusive advisory lock held for as long as the guard lives.
///
/// Returned by [`lock_exclusive_async`] so an `async` critical section — a
/// token exchange over the network — can serialise against other holders
/// without blocking a runtime worker on `flock`.
#[derive(Debug)]
pub struct FileLockGuard {
    file: fs::File,
    path: std::path::PathBuf,
}

impl FileLockGuard {
    /// Path of the lock file this guard holds.
    #[must_use]
    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl Drop for FileLockGuard {
    fn drop(&mut self) {
        // Best effort: the lock is released by closing the descriptor anyway.
        let _ = self.file.unlock();
    }
}

/// How often a contended lock is re-tried while waiting.
const LOCK_POLL_INTERVAL: std::time::Duration = std::time::Duration::from_millis(20);

/// Acquire an exclusive advisory lock on `path`, waiting up to `timeout`.
///
/// `flock` has no async form, so the lock is polled rather than waited on: a
/// blocking [`std::fs::File::lock`] inside an `async fn` would park a runtime
/// worker for as long as another process holds it, which for a credential
/// refresh can be a full network round trip.
///
/// Contention is [`TryLockError::WouldBlock`], a variant of its own rather than
/// a platform errno to classify: `EWOULDBLOCK` maps to
/// [`io::ErrorKind::WouldBlock`] on unix, but Windows answers
/// `ERROR_LOCK_VIOLATION`, which maps to nothing in particular. Reading
/// contention as a broken lock would make the waiter proceed *unlocked*, and
/// two holders of one credential would then spend the same refresh token twice
/// (issue #239).
///
/// # Errors
///
/// Returns [`io::ErrorKind::WouldBlock`] when the lock is still held after
/// `timeout`, or the underlying error when the lock file cannot be opened.
pub async fn lock_exclusive_async(
    path: &Path,
    timeout: std::time::Duration,
) -> io::Result<FileLockGuard> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut options = OpenOptions::new();
    options.read(true).write(true).create(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let file = options.open(path)?;
    let mut waited = std::time::Duration::ZERO;
    loop {
        match file.try_lock() {
            Ok(()) => {
                return Ok(FileLockGuard {
                    file,
                    path: path.to_path_buf(),
                });
            }
            Err(TryLockError::WouldBlock) => {
                if waited >= timeout {
                    return Err(io::Error::new(
                        io::ErrorKind::WouldBlock,
                        format!("timed out waiting for the lock on {}", path.display()),
                    ));
                }
                tokio::time::sleep(LOCK_POLL_INTERVAL).await;
                waited = waited.saturating_add(LOCK_POLL_INTERVAL);
            }
            Err(TryLockError::Error(error)) => return Err(error),
        }
    }
}

/// Sync a directory entry update on platforms that support directory fsync.
pub fn sync_directory(path: &Path) -> io::Result<()> {
    #[cfg(unix)]
    {
        fs::File::open(path)?.sync_all()
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn durable_write_is_owner_only_and_leaves_no_temporary_file() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("state.json");
        atomic_write_owner_only(&path, b"one").unwrap();
        atomic_write_owner_only(&path, b"two").unwrap();
        assert_eq!(fs::read(&path).unwrap(), b"two");
        assert_eq!(fs::read_dir(directory.path()).unwrap().count(), 1);
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            assert_eq!(
                fs::metadata(path).unwrap().permissions().mode() & 0o777,
                0o600
            );
        }
    }

    #[test]
    fn transactional_failure_after_primary_rename_restores_previous_bytes() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("state.json");
        atomic_write_owner_only(&path, b"old").unwrap();
        let _fault = inject_fault(&path, FaultPoint::AfterRename);

        transactional_write_owner_only(&path, b"new").expect_err("late write must fail");

        assert_eq!(fs::read(&path).unwrap(), b"old");
        assert!(
            !sibling_with_suffix(&path, ROLLBACK_SUFFIX)
                .unwrap()
                .exists()
        );
        assert!(!sibling_with_suffix(&path, COMMIT_SUFFIX).unwrap().exists());
    }

    #[test]
    fn transactional_failure_while_committing_restores_previous_bytes() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("state.json");
        atomic_write_owner_only(&path, b"old").unwrap();
        let commit = sibling_with_suffix(&path, COMMIT_SUFFIX).unwrap();
        let _fault = inject_fault(&commit, FaultPoint::AfterRename);

        transactional_write_owner_only(&path, b"new").expect_err("commit must fail");

        assert_eq!(fs::read(&path).unwrap(), b"old");
        assert!(
            !sibling_with_suffix(&path, ROLLBACK_SUFFIX)
                .unwrap()
                .exists()
        );
        assert!(!commit.exists());
    }

    #[test]
    fn restart_recovery_obeys_the_durable_commit_marker() {
        for committed in [false, true] {
            let directory = tempfile::tempdir().unwrap();
            let path = directory.path().join("state.json");
            let rollback = sibling_with_suffix(&path, ROLLBACK_SUFFIX).unwrap();
            let commit = sibling_with_suffix(&path, COMMIT_SUFFIX).unwrap();
            atomic_write_owner_only(&path, b"new").unwrap();
            atomic_write_owner_only(&rollback, b"\x01old").unwrap();
            if committed {
                atomic_write_owner_only(&commit, b"committed\n").unwrap();
            }

            recover_transactional_write(&path).unwrap();

            assert_eq!(
                fs::read(&path).unwrap(),
                if committed { b"new" } else { b"old" }
            );
            assert!(!rollback.exists());
            assert!(!commit.exists());
        }
    }

    #[test]
    fn committed_cleanup_failures_never_make_rollback_authoritative() {
        for point in [
            FaultPoint::RemoveRollback,
            FaultPoint::SyncAfterRollbackRemoval,
            FaultPoint::RemoveCommit,
            FaultPoint::SyncAfterCommitRemoval,
        ] {
            let directory = tempfile::tempdir().unwrap();
            let path = directory.path().join("state.json");
            let rollback = sibling_with_suffix(&path, ROLLBACK_SUFFIX).unwrap();
            let commit = sibling_with_suffix(&path, COMMIT_SUFFIX).unwrap();
            atomic_write_owner_only(&path, b"new").unwrap();
            atomic_write_owner_only(&rollback, b"\x01old").unwrap();
            atomic_write_owner_only(&commit, b"committed\n").unwrap();
            let fault = inject_fault(&path, point);

            recover_transactional_write(&path).expect_err("cleanup fault must be reported");
            assert_eq!(fs::read(&path).unwrap(), b"new", "fault at {point:?}");
            if matches!(
                point,
                FaultPoint::RemoveRollback
                    | FaultPoint::SyncAfterRollbackRemoval
                    | FaultPoint::RemoveCommit
            ) {
                assert!(commit.exists(), "fault at {point:?}");
            }
            drop(fault);

            recover_transactional_write(&path).unwrap();
            recover_transactional_write(&path).unwrap();
            assert_eq!(fs::read(&path).unwrap(), b"new", "fault at {point:?}");
            assert!(!rollback.exists(), "fault at {point:?}");
            assert!(!commit.exists(), "fault at {point:?}");
        }
    }

    #[test]
    fn late_unlock_failure_does_not_reclassify_a_completed_operation() {
        let directory = tempfile::tempdir().unwrap();
        let lock_path = directory.path().join("state.lock");
        let _fault = inject_fault(&lock_path, FaultPoint::Unlock);

        let result = with_exclusive_lock::<_, io::Error>(&lock_path, || Ok(7)).unwrap();

        assert_eq!(result, 7);
    }

    /// Contention has to be recognised on every platform, not only where it
    /// happens to map onto `WouldBlock`.
    ///
    /// Windows answers a contended `LockFileEx` with `ERROR_LOCK_VIOLATION`,
    /// which `io::ErrorKind` does not classify; reading that as a broken lock
    /// makes the waiter proceed *unlocked*, and two holders of one credential
    /// then spend the same refresh token twice — exactly the race the lock
    /// exists to prevent (issue #239). The standard library answers with
    /// [`TryLockError::WouldBlock`] on every platform, so this asserts the
    /// variant rather than an errno.
    ///
    /// Advisory locks belong to the *open file description*, so two separate
    /// handles inside one process contend exactly as two processes do — which
    /// is what lets this run without spawning one.
    #[tokio::test]
    async fn contention_is_told_apart_from_a_lock_that_cannot_work() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("credential.lock");

        let holder = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(&path)
            .unwrap();
        holder.lock().unwrap();

        let waiter = OpenOptions::new()
            .read(true)
            .write(true)
            .open(&path)
            .unwrap();
        assert!(
            matches!(waiter.try_lock(), Err(TryLockError::WouldBlock)),
            "a contended lock must report WouldBlock, not a platform errno"
        );

        // And the polling waiter must read that as "held", not as "broken".
        let refused = lock_exclusive_async(&path, std::time::Duration::from_millis(60)).await;
        let error = refused.expect_err("the lock was held");
        assert_eq!(error.kind(), io::ErrorKind::WouldBlock);

        holder.unlock().unwrap();
        assert!(
            lock_exclusive_async(&path, std::time::Duration::from_millis(60))
                .await
                .is_ok(),
            "the lock must be available once the holder releases it"
        );
    }

    #[tokio::test]
    async fn lock_open_errors_are_returned_to_the_caller() {
        let directory = tempfile::tempdir().unwrap();
        let blocking_file = directory.path().join("not-a-directory");
        fs::write(&blocking_file, b"occupied").unwrap();

        let error = lock_exclusive_async(
            &blocking_file.join("credential.lock"),
            std::time::Duration::from_millis(60),
        )
        .await
        .expect_err("a lock below a regular file cannot be opened");

        assert_ne!(error.kind(), io::ErrorKind::WouldBlock);
        assert!(error.raw_os_error().is_some(), "{error}");
    }

    /// Two holders of one credential must serialise, and a holder that cannot
    /// get in must give up rather than wait forever: a stale lock must never be
    /// able to wedge token renewal (issue #239).
    ///
    /// Linux-only because the contending holder is `flock(1)`, which macOS does
    /// not ship; the code under test is the same on both.
    #[cfg(target_os = "linux")]
    #[tokio::test]
    async fn an_exclusive_lock_excludes_and_then_gives_up() {
        use std::os::unix::fs::PermissionsExt as _;

        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("nested").join("credential.lock");
        let taken = directory.path().join("taken");
        {
            let guard = lock_exclusive_async(&path, std::time::Duration::from_secs(1))
                .await
                .expect("first holder");
            assert_eq!(guard.path(), path);
            assert_eq!(
                fs::metadata(&path).unwrap().permissions().mode() & 0o777,
                0o600
            );
        }

        // Contention is exercised from another process: two lock attempts on
        // the same descriptor within one process would not exclude each other.
        let mut holder = crate::operation_context::command("sh")
            .arg("-c")
            .arg(format!(
                "exec 9>>'{}'; flock 9 && touch '{}' && sleep 5",
                path.display(),
                taken.display()
            ))
            .spawn()
            .expect("spawn the competing holder");
        for _ in 0..200 {
            if taken.exists() {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        assert!(taken.exists(), "the competing holder never took the lock");

        let refused = lock_exclusive_async(&path, std::time::Duration::from_millis(60)).await;
        let error = refused.expect_err("the lock was held by another process");
        assert_eq!(error.kind(), io::ErrorKind::WouldBlock);
        assert!(error.to_string().contains("credential.lock"), "{error}");

        let _ = holder.kill();
        let _ = holder.wait();
    }

    /// A read-only mount is the common cause of a failed credential write, and
    /// the bare `errno` does not say what to change (issue #205).
    #[test]
    fn a_read_only_mount_is_named_as_the_cause() {
        let message = describe_write_failure(
            Path::new("/data/claude/.credentials.json"),
            &io::Error::from(io::ErrorKind::ReadOnlyFilesystem),
        );
        assert!(
            message.contains("/data/claude/.credentials.json"),
            "{message}"
        );
        assert!(message.contains("read-only"), "{message}");
        // The remedy must be actionable, and say the cost of applying it.
        assert!(message.contains(":ro"), "{message}");
        assert!(
            message.contains("token renewal do not need write"),
            "{message}"
        );
    }

    #[test]
    fn other_write_failures_keep_the_underlying_error() {
        let message = describe_write_failure(
            Path::new("/data/x.json"),
            &io::Error::from(io::ErrorKind::PermissionDenied),
        );
        assert!(message.contains("/data/x.json"), "{message}");
        assert!(!message.contains("read-only"), "{message}");
    }
}

//! Explicit, bounded emergency mode that accepts any incoming Router token
//! (issue #645).
//!
//! The mode exists for an operator recovering their own deployment: a client
//! holding an old, unknown, expired, revoked, foreign or malformed Router token
//! keeps working while the real token store is repaired. It is never the
//! default and never switches itself on.
//!
//! What it changes, and nothing more:
//!
//! - **Client (inference, model discovery, usage, run lease) routes.** Any
//!   *non-empty* credential in any accepted carrier (`Authorization: Bearer`,
//!   `x-api-key`, `x-goog-api-key`; `la_sk_`, `at-` or anything else) is
//!   accepted. The caller receives synthetic claims whose id is
//!   `emergency-bypass-<fingerprint>`, so no durable token record is read for
//!   authority, charged, renewed, revoked or revived. Budgets, rate limits and
//!   per-token model pins therefore do not apply to bypassed requests.
//! - **No credential at all** is still `401`: the mode accepts any *token*, not
//!   anonymous callers.
//! - **Management routes** keep ordinary administrator authentication. An
//!   emergency token can neither mint, rotate nor revoke credentials, which is
//!   what keeps the mode non-destructive.
//! - **Consumer subscriptions** keep their entitlement matrix and request
//!   evidence rules, because those protect the provider account rather than
//!   the Router. The client binding the matrix needs is inferred from the
//!   request (its user agent and client headers, the `at-` Codex carrier) and
//!   only then from the unverified token payload.
//! - **Upstream credentials** are untouched and must still be valid.
//!
//! Every bypass is counted by reason and logged with a token fingerprint, never
//! the token itself. The mode ends when its bounded duration lapses, when an
//! administrator calls `POST /api/management/emergency-auth/disable`, or when
//! the process restarts without the flag.

use std::collections::BTreeMap;
use std::net::SocketAddr;
use std::sync::Mutex;
use std::sync::atomic::{AtomicI64, AtomicU64, Ordering};

use axum::http::HeaderMap;

use crate::clients::ClientKind;
use crate::token::TokenClaims;

/// Command-line flag that turns the mode on.
pub const FLAG: &crate::translation_core::Str = "--emergency-accept-any-token";
/// Environment variable that turns the mode on.
pub const ENV: &crate::translation_core::Str = "EMERGENCY_ACCEPT_ANY_TOKEN";
/// Environment variable acknowledging exposure beyond loopback.
pub const ALLOW_NON_LOOPBACK_ENV: &crate::translation_core::Str = "EMERGENCY_ALLOW_NON_LOOPBACK";
/// Environment variable bounding how long the mode stays on.
pub const DURATION_ENV: &crate::translation_core::Str = "EMERGENCY_DURATION_MINUTES";
/// Every environment variable that configures the mode. Deployment launchers
/// strip these so an ordinary deployment never inherits the mode silently.
pub const ENV_VARS: [&crate::translation_core::Str; 3] = [ENV, ALLOW_NON_LOOPBACK_ENV, DURATION_ENV];
/// Default lifetime of the mode once enabled.
pub const DEFAULT_DURATION_MINUTES: u64 = 60;
/// Longest lifetime an operator may request. A forgotten mode lapses within a
/// day even if nobody disables it.
pub const MAX_DURATION_MINUTES: u64 = 24 * 60;
/// Prefix of the synthetic token id given to every bypassed request.
pub const SUBJECT_PREFIX: &crate::translation_core::Str = "emergency-bypass-";
/// Label given to every bypassed request, visible in the request log.
pub const LABEL: &crate::translation_core::Str = "emergency-bypass";
/// Response header set on `/api/health` while the mode is active.
pub const HEALTH_HEADER: &crate::translation_core::Str = "x-link-assistant-emergency-auth";

/// Operator configuration for the mode, resolved from CLI, env and `.lenv`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct EmergencyAuthConfig {
    /// Whether the mode starts enabled.
    pub enabled: bool,
    /// Explicit acknowledgement that a non-loopback listener may serve it.
    pub allow_non_loopback: bool,
    /// How long it stays on after start-up.
    pub duration_minutes: u64,
}

impl Default for EmergencyAuthConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            allow_non_loopback: false,
            duration_minutes: DEFAULT_DURATION_MINUTES,
        }
    }
}

impl EmergencyAuthConfig {
    /// Read the switches from the environment, for the legacy
    /// [`crate::config::Config::from_env`] path. Unparsable values keep the
    /// mode off rather than guessing.
    #[must_use]
    pub fn from_env() -> Self {
        let truthy = |name: &str| {
            crate::operation_context::var(name).is_ok_and(|value| {
                matches!(
                    value.trim().to_ascii_lowercase().as_str(),
                    "1" | "true" | "yes" | "on"
                )
            })
        };
        Self {
            enabled: truthy(ENV),
            allow_non_loopback: truthy(ALLOW_NON_LOOPBACK_ENV),
            duration_minutes: crate::operation_context::var(DURATION_ENV)
                .ok()
                .and_then(|value| value.trim().parse().ok())
                .unwrap_or(DEFAULT_DURATION_MINUTES),
        }
    }

    /// Refuse a configuration that would silently expose the mode.
    ///
    /// # Errors
    ///
    /// Returns an operator-facing message when the duration is out of bounds
    /// or when a listener is not loopback and exposure was not acknowledged.
    pub fn check(&self, listeners: &[SocketAddr]) -> crate::translation_core::Outcome<(), String> {
        if !self.enabled {
            return Ok(());
        }
        if self.duration_minutes == 0 || self.duration_minutes > MAX_DURATION_MINUTES {
            return Err(format!(
                "{DURATION_ENV} must be between 1 and {MAX_DURATION_MINUTES} minutes"
            ));
        }
        let exposed = listeners
            .iter()
            .filter(|address| !address.ip().is_loopback())
            .map(ToString::to_string)
            .collect::<Vec<_>>();
        if exposed.is_empty() || self.allow_non_loopback {
            return Ok(());
        }
        Err(format!(
            "{FLAG} accepts any Router token, but the router would listen on non-loopback \
             address(es) {}. Bind to 127.0.0.1 (for example `--host 127.0.0.1`) or acknowledge \
             the exposure with --emergency-allow-non-loopback / {ALLOW_NON_LOOPBACK_ENV}=true.",
            exposed.join(", ")
        ))
    }
}

/// Live state of the mode, shared by every request through the token manager.
#[derive(Debug, Default)]
pub struct EmergencyAuth {
    /// Unix second until which the mode is active; `0` means off.
    active_until: AtomicI64,
    bypassed: AtomicU64,
    reasons: Mutex<BTreeMap<&'static str, u64>>,
}

/// Point-in-time view of the mode for diagnostics.
#[derive(Clone, Debug, Default, serde::Serialize, schemars::JsonSchema)]
pub struct EmergencyAuthStatus {
    pub active: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub expires_at: Option<i64>,
    pub bypassed_requests: u64,
    pub bypassed_by_reason: BTreeMap<&'static str, u64>,
}

impl EmergencyAuth {
    /// Turn the mode on for a bounded number of minutes and return the unix
    /// second at which it lapses.
    pub fn enable_for_minutes(&self, minutes: u64) -> i64 {
        let minutes = minutes.clamp(1, MAX_DURATION_MINUTES);
        let seconds = i64::try_from(minutes * 60).unwrap_or(i64::MAX);
        let until = now().saturating_add(seconds);
        self.active_until.store(until, Ordering::SeqCst);
        until
    }

    /// Apply a checked start-up configuration: when enabled, turn the mode on
    /// and log a warning that names every consequence. Returns the lapse time.
    pub fn start(&self, config: &EmergencyAuthConfig) -> crate::translation_core::Maybe<i64> {
        if !config.enabled {
            return None;
        }
        let until = self.enable_for_minutes(config.duration_minutes);
        let lapses = chrono::DateTime::from_timestamp(until, 0)
            .map_or_else(|| until.to_string(), |time| time.to_rfc3339());
        tracing::warn!(
            "EMERGENCY ANY-TOKEN MODE IS ON until {lapses}: client routes accept any non-empty \
             Router token without signature, expiry, revocation, record, budget or model-policy \
             checks. Management routes keep normal admin authentication and no token record is \
             modified. Turn it off with POST /api/management/emergency-auth/disable or restart \
             without {FLAG}."
        );
        Some(until)
    }

    /// Turn the mode off at once. Returns whether it was on.
    pub fn disable(&self) -> bool {
        let previous = self.active_until.swap(0, Ordering::SeqCst);
        previous > now()
    }

    /// When the mode lapses, if it is on right now.
    #[must_use]
    pub fn active_until(&self) -> crate::translation_core::Maybe<i64> {
        let until = self.active_until.load(Ordering::SeqCst);
        (until > now()).then_some(until)
    }

    /// Whether the mode is on right now.
    #[must_use]
    pub fn is_active(&self) -> bool {
        self.active_until().is_some()
    }

    /// Count one bypassed request under the check it bypassed.
    pub fn record_bypass(&self, reason: &'static crate::translation_core::Str) {
        self.bypassed.fetch_add(1, Ordering::Relaxed);
        if let Ok(mut reasons) = self.reasons.lock() {
            *reasons.entry(reason).or_default() += 1;
        }
    }

    /// Snapshot for status endpoints.
    #[must_use]
    pub fn status(&self) -> EmergencyAuthStatus {
        let expires_at = self.active_until();
        EmergencyAuthStatus {
            active: expires_at.is_some(),
            expires_at,
            bypassed_requests: self.bypassed.load(Ordering::Relaxed),
            bypassed_by_reason: self
                .reasons
                .lock()
                .map(|reasons| reasons.clone())
                .unwrap_or_default(),
        }
    }

    /// Prometheus lines for the mode.
    #[must_use]
    pub fn render_prometheus(&self) -> String {
        use std::fmt::Write as _;
        let status = self.status();
        let mut body = String::from(
            "# HELP link_assistant_emergency_auth_active 1 while the emergency any-token mode is on.\n\
             # TYPE link_assistant_emergency_auth_active gauge\n",
        );
        let _ = writeln!(
            body,
            "link_assistant_emergency_auth_active {}",
            u8::from(status.active)
        );
        body.push_str(
            "# HELP link_assistant_emergency_auth_bypassed_total Requests admitted by the emergency any-token mode, by the check they bypassed.\n\
             # TYPE link_assistant_emergency_auth_bypassed_total counter\n",
        );
        if status.bypassed_by_reason.is_empty() {
            body.push_str("link_assistant_emergency_auth_bypassed_total 0\n");
        }
        for (reason, count) in &status.bypassed_by_reason {
            let _ = writeln!(
                body,
                "link_assistant_emergency_auth_bypassed_total{{reason=\"{reason}\"}} {count}"
            );
        }
        body
    }
}

/// Stable, non-reversible fingerprint of a token for logs and diagnostics.
#[must_use]
pub fn token_fingerprint(token: &crate::translation_core::Str) -> String {
    use sha2::Digest;
    let digest = sha2::Sha256::digest(token.as_bytes());
    hex::encode(&digest[..6])
}

/// Claims given to a request the emergency mode admits.
///
/// The id is derived from the token fingerprint, never from the token's own
/// `sub`, so budget admission, usage settlement and run-lease renewal find no
/// durable record and change nothing.
#[must_use]
pub fn synthetic_claims(token: &crate::translation_core::Str, headers: &HeaderMap) -> TokenClaims {
    let payload = unverified_payload(token);
    let payload_field = |name: &str| {
        payload
            .as_ref()
            .and_then(|value| value.get(name))
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
    };
    let client = infer_client(token, headers).or_else(|| {
        payload_field("client_kind")
            .as_deref()
            .and_then(ClientKind::from_str_opt)
    });
    let fingerprint = token_fingerprint(token);
    let now = now();
    TokenClaims {
        sub: format!("{SUBJECT_PREFIX}{fingerprint}"),
        iat: now,
        exp: now.saturating_add(60),
        label: LABEL.to_string(),
        // Never administrative: management routes keep their own checks.
        scope: String::new(),
        github_repos: Vec::new(),
        client_kind: client.map(|client| client.canonical_name().to_string()),
        principal_id: client.map(|_| {
            payload_field("principal_id")
                .filter(|principal| !principal.trim().is_empty())
                .unwrap_or_else(|| format!("emergency-{fingerprint}"))
        }),
    }
}

/// Whether claims were produced by [`synthetic_claims`].
#[must_use]
pub fn is_synthetic(claims: &TokenClaims) -> bool {
    is_synthetic_id(&claims.sub) && claims.label == LABEL
}

/// Whether a token id is the synthetic id of a bypassed request. Real ids are
/// UUIDs, so the prefix can never name a durable record.
#[must_use]
pub fn is_synthetic_id(token_id: &crate::translation_core::Str) -> bool {
    token_id.starts_with(SUBJECT_PREFIX)
}

/// Decode a JWT payload without verifying it. Used only to keep a bypassed
/// request's client binding and subscriber continuity; never as authority.
fn unverified_payload(token: &crate::translation_core::Str) -> crate::translation_core::Maybe<crate::translation_core::Json> {
    use base64::Engine;
    let jwt = crate::token::token_jwt(token).unwrap_or(token);
    let payload = jwt.split('.').nth(1)?;
    let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(payload.trim_end_matches('='))
        .ok()?;
    serde_json::from_slice(&bytes).ok()
}

/// Infer the calling client from what the request itself says.
fn infer_client(token: &crate::translation_core::Str, headers: &HeaderMap) -> crate::translation_core::Maybe<ClientKind> {
    let header = |name: &str| {
        headers
            .get(name)
            .and_then(|value| value.to_str().ok())
            .filter(|value| !value.is_empty())
    };
    if let Some(client) = header("x-link-assistant-client").and_then(ClientKind::from_str_opt) {
        return Some(client);
    }
    let agent = header("user-agent").map(str::to_ascii_lowercase);
    let agent = agent.as_deref().unwrap_or_default();
    if agent.starts_with("claude") {
        Some(ClientKind::ClaudeCode)
    } else if agent.starts_with("codex") {
        Some(ClientKind::Codex)
    } else if agent.starts_with("opencode/") {
        Some(ClientKind::Opencode)
    } else if agent.starts_with("grok") {
        Some(ClientKind::GrokCli)
    } else if header("x-goog-api-client").is_some() || header("x-goog-api-key").is_some() {
        Some(ClientKind::GeminiCli)
    } else if header("x-stainless-package-version").is_some() {
        Some(ClientKind::QwenCode)
    } else if token.starts_with(crate::token::CODEX_TOKEN_PREFIX) {
        // The `at-` prefix is only a fallback: the carrier and user agent say
        // which client actually sent it, so an `at-` token presented to the
        // Gemini surface is still a Gemini request.
        Some(ClientKind::Codex)
    } else {
        None
    }
}

fn now() -> i64 {
    crate::operation_context::now().timestamp()
}

