        let mut translator = NativeStreamTranslator::default();
        let first = translator
            .push(b"data: {\"response\":{\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"one\"}]}}]}}\n\n")
            .unwrap();
        let first = String::from_utf8(first.to_vec()).unwrap();
        assert!(first.contains("one"), "{first}");
        assert!(!first.contains("response"), "{first}");
    }

    #[test]
    fn upstream_error_events_are_forwarded_without_private_payload_logging() {
        let mut translator = OpenAiStreamTranslator::new("model");
        let output = translator
            .push(b"data: {\"error\":{\"code\":429,\"message\":\"limited\"}}\n\n")
            .unwrap();
        let output = String::from_utf8(output.to_vec()).unwrap();
        assert!(output.contains("limited"), "{output}");
        assert!(output.contains("rate_limit_error"), "{output}");
        assert!(output.contains("rate_limit_exceeded"), "{output}");
        assert!(!output.contains("[DONE]"), "{output}");
    }

    fn events(output: &str) -> Vec<Value> {
        output
            .lines()
            .filter_map(|line| line.strip_prefix("data: "))
            .filter(|data| *data != "[DONE]")
            .map(|data| serde_json::from_str(data).unwrap())
            .collect()
    }

    #[test]
    fn responses_stream_preserves_text_tool_identity_finish_and_usage_across_splits() {
        let mut translator = ResponsesStreamTranslator::new("requested-model");
        assert!(
            translator
                .push(b"data: {\"response\":{\"modelVersion\":\"served-model\",\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"hel")
                .unwrap()
                .is_empty()
        );
        let output = translator
            .push(b"lo\"},{\"functionCall\":{\"id\":\"call_7\",\"name\":\"lookup\",\"args\":{\"key\":\"v\"}}}]},\"finishReason\":\"STOP\"}],\"usageMetadata\":{\"promptTokenCount\":2,\"candidatesTokenCount\":3,\"totalTokenCount\":5}}}\n\n")
            .unwrap();
        let output = String::from_utf8(output.to_vec()).unwrap();
        let events = events(&output);
        assert!(events.iter().any(|event| {
            event["type"] == "response.output_text.delta" && event["delta"] == "hello"
        }));
        assert!(events.iter().any(|event| {
            event["type"] == "response.function_call_arguments.done"
                && event["arguments"] == "{\"key\":\"v\"}"
        }));
        let completed = events
            .iter()
            .find(|event| event["type"] == "response.completed")
            .unwrap();
        assert_eq!(completed["response"]["status"], "completed");
        assert_eq!(completed["response"]["model"], "served-model");
        assert_eq!(completed["response"]["output"][1]["call_id"], "call_7");
        assert_eq!(completed["response"]["output"][1]["name"], "lookup");
        assert_eq!(completed["response"]["usage"]["total_tokens"], 5);
        assert!(output.ends_with("data: [DONE]\n\n"));
    }

    #[test]
    fn responses_stream_uses_incomplete_terminal_events_for_every_non_stop_reason() {
        for (reason, incomplete) in [
            ("MAX_TOKENS", "max_output_tokens"),
            ("SAFETY", "content_filter"),
            ("RECITATION", "content_filter"),
            ("MALFORMED_FUNCTION_CALL", "content_filter"),
        ] {
            let mut translator = ResponsesStreamTranslator::new("model");
            let payload = format!(
                "data: {{\"response\":{{\"candidates\":[{{\"content\":{{\"parts\":[{{\"text\":\"partial\"}}]}},\"finishReason\":\"{reason}\"}}]}}}}\n\n"
            );
            let output = translator.push(payload.as_bytes()).unwrap();
            let output = String::from_utf8(output.to_vec()).unwrap();
            let events = events(&output);
            let terminal = events
                .iter()
                .find(|event| event["type"] == "response.incomplete")
                .unwrap_or_else(|| panic!("missing incomplete event for {reason}: {output}"));
            assert_eq!(terminal["response"]["status"], "incomplete", "{reason}");
            assert_eq!(
                terminal["response"]["incomplete_details"]["reason"], incomplete,
                "{reason}"
            );
            assert!(!output.contains("response.completed"), "{reason}: {output}");
        }
    }

    #[test]
    fn responses_stream_errors_use_responses_error_events() {
        let mut translator = ResponsesStreamTranslator::new("model");
        let output = translator
            .push(b"data: {\"error\":{\"code\":429,\"message\":\"limited\"}}\n\n")
            .unwrap();
        let output = String::from_utf8(output.to_vec()).unwrap();
        let event = events(&output).pop().unwrap();
        assert_eq!(event["type"], "error");
        assert_eq!(event["code"], "rate_limit_exceeded");
        assert_eq!(event["message"], "limited");
        assert!(!output.contains("[DONE]"));
    }
}

//! Native Gemini ↔ `OpenAI` Chat Completions translation.
//!
//! The Gemini CLI speaks only `generateContent`/`streamGenerateContent`. Its
//! requests must therefore reach Codex, Claude and Qwen subscriptions through
//! the router's `OpenAI` Chat Completions path, which every other namespace
//! already shares. This module owns that translation in both directions so the
//! HTTP handler in [`crate::gemini`] stays a thin router.
//!
//! The translation is intentionally lossless for the parts Gemini CLI actually
//! uses: system instruction, multi-turn text, client function declarations,
//! function calls, function results, generation config and usage metadata.

use serde_json::{Value, json};

/// Gemini part-role for assistant turns.
const MODEL_ROLE: &str = "model";

#[path = "gemini_bridge_request.rs"]
mod request;
pub use request::{chat_to_gemini_request, gemini_request_to_chat};
pub(crate) use request::{
    chat_to_gemini_request_checked, gemini_request_to_chat_checked, responses_to_chat_checked,
};

/// Translate an `OpenAI` Chat Completion into a native Gemini
/// `GenerateContentResponse`.
#[must_use]
pub fn chat_to_gemini_response(chat: &Value, model: &str) -> Value {
    let choice = chat
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first());
    let message = choice.and_then(|choice| choice.get("message"));

    let mut parts: Vec<Value> = Vec::new();
    if let Some(text) = message
        .and_then(|message| message.get("content"))
        .and_then(Value::as_str)
        && !text.is_empty()
    {
        parts.push(json!({ "text": text }));
    }
    for call in message
        .and_then(|message| message.get("tool_calls"))
        .and_then(Value::as_array)
        .map_or(&[][..], Vec::as_slice)
    {
        let function = call.get("function");
        let name = function
            .and_then(|function| function.get("name"))
            .and_then(Value::as_str)
            .unwrap_or_default();
        let args = function
            .and_then(|function| function.get("arguments"))
            .and_then(Value::as_str)
            .and_then(|arguments| serde_json::from_str::<Value>(arguments).ok())
            .unwrap_or_else(|| json!({}));
        let mut call_part = json!({ "name": name, "args": args });
        if let Some(id) = call.get("id").and_then(Value::as_str) {
            call_part["id"] = json!(id);
        }
        parts.push(json!({ "functionCall": call_part }));
    }

    let finish_reason = choice
        .and_then(|choice| choice.get("finish_reason"))
        .and_then(Value::as_str)
        .map_or("STOP", map_finish_reason);

    let usage = chat.get("usage");
    let prompt_tokens = usage
        .and_then(|usage| usage.get("prompt_tokens"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let completion_tokens = usage
        .and_then(|usage| usage.get("completion_tokens"))
        .and_then(Value::as_u64)
        .unwrap_or(0);

    json!({
        "candidates": [{
            "index": 0,
            "content": { "role": MODEL_ROLE, "parts": parts },
            "finishReason": finish_reason,
        }],
        "usageMetadata": {
            "promptTokenCount": prompt_tokens,
            "candidatesTokenCount": completion_tokens,
            "totalTokenCount": prompt_tokens + completion_tokens,
        },
        "modelVersion": model,
    })
}

fn map_finish_reason(openai: &str) -> &'static str {
    match openai {
        "length" => "MAX_TOKENS",
        "content_filter" => "SAFETY",
        _ => "STOP",
    }
}

/// Translate an `OpenAI`-shaped error body into Gemini's error envelope.
#[must_use]
pub fn openai_error_to_gemini(status: u16, body: &Value) -> Value {
    let message = body
        .pointer("/error/message")
        .and_then(Value::as_str)
        .unwrap_or("upstream request failed");
    let status_text = match status {
        400 => "INVALID_ARGUMENT",
        401 | 403 => "PERMISSION_DENIED",
        404 => "NOT_FOUND",
        429 => "RESOURCE_EXHAUSTED",
        503 => "UNAVAILABLE",
        _ => "INTERNAL",
    };
    json!({
        "error": {
            "code": status,
            "message": message,
            "status": status_text,
        }
    })
}

#[cfg(test)]
