//! Git smart-HTTP proxy with ref-update policy.
//!
//! The GitHub API proxy denies deletions and forced ref updates, but it only
//! ever sees REST and GraphQL. A `git push --force` travels over the git
//! transport as a single `git-receive-pack` exchange and never reaches those
//! routes, so configuring an agent's git to "use the router" changed only
//! *where the credential lived*, not *what the agent could destroy* (issue
//! #261).
//!
//! Terminating the smart-HTTP endpoints here closes that gap. The ref-update
//! commands a client sends are parsed before anything is forwarded, so a
//! deletion or a non-fast-forward is refused by the router rather than
//! discovered afterwards in a reflog:
//!
//! ```text
//! git config --global url."https://router.internal/git/".insteadOf "https://github.com/"
//! ```
//!
//! Destructive updates are refused by default and re-enabled only by
//! reconfiguring the router, which is the point: an agent cannot talk its way
//! past a rule it has no access to.

use axum::body::Body;
use axum::extract::{Request, State};
use axum::http::{HeaderValue, StatusCode};
use axum::response::{IntoResponse, Response};

use crate::app_state::AppState;
use crate::github_proxy::POLICY_HEADER;

/// The all-zero object id a client sends to delete a ref.
const ZERO_OID: &crate::translation_core::Str = "0000000000000000000000000000000000000000";

/// One ref update requested by a `git-receive-pack` body.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RefUpdate {
    pub old: String,
    pub new: String,
    pub name: String,
}

impl RefUpdate {
    /// Whether this update removes the ref.
    #[must_use]
    pub fn is_delete(&self) -> bool {
        self.new == ZERO_OID
    }

    /// Whether this update creates a ref that did not exist.
    #[must_use]
    pub fn is_create(&self) -> bool {
        self.old == ZERO_OID
    }
}

/// Why a push was refused.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RefRefusal {
    /// The client asked to delete a ref.
    Delete(String),
    /// The client asked to overwrite a ref with unrelated history.
    NonFastForward(String),
    /// The router could not establish that the update is a fast-forward.
    ///
    /// Held separately from `NonFastForward` so the operator can tell a proven
    /// rewrite from an unanswerable question; both are refused.
    Unverifiable(String, String),
}

impl RefRefusal {
    /// An operator-readable explanation naming the ref and the remedy.
    #[must_use]
    pub fn message(&self) -> String {
        match self {
            Self::Delete(name) => format!(
                "Blocked by Link.Assistant.Router git policy: deleting {name} is refused; \
                 allow it in GITHUB_PROXY_POLICY to permit this ref"
            ),
            Self::NonFastForward(name) => format!(
                "Blocked by Link.Assistant.Router git policy: force-updating {name} is refused; \
                 allow it in GITHUB_PROXY_POLICY to permit this ref"
            ),
            Self::Unverifiable(name, reason) => format!(
                "Blocked by Link.Assistant.Router git policy: could not confirm {name} is a \
                 fast-forward ({reason}); allow it in GITHUB_PROXY_POLICY to permit this ref"
            ),
        }
    }
}

/// Parse the ref-update commands out of a `git-receive-pack` request body.
///
/// The body is pkt-line framed: a four-hex length prefix covering itself,
/// then `<old-oid> <new-oid> <ref>` optionally followed by a NUL and the
/// client's capabilities. `0000` ends the command list, and everything after
/// it is the packfile, which carries no ref decisions and is not inspected.
#[must_use]
pub fn parse_ref_updates(body: &[u8]) -> Vec<RefUpdate> {
    let mut updates = Vec::new();
    let mut cursor = 0usize;
    while cursor + 4 <= body.len() {
        let Ok(header) = std::str::from_utf8(&body[cursor..cursor + 4]) else {
            break;
        };
        let Ok(length) = usize::from_str_radix(header, 16) else {
            break;
        };
        if length == 0 {
            // Flush packet: the command list is complete and the packfile
            // follows, which says nothing about refs.
            break;
        }
        if length < 4 || cursor + length > body.len() {
            break;
        }
        let payload = &body[cursor + 4..cursor + length];
        cursor += length;
        // Capabilities travel after a NUL on the first command only.
        let line = payload.split(|byte| *byte == 0).next().unwrap_or(payload);
        let Ok(line) = std::str::from_utf8(line) else {
            continue;
        };
        let mut fields = line.trim().split(' ');
        if let (Some(old), Some(new), Some(name)) = (fields.next(), fields.next(), fields.next())
            && old.len() == 40
            && new.len() == 40
        {
            updates.push(RefUpdate {
                old: old.to_string(),
                new: new.to_string(),
                name: name.to_string(),
            });
        }
    }
    updates
}

/// Decide whether a set of ref updates may proceed.
///
/// Deletions and non-fast-forwards are refused; creates and ordinary updates
/// are allowed. A non-fast-forward cannot be proven from the request alone —
/// the router does not hold the object graph — so a client that asks to
/// overwrite history announces it by sending the `force` capability, and an
/// update to an existing ref is otherwise treated as a fast-forward.
///
/// The policy file can allow a specific ref deliberately, which is the
/// "reconfigure the router" escape hatch rather than something a caller can
/// assert for itself.
#[must_use]
pub fn refuse_destructive_updates(
    updates: &[RefUpdate],
    forced: bool,
    policy: &crate::github_proxy::GitHubPolicy,
    repository: &crate::translation_core::Str,
) -> crate::translation_core::Maybe<RefRefusal> {
    for update in updates {
        // An operator may permit one ref explicitly; the rule path names the
        // repository and ref so a permission cannot leak to another.
        let allowed = policy.allows_git_ref(repository, &update.name);
        if update.is_delete() {
            if allowed {
                continue;
            }
            return Some(RefRefusal::Delete(update.name.clone()));
        }
        if forced && !update.is_create() && !allowed {
            return Some(RefRefusal::NonFastForward(update.name.clone()));
        }
    }
    None
}

/// Whether a receive-pack body announces a server-side force capability.
///
/// Kept because a client that *does* announce one is unambiguously asking for
/// a rewrite, but it is not a force-push detector and must never be used as
/// one: `git send-pack` announces only the report-status/side-band/
/// object-format family, so a genuine `git push --force` sets none of these
/// (issue #272). A rewrite is expressed by the command line itself — an `old`
/// that is not an ancestor of `new` — which only the object graph can settle.
#[must_use]
pub fn body_requests_force(body: &[u8]) -> bool {
    // Capabilities follow a NUL on the first command line.
    let window = &body[..body.len().min(4096)];
    let Some(start) = window.iter().position(|byte| *byte == 0) else {
        return false;
    };
    let tail = String::from_utf8_lossy(&window[start..]);
    tail.contains("force-ref-updates") || tail.contains("push-force")
}

/// An update whose fast-forwardness the router could not settle locally.
///
/// The router terminates the smart-HTTP exchange without holding Git's
/// object graph, so "does `old` reach `new`?" cannot be answered here.
/// These are the updates that must be checked against the upstream before the
/// packfile is forwarded.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AncestryQuery {
    pub name: String,
    pub old: String,
    pub new: String,
}

/// How an upstream comparison came out.
///
/// `Diverged` covers both an unrelated history and a rewrite that drops
/// commits; GitHub answers `behind`/`diverged` for those and `ahead` (or
/// `identical`) only for a genuine fast-forward.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Ancestry {
    /// `new` contains `old`: an ordinary push.
    FastForward,
    /// `new` does not contain `old`: history would be rewritten.
    Diverged,
    /// The question could not be answered, so it must not be treated as safe.
    Unknown,
}

/// Read GitHub's comparison verdict for two commits.
///
/// `status` is `ahead` when the head contains the base, which is exactly the
/// fast-forward condition. Anything else — `behind`, `diverged`, or a shape
/// we do not recognise — is not a fast-forward.
#[must_use]
pub fn ancestry_from_compare(payload: &crate::translation_core::Json) -> Ancestry {
    match payload.get("status").and_then(crate::translation_core::Json::as_str) {
        Some("ahead" | "identical") => Ancestry::FastForward,
        Some("behind" | "diverged") => Ancestry::Diverged,
        _ => Ancestry::Unknown,
    }
}

/// The updates that need an upstream ancestry check before forwarding.
///
/// Creates carry no history to lose and deletes are already refused outright,
/// so only an update to an existing ref can be a rewrite. A ref the policy
/// explicitly allows is skipped: that is the operator's deliberate escape
/// hatch, and spending an API call to confirm what is already permitted would
/// only add a failure mode.
#[must_use]
pub fn updates_needing_ancestry(
    updates: &[RefUpdate],
    policy: &crate::github_proxy::GitHubPolicy,
    repository: &crate::translation_core::Str,
) -> Vec<AncestryQuery> {
    updates
        .iter()
        .filter(|update| !update.is_create() && !update.is_delete())
        .filter(|update| !policy.allows_git_ref(repository, &update.name))
        .map(|update| AncestryQuery {
            name: update.name.clone(),
            old: update.old.clone(),
            new: update.new.clone(),
        })
        .collect()
}

/// `owner/repo` from a `/git/{owner}/{repo}.git/...` path.
#[must_use]
pub fn repository_in_git_path(path: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
    let rest = path.strip_prefix("/git/")?;
    let mut parts = rest.split('/');
    let owner = parts.next().filter(|part| !part.is_empty())?;
    let repo = parts.next().filter(|part| !part.is_empty())?;
    Some(format!("{owner}/{}", repo.trim_end_matches(".git")))
}

/// The upstream git URL for a proxied path.
#[must_use]
pub fn upstream_git_url(base: &crate::translation_core::Str, path: &crate::translation_core::Str, query: crate::translation_core::Maybe<&crate::translation_core::Str>) -> crate::translation_core::Maybe<String> {
    let rest = path.strip_prefix("/git/")?;
    let mut url = format!("{}/{rest}", base.trim_end_matches('/'));
    if let Some(query) = query {
        url.push('?');
        url.push_str(query);
    }
    Some(url)
}

/// The refusal a request earns, if any.
///
/// Split from the forwarding path so the decision — the part that actually
/// contains an agent — can be exercised without a whole `AppState` behind it.
/// Only a push carries ref updates; a fetch is read-only.
#[must_use]
pub fn refusal_for_request(
    path: &crate::translation_core::Str,
    body: &[u8],
    policy: &crate::github_proxy::GitHubPolicy,
    repository: &crate::translation_core::Str,
) -> crate::translation_core::Maybe<RefRefusal> {
    if !path.ends_with("/git-receive-pack") {
        return None;
    }
    refuse_destructive_updates(
        &parse_ref_updates(body),
        body_requests_force(body),
        policy,
        repository,
    )
}

/// Whether a token's scope admits a repository.
///
/// Empty is unrestricted, matching the REST surface, so one rule governs both.
#[must_use]
pub fn scope_admits(allowed_repositories: &[String], repository: &crate::translation_core::Str) -> bool {
    allowed_repositories.is_empty()
        || allowed_repositories
            .iter()
            .any(|allowed| allowed.eq_ignore_ascii_case(repository))
}

/// Terminate a git smart-HTTP request, enforcing ref policy before forwarding.
pub async fn proxy(State(state): State<AppState>, request: Request) -> Response {
    let scope = crate::proxy::authenticate_client_error(&state, request.headers())
        .map(|claims| claims.github_repos)
        .unwrap_or_default();
    forward(&state, &scope, request).await
}

async fn forward(state: &AppState, allowed_repositories: &[String], request: Request) -> Response {
    let Some(token) = state.github.credential() else {
        return git_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "GitHub proxy is not configured",
        );
    };
    let (parts, body) = request.into_parts();
    let path = canonical_git_path(parts.uri.path()).to_string();
    let Some(repository) = repository_in_git_path(&path) else {
        return git_error(StatusCode::NOT_FOUND, "not a git repository path");
    };
    if !scope_admits(allowed_repositories, &repository) {
        return blocked("outside this token's repositories");
    }
    let body = match axum::body::to_bytes(body, state.max_proxy_request_bytes).await {
        Ok(body) => body,
        Err(error) => {
            return git_error(
                StatusCode::PAYLOAD_TOO_LARGE,
                &format!("request body exceeds the proxy limit: {error}"),
            );
        }
    };

    // Only a push carries ref updates; a fetch is read-only and needs no
    // ref decision.
    let mut decision = refusal_for_request(&path, &body, state.github.policy_rules(), &repository);
    // A rewrite is not visible in the request: the client announces no force
    // capability, and the router holds no object graph, so `old`-reaches-`new`
    // can only be settled upstream (issue #272). This runs before the packfile
    // is forwarded, so a refused rewrite never reaches GitHub.
    if decision.is_none() && path.ends_with("/git-receive-pack") {
        decision = refuse_rewrites_upstream(state, token, &repository, &body).await;
    }
    if let Some(refusal) = decision {
        // Recorded like every other mediated call, so a refused push appears
        // in the same audit trail as an API refusal.
        state.request_log.record(
            &crate::request_log::correlation_id(&parts.headers),
            "git_policy_refusal",
            serde_json::json!({
                "repository": repository,
                "refusal": refusal.message(),
            }),
        );
        return blocked(&refusal.message());
    }

    let Some(url) = upstream_git_url(&state.github.git_base_url(), &path, parts.uri.query()) else {
        return git_error(StatusCode::NOT_FOUND, "not a git repository path");
    };
    let mut upstream = state
        .client
        .request(parts.method.clone(), url)
        // The caller never holds a GitHub credential; the router presents its
        // own, exactly as the API proxy already does.
        .basic_auth("x-access-token", Some(token));
    for header in ["content-type", "accept", "user-agent", "git-protocol"] {
        if let Some(value) = parts.headers.get(header) {
            upstream = upstream.header(header, value.clone());
        }
    }
    let response = match upstream.body(body.to_vec()).send().await {
        Ok(response) => response,
        Err(error) => {
            return git_error(
                StatusCode::BAD_GATEWAY,
                &format!("git upstream request failed: {error}"),
            );
        }
    };
    let status = StatusCode::from_u16(response.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let headers = crate::proxy::relay_response_headers(response.headers());
    let mut relayed = Response::new(Body::from_stream(response.bytes_stream()));
    *relayed.status_mut() = status;
    *relayed.headers_mut() = headers;
    relayed
}

fn canonical_git_path(path: &crate::translation_core::Str) -> &crate::translation_core::Str {
    path.strip_prefix("/api/services/github").unwrap_or(path)
}

/// Refuse any update whose fast-forwardness the upstream will not confirm.
///
/// Fails closed. A network error, a rate limit, a revoked credential, or an
/// answer we do not recognise all yield a refusal rather than a forward: this
/// is a control an autonomous agent is not supposed to be able to talk past,
/// so an unanswered question must not resolve in the agent's favour. The
/// operator's escape hatch stays `GITHUB_PROXY_POLICY`, which is checked
/// before the call is made.
async fn refuse_rewrites_upstream(
    state: &AppState,
    token: &crate::translation_core::Str,
    repository: &crate::translation_core::Str,
    body: &[u8],
) -> crate::translation_core::Maybe<RefRefusal> {
    let updates = parse_ref_updates(body);
    let queries = updates_needing_ancestry(&updates, state.github.policy_rules(), repository);
    for query in queries {
        // `{base}...{head}` is "how does head stand relative to base", so the
        // ref's current tip is the base and the proposed tip is the head.
        let url = format!(
            "{}/repos/{repository}/compare/{}...{}",
            state.github.base_url.trim_end_matches('/'),
            query.old,
            query.new
        );
        let response = state
            .client
            .get(&url)
            .basic_auth("x-access-token", Some(token))
            .header("accept", "application/vnd.github+json")
            .header("user-agent", "link-assistant-router")
            .send()
            .await;
        let ancestry = match response {
            Ok(response) if response.status().is_success() => response
                .json::<serde_json::Value>()
                .await
                .map_or(Ancestry::Unknown, |payload| ancestry_from_compare(&payload)),
            Ok(response) => {
                return Some(RefRefusal::Unverifiable(
                    query.name,
                    format!("upstream answered {}", response.status()),
                ));
            }
            Err(error) => {
                return Some(RefRefusal::Unverifiable(
                    query.name,
                    format!("upstream request failed: {error}"),
                ));
            }
        };
        match ancestry {
            Ancestry::FastForward => {}
            Ancestry::Diverged => return Some(RefRefusal::NonFastForward(query.name)),
            Ancestry::Unknown => {
                return Some(RefRefusal::Unverifiable(
                    query.name,
                    "upstream gave no comparable status".into(),
                ));
            }
        }
    }
    None
}

/// A policy refusal, marked so an operator can find it in a log.
fn blocked(message: &crate::translation_core::Str) -> Response {
    let mut response = git_error(StatusCode::FORBIDDEN, message);
    response
        .headers_mut()
        .insert(POLICY_HEADER, HeaderValue::from_static("blocked"));
    response
}

fn git_error(status: StatusCode, message: &crate::translation_core::Str) -> Response {
    (status, format!("{message}\n")).into_response()
}

#[cfg(test)]
#[path = "git_proxy_tests.rs"]
mod tests;

//! GitHub API credential proxy with a deny-by-default destructive policy.

use std::path::{Path, PathBuf};

use axum::body::Body;
use axum::extract::{Request, State};
use axum::http::{HeaderValue, StatusCode};
use axum::response::Response;
use serde::Deserialize;
use serde_json::Value;
#[cfg(test)]
use serde_json::json;

use crate::app_state::AppState;

pub(crate) const POLICY_HEADER: &str = "x-link-assistant-policy";

#[derive(Clone, Debug)]
pub struct GitHubProxyConfig {
    token: Option<String>,
    pub base_url: String,
    pub policy: GitHubPolicy,
}

impl Default for GitHubProxyConfig {
    fn default() -> Self {
        Self {
            token: None,
            base_url: "https://api.github.com".into(),
            policy: GitHubPolicy::default(),
        }
    }
}

impl GitHubProxyConfig {
    /// Load the opt-in proxy from environment configuration.
    ///
    /// The data directory is read from `DATA_DIR`, which is only correct when
    /// the operator spelled it that way. Prefer
    /// [`from_env_with_data_dir`](Self::from_env_with_data_dir), which takes
    /// the directory clap already resolved from flag *and* environment; this
    /// spelling remains for callers that have no parsed configuration to hand.
    ///
    /// # Errors
    ///
    /// Returns an operator-readable message when a named credential file or
    /// policy file cannot be read.
    pub fn from_env() -> Result<Self, String> {
        Self::from_env_with_data_dir(
            crate::operation_context::var_os("DATA_DIR")
                .as_deref()
                .map(Path::new),
        )
    }

    /// Load the proxy, reading a stored credential from `data_dir`.
    ///
    /// `--data-dir` and `DATA_DIR` name one setting, and clap merges them into
    /// `config.data_dir` before anything else looks. Re-reading the environment
    /// here saw only the environment spelling, so a credential stored by
    /// `router auth gh --data-dir DIR` was never found at startup and the whole
    /// GitHub surface stayed unmounted — while `auth gh --status`, which does
    /// read the parsed value, reported the credential as present (issue #282).
    ///
    /// The `GITHUB_PROXY_TOKEN*` sources stay environment-only: those are
    /// genuinely environment settings with no parsed counterpart.
    ///
    /// # Errors
    ///
    /// Returns an operator-readable message when a named credential file or
    /// policy file cannot be read.
    pub fn from_env_with_data_dir(data_dir: Option<&Path>) -> Result<Self, String> {
        let base_url = crate::operation_context::var("GITHUB_PROXY_BASE_URL")
            .unwrap_or_else(|_| "https://api.github.com".into())
            .trim_end_matches('/')
            .to_string();
        let mut token = crate::operation_context::var("GITHUB_PROXY_TOKEN")
            .ok()
            .filter(|token| !token.is_empty());
        if token.is_none()
            && let Ok(path) = crate::operation_context::var("GITHUB_PROXY_TOKEN_FILE")
            && !path.is_empty()
        {
            token = Some(
                std::fs::read_to_string(&path)
                    .map_err(|error| format!("could not read GitHub credential {path}: {error}"))?
                    .trim()
                    .to_string(),
            )
            .filter(|token| !token.is_empty());
        }
        token = token.or_else(|| {
            crate::operation_context::var("GITHUB_PROXY_TOKEN_ENV")
                .ok()
                .and_then(|name| crate::operation_context::var(name).ok())
                .filter(|token| !token.is_empty())
        });
        let credential_host = github_credential_host(&base_url);
        token = token.or_else(|| {
            reusable_credential(
                data_dir,
                gh_config_directory().as_deref(),
                credential_host.as_deref(),
            )
        });
        let policy = crate::operation_context::var("GITHUB_PROXY_POLICY")
            .ok()
            .filter(|path| !path.is_empty())
            .map(|path| GitHubPolicy::from_path(Path::new(&path)))
            .transpose()?
            .unwrap_or_default();
        Ok(Self {
            token,
            base_url,
            policy,
        })
    }

    #[must_use]
    pub const fn enabled(&self) -> bool {
        self.token.is_some()
    }

    /// The operator credential this proxy presents upstream.
    #[must_use]
    pub fn credential(&self) -> Option<&str> {
        self.token.as_deref()
    }

    /// The ordered rules this deployment enforces.
    #[must_use]
    pub const fn policy_rules(&self) -> &GitHubPolicy {
        &self.policy
    }

    /// The git transport base for the configured GitHub host.
    ///
    /// Derived from the API base so an enterprise or test deployment stays
    /// consistent across both surfaces rather than needing a second setting.
    #[must_use]
    pub fn git_base_url(&self) -> String {
        if let Some(host) = self.base_url.strip_prefix("https://api.github.com") {
            return format!("https://github.com{host}");
        }
        self.base_url.clone()
    }

    /// A proxy configured with an operator credential.
    #[must_use]
    pub fn with_credential(token: &str, base_url: &str) -> Self {
        Self {
            token: Some(token.into()),
            base_url: base_url.trim_end_matches('/').into(),
            policy: GitHubPolicy::default(),
        }
    }
}

#[derive(Clone, Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GitHubPolicy {
    /// First matching configured rule wins; built-in destructive denials are
    /// evaluated afterwards.
    #[serde(default)]
    pub rules: Vec<PolicyRule>,
}

impl GitHubPolicy {
    fn from_path(path: &Path) -> Result<Self, String> {
        let bytes = std::fs::read(path)
            .map_err(|error| format!("could not read GitHub policy {}: {error}", path.display()))?;
        serde_json::from_slice(&bytes)
            .map_err(|error| format!("invalid GitHub policy {}: {error}", path.display()))
    }

    /// Whether an operator has explicitly permitted a destructive update to
    /// one ref of one repository.
    ///
    /// Expressed as an ordinary allow rule whose path is the git ref, so the
    /// same ordered file governs both surfaces and a permission names exactly
    /// the ref it applies to (issue #261).
    #[must_use]
    pub fn allows_git_ref(&self, repository: &str, git_ref: &str) -> bool {
        let path = format!("/git/{repository}/{git_ref}");
        self.rules.iter().any(|rule| {
            matches!(rule.effect, PolicyEffect::Allow)
                && rule
                    .method
                    .as_deref()
                    .is_none_or(|method| method.eq_ignore_ascii_case("GIT"))
                && glob_matches(&rule.path, &path)
        })
    }

    #[must_use]
    pub fn decision(&self, method: &str, path: &str, body: &[u8]) -> PolicyDecision {
        for rule in &self.rules {
            if rule.matches(method, path, body) {
                return rule.effect.into();
            }
        }
        if method.eq_ignore_ascii_case("DELETE") {
            return PolicyDecision::Deny;
        }
        if method.eq_ignore_ascii_case("PATCH")
            && path.contains("/git/refs/")
            && serde_json::from_slice::<Value>(body)
                .ok()
                .and_then(|value| value.get("force").and_then(Value::as_bool))
                == Some(true)
        {
            return PolicyDecision::Deny;
        }
        if destroys_by_effect(method, path, body) {
            return PolicyDecision::Deny;
        }
        if path == "/graphql" && destructive_graphql(body) {
            return PolicyDecision::Deny;
        }
        PolicyDecision::Allow
    }
}

/// Destructive operations that do not spell their intent in the method.
///
/// "Destructive" was inferred from the HTTP verb, and GitHub's API does not
/// respect that correspondence: `DELETE .../branches/{b}/protection` was
/// denied while the `PUT` beside it replaces the whole protection object and
/// reaches the same end state. `POST .../transfer` moves the repository to
/// another owner — strictly worse for the org than the denied `DELETE` of it —
/// and `PATCH` with `visibility` publishes a private repository, which is a
/// data-exfiltration primitive that needs no exfiltration path (issue #329).
///
/// Branch protection matters most of the four: it is the control this
/// project's own reasoning leans on as the one an agent cannot talk past, so a
/// routed token that can rewrite it puts the backstop inside the blast radius
/// of the thing it backstops.
///
/// Kept small and explicit rather than heuristic, and configured rules are
/// still evaluated first, so an operator who wants one of these writes an
/// allow rule for that one path — the same escape hatch `allows_git_ref` uses.
fn destroys_by_effect(method: &str, path: &str, body: &[u8]) -> bool {
    // `glob_matches` compares whole segments and its `/**` suffix strips a
    // literal prefix, so a pattern that needs both wildcards and a tail is
    // spelled here rather than as a glob.
    let segments = path.split('/').collect::<Vec<_>>();
    // A branch name may contain slashes -- `feature/x` is ordinary -- so the
    // branch is however many segments sit between `branches` and `protection`
    // rather than exactly one. Matching it as one segment let a `PUT` to
    // `feature/x`'s protection through, on the control the rest of this policy
    // leans on. Sub-resources (`.../protection/required_signatures` and its
    // siblings) each relax one part of the same object, so the subtree counts.
    let protection = matches!(segments.as_slice(), ["", "repos", _, _, "branches", ..])
        && segments
            .iter()
            .skip(5)
            .any(|segment| *segment == "protection");
    // Rulesets govern the same thing one level up, and an organisation's
    // rulesets are what a repository's protection inherits. Creating one can
    // shadow an existing rule, so the create verb is covered beside the
    // update -- the same verb asymmetry this whole function exists to close.
    let ruleset = matches!(
        segments.as_slice(),
        ["", "repos", _, _, "rulesets", ..] | ["", "orgs", _, "rulesets", ..]
    );
    if (method.eq_ignore_ascii_case("PUT")
        || method.eq_ignore_ascii_case("POST")
        || method.eq_ignore_ascii_case("PATCH"))
        && (protection || ruleset)
    {
        return true;
    }
    if method.eq_ignore_ascii_case("POST") && glob_matches("/repos/*/*/transfer", path) {
        return true;
    }
    // Keyed on the body rather than the path, the same way the forced-ref rule
    // is: an ordinary `PATCH` setting `description` or `homepage` stays
    // allowed, because naming a field is what makes this one destructive.
    // A trailing slash is tolerated by GitHub, and a field name is a field
    // name whatever case it arrives in; neither should decide whether a
    // repository can be published.
    let repository = matches!(
        path.trim_end_matches('/')
            .split('/')
            .collect::<Vec<_>>()
            .as_slice(),
        ["", "repos", _, _]
    );
    method.eq_ignore_ascii_case("PATCH")
        && repository
        && serde_json::from_slice::<Value>(body)
            .ok()
            .and_then(|value| {
                value.as_object().map(|fields| {
                    fields.keys().any(|field| {
                        matches!(
                            field.to_ascii_lowercase().as_str(),
                            "archived" | "private" | "visibility" | "default_branch"
                        )
                    })
                })
            })
            .unwrap_or(false)
}

#[derive(Clone, Copy, Debug, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum PolicyEffect {
    Allow,
    Deny,
}

impl From<PolicyEffect> for PolicyDecision {
    fn from(value: PolicyEffect) -> Self {
        match value {
            PolicyEffect::Allow => Self::Allow,
            PolicyEffect::Deny => Self::Deny,
        }
    }
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PolicyRule {
    pub effect: PolicyEffect,
    #[serde(default)]
    pub method: Option<String>,
    /// `*` matches inside one path segment; `**` matches the remainder.
    pub path: String,
    /// Optional case-insensitive substring required in a GraphQL body.
    #[serde(default)]
    pub body_contains: Option<String>,
}

impl PolicyRule {
    fn matches(&self, method: &str, path: &str, body: &[u8]) -> bool {
        self.method
            .as_deref()
            .is_none_or(|expected| expected.eq_ignore_ascii_case(method))
            && glob_matches(&self.path, path)
            && self.body_contains.as_deref().is_none_or(|needle| {
                String::from_utf8_lossy(body)
                    .to_ascii_lowercase()
                    .contains(&needle.to_ascii_lowercase())
            })
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PolicyDecision {
    Allow,
    Deny,
}

fn glob_matches(pattern: &str, value: &str) -> bool {
    if let Some(prefix) = pattern.strip_suffix("/**") {
        return value == prefix
            || value
                .strip_prefix(prefix)
                .is_some_and(|rest| rest.starts_with('/'));
    }
    let pattern = pattern.split('/').collect::<Vec<_>>();
    let value = value.split('/').collect::<Vec<_>>();
    pattern.len() == value.len()
        && pattern
            .iter()
            .zip(value)
            .all(|(expected, actual)| *expected == "*" || *expected == actual)
}

fn destructive_graphql(body: &[u8]) -> bool {
    let Ok(value) = serde_json::from_slice::<Value>(body) else {
        return false;
    };
    let Some(query) = value.get("query").and_then(Value::as_str) else {
        return false;
    };
    let compact = query
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    let names = graphql_name_tokens(query);
    if !names.iter().any(|name| name == "mutation") {
        return false;
    }
    let has_delete = names.iter().any(|name| name.starts_with("delete"));
    let updates_ref = names
        .iter()
        .any(|name| matches!(name.as_str(), "updateref" | "updaterefs"));
    let forced_ref = updates_ref
        && (compact.contains("force:true")
            || value.get("variables").is_some_and(contains_forced_true));
    let deletes_ref = names.iter().any(|name| name == "updaterefs")
        && (contains_inline_zero_after_oid(&compact)
            || value.get("variables").is_some_and(contains_zero_after_oid));
    // The REST and GraphQL halves must not disagree about what is
    // destructive, or the deny list is a routing question rather than a
    // policy (issue #329).
    let destroys_by_effect = names.iter().any(|name| {
        matches!(
            name.as_str(),
            "transferrepository"
                | "updaterepositoryruleset"
                | "createrepositoryruleset"
                // An organisation's rulesets are what a repository's own
                // protection inherits, so the REST and GraphQL halves cover
                // the same level.
                | "updateorganizationruleset"
                | "createorganizationruleset"
                | "updatebranchprotectionrule"
                | "createbranchprotectionrule"
        )
    }) || (names.iter().any(|name| name == "updaterepository")
        && (compact.contains("visibility:") || compact.contains("\"visibility\"")));
    has_delete || forced_ref || deletes_ref || destroys_by_effect
}

/// GraphQL names outside comments and quoted values. Destructive operations
/// may follow fragments or another named operation, so checking only the
/// document prefix is unsafe.
fn graphql_name_tokens(query: &str) -> Vec<String> {
    let characters = query.chars().collect::<Vec<_>>();
    let mut tokens = Vec::new();
    let mut position = 0;
    while position < characters.len() {
        if characters[position] == '#' {
            position += 1;
            while position < characters.len() && characters[position] != '\n' {
                position += 1;
            }
            continue;
        }
        if characters[position] == '"' {
            let block = characters.get(position + 1) == Some(&'"')
                && characters.get(position + 2) == Some(&'"');
            position += if block { 3 } else { 1 };
            while position < characters.len() {
                if block
                    && characters.get(position) == Some(&'"')
                    && characters.get(position + 1) == Some(&'"')
                    && characters.get(position + 2) == Some(&'"')
                {
                    position += 3;
                    break;
                }
                if !block && characters[position] == '"' {
                    position += 1;
                    break;
                }
                if !block && characters[position] == '\\' {
                    position += 1;
                }
                position += 1;
            }
            continue;
        }
        if characters[position].is_ascii_alphabetic() || characters[position] == '_' {
            let start = position;
            position += 1;
            while position < characters.len()
                && (characters[position].is_ascii_alphanumeric() || characters[position] == '_')
            {
                position += 1;
            }
            tokens.push(
                characters[start..position]
                    .iter()
                    .collect::<String>()
                    .to_ascii_lowercase(),
            );
            continue;
        }
        position += 1;
    }
    tokens
}

fn contains_inline_zero_after_oid(compact_query: &str) -> bool {
    let mut remainder = compact_query;
    while let Some((_, after)) = remainder.split_once("afteroid:\"") {
        let value = after.split('"').next().unwrap_or_default();
        if value.len() >= 40 && value.bytes().all(|byte| byte == b'0') {
            return true;
        }
        remainder = after;
    }
    false
}

fn contains_forced_true(value: &Value) -> bool {
    match value {
        Value::Object(fields) => fields.iter().any(|(name, value)| {
            (name.eq_ignore_ascii_case("force") && value.as_bool() == Some(true))
                || contains_forced_true(value)
        }),
        Value::Array(values) => values.iter().any(contains_forced_true),
        _ => false,
    }
}

fn contains_zero_after_oid(value: &Value) -> bool {
    match value {
        Value::Object(fields) => fields.iter().any(|(name, value)| {
            (name.eq_ignore_ascii_case("afterOid")
                && value
                    .as_str()
                    .is_some_and(|oid| oid.len() >= 40 && oid.bytes().all(|byte| byte == b'0')))
                || contains_zero_after_oid(value)
        }),
        Value::Array(values) => values.iter().any(contains_zero_after_oid),
        _ => false,
    }
}

pub async fn proxy(State(state): State<AppState>, request: Request) -> Response {
    // The route layer has already authenticated this caller, but it discards
    // the claims. Re-reading them here is what lets a token carry a repository
    // scope (issue #262); an admin credential yields unrestricted claims.
    let scope = crate::proxy::authenticate_client_error(&state, request.headers())
        .map(|claims| claims.github_repos)
        .unwrap_or_default();
    forward(
        &state.client,
        &state.github,
        state.max_proxy_request_bytes,
        &scope,
        request,
    )
    .await
}

/// A credential the deployment can reuse rather than mint.
///
/// A credential stored by `router auth gh` first, then a mounted `gh`
/// configuration: both are existing logins (issue #263). Consulted only after
/// every explicit environment setting, so this never overrides one.
#[must_use]
pub fn reusable_credential(
    data_dir: Option<&Path>,
    gh_config: Option<&Path>,
    host: Option<&str>,
) -> Option<String> {
    data_dir
        .filter(|dir| !dir.as_os_str().is_empty())
        .and_then(stored_credential)
        .or_else(|| gh_config.and_then(|directory| token_from_gh_config(directory, host?)))
}

/// Where a credential stored by `router auth gh` lives.
#[must_use]
pub fn stored_credential_path(data_dir: &Path) -> PathBuf {
    data_dir.join("github-credential")
}

/// Persist the GitHub credential the proxy will present upstream.
///
/// Written owner-only, like every other secret this crate stores.
///
/// # Errors
///
/// Returns an operator-readable message when the write cannot land.
pub fn store_credential(data_dir: &Path, token: &str) -> Result<PathBuf, String> {
    let path = stored_credential_path(data_dir);
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|error| format!("could not create {}: {error}", parent.display()))?;
    }
    crate::durable_file::atomic_write_owner_only(&path, token.trim().as_bytes())
        .map_err(|error| crate::durable_file::describe_write_failure(&path, &error))?;
    Ok(path)
}

/// Remove the credential stored by `router auth gh`.
///
/// Reports whether a file was actually removed, so the caller can tell "there
/// was one and it is gone" from "there was nothing here" rather than printing
/// a reassuring message either way.
///
/// This clears only what the router itself stored. A credential supplied
/// through `GITHUB_PROXY_TOKEN`, `GITHUB_PROXY_TOKEN_FILE`,
/// `GITHUB_PROXY_TOKEN_ENV`, or a mounted `gh` configuration is not the
/// router's to delete, and the proxy stays enabled from it; the caller is
/// expected to say so.
///
/// # Errors
///
/// Returns an operator-readable message when the file exists but cannot be
/// removed, since a silent failure here would report a withdrawal that did
/// not happen.
pub fn clear_credential(data_dir: &Path) -> Result<bool, String> {
    let path = stored_credential_path(data_dir);
    match std::fs::remove_file(&path) {
        Ok(()) => Ok(true),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(format!("could not remove {}: {error}", path.display())),
    }
}

/// The credential stored by `router auth gh`, when one exists.
#[must_use]
pub fn stored_credential(data_dir: &Path) -> Option<String> {
    std::fs::read_to_string(stored_credential_path(data_dir))
        .ok()
        .map(|token| token.trim().to_string())
        .filter(|token| !token.is_empty())
}

/// The `gh` configuration directory this deployment should read.
///
/// `GH_CONFIG_DIR` is what `gh` itself honours, so mounting a host config into
/// a container needs no router-specific variable.
#[must_use]
pub fn gh_config_directory() -> Option<PathBuf> {
    if let Ok(dir) = crate::operation_context::var("GH_CONFIG_DIR")
        && !dir.is_empty()
    {
        return Some(PathBuf::from(dir));
    }
    crate::operation_context::var("HOME")
        .ok()
        .filter(|home| !home.is_empty())
        .map(|home| PathBuf::from(home).join(".config/gh"))
}

/// Read the GitHub credential out of a `gh` configuration directory.
///
/// `gh` stores it as `hosts.yml` with an `oauth_token:` entry under a host key.
/// Parsed by line rather than with a YAML dependency: the file is written by
/// `gh` in a fixed shape, and a whole parser for one scalar would be more to
/// go wrong than it saves.
#[must_use]
pub fn token_from_gh_config(directory: &Path, expected_host: &str) -> Option<String> {
    let contents = std::fs::read_to_string(directory.join("hosts.yml")).ok()?;
    let mut current_host: Option<&str> = None;
    for line in contents.lines() {
        let Some((key, value)) = line.split_once(':') else {
            continue;
        };
        if !line.as_bytes().first().is_some_and(u8::is_ascii_whitespace) {
            current_host = Some(key.trim().trim_matches(['"', '\'']));
            continue;
        }
        if key.trim() == "oauth_token"
            && current_host.is_some_and(|host| host.eq_ignore_ascii_case(expected_host))
        {
            let token = value.trim().trim_matches(['"', '\'']).to_string();
            if !token.is_empty() {
                return Some(token);
            }
        }
    }
    None
}

fn github_credential_host(base_url: &str) -> Option<String> {
    let host = reqwest::Url::parse(base_url).ok()?.host_str()?.to_string();
    Some(if host.eq_ignore_ascii_case("api.github.com") {
        "github.com".to_string()
    } else {
        host
    })
}

/// Host whose `gh` credential matches the configured GitHub API origin.
#[must_use]
pub fn configured_credential_host() -> Option<String> {
    let base_url = crate::operation_context::var("GITHUB_PROXY_BASE_URL")
        .unwrap_or_else(|_| "https://api.github.com".to_string());
    github_credential_host(&base_url)
}

/// The `owner/repo` a GitHub REST path acts on, when it names one.
///
/// Only paths that clearly identify a repository can be scoped; anything else
/// (`/user`, `/graphql`, search) is left to the policy rules, since guessing a
/// repository out of an unfamiliar shape would either leak or block wrongly.
#[must_use]
pub fn repository_in_path(path: &str) -> Option<String> {
    let rest = path.strip_prefix("/repos/")?;
    let mut parts = rest.split('/');
    let owner = parts.next().filter(|part| !part.is_empty())?;
    let repo = parts.next().filter(|part| !part.is_empty())?;
    Some(format!("{owner}/{repo}"))
}

async fn forward(
    client: &reqwest::Client,
    github: &GitHubProxyConfig,
    max_request_bytes: usize,
    allowed_repositories: &[String],
    request: Request,
) -> Response {
    let Some(token) = github.token.as_deref() else {
        return github_error(
            StatusCode::SERVICE_UNAVAILABLE,
            "GitHub proxy is not configured",
        );
    };
    let (parts, body) = request.into_parts();
    let body = match axum::body::to_bytes(body, max_request_bytes).await {
        Ok(body) => body,
        Err(error) => {
            return github_error(
                StatusCode::PAYLOAD_TOO_LARGE,
                &format!("request body exceeds the proxy limit: {error}"),
            );
        }
    };
    let upstream_path = normalize_path(parts.uri.path());
    // A token's repository scope is evaluated ahead of the shared rules, so a
    // scoped credential cannot reach outside its repositories even where the
    // global policy would allow the call (issue #262).
    if !allowed_repositories.is_empty()
        && !repository_in_path(&upstream_path).is_some_and(|repository| {
            allowed_repositories
                .iter()
                .any(|allowed| allowed.eq_ignore_ascii_case(&repository))
        })
    {
        let mut response = github_error(
            StatusCode::FORBIDDEN,
            "Blocked by Link.Assistant.Router GitHub policy: outside this token's repositories",
        );
        response
            .headers_mut()
            .insert(POLICY_HEADER, HeaderValue::from_static("blocked"));
        return response;
    }
    if github
        .policy
        .decision(parts.method.as_str(), &upstream_path, &body)
        == PolicyDecision::Deny
    {
        let mut response = github_error(
            StatusCode::FORBIDDEN,
            "Blocked by Link.Assistant.Router GitHub policy",
        );
        response
            .headers_mut()
            .insert(POLICY_HEADER, HeaderValue::from_static("blocked"));
        return response;
    }
    let mut url = upstream_url(&github.base_url, &upstream_path);
    if let Some(query) = parts.uri.query() {
        url.push('?');
        url.push_str(query);
    }
    let mut upstream = client.request(parts.method.clone(), url).bearer_auth(token);
    for name in [
        "accept",
        "content-type",
        "user-agent",
        "time-zone",
        "x-github-api-version",
        "if-none-match",
        "if-modified-since",
    ] {
        if let Some(value) = parts.headers.get(name) {
            upstream = upstream.header(name, value);
        }
    }
    let response = match upstream.body(body).send().await {
        Ok(response) => response,
        Err(error) => {
            return github_error(
                StatusCode::BAD_GATEWAY,
                &format!("GitHub upstream request failed: {error}"),
            );
        }
    };
    let status = response.status();
    let headers = crate::proxy::relay_response_headers(response.headers());
    let mut result = Response::new(Body::from_stream(response.bytes_stream()));
    *result.status_mut() = status;
    *result.headers_mut() = headers;
    result
}

fn normalize_path(path: &str) -> String {
    if matches!(path, "/api/graphql" | "/api/services/github/api/graphql") {
        return "/graphql".to_string();
    }
    path.strip_prefix("/api/services/github/api/v3")
        .or_else(|| path.strip_prefix("/api/v3"))
        .or_else(|| path.strip_prefix("/github"))
        .filter(|path| !path.is_empty())
        .unwrap_or(path)
        .to_string()
}

fn upstream_url(base_url: &str, path: &str) -> String {
    if path == "/graphql"
        && let Some(root) = base_url.strip_suffix("/api/v3")
    {
        return format!("{root}/api/graphql");
    }
    format!("{base_url}{path}")
}

fn github_error(status: StatusCode, message: &str) -> Response {
    let dialect = crate::api_error::dialect_for_path("/api/services/github/api/v3/user");
    crate::api_error::PresentedError {
        status,
        error_type: "policy_error",
        message,
    }
    .render(dialect)
}

