        let mut state = AppState::for_tests(directory.path());
        state.upstream_provider = crate::config::UpstreamProvider::Gonka;
        state.gonka =
            GonkaConfig::new(Some("broker-secret".into()), Some(&base_url), String::new());
        let (token, token_id) = state
            .token_manager
            .issue_with_id(&crate::token::IssueRequest {
                ttl_hours: 1,
                label: "gonka-stream",
                ..crate::token::IssueRequest::default()
            })
            .unwrap();
        let mut headers = HeaderMap::new();
        headers.insert(
            "authorization",
            HeaderValue::from_str(&format!("Bearer {token}")).unwrap(),
        );
        headers.insert("x-request-id", HeaderValue::from_static("gonka-stream"));

        let response = tokio::time::timeout(
            Duration::from_millis(500),
            forward_openai(
                &state,
                &headers,
                json!({"model":"live-model","messages":[],"stream":true}),
                "/v1/chat/completions",
                crate::metrics::Surface::OpenAIChat,
            ),
        )
        .await
        .expect("response headers must not wait for stream completion");
        assert_eq!(response.status(), StatusCode::ACCEPTED);
        assert_eq!(response.headers()["x-request-id"], "gonka-request");
        assert!(!response.headers().contains_key("x-hidden"));
        assert!(!response.headers().contains_key("x-api-key"));
        let mut body = response.into_body();
        let first = tokio::time::timeout(Duration::from_millis(500), body.frame())
            .await
            .expect("first frame must be incremental")
            .unwrap()
            .unwrap()
            .into_data()
            .unwrap();
        assert!(String::from_utf8_lossy(&first).contains("total_tokens"));
        drop(body);

        assert_eq!(
            state
                .token_manager
                .store()
                .get(&token_id)
                .unwrap()
                .unwrap()
                .used_tokens,
            3,
            "disconnect still settles usage observed before it"
        );
        assert!(state.metrics.bytes_in.load(Ordering::Relaxed) > 0);
        let written = std::fs::read_to_string(
            directory
                .path()
                .join("requests/unauthenticated/requests.lino"),
        )
        .unwrap();
        let settled = written
            .lines()
            .filter_map(crate::lino_json::decode_line)
            .find(|record| record["phase"] == "stream_end")
            .expect("dropping the client body must settle the stream");
        assert_eq!(settled["outcome"], "ended_without_terminator");
        server.abort();
    }

    #[tokio::test]
    async fn upstream_transport_error_is_relayed_and_settled() {
        use futures_util::StreamExt as _;
        use tokio::io::{AsyncReadExt as _, AsyncWriteExt as _};

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let url = format!("http://{}/", listener.local_addr().unwrap());
        let upstream = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.unwrap();
            let mut request = [0_u8; 1024];
            let _ = socket.read(&mut request).await.unwrap();
            let frame = b"data: {\"choices\":[]}\n\n";
            socket
                .write_all(
                    format!(
                        "HTTP/1.1 200 OK\r\ncontent-type: text/event-stream\r\ntransfer-encoding: chunked\r\n\r\n{:X}\r\n",
                        frame.len()
                    )
                    .as_bytes(),
                )
                .await
                .unwrap();
            socket.write_all(frame).await.unwrap();
            socket.write_all(b"\r\n").await.unwrap();
            tokio::time::sleep(Duration::from_millis(25)).await;
            socket.write_all(b"not-a-chunk-size\r\n").await.unwrap();
        });
        let response = reqwest::get(url).await.unwrap();
        let directory = tempfile::tempdir().unwrap();
        let state = AppState::for_tests(directory.path());
        let mut stream = Box::pin(GonkaRelayStream::new(
            response,
            &state,
            "gonka-error".into(),
            None,
            0,
        ));
        assert!(stream.next().await.unwrap().is_ok());
        assert!(stream.next().await.unwrap().is_err());
        drop(stream);
        upstream.await.unwrap();

        let written = std::fs::read_to_string(
            directory
                .path()
                .join("requests/unauthenticated/requests.lino"),
        )
        .unwrap();
        let settled = written
            .lines()
            .filter_map(crate::lino_json::decode_line)
            .find(|record| record["phase"] == "stream_end")
            .expect("transport failure must settle the stream");
        assert_eq!(settled["outcome"], "upstream_error");
        assert!(!settled["complete"].as_bool().unwrap());
    }
}

//! Scoped, private diagnostics for ordinary Claude launches (issue #717).

use std::fs::{self, File, OpenOptions};
use std::io::{self, Seek as _, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::sync::{Arc, Mutex};

use serde_json::json;
use tracing::instrument::WithSubscriber as _;

mod redaction;

const MAX_BYTES: u64 = 1024 * 1024;
const ARCHIVES: usize = 5;
const MAX_MESSAGE_BYTES: usize = 16 * 1024;

tokio::task_local! {
    static ACTIVE: Arc<DiagnosticLog>;
}

struct DiagnosticLog {
    directory: PathBuf,
    launch_id: String,
    terminal: bool,
    secrets: Mutex<Vec<String>>,
    failure: Mutex<Option<String>>,
}

impl DiagnosticLog {
    fn open(data_dir: &Path, terminal: bool) -> io::Result<Arc<Self>> {
        let directory = data_dir.join("launcher");
        reject_symlink(&directory)?;
        let mut builder = fs::DirBuilder::new();
        builder.recursive(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::{DirBuilderExt as _, PermissionsExt as _};
            builder.mode(0o700);
            builder.create(&directory)?;
            fs::set_permissions(&directory, fs::Permissions::from_mode(0o700))?;
        }
        #[cfg(not(unix))]
        builder.create(&directory)?;
        // Fail before discovery if either the lock or destination is unavailable.
        let _lock = private_file(&directory.join("launcher.lock"))?;
        let _file = private_file(&directory.join("launcher.log"))?;
        let secrets = crate::operation_context::current()
            .map_or_else(
                || {
                    std::env::vars_os()
                        .map(|(name, value)| {
                            (
                                name.to_string_lossy().into_owned(),
                                value.to_string_lossy().into_owned(),
                            )
                        })
                        .collect::<Vec<_>>()
                },
                |context| {
                    context
                        .environment
                        .iter()
                        .map(|(name, value)| {
                            (
                                name.to_string_lossy().into_owned(),
                                value.to_string_lossy().into_owned(),
                            )
                        })
                        .collect()
                },
            )
            .into_iter()
            .filter_map(|(name, value)| redaction::secret_name(&name).then_some(value))
            .filter(|value| !value.is_empty())
            .collect();
        Ok(Arc::new(Self {
            directory,
            launch_id: uuid::Uuid::new_v4().to_string(),
            terminal,
            secrets: Mutex::new(secrets),
            failure: Mutex::new(None),
        }))
    }

    fn sanitize(&self, text: &str) -> String {
        redaction::sanitize(text, &self.secrets.lock().expect("launcher secrets lock"))
    }

    fn record(&self, event: &str, message: &str) {
        let mut message = self.sanitize(message);
        if message.len() > MAX_MESSAGE_BYTES {
            let mut end = MAX_MESSAGE_BYTES;
            while !message.is_char_boundary(end) {
                end -= 1;
            }
            message.truncate(end);
            message.push_str(" [truncated]");
        }
        let record = json!({
            "timestamp": chrono::Utc::now().to_rfc3339(),
            "launch_id": self.launch_id,
            "event": event,
            "message": message.trim_end(),
        });
        if let Err(error) = self.append(format!("{record}\n").as_bytes()) {
            *self.failure.lock().expect("launcher failure lock") = Some(error.to_string());
        }
        if let Err(error) = crate::logging::event_file(format_args!(
            "launch_id={} {event} {}",
            self.launch_id,
            message.trim_end()
        )) {
            *self.failure.lock().expect("launcher failure lock") = Some(error.to_string());
        }
    }

    fn append(&self, bytes: &[u8]) -> io::Result<()> {
        let lock = private_file(&self.directory.join("launcher.lock"))?;
        fs2::FileExt::lock_exclusive(&lock)?;
        // Open under the lock each time: another process may have rotated the file.
        let path = self.directory.join("launcher.log");
        let mut file = private_file(&path)?;
        if file.metadata()?.len() + bytes.len() as u64 > MAX_BYTES {
            drop(file);
            for number in (1..=ARCHIVES).rev() {
                let destination = self.directory.join(format!("launcher.log.{number}"));
                reject_symlink(&destination)?;
                if destination.exists() {
                    fs::remove_file(&destination)?;
                }
                let source = if number == 1 {
                    path.clone()
                } else {
                    self.directory.join(format!("launcher.log.{}", number - 1))
                };
                reject_symlink(&source)?;
                if source.exists() {
                    fs::rename(source, destination)?;
                }
            }
            file = private_file(&path)?;
        }
        // Windows append-only handles lack the access required by file locks
        // and sync_data. Seek while holding the lock on a read/write handle.
        file.seek(SeekFrom::End(0))?;
        file.write_all(bytes)?;
        file.sync_data()
        // Dropping the lock releases it on success and on every error path.
    }

    fn check(&self) -> Result<(), String> {
        self.failure
            .lock()
            .expect("launcher failure lock")
            .as_ref()
            .map_or(Ok(()), |error| {
                Err(format!("could not persist launcher diagnostics: {error}"))
            })
    }
}

fn reject_symlink(path: &Path) -> io::Result<()> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if metadata.file_type().is_symlink() => Err(io::Error::other(
            "launcher log destination must not be a symlink",
        )),
        Ok(_) => Ok(()),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error),
    }
}

fn private_file(path: &Path) -> io::Result<File> {
    reject_symlink(path)?;
    let mut options = OpenOptions::new();
    options.create(true).read(true).write(true).truncate(false);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let file = options.open(path)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        file.set_permissions(fs::Permissions::from_mode(0o600))?;
    }
    Ok(file)
}

/// Open Claude diagnostics before the process-wide operational log or preflight.
pub async fn run_process(
    args: &crate::cli::WithArgs,
    data_dir: &Path,
    verbose: bool,
    work: impl std::future::Future<Output = ExitCode>,
) -> ExitCode {
    if args.client == crate::clients::ClientKind::ClaudeCode && !args.global && !args.undo {
        run(args, Some(data_dir), verbose, async { Ok(work.await) }).await
    } else {
        work.await
    }
}

pub fn is_active() -> bool {
    ACTIVE.try_with(|_| ()).is_ok()
}

/// Run a Claude invocation with logging already open before polling its work.
pub async fn run(
    args: &crate::cli::WithArgs,
    data_dir: Option<&Path>,
    verbose: bool,
    work: impl std::future::Future<Output = Result<ExitCode, super::with_command::AnyError>>,
) -> ExitCode {
    let directory = data_dir.map_or_else(crate::config::default_data_dir, Path::to_path_buf);
    let log = match DiagnosticLog::open(&directory, verbose) {
        Ok(log) => log,
        Err(error) => {
            // An unwritable destination must never allow an unlogged launch.
            // Structured callers still receive an inspectable error result.
            if verbose || crate::operation_context::current().is_some() {
                eprintln!(
                    "error: could not open launcher log {}: {error}",
                    directory.display()
                );
            }
            return ExitCode::from(1);
        }
    };
    if let Some(token) = &args.token {
        log.secrets.lock().unwrap().push(token.clone());
    }
    log.record("launch_started", "Claude launcher diagnostics opened");
    if let Err(error) = log.check() {
        if verbose || crate::operation_context::current().is_some() {
            eprintln!("error: {error}");
        }
        return ExitCode::from(1);
    }
    let writer = log.clone();
    let subscriber = tracing_subscriber::fmt()
        .with_ansi(false)
        .with_env_filter(crate::logging::env_filter(
            verbose,
            crate::operation_context::var("RUST_LOG").ok().as_deref(),
        ))
        .with_writer(move || TraceWriter {
            log: writer.clone(),
            bytes: Vec::new(),
        })
        .finish();
    ACTIVE
        .scope(
            log.clone(),
            async {
                let code = match work.await {
                    Ok(code) => {
                        if code != ExitCode::SUCCESS {
                            record("launch_failed", &format!("launcher exit status: {code:?}"));
                        }
                        record(
                            "launch_finished",
                            &format!("launcher exit status: {code:?}"),
                        );
                        code
                    }
                    Err(error) => {
                        record("launch_failed", &error.to_string());
                        eprintln!("error: {error}");
                        ExitCode::from(1)
                    }
                };
                if let Err(error) = log.check() {
                    eprintln!("error: {error}");
                    ExitCode::from(1)
                } else {
                    code
                }
            }
            .with_subscriber(subscriber),
        )
        .await
}

/// Route Router output while leaving the vendor's inherited descriptors alone.
pub fn capture(arguments: std::fmt::Arguments<'_>) -> bool {
    ACTIVE
        .try_with(|log| {
            let original = arguments.to_string();
            log.record("diagnostic", &original);
            if log.terminal || crate::operation_context::current().is_some() {
                let message = log.sanitize(&original);
                crate::operation_output::write_passthrough(true, format_args!("{message}"));
            }
        })
        .is_ok()
}

pub fn record(event: &str, message: &str) {
    let _ = ACTIVE.try_with(|log| log.record(event, message));
}

pub fn add_secret(secret: Option<&str>) {
    if let Some(secret) = secret.filter(|secret| !secret.is_empty()) {
        let _ = ACTIVE.try_with(|log| log.secrets.lock().unwrap().push(secret.to_string()));
    }
}

pub fn check() -> Result<(), String> {
    ACTIVE.try_with(|log| log.check()).unwrap_or(Ok(()))
}

struct TraceWriter {
    log: Arc<DiagnosticLog>,
    bytes: Vec<u8>,
}

impl Write for TraceWriter {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        self.bytes.extend_from_slice(bytes);
        Ok(bytes.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

impl Drop for TraceWriter {
    fn drop(&mut self) {
        if !self.bytes.is_empty() {
            let original = String::from_utf8_lossy(&self.bytes);
            self.log.record("trace", &original);
            if self.log.terminal {
                let message = self.log.sanitize(&original);
                crate::operation_output::write_passthrough(true, format_args!("{message}"));
            }
        }
    }
}

#[cfg(test)]
#[path = "launcher_log_tests.rs"]
mod tests;

//! Redact credentials before persistence, truncation, or verbose rendering.

pub(super) fn secret_name(name: &str) -> bool {
    crate::request_log::is_secret_name(name) || name.to_ascii_lowercase().contains("cookie")
}

pub(super) fn sanitize(text: &str, secrets: &[String]) -> String {
    let mut text = text.to_string();
    for secret in secrets.iter().filter(|secret| !secret.is_empty()) {
        text = text.replace(secret, "[redacted]");
        // A server may JSON-escape a known credential in its error body.
        let encoded = serde_json::to_string(secret).expect("credential string serializes");
        text = text.replace(&encoded[1..encoded.len() - 1], "[redacted]");
    }
    redact_fields(&redact_urls(&redact_bearers_and_jwts(
        &crate::login_url::redact_secrets(&text),
    )))
}

fn redact_bearers_and_jwts(text: &str) -> String {
    let mut result = String::new();
    let mut copied = 0;
    for (position, _) in text.char_indices() {
        if position < copied {
            continue;
        }
        let rest = &text[position..];
        let bearer = rest
            .get(..7)
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("bearer "));
        if !bearer && !rest.starts_with("eyJ") {
            continue;
        }
        let start = position + if bearer { 7 } else { 0 };
        let value = &text[start..];
        let end = value
            .find(|c: char| !c.is_ascii_alphanumeric() && !matches!(c, '.' | '-' | '_'))
            .unwrap_or(value.len());
        if end > 0 && (bearer || value[..end].matches('.').count() == 2) {
            result.push_str(&text[copied..start]);
            result.push_str("[redacted]");
            copied = start + end;
        }
    }
    result.push_str(&text[copied..]);
    result
}

fn redact_urls(text: &str) -> String {
    let mut result = String::new();
    let mut rest = text;
    while let Some(start) = [rest.find("http://"), rest.find("https://")]
        .into_iter()
        .flatten()
        .min()
    {
        result.push_str(&rest[..start]);
        let candidate = &rest[start..];
        let end = candidate
            .find(|c: char| {
                c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>' | ')' | ']' | '}')
            })
            .unwrap_or(candidate.len());
        let candidate = &candidate[..end];
        if let Ok(mut url) = url::Url::parse(candidate) {
            let mut changed = false;
            if !url.username().is_empty() || url.password().is_some() {
                changed = true;
                let _ = url.set_username("redacted");
                let _ = url.set_password(None);
            }
            let query = url
                .query_pairs()
                .map(|(name, value)| {
                    let value = if secret_name(&name) {
                        changed = true;
                        "[redacted]".to_string()
                    } else {
                        value.into_owned()
                    };
                    (name.into_owned(), value)
                })
                .collect::<Vec<_>>();
            if !query.is_empty() {
                url.query_pairs_mut().clear().extend_pairs(query);
            }
            // OAuth responses can carry credentials in the fragment.
            if url.fragment().is_some() {
                changed = true;
                url.set_fragment(Some("redacted"));
            }
            result.push_str(if changed { url.as_str() } else { candidate });
        } else {
            result.push_str(candidate);
        }
        rest = &rest[start + end..];
    }
    result.push_str(rest);
    result
}

/// Handle JSON fields, HTTP headers, query parameters and key=value diagnostics.
fn redact_fields(text: &str) -> String {
    let bytes = text.as_bytes();
    let mut result = String::new();
    let mut copied = 0;
    let mut position = 0;
    while position < bytes.len() {
        if !bytes[position].is_ascii_alphabetic() {
            position += 1;
            continue;
        }
        let start = position;
        while position < bytes.len()
            && (bytes[position].is_ascii_alphanumeric() || matches!(bytes[position], b'_' | b'-'))
        {
            position += 1;
        }
        let name = &text[start..position];
        let mut value = position;
        if bytes.get(value).is_some_and(|b| matches!(b, b'"' | b'\'')) {
            value += 1;
        }
        while bytes.get(value).is_some_and(u8::is_ascii_whitespace) {
            value += 1;
        }
        if !secret_name(name) || !bytes.get(value).is_some_and(|b| matches!(b, b':' | b'=')) {
            continue;
        }
        value += 1;
        while bytes.get(value).is_some_and(u8::is_ascii_whitespace) {
            value += 1;
        }
        // Secret JSON fields may contain objects or arrays rather than strings.
        if bytes.get(value).is_some_and(|b| matches!(b, b'{' | b'[')) {
            let mut values =
                serde_json::Deserializer::from_str(&text[value..]).into_iter::<serde_json::Value>();
            if matches!(values.next(), Some(Ok(_))) {
                result.push_str(&text[copied..value]);
                result.push_str("\"[redacted]\"");
                copied = value + values.byte_offset();
                position = copied;
                continue;
            }
        }
        let quote = bytes
            .get(value)
            .copied()
            .filter(|b| matches!(b, b'"' | b'\''));
        if quote.is_some() {
            value += 1;
        }
        let mut end = value;
        if let Some(quote) = quote {
            while end < bytes.len() && bytes[end] != quote {
                if bytes[end] == b'\\' {
                    end += 1;
                }
                end = (end + 1).min(bytes.len());
            }
        } else {
            // Include the entire value of a Cookie header, including its pairs.
            let cookie =
                name.eq_ignore_ascii_case("cookie") || name.eq_ignore_ascii_case("set-cookie");
            if text[value..]
                .get(..7)
                .is_some_and(|prefix| prefix.eq_ignore_ascii_case("bearer "))
            {
                end += 7;
            }
            if text[end..].starts_with("[redacted]") {
                end += "[redacted]".len();
            }
            while end < bytes.len()
                && !matches!(
                    bytes[end],
                    b'\r' | b'\n' | b'"' | b'\'' | b'}' | b']' | b'&'
                )
                && (cookie
                    || !bytes[end].is_ascii_whitespace() && !matches!(bytes[end], b',' | b';'))
            {
                end += 1;
            }
        }
        result.push_str(&text[copied..value]);
        result.push_str("[redacted]");
        copied = end;
        position = end;
    }
    result.push_str(&text[copied..]);
    result
}

//! Lefine's persisted `OpenAI` Chat Completions provider contract.

use std::collections::HashSet;

use crate::providers::{LiveProviderModel, ProviderKind, ResolvedProvider};

pub const BASE_URL: &crate::translation_core::Str = "https://lefine.pro/v1";
pub const COMPATIBLE_CLIENTS: [&crate::translation_core::Str; 3] = ["grok", "opencode", "qwen"];
const MAX_CATALOG_BODY: usize = 1024 * 1024;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CatalogFailureKind {
    CredentialRejected,
    RateLimited,
    Unavailable,
}

#[derive(Debug)]
pub struct CatalogFailure {
    kind: CatalogFailureKind,
    message: &'static str,
}

impl CatalogFailure {
    const fn new(kind: CatalogFailureKind, message: &'static crate::translation_core::Str) -> Self {
        Self { kind, message }
    }

    #[must_use]
    pub const fn kind(&self) -> CatalogFailureKind {
        self.kind
    }
}

impl std::fmt::Display for CatalogFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(self.message)
    }
}

impl std::error::Error for CatalogFailure {}

/// Positively validate a Lefine key and return its exact live model catalog.
pub(crate) async fn fetch_catalog(
    client: &reqwest::Client,
    provider: &ResolvedProvider,
) -> crate::translation_core::Outcome<Vec<LiveProviderModel>, CatalogFailure> {
    if provider.kind != ProviderKind::Lefine {
        return Err(CatalogFailure::new(
            CatalogFailureKind::Unavailable,
            "provider does not use the Lefine catalog contract",
        ));
    }
    let key = provider
        .api_key
        .as_deref()
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            CatalogFailure::new(
                CatalogFailureKind::CredentialRejected,
                "Lefine API key is unavailable",
            )
        })?;
    let response = client
        .get(catalog_url(&provider.base_url))
        .bearer_auth(key)
        .send()
        .await
        .map_err(|_| unavailable("Lefine model catalog could not be verified"))?;
    let status = response.status();
    if matches!(
        status,
        reqwest::StatusCode::UNAUTHORIZED | reqwest::StatusCode::FORBIDDEN
    ) {
        return Err(CatalogFailure::new(
            CatalogFailureKind::CredentialRejected,
            "Lefine API key was rejected",
        ));
    }
    if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
        return Err(CatalogFailure::new(
            CatalogFailureKind::RateLimited,
            "Lefine model catalog was rate limited",
        ));
    }
    if !status.is_success() {
        return Err(unavailable("Lefine model catalog is unavailable"));
    }
    if response
        .content_length()
        .is_some_and(|length| length > MAX_CATALOG_BODY as u64)
    {
        return Err(unavailable(
            "Lefine model catalog exceeded the response limit",
        ));
    }
    let bytes = response
        .bytes()
        .await
        .map_err(|_| unavailable("Lefine model catalog could not be read"))?;
    if bytes.len() > MAX_CATALOG_BODY {
        return Err(unavailable(
            "Lefine model catalog exceeded the response limit",
        ));
    }
    let payload: serde_json::Value = serde_json::from_slice(&bytes)
        .map_err(|_| unavailable("Lefine model catalog response was malformed"))?;
    if let Some(error) = payload.get("error") {
        return Err(body_error(error));
    }
    let entries = payload
        .get("data")
        .and_then(serde_json::Value::as_array)
        .filter(|entries| !entries.is_empty())
        .ok_or_else(|| unavailable("Lefine model catalog contained no models"))?;
    let mut models = exact_models(entries)?;
    let source_url = catalog_url(&provider.base_url);
    let account = provider
        .subscriber_id
        .as_deref()
        .unwrap_or(provider.name.as_str());
    for model in &mut models {
        crate::model_evidence::annotate_live_catalog(
            &mut model.raw,
            &source_url,
            &provider.base_url,
            account,
            &["openai-compatible:/models"],
        );
    }
    Ok(models)
}

/// Operator-configured exact IDs used only while live discovery is unavailable.
pub(crate) fn configured_catalog(
    provider: &ResolvedProvider,
) -> crate::translation_core::Outcome<Vec<LiveProviderModel>, CatalogFailure> {
    if provider.models.is_empty() {
        return Err(unavailable(
            "Lefine live catalog is unavailable and no exact fallback models are configured",
        ));
    }
    Ok(provider
        .models
        .iter()
        .map(|id| LiveProviderModel {
            id: id.clone(),
            raw: serde_json::Map::from_iter([
                ("id".into(), crate::translation_core::Json::String(id.clone())),
                ("object".into(), crate::translation_core::Json::String("model".into())),
                (
                    "catalog_source".into(),
                    crate::translation_core::Json::String("configured_fallback".into()),
                ),
            ]),
        })
        .collect())
}

fn exact_models(entries: &[crate::translation_core::Json]) -> crate::translation_core::Outcome<Vec<LiveProviderModel>, CatalogFailure> {
    let mut seen = HashSet::new();
    let mut models = Vec::new();
    for entry in entries {
        let raw = entry
            .as_object()
            .cloned()
            .ok_or_else(|| unavailable("Lefine catalog contained an invalid model record"))?;
        let id = raw
            .get("id")
            .and_then(crate::translation_core::Json::as_str)
            .filter(|id| !id.is_empty() && *id == id.trim())
            .ok_or_else(|| unavailable("Lefine catalog contained an invalid exact model id"))?;
        if seen.insert(id.to_string()) {
            models.push(LiveProviderModel {
                id: id.to_string(),
                raw,
            });
        }
    }
    Ok(models)
}

fn body_error(error: &crate::translation_core::Json) -> CatalogFailure {
    let field = |name: &str| {
        error.get(name).map_or_else(String::new, |value| {
            value
                .as_str()
                .map_or_else(|| value.to_string(), str::to_string)
        })
    };
    let description = error
        .as_str()
        .map_or_else(
            || [field("code"), field("type"), field("message")].join(" "),
            str::to_string,
        )
        .to_ascii_lowercase();
    let kind = if description.contains("api_key")
        || description.contains("api key")
        || description.contains("auth")
        || description.split_whitespace().any(|value| value == "401")
    {
        CatalogFailureKind::CredentialRejected
    } else if description.contains("rate")
        || description.split_whitespace().any(|value| value == "429")
    {
        CatalogFailureKind::RateLimited
    } else {
        CatalogFailureKind::Unavailable
    };
    CatalogFailure::new(kind, "Lefine model catalog returned an error")
}

fn catalog_url(base_url: &crate::translation_core::Str) -> String {
    let base = base_url.trim_end_matches('/');
    if base.ends_with("/v1") {
        format!("{base}/models")
    } else {
        format!("{base}/v1/models")
    }
}

const fn unavailable(message: &'static crate::translation_core::Str) -> CatalogFailure {
    CatalogFailure::new(CatalogFailureKind::Unavailable, message)
}

#[cfg(test)]
#[path = "lefine_tests.rs"]
