/// The effective server and the optional lease that controls a managed local one.
pub struct ResolvedServer {
    /// Public origin used for health, service catalogs, and generated clients.
    pub base_url: String,
    /// Private origin used only for management API calls.
    pub management_url: String,
    pub token: Option<String>,
    pub source: &'static str,
    pub run_max_requests: Option<u64>,
    /// Router-owned CA bundle for requests and clients using `base_url`.
    pub ca_cert: Option<PathBuf>,
    /// Router-owned CA bundle for requests using `management_url`.
    pub management_ca_cert: Option<PathBuf>,
    _lease: Option<ManagedLease>,
}

impl ResolvedServer {
    /// A server reference for an already-known origin.
    ///
    /// Holds no managed-container lease, so it neither starts nor keeps one
    /// alive — for a router that is simply already running at `base_url`.
    #[must_use]
    pub fn at(base_url: impl Into<String>, token: Option<String>, source: &'static str) -> Self {
        let base_url = base_url.into();
        Self {
            management_url: base_url.clone(),
            base_url,
            token,
            source,
            run_max_requests: None,
            ca_cert: None,
            management_ca_cert: None,
            _lease: None,
        }
    }

    /// A server whose management and inference listeners are intentionally
    /// disjoint.
    #[must_use]
    pub fn at_origins(
        base_url: impl Into<String>,
        management_url: impl Into<String>,
        token: Option<String>,
        source: &'static str,
    ) -> Self {
        Self {
            base_url: base_url.into(),
            management_url: management_url.into(),
            token,
            source,
            run_max_requests: None,
            ca_cert: None,
            management_ca_cert: None,
            _lease: None,
        }
    }

    /// HTTP client carrying the trust associated with the inference origin.
    pub fn inference_client(&self) -> Result<reqwest::Client, AnyError> {
        self.inference_client_with_timeout(Duration::from_secs(10))
    }

    pub(crate) fn inference_client_with_timeout(
        &self,
        timeout: Duration,
    ) -> Result<reqwest::Client, AnyError> {
        http_client(self.ca_cert.as_deref(), timeout)
    }

    /// HTTP client carrying the trust associated with the management origin.
    pub fn management_client(&self) -> Result<reqwest::Client, AnyError> {
        self.management_client_with_timeout(Duration::from_secs(10))
    }

    pub(crate) fn management_client_with_timeout(
        &self,
        timeout: Duration,
    ) -> Result<reqwest::Client, AnyError> {
        http_client(self.management_ca_cert.as_deref(), timeout)
    }
}

