//! Canonical, credential-free Router origins.

use super::AnyError;

/// Whether two spellings name the same Router.
pub(super) fn same_origin(one: &str, other: &str) -> bool {
    match (normalize_server(one), normalize_server(other)) {
        (Ok(one), Ok(other)) => one == other,
        _ => false,
    }
}

pub(super) fn normalize_server(server: &str) -> Result<String, AnyError> {
    let parsed = url::Url::parse(server.trim()).map_err(|_| {
        "server URL must be an absolute http:// or https:// origin without credentials, path, query, or fragment"
    })?;
    if !matches!(parsed.scheme(), "http" | "https")
        || parsed.cannot_be_a_base()
        || parsed.host_str().is_none()
        || !parsed.username().is_empty()
        || parsed.password().is_some()
        || parsed.path() != "/"
        || parsed.query().is_some()
        || parsed.fragment().is_some()
    {
        return Err(
            "server URL must be an absolute http:// or https:// origin without credentials, path, query, or fragment"
                .into(),
        );
    }
    let host = match parsed.host().expect("checked above") {
        url::Host::Ipv6(address) => format!("[{address}]"),
        host => host.to_string(),
    };
    Ok(parsed.port().map_or_else(
        || format!("{}://{host}", parsed.scheme()),
        |port| format!("{}://{host}:{port}", parsed.scheme()),
    ))
}

/// Validate and canonicalize a public server origin without ever embedding
/// the rejected input in an error.
pub fn canonical_server_origin(server: &str) -> Result<String, AnyError> {
    normalize_server(server)
}

//! Cross-platform liveness check for managed-server lease owners.

#[cfg(unix)]
use std::process::Stdio;

pub(super) fn process_alive(pid: u32) -> bool {
    if pid == std::process::id() {
        return true;
    }
    #[cfg(unix)]
    {
        crate::operation_context::process_output(
            crate::operation_context::command("kill")
                .args(["-0", &pid.to_string()])
                .stdout(Stdio::null())
                .stderr(Stdio::null()),
        )
        .is_ok_and(|output| output.status.success())
    }
    #[cfg(windows)]
    {
        crate::operation_context::process_output(
            &mut crate::operation_context::command("tasklist").args([
                "/FI",
                &format!("PID eq {pid}"),
                "/NH",
            ]),
        )
        .is_ok_and(|output| {
            output.status.success()
                && String::from_utf8_lossy(&output.stdout).contains(&pid.to_string())
        })
    }
}

//! Heartbeat for a live `router with` process.

use std::time::Duration;
use tracing::instrument::WithSubscriber as _;

use super::RunCredential;

const HEARTBEAT_INTERVAL: Duration = Duration::from_secs(30);

pub(super) struct Lease {
    url: String,
    client: reqwest::Client,
}

impl Lease {
    pub(super) fn new(base_url: &str, client: reqwest::Client) -> Self {
        Self {
            url: format!(
                "{}{}",
                base_url.trim_end_matches('/'),
                crate::route_contract::route_template(crate::route_contract::RouteId::RunLease)
            ),
            client,
        }
    }
}

pub struct Guard(tokio::task::JoinHandle<()>);

impl Drop for Guard {
    fn drop(&mut self) {
        self.0.abort();
    }
}

/// What one heartbeat answer means for the wrapper (issue #644).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Beat {
    /// The lease was renewed.
    Renewed,
    /// The server predates the run-lease endpoint (a rollback to an older
    /// release answers 404/405). The run's token is still valid until its
    /// own expiry, so heartbeating stops quietly instead of warning forever.
    Unsupported,
    /// The server no longer accepts this run's token: its record is missing,
    /// revoked or expired, or the issuer secret changed.
    Rejected,
    /// The token is accepted but the lease cannot be renewed.
    Refused,
    /// A transient failure; try again on the next beat.
    Transient,
}

impl Beat {
    pub(super) const fn classify(status: reqwest::StatusCode) -> Self {
        match status.as_u16() {
            200..=299 => Self::Renewed,
            404 | 405 => Self::Unsupported,
            401 | 403 => Self::Rejected,
            409 => Self::Refused,
            _ => Self::Transient,
        }
    }

    const fn reason(self) -> &'static str {
        match self {
            Self::Renewed => "renewed",
            Self::Unsupported => crate::auth_diagnostics::reason::UNSUPPORTED_LEASE_ENDPOINT,
            Self::Rejected => "token_rejected",
            Self::Refused => crate::auth_diagnostics::reason::RUN_LEASE_UNRENEWABLE,
            Self::Transient => "transient",
        }
    }
}

pub fn start(credential: &RunCredential) -> Option<Guard> {
    let lease = credential.run_lease.as_ref()?;
    let url = lease.url.clone();
    let client = lease.client.clone();
    let token = credential.token.clone();
    Some(Guard(tokio::spawn(async move {
        let mut last = Beat::Renewed;
        loop {
            tokio::time::sleep(HEARTBEAT_INTERVAL).await;
            let beat = match client
                .post(&url)
                .bearer_auth(&token)
                .timeout(Duration::from_secs(10))
                .send()
                .await
            {
                Ok(response) => Beat::classify(response.status()),
                Err(error) => {
                    tracing::debug!(error = %error, "wrapper run lease heartbeat could not reach Router");
                    Beat::Transient
                }
            };
            // Warn when the outcome changes, not on every beat.
            if beat != last {
                match beat {
                    Beat::Renewed => tracing::info!("wrapper run lease heartbeat recovered"),
                    Beat::Unsupported => tracing::warn!(
                        reason = beat.reason(),
                        "Router does not serve the run lease endpoint (an older release, e.g. \
                         after a rollback); the run continues on its token's own expiry"
                    ),
                    _ => tracing::warn!(
                        reason = beat.reason(),
                        "wrapper run lease heartbeat was not renewed; see \
                         GET /api/management/auth/diagnostics on the Router"
                    ),
                }
                last = beat;
            }
            if beat == Beat::Unsupported {
                return;
            }
        }
    }.with_current_subscriber())))
}

#[cfg(test)]
mod tests {
    use super::Beat;
    use reqwest::StatusCode;

    #[test]
    fn a_legacy_server_without_the_endpoint_is_unsupported_not_an_auth_failure() {
        assert_eq!(Beat::classify(StatusCode::NOT_FOUND), Beat::Unsupported);
        assert_eq!(
            Beat::classify(StatusCode::METHOD_NOT_ALLOWED),
            Beat::Unsupported
        );
        assert_eq!(Beat::classify(StatusCode::OK), Beat::Renewed);
        assert_eq!(Beat::classify(StatusCode::UNAUTHORIZED), Beat::Rejected);
        assert_eq!(Beat::classify(StatusCode::CONFLICT), Beat::Refused);
        assert_eq!(Beat::classify(StatusCode::BAD_GATEWAY), Beat::Transient);
        assert_eq!(
            Beat::Unsupported.reason(),
            crate::auth_diagnostics::reason::UNSUPPORTED_LEASE_ENDPOINT
        );
    }
}

//! Which router this machine is pointed at, and where that choice is kept.
//!
//! Split from `managed_server.rs` to keep that file within the repository's
//! 1000-line limit. The selection is one small, well-bounded thing: a file
//! under the router's state directory, two environment variables that outrank
//! it, and the rules for reading, writing and clearing them.

use std::fs;
use std::path::{Path, PathBuf};

use super::state::{state_directory, state_file_for_read, write_private_json};
use super::{AnyError, PersistedServer, SERVER_CONFIG, normalize_server};
use sha2::{Digest as _, Sha256};

const TRUST_DIRECTORY: &str = "server-trust";

/// The router this machine has explicitly been pointed at, if any.
///
/// Explicit only: the environment or a persisted `server use`. Discovery and
/// the managed container are deliberately absent, so this answers "did the
/// operator select a deployment?" without probing, starting or pulling
/// anything. A command that can only act locally uses it to refuse honestly
/// rather than acting on a router the operator did not name (issue #296).
pub fn selected_server() -> Result<Option<String>, AnyError> {
    if let Some(selected) = crate::operation_context::var("LINK_ASSISTANT_ROUTER_URL")
        .or_else(|_| crate::operation_context::var("ROUTER_URL"))
        .ok()
        .filter(|value| !value.trim().is_empty())
    {
        return normalize_server(&selected).map(Some);
    }
    load_persisted()?
        .map(|persisted| persisted.server)
        .filter(|value| !value.trim().is_empty())
        .map(|value| normalize_server(&value))
        .transpose()
}

pub fn save_persisted(config: &PersistedServer) -> Result<PathBuf, AnyError> {
    let config = normalized_config(config)?;
    let path = state_directory()?.join(SERVER_CONFIG);
    write_private_json(&path, &config)?;
    Ok(path)
}

fn normalized_config(config: &PersistedServer) -> Result<PersistedServer, AnyError> {
    if config.server.is_empty() {
        return Err("server URL must not be empty".into());
    }
    let mut config = config.clone();
    config.server = normalize_server(&config.server)?;
    config.management_server = config
        .management_server
        .as_deref()
        .map(normalize_server)
        .transpose()?;
    if config.management_server.as_deref() == Some(config.server.as_str()) {
        config.management_server = None;
    }
    Ok(config)
}

/// Save a selection after importing its optional CA bundles into Router state.
pub fn save_persisted_with_trust(
    config: &PersistedServer,
    ca_cert: Option<&Path>,
    management_ca_cert: Option<&Path>,
) -> Result<PathBuf, AnyError> {
    let previous = load_persisted().ok().flatten();
    // Validate before copying trust material so a bad URL cannot leave an
    // unreferenced Router-owned certificate behind.
    let mut selected = normalized_config(config)?;
    let mut imported = Vec::new();
    selected.ca_cert = match ca_cert {
        Some(path) => {
            let name = import_certificate(path)?;
            imported.push(name.clone());
            Some(name)
        }
        None => previous
            .as_ref()
            .filter(|held| super::same_origin(&held.server, &selected.server))
            .and_then(|held| held.ca_cert.clone()),
    };
    let selected_management = selected
        .management_server
        .as_deref()
        .unwrap_or(&selected.server);
    selected.management_ca_cert = match management_ca_cert {
        Some(path) => match import_certificate(path) {
            Ok(name) => {
                imported.push(name.clone());
                Some(name)
            }
            Err(error) => {
                remove_imported_certificates(&imported, previous.as_ref());
                return Err(error);
            }
        },
        None => previous.as_ref().and_then(|held| {
            let held_management = held.management_server.as_deref().unwrap_or(&held.server);
            super::same_origin(held_management, selected_management)
                .then(|| held.management_ca_cert.clone())
                .flatten()
        }),
    };
    if selected.management_server.is_none() && selected.management_ca_cert.is_none() {
        selected.management_ca_cert = selected.ca_cert.clone();
    }
    let path = match save_persisted(&selected) {
        Ok(path) => path,
        Err(error) => {
            remove_imported_certificates(&imported, previous.as_ref());
            return Err(error);
        }
    };
    if let Some(previous) = previous {
        remove_unreferenced_certificates(&previous, &selected);
    }
    Ok(path)
}

fn remove_imported_certificates(imported: &[String], retained: Option<&PersistedServer>) {
    for name in imported {
        if retained.is_some_and(|config| {
            config.ca_cert.as_deref() == Some(name)
                || config.management_ca_cert.as_deref() == Some(name)
        }) {
            continue;
        }
        if let Ok(Some(path)) = certificate_path(Some(name)) {
            let _ = fs::remove_file(path);
        }
    }
}

fn import_certificate(source: &Path) -> Result<String, AnyError> {
    let bytes = fs::read(source).map_err(|error| {
        format!(
            "could not read CA certificate {}: {error}",
            source.display()
        )
    })?;
    let certificates = reqwest::Certificate::from_pem_bundle(&bytes)
        .map_err(|error| format!("invalid PEM CA certificate {}: {error}", source.display()))?;
    if certificates.is_empty() {
        return Err(format!(
            "CA certificate {} contains no certificates",
            source.display()
        )
        .into());
    }
    let name = format!("ca-{}.pem", hex::encode(Sha256::digest(&bytes)));
    let directory = state_directory()?.join(TRUST_DIRECTORY);
    fs::create_dir_all(&directory)?;
    super::state::set_owner_only(&directory)?;
    crate::durable_file::atomic_write_owner_only(&directory.join(&name), &bytes)?;
    Ok(name)
}

pub(super) fn certificate_path(name: Option<&str>) -> Result<Option<PathBuf>, AnyError> {
    let Some(name) = name else {
        return Ok(None);
    };
    let candidate = Path::new(name);
    if candidate.file_name().and_then(|part| part.to_str()) != Some(name)
        || !name.starts_with("ca-")
        || candidate.extension().and_then(|part| part.to_str()) != Some("pem")
    {
        return Err("persisted Router CA name is invalid".into());
    }
    let path = state_directory()?.join(TRUST_DIRECTORY).join(name);
    if !path.is_file() {
        return Err(format!(
            "selected Router CA certificate {} is missing; select the server again with --ca-cert",
            path.display()
        )
        .into());
    }
    Ok(Some(path))
}

fn remove_unreferenced_certificates(previous: &PersistedServer, selected: &PersistedServer) {
    for name in [
        previous.ca_cert.as_deref(),
        previous.management_ca_cert.as_deref(),
    ]
    .into_iter()
    .flatten()
    {
        if selected.ca_cert.as_deref() == Some(name)
            || selected.management_ca_cert.as_deref() == Some(name)
        {
            continue;
        }
        if let Ok(Some(path)) = certificate_path(Some(name)) {
            let _ = fs::remove_file(path);
        }
    }
}

pub fn clear_persisted() -> Result<PathBuf, AnyError> {
    let previous = load_persisted().ok().flatten();
    let path = state_directory()?.join(SERVER_CONFIG);
    match fs::remove_file(&path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }
    if let Some(previous) = previous {
        remove_unreferenced_certificates(&previous, &PersistedServer::default());
    }
    Ok(path)
}

pub fn load_persisted() -> Result<Option<PersistedServer>, AnyError> {
    let path = state_file_for_read(SERVER_CONFIG)?;
    match fs::read_to_string(&path) {
        Ok(source) => {
            let mut persisted: PersistedServer =
                crate::lino_json::decode(&source).map_err(|error| {
                    format!(
                        "invalid persisted server configuration {}: {error}",
                        path.display()
                    )
                })?;
            persisted.server = normalize_server(&persisted.server)?;
            persisted.management_server = persisted
                .management_server
                .as_deref()
                .map(normalize_server)
                .transpose()?;
            Ok(Some(persisted))
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(error.into()),
    }
}

pub fn configured_source() -> Result<String, AnyError> {
    if let Ok(value) = crate::operation_context::var("LINK_ASSISTANT_ROUTER_URL") {
        return Ok(format!("environment: {}", normalize_server(&value)?));
    }
    if let Ok(value) = crate::operation_context::var("ROUTER_URL") {
        return Ok(format!("environment: {}", normalize_server(&value)?));
    }
    if let Some(config) = load_persisted()? {
        return Ok(format!(
            "persisted: {} (token {})",
            normalize_server(&config.server)?,
            if config.token.is_some() {
                "set"
            } else {
                "unset"
            }
        ));
    }
    Ok("managed local container".to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A selection must be a URL the CLI can actually reach. `save_persisted`
    /// rejects the two ways it cannot be — empty, and without a scheme —
    /// rather than writing a value every later command has to re-validate.
    #[test]
    fn a_selection_must_be_an_absolute_http_url() {
        let empty = PersistedServer {
            server: String::new(),
            management_server: None,
            token: None,
            run_max_requests: None,
            ca_cert: None,
            management_ca_cert: None,
        };
        assert!(
            save_persisted(&empty).is_err(),
            "an empty selection is not a router"
        );

        let schemeless = PersistedServer {
            server: "router.example:8080".into(),
            management_server: None,
            token: None,
            run_max_requests: None,
            ca_cert: None,
            management_ca_cert: None,
        };
        let error = save_persisted(&schemeless)
            .expect_err("a schemeless URL must be refused")
            .to_string();
        assert!(
            error.contains("http://") && error.contains("https://"),
            "the refusal must name what is acceptable: {error}"
        );
    }

    /// Clearing a selection that was never made is not an error: `server use
    /// --clear` runs on machines that never selected anything.
    #[test]
    fn clearing_an_absent_selection_succeeds() {
        // Against a root this test owns. Without it `clear_persisted` resolved
        // the developer's real `~/.config/link-assistant-router/server.json`
        // and deleted it -- a file holding a live token -- and the test passed
        // either way, which is why it read as harmless (issue #343).
        let directory = tempfile::tempdir().expect("temporary state root");
        let _guard = super::super::state::claim_state_root(directory.path().to_path_buf());

        let first = clear_persisted().expect("clearing is idempotent");
        let second = clear_persisted().expect("and stays idempotent");
        assert_eq!(first, second, "both name the same path");
        assert!(
            first.starts_with(directory.path()),
            "the path cleared must be the one this test owns: {}",
            first.display()
        );
    }

    /// Clearing removes a selection that is present, and only that one.
    ///
    /// The old test was named for an absent selection but nothing made it
    /// absent, so on a machine that had one it silently exercised the
    /// deletion path against real state (issue #343).
    #[test]
    fn clearing_a_present_selection_removes_it() {
        let directory = tempfile::tempdir().expect("temporary state root");
        let _guard = super::super::state::claim_state_root(directory.path().to_path_buf());

        save_persisted(&PersistedServer {
            server: "http://127.0.0.1:18878".to_string(),
            management_server: None,
            token: Some("la_sk_example".to_string()),
            run_max_requests: None,
            ca_cert: None,
            management_ca_cert: None,
        })
        .expect("save a selection");
        assert!(load_persisted().expect("load").is_some(), "it was saved");

        let cleared = clear_persisted().expect("clear it");
        assert!(cleared.starts_with(directory.path()));
        assert!(
            load_persisted().expect("load").is_none(),
            "the selection is gone after clearing"
        );
    }

    #[test]
    fn split_origins_round_trip_canonically_and_legacy_files_still_default() {
        let directory = tempfile::tempdir().expect("temporary state root");
        let _guard = super::super::state::claim_state_root(directory.path().to_path_buf());

        let path = save_persisted(&PersistedServer {
            server: "https://Inference.Example:443/".to_string(),
            management_server: Some("https://Admin.Example:8443/".to_string()),
            token: Some("la_sk_example".to_string()),
            run_max_requests: Some(4),
            ca_cert: None,
            management_ca_cert: None,
        })
        .expect("save split selection");
        let loaded = load_persisted().expect("load").expect("selection");
        assert_eq!(loaded.server, "https://inference.example");
        assert_eq!(
            loaded.management_server.as_deref(),
            Some("https://admin.example:8443")
        );

        fs::write(
            path,
            r#"{"server":"https://legacy.example","token":"la_sk_legacy"}"#,
        )
        .expect("seed legacy selection");
        let legacy = load_persisted().expect("load legacy").expect("selection");
        assert_eq!(legacy.server, "https://legacy.example");
        assert_eq!(legacy.management_server, None);
        assert_eq!(legacy.ca_cert, None);
        assert_eq!(legacy.management_ca_cert, None);
    }

    /// Selection takes ownership of trust material. The source can disappear,
    /// and clearing the selection removes only the copies Router owns.
    #[test]
    fn selected_ca_certificates_are_owned_and_cleaned_with_the_selection() {
        let directory = tempfile::tempdir().expect("temporary state root");
        let _guard = super::super::state::claim_state_root(directory.path().to_path_buf());
        let source = tempfile::tempdir().expect("certificate source");
        let (inference_ca, _) = crate::tls::ensure_generated(
            &source.path().join("inference"),
            &["inference.example".to_string()],
        )
        .expect("generate inference CA");
        let (management_ca, _) = crate::tls::ensure_generated(
            &source.path().join("management"),
            &["management.example".to_string()],
        )
        .expect("generate management CA");

        save_persisted_with_trust(
            &PersistedServer {
                server: "https://inference.example".into(),
                management_server: Some("https://management.example".into()),
                token: Some("la_sk_example".into()),
                run_max_requests: None,
                ca_cert: None,
                management_ca_cert: None,
            },
            Some(&inference_ca),
            Some(&management_ca),
        )
        .expect("save trusted selection");
        let loaded = load_persisted().expect("load").expect("selection");
        let inference_owned = certificate_path(loaded.ca_cert.as_deref())
            .expect("resolve inference CA")
            .expect("inference CA");
        let management_owned = certificate_path(loaded.management_ca_cert.as_deref())
            .expect("resolve management CA")
            .expect("management CA");
        assert_ne!(inference_owned, inference_ca);
        assert_ne!(management_owned, management_ca);
        assert_eq!(
            fs::read(&inference_owned).unwrap(),
            fs::read(&inference_ca).unwrap()
        );
        assert_eq!(
            fs::read(&management_owned).unwrap(),
            fs::read(&management_ca).unwrap()
        );
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            assert_eq!(
                fs::metadata(&inference_owned).unwrap().permissions().mode() & 0o777,
                0o600
            );
            assert_eq!(
                fs::metadata(inference_owned.parent().unwrap())
                    .unwrap()
                    .permissions()
                    .mode()
                    & 0o777,
                0o700
            );
        }

        drop(source);
        assert!(!inference_ca.exists() && !management_ca.exists());
        assert!(inference_owned.is_file() && management_owned.is_file());

        let unrelated = super::super::state::state_directory()
            .unwrap()
            .join("unrelated-state");
        fs::write(&unrelated, "keep").expect("write unrelated state");
        clear_persisted().expect("clear selection");
        assert!(!inference_owned.exists());
        assert!(!management_owned.exists());
        assert!(unrelated.exists());
    }

    /// A partially valid selection is transactional: importing one CA before
    /// rejecting the other must not mutate the saved selection or leak a copy.
    #[test]
    fn rejected_trust_selection_removes_newly_imported_certificates() {
        let directory = tempfile::tempdir().expect("temporary state root");
        let _guard = super::super::state::claim_state_root(directory.path().to_path_buf());
        let source = tempfile::tempdir().expect("certificate source");
        let (valid_ca, _) = crate::tls::ensure_generated(
            &source.path().join("valid"),
            &["inference.example".to_string()],
        )
        .expect("generate inference CA");
        let invalid_ca = source.path().join("invalid.pem");
        fs::write(&invalid_ca, "not a certificate").expect("write invalid CA");
        let original = PersistedServer {
            server: "https://original.example".into(),
            token: Some("la_sk_original".into()),
            ..PersistedServer::default()
        };
        save_persisted(&original).expect("save original selection");

        let error = save_persisted_with_trust(
            &PersistedServer {
                server: "https://inference.example".into(),
                management_server: Some("https://management.example".into()),
                ..PersistedServer::default()
            },
            Some(&valid_ca),
            Some(&invalid_ca),
        )
        .expect_err("invalid management CA must reject the whole selection")
        .to_string();

        assert!(
            error.contains("CA certificate"),
            "unexpected error: {error}"
        );
        let retained = load_persisted()
            .unwrap()
            .expect("original selection retained");
        assert_eq!(retained.server, original.server);
        assert_eq!(retained.token, original.token);
        assert_eq!(retained.ca_cert, None);
        assert_eq!(retained.management_ca_cert, None);
        let trust = super::super::state::state_directory()
            .unwrap()
            .join(TRUST_DIRECTORY);
        assert_eq!(fs::read_dir(trust).unwrap().count(), 0);
    }
}

//! Structured selection and managed lifecycle facts behind `server status`.
use super::{AnyError, CONTAINER, VOLUME};
use crate::operation_reports::{ManagedServerStatus, ServerSelection};

pub async fn selection() -> Result<(ServerSelection, String), AnyError> {
    for name in ["LINK_ASSISTANT_ROUTER_URL", "ROUTER_URL"] {
        if let Ok(value) = crate::operation_context::var(name) {
            let url = super::normalize_server(&value)?;
            return Ok((
                ServerSelection {
                    source: "environment".into(),
                    url: Some(url.clone()),
                    token_configured: crate::operation_context::var("LINK_ASSISTANT_ROUTER_TOKEN")
                        .or_else(|_| crate::operation_context::var("LINK_ASSISTANT_TOKEN"))
                        .is_ok(),
                },
                format!("environment: {url}"),
            ));
        }
    }
    if let Some(config) = super::load_persisted()? {
        let url = super::normalize_server(&config.server)?;
        let token_configured = config.token.is_some();
        return Ok((
            ServerSelection {
                source: "persisted".into(),
                url: Some(url.clone()),
                token_configured,
            },
            format!(
                "persisted: {url} (token {})",
                if token_configured { "set" } else { "unset" }
            ),
        ));
    }
    if let Some(url) = super::discover_local_router(false).await {
        return Ok((
            ServerSelection {
                source: "discovered".into(),
                url: Some(url.clone()),
                token_configured: crate::operation_context::var("LINK_ASSISTANT_ROUTER_TOKEN")
                    .or_else(|_| crate::operation_context::var("LINK_ASSISTANT_TOKEN"))
                    .is_ok(),
            },
            format!("already-running local server: {url}"),
        ));
    }
    Ok((
        ServerSelection {
            source: "managed".into(),
            url: None,
            token_configured: false,
        },
        "managed local container".into(),
    ))
}

pub fn managed() -> Result<(ManagedServerStatus, String), AnyError> {
    let lock = super::lock_state()?;
    let mut state = super::load_managed()?;
    if let Some(state) = state.as_mut() {
        super::prune_references(state);
        super::save_managed(state)?;
    }
    drop(lock);
    let (lifecycle, detail) = match super::docker_container_state() {
        Ok(state) => (state, None),
        Err(error) => ("unavailable".into(), Some(error.to_string())),
    };
    let report = ManagedServerStatus {
        present: state.is_some(),
        state: lifecycle.clone(),
        detail: detail.clone(),
        container: CONTAINER.into(),
        volume: VOLUME.into(),
        url: state
            .as_ref()
            .map(|state| format!("http://127.0.0.1:{}", state.port)),
        administrator_claimed: state.as_ref().is_some_and(|state| state.claimed),
        users: state.as_ref().map_or(0, |state| state.references.len()),
        keep_running: state.as_ref().is_some_and(|state| state.keep_running),
    };
    let human = match state {
        Some(state) => {
            let subscriptions = if lifecycle == "running" {
                super::docker_subscription_status()
            } else {
                "not queried while stopped".into()
            };
            let lifecycle = detail.map_or(lifecycle, |detail| format!("unavailable ({detail})"));
            format!(
                "{lifecycle}; administrator={}; container={CONTAINER}; volume={VOLUME}; url=http://127.0.0.1:{}; users={}; subscriptions={subscriptions}",
                if state.claimed {
                    "claimed"
                } else {
                    "unclaimed"
                },
                state.port,
                state.references.len()
            )
        }
        None => format!("absent; container={CONTAINER}; volume={VOLUME}"),
    };
    Ok((report, human))
}

use super::*;

impl RunCredential {
    /// The durable record id retained so a persistent credential remains
    /// revocable later (issue #190).
    #[must_use]
    pub fn id(&self) -> Option<String> {
        token_subject(&self.token).ok()
    }

    /// Whether this command minted the credential. Supplied tokens may be
    /// shared with other machines and must not be revoked implicitly (#296).
    #[must_use]
    pub const fn was_minted(&self) -> bool {
        self.revocation.is_some()
    }
}

pub fn token_subject(token: &str) -> Result<String, AnyError> {
    token_claim(token)?
        .get("sub")
        .and_then(Value::as_str)
        .map(str::to_string)
        .ok_or_else(|| "router run token has no subject to revoke".into())
}

pub fn token_client_binding(token: &str) -> Result<(Option<String>, Option<String>), AnyError> {
    let claims = token_claim(token)?;
    Ok((
        claims
            .get("client_kind")
            .and_then(Value::as_str)
            .map(str::to_string),
        claims
            .get("principal_id")
            .and_then(Value::as_str)
            .map(str::to_string),
    ))
}

pub(super) fn exact_token_binding(token: &str, client: ClientKind) -> Result<String, AnyError> {
    let (bound, principal) = token_client_binding(token)?;
    if bound.as_deref() != Some(client.canonical_name()) {
        return Err(format!(
            "the supplied token must carry the exact `{}` client binding",
            client.canonical_name()
        )
        .into());
    }
    principal
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| "the supplied token must carry a subscriber principal".into())
}

fn token_claim(token: &str) -> Result<Value, AnyError> {
    let payload = token
        .split('.')
        .nth(1)
        .ok_or("router returned a token without a JWT payload")?;
    let decoded = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(payload)
        .map_err(|error| format!("router returned an invalid JWT payload: {error}"))?;
    serde_json::from_slice(&decoded).map_err(Into::into)
}

//! Owner-only on-disk state for the managed background router.
//!
//! Split from `managed_server.rs` to keep that file within the repository's
//! 1000-line limit.

use std::fs::{self, File, OpenOptions};
use std::io::Write as _;
use std::path::{Path, PathBuf};

use serde::Serialize;

use super::{AnyError, CONFIG_DIRECTORY, MANAGED_LOCK, MANAGED_STATE, ManagedState};

// A state root a test has claimed for itself, in this thread only.
//
// `cargo test` deleted the developer's own `server.json` — a file holding a
// live token — because `clearing_an_absent_selection_succeeds` called
// `clear_persisted()` with nothing overriding `HOME`, so it removed the real
// one. The test passed either way, which is why it read as harmless
// (issue #343).
//
// A thread-local rather than an environment variable: `XDG_CONFIG_HOME` is
// process-global and this crate forbids `unsafe`, so a test could not
// override it without racing every other test in the binary.
#[cfg(test)]
thread_local! {
    static TEST_STATE_ROOT: std::cell::RefCell<Option<PathBuf>> =
        const { std::cell::RefCell::new(None) };
}

/// Point state resolution at `root` until the guard is dropped.
///
/// Every test that reads or writes router state must hold one of these: the
/// alternative is a test that operates on whoever ran it.
#[cfg(test)]
pub fn claim_state_root(root: PathBuf) -> StateRootGuard {
    TEST_STATE_ROOT.with(|slot| *slot.borrow_mut() = Some(root));
    StateRootGuard
}

/// Restores real state resolution when the test ends, panic or not.
#[cfg(test)]
pub struct StateRootGuard;

#[cfg(test)]
impl Drop for StateRootGuard {
    fn drop(&mut self) {
        TEST_STATE_ROOT.with(|slot| *slot.borrow_mut() = None);
    }
}

pub(super) fn state_directory() -> Result<PathBuf, AnyError> {
    let root = resolved_root()?;
    let path = root.join(CONFIG_DIRECTORY);
    fs::create_dir_all(&path)?;
    set_owner_only(&path)?;
    Ok(path)
}

/// Resolve a state file for a read without creating its parent directory.
pub(super) fn state_file_for_read(name: &str) -> Result<PathBuf, AnyError> {
    Ok(resolved_root()?.join(CONFIG_DIRECTORY).join(name))
}

/// The directory router state lives under, outside tests.
///
/// An empty variable is unset, not configured: taking `Some("")` as a root
/// made every state path relative and wrote a live token into `$PWD`
/// (issue #340).
#[cfg(not(test))]
fn resolved_root() -> Result<PathBuf, AnyError> {
    let root = crate::env_paths::directory("XDG_CONFIG_HOME")
        .or_else(|| crate::env_paths::directory("HOME").map(|home| home.join(".config")))
        .or_else(|| crate::env_paths::directory("APPDATA"))
        .ok_or("HOME, XDG_CONFIG_HOME, and APPDATA are unset; cannot store server state")?;
    Ok(crate::env_paths::require_absolute(
        root,
        "the router's state directory",
    )?)
}

/// The root a test claimed, refusing to fall back to the developer's own.
///
/// No test may resolve real state. The failure mode is silent -- a test that
/// deletes the developer's credential passes just the same -- and silence is
/// what let it ship, so an unclaimed resolution fails loudly (issue #343).
#[cfg(test)]
fn resolved_root() -> Result<PathBuf, AnyError> {
    TEST_STATE_ROOT
        .with(|slot| slot.borrow().clone())
        .ok_or_else(|| {
            AnyError::from(
                "a test resolved the real state directory without claiming one; wrap it in \
                 `claim_state_root(tempfile::tempdir()?.path())`",
            )
        })
}

pub(super) fn lock_state() -> Result<File, AnyError> {
    let path = state_directory()?.join(MANAGED_LOCK);
    let file = OpenOptions::new()
        .create(true)
        .truncate(false)
        .read(true)
        .write(true)
        .open(path)?;
    file.lock()?;
    Ok(file)
}

pub(super) fn load_managed() -> Result<Option<ManagedState>, AnyError> {
    let path = state_directory()?.join(MANAGED_STATE);
    match fs::read_to_string(&path) {
        Ok(source) => Ok(Some(crate::lino_json::decode(&source).map_err(
            |error| format!("invalid managed server state {}: {error}", path.display()),
        )?)),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(error.into()),
    }
}

pub(super) fn save_managed(state: &ManagedState) -> Result<(), AnyError> {
    write_private_json(&state_directory()?.join(MANAGED_STATE), state)
}

pub(super) fn write_private_json(path: &Path, value: &impl Serialize) -> Result<(), AnyError> {
    let temporary = path.with_extension(format!("tmp-{}", uuid::Uuid::new_v4()));
    let mut options = OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let mut file = options.open(&temporary)?;
    // Links notation, readable, with the file name unchanged so an existing
    // installation keeps its path and migrates on the next write (issue #235).
    file.write_all(crate::lino_json::encode(value)?.as_bytes())?;
    file.write_all(b"\n")?;
    file.sync_all()?;
    #[cfg(windows)]
    if path.exists() {
        fs::remove_file(path)?;
    }
    fs::rename(&temporary, path)?;
    set_owner_only(path)?;
    Ok(())
}

pub(super) fn set_owner_only(path: &Path) -> Result<(), std::io::Error> {
    #[cfg(not(unix))]
    let _ = path;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        let mode = if path.is_dir() { 0o700 } else { 0o600 };
        fs::set_permissions(path, fs::Permissions::from_mode(mode))?;
    }
    Ok(())
}

//! Live metrics and operational endpoints.
//!
//! Issue #7 R11 requires the router to expose Prometheus-compatible
//! `/api/management/metrics`, plus `/api/management/usage` and
//! `/api/management/accounts` for fleet ops.
//!
//! This module provides:
//!
//! - [`Metrics`] — atomic counters that handlers update (request totals,
//!   errors, bytes streamed, per-status codes, OpenAI-translation counts).
//! - [`render_prometheus`] — formats those counters in the Prometheus
//!   text-exposition format consumed by `/metrics`.
//! - [`UsageSnapshot`] / [`usage_snapshot`] — aggregate counts and per-
//!   account usage, served as JSON by `/api/management/usage`.
//! - [`Metrics`] recording methods — tiny helpers that handlers can call from
//!   `proxy_handler` and the `OpenAI` translators.
//!
//! The implementation is intentionally lock-free (atomics + a single Mutex
//! for the per-status / per-account maps) so it stays cheap on the hot path.

use std::collections::HashMap;
use std::fmt::Write as _;
use std::sync::Mutex;
use std::sync::atomic::{AtomicU64, Ordering};

use serde::Serialize;

/// Live counters updated by request handlers.
#[derive(Debug, Default)]
pub struct Metrics {
    pub requests_total: AtomicU64,
    pub errors_total: AtomicU64,
    pub bytes_in: AtomicU64,
    pub bytes_out: AtomicU64,
    pub openai_chat_completions: AtomicU64,
    pub openai_responses: AtomicU64,
    pub anthropic_messages: AtomicU64,
    pub tokens_issued: AtomicU64,
    pub tokens_revoked: AtomicU64,
    /// Pooled requests retried on another account before the first byte
    /// (issue #676).
    pub pool_failovers: AtomicU64,
    /// "Warmup" probes answered locally (issue #677).
    pub warmup_intercepted: AtomicU64,
    pub status_counts: Mutex<HashMap<u16, u64>>,
    pub account_calls: Mutex<HashMap<String, u64>>,
    /// Per-token request counters, keyed by router token id (JWT `sub`).
    ///
    /// Issue #45 wants one token per task so usage can be attributed; this is
    /// the monitoring half of that (the durable half is [`crate::audit`]).
    pub token_calls: Mutex<HashMap<String, TokenUsage>>,
}

/// Per-token usage accumulated by [`Metrics::record_token_request`].
#[derive(Debug, Clone, Default, Serialize, schemars::JsonSchema)]
pub struct TokenUsage {
    /// Label the token was issued with (empty when none was given).
    pub label: String,
    /// Requests authorised for this token since the router started.
    pub requests: u64,
}

impl Metrics {
    pub fn record_request(&self, surface: Surface, status: u16, account: crate::translation_core::Maybe<&crate::translation_core::Str>) {
        self.requests_total.fetch_add(1, Ordering::Relaxed);
        if status >= 400 {
            self.errors_total.fetch_add(1, Ordering::Relaxed);
        }
        match surface {
            Surface::Anthropic => {
                self.anthropic_messages.fetch_add(1, Ordering::Relaxed);
            }
            Surface::OpenAIChat => {
                self.openai_chat_completions.fetch_add(1, Ordering::Relaxed);
            }
            Surface::OpenAIResponses => {
                self.openai_responses.fetch_add(1, Ordering::Relaxed);
            }
        }
        if let Ok(mut g) = self.status_counts.lock() {
            *g.entry(status).or_insert(0) += 1;
        }
        if let Some(acct) = account
            && let Ok(mut g) = self.account_calls.lock()
        {
            *g.entry(acct.to_string()).or_insert(0) += 1;
        }
    }

    /// Attribute one authorised request to a router token.
    ///
    /// Called once per request, right after the token is validated, so the
    /// counter reflects requests the router accepted for that token — the same
    /// unit `max_requests` budgets.
    pub fn record_token_request(&self, token_id: &crate::translation_core::Str, label: &crate::translation_core::Str) {
        if let Ok(mut g) = self.token_calls.lock() {
            let entry = g.entry(token_id.to_string()).or_default();
            if entry.label.is_empty() && !label.is_empty() {
                entry.label = label.to_string();
            }
            entry.requests += 1;
        }
    }

    pub fn record_bytes(&self, sent: u64, received: u64) {
        self.bytes_out.fetch_add(sent, Ordering::Relaxed);
        self.bytes_in.fetch_add(received, Ordering::Relaxed);
    }

    pub fn record_token_issued(&self) {
        self.tokens_issued.fetch_add(1, Ordering::Relaxed);
    }

    pub fn record_token_revoked(&self) {
        self.tokens_revoked.fetch_add(1, Ordering::Relaxed);
    }

    /// One pooled request moved to another account before its first byte.
    pub fn record_pool_failover(&self) {
        self.pool_failovers.fetch_add(1, Ordering::Relaxed);
    }

    /// One "Warmup" probe answered without an upstream call.
    pub fn record_warmup_intercepted(&self) {
        self.warmup_intercepted.fetch_add(1, Ordering::Relaxed);
    }
}

/// Which API surface generated the request.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Surface {
    Anthropic,
    OpenAIChat,
    OpenAIResponses,
}

/// JSON-serialisable snapshot of [`Metrics`] for `/api/management/usage`.
#[derive(Debug, Serialize, schemars::JsonSchema)]
pub struct UsageSnapshot {
    pub requests_total: u64,
    pub errors_total: u64,
    pub bytes_in: u64,
    pub bytes_out: u64,
    pub openai_chat_completions: u64,
    pub openai_responses: u64,
    pub anthropic_messages: u64,
    pub tokens_issued: u64,
    pub tokens_revoked: u64,
    pub status_counts: HashMap<u16, u64>,
    pub account_calls: HashMap<String, u64>,
    /// Per-token request counts keyed by router token id.
    pub token_calls: HashMap<String, TokenUsage>,
}

#[must_use]
pub fn usage_snapshot(m: &Metrics) -> UsageSnapshot {
    UsageSnapshot {
        requests_total: m.requests_total.load(Ordering::Relaxed),
        errors_total: m.errors_total.load(Ordering::Relaxed),
        bytes_in: m.bytes_in.load(Ordering::Relaxed),
        bytes_out: m.bytes_out.load(Ordering::Relaxed),
        openai_chat_completions: m.openai_chat_completions.load(Ordering::Relaxed),
        openai_responses: m.openai_responses.load(Ordering::Relaxed),
        anthropic_messages: m.anthropic_messages.load(Ordering::Relaxed),
        tokens_issued: m.tokens_issued.load(Ordering::Relaxed),
        tokens_revoked: m.tokens_revoked.load(Ordering::Relaxed),
        status_counts: m
            .status_counts
            .lock()
            .map(|g| g.clone())
            .unwrap_or_default(),
        account_calls: m
            .account_calls
            .lock()
            .map(|g| g.clone())
            .unwrap_or_default(),
        token_calls: m.token_calls.lock().map(|g| g.clone()).unwrap_or_default(),
    }
}

/// Render the current metrics in Prometheus text-exposition format.
#[must_use]
pub fn render_prometheus(m: &Metrics) -> String {
    let snap = usage_snapshot(m);
    let mut out = String::new();
    let pairs: [(&str, u64); 9] = [
        ("link_assistant_requests_total", snap.requests_total),
        ("link_assistant_errors_total", snap.errors_total),
        ("link_assistant_bytes_in_total", snap.bytes_in),
        ("link_assistant_bytes_out_total", snap.bytes_out),
        (
            "link_assistant_openai_chat_completions_total",
            snap.openai_chat_completions,
        ),
        (
            "link_assistant_openai_responses_total",
            snap.openai_responses,
        ),
        (
            "link_assistant_anthropic_messages_total",
            snap.anthropic_messages,
        ),
        ("link_assistant_tokens_issued_total", snap.tokens_issued),
        ("link_assistant_tokens_revoked_total", snap.tokens_revoked),
    ];
    for (name, value) in pairs {
        out.push_str("# TYPE ");
        out.push_str(name);
        out.push_str(" counter\n");
        out.push_str(name);
        out.push(' ');
        out.push_str(&value.to_string());
        out.push('\n');
    }
    for (name, counter) in [
        ("link_assistant_pool_failovers_total", &m.pool_failovers),
        (
            "link_assistant_warmup_intercepted_total",
            &m.warmup_intercepted,
        ),
    ] {
        let _ = writeln!(
            out,
            "# TYPE {name} counter\n{name} {}",
            counter.load(Ordering::Relaxed)
        );
    }
    out.push_str("# TYPE link_assistant_status_total counter\n");
    let mut sorted_status: Vec<_> = snap.status_counts.iter().collect();
    sorted_status.sort_by_key(|(k, _)| *k);
    for (status, count) in sorted_status {
        let _ = writeln!(
            out,
            "link_assistant_status_total{{code=\"{status}\"}} {count}"
        );
    }
    out
}

/// Render the per-subscription health gauge in Prometheus exposition format.
///
/// This is the signal a monitor actually wants and the one that did not exist:
/// a revoked subscription produced no counter, no status change and no alert,
/// leaving a container log as the only witness (issue #318). Provider names are
/// vendor names, never account identifiers, so this carries nothing the rest of
/// `/metrics` does not already expose.
#[must_use]
pub fn render_subscription_health(providers: &[(&crate::translation_core::Str, bool)]) -> String {
    if providers.is_empty() {
        return String::new();
    }
    let mut out = String::from(
        "# HELP link_assistant_subscription_healthy Whether a configured subscription can serve \
         requests (1) or not (0).\n# TYPE link_assistant_subscription_healthy gauge\n",
    );
    let mut sorted = providers.to_vec();
    sorted.sort_unstable_by_key(|(name, _)| *name);
    for (provider, healthy) in sorted {
        let _ = writeln!(
            out,
            "link_assistant_subscription_healthy{{provider=\"{provider}\"}} {}",
            u8::from(healthy)
        );
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn per_token_requests_are_counted_and_labelled() {
        let m = Metrics::default();
        m.record_token_request("tok-a", "task-a");
        m.record_token_request("tok-a", "task-a");
        m.record_token_request("tok-b", "task-b");

        let snap = usage_snapshot(&m);
        assert_eq!(snap.token_calls["tok-a"].requests, 2);
        assert_eq!(snap.token_calls["tok-a"].label, "task-a");
        assert_eq!(snap.token_calls["tok-b"].requests, 1);

        let out = render_prometheus(&m);
        assert!(
            !out.contains("tok-a"),
            "public metrics leaked a token id: {out}"
        );
        assert!(
            !out.contains("task-a"),
            "public metrics leaked a token label: {out}"
        );
    }

    #[test]
    fn public_metrics_omit_token_labels_and_account_names() {
        let m = Metrics::default();
        m.record_token_request("tok-a", "task \"one\"\nline");
        m.record_request(Surface::Anthropic, 200, Some("primary-account"));
        let out = render_prometheus(&m);
        assert!(
            !out.contains("tok-a"),
            "public metrics leaked a token id: {out}"
        );
        assert!(
            !out.contains("task"),
            "public metrics leaked a token label: {out}"
        );
        assert!(
            !out.contains("primary-account"),
            "public metrics leaked an account name: {out}"
        );
    }

    #[test]
    fn token_counters_are_absent_until_a_token_is_used() {
        let m = Metrics::default();
        m.record_request(Surface::Anthropic, 200, None);
        assert!(usage_snapshot(&m).token_calls.is_empty());
        assert!(!render_prometheus(&m).contains("link_assistant_token_requests_total{"));
    }

    #[test]
    fn record_and_render_basic_counters() {
        let m = Metrics::default();
        m.record_request(Surface::Anthropic, 200, Some("primary"));
        m.record_request(Surface::OpenAIChat, 200, Some("primary"));
        m.record_request(Surface::OpenAIChat, 500, Some("account-1"));
        m.record_token_issued();
        m.record_bytes(100, 50);

        let out = render_prometheus(&m);
        assert!(out.contains("link_assistant_requests_total 3"));
        assert!(out.contains("link_assistant_errors_total 1"));
        assert!(out.contains("link_assistant_anthropic_messages_total 1"));
        assert!(out.contains("link_assistant_openai_chat_completions_total 2"));
        assert!(out.contains("link_assistant_tokens_issued_total 1"));
        assert!(out.contains("code=\"200\""));
        assert!(out.contains("code=\"500\""));
        assert!(!out.contains("account=\"primary\""));
    }

    #[test]
    fn usage_snapshot_returns_consistent_values() {
        let m = Metrics::default();
        m.record_request(Surface::OpenAIResponses, 200, None);
        let snap = usage_snapshot(&m);
        assert_eq!(snap.requests_total, 1);
        assert_eq!(snap.openai_responses, 1);
        assert_eq!(snap.errors_total, 0);
    }

    /// A deployment with no subscription configured adds no series at all,
    /// rather than an empty `# TYPE` header a scraper has to skip.
    #[test]
    fn no_configured_subscription_renders_nothing() {
        assert!(render_subscription_health(&[]).is_empty());
    }

    /// One gauge per subscription, in a stable order, carrying the vendor name
    /// and nothing else (issue #318).
    #[test]
    fn the_gauge_is_typed_sorted_and_carries_only_the_vendor_name() {
        let rendered = render_subscription_health(&[("codex", true), ("claude", false)]);
        assert!(rendered.contains("# TYPE link_assistant_subscription_healthy gauge"));
        assert!(rendered.contains("# HELP link_assistant_subscription_healthy"));
        let claude = rendered
            .find("link_assistant_subscription_healthy{provider=\"claude\"} 0")
            .expect("a revoked subscription reads 0");
        let codex = rendered
            .find("link_assistant_subscription_healthy{provider=\"codex\"} 1")
            .expect("a working subscription reads 1");
        assert!(claude < codex, "series are sorted, so scrapes diff cleanly");
    }
}

//! Live subscription model discovery with stale-on-error caching.

use std::collections::{BTreeSet, HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::RwLock;
use std::time::Duration;

use serde_json::Value;

use crate::subscription::{SubscriptionProvider, SubscriptionReader, SubscriptionToken};

#[path = "model_catalog_parse.rs"]
mod parse;
#[cfg(test)]
use parse::parse_catalog;
use parse::{next_catalog_cursor, parse_catalog_records, provider_protocols};
#[path = "model_catalog_errors.rs"]
mod errors;
#[path = "model_catalog_persistence.rs"]
mod persistence;
#[path = "model_catalog_selector.rs"]
mod selector;
#[path = "model_catalog_startup.rs"]
mod startup;
#[cfg(test)]
use errors::resource_error_code;
