//! Source configuration and the compact local definition grammar.
use crate::model_contract::{ModelRouteScope, ModelSelectorKind, ModelTruthDescriptor};
use std::time::Duration;

/// Three hours between source refresh attempts by default.
pub const DEFAULT_REFRESH_SECS: u64 = 10_800;

/// Operator definitions configuration. Defaults preserve live catalogs exactly.
#[derive(Clone, Debug)]
pub struct CatalogSourcesConfig {
    /// Comma-separated CLI/environment values in precedence order.
    pub sources: Vec<String>,
    /// Positive refresh interval in seconds (maximum one year).
    pub refresh_secs: u64,
    /// Explicit local definitions, applied after all sources.
    pub local_models: Vec<ModelTruthDescriptor>,
}

impl Default for CatalogSourcesConfig {
    fn default() -> Self {
        Self {
            sources: Vec::new(),
            refresh_secs: DEFAULT_REFRESH_SECS,
            local_models: Vec::new(),
        }
    }
}

impl CatalogSourcesConfig {
    /// Read source settings through the scoped environment without global mutation.
    pub fn from_env() -> Result<Self, String> {
        let sources = crate::operation_context::var("MODEL_CATALOG_SOURCES").unwrap_or_default();
        let refresh_secs = crate::operation_context::var("MODEL_CATALOG_REFRESH_SECS").map_or(
            Ok(DEFAULT_REFRESH_SECS),
            |raw| {
                raw.parse().map_err(|_| {
                    "MODEL_CATALOG_REFRESH_SECS must be a positive integer".to_string()
                })
            },
        )?;
        let config = Self {
            sources: sources
                .split(',')
                .map(str::trim)
                .filter(|source| !source.is_empty())
                .map(str::to_string)
                .collect(),
            refresh_secs,
            local_models: Vec::new(),
        };
        config.validate()?;
        Ok(config)
    }

    /// Reject unbounded polling or source counts and invalid local definitions.
    pub fn validate(&self) -> Result<(), String> {
        if self.refresh_secs == 0 || self.refresh_secs > 31_536_000 {
            return Err("MODEL_CATALOG_REFRESH_SECS must be between 1 and 31536000".into());
        }
        if self.sources.len() > 32 || self.local_models.len() > super::MAX_MODELS {
            return Err("at most 32 sources and 4096 local model entries are supported".into());
        }
        for model in &self.local_models {
            super::validate_definition(&mut model.clone())?;
        }
        Ok(())
    }

    pub(super) const fn interval(&self) -> Duration {
        Duration::from_secs(self.refresh_secs)
    }
}

/// Parse `name=provider:upstream`, preserving colons inside the upstream id.
pub fn local_model(value: &str) -> Result<ModelTruthDescriptor, String> {
    let (id, target) = value
        .split_once('=')
        .ok_or("local model must use name=provider:upstream")?;
    let (provider, upstream) = target
        .split_once(':')
        .ok_or("local model must use name=provider:upstream")?;
    let mut definition = ModelTruthDescriptor {
        requested_selector: Some(id.to_string()),
        selector_kind: if id == upstream {
            ModelSelectorKind::Concrete
        } else {
            ModelSelectorKind::OperatorAlias
        },
        route: ModelRouteScope {
            provider: Some(provider.to_string()),
            ..ModelRouteScope::default()
        },
        upstream_request_model: Some(upstream.to_string()),
        ..ModelTruthDescriptor::default()
    };
    super::validate_definition(&mut definition)?;
    Ok(definition)
}

pub(super) fn canonical_provider(provider: &str) -> String {
    match provider {
        "claude" => "anthropic",
        "chatgpt" | "openai-codex" => "codex",
        "google" => "gemini",
        "qwen-code" => "qwen",
        other => other,
    }
    .to_string()
}

pub(super) fn subscription_provider(
    provider: &str,
) -> Option<crate::subscription::SubscriptionProvider> {
    use crate::subscription::SubscriptionProvider as S;
    match provider {
        "anthropic" => Some(S::Claude),
        "codex" => Some(S::Codex),
        "gemini" => Some(S::Gemini),
        "qwen" => Some(S::Qwen),
        _ => None,
    }
}

//! Bounded file and HTTP reads using a dedicated guarded transport.
use super::{MAX_DOCUMENT_BYTES, ModelCatalogDocument, parse_document};
use crate::upstream_guard::{GuardedResolver, NetworkPolicy};
use tokio::io::AsyncReadExt;

pub(super) async fn load(source: &str) -> Result<ModelCatalogDocument, String> {
    load_with_policy(source, NetworkPolicy::from_env()).await
}

pub(super) async fn load_with_policy(
    source: &str,
    policy: NetworkPolicy,
) -> Result<ModelCatalogDocument, String> {
    let mut bytes = Vec::new();
    if source.starts_with("http://") || source.starts_with("https://") {
        let url = url::Url::parse(source).map_err(|_| "invalid catalog URL")?;
        if !url.username().is_empty() || url.password().is_some() {
            return Err("catalog URLs must not contain credentials".into());
        }
        policy
            .check_base_url(source)
            .map_err(|error| error.to_string())?;
        // Never fall back to an unguarded client. Disable environment proxies,
        // which could resolve a public URL to a private address outside this guard.
        let client = crate::upstream_client::upstream_client_builder()
            .no_proxy()
            .dns_resolver(std::sync::Arc::new(GuardedResolver::new(policy)))
            .build()
            .map_err(|_| "could not construct guarded catalog client")?;
        let mut response = client
            .get(url)
            .send()
            .await
            .map_err(|_| "catalog HTTP request failed")?;
        if !response.status().is_success() {
            return Err(format!("catalog returned HTTP {}", response.status()));
        }
        if response
            .content_length()
            .is_some_and(|size| size > MAX_DOCUMENT_BYTES as u64)
        {
            return Err("model catalog exceeds the 1 MiB size limit".into());
        }
        while let Some(chunk) = response
            .chunk()
            .await
            .map_err(|_| "catalog body read failed")?
        {
            if chunk.len() > MAX_DOCUMENT_BYTES.saturating_sub(bytes.len()) {
                return Err("model catalog exceeds the 1 MiB size limit".into());
            }
            bytes.extend_from_slice(&chunk);
        }
    } else {
        let path = if source.starts_with("file:") {
            let url = url::Url::parse(source).map_err(|_| "invalid file URL")?;
            // On Windows, to_file_path also accepts remote hosts as UNC paths.
            // File URLs must remain local and never bypass the HTTP guard.
            if !matches!(url.host_str(), None | Some("localhost")) {
                return Err("file URL must name a local path".into());
            }
            url.to_file_path()
                .map_err(|()| "file URL must name a local path")?
        } else if source.contains("://") {
            return Err("catalog URLs must use http, https or file".into());
        } else {
            std::path::PathBuf::from(source)
        };
        if !tokio::fs::metadata(&path)
            .await
            .map_err(|_| "catalog file metadata unavailable")?
            .is_file()
        {
            return Err("catalog source must be a regular file".into());
        }
        let file = tokio::fs::File::open(&path)
            .await
            .map_err(|_| "catalog file could not be opened")?;
        file.take((MAX_DOCUMENT_BYTES + 1) as u64)
            .read_to_end(&mut bytes)
            .await
            .map_err(|_| "catalog file could not be read")?;
    }
    parse_document(&bytes)
}

//! Apply operator definitions only to an already authorized live inventory.
use super::ModelCatalogSources;
use crate::model_contract::{ModelRouteScope, ModelTruthDescriptor};
use crate::providers::LiveProviderModel;
use axum::extract::{Path, State};
use axum::response::{IntoResponse, Response};
use serde_json::{Value, json};

impl ModelCatalogSources {
    /// Apply provider-scoped definitions while retaining all unmodified live records.
    pub(crate) fn overlay(
        &self,
        provider: &str,
        mut live: Vec<LiveProviderModel>,
    ) -> Vec<LiveProviderModel> {
        // These fields carry Router's mapping authority, never vendor input.
        for model in &mut live {
            model.raw.remove("router_upstream_model");
            model.raw.remove("router_model_definition");
        }
        let definitions = self.definitions(provider);
        if definitions.is_empty() {
            return live;
        }
        let mut effective = live.clone();
        for mut definition in definitions {
            let id = definition
                .requested_selector
                .as_deref()
                .expect("validated id");
            let upstream = definition
                .upstream_request_model
                .as_deref()
                .expect("validated upstream");
            let Some(target) = live.iter().find(|model| model.id == upstream) else {
                continue;
            };
            let alias = id != upstream;
            // An alias must not silently replace a separately advertised live id.
            if alias && live.iter().any(|model| model.id == id) {
                continue;
            }
            definition.capability_provenance =
                json!({"source_kind":"operator_override", "router_version":crate::VERSION});
            let mut raw = if alias {
                serde_json::Map::new()
            } else {
                target.raw.clone()
            };
            if alias {
                for key in ["router_account", "router_endpoint", "router_protocols"] {
                    if let Some(value) = target.raw.get(key) {
                        raw.insert(key.into(), value.clone());
                    }
                }
            }
            raw.insert("id".into(), Value::String(id.to_string()));
            raw.insert("selector_kind".into(), json!(definition.selector_kind));
            raw.insert(
                "router_upstream_model".into(),
                Value::String(upstream.to_string()),
            );
            raw.insert(
                "router_model_definition".into(),
                serde_json::to_value(&definition).expect("truth serializes"),
            );
            let model = LiveProviderModel {
                id: id.to_string(),
                raw,
            };
            if let Some(existing) = effective.iter_mut().find(|model| model.id == id) {
                *existing = model;
            } else {
                effective.push(model);
            }
        }
        effective
    }

    pub(crate) fn annotate_subscription(
        &self,
        records: &mut [crate::model_catalog::CatalogRecord],
    ) {
        let mut providers = std::collections::HashMap::new();
        for record in records {
            record.raw.remove("router_model_definition");
            // Subscription overlays are exact-id only. They never populate the
            // cache's routable IDs or authenticate a missing account.
            let definitions = providers.entry(record.provider).or_insert_with(|| {
                self.definitions(record.provider.as_str())
                    .into_iter()
                    .map(|model| {
                        (
                            model.requested_selector.clone().expect("validated id"),
                            model,
                        )
                    })
                    .collect::<std::collections::BTreeMap<_, _>>()
            });
            if let Some(mut definition) = definitions.get(&record.canonical_id).cloned() {
                definition.capability_provenance =
                    json!({"source_kind":"operator_override", "router_version":crate::VERSION});
                record.raw.insert(
                    "router_model_definition".into(),
                    serde_json::to_value(definition).expect("truth serializes"),
                );
            }
        }
    }
}

/// Effective provider-scoped catalog for the existing admin-only management boundary.
#[derive(Clone, Debug, serde::Deserialize, serde::Serialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ModelDefinitionsResponse {
    /// Canonical subscription service or configured provider name.
    pub channel: String,
    /// Current live definitions after eligible operator overlays.
    pub models: Vec<ModelTruthDescriptor>,
}

pub async fn model_definitions(
    State(state): State<crate::app_state::AppState>,
    Path(channel): Path<String>,
) -> Response {
    let channel = super::config::canonical_provider(&channel);
    let sources = state.model_catalogs.sources();
    let models = if let Some(provider) = super::config::subscription_provider(&channel) {
        let mut records = state.model_catalogs.records(provider);
        sources.annotate_subscription(&mut records);
        records
            .into_iter()
            .map(|record| {
                let mut definition = truth(&record.canonical_id, &channel, &record.raw);
                definition.route.account = Some(record.account);
                definition.route.protocols = serde_json::from_value(json!(record.protocols))
                    .expect("protocols serialize as strings");
                definition
            })
            .collect()
    } else {
        let provider = match state.provider_store.resolve(&channel) {
            Ok(Some(provider))
                if matches!(
                    provider.kind,
                    crate::providers::ProviderKind::OpenAICompatible
                        | crate::providers::ProviderKind::Lefine
                ) =>
            {
                provider
            }
            Ok(_) => {
                return crate::proxy::error_response(
                    http::StatusCode::NOT_FOUND,
                    "not_found_error",
                    "unknown model catalog channel",
                );
            }
            Err(_) => {
                return crate::proxy::error_response(
                    http::StatusCode::INTERNAL_SERVER_ERROR,
                    "api_error",
                    "provider catalog unavailable",
                );
            }
        };
        match crate::provider_proxy::live_openai_compatible_catalog(&state, &provider).await {
            Ok(models) => models
                .into_iter()
                .map(|model| truth(&model.id, &channel, &model.raw))
                .collect(),
            Err(_) => {
                return crate::proxy::error_response(
                    http::StatusCode::SERVICE_UNAVAILABLE,
                    "api_error",
                    "live model catalog unavailable",
                );
            }
        }
    };
    axum::Json(ModelDefinitionsResponse { channel, models }).into_response()
}

fn truth(id: &str, provider: &str, raw: &serde_json::Map<String, Value>) -> ModelTruthDescriptor {
    let mut definition = raw
        .get("router_model_definition")
        .cloned()
        .and_then(|value| serde_json::from_value(value).ok())
        .unwrap_or_else(|| ModelTruthDescriptor {
            requested_selector: Some(id.to_string()),
            upstream_request_model: Some(id.to_string()),
            selector_kind: crate::model_contract::ModelSelectorKind::from_catalog_value(
                raw.get("selector_kind"),
            ),
            ..ModelTruthDescriptor::default()
        });
    definition.route = ModelRouteScope {
        provider: Some(provider.to_string()),
        account: raw
            .get("router_account")
            .and_then(Value::as_str)
            .map(str::to_string),
        endpoint: raw
            .get("router_endpoint")
            .and_then(Value::as_str)
            .map(str::to_string),
        protocols: raw
            .get("router_protocols")
            .and_then(Value::as_array)
            .map(|values| {
                values
                    .iter()
                    .filter_map(Value::as_str)
                    .map(str::to_string)
                    .collect()
            })
            .unwrap_or_default(),
    };
    definition
}

//! Machine-readable model-contract diagnostics.

use std::process::ExitCode;

use serde_json::{Value, json};

use crate::cli::{AuthTarget, ModelOp};
use crate::clients::ClientKind;
use crate::model_contract::{ModelRouteScope, ModelSelectorKind, ModelTruthDescriptor};

type AnyError = Box<dyn std::error::Error + Send + Sync>;

/// Run one model diagnostic without constructing server-only configuration.
pub async fn run(operation: &ModelOp) -> ExitCode {
    exit_code(run_inner(operation).await)
}

fn exit_code(result: crate::translation_core::Outcome<bool, AnyError>) -> ExitCode {
    match result {
        Ok(found) => {
            if found {
                ExitCode::SUCCESS
            } else {
                ExitCode::from(1)
            }
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

async fn run_inner(operation: &ModelOp) -> crate::translation_core::Outcome<bool, AnyError> {
    match operation {
        ModelOp::Explain { id, client, target } => explain(id, *client, target).await,
    }
}

async fn explain(id: &crate::translation_core::Str, client: ClientKind, target: &AuthTarget) -> crate::translation_core::Outcome<bool, AnyError> {
    if id.is_empty() {
        return Err("model selector must not be empty".into());
    }
    let server = resolve_target(target).await?;
    explain_at(id, client, &server).await
}

async fn explain_at(
    id: &crate::translation_core::Str,
    client: ClientKind,
    server: &crate::managed_server::ResolvedServer,
) -> crate::translation_core::Outcome<bool, AnyError> {
    let token = server.token.as_deref().ok_or(
        "the selected router has no client token; select one with `router server use --token ...`",
    )?;
    let url = format!("{}/api/models", server.base_url.trim_end_matches('/'));
    let request = server
        .inference_client()?
        .get(&url)
        .header("x-link-assistant-model-diagnostics", "1")
        .header("x-link-assistant-client", client.canonical_name());
    let request = match client {
        ClientKind::ClaudeCode => request.header("x-api-key", token),
        ClientKind::GeminiCli => request.header("x-goog-api-key", token),
        _ => request.bearer_auth(token),
    };
    let response = request.send().await?;
    let status = response.status();
    let text = response.text().await.unwrap_or_default();
    if !status.is_success() {
        return Err(format!("router model catalog failed at {url} ({status}): {text}").into());
    }
    let catalog: Value = serde_json::from_str(&text)?;
    let (diagnostic, found) = diagnostic(id, client, &catalog);
    let mut report = diagnostic.clone();
    report["output"] = json!([]);
    crate::operation_output::report(serde_json::from_value::<
        crate::operation_reports::ModelExplanationReport,
    >(report)?);
    println!("{}", serde_json::to_string_pretty(&diagnostic)?);
    Ok(found)
}

fn diagnostic(id: &crate::translation_core::Str, client: ClientKind, catalog: &crate::translation_core::Json) -> (crate::translation_core::Json, bool) {
    let mut matches = catalog
        .get("data")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|entry| entry.get("id").and_then(Value::as_str) == Some(id))
        .cloned()
        .collect::<Vec<_>>();
    matches.extend(
        catalog
            .get("catalog_conflict_candidates")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter(|entry| entry.get("id").and_then(Value::as_str) == Some(id))
            .cloned(),
    );
    let catalog_conflicts = catalog
        .get("catalog_conflicts")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let conflicted = catalog_conflicts
        .iter()
        .any(|candidate| candidate.as_str() == Some(id));
    let found = matches.len() == 1 && !conflicted;
    let entry = found.then(|| &matches[0]);
    let scope = entry
        .and_then(|value| value.pointer("/capability_provenance/scope"))
        .cloned()
        .unwrap_or(Value::Null);
    let (selector_kind, descriptor_selector_kind) = selector_kind(entry);
    let routing_state = if conflicted {
        "conflict"
    } else {
        match matches.len() {
            0 => "unknown",
            1 => "unique",
            _ => "conflict",
        }
    };
    let provenance = entry
        .and_then(|value| value.get("capability_provenance"))
        .cloned()
        .unwrap_or(Value::Null);
    let route_scope = provenance.get("scope").cloned().unwrap_or(Value::Null);
    let descriptor = ModelTruthDescriptor {
        requested_selector: Some(id.to_string()),
        selector_kind: descriptor_selector_kind,
        route: ModelRouteScope {
            provider: route_scope
                .get("provider")
                .and_then(Value::as_str)
                .map(str::to_string),
            account: route_scope
                .get("account")
                .and_then(Value::as_str)
                .map(str::to_string),
            endpoint: route_scope
                .get("endpoint")
                .and_then(Value::as_str)
                .map(str::to_string),
            protocols: route_scope
                .get("protocols")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(Value::as_str)
                .map(str::to_string)
                .collect(),
        },
        upstream_request_model: found.then(|| id.to_string()),
        upstream_served_model: None,
        capabilities: effective_capabilities(entry),
        capability_provenance: provenance.clone(),
        allow_substitution: catalog
            .pointer("/model_policy/allow_substitution")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        substitution_source: catalog
            .pointer("/model_policy/substitution_source")
            .and_then(Value::as_str)
            .map(str::to_string),
    };
    let diagnostic = crate::translation_core::json!({
        "contract_version": 1,
        "model_descriptor": descriptor,
        "requested_selector": id,
        "selector_kind": selector_kind,
        "served_identity": null,
        "client_representation": {
            "client": client.canonical_name(),
            "advertisements": matches,
        },
        "route_scope": scope,
        "capability_provenance": provenance,
        "model_policy": catalog.get("model_policy").cloned().unwrap_or_else(|| json!({})),
        "health": {
            "healthy_providers": catalog.get("healthy_providers").cloned().unwrap_or_else(|| json!([])),
            "starting_providers": catalog.get("starting_providers").cloned().unwrap_or_else(|| json!([])),
            "degraded_providers": catalog.get("degraded_providers").cloned().unwrap_or_else(|| json!([])),
            "degraded_reasons": catalog.get("degraded_reasons").cloned().unwrap_or_else(|| json!({})),
        },
        "routing": {
            "state": routing_state,
            "candidate_count": matches.len(),
            "catalog_conflicts": catalog_conflicts,
        },
    });
    (diagnostic, found)
}

fn selector_kind(entry: crate::translation_core::Maybe<&crate::translation_core::Json>) -> (&crate::translation_core::Str, ModelSelectorKind) {
    let label = entry
        .and_then(|value| value.get("selector_kind"))
        .and_then(crate::translation_core::Json::as_str)
        .unwrap_or("unknown");
    let kind = ModelSelectorKind::from_wire(label);
    (label, kind)
}

fn effective_capabilities(entry: crate::translation_core::Maybe<&crate::translation_core::Json>) -> crate::translation_core::Json {
    const FIELDS: [&str; 8] = [
        "context_window",
        "max_output_tokens",
        "modalities",
        "pricing",
        "deprecation_date",
        "default_reasoning_level",
        "supported_reasoning_levels",
        "client_capabilities",
    ];
    let Some(entry) = entry.and_then(Value::as_object) else {
        return Value::Null;
    };
    let capabilities = FIELDS
        .into_iter()
        .filter_map(|field| entry.get(field).cloned().map(|value| (field.into(), value)))
        .collect::<serde_json::Map<_, _>>();
    Value::Object(capabilities)
}

async fn resolve_target(
    target: &AuthTarget,
) -> crate::translation_core::Outcome<crate::managed_server::ResolvedServer, AnyError> {
    if target.local {
        return crate::managed_server::discovered_local_router()
            .await
            .ok_or_else(|| "no router is listening on this machine".into());
    }
    crate::managed_server::resolve(
        target.server.as_deref(),
        target.management_server.as_deref(),
        None,
        None,
        target.managed,
    )
    .await
}

#[cfg(test)]
mod tests {
    use std::sync::{Arc, Mutex};

    use axum::{Router, http::HeaderMap, routing::get};

    use super::*;

    fn target() -> AuthTarget {
        AuthTarget {
            local: false,
            server: None,
            management_server: None,
            managed: false,
        }
    }

    async fn server(
        status: axum::http::StatusCode,
        body: String,
    ) -> (
        String,
        Arc<Mutex<Vec<HeaderMap>>>,
        tokio::task::JoinHandle<()>,
    ) {
        let requests = Arc::new(Mutex::new(Vec::new()));
        let recorded = Arc::clone(&requests);
        let app = Router::new().route(
            "/api/models",
            get(move |headers: HeaderMap| {
                let recorded = Arc::clone(&recorded);
                let body = body.clone();
                async move {
                    recorded.lock().expect("request record").push(headers);
                    (status, body)
                }
            }),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind model catalog fixture");
        let address = listener.local_addr().expect("catalog fixture address");
        let task = tokio::spawn(async move {
            axum::serve(listener, app)
                .await
                .expect("serve model catalog fixture");
        });
        (format!("http://{address}"), requests, task)
    }

    #[test]
    fn missing_or_unrecognized_selector_metadata_stays_unknown() {
        assert_eq!(selector_kind(None), ("unknown", ModelSelectorKind::Unknown));
        let entry = json!({"selector_kind": "invented-from-name"});
        assert_eq!(
            selector_kind(Some(&entry)),
            ("invented-from-name", ModelSelectorKind::Unknown)
        );
    }

    #[test]
    fn selector_metadata_maps_only_explicit_contract_kinds() {
        for (label, expected) in [
            (
                "provider_dynamic_alias",
                ModelSelectorKind::ProviderDynamicAlias,
            ),
            (
                "provider_advertised_alias",
                ModelSelectorKind::ProviderDynamicAlias,
            ),
            ("operator_alias", ModelSelectorKind::OperatorAlias),
            ("concrete", ModelSelectorKind::Concrete),
            ("provider_advertised_exact_id", ModelSelectorKind::Concrete),
        ] {
            let entry = json!({"selector_kind": label});
            assert_eq!(selector_kind(Some(&entry)), (label, expected));
        }
    }

    #[test]
    fn unique_catalog_entry_produces_the_complete_truth_descriptor() {
        let catalog = json!({
            "data": [{
                "id": "provider/model-v1",
                "selector_kind": "provider_advertised_exact_id",
                "context_window": 200_000,
                "max_output_tokens": 16_384,
                "modalities": ["text"],
                "pricing": {"input": 1},
                "deprecation_date": null,
                "default_reasoning_level": "high",
                "supported_reasoning_levels": ["low", "high"],
                "client_capabilities": {"codex": {"supported": true}},
                "ignored": "not-a-capability",
                "capability_provenance": {
                    "scope": {
                        "provider": "provider",
                        "account": "account-1",
                        "endpoint": "https://provider.example/v1",
                        "protocols": ["openai-responses"]
                    },
                    "source": "provider-api"
                }
            }],
            "model_policy": {
                "allow_substitution": true,
                "substitution_source": "operator opt-in"
            },
            "healthy_providers": ["provider"],
            "degraded_providers": [],
            "degraded_reasons": {}
        });
        let (value, found) = diagnostic("provider/model-v1", ClientKind::Codex, &catalog);
        assert!(found);
        assert_eq!(value["routing"]["state"], "unique");
        assert_eq!(value["routing"]["candidate_count"], 1);
        assert_eq!(value["selector_kind"], "provider_advertised_exact_id");
        assert_eq!(value["model_descriptor"]["selector_kind"], "concrete");
        assert_eq!(
            value["model_descriptor"]["route"]["protocols"][0],
            "openai-responses"
        );
        assert_eq!(
            value["model_descriptor"]["capabilities"]["context_window"],
            200_000
        );
        assert!(
            value["model_descriptor"]["capabilities"]
                .get("ignored")
                .is_none()
        );
        assert_eq!(value["model_descriptor"]["allow_substitution"], true);
        assert_eq!(value["health"]["healthy_providers"][0], "provider");
    }

    #[test]
    fn ambiguous_conflicting_and_unknown_selectors_fail_closed() {
        let duplicate = json!({
            "data": [
                {"id": "same", "selector_kind": "concrete"},
                {"id": "same", "selector_kind": "operator_alias"}
            ]
        });
        let (value, found) = diagnostic("same", ClientKind::Agent, &duplicate);
        assert!(!found);
        assert_eq!(value["routing"]["state"], "conflict");
        assert_eq!(value["routing"]["candidate_count"], 2);
        assert!(value["model_descriptor"]["capabilities"].is_null());

        let conflicted = json!({
            "data": [],
            "catalog_conflict_candidates": [{"id": "same", "selector_kind": "concrete"}],
            "catalog_conflicts": ["same"]
        });
        let (value, found) = diagnostic("same", ClientKind::ClaudeCode, &conflicted);
        assert!(!found);
        assert_eq!(value["routing"]["state"], "conflict");
        assert_eq!(value["routing"]["catalog_conflicts"][0], "same");

        let (value, found) = diagnostic("missing", ClientKind::GeminiCli, &json!({}));
        assert!(!found);
        assert_eq!(value["routing"]["state"], "unknown");
        assert_eq!(value["route_scope"], Value::Null);
        assert_eq!(value["model_policy"], json!({}));
        assert_eq!(value["health"]["degraded_providers"], json!([]));
    }

    #[tokio::test]
    async fn catalog_fetch_uses_each_clients_native_authentication_header() {
        let body = json!({
            "data": [{"id": "model-v1", "selector_kind": "concrete"}]
        });
        let (url, requests, task) = server(axum::http::StatusCode::OK, body.to_string()).await;
        let router = crate::managed_server::ResolvedServer::at(
            url,
            Some("ordinary-token".to_string()),
            "test",
        );
        for client in [
            ClientKind::ClaudeCode,
            ClientKind::GeminiCli,
            ClientKind::Codex,
        ] {
            assert!(explain_at("model-v1", client, &router).await.unwrap());
        }
        let requests = requests.lock().expect("request record");
        assert_eq!(requests[0]["x-api-key"], "ordinary-token");
        assert_eq!(requests[1]["x-goog-api-key"], "ordinary-token");
        assert_eq!(requests[2]["authorization"], "Bearer ordinary-token");
        task.abort();
    }

    #[tokio::test]
    async fn catalog_fetch_reports_missing_tokens_http_errors_and_invalid_json() {
        let router = crate::managed_server::ResolvedServer::at("http://127.0.0.1:1", None, "test");
        assert!(
            explain_at("model-v1", ClientKind::Codex, &router)
                .await
                .unwrap_err()
                .to_string()
                .contains("no client token")
        );

        let (url, _, task) = server(
            axum::http::StatusCode::SERVICE_UNAVAILABLE,
            json!({"error": "catalog offline"}).to_string(),
        )
        .await;
        let router = crate::managed_server::ResolvedServer::at(
            url,
            Some("ordinary-token".to_string()),
            "test",
        );
        let error = explain_at("model-v1", ClientKind::Agent, &router)
            .await
            .unwrap_err()
            .to_string();
        assert!(error.contains("503 Service Unavailable"), "{error}");
        assert!(error.contains("catalog offline"), "{error}");
        task.abort();

        let (url, _, task) = server(axum::http::StatusCode::OK, "not-json".to_string()).await;
        let router = crate::managed_server::ResolvedServer::at(
            url,
            Some("ordinary-token".to_string()),
            "test",
        );
        assert!(
            explain_at("model-v1", ClientKind::Agent, &router)
                .await
                .is_err()
        );
        task.abort();
    }

    #[tokio::test]
    async fn empty_selector_fails_before_target_resolution() {
        let operation = ModelOp::Explain {
            id: String::new(),
            client: ClientKind::Agent,
            target: target(),
        };
        assert_ne!(run(&operation).await, ExitCode::SUCCESS);
    }

    #[test]
    fn command_status_distinguishes_unique_and_unresolved_models() {
        assert_eq!(exit_code(Ok(true)), ExitCode::SUCCESS);
        assert_eq!(exit_code(Ok(false)), ExitCode::from(1));
    }
}

//! Model-selection and served-identity contracts shared by every protocol.
//!
//! A wrapper-selected model is an authorization boundary, not an argv hint.
//! The durable policy below is deliberately exact and case-sensitive: model
//! aliases are accepted only when the provider advertised that exact alias.

use serde::{Deserialize, Serialize};

/// Kind of selector a caller supplied. Dynamic aliases are factual only when
/// the authenticated provider catalog advertised that exact spelling.
///
/// This is the one wire contract for `selector_kind`: every producer
/// serializes the canonical `snake_case` spelling, and every consumer —
/// catalog projection, `router model` diagnostics and the wrapper's typed
/// catalog rows — reads through [`Self::from_wire`]. Router once emitted
/// `provider_advertised_exact_id` for live z.ai rows while the wrapper's
/// derived parser accepted only the canonical names, so one such row made
/// `router with` reject the whole catalog (issue #620). A spelling this
/// build does not know is `Unknown`, never a parse failure: an older wrapper
/// must degrade to "no alias evidence", not to "no models".
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum ModelSelectorKind {
    Concrete,
    ProviderDynamicAlias,
    OperatorAlias,
    #[default]
    Unknown,
}

impl<'de> Deserialize<'de> for ModelSelectorKind {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let value = Option::<String>::deserialize(deserializer)?;
        Ok(value.as_deref().map_or(Self::Unknown, Self::from_wire))
    }
}

impl ModelSelectorKind {
    /// Interpret one wire spelling, including the provider-advertised
    /// synonyms earlier releases emitted.
    #[must_use]
    pub fn from_wire(value: &str) -> Self {
        match value {
            "provider_dynamic_alias" | "provider_advertised_alias" => Self::ProviderDynamicAlias,
            "operator_alias" => Self::OperatorAlias,
            "concrete" | "provider_advertised_exact_id" => Self::Concrete,
            _ => Self::Unknown,
        }
    }

    /// Interpret only explicit catalog metadata; selector spelling is never
    /// evidence that an id is an alias.
    #[must_use]
    pub fn from_catalog_value(value: Option<&serde_json::Value>) -> Self {
        value
            .and_then(serde_json::Value::as_str)
            .map_or(Self::Unknown, Self::from_wire)
    }

    /// The canonical wire spelling every producer emits.
    #[must_use]
    pub const fn as_wire(self) -> &'static str {
        match self {
            Self::Concrete => "concrete",
            Self::ProviderDynamicAlias => "provider_dynamic_alias",
            Self::OperatorAlias => "operator_alias",
            Self::Unknown => "unknown",
        }
    }

    /// Whether this selector explicitly delegates concrete resolution.
    #[must_use]
    pub const fn permits_resolution(self) -> bool {
        matches!(self, Self::ProviderDynamicAlias | Self::OperatorAlias)
    }
}

/// Exact routing scope for one model observation or exchange.
#[derive(Clone, Debug, Default, Deserialize, Eq, PartialEq, Serialize, schemars::JsonSchema)]
pub struct ModelRouteScope {
    pub provider: Option<String>,
    pub account: Option<String>,
    pub endpoint: Option<String>,
    pub protocols: Vec<String>,
}

/// Canonical truth descriptor used by model diagnostics and boundary logs.
///
/// `None` is intentionally serialized as JSON `null`: it means unknown, not
/// that Router may fill the field from a nearby selector.
#[derive(Clone, Debug, Default, Deserialize, Eq, PartialEq, Serialize, schemars::JsonSchema)]
pub struct ModelTruthDescriptor {
    pub requested_selector: Option<String>,
    pub selector_kind: ModelSelectorKind,
    pub route: ModelRouteScope,
    pub upstream_request_model: Option<String>,
    pub upstream_served_model: Option<String>,
    pub capabilities: serde_json::Value,
    pub capability_provenance: serde_json::Value,
    pub allow_substitution: bool,
    pub substitution_source: Option<String>,
}

// Serde's `skip_serializing_if` callback must accept a reference.
#[allow(clippy::trivially_copy_pass_by_ref)]
const fn is_false(value: &bool) -> bool {
    !*value
}

/// Model authority attached to one router-issued credential.
///
/// An empty allow-list preserves the historical unpinned behavior. A
/// non-empty list contains every exact selector the holder may request;
/// multiple entries therefore represent an explicit switching grant.
#[derive(Clone, Debug, Default, Deserialize, Eq, PartialEq, Serialize, schemars::JsonSchema)]
pub struct ModelAccessPolicy {
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub allowed_models: Vec<String>,
    /// Permit a provider to serve a different concrete model than requested.
    /// This never widens `allowed_models` at request time.
    #[serde(default, skip_serializing_if = "is_false")]
    pub allow_substitution: bool,
    /// User-controlled setting that enabled substitution, when enabled.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub substitution_source: Option<String>,
}

impl ModelAccessPolicy {
    /// Create a policy for one exact selector.
    #[must_use]
    pub fn exact(model: impl Into<String>) -> Self {
        Self {
            allowed_models: vec![model.into()],
            allow_substitution: false,
            substitution_source: None,
        }
    }

    /// Whether this credential permits the exact request selector.
    #[must_use]
    pub fn permits(&self, requested: &str) -> bool {
        self.allowed_models.is_empty()
            || self
                .allowed_models
                .iter()
                .any(|allowed| allowed == requested)
    }

    /// Validate values before persisting a grant.
    pub fn validate(&self) -> Result<(), String> {
        if self
            .allowed_models
            .iter()
            .any(|model| model.trim().is_empty())
        {
            return Err("allowed model ids must not be empty".to_string());
        }
        let mut unique = self.allowed_models.clone();
        unique.sort();
        unique.dedup();
        if unique.len() != self.allowed_models.len() {
            return Err("allowed model ids must not contain duplicates".to_string());
        }
        if self.allow_substitution
            && self
                .substitution_source
                .as_deref()
                .is_none_or(|source| source.trim().is_empty())
        {
            return Err(
                "enabled model substitution must name its configuration source".to_string(),
            );
        }
        if !self.allow_substitution && self.substitution_source.is_some() {
            return Err(
                "a substitution source requires model substitution to be enabled".to_string(),
            );
        }
        Ok(())
    }
}

/// Stable machine-readable refusal for a request outside a token grant.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize, schemars::JsonSchema)]
pub struct ModelAccessError {
    pub code: String,
    pub requested_model: String,
    pub allowed_models: Vec<String>,
}

impl ModelAccessError {
    #[must_use]
    pub fn new(requested: &str, policy: &ModelAccessPolicy) -> Self {
        Self {
            code: "model_not_allowed".to_string(),
            requested_model: requested.to_string(),
            allowed_models: policy.allowed_models.clone(),
        }
    }

    #[must_use]
    pub fn policy_unavailable(requested: &str) -> Self {
        Self {
            code: "model_policy_unavailable".to_string(),
            requested_model: requested.to_string(),
            allowed_models: Vec::new(),
        }
    }
}

impl std::fmt::Display for ModelAccessError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.code == "model_policy_unavailable" {
            return write!(
                formatter,
                "model_policy_unavailable: could not verify the exact model grant for `{}`",
                self.requested_model
            );
        }
        write!(
            formatter,
            "model_not_allowed: requested model `{}` is outside this credential's exact allow-list [{}]",
            self.requested_model,
            self.allowed_models.join(", ")
        )
    }
}

impl std::error::Error for ModelAccessError {}

/// Stable refusal when an upstream response does not prove what served it.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize, schemars::JsonSchema)]
pub struct ServedModelError {
    pub code: String,
    pub requested_model: String,
    pub served_model: Option<String>,
}

impl std::fmt::Display for ServedModelError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self.served_model.as_deref() {
            Some(served) => write!(
                formatter,
                "{}: requested `{}` but upstream served `{served}`",
                self.code, self.requested_model
            ),
            None => write!(
                formatter,
                "served_model_unknown: upstream omitted the model that served request `{}`",
                self.requested_model
            ),
        }
    }
}

impl std::error::Error for ServedModelError {}

/// Require an upstream to identify the served model and enforce strict
/// equality unless substitution was explicitly enabled for the credential.
pub fn validate_served_model(
    requested: &str,
    served: Option<&str>,
    allow_substitution: bool,
) -> Result<String, ServedModelError> {
    validate_served_model_for_selector(
        requested,
        served,
        allow_substitution,
        ModelSelectorKind::Concrete,
    )
}

/// Validate served identity with exact, evidence-backed selector semantics.
///
/// A provider or operator alias is itself the caller's explicit request for a
/// resolution policy. It may therefore resolve to another concrete id without
/// turning on the broader fallback/substitution setting. Unknown selectors are
/// deliberately treated as concrete and fail closed.
pub fn validate_served_model_for_selector(
    requested: &str,
    served: Option<&str>,
    allow_substitution: bool,
    selector_kind: ModelSelectorKind,
) -> Result<String, ServedModelError> {
    let served = served
        .filter(|model| !model.is_empty())
        .ok_or_else(|| ServedModelError {
            code: "served_model_unknown".to_string(),
            requested_model: requested.to_string(),
            served_model: None,
        })?;
    // With no requested selector there is nothing to substitute, but the
    // upstream still has to identify the concrete model that served.  This is
    // how an intentionally unpinned credential remains truthful without
    // turning an omitted selector into a Router-chosen default.
    if !requested.is_empty()
        && served != crate::thinking::base_model(requested)
        && !allow_substitution
        && !selector_kind.permits_resolution()
    {
        return Err(ServedModelError {
            code: "model_substitution_not_allowed".to_string(),
            requested_model: requested.to_string(),
            served_model: Some(served.to_string()),
        });
    }
    Ok(served.to_string())
}

/// Read a concrete model identity from a translated upstream object.
///
/// The supported locations are upstream protocol fields, not Router-private
/// metadata. Callers validate this before reshaping the object so a translator
/// never has to invent an identity merely to satisfy its output schema.
#[must_use]
pub fn served_model_from(payload: &serde_json::Value) -> Option<&str> {
    [
        "/model",
        "/modelVersion",
        "/response/model",
        "/response/modelVersion",
        "/message/model",
    ]
    .into_iter()
    .find_map(|pointer| {
        payload
            .pointer(pointer)
            .and_then(serde_json::Value::as_str)
            .filter(|model| !model.is_empty())
    })
}

/// Validate identity for every translated response.
///
/// Unpinned credentials may omit a request selector, but the translated
/// upstream must still prove the concrete model that served. A differing
/// non-empty selector is accepted only when substitution was explicitly
/// enabled on the credential.
pub fn validate_translated_response(
    requested: &str,
    payload: &serde_json::Value,
    policy: &ModelAccessPolicy,
) -> Result<Option<String>, ServedModelError> {
    validate_served_model(
        requested,
        served_model_from(payload),
        policy.allow_substitution,
    )
    .map(Some)
}

/// Validate a translated response with catalog-proven selector semantics.
pub fn validate_translated_response_for_selector(
    requested: &str,
    payload: &serde_json::Value,
    policy: &ModelAccessPolicy,
    selector_kind: ModelSelectorKind,
) -> Result<Option<String>, ServedModelError> {
    validate_served_model_for_selector(
        requested,
        served_model_from(payload),
        policy.allow_substitution,
        selector_kind,
    )
    .map(Some)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every spelling Router has emitted — and one it has not yet — parses
    /// through serde exactly as the hand-written catalog reader does, so a
    /// single row can never fail a typed catalog again (issue #620).
    #[test]
    fn selector_kind_has_one_forward_compatible_wire_contract() {
        let cases = [
            ("concrete", ModelSelectorKind::Concrete),
            ("provider_advertised_exact_id", ModelSelectorKind::Concrete),
            (
                "provider_dynamic_alias",
                ModelSelectorKind::ProviderDynamicAlias,
            ),
            (
                "provider_advertised_alias",
                ModelSelectorKind::ProviderDynamicAlias,
            ),
            ("operator_alias", ModelSelectorKind::OperatorAlias),
            ("unknown", ModelSelectorKind::Unknown),
            ("a_kind_from_a_future_release", ModelSelectorKind::Unknown),
        ];
        for (wire, expected) in cases {
            let value = serde_json::Value::String(wire.into());
            assert_eq!(ModelSelectorKind::from_wire(wire), expected, "{wire}");
            assert_eq!(
                ModelSelectorKind::from_catalog_value(Some(&value)),
                expected,
                "{wire}"
            );
            assert_eq!(
                serde_json::from_value::<ModelSelectorKind>(value).unwrap(),
                expected,
                "{wire}"
            );
        }
        assert_eq!(
            serde_json::from_value::<ModelSelectorKind>(serde_json::Value::Null).unwrap(),
            ModelSelectorKind::Unknown
        );
        for kind in [
            ModelSelectorKind::Concrete,
            ModelSelectorKind::ProviderDynamicAlias,
            ModelSelectorKind::OperatorAlias,
            ModelSelectorKind::Unknown,
        ] {
            assert_eq!(serde_json::to_value(kind).unwrap(), kind.as_wire());
            assert_eq!(ModelSelectorKind::from_wire(kind.as_wire()), kind);
        }
    }

    #[test]
    fn exact_policy_is_case_sensitive_and_fail_closed() {
        let policy = ModelAccessPolicy::exact("provider/model-v1");
        assert!(policy.permits("provider/model-v1"));
        assert!(!policy.permits("provider/Model-v1"));
        assert!(!policy.permits("model-v1"));
    }

    #[test]
    fn substitution_requires_a_durable_configuration_source() {
        let mut policy = ModelAccessPolicy::exact("provider/model-v1");
        policy.allow_substitution = true;
        assert_eq!(
            policy.validate().unwrap_err(),
            "enabled model substitution must name its configuration source"
        );

        policy.substitution_source = Some("router with --allow-model-substitution".into());
        assert!(policy.validate().is_ok());

        policy.allow_substitution = false;
        assert_eq!(
            policy.validate().unwrap_err(),
            "a substitution source requires model substitution to be enabled"
        );
    }

    #[test]
    fn served_identity_requires_explicit_substitution() {
        let denied = validate_served_model("requested", Some("actual"), false).unwrap_err();
        assert_eq!(denied.code, "model_substitution_not_allowed");
        assert_eq!(
            validate_served_model("requested", Some("actual"), true).unwrap(),
            "actual"
        );
        assert_eq!(
            validate_served_model("requested", None, true)
                .unwrap_err()
                .code,
            "served_model_unknown"
        );
    }

    #[test]
    fn empty_outer_identity_does_not_hide_a_concrete_protocol_identity() {
        let payload = serde_json::json!({
            "model": null,
            "response": {"model": "served-exact"}
        });
        assert_eq!(served_model_from(&payload), Some("served-exact"));
    }

    #[test]
    fn only_explicit_alias_metadata_permits_provider_resolution() {
        assert_eq!(
            validate_served_model_for_selector(
                "auto-review",
                Some("model-b"),
                false,
                ModelSelectorKind::ProviderDynamicAlias,
            )
            .unwrap(),
            "model-b"
        );
        for kind in [ModelSelectorKind::Concrete, ModelSelectorKind::Unknown] {
            assert_eq!(
                validate_served_model_for_selector("auto-review", Some("model-b"), false, kind)
                    .unwrap_err()
                    .code,
                "model_substitution_not_allowed"
            );
        }
        assert_eq!(
            ModelSelectorKind::from_catalog_value(Some(&serde_json::json!(
                "provider_dynamic_alias"
            ))),
            ModelSelectorKind::ProviderDynamicAlias
        );
        assert_eq!(
            ModelSelectorKind::from_catalog_value(Some(&serde_json::json!("looks-auto"))),
            ModelSelectorKind::Unknown
        );
    }

    #[test]
    fn pinned_translated_response_must_prove_identity() {
        let policy = ModelAccessPolicy::exact("model-a");
        let mismatch = validate_translated_response(
            "model-a",
            &serde_json::json!({"model": "model-b"}),
            &policy,
        )
        .unwrap_err();
        assert_eq!(mismatch.code, "model_substitution_not_allowed");
        assert_eq!(
            validate_translated_response("model-a", &serde_json::json!({}), &policy)
                .unwrap_err()
                .code,
            "served_model_unknown"
        );
    }

    #[test]
    fn unpinned_translated_response_still_requires_concrete_identity() {
        let policy = ModelAccessPolicy::default();
        assert_eq!(
            validate_translated_response("", &serde_json::json!({}), &policy)
                .unwrap_err()
                .code,
            "served_model_unknown"
        );
        assert_eq!(
            validate_translated_response(
                "",
                &serde_json::json!({"modelVersion": "provider/model"}),
                &policy,
            )
            .unwrap(),
            Some("provider/model".to_string())
        );
    }
}

//! Provider-observation provenance attached before catalog projection.

use serde_json::Map;
use serde_json::Value;

pub fn annotate_live_catalog(
    raw: &mut Map<String, Value>,
    source_url: &str,
    endpoint: &str,
    account: &str,
    protocols: &[&str],
) {
    let fetched_at = crate::operation_context::now().to_rfc3339();
    raw.insert("router_source_url".into(), Value::String(source_url.into()));
    raw.insert("router_endpoint".into(), Value::String(endpoint.into()));
    raw.insert("router_account".into(), Value::String(account.into()));
    raw.insert("router_protocols".into(), crate::translation_core::json!(protocols));
    raw.insert(
        "router_fetched_at".into(),
        Value::String(fetched_at.clone()),
    );
    raw.insert("router_health_generation".into(), Value::String(fetched_at));
}

//! Authenticated single-model retrieval from native or fresh live catalogs.

use axum::body::{Body, Bytes};
use axum::extract::{OriginalUri, Path, State};
use axum::http::{HeaderMap, HeaderValue, StatusCode, Uri};
use axum::response::{IntoResponse, Response};
use futures_util::StreamExt;

use crate::app_state::AppState;
use crate::route_contract::ApiDialect;

pub async fn retrieve(
    State(state): State<AppState>,
    Path(model_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Response {
    let dialect = crate::route_contract::dialect_for_path(uri.path()).unwrap_or(ApiDialect::OpenAi);
    let claims = match crate::proxy::authenticate_client_error(&state, &headers) {
        Ok(claims) => claims,
        Err(error) => return error.render(dialect),
    };
    let (client, _) = match crate::client_policy::bound_client(&claims) {
        Ok(bound) => bound,
        Err(error) => {
            return error_response(dialect, StatusCode::FORBIDDEN, "permission_error", &error);
        }
    };
    if !valid_model_id(&model_id)
        || !crate::client_policy::request_evidence(
            client,
            crate::client_policy::ClientProtocol::Catalog,
            uri.path(),
            &headers,
        )
    {
        return model_not_found(dialect, &model_id);
    }

    let listed = crate::model_routing::models(
        State(state.clone()),
        OriginalUri(uri.clone()),
        headers.clone(),
    )
    .await;
    if !listed.status().is_success() {
        return listed;
    }
    let bytes = match axum::body::to_bytes(listed.into_body(), state.max_proxy_request_bytes).await
    {
        Ok(bytes) => bytes,
        Err(error) => {
            return error_response(
                dialect,
                StatusCode::BAD_GATEWAY,
                "api_error",
                &format!("model catalog response is too large: {error}"),
            );
        }
    };
    let catalog: serde_json::Value = match serde_json::from_slice(&bytes) {
        Ok(catalog) => catalog,
        Err(error) => {
            return error_response(
                dialect,
                StatusCode::BAD_GATEWAY,
                "api_error",
                &format!("model catalog response is invalid: {error}"),
            );
        }
    };
    let Some(entry) = catalog
        .get("data")
        .and_then(serde_json::Value::as_array)
        .and_then(|models| {
            models.iter().find(|model| {
                model.get("id").and_then(serde_json::Value::as_str) == Some(&model_id)
            })
        })
        .cloned()
    else {
        return model_not_found(dialect, &model_id);
    };

    if uri.path().starts_with("/api/services/openai/")
        && let Some(response) =
            retrieve_openai_native(&state, client, &headers, &model_id, &entry, &uri).await
    {
        return response;
    }
    project_catalog_entry(dialect, entry)
}

async fn retrieve_openai_native(
    state: &AppState,
    client: crate::clients::ClientKind,
    headers: &HeaderMap,
    model_id: &crate::translation_core::Str,
    entry: &crate::translation_core::Json,
    uri: &Uri,
) -> crate::translation_core::Maybe<Response> {
    let owner = entry.get("owned_by").and_then(serde_json::Value::as_str)?;
    let provider = state.provider_store.resolve(owner).ok().flatten()?;
    if provider.kind != crate::providers::ProviderKind::OpenAICompatible
        || !provider.supports_client(client)
    {
        return None;
    }
    let api_key = provider.api_key.as_deref()?;
    let path = format!(
        "/v1/models/{}",
        crate::responses_lifecycle::percent_encode_segment(model_id)
    );
    let path = uri
        .query()
        .map_or_else(|| path.clone(), |query| format!("{path}?{query}"));
    let client =
        crate::upstream_client::guarded_provider_client(&state.client, &provider.base_url).ok()?;
    let request = client
        .get(crate::provider_proxy::join_openai_compatible_url(
            &provider.base_url,
            &path,
        ))
        .headers(crate::proxy::native_request_headers(headers, api_key));
    let correlation_id = crate::request_log::correlation_id(headers);
    let Ok(upstream) = state
        .request_log
        .send_upstream(&correlation_id, client, request)
        .await
    else {
        return None;
    };
    if matches!(
        upstream.status(),
        reqwest::StatusCode::NOT_FOUND
            | reqwest::StatusCode::METHOD_NOT_ALLOWED
            | reqwest::StatusCode::NOT_IMPLEMENTED
    ) {
        return None;
    }
    Some(
        bounded_native_response(state, upstream, &correlation_id)
            .await
            .unwrap_or_else(|message| {
                error_response(
                    ApiDialect::OpenAi,
                    StatusCode::BAD_GATEWAY,
                    "api_error",
                    &message,
                )
            }),
    )
}

async fn bounded_native_response(
    state: &AppState,
    upstream: reqwest::Response,
    correlation_id: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<Response, String> {
    let status = StatusCode::from_u16(upstream.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let headers = crate::proxy::relay_response_headers(upstream.headers());
    let mut stream = upstream.bytes_stream();
    let mut body = Vec::new();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|error| format!("upstream model response failed: {error}"))?;
        if body.len().saturating_add(chunk.len()) > state.max_proxy_request_bytes {
            return Err("upstream model response exceeds the proxy limit".into());
        }
        body.extend_from_slice(&chunk);
    }
    state
        .request_log
        .record_upstream_body(correlation_id, &body);
    state.metrics.record_request(
        crate::metrics::Surface::OpenAIResponses,
        status.as_u16(),
        None,
    );
    state.metrics.record_bytes(0, body.len() as u64);
    let mut response = Response::new(Body::from(Bytes::from(body)));
    *response.status_mut() = status;
    *response.headers_mut() = headers;
    Ok(response)
}

fn project_catalog_entry(dialect: ApiDialect, mut entry: crate::translation_core::Json) -> Response {
    let Some(model) = entry.as_object_mut() else {
        return error_response(
            dialect,
            StatusCode::BAD_GATEWAY,
            "api_error",
            "live model catalog contained a non-object entry",
        );
    };
    for private in ["canonical_id", "provider", "router_fetched_at"] {
        model.remove(private);
    }
    if dialect == ApiDialect::Anthropic {
        model.remove("object");
        model.remove("owned_by");
        model
            .entry("type")
            .or_insert_with(|| crate::translation_core::Json::String("model".into()));
        if let Some(id) = model
            .get("id")
            .and_then(crate::translation_core::Json::as_str)
            .map(str::to_string)
        {
            model
                .entry("display_name")
                .or_insert_with(|| crate::translation_core::Json::String(id));
        }
    } else {
        model
            .entry("object")
            .or_insert_with(|| crate::translation_core::Json::String("model".into()));
    }
    let mut response = axum::Json(entry).into_response();
    response
        .headers_mut()
        .insert("content-type", HeaderValue::from_static("application/json"));
    response
}

fn valid_model_id(model_id: &crate::translation_core::Str) -> bool {
    !model_id.is_empty()
        && model_id.len() <= 512
        && !model_id.contains('/')
        && !model_id.chars().any(char::is_control)
}

fn model_not_found(dialect: ApiDialect, model_id: &crate::translation_core::Str) -> Response {
    error_response(
        dialect,
        StatusCode::NOT_FOUND,
        if dialect == ApiDialect::Anthropic {
            "not_found_error"
        } else {
            "invalid_request_error"
        },
        &format!("model '{model_id}' was not found"),
    )
}

fn error_response(
    dialect: ApiDialect,
    status: StatusCode,
    error_type: &crate::translation_core::Str,
    message: &crate::translation_core::Str,
) -> Response {
    crate::api_error::PresentedError {
        status,
        error_type,
        message,
    }
    .render(dialect)
}

