/// Consume an automatic Anthropic-surface request and return its concrete state.
pub async fn route_anthropic_request(
    state: &AppState,
    request: Request,
) -> Result<(AppState, Request), Response> {
    route_anthropic_request_with_subscription(state, request)
        .await
        .map(|(routed, request)| (routed.state, request))
}

pub(crate) async fn route_anthropic_request_with_subscription(
    state: &AppState,
    request: Request,
) -> Result<(RoutedState, Request), Response> {
    route_anthropic_request_with_subscription_for_providers(
        state,
        request,
        &SubscriptionProvider::ALL,
    )
    .await
}

pub(crate) async fn route_anthropic_request_with_subscription_for_providers(
    state: &AppState,
    request: Request,
    entitled_providers: &[SubscriptionProvider],
) -> Result<(RoutedState, Request), Response> {
    let path = request.uri().path().to_string();
    let (parts, body) = request.into_parts();
    let body_bytes = axum::body::to_bytes(body, state.max_proxy_request_bytes)
        .await
        .map_err(|error| {
            crate::proxy::error_response(
                StatusCode::PAYLOAD_TOO_LARGE,
                "invalid_request_error",
                &format!(
                    "request body exceeds the {} byte proxy limit: {error}",
                    state.max_proxy_request_bytes
                ),
            )
        })?;
    let routing_body = serde_json::from_slice(&body_bytes).map_err(|error| {
        crate::proxy::error_response(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &format!("Failed to parse request body as JSON: {error}"),
        )
    })?;
    let routed = if path.ends_with("/messages") || path.ends_with("/messages/count_tokens") {
        let claims = crate::proxy::authenticate_client(state, &parts.headers)
            .map_err(|response| *response)?;
        let client = crate::client_policy::bound_client(&claims)
            .map(|(client, _)| client)
            .map_err(|error| {
                crate::proxy::error_response(StatusCode::FORBIDDEN, "permission_error", &error)
            })?;
        let owner =
            crate::response_affinity::ResponseOwner::from_claims(&claims).map_err(|message| {
                crate::proxy::error_response(StatusCode::FORBIDDEN, "permission_error", &message)
            })?;
        let resource_destination =
            anthropic_message_resource_destination(state, &owner, &routing_body)?;
        let mut routed = route_state_with_subscription_for_client(
            state,
            &routing_body,
            entitled_providers,
            Some(client),
            crate::zai_coding_plan::authorize_automatic_discovery(
                state,
                &claims,
                &parts.headers,
                crate::client_policy::ClientProtocol::AnthropicMessages,
                &path,
            ),
        )
        .await
        .map_err(|error| model_route_error_response(&error))?;
        if let Some(crate::response_affinity::AffinityDestination::Subscription {
            provider: SubscriptionProvider::Claude,
            account,
            upstream_account_id,
            base_url,
        }) = resource_destination
        {
            let subscription = routed
                .subscription
                .as_ref()
                .filter(|subscription| subscription.provider == SubscriptionProvider::Claude)
                .ok_or_else(|| {
                    crate::proxy::error_response(
                        StatusCode::CONFLICT,
                        "invalid_request_error",
                        "Anthropic native resources cannot be used on the selected provider",
                    )
                })?;
            let bound = subscription
                .bind_to_account(state, &account)
                .await
                .map_err(|_| {
                    crate::proxy::error_response(
                        StatusCode::SERVICE_UNAVAILABLE,
                        "api_error",
                        "the Anthropic native resource account cannot serve this request",
                    )
                })?;
            let selected = bound
                .selected_token()
                .expect("an exact resource account snapshot is ready");
            let current_base = state
                .subscription_base_url
                .clone()
                .unwrap_or_else(|| selected.base_url(SubscriptionProvider::Claude));
            if selected.account_id != upstream_account_id
                || current_base.trim_end_matches('/') != base_url.trim_end_matches('/')
            {
                return Err(crate::proxy::error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "api_error",
                    "the Anthropic native resource authority changed",
                ));
            }
            routed.subscription = Some(bound);
            routed.state.upstream_provider = UpstreamProvider::Anthropic;
            routed.state.account_router = None;
        }
        routed
    } else {
        route_pinned_subscription(state, SubscriptionProvider::Claude)
            .await
            .map_err(|error| {
                crate::proxy::error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_request_error",
                    &error.to_string(),
                )
            })?
    };
    Ok((routed, Request::from_parts(parts, Body::from(body_bytes))))
}

