//! Exact-ID collision handling shared by every model catalog source.

use serde_json::Value;

use crate::model_catalog::CatalogRecord;

use super::{ModelRouteError, provider_owner};

pub(super) fn project_record(record: CatalogRecord) -> Value {
    let exposed_id = record.canonical_id.clone();
    let mut projected = record.raw;
    projected.insert("id".into(), Value::String(exposed_id));
    let upstream = projected
        .remove("_router_policy_upstream")
        .unwrap_or_else(|| Value::String(record.canonical_id.clone()));
    projected.insert("canonical_id".into(), upstream);
    projected.insert(
        "provider".into(),
        Value::String(record.provider.as_str().to_string()),
    );
    projected
        .entry("object")
        .or_insert_with(|| Value::String("model".into()));
    projected.insert("router_fetched_at".into(), Value::from(record.fetched_at));
    projected
        .entry("owned_by")
        .or_insert_with(|| Value::String(provider_owner(record.provider).to_string()));
    Value::Object(projected)
}

pub(super) fn conflict(catalog: &Value) -> Option<ModelRouteError> {
    let ids = catalog
        .get("catalog_conflicts")
        .and_then(Value::as_array)
        .filter(|ids| !ids.is_empty())?;
    Some(ModelRouteError::Conflict(format!(
        "exact model id collision across healthy providers: {}",
        ids.iter()
            .filter_map(Value::as_str)
            .collect::<Vec<_>>()
            .join(", ")
    )))
}

/// Insert one provider-advertised model without resolving exact-ID collisions
/// by provider order. Conflicting candidates leave the routable `data` set and
/// remain available only to the authenticated diagnostics surface.
pub fn insert_candidate(catalog: &mut Value, candidate: Value) {
    let Some(id) = candidate
        .get("id")
        .and_then(Value::as_str)
        .filter(|id| !id.is_empty())
        .map(str::to_string)
    else {
        return;
    };
    let Some(object) = catalog.as_object_mut() else {
        return;
    };
    let already_conflicted = object
        .get("catalog_conflicts")
        .and_then(Value::as_array)
        .is_some_and(|conflicts| conflicts.iter().any(|conflict| conflict == &id));
    if already_conflicted {
        object
            .entry("catalog_conflict_candidates")
            .or_insert_with(|| Value::Array(Vec::new()))
            .as_array_mut()
            .expect("catalog conflict candidates are an array")
            .push(candidate);
        return;
    }
    let existing = object
        .get_mut("data")
        .and_then(Value::as_array_mut)
        .and_then(|data| {
            data.iter()
                .position(|entry| entry.get("id").and_then(Value::as_str) == Some(&id))
                .map(|position| data.remove(position))
        });
    let Some(existing) = existing else {
        object
            .entry("data")
            .or_insert_with(|| Value::Array(Vec::new()))
            .as_array_mut()
            .expect("catalog data are an array")
            .push(candidate);
        return;
    };
    let conflicts = object
        .entry("catalog_conflicts")
        .or_insert_with(|| Value::Array(Vec::new()))
        .as_array_mut()
        .expect("catalog conflicts are an array");
    conflicts.push(Value::String(id));
    conflicts.sort_by(|left, right| left.as_str().cmp(&right.as_str()));
    let candidates = object
        .entry("catalog_conflict_candidates")
        .or_insert_with(|| Value::Array(Vec::new()))
        .as_array_mut()
        .expect("catalog conflict candidates are an array");
    candidates.push(existing);
    candidates.push(candidate);
}

/// Project one selected account's exact record through the model-truth contract.
pub fn thinking_model_truth(record: &CatalogRecord) -> crate::model_contract::ModelTruthDescriptor {
    let raw = project_record(record.clone());
    let projected = super::aggregate::project_model(
        raw.as_object().expect("record projection is an object"),
        &record.canonical_id,
    );
    let provenance = projected
        .get("capability_provenance")
        .cloned()
        .unwrap_or(Value::Null);
    crate::model_contract::ModelTruthDescriptor {
        upstream_request_model: Some(record.canonical_id.clone()),
        route: serde_json::from_value(provenance["scope"].clone()).unwrap_or_default(),
        capabilities: Value::Object(projected),
        capability_provenance: provenance,
        ..crate::model_contract::ModelTruthDescriptor::default()
    }
}

use super::{
    AppState, HeaderMap, IntoResponse, OriginalUri, Response, State, StatusCode,
    SubscriptionProvider, UpstreamProvider, append_stored_provider_models, append_zai_models,
    catalog_conflict, configured_catalog_snapshot, json, merge_configured_degradation,
    model_catalog_with, model_route_error_response, principal_catalog_records,
};

/// Canonical `GET /api/services/*/v1/models` catalogs across automatic or
/// explicitly pinned providers.
pub async fn models(
    State(state): State<AppState>,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Response {
    let claims = match crate::proxy::authenticate_client(&state, &headers) {
        Ok(claims) => claims,
        Err(response) => return *response,
    };
    let path = uri.path();
    let diagnostics = headers
        .get("x-link-assistant-model-diagnostics")
        .and_then(|value| value.to_str().ok())
        == Some("1");
    let principal_accounts = claims.principal_id.clone().into_iter().collect::<Vec<_>>();

    let entitled = |provider| {
        crate::client_policy::enforce_subscription_for_claims(
            &state,
            &claims,
            &headers,
            provider,
            crate::client_policy::ClientProtocol::Catalog,
            path,
        )
    };

    let mut models = match state.upstream_provider {
        UpstreamProvider::Auto => {
            let snapshot = configured_catalog_snapshot(&state).await;
            let healthy = snapshot
                .healthy_providers()
                .into_iter()
                .filter(|provider| entitled(*provider).is_ok())
                .collect::<Vec<_>>();
            let mut catalog = model_catalog_with(&healthy, &state.model_catalogs, |provider| {
                principal_catalog_records(&state, provider, &principal_accounts)
            });
            // A revoked subscription is filtered out before `model_catalog`
            // ever sees it, so it could never reach `degraded_providers` and
            // simply vanished from `data`. Absence is not an alert: a monitor
            // cannot tell it from a provider that was never configured here
            // (issue #318).
            let visible_health = snapshot
                .health()
                .iter()
                .filter(|entry| entitled(entry.provider).is_ok())
                .cloned()
                .collect::<Vec<_>>();
            merge_configured_degradation(&visible_health, &mut catalog);
            if let Err(error) =
                append_stored_provider_models(&state, &claims, &headers, path, &mut catalog).await
            {
                return model_route_error_response(&error);
            }
            if let Err(error) =
                append_zai_models(&state, &claims, &headers, path, &mut catalog).await
            {
                return model_route_error_response(&error);
            }
            append_gonka_models(&state, &claims, &headers, path, &mut catalog).await;
            catalog
        }
        UpstreamProvider::Anthropic => {
            if let Err(response) = entitled(SubscriptionProvider::Claude) {
                return response;
            }
            model_catalog_with(
                &[SubscriptionProvider::Claude],
                &state.model_catalogs,
                |provider| principal_catalog_records(&state, provider, &principal_accounts),
            )
        }
        UpstreamProvider::Gonka => {
            let Some(gonka) = state.gonka.as_ref() else {
                return crate::proxy::error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "api_error",
                    crate::gonka::MISSING_API_KEY_MESSAGE,
                );
            };
            match gonka.live_catalog(&state.client).await {
                Ok(models) => crate::gonka::catalog_json(models),
                Err(error) => {
                    return crate::proxy::error_response(
                        StatusCode::SERVICE_UNAVAILABLE,
                        "api_error",
                        &error,
                    );
                }
            }
        }
        UpstreamProvider::Crater => crate::crater::list_models(),
        UpstreamProvider::Codex => {
            if let Err(response) = entitled(SubscriptionProvider::Codex) {
                return response;
            }
            model_catalog_with(
                &[SubscriptionProvider::Codex],
                &state.model_catalogs,
                |provider| principal_catalog_records(&state, provider, &principal_accounts),
            )
        }
        UpstreamProvider::Qwen => {
            if let Err(response) = entitled(SubscriptionProvider::Qwen) {
                return response;
            }
            model_catalog_with(
                &[SubscriptionProvider::Qwen],
                &state.model_catalogs,
                |provider| principal_catalog_records(&state, provider, &principal_accounts),
            )
        }
        UpstreamProvider::Gemini => {
            if let Err(response) = entitled(SubscriptionProvider::Gemini) {
                return response;
            }
            model_catalog_with(
                &[SubscriptionProvider::Gemini],
                &state.model_catalogs,
                |provider| principal_catalog_records(&state, provider, &principal_accounts),
            )
        }
        UpstreamProvider::OpenAICompatible => {
            let mut catalog = json!({"object": "list", "data": []});
            if let Err(error) =
                append_stored_provider_models(&state, &claims, &headers, path, &mut catalog).await
            {
                return model_route_error_response(&error);
            }
            catalog
        }
        UpstreamProvider::ZaiCodingPlan => {
            let mut catalog = json!({"object": "list", "data": []});
            if let Err(error) =
                append_zai_models(&state, &claims, &headers, path, &mut catalog).await
            {
                return model_route_error_response(&error);
            }
            catalog
        }
    };
    let policy = match crate::proxy::model_policy_for_claims(&state, &claims) {
        Ok(policy) => policy,
        Err(error) => {
            return crate::proxy::error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "model_policy_unavailable",
                &format!("could not read the credential model policy: {error}"),
            );
        }
    };
    apply_model_policy(&mut models, &policy);
    if !diagnostics && let Some(error) = catalog_conflict(&models) {
        return model_route_error_response(&error);
    }
    match super::native_catalog::project(path, uri.query(), &models) {
        Ok(Some(native)) => (StatusCode::OK, axum::Json(native)).into_response(),
        Ok(None) => (StatusCode::OK, axum::Json(models)).into_response(),
        Err(error) => crate::api_error::PresentedError {
            status: error.status,
            error_type: error.error_type,
            message: &error.message,
        }
        .render(crate::api_error::dialect_for_path(path)),
    }
}

/// Make discovery obey the same durable authority as inference. A pinned
/// credential must never learn about (and then let a client auto-select) a
/// model it cannot request. The Claude `[1m]` spelling is retained only when
/// its exact Anthropic base was live; the exposed id is changed to the exact
/// selector authorized by the token.
fn apply_model_policy(
    catalog: &mut serde_json::Value,
    policy: &crate::model_contract::ModelAccessPolicy,
) {
    let Some(object) = catalog.as_object_mut() else {
        return;
    };
    object.insert(
        "model_policy".into(),
        serde_json::to_value(policy).unwrap_or_else(|_| json!({})),
    );
    if policy.allowed_models.is_empty() {
        return;
    }
    let available = object
        .get("data")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    if let Some(candidates) = object
        .get_mut("catalog_conflict_candidates")
        .and_then(serde_json::Value::as_array_mut)
    {
        candidates.retain(|entry| {
            entry
                .get("canonical_id")
                .or_else(|| entry.get("id"))
                .and_then(serde_json::Value::as_str)
                .is_some_and(|id| policy.permits(id))
        });
    }
    let conflicting_ids = object
        .get("catalog_conflict_candidates")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|entry| entry.get("id").and_then(serde_json::Value::as_str))
        .map(str::to_string)
        .collect::<std::collections::HashSet<_>>();
    if let Some(conflicts) = object
        .get_mut("catalog_conflicts")
        .and_then(serde_json::Value::as_array_mut)
    {
        conflicts.retain(|entry| {
            entry
                .as_str()
                .is_some_and(|id| conflicting_ids.contains(id) || policy.permits(id))
        });
    }
    let mut visible = Vec::new();
    // Account aliases are authorized against their exact upstream identity.
    for entry in &available {
        let native = entry
            .get("canonical_id")
            .and_then(serde_json::Value::as_str);
        if native.is_some_and(|native| entry["id"] != native && policy.permits(native)) {
            visible.push(entry.clone());
        }
    }
    for allowed in &policy.allowed_models {
        if let Some(exact) = available.iter().find(|entry| {
            entry["id"] == *allowed
                && entry
                    .get("canonical_id")
                    .and_then(serde_json::Value::as_str)
                    .is_none_or(|native| policy.permits(native))
        }) {
            visible.push(exact.clone());
            continue;
        }
        let Some(base) = allowed.strip_suffix("[1m]") else {
            continue;
        };
        let Some(mut variant) = available
            .iter()
            .find(|entry| entry["id"] == base && entry["owned_by"].as_str() == Some("anthropic"))
            .cloned()
        else {
            continue;
        };
        if let Some(entry) = variant.as_object_mut() {
            entry.insert("id".into(), serde_json::Value::String(allowed.clone()));
            entry.insert(
                "selector_kind".into(),
                serde_json::Value::String(
                    crate::model_contract::ModelSelectorKind::OperatorAlias
                        .as_wire()
                        .into(),
                ),
            );
            entry.insert(
                "variant_of".into(),
                serde_json::Value::String(base.to_string()),
            );
        }
        visible.push(variant);
    }
    let mut seen = std::collections::HashSet::new();
    visible.retain(|entry| seen.insert(entry["id"].to_string()));
    object.insert("data".into(), serde_json::Value::Array(visible));
}

async fn append_gonka_models(
    state: &AppState,
    claims: &crate::token::TokenClaims,
    headers: &HeaderMap,
    path: &str,
    catalog: &mut serde_json::Value,
) {
    let Ok((client, _)) = crate::client_policy::bound_client(claims) else {
        return;
    };
    if !crate::gonka::supports_client(client)
        || !crate::client_policy::request_evidence(
            client,
            crate::client_policy::ClientProtocol::Catalog,
            path,
            headers,
        )
    {
        return;
    }
    let Some(gonka) = state.gonka.as_ref() else {
        return;
    };
    let Ok(models) = gonka.live_catalog(&state.client).await else {
        catalog_status(catalog, "gonka", false);
        return;
    };
    crate::gonka::merge_catalog(catalog, models);
    catalog_status(catalog, "gonka", true);
}

fn catalog_status(catalog: &mut serde_json::Value, provider: &str, healthy: bool) {
    let Some(object) = catalog.as_object_mut() else {
        return;
    };
    let field = if healthy {
        "healthy_providers"
    } else {
        "degraded_providers"
    };
    let entries = object
        .entry(field)
        .or_insert_with(|| serde_json::Value::Array(Vec::new()));
    if let Some(entries) = entries.as_array_mut()
        && !entries.iter().any(|entry| entry == provider)
    {
        entries.push(serde_json::Value::String(provider.to_string()));
    }
    if !healthy {
        let reasons = object
            .entry("degraded_reasons")
            .or_insert_with(|| serde_json::Value::Object(serde_json::Map::new()));
        if let Some(reasons) = reasons.as_object_mut() {
            reasons.insert(
                provider.to_string(),
                serde_json::Value::String("live Gonka catalog refresh failed".into()),
            );
        }
    }
}

/// Client-scoped normalized union of every currently routable model.
pub async fn aggregate_models(
    State(state): State<AppState>,
    OriginalUri(uri): OriginalUri,
    headers: HeaderMap,
) -> Response {
    let claims = match crate::proxy::authenticate_client(&state, &headers) {
        Ok(claims) => claims,
        Err(response) => return *response,
    };
    let Ok((client, _)) = crate::client_policy::bound_client(&claims) else {
        return crate::proxy::error_response(
            StatusCode::FORBIDDEN,
            "permission_error",
            "the token has no supported managed-client binding",
        );
    };

    let path = uri.path();
    if !crate::client_policy::request_evidence(
        client,
        crate::client_policy::ClientProtocol::Catalog,
        path,
        &headers,
    ) {
        return crate::proxy::error_response(
            StatusCode::FORBIDDEN,
            "permission_error",
            "request evidence does not match the token's managed-client binding",
        );
    }

    // Reuse the same authorization, health, principal, configured-provider,
    // and exact-ID collision pipeline as the native OpenAI-shaped catalog.
    let response = models(State(state), OriginalUri(uri), headers).await;
    if response.status() != StatusCode::OK {
        return response;
    }
    let (parts, body) = response.into_parts();
    let bytes = match axum::body::to_bytes(body, 16 * 1024 * 1024).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return crate::proxy::error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &format!("could not read aggregate catalog: {error}"),
            );
        }
    };
    let catalog: serde_json::Value = match serde_json::from_slice(&bytes) {
        Ok(catalog) => catalog,
        Err(error) => {
            return crate::proxy::error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &format!("could not normalize aggregate catalog: {error}"),
            );
        }
    };
    match super::aggregate::project_catalog(&catalog, client) {
        Ok(catalog) => (parts.status, axum::Json(catalog)).into_response(),
        Err(error) => model_route_error_response(&error),
    }
}

#[cfg(test)]
mod model_policy_tests {
    use super::*;

    #[test]
    fn pinned_catalog_contains_only_exact_authorized_selectors() {
        let mut catalog = json!({"object":"list","data":[
            {"id":"model-a","owned_by":"openai"},
            {"id":"model-b","owned_by":"openai"}
        ]});
        let policy = crate::model_contract::ModelAccessPolicy::exact("model-b");
        apply_model_policy(&mut catalog, &policy);
        assert_eq!(
            catalog["data"],
            json!([{"id":"model-b","owned_by":"openai"}])
        );
        assert_eq!(
            catalog["model_policy"]["allowed_models"],
            json!(["model-b"])
        );
    }

    #[test]
    fn anthropic_context_variant_is_exposed_as_the_authorized_selector() {
        let mut catalog = json!({"object":"list","data":[
            {"id":"claude-live","owned_by":"anthropic"},
            {"id":"compatible","owned_by":"other"}
        ]});
        let policy = crate::model_contract::ModelAccessPolicy::exact("claude-live[1m]");
        apply_model_policy(&mut catalog, &policy);
        assert_eq!(catalog["data"][0]["id"], "claude-live[1m]");
        assert_eq!(catalog["data"][0]["variant_of"], "claude-live");
        assert_eq!(catalog["data"][0]["selector_kind"], "operator_alias");
        let projected: crate::clients::RouterModel =
            serde_json::from_value(catalog["data"][0].clone()).unwrap();
        assert_eq!(
            projected.selector_kind,
            crate::model_contract::ModelSelectorKind::OperatorAlias
        );
    }
}

//! Deliberately small, provider-neutral model catalogue projection.

use std::collections::HashSet;

use serde_json::{Map, Value, json};

use crate::clients::ClientKind;
use crate::model_routing::ModelRouteError;

pub(super) fn project_catalog(
    catalog: &Value,
    _client: ClientKind,
) -> Result<Value, ModelRouteError> {
    let entries = catalog
        .get("data")
        .and_then(Value::as_array)
        .ok_or_else(|| ModelRouteError::NotFound("model catalog has no data array".into()))?;
    let mut seen = HashSet::new();
    let mut data = Vec::with_capacity(entries.len());
    for entry in entries {
        let Some(raw) = entry.as_object() else {
            continue;
        };
        let Some(id) = raw.get("id").and_then(Value::as_str) else {
            continue;
        };
        if !seen.insert(id.to_string()) {
            return Err(ModelRouteError::Conflict(format!(
                "exact model id collision across healthy providers: {id}"
            )));
        }
        data.push(Value::Object(project_model(raw, id)));
    }
    data.sort_by(|left, right| {
        left.get("id")
            .and_then(Value::as_str)
            .cmp(&right.get("id").and_then(Value::as_str))
    });
    let mut projected = Map::from_iter([
        ("object".into(), Value::String("list".into())),
        ("data".into(), Value::Array(data)),
    ]);
    for field in [
        "model_policy",
        "healthy_providers",
        "starting_providers",
        "degraded_providers",
        "degraded_reasons",
        "catalog_conflicts",
        "using_fallback",
    ] {
        if let Some(value) = catalog.get(field) {
            projected.insert(field.into(), value.clone());
        }
    }
    if let Some(candidates) = catalog
        .get("catalog_conflict_candidates")
        .and_then(Value::as_array)
    {
        let candidates = candidates
            .iter()
            .filter_map(Value::as_object)
            .filter_map(|raw| {
                let id = raw.get("id").and_then(Value::as_str)?;
                Some(Value::Object(project_model(raw, id)))
            })
            .collect::<Vec<_>>();
        projected.insert(
            "catalog_conflict_candidates".into(),
            Value::Array(candidates),
        );
    }
    Ok(Value::Object(projected))
}

pub(super) fn project_model(raw: &Map<String, Value>, id: &str) -> Map<String, Value> {
    let service = service(raw);
    let owner = raw
        .get("owned_by")
        .and_then(Value::as_str)
        .filter(|owner| !owner.is_empty())
        .unwrap_or(service);
    let mut projected = Map::from_iter([
        ("id".into(), Value::String(id.to_string())),
        ("service".into(), Value::String(service.to_string())),
        ("owned_by".into(), Value::String(owner.to_string())),
    ]);
    for field in ["selector_kind", "variant_of"] {
        if let Some(value) = raw.get(field) {
            projected.insert(field.into(), value.clone());
        }
    }
    super::native_catalog::copy_availability(raw, &mut projected);
    if let Some(fetched) = raw
        .get("router_fetched_at")
        .filter(|value| value.is_number() || value.is_string())
    {
        projected.insert("metadata_fetched_at".into(), fetched.clone());
    }
    if let Some(created) = raw.get("created").filter(|value| value.is_number()) {
        projected.insert("provider_created_at".into(), created.clone());
    }
    let source_kind = capability_source_kind(raw);
    if source_kind != "unknown" {
        project_capability_fields(raw, &mut projected);
    }
    let capability_fields = CAPABILITY_FIELDS
        .into_iter()
        .filter(|field| projected.contains_key(*field))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let source_url = raw.get("router_source_url").cloned().unwrap_or(Value::Null);
    let retrieved_at = raw.get("router_fetched_at").cloned().unwrap_or(Value::Null);
    let scope = json!({
        "provider": raw.get("provider").cloned().unwrap_or_else(|| Value::String(owner.to_string())),
        "account": raw.get("router_account").cloned().unwrap_or(Value::Null),
        "endpoint": raw.get("router_endpoint").cloned().unwrap_or(Value::Null),
        "protocols": raw.get("router_protocols").cloned().unwrap_or(Value::Null),
        "model": id,
    });
    let fields = capability_fields
        .iter()
        .map(|field| {
            let raw_field = capability_raw_field(raw, field);
            (
                field.clone(),
                json!({
                    "field": field,
                    "value": projected.get(field).cloned().unwrap_or(Value::Null),
                    "source_kind": source_kind,
                    "source_url": source_url.clone(),
                    "upstream_raw_field": raw_field,
                    "retrieved_at": retrieved_at.clone(),
                    "router_version": crate::VERSION,
                    "scope": scope.clone(),
                    "effective_restriction": "exact_model_record",
                    "conflict": false,
                    "unknown": source_kind == "unknown",
                }),
            )
        })
        .collect::<Map<_, _>>();
    projected.insert(
        "capability_provenance".into(),
        json!({
            "source_kind": source_kind,
            "source_url": source_url,
            "retrieved_at": retrieved_at,
            "scope": scope,
            "fields": fields,
        }),
    );
    projected
}

const CAPABILITY_FIELDS: [&str; 9] = [
    "context_window",
    "max_output_tokens",
    "modalities",
    "pricing",
    "deprecation_date",
    "default_reasoning_level",
    "supported_reasoning_levels",
    "client_capabilities",
    "thinking",
];

fn capability_source_kind(raw: &Map<String, Value>) -> &'static str {
    let nonempty = |field| {
        raw.get(field)
            .and_then(Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
    };
    let provider_is_known = nonempty("provider") || nonempty("owned_by");
    let protocols_are_exact = raw
        .get("router_protocols")
        .and_then(Value::as_array)
        .is_some_and(|protocols| {
            !protocols.is_empty()
                && protocols.iter().all(|protocol| {
                    protocol
                        .as_str()
                        .is_some_and(|value| !value.trim().is_empty())
                })
        });
    let retrieved_at_is_known = raw.get("router_fetched_at").is_some_and(|value| {
        value.is_number()
            || value
                .as_str()
                .is_some_and(|timestamp| !timestamp.trim().is_empty())
    });
    if provider_is_known
        && nonempty("router_account")
        && nonempty("router_endpoint")
        && protocols_are_exact
        && nonempty("router_source_url")
        && retrieved_at_is_known
    {
        "authenticated_live_catalog"
    } else {
        "unknown"
    }
}

fn project_capability_fields(raw: &Map<String, Value>, projected: &mut Map<String, Value>) {
    if let Some(thinking) = raw.get("thinking").filter(|value| value.is_object())
        && serde_json::from_value::<crate::thinking::ThinkingSupport>(thinking.clone())
            .is_ok_and(|support| support.has_facts())
    {
        projected.insert("thinking".into(), thinking.clone());
    }

    copy_first_number(
        raw,
        projected,
        "context_window",
        &[
            "context_window",
            "max_input_tokens",
            "inputTokenLimit",
            "input_token_limit",
            "context_length",
        ],
    );
    copy_first_number(
        raw,
        projected,
        "max_output_tokens",
        &[
            "max_output_tokens",
            "max_tokens",
            "outputTokenLimit",
            "output_token_limit",
        ],
    );
    if let Some(modalities) = normalized_modalities(raw) {
        projected.insert("modalities".into(), modalities);
    }
    if let Some(pricing) = normalized_pricing(raw) {
        projected.insert("pricing".into(), pricing);
    }
    if let Some(value) = ["deprecation_date", "deprecationDate"]
        .into_iter()
        .find_map(|key| raw.get(key))
        .filter(|value| value.is_string() || value.is_null())
    {
        projected.insert("deprecation_date".into(), value.clone());
    }
    if let Some(value) = raw
        .get("default_reasoning_level")
        .filter(|value| value.is_string())
    {
        projected.insert("default_reasoning_level".into(), value.clone());
    }
    if let Some(levels) = normalized_reasoning_levels(raw) {
        projected.insert("supported_reasoning_levels".into(), levels);
    }
    if let Some(capabilities) = raw.get("client_capabilities").and_then(Value::as_object) {
        projected.insert(
            "client_capabilities".into(),
            Value::Object(capabilities.clone()),
        );
    }
}

fn capability_raw_field<'a>(raw: &'a Map<String, Value>, field: &str) -> Option<&'a str> {
    let candidates: &[&str] = match field {
        "context_window" => &[
            "context_window",
            "max_input_tokens",
            "inputTokenLimit",
            "input_token_limit",
            "context_length",
        ],
        "max_output_tokens" => &[
            "max_output_tokens",
            "max_tokens",
            "outputTokenLimit",
            "output_token_limit",
        ],
        "modalities" => &[
            "modalities",
            "input_modalities",
            "supported_input_modalities",
            "output_modalities",
            "supported_output_modalities",
        ],
        "pricing" => &["pricing", "input_per_mtok", "output_per_mtok", "currency"],
        "deprecation_date" => &["deprecation_date", "deprecationDate"],
        "default_reasoning_level" => &["default_reasoning_level"],
        "supported_reasoning_levels" => &["supported_reasoning_levels"],
        "client_capabilities" => &["client_capabilities"],
        _ => &[],
    };
    candidates
        .iter()
        .copied()
        .find(|candidate| raw.contains_key(*candidate))
}

fn normalized_reasoning_levels(raw: &Map<String, Value>) -> Option<Value> {
    let levels = raw.get("supported_reasoning_levels")?.as_array()?;
    let normalized = levels
        .iter()
        .filter_map(Value::as_object)
        .filter_map(|level| {
            let effort = level.get("effort")?.as_str()?;
            let mut value = Map::from_iter([("effort".into(), Value::String(effort.to_string()))]);
            if let Some(description) = level.get("description").and_then(Value::as_str) {
                value.insert("description".into(), Value::String(description.to_string()));
            }
            Some(Value::Object(value))
        })
        .collect::<Vec<_>>();
    (!normalized.is_empty()).then_some(Value::Array(normalized))
}

fn service(raw: &Map<String, Value>) -> &str {
    match raw.get("provider").and_then(Value::as_str) {
        Some("claude") => "anthropic",
        Some("codex") => "codex",
        Some("gemini") => "gemini",
        Some("qwen") => "qwen",
        _ => raw
            .get("owned_by")
            .and_then(Value::as_str)
            .filter(|owner| !owner.is_empty())
            .unwrap_or("openai"),
    }
}

fn copy_first_number(
    raw: &Map<String, Value>,
    target: &mut Map<String, Value>,
    target_key: &str,
    source_keys: &[&str],
) {
    if let Some(value) = source_keys
        .iter()
        .find_map(|key| raw.get(*key))
        .filter(|value| value.is_number())
    {
        target.insert(target_key.to_string(), value.clone());
    }
}

fn normalized_modalities(raw: &Map<String, Value>) -> Option<Value> {
    if let Some(modalities) = raw.get("modalities").and_then(Value::as_object) {
        let mut normalized = Map::new();
        for key in ["input", "output"] {
            if let Some(values) = string_array(modalities.get(key)) {
                normalized.insert(key.into(), values);
            }
        }
        if !normalized.is_empty() {
            return Some(Value::Object(normalized));
        }
    }
    let mut normalized = Map::new();
    for (target, sources) in [
        ("input", ["input_modalities", "supported_input_modalities"]),
        (
            "output",
            ["output_modalities", "supported_output_modalities"],
        ),
    ] {
        if let Some(values) = sources
            .into_iter()
            .find_map(|source| string_array(raw.get(source)))
        {
            normalized.insert(target.into(), values);
        }
    }
    (!normalized.is_empty()).then_some(Value::Object(normalized))
}

fn string_array(value: Option<&Value>) -> Option<Value> {
    let values = value?.as_array()?;
    values
        .iter()
        .all(Value::is_string)
        .then(|| Value::Array(values.clone()))
}

fn normalized_pricing(raw: &Map<String, Value>) -> Option<Value> {
    let source = raw.get("pricing").and_then(Value::as_object).unwrap_or(raw);
    let mut pricing = Map::new();
    for key in ["input_per_mtok", "output_per_mtok", "currency"] {
        if let Some(value) = source
            .get(key)
            .filter(|value| value.is_string() || value.is_number())
        {
            pricing.insert(key.into(), value.clone());
        }
    }
    (!pricing.is_empty()).then_some(Value::Object(pricing))
}

