use super::{AppState, HeaderMap, ModelRouteError, UpstreamProvider, Value};

pub(super) async fn append_stored_provider_models(
    state: &AppState,
    claims: &crate::token::TokenClaims,
    headers: &HeaderMap,
    path: &str,
    catalog: &mut Value,
) -> Result<(), ModelRouteError> {
    let Ok((client, _)) = crate::client_policy::bound_client(claims) else {
        return Ok(());
    };
    if !crate::client_policy::request_evidence(
        client,
        crate::client_policy::ClientProtocol::Catalog,
        path,
        headers,
    ) {
        return Ok(());
    }
    let Ok(providers) = state.provider_store.list() else {
        return Ok(());
    };
    for record in providers.iter().filter(|record| {
        record.enabled
            && record.kind != crate::providers::ProviderKind::ZaiCodingPlan
            && (state.upstream_provider == UpstreamProvider::Auto
                || record.name == state.openai_compatible.provider_name)
            && record
                .effective_supported_clients()
                .iter()
                .any(|supported| supported == client.canonical_name())
    }) {
        let Ok(Some(provider)) = state.provider_store.resolve(&record.name) else {
            continue;
        };
        let Ok(live_models) =
            crate::provider_proxy::live_openai_compatible_catalog(state, &provider).await
        else {
            mark_provider_degraded(
                catalog,
                &provider.name,
                "live provider catalog refresh failed",
            );
            continue;
        };
        let exhaustion = state.provider_store.exhaustion(&provider.name);
        for model in live_models {
            let mut projected = model.raw;
            projected.insert("id".into(), Value::String(model.id));
            projected
                .entry("object")
                .or_insert_with(|| Value::String("model".into()));
            projected.insert("owned_by".into(), Value::String(provider.name.clone()));
            mark_row_unavailable(&mut projected, exhaustion.as_ref());
            super::insert_catalog_candidate(catalog, Value::Object(projected));
        }
        match exhaustion {
            Some(exhaustion) => {
                mark_provider_degraded(catalog, &provider.name, &exhaustion.summary());
            }
            None => mark_provider_healthy(catalog, &provider.name),
        }
    }
    Ok(())
}

/// Keep an exhausted account's rows listed — z.ai still lists them — but say
/// on each row that Router cannot currently serve it, and why (issue #657).
fn mark_row_unavailable(
    row: &mut serde_json::Map<String, Value>,
    exhaustion: Option<&crate::zai_upstream_error::ZaiExhaustion>,
) {
    if let Some(exhaustion) = exhaustion {
        row.insert("router_available".into(), Value::Bool(false));
        row.insert(
            "router_unavailable_reason".into(),
            Value::String(exhaustion.summary()),
        );
    }
}

fn mark_provider_degraded(catalog: &mut Value, provider: &str, reason: &str) {
    let Some(object) = catalog.as_object_mut() else {
        return;
    };
    let entries = object
        .entry("degraded_providers")
        .or_insert_with(|| Value::Array(Vec::new()));
    if let Some(entries) = entries.as_array_mut()
        && !entries.iter().any(|entry| entry == provider)
    {
        entries.push(Value::String(provider.to_string()));
    }
    let reasons = object
        .entry("degraded_reasons")
        .or_insert_with(|| Value::Object(serde_json::Map::new()));
    if let Some(reasons) = reasons.as_object_mut() {
        reasons.insert(provider.to_string(), Value::String(reason.into()));
    }
}

fn mark_provider_healthy(catalog: &mut Value, provider: &str) {
    let Some(object) = catalog.as_object_mut() else {
        return;
    };
    let entries = object
        .entry("healthy_providers")
        .or_insert_with(|| Value::Array(Vec::new()));
    if let Some(entries) = entries.as_array_mut()
        && !entries.iter().any(|entry| entry == provider)
    {
        entries.push(Value::String(provider.to_string()));
    }
}

/// Add only the healthy Coding Plan aliases authorized for this signed client.
pub(super) async fn append_zai_models(
    state: &AppState,
    claims: &crate::token::TokenClaims,
    headers: &HeaderMap,
    path: &str,
    catalog: &mut Value,
) -> Result<(), ModelRouteError> {
    let Ok(Some(provider)) = crate::zai_coding_plan::resolve(state) else {
        return Ok(());
    };
    let Ok((client, _)) =
        crate::zai_coding_plan::authorize_catalog(&provider, claims, headers, path)
    else {
        return Ok(());
    };
    let Ok(live_models) = crate::zai_coding_plan::live_catalog(state, &provider).await else {
        mark_provider_degraded(catalog, "z.ai", "live z.ai catalog refresh failed");
        return Ok(());
    };
    let exhaustion = state.provider_store.exhaustion(&provider.name);
    let registry = crate::zai_coding_plan::live_registry_for_client(client, &live_models)
        .map_err(ModelRouteError::NotFound)?;
    for (entry, live) in registry.into_iter().zip(live_models) {
        let mut projected = live.raw;
        projected.insert("id".into(), Value::String(entry.exposed_id));
        projected.insert(
            "router_protocols".into(),
            serde_json::json!([entry.protocol]),
        );
        projected.insert(
            "selector_kind".into(),
            // The canonical spelling, which every released wrapper parses
            // (issue #620); see `ModelSelectorKind`.
            Value::String(
                crate::model_contract::ModelSelectorKind::Concrete
                    .as_wire()
                    .into(),
            ),
        );
        projected
            .entry("object")
            .or_insert_with(|| Value::String("model".into()));
        projected
            .entry("owned_by")
            .or_insert_with(|| Value::String(entry.owner.into()));
        mark_row_unavailable(&mut projected, exhaustion.as_ref());
        super::insert_catalog_candidate(catalog, Value::Object(projected));
    }
    if let Some(exhaustion) = exhaustion {
        mark_provider_degraded(catalog, "z.ai", &exhaustion.summary());
        return Ok(());
    }
    if let Some(healthy) = catalog
        .get_mut("healthy_providers")
        .and_then(Value::as_array_mut)
        && !healthy.iter().any(|entry| entry == "z.ai")
    {
        healthy.push(Value::String("z.ai".into()));
    }
    Ok(())
}

/// The stored provider that declares `model`, when exactly one does.
///
/// Stored providers were reachable only by pinning `UPSTREAM_PROVIDER`, which
/// pins the *whole deployment* — so one router could serve vendor
/// subscriptions or a local OpenAI-compatible endpoint, never both (issue
/// #260). A provider that declares its models can now win a route in automatic
/// mode on the strength of that declaration.
///
pub(super) async fn stored_provider_for_model(
    state: &AppState,
    model: &str,
    client: Option<crate::clients::ClientKind>,
) -> Result<Option<crate::providers::ResolvedProvider>, ModelRouteError> {
    let Some(client) = client else {
        return Ok(None);
    };
    let Ok(providers) = state.provider_store.list() else {
        return Ok(None);
    };
    let mut declaring = Vec::new();
    for record in providers.into_iter().filter(|record| {
        record.enabled
            && record.kind != crate::providers::ProviderKind::ZaiCodingPlan
            && record
                .effective_supported_clients()
                .iter()
                .any(|supported| supported == client.canonical_name())
    }) {
        let Ok(Some(provider)) = state.provider_store.resolve(&record.name) else {
            continue;
        };
        let Ok(live) =
            crate::provider_proxy::live_openai_compatible_catalog(state, &provider).await
        else {
            continue;
        };
        if live.iter().any(|candidate| candidate.id == model) {
            declaring.push(provider);
        }
    }
    let Some(first) = declaring.first() else {
        return Ok(None);
    };
    if let Some(second) = declaring.get(1) {
        // The same rule subscriptions already follow: an ambiguous unqualified
        // name is refused rather than resolved by declaration order.
        return Err(ModelRouteError::Conflict(format!(
            "exact model id '{model}' is declared by multiple stored providers ({}, {})",
            first.name, second.name
        )));
    }
    Ok(Some(first.clone()))
}

/// Point `state` at a stored provider for this request only.
pub(super) fn route_stored_provider(
    state: &AppState,
    provider: &crate::providers::ResolvedProvider,
    model: &str,
) -> AppState {
    let mut routed = state.clone();
    routed.upstream_provider = if provider.kind == crate::providers::ProviderKind::ZaiCodingPlan {
        UpstreamProvider::ZaiCodingPlan
    } else {
        UpstreamProvider::OpenAICompatible
    };
    routed
        .openai_compatible
        .provider_name
        .clone_from(&provider.name);
    routed.bridge_model = Some(model.to_string());
    routed
}

/// Preserve the exact model id returned by the provider catalog.
#[must_use]
pub const fn bare_model_id(model: &str) -> &str {
    model
}

use serde_json::Value;

use super::{
    AppState, ModelRouteError, RoutedState, UpstreamProvider, route_stored_provider,
    route_subscription_model_for_providers, stored_provider_for_model,
};

pub async fn route_state_with_subscription(
    state: &AppState,
    body: &Value,
) -> Result<RoutedState, ModelRouteError> {
    route_state_with_subscription_for_providers(
        state,
        body,
        &crate::subscription::SubscriptionProvider::ALL,
    )
    .await
}

pub async fn route_state_with_subscription_for_providers(
    state: &AppState,
    body: &Value,
    entitled_providers: &[crate::subscription::SubscriptionProvider],
) -> Result<RoutedState, ModelRouteError> {
    route_state_with_subscription_for_client(state, body, entitled_providers, None, false).await
}

pub async fn route_state_with_subscription_for_client(
    state: &AppState,
    body: &Value,
    entitled_providers: &[crate::subscription::SubscriptionProvider],
    client: Option<crate::clients::ClientKind>,
    zai_authorized: bool,
) -> Result<RoutedState, ModelRouteError> {
    if state.upstream_provider != UpstreamProvider::Auto {
        if let Some(provider) = state.upstream_provider.subscription_provider() {
            return super::route_pinned_subscription(state, provider).await;
        }
        return Ok(RoutedState {
            state: state.clone(),
            subscription: None,
        });
    }
    let model = body
        .get("model")
        .and_then(Value::as_str)
        .filter(|model| !model.is_empty())
        .ok_or(ModelRouteError::ModelRequired)?;
    if let Some(scope) = crate::account_policy_scope::current()
        && scope.context.model.as_deref() != Some(model)
        && scope.upstream_model == model
        && let Some(router) = state.account_router.as_ref()
        && entitled_providers.contains(&router.provider())
    {
        // An operator alias or account prefix already proved its exact account-owned model.
        return route_subscription_model_for_providers(state, model, &[router.provider()]).await;
    }
    let visible_subscription = entitled_providers.iter().any(|provider| {
        state
            .model_catalogs
            .models(*provider)
            .iter()
            .any(|candidate| candidate == model)
    });
    let stored = stored_provider_for_model(state, model, client).await?;
    let zai = crate::zai_coding_plan::live_provider_for_model(state, model, client, zai_authorized)
        .await?;
    // Gonka is merged after existing compatible catalogs and therefore owns
    // only an otherwise-unclaimed canonical id. The same precedence keeps the
    // de-duplicated catalog and dispatch decisions consistent.
    let gonka = if visible_subscription || stored.is_some() || zai.is_some() {
        false
    } else if client.is_some_and(crate::gonka::supports_client) {
        match state.gonka.as_ref() {
            Some(gonka) => gonka
                .live_catalog(&state.client)
                .await
                .is_ok_and(|models| models.iter().any(|candidate| candidate.id == model)),
            None => false,
        }
    } else {
        false
    };
    let owner_count = usize::from(visible_subscription)
        + usize::from(stored.is_some())
        + usize::from(zai.is_some())
        + usize::from(gonka);
    if owner_count > 1 {
        return Err(ModelRouteError::Conflict(format!(
            "exact model id '{model}' is advertised by more than one healthy provider"
        )));
    }
    if visible_subscription {
        return route_subscription_model_for_providers(state, model, entitled_providers).await;
    }
    if let Some(stored) = stored.or(zai) {
        return Ok(RoutedState {
            state: route_stored_provider(state, &stored, model),
            subscription: None,
        });
    }
    if gonka {
        let mut routed = state.clone();
        routed.upstream_provider = UpstreamProvider::Gonka;
        return Ok(RoutedState {
            state: routed,
            subscription: None,
        });
    }
    route_subscription_model_for_providers(state, model, entitled_providers)
        .await
        .map_err(|error| match error {
            ModelRouteError::NotFound(_) if !zai_authorized => {
                crate::zai_coding_plan::unproven_request_for_listed_model(state, model, client)
                    .map_or(error, ModelRouteError::Forbidden)
            }
            other => other,
        })
}

/// Compatibility wrapper returning only the routed state.
pub async fn route_state(state: &AppState, body: &Value) -> Result<AppState, ModelRouteError> {
    route_state_with_subscription(state, body)
        .await
        .map(|routed| routed.state)
}

//! Monitoring endpoints served on the proxy port.

use axum::extract::{Path, State};
use axum::http::{HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};

use crate::app_state::AppState;
use crate::proxy::{error_response, is_admin_authorised};

fn admin_required() -> Response {
    error_response(
        StatusCode::UNAUTHORIZED,
        "authentication_error",
        "admin credential required",
    )
}

/// `GET /metrics` — Prometheus text-exposition format.
///
/// Deliberately left open: it carries aggregate counters only, and scrapers
/// (Prometheus, container health checks) are typically unauthenticated.
pub async fn metrics_endpoint(State(state): State<AppState>) -> impl IntoResponse {
    let mut body = crate::metrics::render_prometheus(&state.metrics);
    // A dead subscription had no counter of its own, so no scrape could see it
    // (issue #318). Rendered here rather than in `metrics.rs` so the counter
    // registry stays free of subscription types.
    let health = crate::model_routing::configured_provider_health_report(&state).await;
    let mut gauges = health
        .iter()
        .map(|entry| (entry.provider.as_str(), entry.is_serving()))
        .collect::<Vec<_>>();
    if let Some(healthy) = crate::zai_coding_plan::configured_health(&state).await {
        gauges.push(("z.ai", healthy));
    }
    body.push_str(&crate::metrics::render_subscription_health(&gauges));
    body.push_str(&state.token_manager.diagnostics().render_prometheus());
    body.push_str(&state.token_manager.emergency().render_prometheus());
    if let Some(router) = state.account_router.as_ref() {
        body.push_str(&router.limit_counts().render_prometheus());
    }
    (
        StatusCode::OK,
        [("content-type", "text/plain; version=0.0.4")],
        body,
    )
        .into_response()
}

/// `GET /api/management/usage` — JSON usage snapshot. Requires an admin credential.
///
/// Unlike `/metrics`, this snapshot names individual tokens and accounts.
pub async fn usage_endpoint(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return admin_required();
    }
    let snap = crate::metrics::usage_snapshot(&state.metrics);
    (StatusCode::OK, axum::Json(snap)).into_response()
}

/// `GET /api/management/accounts` — admin-only health snapshot of configured accounts.
pub async fn accounts_endpoint(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return admin_required();
    }
    let Some(router) = state.account_router.as_ref() else {
        return (StatusCode::OK, axum::Json(single_account_view(&state))).into_response();
    };
    let snap: Vec<serde_json::Value> = router
        .health_snapshot_with(Some(&state.subscription_cache))
        .into_iter()
        .map(|health| {
            let mut value = serde_json::json!({
                "name": health.name,
                "home": health.home.display().to_string(),
                "healthy": health.healthy,
                "credential": health.credential.label(),
                "used": health.used,
                "request_limit": health.request_limit,
                "remaining_requests": health.remaining_requests,
                "last_error": health.last_error,
                "cooldown_remaining_seconds": health.cooldown_remaining.map(|d| d.as_secs()),
                "cooldown_reason": health.limits.cooldown_reason,
                "cooldown_until_unix": health.limits.cooldown_until_unix,
                "model_cooldowns": health.limits.model_cooldowns,
                "paused": health.limits.paused_at(crate::account_limits::now_unix()),
                "pause": health.limits.pause,
                "windows": health.limits.windows,
            });
            value.as_object_mut().expect("account object").extend(
                crate::account_policy_management::fields(router, &health.name)
                    .as_object()
                    .unwrap()
                    .clone(),
            );
            value
        })
        .collect();
    (
        StatusCode::OK,
        axum::Json(serde_json::json!({"accounts": snap})),
    )
        .into_response()
}

/// `POST /api/management/accounts/{name}/pause` — take a pooled account out of
/// rotation until it is resumed (issue #677).
///
/// An optional JSON body may carry
/// `until_unix` (lift on its own then) and `reason`. Admin-only.
pub async fn account_pause_endpoint(
    State(state): State<AppState>,
    Path(name): Path<String>,
    headers: HeaderMap,
    body: Option<axum::Json<serde_json::Value>>,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return admin_required();
    }
    let Some(router) = state.account_router.as_ref() else {
        return no_pool();
    };
    let body = body.map(|axum::Json(body)| body).unwrap_or_default();
    let until_unix = body.get("until_unix").and_then(serde_json::Value::as_u64);
    let reason = body
        .get("reason")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("paused by an operator");
    match router.pause(&name, until_unix, reason) {
        Ok(()) => (
            StatusCode::OK,
            axum::Json(
                serde_json::json!({"account": name, "paused": true, "until_unix": until_unix}),
            ),
        )
            .into_response(),
        Err(error) => error_response(StatusCode::NOT_FOUND, "not_found_error", &error.to_string()),
    }
}

/// `POST /api/management/accounts/{name}/resume` — lift a manual or threshold
/// pause (issue #677). Admin-only.
pub async fn account_resume_endpoint(
    State(state): State<AppState>,
    Path(name): Path<String>,
    headers: HeaderMap,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return admin_required();
    }
    let Some(router) = state.account_router.as_ref() else {
        return no_pool();
    };
    match router.resume(&name) {
        Ok(was_paused) => (
            StatusCode::OK,
            axum::Json(
                serde_json::json!({"account": name, "paused": false, "was_paused": was_paused}),
            ),
        )
            .into_response(),
        Err(error) => error_response(StatusCode::NOT_FOUND, "not_found_error", &error.to_string()),
    }
}

fn no_pool() -> Response {
    error_response(
        StatusCode::CONFLICT,
        "invalid_request_error",
        "no account pool is configured",
    )
}

/// `GET /api/management/auth/status` — provider-verified credential status.
pub async fn credential_status_endpoint(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return admin_required();
    }
    let catalog_override = state
        .upstream_provider
        .subscription_provider()
        .zip(state.subscription_base_url.as_deref());
    let reports = crate::credential_status::evaluate(
        &state.client,
        &state.subscription_cache,
        &state.subscription_readers,
        catalog_override,
    )
    .await;
    (
        StatusCode::OK,
        axum::Json(serde_json::json!({"credentials": reports})),
    )
        .into_response()
}

/// The credential this deployment holds when there is no account pool.
///
/// An empty `accounts` array used to be the whole answer here, which the CLI
/// could only read as "nothing is configured" — the same sentence it prints for
/// a deployment with no credential at all. A single-subscription router serving
/// traffic was therefore reported as unauthorized, pointing an operator at a
/// re-authentication it did not need (issue #281).
///
/// Each provider this deployment reads is named with the verdict the pooled
/// surfaces use, so both modes answer the question `auth status` actually asks.
/// `accounts` stays empty and keeps its meaning — *no account pool* — while
/// `credentials` carries the credential state, so a reader of either field
/// still gets what it expects.
///
/// Disk-only, like the pooled snapshot beside it: this is an admin `GET`, and
/// probing each vendor upstream would turn one request into several outbound
/// ones. `refreshable` already distinguishes "expired but recoverable" from
/// dead, which is the distinction the empty array was destroying.
fn single_account_view(state: &AppState) -> crate::translation_core::Json {
    let now_ms = crate::operation_context::now().timestamp_millis();
    let credentials: Vec<serde_json::Value> = state
        .subscription_readers
        .iter()
        .map(|reader| {
            let credential = crate::accounts::credential_state_of(
                reader,
                "primary",
                now_ms,
                Some(&state.subscription_cache),
            );
            crate::translation_core::json!({
                "name": reader.provider().to_string(),
                "home": reader.home().display().to_string(),
                "credential": credential.label(),
                "healthy": credential.can_serve(),
            })
        })
        .collect();
    crate::translation_core::json!({
        "accounts": [],
        "credentials": credentials,
        "note": "single-account mode (no AccountRouter configured)",
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::subscription::{SubscriptionProvider, SubscriptionReader};

    /// A single-account deployment names its credentials, not an empty pool.
    ///
    /// `accounts: []` alone could only be read as "nothing is configured", the
    /// same answer given for a deployment holding no credential at all — so a
    /// router serving live traffic was reported as unauthorized (issue #281).
    #[test]
    fn a_single_account_view_reports_each_provider() {
        let dir = tempfile::tempdir().expect("data dir");
        let home = tempfile::tempdir().expect("home");
        std::fs::write(
            home.path().join(".credentials.json"),
            serde_json::json!({
                "claudeAiOauth": {
                    "accessToken": "live-access",
                    "refreshToken": "live-refresh",
                    // Far enough out that the verdict cannot be a clock artefact.
                    "expiresAt": 4_102_444_800_000_i64,
                }
            })
            .to_string(),
        )
        .expect("plant a live credential");

        let mut state = AppState::for_tests(dir.path());
        state.subscription_readers = vec![
            SubscriptionReader::new(SubscriptionProvider::Claude, home.path()),
            SubscriptionReader::new(SubscriptionProvider::Codex, dir.path()),
        ];

        let view = single_account_view(&state);

        assert_eq!(
            view["accounts"].as_array().map(Vec::len),
            Some(0),
            "the pool is genuinely empty and keeps its meaning"
        );
        assert!(
            view["note"]
                .as_str()
                .is_some_and(|n| n.contains("single-account")),
            "the server keeps explaining why: {view}"
        );
        let credentials = view["credentials"].as_array().expect("credentials");
        assert_eq!(credentials.len(), 2, "{view}");
        assert_eq!(credentials[0]["name"], "claude");
        assert_eq!(
            credentials[0]["credential"], "ok",
            "a live credential must not read as missing: {view}"
        );
        assert_eq!(credentials[0]["healthy"], true);
        assert_eq!(
            credentials[1]["credential"], "missing",
            "and an absent one must still say so: {view}"
        );
        assert_eq!(credentials[1]["healthy"], false);
    }
}

//! Machine Payments Protocol helpers for paid OpenAI-compatible endpoints.
//!
//! MPP uses HTTP `402 Payment Required` plus a `WWW-Authenticate: Payment`
//! challenge. The router exposes this as an optional gate in front of the
//! `OpenAI` surface so agents can discover payment requirements without relying
//! on the ForgeFed/ActivityPub metadata path.

use axum::body::Body;
use axum::http::{HeaderValue, StatusCode};
use axum::response::{IntoResponse, Response};


/// Runtime configuration for MPP charge challenges.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MppConfig {
    /// Whether `OpenAI` endpoints should return MPP 402 challenges when the
    /// caller has not supplied a payment credential.
    pub enabled: bool,
    /// Price per `OpenAI` request, encoded as a decimal string.
    pub amount: String,
    /// ISO currency or payment-method-specific asset symbol.
    pub currency: String,
    /// Recipient wallet, merchant, account, or payment address.
    pub recipient: String,
    /// Optional payment method identifier, for example `tempo`, `stripe`, or
    /// `lightning`.
    pub method: Option<String>,
}

impl MppConfig {
    /// Return true when the config has enough data to challenge callers.
    #[must_use]
    pub fn is_configured(&self) -> bool {
        self.enabled
            && !self.amount.trim().is_empty()
            && !self.currency.trim().is_empty()
            && !self.recipient.trim().is_empty()
    }
}

/// Return true when the request carries an MPP payment credential.
#[must_use]
pub fn has_payment_credential(headers: &axum::http::HeaderMap) -> bool {
    headers
        .get("authorization")
        .and_then(|v| v.to_str().ok())
        .is_some_and(|v| v.trim_start().starts_with("Payment "))
}

/// Build an MPP `402 Payment Required` response for an unpaid endpoint.
#[must_use]
pub fn payment_required(config: &MppConfig, path: &crate::translation_core::Str) -> Response {
    let challenge = challenge_header(config, path);
    let mut resp = (
        StatusCode::PAYMENT_REQUIRED,
        axum::Json(crate::translation_core::json!({
            "type": "error",
            "error": {
                "type": "payment_required",
                "message": "Payment required for OpenAI-compatible endpoint",
                "protocol": "mpp",
                "intent": "charge",
                "amount": config.amount,
                "currency": config.currency,
                "recipient": config.recipient,
                "method": config.method,
                "resource": path,
            }
        })),
    )
        .into_response();

    resp.headers_mut()
        .insert("content-type", HeaderValue::from_static("application/json"));
    if let Ok(value) = HeaderValue::from_str(&challenge) {
        resp.headers_mut().insert("www-authenticate", value);
    }
    resp
}

fn challenge_header(config: &MppConfig, path: &crate::translation_core::Str) -> String {
    let mut params = vec![
        ("protocol", "mpp".to_string()),
        ("intent", "charge".to_string()),
        ("amount", config.amount.clone()),
        ("currency", config.currency.clone()),
        ("recipient", config.recipient.clone()),
        ("resource", path.to_string()),
    ];
    if let Some(method) = config.method.as_ref().filter(|s| !s.trim().is_empty()) {
        params.push(("method", method.clone()));
    }

    let encoded = params
        .into_iter()
        .map(|(k, v)| format!(r#"{k}="{}""#, escape_header_value(&v)))
        .collect::<Vec<_>>()
        .join(", ");
    format!("Payment {encoded}")
}

fn escape_header_value(value: &crate::translation_core::Str) -> String {
    value.replace('\\', r"\\").replace('"', r#"\""#)
}

/// Convert a consumed payment credential into a clear unsupported response.
///
/// Full settlement verification is method-specific and should be provided by
/// an MPP SDK or payment-method adapter. Until then, returning 501 is safer
/// than accepting unaudited payment proofs.
#[must_use]
pub fn unsupported_payment_verification() -> Response {
    let mut resp = Response::new(Body::from(
        crate::translation_core::json!({
            "type": "error",
            "error": {
                "type": "payment_verification_unavailable",
                "message": "MPP payment credential verification is not configured"
            }
        })
        .to_string(),
    ));
    *resp.status_mut() = StatusCode::NOT_IMPLEMENTED;
    resp.headers_mut()
        .insert("content-type", HeaderValue::from_static("application/json"));
    resp
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::http::HeaderMap;

    fn config() -> MppConfig {
        MppConfig {
            enabled: true,
            amount: "0.01".into(),
            currency: "USD".into(),
            recipient: "acct_123".into(),
            method: Some("stripe".into()),
        }
    }

    #[test]
    fn challenge_response_uses_http_402_and_payment_auth_scheme() {
        let resp = payment_required(&config(), "/v1/chat/completions");

        assert_eq!(resp.status(), StatusCode::PAYMENT_REQUIRED);
        let header = resp
            .headers()
            .get("www-authenticate")
            .and_then(|v| v.to_str().ok())
            .expect("challenge header");
        assert!(header.starts_with("Payment "));
        assert!(header.contains(r#"protocol="mpp""#));
        assert!(header.contains(r#"intent="charge""#));
        assert!(header.contains(r#"resource="/v1/chat/completions""#));
    }

    #[test]
    fn detects_payment_authorization_credentials() {
        let mut headers = HeaderMap::new();
        assert!(!has_payment_credential(&headers));

        headers.insert(
            "authorization",
            HeaderValue::from_static("Payment credential-token"),
        );
        assert!(has_payment_credential(&headers));
    }

    #[test]
    fn requires_enabled_and_charge_details() {
        assert!(config().is_configured());

        let mut missing = config();
        missing.recipient.clear();
        assert!(!missing.is_configured());
    }
}

//! Byte-transparent native vendor service forwarding.
//!
//! These endpoints are provider-owned resources and control-plane operations,
//! not inference translations. Router authenticates and binds an upstream
//! account, swaps only credentials, and leaves request/response bytes opaque.

use axum::body::{Body, Bytes};
use axum::extract::ws::{CloseFrame, Message, WebSocket, WebSocketUpgrade};
use axum::extract::{FromRequestParts, Request, State};
use axum::http::{HeaderMap, HeaderValue, Method, StatusCode};
use axum::response::{IntoResponse, Response};
use futures_util::{SinkExt, StreamExt};
use sha2::{Digest as _, Sha256};
use std::io::{Seek as _, Write as _};
use std::sync::Arc;
use tokio_tungstenite::tungstenite;
use tokio_tungstenite::tungstenite::client::IntoClientRequest as _;

use crate::app_state::AppState;
use crate::clients::ClientKind;
use crate::response_affinity::{
    AffinityDestination, ResponseAffinity, ResponseNamespace, ResponseOwner,
};
use crate::route_contract::{RouteId, route_for_path};
use crate::subscription::SubscriptionProvider;

const CONNECT_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(15);
type UpstreamWebSocket =
    tokio_tungstenite::WebSocketStream<tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>>;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Service {
    OpenAi,
    Anthropic,
    Codex,
    CodexBackend,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NativeResourceAction {
    Create,
    Use,
    Delete,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct NativeResourceRequest {
    namespace: ResponseNamespace,
    action: NativeResourceAction,
    id: Option<String>,
    parent_id: Option<String>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct NativeListRequest {
    namespace: ResponseNamespace,
    parent_id: Option<String>,
}

pub struct Target {
    pub client: reqwest::Client,
    pub url: String,
    pub headers: HeaderMap,
}

enum NativeRequestBody {
    Memory(Bytes),
    Spool {
        file: tempfile::NamedTempFile,
        len: usize,
    },
}

impl NativeRequestBody {
    const fn routing_bytes(&self) -> Option<&Bytes> {
        match self {
            Self::Memory(bytes) => Some(bytes),
            Self::Spool { .. } => None,
        }
    }

    const fn len(&self) -> usize {
        match self {
            Self::Memory(bytes) => bytes.len(),
            Self::Spool { len, .. } => *len,
        }
    }
}

pub async fn openai(State(state): State<AppState>, request: Request) -> Response {
    Box::pin(forward(state, request, Service::OpenAi)).await
}

pub async fn anthropic(State(state): State<AppState>, request: Request) -> Response {
    Box::pin(forward(state, request, Service::Anthropic)).await
}

pub async fn codex(State(state): State<AppState>, request: Request) -> Response {
    Box::pin(forward(state, request, Service::Codex)).await
}

pub async fn codex_backend(State(state): State<AppState>, request: Request) -> Response {
    Box::pin(forward(state, request, Service::CodexBackend)).await
}

async fn forward(state: AppState, request: Request, service: Service) -> Response {
    let method = request.method().clone();
    let uri = request.uri().clone();
    let path = uri.path();
    let Some(route) = route_for_path(&method, path).filter(|route| route_belongs(**route, service))
    else {
        return not_found();
    };
    if service == Service::CodexBackend && crate::codex_remote_control::is_remote_control_path(path)
    {
        return Box::pin(crate::codex_remote_control::forward(state, request)).await;
    }
    let mut headers = request.headers().clone();
    let claims = match crate::proxy::authenticate_client_error(&state, &headers) {
        Ok(claims) => claims,
        Err(error) => return error.render(route.dialect),
    };
    if service == Service::CodexBackend {
        let supported = crate::proxy::codex_carrier_accepted(
            &state,
            crate::proxy::extract_client_token(&headers),
        );
        if !supported {
            return error(
                StatusCode::UNAUTHORIZED,
                "authentication_error",
                "Codex backend routes require the paired Router-issued at- token",
            );
        }
    }
    if path == "/api/services/codex/v1/user-auth-credential/whoami" {
        return whoami(&state, &headers, &claims).await;
    }
    if path == "/api/services/codex/backend-api/wham/accounts/check" {
        return codex_accounts_check(&state, &headers, &claims).await;
    }
    if path == "/api/services/openai/v1/realtime/client_secrets" {
        return error(
            StatusCode::NOT_IMPLEMENTED,
            "unsupported_operation",
            "Router does not expose upstream Realtime client secrets",
        );
    }
    if let Err(response) = authorize_service(&state, &claims, service) {
        return response;
    }
    if let Err(error) = state.token_manager.enforce_request_budget(&claims.sub) {
        return crate::token_http::budget_error_response(&error);
    }
    let owner = match ResponseOwner::from_claims(&claims) {
        Ok(owner) => owner,
        Err(message) => return error(StatusCode::FORBIDDEN, "permission_error", &message),
    };
    if method == Method::GET && is_websocket(&headers) {
        let affinity = match realtime_sideband(service, path, uri.query()) {
            Ok(Some((namespace, call_id))) => {
                match state
                    .provider_store
                    .response_affinities()
                    .lookup(namespace, &call_id, &owner)
                {
                    Ok(Some(affinity)) => Some(affinity),
                    Ok(None) => {
                        return error(
                            StatusCode::NOT_FOUND,
                            "not_found_error",
                            "the Realtime call is unavailable",
                        );
                    }
                    Err(_) => return unavailable("Realtime call affinity is unavailable"),
                }
            }
            Ok(None) => None,
            Err(()) => {
                return error(
                    StatusCode::BAD_REQUEST,
                    "invalid_request_error",
                    "exactly one non-empty Realtime call_id is allowed",
                );
            }
        };
        let target = match target(
            &state,
            &headers,
            &claims,
            service,
            &uri,
            None,
            affinity.as_ref().map(|affinity| &affinity.destination),
        )
        .await
        {
            Ok((target, _)) => target,
            Err(response) => return response,
        };
        let Ok(policy) = crate::proxy::model_policy_for_claims(&state, &claims) else {
            return unavailable("model policy is unavailable");
        };
        return upgrade_websocket(state, request, target, Some((claims.sub, policy))).await;
    }
    let spool = headers
        .get("content-type")
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.to_ascii_lowercase().starts_with("multipart/"));
    let body = match collect_native_body(request.into_body(), state.max_proxy_request_bytes, spool)
        .await
    {
        Ok(body) => body,
        Err(response) => return response,
    };
    let body = if service == Service::Codex
        && method == Method::POST
        && matches!(
            path,
            "/api/services/codex/v1/realtime/calls" | "/api/services/codex/v1/live"
        ) {
        match translate_codex_realtime_call(&mut headers, body).await {
            Ok(body) => body,
            Err(response) => return response,
        }
    } else {
        body
    };
    let routing_body = body.routing_bytes();
    if requires_json_object(service, &method, path)
        && !routing_body.is_some_and(|bytes| {
            serde_json::from_slice::<serde_json::Value>(bytes).is_ok_and(|value| value.is_object())
        })
    {
        return error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "the native service request body must be a JSON object",
        );
    }
    if let Err(response) = enforce_native_model_policy(
        &state,
        &claims,
        service,
        &method,
        path,
        routing_body.map_or(&[][..], Bytes::as_ref),
    ) {
        return response;
    }
    let resource = match mcp_session_resource_request(&method, path, &headers) {
        Ok(resource) => resource.or_else(|| native_resource_request(&method, path)),
        Err(response) => return response,
    };
    let list = native_list_request(&method, path);
    let list_destination = match list.as_ref() {
        Some(list) => match native_list_destination(&state, &owner, list) {
            Ok(destination) => destination,
            Err(response) => return response,
        },
        None => None,
    };
    let existing = match resource
        .as_ref()
        .map(|resource| existing_resource(&state, &owner, resource))
        .transpose()
    {
        Ok(affinity) => affinity.flatten(),
        Err(response) => return response,
    };
    let referenced = match referenced_response_affinity(
        &state,
        &owner,
        service,
        path,
        routing_body.map_or(&[][..], Bytes::as_ref),
    ) {
        Ok(affinity) => affinity,
        Err(response) => return response,
    };
    let exact_destination = match one_native_destination(
        existing.as_ref().map(|affinity| &affinity.destination),
        referenced.as_ref().map(|affinity| &affinity.destination),
        list_destination.as_ref(),
    ) {
        Ok(destination) => destination,
        Err(response) => return response,
    };
    let (target, destination) = match target(
        &state,
        &headers,
        &claims,
        service,
        &uri,
        routing_body,
        exact_destination.as_ref(),
    )
    .await
    {
        Ok(target) => target,
        Err(response) => return response,
    };
    if let Some(operation) = codex_history_notes_operation(path) {
        crate::audit::record_control_plane_request(&state, &claims, "codex", operation);
    }
    if path == "/api/services/anthropic/v1/files"
        && method == Method::POST
        && let Err(response) = require_claude_file_upload_scope(&state, &destination)
    {
        return response;
    }
    if path == "/api/services/anthropic/v1/messages/batches"
        && method == Method::POST
        && let Err(response) = validate_anthropic_batch(
            &state,
            &destination,
            routing_body.map_or(&[][..], Bytes::as_ref),
        )
    {
        return response;
    }
    let usage_token_id = tracks_native_usage(service, path).then_some(claims.sub.as_str());
    let mut response = relay_native_http(&state, &method, body, target, usage_token_id).await;
    if let Some(namespace) = created_response_namespace(service, path) {
        let context = crate::resource_capture::CaptureContext::native(
            namespace,
            owner.clone(),
            destination.clone(),
            None,
        );
        response = crate::resource_capture::capture(&state, context, response).await;
    }
    if let Some(list) = list {
        response = filter_native_list_response(&state, &owner, &list, response).await;
    }
    if let Some(resource) = resource {
        if matches!(
            resource.namespace,
            ResponseNamespace::OpenAiRealtimeCalls | ResponseNamespace::CodexRealtimeCalls
        ) && resource.action == NativeResourceAction::Create
            && response.status().is_success()
            && let Err(rewrite_error) = rewrite_realtime_location(service, path, &mut response)
        {
            return rewrite_error;
        }
        return finish_resource_request(&state, owner, destination, resource, existing, response)
            .await;
    }
    response
}

fn enforce_native_model_policy(
    state: &AppState,
    claims: &crate::token::TokenClaims,
    service: Service,
    method: &Method,
    path: &str,
    body: &[u8],
) -> Result<(), Response> {
    if method != Method::POST {
        return Ok(());
    }
    let policy = crate::proxy::model_policy_for_claims(state, claims)
        .map_err(|_| unavailable("model policy is unavailable"))?;
    if policy.allowed_models.is_empty() {
        return Ok(());
    }
    let document = serde_json::from_slice::<serde_json::Value>(body).ok();
    let mut requested = document
        .as_ref()
        .and_then(|value| value.get("model"))
        .and_then(serde_json::Value::as_str)
        .into_iter()
        .collect::<Vec<_>>();
    if service == Service::Anthropic && path == "/api/services/anthropic/v1/messages/batches" {
        requested.extend(
            document
                .as_ref()
                .and_then(|value| value.get("requests"))
                .and_then(serde_json::Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(|request| request.pointer("/params/model"))
                .filter_map(serde_json::Value::as_str),
        );
    }
    if requested.is_empty() && tracks_native_usage(service, path) {
        return Err(error(
            StatusCode::BAD_REQUEST,
            "model_required",
            "a pinned credential requires an explicit exact model on every inference request",
        ));
    }
    for model in requested {
        crate::proxy::authorize_model_for_claims(
            state,
            claims,
            model,
            if service == Service::Anthropic {
                crate::api_error::ApiDialect::Anthropic
            } else {
                crate::api_error::ApiDialect::OpenAi
            },
        )?;
    }
    Ok(())
}

fn realtime_sideband(
    service: Service,
    path: &str,
    query: Option<&str>,
) -> Result<Option<(ResponseNamespace, String)>, ()> {
    let namespace = match service {
        Service::OpenAi => ResponseNamespace::OpenAiRealtimeCalls,
        Service::Codex => ResponseNamespace::CodexRealtimeCalls,
        Service::Anthropic | Service::CodexBackend => return Ok(None),
    };
    if service == Service::Codex
        && let Some(encoded) = path.strip_prefix("/api/services/codex/v1/live/")
    {
        let id = percent_decode_segment(encoded).ok_or(())?;
        if id.is_empty() {
            return Err(());
        }
        return Ok(Some((namespace, id)));
    }
    let realtime = match service {
        Service::OpenAi => "/api/services/openai/v1/realtime",
        Service::Codex => "/api/services/codex/v1/realtime",
        Service::Anthropic | Service::CodexBackend => unreachable!(),
    };
    if path != realtime {
        return Ok(None);
    }
    let mut ids = query
        .into_iter()
        .flat_map(|query| url::form_urlencoded::parse(query.as_bytes()))
        .filter_map(|(key, value)| (key == "call_id").then_some(value.into_owned()));
    let Some(id) = ids.next() else {
        return Ok(None);
    };
    if id.is_empty() || ids.next().is_some() {
        return Err(());
    }
    Ok(Some((namespace, id)))
}

/// Decode a path selector, retaining literal plus signs and rejecting invalid UTF-8.
pub fn percent_decode_segment(encoded: &str) -> Option<String> {
    let bytes = encoded.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' {
            let high = hex_digit(*bytes.get(index + 1)?)?;
            let low = hex_digit(*bytes.get(index + 2)?)?;
            decoded.push((high << 4) | low);
            index += 3;
        } else {
            decoded.push(bytes[index]);
            index += 1;
        }
    }
    String::from_utf8(decoded).ok()
}

const fn hex_digit(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

async fn collect_native_body(
    body: Body,
    limit: usize,
    spool: bool,
) -> Result<NativeRequestBody, Response> {
    if !spool {
        return axum::body::to_bytes(body, limit)
            .await
            .map(NativeRequestBody::Memory)
            .map_err(|_| {
                error(
                    StatusCode::PAYLOAD_TOO_LARGE,
                    "invalid_request_error",
                    "request body exceeds the proxy limit",
                )
            });
    }
    let mut file = tempfile::NamedTempFile::new()
        .map_err(|_| unavailable("a temporary upload spool could not be created"))?;
    let mut len = 0usize;
    let mut source = body.into_data_stream();
    while let Some(chunk) = source.next().await {
        let chunk = chunk.map_err(|_| {
            error(
                StatusCode::BAD_REQUEST,
                "invalid_request_error",
                "request body stream failed",
            )
        })?;
        len = len.checked_add(chunk.len()).ok_or_else(|| {
            error(
                StatusCode::PAYLOAD_TOO_LARGE,
                "invalid_request_error",
                "request body exceeds the proxy limit",
            )
        })?;
        if len > limit {
            return Err(error(
                StatusCode::PAYLOAD_TOO_LARGE,
                "invalid_request_error",
                "request body exceeds the proxy limit",
            ));
        }
        file.write_all(&chunk)
            .map_err(|_| unavailable("the temporary upload spool could not be written"))?;
    }
    file.flush()
        .map_err(|_| unavailable("the temporary upload spool could not be written"))?;
    file.as_file_mut()
        .rewind()
        .map_err(|_| unavailable("the temporary upload spool could not be prepared"))?;
    Ok(NativeRequestBody::Spool { file, len })
}

async fn translate_codex_realtime_call(
    headers: &mut HeaderMap,
    body: NativeRequestBody,
) -> Result<NativeRequestBody, Response> {
    let content_type = headers
        .get("content-type")
        .and_then(|value| value.to_str().ok())
        .ok_or_else(|| {
            error(
                StatusCode::BAD_REQUEST,
                "invalid_request_error",
                "Codex Realtime call creation requires a supported content type",
            )
        })?;
    let media_type = content_type.split(';').next().unwrap_or_default().trim();
    if media_type.eq_ignore_ascii_case("application/sdp")
        || media_type.eq_ignore_ascii_case("application/json")
    {
        return Ok(body);
    }
    if !media_type.eq_ignore_ascii_case("multipart/form-data") {
        return Err(error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "Codex Realtime call creation supports SDP, multipart, or JSON bodies",
        ));
    }
    let boundary = multipart_boundary(content_type).ok_or_else(|| {
        error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "Codex Realtime multipart body has an invalid boundary",
        )
    })?;
    let bytes = native_body_bytes(body).await?;
    let (sdp, session) = parse_codex_realtime_multipart(&bytes, &boundary)?;
    let encoded = serde_json::to_vec(&serde_json::json!({
        "sdp": sdp,
        "session": session,
    }))
    .map_err(|_| unavailable("Codex Realtime backend JSON could not be encoded"))?;
    headers.insert("content-type", HeaderValue::from_static("application/json"));
    headers.remove("content-length");
    Ok(NativeRequestBody::Memory(Bytes::from(encoded)))
}

async fn native_body_bytes(body: NativeRequestBody) -> Result<Bytes, Response> {
    match body {
        NativeRequestBody::Memory(bytes) => Ok(bytes),
        NativeRequestBody::Spool { file, len } => {
            let bytes = tokio::fs::read(file.path())
                .await
                .map_err(|_| unavailable("the temporary upload spool could not be read"))?;
            if bytes.len() != len {
                return Err(unavailable(
                    "the temporary upload spool changed before forwarding",
                ));
            }
            Ok(Bytes::from(bytes))
        }
    }
}

fn multipart_boundary(content_type: &str) -> Option<String> {
    content_type.split(';').skip(1).find_map(|parameter| {
        let (name, raw_value) = parameter.trim().split_once('=')?;
        if !name.trim().eq_ignore_ascii_case("boundary") {
            return None;
        }
        let raw_value = raw_value.trim();
        let value = raw_value
            .strip_prefix('"')
            .and_then(|value| value.strip_suffix('"'))
            .unwrap_or(raw_value);
        (!value.is_empty()
            && value.len() <= 70
            && value
                .bytes()
                .all(|byte| byte.is_ascii_graphic() && byte != b'"'))
        .then(|| value.to_string())
    })
}

fn parse_codex_realtime_multipart(
    body: &[u8],
    boundary: &str,
) -> Result<(String, serde_json::Value), Response> {
    let delimiter = format!("--{boundary}").into_bytes();
    let separator = format!("\r\n--{boundary}").into_bytes();
    let mut cursor = 0usize;
    let mut sdp = None;
    let mut session = None;
    loop {
        if !body
            .get(cursor..)
            .is_some_and(|tail| tail.starts_with(&delimiter))
        {
            return Err(invalid_codex_multipart());
        }
        cursor += delimiter.len();
        if body
            .get(cursor..)
            .is_some_and(|tail| tail.starts_with(b"--"))
        {
            cursor += 2;
            if !matches!(body.get(cursor..), Some(b"" | b"\r\n")) {
                return Err(invalid_codex_multipart());
            }
            break;
        }
        if !body
            .get(cursor..)
            .is_some_and(|tail| tail.starts_with(b"\r\n"))
        {
            return Err(invalid_codex_multipart());
        }
        cursor += 2;
        let header_end = find_bytes(body.get(cursor..).unwrap_or_default(), b"\r\n\r\n")
            .ok_or_else(invalid_codex_multipart)?;
        let headers = std::str::from_utf8(&body[cursor..cursor + header_end])
            .map_err(|_| invalid_codex_multipart())?;
        cursor += header_end + 4;
        let content_end = find_bytes(body.get(cursor..).unwrap_or_default(), &separator)
            .ok_or_else(invalid_codex_multipart)?;
        let content = &body[cursor..cursor + content_end];
        cursor += content_end + 2;
        match multipart_field_name(headers).as_deref() {
            Some("sdp") if sdp.is_none() => {
                sdp = Some(
                    std::str::from_utf8(content)
                        .map_err(|_| invalid_codex_multipart())?
                        .to_string(),
                );
            }
            Some("session") if session.is_none() => {
                session =
                    Some(serde_json::from_slice(content).map_err(|_| invalid_codex_multipart())?);
            }
            Some("sdp" | "session") => return Err(invalid_codex_multipart()),
            _ => {}
        }
    }
    match (sdp, session) {
        (Some(sdp), Some(session)) if !sdp.is_empty() => Ok((sdp, session)),
        _ => Err(invalid_codex_multipart()),
    }
}

fn multipart_field_name(headers: &str) -> Option<String> {
    let disposition = headers.lines().find_map(|line| {
        let (name, value) = line.split_once(':')?;
        name.trim()
            .eq_ignore_ascii_case("content-disposition")
            .then_some(value)
    })?;
    disposition.split(';').skip(1).find_map(|parameter| {
        let (name, raw_value) = parameter.trim().split_once('=')?;
        name.trim().eq_ignore_ascii_case("name").then(|| {
            raw_value
                .trim()
                .strip_prefix('"')
                .and_then(|value| value.strip_suffix('"'))
                .unwrap_or_else(|| raw_value.trim())
                .to_string()
        })
    })
}

fn find_bytes(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    (!needle.is_empty())
        .then(|| {
            haystack
                .windows(needle.len())
                .position(|window| window == needle)
        })
        .flatten()
}

fn invalid_codex_multipart() -> Response {
    error(
        StatusCode::BAD_REQUEST,
        "invalid_request_error",
        "Codex Realtime multipart body must contain one SDP and one JSON session field",
    )
}

fn require_claude_file_upload_scope(
    state: &AppState,
    destination: &AffinityDestination,
) -> Result<(), Response> {
    let AffinityDestination::Subscription {
        provider: SubscriptionProvider::Claude,
        account,
        ..
    } = destination
    else {
        return Err(unavailable(
            "the selected credential cannot authorize Anthropic file uploads",
        ));
    };
    let reader = state
        .account_router
        .as_ref()
        .filter(|router| router.provider() == SubscriptionProvider::Claude)
        .and_then(|router| {
            router
                .subscription_readers()
                .into_iter()
                .find_map(|(name, reader)| (name == *account).then_some(reader))
        })
        .or_else(|| {
            (account == crate::credential_recovery_store::PRIMARY_ACCOUNT)
                .then(|| {
                    state
                        .subscription_readers
                        .iter()
                        .find(|reader| reader.provider() == SubscriptionProvider::Claude)
                        .cloned()
                        .or_else(|| {
                            state
                                .subscription_reader
                                .as_ref()
                                .filter(|reader| reader.provider() == SubscriptionProvider::Claude)
                                .cloned()
                        })
                })
                .flatten()
        })
        .ok_or_else(|| unavailable("the selected Claude credential is unavailable"))?;
    match reader.has_claude_scope("user:file_upload") {
        Ok(true) => Ok(()),
        Ok(false) => Err(anthropic_error(
            StatusCode::FORBIDDEN,
            "permission_error",
            "the selected Claude credential does not authorize file uploads",
        )),
        Err(_) => Err(unavailable(
            "the selected Claude credential authorization is unreadable",
        )),
    }
}

fn validate_anthropic_batch(
    state: &AppState,
    destination: &AffinityDestination,
    body: &[u8],
) -> Result<(), Response> {
    let AffinityDestination::Subscription {
        provider: SubscriptionProvider::Claude,
        account,
        ..
    } = destination
    else {
        return Err(anthropic_error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "Anthropic message batches require one native Claude account",
        ));
    };
    let document = serde_json::from_slice::<serde_json::Value>(body).map_err(|_| {
        anthropic_error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "message batch body must be valid JSON",
        )
    })?;
    let requests = document
        .get("requests")
        .and_then(serde_json::Value::as_array)
        .filter(|requests| !requests.is_empty())
        .ok_or_else(|| {
            anthropic_error(
                StatusCode::BAD_REQUEST,
                "invalid_request_error",
                "message batch requests must be a non-empty array",
            )
        })?;
    let catalog = state
        .model_catalogs
        .status_for(SubscriptionProvider::Claude, account);
    let models = catalog.routable_models();
    for request in requests {
        let model = request
            .pointer("/params/model")
            .and_then(serde_json::Value::as_str)
            .filter(|model| !model.is_empty())
            .ok_or_else(|| {
                anthropic_error(
                    StatusCode::BAD_REQUEST,
                    "invalid_request_error",
                    "every message batch request requires a non-empty model",
                )
            })?;
        if !models.iter().any(|candidate| candidate == model) {
            return Err(anthropic_error(
                StatusCode::BAD_REQUEST,
                "invalid_request_error",
                "a message batch model is unavailable on the selected Claude account",
            ));
        }
    }
    Ok(())
}

