use serde_json::{Value, json};

use super::ChatMessage;

pub fn extract_text(content: &Value) -> Option<String> {
    match content {
        Value::String(s) => Some(s.clone()),
        Value::Array(parts) => {
            let mut buf = String::new();
            for p in parts {
                if let Some(t) = p.get("text").and_then(Value::as_str) {
                    buf.push_str(t);
                } else if let Some(s) = p.as_str() {
                    buf.push_str(s);
                }
            }
            if buf.is_empty() { None } else { Some(buf) }
        }
        _ => None,
    }
}

pub fn translate_parts(parts: &[Value]) -> Vec<Value> {
    parts
        .iter()
        .filter_map(|p| {
            let kind = p.get("type").and_then(Value::as_str).unwrap_or("text");
            match kind {
                "text" | "input_text" | "output_text" => {
                    let text = p.get("text").and_then(Value::as_str).unwrap_or("");
                    let mut block = json!({"type": "text", "text": text});
                    if p.get("prompt_cache_breakpoint").is_some() {
                        block["cache_control"] = json!({"type": "ephemeral"});
                    }
                    Some(block)
                }
                "image_url" => {
                    let url = p
                        .get("image_url")
                        .and_then(|v| v.get("url"))
                        .and_then(Value::as_str)
                        .unwrap_or("");
                    let mut block = json!({
                        "type": "image",
                        "source": {"type": "url", "url": url}
                    });
                    if p.get("prompt_cache_breakpoint").is_some() {
                        block["cache_control"] = json!({"type": "ephemeral"});
                    }
                    Some(block)
                }
                "input_image" => {
                    let url = p.get("image_url").and_then(Value::as_str).unwrap_or("");
                    let mut block = json!({
                        "type": "image",
                        "source": {"type": "url", "url": url}
                    });
                    if p.get("prompt_cache_breakpoint").is_some() {
                        block["cache_control"] = json!({"type": "ephemeral"});
                    }
                    Some(block)
                }
                _ => None,
            }
        })
        .collect()
}

/// Whether a tool entry can be represented in the Anthropic dialect.
///
/// Anthropic understands function tools and the two server-side tools. Codex
/// CLI additionally sends `namespace`, `custom` and `tool_search` as part of its
/// ordinary tool set, and those have no Anthropic equivalent.
fn is_translatable(tool: &Value) -> bool {
    let kind = tool
        .get("type")
        .and_then(Value::as_str)
        .unwrap_or("function");
    match kind {
        "function" => tool
            .get("function")
            .unwrap_or(tool)
            .get("name")
            .and_then(Value::as_str)
            .is_some_and(|name| !name.is_empty()),
        "web_search" | "web_fetch" => true,
        _ => false,
    }
}

/// A human-readable name for a tool entry, for reporting what was dropped.
fn tool_label(tool: &Value) -> String {
    let kind = tool
        .get("type")
        .and_then(Value::as_str)
        .unwrap_or("function");
    tool.get("function")
        .unwrap_or(tool)
        .get("name")
        .and_then(Value::as_str)
        .filter(|name| !name.is_empty())
        .map_or_else(|| kind.to_string(), |name| format!("{kind} ({name})"))
}

/// Tool entries that cannot cross into the Anthropic dialect, in order.
///
/// Dropping these is preferable to refusing the request. A model is never
/// obliged to call a tool, so a request carrying the nine usable tools of a
/// Codex turn is far more useful than a `400` naming the one that did not fit
/// (issue #215). The caller is told what was dropped rather than left to infer
/// it from an agent that quietly never uses sub-agents.
#[must_use]
pub fn untranslatable_anthropic_tools(tools: &Value) -> Vec<String> {
    tools.as_array().map_or_else(Vec::new, |tools| {
        tools
            .iter()
            .filter(|tool| !is_translatable(tool))
            .map(tool_label)
            .collect()
    })
}

pub fn translate_tools(tools: &Value) -> Value {
    match tools {
        Value::Array(arr) => {
            let mapped: Vec<Value> = arr
                .iter()
                // An untranslatable entry is dropped rather than passed through
                // verbatim: forwarding a shape Anthropic does not define would
                // trade a router `400` for a vendor one (issue #215).
                .filter(|t| is_translatable(t))
                .map(|t| {
                    let kind = t.get("type").and_then(Value::as_str).unwrap_or("function");
                    match kind {
                        "web_search" => {
                            let mut tool = json!({
                                "type": "web_search_20250305",
                                "name": "web_search",
                            });
                            for key in [
                                "max_uses",
                                "allowed_domains",
                                "blocked_domains",
                                "user_location",
                            ] {
                                if let Some(value) = t.get(key) {
                                    tool[key] = value.clone();
                                }
                            }
                            return tool;
                        }
                        "web_fetch" => {
                            let mut tool = json!({
                                "type": "web_fetch_20250910",
                                "name": "web_fetch",
                            });
                            if let Some(max_uses) = t.get("max_uses") {
                                tool["max_uses"] = max_uses.clone();
                            }
                            return tool;
                        }
                        "function" => {}
                        _ => return t.clone(),
                    }
                    // Chat Completions nests a function definition while the
                    // Responses API keeps the same fields flat.
                    let func = t.get("function").unwrap_or(t);
                    let name = func
                        .get("name")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_string();
                    let description = func
                        .get("description")
                        .cloned()
                        .unwrap_or(Value::String(String::new()));
                    let parameters = func.get("parameters").cloned().unwrap_or_else(|| json!({}));
                    let mut mapped = json!({
                        "name": name,
                        "description": description,
                        "input_schema": parameters,
                    });
                    if let Some(strict) = func.get("strict") {
                        mapped["strict"] = strict.clone();
                    }
                    mapped
                })
                .collect();
            Value::Array(mapped)
        }
        other => other.clone(),
    }
}

/// Validate function-tool fields that must survive an Anthropic bridge.
#[must_use]
pub fn invalid_anthropic_tool_definition(tools: &Value) -> Option<String> {
    let Some(tools) = tools.as_array() else {
        return Some("tools must be an array".into());
    };
    for (index, tool) in tools.iter().enumerate() {
        let kind = tool
            .get("type")
            .and_then(Value::as_str)
            .unwrap_or("function");
        if kind != "function" {
            continue;
        }
        let function = tool.get("function").unwrap_or(tool);
        if function
            .get("name")
            .and_then(Value::as_str)
            .is_none_or(str::is_empty)
        {
            return Some(format!("tools[{index}] is missing function name"));
        }
        if function
            .get("parameters")
            .is_some_and(|schema| !schema.is_object())
        {
            return Some(format!("tools[{index}].parameters must be an object"));
        }
        if function
            .get("strict")
            .is_some_and(|strict| !strict.is_boolean())
        {
            return Some(format!("tools[{index}].strict must be a boolean"));
        }
    }
    None
}

/// Validate prior Chat tool turns before translating them to Anthropic. Empty
/// identifiers or malformed JSON arguments cannot be repaired without losing
/// the caller's tool protocol state.
#[must_use]
pub fn untranslatable_chat_tool_history(messages: &[ChatMessage]) -> Option<String> {
    for message in messages {
        if message.content.as_array().is_some_and(|parts| {
            parts
                .iter()
                .any(|part| part.get("type").and_then(Value::as_str) == Some("input_audio"))
        }) {
            return Some(
                "input_audio content cannot be represented by the selected Anthropic provider"
                    .into(),
            );
        }
        if message.role == "tool" && message.tool_call_id.as_deref().is_none_or(str::is_empty) {
            return Some("role=tool message is missing tool_call_id".into());
        }
        let Some(tool_calls) = message.tool_calls.as_ref() else {
            continue;
        };
        let Some(tool_calls) = tool_calls.as_array() else {
            return Some("assistant tool_calls must be an array".into());
        };
        for call in tool_calls {
            if call
                .get("id")
                .and_then(Value::as_str)
                .is_none_or(str::is_empty)
            {
                return Some("assistant tool call is missing id".into());
            }
            let Some(function) = call.get("function") else {
                return Some("assistant tool call is missing function".into());
            };
            if function
                .get("name")
                .and_then(Value::as_str)
                .is_none_or(str::is_empty)
            {
                return Some("assistant tool call is missing function.name".into());
            }
            let Some(arguments) = function.get("arguments").and_then(Value::as_str) else {
                return Some("assistant tool call is missing string function.arguments".into());
            };
            if serde_json::from_str::<Value>(arguments).is_err() {
                return Some("assistant tool call function.arguments is not valid JSON".into());
            }
        }
    }
    None
}

pub fn translate_tool_choice(choice: &Value) -> Value {
    match choice {
        Value::String(s) => match s.as_str() {
            "required" => json!({"type": "any"}),
            "none" => json!({"type": "none"}),
            // "auto" plus any unrecognised string default to auto.
            _ => json!({"type": "auto"}),
        },
        Value::Object(map) => {
            if let Some(func) = map.get("function").and_then(Value::as_object)
                && let Some(name) = func.get("name").and_then(Value::as_str)
            {
                return json!({"type": "tool", "name": name});
            }
            if map.get("type").and_then(Value::as_str) == Some("function")
                && let Some(name) = map.get("name").and_then(Value::as_str)
            {
                return json!({"type": "tool", "name": name});
            }
            json!({"type": "auto"})
        }
        _ => json!({"type": "auto"}),
    }
}

/// Return a semantic error for a tool-choice shape that would otherwise be
/// silently weakened to `auto` during Anthropic translation.
#[must_use]
pub fn untranslatable_anthropic_tool_choice(choice: &Value) -> Option<String> {
    match choice {
        Value::String(mode) if matches!(mode.as_str(), "auto" | "required" | "none") => None,
        Value::Object(map) => {
            let nested_name = map
                .get("function")
                .and_then(Value::as_object)
                .and_then(|function| function.get("name"))
                .and_then(Value::as_str);
            let flat_name = (map.get("type").and_then(Value::as_str) == Some("function"))
                .then(|| map.get("name").and_then(Value::as_str))
                .flatten();
            (nested_name.is_none() && flat_name.is_none())
                .then(|| "tool_choice must select auto, required, none, or a named function".into())
        }
        _ => Some("tool_choice must select auto, required, none, or a named function".into()),
    }
}

//! Incremental Anthropic SSE to `OpenAI` SSE translation.
//!
//! Split from `openai.rs` to keep that file within the repository's 1000-line
//! limit. The streamed and non-streaming translations must agree; see the
//! drift-guard test in `openai_response_tests.rs` (issue #218).

use std::collections::BTreeMap;

use serde_json::{Value, json};

use super::{done_frame, extract_sse_data, map_finish_reason, response_sse_frame, sse_frame};

/// OpenAI-compatible stream response shape to emit while translating
/// Anthropic SSE events.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OpenAIStreamShape {
    ChatCompletion,
    Response,
}

/// Incremental Anthropic SSE to `OpenAI` SSE translator.
#[derive(Debug, Clone)]
pub struct OpenAIStreamTranslator {
    shape: OpenAIStreamShape,
    served_model: String,
    id: String,
    created: i64,
    buffer: Vec<u8>,
    sent_chat_role: bool,
    sent_response_created: bool,
    sent_final: bool,
    failed: Option<()>,
    usage_requested: Option<()>,
    usage: crate::bridge_response::AnthropicUsage,
    stop_reason: Option<String>,
    response_output_text: String,
    response_annotations: Vec<Value>,
    citation_search_from: usize,
    /// The output slot the text item occupies, once any text has arrived.
    ///
    /// `None` until then, which is what keeps a tool-only turn from carrying an
    /// empty `output_text` item: a well-formed, successful, empty answer is
    /// worse than an error, because the client cannot tell anything went wrong
    /// (issue #218). The item is announced on first text rather than up front.
    response_text_item: Option<u64>,
    /// Streamed tool calls, keyed by the upstream content-block index.
    ///
    /// Anthropic announces a `tool_use` block and then streams its arguments as
    /// `input_json_delta` fragments, so the name and identifier must be held
    /// until the arguments are complete.
    response_tool_calls: BTreeMap<u64, ResponseToolCall>,
    /// Output slots already used, so each item gets a distinct `output_index`.
    response_output_index: u64,
}

/// A `function_call` item being assembled from an upstream `tool_use` block.
#[derive(Clone, Debug)]
struct ResponseToolCall {
    call_id: String,
    name: String,
    arguments: String,
    output_index: u64,
}

impl ResponseToolCall {
    /// The completed item, in the same shape the non-streaming path builds
    /// (`responses::chat_tool_call_to_responses`), so the two agree.
    fn item(&self) -> Value {
        json!({
            "id": format!("fc-{}", self.call_id),
            "type": "function_call",
            "status": "completed",
            "call_id": self.call_id,
            "name": self.name,
            "arguments": if self.arguments.is_empty() { "{}" } else { &self.arguments },
        })
    }
}

impl OpenAIStreamTranslator {
    /// Create a stream translator for one upstream request.
    #[must_use]
    pub fn new(shape: OpenAIStreamShape, _resolved_model: &str) -> Self {
        let prefix = match shape {
            OpenAIStreamShape::ChatCompletion => "chatcmpl",
            OpenAIStreamShape::Response => "resp",
        };
        Self {
            shape,
            // The response model is supplied by the upstream `message_start`.
            // Starting empty prevents a requested/routed selector from being
            // emitted as though it were the model that actually served.
            served_model: String::new(),
            id: format!("{prefix}-{}", uuid::Uuid::new_v4()),
            created: crate::operation_context::now().timestamp(),
            buffer: Vec::new(),
            sent_chat_role: false,
            sent_response_created: false,
            sent_final: false,
            failed: None,
            usage_requested: None,
            usage: crate::bridge_response::AnthropicUsage::default(),
            stop_reason: None,
            response_output_text: String::new(),
            response_annotations: Vec::new(),
            citation_search_from: 0,
            response_text_item: None,
            response_tool_calls: BTreeMap::new(),
            response_output_index: 0,
        }
    }

    /// Request a final Chat Completions usage chunk with empty choices.
    #[must_use]
    pub const fn with_include_usage(mut self, include_usage: bool) -> Self {
        self.usage_requested = if include_usage { Some(()) } else { None };
        self
    }

    /// Push raw upstream bytes and return zero or more `OpenAI` SSE frames.
    pub fn push(&mut self, chunk: &[u8]) -> Vec<String> {
        let mut frames = Vec::new();
        for block in crate::sse::push_blocks(&mut self.buffer, chunk) {
            frames.extend(self.translate_block(&block));
        }
        frames
    }

    fn translate_block(&mut self, block: &str) -> Vec<String> {
        if self.failed.is_some() {
            return Vec::new();
        }
        let data = extract_sse_data(block);
        if data.is_empty() {
            return Vec::new();
        }
        if data == "[DONE]" {
            self.sent_final = true;
            return vec![done_frame()];
        }
        let Ok(event) = serde_json::from_str::<Value>(&data) else {
            return Vec::new();
        };
        if event.get("type").and_then(Value::as_str) == Some("error") {
            self.failed = Some(());
            let error = event.get("error").cloned().unwrap_or_else(|| {
                json!({"type": "served_model_unknown", "message": "upstream model identity is unverifiable"})
            });
            return match self.shape {
                OpenAIStreamShape::ChatCompletion => {
                    vec![sse_frame(&json!({"error": error})), done_frame()]
                }
                OpenAIStreamShape::Response => vec![
                    response_sse_frame(&json!({
                        "type": "response.failed",
                        "response": {
                            "id": self.id,
                            "object": "response",
                            "status": "failed",
                            "error": error,
                        }
                    })),
                    done_frame(),
                ],
            };
        }
        match self.shape {
            OpenAIStreamShape::ChatCompletion => self.translate_chat_event(&event),
            OpenAIStreamShape::Response => self.translate_response_event(&event),
        }
    }

    fn translate_chat_event(&mut self, event: &Value) -> Vec<String> {
        match event.get("type").and_then(Value::as_str) {
            Some("message_start") => {
                self.capture_upstream_identity(event);
                self.capture_anthropic_usage(event.pointer("/message/usage"));
                if let Some(id) = event
                    .get("message")
                    .and_then(|m| m.get("id"))
                    .and_then(Value::as_str)
                {
                    self.id = format!("chatcmpl-{id}");
                }
                self.sent_chat_role = true;
                vec![self.chat_frame(&json!({"role": "assistant"}), None)]
            }
            Some("content_block_start") => {
                let block = event.get("content_block").unwrap_or(&Value::Null);
                if block.get("type").and_then(Value::as_str) != Some("tool_use") {
                    return Vec::new();
                }
                self.sent_chat_role = true;
                let index = event.get("index").and_then(Value::as_u64).unwrap_or(0);
                let id = block.get("id").and_then(Value::as_str).unwrap_or("");
                let name = block.get("name").and_then(Value::as_str).unwrap_or("");
                vec![self.chat_frame(
                    &json!({
                        "tool_calls": [{
                            "index": index,
                            "id": id,
                            "type": "function",
                            "function": {"name": name, "arguments": ""}
                        }]
                    }),
                    None,
                )]
            }
            Some("content_block_delta") => {
                let delta = event.get("delta").unwrap_or(&Value::Null);
                match delta.get("type").and_then(Value::as_str) {
                    Some("text_delta") => {
                        let text = delta.get("text").and_then(Value::as_str).unwrap_or("");
                        self.response_output_text.push_str(text);
                        let mut payload = json!({"content": text});
                        if !self.sent_chat_role {
                            payload["role"] = Value::String("assistant".into());
                            self.sent_chat_role = true;
                        }
                        vec![self.chat_frame(&payload, None)]
                    }
                    Some("citations_delta") => {
                        let Some((annotation, next)) =
                            crate::bridge_response::annotation_from_anthropic_delta(
                                delta,
                                &self.response_output_text,
                                self.citation_search_from,
                            )
                        else {
                            return self.fail_citation();
                        };
                        self.citation_search_from = next;
                        self.response_annotations.push(annotation.clone());
                        vec![self.chat_frame(
                            &json!({
                                "annotations": crate::bridge_response::chat_annotations(&[annotation])
                            }),
                            None,
                        )]
                    }
                    Some("input_json_delta") => {
                        let partial = delta
                            .get("partial_json")
                            .and_then(Value::as_str)
                            .unwrap_or("");
                        let index = event.get("index").and_then(Value::as_u64).unwrap_or(0);
                        vec![self.chat_frame(
                            &json!({
                                "tool_calls": [{
                                    "index": index,
                                    "function": {"arguments": partial}
                                }]
                            }),
                            None,
                        )]
                    }
                    _ => Vec::new(),
                }
            }
            Some("message_delta") => {
                self.capture_anthropic_usage(event.get("usage"));
                event
                    .get("delta")
                    .and_then(|d| d.get("stop_reason"))
                    .and_then(Value::as_str)
                    .map_or_else(Vec::new, |reason| {
                        self.stop_reason = Some(reason.to_string());
                        self.sent_final = true;
                        vec![self.chat_frame(&json!({}), Some(map_finish_reason(reason)))]
                    })
            }
            Some("message_stop") => {
                let mut frames = Vec::new();
                if !self.sent_final {
                    frames.push(self.chat_frame(&json!({}), Some("stop")));
                    self.sent_final = true;
                }
                if self.usage_requested.is_some() {
                    frames.push(self.chat_usage_frame());
                }
                frames.push(done_frame());
                frames
            }
            _ => Vec::new(),
        }
    }

    fn translate_response_event(&mut self, event: &Value) -> Vec<String> {
        match event.get("type").and_then(Value::as_str) {
            Some("message_start") => {
                self.capture_upstream_identity(event);
                self.capture_anthropic_usage(event.pointer("/message/usage"));
                if let Some(id) = event
                    .get("message")
                    .and_then(|m| m.get("id"))
                    .and_then(Value::as_str)
                {
                    self.id = format!("resp-{id}");
                }
                self.sent_response_created = true;
                // The message item is announced when the first text arrives,
                // not here: a tool-only turn must not carry an empty
                // `output_text` item (issue #218).
                vec![
                    response_sse_frame(&json!({
                        "type": "response.created",
                        "response": self.response_object("in_progress", false)
                    })),
                    response_sse_frame(&json!({
                        "type": "response.in_progress",
                        "response": self.response_object("in_progress", false)
                    })),
                ]
            }
            Some("content_block_start") => {
                // Anthropic announces a tool call here, with the identifier and
                // name the caller needs before any arguments arrive.
                let block = event.get("content_block").unwrap_or(&Value::Null);
                if block.get("type").and_then(Value::as_str) != Some("tool_use") {
                    return Vec::new();
                }
                self.sent_response_created = true;
                let index = event.get("index").and_then(Value::as_u64).unwrap_or(0);
                let call = ResponseToolCall {
                    call_id: block
                        .get("id")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_string(),
                    name: block
                        .get("name")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_string(),
                    arguments: String::new(),
                    output_index: self.take_output_index(),
                };
                let frame = response_sse_frame(&json!({
                    "type": "response.output_item.added",
                    "output_index": call.output_index,
                    "item": {
                        "id": format!("fc-{}", call.call_id),
                        "type": "function_call",
                        "status": "in_progress",
                        "call_id": call.call_id,
                        "name": call.name,
                        "arguments": "",
                    }
                }));
                self.response_tool_calls.insert(index, call);
                vec![frame]
            }
            Some("content_block_delta") => {
                if !self.sent_response_created {
                    self.sent_response_created = true;
                }
                let delta = event.get("delta").unwrap_or(&Value::Null);
                match delta.get("type").and_then(Value::as_str) {
                    Some("text_delta") => {
                        let text = delta.get("text").and_then(Value::as_str).unwrap_or("");
                        let mut frames = self.open_response_text_item();
                        self.response_output_text.push_str(text);
                        frames.push(response_sse_frame(&json!({
                            "type": "response.output_text.delta",
                            "response_id": self.id,
                            "item_id": self.response_item_id(),
                            "output_index": self.response_text_item.unwrap_or(0),
                            "content_index": 0,
                            "delta": text
                        })));
                        frames
                    }
                    Some("citations_delta") => {
                        let Some((annotation, next)) =
                            crate::bridge_response::annotation_from_anthropic_delta(
                                delta,
                                &self.response_output_text,
                                self.citation_search_from,
                            )
                        else {
                            return self.fail_citation();
                        };
                        self.citation_search_from = next;
                        self.response_annotations.push(annotation.clone());
                        vec![response_sse_frame(&json!({
                            "type": "response.output_text.annotation.added",
                            "item_id": self.response_item_id(),
                            "output_index": self.response_text_item.unwrap_or(0),
                            "content_index": 0,
                            "annotation_index": self.response_annotations.len() - 1,
                            "annotation": annotation,
                        }))]
                    }
                    Some("input_json_delta") => {
                        // The arguments arrive as fragments that must be
                        // concatenated in order; a fragment is not valid JSON on
                        // its own.
                        let partial = delta
                            .get("partial_json")
                            .and_then(Value::as_str)
                            .unwrap_or("");
                        let index = event.get("index").and_then(Value::as_u64).unwrap_or(0);
                        let Some(call) = self.response_tool_calls.get_mut(&index) else {
                            return Vec::new();
                        };
                        call.arguments.push_str(partial);
                        vec![response_sse_frame(&json!({
                            "type": "response.function_call_arguments.delta",
                            "item_id": format!("fc-{}", call.call_id),
                            "output_index": call.output_index,
                            "delta": partial
                        }))]
                    }
                    _ => Vec::new(),
                }
            }
            Some("content_block_stop") => {
                let index = event.get("index").and_then(Value::as_u64).unwrap_or(0);
                let Some(call) = self.response_tool_calls.get(&index) else {
                    return Vec::new();
                };
                let arguments = if call.arguments.is_empty() {
                    "{}"
                } else {
                    &call.arguments
                };
                vec![
                    response_sse_frame(&json!({
                        "type": "response.function_call_arguments.done",
                        "item_id": format!("fc-{}", call.call_id),
                        "output_index": call.output_index,
                        "arguments": arguments
                    })),
                    response_sse_frame(&json!({
                        "type": "response.output_item.done",
                        "output_index": call.output_index,
                        "item": call.item()
                    })),
                ]
            }
            Some("message_delta") => {
                self.capture_anthropic_usage(event.get("usage"));
                self.stop_reason = event
                    .pointer("/delta/stop_reason")
                    .and_then(Value::as_str)
                    .map(str::to_string);
                Vec::new()
            }
            Some("message_stop") => {
                self.sent_final = true;
                let stop = crate::bridge_response::stop_semantics(self.stop_reason.as_deref());
                let mut frames = Vec::new();
                // Only close the text item if one was ever opened. A tool-only
                // turn previously ended here with `"text": ""`, which reads to
                // the caller as a successful empty answer (issue #218).
                if let Some(index) = self.response_text_item {
                    let mut done = json!({
                        "type": if stop.refusal { "response.refusal.done" } else { "response.output_text.done" },
                        "item_id": self.response_item_id(),
                        "output_index": index,
                        "content_index": 0
                    });
                    done[if stop.refusal { "refusal" } else { "text" }] =
                        Value::String(self.response_output_text.clone());
                    frames.push(response_sse_frame(&done));
                    frames.push(response_sse_frame(&json!({
                        "type": "response.content_part.done",
                        "item_id": self.response_item_id(),
                        "output_index": index,
                        "content_index": 0,
                        "part": self.response_content_part(&self.response_output_text)
                    })));
                    frames.push(response_sse_frame(&json!({
                        "type": "response.output_item.done",
                        "output_index": index,
                        "item": self.response_output_item(stop.response_status, true)
                    })));
                }
                let terminal = if stop.response_status == "completed" {
                    "response.completed"
                } else {
                    "response.incomplete"
                };
                frames.push(response_sse_frame(&json!({
                    "type": terminal,
                    "response": self.response_object(stop.response_status, true)
                })));
                frames.push(done_frame());
                frames
            }
            _ => Vec::new(),
        }
    }

    fn chat_frame(&self, delta: &Value, finish_reason: Option<&str>) -> String {
        let mut frame = json!({
            "id": self.id,
            "object": "chat.completion.chunk",
            "created": self.created,
            "model": self.served_model,
            "choices": [{
                "index": 0,
                "delta": delta,
                "finish_reason": finish_reason
            }]
        });
        if let Some(tier) = self.usage.openai_service_tier() {
            frame["service_tier"] = Value::String(tier.into());
        }
        sse_frame(&frame)
    }

    fn chat_usage_frame(&self) -> String {
        sse_frame(&json!({
            "id": self.id,
            "object": "chat.completion.chunk",
            "created": self.created,
            "model": self.served_model,
            "choices": [],
            "usage": self.usage.chat()
        }))
    }

    fn capture_anthropic_usage(&mut self, usage: Option<&Value>) {
        self.usage.absorb(usage);
    }

    fn response_object(&self, status: &str, include_output: bool) -> Value {
        // The completed response lists every item the stream produced, in the
        // order the caller saw them: a tool-only turn carries just its
        // `function_call` items, and a mixed turn carries both (issue #218).
        let output = if include_output {
            let mut items: Vec<(u64, Value)> = self
                .response_tool_calls
                .values()
                .map(|call| (call.output_index, call.item()))
                .collect();
            if let Some(index) = self.response_text_item {
                items.push((index, self.response_output_item(status, true)));
            }
            items.sort_by_key(|(index, _)| *index);
            items.into_iter().map(|(_, item)| item).collect()
        } else {
            Vec::new()
        };
        let mut response = json!({
            "id": self.id,
            "object": "response",
            "created_at": self.created,
            "model": self.served_model,
            "status": status,
            "output": output
        });
        if let Some(tier) = self.usage.openai_service_tier() {
            response["service_tier"] = Value::String(tier.into());
        }
        if status != "in_progress" {
            response["usage"] = self.usage.responses();
            if let Some(reason) =
                crate::bridge_response::stop_semantics(self.stop_reason.as_deref())
                    .incomplete_reason
            {
                response["incomplete_details"] = json!({"reason": reason});
            }
        }
        response
    }

    fn response_item_id(&self) -> String {
        format!("msg-{}", self.id)
    }

    /// Claim the next output slot, so text and each tool call are distinct
    /// items in the response as Anthropic's increasing block indices intend.
    const fn take_output_index(&mut self) -> u64 {
        let index = self.response_output_index;
        self.response_output_index += 1;
        index
    }

    /// Announce the text item on first use, so a tool-only turn never carries
    /// an empty one (issue #218).
    fn open_response_text_item(&mut self) -> Vec<String> {
        if self.response_text_item.is_some() {
            return Vec::new();
        }
        let index = self.take_output_index();
        self.response_text_item = Some(index);
        vec![
            response_sse_frame(&json!({
                "type": "response.output_item.added",
                "output_index": index,
                "item": self.response_output_item("in_progress", false)
            })),
            response_sse_frame(&json!({
                "type": "response.content_part.added",
                "item_id": self.response_item_id(),
                "output_index": index,
                "content_index": 0,
                "part": self.response_content_part("")
            })),
        ]
    }

    fn response_content_part(&self, text: &str) -> Value {
        if crate::bridge_response::stop_semantics(self.stop_reason.as_deref()).refusal {
            json!({"type": "refusal", "refusal": text})
        } else {
            json!({"type": "output_text", "text": text, "annotations": self.response_annotations})
        }
    }

    fn response_output_item(&self, status: &str, include_content: bool) -> Value {
        let content = if include_content {
            vec![self.response_content_part(&self.response_output_text)]
        } else {
            Vec::new()
        };
        json!({
            "id": self.response_item_id(),
            "type": "message",
            "status": status,
            "role": "assistant",
            "content": content
        })
    }

    fn capture_upstream_identity(&mut self, event: &Value) {
        if let Some(model) = event
            .get("message")
            .and_then(|message| message.get("model"))
            .and_then(Value::as_str)
        {
            self.served_model = model.to_string();
        }
    }

    fn fail_citation(&mut self) -> Vec<String> {
        self.failed = Some(());
        let message = "upstream returned an unrepresentable citation";
        match self.shape {
            OpenAIStreamShape::ChatCompletion => vec![
                sse_frame(&json!({"error": {"type": "api_error", "message": message}})),
                done_frame(),
            ],
            OpenAIStreamShape::Response => vec![
                response_sse_frame(&json!({
                    "type": "response.failed",
                    "response": {
                        "id": self.id,
                        "object": "response",
                        "status": "failed",
                        "error": {"code": "server_error", "message": message}
                    }
                })),
                done_frame(),
            ],
        }
    }
}

//! Injectable environment, filesystem roots, clock and subprocess runner.
use std::collections::BTreeMap;
use std::ffi::{OsStr, OsString};
use std::path::PathBuf;
use std::process::{Command, Output};
use std::sync::{Arc, Mutex};
use std::time::Duration;

/// A process dependency; tests can return fixtures without spawning commands.
pub trait ProcessRunner: Send + Sync {
    /// Execute an external dependency with a finite deadline.
    fn output(&self, command: &mut Command, deadline: Duration) -> std::io::Result<Output>;

    /// Start an owned background dependency; override to launch a test fixture.
    fn spawn(&self, command: &mut Command) -> std::io::Result<std::process::Child> {
        command.spawn()
    }
}

/// Output accumulated by the operation; never redirected process-wide.
#[derive(Default)]
pub(crate) struct CapturedOutput {
    pub stdout: String,
    pub stderr: String,
    pub data: Option<serde_json::Value>,
}

/// Parameters scoped to one library operation. Clones share dependency objects.
#[derive(Clone)]
pub struct OperationContext {
    /// Environment snapshot; reads do not mutate the process environment.
    pub environment: BTreeMap<OsString, OsString>,
    /// Optional filesystem home root.
    pub home: Option<PathBuf>,
    /// Optional persistent Router state root.
    pub data_dir: Option<PathBuf>,
    /// Working directory for subprocesses and relative operation paths.
    pub working_directory: PathBuf,
    /// Injected timestamp; `None` uses the actual clock.
    pub now: Option<chrono::DateTime<chrono::Utc>>,
    /// Injected external dependency runner; `None` uses native bounded execution.
    pub process_runner: Option<Arc<dyn ProcessRunner>>,
    /// Finite deadline for noninteractive external dependencies.
    pub process_deadline: Duration,
    /// Router daemon used by host deployments. Libraries must select a real CLI binary.
    /// When absent, scoped `ROUTER_BIN` or the running Router CLI is used.
    pub daemon_executable: Option<PathBuf>,
    pub(crate) output: Arc<Mutex<CapturedOutput>>,
    pub(crate) deployment_instance: Arc<Mutex<Option<String>>>,
    pub(crate) deployment_settings: Arc<Mutex<crate::deploy_local::runtime_env::LocalSettings>>,
}

impl Default for OperationContext {
    fn default() -> Self {
        Self {
            environment: std::env::vars_os().collect(),
            home: None,
            data_dir: None,
            working_directory: std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
            now: None,
            process_runner: None,
            process_deadline: Duration::from_secs(60),
            daemon_executable: None,
            output: Arc::new(Mutex::new(CapturedOutput::default())),
            deployment_instance: Arc::default(),
            deployment_settings: Arc::default(),
        }
    }
}

impl OperationContext {
    /// Use an isolated home/state directory while preserving required PATH.
    #[must_use]
    pub fn isolated(root: impl Into<PathBuf>) -> Self {
        let root = root.into();
        let mut context = Self {
            home: Some(root.clone()),
            data_dir: Some(root.join("router-data")),
            ..Self::default()
        };
        for name in [
            "HOME",
            "USERPROFILE",
            "XDG_CONFIG_HOME",
            "XDG_DATA_HOME",
            "XDG_CACHE_HOME",
            "CLAUDE_CONFIG_DIR",
            "CODEX_HOME",
        ] {
            context.environment.remove(OsStr::new(name));
        }
        context
            .environment
            .insert("HOME".into(), root.into_os_string());
        context
    }

    /// Scope a synchronous preparation step without changing global dependencies.
    pub fn scope<T>(&self, operation: impl FnOnce() -> T) -> T {
        ACTIVE.sync_scope(self.clone(), operation)
    }

    /// Scope asynchronous dependencies for a lower-level operation.
    pub async fn scope_async<T>(&self, operation: impl std::future::Future<Output = T>) -> T {
        ACTIVE.scope(self.clone(), operation).await
    }

    /// Override one environment dependency without changing global state.
    pub fn set_env(&mut self, name: impl Into<OsString>, value: impl Into<OsString>) {
        self.environment.insert(name.into(), value.into());
    }
}

tokio::task_local! {
    pub(crate) static ACTIVE: OperationContext;
}

pub(crate) fn current() -> Option<OperationContext> {
    ACTIVE.try_with(Clone::clone).ok()
}

/// Read a variable from the current operation, or the native environment.
pub fn var_os(name: impl AsRef<OsStr>) -> Option<OsString> {
    ACTIVE
        .try_with(|context| context.environment.get(name.as_ref()).cloned())
        .unwrap_or_else(|_| std::env::var_os(name.as_ref()))
}

/// Read a Unicode environment dependency.
pub fn var(name: impl AsRef<OsStr>) -> Result<String, std::env::VarError> {
    var_os(name.as_ref())
        .ok_or(std::env::VarError::NotPresent)
        .and_then(|value| value.into_string().map_err(std::env::VarError::NotUnicode))
}

/// Read the operation clock.
#[must_use]
pub fn now() -> chrono::DateTime<chrono::Utc> {
    ACTIVE
        .try_with(|context| context.now)
        .ok()
        .flatten()
        .unwrap_or_else(chrono::Utc::now)
}

/// Preserve native wall-clock precision while honoring the scoped timestamp.
pub(crate) fn system_time() -> std::time::SystemTime {
    ACTIVE
        .try_with(|context| context.now)
        .ok()
        .flatten()
        .map_or_else(std::time::SystemTime::now, Into::into)
}

/// Resolve filesystem paths against the caller's working directory.
pub fn current_dir() -> std::io::Result<PathBuf> {
    ACTIVE
        .try_with(|context| context.working_directory.clone())
        .or_else(|_| std::env::current_dir())
}

/// Create a dependency command using the operation environment and directory.
/// A later explicit `env_clear()` remains authoritative (verification relies on it).
pub fn command(program: impl AsRef<OsStr>) -> Command {
    let mut command = Command::new(program);
    if let Some(context) = current() {
        command
            .env_clear()
            .envs(&context.environment)
            .current_dir(&context.working_directory);
    }
    command
}

/// Execute an external dependency with the operation's finite deadline.
pub fn process_output(command: &mut Command) -> std::io::Result<Output> {
    let deadline = current().map_or(Duration::from_secs(60), |context| context.process_deadline);
    bounded_output(command, deadline)
}

/// Bound an external dependency with an explicit deadline and injectable runner.
pub fn bounded_output(command: &mut Command, deadline: Duration) -> std::io::Result<Output> {
    if let Some(runner) = current().and_then(|context| context.process_runner) {
        runner.output(command, deadline)
    } else {
        crate::bounded_process::output(command, deadline)
    }
}

/// Start a background dependency through the operation runner, preserving its pipes.
pub fn spawn_process(command: &mut Command) -> std::io::Result<std::process::Child> {
    if let Some(runner) = current().and_then(|context| context.process_runner) {
        runner.spawn(command)
    } else {
        command.spawn()
    }
}

//! Domain reports shared by Rust operations, JSON contracts and generated bindings.
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct Check {
    pub name: String,
    pub state: String,
    pub detail: Option<String>,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ProviderHealth {
    pub provider: crate::subscription::SubscriptionProvider,
    pub credential_root: String,
    pub state: String,
    pub models: Vec<String>,
    pub detail: Option<String>,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct DeploymentHealth {
    pub deployment: crate::deploy::registry::Entry,
    pub present: bool,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ModelRecommendation {
    pub provider: crate::subscription::SubscriptionProvider,
    pub model: String,
    pub reason: String,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct DoctorReport {
    pub status: String,
    pub version: String,
    pub checks: Vec<Check>,
    pub providers: Vec<ProviderHealth>,
    pub deployments: Vec<DeploymentHealth>,
    pub recommended_models: Vec<ModelRecommendation>,
    pub data_dir: std::path::PathBuf,
    pub listen_addr: String,
    pub forwarded_headers: Vec<String>,
    pub output: Vec<String>,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct AuthStatusReport {
    pub server: Option<String>,
    pub credentials: Vec<crate::credential_status::CredentialAcceptanceReport>,
    pub sources: Vec<crate::credential_source::SourceReport>,
    pub api_key_providers: Vec<crate::providers::RedactedProviderRecord>,
    pub output: Vec<String>,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ClientState {
    pub client: String,
    pub installed: bool,
    pub configured: bool,
    pub config_path: PathBuf,
    pub dialect: String,
    pub base_url: Option<String>,
    pub token_env: Option<String>,
    pub token_env_set: bool,
    /// Router ownership of the effective routing configuration.
    pub ownership_state: crate::clients::OwnershipState,
    /// Highest-precedence source which currently selects the endpoint.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub effective_source: Option<crate::clients::ConfigSource>,
    /// Routing-critical key names which disagree; values are never retained.
    pub conflicts: Vec<String>,
    /// Why this client's configuration could not be read, if it could not.
    ///
    /// A damaged file is a property of one row, not of the listing: propagating
    /// it ended the table at that client and silently hid every client after
    /// it, while the error named a *different* client than the one missing
    /// (issue #304).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub unreadable: Option<String>,
    /// Why the router cannot manage this client at all, if it cannot.
    ///
    /// `configured: false` is indistinguishable from a real answer for a
