//! Bounded pre-relay inspection and byte-preserving pool response streams.

use axum::http::{HeaderMap, StatusCode};
use bytes::{Bytes, BytesMut};
use futures_util::{StreamExt, stream::BoxStream};

const MAX_ERROR_BYTES: usize = 16 * 1024;

pub struct PoolResponse {
    status: StatusCode,
    headers: HeaderMap,
    body: BoxStream<'static, reqwest::Result<Bytes>>,
}

impl PoolResponse {
    /// Inspect an error body, or require a body byte before accepting a
    /// streaming success. All inspected bytes remain in the relay stream.
    pub(crate) async fn prepare(
        response: reqwest::Response,
        probe: bool,
    ) -> crate::translation_core::Outcome<(Self, Bytes), String> {
        let status = response.status();
        let headers = response.headers().clone();
        let mut body = response.bytes_stream().boxed();
        let mut chunks = Vec::new();
        let mut prefix = BytesMut::new();
        let mut pending = None;
        let inspect_error = !status.is_success();
        if inspect_error || probe {
            loop {
                match body.next().await {
                    Some(Ok(chunk)) if chunk.is_empty() => {}
                    Some(Ok(chunk)) => {
                        if inspect_error {
                            let count = chunk.len().min(MAX_ERROR_BYTES - prefix.len());
                            prefix.extend_from_slice(&chunk[..count]);
                        }
                        chunks.push(Ok(chunk));
                        if !inspect_error || prefix.len() >= MAX_ERROR_BYTES {
                            break;
                        }
                    }
                    Some(Err(error)) if !inspect_error => return Err(error.to_string()),
                    Some(Err(error)) => {
                        pending = Some(Err(error));
                        break;
                    }
                    None if !inspect_error => {
                        return Err("upstream stream ended before its first body byte".into());
                    }
                    None => break,
                }
            }
        }
        Ok((
            Self {
                status,
                headers,
                body: futures_util::stream::iter(chunks)
                    .chain(futures_util::stream::iter(pending))
                    .chain(body)
                    .boxed(),
            },
            prefix.freeze(),
        ))
    }

    pub(crate) fn observe(mut self, mut observer: crate::pool_stream_limits::StreamLimits) -> Self {
        self.body = self
            .body
            .map(move |chunk| {
                if let Ok(bytes) = &chunk {
                    observer.push(bytes);
                }
                chunk
            })
            .boxed();
        self
    }

    pub(crate) const fn status(&self) -> StatusCode {
        self.status
    }
    pub(crate) const fn headers(&self) -> &HeaderMap {
        &self.headers
    }
    pub(crate) fn bytes_stream(self) -> BoxStream<'static, reqwest::Result<Bytes>> {
        self.body
    }

    pub(crate) async fn bytes(self) -> reqwest::Result<Bytes> {
        let mut body = self.body;
        let mut bytes = BytesMut::new();
        while let Some(chunk) = body.next().await {
            bytes.extend_from_slice(&chunk?);
        }
        Ok(bytes.freeze())
    }
}

//! Retry rounds bounded by credential count, wait interval and failover budget.

use std::time::{Duration, Instant};

use crate::accounts::{AccountRouter, RoutingContext};

/// Optional additional failover rounds and their credential/wait bounds.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RetryPolicy {
    /// Additional rounds; zero preserves the existing single-round behaviour.
    pub rounds: u32,
    /// Credentials tried in each round; zero uses the failover attempt bound.
    pub max_credentials: u32,
    /// Longest cooldown wait accepted between rounds.
    pub max_interval: Duration,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            rounds: 0,
            max_credentials: 0,
            max_interval: Duration::from_secs(30),
        }
    }
}

pub(crate) struct RetryBudget {
    policy: RetryPolicy,
    round: u32,
    per_round: u32,
    pub(crate) max_attempts: u32,
}

impl RetryBudget {
    pub(crate) fn new(router: crate::translation_core::Maybe<&AccountRouter>, failover: bool, attempts: u32) -> Self {
        let policy = if failover {
            router.map_or_else(RetryPolicy::default, AccountRouter::retry_policy)
        } else {
            RetryPolicy::default()
        };
        let per_round = if failover {
            attempts.max(1).min(if policy.max_credentials == 0 {
                u32::MAX
            } else {
                policy.max_credentials
            })
        } else {
            1
        };
        Self {
            policy,
            round: 0,
            per_round,
            max_attempts: per_round.saturating_mul(policy.rounds.min(16) + 1),
        }
    }

    pub(crate) const fn round_full(&self, context: &RoutingContext) -> bool {
        context.exclude.len() >= self.per_round as usize
    }

    pub(crate) const fn rounds_used(&self) -> u32 {
        self.round
    }

    pub(crate) fn consume_rounds(&mut self, rounds: u32) {
        self.round = rounds.min(self.policy.rounds.min(16));
        self.max_attempts = self
            .per_round
            .saturating_mul(self.policy.rounds.min(16) - self.round + 1);
    }

    pub(crate) async fn next_round(
        &mut self,
        router: Option<&AccountRouter>,
        context: &mut RoutingContext,
        deadline: Instant,
    ) -> bool {
        if self.round >= self.policy.rounds.min(16) {
            tracing::debug!(
                round = self.round,
                rounds = self.policy.rounds,
                "account retry rounds are exhausted"
            );
            return false;
        }
        let Some(delay) = router.and_then(|router| router.retry_delay(context)) else {
            tracing::debug!("no account has an eligible retry recovery");
            return false;
        };
        if delay > self.policy.max_interval
            || deadline.saturating_duration_since(Instant::now()) <= delay
        {
            tracing::debug!(
                delay_ms = delay.as_millis(),
                max_interval_ms = self.policy.max_interval.as_millis(),
                remaining_ms = deadline
                    .saturating_duration_since(Instant::now())
                    .as_millis(),
                "account retry wait exceeds its time bounds"
            );
            return false;
        }
        tracing::debug!(
            round = self.round + 1,
            wait_ms = delay.as_millis(),
            "waiting for an account retry round"
        );
        tokio::time::sleep(delay).await;
        if Instant::now() >= deadline {
            return false;
        }
        self.round += 1;
        context.exclude.clear();
        true
    }
}

//! Observe in-band vendor errors without changing or replaying stream bytes.

use axum::http::HeaderMap;
use serde_json::Value;

use crate::accounts::{AccountRouter, UpstreamObservation};

const MAX_EVENT_BYTES: usize = 64 * 1024;

pub struct StreamLimits {
    router: AccountRouter,
    account: String,
    model: Option<String>,
    line: Vec<u8>,
    oversized: bool,
    relayed: bool,
}

impl StreamLimits {
    pub(crate) fn new(router: AccountRouter, account: String, model: crate::translation_core::Maybe<String>) -> Self {
        // Response streams outlive task-local policy dispatch. Retain its opt-out.
        let scoped = crate::account_policy_scope::current();
        let relayed = scoped.as_ref().is_some_and(|scope| {
            *scope
                .last_action
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                == Some(crate::account_routing_policy::ErrorAction::Relay)
        });
        Self {
            router,
            account,
            model: scoped.map(|scope| scope.upstream_model.clone()).or(model),
            line: Vec::new(),
            oversized: false,
            relayed,
        }
    }

    pub(crate) fn push(&mut self, bytes: &[u8]) {
        for byte in bytes {
            if *byte == b'\n' {
                if !self.oversized {
                    let line = std::mem::take(&mut self.line);
                    if let Some(data) = line.strip_prefix(b"data:")
                        && let Ok(value) = serde_json::from_slice::<Value>(data)
                    {
                        self.observe_event(&value);
                    }
                }
                self.line.clear();
                self.oversized = false;
            } else if !self.oversized {
                if self.line.len() == MAX_EVENT_BYTES {
                    self.line.clear();
                    self.oversized = true;
                } else {
                    self.line.push(*byte);
                }
            }
        }
    }

    /// Also used by WebSocket frames, whose error is already JSON.
    pub(crate) fn observe_event(&self, value: &crate::translation_core::Json) {
        if self.relayed {
            return;
        }
        let kind = value
            .get("type")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if !matches!(kind, "error" | "response.failed") {
            return;
        }
        let error = value
            .get("error")
            .or_else(|| value.pointer("/response/error"));
        let Some(error) = error else {
            return;
        };
        let terminal = crate::account_limits::terminal_quota(error);
        let codes = [error.get("type"), error.get("code")]
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .collect::<Vec<_>>();
        let inferred = if codes.iter().any(|code| {
            matches!(
                *code,
                "authentication_error" | "invalid_api_key" | "token_expired"
            )
        }) {
            401
        } else if terminal
            || codes
                .iter()
                .any(|code| matches!(*code, "rate_limit_error" | "rate_limit_exceeded"))
        {
            429
        } else {
            0
        };
        let status = value
            .get("status")
            .and_then(Value::as_u64)
            .or_else(|| error.get("status").and_then(Value::as_u64))
            .and_then(|status| u16::try_from(status).ok())
            .unwrap_or(inferred);
        if !matches!(status, 401 | 403 | 429) {
            return;
        }
        let retry_after = error
            .get("resets_in_seconds")
            .and_then(Value::as_u64)
            .map(std::time::Duration::from_secs);
        self.router.observe_upstream(&UpstreamObservation {
            account: &self.account,
            model: self.model.as_deref(),
            status,
            headers: &HeaderMap::new(),
            body: &serde_json::json!({"error": error}).to_string().into_bytes(),
            retry_after,
        });
    }
}

//! Explicit primary listener configuration.

use crate::route_contract::ListenerKind;
use crate::tls::TlsSetup;
use std::net::SocketAddr;

/// Wire transport used by one primary listener.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ListenerTransport {
    /// Plain HTTP.
    Http,
    /// HTTPS using Router's configured certificate pair.
    Tls,
}

impl ListenerTransport {
    /// URL scheme exposed by this transport.
    #[must_use]
    pub const fn scheme(self) -> &'static crate::translation_core::Str {
        match self {
            Self::Http => "http",
            Self::Tls => "https",
        }
    }
}

/// One additional network-facing primary listener.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PrimaryListenerConfig {
    /// Concrete address to bind.
    pub address: SocketAddr,
    /// Canonical route set exposed on this socket.
    pub kind: ListenerKind,
    /// Plain HTTP or fail-closed TLS.
    pub transport: ListenerTransport,
}

impl std::str::FromStr for PrimaryListenerConfig {
    type Err = String;

    fn from_str(raw: &str) -> Result<Self, Self::Err> {
        let invalid =
            || format!("invalid listener {raw:?}; expected ADDR=combined|inference-only,http|tls");
        let (address, selection) = raw.split_once('=').ok_or_else(invalid)?;
        let (kind, transport) = selection.split_once(',').ok_or_else(invalid)?;
        if transport.contains(',') {
            return Err(invalid());
        }
        let address = SocketAddr::from_str(address.trim()).map_err(|_| invalid())?;
        let kind = match kind.trim() {
            "combined" => ListenerKind::Combined,
            "inference-only" => ListenerKind::InferenceOnly,
            _ => return Err(invalid()),
        };
        let transport = match transport.trim() {
            "http" => ListenerTransport::Http,
            "tls" => ListenerTransport::Tls,
            _ => return Err(invalid()),
        };
        Ok(Self {
            address,
            kind,
            transport,
        })
    }
}

/// A primary socket reserved during atomic startup.
pub struct BoundPrimaryListener {
    config: PrimaryListenerConfig,
    listener: tokio::net::TcpListener,
    tls: Option<axum_server::tls_rustls::RustlsConfig>,
}

impl BoundPrimaryListener {
    /// Route and transport configuration for this socket.
    #[must_use]
    pub const fn config(&self) -> PrimaryListenerConfig {
        self.config
    }

    /// The actual address selected by the operating system.
    pub fn local_addr(&self) -> std::io::Result<SocketAddr> {
        self.listener.local_addr()
    }

    /// Serve this prebound listener until the shared shutdown notice arrives.
    ///
    /// # Errors
    ///
    /// Returns an error when the HTTP or HTTPS server fails.
    pub async fn serve(
        self,
        app: axum::Router,
        shutdown: impl std::future::Future<Output = ()> + Send + 'static,
    ) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let address = self.listener.local_addr()?;
        tracing::info!(
            "Listening on {}://{} ({:?})",
            self.config.transport.scheme(),
            address,
            self.config.kind
        );
        let result = if let Some(tls) = self.tls {
            crate::tls::serve_prebound_https(self.listener, app, tls, shutdown).await
        } else {
            axum::serve(
                self.listener,
                app.into_make_service_with_connect_info::<SocketAddr>(),
            )
            .with_graceful_shutdown(shutdown)
            .await?;
            Ok(())
        };
        tracing::info!(
            "Stopped {}://{} ({:?})",
            self.config.transport.scheme(),
            address,
            self.config.kind
        );
        result
    }
}

/// Reserve every primary socket before any listener starts serving.
///
/// # Errors
///
/// Returns an error when TLS is not configured or any socket cannot be bound.
pub async fn bind_all(
    listeners: &[PrimaryListenerConfig],
    tls_setup: &TlsSetup,
) -> crate::translation_core::Outcome<Vec<BoundPrimaryListener>, String> {
    let mut bound = Vec::with_capacity(listeners.len());
    for config in listeners {
        let tls = match (config.transport, tls_setup) {
            (ListenerTransport::Http, _) => None,
            (ListenerTransport::Tls, TlsSetup::Enabled { cert, key }) => {
                Some(crate::tls::load_config(cert, key).await?)
            }
            (ListenerTransport::Tls, TlsSetup::Disabled) => {
                return Err(format!(
                    "listener {} requires TLS; configure TLS_CERT_FILE and TLS_KEY_FILE or TLS_SELF_SIGNED=1",
                    config.address
                ));
            }
        };
        let listener = tokio::net::TcpListener::bind(config.address)
            .await
            .map_err(|error| format!("could not bind listener {}: {error}", config.address))?;
        bound.push(BoundPrimaryListener {
            config: *config,
            listener,
            tls,
        });
    }
    Ok(bound)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn listener_grammar_selects_one_canonical_route_set_and_transport() {
        assert_eq!(
            "127.0.0.1:8443=inference-only,tls".parse(),
            Ok(PrimaryListenerConfig {
                address: ([127, 0, 0, 1], 8443).into(),
                kind: ListenerKind::InferenceOnly,
                transport: ListenerTransport::Tls,
            })
        );
        assert_eq!(
            "[::1]:8080=combined,http".parse(),
            Ok(PrimaryListenerConfig {
                address: ([0, 0, 0, 0, 0, 0, 0, 1], 8080).into(),
                kind: ListenerKind::Combined,
                transport: ListenerTransport::Http,
            })
        );
    }

    #[tokio::test]
    async fn every_http_socket_is_reserved_before_serving() {
        let listeners = [
            PrimaryListenerConfig {
                address: ([127, 0, 0, 1], 0).into(),
                kind: ListenerKind::Combined,
                transport: ListenerTransport::Http,
            },
            PrimaryListenerConfig {
                address: ([127, 0, 0, 1], 0).into(),
                kind: ListenerKind::InferenceOnly,
                transport: ListenerTransport::Http,
            },
        ];

        let bound = bind_all(&listeners, &TlsSetup::Disabled)
            .await
            .expect("both sockets should be reserved");
        assert_eq!(bound.len(), 2);
        assert_ne!(
            bound[0].local_addr().unwrap(),
            bound[1].local_addr().unwrap()
        );
    }

    #[tokio::test]
    async fn an_explicit_tls_listener_loads_its_certificate_before_serving() {
        let data_dir = tempfile::tempdir().expect("data directory");
        let (cert, key) = crate::tls::ensure_generated(
            data_dir.path(),
            &crate::tls::generated_subject_names("127.0.0.1"),
        )
        .expect("generate test certificate");
        let listeners = [PrimaryListenerConfig {
            address: ([127, 0, 0, 1], 0).into(),
            kind: ListenerKind::InferenceOnly,
            transport: ListenerTransport::Tls,
        }];

        let bound = bind_all(&listeners, &TlsSetup::Enabled { cert, key })
            .await
            .expect("TLS listener should be fully prepared");
        assert_eq!(bound[0].config(), listeners[0]);
        assert_ne!(bound[0].local_addr().unwrap().port(), 0);
    }

    #[tokio::test]
    async fn a_failed_later_bind_releases_every_earlier_socket() {
        let first = std::net::TcpListener::bind("127.0.0.1:0")
            .expect("reserve first address")
            .local_addr()
            .expect("first address");
        let occupied = std::net::TcpListener::bind("127.0.0.1:0").expect("occupy second address");
        let second = occupied.local_addr().expect("second address");
        let listeners = [first, second].map(|address| PrimaryListenerConfig {
            address,
            kind: ListenerKind::Combined,
            transport: ListenerTransport::Http,
        });

        let Err(error) = bind_all(&listeners, &TlsSetup::Disabled).await else {
            panic!("the occupied second address must fail startup");
        };
        assert!(error.contains(&second.to_string()), "{error}");
        std::net::TcpListener::bind(first).expect("the earlier socket must have been released");
    }

    #[tokio::test]
    async fn tls_transport_never_falls_back_to_plaintext() {
        let listeners = [PrimaryListenerConfig {
            address: ([127, 0, 0, 1], 0).into(),
            kind: ListenerKind::InferenceOnly,
            transport: ListenerTransport::Tls,
        }];
        let Err(error) = bind_all(&listeners, &TlsSetup::Disabled).await else {
            panic!("TLS without a certificate must fail closed");
        };
        assert!(error.contains("requires TLS"), "{error}");
    }

    #[tokio::test]
    async fn a_bound_tls_listener_rejects_plain_http() {
        let data_dir = tempfile::tempdir().expect("data directory");
        let (cert, key) = crate::tls::ensure_generated(
            data_dir.path(),
            &crate::tls::generated_subject_names("127.0.0.1"),
        )
        .expect("generate test certificate");
        let listeners = [PrimaryListenerConfig {
            address: ([127, 0, 0, 1], 0).into(),
            kind: ListenerKind::InferenceOnly,
            transport: ListenerTransport::Tls,
        }];
        let listener = bind_all(
            &listeners,
            &TlsSetup::Enabled {
                cert: cert.clone(),
                key,
            },
        )
        .await
        .expect("prepare TLS listener")
        .pop()
        .expect("one listener");
        let port = listener.local_addr().expect("bound address").port();
        let serving = tokio::spawn(listener.serve(
            axum::Router::new().route("/health", axum::routing::get(|| async { "ok" })),
            std::future::pending(),
        ));

        let trusted = reqwest::Client::builder()
            .add_root_certificate(
                reqwest::Certificate::from_pem(&std::fs::read(cert).expect("read certificate"))
                    .expect("parse certificate"),
            )
            .build()
            .expect("TLS client");
        let url = format!("https://127.0.0.1:{port}/health");
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while trusted.get(&url).send().await.is_err() {
            assert!(
                std::time::Instant::now() < deadline,
                "TLS never became ready"
            );
            tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        }
        let plaintext = reqwest::Client::new()
            .get(format!("http://127.0.0.1:{port}/health"))
            .timeout(std::time::Duration::from_secs(2))
            .send()
            .await;
        serving.abort();

        assert!(
            plaintext.is_err(),
            "a TLS listener must never answer plaintext"
        );
    }
}

//! Process modes that run before ordinary CLI dispatch.
use std::process::ExitCode;

/// Run daemon modes or the human/JSON CLI adapter.
pub async fn run_from_environment() -> ExitCode {
    let daemon = crate::operation_context::var_os(crate::deploy_relay::STATE_ENV).is_some()
        || crate::operation_context::var_os("LINK_ASSISTANT_ROUTER_INTERNAL_CODEX_BRIDGE")
            .is_some();
    if daemon {
        crate::logging::run(
            &crate::config::default_data_dir(),
            false,
            "daemon",
            Vec::new(),
            true,
            Box::pin(run_inner()),
        )
        .await
    } else {
        run_inner().await
    }
}

/// Run the process adapter, including daemon modes.
async fn run_inner() -> ExitCode {
    match link_assistant_router::deploy_relay::run_from_env().await {
        Ok(Some(())) => return ExitCode::SUCCESS,
        Ok(None) => {}
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    }
    match link_assistant_router::codex_loopback_bridge::daemon_request_from_env() {
        Ok(Some(request)) => {
            return match link_assistant_router::codex_loopback_bridge::run_persistent_daemon(
                request,
            )
            .await
            {
                Ok(()) => ExitCode::SUCCESS,
                Err(error) => {
                    eprintln!("error: {error}");
                    ExitCode::from(1)
                }
            };
        }
        Ok(None) => {}
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    }
    let arguments =
        link_assistant_router::cli::protect_client_arguments(std::env::args_os().collect(), true);
    crate::operations::run_arguments(arguments).await
}

//! Transactional acceptance for persisted upstream providers.

use serde::{Deserialize, Serialize};

use crate::providers::{
    ProviderError, ProviderKind, ProviderRecord, ProviderStore, ProviderUpsert,
};

/// Atomic installation policy for a staged provider record.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProviderInstallMode {
    Replace,
    IfAbsent,
}

/// Result of atomically installing a staged provider record.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProviderInstallResult {
    Created(ProviderRecord),
    Replaced(ProviderRecord),
    AlreadyPresent(ProviderRecord),
}

/// Stable machine-readable provider provisioning outcome.
#[derive(Debug, Clone, Copy, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum ProviderProvisionOutcome {
    Created,
    Replaced,
    AlreadyPresent,
}

/// A completed provider provisioning transaction.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProviderProvision {
    pub outcome: ProviderProvisionOutcome,
    pub record: ProviderRecord,
}

/// Public response with provider configuration but no credential or subscriber identity.
#[derive(Debug, Deserialize, Serialize)]
pub struct ProviderProvisionResponse {
    pub outcome: ProviderProvisionOutcome,
    pub name: String,
    pub kind: ProviderKind,
    pub base_url: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_model: Option<String>,
    pub models: Vec<String>,
    pub supported_clients: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub api_key_env: Option<String>,
    pub has_encrypted_api_key: bool,
    pub enabled: bool,
    pub intermediary_risk_acknowledged: bool,
    pub unsupported_clients: Vec<String>,
}

impl ProviderProvision {
    #[must_use]
    pub fn response(&self) -> ProviderProvisionResponse {
        let redacted = self.record.redacted();
        ProviderProvisionResponse {
            outcome: self.outcome,
            name: redacted.name,
            kind: redacted.kind,
            base_url: redacted.base_url,
            default_model: redacted.default_model,
            models: redacted.models,
            supported_clients: redacted.supported_clients,
            api_key_env: redacted.api_key_env,
            has_encrypted_api_key: redacted.has_encrypted_api_key,
            enabled: redacted.enabled,
            intermediary_risk_acknowledged: redacted.intermediary_risk_acknowledged,
            unsupported_clients: redacted.unsupported_clients,
        }
    }
}

/// Stable machine-readable reason a candidate was not promoted.
#[derive(Debug, Clone, Copy, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum ProviderProvisionFailureKind {
    InvalidCandidate,
    CredentialRejected,
    RateLimited,
    Unverified,
    PersistenceUncertain,
}

/// Secret-free provider acceptance failure.
#[derive(Debug)]
pub struct ProviderProvisionFailure {
    kind: ProviderProvisionFailureKind,
    message: &'static str,
}

impl ProviderProvisionFailure {
    const fn new(kind: ProviderProvisionFailureKind, message: &'static str) -> Self {
        Self { kind, message }
    }

    #[must_use]
    pub const fn kind(&self) -> ProviderProvisionFailureKind {
        self.kind
    }
}

impl std::fmt::Display for ProviderProvisionFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(self.message)
    }
}

impl std::error::Error for ProviderProvisionFailure {}

/// Stage, validate without inference, and atomically promote one provider.
pub async fn provision(
    client: &reqwest::Client,
    store: &ProviderStore,
    input: ProviderUpsert,
) -> Result<ProviderProvision, ProviderProvisionFailure> {
    let mode = if input.if_absent {
        ProviderInstallMode::IfAbsent
    } else {
        ProviderInstallMode::Replace
    };
    let candidate = store.stage(input).map_err(stage_failure)?;
    if mode == ProviderInstallMode::IfAbsent
        && let Some(record) = store.get(&candidate.name).map_err(persistence_failure)?
    {
        return Ok(ProviderProvision {
            outcome: ProviderProvisionOutcome::AlreadyPresent,
            record,
        });
    }
    if candidate.kind == ProviderKind::ZaiCodingPlan {
        let resolved = store.resolve_record(&candidate).map_err(stage_failure)?;
        crate::zai_coding_plan::fetch_catalog(client, &resolved)
            .await
            .map_err(|error| {
                use crate::zai_coding_plan::ZaiProbeFailureKind as Kind;
                let kind = match error.kind() {
                    Kind::CredentialRejected => ProviderProvisionFailureKind::CredentialRejected,
                    Kind::RateLimited => ProviderProvisionFailureKind::RateLimited,
                    Kind::Unverified => ProviderProvisionFailureKind::Unverified,
                };
                ProviderProvisionFailure::new(kind, "provider candidate was not accepted")
            })?;
    }
    if candidate.kind == ProviderKind::Lefine {
        let resolved = store.resolve_record(&candidate).map_err(stage_failure)?;
        crate::lefine::fetch_catalog(client, &resolved)
            .await
            .map_err(|error| {
                use crate::lefine::CatalogFailureKind as Kind;
                let kind = match error.kind() {
                    Kind::CredentialRejected => ProviderProvisionFailureKind::CredentialRejected,
                    Kind::RateLimited => ProviderProvisionFailureKind::RateLimited,
                    Kind::Unavailable => ProviderProvisionFailureKind::Unverified,
                };
                ProviderProvisionFailure::new(kind, "provider candidate was not accepted")
            })?;
    }
    let installed = store.promote(candidate, mode).map_err(promotion_failure)?;
    let (outcome, record) = match installed {
        ProviderInstallResult::Created(record) => (ProviderProvisionOutcome::Created, record),
        ProviderInstallResult::Replaced(record) => (ProviderProvisionOutcome::Replaced, record),
        ProviderInstallResult::AlreadyPresent(record) => {
            (ProviderProvisionOutcome::AlreadyPresent, record)
        }
    };
    Ok(ProviderProvision { outcome, record })
}

fn stage_failure(error: ProviderError) -> ProviderProvisionFailure {
    match error {
        ProviderError::Invalid(_) => ProviderProvisionFailure::new(
            ProviderProvisionFailureKind::InvalidCandidate,
            "provider candidate is invalid",
        ),
        _ => persistence_failure(error),
    }
}

fn promotion_failure(error: ProviderError) -> ProviderProvisionFailure {
    match error {
        ProviderError::Invalid(_) => ProviderProvisionFailure::new(
            ProviderProvisionFailureKind::InvalidCandidate,
            "provider candidate conflicts with active policy",
        ),
        _ => persistence_failure(error),
    }
}

fn persistence_failure(_error: ProviderError) -> ProviderProvisionFailure {
    ProviderProvisionFailure::new(
        ProviderProvisionFailureKind::PersistenceUncertain,
        "provider store could not confirm the transaction",
    )
}

