}

/// In-memory live catalog state. Provider configuration remains file-backed;
/// discovery results are deliberately process-local and refreshed by identity.
#[derive(Debug, Clone)]
pub(crate) struct CachedProviderCatalog {
    pub fingerprint: String,
    pub models: Vec<LiveProviderModel>,
    pub last_success: Option<Instant>,
    pub last_attempt: Instant,
    pub error: Option<String>,
}

impl ResolvedProvider {
    /// Whether this provider advertises `model` by name.
    ///
    /// A declared model is what lets a stored provider win a route in
    /// automatic mode, instead of being reachable only by pinning the whole
    /// deployment to it (issue #260).
    #[must_use]
    pub fn declares(&self, model: &str) -> bool {
        self.models.iter().any(|id| id == model)
    }

    /// Whether this provider's reviewed adapter supports the exact client.
    #[must_use]
    pub fn supports_client(&self, client: crate::clients::ClientKind) -> bool {
        self.supported_clients
            .iter()
            .any(|value| value == client.canonical_name())
    }
}

/// File-backed provider store.
#[derive(Clone)]
pub struct ProviderStore {
    path: PathBuf,
    lock_path: PathBuf,
    token_secret: Arc<String>,
    inner: Arc<RwLock<HashMap<String, ProviderRecord>>>,
    entitlement_policy: Arc<RwLock<crate::client_policy::SubscriptionEntitlementPolicy>>,
    provider_catalogs: Arc<RwLock<HashMap<String, CachedProviderCatalog>>>,
    exhaustions: Arc<RwLock<HashMap<String, crate::zai_upstream_error::ZaiExhaustion>>>,
    data_dir: PathBuf,
    response_affinities: crate::response_affinity::ResponseAffinityStore,
    codex_remote_control: crate::codex_remote_control::CodexRemoteControlStore,
}

impl ProviderStore {
    /// Open a provider store at `<data_dir>/providers.lenv`.
    pub fn open(data_dir: &Path, token_secret: &str) -> Result<Self, ProviderError> {
        let path = data_dir.join("providers.lenv");
        let lock_path = path.with_extension("lock");
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        let records = crate::durable_file::with_exclusive_lock(&lock_path, || {
            crate::durable_file::recover_transactional_write(&path)?;
            if path.exists() {
                decode_provider_lenv(&fs::read_to_string(&path)?)
            } else {
                Ok(Vec::new())
            }
        })?;
        let inner = records
            .into_iter()
            .map(|record| (record.name.clone(), record))
            .collect();
        let response_affinities = crate::response_affinity::ResponseAffinityStore::open(data_dir)
            .map_err(|error| ProviderError::Invalid(error.to_string()))?;
        let codex_remote_control =
            crate::codex_remote_control::CodexRemoteControlStore::open(data_dir, token_secret)
                .map_err(|error| ProviderError::Invalid(error.to_string()))?;
        Ok(Self {
            lock_path,
            path,
            token_secret: Arc::new(token_secret.to_string()),
            inner: Arc::new(RwLock::new(inner)),
            entitlement_policy: Arc::new(RwLock::new(
                crate::client_policy::SubscriptionEntitlementPolicy::default(),
            )),
            provider_catalogs: Arc::new(RwLock::new(HashMap::new())),
            exhaustions: Arc::new(RwLock::new(crate::zai_upstream_error::load(data_dir))),
            data_dir: data_dir.to_path_buf(),
            response_affinities,
            codex_remote_control,
        })
    }

    pub(crate) const fn response_affinities(
        &self,
    ) -> &crate::response_affinity::ResponseAffinityStore {
        &self.response_affinities
    }

    pub(crate) const fn codex_remote_control(
        &self,
    ) -> &crate::codex_remote_control::CodexRemoteControlStore {
        &self.codex_remote_control
    }

    /// Install the boot-validated consumer-subscription bridge policy.
    pub fn set_subscription_entitlement_policy(
        &self,
        policy: crate::client_policy::SubscriptionEntitlementPolicy,
    ) -> Result<(), ProviderError> {
        *self
            .entitlement_policy
            .write()
            .map_err(|_| ProviderError::LockPoisoned)? = policy;
        Ok(())
    }

    /// Snapshot the policy used by catalog and dispatch.
    pub fn subscription_entitlement_policy(
        &self,
    ) -> Result<crate::client_policy::SubscriptionEntitlementPolicy, ProviderError> {
        self.entitlement_policy
            .read()
            .map_err(|_| ProviderError::LockPoisoned)
            .map(|policy| policy.clone())
    }

    pub(crate) fn cached_provider_catalog(
        &self,
        name: &str,
    ) -> Result<Option<CachedProviderCatalog>, ProviderError> {
        self.provider_catalogs
            .read()
            .map_err(|_| ProviderError::LockPoisoned)
            .map(|catalogs| catalogs.get(name).cloned())
    }

    pub(crate) fn cache_provider_catalog(
        &self,
        name: &str,
        catalog: CachedProviderCatalog,
    ) -> Result<(), ProviderError> {
        self.provider_catalogs
            .write()
            .map_err(|_| ProviderError::LockPoisoned)?
            .insert(name.to_string(), catalog);
        Ok(())
    }

    /// Record that a provider's account refused inference until the operator
    /// acts (issue #657). The next successful response clears it; until then
    /// it is kept under the data directory, so it survives a restart and
    /// offline diagnostics see it.
    pub(crate) fn record_exhaustion(
        &self,
        name: &str,
        exhaustion: crate::zai_upstream_error::ZaiExhaustion,
    ) {
        if let Ok(mut exhaustions) = self.exhaustions.write() {
            exhaustions.insert(name.to_string(), exhaustion);
            crate::zai_upstream_error::save(&self.data_dir, &exhaustions);
        }
    }

    /// Forget a recorded exhaustion after the provider served a request.
    pub(crate) fn clear_exhaustion(&self, name: &str) {
        if let Ok(mut exhaustions) = self.exhaustions.write()
            && exhaustions.remove(name).is_some()
        {
            crate::zai_upstream_error::save(&self.data_dir, &exhaustions);
        }
    }

    /// The provider's last recorded exhaustion, if it has not served since.
    #[must_use]
    pub fn exhaustion(&self, name: &str) -> Option<crate::zai_upstream_error::ZaiExhaustion> {
        self.exhaustions
            .read()
            .ok()
            .and_then(|exhaustions| exhaustions.get(name).cloned())
    }

    /// Return all providers sorted by name.
    pub fn list(&self) -> Result<Vec<ProviderRecord>, ProviderError> {
        self.refresh()?;
        let mut records: Vec<_> = {
            let guard = self.inner.read().map_err(|_| ProviderError::LockPoisoned)?;
            guard.values().cloned().collect()
        };
        records.sort_by(|a, b| a.name.cmp(&b.name));
        Ok(records)
    }

    /// Return all providers with secrets redacted.
    pub fn list_redacted(&self) -> Result<Vec<RedactedProviderRecord>, ProviderError> {
        Ok(self.list()?.iter().map(ProviderRecord::redacted).collect())
    }

    /// Get one provider by name.
    pub fn get(&self, name: &str) -> Result<Option<ProviderRecord>, ProviderError> {
        self.refresh()?;
        let guard = self.inner.read().map_err(|_| ProviderError::LockPoisoned)?;
        Ok(guard.get(name).cloned())
    }

    /// Add or replace a provider, encrypting any inline API key.
    pub fn upsert(&self, input: ProviderUpsert) -> Result<ProviderRecord, ProviderError> {
        let record = self.stage(input)?;
        match self.promote(record, ProviderInstallMode::Replace)? {
            ProviderInstallResult::Created(record)
            | ProviderInstallResult::Replaced(record)
            | ProviderInstallResult::AlreadyPresent(record) => Ok(record),
        }
    }

    /// Build and encrypt a candidate without changing the active store.
    pub fn stage(&self, input: ProviderUpsert) -> Result<ProviderRecord, ProviderError> {
        self.build_record(input)
    }

    /// Atomically promote a previously validated candidate.
    pub fn promote(
        &self,
        record: ProviderRecord,
        mode: ProviderInstallMode,
    ) -> Result<ProviderInstallResult, ProviderError> {
        let name = record.name.clone();
        let result = self.mutate(
            |records| -> (Result<ProviderInstallResult, ProviderError>, bool) {
                if mode == ProviderInstallMode::IfAbsent
                    && let Some(existing) = records.get(&record.name)
                {
                    return (
                        Ok(ProviderInstallResult::AlreadyPresent(existing.clone())),
                        false,
                    );
                }
                if record.enabled
                    && record.kind == ProviderKind::ZaiCodingPlan
                    && records.values().any(|existing| {
                        existing.enabled
                            && existing.kind == ProviderKind::ZaiCodingPlan
                            && existing.name != record.name
                    })
                {
                    return (
                        Err(ProviderError::Invalid(
                            "only one personal z.ai Coding Plan subscriber may be enabled".into(),
                        )),
                        false,
                    );
                }
                let replaced = records.contains_key(&record.name);
                records.insert(record.name.clone(), record.clone());
                let result = if replaced {
                    ProviderInstallResult::Replaced(record)
                } else {
                    ProviderInstallResult::Created(record)
                };
                (Ok(result), true)
            },
        )?;
        // A replaced key or account may have quota; the next request re-learns.
        if matches!(
            result,
            Ok(ProviderInstallResult::Created(_) | ProviderInstallResult::Replaced(_))
        ) {
            self.clear_exhaustion(&name);
        }
        result
    }

    /// Delete a provider by name.
    pub fn delete(&self, name: &str) -> Result<bool, ProviderError> {
        let removed = self.mutate(|records| {
            let removed = records.remove(name).is_some();
            (removed, removed)
        })?;
        if removed {
            self.clear_exhaustion(name);
        }
        Ok(removed)
    }

    /// Import providers from JSON, `.lenv`, or indented Links-style config.
    pub fn import_file(&self, path: &Path) -> Result<usize, ProviderError> {
        let text = fs::read_to_string(path)?;
        let inputs = parse_provider_import(&text)?;
        let count = inputs.len();
        for input in inputs {
            self.upsert(input)?;
        }
        Ok(count)
    }

    /// Resolve a provider plus decrypted API key for forwarding.
    pub fn resolve(&self, name: &str) -> Result<Option<ResolvedProvider>, ProviderError> {
        let Some(record) = self.get(name)? else {
            return Ok(None);
        };
        if !record.enabled {
            return Ok(None);
        }
        self.resolve_record(&record).map(Some)
    }

    /// Resolve a staged record without installing it.
    pub fn resolve_record(
        &self,
        record: &ProviderRecord,
    ) -> Result<ResolvedProvider, ProviderError> {
        let api_key = record
            .api_key_env
            .as_deref()
            .and_then(|env_name| crate::operation_context::var(env_name).ok())
            .filter(|s| !s.is_empty())
            .map(Ok)
            .or_else(|| {
                record
                    .encrypted_api_key
                    .as_deref()
                    .map(|encrypted| decrypt_api_key(encrypted, &self.token_secret))
            })
            .transpose()?;
        let supported_clients = record.effective_supported_clients();
        Ok(ResolvedProvider {
            name: record.name.clone(),
            kind: record.kind,
            base_url: record.base_url.clone(),
            default_model: record.default_model.clone(),
            models: record.models.clone(),
            supported_clients,
            api_key,
            subscriber_id: record.subscriber_id.clone(),
            intermediary_risk_acknowledged: record.intermediary_risk_acknowledged,
            unsupported_clients: record.unsupported_clients.clone(),
        })
    }

    fn build_record(&self, input: ProviderUpsert) -> Result<ProviderRecord, ProviderError> {
        let name = normalize_name(&input.name)?;
        let kind = match input.kind.as_deref() {
            Some(value) => ProviderKind::from_str_opt(value)
                .ok_or_else(|| ProviderError::Invalid(format!("unknown provider kind: {value}")))?,
            None => ProviderKind::default(),
        };
        if name == "z.ai" && kind != ProviderKind::ZaiCodingPlan {
            return Err(ProviderError::Invalid(
                "provider name 'z.ai' is reserved for the Coding Plan model namespace".into(),
            ));
        }
        let base_url = input.base_url.trim_end_matches('/').to_string();
        if base_url.is_empty() {
            return Err(ProviderError::Invalid("base_url is required".into()));
        }
        crate::upstream_client::check_provider_base_url(&base_url)
            .map_err(|error| ProviderError::Invalid(error.to_string()))?;
        let encrypted_api_key = match input.api_key.as_deref().filter(|s| !s.is_empty()) {
            Some(key) => Some(encrypt_api_key(key, &self.token_secret)?),
            None => input.encrypted_api_key.filter(|s| !s.is_empty()),
        };
        let models = input.models.unwrap_or_default();
        let mut supported_clients = input.supported_clients.unwrap_or_default();
        for value in &supported_clients {
            let client = crate::clients::ClientKind::from_str_opt(value).ok_or_else(|| {
                ProviderError::Invalid(format!("unknown supported client: {value}"))
            })?;
            if value != client.canonical_name() {
                return Err(ProviderError::Invalid(format!(
                    "supported client must use canonical name '{}'",
                    client.canonical_name()
                )));
            }
        }
        supported_clients.sort();
        supported_clients.dedup();
        let subscriber_id = input.subscriber_id.filter(|value| !value.trim().is_empty());
        let intermediary_risk_acknowledged = input.acknowledge_intermediary_risk.unwrap_or(false);
        let unsupported_clients = input.acknowledge_unsupported_clients.unwrap_or_default();
        let enabled = input.enabled.unwrap_or(kind != ProviderKind::ZaiCodingPlan);
        if kind == ProviderKind::ZaiCodingPlan {
            if !supported_clients.is_empty() {
                return Err(ProviderError::Invalid(
                    "z.ai Coding Plan client compatibility is derived from its reviewed policy; use --acknowledge-unsupported-client for a risk-accepted client".into(),
                ));
            }
            if base_url != "https://api.z.ai" && !cfg!(test) {
                return Err(ProviderError::Invalid(
                    "z.ai Coding Plan base_url must be https://api.z.ai".into(),
                ));
            }
            let subscriber = subscriber_id.as_deref().ok_or_else(|| {
                ProviderError::Invalid("z.ai Coding Plan requires --subscriber-id".into())
            })?;
            crate::zai_coding_plan::ZaiCodingPlanPolicy::new(
                subscriber,
                intermediary_risk_acknowledged,
                &unsupported_clients,
            )
            .map_err(ProviderError::Invalid)?;
            if models.iter().any(|model| model.trim().is_empty()) {
                return Err(ProviderError::Invalid(
                    "z.ai Coding Plan model identifiers cannot be empty".into(),
                ));
            }
            if enabled && !intermediary_risk_acknowledged {
                return Err(ProviderError::Invalid(
                    "enabling z.ai Coding Plan requires --acknowledge-intermediary-risk".into(),
                ));
            }
        } else {
            if kind == ProviderKind::Lefine {
                validate_lefine_config(
                    &base_url,
                    &models,
                    &supported_clients,
                    input.default_model.as_deref(),
                )?;
            }
            if subscriber_id.is_some()
                || intermediary_risk_acknowledged
                || !unsupported_clients.is_empty()
            {
                return Err(ProviderError::Invalid(
                    "Coding Plan subscriber/risk settings require kind z.ai-coding-plan".into(),
                ));
            }
        }
        Ok(ProviderRecord {
            name,
            kind,
            base_url,
            default_model: input.default_model.filter(|s| !s.is_empty()),
            models,
            supported_clients,
            api_key_env: input.api_key_env.filter(|s| !s.is_empty()),
            encrypted_api_key,
            enabled,
            subscriber_id,
            intermediary_risk_acknowledged,
            unsupported_clients,
        })
    }

    fn flush(&self, guard: &HashMap<String, ProviderRecord>) -> Result<(), ProviderError> {
        let mut records: Vec<&ProviderRecord> = guard.values().collect();
        records.sort_by(|a, b| a.name.cmp(&b.name));
        let body = encode_provider_lenv(records.iter().copied())?;
        atomic_write(&self.path, body.as_bytes())?;
        Ok(())
    }

    fn load_map(&self) -> Result<HashMap<String, ProviderRecord>, ProviderError> {
        if !self.path.exists() {
            return Ok(HashMap::new());
        }
        Ok(decode_provider_lenv(&fs::read_to_string(&self.path)?)?
            .into_iter()
            .map(|record| (record.name.clone(), record))
            .collect())
    }

    fn refresh(&self) -> Result<(), ProviderError> {
        crate::durable_file::with_exclusive_lock(&self.lock_path, || {
            crate::durable_file::recover_transactional_write(&self.path)?;
            let records = self.load_map()?;
            *self
                .inner
                .write()
                .map_err(|_| ProviderError::LockPoisoned)? = records;
            Ok(())
        })
    }

    fn mutate<T>(
        &self,
        operation: impl FnOnce(&mut HashMap<String, ProviderRecord>) -> (T, bool),
    ) -> Result<T, ProviderError> {
        crate::durable_file::with_exclusive_lock(&self.lock_path, || {
            crate::durable_file::recover_transactional_write(&self.path)?;
            let mut guard = self
                .inner
                .write()
                .map_err(|_| ProviderError::LockPoisoned)?;
            *guard = self.load_map()?;
            let before = guard.clone();
            let (result, changed) = operation(&mut guard);
            if !changed {
                return Ok(result);
            }
            if let Err(error) = self.flush(&guard) {
                *guard = before;
                drop(guard);
                return Err(error);
            }
            drop(guard);
            Ok(result)
        })
    }
}

/// Errors returned by provider storage and encryption.
#[derive(Debug)]
pub enum ProviderError {
    Io(io::Error),
    Json(serde_json::Error),
    Base64(base64::DecodeError),
    Crypto(String),
    Invalid(String),
    LockPoisoned,
}

impl std::fmt::Display for ProviderError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Io(e) => write!(f, "provider storage I/O error: {e}"),
            Self::Json(e) => write!(f, "provider JSON error: {e}"),
            Self::Base64(e) => write!(f, "provider secret base64 error: {e}"),
            Self::Crypto(e) => write!(f, "provider secret crypto error: {e}"),
            Self::Invalid(e) => write!(f, "invalid provider config: {e}"),
            Self::LockPoisoned => write!(f, "provider store lock poisoned"),
        }
    }
}

impl std::error::Error for ProviderError {}

impl From<io::Error> for ProviderError {
    fn from(value: io::Error) -> Self {
        Self::Io(value)
    }
}

impl From<serde_json::Error> for ProviderError {
    fn from(value: serde_json::Error) -> Self {
        Self::Json(value)
    }
}

impl From<base64::DecodeError> for ProviderError {
    fn from(value: base64::DecodeError) -> Self {
        Self::Base64(value)
    }
}

fn validate_lefine_config(
    base_url: &str,
    models: &[String],
    supported_clients: &[String],
    default_model: Option<&str>,
) -> Result<(), ProviderError> {
    if base_url != crate::lefine::BASE_URL && !cfg!(test) {
        return Err(ProviderError::Invalid(format!(
            "Lefine base_url must be {}",
            crate::lefine::BASE_URL
        )));
    }
    if !supported_clients.is_empty() {
        return Err(ProviderError::Invalid(
            "Lefine client compatibility is fixed by its native Chat Completions adapter".into(),
        ));
    }
    let mut seen = std::collections::HashSet::new();
    for model in models {
        if model.is_empty() || model != model.trim() || !seen.insert(model) {
            return Err(ProviderError::Invalid(
                "Lefine fallback models must be unique non-empty exact ids".into(),
            ));
        }
    }
    if let Some(default) = default_model {
        if default.is_empty() || default != default.trim() {
            return Err(ProviderError::Invalid(
                "Lefine default_model must be a non-empty exact id".into(),
            ));
        }
        if !models.is_empty() && !models.iter().any(|model| model == default) {
            return Err(ProviderError::Invalid(
                "Lefine default_model must occur in configured fallback models".into(),
            ));
        }
    }
    Ok(())
}

fn normalize_name(name: &str) -> Result<String, ProviderError> {
    let name = name.trim();
    if name.is_empty() {
        return Err(ProviderError::Invalid("name is required".into()));
    }
    if name
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.'))
    {
        return Ok(name.to_string());
    }
    Err(ProviderError::Invalid(
        "name may contain only ASCII letters, digits, dash, underscore, and dot".into(),
    ))
}

fn cipher(token_secret: &str) -> Result<Aes256Gcm, ProviderError> {
    // The key is `SHA256(token_secret)`, so a stand-in secret wraps a vendor
    // API key in a value published in the source — `has_encrypted_api_key:
    // true` while the key is effectively in the clear (issue #300).
    crate::token_secret::ensure_real(token_secret).map_err(ProviderError::Invalid)?;
    let key = Sha256::digest(token_secret.as_bytes());
    Aes256Gcm::new_from_slice(&key)
        .map_err(|e| ProviderError::Crypto(format!("invalid AES key: {e}")))
}

fn encrypt_api_key(api_key: &str, token_secret: &str) -> Result<String, ProviderError> {
    let cipher = cipher(token_secret)?;
    let nonce = Nonce::try_generate()
        .map_err(|e| ProviderError::Crypto(format!("nonce generation failed: {e}")))?;
    let encrypted = cipher
        .encrypt(&nonce, api_key.as_bytes())
        .map_err(|e| ProviderError::Crypto(format!("encrypt failed: {e}")))?;
    let mut packed = nonce.to_vec();
    packed.extend_from_slice(&encrypted);
    Ok(format!("aes256gcm:{}", STANDARD.encode(packed)))
}

/// Encrypt another Router-owned secret with the same deployment key used for
/// provider credentials. The format stays private to durable Router stores.
pub(crate) fn seal_secret(secret: &str, token_secret: &str) -> Result<String, ProviderError> {
    encrypt_api_key(secret, token_secret)
}

/// The key a published stand-in would have produced, for recognition only.
///
/// Never used to encrypt: `cipher` refuses every placeholder, which is the
/// whole of issue #300. This exists so a record the old build wrote can be
/// named as disclosed instead of failing opaquely.
fn legacy_cipher(placeholder: &str) -> Option<Aes256Gcm> {
    let key = Sha256::digest(placeholder.as_bytes());
    Aes256Gcm::new_from_slice(&key).ok()
}

fn decrypt_api_key(encrypted: &str, token_secret: &str) -> Result<String, ProviderError> {
    let encoded = encrypted
        .strip_prefix("aes256gcm:")
        .ok_or_else(|| ProviderError::Invalid("unsupported provider secret format".into()))?;
    let packed = STANDARD.decode(encoded)?;
    if packed.len() < 13 {
        return Err(ProviderError::Invalid(
            "encrypted provider secret is too short".into(),
        ));
    }
    let (nonce_bytes, ciphertext) = packed.split_at(12);
    let mut nonce = Nonce::default();
    nonce.copy_from_slice(nonce_bytes);
    let plaintext = match cipher(token_secret)?.decrypt(&nonce, ciphertext) {
        Ok(plaintext) => plaintext,
        Err(error) => {
            // A record that decrypts under a published stand-in was encrypted
            // under a key anyone can read out of the source. That key must be
            // considered disclosed, and the operator told so plainly rather
            // than left with an opaque failure to interpret (issue #300).
            for placeholder in crate::token_secret::LEGACY_PLACEHOLDERS {
                // Built directly rather than through `cipher`, which now
                // refuses a stand-in: the point here is to recognise a record
                // the old build wrote, so the detection must be able to derive
                // the very key that must never be used to write another.
                if legacy_cipher(placeholder)
                    .is_some_and(|legacy| legacy.decrypt(&nonce, ciphertext).is_ok())
                {
                    return Err(ProviderError::Crypto(format!(
                        "this provider's API key was encrypted under the placeholder secret \
                         `{placeholder}`, which is published in the router's own source: treat \
                         the key as disclosed, rotate it at the vendor, and re-enter it with \
                         `providers add --api-key-stdin` under a real TOKEN_SECRET"
                    )));
                }
            }
            return Err(ProviderError::Crypto(format!("decrypt failed: {error}")));
        }
    };
    String::from_utf8(plaintext)
        .map_err(|e| ProviderError::Crypto(format!("secret is not UTF-8: {e}")))
}

/// Decrypt a value produced by [`seal_secret`].
pub(crate) fn open_secret(encrypted: &str, token_secret: &str) -> Result<String, ProviderError> {
    decrypt_api_key(encrypted, token_secret)
}

fn encode_provider_lenv<'a>(
    records: impl IntoIterator<Item = &'a ProviderRecord>,
) -> Result<String, ProviderError> {
    let mut out = String::new();
    out.push_str("# Link.Assistant.Router provider store\n");
    out.push_str("# Each PROVIDER value is JSON; inline API keys are encrypted.\n");
    for record in records {
        out.push_str("PROVIDER: ");
        out.push_str(&serde_json::to_string(record)?);
        out.push('\n');
    }
    Ok(out)
}

fn decode_provider_lenv(input: &str) -> Result<Vec<ProviderRecord>, ProviderError> {
    let mut records = Vec::new();
    for raw in input.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(json) = line.strip_prefix("PROVIDER: ") {
            records.push(serde_json::from_str(json)?);
        }
    }
    Ok(records)
}

#[path = "provider_import.rs"]
mod provider_import;
pub use provider_import::parse_provider_import;

fn atomic_write(path: &Path, contents: &[u8]) -> Result<(), ProviderError> {
    crate::durable_file::transactional_write_owner_only(path, contents).map_err(Into::into)
}

#[cfg(test)]
#[path = "providers_tests.rs"]
mod tests;

use super::{ProviderError, ProviderKind, ProviderUpsert};

/// Parse a provider manifest without a store to write it into.
///
/// Public so a remote `providers import` can read the manifest on *this*
/// machine and declare each provider on the selected deployment, which is what
/// importing into another router means (issue #294).
///
/// # Errors
///
/// Returns the parse error when the manifest is not readable as provider
/// declarations.
pub fn parse_provider_import(input: &str) -> Result<Vec<ProviderUpsert>, ProviderError> {
    let trimmed = input.trim_start();
    let providers = if trimmed.starts_with('{') {
        let doc: serde_json::Value = serde_json::from_str(input)?;
        if let Some(providers) = doc.get("providers").and_then(serde_json::Value::as_array) {
            providers
                .iter()
                .cloned()
                .map(serde_json::from_value)
                .collect::<Result<Vec<_>, _>>()
                .map_err(ProviderError::Json)?
        } else {
            vec![serde_json::from_value(doc).map_err(ProviderError::Json)?]
        }
    } else if trimmed.starts_with('[') {
        serde_json::from_str(input).map_err(ProviderError::Json)?
    } else {
        parse_lenv_or_indented(input)?
    };
    reject_plaintext_lefine_imports(&providers)?;
    Ok(providers)
}

fn reject_plaintext_lefine_imports(providers: &[ProviderUpsert]) -> Result<(), ProviderError> {
    if providers.iter().any(|provider| {
        provider
            .kind
            .as_deref()
            .and_then(ProviderKind::from_str_opt)
            == Some(ProviderKind::Lefine)
            && provider
                .api_key
                .as_deref()
                .is_some_and(|key| !key.is_empty())
    }) {
        return Err(ProviderError::Invalid(
            "Lefine import files cannot contain plaintext api_key material; use api_key_env or providers add --api-key-stdin"
                .into(),
        ));
    }
    Ok(())
}

fn parse_lenv_or_indented(input: &str) -> Result<Vec<ProviderUpsert>, ProviderError> {
    if input.lines().any(|line| line.starts_with("PROVIDER: ")) {
        let mut providers = Vec::new();
        for raw in input.lines() {
            if let Some(json) = raw.trim().strip_prefix("PROVIDER: ") {
                providers.push(serde_json::from_str(json)?);
            }
        }
        return Ok(providers);
    }
    parse_indented_provider_config(input)
}

fn parse_indented_provider_config(input: &str) -> Result<Vec<ProviderUpsert>, ProviderError> {
    let mut providers = Vec::new();
    let mut current: Option<ProviderUpsert> = None;
    for raw in input.lines() {
        let line = raw.trim_end();
        if line.trim().is_empty() || line.trim_start().starts_with('#') {
            continue;
        }
        if !line.starts_with(' ') && !line.starts_with('\t') {
            if let Some(provider) = current.take() {
                providers.push(provider);
            }
            current = Some(ProviderUpsert {
                name: line.trim().to_string(),
                kind: Some("openai-compatible".into()),
                base_url: String::new(),
                default_model: None,
                models: Some(Vec::new()),
                supported_clients: Some(Vec::new()),
                api_key: None,
                api_key_env: None,
                encrypted_api_key: None,
                enabled: Some(true),
                subscriber_id: None,
                acknowledge_intermediary_risk: None,
                acknowledge_unsupported_clients: None,
                if_absent: false,
            });
            continue;
        }
        let Some(provider) = current.as_mut() else {
            return Err(ProviderError::Invalid(
                "indented provider field without provider name".into(),
            ));
        };
        let (key, value) = split_indented_field(line.trim())?;
        match key {
            "kind" => provider.kind = Some(value),
            "base_url" | "base-url" | "api_base" | "api-base" => provider.base_url = value,
            "model" | "default_model" | "default-model" => provider.default_model = Some(value),
            "models" => {
                provider.models = Some(
                    value
                        .split(',')
                        .map(str::trim)
                        .filter(|s| !s.is_empty())
                        .map(ToString::to_string)
                        .collect(),
                );
            }
            "supported_clients" | "supported-clients" => {
                provider.supported_clients = Some(
                    value
                        .split(',')
                        .map(str::trim)
                        .filter(|entry| !entry.is_empty())
                        .map(ToString::to_string)
                        .collect(),
                );
            }
            "api_key" | "api-key" => provider.api_key = Some(value),
            "api_key_env" | "api-key-env" => provider.api_key_env = Some(value),
            "enabled" => provider.enabled = Some(matches!(value.as_str(), "true" | "1" | "yes")),
            "subscriber_id" | "subscriber-id" => provider.subscriber_id = Some(value),
            "acknowledge_intermediary_risk" | "acknowledge-intermediary-risk" => {
                provider.acknowledge_intermediary_risk =
                    Some(matches!(value.as_str(), "true" | "1" | "yes"));
            }
            "acknowledge_unsupported_clients" | "acknowledge-unsupported-clients" => {
                provider.acknowledge_unsupported_clients = Some(
                    value
                        .split(',')
                        .map(str::trim)
                        .filter(|entry| !entry.is_empty())
                        .map(ToString::to_string)
                        .collect(),
                );
            }
            other => {
                return Err(ProviderError::Invalid(format!(
                    "unknown provider field: {other}"
                )));
            }
        }
    }
    if let Some(provider) = current {
        providers.push(provider);
    }
    if providers.is_empty() {
        return Err(ProviderError::Invalid(
            "provider import did not contain any providers".into(),
        ));
    }
    Ok(providers)
}

fn split_indented_field(line: &str) -> Result<(&str, String), ProviderError> {
    let Some((key, raw_value)) = line.split_once(char::is_whitespace) else {
        return Err(ProviderError::Invalid(format!(
            "provider field must be key value: {line}"
        )));
    };
    let value = raw_value.trim();
    Ok((key, unquote(value)))
}

fn unquote(value: &str) -> String {
    value
        .strip_prefix('"')
        .and_then(|v| v.strip_suffix('"'))
        .unwrap_or(value)
        .to_string()
}

//! `router providers` — manage stored OpenAI-compatible providers.
//!
//! Split from `main.rs` to keep that file within the repository's 1000-line
//! limit.

use std::process::ExitCode;

use crate::cli::ProviderOp;
use crate::config::Config;
use crate::provider_acceptance::{ProviderProvisionFailureKind, ProviderProvisionResponse};
use crate::providers::{ProviderStore, ProviderUpsert};

#[derive(Debug, PartialEq, serde::Serialize)]
struct ProviderImportReport {
    complete: bool,
    results: Vec<serde_json::Value>,
}

fn import_failure(name: &crate::translation_core::Str, outcome: ProviderProvisionFailureKind) -> crate::translation_core::Json {
    crate::translation_core::json!({"name": name, "outcome": outcome})
}

fn remote_failure(body: &crate::translation_core::Json) -> ProviderProvisionFailureKind {
    let outcome = body.pointer("/error/outcome").cloned();
    outcome
        .and_then(|value| serde_json::from_value(value).ok())
        .unwrap_or(ProviderProvisionFailureKind::Unverified)
}

fn print_import_report(report: &ProviderImportReport) {
    println!(
        "{}",
        serde_json::to_string_pretty(report)
            .unwrap_or_else(|_| { r#"{"complete":false,"results":[]}"#.to_string() })
    );
}

async fn local_import_report(
    client: &reqwest::Client,
    store: &ProviderStore,
    inputs: Vec<ProviderUpsert>,
) -> ProviderImportReport {
    let mut report = ProviderImportReport {
        complete: true,
        results: Vec::with_capacity(inputs.len()),
    };
    for input in inputs {
        let name = input.name.clone();
        match crate::provider_acceptance::provision(client, store, input).await {
            Ok(result) => {
                report
                    .results
                    .push(serde_json::to_value(result.response()).unwrap_or_else(|_| {
                        import_failure(&name, ProviderProvisionFailureKind::PersistenceUncertain)
                    }));
            }
            Err(error) => {
                report.complete = false;
                report.results.push(import_failure(&name, error.kind()));
                break;
            }
        }
    }
    report
}

async fn remote_import_report(
    server: &crate::managed_server::ResolvedServer,
    imported: &[ProviderUpsert],
) -> crate::translation_core::Outcome<ProviderImportReport, String> {
    let mut report = ProviderImportReport {
        complete: true,
        results: Vec::with_capacity(imported.len()),
    };
    for record in imported {
        let name = record.name.clone();
        let response = crate::auth_remote::post_response(
            server,
            crate::route_contract::route_template(crate::route_contract::RouteId::Providers),
            upsert_body(record)?,
        )
        .await;
        match response {
            Ok((status, body)) if status.is_success() => {
                if let Ok(safe) = serde_json::from_value::<ProviderProvisionResponse>(body) {
                    report
                        .results
                        .push(serde_json::to_value(safe).unwrap_or_else(|_| {
                            import_failure(&name, ProviderProvisionFailureKind::Unverified)
                        }));
                } else {
                    report.complete = false;
                    report.results.push(import_failure(
                        &name,
                        ProviderProvisionFailureKind::Unverified,
                    ));
                    break;
                }
            }
            Ok((_, body)) => {
                report.complete = false;
                report
                    .results
                    .push(import_failure(&name, remote_failure(&body)));
                break;
            }
            Err(_) => {
                report.complete = false;
                report.results.push(import_failure(
                    &name,
                    ProviderProvisionFailureKind::Unverified,
                ));
                break;
            }
        }
    }
    Ok(report)
}

#[must_use]
pub async fn run(config: &Config, op: &ProviderOp) -> ExitCode {
    let store = match ProviderStore::open(&config.data_dir, &config.token_secret) {
        Ok(store) => store,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::from(1);
        }
    };
    run_with(&store, op).await
}

/// The same commands against the *selected* router (issue #294).
///
/// The deployment already exposes full CRUD for providers, admin-gated, so
/// these are honoured rather than refused. `import` is the exception in shape
/// only: it reads a file on *this* machine and then declares each provider
/// remotely, which is what an operator means by importing a local manifest
/// into a deployment.
pub async fn run_remote(
    server: &crate::managed_server::ResolvedServer,
    op: &ProviderOp,
) -> ExitCode {
    warn_zai_policy(op);
    match remote_result(server, op).await {
        Ok(code) => code,
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

fn warn_zai_policy(op: &ProviderOp) {
    if let ProviderOp::Add {
        kind,
        enabled,
        acknowledge_intermediary_risk,
        acknowledge_unsupported_client,
        ..
    } = op
        && crate::providers::ProviderKind::from_str_opt(kind)
            == Some(crate::providers::ProviderKind::ZaiCodingPlan)
        && *enabled
    {
        eprintln!(
            "WARNING: z.ai Coding Plan is a personal subscription. Intermediary proxying is not explicitly approved; policy violations may restrict or ban the subscriber account."
        );
        if *acknowledge_intermediary_risk {
            eprintln!("risk accepted: intermediary z.ai Coding Plan proxying");
        }
        for client in acknowledge_unsupported_client {
            eprintln!(
                "WARNING: unsupported z.ai tool risk accepted only for client '{client}'; this may cause account restrictions or a ban"
            );
        }
    }
}

/// The call one provider operation makes against the selected router.
///
/// Separated from sending it so the request can be asserted without a server:
/// a wrong path or a body missing a declared model is the kind of mistake an
/// operator only sees as a provider that never wins a route.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Call {
    /// `GET`, `POST` or `DELETE`, as the endpoint expects.
    pub method: &'static str,
    /// The admin route this operation uses.
    pub path: String,
    /// The JSON body, for a `POST`.
    pub body: Option<serde_json::Value>,
}

/// The call `op` makes, for everything but `import`.
///
/// `import` reads a manifest on this machine and then makes one `add` call per
/// provider it declares, so it has no single call of its own.
///
/// # Errors
///
/// Returns an operator-readable message when the provider cannot be encoded.
pub fn call_for(op: &ProviderOp) -> crate::translation_core::Outcome<crate::translation_core::Maybe<Call>, String> {
    Ok(match op {
        ProviderOp::List { .. } => Some(Call {
            method: "GET",
            path: crate::route_contract::route_template(crate::route_contract::RouteId::Providers)
                .to_string(),
            body: None,
        }),
        ProviderOp::Show { name, .. } => Some(Call {
            method: "GET",
            path: format!("/api/management/providers/{name}"),
            body: None,
        }),
        ProviderOp::Remove { name, .. } => Some(Call {
            method: "DELETE",
            path: format!("/api/management/providers/{name}"),
            body: None,
        }),
        ProviderOp::Add {
            name,
            kind,
            base_url,
            model,
            models,
            supported_clients,
            api_key,
            api_key_stdin,
            api_key_env,
            subscriber_id,
            acknowledge_intermediary_risk,
            acknowledge_unsupported_client,
            enabled,
            if_absent,
            ..
        } => {
            reject_lefine_argv_key(kind, api_key.as_ref())?;
            Some(Call {
                method: "POST",
                path: crate::route_contract::route_template(
                    crate::route_contract::RouteId::Providers,
                )
                .to_string(),
                body: Some(upsert_body(&ProviderUpsert {
                    name: name.clone(),
                    kind: Some(kind.clone()),
                    base_url: base_url.clone(),
                    default_model: model.clone(),
                    models: Some(models.clone()),
                    supported_clients: Some(supported_clients.clone()),
                    api_key: supplied_api_key(api_key.as_ref(), *api_key_stdin)
                        .map_err(|error| error.to_string())?,
                    api_key_env: api_key_env.clone(),
                    encrypted_api_key: None,
                    enabled: Some(*enabled),
                    subscriber_id: subscriber_id.clone(),
                    acknowledge_intermediary_risk: Some(*acknowledge_intermediary_risk),
                    acknowledge_unsupported_clients: Some(acknowledge_unsupported_client.clone()),
                    if_absent: *if_absent,
                })?),
            })
        }
        ProviderOp::Import { .. } => None,
    })
}

/// The vendor API key this invocation supplies, from argv or standard input.
///
/// `--api-key-stdin` exists because this was the one secret in the tool that
/// could travel only through argv, where shell history and `ps` expose it —
/// while every other secret already had a stdin form (issue #314).
fn supplied_api_key(
    api_key: Option<&String>,
    api_key_stdin: bool,
) -> Result<Option<String>, Box<dyn std::error::Error + Send + Sync>> {
    if api_key_stdin {
        return crate::server_command::read_token().map(Some);
    }
    Ok(api_key.cloned())
}

fn reject_lefine_argv_key(kind: &crate::translation_core::Str, api_key: crate::translation_core::Maybe<&String>) -> crate::translation_core::Outcome<(), String> {
    if crate::providers::ProviderKind::from_str_opt(kind)
        == Some(crate::providers::ProviderKind::Lefine)
        && api_key.is_some()
    {
        return Err("Lefine API keys must use --api-key-stdin or --api-key-env".into());
    }
    Ok(())
}

/// One provider as the endpoint's own request type encodes it.
///
/// Built from [`ProviderUpsert`] rather than a hand-written JSON object, so the
/// remote and local paths cannot describe a provider differently.
///
/// # Errors
///
/// Returns an operator-readable message when the record cannot be encoded.
pub fn upsert_body(upsert: &ProviderUpsert) -> crate::translation_core::Outcome<crate::translation_core::Json, String> {
    serde_json::to_value(upsert).map_err(|error| error.to_string())
}

/// The provider records inside a `/api/management/providers` answer.
#[must_use]
pub fn records_in(answer: &crate::translation_core::Json) -> Vec<crate::translation_core::Json> {
    answer
        .get("data")
        .and_then(crate::translation_core::Json::as_array)
        .cloned()
        .unwrap_or_default()
}

async fn remote_result(
    server: &crate::managed_server::ResolvedServer,
    op: &ProviderOp,
) -> crate::translation_core::Outcome<ExitCode, String> {
    if let ProviderOp::Import { path, .. } = op {
        // The manifest is this machine's file; the providers it declares are
        // the deployment's. Reading here and declaring there is what "import
        // into that router" means.
        let text = std::fs::read_to_string(path)
            .map_err(|error| format!("could not read {}: {error}", path.display()))?;
        let imported = crate::providers::parse_provider_import(&text)
            .map_err(|error| format!("could not parse {}: {error}", path.display()))?;
        let report = remote_import_report(server, &imported).await?;
        print_import_report(&report);
        return Ok(if report.complete {
            ExitCode::SUCCESS
        } else {
            ExitCode::from(1)
        });
    }

    let Some(call) = call_for(op)? else {
        return Ok(ExitCode::from(1));
    };
    let answer = match (call.method, call.body) {
        ("POST", Some(body)) => crate::auth_remote::post(server, &call.path, body).await,
        ("DELETE", _) => crate::auth_remote::delete(server, &call.path).await,
        _ => crate::auth_remote::get(server, &call.path).await,
    };

    match op {
        ProviderOp::List { json, .. } => {
            let records = records_in(&answer?);
            if *json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&records).unwrap_or_else(|_| "[]".to_string())
                );
            } else {
                print_remote_table(&records);
            }
            Ok(ExitCode::SUCCESS)
        }
        ProviderOp::Show { name, .. } => match answer {
            Ok(record) => {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&record).unwrap_or_default()
                );
                Ok(ExitCode::SUCCESS)
            }
            // The local path exits 2 for an unknown provider; matching it keeps
            // a script's meaning the same against either target.
            Err(error) if error.contains("404") => {
                eprintln!("not found: {name}");
                Ok(ExitCode::from(2))
            }
            Err(error) => Err(error),
        },
        ProviderOp::Remove { name, .. } => {
            answer?;
            println!("removed {name}");
            Ok(ExitCode::SUCCESS)
        }
        ProviderOp::Add { .. } => {
            let answer = answer?;
            println!(
                "{}",
                serde_json::to_string_pretty(&answer)
                    .map_err(|error| format!("could not encode provider outcome: {error}"))?
            );
            Ok(ExitCode::SUCCESS)
        }
        // Returned above.
        ProviderOp::Import { .. } => Ok(ExitCode::from(1)),
    }
}

/// The provider table, in the one format both paths print.
///
/// Same columns, widths and order as the local table: an operator reading one
/// has no way to tell which machine answered, so a column that differs between
/// them would be worse than no column at all.
///
/// `kind` is taken through [`ProviderKind::as_str`] so table output stays
/// aligned with the accepted CLI spelling.
fn print_remote_table(records: &[crate::translation_core::Json]) {
    println!(
        "{:<20}  {:<18}  {:<32}  {:<10}  default_model",
        "name", "kind", "base_url", "enabled"
    );
    for record in records {
        let text = |key: &str| {
            record
                .get(key)
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
        };
        let kind = crate::providers::ProviderKind::from_str_opt(text("kind"))
            .unwrap_or_default()
            .as_str();
        println!(
            "{:<20}  {:<18}  {:<32}  {:<10}  {}",
            text("name"),
            kind,
            text("base_url"),
            record
                .get("enabled")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
            text("default_model"),
        );
    }
}

/// The same command against an already-open store.
///
/// Split from [`run`] so the operations can be exercised without constructing
/// a whole configuration around them.
#[must_use]
pub async fn run_with(store: &ProviderStore, op: &ProviderOp) -> ExitCode {
    warn_zai_policy(op);
    let client = match crate::upstream_client::build_upstream_client() {
        Ok(client) => client,
        Err(error) => {
            eprintln!("error: could not build provider validation client: {error}");
            return ExitCode::from(1);
        }
    };
    match op {
        ProviderOp::List { json, .. } => match store.list_redacted() {
            Ok(records) if *json => {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&records).unwrap_or_else(|_| "[]".to_string())
                );
                ExitCode::SUCCESS
            }
            Ok(records) => {
                println!(
                    "{:<20}  {:<18}  {:<32}  {:<10}  default_model",
                    "name", "kind", "base_url", "enabled"
                );
                for record in records {
                    println!(
                        "{:<20}  {:<18}  {:<32}  {:<10}  {}",
                        record.name,
                        record.kind.as_str(),
                        record.base_url,
                        record.enabled,
                        record.default_model.unwrap_or_default()
                    );
                }
                ExitCode::SUCCESS
            }
            Err(e) => {
                eprintln!("error: {e}");
                ExitCode::from(1)
            }
        },
        ProviderOp::Add {
            name,
            kind,
            base_url,
            model,
            models,
            supported_clients,
            api_key,
            api_key_stdin,
            api_key_env,
            subscriber_id,
            acknowledge_intermediary_risk,
            acknowledge_unsupported_client,
            enabled,
            if_absent,
            ..
        } => {
            if let Err(error) = reject_lefine_argv_key(kind, api_key.as_ref()) {
                eprintln!("error: {error}");
                return ExitCode::from(2);
            }
            let api_key = match supplied_api_key(api_key.as_ref(), *api_key_stdin) {
                Ok(api_key) => api_key,
                Err(error) => {
                    eprintln!("error: {error}");
                    return ExitCode::from(2);
                }
            };
            let input = ProviderUpsert {
                name: name.clone(),
                kind: Some(kind.clone()),
                base_url: base_url.clone(),
                default_model: model.clone(),
                models: Some(models.clone()),
                supported_clients: Some(supported_clients.clone()),
                api_key,
                api_key_env: api_key_env.clone(),
                encrypted_api_key: None,
                enabled: Some(*enabled),
                subscriber_id: subscriber_id.clone(),
                acknowledge_intermediary_risk: Some(*acknowledge_intermediary_risk),
                acknowledge_unsupported_clients: Some(acknowledge_unsupported_client.clone()),
                if_absent: *if_absent,
            };
            match crate::provider_acceptance::provision(&client, store, input).await {
                Ok(result) => {
                    println!(
                        "{}",
                        serde_json::to_string_pretty(&result.response()).unwrap_or_default()
                    );
                    ExitCode::SUCCESS
                }
                Err(e) => {
                    eprintln!("error: {e}");
                    ExitCode::from(1)
                }
            }
        }
        ProviderOp::Show { name, .. } => match store.get(name) {
            Ok(Some(record)) => {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&record.redacted()).unwrap_or_default()
                );
                ExitCode::SUCCESS
            }
            Ok(None) => {
                eprintln!("not found: {name}");
                ExitCode::from(2)
            }
            Err(e) => {
                eprintln!("error: {e}");
                ExitCode::from(1)
            }
        },
        ProviderOp::Remove { name, .. } => match store.delete(name) {
            Ok(true) => {
                println!("removed {name}");
                ExitCode::SUCCESS
            }
            Ok(false) => {
                eprintln!("not found: {name}");
                ExitCode::from(2)
            }
            Err(e) => {
                eprintln!("error: {e}");
                ExitCode::from(1)
            }
        },
        ProviderOp::Import { path, .. } => match std::fs::read_to_string(path)
            .map_err(crate::providers::ProviderError::from)
            .and_then(|text| crate::providers::parse_provider_import(&text))
        {
            Ok(inputs) => {
                let report = local_import_report(&client, store, inputs).await;
                print_import_report(&report);
                if report.complete {
                    ExitCode::SUCCESS
                } else {
                    ExitCode::from(1)
                }
            }
            Err(e) => {
                eprintln!("error: {e}");
                ExitCode::from(1)
            }
        },
    }
}

