//! Reviewed native Anthropic request-header forwarding.
//!
//! Native proxying preserves the official client's application-level
//! identity. Only authentication, routing/transport framing, hop-by-hop
//! fields, and Router-internal metadata may change.

use std::collections::HashSet;

use axum::http::{HeaderMap, HeaderName, HeaderValue};
use log_lazy::LogLazy;

use super::REQUIRED_FORWARD_HEADERS;

/// Representative end-to-end identity/protocol headers preserved upstream.
#[must_use]
pub fn forwarded_client_headers() -> Vec<&'static str> {
    vec![
        "user-agent",
        "anthropic-version",
        "anthropic-beta",
        "x-stainless-*",
        "x-claude-code-*",
        "accept",
        "content-type",
    ]
}

/// Default used only by explicit cross-protocol adapters.
pub const DEFAULT_ANTHROPIC_VERSION: &str = "2023-06-01";

/// Anthropic OAuth flag used only by explicit cross-protocol adapters.
pub const OAUTH_BETA_FLAG: &str = "oauth-2025-04-20";

/// Deliberate proxy request-body ceiling.
pub const MAX_PROXY_REQUEST_BYTES: usize = crate::config::DEFAULT_MAX_PROXY_REQUEST_BYTES;

/// Reviewed ingress/network-origin metadata that never belongs on a native
/// provider request. Header names are case-insensitive after `HeaderMap`
/// parsing, and every repeated value is removed by the shared classifier.
pub const INGRESS_NETWORK_HEADERS: &[&str] = &[
    "forwarded",
    "x-forwarded-for",
    "x-forwarded-host",
    "x-forwarded-proto",
    "x-forwarded-port",
    "x-forwarded-server",
    "x-original-forwarded-for",
    "x-real-ip",
    "x-client-ip",
    "x-cluster-client-ip",
    "cf-connecting-ip",
    "true-client-ip",
    "fastly-client-ip",
    "fly-client-ip",
    "x-envoy-external-address",
    "x-forwarded-client-cert",
    "x-azure-clientip",
    "x-appengine-user-ip",
    "cloudfront-viewer-address",
];

/// Merge the OAuth bridge beta flag for explicit protocol conversion paths.
#[must_use]
pub fn merge_oauth_beta(existing: Option<&str>) -> String {
    match existing {
        Some(v) if v.split(',').map(str::trim).any(|f| f == OAUTH_BETA_FLAG) => v.to_string(),
        Some(v) if !v.trim().is_empty() => format!("{v},{OAUTH_BETA_FLAG}"),
        _ => OAUTH_BETA_FLAG.to_string(),
    }
}

fn replaced_or_transport_header(name: &str) -> bool {
    INGRESS_NETWORK_HEADERS.contains(&name)
        || matches!(
            name,
            "authorization"
                | "x-api-key"
                | "x-goog-api-key"
                | "anthropic-auth-token"
                | "proxy-authorization"
                | "proxy-authenticate"
                | "host"
                | "connection"
                | "proxy-connection"
                | "keep-alive"
                | "transfer-encoding"
                | "upgrade"
                | "te"
                | "trailer"
                | "content-length"
                | "accept-encoding"
                | "cookie"
                | "chatgpt-account-id"
                | "sec-websocket-key"
                | "sec-websocket-version"
                | "sec-websocket-extensions"
                | "sec-websocket-accept"
        )
        || name.starts_with("x-link-assistant-")
        || name.starts_with("x-router-")
}

pub fn native_request_headers(incoming: &HeaderMap, bearer_token: &str) -> HeaderMap {
    let connection_nominated: HashSet<HeaderName> = incoming
        .get_all("connection")
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(','))
        .filter_map(|name| HeaderName::from_bytes(name.trim().as_bytes()).ok())
        .collect();
    let mut headers = HeaderMap::new();
    for (name, value) in incoming {
        if !replaced_or_transport_header(name.as_str()) && !connection_nominated.contains(name) {
            headers.append(name.clone(), value.clone());
        }
    }
    if let Ok(auth_val) = HeaderValue::from_str(&format!("Bearer {bearer_token}")) {
        headers.insert("authorization", auth_val);
    }
    headers
}

/// Preserve the caller's end-to-end request identifier across a protocol
/// translation. Translated requests intentionally rebuild protocol headers,
/// but correlation remains the caller's application-level metadata; Router's
/// own correlation id stays exclusively in request-log state.
#[must_use]
pub fn translated_request_id(incoming: &HeaderMap) -> Option<HeaderValue> {
    incoming.get("x-request-id").cloned()
}

/// Preserve native end-to-end headers and replace only the Router credential.
pub fn build_upstream_headers(
    incoming: &HeaderMap,
    oauth_token: &str,
    logger: &LogLazy,
) -> HeaderMap {
    let headers = native_request_headers(incoming, oauth_token);
    for &header_name in REQUIRED_FORWARD_HEADERS {
        if let Some(val) = headers.get(header_name) {
            logger.trace(|| {
                format!(
                    "Forwarding {header_name}: {}",
                    val.to_str().unwrap_or("<non-utf8>")
                )
            });
        }
    }
    headers
}

//! Mapping an inbound request path to its upstream path.
//!
//! Split from `proxy.rs` to keep that file within the repository's 1000-line
//! limit.

/// Resolve the upstream path from the incoming request path.
///
/// Maps all supported API format paths to the correct upstream path:
/// - `/v1/messages` -> `/v1/messages` (Anthropic Messages)
/// - `/v1/messages/count_tokens` -> `/v1/messages/count_tokens` (Anthropic Messages)
/// - `/invoke` -> `/invoke` (Bedrock)
/// - `/invoke-with-response-stream` -> `/invoke-with-response-stream` (Bedrock)
/// - Paths ending in `:rawPredict` or `:streamRawPredict` -> pass through (Vertex)
/// - `/api/latest/anthropic/*` -> `/*` (legacy)
#[must_use]
pub fn resolve_upstream_path(path: &str) -> String {
    if let Some(rest) = path.strip_prefix("/api/services/anthropic") {
        return rest.to_string();
    }
    if let Some(rest) = path.strip_prefix("/api/services/bedrock") {
        return rest.to_string();
    }
    if let Some(rest) = path.strip_prefix("/api/services/vertex") {
        return rest.to_string();
    }
    if let Some(rest) = path.strip_prefix("/api/anthropic") {
        return rest.to_string();
    }
    // Legacy prefix: strip and forward
    if let Some(rest) = path.strip_prefix("/api/latest/anthropic") {
        return rest.to_string();
    }

    // All other paths (Anthropic /v1/*, Bedrock /invoke*, Vertex *:rawPredict)
    // are forwarded as-is to the upstream
    path.to_string()
}

//! Account selection and the upstream send for the Anthropic pass-through,
//! with opt-in pre-first-byte failover across the account pool (issue #676).
//!
//! Without failover this sends exactly once, as before. With
//! `POOL_FAILOVER=pre-first-byte` a `429`, `529`, retryable `5xx`, `401` or
//! transport error is answered by sending the same request on the next
//! eligible account. Every attempt happens before a byte of the response is
//! relayed, so the client sees one response — the first success, or the last
//! failure. The loop stops at `POOL_FAILOVER_MAX_ATTEMPTS`, after
//! `POOL_FAILOVER_BUDGET_SECS`, when no other account can serve, for a
//! token-pinned account, and — because axum drops a handler whose client
//! disconnected — as soon as the client goes away.

use std::time::Instant;

use axum::http::{HeaderMap, Method, StatusCode};
use axum::response::Response;
use bytes::Bytes;
use futures_util::stream::BoxStream;
use serde_json::{Value, json};

use super::{AppState, build_upstream_headers, error_response, retry_after_duration};
use crate::account_http::CookieMode;
use crate::accounts::{RoutingContext, UpstreamObservation};
use crate::pool_failover::{RetryReason, classify_status};
use crate::request_routing::ResolvedUpstreamCredential;
use crate::subscription::SubscriptionProvider;

/// Everything one dispatch needs from the handler.
pub(super) struct Dispatch<'a> {
    pub state: &'a AppState,
    pub method: &'a Method,
    pub upstream_url: &'a str,
    pub incoming_headers: &'a HeaderMap,
    pub body: Bytes,
    pub routing_body: &'a Value,
    pub from_thinking_suffix: bool,
    pub context: RoutingContext,
    pub subscription: Option<&'a crate::model_routing::ValidatedSubscription>,
    pub correlation_id: &'a str,
}

/// The upstream response the client will receive.
pub(super) struct UpstreamReply {
    pub status: StatusCode,
    pub headers: HeaderMap,
    /// The pooled account that produced it, if any.
    pub account: Option<String>,
    pub body: BoxStream<'static, reqwest::Result<Bytes>>,
}

impl UpstreamReply {
    fn prepared(response: crate::pool_response::PoolResponse, account: Option<String>) -> Self {
        Self {
            status: response.status(),
            headers: response.headers().clone(),
            account,
            body: response.bytes_stream(),
        }
    }
}

/// The last thing that went wrong, relayed when no attempt succeeds.
enum Failure {
    Reply(UpstreamReply),
    Transport(String),
}

/// Select an account, send, and — with failover on — retry on another account
/// until a response can be relayed.
pub(super) async fn dispatch(request: Dispatch<'_>) -> Result<UpstreamReply, Response> {
    let state = request.state;
    let policy = crate::pool_failover::current();
    let router = state.account_router.as_ref();
    // A token-pinned account never falls back.
    let failover = router.is_some_and(crate::accounts::AccountRouter::failover_enabled)
        && request.context.pinned_account.is_none();
    let mut budget = crate::pool_retry::RetryBudget::new(router, failover, policy.max_attempts);
    let max_attempts = budget.max_attempts;
    let deadline = policy.deadline(Instant::now());
    // The account whose signatures the conversation history carries.
    let mut origin = router.and_then(|router| router.session_account(&request.context));
    let mut context = request.context.clone();
    let mut last: Option<Failure> = None;
    let mut stripped: Option<Bytes> = None;
    let mut attempt = 0;
    while attempt < max_attempts {
        if budget.round_full(&context) && !budget.next_round(router, &mut context, deadline).await {
            break;
        }
        if attempt > 0 && Instant::now() >= deadline {
            log_stop(state, request.correlation_id, attempt, "budget exhausted");
            break;
        }
        let resolved =
            match resolve_upstream_credentials(state, &context, request.subscription).await {
                Ok(resolved) => resolved,
                Err(error) => {
                    if budget.next_round(router, &mut context, deadline).await {
                        continue;
                    }
                    if attempt > 0 {
                        log_stop(state, request.correlation_id, attempt, &error.to_string());
                        break;
                    }
                    if let Some(error) = request.subscription.and_then(|subscription| {
                        subscription.unavailable_error(state, context.pinned_account.as_deref())
                    }) {
                        return Err(crate::model_routing::model_route_error_response(&error));
                    }
                    tracing::error!("Failed to resolve upstream credentials: {error}");
                    return Err(error_response(
                        StatusCode::BAD_GATEWAY,
                        "api_error",
                        "Upstream authentication unavailable",
                    ));
                }
            };
        let mut account = resolved.account.clone();
        attempt += 1;
        if origin.is_none() {
            origin.clone_from(&account);
        }
        state.request_log.set_account(
            request.correlation_id,
            account.as_deref().unwrap_or("primary"),
        );
        if let (Some(account), Some(token)) = (account.as_deref(), resolved.evidence_token.as_ref())
        {
            crate::account_policy_scope::credential(account, token);
        }
        // An already-bound subscription cannot move; do not send twice.
        if attempt > 1
            && account
                .as_ref()
                .is_none_or(|account| context.exclude.contains(account))
        {
            log_stop(state, request.correlation_id, attempt, "no other account");
            break;
        }
        let history_account = origin.clone().or_else(|| context.exclude.first().cloned());
        let body = if failover
            && account.is_some()
            && history_account.is_some_and(|origin| Some(origin) != account)
        {
            stripped
                .get_or_insert_with(|| strip_signed_history(request.routing_body, &request.body))
                .clone()
        } else {
            request.body.clone()
        };
        let body = if let Some(account) = account.as_deref() {
            apply_thinking_for_attempt(&request, &body, account)?
        } else {
            body
        };
        let mut headers = build_upstream_headers(
            request.incoming_headers,
            &resolved.access_token,
            &state.logger,
        );
        if body != request.body {
            headers.remove(axum::http::header::CONTENT_LENGTH);
        }
        state.logger.verbose(|| {
            format!(
                "Forwarding {} {} ({} bytes, attempt {attempt})",
                request.method,
                request.upstream_url,
                body.len()
            )
        });
        // Each pooled account sends on its own connections, through its own
        // egress proxy when it has one (issue #678).
        let upstream_call = async {
            let client = crate::account_http::pooled_client(
                router,
                account.as_deref(),
                &state.client,
                CookieMode::None,
            )?;
            let builder = client
                .request(request.method.clone(), request.upstream_url)
                .headers(headers)
                .body(body);
            let response = state
                .request_log
                .send_upstream(request.correlation_id, &client, builder)
                .await
                .map_err(|error| error.to_string())?;
            crate::request_routing::record_claude_evidence(
                state,
                account.as_deref(),
                resolved.evidence_token.as_ref(),
                response.status().as_u16(),
            )
            .await;
            let probe = failover
                && response.status().is_success()
                && response
                    .headers()
                    .get("content-type")
                    .and_then(|value| value.to_str().ok())
                    .is_some_and(|value| value.contains("text/event-stream"));
            crate::pool_response::PoolResponse::prepare(response, probe).await
        };
        let outcome = if failover && attempt > 1 {
            let bounded =
                tokio::time::timeout_at(tokio::time::Instant::from_std(deadline), upstream_call)
                    .await;
            let Ok(outcome) = bounded else {
                log_stop(state, request.correlation_id, attempt, "budget exhausted");
                break;
            };
            outcome
        } else {
            upstream_call.await
        };
        let (mut response, peeked) = match outcome {
            Ok(response) => response,
            Err(error) => {
                tracing::error!("Upstream request failed: {error}");
                if failover && attempt < max_attempts {
                    note_failover(
                        state,
                        request.correlation_id,
                        attempt,
                        account.as_deref(),
                        RetryReason::Transport,
                    );
                    // A vendor reply (with its Retry-After) beats a later
                    // connection failure as the answer to relay.
                    if !matches!(last, Some(Failure::Reply(_))) {
                        last = Some(Failure::Transport(error));
                    }
                    context.exclude.extend(account);
                    continue;
                }
                if let Some(Failure::Reply(reply)) = last {
                    return Ok(reply);
                }
                return Err(transport_error(&error));
            }
        };
        if crate::account_policy_scope::active() {
            account = crate::account_policy_scope::account();
        }
        let status = response.status().as_u16();
        if status >= 400 {
            tracing::warn!(
                request_id = request.correlation_id,
                upstream_status = status,
                error_class = crate::logging::http_failure(status),
                "upstream request rejected"
            );
        }
        let retry_after = retry_after_duration(response.headers());
        state
            .logger
            .verbose(|| format!("Upstream responded: {status} (attempt {attempt})"));
        let reason = classify_status(status);
        if let (Some(router), Some(name)) = (router, account.as_ref()) {
            response = response.observe(crate::pool_stream_limits::StreamLimits::new(
                router.clone(),
                name.clone(),
                context.model.clone(),
            ));
        }
        let reply = UpstreamReply::prepared(response, account.clone());
        // Every response, `count_tokens` included, updates the vendor
        // rate-limit state (issue #677).
        if !crate::account_policy_scope::active()
            && let (Some(router), Some(name)) = (router, account.as_deref())
        {
            router.observe_upstream(&UpstreamObservation {
                account: name,
                model: context.model.as_deref(),
                status,
                headers: &reply.headers,
                body: &peeked,
                retry_after,
            });
        }
        match reason {
            Some(reason) if failover && attempt < max_attempts => {
                note_failover(
                    state,
                    request.correlation_id,
                    attempt,
                    account.as_deref(),
                    reason,
                );
                // Dropping the earlier failure closes its connection.
                last = Some(Failure::Reply(reply));
                context.exclude.extend(account);
            }
            _ => return Ok(reply),
        }
    }
    match last {
        Some(Failure::Reply(reply)) => Ok(reply),
        Some(Failure::Transport(error)) => Err(transport_error(&error)),
        None => Err(error_response(
            StatusCode::BAD_GATEWAY,
            "api_error",
            "Upstream authentication unavailable",
        )),
    }
}

fn apply_thinking_for_attempt(
    request: &Dispatch<'_>,
    bytes: &Bytes,
    account: &str,
) -> Result<Bytes, Response> {
    if !request
        .routing_body
        .get("messages")
        .is_some_and(Value::is_array)
    {
        return Ok(bytes.clone());
    }
    let Ok(mut body) = serde_json::from_slice::<Value>(bytes) else {
        return Ok(bytes.clone());
    };
    let model = body
        .get("model")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let changed = crate::thinking::apply_for_account(
        request.state,
        &mut body,
        &model,
        SubscriptionProvider::Claude,
        account,
        &request.state.upstream_base_url,
        crate::thinking::ThinkingProtocol::Anthropic,
        crate::thinking::ThinkingProtocol::Anthropic,
        request.from_thinking_suffix,
    )
    .map_err(|reason| error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &reason))?;
    if changed {
        serde_json::to_vec(&body).map(Bytes::from).map_err(|error| {
            error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &error.to_string(),
            )
        })
    } else {
        Ok(bytes.clone())
    }
}

fn transport_error(error: &str) -> Response {
    error_response(
        StatusCode::BAD_GATEWAY,
        "api_error",
        &format!("Upstream request failed: {error}"),
    )
}

/// The request body without Claude thinking blocks, whose signatures only the
/// account that produced them accepts. Unchanged bytes when there were none.
fn strip_signed_history(routing_body: &Value, original: &Bytes) -> Bytes {
    let mut body = routing_body.clone();
    if !crate::pool_failover::strip_anthropic_thinking(&mut body) {
        return original.clone();
    }
    serde_json::to_vec(&body).map_or_else(|_| original.clone(), Bytes::from)
}

/// Record one failed attempt that is being retried, under the request's
/// correlation id.
pub fn note_failover(
    state: &AppState,
    correlation_id: &str,
    attempt: u32,
    account: Option<&str>,
    reason: RetryReason,
) {
    state.metrics.record_pool_failover();
    tracing::info!(
        correlation_id,
        attempt,
        account = account.unwrap_or("primary"),
        reason = reason.as_str(),
        "pool failover: retrying on another account before the first byte"
    );
    state.request_log.record(
        correlation_id,
        "pool_failover",
        json!({"attempt": attempt, "account": account, "reason": reason.as_str()}),
    );
}

pub fn log_stop(state: &AppState, correlation_id: &str, attempt: u32, why: &str) {
    tracing::info!(correlation_id, attempt, "pool failover stopped: {why}");
    state.request_log.record(
        correlation_id,
        "pool_failover_stopped",
        json!({"attempt": attempt, "reason": why}),
    );
}

/// Resolve and refresh the selected OAuth credential, retaining the full token
/// so inference evidence can be bound to the generation that produced it.
pub(super) async fn resolve_upstream_credentials(
    state: &AppState,
    context: &RoutingContext,
    validated: Option<&crate::model_routing::ValidatedSubscription>,
) -> Result<ResolvedUpstreamCredential, Box<dyn std::error::Error + Send + Sync>> {
    if let Some(validated) = validated {
        if validated.provider != SubscriptionProvider::Claude {
            return Err("validated subscription does not match the Anthropic provider".into());
        }
        let selected = validated
            .for_dispatch_with_context(state, context)
            .await
            .map_err(std::io::Error::other)?;
        return Ok(ResolvedUpstreamCredential {
            access_token: selected.token.access_token.clone(),
            account: Some(selected.name),
            evidence_token: Some(selected.token),
        });
    }
    if let Some(router) = state.account_router.as_ref() {
        let sel = router
            .select_subscription_where_authoritative(context, &state.subscription_cache, |_| true)
            .await?;
        let now_ms = crate::operation_context::now().timestamp_millis();
        // The refresh leaves through the account's own egress as well.
        let client = router
            .http_client(&sel.name, CookieMode::None)
            .map_err(std::io::Error::other)?;
        let token = state
            .subscription_cache
            .get_fresh_loaded(&client, router.provider(), &sel.name, sel.token, now_ms)
            .await
            .map_err(std::io::Error::other)?;
        return Ok(ResolvedUpstreamCredential {
            access_token: token.access_token.clone(),
            account: Some(sel.name),
            evidence_token: Some(token),
        });
    }
    if state
        .subscription_cache
        .store_for_subscription(
            SubscriptionProvider::Claude,
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
        )
        .is_some()
    {
        let token = state
            .subscription_cache
            .get_fresh_registered(
                &state.client,
                SubscriptionProvider::Claude,
                crate::credential_recovery_store::PRIMARY_ACCOUNT,
                crate::operation_context::now().timestamp_millis(),
            )
            .await
            .map_err(std::io::Error::other)?;
        return Ok(ResolvedUpstreamCredential {
            access_token: token.access_token.clone(),
            account: None,
            evidence_token: Some(token),
        });
    }
    let token = state
        .oauth_provider
        .get_fresh_token(&state.client, &state.subscription_cache)
        .await?;
    Ok(ResolvedUpstreamCredential {
        access_token: token,
        account: None,
        evidence_token: None,
    })
}

