pub async fn openai_responses_route(
    State(state): State<AppState>,
    axum::extract::OriginalUri(uri): axum::extract::OriginalUri,
    request: axum::extract::Request,
) -> Response {
    let Some(namespace) = crate::response_affinity::ResponseNamespace::from_path(uri.path()) else {
        return crate::responses_lifecycle::response_not_found();
    };
    let native_route = namespace == crate::response_affinity::ResponseNamespace::CodexResponses;
    let headers = request.headers().clone();
    if let Err(response) = crate::proxy::authenticate_client(&state, &headers) {
        return *response;
    }
    let parsed = match crate::encoded_request_body::read_native_json(
        &headers,
        request.into_body(),
        state.max_proxy_request_bytes,
        native_route,
    )
    .await
    {
        Ok(parsed) => parsed,
        Err(response) => return response,
    };
    openai_responses_with_route(
        state,
        headers,
        Ok((parsed.value, native_route.then_some(parsed.native))),
        native_route,
        namespace,
    )
    .await
}

fn extracted_responses_body(
    body: Result<axum::Json<serde_json::Value>, JsonRejection>,
) -> Result<
    (
        serde_json::Value,
        Option<crate::encoded_request_body::NativeBody>,
    ),
    Response,
> {
    body.map(|axum::Json(value)| (value, None))
        .map_err(|error| {
            crate::api_error::malformed_json_response_for_surface(
                crate::metrics::Surface::OpenAIResponses,
                &error.body_text(),
            )
        })
}

async fn openai_responses_with_route(
    state: AppState,
    headers: HeaderMap,
    body: Result<
        (
            serde_json::Value,
            Option<crate::encoded_request_body::NativeBody>,
        ),
        Response,
    >,
    native_route: bool,
    namespace: crate::response_affinity::ResponseNamespace,
) -> Response {
    let (mut body, native_body) = match body {
        Ok(body) => body,
        Err(response) => return response,
    };
    let routing_body = body.clone();
    if let Err(response) =
        crate::thinking::normalize_ingress(&mut body, crate::metrics::Surface::OpenAIResponses)
    {
        return response;
    }
    let state = match state_for_previous_response(&state, &headers, namespace, &body) {
        Ok(state) => state,
        Err(response) => return response,
    };
    let client_path = if native_route {
        "/api/services/codex/v1/responses"
    } else {
        "/v1/responses"
    };
    let routed = match route_openai_request(
        &state,
        &headers,
        &body,
        crate::client_policy::ClientProtocol::OpenAIResponses,
        client_path,
    )
    .await
    {
        Ok(routed) => routed,
        Err(response) => return response,
    };
    let state = routed.state;
    let subscription = routed.subscription;
    rewrite_routed_model(&mut body, &state, subscription.as_ref());
    let store_requested = body.get("store").and_then(serde_json::Value::as_bool) == Some(true);
    let persistent_response_capable = matches!(
        state.upstream_provider,
        UpstreamProvider::OpenAICompatible | UpstreamProvider::Codex | UpstreamProvider::Qwen
    );
    if store_requested && !persistent_response_capable {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "the selected provider cannot preserve the stored Responses lifecycle",
        );
    }
    // The native Responses protocol stores by default; `store: false` is the
    // only opt-out. Translated providers retain their historical stateless
    // default and reject an explicit storage request above.
    let should_capture = persistent_response_capable
        && body.get("store").and_then(serde_json::Value::as_bool) != Some(false);
    let capture = if should_capture {
        match crate::resource_capture::prepare(&state, &headers, namespace).await {
            Ok(capture) => Some(capture),
            Err(response) => return response,
        }
    } else {
        None
    };
    if let Some(provider) = state.upstream_provider.subscription_provider()
        && let Err(response) = crate::client_policy::enforce_subscription(
            &state,
            &headers,
            provider,
            crate::client_policy::ClientProtocol::OpenAIResponses,
            client_path,
        )
    {
        return response;
    }
    if let Some(provider) = state.upstream_provider.subscription_provider()
        && let Some(kind) =
            crate::capabilities::unsupported_server_tool_type(provider, body.get("tools"))
    {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &format!("Unsupported server-side tool for selected provider: {kind}"),
        );
    }
    if let Some(reason) = crate::capabilities::unhonourable_server_tool_request(
        body.get("tools"),
        body.get("tool_choice"),
    ) {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if state.upstream_provider == UpstreamProvider::Gonka {
        return crate::gonka::forward_openai(
            &state,
            &headers,
            body,
            "/v1/responses",
            crate::metrics::Surface::OpenAIResponses,
        )
        .await;
    }
    if state.upstream_provider == UpstreamProvider::ZaiCodingPlan {
        return crate::zai_coding_plan::forward(
            &state,
            &headers,
            body,
            "/v1/responses",
            crate::client_policy::ClientProtocol::OpenAIResponses,
            crate::metrics::Surface::OpenAIResponses,
        )
        .await;
    }
    if state.upstream_provider == UpstreamProvider::OpenAICompatible {
        let response = crate::provider_proxy::forward_openai_compatible_routed(
            &state,
            &headers,
            body,
            &routing_body,
            "/v1/responses",
            crate::metrics::Surface::OpenAIResponses,
        )
        .await;
        return capture_created_resource(&state, capture, response).await;
    }
    if matches!(
        state.upstream_provider,
        UpstreamProvider::Codex | UpstreamProvider::Qwen
    ) {
        let response = crate::subscription_proxy::forward_subscription_openai_routed_native(
            &state,
            &headers,
            body,
            &routing_body,
            "/v1/responses",
            crate::metrics::Surface::OpenAIResponses,
            crate::subscription_proxy::RoutedSubscriptionContext {
                validated: subscription.as_ref(),
                entitlement: None,
                native_route,
            },
            native_body,
        )
        .await;
        return capture_created_resource(&state, capture, response).await;
    }
    if let Some(reason) = crate::bridge_controls::unknown_responses_field(&body) {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if let Err(reason) = crate::bridge_controls::validate_responses_resource_selectors(&body) {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if let Some(reason) =
        crate::bridge_controls::untranslatable_openai_service_tier(body.get("service_tier"))
    {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if let Some(reason) = crate::bridge_controls::untranslatable_moderation(body.get("moderation"))
    {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if let Err(reason) = crate::bridge_controls::validate_openai_prompt_cache(
        &body,
        state.upstream_provider != UpstreamProvider::Gemini,
    ) {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if state.upstream_provider == UpstreamProvider::Gemini {
        return crate::gemini::forward_responses_routed(
            &state,
            &headers,
            body,
            &routing_body,
            subscription.as_ref(),
        )
        .await;
    }
    if let Some(reason) = crate::bridge_request::untranslatable_responses_state(&body) {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    let req = match serde_json::from_value::<responses::OpenAIResponseRequest>(body) {
        Ok(req) => req,
        Err(e) => {
            return crate::api_error::error_response_for_surface(
                crate::metrics::Surface::OpenAIResponses,
                StatusCode::BAD_REQUEST,
                "invalid_request_error",
                &format!("invalid OpenAI responses request: {e}"),
            );
        }
    };
    let stream_requested = req.stream.unwrap_or(false);
    if let Err(reason) = crate::structured_output::responses_format(req.text.as_ref()) {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if let Err(reason) = crate::bridge_controls::validate_responses(&req) {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    // Validate against the account's live catalog rather than a built-in alias
    // table (issue #192). An account that has discovered nothing cannot judge
    // the name, so the upstream is left to decide.
    let catalog = state
        .model_catalogs
        .models(crate::subscription::SubscriptionProvider::Claude);
    if openai::resolve_model_with(&req.model, &BTreeMap::new(), &catalog).is_none() {
        return crate::model_routing::model_not_found_response(&req.model, &catalog);
    }
    // A tool entry Anthropic cannot represent is dropped, not fatal. Codex CLI
    // sends `namespace`, `custom` and `tool_search` in its ordinary tool set, so
    // rejecting the request refused nine usable tools over one that did not fit
    // — and made a documented client unable to drive Claude models at all
    // (issue #215). The drop is reported below so it is discoverable.
    let dropped_tools = req
        .tools
        .as_ref()
        .map(openai::untranslatable_anthropic_tools)
        .unwrap_or_default();
    if let Some(reason) = req
        .tools
        .as_ref()
        .and_then(openai::invalid_anthropic_tool_definition)
    {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if let Some(reason) = req
        .tool_choice
        .as_ref()
        .and_then(openai::untranslatable_anthropic_tool_choice)
    {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    if let Some(reason) = responses::untranslatable_tool_history(&req.input) {
        return crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            &reason,
        );
    }
    let body = responses::response_to_anthropic(&req);
    let response = forward_openai(
        &state,
        &headers,
        body,
        OpenAIForwardContext {
            routing_body: &routing_body,
            surface: crate::metrics::Surface::OpenAIResponses,
            stream_options: (stream_requested, OpenAIShape::Response, false),
            validated: subscription.as_ref(),
            entitlement_granted: true,
        },
    )
    .await;
    report_dropped_tools(&state, &headers, response, &dropped_tools)
}

#[cfg(test)]
#[path = "proxy_openai_tests.rs"]
mod routed_model_tests;

use super::{AppState, HeaderMap, Response, StatusCode, UpstreamProvider};

/// Resolve only the model alias owned by this `OpenAI` request route.
pub(super) fn canonical_openai_model<'a>(
    provider: UpstreamProvider,
    has_subscription: bool,
    routed_stored_model: Option<&'a str>,
    requested: &'a str,
) -> &'a str {
    if has_subscription {
        return crate::model_routing::subscription_model_identity(requested).1;
    }
    if provider == UpstreamProvider::OpenAICompatible {
        return routed_stored_model.unwrap_or(requested);
    }
    requested
}

pub(crate) async fn route_openai_request(
    state: &AppState,
    headers: &HeaderMap,
    body: &serde_json::Value,
    protocol: crate::client_policy::ClientProtocol,
    path: &str,
) -> Result<crate::model_routing::RoutedState, Response> {
    let claims = crate::proxy::authenticate_client_error(state, headers)
        .map_err(|error| error.render(crate::api_error::ApiDialect::OpenAi))?;
    let requested = body
        .get("model")
        .and_then(serde_json::Value::as_str)
        .filter(|model| !model.is_empty())
        .ok_or_else(|| {
            crate::api_error::PresentedError {
                status: StatusCode::BAD_REQUEST,
                error_type: "model_required",
                message: "request model must be a non-empty exact catalog id",
            }
            .render(crate::api_error::ApiDialect::OpenAi)
        })?;
    crate::proxy::authorize_model_for_claims(
        state,
        &claims,
        requested,
        crate::api_error::ApiDialect::OpenAi,
    )?;
    if state.upstream_provider != UpstreamProvider::Auto {
        return crate::model_routing::route_state_with_subscription(state, body)
            .await
            .map_err(|error| crate::model_routing::model_route_error_response(&error));
    }
    let client = crate::client_policy::bound_client(&claims)
        .map(|(client, _)| client)
        .map_err(|error| {
            crate::proxy::error_response(StatusCode::FORBIDDEN, "permission_error", &error)
        })?;
    let policy = state
        .provider_store
        .subscription_entitlement_policy()
        .map_err(|error| {
            crate::proxy::error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &format!("could not read subscription entitlement policy: {error}"),
            )
        })?;
    if policy.request_evidence(client, protocol, path, headers)
        == crate::client_policy::RequestEvidence::Denied
    {
        return Err(crate::proxy::error_response(
            StatusCode::FORBIDDEN,
            "permission_error",
            &format!(
                "request evidence does not match the token's {} client binding",
                client.canonical_name()
            ),
        ));
    }
    let entitled = crate::client_policy::entitled_subscription_providers_for_claims(
        state, &claims, headers, protocol, path,
    )?;
    crate::model_routing::route_state_with_subscription_for_client(
        state,
        body,
        &entitled,
        Some(client),
        crate::zai_coding_plan::authorize_automatic_discovery(
            state, &claims, headers, protocol, path,
        ),
    )
    .await
    .map_err(|error| crate::model_routing::model_route_error_response(&error))
}

pub(crate) fn rewrite_routed_model(
    body: &mut serde_json::Value,
    state: &AppState,
    subscription: Option<&crate::model_routing::ValidatedSubscription>,
) {
    let Some(requested) = body
        .get("model")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
    else {
        return;
    };
    let canonical = canonical_openai_model(
        state.upstream_provider,
        subscription.is_some(),
        state.bridge_model.as_deref(),
        &requested,
    );
    if !canonical.is_empty() && canonical != requested {
        body["model"] = serde_json::Value::String(canonical.to_string());
    }
}

pub(super) fn state_for_previous_response(
    state: &AppState,
    headers: &HeaderMap,
    namespace: crate::response_affinity::ResponseNamespace,
    body: &serde_json::Value,
) -> Result<AppState, Response> {
    let Some(previous) = body.get("previous_response_id") else {
        return Ok(state.clone());
    };
    let Some(previous) = previous.as_str().filter(|id| !id.is_empty()) else {
        return Err(crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "previous_response_id must be a non-empty string",
        ));
    };
    let claims = crate::proxy::authenticate_client_error(state, headers)
        .map_err(|error| error.render(crate::api_error::ApiDialect::OpenAi))?;
    let owner = crate::response_affinity::ResponseOwner::from_claims(&claims).map_err(|error| {
        crate::api_error::error_response_for_surface(
            crate::metrics::Surface::OpenAIResponses,
            StatusCode::FORBIDDEN,
            "permission_error",
            &error,
        )
    })?;
    let affinity = state
        .provider_store
        .response_affinities()
        .lookup(namespace, previous, &owner)
        .map_err(|error| {
            crate::api_error::error_response_for_surface(
                crate::metrics::Surface::OpenAIResponses,
                StatusCode::SERVICE_UNAVAILABLE,
                "api_error",
                &format!("response affinity is unavailable: {error}"),
            )
        })?;
    let Some(affinity) = affinity else {
        // Existing native clients can hold provider-created continuation IDs
        // from before Router began recording affinity. Preserve that request
        // path; every ID Router does know remains owner-scoped and pinned.
        return Ok(state.clone());
    };
    if let crate::response_affinity::AffinityDestination::Subscription { account, .. } =
        &affinity.destination
    {
        let pin = state
            .token_manager
            .account_for(&claims.sub)
            .map_err(|error| {
                crate::api_error::error_response_for_surface(
                    crate::metrics::Surface::OpenAIResponses,
                    StatusCode::SERVICE_UNAVAILABLE,
                    "api_error",
                    &format!("failed to resolve account binding: {error}"),
                )
            })?;
        if pin
            .as_deref()
            .unwrap_or(crate::credential_recovery_store::PRIMARY_ACCOUNT)
            != account
        {
            return Err(crate::responses_lifecycle::response_not_found());
        }
    }
    crate::resource_capture::pin_state(state, &affinity)
}

pub(super) async fn capture_created_resource(
    state: &AppState,
    capture: Option<crate::resource_capture::CaptureContext>,
    response: Response,
) -> Response {
    match capture {
        Some(capture) => crate::resource_capture::capture(state, capture, response).await,
        None => response,
    }
}

use super::{
    AppState, Body, DEFAULT_ANTHROPIC_VERSION, HeaderMap, HeaderValue, IntoResponse, Response,
    StatusCode, StreamExt, authenticate_client, error_response, merge_oauth_beta, openai,
    relay_response_headers, request_routing_context, resolve_upstream_credentials, responses,
    retry_after_duration,
};

#[derive(Clone, Copy)]
pub(super) enum OpenAIShape {
    Chat,
    Response,
}

pub(super) struct OpenAIForwardContext<'a> {
    pub(super) routing_body: &'a serde_json::Value,
    pub(super) surface: crate::metrics::Surface,
    pub(super) stream_options: (bool, OpenAIShape, bool),
    pub(super) validated: Option<&'a crate::model_routing::ValidatedSubscription>,
    pub(super) entitlement_granted: bool,
}

pub(super) async fn forward_openai(
    state: &AppState,
    headers: &HeaderMap,
    body: serde_json::Value,
    context: OpenAIForwardContext<'_>,
) -> Response {
    let OpenAIForwardContext {
        routing_body,
        surface,
        stream_options: (stream_requested, shape, include_usage),
        validated,
        entitlement_granted,
    } = context;
    let served_model = body["model"].as_str().unwrap_or_default().to_string();
    let path = match shape {
        OpenAIShape::Chat => "/v1/chat/completions",
        OpenAIShape::Response => "/v1/responses",
    };
    if let Some(resp) = maybe_mpp_challenge(state, headers, path) {
        return resp;
    }

    // Validate caller token.
    let claims = match authenticate_client(state, headers) {
        Ok(claims) => claims,
        Err(response) => return *response,
    };
    let requested_model = routing_body
        .get("model")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    let model_policy = if requested_model.is_empty() {
        match crate::proxy::model_policy_for_claims(state, &claims) {
            Ok(policy) if policy.allowed_models.is_empty() => policy,
            Ok(_) => {
                return error_response(
                    StatusCode::BAD_REQUEST,
                    "model_required",
                    "a pinned credential requires a non-empty exact model",
                );
            }
            Err(error) => {
                return error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "model_policy_unavailable",
                    &error.to_string(),
                );
            }
        }
    } else {
        match crate::proxy::authorize_model_for_claims(
            state,
            &claims,
            requested_model,
            crate::api_error::ApiDialect::OpenAi,
        ) {
            Ok(policy) => policy,
            Err(response) => return response,
        }
    };
    if !entitlement_granted {
        return error_response(
            StatusCode::FORBIDDEN,
            "permission_error",
            "consumer-subscription entitlement was not checked at ingress",
        );
    }
    let reserved = crate::token_reservation::estimate(&body).total();
    if let Err(e) = state
        .token_manager
        .enforce_request_budget_reserving(&claims.sub, reserved)
    {
        return crate::token_http::budget_error_response(&e);
    }
    let mut reservation = crate::usage::ReservationGuard::new(
        state.token_manager.clone(),
        claims.sub.clone(),
        reserved,
    );
    crate::audit::record_authorised_request(state, &claims, surface, path, Some(routing_body));

    let pinned_account = match state.token_manager.account_for(&claims.sub) {
        Ok(account) => account,
        Err(error) => {
            return error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &format!("failed to resolve token account binding: {error}"),
            );
        }
    };
    let routing_context = request_routing_context(headers, routing_body, pinned_account);

    // Resolve OAuth credentials.
    let resolved = match resolve_upstream_credentials(state, &routing_context, validated).await {
        Ok(resolved) => resolved,
        Err(e) => {
            tracing::error!("openai: upstream credentials unavailable: {e}");
            return error_response(
                StatusCode::BAD_GATEWAY,
                "api_error",
                "Upstream authentication unavailable",
            );
        }
    };
    if let (Some(account), Some(token)) = (
        resolved.account.as_deref(),
        resolved.evidence_token.as_ref(),
    ) {
        crate::account_policy_scope::credential(account, token);
    }
    let oauth_token = resolved.access_token;
    let mut selected_account = resolved.account;
    let evidence_token = resolved.evidence_token;
    let selector_kind = selected_account.as_deref().map_or(
        crate::model_contract::ModelSelectorKind::Unknown,
        |account| {
            state.model_catalogs.selector_kind_for(
                crate::subscription::SubscriptionProvider::Claude,
                account,
                requested_model,
            )
        },
    );

    let upstream_url = format!(
        "{}/v1/messages",
        state.upstream_base_url.trim_end_matches('/')
    );
    // Claude MAX OAuth inference requires Claude Code's identity as the first
    // system block; OpenAI-dialect clients such as Codex never send it.
    let mut body = body;
    if let Err(reason) = crate::thinking::anthropic::apply_translated_suffix(
        &mut body,
        routing_body,
        match shape {
            OpenAIShape::Chat => crate::thinking::ThinkingProtocol::OpenAIChat,
            OpenAIShape::Response => crate::thinking::ThinkingProtocol::OpenAIResponses,
        },
        crate::thinking::ThinkingProtocol::Anthropic,
    ) {
        return error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &reason);
    }
    if let Some(account) = selected_account.as_deref()
        && let Err(reason) = crate::thinking::apply_for_account(
            state,
            &mut body,
            &served_model,
            crate::subscription::SubscriptionProvider::Claude,
            account,
            &state.upstream_base_url,
            crate::thinking::ThinkingProtocol::Anthropic,
            match shape {
                OpenAIShape::Chat => crate::thinking::ThinkingProtocol::OpenAIChat,
                OpenAIShape::Response => crate::thinking::ThinkingProtocol::OpenAIResponses,
            },
            crate::thinking::suffix_applies(
                routing_body,
                requested_model,
                match shape {
                    OpenAIShape::Chat => crate::thinking::ThinkingProtocol::OpenAIChat,
                    OpenAIShape::Response => crate::thinking::ThinkingProtocol::OpenAIResponses,
                },
            ),
        )
    {
        return error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &reason);
    }
    if entitlement_granted && crate::claude_identity::is_oauth_credential(&oauth_token) {
        crate::claude_identity::ensure_claude_code_system(&mut body);
    }
    let serialized = match serde_json::to_vec(&body) {
        Ok(v) => v,
        Err(e) => {
            return error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &format!("failed to serialize translated body: {e}"),
            );
        }
    };
    let bytes_sent = serialized.len() as u64;

    let mut req_builder = state
        .client
        .post(&upstream_url)
        .header("authorization", format!("Bearer {oauth_token}"))
        .header("content-type", "application/json")
        .header("anthropic-version", DEFAULT_ANTHROPIC_VERSION)
        .body(serialized);
    if let Some(request_id) = crate::proxy::translated_request_id(headers) {
        req_builder = req_builder.header("x-request-id", request_id);
    }
    // Ensure the Claude MAX OAuth beta flag is present, merging any value the
    // caller supplied (OpenAI clients rarely send one).
    let merged_beta = merge_oauth_beta(headers.get("anthropic-beta").and_then(|v| v.to_str().ok()));
    req_builder = req_builder.header("anthropic-beta", merged_beta);
    let correlation_id = crate::request_log::correlation_id(headers);
    let upstream_resp = match state
        .request_log
        .send_upstream(&correlation_id, &state.client, req_builder)
        .await
    {
        Ok(r) => r,
        Err(e) => {
            state
                .metrics
                .record_request(surface, 502, selected_account.as_deref());
            return error_response(
                StatusCode::BAD_GATEWAY,
                "api_error",
                &format!("upstream request failed: {e}"),
            );
        }
    };
    if crate::account_policy_scope::active() {
        selected_account = crate::account_policy_scope::account();
    }
    let upstream_status = upstream_resp.status();
    if !upstream_status.is_success() {
        tracing::warn!(
            upstream_status = upstream_status.as_u16(),
            error_class = crate::logging::http_failure(upstream_status.as_u16()),
            "upstream request rejected"
        );
    }
    crate::request_routing::record_claude_evidence(
        state,
        selected_account.as_deref(),
        evidence_token.as_ref(),
        upstream_status.as_u16(),
    )
    .await;
    let retry_after = retry_after_duration(upstream_resp.headers());
    let response_headers = relay_response_headers(upstream_resp.headers());
    if stream_requested && upstream_status.is_success() {
        state
            .metrics
            .record_request(surface, 200, selected_account.as_deref());
        let stream_shape = match shape {
            OpenAIShape::Chat => openai::OpenAIStreamShape::ChatCompletion,
            OpenAIShape::Response => openai::OpenAIStreamShape::Response,
        };
        let translator = openai::OpenAIStreamTranslator::new(stream_shape, &served_model)
            .with_include_usage(include_usage);
        let identity = crate::output_limit::ResponsesStreamRewriter::new(requested_model, None)
            .with_model_policy(&model_policy)
            .with_selector_kind(selector_kind);
        let completion_audit = crate::audit::ResponseModelAudit::new(state, &claims, surface, path)
            .with_models(Some(requested_model), Some(&served_model))
            .with_provider(Some("claude"))
            .with_provider_account(selected_account.as_deref())
            .with_provider_endpoint(Some(&state.upstream_base_url))
            .with_selector_kind(selector_kind);
        let translation_state =
            std::sync::Arc::new(std::sync::Mutex::new((translator, identity, false)));
        let chunk_translation_state = std::sync::Arc::clone(&translation_state);
        let chunk_completion_audit = completion_audit.clone();
        let response_log = std::sync::Arc::clone(&state.request_log);
        let mut usage = reservation.take().into_tracker();
        let stream = upstream_resp.bytes_stream().map(move |chunk| match chunk {
            Ok(bytes) => {
                response_log.record_upstream_body(&correlation_id, &bytes);
                usage.feed(&bytes);
                let output = {
                    let mut state = chunk_translation_state
                        .lock()
                        .expect("stream translation state lock");
                    let (translator, identity, model_audited) = &mut *state;
                    let verified = identity.push(&bytes);
                    let served_model = identity.upstream_model().map(str::to_string);
                    if !*model_audited && let Some(served_model) = served_model.as_deref() {
                        chunk_completion_audit.record_verified(served_model);
                        *model_audited = true;
                    }
                    let output = translator.push(verified.as_bytes()).join("");
                    drop(state);
                    output
                };
                Ok::<bytes::Bytes, std::io::Error>(bytes::Bytes::from(output))
            }
            Err(e) => Err(std::io::Error::other(e)),
        });
        let stream = stream.chain(futures_util::stream::once(async move {
            let output = {
                let mut state = translation_state
                    .lock()
                    .expect("stream translation state lock");
                let (translator, identity, model_audited) = &mut *state;
                let verified = identity.finish();
                let served_model = identity.upstream_model().map(str::to_string);
                if !*model_audited && let Some(served_model) = served_model.as_deref() {
                    completion_audit.record_verified(served_model);
                    *model_audited = true;
                }
                let output = translator.push(verified.as_bytes()).join("");
                drop(state);
                output
            };
            Ok::<bytes::Bytes, std::io::Error>(bytes::Bytes::from(output))
        }));
        // A cut Claude stream ends with an error in the client's dialect,
        // never with a synthesized `[DONE]` (issue #668).
        let dialect = match shape {
            OpenAIShape::Chat => crate::stream_termination::StreamDialect::OpenAiChat,
            OpenAIShape::Response => crate::stream_termination::StreamDialect::Responses,
        };
        let stream = crate::stream_termination::in_band_errors(stream, Some(dialect));
        let mut response = Response::new(Body::from_stream(stream));
        *response.status_mut() = StatusCode::OK;
        *response.headers_mut() = response_headers;
        response.headers_mut().insert(
            "content-type",
            HeaderValue::from_static("text/event-stream; charset=utf-8"),
        );
        return response;
    }
    let upstream_body = match upstream_resp.bytes().await {
        Ok(b) => b,
        Err(e) => {
            state
                .metrics
                .record_request(surface, 502, selected_account.as_deref());
            return error_response(
                StatusCode::BAD_GATEWAY,
                "api_error",
                &format!("upstream body read failed: {e}"),
            );
        }
    };
    state
        .request_log
        .record_upstream_body(&correlation_id, &upstream_body);
    let bytes_received = upstream_body.len() as u64;
    state.metrics.record_bytes(bytes_sent, bytes_received);

    if !upstream_status.is_success() {
        if upstream_status.as_u16() == 429
            && let (Some(router), Some(name)) =
                (state.account_router.as_ref(), selected_account.as_deref())
        {
            router.report_failure_with_retry_after(name, "upstream returned 429", retry_after);
        }
        state.metrics.record_request(
            surface,
            upstream_status.as_u16(),
            selected_account.as_deref(),
        );
        let parsed: serde_json::Value =
            serde_json::from_slice(&upstream_body).unwrap_or_else(|_| serde_json::json!({}));
        let mut resp = (
            StatusCode::from_u16(upstream_status.as_u16()).unwrap_or(StatusCode::BAD_GATEWAY),
            axum::Json(parsed),
        )
            .into_response();
        *resp.headers_mut() = response_headers;
        resp.headers_mut()
            .insert("content-type", HeaderValue::from_static("application/json"));
        return resp;
    }

    let anthropic: serde_json::Value = match serde_json::from_slice(&upstream_body) {
        Ok(v) => v,
        Err(e) => {
            state
                .metrics
                .record_request(surface, 502, selected_account.as_deref());
            return error_response(
                StatusCode::BAD_GATEWAY,
                "api_error",
                &format!("upstream returned non-JSON: {e}"),
            );
        }
    };
    let concrete_served_model =
        match crate::model_contract::validate_translated_response_for_selector(
            requested_model,
            &anthropic,
            &model_policy,
            selector_kind,
        ) {
            Ok(served_model) => served_model,
            Err(error) => {
                return error_response(StatusCode::BAD_GATEWAY, &error.code, &error.to_string());
            }
        };
    if let Some(concrete_served_model) = concrete_served_model.as_deref() {
        crate::audit::ResponseModelAudit::new(state, &claims, surface, path)
            .with_models(Some(requested_model), Some(&served_model))
            .with_provider(Some("claude"))
            .with_provider_account(selected_account.as_deref())
            .with_provider_endpoint(Some(&state.upstream_base_url))
            .with_selector_kind(selector_kind)
            .record_completed(concrete_served_model);
    }
    if let Err(error) =
        crate::bridge_response::validate_anthropic_response_citations(anthropic.get("content"))
    {
        return error_response(
            StatusCode::BAD_GATEWAY,
            "api_error",
            &format!("upstream returned an unrepresentable citation: {error}"),
        );
    }
    reservation
        .take()
        .settle(crate::usage::token_count(&anthropic).unwrap_or(0));

    let concrete_served_model = concrete_served_model.as_deref().unwrap_or_default();
    let translated = match shape {
        OpenAIShape::Chat => {
            openai::anthropic_to_chat_completion(&anthropic, concrete_served_model)
        }
        OpenAIShape::Response => {
            responses::anthropic_to_response(&anthropic, concrete_served_model)
        }
    };

    state
        .metrics
        .record_request(surface, 200, selected_account.as_deref());

    let mut response = (StatusCode::OK, axum::Json(translated)).into_response();
    *response.headers_mut() = response_headers;
    response
        .headers_mut()
        .insert("content-type", HeaderValue::from_static("application/json"));
    response
}

pub(super) fn maybe_mpp_challenge(
    state: &AppState,
    headers: &HeaderMap,
    path: &str,
) -> Option<Response> {
    if !state.mpp.is_configured() {
        return None;
    }
    if crate::mpp::has_payment_credential(headers) {
        return Some(crate::mpp::unsupported_payment_verification());
    }
    Some(crate::mpp::payment_required(&state.mpp, path))
}

//! OAuth refresh and durable rotation handling for vendor subscriptions.
//!
//! When a token read from disk has expired, this module exchanges its
//! `refresh_token` for a fresh access token using the vendor's public OAuth
//! client (the same client ids embedded in each vendor's open-source CLI) and
//! caches the result in memory.
//!
//! Production callers register a recovery-aware store. Any refreshed token is
//! durably persisted there before it can be used; if neither the vendor file
//! nor its recovery sidecar can be committed, serving and diagnostics fail
//! closed. The legacy stateless refresh API still accepts a caller-provided
//! token and cannot provide that transaction guarantee.
//!
//! This is the same behavior `ProxyPal` relies on so the proxy keeps working even
//! when the vendor CLI is not running to refresh its own credential file.
//!
//! Claude is included here too: the runtime container image ships no Claude CLI,
//! so nothing else would keep `~/.claude/.credentials.json` current. The
//! `refreshToken` stored in the nested `claudeAiOauth` block is exchanged the
//! same way.
//!
//! Secrets (access/refresh tokens) are never logged.

use std::collections::HashMap;
use std::sync::Mutex;

use serde::Deserialize;

#[path = "refresh_state.rs"]
mod refresh_state;
use refresh_state::RefreshAttempts;

#[path = "refresh_journal.rs"]
mod refresh_journal;
#[path = "refresh_recovery.rs"]
mod refresh_recovery;
#[path = "refresh_registry.rs"]
mod refresh_registry;
pub use refresh_journal::direct_exchange_shape;
use refresh_journal::{journal_request, journal_response};
use refresh_recovery::{Exchange, RecoveryMode, Rejected, exchange_with_recovery};

