//! Per-subscription refresh suppression, backoff, and single-flight state.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use sha2::{Digest, Sha256};

use crate::subscription::{SubscriptionProvider, SubscriptionToken};

const INITIAL_BACKOFF_MS: i64 = 1_000;
const MAX_BACKOFF_MS: i64 = 5 * 60 * 1_000;
type SubscriptionKey = (SubscriptionProvider, String);
type AttemptLock = Arc<tokio::sync::Mutex<RefreshAttempt>>;

#[derive(Debug, Default)]
pub(super) struct RefreshAttempts {
    inner: Mutex<HashMap<SubscriptionKey, AttemptLock>>,
}

/// How long a refresh token this process just adopted is protected from being
/// spent again.
///
/// A refresh chain is single-use: spending a link yields the next one and
/// invalidates the one spent. When a rotation succeeds and the very next call
/// fails for a reason that is not about the credential, refreshing again
/// destroys a token that was known-good seconds earlier and gains nothing,
/// because no new information about the credential has arrived (issue #319).
pub(super) const ROTATION_GRACE_MS: i64 = 5 * 60 * 1_000;

#[derive(Debug)]
pub(super) struct RefreshAttempt {
    credential: [u8; 32],
    failure: Option<CachedFailure>,
    /// When this process last obtained this credential by refreshing, if it
    /// did. `None` means the credential was read from disk rather than minted
    /// here, so nothing is known about how recently it was rotated.
    rotated_at_ms: Option<i64>,
    /// Fingerprint of the credential this process minted, when it did.
    ///
    /// Kept beside `credential` rather than replacing it. `credential` must go
    /// on tracking the *stored* credential, or a second concurrent caller
    /// holding the same disk token would read the rotation as a change and
    /// refresh again — but the ladder writes the rotation to the very file the
    /// next request reads, so without this the router's own work is
    /// indistinguishable from a re-authentication (issue #319).
    rotated_to: Option<[u8; 32]>,
}

#[derive(Debug, Clone, Copy)]
enum CachedFailure {
    Terminal,
    Transient { failures: u32, retry_at_ms: i64 },
}

impl RefreshAttempts {
    pub(super) fn for_subscription(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
    ) -> AttemptLock {
        let fingerprint = attempt_fingerprint(provider, credential);
        let mut guard = self
            .inner
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        Arc::clone(
            guard
                .entry((provider, account.to_string()))
                .or_insert_with(|| {
                    Arc::new(tokio::sync::Mutex::new(RefreshAttempt {
                        credential: fingerprint,
                        failure: None,
                        rotated_at_ms: None,
                        rotated_to: None,
                    }))
                }),
        )
    }
}

impl RefreshAttempt {
    /// Whether `credential` belongs to the generation this attempt currently
    /// represents. A token this process just refreshed into supersedes the
    /// stored generation that produced it.
    pub(super) fn matches_current(
        &self,
        provider: SubscriptionProvider,
        credential: &SubscriptionToken,
    ) -> bool {
        let fingerprint = attempt_fingerprint(provider, credential);
        self.rotated_to.unwrap_or(self.credential) == fingerprint
    }

    /// Reset state when this provider's durable credential identity changes.
    pub(super) fn reset_if_changed(
        &mut self,
        provider: SubscriptionProvider,
        credential: &SubscriptionToken,
    ) -> bool {
        let fingerprint = attempt_fingerprint(provider, credential);
        if self.credential == fingerprint {
            return false;
        }
        // The credential this process just minted, arriving back through the
        // file the ladder wrote it to. That is not a re-authentication, and
        // reading it as one cleared the guard seconds after it was armed and
        // dropped a cache that had just been filled (issue #319).
        if self.rotated_to == Some(fingerprint) {
            self.credential = fingerprint;
            return false;
        }
        self.credential = fingerprint;
        self.failure = None;
        // A credential nobody here minted: whatever this process rotated to is
        // no longer what is being used, so the grace period does not carry over.
        self.rotated_at_ms = None;
        self.rotated_to = None;
        true
    }

    /// Record that this process minted `credential` by refreshing.
    ///
    /// The fingerprint moves with it. The recovery ladder writes a rotation
    /// back to the very file `read_token` reads, so without this the next
    /// inbound request hands `get_fresh_for` a credential that differs from the
    /// one this attempt was keyed on, [`Self::reset_if_changed`] reads the
    /// router's own rotation as a re-authentication, and the guard is cleared
    /// seconds after it is armed (issue #319).
    pub(super) fn record_rotation(
        &mut self,
        provider: SubscriptionProvider,
        now_ms: i64,
        credential: &SubscriptionToken,
    ) {
        self.rotated_to = Some(attempt_fingerprint(provider, credential));
        self.rotated_at_ms = Some(now_ms);
    }

    /// How long ago this process rotated into the current credential.
    pub(super) const fn rotated_within(&self, now_ms: i64, window_ms: i64) -> Option<i64> {
        match self.rotated_at_ms {
            Some(rotated_at_ms) if now_ms.saturating_sub(rotated_at_ms) < window_ms => {
                Some(now_ms.saturating_sub(rotated_at_ms))
            }
            _ => None,
        }
    }

    pub(super) const fn suppresses_attempt(&self, now_ms: i64) -> bool {
        match self.failure {
            Some(CachedFailure::Terminal) => true,
            Some(CachedFailure::Transient { retry_at_ms, .. }) => now_ms < retry_at_ms,
            None => false,
        }
    }

    pub(super) const fn record_success(&mut self) {
        self.failure = None;
    }

    pub(super) const fn record_terminal_failure(&mut self) {
        self.failure = Some(CachedFailure::Terminal);
    }

    /// Record a retryable failure, waiting at least `retry_after_ms` when the
    /// endpoint named its own delay.
    ///
    /// The larger of the two wins: our backoff must not undercut a `Retry-After`
    /// the vendor asked for, and a small `Retry-After` must not reset a backoff
    /// that repeated failures have already grown (issue #203).
    pub(super) fn record_transient_failure_after(
        &mut self,
        now_ms: i64,
        retry_after_ms: Option<i64>,
    ) {
        let failures = match self.failure {
            Some(CachedFailure::Transient { failures, .. }) => failures.saturating_add(1),
            _ => 1,
        };
        let shift = failures.saturating_sub(1).min(18);
        let delay = INITIAL_BACKOFF_MS
            .saturating_mul(1_i64 << shift)
            .min(MAX_BACKOFF_MS)
            .max(retry_after_ms.unwrap_or(0));
        self.failure = Some(CachedFailure::Transient {
            failures,
            retry_at_ms: now_ms.saturating_add(delay),
        });
    }
}

/// Identify every credential-file change without retaining another plaintext
/// copy of its secrets in failure state.
/// A stable identity for one credential's contents, without storing it.
///
/// Shared with the rejection registry so a verdict reached about one chain link
/// is discarded the moment the file on disk holds a different one (issue #245).
pub(super) fn credential_fingerprint(token: &SubscriptionToken) -> [u8; 32] {
    credential_fingerprint_with_expiry(token, true)
}

/// Identity used only by one process's refresh attempt state.
///
/// Codex writes access/refresh/account state but intentionally leaves its old
/// expiry representation in the credential document. Ignoring only that
/// provider's expiry keeps a self-minted rotation recognizable after its real
/// durable round trip. Durable recovery and rejection records continue to use
/// [`credential_fingerprint`], which remains exact across every token field.
fn attempt_fingerprint(provider: SubscriptionProvider, token: &SubscriptionToken) -> [u8; 32] {
    credential_fingerprint_with_expiry(token, provider != SubscriptionProvider::Codex)
}

fn credential_fingerprint_with_expiry(token: &SubscriptionToken, include_expiry: bool) -> [u8; 32] {
    fn hash_field(hasher: &mut Sha256, value: Option<&str>) {
        match value {
            Some(value) => {
                hasher.update([1]);
                hasher.update(value.len().to_le_bytes());
                hasher.update(value.as_bytes());
            }
            None => hasher.update([0]),
        }
    }

    let mut hasher = Sha256::new();
    hash_field(&mut hasher, Some(&token.access_token));
    hash_field(&mut hasher, token.refresh_token.as_deref());
    if include_expiry {
        match token.expires_at_ms {
            Some(expiry) => {
                hasher.update([1]);
                hasher.update(expiry.to_le_bytes());
            }
            None => hasher.update([0]),
        }
    }
    hash_field(&mut hasher, token.account_id.as_deref());
    hash_field(&mut hasher, token.resource_url.as_deref());
    hasher.finalize().into()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn token(refresh: &str) -> SubscriptionToken {
        SubscriptionToken {
            access_token: "expired".into(),
            refresh_token: Some(refresh.into()),
            expires_at_ms: Some(1),
            account_id: None,
            resource_url: None,
        }
    }

    #[tokio::test]
    async fn terminal_failure_is_rearmed_only_by_changed_credentials() {
        let attempts = RefreshAttempts::default();
        let original = token("revoked");
        let attempt = attempts.for_subscription(SubscriptionProvider::Claude, "primary", &original);
        let mut state = attempt.lock().await;
        state.record_terminal_failure();
        assert!(state.suppresses_attempt(10_000));
        assert!(!state.reset_if_changed(SubscriptionProvider::Claude, &original));
        assert!(state.suppresses_attempt(20_000));
        assert!(state.reset_if_changed(SubscriptionProvider::Claude, &token("new-login")));
        assert!(!state.suppresses_attempt(20_000));
        drop(state);
    }

    #[tokio::test]
    async fn transient_failures_back_off_exponentially_with_a_ceiling() {
        let attempts = RefreshAttempts::default();
        let attempt =
            attempts.for_subscription(SubscriptionProvider::Claude, "primary", &token("transient"));
        let mut state = attempt.lock().await;
        state.record_transient_failure_after(10_000, None);
        assert!(state.suppresses_attempt(10_999));
        assert!(!state.suppresses_attempt(11_000));
        state.record_transient_failure_after(11_000, None);
        assert!(state.suppresses_attempt(12_999));
        assert!(!state.suppresses_attempt(13_000));
        for _ in 0..30 {
            state.record_transient_failure_after(20_000, None);
        }
        assert!(state.suppresses_attempt(319_999));
        assert!(!state.suppresses_attempt(320_000));
        drop(state);
    }
}

#[cfg(test)]
mod rotation_tests {
    use super::*;

    fn token(access: &str, refresh: &str) -> SubscriptionToken {
        SubscriptionToken {
            access_token: access.into(),
            refresh_token: Some(refresh.into()),
            expires_at_ms: Some(0),
            account_id: None,
            resource_url: None,
        }
    }

    /// The guard is a window, not a latch: it reports the age while it holds
    /// and nothing once it lapses (issue #319).
    #[test]
    fn the_rotation_window_reports_an_age_and_then_lapses() {
        let mut attempt = RefreshAttempt {
            credential: credential_fingerprint(&token("a", "r1")),
            failure: None,
            rotated_at_ms: None,
            rotated_to: None,
        };
        assert_eq!(attempt.rotated_within(1_000, ROTATION_GRACE_MS), None);

        attempt.record_rotation(SubscriptionProvider::Claude, 1_000, &token("b", "r2"));
        assert_eq!(attempt.rotated_within(1_000, ROTATION_GRACE_MS), Some(0));
        assert_eq!(
            attempt.rotated_within(61_000, ROTATION_GRACE_MS),
            Some(60_000),
            "still inside the five-minute window"
        );
        assert_eq!(
            attempt.rotated_within(1_000 + ROTATION_GRACE_MS, ROTATION_GRACE_MS),
            None,
            "the window is half-open, so it lapses exactly on the boundary"
        );
    }

    /// The credential this process minted, arriving back through the file the
    /// ladder wrote it to, is not a re-authentication.
    #[test]
    fn a_self_minted_credential_is_not_read_as_a_re_authentication() {
        let original = token("a", "r1");
        let rotated = token("b", "r2");
        let mut attempt = RefreshAttempt {
            credential: credential_fingerprint(&original),
            failure: None,
            rotated_at_ms: None,
            rotated_to: None,
        };
        attempt.record_rotation(SubscriptionProvider::Claude, 1_000, &rotated);

        assert!(
            !attempt.reset_if_changed(SubscriptionProvider::Claude, &rotated),
            "the router's own rotation must not clear its own guard"
        );
        assert_eq!(
            attempt.rotated_within(2_000, ROTATION_GRACE_MS),
            Some(1_000),
            "the guard still holds"
        );

        // A credential nobody here minted *is* a re-authentication.
        assert!(attempt.reset_if_changed(SubscriptionProvider::Claude, &token("c", "r3")));
        assert_eq!(attempt.rotated_within(2_000, ROTATION_GRACE_MS), None);
    }

    /// Codex's expiry is serialization loss, not credential identity. Every
    /// bearer, refresh-chain, account, and resource change remains an external
    /// replacement and must clear the old attempt state.
    #[test]
    fn codex_attempt_identity_ignores_only_expiry() {
        let original = SubscriptionToken {
            access_token: "access-a".into(),
            refresh_token: Some("refresh-a".into()),
            expires_at_ms: Some(10),
            account_id: Some("account-a".into()),
            resource_url: Some("resource-a".into()),
        };
        let attempt_for = || RefreshAttempt {
            credential: attempt_fingerprint(SubscriptionProvider::Codex, &original),
            failure: None,
            rotated_at_ms: Some(1),
            rotated_to: Some(attempt_fingerprint(SubscriptionProvider::Codex, &original)),
        };

        let mut lossy_expiry = original.clone();
        lossy_expiry.expires_at_ms = Some(1);
        assert!(
            !attempt_for().reset_if_changed(SubscriptionProvider::Codex, &lossy_expiry),
            "Codex expiry alone is not a new credential"
        );
        assert!(
            attempt_for().reset_if_changed(SubscriptionProvider::Claude, &lossy_expiry),
            "other providers retain exact expiry identity"
        );

        for replacement in [
            SubscriptionToken {
                access_token: "access-b".into(),
                ..original.clone()
            },
            SubscriptionToken {
                refresh_token: Some("refresh-b".into()),
                ..original.clone()
            },
            SubscriptionToken {
                account_id: Some("account-b".into()),
                ..original.clone()
            },
            SubscriptionToken {
                resource_url: Some("resource-b".into()),
                ..original.clone()
            },
        ] {
            assert!(
                attempt_for().reset_if_changed(SubscriptionProvider::Codex, &replacement),
                "a changed Codex bearer/refresh/account/resource must be a new credential"
            );
        }
    }
}

//! The protocol journal: what a token exchange looked like, never what it carried.
//!
//! These OAuth endpoints are undocumented, change without notice, and attest
//! their clients — so a refresh that works in one particular shape and fails in
//! another is a thing an operator must be able to see from the log alone,
//! without a packet capture (issue #239).
//!
//! Everything here records *shape*: method, URL, header names with their
//! non-secret values, and body field names. Values are the secrets and are
//! never written.

use super::{BodyStyle, refresh_config};
use crate::subscription::SubscriptionProvider;

/// Record the *shape* of an outbound token exchange, never its contents.
///
/// These OAuth endpoints are undocumented and attest their clients, so when a
/// refresh only succeeds in one particular shape an operator needs to be able
/// to reproduce that shape from the log alone. Header names with their
/// (non-secret) values and body field *names* are enough to do that; the field
/// values are the secrets and are never written (issue #239).
pub(super) fn journal_request(
    provider: SubscriptionProvider,
    token_url: &str,
    content_type: &str,
    headers: &[(String, String)],
    body_fields: &[&str],
) {
    tracing::debug!(
        "{provider} token exchange: {}",
        exchange_shape(token_url, content_type, headers, body_fields)
    );
}

/// Render one exchange as method, URL, headers and body field *names*.
fn exchange_shape(
    token_url: &str,
    content_type: &str,
    headers: &[(String, String)],
    body_fields: &[&str],
) -> String {
    let mut sent = vec![format!("content-type: {content_type}")];
    sent.extend(
        headers
            .iter()
            .map(|(name, value)| format!("{name}: {value}")),
    );
    format!(
        "POST {token_url} [{}] body fields [{}] (values omitted)",
        sent.join(", "),
        body_fields.join(", ")
    )
}

/// The exchange the router itself would send for `provider`, without sending it.
///
/// Built from the same configuration `refresh_at` uses, so a fallback record
/// can be compared against what the vendor's own client does: if the two send
/// different headers, the journal shows it without further debugging (issue
/// #239).
#[must_use]
pub fn direct_exchange_shape(provider: SubscriptionProvider) -> String {
    let config = refresh_config(provider);
    let headers = super::refresh_headers(provider);
    let content_type = match config.style {
        BodyStyle::Json => "application/json",
        BodyStyle::Form => "application/x-www-form-urlencoded",
    };
    let mut fields = vec!["grant_type", "refresh_token", "client_id"];
    if provider == SubscriptionProvider::Gemini {
        fields.push("client_secret");
    }
    exchange_shape(config.token_url, content_type, &headers, &fields)
}

/// Record which fields a successful token response carried.
///
/// Field names only: whether `refresh_token` came back at all is the difference
/// between a rotating and a non-rotating vendor, and that is exactly what a
/// later diagnosis needs to know.
pub(super) fn journal_response(
    provider: SubscriptionProvider,
    status: u16,
    document: &serde_json::Value,
) {
    let fields = document.as_object().map_or_else(
        || String::from("<not an object>"),
        |map| map.keys().cloned().collect::<Vec<_>>().join(", "),
    );
    tracing::debug!("{provider} token exchange answered HTTP {status} with fields [{fields}]");
}

//! The recovery ladder a token exchange climbs before declaring a credential dead.
//!
//! A rotated refresh token and a revoked one fail identically: the endpoint
//! answers `invalid_grant` to both. Concluding "revoked" from that answer alone
//! is what turns a routine rotation race — the vendor CLI, a second router, or
//! this router's own earlier refresh moved the chain forward — into a manual
//! re-authentication (issue #239).
//!
//! So before concluding anything, each exchange:
//!
//! 1. takes the credential's advisory lock, so read → refresh → write cannot
//!    interleave with another holder's;
//! 2. re-reads the store — the copy on disk may already be newer than the token
//!    we were handed, in which case no exchange is spent at all;
//! 3. exchanges the best link it has;
//! 4. on `invalid_grant`, re-reads the store *again* and retries once with a
//!    newer link, because the rotation may have landed while we were exchanging;
//! 5. persists a rotated link before the new access token is used, so the
//!    rotation survives a restart on every path, not just catalog polling;
//! 6. and only then reports failure — naming which of the two causes it is.
//!
//! Secrets are never logged. What *is* logged is the shape of the exchange —
//! method, URL, header names, body field names, response status and which
//! response fields came back — because these OAuth endpoints are undocumented
//! and an operator reproducing a working request needs the shape, not the
//! values.

use std::sync::Arc;

use super::{REFRESH_SKEW_MS, RefreshError, refresh_at};
use crate::credential_store::{CredentialStore, has_newer_refresh_link, is_same_link};
use crate::subscription::{SubscriptionProvider, SubscriptionToken};
use crate::vendor_cli_refresh::VendorCli;

/// Which rung of the ladder produced a usable credential.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum RecoveryRung {
    /// The credential store already held a usable token; no exchange spent.
    AdoptedStoredToken,
    /// The link we were handed was exchanged successfully.
    DirectExchange,
    /// Our link was rejected; a newer one from the store was exchanged instead.
    AdoptedRotatedLink,
    /// Every direct exchange was rejected; the vendor's own client rotated the
    /// chain and we adopted what it wrote.
    VendorCliRotation,
}

impl RecoveryRung {
    /// How this recovery happened, in the operator's terms.
    pub(super) const fn describe(self) -> &'static str {
        match self {
            Self::AdoptedStoredToken => {
                "adopted a newer credential from disk without spending an exchange"
            }
            Self::DirectExchange => "exchanged the stored refresh token",
            Self::AdoptedRotatedLink => {
                "the stored refresh token was rejected; adopted a newer one from disk and retried"
            }
            Self::VendorCliRotation => {
                "every direct exchange was rejected; the vendor client rotated the chain and its \
                 credential was adopted"
            }
        }
    }

    /// Whether this rung represents recovery from a failure worth reporting at
    /// `info`, as opposed to an ordinary refresh.
    pub(super) const fn is_recovery(self) -> bool {
        matches!(self, Self::AdoptedRotatedLink | Self::VendorCliRotation)
    }
}

/// A credential obtained by the ladder.
#[derive(Debug)]
pub(super) struct Recovered {
    /// The usable token.
    pub(super) token: SubscriptionToken,
    /// Which rung produced it.
    pub(super) rung: RecoveryRung,
}

/// A credential the ladder could not recover.
#[derive(Debug)]
pub(super) struct Rejected {
    /// The underlying endpoint failure, for classification (terminal, rate
    /// limited, retryable).
    pub(super) error: RefreshError,
    /// Operator-facing explanation that distinguishes a revoked credential from
    /// one that was rotated past.
    pub(super) message: String,
}

/// Everything one token exchange needs besides the credential itself.
///
/// Grouped rather than passed as a parameter list because every rung of the
/// ladder needs all of it.
#[derive(Debug, Clone, Copy)]
pub(super) struct Exchange<'a> {
    /// HTTP client to exchange with.
    pub(super) client: &'a reqwest::Client,
    /// Token endpoint, overridable so tests exercise the real request shape.
    pub(super) token_url: &'a str,
    /// Subscription provider being refreshed.
    pub(super) provider: SubscriptionProvider,
    /// Wall clock in epoch milliseconds.
    pub(super) now_ms: i64,
    /// Why the ladder is climbing.
    pub(super) mode: RecoveryMode,
}

/// Why the ladder is climbing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum RecoveryMode {
    /// The token is at or near its stated expiry.
    Proactive,
    /// An upstream rejected the token regardless of its stated expiry, so only
    /// a *different* access token counts as progress.
    AfterRejection,
    /// Credential import must prove the rotating chain itself. A live access
    /// token found in the isolated store is therefore not a substitute for a
    /// successful refresh-token exchange.
    ImportValidation,
}

/// The links this exchange has already spent.
///
/// Both are needed once the ladder reaches the vendor client: `base` says which
/// access token was rejected, `newest` says which chain link the store held
/// before the client ran, so a client that changed nothing can be told from one
/// that rotated.
#[derive(Debug, Clone, Copy)]
struct Tried<'a> {
    /// The credential the caller handed us.
    base: &'a SubscriptionToken,
    /// The newest link we found before giving up on direct exchanges.
    newest: &'a SubscriptionToken,
}

/// Whether a credential found in the store can be used as-is.
fn is_usable(
    candidate: &SubscriptionToken,
    base: &SubscriptionToken,
    mode: RecoveryMode,
    now_ms: i64,
) -> bool {
    match mode {
        // Adopt only a token that still has life left, using the same skew the
        // proactive path applies so we do not adopt one we would refresh again
        // on the very next call.
        RecoveryMode::Proactive => !candidate.is_expired(now_ms.saturating_add(REFRESH_SKEW_MS)),
        // The rejected access token is not usable no matter what its timestamp
        // claims; replaying it would just repeat the 401.
        RecoveryMode::AfterRejection => {
            candidate.access_token != base.access_token && !candidate.is_expired(now_ms)
        }
        RecoveryMode::ImportValidation => false,
    }
}

fn storage_rejection(message: impl Into<String>) -> Rejected {
    let error = RefreshError::Storage(message.into());
    let message = error.to_string();
    Rejected { error, message }
}

/// Fixed provider-scoped text used for a proactive refresh warning.
///
/// Kept as a pure formatter so redaction tests verify the exact value handed
/// to tracing without installing process-global tracing dispatchers.
pub(super) fn refresh_failure_diagnostic(provider: SubscriptionProvider, message: &str) -> String {
    format!("subscription token refresh for {provider} failed: {message}")
}

/// Fixed provider-scoped text used for a terminal refresh announcement.
pub(super) fn terminal_failure_diagnostic(
    provider: SubscriptionProvider,
    message: &str,
    first_announcement: bool,
) -> String {
    if first_announcement {
        format!("{provider} subscription is unusable and cannot recover on its own: {message}")
    } else {
        format!("{provider} subscription is still unusable: {message}")
    }
}

/// Take the credential's advisory lock or reject the transaction.
async fn acquire_lock(
    store: &Arc<dyn CredentialStore>,
    provider: SubscriptionProvider,
) -> Result<crate::durable_file::FileLockGuard, Rejected> {
    let path = store.lock_path().ok_or_else(|| {
        storage_rejection(format!(
            "the registered {provider} credential store has no durable lock path"
        ))
    })?;
    crate::durable_file::lock_exclusive_async(
        &path,
        crate::credential_recovery_store::CREDENTIAL_LOCK_TIMEOUT,
    )
    .await
    .map_err(|error| {
        let action = if error.kind() == std::io::ErrorKind::WouldBlock {
            "timed out waiting for"
        } else {
            "could not acquire"
        };
        storage_rejection(format!("{action} the durable {provider} credential lock"))
    })
}

/// Write every refreshed credential back before its access token is used.
///
/// Some providers rotate only the access token. That still has to be durable
/// for safe import: promoting the original document after proving its refresh
/// chain would install the stale access token rather than the credential the
/// catalog actually accepted. A failed write rejects the transaction so no
/// refreshed value can escape into memory without a durable replacement.
fn persist_rotation(
    store: &Arc<dyn CredentialStore>,
    baseline: &SubscriptionToken,
    fresh: &SubscriptionToken,
    provider: SubscriptionProvider,
) -> Result<(), Rejected> {
    if crate::credential_store::is_same_link(baseline, fresh) {
        return Ok(());
    }
    if store.persist(fresh).is_err() {
        return Err(storage_rejection(format!(
            "could not durably persist the rotated {provider} credential; the registered \
             primary and recovery storage did not accept it"
        )));
    }
    tracing::info!("persisted a refreshed {provider} credential");
    Ok(())
}

fn require_writable_authority(
    store: &Arc<dyn CredentialStore>,
    token: &SubscriptionToken,
    provider: SubscriptionProvider,
) -> Result<(), Rejected> {
    store.prepare_refresh(token).map_err(|_| {
        storage_rejection(format!(
            "refusing to exchange the {provider} refresh token because its authoritative external store cannot be durably advanced"
        ))
    })
}

/// Secret-free summary of what the endpoint answered.
///
/// By the time the ladder builds a terminal message it has established which
/// advice applies. The raw endpoint body has already been discarded, so this
/// formatter can report only the status, stable class, and safe retry hint.
fn endpoint_answer(error: &RefreshError) -> String {
    match error {
        RefreshError::Status(code, class, retry_after) => format!(
            "the endpoint answered HTTP {code} (class {}{})",
            class.label(),
            retry_after.map_or_else(String::new, |seconds| format!(", retry after {seconds}s"))
        ),
        other => other.to_string(),
    }
}

/// Explain a terminal rejection in terms of the two causes it can have.
///
/// "Waiting will not help, re-authenticate" is only true once we have checked
/// that nobody else moved the chain forward. Saying which check was made, and
/// what it found, is the difference between an actionable message and a
/// misleading one (issue #239).
fn terminal_message(
    provider: SubscriptionProvider,
    error: &RefreshError,
    store: Option<&Arc<dyn CredentialStore>>,
    retried_with_newer_link: bool,
) -> String {
    if !error.is_invalid_grant() {
        return error.to_string();
    }
    if store.is_none() {
        return error.to_string();
    }
    let class = error
        .status_class()
        .map_or("terminal_oauth_error", super::RefreshStatusClass::label);
    if retried_with_newer_link {
        return format!(
            "refresh credential was rejected ({class}): a newer refresh token found in \
             the registered {provider} credential store was rejected as well, so the whole token \
             family has been revoked — re-authenticate this subscription with \
             `link-assistant-router auth {provider}` ({})",
            endpoint_answer(error)
        );
    }
    format!(
        "refresh credential was rejected ({class}): the registered {provider} credential \
         store still holds the same refresh token that was just rejected, so it was revoked or \
         already spent elsewhere rather than rotated past — re-authenticate this subscription \
         with `link-assistant-router auth {provider}` ({})",
        endpoint_answer(error)
    )
}

/// Exchange a refresh token, re-reading and re-trying before concluding the
/// credential is dead. See the module documentation for the ladder.
pub(super) async fn exchange_with_recovery(
    exchange: &Exchange<'_>,
    store: Option<&Arc<dyn CredentialStore>>,
    vendor_cli: Option<&Arc<VendorCli>>,
    base: &SubscriptionToken,
) -> Result<Recovered, Rejected> {
    let &Exchange {
        client,
        token_url,
        provider,
        now_ms,
        mode,
    } = exchange;
    let store = store.ok_or_else(|| {
        storage_rejection(format!(
            "a durable credential store is not registered for {provider}"
        ))
    })?;
    // Held for the whole read → refresh → write cycle so the router never races
    // with another holder and never writes a link older than the one on disk.
    let _lock = acquire_lock(store, provider).await?;

    // Rung 1: the store may already be ahead of the token we were handed.
    let stored = store
        .try_reload()
        .map_err(storage_rejection)?
        .ok_or_else(|| {
            storage_rejection(format!(
                "could not re-read the registered {provider} credential while holding its lock"
            ))
        })?;
    let mut candidate = base.clone();
    let mut from_store = false;
    if !is_same_link(&stored, base) {
        if is_usable(&stored, base, mode, now_ms) {
            tracing::info!(
                "{provider} credential recovery: {}",
                RecoveryRung::AdoptedStoredToken.describe()
            );
            return Ok(Recovered {
                token: stored,
                rung: RecoveryRung::AdoptedStoredToken,
            });
        }
        if has_newer_refresh_link(base, &stored) {
            candidate = stored.clone();
            from_store = true;
        }
    }
    let baseline = stored;

    // Rung 2: exchange the newest link we hold.
    require_writable_authority(store, &candidate, provider)?;
    let error = match refresh_at(client, token_url, provider, &candidate, now_ms).await {
        Ok(fresh) => {
            persist_rotation(store, &baseline, &fresh, provider)?;
            let rung = if from_store {
                RecoveryRung::AdoptedRotatedLink
            } else {
                RecoveryRung::DirectExchange
            };
            if rung.is_recovery() {
                tracing::info!("{provider} credential recovery: {}", rung.describe());
            }
            return Ok(Recovered { token: fresh, rung });
        }
        Err(error) => error,
    };
    if !error.is_invalid_grant() {
        return Err(Rejected {
            message: error.to_string(),
            error,
        });
    }

    // Rung 3: the rotation may have landed on disk while we were exchanging.
    // This is the single check that turns the common case from a mandatory
    // re-login back into a retry.
    let reread = store.try_reload().map_err(storage_rejection)?.ok_or_else(|| {
        storage_rejection(format!(
            "could not re-read the registered {provider} credential after the endpoint rejected it"
        ))
    })?;
    if has_newer_refresh_link(&candidate, &reread) {
        tracing::info!(
            "{provider} rejected a refresh token that the registered credential store has \
             already rotated past; retrying once with the newer one"
        );
        require_writable_authority(store, &reread, provider)?;
        match refresh_at(client, token_url, provider, &reread, now_ms).await {
            Ok(fresh) => {
                persist_rotation(store, &reread, &fresh, provider)?;
                tracing::info!(
                    "{provider} credential recovery: {}",
                    RecoveryRung::AdoptedRotatedLink.describe()
                );
                return Ok(Recovered {
                    token: fresh,
                    rung: RecoveryRung::AdoptedRotatedLink,
                });
            }
            Err(second) => {
                return vendor_cli_or_reject(
                    exchange,
                    store,
                    vendor_cli,
                    second,
                    Tried {
                        base,
                        newest: &reread,
                    },
                    true,
                )
                .await;
            }
        }
    }
    // No newer link, but the store's access token itself may still be usable —
    // another holder refreshed and our own refresh token is simply spent.
    if is_usable(&reread, base, mode, now_ms) {
        tracing::info!(
            "{provider} credential recovery: {}",
            RecoveryRung::AdoptedStoredToken.describe()
        );
        return Ok(Recovered {
            token: reread,
            rung: RecoveryRung::AdoptedStoredToken,
        });
    }
    vendor_cli_or_reject(
        exchange,
        store,
        vendor_cli,
        error,
        Tried {
            base,
            newest: &candidate,
        },
        false,
    )
    .await
}

/// Ask the vendor's own client to rotate the chain before giving up.
///
/// This is the last rung: every direct exchange has been rejected, and the only
/// remaining difference between us and a working client is what the client
/// itself can do. If it leaves a newer credential behind, that credential — or
/// one exchange spent on it — recovers the subscription without an operator
/// touching anything (issue #239).
async fn vendor_cli_or_reject(
    exchange: &Exchange<'_>,
    store: &Arc<dyn CredentialStore>,
    vendor_cli: Option<&Arc<VendorCli>>,
    error: RefreshError,
    tried: Tried<'_>,
    retried_with_newer_link: bool,
) -> Result<Recovered, Rejected> {
    let &Exchange {
        client,
        token_url,
        provider,
        now_ms,
        mode,
    } = exchange;
    let reject = |error: RefreshError| Rejected {
        message: terminal_message(provider, &error, Some(store), retried_with_newer_link),
        error,
    };
    let Some(cli) = vendor_cli else {
        return Err(reject(error));
    };
    // Record our own request shape next to the client's, so that if the vendor
    // client succeeds where we failed, the difference between the two exchanges
    // is readable straight from the journal (issue #239).
    tracing::info!(
        "{provider} credential recovery: the exchange the router sent and that was rejected was {}",
        crate::refresh::direct_exchange_shape(provider)
    );
    let Some(rotated) = cli.rotate(store.as_ref(), tried.newest).await else {
        return Err(reject(error));
    };
    // The client normally leaves a usable access token behind, in which case no
    // exchange of our own is needed at all.
    if is_usable(&rotated, tried.base, mode, now_ms) {
        tracing::info!(
            "{provider} credential recovery: {}",
            RecoveryRung::VendorCliRotation.describe()
        );
        return Ok(Recovered {
            token: rotated,
            rung: RecoveryRung::VendorCliRotation,
        });
    }
    if !has_newer_refresh_link(tried.newest, &rotated) {
        return Err(reject(error));
    }
    require_writable_authority(store, &rotated, provider)?;
    match refresh_at(client, token_url, provider, &rotated, now_ms).await {
        Ok(fresh) => {
            persist_rotation(store, &rotated, &fresh, provider)?;
            tracing::info!(
                "{provider} credential recovery: {}",
                RecoveryRung::VendorCliRotation.describe()
            );
            Ok(Recovered {
                token: fresh,
                rung: RecoveryRung::VendorCliRotation,
            })
        }
        Err(second) => Err(reject(second)),
    }
}

