//! Where each subscription's credential lives, and who else can rotate it.
//!
//! Kept beside [`super::TokenCache`] rather than inside it because these are
//! bookkeeping, not policy: every path that can refresh a token registers what
//! it knows here, and the recovery ladder reads it back (issue #239).

use std::sync::Arc;

use super::{SubscriptionKey, TokenCache};
use crate::credential_recovery_store::RecoverableCredentialStore;
use crate::credential_store::CredentialStore;
use crate::subscription::{SubscriptionProvider, SubscriptionReader};
use crate::vendor_cli_refresh::VendorCli;

impl TokenCache {
    /// Load one credential from its authoritative registered store.
    ///
    /// Recovery-aware stores may reconcile a sidecar into the vendor's primary
    /// document while loading, so this operation takes the store's exact
    /// durable transaction lock. The guard is dropped before this method
    /// returns: callers must never carry it into an OAuth or catalog request.
    pub async fn load_authoritative(
        &self,
        provider: SubscriptionProvider,
        account: &str,
    ) -> Result<Option<crate::subscription::SubscriptionToken>, String> {
        let credential = self
            .reload_registered_store_locked(provider, account)
            .await?;
        // A changed credential is a re-authentication, so verdicts about its
        // predecessor must not keep the account excluded until catalog poll.
        if let Some(token) = credential.as_ref() {
            self.reconcile_authoritative_credential(provider, account, token)
                .await;
        }
        Ok(credential)
    }

    /// Reload the registered store under its durable lock without touching
    /// process-local attempt state.
    ///
    /// The suppression path already holds that attempt's async mutex and must
    /// use this lower-level operation before reconciling through its existing
    /// guard. Calling [`Self::load_authoritative`] there would recursively
    /// acquire the same non-reentrant mutex.
    pub(super) async fn reload_registered_store_locked(
        &self,
        provider: SubscriptionProvider,
        account: &str,
    ) -> Result<Option<crate::subscription::SubscriptionToken>, String> {
        let store = self
            .store_for_subscription(provider, account)
            .ok_or_else(|| format!("no durable {provider} credential store is registered"))?;
        let lock_path = store.lock_path().ok_or_else(|| {
            format!("no durable transaction lock is available for {provider} credentials")
        })?;
        let credential = {
            let _guard = crate::durable_file::lock_exclusive_async(
                &lock_path,
                crate::credential_recovery_store::CREDENTIAL_LOCK_TIMEOUT,
            )
            .await
            .map_err(|error| {
                if error.kind() == std::io::ErrorKind::WouldBlock {
                    format!("timed out waiting for the {provider} credential transaction lock")
                } else {
                    format!("could not acquire the {provider} credential transaction lock")
                }
            })?;
            store
                .try_reload()
                .map_err(|_| format!("the {provider} credential store is unusable"))?
        };
        // The durable guard is gone before this method returns. No network call
        // or process-local async lock is made while it is held.
        Ok(credential)
    }

    /// Register where a subscription's credential lives.
    ///
    /// Every path that can refresh a token registers its store, so a rotation
    /// performed while serving a request is written back exactly as one
    /// performed by catalog polling is, and a rejection can be checked against
    /// the newest credential on disk before it is believed (issue #239).
    pub fn register_store(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        store: Arc<dyn CredentialStore>,
    ) {
        if let Ok(mut guard) = self.stores.lock() {
            guard.insert(key(provider, account), store);
        }
    }

    /// Register a [`SubscriptionReader`] as the credential store for an account.
    pub fn register_reader(&self, account: &str, reader: &SubscriptionReader) {
        self.register_store_if_absent(reader.provider(), account, Arc::new(reader.clone()));
    }

    /// Register every reader under the same account name.
    pub fn register_readers(&self, account: &str, readers: &[SubscriptionReader]) {
        for reader in readers {
            self.register_reader(account, reader);
        }
    }

    /// Register every reader with data-directory-backed durable recovery.
    pub fn register_readers_in(
        &self,
        account: &str,
        readers: &[SubscriptionReader],
        data_dir: &std::path::Path,
    ) {
        for reader in readers {
            let primary: Arc<dyn CredentialStore> = Arc::new(reader.clone());
            let recoverable = Arc::new(RecoverableCredentialStore::new(
                reader.provider(),
                account,
                primary,
                data_dir,
            ));
            self.register_store(reader.provider(), account, recoverable);
        }
    }

    /// Construct a diagnostic cache with the same durable stores as serving.
    #[must_use]
    pub fn registered_for(readers: &[SubscriptionReader], data_dir: &std::path::Path) -> Self {
        let cache = Self::new();
        cache.register_readers_in(
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
            readers,
            data_dir,
        );
        cache.persist_rejections_in(data_dir);
        cache
    }

    fn register_store_if_absent(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        store: Arc<dyn CredentialStore>,
    ) {
        if let Ok(mut guard) = self.stores.lock() {
            guard.entry(key(provider, account)).or_insert(store);
        }
    }

    /// The registered credential store for a subscription, if any.
    #[must_use]
    pub fn store_for_subscription(
        &self,
        provider: SubscriptionProvider,
        account: &str,
    ) -> Option<Arc<dyn CredentialStore>> {
        let guard = self.stores.lock().ok()?;
        guard.get(&key(provider, account)).map(Arc::clone)
    }

    /// Allow the recovery ladder to ask a vendor client to rotate this
    /// subscription's credential once every direct exchange has been rejected.
    ///
    /// Registered only when an operator configured a CLI binary: running a
    /// vendor client is a side effect nobody should get by default.
    pub fn register_vendor_cli(&self, account: &str, cli: Arc<VendorCli>) {
        if let Ok(mut guard) = self.vendor_clis.lock() {
            guard.insert(key(cli.provider(), account), cli);
        }
    }

    /// The vendor client registered for a subscription, if any.
    #[must_use]
    pub fn vendor_cli_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
    ) -> Option<Arc<VendorCli>> {
        let guard = self.vendor_clis.lock().ok()?;
        guard.get(&key(provider, account)).map(Arc::clone)
    }
}

fn key(provider: SubscriptionProvider, account: &str) -> SubscriptionKey {
    (provider, account.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn raw_catalog_registration_does_not_replace_recoverable_registration() {
        let root = tempfile::tempdir().expect("temp root");
        let credential_home = root.path().join("codex-home");
        let data_dir = root.path().join("router-data");
        std::fs::create_dir_all(&credential_home).expect("credential home");
        let reader = SubscriptionReader::new(SubscriptionProvider::Codex, &credential_home);
        let readers = vec![reader.clone()];

        let cache = TokenCache::registered_for(&readers, &data_dir);
        let recovery_lock = cache
            .store_for_subscription(SubscriptionProvider::Codex, "primary")
            .and_then(|store| store.lock_path())
            .expect("recoverable store lock");

        cache.register_reader("primary", &reader);

        assert_eq!(
            cache
                .store_for_subscription(SubscriptionProvider::Codex, "primary")
                .and_then(|store| store.lock_path()),
            Some(recovery_lock.clone())
        );
        assert!(
            recovery_lock.starts_with(data_dir.join("refresh-recovery")),
            "the durable lock must live in router data, not the vendor home"
        );
    }

    #[test]
    fn durable_registration_upgrades_an_existing_raw_catalog_reader() {
        let root = tempfile::tempdir().expect("temp root");
        let credential_home = root.path().join("codex-home");
        let data_dir = root.path().join("router-data");
        std::fs::create_dir_all(&credential_home).expect("credential home");
        let reader = SubscriptionReader::new(SubscriptionProvider::Codex, &credential_home);
        let readers = vec![reader.clone()];
        let cache = TokenCache::new();

        cache.register_reader("primary", &reader);
        let raw_lock = cache
            .store_for_subscription(SubscriptionProvider::Codex, "primary")
            .and_then(|store| store.lock_path())
            .expect("raw reader lock");
        assert!(
            !raw_lock.starts_with(data_dir.join("refresh-recovery")),
            "the setup must begin with a bare reader"
        );

        cache.register_readers_in("primary", &readers, &data_dir);

        let durable_lock = cache
            .store_for_subscription(SubscriptionProvider::Codex, "primary")
            .and_then(|store| store.lock_path())
            .expect("recoverable store lock");
        assert!(
            durable_lock.starts_with(data_dir.join("refresh-recovery")),
            "durable registration left the raw store installed: {durable_lock:?}"
        );
    }
}

use super::{
    CredentialEvidence, Exchange, REFRESH_SKEW_MS, ROTATION_ATTRIBUTION_MS, RecoveryMode, Rejected,
    SubscriptionKey, SubscriptionProvider, SubscriptionToken, TokenCache, exchange_with_recovery,
    refresh_recovery, refresh_state,
};

/// Import errors must classify the failure without echoing token-endpoint
/// bodies, which can contain credential or account material.
fn safe_import_refresh_error(
    provider: SubscriptionProvider,
    error: &super::RefreshError,
) -> super::ImportRefreshFailure {
    let kind = match error {
        super::RefreshError::NoRefreshToken | super::RefreshError::Unsupported => {
            super::ImportRefreshFailureKind::NotAttempted
        }
        error if error.is_invalid_grant() => super::ImportRefreshFailureKind::ExchangeRejected,
        super::RefreshError::Storage(_) => super::ImportRefreshFailureKind::PersistenceUncertain,
        super::RefreshError::Request(_)
        | super::RefreshError::Status(_, _, _)
        | super::RefreshError::Parse(_) => super::ImportRefreshFailureKind::ExchangeUncertain,
    };
    let message = match error {
        super::RefreshError::NoRefreshToken => {
            format!("the {provider} candidate is not refreshable and was not accepted")
        }
        error if error.is_invalid_grant() => {
            let class = error
                .status_class()
                .map_or("terminal_oauth_error", super::RefreshStatusClass::label);
            format!("the {provider} candidate refresh chain was rejected ({class})")
        }
        super::RefreshError::Status(code, _, _) => format!(
            "the {provider} candidate refresh chain was not verified (token endpoint HTTP {code})"
        ),
        super::RefreshError::Request(_) => format!(
            "the {provider} candidate refresh chain was not verified (token endpoint unavailable)"
        ),
        super::RefreshError::Parse(_) => format!(
            "the {provider} candidate refresh chain was not verified (invalid token response)"
        ),
        super::RefreshError::Storage(_) => {
            format!("the {provider} candidate refresh result could not be durably persisted")
        }
        super::RefreshError::Unsupported => {
            format!("the {provider} candidate refresh chain cannot be validated")
        }
    };
    super::ImportRefreshFailure::new(kind, message)
}

impl TokenCache {
    /// Create an empty cache.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Return a non-expired token for `provider`, refreshing if needed.
    ///
    /// Resolution order:
    /// 1. If the on-disk token is still valid, use it (the vendor CLI may have
    ///    refreshed it more recently than our cache).
    /// 2. Otherwise reuse a cached refreshed token while it remains valid.
    /// 3. Otherwise exchange the refresh token and cache the result.
    ///
    /// On refresh failure the (expired) disk token is returned unchanged so the
    /// caller can still attempt the upstream call and surface its error.
    pub async fn get_fresh(
        &self,
        client: &reqwest::Client,
        provider: SubscriptionProvider,
        disk_token: SubscriptionToken,
        now_ms: i64,
    ) -> SubscriptionToken {
        self.get_fresh_for(
            client,
            provider,
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
            disk_token,
            now_ms,
        )
        .await
    }

    /// Account-scoped variant of [`Self::get_fresh`].
    pub async fn get_fresh_for(
        &self,
        client: &reqwest::Client,
        provider: SubscriptionProvider,
        account: &str,
        disk_token: SubscriptionToken,
        now_ms: i64,
    ) -> SubscriptionToken {
        let token_url = super::refresh_token_url(provider);
        self.get_fresh_for_at(client, &token_url, provider, account, disk_token, now_ms)
            .await
    }

    /// Load one registered credential authoritatively, then refresh it if
    /// necessary after releasing the durable load lock.
    ///
    /// Unlike [`Self::get_fresh_for`], storage uncertainty is returned to the
    /// caller instead of being collapsed into a caller-provided fallback.
    pub async fn get_fresh_registered(
        &self,
        client: &reqwest::Client,
        provider: SubscriptionProvider,
        account: &str,
        now_ms: i64,
    ) -> Result<SubscriptionToken, String> {
        let token_url = super::refresh_token_url(provider);
        self.get_fresh_registered_at(client, &token_url, provider, account, now_ms)
            .await
    }

    /// Prove that a registered credential's refresh chain can advance.
    ///
    /// Unlike ordinary pre-flight refresh, this always exchanges the refresh
    /// token even when the current access token is still live. It uses only the
    /// direct OAuth recovery rungs, persists the complete result through the
    /// registered durable store, and returns no token until that persistence
    /// succeeds. Credential import uses this against an isolated candidate
    /// store so a stale refresh link can never replace a working destination
    /// merely because its access token still passes a catalog probe (#385).
    pub async fn validate_refresh_chain_registered(
        &self,
        client: &reqwest::Client,
        provider: SubscriptionProvider,
        account: &str,
        now_ms: i64,
    ) -> Result<SubscriptionToken, String> {
        self.validate_refresh_chain_registered_classified(client, provider, account, now_ms)
            .await
            .map_err(|error| error.to_string())
    }

    /// Classified variant used by machine-readable credential import.
    pub async fn validate_refresh_chain_registered_classified(
        &self,
        client: &reqwest::Client,
        provider: SubscriptionProvider,
        account: &str,
        now_ms: i64,
    ) -> Result<SubscriptionToken, super::ImportRefreshFailure> {
        let token_url = super::refresh_token_url(provider);
        self.validate_refresh_chain_registered_at_classified(
            client, &token_url, provider, account, now_ms,
        )
        .await
    }

    /// Endpoint-overridable variant used by end-to-end import tests.
    #[doc(hidden)]
    pub async fn validate_refresh_chain_registered_at(
        &self,
        client: &reqwest::Client,
        token_url: &str,
        provider: SubscriptionProvider,
        account: &str,
        now_ms: i64,
    ) -> Result<SubscriptionToken, String> {
        self.validate_refresh_chain_registered_at_classified(
            client, token_url, provider, account, now_ms,
        )
        .await
        .map_err(|error| error.to_string())
    }

    /// Endpoint-overridable classified variant used by import contract tests.
    #[doc(hidden)]
    pub async fn validate_refresh_chain_registered_at_classified(
        &self,
        client: &reqwest::Client,
        token_url: &str,
        provider: SubscriptionProvider,
        account: &str,
        now_ms: i64,
    ) -> Result<SubscriptionToken, super::ImportRefreshFailure> {
        let not_attempted = |message| {
            super::ImportRefreshFailure::new(super::ImportRefreshFailureKind::NotAttempted, message)
        };
        let persistence_uncertain = |message| {
            super::ImportRefreshFailure::new(
                super::ImportRefreshFailureKind::PersistenceUncertain,
                message,
            )
        };
        let baseline = self
            .load_authoritative(provider, account)
            .await
            .map_err(not_attempted)?
            .ok_or_else(|| {
                not_attempted(format!("the {provider} candidate credential is absent"))
            })?;
        if baseline.refresh_token.as_deref().is_none_or(str::is_empty) {
            return Err(not_attempted(format!(
                "the {provider} candidate is not refreshable and was not accepted"
            )));
        }
        let attempt = self.attempts.for_subscription(provider, account, &baseline);
        let mut attempt = attempt.lock().await;
        if attempt.reset_if_changed(provider, &baseline) {
            self.forget(&(provider, account.to_string()), provider);
        }
        let store = self
            .store_for_subscription(provider, account)
            .ok_or_else(|| {
                not_attempted(format!(
                    "no durable {provider} candidate store is registered"
                ))
            })?;
        let exchange = Exchange {
            client,
            token_url,
            provider,
            now_ms,
            mode: RecoveryMode::ImportValidation,
        };
        let fresh = exchange_with_recovery(&exchange, Some(&store), None, &baseline)
            .await
            .map_err(|rejection| safe_import_refresh_error(provider, &rejection.error))?
            .token;
        self.accept(&mut attempt, provider, account, &fresh, Some(now_ms));
        drop(attempt);

        // Reread what was durably committed rather than trusting the exchange's
        // in-memory return value. This is the credential later catalog-tested
        // and promoted.
        let durable = self
            .load_authoritative(provider, account)
            .await
            .map_err(persistence_uncertain)?
            .ok_or_else(|| {
                persistence_uncertain(format!(
                    "the durable {provider} candidate disappeared after refresh"
                ))
            })?;
        if fresh.access_token != durable.access_token
            || fresh.refresh_token != durable.refresh_token
        {
            return Err(persistence_uncertain(format!(
                "the durable {provider} candidate did not retain the validated refresh result"
            )));
        }
        Ok(durable)
    }

    /// Testable token-endpoint variant of [`Self::get_fresh_registered`].
    ///
    /// The registered durable store remains authoritative; only the remote
    /// endpoint is replaceable so diagnostics can exercise real transaction
    /// failures without contacting a vendor.
    pub(crate) async fn get_fresh_registered_at(
        &self,
        client: &reqwest::Client,
        token_url: &str,
        provider: SubscriptionProvider,
        account: &str,
        now_ms: i64,
    ) -> Result<SubscriptionToken, String> {
        let disk_token = self
            .load_authoritative(provider, account)
            .await?
            .ok_or_else(|| {
                format!("failed to load {provider} credentials from the registered store")
            })?;
        self.get_fresh_for_at_checked(client, token_url, provider, account, disk_token, now_ms)
            .await
    }

    /// Refresh a baseline that was just returned by [`Self::load_authoritative`].
    ///
    /// This avoids a redundant second locked reload while preserving the rule
    /// that no caller-provided raw credential can bypass the registered store.
    pub(crate) async fn get_fresh_loaded(
        &self,
        client: &reqwest::Client,
        provider: SubscriptionProvider,
        account: &str,
        disk_token: SubscriptionToken,
        now_ms: i64,
    ) -> Result<SubscriptionToken, String> {
        let token_url = super::refresh_token_url(provider);
        self.get_fresh_for_at_checked(client, &token_url, provider, account, disk_token, now_ms)
            .await
    }

    /// Refresh regardless of what the token's own `exp` claim says.
    ///
    /// A vendor may invalidate an access token *before* its stated expiry —
    /// a plan change, a session reset — and answers `401` to a token whose
    /// `exp` is still days away (issue #205). `exp` is therefore only ever an
    /// optimisation for refreshing early; a `401` from the resource endpoint
    /// is the authority on whether a token is actually accepted.
    ///
    /// Returns `None` when no fresher token could be obtained, so a caller can
    /// tell "retry with this" from "there is nothing new to retry with" and
    /// avoid replaying a request with the credential that just failed.
    pub async fn refresh_rejected(
        &self,
        client: &reqwest::Client,
        provider: SubscriptionProvider,
        account: &str,
        disk_token: SubscriptionToken,
        now_ms: i64,
    ) -> Option<SubscriptionToken> {
        let token_url = super::refresh_token_url(provider);
        self.refresh_rejected_at(client, &token_url, provider, account, disk_token, now_ms)
            .await
    }

    pub(crate) async fn refresh_rejected_at(
        &self,
        client: &reqwest::Client,
        token_url: &str,
        provider: SubscriptionProvider,
        account: &str,
        rejected: SubscriptionToken,
        now_ms: i64,
    ) -> Option<SubscriptionToken> {
        let attempt = self.attempts.for_subscription(provider, account, &rejected);
        // The same lock the pre-flight path uses, so concurrent 401s share one
        // exchange instead of each spending the refresh token.
        let mut attempt = attempt.lock().await;

        // A concurrent caller may have refreshed while we waited for the lock.
        // Anything that differs from the token just rejected is worth retrying.
        if let Some(cached) = self.cached_valid_for(provider, account, now_ms)
            && cached.access_token != rejected.access_token
        {
            return Some(cached);
        }
        // A credential this process rotated into moments ago is not evidence
        // of anything yet. Refreshing it spends the only good link of a
        // single-use chain against a verdict that was never about the token
        // (issue #319).
        if let Some(age_ms) = attempt.rotated_within(now_ms, refresh_state::ROTATION_GRACE_MS) {
            tracing::warn!(
                "not refreshing the {provider} credential: this process rotated into it \
                 {}s ago and a refresh chain is single-use, so spending it again would \
                 destroy a token that was known good; retrying the existing one",
                age_ms / 1_000
            );
            return None;
        }
        let base = match self
            .unsuppressed_base(&mut attempt, provider, account, rejected.clone(), now_ms)
            .await
        {
            Ok(Some(base)) => base,
            Ok(None) => return None,
            Err(error) => {
                self.record_refresh_error_for(provider, account, &error);
                return None;
            }
        };
        let exchange = Exchange {
            client,
            token_url,
            provider,
            now_ms,
            mode: RecoveryMode::AfterRejection,
        };
        let result = match self.climb(&exchange, account, &base).await {
            Ok(fresh) => {
                self.accept(&mut attempt, provider, account, &fresh, Some(now_ms));
                // A refresh that returned the same access token has not
                // recovered anything; replaying would just repeat the 401.
                (fresh.access_token != rejected.access_token).then_some(fresh)
            }
            Err(rejection) => {
                // When this process performed the previous rotation, say so.
                // "revoked or already spent elsewhere" sends the operator
                // looking for an external holder that may not exist, while the
                // fatal spend is recorded right here (issue #319).
                let message = attempt
                    .rotated_within(now_ms, ROTATION_ATTRIBUTION_MS)
                    .map_or_else(
                        || rejection.message.clone(),
                        |age_ms| {
                            format!(
                                "{} — note: this process rotated into that refresh token {}s ago, \
                             so it was spent here rather than by another holder",
                                rejection.message,
                                age_ms / 1_000
                            )
                        },
                    );
                let rejection = Rejected {
                    message,
                    ..rejection
                };
                self.record_refresh_error_for(provider, account, &rejection.message);
                if rejection.error.is_invalid_grant() {
                    // healthy -> permanently unauthenticated is a state
                    // transition that needs a human in a browser and will not
                    // self-heal. Logged at WARN it sat below every sane
                    // `level>=ERROR` pipeline, so a twelve-hour outage produced
                    // a clean log (issue #321).
                    self.log_terminal_once_for(provider, account, &rejection.message);
                    attempt.record_terminal_failure();
                    self.record_credential_rejected_for(provider, account);
                    // Per account as well as per provider: the provider-wide
                    // verdict cannot say *which* account of a pool is dead,
                    // and `accounts list` reports one row each (issue #245).
                    self.record_refresh_refused(provider, account, &base);
                } else {
                    tracing::warn!(
                        "refresh after a rejected {provider} token failed: {}",
                        rejection.message
                    );
                    attempt
                        .record_transient_failure_after(now_ms, rejection.error.retry_after_ms());
                }
                None
            }
        };
        drop(attempt);
        result
    }

    pub(super) async fn get_fresh_for_at(
        &self,
        client: &reqwest::Client,
        token_url: &str,
        provider: SubscriptionProvider,
        account: &str,
        disk_token: SubscriptionToken,
        now_ms: i64,
    ) -> SubscriptionToken {
        let fallback = disk_token.clone();
        match self
            .get_fresh_for_at_checked(client, token_url, provider, account, disk_token, now_ms)
            .await
        {
            Ok(token) => token,
            Err(error) => {
                self.record_refresh_error_for(provider, account, &error);
                fallback
            }
        }
    }

    async fn get_fresh_for_at_checked(
        &self,
        client: &reqwest::Client,
        token_url: &str,
        provider: SubscriptionProvider,
        account: &str,
        disk_token: SubscriptionToken,
        now_ms: i64,
    ) -> Result<SubscriptionToken, String> {
        let key = (provider, account.to_string());
        let attempt = self
            .attempts
            .for_subscription(provider, account, &disk_token);
        let mut attempt = attempt.lock().await;

        // Re-authentication replaces at least one credential field. Forget
        // both negative and positive state derived from the previous file.
        if attempt.reset_if_changed(provider, &disk_token) {
            self.forget(&key, provider);
        }
        // Refresh slightly *before* expiry rather than after a request has
        // already failed: a token that expires mid-flight surfaces to the
        // caller as an upstream error, and a credential only ever refreshed
        // reactively can sit unused past its refresh window (issue #203).
        if !disk_token.is_expired(now_ms.saturating_add(REFRESH_SKEW_MS)) {
            return Ok(disk_token);
        }
        if let Some(cached) = self.cached_valid_for(provider, account, now_ms) {
            return Ok(cached);
        }
        let Some(base) = self
            .unsuppressed_base(&mut attempt, provider, account, disk_token.clone(), now_ms)
            .await?
        else {
            return Ok(disk_token);
        };
        if !base.is_expired(now_ms.saturating_add(REFRESH_SKEW_MS)) {
            // The store was already ahead of the token we were handed; there is
            // nothing to exchange.
            self.accept(&mut attempt, provider, account, &base, None);
            return Ok(base);
        }
        let exchange = Exchange {
            client,
            token_url,
            provider,
            now_ms,
            mode: RecoveryMode::Proactive,
        };
        match self.climb(&exchange, account, &base).await {
            Ok(fresh) => {
                self.accept(&mut attempt, provider, account, &fresh, Some(now_ms));
                drop(attempt);
                Ok(fresh)
            }
            Err(rejection) => {
                self.record_refresh_error_for(provider, account, &rejection.message);
                if rejection.error.is_invalid_grant() {
                    self.log_terminal_once_for(provider, account, &rejection.message);
                    attempt.record_terminal_failure();
                    self.record_credential_rejected_for(provider, account);
                    self.record_refresh_refused(provider, account, &base);
                } else {
                    tracing::warn!(
                        "{}",
                        refresh_recovery::refresh_failure_diagnostic(provider, &rejection.message)
                    );
                    // Everything else is retryable. In particular a 429 must
                    // not record rejection evidence: the credential is fine,
                    // and marking it rejected would drop the provider out of
                    // routing until restart (issue #203).
                    attempt
                        .record_transient_failure_after(now_ms, rejection.error.retry_after_ms());
                }
                drop(attempt);
                // The stamped-expired token is returned unchanged on purpose:
                // it may still be honoured by the inference endpoint.
                Ok(disk_token)
            }
        }
    }

    /// Run the recovery ladder for one subscription.
    async fn climb(
        &self,
        exchange: &Exchange<'_>,
        account: &str,
        base: &SubscriptionToken,
    ) -> Result<SubscriptionToken, refresh_recovery::Rejected> {
        let provider = exchange.provider;
        let store = self.store_for_subscription(provider, account);
        let vendor_cli = self.vendor_cli_for(provider, account);
        exchange_with_recovery(exchange, store.as_ref(), vendor_cli.as_ref(), base)
            .await
            .map(|recovered| {
                if let Ok(mut guard) = self.recoveries.lock() {
                    guard.insert(provider, recovered.rung.describe());
                }
                recovered.token
            })
    }

    /// How `provider`'s credential was last resolved, in the operator's terms.
    #[must_use]
    pub fn last_recovery(&self, provider: SubscriptionProvider) -> Option<&'static str> {
        self.recoveries
            .lock()
            .ok()
            .and_then(|guard| guard.get(&provider).copied())
    }

    /// The credential to exchange, or `None` when a cached failure still
    /// suppresses this subscription.
    ///
    /// A suppressed subscription is not simply skipped: the terminal verdict was
    /// reached about *one* chain link, and another holder may have rotated the
    /// chain forward since. Re-reading the store before honouring the
    /// suppression is what stops a single `invalid_grant` from disabling the
    /// subscription until someone re-authenticates by hand (issue #239).
    async fn unsuppressed_base(
        &self,
        attempt: &mut refresh_state::RefreshAttempt,
        provider: SubscriptionProvider,
        account: &str,
        held: SubscriptionToken,
        now_ms: i64,
    ) -> Result<Option<SubscriptionToken>, String> {
        if !attempt.suppresses_attempt(now_ms) {
            return Ok(Some(held));
        }
        let stored = self
            .reload_registered_store_locked(provider, account)
            .await?
            .ok_or_else(|| {
                format!("failed to load {provider} credentials from the registered store")
            })?;
        if !attempt.reset_if_changed(provider, &stored) {
            return Ok(None);
        }
        tracing::info!(
            "the {provider} credential on disk changed since it was last rejected; retrying with \
             it instead of waiting for a manual re-authentication"
        );
        self.forget(&(provider, account.to_string()), provider);
        Ok(Some(stored))
    }

    /// Record a successful resolution: cache the token and clear failure state.
    fn accept(
        &self,
        attempt: &mut refresh_state::RefreshAttempt,
        provider: SubscriptionProvider,
        account: &str,
        token: &SubscriptionToken,
        rotated_at_ms: Option<i64>,
    ) {
        // Remember that *this* process minted the credential, and when. A
        // single-use chain must not be spent again moments later on evidence
        // that is not about the credential, and a chain that does die deserves
        // to be reported as spent here rather than blamed on another holder
        // (issue #319). `None` means the credential was adopted rather than
        // exchanged, so no link was spent and no grace period is owed.
        if let Some(now_ms) = rotated_at_ms {
            // The fingerprint moves to the token we just minted, because the
            // ladder has already written it to the file the next caller reads.
            // Leaving it behind is what let a rotation this process performed
            // look like a re-authentication (issue #319).
            attempt.record_rotation(provider, now_ms, token);
        }
        self.store_for(provider, account, token.clone());
        attempt.record_success();
        self.record_credential_working_for(provider, account);
        if let Ok(mut guard) = self.refresh_errors.lock() {
            guard.remove(&(provider, account.to_string()));
        }
        // A refresh that succeeded settles the question for this account: any
        // earlier refusal was about a link the chain has since moved past.
        self.rejections.clear(provider, account);
    }

    /// Drop cached state derived from a credential that has been replaced.
    pub(super) fn forget(&self, key: &SubscriptionKey, provider: SubscriptionProvider) {
        if let Ok(mut guard) = self.inner.lock() {
            guard.remove(key);
        }
        if let Ok(mut guard) = self.evidence.lock() {
            guard.remove(key);
        }
        if let Ok(mut guard) = self.refresh_errors.lock() {
            guard.remove(key);
        }
        self.rejections.clear(provider, &key.1);
        self.clear_terminal_announcement_for(provider, &key.1);
    }

    /// Clear verdicts derived from a credential that an authoritative reload
    /// proves has been replaced.
    pub(super) async fn reconcile_authoritative_credential(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
    ) {
        let key = (provider, account.to_string());
        let attempt = self
            .attempts
            .for_subscription(provider, account, credential);
        if attempt.lock().await.reset_if_changed(provider, credential) {
            self.forget(&key, provider);
        }
    }

    /// Record that an upstream call succeeded with `provider`'s credential.
    pub fn record_credential_working(&self, provider: SubscriptionProvider) {
        self.record_credential_working_for(
            provider,
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
        );
    }

    /// Record that one stable router account served successfully.
    pub fn record_credential_working_for(&self, provider: SubscriptionProvider, account: &str) {
        self.record_evidence_for(provider, account, CredentialEvidence::Working);
        // A provider that is serving again may die again, and that death is a
        // new event that must be announced (issue #321).
        self.clear_terminal_announcement_for(provider, account);
    }
    pub(super) fn cached_valid_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        now_ms: i64,
    ) -> Option<SubscriptionToken> {
        let guard = self.inner.lock().ok()?;
        guard
            .get(&(provider, account.to_string()))
            .filter(|token| !token.is_expired(now_ms))
            .cloned()
    }

    pub(super) fn store_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        token: SubscriptionToken,
    ) {
        if let Ok(mut guard) = self.inner.lock() {
            guard.insert((provider, account.to_string()), token);
        }
    }
}

#[cfg(test)]
mod import_error_tests {
    use super::*;

    /// Safe-import failures describe the class of failure without echoing an
    /// endpoint body or storage detail that may contain credential material.
    #[test]
    fn import_refresh_errors_are_complete_and_secret_free() {
        let cases = [
            (
                super::super::RefreshError::NoRefreshToken,
                super::super::ImportRefreshFailureKind::NotAttempted,
            ),
            (
                super::super::RefreshError::from_status(
                    400,
                    r#"{"error":"invalid_grant","secret":"must-not-leak"}"#,
                    None,
                ),
                super::super::ImportRefreshFailureKind::ExchangeRejected,
            ),
            (
                super::super::RefreshError::from_status(503, "upstream body must-not-leak", None),
                super::super::ImportRefreshFailureKind::ExchangeUncertain,
            ),
            (
                super::super::RefreshError::Request("request detail must-not-leak".into()),
                super::super::ImportRefreshFailureKind::ExchangeUncertain,
            ),
            (
                super::super::RefreshError::Parse("parse detail must-not-leak".into()),
                super::super::ImportRefreshFailureKind::ExchangeUncertain,
            ),
            (
                super::super::RefreshError::Storage("storage detail must-not-leak".into()),
                super::super::ImportRefreshFailureKind::PersistenceUncertain,
            ),
            (
                super::super::RefreshError::Unsupported,
                super::super::ImportRefreshFailureKind::NotAttempted,
            ),
        ];

        for (error, expected) in cases {
            let failure = safe_import_refresh_error(SubscriptionProvider::Claude, &error);
            let message = failure.to_string();
            assert_eq!(failure.kind(), expected, "{message}");
            assert!(message.contains("claude"), "{message}");
            assert!(!message.contains("must-not-leak"), "{message}");
        }
    }
}

//! What upstream responses say about a subscription's credential.
//!
//! Split from `refresh.rs` to stay inside the per-file line limit. This is the
//! evidence `/api/management/health/subscriptions`, `/api/management/metrics`
//! and `model_routing` all read
//! (issues #318, #319).

use super::{CredentialEvidence, SubscriptionProvider, SubscriptionToken, TokenCache};

impl TokenCache {
    /// Announce a terminal credential failure once, at `ERROR`.
    ///
    /// A router that cannot serve a configured subscription, and cannot fix it
    /// without a human in a browser, is in an error state by any definition.
    /// Logged at `WARN` it sat below every ordinary `level>=ERROR` pipeline,
    /// so a twelve-hour outage produced a log with zero errors in it, and the
    /// one meaningful line was buried under 146 repetitions of its consequence
    /// (issue #321).
    ///
    /// Repeats are suppressed until the provider recovers, because the
    /// condition is already known and restating it hides new events.
    pub(super) fn log_terminal_once_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        message: &str,
    ) {
        let first = self.take_terminal_announcement_for(provider, account);
        let diagnostic =
            super::refresh_recovery::terminal_failure_diagnostic(provider, message, first);
        if first {
            tracing::error!("{diagnostic}");
        } else {
            tracing::debug!("{diagnostic}");
        }
    }

    /// Claim the right to announce this provider's terminal failure.
    ///
    /// True exactly once per outage, so the transition is reported and its
    /// restatements are not.
    #[cfg(test)]
    pub(super) fn take_terminal_announcement(&self, provider: SubscriptionProvider) -> bool {
        self.take_terminal_announcement_for(
            provider,
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
        )
    }

    pub(super) fn take_terminal_announcement_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
    ) -> bool {
        self.announced_terminal
            .lock()
            .is_ok_and(|mut guard| guard.insert((provider, account.to_string())))
    }

    /// Forget that a provider's terminal failure was announced, so a later one
    /// is reported again.
    pub(super) fn clear_terminal_announcement_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
    ) {
        if let Ok(mut guard) = self.announced_terminal.lock() {
            guard.remove(&(provider, account.to_string()));
        }
    }

    /// Record what an upstream status code says about `provider`'s credential.
    ///
    /// This is the evidence [`crate::model_routing::healthy_providers`] trusts
    /// over `expiresAt`: a served request proves the credential works even when
    /// its timestamp says otherwise, and only a 401/403 proves it does not.
    /// Every other status describes the request, not the credential.
    pub fn record_status(&self, provider: SubscriptionProvider, status: u16) {
        self.record_status_for(
            provider,
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
            status,
        );
    }

    /// Record one upstream verdict for one stable router account.
    pub fn record_status_for(&self, provider: SubscriptionProvider, account: &str, status: u16) {
        if status == 401 || status == 403 {
            self.record_credential_rejected_for(provider, account);
            // The third producer of the same state, and the one that was
            // silent. A credential rejected while serving a request makes the
            // provider unusable exactly as a rejected refresh does (#321).
            self.announce_unusable_for(
                provider,
                account,
                &format!("an upstream request was refused with HTTP {status}"),
            );
        } else if (200..300).contains(&status) {
            self.record_credential_working_for(provider, account);
        }
    }

    /// Record an inference verdict only while it still describes the current
    /// credential generation for this stable router account.
    ///
    /// Selection and the upstream call happen before this method. The only
    /// guard acquired here is the per-account refresh-attempt mutex, after the
    /// network response exists; no durable credential/store lock or network
    /// operation overlaps it. Reconciliation uses the same mutex, so either an
    /// old response commits first and replacement clears it, or replacement
    /// wins first and the stale response is ignored atomically.
    pub(crate) async fn record_status_for_credential(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
        status: u16,
    ) {
        let attempt = self
            .attempts
            .for_subscription(provider, account, credential);
        let attempt = attempt.lock().await;
        if attempt.matches_current(provider, credential) {
            self.record_status_for(provider, account, status);
        }
    }

    /// Record that an upstream rejected `provider`'s credential (401/403).
    /// Announce that a provider became unusable, whichever path discovered it.
    ///
    /// `Rejected` is the single state that drives
    /// `/api/management/health/subscriptions` to
    /// 503, the `/metrics` gauge to 0, and removal from routing. It was set
    /// from three places at three severities — once at `ERROR`, once at
    /// `WARN`, and once silently — so a subscription revoked between refresh
    /// ticks produced a 503 with no error line anywhere, which is the outage
    /// shape issue #321 exists to prevent.
    pub(crate) fn announce_unusable_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        reason: &str,
    ) {
        self.log_terminal_once_for(provider, account, reason);
    }

    pub fn record_credential_rejected(&self, provider: SubscriptionProvider) {
        self.record_credential_rejected_for(
            provider,
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
        );
    }

    /// Record a rejected credential for one stable router account.
    pub fn record_credential_rejected_for(&self, provider: SubscriptionProvider, account: &str) {
        self.record_evidence_for(provider, account, CredentialEvidence::Rejected);
    }

    /// Record that a refresh for `account` was refused for `credential` itself.
    ///
    /// The evidence recorded alongside this is per *provider*, which is right
    /// for routing a vendor away but wrong for reporting one account of a pool:
    /// several accounts share a provider, and one revoked chain must not make
    /// its healthy neighbours look revoked too (issue #245).
    pub fn record_refresh_refused(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
    ) {
        self.rejections.record(provider, account, credential);
    }

    /// Persist refusals in `data_dir`, so a later process can read them.
    pub fn persist_rejections_in(&self, data_dir: &std::path::Path) {
        self.rejections.persist_in(data_dir);
    }

    /// Whether a refresh has already been refused for exactly this credential.
    ///
    /// `false` once the file on disk differs from the one that was refused: a
    /// rejection is a fact about one chain link, not about the account, so a
    /// credential rotated forward by another holder is reported as recoverable
    /// again with no restart (issue #239).
    #[must_use]
    pub fn refresh_was_refused(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
    ) -> bool {
        self.rejections.was_refused(provider, account, credential)
    }

    /// The most recent upstream verdict for `provider`, if any call was made.
    #[must_use]
    pub fn evidence(&self, provider: SubscriptionProvider) -> Option<CredentialEvidence> {
        self.evidence_for(provider, crate::credential_recovery_store::PRIMARY_ACCOUNT)
    }

    /// The most recent upstream verdict for one stable router account.
    #[must_use]
    pub fn evidence_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
    ) -> Option<CredentialEvidence> {
        self.evidence
            .lock()
            .ok()
            .and_then(|guard| guard.get(&(provider, account.to_string())).copied())
    }

    /// The most recent refresh failure for `provider`, if the last attempt failed.
    #[must_use]
    pub fn last_refresh_error(&self, provider: SubscriptionProvider) -> Option<String> {
        self.last_refresh_error_for(provider, crate::credential_recovery_store::PRIMARY_ACCOUNT)
    }

    /// The most recent refresh failure for one stable router account.
    #[must_use]
    pub fn last_refresh_error_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
    ) -> Option<String> {
        self.refresh_errors
            .lock()
            .ok()
            .and_then(|guard| guard.get(&(provider, account.to_string())).cloned())
    }

    pub(super) fn record_evidence_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        evidence: CredentialEvidence,
    ) {
        if let Ok(mut guard) = self.evidence.lock() {
            guard.insert((provider, account.to_string()), evidence);
        }
    }

    #[cfg(test)]
    pub(super) fn record_refresh_error(&self, provider: SubscriptionProvider, error: &str) {
        self.record_refresh_error_for(
            provider,
            crate::credential_recovery_store::PRIMARY_ACCOUNT,
            error,
        );
    }

    pub(super) fn record_refresh_error_for(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        error: &str,
    ) {
        if let Ok(mut guard) = self.refresh_errors.lock() {
            guard.insert((provider, account.to_string()), error.to_string());
        }
    }

    /// Seed the cache with an already-refreshed token for `provider`/`account`.
    ///
    /// Used by callers that obtained a token outside [`Self::get_fresh_for`]
    /// (and by tests) so a subsequent lookup reuses it instead of exchanging
    /// the refresh token again.
    pub fn store_refreshed(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        token: SubscriptionToken,
    ) {
        self.store_for(provider, account, token);
    }
}

//! Which credentials a refresh has already been refused for, across restarts.
//!
//! The in-memory record answers this for a running router, but `accounts list`
//! is a separate short-lived process: it has performed no refresh, so it had
//! nothing to consult and reported a revoked chain as `refreshable` — the
//! contradiction issue #245 was filed about, in the very command it reproduced
//! with.
//!
//! Only a SHA-256 fingerprint of the credential is written, never the token.
//! That is also what makes the record expire correctly: once a holder rotates
//! the chain forward the file no longer matches, the verdict stops applying,
//! and the account reports recoverable again with no restart and no manual
//! step — the same "re-read the store before concluding" rule the refresh
//! ladder already follows (issue #239).

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::subscription::{SubscriptionProvider, SubscriptionToken};

/// Hex-encoded fingerprint of a credential's contents.
///
/// The fingerprint, never the token: a file that outlives the process must not
/// carry a secret, and a hash is all the identity a "has this exact chain link
/// been refused?" question needs (issue #245).
fn fingerprint_hex(credential: &SubscriptionToken) -> String {
    crate::refresh::credential_fingerprint(credential)
        .iter()
        .fold(String::with_capacity(64), |mut out, byte| {
            use std::fmt::Write as _;
            let _ = write!(out, "{byte:02x}");
            out
        })
}

/// File name inside the router's data directory.
pub const REJECTIONS_FILE_NAME: &str = "refresh-rejections.lino";

/// Fingerprints of refused credentials, keyed by `<provider>/<account>`.
#[derive(Debug, Default, Clone, Deserialize, Serialize)]
struct RejectionFile {
    /// Hex-encoded SHA-256 of the credential that was refused.
    #[serde(default)]
    refused: BTreeMap<String, String>,
}

/// A durable record of terminal refresh refusals.
#[derive(Debug, Clone)]
pub struct RejectionStore {
    path: PathBuf,
}

impl RejectionStore {
    /// Open the store kept in `data_dir`.
    #[must_use]
    pub fn open(data_dir: &Path) -> Self {
        Self {
            path: data_dir.join(REJECTIONS_FILE_NAME),
        }
    }

    /// Record that a refresh was refused for exactly `credential`.
    ///
    /// A store that cannot be written is not an error worth failing a request
    /// over: the in-memory record still holds for this process, and the next
    /// write may succeed. It is logged rather than propagated.
    pub fn record(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
    ) {
        let mut file = self.load();
        file.refused
            .insert(Self::key(provider, account), fingerprint_hex(credential));
        if let Err(error) = self.save(&file) {
            tracing::warn!(
                "could not record the refused {provider} credential for {account}: {error}"
            );
        }
    }

    /// Forget any refusal recorded for `account`, after a refresh succeeded.
    pub fn clear(&self, provider: SubscriptionProvider, account: &str) {
        let mut file = self.load();
        if file.refused.remove(&Self::key(provider, account)).is_none() {
            return;
        }
        if let Err(error) = self.save(&file) {
            tracing::warn!("could not clear the {provider} refusal for {account}: {error}");
        }
    }

    /// Whether a refresh has already been refused for exactly this credential.
    #[must_use]
    pub fn was_refused(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
    ) -> bool {
        let fingerprint = fingerprint_hex(credential);
        self.load()
            .refused
            .get(&Self::key(provider, account))
            .is_some_and(|recorded| *recorded == fingerprint)
    }

    /// Read on every call rather than cached: a running router writes this file
    /// while the CLI reads it, and a cached copy would answer with what was
    /// true when the process started — the staleness this store exists to end.
    fn load(&self) -> RejectionFile {
        std::fs::read_to_string(&self.path)
            .ok()
            .and_then(|raw| crate::lino_json::decode::<RejectionFile>(&raw).ok())
            .unwrap_or_default()
    }

    fn save(&self, file: &RejectionFile) -> Result<(), Box<dyn std::error::Error>> {
        if let Some(parent) = self.path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let encoded = crate::lino_json::encode(file)?;
        let temporary = self
            .path
            .with_extension(format!("tmp-{}", uuid::Uuid::new_v4()));
        // Owner-only, like every sibling in the data directory. This file
        // carries fingerprints rather than secrets, but a record of which
        // accounts are dead is still an operator's business alone, and a file
        // whose permissions differ from its neighbours invites the question of
        // why.
        let mut options = std::fs::OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;
            options.mode(0o600);
        }
        {
            use std::io::Write as _;
            let mut handle = options.open(&temporary)?;
            handle.write_all(encoded.as_bytes())?;
            handle.write_all(b"\n")?;
            handle.sync_all()?;
        }
        std::fs::rename(&temporary, &self.path)?;
        Ok(())
    }

    fn key(provider: SubscriptionProvider, account: &str) -> String {
        format!("{provider}/{account}")
    }
}

/// In-memory refusals plus their durable mirror.
///
/// One type so callers cannot consult one and forget the other: the running
/// router needs the fast in-process answer, and `accounts list` — a separate
/// short-lived process — needs the recorded one (issue #245).
#[derive(Debug, Default)]
pub struct RejectionRecord {
    remembered:
        std::sync::Mutex<std::collections::HashMap<(SubscriptionProvider, String), [u8; 32]>>,
    durable: std::sync::Mutex<Option<RejectionStore>>,
}

impl RejectionRecord {
    /// Mirror refusals into `data_dir` so a later process can read them.
    pub fn persist_in(&self, data_dir: &Path) {
        if let Ok(mut guard) = self.durable.lock() {
            *guard = Some(RejectionStore::open(data_dir));
        }
    }

    /// Record that a refresh was refused for exactly `credential`.
    pub fn record(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
    ) {
        if let Ok(mut guard) = self.remembered.lock() {
            guard.insert(
                (provider, account.to_string()),
                crate::refresh::credential_fingerprint(credential),
            );
        }
        if let Some(store) = self.store() {
            store.record(provider, account, credential);
        }
    }

    /// Forget any refusal for `account`, after a refresh succeeded.
    pub fn clear(&self, provider: SubscriptionProvider, account: &str) {
        if let Ok(mut guard) = self.remembered.lock() {
            guard.remove(&(provider, account.to_string()));
        }
        if let Some(store) = self.store() {
            store.clear(provider, account);
        }
    }

    /// Whether a refresh was already refused for exactly this credential.
    #[must_use]
    pub fn was_refused(
        &self,
        provider: SubscriptionProvider,
        account: &str,
        credential: &SubscriptionToken,
    ) -> bool {
        let fingerprint = crate::refresh::credential_fingerprint(credential);
        let remembered = self
            .remembered
            .lock()
            .ok()
            .and_then(|guard| {
                guard
                    .get(&(provider, account.to_string()))
                    .map(|refused| *refused == fingerprint)
            })
            .unwrap_or(false);
        remembered
            || self
                .store()
                .is_some_and(|store| store.was_refused(provider, account, credential))
    }

    fn store(&self) -> Option<RejectionStore> {
        self.durable.lock().ok().and_then(|guard| guard.clone())
    }
}

