/// One record saying that older records were discarded to stay inside
/// `REQUEST_LOG_MAX_BYTES`.
///
/// Dropping data under a bound is defensible; dropping it invisibly is what
/// turns a bounded log into an unreliable one. This log is the only place the
/// request and response bodies exist, and an auditor reading it asks about the
/// beginning of a session — the end compaction removes first (issue #322).
fn discard_marker(discarded_bytes: u64, retained_bytes: Option<usize>) -> Vec<u8> {
    let mut line = crate::lino_json::encode_line(&json!({
        "time": crate::operation_context::now().to_rfc3339(),
        "phase": "log_compaction",
        "body": retained_bytes.map_or_else(
            || format!(
                "[OMITTED: {discarded_bytes} bytes of older records discarded; the incoming \
                 record alone exceeds the request log limit]"
            ),
            |retained| format!(
                "[OMITTED: {discarded_bytes} bytes of older records discarded to stay within \
                 the request log limit; {retained} bytes retained]"
            ),
        ),
    }))
    .unwrap_or_default()
    .into_bytes();
    line.push(b'\n');
    line
}

//! Bounded request lookup, clear, and active-account snapshots.
use super::RequestLog;
use serde_json::{Value, json};
use std::collections::BTreeMap;
use std::fs;
use std::io::{self, BufRead as _, Read as _};
use std::path::PathBuf;
use std::sync::Arc;

const MAX_LOOKUP_BYTES: u64 = 10 * 1024 * 1024;

impl RequestLog {
    /// Attach an explicitly enabled error store. Disabled for ordinary constructors.
    #[must_use]
    pub fn with_error_log(mut self, log: Arc<crate::error_log::ErrorLog>) -> Self {
        self.error_log = Some(log);
        self
    }

    pub(crate) fn with_error_log_from_env(self) -> Self {
        match crate::error_log::ErrorLog::from_env() {
            Some(log) => self.with_error_log(log),
            None => self,
        }
    }

    /// Enabled error capture store, if any.
    #[must_use]
    pub const fn error_log(&self) -> Option<&Arc<crate::error_log::ErrorLog>> {
        self.error_log.as_ref()
    }

    /// Read all retained phases for an id, accepting links notation and legacy JSON.
    pub fn lookup(&self, id: &str) -> io::Result<Vec<Value>> {
        if id.is_empty() || id.len() > 128 {
            return Err(io::Error::from(io::ErrorKind::InvalidInput));
        }
        let _guard = self
            .write_lock
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut records = Vec::new();
        let mut size = 0;
        for path in self.files()? {
            let file = fs::File::open(path)?;
            let reader = io::BufReader::new(file.take(self.max_bytes));
            for line in reader.lines() {
                let line = line?;
                // Match the encoded id before parsing unrelated large records.
                if !line.contains(id) {
                    continue;
                }
                if let Some(record) = crate::lino_json::decode_line(&line)
                    && record["correlation_id"].as_str() == Some(id)
                {
                    size += line.len() as u64;
                    if size > MAX_LOOKUP_BYTES {
                        return Err(io::Error::other("request exceeds lookup limit"));
                    }
                    records.push(record);
                }
            }
        }
        Ok(records)
    }

    fn files(&self) -> io::Result<Vec<PathBuf>> {
        match fs::symlink_metadata(&self.root) {
            Ok(metadata) if metadata.is_dir() => (),
            Ok(_) => return Err(io::Error::from(io::ErrorKind::InvalidInput)),
            Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(error) => return Err(error),
        }
        let mut files = Vec::new();
        for entry in fs::read_dir(&self.root)? {
            let entry = entry?;
            if !entry.file_type()?.is_dir() {
                continue;
            }
            for name in [super::LOG_FILE, super::LEGACY_LOG_FILE] {
                let path = entry.path().join(name);
                if fs::symlink_metadata(&path).is_ok_and(|metadata| metadata.is_file()) {
                    files.push(path);
                }
            }
        }
        files.sort();
        Ok(files)
    }

    /// Delete retained request/error files, preserving operational and audit logs.
    pub fn clear(&self) -> io::Result<()> {
        let _guard = self
            .write_lock
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        for file in self.files()? {
            fs::remove_file(file)?;
        }
        *self
            .total_limit_state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        if let Some(log) = &self.error_log {
            log.clear()?;
        }
        Ok(())
    }

    pub(crate) fn set_account(&self, id: &str, account: &str) {
        if let Some(route) = self
            .routes
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get_mut(id)
        {
            route.account = Some(account.to_owned());
        }
    }

    pub(crate) fn begin_upstream(&self, id: &str) {
        if let Some(route) = self
            .routes
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get_mut(id)
        {
            route.account.get_or_insert_with(|| "primary".to_owned());
        }
    }

    /// Active HTTP exchanges per selected account, through response consumption.
    /// Router dispatches immediately, so there is no application queue.
    #[must_use]
    pub fn queue_snapshot(&self, configured: impl IntoIterator<Item = String>) -> Value {
        let mut counts = configured
            .into_iter()
            .map(|name| (name, 0_u64))
            .collect::<BTreeMap<_, _>>();
        let routes = self
            .routes
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut unassigned = 0;
        for route in routes.values() {
            if let Some(name) = &route.account {
                *counts.entry(name.clone()).or_default() += 1;
            } else {
                unassigned += 1;
            }
        }
        let in_flight = routes.len();
        drop(routes);
        let accounts = counts
            .into_iter()
            .map(|(name, in_flight)| json!({"name": name, "in_flight": in_flight, "queued": 0}))
            .collect::<Vec<_>>();
        json!({"accounts": accounts, "in_flight": in_flight, "queued": 0, "unassigned": unassigned})
    }
}

//! Owner-only file and directory creation for the request store.
//!
//! The request log is the only place complete client and upstream bodies
//! exist, so every file and directory it creates is `0o600`/`0o700` from the
//! moment it exists rather than being tightened afterwards. Split from
//! `request_log.rs` to keep that file within the repository's 1000-line limit.

use std::fs::{self, OpenOptions};
use std::io::Write as _;
use std::path::Path;

pub fn ensure_owner_only_dir(path: &Path) -> std::io::Result<()> {
    fs::create_dir_all(path)?;
    set_dir_owner_only(path)
}

#[cfg(unix)]
fn set_dir_owner_only(path: &Path) -> std::io::Result<()> {
    use std::os::unix::fs::PermissionsExt as _;

    fs::set_permissions(path, fs::Permissions::from_mode(0o700))
}

#[cfg(not(unix))]
fn set_dir_owner_only(_path: &Path) -> std::io::Result<()> {
    Ok(())
}

pub(super) fn append_owner_only(path: &Path, contents: &[u8]) -> std::io::Result<()> {
    let mut options = OpenOptions::new();
    options.create(true).append(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let mut file = options.open(path)?;
    set_owner_only(&file)?;
    file.write_all(contents)
}

pub fn write_owner_only(path: &Path, contents: &[u8]) -> std::io::Result<()> {
    let mut options = OpenOptions::new();
    options.create(true).write(true).truncate(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let mut file = options.open(path)?;
    set_owner_only(&file)?;
    file.write_all(contents)
}

#[cfg(unix)]
fn set_owner_only(file: &fs::File) -> std::io::Result<()> {
    use std::os::unix::fs::PermissionsExt as _;

    file.set_permissions(fs::Permissions::from_mode(0o600))
}

#[cfg(not(unix))]
fn set_owner_only(_file: &fs::File) -> std::io::Result<()> {
    Ok(())
}

//! Credential redaction for recorded requests, responses and URIs.
//!
//! The request store holds complete client and upstream exchanges, so it is
//! the one place a credential must never survive. Redaction is partial rather
//! than total wherever a value has to stay distinguishable — an operator
//! correlating two records needs to tell one token from another without either
//! being reconstructable. Split from `request_log.rs` to keep that file within
//! the repository's 1000-line limit.

use std::collections::BTreeMap;

use axum::http::HeaderMap;
use serde_json::{Value, json};

use super::{
    MIN_PARTIAL_REDACTION_LENGTH, REDACTED, REDACTED_PREFIX_LENGTH, REDACTED_SUFFIX_LENGTH,
};

pub(super) fn partially_redact(value: &str) -> String {
    let length = value.chars().count();
    if length < MIN_PARTIAL_REDACTION_LENGTH {
        return REDACTED.to_string();
    }
    let prefix = value
        .chars()
        .take(REDACTED_PREFIX_LENGTH)
        .collect::<String>();
    let suffix = value
        .chars()
        .skip(length - REDACTED_SUFFIX_LENGTH)
        .collect::<String>();
    let mask = "*".repeat(length - REDACTED_PREFIX_LENGTH - REDACTED_SUFFIX_LENGTH);
    format!("{prefix}{mask}{suffix}")
}

fn redact_secret(value: &str) -> String {
    let trimmed = value.trim();
    if trimmed
        .get(..7)
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("bearer "))
    {
        return format!("{}{}", &trimmed[..7], partially_redact(&trimmed[7..]));
    }
    partially_redact(trimmed)
}

/// Mask credentials while retaining header names for diagnostics.
#[must_use]
pub fn redacted_headers(headers: &HeaderMap) -> BTreeMap<String, String> {
    headers
        .iter()
        .map(|(name, value)| {
            let name = name.as_str().to_string();
            let value = if is_secret_name(&name) {
                value
                    .to_str()
                    .map_or_else(|_| REDACTED.to_string(), redact_secret)
            } else {
                value.to_str().map_or_else(
                    |_| "[NON-UTF8]".to_string(),
                    |value| {
                        if is_secret_value(value) {
                            redact_secret(value)
                        } else {
                            value.to_string()
                        }
                    },
                )
            };
            (name, value)
        })
        .collect()
}

/// How a body that is not valid UTF-8 is represented in the log.
///
/// `String::from_utf8_lossy` replaces every invalid byte with U+FFFD, which for
/// a compressed body destroys it: the record is then neither readable nor
/// decodable after the fact (issue #231). Such a body is base64-encoded instead,
/// under a marker that says what the reader is looking at.
pub const BINARY_BODY_KEY: &str = "base64";

/// Encode a body for the log without losing it.
///
/// A body is stored as JSON when it parses as JSON, as text when it is valid
/// UTF-8, and otherwise as base64 — which is what a `gzip`, `br` or `zstd`
/// response looks like here, because the router does not decompress upstream
/// bodies and a single frame of a compressed *stream* cannot be decoded on its
/// own anyway.
#[must_use]
pub fn redacted_body(body: &[u8]) -> Value {
    if let Ok(value) = serde_json::from_slice::<Value>(body) {
        return redact_value(value);
    }
    std::str::from_utf8(body).map_or_else(
        |_| {
            json!({
                BINARY_BODY_KEY: base64::Engine::encode(
                    &base64::engine::general_purpose::STANDARD,
                    body,
                ),
                "bytes": body.len(),
            })
        },
        |text| Value::String(text.to_string()),
    )
}

pub(super) fn redact_value(mut value: Value) -> Value {
    match &mut value {
        Value::Object(object) => {
            for (key, child) in object {
                if key.eq_ignore_ascii_case("metadata") || is_safety_identifier_name(key) {
                    *child = Value::String(REDACTED.to_string());
                } else if is_secret_name(key) {
                    *child = child.as_str().map_or_else(
                        || Value::String(REDACTED.to_string()),
                        |secret| Value::String(redact_secret(secret)),
                    );
                } else if key.eq_ignore_ascii_case("uri")
                    && let Value::String(uri) = child
                {
                    *uri = redacted_uri(uri);
                } else {
                    *child = redact_value(child.take());
                }
            }
        }
        Value::Array(array) => {
            for child in array {
                *child = redact_value(child.take());
            }
        }
        Value::String(text) if is_secret_value(text) => {
            *text = redact_secret(text);
        }
        _ => {}
    }
    value
}

fn is_safety_identifier_name(name: &str) -> bool {
    matches!(
        normalize_name(name).as_str(),
        "safety_identifier" | "user_id" | "prompt_cache_key"
    )
}

pub fn is_secret_name(name: &str) -> bool {
    let normalized = normalize_name(name);
    matches!(
        normalized.as_str(),
        "authorization"
            | "proxy_authorization"
            | "x_api_key"
            | "api_key"
            | "key"
            | "cookie"
            | "set_cookie"
            | "access_token"
            | "refresh_token"
            | "oauth_token"
            | "auth_token"
            | "security_token"
            | "x_auth_token"
            | "x_goog_api_key"
            | "x_amz_security_token"
            | "token"
            | "password"
            | "secret"
            | "client_secret"
            | "private_key"
    ) || normalized.ends_with("_password")
        || normalized.ends_with("_secret")
        || normalized.ends_with("_token")
        || normalized.ends_with("_api_key")
}

fn normalize_name(name: &str) -> String {
    let mut normalized = String::with_capacity(name.len());
    let mut previous_was_lowercase_or_digit = false;
    for character in name.chars() {
        if character.is_ascii_uppercase() {
            if previous_was_lowercase_or_digit && !normalized.ends_with('_') {
                normalized.push('_');
            }
            normalized.push(character.to_ascii_lowercase());
            previous_was_lowercase_or_digit = false;
        } else if character.is_ascii_alphanumeric() {
            normalized.push(character.to_ascii_lowercase());
            previous_was_lowercase_or_digit =
                character.is_ascii_lowercase() || character.is_ascii_digit();
        } else {
            if !normalized.ends_with('_') {
                normalized.push('_');
            }
            previous_was_lowercase_or_digit = false;
        }
    }
    normalized.trim_matches('_').to_string()
}

fn is_secret_value(value: &str) -> bool {
    let value = value.trim();
    value
        .get(..7)
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("bearer "))
        || [
            "sk-ant-",
            crate::token::TOKEN_PREFIX,
            crate::token::CODEX_TOKEN_PREFIX,
            crate::admin::ADMIN_TOKEN_PREFIX,
        ]
        .iter()
        .any(|prefix| value.contains(prefix))
        || is_jwt(
            value
                .strip_prefix(crate::token::TOKEN_PREFIX)
                .or_else(|| value.strip_prefix(crate::token::CODEX_TOKEN_PREFIX))
                .unwrap_or(value),
        )
}

fn is_jwt(value: &str) -> bool {
    let mut segments = value.split('.');
    let Some(header) = segments.next() else {
        return false;
    };
    let Some(payload) = segments.next() else {
        return false;
    };
    let Some(signature) = segments.next() else {
        return false;
    };
    segments.next().is_none()
        && header.starts_with("eyJ")
        && [header, payload, signature].iter().all(|segment| {
            segment.len() >= 8
                && segment.chars().all(|character| {
                    character.is_ascii_alphanumeric() || matches!(character, '-' | '_')
                })
        })
}

pub(super) fn redacted_uri(uri: &str) -> String {
    let Some((path, query)) = uri.split_once('?') else {
        return uri.to_string();
    };
    let query = query
        .split('&')
        .map(|parameter| {
            let (name, value) = parameter.split_once('=').unwrap_or((parameter, ""));
            let decoded_name = percent_decode(name);
            let decoded_value = percent_decode(value);
            if is_secret_name(&decoded_name) || is_secret_value(&decoded_value) {
                format!("{name}={}", redact_secret(&decoded_value))
            } else {
                parameter.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("&");
    format!("{path}?{query}")
}

fn percent_decode(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            b'%' if index + 2 < bytes.len() => {
                if let (Some(high), Some(low)) =
                    (hex_digit(bytes[index + 1]), hex_digit(bytes[index + 2]))
                {
                    decoded.push(high * 16 + low);
                    index += 3;
                    continue;
                }
                decoded.push(bytes[index]);
            }
            b'+' => decoded.push(b' '),
            byte => decoded.push(byte),
        }
        index += 1;
    }
    String::from_utf8_lossy(&decoded).into_owned()
}

const fn hex_digit(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resource_metadata_is_never_written_to_request_logs() {
        let redacted = redacted_body(
            br#"{"store":true,"metadata":{"tenant":"sensitive-customer","case":"secret"}}"#,
        );
        assert_eq!(redacted["store"], true);
        assert_eq!(redacted["metadata"], REDACTED);
        assert!(!redacted.to_string().contains("sensitive-customer"));
        assert!(!redacted.to_string().contains("secret"));
    }
}

//! How a relayed stream finished, and what the log can say about it.
//!
//! Split from `request_log.rs` to keep that file within the repository's
//! 1000-line limit.

use super::RequestLog;

/// How a streamed relay finished, for the terminal log record.
#[derive(Debug, Clone)]
pub struct StreamOutcome {
    /// Whether the response was actually streamed.
    ///
    /// Every response is relayed through the same byte-stream machinery, so a
    /// single-shot JSON reply — gzip-compressed, arriving in a few transfer
    /// chunks — used to be settled as a stream that ended without its
    /// terminator, warning once per successful request (issue #252). A reply
    /// that is not a stream has no terminator to miss.
    pub streamed: bool,
    /// Whether the dialect's own terminator was seen.
    pub terminated: bool,
    /// Whether the frames could be read at all.
    ///
    /// The router relays a compressed body byte for byte — it never decodes
    /// one — so scanning those bytes for `message_stop` searches gzip and can
    /// only ever fail. Reporting that as a missing terminator declared every
    /// healthy compressed stream truncated, once per request (issue #255).
    /// "Not verifiable" is the honest answer, and it is a different answer
    /// from "cut short".
    pub inspectable: bool,
    /// Set when the upstream or the transport failed mid-stream.
    pub detail: Option<String>,
    pub frames: u64,
    pub bytes: u64,
    pub duration_ms: u128,
}

impl StreamOutcome {
    #[must_use]
    pub const fn is_complete(&self) -> bool {
        // A non-streamed reply is complete when nothing failed: there is no
        // dialect terminator to look for in a single JSON document.
        if !self.streamed {
            return self.detail.is_none();
        }
        // An unreadable stream is not known to be complete, and equally not
        // known to be cut. `is_complete` answers "can the log vouch for this",
        // so an unverifiable stream answers no — but `label` distinguishes it
        // from a stream that demonstrably stopped early, and the warning and
        // the anomaly classes follow `label`, not this.
        if !self.inspectable {
            return false;
        }
        self.terminated && self.detail.is_none()
    }

    /// Whether this outcome is evidence that the client saw a truncated answer.
    ///
    /// Only a stream whose frames could actually be read can testify to that.
    /// This is what the operator-facing warning keys on: a signal that fires on
    /// the healthy common case cannot be used to find the unhealthy rare one
    /// (issues #234, #255).
    #[must_use]
    pub const fn is_demonstrably_cut(&self) -> bool {
        if self.detail.is_some() {
            return true;
        }
        self.streamed && self.inspectable && !self.terminated
    }

    /// A short, greppable name for the outcome.
    #[must_use]
    pub const fn label(&self) -> &'static str {
        if self.detail.is_some() {
            "upstream_error"
        } else if !self.streamed {
            "completed_not_streamed"
        } else if self.terminated {
            "completed"
        } else if self.inspectable {
            "ended_without_terminator"
        } else {
            "encoded_not_verifiable"
        }
    }
}

/// Sentinel that ends the relayed stream after its outcome has been recorded.
///
/// The terminal record is emitted by a final stream item, which is then filtered
/// out so the client sees only the real body.
pub const STREAM_END_MARKER: &str = "stream-end marker";

/// Record how a relayed stream finished, warning when it was cut short.
///
/// Silence is what made the defect invisible: an operator reading the log saw
/// only `status=200` while the user's answer was truncated (issue #230).
pub fn settle_stream(
    log: &RequestLog,
    correlation_id: &str,
    outcome: &std::sync::Mutex<StreamOutcome>,
    duration_ms: u128,
    logger: &log_lazy::LogLazy,
) {
    let outcome = {
        let mut outcome = outcome.lock().expect("stream outcome lock");
        outcome.duration_ms = duration_ms;
        outcome.clone()
    };
    if stream_warrants_a_warning(&outcome) {
        logger.warn(|| {
            format!(
                "stream {correlation_id} ended without its terminator after {} frames in {}ms{}",
                outcome.frames,
                outcome.duration_ms,
                outcome
                    .detail
                    .as_ref()
                    .map_or_else(String::new, |detail| format!(": {detail}"))
            )
        });
    }
    log.record_stream_end(correlation_id, &outcome);
}

/// Whether a settled stream deserves an operator-facing warning.
///
/// Only a stream that can be *shown* to have stopped early. A compressed body
/// is relayed undecoded, so its frames say nothing either way, and warning
/// about them filled a healthy deployment's log with one warning per
/// successful request — leaving a genuine truncation indistinguishable from
/// routine traffic, the exact outcome the diagnostics exist to prevent
/// (issues #234, #255).
#[must_use]
pub const fn stream_warrants_a_warning(outcome: &StreamOutcome) -> bool {
    outcome.is_demonstrably_cut()
}

/// Whether a relayed body arrives in a form the router can read.
///
/// The router forwards a compressed body verbatim rather than decoding it, so
/// an encoded stream's frames are gzip (or br, or zstd) on the way through.
/// Scanning those for a dialect terminator can only fail, which is why the
/// scan's result is not evidence about them either way (issue #255).
///
/// `identity` is the explicit "no encoding" value, so it is readable.
#[must_use]
pub fn body_is_inspectable(headers: &reqwest::header::HeaderMap) -> bool {
    headers
        .get(reqwest::header::CONTENT_ENCODING)
        .and_then(|value| value.to_str().ok())
        .is_none_or(|encoding| {
            encoding
                .split(',')
                .all(|part| part.trim().is_empty() || part.trim().eq_ignore_ascii_case("identity"))
        })
}

/// Whether a relayed response is a stream, from its own headers.
#[must_use]
pub fn response_is_streamed(headers: &reqwest::header::HeaderMap) -> bool {
    is_streaming_media_type(
        headers
            .get(reqwest::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok()),
    )
}

/// Whether a response `content-type` denotes a streamed body.
///
/// `text/event-stream` is a stream by definition; anything else — most often
/// `application/json` — is a single document, however many transfer chunks it
/// arrives in. An absent or unreadable header is treated as streaming, so the
/// truncation detection from issue #230 keeps its reach when the upstream
/// declares nothing.
#[must_use]
pub fn is_streaming_media_type(content_type: Option<&str>) -> bool {
    content_type.is_none_or(|value| {
        value
            .split(';')
            .next()
            .unwrap_or_default()
            .trim()
            .eq_ignore_ascii_case("text/event-stream")
    })
}

/// Whether `frame` carries the terminating event of a streaming dialect.
///
/// Anthropic ends a turn with `message_stop`; the `OpenAI` surfaces end with
/// `[DONE]`, the Responses shape with `response.completed`, and Gemini with a
/// final chunk carrying `finishReason`. A stream that stops without one of
/// these was cut mid-flight (issue #230).
#[must_use]
pub fn frame_terminates_stream(frame: &[u8]) -> bool {
    let Ok(text) = std::str::from_utf8(frame) else {
        // A compressed frame cannot be inspected; absence of a terminator is
        // then unknowable rather than false, and the caller says so.
        return false;
    };
    text_terminates_stream(text)
}

/// Whether decoded stream text carries a dialect's terminating event.
///
/// Split from [`frame_terminates_stream`] so the log analyser can settle a
/// stream from the body it already recorded, rather than reporting the ending
/// as unknown whenever the relay wrote no terminal record (issue #258). One
/// list, so the two cannot drift into disagreeing about what "finished" means.
#[must_use]
pub fn text_terminates_stream(text: &str) -> bool {
    text.contains("message_stop")
        || text.contains("[DONE]")
        || text.contains("response.completed")
        // Gemini names no terminating event; the last chunk of a finished turn
        // carries `finishReason` instead.
        || text.contains("finishReason")
}

//! Cached accounting for the bound across every per-token request log.

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

use super::{LEGACY_LOG_FILE, LOG_FILE};

#[derive(Clone, Debug)]
struct Directory {
    modified: SystemTime,
    bytes: u64,
    path: PathBuf,
}

#[derive(Debug)]
pub(super) struct State {
    root_modified: Option<SystemTime>,
    total_bytes: u64,
    directories: HashMap<String, Directory>,
    #[cfg(test)]
    pub(super) full_scans: usize,
}

impl State {
    fn load(root: &Path) -> Option<Self> {
        tracing::debug!(root = %root.display(), "loading request-log total accounting");
        let entries = fs::read_dir(root).ok()?;
        let directories = entries
            .flatten()
            .filter(|entry| entry.path().is_dir())
            .filter_map(|entry| {
                usage(&entry.path())
                    .map(|usage| (entry.file_name().to_string_lossy().into_owned(), usage))
            })
            .collect::<HashMap<_, _>>();
        Some(Self {
            root_modified: root_modified(root),
            total_bytes: directories.values().map(|entry| entry.bytes).sum(),
            directories,
            #[cfg(test)]
            full_scans: 1,
        })
    }

    fn root_changed(&self, root: &Path) -> bool {
        self.root_modified != root_modified(root)
    }

    fn refresh(&mut self, root: &Path, active: &str) {
        if let Some(previous) = self.directories.remove(active) {
            self.total_bytes = self.total_bytes.saturating_sub(previous.bytes);
        }
        if let Some(current) = usage(&root.join(active)) {
            self.total_bytes = self.total_bytes.saturating_add(current.bytes);
            self.directories.insert(active.to_string(), current);
        }
    }
}

fn root_modified(root: &Path) -> Option<SystemTime> {
    fs::metadata(root)
        .and_then(|metadata| metadata.modified())
        .ok()
}

fn usage(path: &Path) -> Option<Directory> {
    let mut bytes = 0_u64;
    let mut modified = UNIX_EPOCH;
    let mut found = false;
    for name in [LOG_FILE, LEGACY_LOG_FILE] {
        let Ok(metadata) = fs::metadata(path.join(name)) else {
            continue;
        };
        if !metadata.is_file() {
            continue;
        }
        found = true;
        bytes = bytes.saturating_add(metadata.len());
        modified = modified.max(metadata.modified().unwrap_or(UNIX_EPOCH));
    }
    found.then(|| Directory {
        modified,
        bytes,
        path: path.to_path_buf(),
    })
}

/// Keep the store inside its total bound without rescanning every token for
/// every record. The enclosing request-log write lock serializes updates to
/// this process-local accounting. A changed root mtime forces a rescan so
/// token directories created or removed outside this logger are incorporated.
pub(super) fn enforce(root: &Path, max_total: u64, active: &str, cached: &Mutex<Option<State>>) {
    let Ok(mut cached) = cached.lock() else {
        return;
    };
    if cached.as_ref().is_none_or(|state| state.root_changed(root)) {
        #[cfg(test)]
        let previous_scans = cached.as_ref().map_or(0, |state| state.full_scans);
        *cached = State::load(root);
        #[cfg(test)]
        if let Some(state) = cached.as_mut() {
            state.full_scans += previous_scans;
        }
    }
    let Some(state) = cached.as_mut() else {
        return;
    };
    state.refresh(root, active);
    if state.total_bytes <= max_total {
        return;
    }

    let mut candidates = state
        .directories
        .iter()
        .map(|(name, entry)| {
            (
                entry.modified,
                entry.bytes,
                entry.path.clone(),
                name.clone(),
            )
        })
        .collect::<Vec<_>>();
    candidates.sort_by_key(|(modified, _, _, _)| *modified);
    for (_, bytes, path, name) in candidates {
        if state.total_bytes <= max_total {
            break;
        }
        // Keep the record that triggered enforcement; older inactive token
        // directories are the eviction unit (issues #322, #331).
        if name == active {
            continue;
        }
        if let Err(error) = fs::remove_dir_all(&path) {
            tracing::warn!("request log eviction failed ({}): {error}", path.display());
            continue;
        }
        state.total_bytes = state.total_bytes.saturating_sub(bytes);
        state.directories.remove(&name);
        tracing::info!(
            token_hash = %name,
            bytes,
            "request log evicted a token directory to stay within the total limit"
        );
    }
    state.root_modified = root_modified(root);
}

#[cfg(test)]
impl State {
    pub(super) const fn accounted_bytes(&self) -> u64 {
        self.total_bytes
    }
}

#[cfg(test)]
mod tests {
