        })
        .join();
        let temporary = tempfile::tempdir().unwrap();

        enforce(temporary.path(), 0, "active", &cached);
    }
}

#[cfg(test)]
mod invalidation_tests {
    use super::*;

    #[test]
    fn directory_changes_reload_accounting_and_appends_refresh_only_the_active_log() {
        use std::io::Write as _;
        let root = tempfile::tempdir().unwrap();
        let active = root.path().join("active");
        fs::create_dir(&active).unwrap();
        fs::write(active.join(LOG_FILE), b"first").unwrap();
        let cached = Mutex::new(None);
        enforce(root.path(), 1000, "active", &cached);
        assert_eq!(cached.lock().unwrap().as_ref().unwrap().full_scans, 1);
        fs::OpenOptions::new()
            .append(true)
            .open(active.join(LOG_FILE))
            .unwrap()
            .write_all(b"second")
            .unwrap();
        enforce(root.path(), 1000, "active", &cached);
        assert_eq!(
            cached.lock().unwrap().as_ref().unwrap().accounted_bytes(),
            11
        );
        assert_eq!(cached.lock().unwrap().as_ref().unwrap().full_scans, 1);

        let external = root.path().join("external");
        fs::create_dir(&external).unwrap();
        fs::write(external.join(LEGACY_LOG_FILE), b"external bytes").unwrap();
        // Force the cached timestamp stale without relying on the filesystem's
        // timestamp resolution or a wall-clock sleep.
        cached.lock().unwrap().as_mut().unwrap().root_modified = Some(UNIX_EPOCH);
        enforce(root.path(), 1000, "active", &cached);
        assert_eq!(cached.lock().unwrap().as_ref().unwrap().full_scans, 2);
        assert_eq!(
            cached.lock().unwrap().as_ref().unwrap().accounted_bytes(),
            25
        );
        fs::remove_dir_all(external).unwrap();
        cached.lock().unwrap().as_mut().unwrap().root_modified = Some(UNIX_EPOCH);
        enforce(root.path(), 1000, "active", &cached);
        assert_eq!(cached.lock().unwrap().as_ref().unwrap().full_scans, 3);
        assert_eq!(
            cached.lock().unwrap().as_ref().unwrap().accounted_bytes(),
            11
        );
    }
}

//! Retain active native exchanges without inspecting or changing body frames.
use super::RequestRouteGuard;
use axum::body::Body;
use axum::response::Response;
use http_body_util::BodyExt as _;

pub(super) fn hold_route(response: Response, guard: RequestRouteGuard) -> Response {
    let (parts, body) = response.into_parts();
    let body = body.map_frame(move |frame| {
        let _keep_route_until_response_body_finishes = &guard;
        frame
    });
    Response::from_parts(parts, Body::new(body))
}

//! Provider-neutral extraction of stable account-routing signals.

use std::time::Duration;

/// Maximum operational cooldown accepted from an untrusted upstream hint.
pub const MAX_RETRY_AFTER: Duration = Duration::from_secs(24 * 60 * 60);

#[must_use]
pub fn bounded_retry_after(duration: Duration) -> Duration {
    duration.min(MAX_RETRY_AFTER)
}

use axum::http::HeaderMap;

use crate::accounts::RoutingContext;

/// Private carrier retaining the full selected credential for later evidence.
pub struct ResolvedUpstreamCredential {
    pub access_token: String,
    pub account: Option<String>,
    pub evidence_token: Option<crate::subscription::SubscriptionToken>,
}

/// Copy only stable routing signals from a request. Header signals take
/// precedence over JSON metadata and the caller token's account binding is
/// carried separately as a strict pin. Recognized thinking suffixes share the
/// base model's account eligibility and cooldown identity.
pub fn request_routing_context(
    headers: &HeaderMap,
    body: &crate::translation_core::Json,
    pinned_account: crate::translation_core::Maybe<String>,
) -> RoutingContext {
    const SESSION_HEADERS: [&str; 4] = [
        "x-claude-code-session-id",
        "x-codex-session-id",
        "x-session-id",
        "session-id",
    ];
    let header_session = SESSION_HEADERS.iter().find_map(|name| {
        headers
            .get(*name)
            .and_then(|value| value.to_str().ok())
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    });
    let body_session = [
        "/context/session_id",
        "/metadata/session_id",
        "/metadata/conversation_id",
        "/session_id",
        "/conversation_id",
        "/prompt_cache_key",
    ]
    .iter()
    .find_map(|pointer| {
        body.pointer(pointer)
            .and_then(serde_json::Value::as_str)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    });
    RoutingContext {
        session_key: header_session.or(body_session),
        parent_session_key: [
            "x-parent-session-id",
            "x-codex-parent-session-id",
            "x-parent-thread-id",
            "parent-session-id",
        ]
        .into_iter()
        .find_map(|name| {
            headers
                .get(name)
                .and_then(|value| value.to_str().ok())
                .filter(|value| !value.trim().is_empty())
                .map(str::to_string)
        })
        .or_else(|| {
            [
                "/context/parent_session_id",
                "/metadata/parent_session_id",
                "/parent_session_id",
                "/context/parent_thread_id",
                "/metadata/parent_thread_id",
                "/parent_thread_id",
            ]
            .into_iter()
            .find_map(|pointer| {
                body.pointer(pointer)
                    .and_then(serde_json::Value::as_str)
                    .filter(|value| !value.trim().is_empty())
                    .map(str::to_string)
            })
        }),
        pinned_account,
        model: body
            .get("model")
            .and_then(serde_json::Value::as_str)
            .filter(|model| !model.is_empty())
            .map(|model| crate::thinking::base_model(model).to_string()),
        exclude: Vec::new(),
    }
}

/// Parse the standard `Retry-After` delta-seconds or HTTP-date forms.
pub fn retry_after_duration(headers: &HeaderMap) -> crate::translation_core::Maybe<Duration> {
    let value = headers.get("retry-after")?.to_str().ok()?.trim();
    if let Ok(seconds) = value.parse::<u64>() {
        return Some(bounded_retry_after(Duration::from_secs(seconds)));
    }
    let retry_at = chrono::DateTime::parse_from_rfc2822(value).ok()?;
    let seconds = retry_at
        .signed_duration_since(crate::operation_context::now())
        .num_seconds()
        .max(0);
    Some(bounded_retry_after(Duration::from_secs(
        u64::try_from(seconds).ok()?,
    )))
}

/// Record what the Anthropic upstream just said about the Claude credential.
///
/// The response status is the only authority on whether a credential still
/// works; see [`crate::refresh::CredentialEvidence`].
pub async fn record_claude_evidence(
    state: &crate::app_state::AppState,
    account: crate::translation_core::Maybe<&crate::translation_core::Str>,
    credential: crate::translation_core::Maybe<&crate::subscription::SubscriptionToken>,
    status: u16,
) {
    if crate::account_policy_scope::active() {
        return;
    }
    let cache = &state.subscription_cache;
    let account = account.unwrap_or(crate::credential_recovery_store::PRIMARY_ACCOUNT);
    if let Some(credential) = credential {
        cache
            .record_status_for_credential(
                crate::subscription::SubscriptionProvider::Claude,
                account,
                credential,
                status,
            )
            .await;
    } else {
        // Preserve the legacy unregistered OAuth provider exactly. It returns
        // only a bearer string, so there is no authoritative generation to
        // compare and no registered store that could reconcile a replacement.
        cache.record_status_for(
            crate::subscription::SubscriptionProvider::Claude,
            account,
            status,
        );
    }
}

//! Capture provider-owned resource identities before exposing stored creates.

#![allow(clippy::redundant_pub_crate)]

use axum::body::{Body, Bytes};
use axum::http::{HeaderMap, HeaderValue, StatusCode};
use axum::response::Response;
use futures_util::StreamExt;

use crate::app_state::AppState;
use crate::response_affinity::{AffinityDestination, ResponseNamespace, ResponseOwner};

const MAX_BUFFERED_ID_PREFIX: usize = 1024 * 1024;
const MAX_BUFFERED_JSON_RESPONSE: usize = 32 * 1024 * 1024;

#[derive(Clone)]
pub(crate) struct CaptureContext {
    namespace: ResponseNamespace,
    owner: ResponseOwner,
    destination: AffinityDestination,
    parent_id: Option<String>,
}

impl CaptureContext {
    pub(crate) const fn native(
        namespace: ResponseNamespace,
        owner: ResponseOwner,
        destination: AffinityDestination,
        parent_id: Option<String>,
    ) -> Self {
        Self {
            namespace,
            owner,
            destination,
            parent_id,
        }
    }
}

pub(crate) async fn prepare(
    state: &AppState,
    headers: &HeaderMap,
    namespace: ResponseNamespace,
) -> Result<CaptureContext, Response> {
    let claims = crate::proxy::authenticate_client_error(state, headers)
        .map_err(|error| error.render(crate::api_error::ApiDialect::OpenAi))?;
    let owner = ResponseOwner::from_claims(&claims)
        .map_err(|message| openai_error(StatusCode::FORBIDDEN, "permission_error", &message))?;
    let destination = destination_for_claims(state, &claims).await?;
    Ok(CaptureContext {
        namespace,
        owner,
        destination,
        parent_id: None,
    })
}

pub(crate) async fn destination_for_claims(
    state: &AppState,
    claims: &crate::token::TokenClaims,
) -> Result<AffinityDestination, Response> {
    if state.upstream_provider == crate::config::UpstreamProvider::OpenAICompatible {
        let provider = crate::provider_proxy::resolve_openai_compatible_provider(state)
            .map_err(|error| unavailable(&format!("provider lookup failed: {error}")))?;
        return Ok(AffinityDestination::StoredProvider {
            name: provider.name,
            provider_kind: provider.kind,
            base_url: provider.base_url,
        });
    }
    let Some(provider) = state.upstream_provider.subscription_provider() else {
        return Err(openai_error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "the selected provider does not support persistent response resources",
        ));
    };
    let pin = state
        .token_manager
        .account_for(&claims.sub)
        .map_err(|error| unavailable(&format!("failed to resolve account binding: {error}")))?;
    let account = match (state.account_router.as_ref(), pin) {
        (Some(router), Some(account)) if router.provider() == provider => account,
        (Some(_), Some(_)) => {
            return Err(unavailable(
                "the token account is not configured for the selected subscription",
            ));
        }
        (Some(_), None) => {
            return Err(openai_error(
                StatusCode::CONFLICT,
                "invalid_request_error",
                "stored resources require an exact subscription account binding",
            ));
        }
        (None, Some(account)) if account != crate::credential_recovery_store::PRIMARY_ACCOUNT => {
            return Err(unavailable(
                "the token's bound subscription account is unavailable",
            ));
        }
        (None, _) => crate::credential_recovery_store::PRIMARY_ACCOUNT.to_string(),
    };
    crate::responses_lifecycle::register_exact_reader(state, provider, &account);
    let token = state
        .subscription_cache
        .load_authoritative(provider, &account)
        .await
        .map_err(|_| unavailable("the exact subscription account is unavailable"))?
        .ok_or_else(|| unavailable("the exact subscription account is unavailable"))?;
    let token = state
        .subscription_cache
        .get_fresh_loaded(
            &state.client,
            provider,
            &account,
            token,
            crate::operation_context::now().timestamp_millis(),
        )
        .await
        .map_err(|_| unavailable("the exact subscription account cannot refresh"))?;
    let base_url = state
        .subscription_base_url
        .clone()
        .unwrap_or_else(|| token.base_url(provider));
    Ok(AffinityDestination::Subscription {
        provider,
        account,
        upstream_account_id: token.account_id,
        base_url,
    })
}

pub(crate) fn pin_state(
    state: &AppState,
    affinity: &crate::response_affinity::ResponseAffinity,
) -> Result<AppState, Response> {
    let mut pinned = state.clone();
    match &affinity.destination {
        AffinityDestination::StoredProvider {
            name,
            provider_kind,
            base_url,
        } => {
            let provider = state
                .provider_store
                .resolve(name)
                .map_err(|error| unavailable(&format!("provider lookup failed: {error}")))?
                .or_else(|| {
                    (state.openai_compatible.provider_name == *name)
                        .then(|| state.openai_compatible.resolve())
                })
                .filter(|provider| {
                    provider.kind == *provider_kind && provider.base_url == *base_url
                })
                .ok_or_else(|| unavailable("the response's exact provider is unavailable"))?;
            pinned.upstream_provider = crate::config::UpstreamProvider::OpenAICompatible;
            pinned.openai_compatible.provider_name = provider.name;
        }
        AffinityDestination::Subscription { provider, .. } => {
            pinned.upstream_provider = match provider {
                crate::subscription::SubscriptionProvider::Claude => {
                    crate::config::UpstreamProvider::Anthropic
                }
                crate::subscription::SubscriptionProvider::Codex => {
                    crate::config::UpstreamProvider::Codex
                }
                crate::subscription::SubscriptionProvider::Gemini => {
                    crate::config::UpstreamProvider::Gemini
                }
                crate::subscription::SubscriptionProvider::Qwen => {
                    crate::config::UpstreamProvider::Qwen
                }
            };
        }
    }
    Ok(pinned)
}

pub(crate) async fn capture(
    state: &AppState,
    context: CaptureContext,
    response: Response,
) -> Response {
    capture_with_json_fields(state, context, response, &["id"]).await
}

pub(crate) async fn capture_with_json_fields(
    state: &AppState,
    context: CaptureContext,
    response: Response,
    id_fields: &[&str],
) -> Response {
    if !response.status().is_success() {
        return response;
    }
    let event_stream = response
        .headers()
        .get("content-type")
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.to_ascii_lowercase().contains("text/event-stream"));
    if event_stream {
        return capture_stream(state, context, response).await;
    }
    let (parts, body) = response.into_parts();
    let bytes = match axum::body::to_bytes(body, MAX_BUFFERED_JSON_RESPONSE).await {
        Ok(bytes) => bytes,
        Err(error) => return upstream_error(&format!("stored response is too large: {error}")),
    };
    let Some(response_id) =
        json_id_from_fields(&bytes, id_fields).or_else(|| location_id(&parts.headers))
    else {
        return upstream_error("stored response did not include a resource id");
    };
    if let Err(error) = record_context(state, context, &response_id) {
        return affinity_error(&error);
    }
    Response::from_parts(parts, Body::from(bytes))
}

async fn capture_stream(state: &AppState, context: CaptureContext, response: Response) -> Response {
    let (parts, body) = response.into_parts();
    let mut source = body.into_data_stream();
    let mut held = Vec::new();
    let mut framed = Vec::new();
    let response_id = loop {
        let Some(chunk) = source.next().await else {
            return upstream_error("stored stream ended before exposing a resource id");
        };
        let bytes = match chunk {
            Ok(bytes) => bytes,
            Err(error) => return upstream_error(&format!("upstream stream failed: {error}")),
        };
        held.extend_from_slice(&bytes);
        let blocks = crate::sse::push_blocks(&mut framed, &bytes);
        if let Some(response_id) = blocks.iter().find_map(|block| sse_id(block)) {
            break response_id;
        }
        if held.len() > MAX_BUFFERED_ID_PREFIX {
            return upstream_error("stored stream did not expose a bounded resource id");
        }
    };
    if let Err(error) = record_context(state, context, &response_id) {
        return affinity_error(&error);
    }
    let prefix = futures_util::stream::once(async move { Ok::<_, axum::Error>(Bytes::from(held)) });
    let stream = prefix.chain(source);
    Response::from_parts(parts, Body::from_stream(stream))
}

#[cfg(test)]
fn json_id(bytes: &[u8]) -> Option<String> {
    json_id_from_fields(bytes, &["id"])
}

fn json_id_from_fields(bytes: &[u8], fields: &[&str]) -> Option<String> {
    let value = serde_json::from_slice::<serde_json::Value>(bytes).ok()?;
    fields.iter().find_map(|field| {
        value
            .get(*field)?
            .as_str()
            .filter(|id| !id.is_empty())
            .map(str::to_string)
    })
}

fn location_id(headers: &HeaderMap) -> Option<String> {
    let location = headers.get("location")?.to_str().ok()?;
    let path = location.split('?').next()?.trim_end_matches('/');
    path.rsplit('/')
        .next()
        .filter(|id| !id.is_empty())
        .map(str::to_string)
}

fn record_context(
    state: &AppState,
    context: CaptureContext,
    response_id: &str,
) -> Result<crate::response_affinity::RecordOutcome, crate::response_affinity::StoreError> {
    let store = state.provider_store.response_affinities();
    if let Some(parent_id) = context.parent_id {
        store.record_child(
            context.namespace,
            response_id,
            &parent_id,
            context.owner,
            context.destination,
        )
    } else {
        store.record(
            context.namespace,
            response_id,
            context.owner,
            context.destination,
        )
    }
}

fn sse_id(block: &str) -> Option<String> {
    block.lines().find_map(|line| {
        let payload = line.strip_prefix("data:")?.trim();
        let value = serde_json::from_str::<serde_json::Value>(payload).ok()?;
        value
            .get("id")
            .or_else(|| value.pointer("/response/id"))
            .and_then(serde_json::Value::as_str)
            .filter(|id| !id.is_empty())
            .map(str::to_string)
    })
}

fn affinity_error(error: &impl std::fmt::Display) -> Response {
    openai_error(
        StatusCode::SERVICE_UNAVAILABLE,
        "api_error",
        &format!("could not persist resource ownership: {error}"),
    )
}

fn unavailable(message: &str) -> Response {
    openai_error(StatusCode::SERVICE_UNAVAILABLE, "api_error", message)
}

fn upstream_error(message: &str) -> Response {
    openai_error(StatusCode::BAD_GATEWAY, "api_error", message)
}

fn openai_error(status: StatusCode, error_type: &str, message: &str) -> Response {
    let body = serde_json::json!({
        "error": {
            "message": message,
            "type": error_type,
            "param": serde_json::Value::Null,
            "code": serde_json::Value::Null,
        }
    });
    let mut response = Response::new(Body::from(
        serde_json::to_vec(&body).expect("JSON values always serialize"),
    ));
    *response.status_mut() = status;
    response
        .headers_mut()
        .insert("content-type", HeaderValue::from_static("application/json"));
    response
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_found_in_json_and_both_stream_shapes() {
        assert_eq!(json_id(br#"{"id":"resp_1"}"#).as_deref(), Some("resp_1"));
        assert_eq!(
            sse_id("event: response.created\ndata: {\"response\":{\"id\":\"resp_2\"}}").as_deref(),
            Some("resp_2")
        );
        assert_eq!(
            sse_id("data: {\"id\":\"chatcmpl-3\",\"choices\":[]}").as_deref(),
            Some("chatcmpl-3")
        );
    }
}

//! Durable ownership and upstream affinity for provider-owned `OpenAI` resources.

#![allow(clippy::redundant_pub_crate)]

use std::fmt;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::Duration;

use serde::{Deserialize, Serialize};

const FILE_NAME: &str = "response-affinities.lino";
const STORE_VERSION: u32 = 1;
const DEFAULT_TTL: Duration = Duration::from_secs(30 * 24 * 60 * 60);
const DEFAULT_MAX_RECORDS: usize = 10_000;
const MAX_RESPONSE_ID_BYTES: usize = 256;

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum ResponseNamespace {
