    #[test]
    fn current_prompt_cache_breakpoints_preserve_parts_and_order() {
        let breakpoint = json!({"mode":"explicit"});
        let converted = try_chat_completion_to_responses(&json!({
            "model":"gpt-5",
            "messages":[
                {"role":"system","content":[{
                    "type":"text","text":"policy",
                    "prompt_cache_breakpoint":breakpoint
                }]},
                {"role":"developer","content":[{
                    "type":"text","text":"application",
                    "prompt_cache_breakpoint":breakpoint
                }]},
                {"role":"user","content":[
                    {"type":"image_url","image_url":{"url":"https://example.com/image.png"},
                     "prompt_cache_breakpoint":breakpoint},
                    {"type":"file","file":{"file_data":"data:application/pdf;base64,AAA","filename":"fixture.pdf"},
                     "prompt_cache_breakpoint":breakpoint}
                ]},
                {"role":"assistant","content":null,"tool_calls":[{
                    "id":"call_1","type":"function",
                    "function":{"name":"inspect","arguments":"{}"}
                }]},
                {"role":"tool","tool_call_id":"call_1","content":[{
                    "type":"text","text":"done"
                }]}
            ]
        }))
        .unwrap();

        assert_eq!(converted["input"][0]["role"], "system");
        assert_eq!(converted["input"][1]["role"], "developer");
        for pointer in [
            "/input/0/content/0/prompt_cache_breakpoint",
            "/input/1/content/0/prompt_cache_breakpoint",
            "/input/2/content/0/prompt_cache_breakpoint",
            "/input/2/content/1/prompt_cache_breakpoint",
        ] {
            assert_eq!(converted.pointer(pointer), Some(&breakpoint), "{pointer}");
        }
        assert!(converted["input"][4]["output"].is_array());

        let tool_output = try_chat_completion_to_responses(&json!({
            "model":"gpt-5",
            "messages":[
                {"role":"assistant","content":null,"tool_calls":[{
                    "id":"call_1","type":"function",
                    "function":{"name":"inspect","arguments":"{}"}
                }]},
                {"role":"tool","tool_call_id":"call_1","content":[{
                    "type":"text","text":"done",
                    "prompt_cache_breakpoint":breakpoint
                }]}
            ]
        }))
        .unwrap();
        assert_eq!(
            tool_output.pointer("/input/1/output/0/prompt_cache_breakpoint"),
            Some(&breakpoint)
        );
    }

    #[test]
    fn unrepresentable_or_malformed_history_is_rejected() {
        for message in [
            json!({"role":"user","content":[{"type":"input_audio","input_audio":{"data":"AAA","format":"wav"}}]}),
            json!({"role":"user","content":[{"type":"image_url","image_url":{}}]}),
            json!({"role":"user","content":[{"type":"file","file":{"filename":"only.txt"}}]}),
            json!({"role":"assistant","content":"prior","audio":{"id":"audio_1"}}),
            json!({"role":"assistant","content":null,"function_call":{"name":"legacy","arguments":"{}"}}),
            json!({"role":"function","name":"legacy","content":"result"}),
            json!({"role":"user","content":[{"type":"unknown","value":"x"}]}),
            json!({"role":"assistant","content":null,"tool_calls":[
                {"id":"call_1","type":"function","function":{"name":"one","arguments":"{}"}},
                {"id":"call_1","type":"function","function":{"name":"two","arguments":"{}"}}
            ]}),
        ] {
            let body = json!({"model":"gpt-5","messages":[message]});
            assert!(try_chat_completion_to_responses(&body).is_err(), "{body}");
        }
    }
}

#[cfg(test)]
mod nonempty_core_projection_goldens {
    use super::{nonempty_string, Value};

    #[test]
    fn complete_json_field_nonempty_edges_keep_the_borrowed_input() {
        let cases = [
            (serde_json::json!({}), "x", None),
            (serde_json::json!({"x": null}), "x", None),
            (serde_json::json!({"x": false}), "x", None),
            (serde_json::json!({"x": 0}), "x", None),
            (serde_json::json!({"x": []}), "x", None),
            (serde_json::json!({"x": ""}), "x", None),
            (serde_json::json!({"x": " "}), "x", Some(" ")),
            (serde_json::json!({"x": "猫😀"}), "x", Some("猫😀")),
            (serde_json::json!({"": "\u{0}"}), "", Some("\u{0}")),
        ];
        for (value, key, expected) in cases {
            let actual = nonempty_string(&value, key);
            assert_eq!(actual, expected);
            if let Some(text) = actual {
                let original = Value::as_str(value.get(key).expect("present source field"))
                    .expect("source field is text");
                assert_eq!(text.as_ptr(), original.as_ptr());
            }
        }
    }
}

//! Buffered Anthropic Messages to `OpenAI` Responses translation.

use serde_json::{Value, json};

#[must_use]
pub fn anthropic_to_response(anthropic: &Value, _resolved_model: &str) -> Value {
    let id = anthropic
        .get("id")
        .and_then(Value::as_str)
        .map_or_else(|| format!("resp-{}", uuid::Uuid::new_v4()), String::from);
    let (text, annotations) =
        crate::bridge_response::anthropic_text_and_annotations(anthropic.get("content"));
    let stop = crate::bridge_response::stop_semantics(
        anthropic.get("stop_reason").and_then(Value::as_str),
    );
    let mut output = Vec::new();
    if let Some(blocks) = anthropic.get("content").and_then(Value::as_array) {
        for block in blocks {
            match block.get("type").and_then(Value::as_str) {
                Some("tool_use") => output.push(json!({
                    "type": "function_call",
                    "call_id": block.get("id").and_then(Value::as_str).unwrap_or_default(),
                    "name": block.get("name").and_then(Value::as_str).unwrap_or_default(),
                    "arguments": serde_json::to_string(
                        block.get("input").unwrap_or(&Value::Null)
                    ).unwrap_or_else(|_| "{}".into()),
                    "status": "completed",
                })),
                Some("server_tool_use") => {
                    let call_type = match block.get("name").and_then(Value::as_str) {
                        Some("web_fetch") => "web_fetch_call",
                        _ => "web_search_call",
                    };
                    output.push(json!({
                        "type": call_type,
                        "id": block.get("id").and_then(Value::as_str).unwrap_or_default(),
                        "status": "in_progress",
                        "action": block.get("input").cloned().unwrap_or_else(|| json!({})),
                    }));
                }
                Some(result_type @ ("web_search_tool_result" | "web_fetch_tool_result")) => {
                    let call_type = if result_type == "web_fetch_tool_result" {
                        "web_fetch_call"
                    } else {
                        "web_search_call"
                    };
                    if let Some(item) = output.iter_mut().rev().find(|item| {
                        item.get("type").and_then(Value::as_str) == Some(call_type)
                            && item.get("id") == block.get("tool_use_id")
                    }) {
                        item["status"] = Value::String("completed".into());
                        item["result"] = block.get("content").cloned().unwrap_or(Value::Null);
                    }
                }
                _ => {}
            }
        }
    }
    if !text.is_empty() || output.is_empty() {
        let part = if stop.refusal {
            json!({"type": "refusal", "refusal": text})
        } else {
            json!({"type": "output_text", "text": text, "annotations": annotations})
        };
        output.push(json!({
            "type": "message",
            "role": "assistant",
            "status": stop.response_status,
            "content": [part]
        }));
    }
    let served_model = anthropic
        .get("model")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let usage = crate::bridge_response::AnthropicUsage::from_value(anthropic.get("usage"));
    let mut response = json!({
        "id": id,
        "object": "response",
        "created_at": crate::operation_context::now().timestamp(),
        "model": served_model,
        "status": stop.response_status,
        "output": output,
        "usage": usage.responses(),
    });
    if let Some(tier) = usage.openai_service_tier() {
        response["service_tier"] = Value::String(tier.into());
    }
    if let Some(reason) = stop.incomplete_reason {
        response["incomplete_details"] = json!({"reason": reason});
    }
    response
}

//! Responses input normalization and bridge validation.

use serde_json::{Value, json};

/// Normalize a Responses input field to the typed list shape Codex requires.
#[must_use]
pub fn normalize_input_items(input: &Value) -> Value {
    fn user_turn(text: &str) -> Value {
        json!({
            "type": "message",
            "role": "user",
            "content": [{"type": "input_text", "text": text}],
        })
    }
    match input {
        Value::String(text) => json!([user_turn(text)]),
        Value::Array(items) => Value::Array(
            items
                .iter()
                .map(|item| item.as_str().map_or_else(|| item.clone(), user_turn))
                .collect(),
        ),
        other => other.clone(),
    }
}

/// Return why prior Responses history cannot be converted to Anthropic.
#[must_use]
pub fn untranslatable_tool_history(input: &Value) -> Option<String> {
    crate::bridge_request::untranslatable_response_history(input)
}

//! Stored `OpenAI Responses` resource lifecycle proxying.

use axum::body::{Body, Bytes};
use axum::extract::{OriginalUri, Path, Request, State};
use axum::http::{HeaderMap, HeaderValue, Method, StatusCode, Uri};
use axum::response::{IntoResponse, Response};

use crate::app_state::AppState;
use crate::response_affinity::{
    AffinityDestination, ResponseAffinity, ResponseNamespace, ResponseOwner,
};
use crate::subscription::{SubscriptionProvider, SubscriptionToken};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Operation {
    Retrieve,
    Delete,
    Cancel,
    InputItems,
}

impl Operation {
    const fn suffix(self) -> &'static crate::translation_core::Str {
        match self {
            Self::Retrieve | Self::Delete => "",
            Self::Cancel => "/cancel",
            Self::InputItems => "/input_items",
        }
    }
}

pub async fn retrieve(
    State(state): State<AppState>,
    Path(response_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    forward(state, response_id, uri, request, Operation::Retrieve).await
}

pub async fn delete(
    State(state): State<AppState>,
    Path(response_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    forward(state, response_id, uri, request, Operation::Delete).await
}

pub async fn cancel(
    State(state): State<AppState>,
    Path(response_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    forward(state, response_id, uri, request, Operation::Cancel).await
}

pub async fn input_items(
    State(state): State<AppState>,
    Path(response_id): Path<String>,
    OriginalUri(uri): OriginalUri,
    request: Request,
) -> Response {
    forward(state, response_id, uri, request, Operation::InputItems).await
}

async fn forward(
    state: AppState,
    response_id: String,
    uri: Uri,
    request: Request,
    operation: Operation,
) -> Response {
    let claims = match crate::proxy::authenticate_client_error(&state, request.headers()) {
        Ok(claims) => claims,
        Err(error) => return error.render(crate::api_error::ApiDialect::OpenAi),
    };
    let owner = match ResponseOwner::from_claims(&claims) {
        Ok(owner) => owner,
        Err(error) => return openai_error(StatusCode::FORBIDDEN, "permission_error", &error),
    };
    let Some(namespace) = ResponseNamespace::from_path(uri.path()) else {
        return response_not_found();
    };
    let affinity =
        match state
            .provider_store
            .response_affinities()
            .lookup(namespace, &response_id, &owner)
        {
            Ok(Some(affinity)) => affinity,
            Ok(None) => return response_not_found(),
            Err(error) => return affinity_storage_error(&error),
        };
    let (parts, body) = request.into_parts();
    let body = match axum::body::to_bytes(body, state.max_proxy_request_bytes).await {
        Ok(body) => body,
        Err(error) => {
            return openai_error(
                StatusCode::PAYLOAD_TOO_LARGE,
                "invalid_request_error",
                &format!("request body exceeds the proxy limit: {error}"),
            );
        }
    };
    let upstream_path = upstream_path(&response_id, operation, uri.query());
    let correlation_id = crate::request_log::correlation_id(&parts.headers);
    let outcome = match &affinity.destination {
        AffinityDestination::StoredProvider {
            name,
            provider_kind,
            base_url,
        } => forward_stored_provider(
            &state,
            &claims,
            &parts.method,
            &parts.headers,
            &body,
            uri.path(),
            &upstream_path,
            name,
            *provider_kind,
            base_url,
            &correlation_id,
        )
        .await
        .map(|response| (response, None)),
        AffinityDestination::Subscription {
            provider,
            account,
            upstream_account_id,
            base_url,
        } => forward_subscription(
            &state,
            &claims,
            &parts.method,
            &parts.headers,
            &body,
            uri.path(),
            &upstream_path,
            *provider,
            account,
            upstream_account_id.as_deref(),
            base_url,
            &correlation_id,
        )
        .await
        .map(|response| (response, Some(account.clone()))),
    };
    let (upstream, account) = match outcome {
        Ok(outcome) => outcome,
        Err(response) => return response,
    };
    relay(
        &state,
        affinity,
        operation,
        upstream,
        account.as_deref(),
        body.len() as u64,
        &correlation_id,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
pub(crate) async fn forward_stored_provider(
    state: &AppState,
    claims: &crate::token::TokenClaims,
    method: &Method,
    headers: &HeaderMap,
    body: &Bytes,
    client_path: &crate::translation_core::Str,
    upstream_path: &crate::translation_core::Str,
    name: &crate::translation_core::Str,
    expected_kind: crate::providers::ProviderKind,
    expected_base_url: &crate::translation_core::Str,
    correlation_id: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<reqwest::Response, Response> {
    let provider = state
        .provider_store
        .resolve(name)
        .map_err(|error| unavailable(&format!("provider lookup failed: {error}")))?
        .or_else(|| {
            (state.openai_compatible.provider_name == name)
                .then(|| state.openai_compatible.resolve())
        })
        .filter(|provider| provider.kind == expected_kind && provider.base_url == expected_base_url)
        .ok_or_else(|| unavailable("the response's exact provider is no longer available"))?;
    let (client, _) = crate::client_policy::bound_client(claims)
        .map_err(|error| openai_error(StatusCode::FORBIDDEN, "permission_error", &error))?;
    if !provider.supports_client(client)
        || !crate::client_policy::request_evidence(
            client,
            crate::client_policy::ClientProtocol::OpenAIResponses,
            client_path,
            headers,
        )
    {
        return Err(openai_error(
            StatusCode::FORBIDDEN,
            "permission_error",
            "the stored provider has no tested adapter for this signed client request",
        ));
    }
    let api_key = provider
        .api_key
        .as_deref()
        .ok_or_else(|| unavailable("the response's provider credential is unavailable"))?;
    let client = crate::upstream_client::guarded_provider_client(&state.client, &provider.base_url)
        .map_err(|error| {
            openai_error(
                StatusCode::FORBIDDEN,
                "permission_error",
                &error.to_string(),
            )
        })?;
    let request = client
        .request(
            reqwest::Method::from_bytes(method.as_str().as_bytes())
                .expect("HTTP methods accepted by axum are valid for reqwest"),
            crate::provider_proxy::join_openai_compatible_url(&provider.base_url, upstream_path),
        )
        .headers(crate::proxy::native_request_headers(headers, api_key))
        .body(body.clone());
    state
        .request_log
        .send_upstream(correlation_id, client, request)
        .await
        .map_err(|error| upstream_error(&format!("provider request failed: {error}")))
}

#[allow(clippy::too_many_arguments)]
pub(crate) async fn forward_subscription(
    state: &AppState,
    claims: &crate::token::TokenClaims,
    method: &Method,
    headers: &HeaderMap,
    body: &Bytes,
    client_path: &crate::translation_core::Str,
    upstream_path: &crate::translation_core::Str,
    provider: SubscriptionProvider,
    account: &crate::translation_core::Str,
    expected_account_id: crate::translation_core::Maybe<&crate::translation_core::Str>,
    expected_base_url: &crate::translation_core::Str,
    correlation_id: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<reqwest::Response, Response> {
    crate::client_policy::enforce_subscription_for_claims(
        state,
        claims,
        headers,
        provider,
        crate::client_policy::ClientProtocol::OpenAIResponses,
        client_path,
    )?;
    let pinned = state
        .token_manager
        .account_for(&claims.sub)
        .map_err(|error| unavailable(&format!("failed to resolve account binding: {error}")))?;
    if pinned
        .as_deref()
        .unwrap_or(crate::credential_recovery_store::PRIMARY_ACCOUNT)
        != account
    {
        return Err(response_not_found());
    }
    register_exact_reader(state, provider, account);
    let token = state
        .subscription_cache
        .load_authoritative(provider, account)
        .await
        .map_err(|_| unavailable("the response's exact subscription account is unavailable"))?
        .ok_or_else(|| unavailable("the response's exact subscription account is unavailable"))?;
    let token = state
        .subscription_cache
        .get_fresh_loaded(
            &state.client,
            provider,
            account,
            token,
            crate::operation_context::now().timestamp_millis(),
        )
        .await
        .map_err(|_| unavailable("the response's exact subscription account cannot refresh"))?;
    verify_subscription_destination(
        state,
        provider,
        &token,
        expected_account_id,
        expected_base_url,
    )?;
    let url = crate::subscription_proxy::join_subscription_url(
        provider,
        expected_base_url,
        upstream_path,
    );
    let upstream_client = crate::upstream_client::subscription_client(
        &state.client,
        provider,
        state.subscription_base_url.is_some(),
    );
    let build = |token: &SubscriptionToken| {
        let mut native = crate::proxy::native_request_headers(headers, &token.access_token);
        if provider == SubscriptionProvider::Codex
            && let Some(account_id) = token.account_id.as_deref()
            && let Ok(value) = HeaderValue::from_str(account_id)
        {
            native.insert("chatgpt-account-id", value);
        }
        upstream_client
            .request(
                reqwest::Method::from_bytes(method.as_str().as_bytes())
                    .expect("HTTP methods accepted by axum are valid for reqwest"),
                &url,
            )
            .headers(native)
            .body(body.clone())
    };
    let mut response = state
        .request_log
        .send_upstream(correlation_id, upstream_client, build(&token))
        .await
        .map_err(|error| upstream_error(&format!("subscription request failed: {error}")))?;
    if response.status() == reqwest::StatusCode::UNAUTHORIZED
        && let Some(refreshed) = state
            .subscription_cache
            .refresh_rejected(
                &state.client,
                provider,
                account,
                token,
                crate::operation_context::now().timestamp_millis(),
            )
            .await
    {
        verify_subscription_destination(
            state,
            provider,
            &refreshed,
            expected_account_id,
            expected_base_url,
        )?;
        response = state
            .request_log
            .send_upstream(correlation_id, upstream_client, build(&refreshed))
            .await
            .map_err(|error| upstream_error(&format!("subscription retry failed: {error}")))?;
    }
    Ok(response)
}

pub(crate) fn register_exact_reader(
    state: &AppState,
    provider: SubscriptionProvider,
    account: &crate::translation_core::Str,
) {
    if let Some(router) = state
        .account_router
        .as_ref()
        .filter(|router| router.provider() == provider)
    {
        for (candidate, reader) in router.subscription_readers() {
            if candidate == account {
                state.subscription_cache.register_reader(account, &reader);
            }
        }
    } else if account == crate::credential_recovery_store::PRIMARY_ACCOUNT
        && let Some(reader) = state
            .subscription_readers
            .iter()
            .find(|reader| reader.provider() == provider)
            .or_else(|| {
                state
                    .subscription_reader
                    .as_ref()
                    .filter(|reader| reader.provider() == provider)
            })
    {
        state.subscription_cache.register_reader(account, reader);
    }
}

fn verify_subscription_destination(
    state: &AppState,
    provider: SubscriptionProvider,
    token: &SubscriptionToken,
    expected_account_id: crate::translation_core::Maybe<&crate::translation_core::Str>,
    expected_base_url: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<(), Response> {
    let base_url = state
        .subscription_base_url
        .clone()
        .unwrap_or_else(|| token.base_url(provider));
    if base_url != expected_base_url || token.account_id.as_deref() != expected_account_id {
        return Err(unavailable(
            "the response's exact subscription destination has changed",
        ));
    }
    Ok(())
}

async fn relay(
    state: &AppState,
    affinity: ResponseAffinity,
    operation: Operation,
    upstream: reqwest::Response,
    account: crate::translation_core::Maybe<&crate::translation_core::Str>,
    bytes_sent: u64,
    correlation_id: &crate::translation_core::Str,
) -> Response {
    let status = StatusCode::from_u16(upstream.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let headers = crate::proxy::relay_response_headers(upstream.headers());
    let body = match upstream.bytes().await {
        Ok(body) => body,
        Err(error) => return upstream_error(&format!("upstream body read failed: {error}")),
    };
    state
        .request_log
        .record_upstream_body(correlation_id, &body);
    state.metrics.record_request(
        crate::metrics::Surface::OpenAIResponses,
        status.as_u16(),
        account,
    );
    state.metrics.record_bytes(bytes_sent, body.len() as u64);
    if matches!(status, StatusCode::NOT_FOUND | StatusCode::GONE) {
        let _ = state
            .provider_store
            .response_affinities()
            .remove_if_matches(&affinity);
        return response_not_found();
    }
    if operation == Operation::Delete
        && status.is_success()
        && let Err(error) = state
            .provider_store
            .response_affinities()
            .remove_if_matches(&affinity)
    {
        return affinity_storage_error(&error);
    }
    let mut response = Response::new(Body::from(body));
    *response.status_mut() = status;
    *response.headers_mut() = headers;
    response
}

fn upstream_path(response_id: &crate::translation_core::Str, operation: Operation, query: crate::translation_core::Maybe<&crate::translation_core::Str>) -> String {
    let encoded_id = percent_encode_segment(response_id);
    let query = query.map_or(String::new(), |query| format!("?{query}"));
    format!("/v1/responses/{encoded_id}{}{query}", operation.suffix())
}

pub(crate) fn percent_encode_segment(segment: &crate::translation_core::Str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut encoded = String::with_capacity(segment.len());
    for byte in segment.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            encoded.push(char::from(byte));
        } else {
            encoded.push('%');
            encoded.push(char::from(HEX[(byte >> 4) as usize]));
            encoded.push(char::from(HEX[(byte & 0x0f) as usize]));
        }
    }
    encoded
}

pub(crate) fn response_not_found() -> Response {
    (
        StatusCode::NOT_FOUND,
        axum::Json(crate::translation_core::json!({
            "error": {
                "message": "Response not found",
                "type": "invalid_request_error",
                "param": serde_json::Value::Null,
                "code": "response_not_found",
            }
        })),
    )
        .into_response()
}

fn affinity_storage_error(error: &impl std::fmt::Display) -> Response {
    openai_error(
        StatusCode::SERVICE_UNAVAILABLE,
        "api_error",
        &format!("response affinity is unavailable: {error}"),
    )
}

fn unavailable(message: &crate::translation_core::Str) -> Response {
    openai_error(StatusCode::SERVICE_UNAVAILABLE, "api_error", message)
}

fn upstream_error(message: &crate::translation_core::Str) -> Response {
    openai_error(StatusCode::BAD_GATEWAY, "api_error", message)
}

fn openai_error(status: StatusCode, error_type: &crate::translation_core::Str, message: &crate::translation_core::Str) -> Response {
    crate::api_error::PresentedError {
        status,
        error_type,
        message,
    }
    .render(crate::api_error::ApiDialect::OpenAi)
}

