#[allow(clippy::too_many_arguments)]
pub(super) async fn relay<S>(
    state: &AppState,
    headers: &HeaderMap,
    initial_claims: &crate::token::TokenClaims,
    path: &str,
    target: &UpstreamTarget,
    named_streams: &mut HashSet<String>,
    tracking: &mut TurnTracking,
    mut downstream: WebSocket,
    mut upstream: tokio_tungstenite::WebSocketStream<S>,
) where
    S: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin,
{
    let connection_limit = tokio::time::sleep(MAX_CONNECTION_AGE);
    tokio::pin!(connection_limit);
    loop {
        tokio::select! {
            biased;
            () = &mut connection_limit => {
                let error = websocket_error(
                    StatusCode::BAD_REQUEST,
                    "invalid_request_error",
                    "websocket_connection_limit_reached",
                    "Responses websocket connection limit reached (60 minutes). Create a new websocket connection to continue.",
                    None,
                    None,
                );
                let _ = downstream.send(Message::Text(error.to_string().into())).await;
                let _ = downstream.send(Message::Close(Some(CloseFrame { code: 1000, reason: "connection lifetime reached".into() }))).await;
                let _ = upstream.close(None).await;
                break;
            }
            client_message = downstream.next() => {
                let Some(client_message) = client_message else {
                    let _ = upstream.close(None).await;
                    break;
                };
                let Ok(mut message) = client_message else {
                    let _ = upstream.close(None).await;
                    break;
                };
                if let Message::Text(text) = &message {
                    let bytes = text.as_bytes();
                    let mut value = match serde_json::from_slice::<Value>(bytes) {
                        Ok(value) if value.is_object() => value,
                        _ => {
                            let error = websocket_error(
                                StatusCode::BAD_REQUEST,
                                "invalid_request_error",
                                "invalid_websocket_event",
                                "WebSocket messages must be JSON objects",
                                None,
                                None,
                            );
                            let _ = downstream.send(Message::Text(error.to_string().into())).await;
                            continue;
                        }
                    };
                    if value.get("type").and_then(Value::as_str) == Some("response.create") {
                        match crate::thinking::normalize_request(&mut value, crate::thinking::ThinkingProtocol::OpenAIResponses) {
                            Ok(true) => message = Message::Text(value.to_string().into()),
                            Ok(false) => {},
                            Err(reason) => {
                                let error = websocket_error(StatusCode::BAD_REQUEST, "invalid_request_error", "invalid_thinking_config", &reason, Some("model"), None);
                                let _ = downstream.send(Message::Text(error.to_string().into())).await;
                                continue;
                            }
                        }

                        let lane = match validate_stream_id(&value) {
                            Ok(lane) => lane,
                            Err(error) => {
                                let _ = downstream.send(Message::Text(error.to_string().into())).await;
                                continue;
                            }
                        };
                        if let Some(lane_name) = lane.as_ref()
                            && !named_streams.contains(lane_name)
                            && named_streams.len() >= MAX_NAMED_STREAMS
                        {
                            let error = websocket_error(
                                StatusCode::BAD_REQUEST,
                                "invalid_request_error",
                                "websocket_stream_limit_reached",
                                "This WebSocket connection has reached its maximum number of distinct stream IDs (32). Reuse an existing stream_id or open a new WebSocket connection.",
                                Some("stream_id"),
                                Some(lane_name),
                            );
                            let _ = downstream.send(Message::Text(error.to_string().into())).await;
                            continue;
                        }
                        let claims = match crate::proxy::authenticate_client_error(state, headers) {
                            Ok(claims) if claims.sub == initial_claims.sub => claims,
                            Ok(_) => {
                                let error = websocket_error(
                                    StatusCode::FORBIDDEN,
                                    "authentication_error",
                                    "connection_identity_changed",
                                    "the Router client identity changed during the WebSocket connection",
                                    None,
                                    lane.as_deref(),
                                );
                                fail_and_close(&mut downstream, error, 1008).await;
                                let _ = upstream.close(None).await;
                                break;
                            }
                            Err(error) => {
                                let event = websocket_error(
                                    error.status,
                                    "authentication_error",
                                    "authentication_failed",
                                    &error.message,
                                    None,
                                    lane.as_deref(),
                                );
                                fail_and_close(&mut downstream, event, 1008).await;
                                let _ = upstream.close(None).await;
                                break;
                            }
                        };
                        let model = value.get("model").and_then(Value::as_str).unwrap_or_default();
                        let Ok(policy) = crate::proxy::model_policy_for_claims(state, &claims)
                        else {
                            let denied =
                                crate::model_contract::ModelAccessError::policy_unavailable(model);
                            let error = websocket_error(
                                StatusCode::SERVICE_UNAVAILABLE,
                                "api_error",
                                &denied.code,
                                &denied.to_string(),
                                Some("model"),
                                lane.as_deref(),
                            );
                            let _ = downstream.send(Message::Text(error.to_string().into())).await;
                            continue;
                        };
                        if model.is_empty() && !policy.allowed_models.is_empty() {
                            let error = websocket_error(
                                StatusCode::BAD_REQUEST,
                                "invalid_request_error",
                                "model_required",
                                "a pinned credential requires an explicit model",
                                Some("model"),
                                lane.as_deref(),
                            );
                            let _ = downstream.send(Message::Text(error.to_string().into())).await;
                            continue;
                        }
                        if !policy.permits(model) {
                            let denied =
                                crate::model_contract::ModelAccessError::new(model, &policy);
                            let error = websocket_error(
                                StatusCode::FORBIDDEN,
                                "permission_error",
                                &denied.code,
                                &denied.to_string(),
                                Some("model"),
                                lane.as_deref(),
                            );
                            let _ = downstream.send(Message::Text(error.to_string().into())).await;
                            continue;
                        }
                        if model.is_empty() || !target.allowed_models.iter().any(|candidate| candidate == model) {
                            let error = websocket_error(
                                StatusCode::BAD_REQUEST,
                                "invalid_request_error",
                                "websocket_model_mismatch",
                                "the requested model is not available from this connection's bound provider account",
                                Some("model"),
                                lane.as_deref(),
                            );
                            let _ = downstream.send(Message::Text(error.to_string().into())).await;
                            continue;
                        }
                        let model = model.to_string();
                        match thinking_controls::apply_for_target(state, target, &mut value) {
                            Ok(true) => message = Message::Text(value.to_string().into()),
                            Ok(false) => {},
                            Err(error) => {
                                let _ = downstream.send(Message::Text(error.to_string().into())).await;
                                continue;
                            }
                        }
                        let tracker = match reserve_turn(state, &claims, &value) {
                            Ok(tracker) => tracker,
                            Err(error) => {
                                let _ = downstream.send(Message::Text(error.to_string().into())).await;
                                continue;
                            }
                        };
                        crate::audit::record_authorised_request_with_resolved_model(
                            &target_state(state, target),
                            &claims,
                            Surface::OpenAIResponses,
                            path,
                            Some(&value),
                            Some(&model),
                        );
                        if let Some(lane_name) = lane.as_ref() {
                            named_streams.insert(lane_name.clone());
                        }
                        tracking.push(lane, tracker, target, &value);
                    }
                }
                let closes = matches!(message, Message::Close(_));
                let upstream_message = downstream_to_upstream(message);
                if upstream.send(upstream_message).await.is_err() || closes {
                    break;
                }
            }
            upstream_message = upstream.next() => {
                let Some(upstream_message) = upstream_message else {
                    let _ = downstream.send(Message::Close(Some(CloseFrame { code: 1011, reason: "upstream disconnected".into() }))).await;
                    break;
                };
                let message = match upstream_message {
                    Ok(message) => message,
                    Err(error) => {
                        let event = websocket_error(
                            StatusCode::BAD_GATEWAY,
                            "api_error",
                            "websocket_upstream_error",
                            &format!("upstream WebSocket failed: {error}"),
                            None,
                            None,
                        );
                        let _ = downstream.send(Message::Text(event.to_string().into())).await;
                        let _ = downstream.send(Message::Close(Some(CloseFrame { code: 1011, reason: "upstream WebSocket failed".into() }))).await;
                        break;
                    }
                };
                if let tungstenite::Message::Text(text) = &message
                    && let Ok(value) = serde_json::from_slice::<Value>(text.as_bytes())
                {
                    tracking.feed_terminal(&value, text.as_bytes());
                }
                let closes = matches!(message, tungstenite::Message::Close(_));
                if downstream.send(upstream_to_downstream(message)).await.is_err() || closes {
                    break;
                }
            }
        }
    }
}

//! Thinking controls use the connection's selected account on every turn.
use axum::http::StatusCode;
use serde_json::Value;

use super::{AppState, UpstreamTarget, stream_id, websocket_error};
use crate::subscription::SubscriptionProvider;
use crate::thinking::ThinkingProtocol;

#[derive(Debug)]
pub(super) struct AccountScope {
    pub(super) account: String,
    pub(super) base_url: String,
}

pub(super) fn apply_for_target(
    state: &AppState,
    target: &UpstreamTarget,
    event: &mut Value,
) -> Result<bool, Value> {
    let Some(scope) = target.thinking_account.as_ref() else {
        return Ok(false);
    };
    let model = event
        .get("model")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    crate::thinking::apply_for_account(
        state,
        event,
        &model,
        SubscriptionProvider::Codex,
        &scope.account,
        &scope.base_url,
        ThinkingProtocol::Codex,
        ThinkingProtocol::OpenAIResponses,
        false,
    )
    .map_err(|reason| {
        websocket_error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "invalid_thinking_config",
            &reason,
            Some("model"),
            stream_id(event).as_deref(),
        )
    })
}

pub(super) fn parse_create_event(bytes: &[u8]) -> Result<Value, Value> {
    let mut value = serde_json::from_slice::<Value>(bytes).map_err(|_| {
        websocket_error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "invalid_websocket_event",
            "the first WebSocket message must be valid JSON",
            None,
            None,
        )
    })?;
    if !value.is_object() || value.get("type").and_then(Value::as_str) != Some("response.create") {
        return Err(websocket_error(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "invalid_websocket_event",
            "the first WebSocket message must be a response.create event",
            Some("type"),
            stream_id(&value).as_deref(),
        ));
    }
    crate::thinking::normalize_request(&mut value, ThinkingProtocol::OpenAIResponses).map_err(
        |reason| {
            websocket_error(
                StatusCode::BAD_REQUEST,
                "invalid_request_error",
                "invalid_websocket_event",
                &reason,
                Some("model"),
                stream_id(&value).as_deref(),
            )
        },
    )?;
    Ok(value)
}

//! Per-lane usage and cooldown observation for accepted WebSocket turns.
use super::{UpstreamTarget, Value};
use std::collections::{HashMap, VecDeque};

pub(super) struct TurnTracking {
    by_lane: HashMap<
        Option<String>,
        VecDeque<(
            crate::usage::UsageTracker,
            Option<crate::pool_stream_limits::StreamLimits>,
        )>,
    >,
}

impl TurnTracking {
    pub(super) fn new() -> Self {
        Self {
            by_lane: HashMap::new(),
        }
    }

    pub(super) fn push(
        &mut self,
        lane: Option<String>,
        tracker: crate::usage::UsageTracker,
        target: &UpstreamTarget,
        event: &Value,
    ) {
        let observer = target.pool.as_ref().map(|(router, account)| {
            crate::pool_stream_limits::StreamLimits::new(
                router.clone(),
                account.clone(),
                event
                    .get("model")
                    .and_then(Value::as_str)
                    .map(str::to_string),
            )
        });
        self.by_lane
            .entry(lane)
            .or_default()
            .push_back((tracker, observer));
    }

    pub(super) fn feed_terminal(&mut self, value: &Value, bytes: &[u8]) {
        let event_type = value
            .get("type")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if !matches!(
            event_type,
            "response.completed" | "response.incomplete" | "response.failed" | "error"
        ) {
            return;
        }
        let lane = value
            .get("stream_id")
            .and_then(Value::as_str)
            .map(str::to_string);
        let remove_lane = self.by_lane.get_mut(&lane).is_some_and(|queue| {
            if let Some((mut tracker, observer)) = queue.pop_front() {
                tracker.feed(bytes);
                if let Some(observer) = observer {
                    observer.observe_event(value);
                }
            }
            queue.is_empty()
        });
        if remove_lane {
            self.by_lane.remove(&lane);
        }
    }
}

