async fn authenticate_client_route(
    State(state): State<AppState>,
    request: Request,
    next: Next,
) -> Response {
    let path = request.uri().path();
    if crate::codex_remote_control::authenticates_continuation(request.method(), path) {
        return next.run(request).await;
    }
    if is_openai_payment_path(path)
        && let Some(response) = proxy::maybe_mpp_challenge(&state, request.headers(), path)
    {
        return response;
    }
    if let Err(error) = proxy::authenticate_client_error(&state, request.headers()) {
        return error.render(crate::api_error::dialect_for_path(path));
    }
    next.run(request).await
}

async fn authenticate_inference_route(
    State((state, anthropic_enabled)): State<(AppState, bool)>,
    request: Request,
    next: Next,
) -> Response {
    let path = request.uri().path();
    if !anthropic_enabled
        && route_for_path(request.method(), path)
            .is_some_and(|route| route.id == RouteId::AnthropicVertex)
    {
        return not_found().await;
    }
    authenticate_client_route(State(state), request, next).await
}

fn is_openai_payment_path(path: &crate::translation_core::Str) -> bool {
    route_for_path(&axum::http::Method::POST, path).is_some_and(|spec| {
        matches!(
            spec.id,
            RouteId::OpenAiChatCompletions
                | RouteId::OpenAiResponses
                | RouteId::CodexChatCompletions
                | RouteId::CodexResponses
                | RouteId::QwenChatCompletions
                | RouteId::QwenResponses
        )
    })
}

async fn not_found() -> Response {
    proxy::error_response(StatusCode::NOT_FOUND, "not_found_error", "route not found")
}

async fn vertex_proxy_handler(State(state): State<AppState>, request: Request) -> Response {
    let path = request.uri().path();
    let model_action = path
        .split_once("/publishers/anthropic/models/")
        .map(|(_, action)| action)
        .unwrap_or_default();
    let direct = !model_action.contains('/')
        && (model_action
            .strip_suffix(":rawPredict")
            .is_some_and(|model| !model.is_empty())
            || model_action
                .strip_suffix(":streamRawPredict")
                .is_some_and(|model| !model.is_empty()));
    let count_tokens = model_action
        .strip_suffix("/count-tokens:rawPredict")
        .is_some_and(|model| !model.is_empty() && !model.contains('/'));
    if !direct && !count_tokens {
        return not_found().await;
    }
    proxy::proxy_handler(State(state), request).await
}

//! Byte-safe incremental Server-Sent Events framing.

/// Append one arbitrary transport chunk and return every complete SSE block.
///
/// Transport chunks may split a multi-byte UTF-8 scalar. Keeping the pending
/// tail as bytes ensures conversion happens only after a complete SSE block is
/// available, so a valid event cannot acquire replacement characters merely
/// because of a network boundary.
pub fn push_blocks(buffer: &mut Vec<u8>, chunk: &[u8]) -> Vec<String> {
    buffer.extend_from_slice(chunk);
    let mut blocks = Vec::new();
    while let Some((index, separator_len)) = find_separator(buffer) {
        let block = buffer.drain(..index).collect::<Vec<_>>();
        buffer.drain(..separator_len);
        blocks.push(String::from_utf8_lossy(&block).into_owned());
    }
    blocks
}

fn find_separator(buffer: &[u8]) -> crate::translation_core::Maybe<(usize, usize)> {
    let crlf = buffer.windows(4).position(|window| window == b"\r\n\r\n");
    let lf = buffer.windows(2).position(|window| window == b"\n\n");
    match (crlf, lf) {
        (Some(left), Some(right)) if left <= right => Some((left, 4)),
        (Some(_), Some(right)) => Some((right, 2)),
        (Some(index), None) => Some((index, 4)),
        (None, Some(index)) => Some((index, 2)),
        (None, None) => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_multibyte_scalar_split_across_chunks_is_decoded_once_complete() {
        let frame = "data: {\"delta\":\"世\"}\n\n".as_bytes();
        let character = frame.iter().position(|byte| *byte == 0xe4).unwrap();
        for split in [character + 1, character + 2] {
            let mut buffer = Vec::new();
            assert!(push_blocks(&mut buffer, &frame[..split]).is_empty());
            let blocks = push_blocks(&mut buffer, &frame[split..]);
            assert_eq!(blocks, ["data: {\"delta\":\"世\"}"]);
            assert!(!blocks[0].contains('\u{fffd}'));
        }
    }
}

//! Local stop-sequence enforcement for backends that cannot accept `stop`.

use serde_json::Value;

/// Incremental matcher that withholds only the tail which might begin a stop
/// sequence, so a match split across arbitrary SSE chunks is never leaked.
#[derive(Clone, Debug, Default)]
pub struct StopSequenceFilter {
    sequences: Vec<String>,
    pending: String,
    stopped: bool,
}

impl StopSequenceFilter {
    #[must_use]
    pub fn new(sequences: Vec<String>) -> Self {
        Self {
            sequences: sequences
                .into_iter()
                .filter(|sequence| !sequence.is_empty())
                .collect(),
            pending: String::new(),
            stopped: false,
        }
    }

    #[must_use]
    pub const fn enabled(&self) -> bool {
        !self.sequences.is_empty()
    }

    /// Return safe visible text and the matched sequence, if this chunk stops
    /// generation. Calls after a match return no text.
    pub fn push(&mut self, text: &crate::translation_core::Str) -> (String, crate::translation_core::Maybe<String>) {
        if self.stopped {
            return (String::new(), None);
        }
        self.pending.push_str(text);
        let matched = self
            .sequences
            .iter()
            .filter_map(|sequence| self.pending.find(sequence).map(|index| (index, sequence)))
            .min_by_key(|(index, _)| *index)
            .map(|(index, sequence)| (index, sequence.clone()));
        if let Some((index, sequence)) = matched {
            let visible = self.pending[..index].to_string();
            self.pending.clear();
            self.stopped = true;
            return (visible, Some(sequence));
        }

        let retain = self
            .pending
            .char_indices()
            .map(|(index, _)| &self.pending[index..])
            .chain(std::iter::once(self.pending.as_str()))
            .filter(|suffix| {
                !suffix.is_empty()
                    && self
                        .sequences
                        .iter()
                        .any(|sequence| sequence.starts_with(*suffix))
            })
            .map(str::len)
            .max()
            .unwrap_or(0);
        let split = self.pending.len() - retain;
        let visible = self.pending[..split].to_string();
        self.pending.drain(..split);
        (visible, None)
    }

    /// Flush withheld text when generation finishes without a match.
    pub fn finish(&mut self) -> String {
        if self.stopped {
            return String::new();
        }
        std::mem::take(&mut self.pending)
    }
}

#[must_use]
pub fn from_value(value: crate::translation_core::Maybe<&crate::translation_core::Json>) -> Vec<String> {
    match value {
        Some(Value::String(sequence)) => vec![sequence.clone()],
        Some(Value::Array(sequences)) => sequences
            .iter()
            .filter_map(Value::as_str)
            .map(str::to_string)
            .collect(),
        _ => Vec::new(),
    }
}

/// Apply stop semantics to a buffered string and return the matched sequence.
pub fn truncate(text: &mut String, sequences: &[String]) -> Option<String> {
    let (index, sequence) = sequences
        .iter()
        .filter(|sequence| !sequence.is_empty())
        .filter_map(|sequence| text.find(sequence).map(|index| (index, sequence)))
        .min_by_key(|(index, _)| *index)?;
    text.truncate(index);
    Some(sequence.clone())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_a_stop_split_across_chunks_without_leaking_its_prefix() {
        let mut filter = StopSequenceFilter::new(vec!["<END>".into()]);
        assert_eq!(filter.push("hello <E"), ("hello ".into(), None));
        assert_eq!(
            filter.push("ND> ignored"),
            (String::new(), Some("<END>".into()))
        );
        assert_eq!(filter.push("more"), (String::new(), None));
        assert!(filter.finish().is_empty());
    }

    #[test]
    fn unicode_tail_is_held_on_a_character_boundary() {
        let mut filter = StopSequenceFilter::new(vec!["終わり".into()]);
        let (visible, matched) = filter.push("回答は終");
        assert_eq!(visible, "回答は");
        assert!(matched.is_none());
        let (visible, matched) = filter.push("わり後");
        assert!(visible.is_empty());
        assert_eq!(matched.as_deref(), Some("終わり"));
    }
}

//! Token persistence backends.
//!
//! Issued-token state can be persisted as real Links Notation text, a native
//! file-mapped doublets links network, or both.
//!
//! This module provides:
//!
//! - The [`TokenStore`] trait — a small async-ish (sync, for now) API for
//!   listing, persisting, and revoking [`TokenRecord`]s.
//! - [`MemoryTokenStore`] — an in-memory implementation, used in tests and
//!   for [`StoragePolicy::Memory`].
//! - [`TextTokenStore`] — persists records through `lino-objects-codec` at
//!   `<data_dir>/tokens.lino`.
//! - [`BinaryTokenStore`] — persists the same `Type → SubType → Value` links network
//!   in a `doublets` store backed by `link-cli`'s `PersistentFileMapped` at
//!   `<data_dir>/tokens.bin`.
//! - [`DualTokenStore`] — fans writes out to two stores (typically text +
//!   binary) and reads from the *first* store, falling back to the second
//!   on miss. This is the default when [`StoragePolicy::Both`] is set.
//! - [`build_token_store`] — factory that picks the right combination of
//!   stores based on the [`StoragePolicy`] from configuration.
//!
//! All persistence operations are best-effort: failures are surfaced as
//! [`StorageError`] but never panic, and all read paths gracefully tolerate
//! missing files (returning an empty record set).

// We intentionally hold a write guard across the (insert + flush) pair for
// atomicity; clippy's `significant_drop_tightening` would push us into
// chained calls that lose readability without helping contention in practice.
#![allow(clippy::significant_drop_tightening)]

use std::collections::HashMap;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, RwLock};

use serde::{Deserialize, Serialize};

use crate::config::StoragePolicy;

mod associative;
mod associative_text;
mod file_mapped;
mod legacy;
mod model_policy;

/// One persisted token record.
///
/// `id` is the JWT `sub` (a UUID); the JWT itself is NOT stored — only the
/// metadata required to list/expire/revoke.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, schemars::JsonSchema)]
pub struct TokenRecord {
    pub id: String,
    pub label: String,
    pub issued_at: i64,
    pub expires_at: i64,
    pub revoked: bool,
    /// Whether this credential belongs only to a wrapper run.
    ///
    /// Dead ephemeral records are compacted as part of the next issuance so
    /// repeated `router with` runs cannot grow durable storage forever.
    #[serde(default)]
    pub ephemeral: bool,
    /// Expiry of the wrapper process's renewable liveness lease.
    ///
    /// `None` is deliberately not treated as live: records written before run
    /// leases existed cannot prove whether their wrapper still exists.
    #[serde(default)]
    pub run_lease_expires_at: Option<i64>,
    /// How long, in seconds, an active token's expiry slides ahead of now.
    ///
    /// `None` is a fixed clock: the expiry set at issue time is final, which
    /// is what every token did before. `Some(window)` means a request served
    /// with this token pushes `expires_at` to `now + window`, so a session in
    /// continuous use never expires while one abandoned for longer than the
    /// window still does -- which is the behaviour the bound is for. A
    /// day-long session died mid-work against the fixed 24-hour clock twice
    /// (issue #354).
    #[serde(default)]
    pub sliding_window_seconds: Option<i64>,
    /// Optional account identifier the token is bound to (multi-account mode).
    #[serde(default)]
    pub account: Option<String>,
    /// Optional cap on the number of upstream requests this token may make.
    /// `None` means unlimited. Used to bound how much a task can consume.
    #[serde(default)]
    pub max_requests: Option<u64>,
    /// Number of upstream requests already made with this token.
    #[serde(default)]
    pub used_requests: u64,
    /// Optional cap on tokens reported by successful upstream responses.
    /// `None` means unlimited.
    #[serde(default)]
    pub max_tokens: Option<u64>,
    /// Total input and output tokens reported for this credential.
    #[serde(default)]
    pub used_tokens: u64,
    /// Tokens reserved by requests that have been admitted but have not yet
    /// reported their actual usage.
    ///
    /// A hard `max_tokens` cap cannot be enforced from `used_tokens` alone:
    /// usage is only known *after* a response completes, so a single large
    /// answer could push the persisted total arbitrarily far past the cap
    /// (issue #195). Admission therefore reserves the request's declared output
    /// budget up front and counts it against the cap; settlement swaps the
    /// reservation for the real figure. Requests still in flight after a crash
    /// leave a stale reservation, which [`TokenStore::release_stale_reservations`]
    /// clears.
    #[serde(default)]
    pub reserved_tokens: u64,
    /// Optional fixed-window request rate limit. `None` means unlimited.
    #[serde(default)]
    pub rate_limit_per_minute: Option<u64>,
    /// Unix timestamp at which the current rate-limit window began.
    #[serde(default)]
    pub rate_window_started_at: i64,
    /// Requests admitted during the current rate-limit window.
    #[serde(default)]
    pub rate_window_requests: u64,
    /// Privilege scope carried by the token. Empty (the default) means an
    /// ordinary client token that may only proxy inference; `"admin"` marks a
    /// credential that also unlocks the administrative endpoints. See
    /// [`crate::token::ADMIN_SCOPE`].
    #[serde(default)]
    pub scope: String,
    /// Repositories this token may reach through the GitHub proxy; empty is
    /// unrestricted (issue #262).
    ///
    /// `serde(default)` so a store written before this field keeps loading,
    /// and an existing token keeps the access it was issued with.
    #[serde(default)]
    pub github_repos: Vec<String>,
    /// Canonical managed client adapter; absent on legacy/manual tokens.
    #[serde(default)]
    pub client_kind: Option<String>,
    /// Subscriber identity paired with `client_kind`.
    #[serde(default)]
    pub principal_id: Option<String>,
    /// Exact model authority attached to this credential. Empty is the
    /// backwards-compatible unpinned policy used by manually issued tokens.
    #[serde(default)]
    pub model_policy: crate::model_contract::ModelAccessPolicy,
}

/// Errors a [`TokenStore`] can return.
#[derive(Debug)]
pub enum StorageError {
    Io(io::Error),
    Codec(String),
    Capacity(String),
    LockPoisoned,
}

impl std::fmt::Display for StorageError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Io(e) => write!(f, "storage I/O error: {e}"),
            Self::Codec(msg) => write!(f, "storage codec error: {msg}"),
            Self::Capacity(msg) => write!(f, "storage capacity error: {msg}"),
            Self::LockPoisoned => write!(f, "storage lock poisoned"),
        }
    }
}

impl std::error::Error for StorageError {}

impl From<io::Error> for StorageError {
    fn from(e: io::Error) -> Self {
        Self::Io(e)
    }
}

/// Persistent token store API.
///
/// Implementations must be cheap to clone (use `Arc` internally) — the
/// router shares them across handler tasks.
pub trait TokenStore: Send + Sync {
    fn list(&self) -> Result<Vec<TokenRecord>, StorageError>;
    fn get(&self, id: &str) -> Result<Option<TokenRecord>, StorageError>;
    fn put(&self, record: TokenRecord) -> Result<(), StorageError>;
    fn delete(&self, id: &str) -> Result<bool, StorageError>;
    /// Insert `record` while removing expired or revoked wrapper credentials.
    ///
    /// Persistent implementations override this so pruning and insertion are
    /// one durable mutation. The default keeps third-party stores compatible.
    fn put_compacting_ephemeral(&self, record: TokenRecord, now: i64) -> Result<(), StorageError> {
        for stale in self
            .list()?
            .into_iter()
            .filter(|held| held.ephemeral && (held.revoked || held.expires_at <= now))
        {
            self.delete(&stale.id)?;
        }
        self.put(record)
    }
    fn revoke(&self, id: &str) -> Result<bool, StorageError> {
        if let Some(mut rec) = self.get(id)? {
            if rec.revoked {
                return Ok(false);
            }
            rec.revoked = true;
            self.put(rec)?;
            return Ok(true);
        }
        Ok(false)
    }
    fn revoked_ids(&self) -> Result<Vec<String>, StorageError> {
        Ok(self
            .list()?
            .into_iter()
            .filter(|r| r.revoked)
            .map(|r| r.id)
            .collect())
    }

    /// Renew an existing wrapper lease without creating one on a legacy token.
    fn renew_run_lease(
        &self,
        id: &str,
        now: i64,
        ttl_seconds: i64,
    ) -> Result<Option<i64>, StorageError> {
        let Some(mut record) = self.get(id)? else {
            return Ok(None);
        };
        let renewed = advance_run_lease(Some(&mut record), now, ttl_seconds);
        if renewed.is_some() {
            self.put(record)?;
        }
        Ok(renewed)
    }

    /// Atomically check the request budget for `id` and, when there is room,
    /// increment the used-request counter.
    ///
    /// Returns `Ok(true)` when the request is permitted (and was recorded),
    /// or `Ok(false)` when the token is already at or over its `max_requests`
    /// budget. Tokens that have no stored record, or whose record has no
    /// limit (`max_requests == None`), are always permitted.
    ///
    /// Note: the default implementation performs a `get` then a `put`, which
    /// is not strictly atomic across concurrent callers, so a small number of
    /// requests may slip over the limit under heavy parallelism. This is an
    /// acceptable trade-off for a per-task usage cap; backends that need exact
    /// enforcement can override this with a locked read-modify-write.
    fn try_consume_request(&self, id: &str) -> Result<bool, StorageError> {
        if let Some(mut rec) = self.get(id)? {
            if let Some(max) = rec.max_requests
                && rec.used_requests >= max
            {
                return Ok(false);
            }
            rec.used_requests = rec.used_requests.saturating_add(1);
            self.put(rec)?;
        }
        Ok(true)
    }

    /// Atomically enforce every pre-request limit and record an admitted call.
    fn try_admit_request(&self, id: &str, now: i64) -> Result<RequestAdmission, StorageError> {
        self.try_admit_request_reserving(id, now, 0)
    }

    /// Atomically enforce every pre-request limit, reserving `reserve` tokens of
    /// spend budget for the admitted call.
    ///
    /// Every admitted request must later be settled with
    /// [`TokenStore::settle_token_usage`] so the reservation is released.
    fn try_admit_request_reserving(
        &self,
        id: &str,
        now: i64,
        reserve: u64,
    ) -> Result<RequestAdmission, StorageError> {
        let Some(mut record) = self.get(id)? else {
            return Ok(RequestAdmission::Admitted);
        };
        let admission = admit_request_reserving(Some(&mut record), now, reserve);
        if admission == RequestAdmission::Admitted {
            self.put(record)?;
        }
        Ok(admission)
    }

    /// Add actual input and output usage reported by an upstream response.
    fn record_token_usage(&self, id: &str, tokens: u64) -> Result<(), StorageError> {
        if let Some(mut record) = self.get(id)? {
            record.used_tokens = record.used_tokens.saturating_add(tokens);
            self.put(record)?;
        }
        Ok(())
    }

    /// Release `reserved` tokens of budget and record `actual` usage in one step.
    fn settle_token_usage(&self, id: &str, reserved: u64, actual: u64) -> Result<(), StorageError> {
        if let Some(mut record) = self.get(id)? {
            settle_token_usage(Some(&mut record), reserved, actual);
            self.put(record)?;
        }
        Ok(())
    }

    /// Clear reservations left behind by requests that never settled.
    ///
    /// A process that dies mid-request leaves its reservation pinned against the
    /// cap forever, which would eventually reject every subsequent request. The
    /// router calls this once at startup, when by definition nothing is in flight.
    fn release_stale_reservations(&self) -> Result<usize, StorageError> {
        let mut cleared = 0;
        for mut record in self.list()? {
            if record.reserved_tokens > 0 {
                record.reserved_tokens = 0;
                self.put(record)?;
                cleared += 1;
            }
        }
        Ok(cleared)
    }
}

