//! Links Notation document framing for the associative token representation.

use lino_objects_codec::LinoValue;

use super::TokenRecord;
use super::associative::{
    expect_string_field, object_field, record_from_lino_value, record_to_lino_value,
};

pub(super) fn encode_text<'a>(records: impl IntoIterator<Item = &'a TokenRecord>) -> String {
    let records = records
        .into_iter()
        .map(record_to_lino_value)
        .collect::<Vec<_>>();
    lino_objects_codec::encode(&LinoValue::object([
        ("type", LinoValue::String("RouterState".into())),
        ("subtype", LinoValue::String("TokenStore".into())),
        ("value", LinoValue::Array(records)),
    ]))
}

pub(super) fn decode_text(input: &str) -> Result<Vec<TokenRecord>, String> {
    let root = lino_objects_codec::decode(input).map_err(|error| error.to_string())?;
    expect_string_field(&root, "type", "token store")?
        .eq("RouterState")
        .then_some(())
        .ok_or_else(|| "token store type must be RouterState".to_string())?;
    expect_string_field(&root, "subtype", "token store")?
        .eq("TokenStore")
        .then_some(())
        .ok_or_else(|| "token store subtype must be TokenStore".to_string())?;
    let records = object_field(&root, "value", "token store")?;
    let LinoValue::Array(records) = records else {
        return Err("token store value must be an array".into());
    };
    records.iter().map(record_from_lino_value).collect()
}

//! Capacity-preserving file mapping for the doublets token store.
//!
//! Split from `associative.rs` to keep that file within the repository's
//! 1000-line limit.

use std::mem::{MaybeUninit, size_of};

use doublets::mem::RawMem;
use doublets::mem::unit::LinkPart;
use link_cli::storage::PersistentFileMapped;

use super::StorageError;

/// Number of items `unit::Store` bootstraps with before it sizes itself.
#[cfg(test)]
const DOUBLETS_BOOTSTRAP_ITEMS: usize = 8 * 1024;

/// A mapping that keeps the capacity an existing file already represents.
///
/// `FileMapped` starts with a logical capacity of zero however much the file
/// holds, so `unit::Store::new` reads only a small prefix of an existing links
/// network. Schema validation then fails at the first point past the truncation
/// with "doublets schema contains an invalid point". Reads still answer -- the
/// dual store falls back to the text projection -- so the store can look
/// healthy while every write fails (issue #374).
///
/// Three things are needed, and `PersistentFileMapped` alone provides none of
/// them:
///
/// * the capacity has to be adopted without writing over the persisted bytes,
///   which `grow_filled` does not do -- despite its documentation it fills the
///   whole region and empties the store (link-foundation/link-cli#102);
/// * `grow` must return the complete allocation, because that is what
///   `doublets` re-derives its pointers from, not just the new tail;
/// * the store's initial bootstrap `shrink` has to be refused once, or it
///   discards the capacity that was just adopted.
pub(super) struct LoadedFileMapped {
    inner: PersistentFileMapped<LinkPart<usize>>,
    minimum_capacity: usize,
}

impl LoadedFileMapped {
    pub(super) fn new(file: std::fs::File) -> Result<Self, StorageError> {
        let bytes = usize::try_from(file.metadata()?.len())
            .map_err(|_| std::io::Error::other("mapped file is too large for this platform"))?;
        if bytes % size_of::<LinkPart<usize>>() != 0 && bytes >= 4096 {
            return Err(StorageError::Codec(
                "mapped file length is not aligned to a doublets link part".into(),
            ));
        }
        let mut inner = PersistentFileMapped::new(file)?;
        let items = bytes.max(4096) / size_of::<LinkPart<usize>>();
        // SAFETY: `grow_assumed` requires the grown region to be initialised.
        // It is: these bytes were written as `LinkPart<usize>` values by a
        // doublets store on this platform, and `LinkPart<usize>` is `repr(C)`
        // over `usize` fields, so every bit pattern is valid. Its fill closure
        // writes nothing, so no persisted byte is touched.
        #[allow(unsafe_code)]
        unsafe {
            inner
                .grow_assumed(items)
                .map_err(|error| StorageError::Codec(format!("restore capacity: {error}")))?;
        }
        Ok(Self {
            inner,
            minimum_capacity: items,
        })
    }
}

impl RawMem for LoadedFileMapped {
    type Item = LinkPart<usize>;

    fn allocated(&self) -> &[Self::Item] {
        self.inner.allocated()
    }

    fn allocated_mut(&mut self) -> &mut [Self::Item] {
        self.inner.allocated_mut()
    }

    #[allow(unsafe_code)]
    unsafe fn grow(
        &mut self,
        addition: usize,
        fill: impl FnOnce(usize, (&mut [Self::Item], &mut [MaybeUninit<Self::Item>])),
    ) -> doublets::mem::Result<&mut [Self::Item]> {
        // SAFETY: the caller supplies the initialisation callback `RawMem`
        // requires, and the wrapped mapping enforces the same contract.
        unsafe {
            self.inner.grow(addition, fill)?;
        }
        // The mapping returns only the newly grown tail; `doublets` expects the
        // complete allocation when it refreshes its internal pointers.
        Ok(self.inner.allocated_mut())
    }

    fn shrink(&mut self, count: usize) -> doublets::mem::Result<()> {
        // `LinksHeader::allocated` is the highest live address, not a count.
        // During initialization doublets first asks to shrink a loaded mapping
        // to its bootstrap page and then to `allocated`; satisfying the second
        // request discards the live slot at that inclusive address. Preserve
        // every element represented by the existing file. Rebuilds compact by
        // constructing a fresh mapping, so an opened store never needs to
        // shrink below this floor (issue #557).
        if self.inner.allocated().len().saturating_sub(count) < self.minimum_capacity {
            return Ok(());
        }
        self.inner.shrink(count)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Reopening a doublets file performs two initialization shrinks: first to
    /// the bootstrap page, then to the highest allocated address. The latter
    /// address is inclusive, so allowing either shrink discards live storage
    /// and leaves a tree pointer exactly one past the mapping (issue #557).
    #[test]
    fn an_existing_mapping_never_shrinks_below_its_file_capacity() {
        let directory = tempfile::tempdir().expect("temporary directory");
        let path = directory.path().join("tokens.bin");
        let existing_items = DOUBLETS_BOOTSTRAP_ITEMS + 37;
        let file = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create_new(true)
            .open(&path)
            .expect("create mapping");
        file.set_len((existing_items * size_of::<LinkPart<usize>>()) as u64)
            .expect("size mapping");

        let mut mapping = LoadedFileMapped::new(file).expect("load mapping");
        mapping
            .shrink(existing_items - DOUBLETS_BOOTSTRAP_ITEMS)
            .expect("ignore bootstrap shrink");
        mapping.shrink(1).expect("ignore inclusive-address shrink");

        assert_eq!(
            mapping.allocated().len(),
            existing_items,
            "initialization must retain the slot at the highest allocated address"
        );
        assert_eq!(
            std::fs::metadata(path).expect("mapping metadata").len(),
            (existing_items * size_of::<LinkPart<usize>>()) as u64
        );
    }
}

use std::fs;
use std::io::{self, Read};
use std::path::Path;

use super::{StorageError, TokenRecord};

pub(super) const BIN_MAGIC: &[u8; 8] = b"LARTOK01";

pub(super) fn is_binary(path: &Path) -> Result<bool, StorageError> {
    // Too short to carry the magic, so it is not a legacy file. It used to be
    // reported as one, which was harmless while a store only ever appeared
    // fully built -- the old writer renamed a finished temporary into place.
    // A store that is created empty and filled in has a moment of being zero
    // bytes, and a concurrent reader that saw it then decoded it as legacy and
    // failed with "invalid legacy binary magic header" (issue #357).
    if fs::metadata(path)?.len() < BIN_MAGIC.len() as u64 {
        return Ok(false);
    }
    let mut file = fs::File::open(path)?;
    let mut magic = [0u8; 8];
    file.read_exact(&mut magic)?;
    Ok(&magic == BIN_MAGIC)
}

pub(super) fn decode_binary(path: &Path) -> Result<Vec<TokenRecord>, StorageError> {
    let mut file = fs::File::open(path)?;
    let mut magic = [0u8; 8];
    if let Err(error) = file.read_exact(&mut magic) {
        if error.kind() == io::ErrorKind::UnexpectedEof {
            return Ok(Vec::new());
        }
        return Err(error.into());
    }
    if &magic != BIN_MAGIC {
        return Err(StorageError::Codec(
            "invalid legacy binary magic header".into(),
        ));
    }
    let mut records = Vec::new();
    loop {
        let mut len = [0u8; 4];
        match file.read_exact(&mut len) {
            Ok(()) => {}
            Err(error) if error.kind() == io::ErrorKind::UnexpectedEof => break,
            Err(error) => return Err(error.into()),
        }
        let mut data = vec![0u8; u32::from_le_bytes(len) as usize];
        file.read_exact(&mut data)?;
        records.push(
            serde_json::from_slice(&data)
                .map_err(|error| StorageError::Codec(error.to_string()))?,
        );
    }
    Ok(records)
}

pub(super) fn decode_text(input: &str) -> Result<Vec<TokenRecord>, String> {
    let mut records = Vec::new();
    for raw in input.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        records.push(parse_record_line(line)?);
    }
    Ok(records)
}

fn parse_record_line(line: &str) -> Result<TokenRecord, String> {
    let inner = line
        .strip_prefix('(')
        .and_then(|value| value.strip_suffix(')'))
        .ok_or_else(|| format!("expected parens around record: {line}"))?
        .trim();
    let mut tokens = LinoTokens::new(inner);
    let kind = tokens
        .next_atom()
        .ok_or_else(|| "missing record kind".to_string())?;
    if kind != "token" {
        return Err(format!("unexpected record kind: {kind}"));
    }
    let id = tokens
        .next_atom()
        .ok_or_else(|| "missing token id".to_string())?
        .to_string();
    let mut record = TokenRecord {
        id,
        github_repos: Vec::new(),
        sliding_window_seconds: None,
        label: String::new(),
        issued_at: 0,
        expires_at: 0,
        revoked: false,
        ephemeral: false,
        run_lease_expires_at: None,
        account: None,
        max_requests: None,
        used_requests: 0,
        max_tokens: None,
        used_tokens: 0,
        reserved_tokens: 0,
        rate_limit_per_minute: None,
        rate_window_started_at: 0,
        rate_window_requests: 0,
        scope: String::new(),
        client_kind: None,
        principal_id: None,
        model_policy: crate::model_contract::ModelAccessPolicy::default(),
    };
    while let Some(field) = tokens.next_paren_group() {
        parse_field(&mut record, field)?;
    }
    Ok(record)
}

fn parse_field(record: &mut TokenRecord, field: &str) -> Result<(), String> {
    let mut tokens = LinoTokens::new(field);
    let key = tokens
        .next_atom()
        .ok_or_else(|| "field missing key".to_string())?;
    match key {
        "label" => record.label = required_string(&mut tokens, key)?,
        "issued_at" => record.issued_at = required_number(&mut tokens, key)?,
        "expires_at" => record.expires_at = required_number(&mut tokens, key)?,
        "revoked" => {
            let value = required_atom(&mut tokens, key)?;
            record.revoked = matches!(value, "true" | "1" | "yes");
        }
        "run_lease_expires_at" => {
            record.run_lease_expires_at = Some(required_number(&mut tokens, key)?);
        }
        "account" => record.account = tokens.next_string(),
        "max_requests" => record.max_requests = Some(required_number(&mut tokens, key)?),
        "used_requests" => record.used_requests = required_number(&mut tokens, key)?,
        "max_tokens" => record.max_tokens = Some(required_number(&mut tokens, key)?),
        "used_tokens" => record.used_tokens = required_number(&mut tokens, key)?,
        "reserved_tokens" => record.reserved_tokens = required_number(&mut tokens, key)?,
        "rate_limit_per_minute" => {
            record.rate_limit_per_minute = Some(required_number(&mut tokens, key)?);
        }
        "rate_window_started_at" => {
            record.rate_window_started_at = required_number(&mut tokens, key)?;
        }
        "rate_window_requests" => {
            record.rate_window_requests = required_number(&mut tokens, key)?;
        }
        "scope" => record.scope = tokens.next_string().unwrap_or_default(),
        "client_kind" => record.client_kind = tokens.next_string(),
        "principal_id" => record.principal_id = tokens.next_string(),
        "model_policy" => {
            let raw = required_string(&mut tokens, key)?;
            record.model_policy = serde_json::from_str(&raw).map_err(|error| error.to_string())?;
        }
        other => return Err(format!("unknown field: {other}")),
    }
    Ok(())
}

fn required_atom<'a>(tokens: &mut LinoTokens<'a>, name: &str) -> Result<&'a str, String> {
    tokens
        .next_atom()
        .ok_or_else(|| format!("{name} missing value"))
}

fn required_string(tokens: &mut LinoTokens<'_>, name: &str) -> Result<String, String> {
    tokens
        .next_string()
        .ok_or_else(|| format!("{name} missing value"))
}

fn required_number<T>(tokens: &mut LinoTokens<'_>, name: &str) -> Result<T, String>
where
    T: std::str::FromStr,
    T::Err: std::fmt::Display,
{
    required_atom(tokens, name)?
        .parse::<T>()
        .map_err(|error| error.to_string())
}

struct LinoTokens<'a> {
    rest: &'a str,
}

impl<'a> LinoTokens<'a> {
    const fn new(input: &'a str) -> Self {
        Self { rest: input }
    }

    fn skip_ws(&mut self) {
        self.rest = self.rest.trim_start();
    }

    fn next_atom(&mut self) -> Option<&'a str> {
        self.skip_ws();
        if self.rest.is_empty() || self.rest.starts_with('(') || self.rest.starts_with('"') {
            return None;
        }
        let end = self
            .rest
            .find(|character: char| character.is_whitespace() || matches!(character, '(' | ')'))
            .unwrap_or(self.rest.len());
        let (atom, rest) = self.rest.split_at(end);
        self.rest = rest;
        Some(atom)
    }

    fn next_string(&mut self) -> Option<String> {
        self.skip_ws();
        let bytes = self.rest.as_bytes();
        if bytes.first() != Some(&b'"') {
            return None;
        }
        let mut value = String::new();
        let mut index = 1;
        while index < bytes.len() {
            let character = bytes[index];
            if character == b'\\' && index + 1 < bytes.len() {
                value.push(match bytes[index + 1] {
                    b'"' => '"',
                    b'\\' => '\\',
                    b'n' => '\n',
                    b'r' => '\r',
                    b't' => '\t',
                    other => char::from(other),
                });
                index += 2;
            } else if character == b'"' {
                self.rest = &self.rest[index + 1..];
                return Some(value);
            } else {
                value.push(char::from(character));
                index += 1;
            }
        }
        None
    }

    fn next_paren_group(&mut self) -> Option<&'a str> {
        self.skip_ws();
        if !self.rest.starts_with('(') {
            return None;
        }
        let mut depth = 0i32;
        let mut in_string = false;
        let mut escape = false;
        let mut end = 0;
        for (index, &byte) in self.rest.as_bytes().iter().enumerate() {
            if escape {
                escape = false;
                continue;
            }
            if in_string {
                match byte {
                    b'\\' => escape = true,
                    b'"' => in_string = false,
                    _ => {}
                }
                continue;
            }
            match byte {
                b'"' => in_string = true,
                b'(' => depth += 1,
                b')' => {
                    depth -= 1;
                    if depth == 0 {
                        end = index + 1;
                        break;
                    }
                }
                _ => {}
            }
        }
        if end == 0 {
            return None;
        }
        let group = &self.rest[1..end - 1];
        self.rest = &self.rest[end..];
        Some(group)
    }
}

use crate::model_contract::ModelAccessPolicy;

use super::TokenRecord;

pub(super) fn encode(record: &TokenRecord) -> String {
    serde_json::to_string(&record.model_policy).expect("model policy is JSON serializable")
}

pub(super) fn decode(raw: Option<&str>) -> Result<ModelAccessPolicy, String> {
    raw.map_or_else(
        || Ok(ModelAccessPolicy::default()),
        |raw| serde_json::from_str(raw).map_err(|error| error.to_string()),
    )
}

//! Per-record budget arithmetic and record reconciliation.
//!
//! Split from `storage.rs` to keep that file within the repository's
//! 1000-line limit. These are pure functions over a [`TokenRecord`]: they
//! decide whether a request fits the record's bounds and how two copies of
//! one record reconcile, with no knowledge of how records are stored.

use super::{RequestAdmission, TokenRecord};

pub(super) fn consume_request(record: Option<&mut TokenRecord>) -> bool {
    let Some(record) = record else {
        return true;
    };
    if record
        .max_requests
        .is_some_and(|max| record.used_requests >= max)
    {
        return false;
    }
    record.used_requests = record.used_requests.saturating_add(1);
    true
}

/// Apply every pre-request control, reserving `reserve` tokens against the spend cap.
///
/// The spend check compares `used + reserved + reserve` against `max_tokens`, so a
/// request is only admitted when its own declared output budget still fits. Reserving
/// inside the same locked read-modify-write as the counters is what makes concurrent
/// admissions unable to overshoot together.
pub(super) fn admit_request_reserving(
    record: Option<&mut TokenRecord>,
    now: i64,
    reserve: u64,
) -> RequestAdmission {
    let Some(record) = record else {
        return RequestAdmission::Admitted;
    };
    if record
        .max_requests
        .is_some_and(|max| record.used_requests >= max)
    {
        return RequestAdmission::RequestLimitExceeded;
    }
    if let Some(max) = record.max_tokens {
        let committed = record.used_tokens.saturating_add(record.reserved_tokens);
        // `>= max` (not `>`) keeps an exhausted budget rejecting even when the
        // request declares no output budget of its own.
        if committed >= max || committed.saturating_add(reserve) > max {
            return RequestAdmission::TokenLimitExceeded;
        }
    }
    if let Some(max) = record.rate_limit_per_minute {
        if now.saturating_sub(record.rate_window_started_at) >= 60 {
            record.rate_window_started_at = now;
            record.rate_window_requests = 0;
        }
        if record.rate_window_requests >= max {
            return RequestAdmission::RateLimitExceeded;
        }
        record.rate_window_requests = record.rate_window_requests.saturating_add(1);
    }
    record.used_requests = record.used_requests.saturating_add(1);
    record.reserved_tokens = record.reserved_tokens.saturating_add(reserve);
    slide_expiry(record, now);
    RequestAdmission::Admitted
}

/// Push an active token's expiry ahead of the request that just used it.
///
/// Only for a token issued with a window. The expiry a fixed-clock token was
/// given at issue time is final, which is what every token did before.
///
/// Serving the request *is* the evidence that the run is still alive, and it
/// is the evidence the old design threw away: `--run-ttl-hours` was raised
/// from 1 to 24 because interactive sessions outlived an hour, and a session
/// then died against the 24-hour wall while the user was typing into it. Any
/// fixed clock can only fire early; the question was how often (issue #354).
///
/// Never shortens. A window smaller than the remaining life leaves the longer
/// expiry alone, so lowering the window cannot revoke a token early.
const fn slide_expiry(record: &mut TokenRecord, now: i64) {
    let Some(window) = record.sliding_window_seconds else {
        return;
    };
    let extended = now.saturating_add(window);
    if extended > record.expires_at {
        record.expires_at = extended;
    }
}

pub(super) const fn add_token_usage(record: Option<&mut TokenRecord>, tokens: u64) {
    if let Some(record) = record {
        record.used_tokens = record.used_tokens.saturating_add(tokens);
    }
}

/// Replace a request's reservation with the usage the upstream actually reported.
///
/// `reserved` is released whether or not the request produced usage, so cancelled
/// requests, upstream errors, and responses with no usage block all free their budget.
/// `actual` is recorded in full even when it exceeds the reservation: the persisted
/// total must stay truthful about what was really spent.
pub(super) const fn settle_token_usage(
    record: Option<&mut TokenRecord>,
    reserved: u64,
    actual: u64,
) {
    if let Some(record) = record {
        record.reserved_tokens = record.reserved_tokens.saturating_sub(reserved);
        record.used_tokens = record.used_tokens.saturating_add(actual);
    }
}

/// Fold `other` into `current` so neither revocation nor recorded spend is lost.
pub fn merge_safer_record(current: &mut TokenRecord, other: &TokenRecord) {
    current.revoked |= other.revoked;
    current.used_requests = current.used_requests.max(other.used_requests);
    current.used_tokens = current.used_tokens.max(other.used_tokens);
    current.reserved_tokens = current.reserved_tokens.max(other.reserved_tokens);
    if other.rate_window_started_at > current.rate_window_started_at {
        current.rate_window_started_at = other.rate_window_started_at;
        current.rate_window_requests = other.rate_window_requests;
    } else if other.rate_window_started_at == current.rate_window_started_at {
        current.rate_window_requests = current.rate_window_requests.max(other.rate_window_requests);
    }
}

//! The file-mapped doublets token store.
//!
//! Split from `storage.rs` to keep that file within the repository's
//! 1000-line limit.

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, RwLock};

use super::budget::{
    add_token_usage, admit_request_reserving, consume_request, settle_token_usage,
};
use super::{
    RequestAdmission, StorageError, TokenRecord, TokenStore, advance_run_lease, associative,
    compact_ephemeral_records, legacy,
};

/// Decode a current binary projection without mapping the source file writable.
///
/// `doublets::Store::new` updates bookkeeping in its memory backend even when
/// the caller only intends to read. Copying into an owner-only temporary keeps
/// those writes away from the authoritative token store and its modification
/// time; the temporary is removed as soon as decoding finishes.
pub(super) fn load_records_read_only(path: &Path) -> Result<Vec<TokenRecord>, StorageError> {
    let mut source = fs::File::open(path)?;
    let mut temporary = tempfile::NamedTempFile::new()?;
    std::io::copy(&mut source, temporary.as_file_mut())?;
    let store = associative::PersistentStore::open(temporary.path())?;
    store.records()
}

/// Native file-mapped doublets token store.
///
/// Existing `LARTOK01` length-prefixed JSON files are read once and
/// atomically migrated to the doublets representation.
#[derive(Clone)]
pub struct BinaryTokenStore {
    path: PathBuf,
    lock_path: PathBuf,
    pub(super) inner: Arc<RwLock<HashMap<String, TokenRecord>>>,
    /// The doublets store itself, opened once and held for the process.
    ///
    /// A reader-writer lock, so concurrent readers share it and a writer
    /// excludes them: the store is a memory-mapped file whose mutations are
    /// visible to every holder of the mapping, so the lock is what keeps a
    /// rebuild from being observed half-finished (issue #357).
    store: Arc<RwLock<associative::PersistentStore>>,
    /// What the file looked like when `inner` was last loaded from it.
    ///
    /// Re-reading the file on every mutation is what a second router process
    /// requires -- its writes have to become visible here -- but it costs a
    /// full parse of the doublets links network on a path that usually finds
    /// nothing changed. The fingerprint answers "has anyone else written?"
    /// without paying for the full parse (issues #356, #357).
    pub(super) loaded: Arc<RwLock<Option<FileFingerprint>>>,
    /// How many times the file has been parsed, for tests to assert against.
    ///
    /// The saving this type exists for is "a write does not re-parse a store
    /// nobody else touched", which is a count, not a duration -- timing it
    /// cannot hold across runners, where the same ten writes took 5 s here
    /// and 12.9 s on Windows (issues #356, #357).
    #[cfg(test)]
    pub(super) parses: Arc<std::sync::atomic::AtomicUsize>,
}

/// Enough of a file's metadata to tell whether it was replaced.
///
/// The store is written by `rename` over a temporary, so a change always moves
/// the modification time and usually the length; an unchanged file keeps both.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) struct FileFingerprint {
    pub(super) length: u64,
    pub(super) modified: Option<std::time::SystemTime>,
}

impl FileFingerprint {
    pub(super) fn read(path: &Path) -> Option<Self> {
        let metadata = fs::metadata(path).ok()?;
        Some(Self {
            length: metadata.len(),
            modified: metadata.modified().ok(),
        })
    }
}

impl BinaryTokenStore {
    pub fn open(path: impl Into<PathBuf>) -> Result<Self, StorageError> {
        let path = path.into();
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        // A legacy `LARTOK01` file is not a doublets store, so it is decoded
        // and migrated before the store is opened over the path.
        let legacy_records = if path.exists() && legacy::is_binary(&path)? {
            Some(legacy::decode_binary(&path)?)
        } else {
            None
        };
        let migrated = legacy_records.is_some();
        if migrated {
            // The doublets store must not be opened over the legacy bytes.
            fs::remove_file(&path)?;
        }
        let store = associative::PersistentStore::open(&path)?;
        // Opening does not parse the links network. Decoding every record walks
        // one link per byte of every string, and a process that only writes
        // never needs the result. `loaded` is left
        // unset so the first *read* fills it, and `refresh` treats "never
        // loaded" as "changed" (issue #357).
        let map: HashMap<_, _> = legacy_records
            .into_iter()
            .flatten()
            .map(|record| (record.id.clone(), record))
            .collect();
        let fingerprint = None;
        let store = Self {
            lock_path: path.with_extension("lock"),
            path,
            inner: Arc::new(RwLock::new(map)),
            store: Arc::new(RwLock::new(store)),
            loaded: Arc::new(RwLock::new(fingerprint)),
            #[cfg(test)]
            parses: Arc::new(std::sync::atomic::AtomicUsize::new(0)),
        };
        if migrated {
            let guard = store.inner.read().map_err(|_| StorageError::LockPoisoned)?;
            store.flush(&guard)?;
        }
        Ok(store)
    }

    fn flush(&self, guard: &HashMap<String, TokenRecord>) -> Result<(), StorageError> {
        let mut sorted: Vec<&TokenRecord> = guard.values().collect();
        sorted.sort_by(|a, b| a.id.cmp(&b.id));
        self.store
            .write()
            .map_err(|_| StorageError::LockPoisoned)?
            .replace(sorted)?;
        // Our own write is not somebody else's, so record it rather than
        // re-reading the file to discover what we just put there.
        self.remember_fingerprint();
        Ok(())
    }

    fn remember_fingerprint(&self) {
        if let Ok(mut slot) = self.loaded.write() {
            *slot = FileFingerprint::read(&self.path);
        }
    }

    /// Reload only when the file on disk is not the one we last read.
    ///
    /// The reload exists so a second router process's writes become visible;
    /// skipping it when nothing changed keeps that guarantee and removes a
    /// full parse of the links network from every write (issues #356, #357).
    fn reload_if_changed(
        &self,
        guard: &mut HashMap<String, TokenRecord>,
    ) -> Result<(), StorageError> {
        let current = FileFingerprint::read(&self.path);
        let known = self.loaded.read().map_err(|_| StorageError::LockPoisoned)?;
        if current == *known {
            return Ok(());
        }
        drop(known);
        *guard = self.load_map()?;
        self.remember_fingerprint();
        Ok(())
    }

    pub(super) fn load_map(&self) -> Result<HashMap<String, TokenRecord>, StorageError> {
        #[cfg(test)]
        self.parses
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        if !self.path.exists() {
            return Ok(HashMap::new());
        }
        let records = if legacy::is_binary(&self.path)? {
            legacy::decode_binary(&self.path)?
        } else {
            {
                // Reached only when the fingerprint says the file changed,
                // which for a rebuild means the path names a new inode.
                let mut store = self.store.write().map_err(|_| StorageError::LockPoisoned)?;
                store.remap()?;
                store.records()?
            }
        };
        Ok(records
            .into_iter()
            .map(|record| (record.id.clone(), record))
            .collect())
    }

    /// Bring the in-memory map up to date with the file, if it moved.
    ///
    /// A shared lock and a fingerprint check, so a read that finds nothing
    /// changed costs a `stat` rather than a full parse of the links network. This
    /// called by `list`, which the dual store calls on every write through
    /// `merged_records`, so an unguarded reload here made a write pay for a full
    /// parse before changing anything (issues #356, #357).
    fn refresh(&self) -> Result<(), StorageError> {
        crate::durable_file::with_shared_lock(&self.lock_path, || {
            let current = FileFingerprint::read(&self.path);
            if current == *self.loaded.read().map_err(|_| StorageError::LockPoisoned)? {
                return Ok(());
            }
            let map = self.load_map()?;
            *self.inner.write().map_err(|_| StorageError::LockPoisoned)? = map;
            self.remember_fingerprint();
            Ok(())
        })
    }

    fn mutate<T>(
        &self,
        operation: impl FnOnce(&mut HashMap<String, TokenRecord>) -> T,
    ) -> Result<T, StorageError> {
        crate::durable_file::with_exclusive_lock(&self.lock_path, || {
            let mut guard = self.inner.write().map_err(|_| StorageError::LockPoisoned)?;
            self.reload_if_changed(&mut guard)?;
            let before = guard.clone();
            let result = operation(&mut guard);
            if let Err(error) = self.flush(&guard) {
                *guard = before;
                return Err(error);
            }
            Ok(result)
        })
    }

    pub(super) fn replace_all(&self, records: &[TokenRecord]) -> Result<(), StorageError> {
        self.mutate(|current| {
            current.clear();
            current.extend(
                records
                    .iter()
                    .cloned()
                    .map(|record| (record.id.clone(), record)),
            );
        })
    }

    /// Write the links network only when the records differ from disk.
    ///
    /// Rebuilding is the expensive half of a write: `write_binary` stores each
    /// string as one link per byte, and every field key is a per-record path,
    /// so persisting a non-trivial store requires many `create_link` calls. The
    /// dual store calls this for both projections on every mutation, including
    /// mutations that leave the binary projection identical -- a `put` of one
    /// token rebuilds every unchanged record as well (issues #356, #357).
    pub(super) fn replace_all_if_changed(
        &self,
        records: &[TokenRecord],
    ) -> Result<(), StorageError> {
        {
            let guard = self.inner.read().map_err(|_| StorageError::LockPoisoned)?;
            if guard.len() == records.len()
                && records
                    .iter()
                    .all(|record| guard.get(&record.id).is_some_and(|held| held == record))
            {
                return Ok(());
            }
        }
        self.replace_all(records)
    }
}

impl TokenStore for BinaryTokenStore {
    fn list(&self) -> Result<Vec<TokenRecord>, StorageError> {
        self.refresh()?;
        let guard = self.inner.read().map_err(|_| StorageError::LockPoisoned)?;
        Ok(guard.values().cloned().collect())
    }

    fn get(&self, id: &str) -> Result<Option<TokenRecord>, StorageError> {
        self.refresh()?;
        let guard = self.inner.read().map_err(|_| StorageError::LockPoisoned)?;
        Ok(guard.get(id).cloned())
    }

    fn put(&self, record: TokenRecord) -> Result<(), StorageError> {
        self.mutate(|records| {
            records.insert(record.id.clone(), record);
        })
    }

    fn delete(&self, id: &str) -> Result<bool, StorageError> {
        self.mutate(|records| records.remove(id).is_some())
    }

    fn put_compacting_ephemeral(&self, record: TokenRecord, now: i64) -> Result<(), StorageError> {
        self.mutate(|records| {
            compact_ephemeral_records(records, now);
            records.insert(record.id.clone(), record);
        })
    }

    fn try_consume_request(&self, id: &str) -> Result<bool, StorageError> {
        self.mutate(|records| consume_request(records.get_mut(id)))
    }

    fn try_admit_request_reserving(
        &self,
        id: &str,
        now: i64,
        reserve: u64,
    ) -> Result<RequestAdmission, StorageError> {
        self.mutate(|records| admit_request_reserving(records.get_mut(id), now, reserve))
    }

    fn record_token_usage(&self, id: &str, tokens: u64) -> Result<(), StorageError> {
        self.mutate(|records| add_token_usage(records.get_mut(id), tokens))
    }

    fn settle_token_usage(&self, id: &str, reserved: u64, actual: u64) -> Result<(), StorageError> {
        self.mutate(|records| settle_token_usage(records.get_mut(id), reserved, actual))
    }

    fn renew_run_lease(
        &self,
        id: &str,
        now: i64,
        ttl_seconds: i64,
    ) -> Result<Option<i64>, StorageError> {
        self.mutate(|records| advance_run_lease(records.get_mut(id), now, ttl_seconds))
    }
}

//! How a relayed stream ends when its upstream fails mid-flight (issue #668).
//!
//! Once a streaming response has started, its status line is already sent and
//! cannot report a failure. Aborting the body leaves the client to guess: some
//! SDKs surface a network error, while others treat the closed connection as
//! the end of the answer and keep a truncated turn as if it were complete.
//!
//! [`in_band_errors`] wraps a relayed body. When the upstream fails before its
//! terminal event, the client gets exactly one protocol-correct error event in
//! its own dialect and the body ends. Router never synthesizes the dialect's
//! success terminator (`message_stop`, `[DONE]`, `response.completed`). A
//! failure *after* the terminal event ends the body cleanly, because the turn
//! is already complete (counted as success, not as an error). A body that
//! ends cleanly without its terminal event is a cut turn as well, and ends
//! with the same kind of error event.
//!
//! The dialect is only known for bodies Router can inspect. A compressed or
//! non-SSE body is relayed byte for byte, so it keeps the transport abort: an
//! injected plaintext frame would corrupt it.

use std::pin::Pin;
use std::task::{Context, Poll};

use bytes::Bytes;
use futures_util::Stream;
use serde_json::json;

/// Message of the error event sent when the upstream body ends before its
/// terminal event.
pub const INCOMPLETE_STREAM_MESSAGE: &crate::translation_core::Str = "upstream stream ended before completion";

/// Upper bound for the bytes kept while looking for a split terminator.
pub const MAX_SSE_CARRY_BYTES: usize = 64 * 1024;

/// The client-facing wire dialect of a streamed response.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StreamDialect {
    /// Anthropic Messages (`event: error`).
    Anthropic,
    /// `OpenAI` Chat Completions (`data: {"error": …}` without `[DONE]`).
    OpenAiChat,
    /// `OpenAI` Responses (`event: error`, `type: error`).
    Responses,
    /// Gemini `streamGenerateContent` (`data: {"error": …}`).
    Gemini,
}

impl StreamDialect {
    /// The dialect a request path streams in, when the path names one.
    #[must_use]
    pub fn from_path(path: &crate::translation_core::Str) -> crate::translation_core::Maybe<Self> {
        let path = path.split('?').next().unwrap_or(path);
        if path.ends_with("/messages") {
            Some(Self::Anthropic)
        } else if path.ends_with("/chat/completions") {
            Some(Self::OpenAiChat)
        } else if path.ends_with("/responses") {
            Some(Self::Responses)
        } else if path.contains(":streamGenerateContent") {
            Some(Self::Gemini)
        } else {
            None
        }
    }
}

/// Why a stream failed before its terminal event.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FailureKind {
    /// The upstream went silent past the idle timeout.
    Stalled,
    /// The upstream connection was reset or the body could not be read.
    Interrupted,
    /// The upstream body ended cleanly but without its terminal event.
    Truncated,
}

impl FailureKind {
    /// Classify a transport error from the upstream body.
    #[must_use]
    pub fn of(error: &(dyn std::error::Error + 'static)) -> Self {
        let mut source = Some(error);
        while let Some(error) = source {
            if let Some(error) = error.downcast_ref::<reqwest::Error>()
                && error.is_timeout()
            {
                return Self::Stalled;
            }
            if let Some(error) = error.downcast_ref::<std::io::Error>() {
                if error.kind() == std::io::ErrorKind::TimedOut {
                    return Self::Stalled;
                }
                // `io::Error::source` skips the error it wraps; look inside.
                if let Some(inner) = error.get_ref()
                    && Self::of(inner) == Self::Stalled
                {
                    return Self::Stalled;
                }
            }
            source = error.source();
        }
        Self::Interrupted
    }

    /// The failure named by an in-band error event Router itself emitted in
    /// the Chat or Responses dialect, so a bridge relaying that event can
    /// report it in its own dialect instead of as a generic error.
    #[must_use]
    pub fn of_in_band(event: &crate::translation_core::Json) -> crate::translation_core::Maybe<Self> {
        let code = event
            .pointer("/error/code")
            .or_else(|| event.get("code"))
            .and_then(serde_json::Value::as_str)?;
        match code {
            "upstream_timeout" => Some(Self::Stalled),
            "upstream_interrupted" => Some(Self::Interrupted),
            "upstream_incomplete" => Some(Self::Truncated),
            _ => None,
        }
    }

    const fn message(self) -> &'static crate::translation_core::Str {
        match self {
            Self::Stalled => "upstream stream stalled past the idle timeout before completion",
            Self::Interrupted => "upstream stream was interrupted before completion",
            Self::Truncated => INCOMPLETE_STREAM_MESSAGE,
        }
    }
}

/// Render the one error event a client receives for a failed stream.
#[must_use]
pub fn error_frame(dialect: StreamDialect, kind: FailureKind) -> Bytes {
    let message = kind.message();
    let frame = match dialect {
        StreamDialect::Anthropic => {
            let kind = match kind {
                FailureKind::Stalled => "timeout_error",
                FailureKind::Interrupted | FailureKind::Truncated => "api_error",
            };
            let payload = json!({"type": "error", "error": {"type": kind, "message": message}});
            format!("event: error\ndata: {payload}\n\n")
        }
        StreamDialect::OpenAiChat => {
            let code = match kind {
                FailureKind::Stalled => "upstream_timeout",
                FailureKind::Interrupted => "upstream_interrupted",
                FailureKind::Truncated => "upstream_incomplete",
            };
            let payload =
                json!({"error": {"message": message, "type": "server_error", "code": code}});
            format!("data: {payload}\n\n")
        }
        StreamDialect::Responses => {
            let code = match kind {
                FailureKind::Stalled => "upstream_timeout",
                FailureKind::Interrupted => "upstream_interrupted",
                FailureKind::Truncated => "upstream_incomplete",
            };
            let payload = json!({"type": "error", "code": code, "message": message, "param": null});
            format!("event: error\ndata: {payload}\n\n")
        }
        StreamDialect::Gemini => {
            let (code, status) = match kind {
                FailureKind::Stalled => (504, "DEADLINE_EXCEEDED"),
                FailureKind::Interrupted | FailureKind::Truncated => (503, "UNAVAILABLE"),
            };
            let payload = json!({"error": {"code": code, "message": message, "status": status}});
            format!("data: {payload}\n\n")
        }
    };
    Bytes::from(frame)
}

/// Whether one complete SSE block ends the turn in any dialect.
///
/// Parsed per event rather than by substring, so an answer that merely
/// *mentions* `[DONE]` or `message_stop` is not mistaken for its end. An
/// upstream's own in-band error also ends the turn: the client already has
/// its failure, and a second one would only confuse it.
#[must_use]
pub fn block_is_terminal(block: &crate::translation_core::Str) -> bool {
    let mut event = None;
    let mut data = String::new();
    for line in block.lines() {
        let line = line.trim_end_matches('\r');
        if let Some(name) = line.strip_prefix("event:") {
            event = Some(name.trim().to_string());
        } else if let Some(value) = line.strip_prefix("data:") {
            if !data.is_empty() {
                data.push('\n');
            }
            data.push_str(value.strip_prefix(' ').unwrap_or(value));
        }
    }
    if matches!(event.as_deref(), Some("message_stop" | "error")) || data.trim() == "[DONE]" {
        return true;
    }
    let Ok(value) = serde_json::from_str::<serde_json::Value>(&data) else {
        return false;
    };
    let kind = value.get("type").and_then(serde_json::Value::as_str);
    if matches!(
        kind,
        Some(
            "message_stop"
                | "error"
                | "response.completed"
                | "response.incomplete"
                | "response.failed"
        )
    ) || value.get("error").is_some_and(|error| !error.is_null())
    {
        return true;
    }
    let finished = |list: &str, field: &str| {
        value
            .get(list)
            .and_then(serde_json::Value::as_array)
            .is_some_and(|items| {
                items.iter().any(|item| {
                    item.get(field)
                        .and_then(serde_json::Value::as_str)
                        .is_some_and(|reason| !reason.is_empty())
                })
            })
    };
    // Chat Completions and Gemini end the content with a finish reason; any
    // usage chunk after it carries no more of the answer.
    finished("choices", "finish_reason") || finished("candidates", "finishReason")
}

/// Chunk-safe detector for a dialect's terminal event.
///
/// A terminator split across two network chunks (`data: [DO` + `NE]`) is
/// still seen, and the carried bytes stay bounded.
#[derive(Debug, Default)]
pub struct TerminalEventDetector {
    carry: Vec<u8>,
    seen: bool,
}

impl TerminalEventDetector {
    /// Feed one chunk; returns whether a terminal event has been seen so far.
    pub fn push(&mut self, chunk: &[u8]) -> bool {
        for block in crate::sse::push_blocks(&mut self.carry, chunk) {
            self.seen |= block_is_terminal(&block);
        }
        if self.carry.len() > MAX_SSE_CARRY_BYTES {
            // An event this large is content, never a bare terminator.
            let discard = self.carry.len() - MAX_SSE_CARRY_BYTES;
            self.carry.drain(..discard);
        }
        self.seen
    }

    /// Whether a terminal event has been seen, including a final one whose
    /// blank line never arrived.
    #[must_use]
    pub fn seen(&self) -> bool {
        self.seen || block_is_terminal(&String::from_utf8_lossy(&self.carry))
    }

    /// Whether the relayed bytes stop inside an event, so anything appended
    /// must first close it with a blank line.
    #[must_use]
    pub const fn mid_frame(&self) -> bool {
        !self.carry.is_empty()
    }

    #[cfg(test)]
    pub(crate) const fn carried(&self) -> usize {
        self.carry.len()
    }
}

/// Wrap a relayed body so a mid-stream upstream failure ends it with one
/// in-band error event (see the module docs).
///
/// `dialect` is `None` for a body Router cannot rewrite; it then keeps the
/// transport abort.
pub fn in_band_errors<S, E>(stream: S, dialect: Option<StreamDialect>) -> InBandErrors<S>
where
    S: Stream<Item = Result<Bytes, E>>,
{
    InBandErrors {
        inner: Box::pin(stream),
        dialect,
        detector: TerminalEventDetector::default(),
        done: false,
    }
}

/// Stream returned by [`in_band_errors`].
pub struct InBandErrors<S> {
    inner: Pin<Box<S>>,
    dialect: Option<StreamDialect>,
    detector: TerminalEventDetector,
    done: bool,
}

impl<S> InBandErrors<S> {
    /// The error event, preceded by a blank line when the upstream stopped
    /// mid-event, so the client never parses the two as one corrupt event.
    fn terminal_error(&self, dialect: StreamDialect, kind: FailureKind) -> Bytes {
        let frame = error_frame(dialect, kind);
        if !self.detector.mid_frame() {
            return frame;
        }
        let mut closed = Vec::with_capacity(frame.len() + 2);
        closed.extend_from_slice(b"\n\n");
        closed.extend_from_slice(&frame);
        Bytes::from(closed)
    }
}

impl<S, E> Stream for InBandErrors<S>
where
    S: Stream<Item = Result<Bytes, E>>,
    E: Into<Box<dyn std::error::Error + Send + Sync>>,
{
    type Item = Result<Bytes, std::io::Error>;

    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let this = self.get_mut();
        if this.done {
            return Poll::Ready(None);
        }
        match this.inner.as_mut().poll_next(cx) {
            Poll::Ready(Some(Ok(bytes))) => {
                if this.dialect.is_some() {
                    this.detector.push(&bytes);
                }
                Poll::Ready(Some(Ok(bytes)))
            }
            Poll::Ready(Some(Err(error))) => {
                this.done = true;
                let error: Box<dyn std::error::Error + Send + Sync> = error.into();
                let Some(dialect) = this.dialect else {
                    return Poll::Ready(Some(Err(std::io::Error::other(error))));
                };
                if this.detector.seen() {
                    // The turn already completed; a late reset is not a failure.
                    tracing::debug!(%error, "upstream closed after the terminal event");
                    return Poll::Ready(None);
                }
                let kind = FailureKind::of(error.as_ref());
                tracing::warn!(%error, ?kind, ?dialect, "upstream stream failed before completion");
                Poll::Ready(Some(Ok(this.terminal_error(dialect, kind))))
            }
            Poll::Ready(None) => {
                this.done = true;
                match this.dialect {
                    Some(dialect) if !this.detector.seen() => {
                        tracing::warn!(?dialect, "upstream stream ended before its terminal event");
                        Poll::Ready(Some(Ok(
                            this.terminal_error(dialect, FailureKind::Truncated)
                        )))
                    }
                    _ => Poll::Ready(None),
                }
            }
            Poll::Pending => Poll::Pending,
        }
    }
}

