/// A normalized subscription token plus the metadata the proxy needs to route.
#[derive(
    Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize, schemars::JsonSchema,
)]
pub struct SubscriptionToken {
    /// OAuth bearer access token sent as `Authorization: Bearer <token>`.
    pub access_token: String,
    /// OAuth refresh token, when the vendor file stores one.
    pub refresh_token: Option<String>,
    /// Expiry as Unix epoch milliseconds, when known.
    pub expires_at_ms: Option<i64>,
    /// `ChatGPT` account id (`chatgpt-account-id` header) for Codex billing.
    pub account_id: Option<String>,
    /// Per-token base URL override (Qwen `resource_url`).
    pub resource_url: Option<String>,
}

impl SubscriptionToken {
    /// Whether the token is expired relative to `now_ms` (with no skew).
    #[must_use]
    pub fn is_expired(&self, now_ms: i64) -> bool {
        self.expires_at_ms.is_some_and(|exp| exp <= now_ms)
    }

    /// Effective base URL for this token: `resource_url` override or the
    /// provider default. Qwen returns a bare host in `resource_url`, so a
    /// scheme and the `/v1` suffix used by Qwen Code are added when missing.
    #[must_use]
    pub fn base_url(&self, provider: SubscriptionProvider) -> String {
        let Some(resource) = self.resource_url.as_deref().filter(|s| !s.is_empty()) else {
            return provider.default_base_url().to_string();
        };
        let with_scheme = if resource.starts_with("http://") || resource.starts_with("https://") {
            resource.to_string()
        } else {
            format!("https://{resource}")
        };
        if provider == SubscriptionProvider::Qwen
            && !with_scheme.trim_end_matches('/').ends_with("/v1")
        {
            format!("{}/v1", with_scheme.trim_end_matches('/'))
        } else {
            with_scheme
        }
    }
}

//! Subscription health reporting (issue #318).
//!
//! Separate from `proxy::health`, which answers liveness only: `/api/health` drives
//! both Kubernetes probes and a restart cannot mint an OAuth token.

use axum::extract::State;
use axum::http::StatusCode;
use axum::response::IntoResponse;

use crate::app_state::AppState;

/// `GET /api/management/health/subscriptions` — can this router serve what it advertises?
///
/// The signal that did not exist. A revoked subscription left `/api/health` at
/// `ok`, `degraded_providers` empty and no counter anywhere, so the operator
/// learned about it from a client hours later via a message that named neither
/// the subscription nor the credential (issue #318).
///
/// Answers `503` when a *configured* subscription is degraded, which is what
/// lets a stock uptime check fire without knowing anything about router
/// internals. A readable credential still awaiting its first live catalog is
/// listed as starting and answers `200`; a deployment with no credential also
/// answers `200` with empty provider lists.
pub async fn subscription_health(State(state): State<AppState>) -> impl IntoResponse {
    let providers = crate::model_routing::configured_provider_health_report(&state).await;
    let mut degraded = providers
        .iter()
        .filter(|health| health.is_degraded())
        .map(|health| {
            crate::translation_core::json!({
                "provider": health.provider.as_str(),
                "reason": health.summary,
            })
        })
        .collect::<Vec<_>>();
    let mut healthy = providers
        .iter()
        .filter(|health| health.state == crate::model_routing::ProviderHealthState::Healthy)
        .map(|health| health.provider.as_str())
        .collect::<Vec<_>>();
    let starting = providers
        .iter()
        .filter(|health| health.state == crate::model_routing::ProviderHealthState::Starting)
        .map(|health| health.provider.as_str())
        .collect::<Vec<_>>();
    match crate::zai_coding_plan::configured_health(&state).await {
        Some(true) => healthy.push("z.ai"),
        Some(false) => degraded.push(crate::zai_coding_plan::recorded_exhaustion(&state).map_or_else(
            || {
                crate::translation_core::json!({
                    "provider": "z.ai",
                    "reason": "the Coding Plan credential was rejected upstream and needs replacement",
                })
            },
            |exhaustion| {
                crate::translation_core::json!({
                    "provider": "z.ai",
                    "state": "exhausted",
                    "reason": exhaustion.summary(),
                    "upstream_code": exhaustion.code.to_string(),
                })
            },
        )),
        None => {}
    }
    let status = if degraded.is_empty() {
        StatusCode::OK
    } else {
        StatusCode::SERVICE_UNAVAILABLE
    };
    (
        status,
        axum::Json(crate::translation_core::json!({
            "status": if degraded.is_empty() { "ok" } else { "degraded" },
            "starting_providers": starting,
            "healthy_providers": healthy,
            "degraded_providers": degraded,
        })),
    )
        .into_response()
}

//! Forward `OpenAI`-style requests to vendor *subscription* upstreams.
//!
//! Codex (`ChatGPT`) and Qwen authenticate with the user's subscription OAuth
//! token (read by [`crate::subscription`]) and speak `OpenAI`-shaped wire
//! formats — Qwen via `DashScope`'s `OpenAI`-compatible API, Codex via the
//! `ChatGPT` backend Responses API. This module substitutes the client's
//! router token for the subscription bearer token and forwards the request,
//! streaming SSE through untouched, exactly like [`crate::provider_proxy`] does
//! for configured `OpenAI`-compatible providers.
//!
