//! Buffered Codex SSE terminal assembly.

use std::collections::BTreeMap;

pub(super) fn codex_sse_to_response_json(body: &[u8]) -> Option<Vec<u8>> {
    let text = std::str::from_utf8(body).ok()?;
    let mut terminal: Option<serde_json::Value> = None;
    let mut output = BTreeMap::<u64, serde_json::Value>::new();
    for line in text.lines() {
        let Some(payload) = line.strip_prefix("data:") else {
            continue;
        };
        let payload = payload.trim();
        if payload.is_empty() || payload == "[DONE]" {
            continue;
        }
        let Ok(event) = serde_json::from_str::<serde_json::Value>(payload) else {
            continue;
        };
        match event.get("type").and_then(serde_json::Value::as_str) {
            Some("response.output_item.added" | "response.output_item.done") => {
                if let Some(item) = event.get("item") {
                    let index = event
                        .get("output_index")
                        .and_then(serde_json::Value::as_u64)
                        .unwrap_or(output.len() as u64);
                    let mut item = item.clone();
                    if item
                        .get("content")
                        .and_then(serde_json::Value::as_array)
                        .is_none_or(Vec::is_empty)
                        && let Some(content) =
                            output.get(&index).and_then(|item| item.get("content"))
                    {
                        item["content"] = content.clone();
                    }
                    output.insert(index, item);
                }
            }
            Some("response.output_text.delta") => update_text(&mut output, &event, false),
            Some("response.output_text.done") => update_text(&mut output, &event, true),
            Some("response.refusal.delta") => update_refusal(&mut output, &event, false),
            Some("response.refusal.done") => update_refusal(&mut output, &event, true),
            Some("response.completed" | "response.incomplete") => {
                if let Some(response) = event.get("response") {
                    terminal = Some(response.clone());
                }
            }
            Some("response.failed") => {
                if let Some(response) = event.get("response") {
                    let mut response = response.clone();
                    response["error"] =
                        crate::responses::response_failed_error(&event)["error"].clone();
                    terminal = Some(response);
                }
            }
            _ => {}
        }
    }
    if let Some(response) = terminal.as_mut() {
        if response
            .get("output")
            .and_then(serde_json::Value::as_array)
            .is_none()
        {
            response["output"] = serde_json::json!([]);
        }
        if let Some(terminal_output) = response
            .get_mut("output")
            .and_then(serde_json::Value::as_array_mut)
        {
            for (index, item) in output {
                let Ok(index) = usize::try_from(index) else {
                    continue;
                };
                terminal_output.resize(index + 1, serde_json::Value::Null);
                let missing_content = item.get("content").is_some()
                    && terminal_output[index]
                        .get("content")
                        .and_then(serde_json::Value::as_array)
                        .is_none_or(Vec::is_empty);
                if terminal_output[index].is_null() || missing_content {
                    terminal_output[index] = item;
                }
            }
        }
    }
    terminal.and_then(|value| serde_json::to_vec(&value).ok())
}

fn update_text(
    output: &mut BTreeMap<u64, serde_json::Value>,
    event: &serde_json::Value,
    done: bool,
) {
    let output_index = event
        .get("output_index")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0);
    let content_index = event
        .get("content_index")
        .and_then(serde_json::Value::as_u64)
        .and_then(|index| usize::try_from(index).ok())
        .unwrap_or(0);
    let item_id = event
        .get("item_id")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("");
    let item = output.entry(output_index).or_insert_with(|| {
        serde_json::json!({
            "id": item_id, "type": "message", "status": "in_progress",
            "role": "assistant", "content": []
        })
    });
    let Some(content) = item
        .get_mut("content")
        .and_then(serde_json::Value::as_array_mut)
    else {
        return;
    };
    content.resize(content_index + 1, serde_json::Value::Null);
    if content[content_index].is_null() {
        content[content_index] =
            serde_json::json!({"type": "output_text", "text": "", "annotations": []});
    }
    let text = event
        .get(if done { "text" } else { "delta" })
        .and_then(serde_json::Value::as_str)
        .unwrap_or("");
    if done {
        content[content_index]["text"] = serde_json::Value::String(text.to_string());
        item["status"] = serde_json::Value::String("completed".to_string());
    } else if let Some(current) = content[content_index]["text"].as_str() {
        content[content_index]["text"] = serde_json::Value::String(format!("{current}{text}"));
    }
}

fn update_refusal(
    output: &mut BTreeMap<u64, serde_json::Value>,
    event: &serde_json::Value,
    done: bool,
) {
    let output_index = event
        .get("output_index")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0);
    let content_index = event
        .get("content_index")
        .and_then(serde_json::Value::as_u64)
        .and_then(|index| usize::try_from(index).ok())
        .unwrap_or(0);
    let item = output.entry(output_index).or_insert_with(|| {
        serde_json::json!({
            "id": event.get("item_id").and_then(serde_json::Value::as_str).unwrap_or(""),
            "type": "message", "status": "in_progress", "role": "assistant", "content": []
        })
    });
    let Some(content) = item
        .get_mut("content")
        .and_then(serde_json::Value::as_array_mut)
    else {
        return;
    };
    content.resize(content_index + 1, serde_json::Value::Null);
    if content[content_index].is_null() {
        content[content_index] = serde_json::json!({"type": "refusal", "refusal": ""});
    }
    let refusal = event
        .get(if done { "refusal" } else { "delta" })
        .and_then(serde_json::Value::as_str)
        .unwrap_or("");
    if done {
        content[content_index]["refusal"] = serde_json::Value::String(refusal.to_string());
        item["status"] = serde_json::Value::String("completed".to_string());
    } else if let Some(current) = content[content_index]["refusal"].as_str() {
        content[content_index]["refusal"] =
            serde_json::Value::String(format!("{current}{refusal}"));
    }
}

//! Provider-specific headers for subscription upstreams.

use super::{
    CODEX_RESPONSES_LITE_HEADER, CodexResponsesMode, SubscriptionProvider, SubscriptionToken,
};

pub(super) fn subscription_headers(
    provider: SubscriptionProvider,
    token: &SubscriptionToken,
    responses_mode: CodexResponsesMode,
) -> Vec<(&'static str, String)> {
    let mut out = Vec::new();
    if provider == SubscriptionProvider::Codex {
        let identity = crate::codex_identity::headers(token.account_id.as_deref());
        for name in ["user-agent", "originator", "chatgpt-account-id"] {
            if let Some(value) = identity.get(name).and_then(|value| value.to_str().ok()) {
                out.push((name, value.to_string()));
            }
        }
        out.push(("openai-beta", "responses=experimental".to_string()));
        if responses_mode == CodexResponsesMode::Lite {
            out.push((CODEX_RESPONSES_LITE_HEADER, "true".to_string()));
        }
        // Recent Codex models are gated by the CLI version header.
        out.push(("version", crate::codex_identity::client_version()));
    }
    out
}

use super::{CodexResponsesMode, SubscriptionProvider};

/// Extract the concatenated text from a Responses `input` message item.
fn input_item_text(item: &serde_json::Value) -> Option<String> {
    match item.get("content") {
        Some(serde_json::Value::String(s)) => Some(s.clone()),
        Some(serde_json::Value::Array(parts)) => {
            let text: String = parts
                .iter()
                .filter_map(|p| p.get("text").and_then(serde_json::Value::as_str))
                .collect::<Vec<_>>()
                .join("");
            (!text.is_empty()).then_some(text)
        }
        _ => None,
    }
}

/// Apply provider capability rules, then any provider-specific body shaping.
pub(super) fn normalize_subscription_request(
    provider: SubscriptionProvider,
    body: &mut serde_json::Value,
    responses_mode: CodexResponsesMode,
) {
    crate::openai::reconcile_subscription_parameters(provider, body);
    if provider == SubscriptionProvider::Codex {
        normalize_codex_responses_body(body, responses_mode);
    }
}

/// Shape a Responses-API request body for the `ChatGPT` Codex backend.
///
/// The Codex backend is stricter than the generic `OpenAI` Responses API: it
/// always streams and rejects `max_output_tokens`. Standard Responses requests
/// also reject system/developer input messages and require non-empty top-level
/// `instructions`, so those turns are hoisted and a default is used when
/// nothing remains. Responses Lite deliberately keeps its protocol envelope:
/// Codex places `additional_tools` in a developer input item and keeps
/// `instructions` empty.
pub(super) fn normalize_codex_responses_body(
    body: &mut serde_json::Value,
    mode: CodexResponsesMode,
) {
    let Some(obj) = body.as_object_mut() else {
        return;
    };
    obj.entry("reasoning").or_insert_with(
        || serde_json::json!({"effort": crate::clients::DEFAULT_OPENAI_REASONING_EFFORT}),
    );
    // Codex always streams from the ChatGPT backend.
    obj.insert("stream".to_string(), serde_json::Value::Bool(true));
    // ChatGPT subscription inference does not permit stored responses.
    obj.insert("store".to_string(), serde_json::Value::Bool(false));
    // `max_output_tokens` is not accepted by the Codex backend.
    obj.remove("max_output_tokens");
    if mode == CodexResponsesMode::Lite {
        return;
    }
    // The backend rejects a bare-string `input` ("Input must be a list"), so
    // normalise both documented forms to the typed list shape.
    if let Some(input) = obj.get("input") {
        let normalized = crate::responses::normalize_input_items(input);
        obj.insert("input".to_string(), normalized);
    }

    // Hoist system/developer turns out of `input` (Codex forbids them there).
    let mut hoisted: Vec<String> = Vec::new();
    if let Some(serde_json::Value::Array(items)) = obj.get_mut("input") {
        items.retain(
            |item| match item.get("role").and_then(serde_json::Value::as_str) {
                Some("system" | "developer") => {
                    if let Some(text) = input_item_text(item) {
                        hoisted.push(text);
                    }
                    false
                }
                _ => true,
            },
        );
    }

    // Merge existing instructions + hoisted system turns; fall back to a default.
    let mut parts: Vec<String> = Vec::new();
    if let Some(existing) = obj.get("instructions").and_then(serde_json::Value::as_str)
        && !existing.trim().is_empty()
    {
        parts.push(existing.to_string());
    }
    parts.extend(hoisted);
    let instructions = if parts.is_empty() {
        "You are a helpful assistant.".to_string()
    } else {
        parts.join("\n\n")
    };
    obj.insert(
        "instructions".to_string(),
        serde_json::Value::String(instructions),
    );
}

//! Account selection and the upstream send for subscription (Codex, Qwen)
//! requests, with opt-in pre-first-byte failover across the account pool
//! (issue #676).
//!
//! Without failover this sends once — plus the established single replay
//! after a `401` refresh — exactly as before. With
//! `POOL_FAILOVER=pre-first-byte` a `429`, `529`, retryable `5xx`, `401` or
//! transport error is answered by sending the same request on the next
//! eligible account, before any byte reaches the client. The loop honours the
//! same bounds as the Anthropic path: `POOL_FAILOVER_MAX_ATTEMPTS`,
//! `POOL_FAILOVER_BUDGET_SECS`, no other eligible account, a token-pinned
//! account, and a client that went away (axum drops the handler).

use std::time::Instant;

use axum::http::{HeaderMap, HeaderValue, StatusCode};
use axum::response::Response;
use bytes::Bytes;
use serde_json::Value;

use super::{CodexResponsesMode, join_subscription_url, subscription_headers};
use crate::account_http::CookieMode;
use crate::accounts::{RoutingContext, UpstreamObservation};
use crate::metrics::Surface;
use crate::pool_failover::{RetryReason, classify_status};
use crate::proxy::{AppState, error_response, log_stop, note_failover, retry_after_duration};
use crate::subscription::{SubscriptionProvider, SubscriptionToken};

/// Everything one dispatch needs from the handler.
pub(super) struct CodexDispatch<'a> {
    pub state: &'a AppState,
    pub provider: SubscriptionProvider,
    pub headers: &'a HeaderMap,
    pub path: &'a str,
    pub surface: Surface,
    /// The normalized request body.
    pub body: &'a Value,
    /// The client's native bytes, when the request is forwarded natively.
    pub native_body: Option<crate::encoded_request_body::NativeBody>,
    pub native_protocol: bool,
    pub from_thinking_suffix: bool,
    pub responses_mode: CodexResponsesMode,
    pub validated: Option<&'a crate::model_routing::ValidatedSubscription>,
    pub context: RoutingContext,
    pub correlation_id: &'a str,
}

/// The upstream response the client will receive.
pub(super) struct Dispatched {
    pub response: crate::pool_response::PoolResponse,
    /// The account that produced it.
    pub account: String,
    pub base_url: String,
    pub bytes_sent: u64,
}

/// A selection failure: the response for a first attempt, the reason for a
/// later one.
struct SelectError {
    status: StatusCode,
    code: &'static str,
    message: String,
}

impl SelectError {
    fn new(status: StatusCode, code: &'static str, message: impl Into<String>) -> Self {
        Self {
            status,
            code,
            message: message.into(),
        }
    }
}

/// Select an account, send, and — with failover on — retry on another account
/// until a response can be relayed.
pub(super) async fn dispatch(request: CodexDispatch<'_>) -> Result<Dispatched, Response> {
    let state = request.state;
    let policy = crate::pool_failover::current();
    let router = state.account_router.as_ref();
    // A token-pinned account never falls back.
    let failover = router.is_some_and(crate::accounts::AccountRouter::failover_enabled)
        && request.context.pinned_account.is_none();
    let mut budget = crate::pool_retry::RetryBudget::new(router, failover, policy.max_attempts);
    let max_attempts = budget.max_attempts;
    let deadline = policy.deadline(Instant::now());
    let encode = |value: &Value| {
        request.native_body.as_ref().map_or_else(
            || {
                serde_json::to_vec(value)
                    .map_err(|error| format!("failed to serialize request JSON: {error}"))
            },
            |native| native.encode(value),
        )
    };
    let payload = match encode(request.body) {
        Ok(bytes) => Bytes::from(bytes),
        Err(error) => {
            return Err(error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &error,
            ));
        }
    };
    // Reasoning items carry `encrypted_content` only the producing account
    // can read; a request moved to another account must leave them out.
    let mut stripped: Option<Bytes> = None;
    // The account whose encrypted reasoning the conversation history carries.
    let mut origin = router.and_then(|router| router.session_account(&request.context));
    let mut context = request.context.clone();
    let mut last: Option<Result<Dispatched, (String, String)>> = None;
    let mut attempt = 0;
    while attempt < max_attempts {
        if budget.round_full(&context) && !budget.next_round(router, &mut context, deadline).await {
            break;
        }
        if attempt > 0 && Instant::now() >= deadline {
            log_stop(state, request.correlation_id, attempt, "budget exhausted");
            break;
        }
        let (mut account, token) =
            match select_account(state, request.provider, request.validated, &context).await {
                Ok(selected) => selected,
                Err(error) => {
                    if budget.next_round(router, &mut context, deadline).await {
                        continue;
                    }
                    if attempt > 0 {
                        log_stop(state, request.correlation_id, attempt, &error.message);
                        break;
                    }
                    return Err(error_response(error.status, error.code, &error.message));
                }
            };
        attempt += 1;
        origin.get_or_insert_with(|| account.clone());
        // An already-bound account cannot move; do not send twice.
        if attempt > 1 && context.exclude.contains(&account) {
            log_stop(state, request.correlation_id, attempt, "no other account");
            break;
        }
        let history_account = origin.clone().or_else(|| context.exclude.first().cloned());
        let body = if failover
            && history_account
                .as_ref()
                .is_some_and(|origin| origin != &account)
        {
            if stripped.is_none() {
                let mut value = request.body.clone();
                let changed = crate::pool_failover::strip_codex_encrypted_reasoning(&mut value);
                stripped = Some(if changed {
                    encode(&value).map_or_else(|_| payload.clone(), Bytes::from)
                } else {
                    payload.clone()
                });
            }
            stripped.clone().unwrap_or_else(|| payload.clone())
        } else {
            payload.clone()
        };
        let base_url = state
            .subscription_base_url
            .clone()
            .unwrap_or_else(|| token.base_url(request.provider));
        let mut attempt_body = request.body.clone();
        if failover
            && history_account
                .as_ref()
                .is_some_and(|origin| origin != &account)
        {
            crate::pool_failover::strip_codex_encrypted_reasoning(&mut attempt_body);
        }
        let model = attempt_body
            .get("model")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();
        let protocol = if request.provider == SubscriptionProvider::Codex {
            crate::thinking::ThinkingProtocol::Codex
        } else if request.path.ends_with("/chat/completions") {
            crate::thinking::ThinkingProtocol::Qwen
        } else {
            crate::thinking::ThinkingProtocol::OpenAIResponses
        };
        let origin =
            if request.native_protocol && protocol == crate::thinking::ThinkingProtocol::Qwen {
                protocol
            } else {
                match request.surface {
                    Surface::Anthropic => crate::thinking::ThinkingProtocol::Anthropic,
                    Surface::OpenAIChat => crate::thinking::ThinkingProtocol::OpenAIChat,
                    Surface::OpenAIResponses => crate::thinking::ThinkingProtocol::OpenAIResponses,
                }
            };
        let changed = crate::thinking::apply_for_account(
            state,
            &mut attempt_body,
            &model,
            request.provider,
            &account,
            &base_url,
            protocol,
            origin,
            request.from_thinking_suffix,
        )
        .map_err(|reason| {
            error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &reason)
        })?;
        let body = if changed {
            Bytes::from(encode(&attempt_body).map_err(|reason| {
                error_response(StatusCode::INTERNAL_SERVER_ERROR, "api_error", &reason)
            })?)
        } else {
            body
        };
        let bytes_sent = body.len() as u64;
        let attempt_outcome = async {
            let response = send_attempt(&request, &account, token, &base_url, body).await?;
            let probe = failover
                && response.status().is_success()
                && (request.provider == SubscriptionProvider::Codex
                    || response
                        .headers()
                        .get("content-type")
                        .and_then(|value| value.to_str().ok())
                        .is_some_and(|value| value.contains("text/event-stream")));
            crate::pool_response::PoolResponse::prepare(response, probe).await
        };
        let outcome = if failover && attempt > 1 {
            let bounded =
                tokio::time::timeout_at(tokio::time::Instant::from_std(deadline), attempt_outcome)
                    .await;
            let Ok(outcome) = bounded else {
                log_stop(state, request.correlation_id, attempt, "budget exhausted");
                break;
            };
            outcome
        } else {
            attempt_outcome.await
        };
        let (mut response, peeked) = match outcome {
            Ok(response) => response,
            Err(error) => {
                if failover && attempt < max_attempts {
                    note_failover(
                        state,
                        request.correlation_id,
                        attempt,
                        Some(&account),
                        RetryReason::Transport,
                    );
                    context.exclude.push(account.clone());
                    // A vendor reply (with its Retry-After) beats a later
                    // connection failure as the answer to relay.
                    if !matches!(last, Some(Ok(_))) {
                        last = Some(Err((account, error)));
                    }
                    continue;
                }
                if let Some(Ok(dispatched)) = last {
                    return Ok(dispatched);
                }
                return Err(transport_error(&request, Some(&account), &error));
            }
        };
        if let Some(actual) = crate::account_policy_scope::account() {
            account = actual;
        }
        let status = response.status().as_u16();
        if !crate::account_policy_scope::active()
            && let Some(router) = router
        {
            router.observe_upstream(&UpstreamObservation {
                account: &account,
                model: context.model.as_deref(),
                status,
                headers: response.headers(),
                body: &peeked,
                retry_after: retry_after_duration(response.headers()),
            });
        }
        if let Some(router) = router {
            response = response.observe(crate::pool_stream_limits::StreamLimits::new(
                router.clone(),
                account.clone(),
                context.model.clone(),
            ));
        }
        let dispatched = Dispatched {
            response,
            account,
            base_url,
            bytes_sent,
        };
        match classify_status(status) {
            Some(reason) if failover && attempt < max_attempts => {
                note_failover(
                    state,
                    request.correlation_id,
                    attempt,
                    Some(&dispatched.account),
                    reason,
                );
                context.exclude.push(dispatched.account.clone());
                // Dropping an earlier failure closes its connection.
                last = Some(Ok(dispatched));
            }
            _ => return Ok(dispatched),
        }
    }
    match last {
        Some(Ok(dispatched)) => Ok(dispatched),
        Some(Err((account, error))) => Err(transport_error(&request, Some(&account), &error)),
        None => Err(error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "account_unavailable",
            "no subscription account could serve the request",
        )),
    }
}

/// Send one attempt on `account`, replaying it once with a refreshed token
/// when the vendor rejects an unexpired one, and record the credential
/// evidence for the response.
async fn send_attempt(
    request: &CodexDispatch<'_>,
    account: &str,
    token: SubscriptionToken,
    base_url: &str,
    body: Bytes,
) -> Result<reqwest::Response, String> {
    let state = request.state;
    let provider = request.provider;
    crate::account_policy_scope::credential(account, &token);
    let upstream_url = join_subscription_url(provider, base_url, request.path);
    let custom_base_url = state.subscription_base_url.is_some();
    let shared_client =
        crate::upstream_client::subscription_client(&state.client, provider, custom_base_url);
    // A pooled account sends on its own connections, with its own Cloudflare
    // cookies and through its own egress proxy (issue #678).
    let cookies = if provider == SubscriptionProvider::Codex && !custom_base_url {
        CookieMode::CodexCloudflare
    } else {
        CookieMode::None
    };
    let router = state.account_router.as_ref();
    let upstream_client =
        crate::account_http::pooled_client(router, Some(account), shared_client, cookies)?;
    let refresh_client =
        crate::account_http::pooled_client(router, Some(account), &state.client, CookieMode::None)?;
    let upstream_client = &upstream_client;
    let build_request = |token: &SubscriptionToken| {
        let mut builder = upstream_client.post(upstream_url.clone());
        if request.native_protocol {
            let mut native_headers =
                crate::proxy::native_request_headers(request.headers, &token.access_token);
            if provider == SubscriptionProvider::Codex
                && let Some(account_id) = token.account_id.as_deref()
                && let Ok(value) = HeaderValue::from_str(account_id)
            {
                native_headers.insert("chatgpt-account-id", value);
            }
            builder = builder.headers(native_headers);
        } else {
            builder = builder
                .header("content-type", "application/json")
                .header("authorization", format!("Bearer {}", token.access_token));
            if let Some(request_id) = crate::proxy::translated_request_id(request.headers) {
                builder = builder.header("x-request-id", request_id);
            }
            for (name, value) in subscription_headers(provider, token, request.responses_mode) {
                builder = builder.header(name, value);
            }
        }
        builder.body(body.clone())
    };
    let mut response = state
        .request_log
        .send_upstream(
            request.correlation_id,
            upstream_client,
            build_request(&token),
        )
        .await
        .map_err(|error| error.to_string())?;
    // Evidence must name the credential that produced the final upstream
    // response. A successful reactive retry replaces this below.
    let mut evidence_token = Some(token.clone());
    // A validated automatic route owns one account/catalog decision for the
    // whole request. Its 401 is returned unchanged: the ordinary recovery
    // ladder could adopt a different account that appeared after validation.
    // A non-validated pinned route keeps the established reactive refresh.
    // A `401` is the vendor disproving the token's own `exp` claim: it may have
    // invalidated the access token early, and the stored expiry is no evidence
    // to the contrary. Refresh and replay the request exactly once, so a
    // recoverable credential is not reported as dead (issue #205).
    if request.validated.is_none()
        && crate::account_policy_scope::reactive_refresh_allowed(account)
        && response.status() == reqwest::StatusCode::UNAUTHORIZED
        && let Some(refreshed) = state
            .subscription_cache
            .refresh_rejected(
                &refresh_client,
                provider,
                account,
                token,
                crate::operation_context::now().timestamp_millis(),
            )
            .await
    {
        crate::account_policy_scope::credential(account, &refreshed);
        tracing::info!(
            "{provider} rejected an unexpired access token; retrying once with a refreshed one"
        );
        match state
            .request_log
            .send_upstream(
                request.correlation_id,
                upstream_client,
                build_request(&refreshed),
            )
            .await
        {
            // Only one retry: a second 401 is surfaced rather than looped.
            Ok(retried) => {
                response = retried;
                evidence_token = Some(refreshed);
            }
            Err(error) => {
                tracing::warn!("{provider} retry after refresh failed: {error}");
                // B produced no HTTP status. The retained A response is still
                // returned to the caller, but its verdict was superseded by
                // the successful rotation and must not be attributed to B.
                evidence_token = None;
            }
        }
    }
    if !crate::account_policy_scope::active()
        && let Some(evidence_token) = evidence_token.as_ref()
    {
        state
            .subscription_cache
            .record_status_for_credential(
                provider,
                account,
                evidence_token,
                response.status().as_u16(),
            )
            .await;
    }
    Ok(response)
}

fn transport_error(request: &CodexDispatch<'_>, account: Option<&str>, error: &str) -> Response {
    request
        .state
        .metrics
        .record_request(request.surface, 502, account);
    error_response(
        StatusCode::BAD_GATEWAY,
        "api_error",
        &format!(
            "{} subscription upstream request failed: {error}",
            request.provider
        ),
    )
}

/// Pick the account for one attempt and return it with a token ready to send.
async fn select_account(
    state: &AppState,
    provider: SubscriptionProvider,
    validated: Option<&crate::model_routing::ValidatedSubscription>,
    context: &RoutingContext,
) -> Result<(String, SubscriptionToken), SelectError> {
    let selected = if let Some(validated) = validated {
        let selected = validated
            .for_dispatch_with_context(state, context)
            .await
            .map_err(|error| {
                SelectError::new(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "authentication_error",
                    error,
                )
            })?;
        // Automatic model routing already refreshed and validated this exact
        // token. Refreshing again here could adopt a credential that appeared
        // after catalog validation, recreating the account-crossing race.
        return Ok((selected.name, selected.token));
    } else if let Some(router) = state.account_router.as_ref() {
        router
            .select_subscription_where_authoritative(context, &state.subscription_cache, |_| true)
            .await
            .map_err(|error| {
                SelectError::new(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "account_unavailable",
                    error.to_string(),
                )
            })?
    } else {
        let Some(reader) = state.subscription_reader.as_ref() else {
            return Err(SelectError::new(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                "subscription credentials reader is not configured",
            ));
        };
        state
            .subscription_cache
            .register_reader(crate::credential_recovery_store::PRIMARY_ACCOUNT, reader);
        let Ok(Some(disk_token)) = state
            .subscription_cache
            .load_authoritative(provider, crate::credential_recovery_store::PRIMARY_ACCOUNT)
            .await
        else {
            return Err(SelectError::new(
                StatusCode::BAD_GATEWAY,
                "authentication_error",
                format!("failed to read {provider} subscription credentials"),
            ));
        };
        crate::accounts::SelectedSubscriptionAccount {
            name: "primary".to_string(),
            token: disk_token,
        }
    };
    // Pinned routing performs its ordinary serving-path refresh here, through
    // the account's own egress.
    let client = crate::account_http::pooled_client(
        state.account_router.as_ref(),
        Some(&selected.name),
        &state.client,
        CookieMode::None,
    )
    .map_err(|error| {
        SelectError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "account_unavailable",
            error,
        )
    })?;
    let token = state
        .subscription_cache
        .get_fresh_loaded(
            &client,
            provider,
            &selected.name,
            selected.token,
            crate::operation_context::now().timestamp_millis(),
        )
        .await
        .map_err(|error| {
            SelectError::new(
                StatusCode::SERVICE_UNAVAILABLE,
                "authentication_error",
                error,
            )
        })?;
    Ok((selected.name, token))
}

//! Relay a subscription upstream response to the client: stream rewriting and
//! translation, non-streaming collapse and validation, and error re-shaping.

use axum::body::Body;
use axum::http::{HeaderValue, StatusCode};
use axum::response::Response;
use futures_util::StreamExt;

use super::{SubscriptionResponseShape, codex_sse_to_response_json, is_event_stream};
use crate::metrics::Surface;
use crate::proxy::{AppState, error_response, relay_response_headers};
use crate::subscription::SubscriptionProvider;

/// What the relay needs from the request that produced the response.
pub(super) struct Relay<'a> {
    pub state: &'a AppState,
    pub claims: &'a crate::token::TokenClaims,
    pub surface: Surface,
    pub path: &'a str,
    pub routing_body: &'a serde_json::Value,
    pub provider: SubscriptionProvider,
    pub native_protocol: bool,
    pub response_shape: SubscriptionResponseShape,
    pub model_policy: crate::model_contract::ModelAccessPolicy,
    pub selector_kind: crate::model_contract::ModelSelectorKind,
    pub emulated_output_limit: Option<u64>,
    pub resolved_model: Option<String>,
    pub selected_account: Option<String>,
    pub base_url: String,
    pub correlation_id: String,
    pub stream_requested: bool,
    pub bytes_sent: u64,
    pub reservation: crate::usage::ReservationGuard,
}

/// Turn the final upstream response into the client's response.
pub(super) async fn relay(
    relay: Relay<'_>,
    status: StatusCode,
    upstream_resp: crate::pool_response::PoolResponse,
) -> Response {
    let Relay {
        state,
        claims,
        surface,
        path,
        routing_body,
        provider,
        native_protocol,
        response_shape,
        model_policy,
        selector_kind,
        emulated_output_limit,
        resolved_model,
        selected_account,
        base_url,
        correlation_id,
        stream_requested,
        bytes_sent,
        mut reservation,
    } = relay;
    let content_type = upstream_resp
        .headers()
        .get("content-type")
        .cloned()
        .unwrap_or_else(|| HeaderValue::from_static("application/json"));
    // Relay the same safe end-to-end response fields as the Claude path,
    // including provider-specific quota signals and request IDs.
    let response_headers = relay_response_headers(upstream_resp.headers());

    let codex = provider == SubscriptionProvider::Codex;
    if stream_requested || ((!codex || native_protocol) && is_event_stream(&content_type)) {
        // The Codex backend streams SSE but labels it `application/json`; re-label
        // so SSE-aware clients treat the body as the stream it is.
        let stream_content_type = if codex && !native_protocol {
            HeaderValue::from_static("text/event-stream")
        } else {
            content_type
        };
        let requested_model = routing_body
            .get("model")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let include_usage = routing_body
            .pointer("/stream_options/include_usage")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        let stop_sequences = crate::stop_sequences::from_value(routing_body.get("stop"));
        let translator = crate::responses::ResponsesChatStreamTranslator::new(requested_model)
            .with_include_usage(include_usage)
            .with_stop_sequences(stop_sequences)
            .with_output_token_limit(emulated_output_limit);
        let rewriter = crate::output_limit::ResponsesStreamRewriter::new(
            requested_model,
            emulated_output_limit,
        )
        .with_model_policy(&model_policy)
        .with_selector_kind(selector_kind);
        // Native responses remain byte-transparent. Translated streams are
        // inspected before content so the first concrete identity is truthful
        // and later identity drift terminates the stream.
        let rewrite_passthrough = !native_protocol
            && response_shape == SubscriptionResponseShape::Passthrough
            && rewriter.active();
        let response_log = std::sync::Arc::clone(&state.request_log);
        let completion_audit = (!native_protocol && status.is_success()).then(|| {
            crate::audit::ResponseModelAudit::new(state, claims, surface, path)
                .with_models(Some(requested_model), resolved_model.as_deref())
                .with_provider(Some(provider.as_str()))
                .with_provider_account(selected_account.as_deref())
                .with_provider_endpoint(Some(&base_url))
                .with_selector_kind(selector_kind)
        });
        let rewrite_state =
            std::sync::Arc::new(std::sync::Mutex::new((rewriter, translator, false)));
        let chunk_rewrite_state = std::sync::Arc::clone(&rewrite_state);
        let chunk_completion_audit = completion_audit.clone();
        let mut usage = status
            .is_success()
            .then(|| reservation.take().into_tracker());
        let stream = upstream_resp.bytes_stream().map(move |chunk| {
            chunk.map_or_else(
                |error| Err(std::io::Error::other(error)),
                |bytes| {
                    response_log.record_upstream_body(&correlation_id, &bytes);
                    if let Some(tracker) = &mut usage {
                        tracker.feed(&bytes);
                    }
                    let output = {
                        let mut rewrite = chunk_rewrite_state
                            .lock()
                            .expect("stream rewrite state lock");
                        let (rewriter, translator, model_audited) = &mut *rewrite;
                        let output = if codex
                            && response_shape == SubscriptionResponseShape::ChatCompletion
                        {
                            let verified = rewriter.push(&bytes);
                            bytes::Bytes::from(translator.push(verified.as_bytes()).join(""))
                        } else if rewrite_passthrough {
                            bytes::Bytes::from(rewriter.push(&bytes))
                        } else {
                            bytes
                        };
                        let served_model = rewriter.upstream_model().map(str::to_string);
                        if !*model_audited
                            && let (Some(audit), Some(served_model)) =
                                (chunk_completion_audit.as_ref(), served_model.as_deref())
                        {
                            audit.record_verified(served_model);
                            *model_audited = true;
                        }
                        drop(rewrite);
                        output
                    };
                    Ok(output)
                },
            )
        });
        let finish_rewrite = codex && response_shape == SubscriptionResponseShape::ChatCompletion
            || rewrite_passthrough;
        let stream = stream.chain(futures_util::stream::once(async move {
            let output = {
                let mut rewrite = rewrite_state.lock().expect("stream rewrite state lock");
                let (rewriter, translator, model_audited) = &mut *rewrite;
                let verified = if finish_rewrite {
                    rewriter.finish()
                } else {
                    String::new()
                };
                let output = if codex && response_shape == SubscriptionResponseShape::ChatCompletion
                {
                    translator.push(verified.as_bytes()).join("")
                } else {
                    verified
                };
                let served_model = rewriter.upstream_model().map(str::to_string);
                if !*model_audited
                    && let (Some(audit), Some(served_model)) =
                        (completion_audit.as_ref(), served_model.as_deref())
                {
                    audit.record_verified(served_model);
                    *model_audited = true;
                }
                drop(rewrite);
                output
            };
            Ok::<bytes::Bytes, std::io::Error>(bytes::Bytes::from(output))
        }));
        let dialect = (codex
            && status.is_success()
            && crate::request_log::body_is_inspectable(&response_headers))
        .then_some(
            if response_shape == SubscriptionResponseShape::ChatCompletion {
                crate::stream_termination::StreamDialect::OpenAiChat
            } else {
                crate::stream_termination::StreamDialect::Responses
            },
        );
        let stream = crate::stream_termination::in_band_errors(stream, dialect);
        let mut response = Response::new(Body::from_stream(stream));
        *response.status_mut() = status;
        *response.headers_mut() = response_headers;
        response
            .headers_mut()
            .insert("content-type", stream_content_type);
        return response;
    }

    let upstream_body = match upstream_resp.bytes().await {
        Ok(bytes) => bytes,
        Err(e) => {
            state
                .metrics
                .record_request(surface, 502, selected_account.as_deref());
            return error_response(
                StatusCode::BAD_GATEWAY,
                "api_error",
                &format!("{provider} subscription upstream body read failed: {e}"),
            );
        }
    };
    state
        .request_log
        .record_upstream_body(&correlation_id, &upstream_body);
    state
        .metrics
        .record_bytes(bytes_sent, upstream_body.len() as u64);
    if status.is_success() {
        let mut usage = reservation.take().into_tracker();
        usage.feed(&upstream_body);
    }

    if native_protocol {
        let mut response = Response::new(Body::from(upstream_body));
        *response.status_mut() = status;
        *response.headers_mut() = response_headers;
        return response;
    }

    // Codex returns SSE even for `stream:false`, labelled as JSON. Collapse it
    // to the final Responses object for non-streaming clients.
    let mut response_body = upstream_body;
    if codex && status.is_success() {
        if let Some(json) = codex_sse_to_response_json(&response_body) {
            response_body = bytes::Bytes::from(json);
        }
        if response_shape == SubscriptionResponseShape::ChatCompletion {
            let requested_model = routing_body
                .get("model")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let parsed = match serde_json::from_slice::<serde_json::Value>(&response_body) {
                Ok(value) => value,
                Err(error) => {
                    return error_response(
                        StatusCode::BAD_GATEWAY,
                        "api_error",
                        &format!(
                            "Codex subscription upstream returned an invalid response: {error}"
                        ),
                    );
                }
            };
            let served_model =
                match crate::model_contract::validate_translated_response_for_selector(
                    requested_model,
                    &parsed,
                    &model_policy,
                    selector_kind,
                ) {
                    Ok(served_model) => served_model,
                    Err(error) => {
                        return error_response(
                            StatusCode::BAD_GATEWAY,
                            &error.code,
                            &error.to_string(),
                        );
                    }
                };
            if let Some(served_model) = served_model.as_deref() {
                crate::audit::ResponseModelAudit::new(state, claims, surface, path)
                    .with_models(Some(requested_model), resolved_model.as_deref())
                    .with_provider(Some(provider.as_str()))
                    .with_provider_account(selected_account.as_deref())
                    .with_provider_endpoint(Some(&base_url))
                    .with_selector_kind(selector_kind)
                    .record_completed(served_model);
            }
            let mut translated =
                crate::responses::response_to_chat_completion(&parsed, requested_model);
            crate::responses::enforce_chat_stop(
                &mut translated,
                &crate::stop_sequences::from_value(routing_body.get("stop")),
            );
            if let Some(limit) = emulated_output_limit {
                crate::output_limit::enforce_chat_limit(&mut translated, limit);
            }
            response_body = bytes::Bytes::from(
                serde_json::to_vec(&translated).expect("JSON values always serialize"),
            );
        } else if let Ok(mut parsed) = serde_json::from_slice::<serde_json::Value>(&response_body) {
            let requested_model = routing_body
                .get("model")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let served_model =
                match crate::model_contract::validate_translated_response_for_selector(
                    requested_model,
                    &parsed,
                    &model_policy,
                    selector_kind,
                ) {
                    Ok(served_model) => served_model,
                    Err(error) => {
                        return error_response(
                            StatusCode::BAD_GATEWAY,
                            &error.code,
                            &error.to_string(),
                        );
                    }
                };
            if let Some(served_model) = served_model.as_deref() {
                crate::audit::ResponseModelAudit::new(state, claims, surface, path)
                    .with_models(Some(requested_model), resolved_model.as_deref())
                    .with_provider(Some(provider.as_str()))
                    .with_provider_account(selected_account.as_deref())
                    .with_provider_endpoint(Some(&base_url))
                    .with_selector_kind(selector_kind)
                    .record_completed(served_model);
            }
            if let Some(limit) = emulated_output_limit {
                crate::output_limit::enforce_response_limit(&mut parsed, limit);
            }
            response_body = bytes::Bytes::from(
                serde_json::to_vec(&parsed).expect("JSON values always serialize"),
            );
        }

        let mut response = Response::new(Body::from(response_body));
        *response.status_mut() = status;
        *response.headers_mut() = response_headers;
        response
            .headers_mut()
            .insert("content-type", HeaderValue::from_static("application/json"));
        return response;
    }

    if status.is_success()
        && response_shape == SubscriptionResponseShape::Passthrough
        && let Ok(parsed) = serde_json::from_slice::<serde_json::Value>(&response_body)
    {
        let requested_model = routing_body
            .get("model")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let served_model = match crate::model_contract::validate_translated_response_for_selector(
            requested_model,
            &parsed,
            &model_policy,
            selector_kind,
        ) {
            Ok(served_model) => served_model,
            Err(error) => {
                return error_response(StatusCode::BAD_GATEWAY, &error.code, &error.to_string());
            }
        };
        if let Some(served_model) = served_model.as_deref() {
            crate::audit::ResponseModelAudit::new(state, claims, surface, path)
                .with_models(Some(requested_model), resolved_model.as_deref())
                .with_provider(Some(provider.as_str()))
                .with_provider_account(selected_account.as_deref())
                .with_provider_endpoint(Some(&base_url))
                .with_selector_kind(selector_kind)
                .record_completed(served_model);
        }
        response_body =
            bytes::Bytes::from(serde_json::to_vec(&parsed).expect("JSON values always serialize"));
    }

    // Re-shape failures to the caller's dialect and remove operator subscription
    // metadata. The raw body stays in the request log for diagnosis (#213).
    let (response_body, content_type) = if status.is_success() {
        (response_body, content_type)
    } else {
        let rendered = crate::api_error::openai_error_body(status.as_u16(), &response_body);
        (
            bytes::Bytes::from(
                serde_json::to_vec(&rendered).expect("JSON values always serialize"),
            ),
            HeaderValue::from_static("application/json"),
        )
    };

    let mut response = Response::new(Body::from(response_body));
    *response.status_mut() = status;
    *response.headers_mut() = response_headers;
    response.headers_mut().insert("content-type", content_type);
    response
}

