use base64::Engine as _;
use serde_json::Value;

use super::{
    Credits, ExtraUsage, NamedLimit, SpendControl, SpendLimit, SubscriptionToken,
    SubscriptionUsage, UsageProvider, UsageState, UsageWindow,
};

const ANTHROPIC_WINDOWS: [&str; 6] = [
    "five_hour",
    "seven_day",
    "seven_day_oauth_apps",
    "seven_day_opus",
    "seven_day_sonnet",
    "cinder_cove",
];

pub(super) fn recognizable_anthropic_usage(value: &Value) -> bool {
    ANTHROPIC_WINDOWS.into_iter().any(|name| {
        value
            .get(name)
            .and_then(Value::as_object)
            .is_some_and(|window| {
                window.contains_key("utilization") || window.contains_key("resets_at")
            })
    }) || value
        .get("extra_usage")
        .and_then(Value::as_object)
        .is_some_and(|extra| {
            [
                "is_enabled",
                "monthly_limit",
                "used_credits",
                "utilization",
                "currency",
                "resets_at",
            ]
            .into_iter()
            .any(|key| extra.contains_key(key))
        })
        || value
            .get("limits")
            .and_then(Value::as_array)
            .is_some_and(|limits| limits.iter().any(recognizable_anthropic_limit))
}

pub(super) fn recognizable_openai_usage(value: &Value) -> bool {
    value.get("rate_limit").is_some_and(|rate_limit| {
        rate_limit.get("allowed").and_then(Value::as_bool).is_some()
            || rate_limit
                .get("limit_reached")
                .and_then(Value::as_bool)
                .is_some()
            || codex_windows(rate_limit).iter().any(|window| {
                window.used_percentage.is_some()
                    || window.resets_at.is_some()
                    || window.window_seconds.is_some()
            })
    }) || openai_credits(value).is_some()
        || openai_spend_control(value).is_some()
        || !openai_additional_limits(value).is_empty()
        || value
            .pointer("/rate_limit_reached_type/type")
            .and_then(Value::as_str)
            .is_some()
        || reset_credits_available(value).is_some()
}

fn recognizable_anthropic_limit(value: &Value) -> bool {
    let Some(limit) = value.as_object() else {
        return false;
    };
    (limit.get("kind").and_then(Value::as_str).is_some()
        || limit.get("group").and_then(Value::as_str).is_some()
        || value
            .pointer("/scope/model/display_name")
            .and_then(Value::as_str)
            .is_some())
        && (limit.get("percent").and_then(Value::as_f64).is_some()
            || limit.get("resets_at").and_then(Value::as_str).is_some())
}

pub(super) fn normalize_anthropic(value: &Value) -> SubscriptionUsage {
    let mut result = empty_usage(UsageProvider::Anthropic);
    result.state = UsageState::Available;
    result.windows = anthropic_windows(value);
    result.extra_usage = anthropic_extra_usage(value);
    result.additional_limits = anthropic_dynamic_limits(value);
    result.limit_reached = Some(anthropic_limit_reached(&result));
    result.status = if result.limit_reached == Some(true) {
        "limit_reached".into()
    } else {
        "available".into()
    };
    result
}

pub(super) fn anthropic_windows(value: &Value) -> Vec<UsageWindow> {
    ANTHROPIC_WINDOWS
        .into_iter()
        .filter_map(|name| {
            let window = value.get(name)?.as_object()?;
            Some(window_from(
                name,
                window.get("utilization").and_then(Value::as_f64),
                window
                    .get("resets_at")
                    .and_then(|value| safe_string(value, 128)),
                None,
            ))
        })
        .collect()
}

fn anthropic_extra_usage(value: &Value) -> Option<ExtraUsage> {
    let extra = value.get("extra_usage")?.as_object()?;
    let monthly_limit = safe_number(extra.get("monthly_limit"));
    let used_credits = safe_number(extra.get("used_credits"));
    let utilization = safe_percentage(extra.get("utilization"));
    let remaining_credits = monthly_limit
        .zip(used_credits)
        .map(|(limit, used)| (limit - used).max(0.0));
    let result = ExtraUsage {
        is_enabled: extra.get("is_enabled").and_then(Value::as_bool),
        monthly_limit,
        used_credits,
        remaining_credits,
        utilization,
        currency: extra
            .get("currency")
            .and_then(|value| safe_string(value, 16)),
        resets_at: extra
            .get("resets_at")
            .or_else(|| extra.get("reset_at"))
            .and_then(|value| safe_string(value, 128)),
    };
    (result.is_enabled.is_some()
        || result.monthly_limit.is_some()
        || result.used_credits.is_some()
        || result.utilization.is_some()
        || result.currency.is_some()
        || result.resets_at.is_some())
    .then_some(result)
}

fn anthropic_dynamic_limits(value: &Value) -> Vec<NamedLimit> {
    value
        .get("limits")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|limit| anthropic_dynamic_limit(value, limit))
        .collect()
}

fn anthropic_dynamic_limit(root: &Value, value: &Value) -> Option<NamedLimit> {
    let kind = value.get("kind").and_then(|value| safe_string(value, 128));
    let group = value.get("group").and_then(|value| safe_string(value, 128));
    let model_display_name = value
        .pointer("/scope/model/display_name")
        .and_then(|value| safe_string(value, 256));
    let percentage = safe_percentage(value.get("percent"));
    let resets_at = value
        .get("resets_at")
        .and_then(|value| safe_string(value, 128));
    if kind.is_none() && group.is_none() && model_display_name.is_none() {
        return None;
    }
    if percentage.is_none() && resets_at.is_none() {
        return None;
    }
    if duplicate_anthropic_legacy(
        root,
        kind.as_deref(),
        group.as_deref(),
        model_display_name.as_deref(),
    ) {
        return None;
    }
    let name = model_display_name
        .as_ref()
        .or(kind.as_ref())
        .or(group.as_ref())?
        .clone();
    Some(NamedLimit {
        name,
        limit_name: None,
        metered_feature: None,
        kind,
        group,
        model_display_name,
        allowed: None,
        limit_reached: percentage.map(|percent| percent >= 100.0),
        windows: vec![window_from("limit", percentage, resets_at, None)],
        used: None,
        limit: None,
    })
}

fn duplicate_anthropic_legacy(
    root: &Value,
    kind: Option<&str>,
    group: Option<&str>,
    display: Option<&str>,
) -> bool {
    let kind = kind.map(normalize_label);
    let group = group.map(normalize_label);
    let display = display.map(normalize_label);
    ANTHROPIC_WINDOWS.into_iter().any(|legacy| {
        if root.get(legacy).and_then(Value::as_object).is_none() {
            return false;
        }
        let legacy_normalized = normalize_label(legacy);
        if kind.as_deref() == Some(legacy_normalized.as_str()) {
            return true;
        }
        let Some(model_suffix) = legacy.strip_prefix("seven_day_") else {
            return false;
        };
        group.as_deref() == Some("model")
            && kind.as_deref().is_some_and(|kind| {
                kind.contains("week") || kind.contains("seven_day") || kind.contains("scoped")
            })
            && display
                .as_deref()
                .is_some_and(|display| display.contains(&normalize_label(model_suffix)))
    })
}

fn normalize_label(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                '_'
            }
        })
        .collect::<String>()
        .split('_')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("_")
}

fn anthropic_limit_reached(usage: &SubscriptionUsage) -> bool {
    usage
        .windows
        .iter()
        .any(|window| window.used_percentage == Some(100.0))
        || usage
            .additional_limits
            .iter()
            .any(|limit| limit.limit_reached == Some(true))
        || usage
            .extra_usage
            .as_ref()
            .is_some_and(|extra| extra.is_enabled == Some(true) && extra.utilization == Some(100.0))
}

pub(super) fn apply_anthropic_profile(usage: &mut SubscriptionUsage, profile: &Value) {
    let organization = profile.get("organization").unwrap_or(profile);
    if usage.status != "limit_reached" {
        usage.status = organization
            .get("subscription_status")
            .and_then(Value::as_str)
            .unwrap_or("available")
            .to_string();
    }
    usage.plan = organization
        .get("subscription_type")
        .or_else(|| profile.get("subscription_type"))
        .and_then(Value::as_str)
        .map(str::to_string);
    usage.subscription_created = organization
        .get("subscription_created_at")
        .and_then(Value::as_str)
        .map(str::to_string);
    usage.trial_end = organization
        .get("claude_code_trial_ends_at")
        .and_then(Value::as_str)
        .map(str::to_string);
    usage.subscription_end = organization
        .get("subscription_ends_at")
        .and_then(Value::as_str)
        .map(str::to_string);
}

pub(super) fn normalize_openai(value: &Value, token: &SubscriptionToken) -> SubscriptionUsage {
    let rate_limit = value.get("rate_limit").unwrap_or(&Value::Null);
    let mut result = empty_usage(UsageProvider::OpenAi);
    result.state = UsageState::Available;
    result.allowed = rate_limit.get("allowed").and_then(Value::as_bool);
    result.limit_reached = rate_limit.get("limit_reached").and_then(Value::as_bool);
    result.plan = value
        .get("plan_type")
        .and_then(Value::as_str)
        .map(str::to_string)
        .or_else(|| openai_claim(token, "chatgpt_plan_type"));
    result.subscription_end = openai_claim(token, "chatgpt_subscription_active_until");
    result.windows = codex_windows(rate_limit);
    result.additional_limits = openai_additional_limits(value);
    result.credits = openai_credits(value);
    result.spend_control = openai_spend_control(value);
    result.rate_limit_reached_type = value
        .pointer("/rate_limit_reached_type/type")
        .and_then(|value| safe_string(value, 128));
    result.rate_limit_reset_credits_available = reset_credits_available(value);
    result.status = openai_status(&result).into();
    result
}

fn openai_additional_limits(value: &Value) -> Vec<NamedLimit> {
    value
        .get("additional_rate_limits")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|limit| {
            let limit_name = limit
                .get("limit_name")
                .and_then(|value| safe_string(value, 256));
            let metered_feature = limit
                .get("metered_feature")
                .and_then(|value| safe_string(value, 256));
            let name = limit_name.as_ref().or(metered_feature.as_ref())?.clone();
            let rate_limit = limit.get("rate_limit").unwrap_or(&Value::Null);
            Some(NamedLimit {
                name,
                limit_name,
                metered_feature,
                kind: None,
                group: None,
                model_display_name: None,
                allowed: rate_limit.get("allowed").and_then(Value::as_bool),
                limit_reached: rate_limit.get("limit_reached").and_then(Value::as_bool),
                windows: codex_windows(rate_limit),
                used: None,
                limit: None,
            })
        })
        .collect()
}

fn openai_credits(value: &Value) -> Option<Credits> {
    let credits = value.get("credits")?.as_object()?;
    let balance = credits.get("balance").and_then(safe_numeric_string);
    let result = Credits {
        balance,
        has_credits: credits.get("has_credits").and_then(Value::as_bool),
        unlimited: credits.get("unlimited").and_then(Value::as_bool),
        overage_limit_reached: credits
            .get("overage_limit_reached")
            .and_then(Value::as_bool),
        approximate_local_messages: credits
            .get("approx_local_messages")
            .and_then(numeric_message_estimate),
        approximate_cloud_messages: credits
            .get("approx_cloud_messages")
            .and_then(numeric_message_estimate),
    };
    (result.balance.is_some()
        || result.has_credits.is_some()
        || result.unlimited.is_some()
        || result.overage_limit_reached.is_some()
        || result.approximate_local_messages.is_some()
        || result.approximate_cloud_messages.is_some())
    .then_some(result)
}

fn numeric_message_estimate(value: &Value) -> Option<u64> {
    if let Some(count) = value.as_u64() {
        return Some(count);
    }
    let values = value.as_array()?;
    let counts = values
        .iter()
        .filter_map(|entry| entry.get("count").and_then(Value::as_u64))
        .collect::<Vec<_>>();
    (!counts.is_empty()).then(|| counts.into_iter().fold(0_u64, u64::saturating_add))
}

fn openai_spend_control(value: &Value) -> Option<SpendControl> {
    let control = value.get("spend_control")?.as_object()?;
    let individual_limit = control
        .get("individual_limit")
        .and_then(Value::as_object)
        .map(|limit| SpendLimit {
            source: limit.get("source").and_then(|value| safe_string(value, 64)),
            limit: limit.get("limit").and_then(safe_numeric_string),
            used: limit.get("used").and_then(safe_numeric_string),
            remaining: limit.get("remaining").and_then(safe_numeric_string),
            used_percentage: safe_percentage(limit.get("used_percent")),
            remaining_percentage: safe_percentage(limit.get("remaining_percent")),
            reset_after_seconds: limit.get("reset_after_seconds").and_then(Value::as_u64),
            resets_at: limit.get("reset_at").and_then(epoch_timestamp),
        });
    let result = SpendControl {
        reached: control.get("reached").and_then(Value::as_bool),
        individual_limit,
    };
    (result.reached.is_some() || result.individual_limit.is_some()).then_some(result)
}

fn reset_credits_available(value: &Value) -> Option<u64> {
    value
        .get("rate_limit_reset_credits")
        .or_else(|| value.get("rate_limit_reset_credits_summary"))
        .and_then(|credits| credits.get("available_count"))
        .and_then(Value::as_u64)
}

fn openai_status(usage: &SubscriptionUsage) -> &'static str {
    if usage.rate_limit_reached_type.is_some() {
        "limit_reached"
    } else if usage
        .spend_control
        .as_ref()
        .is_some_and(|control| control.reached == Some(true))
    {
        "spend_control_reached"
    } else if usage
        .credits
        .as_ref()
        .is_some_and(|credits| credits.has_credits == Some(false))
    {
        "credits_unavailable"
    } else if usage.allowed == Some(false)
        || usage.limit_reached == Some(true)
        || usage
            .additional_limits
            .iter()
            .any(|limit| limit.allowed == Some(false) || limit.limit_reached == Some(true))
    {
        "limit_reached"
    } else {
        "available"
    }
}

fn codex_windows(value: &Value) -> Vec<UsageWindow> {
    [
        ("primary", "primary_window"),
        ("secondary", "secondary_window"),
    ]
    .into_iter()
    .filter_map(|(name, key)| {
        let window = value.get(key)?;
        Some(window_from(
            name,
            window.get("used_percent").and_then(Value::as_f64),
            window.get("reset_at").and_then(epoch_timestamp),
            window.get("limit_window_seconds").and_then(Value::as_u64),
        ))
    })
    .collect()
}

pub(super) fn openai_claim(token: &SubscriptionToken, key: &str) -> Option<String> {
    openai_claims(&token.access_token)?
        .get(key)
        .and_then(Value::as_str)
        .map(str::to_string)
}

pub(super) fn openai_claims(token: &str) -> Option<Value> {
    let payload = token.split('.').nth(1)?;
    let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(payload)
        .ok()?;
    let claims: Value = serde_json::from_slice(&bytes).ok()?;
    claims
        .get("https://api.openai.com/auth")?
        .as_object()
        .cloned()
        .map(Value::Object)
}

pub(super) fn normalize_zai(value: &Value, partial: bool) -> SubscriptionUsage {
    let mut result = empty_usage(UsageProvider::ZAi);
    result.state = UsageState::Available;
    result.status = if partial {
        "quota_available_details_unverified".into()
    } else {
        "available".into()
    };
    let limits = value
        .get("limits")
        .and_then(Value::as_array)
        .into_iter()
        .flatten();
    for limit in limits {
        let kind = limit
            .get("type")
            .and_then(Value::as_str)
            .unwrap_or("additional");
        let percentage = limit.get("percentage").and_then(Value::as_f64);
        if kind == "TOKENS_LIMIT" {
            result.windows.push(window_from(
                "five_hour_tokens",
                percentage,
                limit
                    .get("resetsAt")
                    .or_else(|| limit.get("resets_at"))
                    .and_then(Value::as_str)
                    .map(str::to_string),
                None,
            ));
        } else {
            result.additional_limits.push(NamedLimit {
                name: if kind == "TIME_LIMIT" {
                    "monthly_mcp".into()
                } else {
                    kind.to_ascii_lowercase()
                },
                limit_name: None,
                metered_feature: None,
                kind: Some(kind.to_string()),
                group: None,
                model_display_name: None,
                allowed: None,
                limit_reached: percentage.map(|percent| percent >= 100.0),
                windows: percentage
                    .map(|used| window_from("limit", Some(used), None, None))
                    .into_iter()
                    .collect(),
                used: limit.get("currentValue").and_then(Value::as_f64),
                limit: limit.get("usage").and_then(Value::as_f64),
            });
        }
    }
    result
}

pub(super) fn window_from(
    name: &str,
    used: Option<f64>,
    resets_at: Option<String>,
    window_seconds: Option<u64>,
) -> UsageWindow {
    let used = used.filter(|value| value.is_finite() && (0.0..=100.0).contains(value));
    UsageWindow {
        name: name.to_string(),
        used_percentage: used,
        remaining_percentage: used.map(|value| (100.0 - value).clamp(0.0, 100.0)),
        resets_at,
        window_seconds,
        contributors: None,
        reset_times: Vec::new(),
    }
}

pub(super) fn empty_usage(provider: UsageProvider) -> SubscriptionUsage {
    SubscriptionUsage {
        provider,
        state: UsageState::Unverified,
        status: "unverified".into(),
        pool: None,
        allowed: None,
        limit_reached: None,
        plan: None,
        windows: Vec::new(),
        additional_limits: Vec::new(),
        credits: None,
        extra_usage: None,
        spend_control: None,
        rate_limit_reached_type: None,
        rate_limit_reset_credits_available: None,
        subscription_end: None,
        trial_end: None,
        subscription_created: None,
        retry_after_seconds: None,
    }
}

fn safe_percentage(value: Option<&Value>) -> Option<f64> {
    safe_number(value).filter(|number| (0.0..=100.0).contains(number))
}

fn safe_number(value: Option<&Value>) -> Option<f64> {
    value
        .and_then(Value::as_f64)
        .filter(|number| number.is_finite() && *number >= 0.0)
}

fn safe_numeric_string(value: &Value) -> Option<String> {
    let text = value
        .as_str()
        .map(str::to_string)
        .or_else(|| value.as_f64().map(|number| number.to_string()))?;
    (text.len() <= 64
        && text
            .parse::<f64>()
            .is_ok_and(|number| number.is_finite() && number >= 0.0))
    .then_some(text)
}

fn safe_string(value: &Value, maximum: usize) -> Option<String> {
    let text = value.as_str()?;
    (!text.is_empty()
        && text.len() <= maximum
        && !text.chars().any(char::is_control)
        && !text.contains('@'))
    .then(|| text.to_string())
}

fn epoch_timestamp(value: &Value) -> Option<String> {
    value
        .as_i64()
        .and_then(|seconds| chrono::DateTime::from_timestamp(seconds, 0))
        .map(|time| time.to_rfc3339())
}

//! Credential-generation-bound caching for subscription usage probes.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, OnceLock};
use std::time::{Duration, Instant};

use sha2::{Digest as _, Sha256};

use super::{
    AppState, ProbeResult, SubscriptionProvider, SubscriptionToken, SubscriptionUsage,
    UsageProvider, credential_unavailable, probe_oauth_loaded_at, probe_zai_provider,
    selected_lefine, unavailable_lefine_usage,
};

const STANDARD_CACHE_TTL: Duration = Duration::from_secs(3 * 60);
const ANTHROPIC_CACHE_TTL: Duration = Duration::from_secs(13 * 60);

#[derive(Clone)]
struct CacheEntry {
    value: SubscriptionUsage,
    expires: Instant,
}

#[derive(Clone, Debug, Eq, Hash, PartialEq)]
struct CacheKey {
    subject: String,
    provider: UsageProvider,
    /// Hash of the active credential and provider endpoint/configuration.
    generation: String,
}

static CACHE: OnceLock<Mutex<HashMap<CacheKey, CacheEntry>>> = OnceLock::new();
static IN_FLIGHT: OnceLock<Mutex<HashMap<CacheKey, Arc<tokio::sync::Mutex<()>>>>> = OnceLock::new();

enum PreparedProbe {
    OAuth {
        subscription: SubscriptionProvider,
        token: SubscriptionToken,
    },
    ZAi(crate::providers::ResolvedProvider),
    Lefine(crate::providers::ResolvedProvider),
}

pub(super) async fn cached_or_probe(
    state: &AppState,
    subject: &str,
    principal: &str,
    provider: UsageProvider,
) -> ProbeResult {
    cached_or_probe_at(state, subject, principal, provider, None).await
}

pub(super) async fn cached_or_probe_at(
    state: &AppState,
    subject: &str,
    principal: &str,
    provider: UsageProvider,
    refresh_url_override: Option<&str>,
) -> ProbeResult {
    // Boxed so this wrapper does not grow every caller's future.
    let result = Box::pin(probe_through_cache(
        state,
        subject,
        principal,
        provider,
        refresh_url_override,
    ))
    .await;
    match (provider, result) {
        (UsageProvider::ZAi, ProbeResult::Usage(mut usage)) => {
            // Applied after the cache: the quota endpoint keeps reporting an
            // account z.ai refuses to serve, and the refusal clears as soon as
            // a request succeeds (issue #657).
            if let Some(exhaustion) = crate::zai_coding_plan::recorded_exhaustion(state) {
                usage.state = super::UsageState::Unavailable;
                usage.status = "exhausted".into();
                usage.allowed = Some(false);
                usage.limit_reached = Some(true);
                usage.rate_limit_reached_type = Some(exhaustion.summary());
            }
            ProbeResult::Usage(usage)
        }
        (_, result) => result,
    }
}

async fn probe_through_cache(
    state: &AppState,
    subject: &str,
    principal: &str,
    provider: UsageProvider,
    refresh_url_override: Option<&str>,
) -> ProbeResult {
    loop {
        let prepared = match prepare_probe(state, principal, provider).await {
            Ok(prepared) => prepared,
            Err(result) => return result,
        };
        let key = cache_key(state, subject, provider, &prepared);
        if let Some(value) = cached_value(&key) {
            return ProbeResult::Usage(Box::new(value));
        }
        let gate = IN_FLIGHT
            .get_or_init(Default::default)
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .entry(key.clone())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone();
        let guard = gate.lock().await;

        // A preceding caller can refresh the credential while this caller is
        // waiting. Rebind to the current generation instead of probing the
        // predecessor after the first result was already published.
        let prepared = match prepare_probe(state, principal, provider).await {
            Ok(prepared) => prepared,
            Err(result) => {
                drop(guard);
                release_gate(&key, &gate);
                return result;
            }
        };
        let current_key = cache_key(state, subject, provider, &prepared);
        if current_key != key {
            drop(guard);
            release_gate(&key, &gate);
            continue;
        }
        if let Some(value) = cached_value(&key) {
            drop(guard);
            release_gate(&key, &gate);
            return ProbeResult::Usage(Box::new(value));
        }

        let result = run_probe(state, principal, provider, prepared, refresh_url_override).await;
        cache_result(state, subject, principal, provider, &key, &result).await;
        drop(guard);
        release_gate(&key, &gate);
        return result;
    }
}

fn cache_key(
    state: &AppState,
    subject: &str,
    provider: UsageProvider,
    prepared: &PreparedProbe,
) -> CacheKey {
    CacheKey {
        subject: subject.to_string(),
        provider,
        generation: probe_generation(state, prepared),
    }
}

fn cached_value(key: &CacheKey) -> Option<SubscriptionUsage> {
    CACHE
        .get_or_init(Default::default)
        .lock()
        .ok()
        .and_then(|mut cache| {
            cache.retain(|_, entry| entry.expires > Instant::now());
            cache.get(key).map(|entry| entry.value.clone())
        })
}

fn release_gate(key: &CacheKey, gate: &Arc<tokio::sync::Mutex<()>>) {
    let mut in_flight = IN_FLIGHT
        .get_or_init(Default::default)
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    if in_flight
        .get(key)
        .is_some_and(|current| Arc::ptr_eq(current, gate))
    {
        in_flight.remove(key);
    }
}

async fn run_probe(
    state: &AppState,
    principal: &str,
    provider: UsageProvider,
    prepared: PreparedProbe,
    refresh_url_override: Option<&str>,
) -> ProbeResult {
    match prepared {
        PreparedProbe::OAuth {
            subscription,
            token,
        } => {
            probe_oauth_loaded_at(
                state,
                principal,
                provider,
                subscription,
                token,
                refresh_url_override,
            )
            .await
        }
        PreparedProbe::ZAi(provider) => probe_zai_provider(state, &provider).await,
        PreparedProbe::Lefine(_) => ProbeResult::Usage(Box::new(unavailable_lefine_usage())),
    }
}

async fn cache_result(
    state: &AppState,
    subject: &str,
    principal: &str,
    provider: UsageProvider,
    key: &CacheKey,
    result: &ProbeResult,
) {
    if let ProbeResult::Usage(value) = &result {
        // A rejected access token may have been refreshed and durably replaced
        // during the probe. Bind the cached result to the successor now stored
        // authoritatively, not to the predecessor prepared above.
        let insert_key = prepare_probe(state, principal, provider)
            .await
            .ok()
            .map_or_else(
                || key.clone(),
                |current| CacheKey {
                    subject: subject.to_string(),
                    provider,
                    generation: probe_generation(state, &current),
                },
            );
        let ttl = value.retry_after_seconds.map_or_else(
            || match provider {
                UsageProvider::Anthropic => ANTHROPIC_CACHE_TTL,
                UsageProvider::OpenAi
                | UsageProvider::ZAi
                | UsageProvider::Lefine
                | UsageProvider::Gemini
                | UsageProvider::Qwen => STANDARD_CACHE_TTL,
            },
            Duration::from_secs,
        );
        if let Ok(mut cache) = CACHE.get_or_init(Default::default).lock() {
            let now = Instant::now();
            let ttl = crate::request_routing::bounded_retry_after(ttl.max(Duration::from_secs(30)));
            cache.insert(
                insert_key,
                CacheEntry {
                    value: value.as_ref().clone(),
                    expires: now.checked_add(ttl).unwrap_or(now),
                },
            );
        }
    }
}

async fn prepare_probe(
    state: &AppState,
    principal: &str,
    provider: UsageProvider,
) -> Result<PreparedProbe, ProbeResult> {
    if let Some(subscription) = provider.subscription() {
        if state
            .subscription_cache
            .store_for_subscription(subscription, principal)
            .is_none()
        {
            return Err(ProbeResult::NotConfigured);
        }
        return match state
            .subscription_cache
            .load_authoritative(subscription, principal)
            .await
        {
            Ok(Some(token)) => Ok(PreparedProbe::OAuth {
                subscription,
                token,
            }),
            Ok(None) => Err(ProbeResult::NotConfigured),
            Err(_) => Err(ProbeResult::Usage(Box::new(credential_unavailable(
                provider,
            )))),
        };
    }
    match provider {
        UsageProvider::ZAi => crate::zai_coding_plan::resolve(state)
            .ok()
            .flatten()
            .filter(|provider| {
                provider
                    .api_key
                    .as_deref()
                    .is_some_and(|key| !key.is_empty())
            })
            .map(PreparedProbe::ZAi)
            .ok_or(ProbeResult::NotConfigured),
        UsageProvider::Lefine => selected_lefine(state)
            .map(PreparedProbe::Lefine)
            .ok_or(ProbeResult::NotConfigured),
        UsageProvider::Anthropic
        | UsageProvider::OpenAi
        | UsageProvider::Gemini
        | UsageProvider::Qwen => unreachable!(),
    }
}

fn probe_generation(state: &AppState, prepared: &PreparedProbe) -> String {
    fn field(hasher: &mut Sha256, value: &str) {
        hasher.update(value.len().to_le_bytes());
        hasher.update(value.as_bytes());
    }

    let mut hasher = Sha256::new();
    match prepared {
        PreparedProbe::OAuth {
            subscription,
            token,
        } => {
            hasher.update(crate::refresh::credential_fingerprint(token));
            field(&mut hasher, subscription.as_str());
            field(
                &mut hasher,
                state.subscription_base_url.as_deref().unwrap_or_default(),
            );
        }
        PreparedProbe::ZAi(provider) | PreparedProbe::Lefine(provider) => {
            field(&mut hasher, &provider.name);
            field(&mut hasher, provider.kind.as_str());
            field(&mut hasher, &provider.base_url);
            field(&mut hasher, provider.api_key.as_deref().unwrap_or_default());
            field(
                &mut hasher,
                provider.default_model.as_deref().unwrap_or_default(),
            );
            for model in &provider.models {
                field(&mut hasher, model);
            }
            for client in &provider.supported_clients {
                field(&mut hasher, client);
            }
        }
    }
    hex::encode(hasher.finalize())
}

//! Formatter and HTTP client shared by local and selected-remote usage commands.

use std::fmt::Write as _;
use std::process::ExitCode;

use crate::subscription_usage::{SubscriptionUsage, UsageEnvelope, UsageProvider};

pub async fn run(
    base_url: &crate::translation_core::Str,
    token: crate::translation_core::Maybe<&crate::translation_core::Str>,
    provider: crate::translation_core::Maybe<UsageProvider>,
    json: bool,
) -> ExitCode {
    let client = reqwest::Client::new();
    run_with_limit(
        &client,
        base_url,
        token,
        provider,
        json,
        crate::subscription_usage::MAX_USAGE_BODY,
    )
    .await
}

/// Run usage against a selected Router with its origin-specific trust.
pub async fn run_selected(
    server: &crate::managed_server::ResolvedServer,
    provider: crate::translation_core::Maybe<UsageProvider>,
    json: bool,
) -> ExitCode {
    let client = match server.inference_client() {
        Ok(client) => client,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    };
    run_with_limit(
        &client,
        &server.base_url,
        server.token.as_deref(),
        provider,
        json,
        crate::subscription_usage::MAX_USAGE_BODY,
    )
    .await
}

async fn run_with_limit(
    client: &reqwest::Client,
    base_url: &crate::translation_core::Str,
    token: crate::translation_core::Maybe<&crate::translation_core::Str>,
    provider: crate::translation_core::Maybe<UsageProvider>,
    json: bool,
    response_limit: usize,
) -> ExitCode {
    let Some(token) = token.filter(|token| !token.is_empty()) else {
        eprintln!(
            "error: subscription usage requires a Router credential; set LINK_ASSISTANT_TOKEN or select a server with a saved client or administrative token"
        );
        return ExitCode::from(2);
    };
    let path = provider.map_or_else(
        || "/api/usage".to_string(),
        |provider| format!("/api/usage/{}", provider.as_str()),
    );
    let url = format!("{}{path}", base_url.trim_end_matches('/'));
    let response = match client
        .get(&url)
        // The endpoint is Router-native rather than a vendor protocol. Send
        // the same token in all supported Router carriers so the signed client
        // kind selects its native evidence rule without decoding credentials
        // client-side.
        .bearer_auth(token)
        .header("x-api-key", token)
        .header("x-goog-api-key", token)
        .send()
        .await
    {
        Ok(response) => response,
        Err(error) => {
            eprintln!("error: router is not reachable at {url}: {error}");
            return ExitCode::from(1);
        }
    };
    let status = response.status();
    let bytes =
        match crate::subscription_usage::bounded_response_bytes(response, response_limit).await {
            Ok(bytes) => bytes,
            Err(crate::subscription_usage::BoundedBodyError::TooLarge) => {
                eprintln!("error: Router usage response exceeded the 2 MiB limit");
                return ExitCode::from(1);
            }
            Err(crate::subscription_usage::BoundedBodyError::Read) => {
                eprintln!("error: could not read Router usage response");
                return ExitCode::from(1);
            }
        };
    if !status.is_success() {
        let message = serde_json::from_slice::<serde_json::Value>(&bytes)
            .ok()
            .and_then(|body| {
                body.pointer("/error/message")
                    .or_else(|| body.pointer("/error/error/message"))
                    .and_then(serde_json::Value::as_str)
                    .map(str::to_string)
            })
            .unwrap_or_else(|| "request was refused".into());
        eprintln!("error: Router usage request failed ({status}): {message}");
        return ExitCode::from(1);
    }
    let envelope: UsageEnvelope = match serde_json::from_slice(&bytes) {
        Ok(envelope) => envelope,
        Err(error) => {
            eprintln!("error: Router returned invalid subscription usage JSON: {error}");
            return ExitCode::from(1);
        }
    };
    let output = match format_envelope(&envelope, json) {
        Ok(output) => output,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    };
    print!("{output}");
    ExitCode::SUCCESS
}

fn format_envelope(envelope: &UsageEnvelope, json: bool) -> crate::translation_core::Outcome<String, String> {
    if json {
        return serde_json::to_string_pretty(envelope)
            .map(|mut output| {
                output.push('\n');
                output
            })
            .map_err(|error| format!("could not encode subscription usage: {error}"));
    }
    if envelope.subscriptions.is_empty() {
        return Ok("No authorized configured subscriptions.\n".into());
    }
    let mut output = String::new();
    for (index, subscription) in envelope.subscriptions.iter().enumerate() {
        if index > 0 {
            output.push('\n');
        }
        format_subscription(&mut output, subscription);
    }
    Ok(output)
}

fn format_subscription(output: &mut String, usage: &SubscriptionUsage) {
    let _ = writeln!(output, "{}", usage.provider.as_str());
    let _ = writeln!(output, "  status: {}", usage.status);
    if let Some(pool) = &usage.pool {
        let _ = writeln!(
            output,
            "  accounts: {} configured, {} contributing, {} unavailable",
            pool.configured_accounts, pool.contributing_accounts, pool.unavailable_accounts
        );
        if let (Some(cooling), Some(paused), Some(models)) = (
            pool.cooling_down_accounts,
            pool.paused_accounts,
            pool.model_cooldowns,
        ) {
            let _ = writeln!(
                output,
                "  rate limits: {cooling} cooling down, {paused} paused, {models} model cooldowns"
            );
        }
    }
    if let Some(allowed) = usage.allowed {
        let _ = writeln!(output, "  allowed: {allowed}");
    }
    if let Some(reached) = usage.limit_reached {
        let _ = writeln!(output, "  limit reached: {reached}");
    }
    if let Some(plan) = &usage.plan {
        let _ = writeln!(output, "  plan: {plan}");
    }
    for window in &usage.windows {
        let used = window
            .used_percentage
            .map_or_else(|| "unavailable".into(), |value| format!("{value:.1}% used"));
        let remaining = window
            .remaining_percentage
            .map(|value| format!(", {value:.1}% remaining"))
            .unwrap_or_default();
        let reset = window
            .resets_at
            .as_deref()
            .map(|value| format!(", resets {value}"))
            .unwrap_or_default();
        let varied_resets = if window.reset_times.is_empty() {
            String::new()
        } else {
            format!(", resets vary: {}", window.reset_times.join(", "))
        };
        let contributors = window
            .contributors
            .map(|count| format!(", {count} contributor(s)"))
            .unwrap_or_default();
        let duration = window
            .window_seconds
            .map(|seconds| format!(", window {}", readable_duration(seconds)))
            .unwrap_or_default();
        let _ = writeln!(
            output,
            "  {}: {used}{remaining}{duration}{reset}{varied_resets}{contributors}",
            window.name
        );
    }
    for limit in &usage.additional_limits {
        let _ = writeln!(output, "  limit {}:", limit.name);
        if let Some(display) = limit
            .limit_name
            .as_deref()
            .filter(|display| *display != limit.name)
        {
            let _ = writeln!(output, "    display name: {display}");
        }
        if let Some(feature) = &limit.metered_feature {
            let _ = writeln!(output, "    metered feature: {feature}");
        }
        if let Some(kind) = &limit.kind {
            let _ = writeln!(output, "    kind: {kind}");
        }
        if let Some(group) = &limit.group {
            let _ = writeln!(output, "    group: {group}");
        }
        if let Some(model) = &limit.model_display_name {
            let _ = writeln!(output, "    model: {model}");
        }
        if let Some(allowed) = limit.allowed {
            let _ = writeln!(output, "    allowed: {allowed}");
        }
        if let Some(reached) = limit.limit_reached {
            let _ = writeln!(output, "    reached: {reached}");
        }
        for window in &limit.windows {
            let used = window
                .used_percentage
                .map_or_else(|| "unavailable".into(), |value| format!("{value:.1}% used"));
            let remaining = window
                .remaining_percentage
                .map(|value| format!(", {value:.1}% remaining"))
                .unwrap_or_default();
            let reset = window
                .resets_at
                .as_deref()
                .map(|value| format!(", resets {value}"))
                .unwrap_or_default();
            let duration = window
                .window_seconds
                .map(|seconds| format!(", window {}", readable_duration(seconds)))
                .unwrap_or_default();
            let _ = writeln!(
                output,
                "    {}: {used}{remaining}{duration}{reset}",
                window.name
            );
        }
        if limit.used.is_some() || limit.limit.is_some() {
            let _ = writeln!(
                output,
                "    amount: {} / {}",
                limit
                    .used
                    .map_or_else(|| "?".into(), |value| value.to_string()),
                limit
                    .limit
                    .map_or_else(|| "?".into(), |value| value.to_string())
            );
        }
    }
    if let Some(credits) = &usage.credits {
        if credits.unlimited == Some(true) {
            let _ = writeln!(output, "  credits: unlimited");
        } else if let Some(balance) = &credits.balance {
            let _ = writeln!(output, "  credits: {balance}");
        } else if credits.overage_limit_reached == Some(true) {
            let _ = writeln!(output, "  credits: overage limit reached");
        }
        if let Some(has_credits) = credits.has_credits {
            let _ = writeln!(output, "  credits available: {has_credits}");
        }
        if let Some(messages) = credits.approximate_local_messages {
            let _ = writeln!(output, "  approximate local messages: {messages}");
        }
        if let Some(messages) = credits.approximate_cloud_messages {
            let _ = writeln!(output, "  approximate cloud messages: {messages}");
        }
    }
    if let Some(extra) = &usage.extra_usage {
        let _ = writeln!(output, "  extra usage:");
        if let Some(enabled) = extra.is_enabled {
            let _ = writeln!(output, "    enabled: {enabled}");
        }
        if extra.used_credits.is_some() || extra.monthly_limit.is_some() {
            let used = extra
                .used_credits
                .map_or_else(|| "?".into(), |value| value.to_string());
            let limit = extra
                .monthly_limit
                .map_or_else(|| "?".into(), |value| value.to_string());
            let currency = extra
                .currency
                .as_deref()
                .map(|currency| format!(" {currency}"))
                .unwrap_or_default();
            let _ = writeln!(output, "    amount: {used} / {limit}{currency}");
        }
        if let Some(remaining) = extra.remaining_credits {
            let _ = writeln!(output, "    remaining: {remaining}");
        }
        if let Some(utilization) = extra.utilization {
            let _ = writeln!(output, "    utilization: {utilization:.1}%");
        }
        if let Some(reset) = &extra.resets_at {
            let _ = writeln!(output, "    resets: {reset}");
        }
    }
    if let Some(control) = &usage.spend_control {
        let _ = writeln!(output, "  spend control:");
        if let Some(reached) = control.reached {
            let _ = writeln!(output, "    reached: {reached}");
        }
        if let Some(limit) = &control.individual_limit {
            if let Some(source) = &limit.source {
                let _ = writeln!(output, "    source: {source}");
            }
            if limit.used.is_some() || limit.limit.is_some() || limit.remaining.is_some() {
                let _ = writeln!(
                    output,
                    "    amount: {} / {}, {} remaining",
                    limit.used.as_deref().unwrap_or("?"),
                    limit.limit.as_deref().unwrap_or("?"),
                    limit.remaining.as_deref().unwrap_or("?")
                );
            }
            if let Some(used) = limit.used_percentage {
                let remaining = limit
                    .remaining_percentage
                    .map(|value| format!(", {value:.1}% remaining"))
                    .unwrap_or_default();
                let _ = writeln!(output, "    utilization: {used:.1}% used{remaining}");
            }
            if let Some(reset) = &limit.resets_at {
                let _ = writeln!(output, "    resets: {reset}");
            }
            if let Some(reset_after) = limit.reset_after_seconds {
                let _ = writeln!(
                    output,
                    "    resets after: {}",
                    readable_duration(reset_after)
                );
            }
        }
    }
    if let Some(reached_type) = &usage.rate_limit_reached_type {
        let _ = writeln!(output, "  limit reason: {reached_type}");
    }
    if let Some(available) = usage.rate_limit_reset_credits_available {
        let _ = writeln!(output, "  reset credits available: {available}");
    }
    if let Some(end) = &usage.subscription_end {
        let _ = writeln!(output, "  subscription ends: {end}");
    }
    if let Some(end) = &usage.trial_end {
        let _ = writeln!(output, "  trial ends: {end}");
    }
    if let Some(retry) = usage.retry_after_seconds {
        let _ = writeln!(output, "  retry after: {retry}s");
    }
}

fn readable_duration(seconds: u64) -> String {
    if seconds > 0 && seconds.is_multiple_of(86_400) {
        format!("{}d", seconds / 86_400)
    } else if seconds > 0 && seconds.is_multiple_of(3_600) {
        format!("{}h", seconds / 3_600)
    } else if seconds > 0 && seconds.is_multiple_of(60) {
        format!("{}m", seconds / 60)
    } else {
        format!("{seconds}s")
    }
}

