//! Telegram admin channel — a long-polling loop over the Bot API.
//!
//! Long polling, not webhooks, on purpose: the whole reason to administer a
//! self-hosted router from a phone is to avoid publishing an inbound port. The
//! bot dials out to `api.telegram.org`, so the deployment needs no public
//! surface at all.
//!
//! Two rules are enforced here, before anything is parsed as a command:
//!
//! 1. **private chats only.** `chat.type` must be `private`. Group, supergroup
//!    and channel updates are dropped untouched — administering token issuance
//!    in a group would hand credentials to every member, and group context
//!    (replies, forwards, bot-to-bot traffic) is a parsing hazard on top;
//! 2. **secrets do not linger.** A reply that carries a credential is deleted
//!    after [`ChatAdminConfig::secret_ttl`](crate::chat_admin::ChatAdminConfig),
//!    and the message says so.
//!
//! The transport is deliberately dependency-free — plain `reqwest` against the
//! documented HTTP API rather than a bot framework.

use std::sync::Arc;
use std::time::Duration;

use reqwest::Client;
use serde_json::{Value, json};

use crate::chat_admin::{ChatAdmin, ChatChannel, Reply};

/// Seconds `getUpdates` is allowed to hold the connection open.
const POLL_TIMEOUT_SECS: u64 = 30;

/// Backoff after a failed poll, so a network outage does not become a hot loop.
const ERROR_BACKOFF: Duration = Duration::from_secs(5);

/// Only these update kinds are requested; anything else never reaches us.
const ALLOWED_UPDATES: &crate::translation_core::Str = r#"["message"]"#;

/// Run the Telegram polling loop until the process ends.
///
/// Returns immediately (doing nothing) when no token is configured, so the
/// caller can spawn it unconditionally.
pub async fn run(chat: Arc<ChatAdmin>, client: Client) {
    let Some(token) = chat.config().telegram_bot_token.clone() else {
        return;
    };
    let bot = TelegramBot {
        client,
        base_url: format!("https://api.telegram.org/bot{}", token.trim()),
    };
    match bot.me().await {
        Ok(name) => tracing::info!("Telegram admin bot connected as @{name} (private chats only)"),
        Err(e) => tracing::warn!("Telegram admin bot could not verify its token: {e}"),
    }
    let mut offset: i64 = 0;
    loop {
        match bot.updates(offset).await {
            Ok(updates) => {
                for update in updates {
                    offset = offset.max(update_id(&update) + 1);
                    handle_update(&chat, &bot, &update).await;
                }
            }
            Err(e) => {
                tracing::warn!("Telegram poll failed: {e}");
                tokio::time::sleep(ERROR_BACKOFF).await;
            }
        }
    }
}

/// Process one update, dropping everything that is not a private message.
async fn handle_update(chat: &Arc<ChatAdmin>, bot: &TelegramBot, update: &crate::translation_core::Json) {
    let Some(message) = update.get("message") else {
        return;
    };
    let Some(chat_id) = message.pointer("/chat/id").and_then(Value::as_i64) else {
        return;
    };
    if !is_private(message) {
        tracing::debug!("Telegram: ignoring a non-private message in chat {chat_id}");
        return;
    }
    // A bot must never take instructions from another bot; nor from a message
    // with no sender (channel posts arrive that way).
    let Some(from) = message.get("from") else {
        return;
    };
    if from.get("is_bot").and_then(Value::as_bool).unwrap_or(false) {
        return;
    }
    let Some(user_id) = from.get("id").and_then(Value::as_i64) else {
        return;
    };
    let Some(text) = message.get("text").and_then(Value::as_str) else {
        return;
    };

    let reply = chat.handle(ChatChannel::Telegram, &user_id.to_string(), text);
    deliver(chat, bot, chat_id, reply).await;
}

/// Send a reply, scheduling deletion when it carries a secret.
async fn deliver(chat: &Arc<ChatAdmin>, bot: &TelegramBot, chat_id: i64, reply: Reply) {
    let secret = reply.secret;
    let ttl = chat.config().secret_ttl;
    match bot.send(chat_id, &reply.text).await {
        Ok(message_id) => {
            if secret && !ttl.is_zero() {
                let bot = bot.clone();
                tokio::spawn(async move {
                    tokio::time::sleep(ttl).await;
                    if let Err(e) = bot.delete(chat_id, message_id).await {
                        tracing::debug!("Telegram: could not delete a secret message: {e}");
                    }
                });
            }
        }
        Err(e) => tracing::warn!("Telegram: could not send a reply: {e}"),
    }
}

/// Whether a message came from a 1:1 conversation.
///
/// Anything other than an explicit `private` chat type is treated as a group —
/// including an absent or unrecognised type, because "unknown" must not fall
/// through to "administer this router".
#[must_use]
pub fn is_private(message: &crate::translation_core::Json) -> bool {
    message.pointer("/chat/type").and_then(crate::translation_core::Json::as_str) == crate::translation_core::Maybe::Some("private")
}

fn update_id(update: &crate::translation_core::Json) -> i64 {
    update.get("update_id").and_then(crate::translation_core::Json::as_i64).unwrap_or(0)
}

/// Minimal Bot API client: the four calls this channel needs.
#[derive(Clone)]
struct TelegramBot {
    client: Client,
    base_url: String,
}

impl TelegramBot {
    /// `getMe` — used once at startup to log the bot identity.
    async fn me(&self) -> crate::translation_core::Outcome<String, String> {
        let body = self.call("getMe", &json!({})).await?;
        Ok(body
            .pointer("/result/username")
            .and_then(Value::as_str)
            .unwrap_or("unknown")
            .to_string())
    }

    /// `getUpdates` with a long timeout, returning the raw update objects.
    async fn updates(&self, offset: i64) -> crate::translation_core::Outcome<Vec<crate::translation_core::Json>, String> {
        let body = self
            .call(
                "getUpdates",
                &json!({
                    "offset": offset,
                    "timeout": POLL_TIMEOUT_SECS,
                    "allowed_updates": serde_json::from_str::<Value>(ALLOWED_UPDATES)
                        .unwrap_or(Value::Null),
                }),
            )
            .await?;
        Ok(body
            .get("result")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default())
    }

    /// `sendMessage`, returning the new message id so secrets can be deleted.
    async fn send(&self, chat_id: i64, text: &crate::translation_core::Str) -> crate::translation_core::Outcome<i64, String> {
        let body = self
            .call(
                "sendMessage",
                &json!({"chat_id": chat_id, "text": text, "disable_web_page_preview": true}),
            )
            .await?;
        Ok(body
            .pointer("/result/message_id")
            .and_then(Value::as_i64)
            .unwrap_or_default())
    }

    /// `deleteMessage` — best effort; Telegram only lets a bot delete its own
    /// recent messages, and the user may have deleted it already.
    async fn delete(&self, chat_id: i64, message_id: i64) -> crate::translation_core::Outcome<(), String> {
        self.call(
            "deleteMessage",
            &json!({"chat_id": chat_id, "message_id": message_id}),
        )
        .await
        .map(|_| ())
    }

    async fn call(&self, method: &crate::translation_core::Str, body: &crate::translation_core::Json) -> crate::translation_core::Outcome<crate::translation_core::Json, String> {
        let response = self
            .client
            .post(format!("{}/{method}", self.base_url))
            .json(body)
            // A little beyond the long-poll timeout, so the poll itself is not
            // cut short by the client timeout.
            .timeout(Duration::from_secs(POLL_TIMEOUT_SECS + 15))
            .send()
            .await
            .map_err(|e| e.to_string())?;
        let value: Value = response.json().await.map_err(|e| e.to_string())?;
        if value.get("ok").and_then(Value::as_bool) == Some(true) {
            Ok(value)
        } else {
            Err(value
                .get("description")
                .and_then(Value::as_str)
                .unwrap_or("Telegram API call failed")
                .to_string())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_private_chats_are_accepted() {
        for kind in ["group", "supergroup", "channel"] {
            let message = json!({"chat": {"id": 1, "type": kind}, "text": "/start"});
            assert!(!is_private(&message), "{kind} must be ignored");
        }
        assert!(is_private(
            &json!({"chat": {"id": 1, "type": "private"}, "text": "/start"})
        ));
    }

    #[test]
    fn a_message_without_a_chat_type_is_not_private() {
        assert!(!is_private(&json!({"chat": {"id": 1}, "text": "/start"})));
        assert!(!is_private(&json!({"text": "/start"})));
    }

    #[test]
    fn the_update_offset_advances_past_the_last_update() {
        assert_eq!(update_id(&json!({"update_id": 41})) + 1, 42);
        assert_eq!(update_id(&json!({})), 0);
    }

    #[test]
    fn update_ids_preserve_signed_domain_and_refuse_other_json_numbers() {
        for expected in [i64::MIN, -1, 0, 1, i64::MAX] {
            assert_eq!(update_id(&json!({"update_id": expected})), expected);
        }
        for update in [
            json!(null),
            json!([]),
            json!({}),
            json!({"update_id": null}),
            json!({"update_id": true}),
            json!({"update_id": "1"}),
            json!({"update_id": []}),
            json!({"update_id": 1.0}),
            json!({"update_id": u64::MAX}),
        ] {
            assert_eq!(update_id(&update), 0, "{update}");
        }
    }
}

//! Canonical thinking controls shared by request translators and provider appliers.
//!
//! The suffix grammar and conversion tables follow `CLIProxyAPI` v8.0.20
//! (MIT, Copyright (c) 2025 router-for-me), commit
//! 0f96f568e4dbf6f84ad7399a74b78344c5eac7e6. Model capability claims come
//! only from exact, scoped model-truth evidence, never from model families.

pub(crate) mod anthropic;
mod apply;
mod catalog;
pub(crate) use catalog::apply_for_account;
mod extract;
mod parser;
pub(crate) mod policy;
mod support;
mod visibility;

pub use extract::extract_config;
pub use parser::{
    SuffixResult, parse_level_suffix, parse_numeric_suffix, parse_special_suffix, parse_suffix,
};
use serde_json::Value;
pub use support::ThinkingSupport;

/// A discrete reasoning effort, ordered from least to most expensive.
#[derive(
    Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd, serde::Deserialize, serde::Serialize,
)]
#[serde(rename_all = "lowercase")]
pub enum ThinkingLevel {
    Minimal,
    Low,
    Medium,
    High,
    XHigh,
    Max,
}

impl ThinkingLevel {
    /// Provider wire spelling for this effort.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Minimal => "minimal",
            Self::Low => "low",
            Self::Medium => "medium",
            Self::High => "high",
            Self::XHigh => "xhigh",
            Self::Max => "max",
        }
    }

    /// Shared semantic conversion, bounded by target evidence when available.
    #[must_use]
    pub const fn budget(self) -> u32 {
        match self {
            Self::Minimal => 512,
            Self::Low => 1024,
            Self::Medium => 8192,
            Self::High => 24576,
            Self::XHigh => 32768,
            Self::Max => 128_000,
        }
    }

    /// Convert a positive budget to the shared effort thresholds.
    #[must_use]
    pub const fn from_budget(budget: u32) -> Self {
        match budget {
            0..=512 => Self::Minimal,
            513..=1024 => Self::Low,
            1025..=8192 => Self::Medium,
            8193..=24576 => Self::High,
            _ => Self::XHigh,
        }
    }
}

/// The requested thinking mode, independent of provider wire format.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ThinkingMode {
    Off,
    Auto,
    Budget(u32),
    Level(ThinkingLevel),
}

/// A provider-independent thinking request. Summary visibility is separate.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ThinkingConfig {
    pub mode: ThinkingMode,
}

/// Wire format for extracting and applying reasoning controls.
/// Additional formats support the upstream conformance corpus; they do not
/// register providers or inference routes.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ThinkingProtocol {
    Anthropic,
    OpenAIChat,
    OpenAIResponses,
    Gemini,
    Vertex,
    Codex,
    Qwen,
    Interactions,
    Antigravity,
    Kimi,
    Xai,
}

// An internal bridge retains the caller's source format and suffix intent;
// its intermediate wire format must not turn a translation into body input.
tokio::task_local! {
    pub(crate) static ORIGIN: (ThinkingProtocol, bool);
}

impl ThinkingProtocol {
    /// Parse a provider or protocol name used by the canonical pipeline.
    #[must_use]
    pub fn from_name(name: &str) -> Option<Self> {
        match name {
            "claude" | "anthropic" => Some(Self::Anthropic),
            "openai" | "openai-chat" => Some(Self::OpenAIChat),
            "openai-response" | "openai-responses" => Some(Self::OpenAIResponses),
            "gemini" => Some(Self::Gemini),
            "vertex" => Some(Self::Vertex),
            "codex" => Some(Self::Codex),
            "qwen" => Some(Self::Qwen),
            "interactions" => Some(Self::Interactions),
            "antigravity" => Some(Self::Antigravity),
            "kimi" => Some(Self::Kimi),
            "xai" => Some(Self::Xai),
            _ => None,
        }
    }

    pub(super) const fn family(self) -> u8 {
        match self {
            Self::Anthropic => 0,
            Self::OpenAIChat | Self::OpenAIResponses | Self::Codex => 1,
            Self::Gemini | Self::Vertex | Self::Antigravity => 2,
            Self::Qwen => 3,
            Self::Interactions => 4,
            Self::Kimi => 5,
            Self::Xai => 6,
        }
    }
}

/// Extract source intent, validate exact model evidence and apply target controls.
///
/// `body` is the translated target; `source` is the original request. Existing
/// body controls take precedence over a suffix so adding suffix support does
/// not change an explicit client setting. No control means no injected default.
/// Unknown capabilities preserve caller intent using protocol conversions;
/// only verified unsupported capability causes a logged drop.
///
/// # Errors
/// Invalid controls or unsupported same-protocol levels/budgets return an error
/// without modifying `body`.
pub fn apply_thinking(
    body: &mut Value,
    source: &Value,
    model: &str,
    from: ThinkingProtocol,
    to: ThinkingProtocol,
    truth: Option<&crate::model_contract::ModelTruthDescriptor>,
) -> Result<Option<ThinkingConfig>, String> {
    if !body.is_object() {
        return Err("thinking target must be a JSON object".into());
    }
    let suffix = parse_suffix(model);
    let base = base_model(model);
    let body_config = if to == ThinkingProtocol::Kimi
        && from == ThinkingProtocol::OpenAIChat
        && source.get("thinking").is_some()
    {
        extract_config(source, ThinkingProtocol::Kimi)?
    } else {
        extract_config(source, from)?
    };
    let config = body_config.or_else(|| (base != model).then(|| suffix.config()).flatten());
    let mut visibility = visibility::extract(source, from);
    let Some(mut config) = config else {
        visibility::apply(body, to, visibility);
        return Ok(None);
    };
    let support = truth.and_then(|truth| support::from_truth(truth, base, to));
    if support
        .as_ref()
        .is_some_and(|support| support.supported == Some(false))
    {
        tracing::debug!(
            model = base,
            ?to,
            "thinking dropped: exact model evidence declares unsupported"
        );
        apply::clear(body, to);
        if body.get("model").is_some() {
            body["model"] = Value::String(base.to_string());
        }
        return Ok(None);
    }
    if to == ThinkingProtocol::Kimi
        && from == ThinkingProtocol::OpenAIChat
        && source.pointer("/thinking/type").and_then(Value::as_str) == Some("enabled")
        && source.pointer("/thinking/effort").is_none()
        && source.get("reasoning_effort").is_none()
    {
        if body.get("model").is_some() {
            body["model"] = Value::String(base.to_string());
        }
        return Ok(None);
    }
    if support.is_some() && visibility.is_none() && from == ThinkingProtocol::OpenAIResponses {
        visibility = source
            .pointer("/reasoning/effort")
            .and_then(Value::as_str)
            .map(|effort| effort != "none");
    }
    if from == ThinkingProtocol::Anthropic
        && matches!(
            to,
            ThinkingProtocol::Gemini | ThinkingProtocol::Vertex | ThinkingProtocol::Antigravity
        )
        && config.mode == ThinkingMode::Auto
        && source.pointer("/thinking/type").and_then(Value::as_str) == Some("adaptive")
    {
        config.mode = ThinkingMode::Level(ThinkingLevel::High);
    }
    if let Some(support) = support.as_ref() {
        config = support::validate(config, support, from, to, body_config.is_none())?;
    }
    let mut updated = body.clone();
    apply::apply(&mut updated, config, to, support.as_ref(), base);
    if updated.get("model").is_some() {
        updated["model"] = Value::String(base.to_string());
    }
    visibility::apply(&mut updated, to, visibility);
    *body = updated;
    Ok(Some(config))
}

/// Strip an interpreted thinking suffix from a selector for routing and policy.
/// Malformed, unrecognized and overflowing suffixes remain exact literal IDs.
#[must_use]
pub fn base_model(model: &str) -> &str {
    let suffix = parse_suffix(model);
    if suffix.config().is_some() && !suffix.model_name.is_empty() {
        suffix.model_name
    } else {
        model
    }
}

/// Whether a recognized suffix supplies the control rather than an explicit body field.
pub(crate) fn suffix_applies(source: &Value, model: &str, protocol: ThinkingProtocol) -> bool {
    base_model(model) != model
        && extract_config(source, protocol).is_ok_and(|config| config.is_none())
}

#[derive(Clone)]
pub(crate) struct SuffixIntent;

/// Apply an additive suffix at ingress, leaving requests without one untouched.
///
/// Explicit body controls retain precedence. The returned boolean indicates
/// whether bytes must be serialized again on a native relay.
pub fn normalize_request(body: &mut Value, protocol: ThinkingProtocol) -> Result<bool, String> {
    let Some(model) = body
        .get("model")
        .and_then(Value::as_str)
        .map(str::to_string)
    else {
        return Ok(false);
    };
    if base_model(&model) == model {
        return Ok(false);
    }
    let source = body.clone();
    let body_protocol = if protocol == ThinkingProtocol::OpenAIChat
        && (source.get("enable_thinking").is_some() || source.get("thinking_budget").is_some())
    {
        ThinkingProtocol::Qwen
    } else {
        protocol
    };
    if extract_config(&source, body_protocol)?.is_none() {
        apply_thinking(body, &source, &model, protocol, protocol, None)?;
    }
    body["model"] = Value::String(base_model(&model).to_string());
    Ok(true)
}

/// Normalize a URL-owned native model selector without adding a body model.
/// Requests with no suffix preserve their body exactly.
pub fn normalize_native_request(
    model: &str,
    body: &mut Value,
    protocol: ThinkingProtocol,
) -> Result<String, String> {
    let base = base_model(model);
    if base == model {
        return Ok(model.to_string());
    }
    let source = body.clone();
    if extract_config(&source, protocol)?.is_none() {
        apply_thinking(body, &source, model, protocol, protocol, None)?;
    }
    Ok(base.to_string())
}

/// Surface-specific rendering for suffix validation at HTTP ingress.
pub(crate) fn normalize_ingress(
    body: &mut Value,
    surface: crate::metrics::Surface,
) -> Result<(), axum::response::Response> {
    let protocol = match surface {
        crate::metrics::Surface::Anthropic => ThinkingProtocol::Anthropic,
        crate::metrics::Surface::OpenAIChat => ThinkingProtocol::OpenAIChat,
        crate::metrics::Surface::OpenAIResponses => ThinkingProtocol::OpenAIResponses,
    };
    normalize_request(body, protocol)
        .map(|_| ())
        .map_err(|reason| {
            crate::api_error::error_response_for_surface(
                surface,
                axum::http::StatusCode::BAD_REQUEST,
                "invalid_request_error",
                &reason,
            )
        })
}

//! Anthropic wire constraints and historical output-limit reconciliation.
use serde_json::{Value, json};

const CLAUDE_DEFAULT_MAX_TOKENS: u64 = 8_192;
const CLAUDE_MIN_THINKING_BUDGET: u64 = 1_024;
const CLAUDE_OUTPUT_HEADROOM: u64 = 8_192;
const CLAUDE_OUTPUT_FLOOR: u64 = 4_096;
const CLAUDE_FIXED_TOKEN_CEILING: u64 = 32_000;
const CLAUDE_ADAPTIVE_TOKEN_CEILING: u64 = 40_192;

/// Convert native Anthropic modes, retaining the bridge's historical max spelling.
pub fn translated_effort(body: &Value) -> Result<Option<&'static str>, String> {
    Ok(
        super::extract_config(body, super::ThinkingProtocol::Anthropic)?.map(|config| {
            if config.mode == super::ThinkingMode::Level(super::ThinkingLevel::Max) {
                "xhigh"
            } else {
                super::apply::effort(config.mode)
            }
        }),
    )
}

fn reasoning_budget(effort: &str) -> u64 {
    match effort {
        "minimal" => 1_024,
        "low" => 4_096,
        "medium" => 8_192,
        "xhigh" => 24_576,
        "max" => 32_000,
        _ => 16_384,
    }
}

fn adaptive_effort(effort: &str) -> &'static str {
    match effort {
        "minimal" | "low" => "low",
        "medium" => "medium",
        "xhigh" | "max" => "max",
        _ => "high",
    }
}

pub fn reconcile_claude_thinking(
    body: &mut Value,
    adaptive_thinking: bool,
    output_limit_was_explicit: bool,
) {
    // A suffix is a default; historical body effort conversion and output
    // headroom continue to win when the client supplied an effort explicitly.
    let model = body
        .get("model")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    if super::base_model(&model) != model {
        if body.pointer("/reasoning/effort").is_none() && body.get("thinking").is_none() {
            let source = body.clone();
            if !output_limit_was_explicit
                && let Some(super::ThinkingConfig {
                    mode: super::ThinkingMode::Budget(budget),
                }) = super::parse_suffix(&model).config()
            {
                body["max_tokens"] =
                    json!(u64::from(budget).saturating_add(CLAUDE_OUTPUT_HEADROOM));
            }
            let _ = super::apply_thinking(
                body,
                &source,
                &model,
                super::ThinkingProtocol::OpenAIResponses,
                super::ThinkingProtocol::Anthropic,
                None,
            );
        }
        body["model"] = json!(super::base_model(&model));
    }
    let requested_effort = body
        .pointer("/reasoning/effort")
        .and_then(Value::as_str)
        .map(str::to_string);
    if let Some(object) = body.as_object_mut() {
        object.remove("reasoning");
    }
    let thinking_present = body.get("thinking").is_some();
    if !thinking_present
        && requested_effort
            .as_deref()
            .is_some_and(|effort| effort != "none")
    {
        let effort = requested_effort.as_deref().unwrap_or("high");
        let requested_budget = reasoning_budget(effort);
        if adaptive_thinking {
            body["thinking"] = json!({"type": "adaptive"});
            if !body.get("output_config").is_some_and(Value::is_object) {
                body["output_config"] = json!({});
            }
            body["output_config"]["effort"] = json!(adaptive_effort(effort));
            if !output_limit_was_explicit {
                body["max_tokens"] = json!(
                    CLAUDE_DEFAULT_MAX_TOKENS
                        .max(requested_budget.saturating_add(CLAUDE_OUTPUT_HEADROOM))
                        .min(CLAUDE_ADAPTIVE_TOKEN_CEILING)
                );
            }
        } else {
            let mut max_tokens = body
                .get("max_tokens")
                .and_then(Value::as_u64)
                .unwrap_or(CLAUDE_DEFAULT_MAX_TOKENS);
            if !output_limit_was_explicit {
                max_tokens = max_tokens
                    .max(requested_budget.saturating_add(CLAUDE_OUTPUT_HEADROOM))
                    .min(CLAUDE_FIXED_TOKEN_CEILING);
                body["max_tokens"] = json!(max_tokens);
            }
            let available = max_tokens
                .saturating_sub(CLAUDE_OUTPUT_FLOOR)
                .max(CLAUDE_MIN_THINKING_BUDGET);
            body["thinking"] = json!({
                "type": "enabled",
                "budget_tokens": requested_budget.min(available),
            });
        }
    }
    let max_tokens = body
        .get("max_tokens")
        .and_then(Value::as_u64)
        .unwrap_or(CLAUDE_DEFAULT_MAX_TOKENS);
    let thinking_enabled = body
        .get("thinking")
        .and_then(|thinking| thinking.get("type"))
        .and_then(Value::as_str)
        .is_some_and(|kind| matches!(kind, "enabled" | "adaptive"));
    if thinking_enabled {
        if let Some(budget) = body
            .pointer("/thinking/budget_tokens")
            .and_then(Value::as_u64)
            && budget.saturating_add(CLAUDE_OUTPUT_FLOOR) > max_tokens
            && max_tokens > CLAUDE_MIN_THINKING_BUDGET
        {
            body["thinking"]["budget_tokens"] = json!(
                max_tokens
                    .saturating_sub(CLAUDE_OUTPUT_FLOOR)
                    .max(CLAUDE_MIN_THINKING_BUDGET)
            );
        }
        if let Some(object) = body.as_object_mut() {
            object.remove("temperature");
            object.remove("top_p");
        }
    }
}

/// Reapply a numeric suffix after an intermediary effort-only protocol so
/// token budgets are not lost to an effort threshold during translation.
pub fn apply_translated_suffix(
    body: &mut Value,
    source: &Value,
    from: super::ThinkingProtocol,
    to: super::ThinkingProtocol,
) -> Result<(), String> {
    let model = source
        .get("model")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if super::base_model(model) == model || super::extract_config(source, from)?.is_some() {
        return Ok(());
    }
    let target_model = body.get("model").cloned();
    if to == super::ThinkingProtocol::Anthropic
        && !["max_tokens", "max_completion_tokens", "max_output_tokens"]
            .iter()
            .any(|key| source.get(*key).is_some_and(|value| !value.is_null()))
        && let Some(super::ThinkingConfig {
            mode: super::ThinkingMode::Budget(budget),
        }) = super::parse_suffix(model).config()
    {
        body["max_tokens"] = json!(u64::from(budget).saturating_add(CLAUDE_OUTPUT_HEADROOM));
    }
    super::apply_thinking(body, source, model, from, to, None)?;
    if let Some(model) = target_model {
        body["model"] = model;
    }
    Ok(())
}

use super::{ThinkingConfig, ThinkingLevel, ThinkingMode, ThinkingProtocol, ThinkingSupport};
use serde_json::{Value, json};

pub(super) fn clear(body: &mut Value, protocol: ThinkingProtocol) {
    use ThinkingProtocol as P;
    match protocol {
        P::Anthropic | P::Kimi => {
            remove(body, "thinking");
            if let Some(config) = body.get_mut("output_config") {
                remove(config, "effort");
            }
        }
        P::OpenAIChat | P::Qwen => {
            remove(body, "reasoning_effort");
            remove(body, "enable_thinking");
            remove(body, "thinking_budget");
            if let Some(reasoning) = body.get_mut("reasoning") {
                remove(reasoning, "effort");
            }
        }
        P::OpenAIResponses | P::Codex | P::Xai => {
            if let Some(reasoning) = body.get_mut("reasoning") {
                remove(reasoning, "effort");
            }
        }
        P::Gemini | P::Vertex => {
            if let Some(generation) = body.get_mut("generationConfig") {
                remove(generation, "thinkingConfig");
            }
            if let Some(generation) = body.get_mut("generation_config") {
                remove(generation, "thinking_config");
            }
        }
        P::Antigravity => {
            if let Some(request) = body.get_mut("request") {
                clear(request, P::Gemini);
            }
        }
        P::Interactions => {
            if let Some(config) = body.get_mut("generation_config") {
                remove(config, "thinking_level");
                remove(config, "thinking_budget");
            }
        }
    }
}

pub(super) fn apply(
    body: &mut Value,
    config: ThinkingConfig,
    to: ThinkingProtocol,
    support: Option<&ThinkingSupport>,
    model: &str,
) {
    use ThinkingProtocol as P;
    match to {
        P::Anthropic => anthropic(body, config.mode, support, model),
        P::OpenAIChat => {
            if let Some(reasoning) = body.get_mut("reasoning") {
                remove(reasoning, "effort");
            }
            body["reasoning_effort"] = json!(effort(config.mode));
        }
        P::OpenAIResponses | P::Codex | P::Xai => {
            object_at(body, "reasoning")["effort"] = json!(effort(config.mode));
        }
        P::Qwen => {
            body["enable_thinking"] = json!(config.mode != ThinkingMode::Off);
            match config.mode {
                ThinkingMode::Budget(budget) => body["thinking_budget"] = json!(budget),
                ThinkingMode::Level(level) => body["thinking_budget"] = json!(level.budget()),
                _ => remove(body, "thinking_budget"),
            }
            remove(body, "reasoning_effort");
            if let Some(reasoning) = body.get_mut("reasoning") {
                remove(reasoning, "effort");
            }
        }
        P::Gemini | P::Vertex => gemini(body, config.mode, support),
        P::Antigravity => gemini(object_at(body, "request"), config.mode, support),
        P::Interactions => {
            let generation = object_at(body, "generation_config");
            generation["thinking_level"] = json!(effort(config.mode));
            remove(generation, "thinking_budget");
        }
        P::Kimi => {
            let thinking = object_at(body, "thinking");
            thinking["type"] = json!(if config.mode == ThinkingMode::Off {
                "disabled"
            } else {
                "enabled"
            });
            if config.mode == ThinkingMode::Off {
                remove(thinking, "effort");
            } else {
                thinking["effort"] = json!(if config.mode == ThinkingMode::Auto {
                    "medium"
                } else {
                    effort(config.mode)
                });
            }
            remove(body, "reasoning_effort");
        }
    }
}

pub(super) const fn effort(mode: ThinkingMode) -> &'static str {
    match mode {
        ThinkingMode::Off => "none",
        ThinkingMode::Auto => "auto",
        ThinkingMode::Level(level) => level.as_str(),
        ThinkingMode::Budget(budget) => ThinkingLevel::from_budget(budget).as_str(),
    }
}

fn gemini(body: &mut Value, mode: ThinkingMode, support: Option<&ThinkingSupport>) {
    use ThinkingMode as M;
    if let Some(mut legacy) = body
        .get_mut("generation_config")
        .and_then(|generation| generation.as_object_mut())
        .and_then(|generation| generation.remove("thinking_config"))
    {
        if let Some(config) = legacy.as_object_mut() {
            for (old, new) in [
                ("thinking_level", "thinkingLevel"),
                ("thinking_budget", "thinkingBudget"),
                ("include_thoughts", "includeThoughts"),
            ] {
                if let Some(value) = config.remove(old) {
                    config.entry(new).or_insert(value);
                }
            }
        }
        if body.pointer("/generationConfig/thinkingConfig").is_none() {
            object_at(body, "generationConfig")["thinkingConfig"] = legacy;
        }
    }
    let generation = object_at(body, "generationConfig");
    if mode == M::Off && support.is_some_and(|support| !support.levels.is_empty()) {
        remove(generation, "thinkingConfig");
        return;
    }
    let thinking = object_at(generation, "thinkingConfig");
    let native_level = support.is_none()
        && (thinking.get("thinkingLevel").is_some() || thinking.get("thinking_level").is_some());
    for field in [
        "thinkingLevel",
        "thinking_level",
        "thinkingBudget",
        "thinking_budget",
    ] {
        remove(thinking, field);
    }
    match mode {
        M::Level(level)
            if native_level || support.is_some_and(|support| !support.levels.is_empty()) =>
        {
            thinking["thinkingLevel"] = json!(level.as_str());
        }
        M::Level(level) => thinking["thinkingBudget"] = json!(level.budget()),
        M::Budget(budget) => thinking["thinkingBudget"] = json!(budget),
        M::Off => thinking["thinkingBudget"] = json!(0),
        M::Auto => thinking["thinkingBudget"] = json!(-1),
    }
}

fn anthropic(body: &mut Value, mode: ThinkingMode, support: Option<&ThinkingSupport>, model: &str) {
    use ThinkingMode as M;
    let adaptive = support
        .and_then(|support| support.adaptive)
        .unwrap_or_else(|| {
            support.is_some_and(|support| !support.levels.is_empty())
                || crate::capabilities::claude_uses_adaptive_thinking(Some(model))
        });
    if let Some(output) = body.get_mut("output_config") {
        remove(output, "effort");
    }
    let thinking = object_at(body, "thinking");
    remove(thinking, "budget_tokens");
    match mode {
        M::Off => {
            thinking["type"] = json!("disabled");
            remove(thinking, "display");
        }
        M::Level(level) if adaptive => {
            thinking["type"] = json!("adaptive");
            let effort = match level {
                ThinkingLevel::Minimal | ThinkingLevel::Low => "low",
                ThinkingLevel::Medium => "medium",
                ThinkingLevel::High => "high",
                ThinkingLevel::XHigh | ThinkingLevel::Max => "max",
            };
            object_at(body, "output_config")["effort"] = json!(effort);
        }
        M::Auto if adaptive => thinking["type"] = json!("adaptive"),
        M::Auto => thinking["type"] = json!("enabled"),
        M::Budget(budget) => {
            thinking["type"] = json!("enabled");
            thinking["budget_tokens"] = json!(budget);
        }
        M::Level(level) => {
            thinking["type"] = json!("enabled");
            thinking["budget_tokens"] = json!(level.budget().max(1024));
        }
    }
    if mode != M::Off {
        if let Some(max) = body.get("max_tokens").and_then(Value::as_u64)
            && let Some(budget) = body
                .pointer("/thinking/budget_tokens")
                .and_then(Value::as_u64)
            && budget >= max
        {
            if max <= 1024 {
                body["thinking"] = json!({"type":"disabled"});
                tracing::debug!(
                    model,
                    max_tokens = max,
                    "thinking dropped: explicit output limit cannot fit Anthropic minimum"
                );
            } else {
                body["thinking"]["budget_tokens"] = json!(budget.min(max - 1));
            }
        }
        remove(body, "temperature");
        remove(body, "top_p");
    }
}

pub(super) fn remove(body: &mut Value, field: &str) {
    if let Some(object) = body.as_object_mut() {
        object.remove(field);
    }
}

pub(super) fn object_at<'a>(body: &'a mut Value, field: &str) -> &'a mut Value {
    if !body.get(field).is_some_and(Value::is_object) {
        body[field] = json!({});
    }
    &mut body[field]
}

//! Resolve capability evidence only after the upstream account is selected.
use super::ThinkingProtocol;
use crate::app_state::AppState;
use crate::subscription::SubscriptionProvider;
use serde_json::Value;

/// Validate a translated or native body against this attempt's exact catalog.
/// Missing, stale, conflicting or differently scoped evidence is unknown.
/// Returns whether the payload changed, allowing native byte replay otherwise.
#[allow(clippy::too_many_arguments)]
pub fn apply_for_account(
    state: &AppState,
    body: &mut Value,
    model: &str,
    provider: SubscriptionProvider,
    account: &str,
    inference_base: &str,
    protocol: ThinkingProtocol,
    origin: ThinkingProtocol,
    from_suffix: bool,
) -> Result<bool, String> {
    let (origin, from_suffix) = super::ORIGIN
        .try_with(|intent| *intent)
        .unwrap_or((origin, from_suffix));
    super::policy::remember(body, protocol, origin, from_suffix);
    let records = state
        .model_catalogs
        .records_for_accounts(provider, &[account.to_string()]);
    let mut matching = records.iter().filter(|record| {
        record.canonical_id == model
            || (provider == SubscriptionProvider::Gemini
                && record.canonical_id == format!("models/{model}"))
    });
    let Some(record) = matching.next() else {
        return Ok(false);
    };
    if matching.next().is_some() {
        return Ok(false);
    }
    if crate::operation_context::now()
        .timestamp()
        .saturating_sub(record.fetched_at)
        > i64::try_from(crate::model_catalog::CATALOG_TTL.as_secs()).unwrap_or(i64::MAX)
    {
        return Ok(false);
    }
    // Discovery and inference must share the configured endpoint. Gemini's
    // documented public registry is separate from its Code Assist inference.
    let base = inference_base.trim_end_matches('/');
    let expected = match provider {
        SubscriptionProvider::Claude => format!("{base}/v1/models"),
        SubscriptionProvider::Codex | SubscriptionProvider::Qwen => format!("{base}/models"),
        SubscriptionProvider::Gemini => {
            if base != "https://cloudcode-pa.googleapis.com" {
                return Ok(false);
            }
            "https://generativelanguage.googleapis.com/v1beta/models".to_string()
        }
    };
    if record.raw.get("router_endpoint").and_then(Value::as_str) != Some(expected.as_str())
        || record.raw.get("router_account").and_then(Value::as_str) != Some(record.account.as_str())
        || record
            .raw
            .get("router_health_generation")
            .and_then(Value::as_str)
            != Some(record.health_generation.as_str())
    {
        return Ok(false);
    }
    let truth = crate::model_routing::thinking_model_truth(record);
    let Some(support) = super::support::from_truth(&truth, &record.canonical_id, protocol) else {
        return Ok(false);
    };
    let Some(config) = super::extract_config(body, protocol)? else {
        return Ok(false);
    };
    if support.supported == Some(false) {
        tracing::debug!(
            model,
            provider = provider.as_str(),
            account,
            "thinking dropped: exact selected model does not support it"
        );
        let original = body.clone();
        super::apply::clear(body, protocol);
        return Ok(*body != original);
    }
    let validated = super::support::validate(config, &support, origin, protocol, from_suffix)?;
    if validated == config {
        return Ok(false);
    }
    let original = body.clone();
    super::apply::apply(
        body,
        validated,
        protocol,
        Some(&support),
        &record.canonical_id,
    );
    Ok(*body != original)
}

