use super::{
    ThinkingConfig, ThinkingMode, ThinkingProtocol, parse_level_suffix, parse_special_suffix,
};
use serde_json::Value;

/// Extract body controls in their existing protocol precedence order.
/// Missing controls return None; explicit off/auto remain distinct.
pub fn extract_config(
    body: &Value,
    protocol: ThinkingProtocol,
) -> Result<Option<ThinkingConfig>, String> {
    use ThinkingProtocol as P;
    validate_containers(body, protocol)?;
    let mode = match protocol {
        P::Anthropic => anthropic(body)?,
        P::Qwen => {
            if body
                .get("enable_thinking")
                .is_some_and(|value| value == false)
            {
                Some(ThinkingMode::Off)
            } else if let Some(mode) = budget(body.get("thinking_budget"))? {
                Some(mode)
            } else {
                level(
                    body.pointer("/reasoning/effort")
                        .or_else(|| body.get("reasoning_effort")),
                )?
                .or_else(|| {
                    (body.get("enable_thinking") == Some(&Value::Bool(true)))
                        .then_some(ThinkingMode::Auto)
                })
            }
        }
        P::OpenAIChat => {
            // Router has always given reasoning.effort precedence over the flat field.
            level(
                body.pointer("/reasoning/effort")
                    .or_else(|| body.get("reasoning_effort")),
            )?
        }
        P::OpenAIResponses | P::Codex | P::Xai => level(body.pointer("/reasoning/effort"))?,
        P::Gemini | P::Vertex | P::Antigravity => {
            let root = if protocol == P::Antigravity {
                body.get("request").unwrap_or(body)
            } else {
                body
            };
            let thinking = root
                .pointer("/generationConfig/thinkingConfig")
                .or_else(|| root.pointer("/generation_config/thinking_config"));
            match thinking {
                Some(thinking) => level(
                    thinking
                        .get("thinkingLevel")
                        .or_else(|| thinking.get("thinking_level")),
                )?
                .map_or_else(
                    || {
                        budget(
                            thinking
                                .get("thinkingBudget")
                                .or_else(|| thinking.get("thinking_budget")),
                        )
                    },
                    |level| Ok(Some(level)),
                )?,
                None => None,
            }
        }
        P::Interactions => level(body.pointer("/generation_config/thinking_level"))?.map_or_else(
            || budget(body.pointer("/generation_config/thinking_budget")),
            |level| Ok(Some(level)),
        )?,
        P::Kimi => match body.pointer("/thinking/type").and_then(Value::as_str) {
            Some("disabled") => Some(ThinkingMode::Off),
            Some("enabled") => {
                level(body.pointer("/thinking/effort"))?.or(Some(ThinkingMode::Auto))
            }
            _ => level(
                body.pointer("/thinking/effort")
                    .or_else(|| body.get("reasoning_effort")),
            )?,
        },
    };
    Ok(mode.map(|mode| ThinkingConfig { mode }))
}

fn validate_containers(body: &Value, protocol: ThinkingProtocol) -> Result<(), String> {
    use ThinkingProtocol as P;
    if !body.is_object() {
        return Err("thinking source must be a JSON object".into());
    }
    let fields: &[&str] = match protocol {
        P::Anthropic => &["/thinking", "/output_config"],
        P::OpenAIChat | P::OpenAIResponses | P::Codex | P::Qwen | P::Xai => &["/reasoning"],
        P::Gemini | P::Vertex => &[
            "/generationConfig",
            "/generationConfig/thinkingConfig",
            "/generation_config",
            "/generation_config/thinking_config",
        ],
        P::Antigravity => &[
            "/request",
            "/request/generationConfig",
            "/request/generationConfig/thinkingConfig",
        ],
        P::Interactions => &["/generation_config"],
        P::Kimi => &["/thinking"],
    };
    for field in fields {
        if body
            .pointer(field)
            .is_some_and(|value| !value.is_null() && !value.is_object())
        {
            return Err(format!("{field} must be an object"));
        }
    }
    if matches!(protocol, P::Anthropic | P::Kimi)
        && body
            .pointer("/thinking/type")
            .is_some_and(|value| !value.is_string())
    {
        return Err("thinking.type must be a string".into());
    }
    if protocol == P::Qwen
        && body
            .get("enable_thinking")
            .is_some_and(|value| !value.is_boolean())
    {
        return Err("enable_thinking must be a boolean".into());
    }
    Ok(())
}

pub(super) fn level(value: Option<&Value>) -> Result<Option<ThinkingMode>, String> {
    let Some(value) = value.filter(|value| !value.is_null()) else {
        return Ok(None);
    };
    let raw = value.as_str().ok_or("thinking effort must be a string")?;
    parse_special_suffix(raw)
        .or_else(|| parse_level_suffix(raw).map(ThinkingMode::Level))
        .map(Some)
        .ok_or_else(|| format!("unsupported thinking effort: {raw}"))
}

fn budget(value: Option<&Value>) -> Result<Option<ThinkingMode>, String> {
    let Some(value) = value.filter(|value| !value.is_null()) else {
        return Ok(None);
    };
    if value.as_i64() == Some(-1) {
        return Ok(Some(ThinkingMode::Auto));
    }
    let budget = value
        .as_u64()
        .and_then(|budget| u32::try_from(budget).ok())
        .ok_or("thinking budget must be -1 or a nonnegative u32 integer")?;
    Ok(Some(if budget == 0 {
        ThinkingMode::Off
    } else {
        ThinkingMode::Budget(budget)
    }))
}

fn anthropic(body: &Value) -> Result<Option<ThinkingMode>, String> {
    let kind = body.pointer("/thinking/type").and_then(Value::as_str);
    match kind {
        Some("disabled") => Ok(Some(ThinkingMode::Off)),
        Some("enabled") => {
            Ok(budget(body.pointer("/thinking/budget_tokens"))?.or(Some(ThinkingMode::Auto)))
        }
        Some("adaptive") => {
            Ok(level(body.pointer("/output_config/effort"))?.or(Some(ThinkingMode::Auto)))
        }
        Some(kind) => Err(format!("unsupported thinking type: {kind}")),
        None => level(body.pointer("/output_config/effort")),
    }
}

use super::{ThinkingConfig, ThinkingLevel, ThinkingMode};

/// Syntactic suffix extraction, matching the upstream last-opening-parenthesis grammar.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SuffixResult<'a> {
    pub model_name: &'a str,
    pub raw_suffix: Option<&'a str>,
}

impl SuffixResult<'_> {
    /// Interpret recognized suffixes. Invalid text and u32 overflow are ignored.
    #[must_use]
    pub fn config(self) -> Option<ThinkingConfig> {
        let raw = self.raw_suffix?;
        let mode = parse_special_suffix(raw)
            .or_else(|| parse_level_suffix(raw).map(ThinkingMode::Level))
            .or_else(|| {
                parse_numeric_suffix(raw).map(|budget| {
                    if budget == 0 {
                        ThinkingMode::Off
                    } else {
                        ThinkingMode::Budget(budget)
                    }
                })
            })?;
        Some(ThinkingConfig { mode })
    }
}

/// Extract a trailing suffix without interpreting its contents.
#[must_use]
pub fn parse_suffix(model: &str) -> SuffixResult<'_> {
    if let Some(open) = model.rfind('(')
        && model.ends_with(')')
    {
        SuffixResult {
            model_name: &model[..open],
            raw_suffix: Some(&model[open + 1..model.len() - 1]),
        }
    } else {
        SuffixResult {
            model_name: model,
            raw_suffix: None,
        }
    }
}

/// Parse a nonnegative u32 budget; leading zeros, plus and signed zero are accepted.
#[must_use]
pub fn parse_numeric_suffix(raw: &str) -> Option<u32> {
    if raw
        .strip_prefix('-')
        .is_some_and(|digits| !digits.is_empty() && digits.bytes().all(|digit| digit == b'0'))
    {
        Some(0)
    } else {
        raw.parse().ok()
    }
}

/// Parse case-insensitive none/auto, including -1 as automatic thinking.
#[must_use]
pub fn parse_special_suffix(raw: &str) -> Option<ThinkingMode> {
    match raw.to_ascii_lowercase().as_str() {
        "none" => Some(ThinkingMode::Off),
        "auto" | "-1" => Some(ThinkingMode::Auto),
        _ => None,
    }
}

/// Parse one of minimal, low, medium, high, xhigh and max, case-insensitively.
#[must_use]
pub fn parse_level_suffix(raw: &str) -> Option<ThinkingLevel> {
    match raw.to_ascii_lowercase().as_str() {
        "minimal" => Some(ThinkingLevel::Minimal),
        "low" => Some(ThinkingLevel::Low),
        "medium" => Some(ThinkingLevel::Medium),
        "high" => Some(ThinkingLevel::High),
        "xhigh" => Some(ThinkingLevel::XHigh),
        "max" => Some(ThinkingLevel::Max),
        _ => None,
    }
}

//! Preserve unconstrained target controls across the account policy retry loop.
use super::ThinkingProtocol;
use serde_json::{Map, Value};

/// Only configuration fields are saved; replay history remains owned by dispatch.
#[derive(Clone)]
pub struct RetryControls {
    fields: Map<String, Value>,
    protocol: ThinkingProtocol,
    origin: ThinkingProtocol,
    from_suffix: bool,
}

const fn keys(protocol: ThinkingProtocol) -> &'static [&'static str] {
    match protocol {
        ThinkingProtocol::Anthropic | ThinkingProtocol::Kimi => &["thinking", "output_config"],
        ThinkingProtocol::OpenAIChat | ThinkingProtocol::Qwen => &[
            "reasoning_effort",
            "reasoning",
            "enable_thinking",
            "thinking_budget",
        ],
        ThinkingProtocol::OpenAIResponses | ThinkingProtocol::Codex | ThinkingProtocol::Xai => {
            &["reasoning"]
        }
        ThinkingProtocol::Gemini | ThinkingProtocol::Vertex | ThinkingProtocol::Antigravity => {
            &["generationConfig", "generation_config"]
        }
        ThinkingProtocol::Interactions => &["thinking_level", "thinking_budget"],
    }
}

/// Capture before the first account can clamp or drop controls, even if its
/// catalog is unknown. Later attempts must not replace this original intent.
pub(super) fn remember(
    body: &Value,
    protocol: ThinkingProtocol,
    origin: ThinkingProtocol,
    from_suffix: bool,
) {
    if let Some(scope) = crate::account_policy_scope::current() {
        scope
            .thinking
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get_or_insert_with(|| RetryControls {
                fields: keys(protocol)
                    .iter()
                    .filter_map(|key| body.get(*key).map(|value| ((*key).into(), value.clone())))
                    .collect(),
                protocol,
                origin,
                from_suffix,
            });
    }
}

/// Restore target controls after account-bound history is stripped, then use
/// the newly selected account's exact capability evidence before sending.
pub fn revalidate(
    scope: &crate::account_policy_scope::PolicyRequest,
    selected: &crate::accounts::SelectedSubscriptionAccount,
    body: &mut Value,
    model: &str,
) -> Result<(), String> {
    let controls = scope
        .thinking
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone();
    let Some(controls) = controls else {
        return Ok(());
    };
    let body = if matches!(
        controls.protocol,
        ThinkingProtocol::Gemini | ThinkingProtocol::Vertex
    ) && body.get("request").is_some_and(Value::is_object)
    {
        body.get_mut("request").expect("Code Assist request object")
    } else {
        body
    };
    if let Some(object) = body.as_object_mut() {
        for key in keys(controls.protocol) {
            match controls.fields.get(*key) {
                Some(value) => {
                    object.insert((*key).into(), value.clone());
                }
                None => {
                    object.remove(*key);
                }
            }
        }
    }
    let provider = scope
        .state
        .account_router
        .as_ref()
        .expect("policy pool")
        .provider();
    let base = if provider == crate::subscription::SubscriptionProvider::Claude {
        scope.state.upstream_base_url.clone()
    } else {
        scope
            .state
            .subscription_base_url
            .clone()
            .unwrap_or_else(|| selected.token.base_url(provider))
    };
    super::apply_for_account(
        &scope.state,
        body,
        model,
        provider,
        &selected.name,
        &base,
        controls.protocol,
        controls.origin,
        controls.from_suffix,
    )?;
    Ok(())
}

use super::{ThinkingConfig, ThinkingLevel, ThinkingMode, ThinkingProtocol, parse_level_suffix};
use crate::model_contract::ModelTruthDescriptor;
use serde_json::Value;

/// Optional exact-model capability facts. None means unknown, never unsupported.
#[derive(Clone, Debug, Default, serde::Deserialize, serde::Serialize)]
#[serde(deny_unknown_fields)]
pub struct ThinkingSupport {
    pub supported: Option<bool>,
    pub min_budget_tokens: Option<u32>,
    pub max_budget_tokens: Option<u32>,
    #[serde(default)]
    pub levels: Vec<ThinkingLevel>,
    pub zero_allowed: Option<bool>,
    pub dynamic_allowed: Option<bool>,
    pub adaptive: Option<bool>,
}

impl ThinkingSupport {
    pub(crate) const fn has_facts(&self) -> bool {
        self.supported.is_some()
            || self.min_budget_tokens.is_some()
            || self.max_budget_tokens.is_some()
            || !self.levels.is_empty()
            || self.zero_allowed.is_some()
            || self.dynamic_allowed.is_some()
            || self.adaptive.is_some()
    }
}

pub(super) fn from_truth(
    truth: &ModelTruthDescriptor,
    model: &str,
    protocol: ThinkingProtocol,
) -> Option<ThinkingSupport> {
    if truth.upstream_request_model.as_deref() != Some(model)
        || !truth
            .route
            .protocols
            .iter()
            .any(|name| matches_protocol(name, protocol))
    {
        return None;
    }
    if trusted_field(truth, model, "thinking") {
        let support: ThinkingSupport =
            serde_json::from_value(truth.capabilities.get("thinking")?.clone()).ok()?;
        if !support.has_facts()
            || matches!((support.min_budget_tokens, support.max_budget_tokens), (Some(min), Some(max)) if min > max)
        {
            return None;
        }
        return Some(support);
    }
    if !trusted_field(truth, model, "supported_reasoning_levels") {
        return None;
    }
    let levels = truth
        .capabilities
        .get("supported_reasoning_levels")?
        .as_array()?;
    let levels = levels
        .iter()
        .filter_map(|level| {
            parse_level_suffix(
                level
                    .as_str()
                    .or_else(|| level.get("effort").and_then(Value::as_str))?,
            )
        })
        .collect::<Vec<_>>();
    (!levels.is_empty()).then_some(ThinkingSupport {
        levels,
        ..ThinkingSupport::default()
    })
}

fn matches_protocol(name: &str, protocol: ThinkingProtocol) -> bool {
    use crate::client_policy::ClientProtocol as C;
    use ThinkingProtocol as P;
    // Discovery serializes ClientProtocol directly. Preserve those exact wire
    // spellings as well as the established public protocol names below.
    let native = serde_json::from_value::<C>(Value::String(name.to_string())).ok();
    let native_matches = matches!(
        (native, protocol),
        (Some(C::AnthropicMessages), P::Anthropic)
            | (Some(C::OpenAIChat), P::OpenAIChat | P::Qwen)
            | (Some(C::OpenAIResponses), P::OpenAIResponses | P::Codex)
            | (Some(C::GeminiNative), P::Gemini | P::Vertex)
    );
    ThinkingProtocol::from_name(name) == Some(protocol)
        || native_matches
        || match protocol {
            P::Anthropic => name == "anthropic_messages",
            P::OpenAIChat | P::Qwen => name == "openai_chat",
            P::OpenAIResponses => name == "openai_responses",
            P::Codex => matches!(
                name,
                "openai_responses" | "openai-response" | "openai-responses"
            ),
            P::Gemini | P::Vertex => name == "gemini_native",
            _ => false,
        }
}

fn trusted_field(truth: &ModelTruthDescriptor, model: &str, field: &str) -> bool {
    let Some(evidence) = truth
        .capability_provenance
        .get("fields")
        .and_then(|fields| fields.get(field))
    else {
        return false;
    };
    let scope = &evidence["scope"];
    truth
        .route
        .provider
        .as_ref()
        .is_some_and(|value| !value.is_empty())
        && truth
            .route
            .account
            .as_ref()
            .is_some_and(|value| !value.is_empty())
        && truth
            .route
            .endpoint
            .as_ref()
            .is_some_and(|value| !value.is_empty())
        && !truth.route.protocols.is_empty()
        && evidence
            .get("source_kind")
            .and_then(Value::as_str)
            .is_some_and(|source| {
                matches!(
                    source,
                    "authenticated_live_catalog"
                        | "authenticated_live_model_catalog"
                        | "reviewed_provider_documentation"
                )
            })
        && evidence.get("conflict") == Some(&Value::Bool(false))
        && evidence.get("unknown") == Some(&Value::Bool(false))
        && scope.get("model").and_then(Value::as_str) == Some(model)
        && scope.get("provider").and_then(Value::as_str) == truth.route.provider.as_deref()
        && scope.get("account").and_then(Value::as_str) == truth.route.account.as_deref()
        && scope.get("endpoint").and_then(Value::as_str) == truth.route.endpoint.as_deref()
        && scope.get("protocols") == Some(&serde_json::json!(truth.route.protocols))
}

pub(super) fn validate(
    config: ThinkingConfig,
    support: &ThinkingSupport,
    from: ThinkingProtocol,
    to: ThinkingProtocol,
    from_suffix: bool,
) -> Result<ThinkingConfig, String> {
    use ThinkingMode as M;
    let has_budget = support.min_budget_tokens.is_some() || support.max_budget_tokens.is_some();
    let has_levels = !support.levels.is_empty();
    let mut mode = config.mode;
    let derived = matches!(mode, M::Budget(_));
    if !has_levels
        && has_budget
        && let M::Level(level) = mode
    {
        mode = M::Budget(level.budget());
    }
    if has_levels
        && (!has_budget || (to == ThinkingProtocol::Anthropic && from != to))
        && let M::Budget(budget) = mode
    {
        mode = M::Level(ThinkingLevel::from_budget(budget));
    }
    if let M::Level(mut level) = mode {
        if to == ThinkingProtocol::Anthropic && from != ThinkingProtocol::Anthropic {
            level = match level {
                ThinkingLevel::Minimal => ThinkingLevel::Low,
                ThinkingLevel::XHigh | ThinkingLevel::Max => {
                    if support.levels.contains(&ThinkingLevel::Max) {
                        ThinkingLevel::Max
                    } else {
                        ThinkingLevel::High
                    }
                }
                _ => level,
            };
        }
        if has_levels && !support.levels.contains(&level) {
            if from.family() == to.family() && !derived {
                return Err(format!(
                    "thinking level {} is not supported by the exact model",
                    level.as_str()
                ));
            }
            level = nearest(level, &support.levels);
        }
        mode = M::Level(level);
    }
    if mode == M::Auto
        && support.dynamic_allowed == Some(false)
        && (has_budget || has_levels)
        && !(to == ThinkingProtocol::Anthropic && has_levels)
    {
        mode = if has_levels && !has_budget {
            M::Level(nearest(ThinkingLevel::Medium, &support.levels))
        } else {
            let min = support.min_budget_tokens.unwrap_or(0);
            let max = support.max_budget_tokens.unwrap_or(min);
            M::Budget(min + max.saturating_sub(min) / 2)
        };
    }
    if mode == M::Auto && to == ThinkingProtocol::Anthropic && has_levels && from != to {
        mode = M::Level(nearest(ThinkingLevel::High, &support.levels));
    }
    if mode == M::Off
        && support.zero_allowed == Some(false)
        && (has_budget || has_levels)
        && !(to == ThinkingProtocol::Anthropic && has_levels)
    {
        mode = if has_levels {
            M::Level(*support.levels.iter().min().unwrap_or(&ThinkingLevel::Low))
        } else {
            M::Budget(support.min_budget_tokens.unwrap_or(0))
        };
    }
    if let M::Budget(budget) = mode {
        let min = support.min_budget_tokens.unwrap_or(0);
        let max = support.max_budget_tokens.unwrap_or(u32::MAX);
        if min > max {
            return Err("conflicting thinking budget evidence".into());
        }
        let clamped = budget.clamp(min, max);
        if budget != clamped
            && !from_suffix
            && from.family() == to.family()
            && matches!(config.mode, M::Budget(_))
        {
            return Err(format!(
                "thinking budget {budget} is outside [{min}, {max}]"
            ));
        }
        mode = M::Budget(clamped);
    }
    if mode != config.mode {
        tracing::debug!(?from, ?to, original = ?config.mode, effective = ?mode,
            "thinking converted or clamped to exact model evidence");
    }
    Ok(ThinkingConfig { mode })
}

pub(super) fn nearest(level: ThinkingLevel, supported: &[ThinkingLevel]) -> ThinkingLevel {
    supported
        .iter()
        .min_by_key(|supported| ((**supported as u8).abs_diff(level as u8), **supported))
        .copied()
        .unwrap_or(level)
}

//! Summary visibility does not change the requested amount of thinking.
use super::ThinkingProtocol;
use super::apply::{object_at, remove};
use serde_json::{Value, json};

pub(super) fn extract(body: &Value, from: ThinkingProtocol) -> Option<bool> {
    use ThinkingProtocol as P;
    match from {
        P::Gemini | P::Vertex => body
            .pointer("/generationConfig/thinkingConfig/includeThoughts")
            .or_else(|| body.pointer("/generationConfig/thinkingConfig/include_thoughts"))
            .or_else(|| body.pointer("/generation_config/thinking_config/include_thoughts"))
            .and_then(Value::as_bool),
        P::Antigravity => extract(body.get("request").unwrap_or(body), P::Gemini),
        P::Anthropic => body
            .pointer("/thinking/display")
            .and_then(Value::as_str)
            .map(|value| value != "omitted"),
        P::OpenAIChat | P::Qwen => body
            .pointer("/reasoning/summary")
            .and_then(Value::as_str)
            .map(|summary| summary != "none")
            .or_else(|| {
                body.get("reasoning_effort")
                    .and_then(Value::as_str)
                    .map(|effort| effort != "none")
            }),
        P::OpenAIResponses | P::Codex | P::Xai => body
            .pointer("/reasoning/summary")
            .or_else(|| body.pointer("/reasoning/generate_summary"))
            .and_then(Value::as_str)
            .map(|value| value != "none"),
        P::Interactions => body
            .pointer("/generation_config/thinking_summaries")
            .and_then(Value::as_str)
            .map(|value| value != "none"),
        P::Kimi => None,
    }
}

pub(super) fn apply(body: &mut Value, to: ThinkingProtocol, visibility: Option<bool>) {
    use ThinkingProtocol as P;
    let Some(visible) = visibility else { return };
    match to {
        P::Gemini | P::Vertex => {
            // An explicit disabled level configuration must not be recreated.
            let Some(thinking) = body.pointer_mut("/generationConfig/thinkingConfig") else {
                return;
            };
            remove(thinking, "include_thoughts");
            thinking["includeThoughts"] = json!(visible);
        }
        P::Antigravity => {
            if let Some(request) = body.get_mut("request") {
                apply(request, P::Gemini, visibility);
            }
        }
        P::Anthropic => {
            if body
                .pointer("/thinking/type")
                .and_then(Value::as_str)
                .is_some_and(|kind| kind != "disabled")
            {
                body["thinking"]["display"] = json!(if visible { "summarized" } else { "omitted" });
            }
        }
        P::OpenAIResponses | P::Codex | P::Xai => {
            if visible {
                let reasoning = object_at(body, "reasoning");
                if reasoning.get("summary").is_none() {
                    reasoning["summary"] = json!("auto");
                }
            } else if let Some(reasoning) = body.get_mut("reasoning") {
                remove(reasoning, "summary");
            }
        }
        P::Interactions => {
            object_at(body, "generation_config")["thinking_summaries"] =
                json!(if visible { "auto" } else { "none" });
        }
        P::OpenAIChat | P::Qwen | P::Kimi => {}
    }
}

//! Optional TLS termination in the router itself.
//!
//! `gh` builds a custom host's REST base as `https://<host>/api/v3/` with no
//! plaintext option, so reaching the GitHub proxy required a separate TLS
//! terminator in front of the router. For a router deliberately *not* reachable
//! from outside — an internal-only sidecar on a private Docker network — that
//! meant standing up a reverse proxy and a private CA purely to satisfy a
//! client's HTTPS requirement, and the one surface most worth mediating (the
//! one that can delete repositories) was the one that could not be pointed at
//! the router (issue #263).
//!
//! Serving TLS here removes that step. `TLS_SELF_SIGNED=1` additionally
//! generates a certificate for the configured names, so a private-network
//! operator enables HTTPS without a CA at all; the certificate is written where
//! `router tls ca` can print it for clients to trust.
//!
//! Unset means unchanged: the router serves plain HTTP exactly as before.

use std::path::{Path, PathBuf};

/// Where the generated certificate and key live inside the data directory.
const GENERATED_DIRECTORY: &crate::translation_core::Str = "tls";
const GENERATED_CERT: &crate::translation_core::Str = "cert.pem";
const GENERATED_KEY: &crate::translation_core::Str = "key.pem";

/// How the router should serve its main listener.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TlsSetup {
    /// Serve plain HTTP, as the router always has.
    Disabled,
    /// Serve HTTPS from this certificate and key.
    Enabled { cert: PathBuf, key: PathBuf },
}

impl TlsSetup {
    /// Whether this setup serves HTTPS.
    #[must_use]
    pub const fn is_enabled(&self) -> bool {
        matches!(self, Self::Enabled { .. })
    }
}

/// Names a generated certificate is valid for.
///
/// A sidecar is reached by its network alias rather than a public hostname, so
/// the container name must be present or the certificate is useless for the
/// deployment it was generated for. Loopback names are included because an
/// operator debugging from inside the container reaches it that way.
#[must_use]
pub fn generated_subject_names(configured: &crate::translation_core::Str) -> Vec<String> {
    let mut names: Vec<String> = configured
        .split(',')
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(str::to_string)
        .collect();
    for fallback in ["localhost", "127.0.0.1"] {
        if !names.iter().any(|name| name == fallback) {
            names.push(fallback.to_string());
        }
    }
    names
}

/// Resolve the TLS setup from the environment.
///
/// An explicit certificate pair wins over generation, so an operator who has a
/// real certificate is never silently served a self-signed one.
///
/// # Errors
///
/// Returns a message when only one half of the pair is set — that is a
/// misconfiguration whose silent fallback to plaintext would be the opposite of
/// what was asked for — or when generation fails.
pub fn from_env(data_dir: &Path) -> crate::translation_core::Outcome<TlsSetup, String> {
    let read = |name: &str| {
        crate::operation_context::var(name)
            .ok()
            .filter(|value| !value.is_empty())
    };
    resolve(
        data_dir,
        read("TLS_CERT_FILE"),
        read("TLS_KEY_FILE"),
        read("TLS_SELF_SIGNED").as_deref() == Some("1"),
        read("TLS_SELF_SIGNED_DNS"),
    )
}

/// Decide the setup from already-read settings.
///
/// Split from [`from_env`] so every branch is reachable in a test: this crate
/// forbids `unsafe`, and mutating the process environment is the only other
/// way to drive them.
///
/// # Errors
///
/// Returns a message when only one half of the pair is given, or when
/// generation fails.
pub fn resolve(
    data_dir: &Path,
    cert: crate::translation_core::Maybe<String>,
    key: crate::translation_core::Maybe<String>,
    self_signed: bool,
    self_signed_dns: crate::translation_core::Maybe<String>,
) -> crate::translation_core::Outcome<TlsSetup, String> {
    match (cert, key) {
        (Some(cert), Some(key)) => Ok(TlsSetup::Enabled {
            cert: PathBuf::from(cert),
            key: PathBuf::from(key),
        }),
        (Some(_), None) => Err("TLS_CERT_FILE is set without TLS_KEY_FILE".to_string()),
        (None, Some(_)) => Err("TLS_KEY_FILE is set without TLS_CERT_FILE".to_string()),
        (None, None) => {
            if !self_signed {
                return Ok(TlsSetup::Disabled);
            }
            let names = generated_subject_names(
                &self_signed_dns.unwrap_or_else(|| "localhost".to_string()),
            );
            let (cert, key) = ensure_generated(data_dir, &names)?;
            Ok(TlsSetup::Enabled { cert, key })
        }
    }
}

/// Paths of the generated certificate pair within `data_dir`.
#[must_use]
pub fn generated_paths(data_dir: &Path) -> (PathBuf, PathBuf) {
    let directory = data_dir.join(GENERATED_DIRECTORY);
    (
        directory.join(GENERATED_CERT),
        directory.join(GENERATED_KEY),
    )
}

/// Generate a self-signed certificate for `names`, reusing an existing one.
///
/// Reused rather than regenerated on every start: clients are told to trust
/// this certificate, and rotating it on restart would break every one of them
/// without saying why.
///
/// # Errors
///
/// Returns a message when the certificate cannot be generated or written.
pub fn ensure_generated(data_dir: &Path, names: &[String]) -> crate::translation_core::Outcome<(PathBuf, PathBuf), String> {
    let (cert_path, key_path) = generated_paths(data_dir);
    if cert_path.is_file() && key_path.is_file() {
        return Ok((cert_path, key_path));
    }
    let generated = rcgen::generate_simple_self_signed(names.to_vec())
        .map_err(|error| format!("could not generate a self-signed certificate: {error}"))?;
    let directory = cert_path
        .parent()
        .ok_or_else(|| "generated certificate has no directory".to_string())?;
    std::fs::create_dir_all(directory)
        .map_err(|error| format!("could not create {}: {error}", directory.display()))?;
    crate::durable_file::atomic_write_owner_only(&cert_path, generated.cert.pem().as_bytes())
        .map_err(|error| crate::durable_file::describe_write_failure(&cert_path, &error))?;
    // The private key is written owner-only, like every other secret this
    // crate persists.
    crate::durable_file::atomic_write_owner_only(
        &key_path,
        generated.signing_key.serialize_pem().as_bytes(),
    )
    .map_err(|error| crate::durable_file::describe_write_failure(&key_path, &error))?;
    Ok((cert_path, key_path))
}

/// The generated certificate in PEM form, for a client to trust.
///
/// # Errors
///
/// Returns a message when no certificate has been generated yet.
pub fn read_generated_certificate(data_dir: &Path) -> crate::translation_core::Outcome<String, String> {
    let (cert_path, _) = generated_paths(data_dir);
    std::fs::read_to_string(&cert_path).map_err(|error| {
        format!(
            "no generated certificate at {}: {error}; start the router with TLS_SELF_SIGNED=1 first",
            cert_path.display()
        )
    })
}

/// Serve the application over HTTPS from a certificate pair.
///
/// Lives in the library so the large `axum_server` serve future is never part
/// of the binary's `main` state machine: on Windows that overflowed the 1 MB
/// main-thread stack for subcommands that never serve at all.
///
/// # Errors
///
/// Returns a message when the certificate cannot be loaded or the listener
/// cannot be bound.
pub async fn serve_https(
    address: std::net::SocketAddr,
    app: axum::Router,
    cert: std::path::PathBuf,
    key: std::path::PathBuf,
    shutdown: impl std::future::Future<Output = ()> + Send + 'static,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    tracing::info!("Serving HTTPS with certificate {}", cert.display());
    let tls = load_config(&cert, &key).await?;
    let listener = tokio::net::TcpListener::bind(address).await?;
    tracing::info!("Listening on https://{}", listener.local_addr()?);
    serve_prebound_https(listener, app, tls, shutdown).await
}

/// Load a TLS certificate pair before any network listener begins serving.
///
/// # Errors
///
/// Returns a message naming the certificate when it cannot be loaded.
pub async fn load_config(
    cert: &Path,
    key: &Path,
) -> crate::translation_core::Outcome<axum_server::tls_rustls::RustlsConfig, String> {
    axum_server::tls_rustls::RustlsConfig::from_pem_file(cert, key)
        .await
        .map_err(|error| {
            format!(
                "could not load the TLS certificate {}: {error}",
                cert.display()
            )
        })
}

/// Serve HTTPS from an already-reserved socket and loaded certificate.
///
/// # Errors
///
/// Returns an error when the socket cannot be converted or served.
pub async fn serve_prebound_https(
    listener: tokio::net::TcpListener,
    app: axum::Router,
    tls: axum_server::tls_rustls::RustlsConfig,
    shutdown: impl std::future::Future<Output = ()> + Send + 'static,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    // `axum_server` stops through a handle rather than a future, so the
    // notice is translated into one. Without this the HTTPS path had no
    // shutdown hook at all and could only ever be killed (issue #334).
    let handle = axum_server::Handle::new();
    let shutdown_handle = handle.clone();
    tokio::spawn(async move {
        shutdown.await;
        // `None` is an unbounded grace period: the deployment's own stop
        // timeout is the bound, and cutting a stream short here would be the
        // very failure this exists to prevent.
        shutdown_handle.graceful_shutdown(None);
    });
    // Reusing this exact socket prevents a second resolution or a bind to a
    // broader address (issue #545).
    let listener = listener.into_std()?;
    axum_server::from_tcp_rustls(listener, tls)?
        .handle(handle)
        .serve(app.into_make_service_with_connect_info::<std::net::SocketAddr>())
        .await?;
    Ok(())
}

