//! Constant-time helpers kept out of the already dense token lifecycle module.

/// Compare two secrets without leaking their contents through timing.
///
/// Both sides are hashed with SHA-256 first, so comparison always runs over 32
/// bytes and never short-circuits at the first different byte.
#[must_use]
pub fn constant_time_eq(a: &str, b: &str) -> bool {
    use sha2::{Digest, Sha256};

    let left = Sha256::digest(a.as_bytes());
    let right = Sha256::digest(b.as_bytes());
    let mut diff = 0u8;
    for (x, y) in left.iter().zip(right.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

//! Renewable wrapper-process leases used by safe local deployment inventory.

use super::{IssueRequest, ModelAccessPolicy, TokenError, TokenManager};

/// How long a wrapper stays provably live without another heartbeat.
pub const RUN_LEASE_TTL_SECONDS: i64 = 120;

impl TokenManager {
    /// Issue an ephemeral, model-pinned token with an explicit liveness lease.
    pub fn issue_ephemeral_with_model_policy_and_run_lease(
        &self,
        request: &IssueRequest<'_>,
        model_policy: &ModelAccessPolicy,
    ) -> Result<String, jsonwebtoken::errors::Error> {
        self.issue_with_id_and_model_policy(
            request,
            true,
            model_policy,
            Some(RUN_LEASE_TTL_SECONDS),
        )
        .map(|(token, _)| token)
    }

    /// Extend an existing lease; an authenticated wrapper may recover after a
    /// server outage, but a legacy record with no lease is never promoted.
    pub fn renew_run_lease(&self, token_id: &str) -> Result<i64, TokenError> {
        // An emergency-bypassed wrapper keeps its heartbeat answered without
        // any record being created or extended (issue #645).
        if crate::emergency_auth::is_synthetic_id(token_id) {
            return Ok(crate::operation_context::now()
                .timestamp()
                .saturating_add(RUN_LEASE_TTL_SECONDS));
        }
        self.store
            .renew_run_lease(
                token_id,
                crate::operation_context::now().timestamp(),
                RUN_LEASE_TTL_SECONDS,
            )
            .map_err(|error| TokenError::Storage(error.to_string()))?
            .ok_or_else(|| {
                TokenError::Invalid(
                    "run lease is absent, revoked, expired as a token, or not ephemeral"
                        .to_string(),
                )
            })
    }
}

//! Incoming-token validation, its diagnostics, and the emergency bypass.

use axum::http::HeaderMap;
use jsonwebtoken::{DecodingKey, Validation, decode};

use super::{TokenClaims, TokenError, TokenManager, token_jwt};
use crate::auth_diagnostics::AuthDiagnostics;
use crate::emergency_auth::EmergencyAuth;

impl TokenManager {
    /// Validate a custom token string.
    ///
    /// Strips either Router carrier prefix, decodes the same JWT, checks
    /// expiration and revocation status, and returns the claims if valid.
    /// This is always the strict check: the emergency mode is applied only by
    /// [`Self::authenticate_incoming`], never here.
    pub fn validate_token(&self, token: &str) -> Result<TokenClaims, TokenError> {
        if crate::token_secret::is_placeholder(&self.secret) {
            return Err(TokenError::IssuerSecretUnset);
        }
        let jwt = token_jwt(token).ok_or(TokenError::InvalidPrefix)?;
        let injected_time = crate::operation_context::current().and_then(|context| context.now);
        let mut validation = Validation::default();
        let leeway = i64::try_from(validation.leeway).unwrap_or(i64::MAX);
        // The decoder has no injectable clock. Keep signature/claim validation,
        // and enforce its same inclusive expiry leeway against the caller's time.
        validation.validate_exp = injected_time.is_none();
        let token_data = decode::<TokenClaims>(
            jwt,
            &DecodingKey::from_secret(self.secret.as_bytes()),
            &validation,
        )
        .and_then(|data| {
            if injected_time
                .is_some_and(|now| data.claims.exp < now.timestamp().saturating_sub(leeway))
            {
                Err(jsonwebtoken::errors::ErrorKind::ExpiredSignature.into())
            } else {
                Ok(data)
            }
        })
        .or_else(|e| match e.kind() {
            // The decoder enforces the `exp` the token was signed with, which
            // a sliding token outgrows: the store holds the extended expiry,
            // and the signature says nothing about it. So a stale signature
            // is re-checked against the record before it is a rejection
            // (issue #354).
            jsonwebtoken::errors::ErrorKind::ExpiredSignature => self
                .decode_ignoring_expiry(jwt)
                .filter(|data| self.expiry_slid_past(&data.claims.sub))
                .ok_or_else(|| {
                    // The decoder knows only that the signature is stale; the
                    // record knows when it was issued and when it lapsed
                    // (issue #355).
                    TokenError::Expired(self.expiry_facts(jwt))
                }),
            // Minted under another issuer secret: a different repair from a
            // corrupt token, so it is told apart (issue #644).
            jsonwebtoken::errors::ErrorKind::InvalidSignature => Err(TokenError::SignatureInvalid),
            _ => Err(TokenError::Invalid(e.to_string())),
        })?;

        let stored = self
            .store
            .get(&token_data.claims.sub)
            .map_err(|e| TokenError::Storage(e.to_string()))?;
        if let Some(record) = stored {
            if record.revoked {
                return Err(TokenError::Revoked);
            }
            if record.client_kind != token_data.claims.client_kind
                || record.principal_id != token_data.claims.principal_id
            {
                return Err(TokenError::BindingMismatch);
            }
        } else if token_data.claims.client_kind.is_some()
            || token_data.claims.principal_id.is_some()
        {
            return Err(TokenError::MissingRecord);
        }

        Ok(token_data.claims)
    }

    /// Authenticate the Router token an incoming request presented.
    ///
    /// Normally identical to [`Self::validate_token`], plus a diagnostic
    /// record of why a rejection happened. While the explicit emergency mode
    /// is on, every non-empty token is admitted with synthetic claims instead
    /// (see [`crate::emergency_auth`]); the store is read, never written.
    pub fn authenticate_incoming(
        &self,
        token: &str,
        headers: &HeaderMap,
    ) -> Result<TokenClaims, TokenError> {
        let verdict = self.validate_token(token);
        let count = crate::auth_diagnostics::first_outcome_in_request();
        if self.emergency.is_active() {
            let bypassed = match &verdict {
                Ok(_) => "none",
                Err(error) => error.reason_code(),
            };
            let claims = crate::emergency_auth::synthetic_claims(token, headers);
            if !count {
                return Ok(claims);
            }
            self.emergency.record_bypass(bypassed);
            tracing::warn!(
                bypassed,
                fingerprint = %crate::emergency_auth::token_fingerprint(token),
                client = claims.client_kind.as_deref().unwrap_or("-"),
                "EMERGENCY AUTH BYPASS: admitted a Router token without normal validation"
            );
            return Ok(claims);
        }
        verdict.inspect_err(|error| {
            if count {
                self.diagnostics.record_error(error, Some(token));
            }
        })
    }

    /// Live state of the explicit emergency any-token mode.
    #[must_use]
    pub fn emergency(&self) -> &EmergencyAuth {
        &self.emergency
    }

    /// Protected authentication-failure diagnostics.
    #[must_use]
    pub fn diagnostics(&self) -> &AuthDiagnostics {
        &self.diagnostics
    }
}

use super::{ADMIN_SCOPE, TOKEN_PREFIX};

/// Errors related to token operations.
#[derive(Debug)]
pub enum TokenError {
    /// Token does not start with the expected prefix.
    InvalidPrefix,
    /// Token has expired.
    ///
    /// `Some` when the record could be read, so the message can say when the
    /// token was issued, how long it was good for, and how long ago it lapsed.
    /// A user whose day-long session died could not otherwise tell a ceiling
    /// from a clock skew from a revocation -- all three printed one sentence
    /// (issue #355).
    Expired(Option<ExpiryFacts>),
    /// Token has been revoked.
    Revoked,
    /// No stored token has the requested subject ID.
    NotFound(String),
    /// Token is otherwise invalid (malformed, unparsable claims, ...).
    Invalid(String),
    /// The JWT is well formed but its signature does not verify with this
    /// deployment's issuer secret: it was minted by another deployment, or
    /// the secret changed (issue #644).
    SignatureInvalid,
    /// No usable issuer secret is configured, so nothing can be verified.
    IssuerSecretUnset,
    /// A client-bound token whose durable record is absent from this store,
    /// typically after a rollback or a data-root switch (issue #644).
    MissingRecord,
    /// The signed client binding disagrees with the durable record.
    BindingMismatch,
    /// Token is valid but lacks the privilege scope the operation requires.
    InsufficientScope,
    /// Token has reached its per-token request budget (`max_requests`).
    ///
    /// `Some` carries used and limit, which the store was holding when it
    /// refused the request (issue #355).
    LimitExceeded(Option<BudgetFacts>),
    /// Token has reached its upstream-reported token budget (`max_tokens`).
    TokenLimitExceeded(Option<BudgetFacts>),
    /// Token has reached its configured one-minute request rate.
    RateLimitExceeded,
    /// Storage backend failure.
    Storage(String),
}

/// When a token was issued, when it lapsed, and how long ago that was.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ExpiryFacts {
    /// When the token was issued.
    pub issued_at: i64,
    /// When it expired.
    pub expires_at: i64,
    /// How long ago it expired, at the moment of the rejection.
    pub ago_seconds: i64,
}

/// How much of a bound has been spent.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BudgetFacts {
    /// The amount already consumed.
    pub used: u64,
    /// The bound it was measured against.
    pub limit: u64,
}

/// Render a unix timestamp for a person reading an error message.
fn render_time(seconds: i64) -> String {
    chrono::DateTime::from_timestamp(seconds, 0)
        .map_or_else(|| seconds.to_string(), |time| time.to_rfc3339())
}

/// Render a span of seconds as the largest unit that stays readable.
///
/// "expired 3d ago" answers the question a user has; a unix timestamp does not.
fn render_duration(seconds: i64) -> String {
    let seconds = seconds.abs();
    match seconds {
        0..=90 => format!("{seconds}s"),
        91..=5399 => format!("{}m", (seconds + 30) / 60),
        5400..=172_799 => format!("{}h", (seconds + 1800) / 3600),
        _ => format!("{}d", (seconds + 43200) / 86400),
    }
}

impl std::fmt::Display for TokenError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidPrefix => {
                write!(
                    f,
                    "Token must start with '{TOKEN_PREFIX}' or '{}' prefix",
                    crate::token::CODEX_TOKEN_PREFIX
                )
            }
            Self::Expired(None) => write!(f, "Token has expired"),
            Self::Expired(Some(facts)) => write!(
                f,
                "Token expired at {} ({} ago)",
                render_time(facts.expires_at),
                render_duration(facts.ago_seconds)
            ),
            Self::Revoked => write!(f, "Token has been revoked"),
            Self::NotFound(id) => write!(f, "Token not found: {id}"),
            Self::Invalid(msg) => write!(f, "Invalid token: {msg}"),
            Self::SignatureInvalid => write!(
                f,
                "Invalid token: signature does not verify with this deployment's issuer secret"
            ),
            Self::IssuerSecretUnset => {
                write!(f, "Invalid token: {}", crate::token_secret::refusal())
            }
            Self::MissingRecord => write!(
                f,
                "Invalid token: bound client token has no durable token record"
            ),
            Self::BindingMismatch => write!(
                f,
                "Invalid token: signed client binding does not match the durable token record"
            ),
            Self::InsufficientScope => {
                write!(f, "Token does not carry the '{ADMIN_SCOPE}' scope")
            }
            Self::LimitExceeded(None) => write!(f, "Token has reached its request limit"),
            Self::LimitExceeded(Some(facts)) => write!(
                f,
                "Token has reached its request limit: {} of {} requests used",
                facts.used, facts.limit
            ),
            Self::TokenLimitExceeded(None) => write!(f, "Token has reached its token limit"),
            Self::TokenLimitExceeded(Some(facts)) => write!(
                f,
                "Token has reached its token limit: {} of {} tokens used",
                facts.used, facts.limit
            ),
            Self::RateLimitExceeded => write!(f, "Token has reached its per-minute rate limit"),
            Self::Storage(msg) => write!(f, "Token storage error: {msg}"),
        }
    }
}

impl TokenError {
    /// Stable message safe to return across the unauthenticated client boundary.
    ///
    /// Decoder and storage details remain available through [`std::fmt::Display`]
    /// for server-side logs, but must not disclose parser internals to callers.
    #[must_use]
    pub fn client_message(&self) -> std::borrow::Cow<'static, str> {
        use std::borrow::Cow;
        match self {
            // Every verification failure reads the same to the caller; the
            // distinction is served on the protected diagnostics endpoint.
            Self::InvalidPrefix
            | Self::Invalid(_)
            | Self::SignatureInvalid
            | Self::IssuerSecretUnset
            | Self::MissingRecord
            | Self::BindingMismatch => Cow::Borrowed("invalid token"),
            // Names the router and the flag, because the client renders its
            // own advice otherwise: a Claude Code session whose per-run token
            // expired mid-work was told `Please run /login`, which points at
            // the Anthropic subscription -- a different credential entirely,
            // and re-authenticating it changes nothing (issue #341).
            Self::Expired(None) => Cow::Borrowed(
                "Token has expired: this is the router's own token, not the model provider's. \
                 A per-run token from `router with` lives for --run-ttl-hours; re-running the \
                 command mints a new one.",
            ),
            Self::Expired(Some(facts)) => Cow::Owned(format!(
                "Token has expired: this is the router's own token, not the model provider's. \
                 Issued {issued}, good for {lifetime}, expired {expired} ({ago} ago). \
                 A per-run token from `router with` lives for --run-ttl-hours; re-running the \
                 command mints a new one.",
                issued = render_time(facts.issued_at),
                lifetime = render_duration(facts.expires_at - facts.issued_at),
                expired = render_time(facts.expires_at),
                ago = render_duration(facts.ago_seconds),
            )),
            Self::Revoked => Cow::Borrowed("Token has been revoked"),
            Self::NotFound(_) => Cow::Borrowed("token not found"),
            Self::InsufficientScope => Cow::Borrowed("insufficient token scope"),
            Self::LimitExceeded(None) => Cow::Borrowed("Token has reached its request limit"),
            Self::LimitExceeded(Some(facts)) => Cow::Owned(format!(
                "Token has reached its request limit: {} of {} requests used. Issue a token \
                 with a larger --max-requests, or use a new one.",
                facts.used, facts.limit
            )),
            Self::TokenLimitExceeded(None) => Cow::Borrowed("Token has reached its token limit"),
            Self::TokenLimitExceeded(Some(facts)) => Cow::Owned(format!(
                "Token has reached its token limit: {} of {} tokens used. Issue a token with a \
                 larger --max-tokens, or use a new one.",
                facts.used, facts.limit
            )),
            Self::RateLimitExceeded => Cow::Borrowed("Token has reached its per-minute rate limit"),
            Self::Storage(_) => Cow::Borrowed("token validation failed"),
        }
    }
}

impl std::error::Error for TokenError {}

//! Admin HTTP endpoints for managing router-issued tokens.
//!
//! These endpoints let an operator mint, list, and revoke the `la_sk_...`
//! tokens that downstream tasks present to the proxy. When `admin_key` is
//! configured they require it as a Bearer credential; the proxy's shared
//! authorization helper enforces that. They are intentionally kept in their
//! own module so the core
//! request-forwarding logic in [`crate::proxy`] stays focused and under the
//! repository's per-file line budget.

// These handlers are `async fn` purely to match axum's handler signature;
// none of them currently `.await`. Mirrors the same allow in `crate::proxy`.
#![allow(clippy::unused_async)]

use axum::extract::State;
use axum::http::{HeaderMap, StatusCode};
use axum::response::IntoResponse;

use crate::model_contract::ModelAccessPolicy;
use crate::proxy::{AppState, error_response, extract_admin_bearer, is_admin_authorised};
use crate::token::{ADMIN_SCOPE, IssueRequest, TokenError};

/// Token issuance endpoint.
///
/// Issues a new custom token. Expects a JSON body such as
/// `{"ttl_hours": 24, "label": "my-token", "max_requests": 100}`.
///
/// When `admin_key` is configured the caller MUST present it as a Bearer
/// token in `Authorization`; otherwise the endpoint is open (matching the
/// original behaviour, kept for backwards compatibility).
pub async fn issue_token(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(req): axum::Json<IssueTokenRequest>,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return error_response(
            StatusCode::UNAUTHORIZED,
            "authentication_error",
            "missing or invalid admin Bearer key",
        );
    }

    let ttl = req.ttl_hours.unwrap_or(24);
    let label = req.label.unwrap_or_default();
    let scope = req.scope.unwrap_or_default();

    let request = IssueRequest {
        ttl_hours: ttl,
        label: &label,
        account: req.account.as_deref(),
        max_requests: req.max_requests,
        max_tokens: req.max_tokens,
        rate_limit_per_minute: req.rate_limit_per_minute,
        scope: &scope,
        github_repos: req.github_repos.clone().unwrap_or_default(),
        sliding_window_seconds: req
            .sliding_expiry
            .unwrap_or(false)
            .then(|| ttl.saturating_mul(3_600)),
        client_kind: None,
        principal_id: None,
    };
    // One shared rule set across HTTP, CLI and chat (issue #194), so the same
    // request cannot be accepted on one surface and refused on another.
    if let Err(message) = request.validate() {
        return error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &message);
    }

    let model_policy = ModelAccessPolicy {
        allowed_models: req.allowed_models.clone().unwrap_or_default(),
        ..ModelAccessPolicy::default()
    };
    if let Err(message) = model_policy.validate() {
        return error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &message);
    }

    match state
        .token_manager
        .issue_with_model_policy(&request, &model_policy)
    {
        Ok(token) => {
            state.metrics.record_token_issued();
            (
                StatusCode::OK,
                axum::Json(serde_json::json!({
                    "token": token,
                    "ttl_hours": ttl,
                    "label": label,
                    "account": req.account,
                    "max_requests": req.max_requests,
                    "max_tokens": req.max_tokens,
                    "rate_limit_per_minute": req.rate_limit_per_minute,
                    "scope": scope,
                })),
            )
                .into_response()
        }
        Err(e) => error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "api_error",
            &format!("Failed to issue token: {e}"),
        ),
    }
}

/// Mint a short-lived token bound to one managed client and subscriber.
///
/// Kept separate from [`issue_token`] so ordinary/manual issuance never gains
/// consumer-subscription authority merely by choosing a suggestive label.
pub async fn issue_client_token(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(req): axum::Json<IssueClientTokenRequest>,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return error_response(
            StatusCode::UNAUTHORIZED,
            "authentication_error",
            "missing or invalid admin Bearer key",
        );
    }
    let Some(client) = crate::clients::ClientKind::from_str_opt(&req.client_kind) else {
        return error_response(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "unknown Router client kind",
        );
    };
    if matches!(client, crate::clients::ClientKind::Cursor) {
        return error_response(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "Cursor has no native Router adapter and cannot receive a bound token",
        );
    }
    let ttl = req.ttl_hours.unwrap_or(24);
    let label = req
        .label
        .unwrap_or_else(|| format!("client-{}", client.canonical_name()));
    let principal = crate::credential_recovery_store::PRIMARY_ACCOUNT;
    let request = IssueRequest {
        ttl_hours: ttl,
        label: &label,
        account: Some(principal),
        max_requests: req.max_requests,
        max_tokens: None,
        rate_limit_per_minute: None,
        scope: "",
        github_repos: Vec::new(),
        sliding_window_seconds: req
            .sliding_expiry
            .unwrap_or(false)
            .then(|| ttl.saturating_mul(3_600)),
        client_kind: Some(client.canonical_name()),
        principal_id: Some(principal),
    };
    if let Err(message) = request.validate() {
        return error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &message);
    }
    let model_policy = ModelAccessPolicy {
        allowed_models: req.allowed_models.clone(),
        allow_substitution: req.allow_model_substitution,
        substitution_source: req.model_substitution_source.clone().or_else(|| {
            req.allow_model_substitution
                .then(|| "client token issuance API".to_string())
        }),
    };
    if let Err(message) = model_policy.validate() {
        return error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &message);
    }
    if req.run_lease && !req.ephemeral {
        return error_response(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "run_lease requires an ephemeral wrapper credential",
        );
    }
    match if req.run_lease {
        state
            .token_manager
            .issue_ephemeral_with_model_policy_and_run_lease(&request, &model_policy)
    } else if req.ephemeral {
        state
            .token_manager
            .issue_ephemeral_with_model_policy(&request, &model_policy)
    } else {
        state
            .token_manager
            .issue_with_model_policy(&request, &model_policy)
    } {
        Ok(token) => {
            state.metrics.record_token_issued();
            (
                StatusCode::OK,
                axum::Json(serde_json::json!({
                    "token": token,
                    "ttl_hours": ttl,
                    "label": label,
                    "client_kind": client.canonical_name(),
                    "principal_id": principal,
                    "model_policy": model_policy,
                })),
            )
                .into_response()
        }
        Err(error) => error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "api_error",
            &format!("Failed to issue bound client token: {error}"),
        ),
    }
}

/// Renew the authenticated wrapper's own liveness lease.
pub async fn renew_run_lease(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> impl IntoResponse {
    let claims = match crate::proxy::authenticate_client_error(&state, &headers) {
        Ok(claims) => claims,
        Err(error) => return error.render(crate::api_error::ApiDialect::Anthropic),
    };
    match state.token_manager.renew_run_lease(&claims.sub) {
        Ok(expires_at) => (
            StatusCode::OK,
            axum::Json(serde_json::json!({ "run_lease_expires_at": expires_at })),
        )
            .into_response(),
        Err(TokenError::Storage(_)) => error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "api_error",
            "could not persist the run lease",
        ),
        Err(_) => {
            state
                .token_manager
                .diagnostics()
                .record(crate::auth_diagnostics::reason::RUN_LEASE_UNRENEWABLE, None);
            error_response(
                StatusCode::CONFLICT,
                "invalid_request_error",
                "this credential has no renewable live run lease",
            )
        }
    }
}

/// List all known tokens (admin endpoint).
pub async fn list_tokens(State(state): State<AppState>, headers: HeaderMap) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return error_response(
            StatusCode::UNAUTHORIZED,
            "authentication_error",
            "admin Bearer key required",
        );
    }
    match state.token_manager.list_tokens() {
        Ok(records) => (
            StatusCode::OK,
            axum::Json(serde_json::json!({"data": records})),
        )
            .into_response(),
        Err(e) => error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "api_error",
            &format!("{e}"),
        ),
    }
}

/// Revoke a token by id (admin endpoint).
pub async fn revoke_token(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(req): axum::Json<RevokeTokenRequest>,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return error_response(
            StatusCode::UNAUTHORIZED,
            "authentication_error",
            "admin Bearer key required",
        );
    }
    match state.token_manager.revoke_token(&req.id) {
        Ok(()) => {
            state.metrics.record_token_revoked();
            (
                StatusCode::OK,
                axum::Json(serde_json::json!({"revoked": req.id})),
            )
                .into_response()
        }
        Err(e @ TokenError::NotFound(_)) => {
            error_response(StatusCode::NOT_FOUND, "not_found", &format!("{e}"))
        }
        Err(e) => error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "api_error",
            &format!("{e}"),
        ),
    }
}

/// Rotate the admin token used to make this call.
///
/// Issues a replacement admin token and revokes the caller's own `sub` in one
/// step — "new token, old one expired". The caller must authenticate with an
/// admin-scoped JWT: the flat `TOKEN_ADMIN_KEY` has no subject to revoke, so
/// it cannot rotate itself and gets HTTP 400 instead.
pub async fn rotate_admin_token(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(req): axum::Json<RotateTokenRequest>,
) -> impl IntoResponse {
    let Some(bearer) = extract_admin_bearer(&headers) else {
        return error_response(
            StatusCode::UNAUTHORIZED,
            "authentication_error",
            "admin Bearer token required",
        );
    };
    let Ok(claims) = state.token_manager.validate_admin_token(bearer) else {
        return error_response(
            StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "rotation requires an admin-scoped token; the flat admin key has no subject to revoke",
        );
    };

    let ttl = req.ttl_hours.unwrap_or(24);
    let label = req.label.unwrap_or_else(|| claims.label.clone());
    match state
        .token_manager
        .rotate_admin_token(&claims.sub, ttl, &label)
    {
        Ok(token) => {
            state.metrics.record_token_issued();
            state.metrics.record_token_revoked();
            (
                StatusCode::OK,
                axum::Json(serde_json::json!({
                    "token": token,
                    "ttl_hours": ttl,
                    "label": label,
                    "scope": ADMIN_SCOPE,
                    "revoked": claims.sub,
                })),
            )
                .into_response()
        }
        Err(e) => error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "api_error",
            &format!("Failed to rotate admin token: {e}"),
        ),
    }
}

/// `POST /api/management/tokens/rotate-client` — reissue one client token by id.
///
/// Distinct from [`rotate_admin_token`], which rotates the caller's own admin
/// credential. Every constraint is preserved unless explicitly overridden, and
/// the previous value is revoked as part of the same operation (issue #194).
pub async fn rotate_client_token(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(req): axum::Json<RotateClientTokenRequest>,
) -> impl IntoResponse {
    if !is_admin_authorised(&state, &headers) {
        return error_response(
            StatusCode::UNAUTHORIZED,
            "authentication_error",
            "missing or invalid admin Bearer key",
        );
    }

    // Rotating an admin credential through the client route would bypass the
    // proof-of-possession that `rotate_admin_token` requires.
    match state.token_manager.store().get(&req.id) {
        Ok(Some(record)) if record.scope == ADMIN_SCOPE => {
            return error_response(
                StatusCode::BAD_REQUEST,
                "invalid_request_error",
                "use /api/management/tokens/rotate to rotate an admin credential",
            );
        }
        Ok(Some(_)) => {}
        Ok(None) => {
            return error_response(
                StatusCode::NOT_FOUND,
                "invalid_request_error",
                &format!("unknown token id {}", req.id),
            );
        }
        Err(error) => {
            return error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "api_error",
                &format!("failed to read token: {error}"),
            );
        }
    }

    let overrides = crate::token::RotateOverrides {
        label: req.label.as_deref(),
        ttl_hours: req.ttl_hours,
        max_requests: req.max_requests,
        max_tokens: req.max_tokens,
        rate_limit_per_minute: req.rate_limit_per_minute,
        account: req.account.as_deref(),
    };
    match state.token_manager.rotate_token_with(&req.id, &overrides) {
        Ok(token) => {
            state.metrics.record_token_issued();
            state.metrics.record_token_revoked();
            (
                StatusCode::OK,
                axum::Json(serde_json::json!({
                    "token": token,
                    "revoked": req.id,
                })),
            )
                .into_response()
        }
        Err(crate::token::TokenError::Invalid(message)) => {
            error_response(StatusCode::BAD_REQUEST, "invalid_request_error", &message)
        }
        Err(e) => error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "api_error",
            &format!("Failed to rotate token: {e}"),
        ),
    }
}

