//! HTTP mapping for token admission failures.

use axum::http::StatusCode;
use axum::response::Response;

pub fn budget_error_response(error: &crate::token::TokenError) -> Response {
    match error {
        crate::token::TokenError::LimitExceeded(_)
        | crate::token::TokenError::TokenLimitExceeded(_)
        | crate::token::TokenError::RateLimitExceeded => crate::api_error::error_response(
            StatusCode::TOO_MANY_REQUESTS,
            "rate_limit_error",
            // The client-facing wording, which carries the counts and says
            // what to do about them; `Display` is for the server's own log
            // (issue #355).
            &error.client_message(),
        ),
        crate::token::TokenError::Storage(_) => crate::api_error::error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "storage_error",
            &error.to_string(),
        ),
        _ => crate::api_error::error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "api_error",
            &error.to_string(),
        ),
    }
}

//! `router tokens import`: bring durable token records back after a rollback,
//! a data-root switch or a restore (issue #644).
//!
//! A rollback from 1.14.3 to an existing 1.11.2 deployment served the older
//! data root, which had never seen the active Claude run token. The token's
//! signature was fine; its durable record was simply absent, so the running
//! session got `401 invalid token`. The repair was to copy exactly that record
//! across — no rotation, no secret change, no other credential touched — and
//! until now it had to be done by hand.
//!
//! The default is additive: a record the target lacks is copied with every
//! field intact (binding, scope, revocation, expiry, lease, budgets, usage,
//! reservations, rate window, model policy), and a record the target already
//! holds is never touched. Where the two copies disagree the difference is
//! reported, field by field, and left for the operator.
//!
//! `--replace` is the explicit, destructive alternative for those conflicts.
//! Even then a revoked record stays revoked and recorded usage never goes
//! down ([`merge_safer_record`]), and the target's records are exported to a
//! private backup file before anything is written.
//!
//! Records hold no token values — only metadata keyed by the token id — so
//! nothing printed here can authenticate anyone.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use serde::Serialize;

use crate::config::StoragePolicy;
use crate::storage::{TokenRecord, TokenStore, build_token_store_read_only, merge_safer_record};

/// Directory, under the target data root, that `--replace` backups go to.
pub const BACKUP_DIRECTORY: &str = "token-import-backups";

/// What to do with a record both sides hold but that differs.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ImportMode {
    /// Copy only missing records; report conflicts and leave them alone.
    MergeMissing,
    /// Also overwrite conflicting records, never reviving a revoked one or
    /// lowering recorded usage.
    Replace,
}

impl ImportMode {
    const fn name(self) -> &'static str {
        match self {
            Self::MergeMissing => "merge-missing",
            Self::Replace => "replace",
        }
    }
}

/// One record both sides hold with different contents.
#[derive(Clone, Debug, Serialize, PartialEq, Eq, schemars::JsonSchema)]
pub struct Conflict {
    pub id: String,
    /// The record fields whose values differ.
    pub fields: Vec<String>,
}

/// The outcome of one import, printed as the command's result.
#[derive(Clone, Debug, Default, Serialize, PartialEq, Eq, schemars::JsonSchema)]
pub struct ImportReport {
    pub mode: &'static str,
    pub dry_run: bool,
    pub source_records: usize,
    pub target_records_before: usize,
    /// Records the target lacked and now holds (or would, in a dry run).
    pub added: Vec<String>,
    /// Records already identical on both sides.
    pub unchanged: Vec<String>,
    /// Records that differ and were left as they are.
    pub conflicts: Vec<Conflict>,
    /// Records overwritten by `--replace`.
    pub replaced: Vec<Conflict>,
    /// Replaced records that stayed revoked because the target had revoked
    /// them: an import never revives a credential.
    pub kept_revoked: Vec<String>,
    /// `--id` values the source does not hold.
    pub missing_from_source: Vec<String>,
    /// Export of the target's records taken before `--replace` wrote.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub backup: Option<PathBuf>,
}

impl ImportReport {
    /// Whether the import changes (or, in a dry run, would change) the target.
    #[must_use]
    pub const fn writes(&self) -> bool {
        !self.added.is_empty() || !self.replaced.is_empty()
    }
}

/// Read every record a source holds, without creating or changing anything.
///
/// Accepted sources:
///
/// * a data directory holding `tokens.lino` and/or `tokens.bin`;
/// * a deployment root whose `data/` directory holds them;
/// * a `router deploy` checkpoint directory (`tokens.json`, `tokens.lino`);
/// * a single `*.lino`, `*.bin` or `*.json` token file under any name.
///
/// # Errors
///
/// A missing path, an unrecognised file, or a store that cannot be decoded.
pub fn read_source(path: &Path) -> Result<Vec<TokenRecord>, String> {
    let metadata =
        fs::metadata(path).map_err(|error| format!("cannot read {}: {error}", path.display()))?;
    if metadata.is_file() {
        return read_file(path);
    }
    let data = path.join("data");
    let directory = if !holds_tokens(path) && holds_tokens(&data) {
        data
    } else {
        path.to_path_buf()
    };
    if !holds_tokens(&directory) {
        return Err(format!(
            "{} holds no tokens.lino, tokens.bin or tokens.json",
            path.display()
        ));
    }
    let mut records = read_directory(&directory)?;
    let checkpoint = directory.join("tokens.json");
    if checkpoint.is_file() {
        merge_into(&mut records, read_json(&checkpoint)?);
    }
    Ok(records.into_values().collect())
}

fn holds_tokens(directory: &Path) -> bool {
    ["tokens.lino", "tokens.bin", "tokens.json"]
        .iter()
        .any(|name| directory.join(name).is_file())
}

fn read_directory(directory: &Path) -> Result<BTreeMap<String, TokenRecord>, String> {
    let store = build_token_store_read_only(StoragePolicy::Both, directory)
        .map_err(|error| format!("cannot decode tokens in {}: {error}", directory.display()))?;
    let records = store.list().map_err(|error| error.to_string())?;
    Ok(records
        .into_iter()
        .map(|record| (record.id.clone(), record))
        .collect())
}

fn read_json(path: &Path) -> Result<Vec<TokenRecord>, String> {
    let bytes =
        fs::read(path).map_err(|error| format!("cannot read {}: {error}", path.display()))?;
    serde_json::from_slice(&bytes)
        .map_err(|error| format!("{} is not a token export: {error}", path.display()))
}

/// A lone store file is decoded from a private copy under its canonical name,
/// so the ordinary read-only decoders apply whatever the file is called.
fn read_file(path: &Path) -> Result<Vec<TokenRecord>, String> {
    let extension = path
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or_default();
    let canonical = match extension {
        "json" => return read_json(path),
        "lino" => "tokens.lino",
        "bin" => "tokens.bin",
        _ => {
            return Err(format!(
                "{} is not a .lino, .bin or .json token file",
                path.display()
            ));
        }
    };
    let workspace = tempfile::tempdir().map_err(|error| error.to_string())?;
    fs::copy(path, workspace.path().join(canonical))
        .map_err(|error| format!("cannot read {}: {error}", path.display()))?;
    Ok(read_directory(workspace.path())?.into_values().collect())
}

/// Two copies of one record in one source (text and binary projections) are
/// reconciled the way the store itself reconciles them.
fn merge_into(records: &mut BTreeMap<String, TokenRecord>, more: Vec<TokenRecord>) {
    for record in more {
        records
            .entry(record.id.clone())
            .and_modify(|current| merge_safer_record(current, &record))
            .or_insert(record);
    }
}

/// The names of the fields in which two records differ.
fn differing_fields(left: &TokenRecord, right: &TokenRecord) -> Vec<String> {
    let as_map = |record: &TokenRecord| match serde_json::to_value(record) {
        Ok(serde_json::Value::Object(map)) => map,
        _ => serde_json::Map::new(),
    };
    let (left, right) = (as_map(left), as_map(right));
    let keys: BTreeSet<&String> = left.keys().chain(right.keys()).collect();
    keys.into_iter()
        .filter(|key| left.get(*key) != right.get(*key))
        .cloned()
        .collect()
}

/// Options for [`import`].
#[derive(Clone, Copy, Debug)]
pub struct ImportOptions<'a> {
    pub mode: ImportMode,
    pub dry_run: bool,
    /// Import only these ids; empty imports every source record.
    pub ids: &'a [String],
    /// Where `--replace` writes its backup of the target's records.
    pub backup_directory: Option<&'a Path>,
}

/// Plan the import against the target's current records and, unless this is
/// a dry run, apply it one record at a time.
///
/// Each write is one ordinary store `put`, taken under the store's own
/// cross-process lock, so a running router keeps serving and sees each record
/// as it lands. An interrupted import leaves every record either fully
/// imported or untouched; running it again finishes the rest, and a completed
/// import run again changes nothing.
///
/// # Errors
///
/// The target store cannot be read or written, or the backup cannot be taken.
pub fn import(
    target: &dyn TokenStore,
    source: Vec<TokenRecord>,
    options: ImportOptions<'_>,
) -> Result<ImportReport, String> {
    let current: BTreeMap<String, TokenRecord> = target
        .list()
        .map_err(|error| format!("cannot read the target token store: {error}"))?
        .into_iter()
        .map(|record| (record.id.clone(), record))
        .collect();
    let mut source: BTreeMap<String, TokenRecord> = source
        .into_iter()
        .map(|record| (record.id.clone(), record))
        .collect();
    let mut report = ImportReport {
        mode: options.mode.name(),
        dry_run: options.dry_run,
        source_records: source.len(),
        target_records_before: current.len(),
        ..ImportReport::default()
    };
    if !options.ids.is_empty() {
        let wanted: BTreeSet<&String> = options.ids.iter().collect();
        report.missing_from_source = wanted
            .iter()
            .filter(|id| !source.contains_key(**id))
            .map(|id| (*id).clone())
            .collect();
        source.retain(|id, _| wanted.contains(id));
    }

    let mut writes = Vec::new();
    for (id, incoming) in source {
        let Some(existing) = current.get(&id) else {
            report.added.push(id);
            writes.push(incoming);
            continue;
        };
        if *existing == incoming {
            report.unchanged.push(id);
            continue;
        }
        let fields = differing_fields(existing, &incoming);
        match options.mode {
            ImportMode::MergeMissing => report.conflicts.push(Conflict { id, fields }),
            ImportMode::Replace => {
                let mut replacement = incoming;
                merge_safer_record(&mut replacement, existing);
                if existing.revoked {
                    report.kept_revoked.push(id.clone());
                }
                if replacement == *existing {
                    report.unchanged.push(id);
                    continue;
                }
                report.replaced.push(Conflict { id, fields });
                writes.push(replacement);
            }
        }
    }

    if options.dry_run || writes.is_empty() {
        return Ok(report);
    }
    if !report.replaced.is_empty() {
        let directory = options
            .backup_directory
            .ok_or("--replace needs a backup location for the target's records")?;
        report.backup = Some(write_backup(directory, &current)?);
    }
    for record in writes {
        let id = record.id.clone();
        target.put(record).map_err(|error| {
            format!(
                "importing {id} failed: {error}; records before it were imported, rerun to finish"
            )
        })?;
    }
    Ok(report)
}

fn write_backup(
    directory: &Path,
    records: &BTreeMap<String, TokenRecord>,
) -> Result<PathBuf, String> {
    let path = directory.join(format!(
        "tokens-{}-{}.json",
        crate::operation_context::now().format("%Y%m%dT%H%M%SZ"),
        &uuid::Uuid::new_v4().simple().to_string()[..8]
    ));
    let records: Vec<&TokenRecord> = records.values().collect();
    let bytes = serde_json::to_vec_pretty(&records).map_err(|error| error.to_string())?;
    fs::create_dir_all(directory)
        .and_then(|()| crate::durable_file::atomic_write_owner_only(&path, &bytes))
        .map_err(|error| {
            format!("cannot back up the target's records; nothing imported: {error}")
        })?;
    Ok(path)
}

/// Human-readable summary of a report.
#[must_use]
pub fn render(report: &ImportReport) -> String {
    use std::fmt::Write as _;
    let verb = if report.dry_run { "would add" } else { "added" };
    let mut text = format!(
        "{verb} {} record(s), {} unchanged, {} conflict(s) left alone, {} replaced ({} source, {} target before; mode {})\n",
        report.added.len(),
        report.unchanged.len(),
        report.conflicts.len(),
        report.replaced.len(),
        report.source_records,
        report.target_records_before,
        report.mode,
    );
    for id in &report.added {
        let _ = writeln!(text, "  + {id}");
    }
    for conflict in &report.conflicts {
        let _ = writeln!(
            text,
            "  ! {} differs in {}; pass --replace to overwrite",
            conflict.id,
            conflict.fields.join(", ")
        );
    }
    for conflict in &report.replaced {
        let _ = writeln!(text, "  ~ {} ({})", conflict.id, conflict.fields.join(", "));
    }
    for id in &report.kept_revoked {
        let _ = writeln!(text, "  - {id} stays revoked");
    }
    for id in &report.missing_from_source {
        let _ = writeln!(text, "  ? {id} is not in the source");
    }
    if let Some(backup) = &report.backup {
        let _ = writeln!(text, "previous records saved to {}", backup.display());
    }
    text
}

/// Flags of `router tokens import`.
#[derive(Clone, Copy, Debug)]
pub struct ImportCommand<'a> {
    pub from: &'a Path,
    pub ids: &'a [String],
    pub replace: bool,
    pub dry_run: bool,
    pub json: bool,
}

/// Run `router tokens import` against the local store in `data_dir`.
///
/// Exit status: 0 when every requested record is present afterwards, 1 on an
/// error, 2 when a requested `--id` is not in the source or conflicts were
/// left alone, so a script notices an import that did not fully happen.
#[must_use]
pub fn run_cli(
    target: &dyn TokenStore,
    data_dir: &Path,
    command: &ImportCommand<'_>,
) -> std::process::ExitCode {
    use std::process::ExitCode;
    let outcome = read_source(command.from).and_then(|source| {
        import(
            target,
            source,
            ImportOptions {
                mode: if command.replace {
                    ImportMode::Replace
                } else {
                    ImportMode::MergeMissing
                },
                dry_run: command.dry_run,
                ids: command.ids,
                backup_directory: Some(&data_dir.join(BACKUP_DIRECTORY)),
            },
        )
    });
    let report = match outcome {
        Ok(report) => report,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    };
    if command.json {
        println!(
            "{}",
            serde_json::to_string_pretty(&report).unwrap_or_default()
        );
    } else {
        print!("{}", render(&report));
    }
    if report.missing_from_source.is_empty() && report.conflicts.is_empty() {
        ExitCode::SUCCESS
    } else {
        ExitCode::from(2)
    }
}

/// Why `tokens import` refuses with another router selected.
#[must_use]
pub fn refusal(server: &crate::managed_server::ResolvedServer) -> String {
    format!(
        "`tokens import` writes the token store of the machine it runs on, and {} is selected. \
         Run it on that deployment — `docker exec <container> router tokens import ...` for a \
         containerised one — or pass --local to import into this machine's store.",
        server.base_url
    )
}

//! How `router tokens list` renders, for local and remote alike.
//!
//! Split out so the two paths cannot drift: an operator reading a table has no
//! way to tell which machine answered, and a column that means one thing
//! locally and another remotely would be worse than no column (issue #293).
//!
//! Driven from JSON rather than [`crate::storage::TokenRecord`] because the
//! remote path receives exactly that — the endpoint serialises the same record,
//! so parsing it back into the struct only to format it would add a failure
//! mode without adding information.

use serde_json::Value;

/// Column headers, in the order [`print_table`] writes them.
const HEADERS: [&crate::translation_core::Str; 9] = [
    "id",
    "issued_at",
    "expires_at",
    "revoked",
    "requests",
    "tokens",
    "reserved",
    "rpm",
    "scope",
];

/// Print the token table, one row per record.
pub fn print_table(records: &[crate::translation_core::Json]) {
    println!(
        "{:<36}  {:<10}  {:<10}  {:<8}  {:<13}  {:<15}  {:<9}  {:<8}  {:<6}  label",
        HEADERS[0],
        HEADERS[1],
        HEADERS[2],
        HEADERS[3],
        HEADERS[4],
        HEADERS[5],
        HEADERS[6],
        HEADERS[7],
        HEADERS[8]
    );
    for record in records {
        println!("{}", row(record));
    }
}

/// One table row, as the local path formats it.
#[must_use]
pub fn row(record: &crate::translation_core::Json) -> crate::translation_core::Text {
    let text = |key: &str| {
        record
            .get(key)
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string()
    };
    let number = |key: &str| record.get(key).and_then(Value::as_u64);
    let used_over_max = |used: &str, max: &str| {
        let used = number(used).unwrap_or(0);
        number(max).map_or_else(|| format!("{used}/-"), |max| format!("{used}/{max}"))
    };

    let scope = record
        .get("scope")
        .and_then(Value::as_str)
        .filter(|scope| !scope.is_empty())
        .unwrap_or("client");
    let rpm = number("rate_limit_per_minute").map_or_else(|| crate::translation_core::format!("{}", "-"), |v| v.to_string());
    let revoked = record
        .get("revoked")
        .and_then(Value::as_bool)
        .unwrap_or(false);

    format!(
        "{:<36}  {:<10}  {:<10}  {:<8}  {:<13}  {:<15}  {:<9}  {:<8}  {scope:<6}  {}",
        text("id"),
        number("issued_at").unwrap_or(0),
        number("expires_at").unwrap_or(0),
        revoked,
        used_over_max("used_requests", "max_requests"),
        used_over_max("used_tokens", "max_tokens"),
        number("reserved_tokens").unwrap_or(0),
        rpm,
        text("label"),
    )
}

#[cfg(test)]
#[path = "token_report_tests.rs"]
mod tests;

//! Pre-dispatch spend reservations for per-token `max_tokens` budgets.
//!
//! A spend cap cannot be enforced from recorded usage alone. Usage is only known
//! once a response completes, so checking `used_tokens < max_tokens` at admission
//! lets a single large answer push the persisted total arbitrarily far past the
//! cap (issue #195).
//!
//! The router therefore reserves budget *before* dispatching. Every protocol
//! declares, or is given, a maximum output size; that figure plus an estimate of
//! the prompt is reserved against the cap at admission and released when the real
//! usage arrives. Because the reservation happens inside the same locked
//! read-modify-write that increments the request counters, concurrent requests
//! cannot collectively overshoot either.
//!
//! # Enforcement contract
//!
//! * A request is admitted only when `used + reserved + estimate <= max_tokens`.
//! * A request whose declared output budget cannot fit is rejected up front with
//!   `token_budget_exceeded` rather than being truncated mid-answer.
//! * Actual usage is always recorded in full, even when it exceeds the estimate,
//!   so the persisted total never understates real spend.
//! * The bound is therefore exact against *declared* budgets. Providers that
//!   report more tokens than the caller's declared maximum (hidden reasoning
//!   tokens, for example) can still land above the cap by that provider-side
//!   excess; the overshoot is bounded by one request's unreported surplus rather
//!   than being unbounded, and both figures are visible to administrators.

use serde_json::Value;

/// Characters per token used by the router's local estimator.
///
/// Matches [`crate::output_limit`] and
/// the bridge request-shape estimator so one request is not
/// measured two different ways.
const CHARS_PER_TOKEN: u64 = 4;

/// Output budget assumed when a request declares none.
///
/// Protocol adapters already default to this figure when shaping upstream
/// requests, so reserving it keeps the reservation aligned with what the
/// upstream is actually allowed to return.
pub const DEFAULT_MAX_OUTPUT_TOKENS: u64 = 4096;

/// The spend a request could report, used to reserve budget before dispatch.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct RequestBudget {
    /// Estimated prompt tokens.
    pub input: u64,
    /// Declared (or defaulted) maximum output tokens.
    pub output: u64,
}

impl RequestBudget {
    /// Total tokens to reserve for this request.
    #[must_use]
    pub const fn total(self) -> u64 {
        self.input.saturating_add(self.output)
    }
}

/// Estimate the spend a request body could report.
///
/// Reads whichever output-cap field the request's protocol uses:
/// `max_output_tokens` (Responses), `max_completion_tokens`/`max_tokens` (Chat
/// Completions and Anthropic Messages), and
/// `generationConfig.maxOutputTokens` (Gemini). When none is present the
/// protocol default applies, matching what the adapters forward upstream.
#[must_use]
pub fn estimate(body: &crate::translation_core::Json) -> RequestBudget {
    RequestBudget {
        input: estimate_input_tokens(body),
        output: declared_output_tokens(body).unwrap_or(DEFAULT_MAX_OUTPUT_TOKENS),
    }
}

/// The caller's declared output cap, in whichever field its protocol uses.
#[must_use]
pub fn declared_output_tokens(body: &crate::translation_core::Json) -> crate::translation_core::Maybe<u64> {
    for field in ["max_output_tokens", "max_completion_tokens", "max_tokens"] {
        if let Some(value) = body.get(field).and_then(crate::translation_core::Json::as_u64) {
            return Some(value);
        }
    }
    body.get("generationConfig")
        .and_then(|config| config.get("maxOutputTokens"))
        .and_then(crate::translation_core::Json::as_u64)
}

/// Estimate prompt tokens from the request's text payload.
///
/// The router has no upstream tokenizer, so it measures the serialized textual
/// content with the same ~4-characters-per-token heuristic used elsewhere. This
/// only has to be good enough to keep a reservation in the right order of
/// magnitude; the real figure replaces it at settlement.
#[must_use]
pub fn estimate_input_tokens(body: &crate::translation_core::Json) -> u64 {
    let mut characters = 0u64;
    for field in ["messages", "input", "contents", "system", "prompt", "tools"] {
        if let Some(value) = body.get(field) {
            characters = characters.saturating_add(text_length(value));
        }
    }
    characters.div_ceil(CHARS_PER_TOKEN)
}

/// Total length of every string in a JSON value.
fn text_length(value: &crate::translation_core::Json) -> u64 {
    match value {
        crate::translation_core::Json::String(text) => text.len() as u64,
        crate::translation_core::Json::Array(items) => items
            .iter()
            .map(text_length)
            .fold(0u64, u64::saturating_add),
        crate::translation_core::Json::Object(fields) => fields
            .values()
            .map(text_length)
            .fold(0u64, u64::saturating_add),
        _ => 0,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn reads_the_responses_output_cap() {
        let body = json!({"max_output_tokens": 1500});
        assert_eq!(declared_output_tokens(&body), Some(1500));
        assert_eq!(estimate(&body).output, 1500);
    }

    #[test]
    fn reads_the_chat_completions_output_caps() {
        assert_eq!(
            declared_output_tokens(&json!({"max_completion_tokens": 700})),
            Some(700)
        );
        assert_eq!(
            declared_output_tokens(&json!({"max_tokens": 800})),
            Some(800)
        );
    }

    #[test]
    fn reads_the_gemini_output_cap() {
        let body = json!({"generationConfig": {"maxOutputTokens": 256}});
        assert_eq!(declared_output_tokens(&body), Some(256));
    }

    #[test]
    fn falls_back_to_the_protocol_default_when_no_cap_is_declared() {
        let body = json!({"messages": []});
        assert_eq!(declared_output_tokens(&body), None);
        assert_eq!(estimate(&body).output, DEFAULT_MAX_OUTPUT_TOKENS);
    }

    #[test]
    fn estimates_prompt_tokens_from_message_text() {
        // 40 characters of content over the 4-characters-per-token heuristic.
        let body = json!({"messages": [{"role": "user", "content": "a".repeat(40)}]});
        // "user" (4) + 40 characters = 44 characters => 11 tokens.
        assert_eq!(estimate_input_tokens(&body), 11);
    }

    #[test]
    fn counts_gemini_contents_and_anthropic_system_prompts() {
        let gemini = json!({"contents": [{"parts": [{"text": "b".repeat(8)}]}]});
        assert!(estimate_input_tokens(&gemini) > 0);
        let anthropic = json!({"system": "c".repeat(16), "messages": []});
        assert!(estimate_input_tokens(&anthropic) >= 4);
    }

    #[test]
    fn total_combines_input_and_output() {
        let budget = RequestBudget {
            input: 10,
            output: 20,
        };
        assert_eq!(budget.total(), 30);
    }

    #[test]
    fn saturates_rather_than_overflowing_on_absurd_declared_budgets() {
        let budget = RequestBudget {
            input: u64::MAX,
            output: u64::MAX,
        };
        assert_eq!(budget.total(), u64::MAX);
    }

    #[test]
    fn ignores_non_textual_payload_fields() {
        assert_eq!(estimate_input_tokens(&json!({"temperature": 0.7})), 0);
    }
}

//! The stand-in used when a command will never sign anything.
//!
//! Several commands act on another deployment, or only read local files, and
//! so have no use for this machine's signing secret. Rather than thread an
//! `Option` through every construction site, they install a stand-in — and the
//! stand-in was an ordinary string, which meant a command that turned out to
//! run *locally* after all went on to sign real tokens and encrypt real vendor
//! API keys with a value published in the source (issue #300).
//!
//! Two things fix that. The value now begins with a NUL byte, which no
//! environment variable or command line can carry, so it cannot be supplied
//! deliberately or arrived at by accident. And every place that actually uses
//! the secret — signing, validating, encrypting — refuses it, so the sentinel
//! is inert rather than merely unlikely: reaching a signer with it produces
//! the ordinary `TOKEN_SECRET is required` error, before anything is written.

/// Marks a secret that exists only to satisfy a type, and must never be used.
///
/// The NUL prefix is what makes it unforgeable: `std::env::var` cannot return
/// a value containing one, and neither can argv.
const SENTINEL: &crate::translation_core::Str = "\u{0}link-assistant-router:no-token-secret:";

/// Values that were written into stores before the sentinel existed.
///
/// Kept so a record encrypted under one can be recognised and named, rather
/// than surfacing as an opaque decryption failure (issue #300).
pub const LEGACY_PLACEHOLDERS: [&crate::translation_core::Str; 3] = [
    "unused-by-remote-command",
    "unused-by-auth",
    "unused-by-this-client-command",
];

/// A stand-in secret for a command that will not sign, naming why.
#[must_use]
pub fn placeholder(reason: &crate::translation_core::Str) -> String {
    format!("{SENTINEL}{reason}")
}

/// Whether this secret is a stand-in rather than a real signing key.
#[must_use]
pub fn is_placeholder(secret: &crate::translation_core::Str) -> bool {
    secret.starts_with(SENTINEL) || LEGACY_PLACEHOLDERS.contains(&secret)
}

/// The message a real signing operation gives when handed a stand-in.
///
/// Deliberately the same text a missing `TOKEN_SECRET` produces: from the
/// operator's side that is exactly what happened, and a second wording would
/// only invite the question of which one is the real problem.
#[must_use]
pub fn refusal() -> crate::translation_core::Text {
    crate::translation_core::format!("{}", "TOKEN_SECRET environment variable is required: this command signs or encrypts on this \
     machine, and no signing secret was supplied")
}

/// Refuse a stand-in before anything is signed or encrypted.
///
/// # Errors
///
/// Returns [`refusal`] when `secret` is a stand-in.
pub fn ensure_real(secret: &crate::translation_core::Str) -> crate::translation_core::Outcome<(), String> {
    if is_placeholder(secret) {
        return Err(refusal());
    }
    Ok(())
}

/// The variable naming a file that holds the signing secret (issue #684).
///
/// A service unit references the file, so the secret never appears in the
/// unit, in `systemctl show`, or in any process's argv.
pub const FILE_ENV: &crate::translation_core::Str = "TOKEN_SECRET_FILE";

/// The secret in `path`, without one trailing line break.
///
/// # Errors
///
/// When the file cannot be read, is not UTF-8, or holds no secret.
pub fn read_file(path: &std::path::Path) -> crate::translation_core::Outcome<String, String> {
    let text = std::fs::read_to_string(path)
        .map_err(|error| format!("{FILE_ENV}={} could not be read: {error}", path.display()))?;
    let secret = text.strip_suffix('\n').map_or(text.as_str(), |text| {
        text.strip_suffix('\r').unwrap_or(text)
    });
    if secret.is_empty() {
        return Err(format!("{FILE_ENV}={} is empty", path.display()));
    }
    Ok(secret.to_string())
}

/// `secret`, or the content of `TOKEN_SECRET_FILE` when no secret was given.
///
/// An explicit `TOKEN_SECRET` or `--token-secret` wins, so a file left in
/// the environment cannot silently replace a secret the operator passed.
///
/// # Errors
///
/// When `TOKEN_SECRET_FILE` is set and cannot supply a secret.
pub fn or_from_file(secret: crate::translation_core::Maybe<String>) -> crate::translation_core::Outcome<crate::translation_core::Maybe<String>, String> {
    if secret.as_deref().is_some_and(|secret| !secret.is_empty()) {
        return Ok(secret);
    }
    crate::operation_context::var_os(FILE_ENV)
        .filter(|path| !path.is_empty())
        .map_or(Ok(secret), |path| {
            read_file(std::path::Path::new(&path)).map(Some)
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The value cannot be supplied by an operator, deliberately or otherwise:
    /// no environment variable or command-line argument can carry a NUL.
    #[test]
    fn a_placeholder_cannot_be_expressed_by_a_caller() {
        let placeholder = placeholder("remote-command");
        assert!(placeholder.contains('\u{0}'), "{placeholder:?}");
        assert!(is_placeholder(&placeholder));
        assert!(std::ffi::CString::new(placeholder).is_err());
    }

    /// The defect in issue #300: a command that resolved to local execution
    /// signed tokens and encrypted vendor keys with a value published in the
    /// source. Every stand-in that ever existed is refused, not just today's.
    #[test]
    fn every_placeholder_is_refused_by_a_real_signer() {
        for legacy in LEGACY_PLACEHOLDERS {
            assert!(ensure_real(legacy).is_err(), "{legacy} was accepted");
        }
        assert!(ensure_real(&placeholder("auth")).is_err());
        assert!(ensure_real("a-real-operator-secret").is_ok());
    }

    #[test]
    fn a_secret_file_loses_one_line_break_and_an_empty_one_is_refused() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("secret");
        std::fs::write(&path, "file-held-secret\n").unwrap();
        assert_eq!(read_file(&path).unwrap(), "file-held-secret");
        std::fs::write(&path, "  spaced \n\n").unwrap();
        assert_eq!(read_file(&path).unwrap(), "  spaced \n");
        std::fs::write(&path, "\n").unwrap();
        assert!(read_file(&path).unwrap_err().contains("empty"));
        assert!(read_file(&directory.path().join("missing")).is_err());
        // An explicit secret wins without the file being consulted.
        assert_eq!(
            or_from_file(Some("explicit".into())).unwrap().as_deref(),
            Some("explicit")
        );
    }
}

//! `router tokens` against the *selected* router.
//!
//! Tokens are the part of a deployment an operator touches most often, and
//! every routine action was remote-only in practice: a token expires and a job
//! starts returning 401, or one leaks and must be revoked now, and the only
//! routes to either were `ssh` into the host or a hand-written `curl` with the
//! right path — `/api/management/tokens/list`, not
//! `/api/management/tokens`, which is `POST`-only and
//! answers 405 to a `GET` (issue #293).
//!
//! The HTTP surface was already complete and admin-gated, and the CLI was
//! already complete for a local store. Only the connection between them was
//! missing, so the capability existed twice and was reachable neither way for
//! the ordinary remote case.

use std::process::ExitCode;

use crate::cli::TokenOp;
use crate::managed_server::ResolvedServer;

/// Run one token operation against `server`.
pub async fn run(server: &ResolvedServer, op: &TokenOp) -> ExitCode {
    // Recovery is proof of local ownership of a token store, so it has no
    // remote form at all — not even a refusing route. Answered before a call is
    // built, because every other verb here maps to an admin endpoint and this
    // one deliberately maps to none (issue #573).
    if matches!(op, TokenOp::RecoverAdmin { .. }) {
        eprintln!("error: {}", crate::admin_recovery::refusal(server));
        return ExitCode::from(2);
    }
    // Import reads another root's files on this machine and writes the store
    // directly; like recovery it has no HTTP form (issue #644).
    if matches!(op, TokenOp::Import { .. }) {
        eprintln!("error: {}", crate::token_import::refusal(server));
        return ExitCode::from(2);
    }
    match execute(server, op).await {
        Ok(code) => code,
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

/// The call one token operation makes: method, path, and body.
///
/// Separated from sending it so the request an operation builds can be
/// asserted without a server. What goes on the wire is the part that can be
/// wrong in a way an operator notices — a rotate aimed at
/// `/api/management/tokens/rotate` would rotate the caller's *own* admin credential
/// rather than the named token — and it is exactly the part a live-server test
/// covers worst.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Call {
    /// `GET` or `POST`, as the endpoint expects.
    pub method: &'static str,
    /// The admin route this operation uses.
    pub path: &'static str,
    /// The JSON body, for a `POST`.
    pub body: Option<serde_json::Value>,
}

/// The call `op` makes against the selected router.
#[must_use]
pub fn call_for(op: &TokenOp) -> Call {
    match op {
        TokenOp::Issue {
            ttl_hours,
            label,
            account,
            max_requests,
            max_tokens,
            rate_limit_per_minute,
            admin,
            github_repo,
            allowed_model,
            ..
        } => Call {
            method: "POST",
            path: crate::route_contract::route_template(crate::route_contract::RouteId::Tokens),
            body: Some(crate::translation_core::json!({
                "ttl_hours": ttl_hours,
                "label": label,
                "account": account,
                "max_requests": max_requests,
                "max_tokens": max_tokens,
                "rate_limit_per_minute": rate_limit_per_minute,
                "scope": admin.then_some(crate::token::ADMIN_SCOPE),
                "github_repos": (!github_repo.is_empty()).then(|| github_repo.clone()),
                "allowed_models": (!allowed_model.is_empty()).then(|| allowed_model.clone()),
            })),
        },
        TokenOp::Rotate {
            id,
            ttl_hours,
            label,
            max_requests,
            max_tokens,
            rate_limit_per_minute,
            account,
            ..
        } => Call {
            method: "POST",
            // `rotate-client` replaces a named token. `/api/management/tokens/rotate`
            // rotates the *caller's own* admin credential, which is a
            // different operation and not what `tokens rotate <ID>` means.
            path: crate::route_contract::route_template(
                crate::route_contract::RouteId::RotateClientToken,
            ),
            body: Some(crate::translation_core::json!({
                "id": id,
                "ttl_hours": ttl_hours,
                "label": (!label.is_empty()).then(|| label.clone()),
                "max_requests": max_requests,
                "max_tokens": max_tokens,
                "rate_limit_per_minute": rate_limit_per_minute,
                "account": account,
            })),
        },
        // `show` has no route of its own: no `GET /api/management/tokens/{id}` exists, and
        // the local command is itself a filter over the list, so this stays a
        // filter rather than growing server surface for something already
        // answerable.
        TokenOp::List { .. } | TokenOp::Show { .. } => Call {
            method: "GET",
            path: crate::route_contract::route_template(crate::route_contract::RouteId::Tokens),
            body: None,
        },
        TokenOp::Revoke { id, .. } | TokenOp::Expire { id, .. } => Call {
            method: "POST",
            path: crate::route_contract::route_template(
                crate::route_contract::RouteId::RevokeToken,
            ),
            body: Some(crate::translation_core::json!({ "id": id })),
        },
        // Recovery has no remote form: it proves local ownership of a store,
        // which is not a thing an HTTP request can demonstrate. `run` refuses
        // before reaching this, and no route exists to name here (issue #573).
        TokenOp::RecoverAdmin { .. } | TokenOp::Import { .. } => Call {
            method: "POST",
            path: "",
            body: None,
        },
    }
}

async fn execute(server: &ResolvedServer, op: &TokenOp) -> crate::translation_core::Outcome<ExitCode, String> {
    let call = call_for(op);
    let answer = match call.body {
        Some(body) => crate::auth_remote::post(server, call.path, body).await?,
        None => crate::auth_remote::get(server, call.path).await?,
    };
    match op {
        TokenOp::Issue { .. } => {
            print_issued(&answer);
            Ok(ExitCode::SUCCESS)
        }
        TokenOp::Rotate { .. } => {
            print_issued(&answer);
            if let Some(revoked) = answer.get("revoked").and_then(serde_json::Value::as_str) {
                eprintln!("revoked {revoked}");
            }
            Ok(ExitCode::SUCCESS)
        }
        TokenOp::List { .. } => {
            crate::token_report::print_table(&records_in(&answer));
            Ok(ExitCode::SUCCESS)
        }
        TokenOp::Revoke { id, .. } | TokenOp::Expire { id, .. } => {
            println!("revoked {id}");
            Ok(ExitCode::SUCCESS)
        }
        TokenOp::Show { id, .. } => Ok(show_one(&records_in(&answer), id)),
        // Unreachable: `run` returns for `RecoverAdmin` before `execute`.
        TokenOp::RecoverAdmin { .. } | TokenOp::Import { .. } => {
            Err("this operation has no remote form".to_string())
        }
    }
}

/// Print one token record, or say it is not there.
///
/// Exits 2 for an unknown id, as the local path does, so a script's meaning is
/// the same against either target.
#[must_use]
pub fn show_one(records: &[crate::translation_core::Json], id: &crate::translation_core::Str) -> ExitCode {
    records
        .iter()
        .find(|record| record.get("id").and_then(serde_json::Value::as_str) == Some(id))
        .map_or_else(
            || {
                eprintln!("not found: {id}");
                ExitCode::from(2)
            },
            |record| {
                println!(
                    "{}",
                    serde_json::to_string_pretty(record).unwrap_or_default()
                );
                ExitCode::SUCCESS
            },
        )
}

/// The token records inside a `/api/management/tokens/list` answer.
#[must_use]
pub fn records_in(answer: &crate::translation_core::Json) -> Vec<crate::translation_core::Json> {
    answer
        .get("data")
        .and_then(crate::translation_core::Json::as_array)
        .cloned()
        .unwrap_or_default()
}

/// Print a freshly issued or rotated token exactly as the local path does.
///
/// The token itself goes to stdout alone, so `tokens issue > file` and
/// `$(router tokens issue)` keep working against a remote deployment.
fn print_issued(answer: &crate::translation_core::Json) {
    if let Some(token) = answer.get("token").and_then(serde_json::Value::as_str) {
        println!("{token}");
    }
}

