#[derive(Debug, Default, PartialEq, Eq)]
struct Counts {
    passed: u64,
    failed: u64,
    ignored: u64,
}

/// Sum libtest's `test result:` lines. They are printed after a binary's
/// tests finish, so parallel output never interleaves them.
fn counts(output: &str) -> Counts {
    let mut total = Counts::default();
    for line in output.lines() {
        let Some(rest) = line.trim().strip_prefix("test result: ") else {
            continue;
        };
        for part in rest.split(['.', ';']) {
            let mut words = part.split_whitespace();
            let (Some(number), Some(label)) = (words.next(), words.next()) else {
                continue;
            };
            let Ok(number) = number.parse::<u64>() else {
                continue;
            };
            match label {
                "passed" => total.passed += number,
                "failed" => total.failed += number,
                "ignored" => total.ignored += number,
                _ => {}
            }
        }
    }
    total
}

/// Skips announced through `tests/common/tiers.rs`, one per test.
fn skips(log: &str) -> Vec<Value> {
    let mut unique = BTreeMap::new();
    for line in log.lines() {
        if let Ok(skip) = serde_json::from_str::<Value>(line)
            && let Some(test) = skip["test"].as_str()
        {
            unique.entry(test.to_string()).or_insert(skip);
        }
    }
    unique.into_values().collect()
}

/// `proven` only when every declared target ran, none failed, and none
/// skipped or were ignored: a skipped case or an unexecuted target never
/// counts toward parity.
const fn status(succeeded: bool, counts: &Counts, skipped: usize, not_run: usize) -> &'static str {
    if !succeeded || counts.failed > 0 {
        "failed"
    } else if not_run > 0 || skipped > 0 || counts.ignored > 0 || counts.passed == 0 {
        "not-proven"
    } else {
        "proven"
    }
}

/// How many test binaries reported a `test result:` line.
fn results(output: &str) -> usize {
    output
        .lines()
        .filter(|line| line.trim().starts_with("test result: "))
        .count()
}

/// One `cargo test` invocation per declared target, labelled by that target.
///
/// Plain `cargo test` stops at the first failing test binary, so every target
/// after it silently went unexecuted while the area reported only what ran
/// (issue #655). One invocation per target, each with `--no-fail-fast`, makes
/// every declared target produce its own result or be named as not run.
fn invocations(run: &Run) -> Vec<(String, Vec<String>)> {
    if run.targets.is_empty() {
        return vec![(run.unit.join(" "), cargo_args(run, None))];
    }
    run.targets
        .iter()
        .map(|target| ((*target).to_string(), cargo_args(run, Some(target))))
        .collect()
}

fn cargo_args(run: &Run, target: Option<&str>) -> Vec<String> {
    let mut args = vec![
        "test".to_string(),
        "--locked".to_string(),
        "--no-fail-fast".to_string(),
    ];
    args.extend(run.unit.iter().map(|arg| (*arg).to_string()));
    if let Some(target) = target {
        args.extend(["--test".to_string(), target.to_string()]);
    }
    if let Some(filter) = run.filter {
        args.push(filter.to_string());
    }
    args.extend(["--".to_string(), "--nocapture".to_string()]);
    if run.serial {
        args.push("--test-threads=1".to_string());
    }
    args
}

fn verify(
    area: &Area,
    directory: &Path,
    variables: &[(String, String)],
    client_filter: Option<&str>,
) -> Value {
    let skip_log = directory.join(format!("{}.skips", area.name));
    verify_with(area, directory, client_filter, |args| {
        match crate::operation_context::bounded_output(
            crate::operation_context::command("cargo")
                .args(args)
                .env(SKIP_LOG, &skip_log)
                .envs(variables.iter().map(|(key, value)| (key, value))),
            crate::operation_context::current()
                .map_or(std::time::Duration::from_secs(3600), |context| {
                    context.process_deadline
                }),
        ) {
            Ok(result) => (
                result.status.success(),
                format!(
                    "{}{}",
                    String::from_utf8_lossy(&result.stderr),
                    String::from_utf8_lossy(&result.stdout)
                ),
            ),
            Err(error) => (false, format!("could not run cargo: {error}\n")),
        }
    })
}

/// [`verify`] with the `cargo` invocation injected: `cargo` receives the
/// arguments and returns its success and combined output.
fn verify_with(
    area: &Area,
    directory: &Path,
    client_filter: Option<&str>,
    mut cargo: impl FnMut(&[String]) -> (bool, String),
) -> Value {
    let skip_log = directory.join(format!("{}.skips", area.name));
    let _ = std::fs::remove_file(&skip_log);
    let mut output = String::new();
    let mut succeeded = true;
    let mut commands = Vec::new();
    let mut targets = Vec::new();
    let mut not_run = Vec::new();
    for run in area.runs {
        for (target, mut args) in invocations(run) {
            if let Some(filter) = client_filter.filter(|_| area.name == "real-clients") {
                args.insert(
                    args.iter()
                        .position(|arg| arg == "--")
                        .expect("test separator"),
                    filter.to_string(),
                );
            }
            commands.push(format!("cargo {}", args.join(" ")));
            eprintln!("verify {}: cargo {}", area.name, args.join(" "));
            let (ran, text) = cargo(&args);
            succeeded &= ran;
            let counted = counts(&text);
            let reported = results(&text) > 0;
            if !reported {
                not_run.push(target.clone());
            }
            targets.push(json!({
                "target": target,
                "status": if reported { status(ran, &counted, 0, 0) } else { "not-run" },
                "passed": counted.passed,
                "failed": counted.failed,
                "ignored": counted.ignored,
            }));
            let _ = writeln!(output, "==> verify {} target {target}", area.name);
            output.push_str(&text);
        }
    }
    let log = directory.join(format!("{}.log", area.name));
    if let Err(error) = std::fs::write(&log, &output) {
        eprintln!("warning: could not write {}: {error}", log.display());
    }
    let counts = counts(&output);
    let skipped = skips(&std::fs::read_to_string(&skip_log).unwrap_or_default());
    let status = status(succeeded, &counts, skipped.len(), not_run.len());
    eprintln!(
        "verify {}: {status} passed={} failed={} ignored={} skipped={} not_run={}{}",
        area.name,
        counts.passed,
        counts.failed,
        counts.ignored,
        skipped.len(),
        not_run.len(),
        named(&not_run)
    );
    json!({
        "name": area.name,
        "covers": area.covers,
        "status": status,
        "ran": true,
        "passed": counts.passed,
        "failed": counts.failed,
        "ignored": counts.ignored,
        "skipped": skipped,
        "not_run": not_run,
        "targets": targets,
        "enable_skipped_with": area.enable,
        "commands": commands,
        "log": log.display().to_string(),
    })
}

/// ` (a, b)` for a non-empty list, so a summary count names what it counts.
fn named(items: &[String]) -> String {
    if items.is_empty() {
        String::new()
    } else {
        format!(" ({})", items.join(", "))
    }
}

/// Areas that executed no test at all, with the reason, and every declared
/// target that produced no result, as `area/target`.
///
/// Counted separately from skipped tests: an area that never ran is not two
/// skipped tests, and the summary must not read as if it were (issue #654).
fn unexecuted(areas: &[Value]) -> (Vec<Value>, Vec<String>) {
    let not_run_areas = areas
        .iter()
        .filter(|area| area["ran"] == false)
        .map(|area| json!({"name": area["name"], "reason": area["reason"], "enable_with": area["enable_with"]}))
        .collect();
    let not_run_targets = areas
        .iter()
        .flat_map(|area| {
            let name = area["name"].as_str().unwrap_or_default().to_string();
            area["not_run"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(Value::as_str)
                .map(move |target| format!("{name}/{target}"))
                .collect::<Vec<_>>()
        })
        .collect();
    (not_run_areas, not_run_targets)
}

/// The one-line summary; every count names what it counts.
fn summary(
    parity: bool,
    failed: bool,
    skipped: usize,
    areas_not_run: &[Value],
    targets_not_run: &[String],
    output: &Path,
) -> String {
    let area_names: Vec<String> = areas_not_run
        .iter()
        .filter_map(|area| area["name"].as_str().map(str::to_string))
        .collect();
    format!(
        "verification parity={parity} failed={failed} skipped={skipped} areas_not_run={}{} targets_not_run={}{} result={}",
        area_names.len(),
        named(&area_names),
        targets_not_run.len(),
        named(targets_not_run),
        output.display()
    )
}

fn usage() -> ExitCode {
    eprintln!(
        "usage: rust-script scripts/verify-contracts.rs [--area NAME]... [--output PATH] [--require-parity] [--list]"
    );
    ExitCode::from(2)
}

fn git_commit() -> Option<String> {
    let output = crate::operation_context::bounded_output(
        crate::operation_context::command("git").args(["rev-parse", "HEAD"]),
        std::time::Duration::from_secs(60),
    )
    .ok()?;
    output
        .status
        .success()
        .then(|| String::from_utf8_lossy(&output.stdout).trim().to_string())
}

fn router_version() -> Option<String> {
    let manifest = std::fs::read_to_string(
        crate::operation_context::current_dir()
            .ok()?
            .join("Cargo.toml"),
    )
    .ok()?;
    manifest
        .lines()
        .find_map(|line| line.strip_prefix("version = "))
        .map(|version| version.trim_matches('"').to_string())
}

fn needs_client_preparation(area: &str) -> bool {
    matches!(
        area,
        "real-clients" | "anthropic-entitlements" | "zai-only-entitlements" | "staging"
    )
}

/// Verification adapter shared by the CLI and importable API.
pub fn run_cli(arguments: Vec<String>) -> ExitCode {
    let mut selected = Vec::new();
    let mut output = PathBuf::from("target/verification/result.json");
    let mut require_parity = false;
    let mut client_filter = None;
    let mut prepare_only = false;
    let mut args = arguments.into_iter();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--area" => selected.push(match args.next() {
                Some(value) => value,
                None => return usage(),
            }),
            "--output" => {
                output = PathBuf::from(match args.next() {
                    Some(value) => value,
                    None => return usage(),
                });
            }
            "--require-parity" => require_parity = true,
            "--client" => {
                client_filter = Some(match args.next() {
                    Some(value) => value,
                    None => return usage(),
                });
            }
            "--prepare-clients" => prepare_only = true,
            "--list" => {
                for area in AREAS {
                    println!("{}\t{}", area.name, area.covers);
                }
                return ExitCode::SUCCESS;
            }
            _ => return usage(),
        }
    }
    for name in &selected {
        if !AREAS.iter().any(|area| area.name == name) {
            eprintln!("error: unknown area {name}; see --list");
            return ExitCode::from(2);
        }
    }
    if output.is_relative()
        && let Some(context) = crate::operation_context::current()
    {
        output = context.working_directory.join(output);
    }
    let directory = output
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .map_or_else(|| PathBuf::from("."), Path::to_path_buf);
    if let Err(error) = std::fs::create_dir_all(&directory) {
        eprintln!("error: could not create {}: {error}", directory.display());
        return ExitCode::from(2);
    }
    let directory = directory.canonicalize().unwrap_or(directory);

    let needs_clients = prepare_only
        || selected.is_empty()
        || selected.iter().any(|name| needs_client_preparation(name));
    let clients: Vec<&str> = if client_filter.is_some()
        || prepare_only
        || selected.is_empty()
        || selected.iter().any(|name| name == "real-clients")
    {
        client_filter.as_deref().into_iter().collect()
    } else if selected.iter().any(|name| name == "zai-only-entitlements") {
        vec!["claude", "codex"]
    } else {
        vec!["claude"]
    };
    if let Some(client) = &client_filter
        && !verification_client::CLIENTS
            .iter()
            .any(|(name, _)| name == client)
    {
        return usage();
    }
    let (preparation, variables) = if needs_clients {
        verification_client::prepare(&clients)
    } else {
        (Vec::new(), Vec::new())
    };
    let preparation_failed = preparation.iter().any(|item| item["status"] == "failed");
    let preparation_unproven = preparation
        .iter()
        .any(|item| item["status"] == "not-proven");
    // Persist discovery even when compilation is refused or preparation fails.
    let client_evidence = directory.join("clients.json");
    if let Err(error) = std::fs::write(
        &client_evidence,
        serde_json::to_string_pretty(&preparation).expect("JSON"),
    ) {
        eprintln!(
            "error: could not write {}: {error}",
            client_evidence.display()
        );
        return ExitCode::from(2);
    }
    let areas: Vec<Value> = AREAS
        .iter()
        .filter(|area| selected.is_empty() || selected.iter().any(|name| name == area.name))
        .filter(|_| !prepare_only)
        .map(|area| {
            if needs_client_preparation(area.name) && (preparation_failed || preparation_unproven) {
                json!({"name":area.name,"status":if preparation_failed {"failed"} else {"not-proven"},"ran":false,"skipped":[],"not_run":[],"reason":"client preparation did not complete; no vendor probes or Cargo test compilation attempted","enable_with":"docs/testing-tiers.md#proving-the-vendor-areas-from-macos"})
            } else { verify(area, &directory, &variables, client_filter.as_deref()) }
        })
        .collect();
    let failed = preparation_failed || areas.iter().any(|area| area["status"] == "failed");
    let parity = !prepare_only
        && !preparation_unproven
        && client_filter.is_none()
        && selected.is_empty()
        && areas.iter().all(|area| area["status"] == "proven");
    let skipped: usize = areas
        .iter()
        .map(|area| area["skipped"].as_array().map_or(0, Vec::len))
        .sum();
    let (areas_not_run, targets_not_run) = unexecuted(&areas);
    let result = json!({
        "schema": SCHEMA,
        "router_version": router_version(),
        "commit": git_commit(),
        "generated_at_unix": crate::operation_context::now().timestamp(),
        "complete": !prepare_only && selected.is_empty() && client_filter.is_none(),
        "parity": parity,
        "failed": failed,
        "skipped": skipped,
        "areas_not_run": areas_not_run,
        "targets_not_run": targets_not_run,
        "areas": areas,
        "client_preparation": preparation,
    });
    let rendered = serde_json::to_string_pretty(&result).expect("a JSON value renders");
    if let Err(error) = std::fs::write(&output, format!("{rendered}\n")) {
        eprintln!("error: could not write {}: {error}", output.display());
        return ExitCode::from(2);
    }
    println!(
        "{}",
        summary(
            parity,
            failed,
            skipped,
            &areas_not_run,
            &targets_not_run,
            &output
        )
    );
    for client in &preparation {
        println!(
            "client={} proven={} source={} host={}{}",
            client["client"].as_str().unwrap_or("unknown"),
            client["observed"].as_str().unwrap_or("not-proven"),
            client["source"].as_str().unwrap_or("installed"),
            client["host_installed"].as_str().unwrap_or("unknown"),
            if client["host_mismatch"] == true {
                " WARNING: proven version differs from host"
            } else {
                ""
            }
        );
    }
    crate::operation_output::record(result);
    if failed {
        return ExitCode::from(1);
    }
    if require_parity && !parity {
        eprintln!(
            "error: parity was required, but some area is not proven; its skipped tests, unexecuted areas and targets, and how to enable them are in {}",
            output.display()
        );
        return ExitCode::from(3);
    }
    ExitCode::SUCCESS
}
#[cfg(test)]
#[path = "verification_tests.rs"]
mod tests;

/// Run the shared verifier in-process. The result contains the saved result.json document.
///
/// ```no_run
/// # async fn example() -> Result<(), Box<dyn std::error::Error>> {
/// use link_assistant_router::{verification, operation_context::OperationContext};
/// let report = verification::run(OperationContext::default(), vec!["--area".into(), "deploy-configuration".into()]).await?;
/// assert!(report.success);
/// # Ok(()) }
/// ```
pub async fn run(
    context: crate::operation_context::OperationContext,
    arguments: Vec<String>,
) -> Result<crate::operations::OperationResult, crate::operations::OperationError> {
    crate::operations::request(
        context,
        crate::cli::Command::Verify(VerificationArgs { arguments }),
    )
    .await
}

//! `router tunnel up|status|down --server TARGET` (issue #682).
//!
//! Reaches a remote Router from this machine over an SSH local forward bound
//! to `127.0.0.1` only. The forward runs either as the tunnel companion
//! container (`--via docker`, restarted by Docker's `unless-stopped` policy)
//! or as a local `ssh -L` under a small supervisor loop that reconnects after
//! a drop (`--via ssh`). The far side's host key is pinned: `up` requires
//! `--ssh-known-hosts` and runs with `StrictHostKeyChecking=yes`, never
//! `accept-new`. `docker` and `ssh` are found on `PATH`.
//!
//! `up` and `status` check `/api/health` and, with a client token in
//! `LINK_ASSISTANT_ROUTER_TOKEN`, an authorized `/v1/models` through the
//! tunnel. The token is sent as a header only; it is never in any argv.

use std::path::{Path, PathBuf};
use std::process::{ExitCode, Stdio};
use std::time::Duration;

use clap::{Args, Subcommand, ValueEnum};
use serde::{Deserialize, Serialize};

/// The client token `up` and `status` authorize `/v1/models` with.
pub const TOKEN_ENV: &str = "LINK_ASSISTANT_ROUTER_TOKEN";

/// The tunnel companion image built from `docker/tunnel/Dockerfile`.
pub const DEFAULT_IMAGE: &str = "link-assistant-router-tunnel";

/// Reconnects a dropped `ssh -L`; the arguments arrive as `"$@"`.
const SUPERVISOR: &str = "while :; do \"$@\"; sleep 5; done";

#[derive(Debug, Args)]
pub struct TunnelArgs {
    #[command(subcommand)]
    pub op: TunnelOp,
}

#[derive(Debug, Subcommand)]
pub enum TunnelOp {
    /// Start the forward (a no-op when it already runs), then check it.
    Up(TunnelTarget),
    /// Report whether the forward runs and the Router answers through it.
    Status(TunnelTarget),
    /// Stop the forward and forget it.
    Down(TunnelTarget),
}

/// How the forward runs.
#[derive(Clone, Copy, Debug, Default, Deserialize, Eq, PartialEq, Serialize, ValueEnum)]
#[serde(rename_all = "kebab-case")]
pub enum Via {
    /// A local `ssh -L`, reconnected by a supervisor loop.
    #[default]
    Ssh,
    /// The tunnel companion container on the host network.
    Docker,
}

#[derive(Clone, Debug, Args)]
pub struct TunnelTarget {
    /// SSH destination (`user@host`; `--via ssh` also accepts a config alias).
    #[arg(long, value_name = "TARGET")]
    pub server: String,
    /// The loopback port on this machine.
    #[arg(long, default_value_t = 8080)]
    pub local_port: u16,
    /// The Router's loopback port on the server.
    #[arg(long, default_value_t = 8080)]
    pub remote_port: u16,
    /// SSH port on the server.
    #[arg(long)]
    pub ssh_port: Option<u16>,
    /// Private key for the server (required with `--via docker`).
    #[arg(long, value_name = "FILE")]
    pub ssh_identity: Option<PathBuf>,
    /// Pinned `known_hosts` file for the server (required by `up`).
    #[arg(long, value_name = "FILE")]
    pub ssh_known_hosts: Option<PathBuf>,
    #[arg(long, value_enum, default_value_t)]
    pub via: Via,
    /// Tunnel companion image for `--via docker`.
    #[arg(long, default_value = DEFAULT_IMAGE)]
    pub image: String,
    /// Seconds `up` waits for the Router to answer through the tunnel.
    #[arg(long, default_value_t = 30)]
    pub wait: u64,
}

/// What `up` started, so `status` and `down` find it.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
struct Record {
    via: Via,
    server: String,
    local_port: u16,
    remote_port: u16,
    /// The supervisor's process group (`--via ssh`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pid: Option<u32>,
    /// The container name (`--via docker`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    container: Option<String>,
}

/// A name for the forward that is safe in a file and container name. A short
/// hash of the exact server keeps `a@b.c` and `a-b-c` apart.
#[must_use]
pub fn tunnel_name(server: &str, local_port: u16) -> String {
    use sha2::Digest as _;
    let digest = sha2::Sha256::digest(server.as_bytes());
    let sanitized: String = server
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
        .collect();
    format!(
        "router-tunnel-{sanitized}-{}-{local_port}",
        hex::encode(&digest[..4])
    )
}

fn state_dir() -> Result<PathBuf, String> {
    crate::operation_context::var_os("HOME")
        .filter(|home| !home.is_empty())
        .map(|home| {
            PathBuf::from(home)
                .join(".link-assistant-router")
                .join("tunnels")
        })
        .ok_or_else(|| "HOME is not set; the tunnel state location is unknown".to_string())
}

fn pinned(target: &TunnelTarget) -> Result<&Path, String> {
    let known = target.ssh_known_hosts.as_deref().ok_or(
        "--ssh-known-hosts is required: the server's host key is pinned, never accepted on first use",
    )?;
    match std::fs::metadata(known) {
        Ok(metadata) if metadata.len() > 0 => Ok(known),
        _ => Err(format!(
            "{} must be a readable, non-empty `known_hosts` file pinning the server's host key",
            known.display()
        )),
    }
}

fn forward_spec(target: &TunnelTarget) -> String {
    format!(
        "127.0.0.1:{}:127.0.0.1:{}",
        target.local_port, target.remote_port
    )
}

/// The `ssh` argv for `--via ssh`; paths and ports only, never a secret.
///
/// # Errors
///
/// When the host key is not pinned.
pub fn ssh_arguments(target: &TunnelTarget) -> Result<Vec<String>, String> {
    let known = pinned(target)?;
    let mut arguments = vec!["-N".to_string()];
    if let Some(port) = target.ssh_port {
        arguments.extend(["-p".to_string(), port.to_string()]);
    }
    if let Some(identity) = &target.ssh_identity {
        arguments.extend([
            "-i".to_string(),
            identity.display().to_string(),
            "-o".to_string(),
            "IdentitiesOnly=yes".to_string(),
        ]);
    }
    for option in [
        "BatchMode=yes".to_string(),
        "ExitOnForwardFailure=yes".to_string(),
        "StrictHostKeyChecking=yes".to_string(),
        format!("UserKnownHostsFile={}", known.display()),
        "GlobalKnownHostsFile=/dev/null".to_string(),
        "GatewayPorts=no".to_string(),
        "ServerAliveInterval=30".to_string(),
        "ServerAliveCountMax=3".to_string(),
    ] {
        arguments.extend(["-o".to_string(), option]);
    }
    arguments.extend([
        "-L".to_string(),
        forward_spec(target),
        "--".to_string(),
        target.server.clone(),
    ]);
    Ok(arguments)
}

/// The `docker run` argv for `--via docker`; paths and ports only.
///
/// The container shares the host network so its `127.0.0.1` listener is
/// this machine's loopback; nothing is published with `-p`.
///
/// # Errors
///
/// When the host key is not pinned, there is no identity, or the server is
/// not `user@host`.
pub fn docker_arguments(target: &TunnelTarget, name: &str) -> Result<Vec<String>, String> {
    let known = pinned(target)?;
    let identity = target
        .ssh_identity
        .as_deref()
        .ok_or("--via docker needs --ssh-identity to mount into the companion")?;
    let (user, host) = target
        .server
        .split_once('@')
        .filter(|(user, host)| !user.is_empty() && !host.is_empty())
        .ok_or("--via docker needs --server user@host")?;
    let absolute = |path: &Path| {
        std::path::absolute(path)
            .map(|path| path.display().to_string())
            .map_err(|error| format!("could not resolve {}: {error}", path.display()))
    };
    let mut arguments: Vec<String> = [
        "run",
        "-d",
        "--name",
        name,
        "--restart",
        "unless-stopped",
        "--network",
        "host",
        "--label",
        "link-assistant.router.tunnel=forward",
    ]
    .map(str::to_string)
    .to_vec();
    // The key is mounted as it is on the host, usually 0600 and owned by the
    // caller: run the companion as that owner so it can read it. The image
    // gives such a user a passwd entry at start (ssh needs one).
    if let Some((uid, gid)) = owner(identity).filter(|(uid, _)| *uid != 0) {
        arguments.extend([
            "--user".to_string(),
            format!("{uid}:{gid}"),
            "--group-add".to_string(),
            "0".to_string(),
        ]);
    }
    for (variable, value) in [
        ("TUNNEL_MODE", "forward".to_string()),
        ("TUNNEL_SSH_HOST", host.to_string()),
        ("TUNNEL_SSH_USER", user.to_string()),
        ("TUNNEL_SSH_PORT", target.ssh_port.unwrap_or(22).to_string()),
        ("TUNNEL_LOCAL_PORT", target.local_port.to_string()),
        ("TUNNEL_TARGET_PORT", target.remote_port.to_string()),
        ("TUNNEL_SSH_KEY", "/run/secrets/ssh-key".to_string()),
        ("TUNNEL_KNOWN_HOSTS", "/run/secrets/known-hosts".to_string()),
    ] {
        arguments.extend(["-e".to_string(), format!("{variable}={value}")]);
    }
    arguments.extend([
        "-v".to_string(),
        format!("{}:/run/secrets/ssh-key:ro", absolute(identity)?),
        "-v".to_string(),
        format!("{}:/run/secrets/known-hosts:ro", absolute(known)?),
        target.image.clone(),
    ]);
    Ok(arguments)
}

/// The owner of `path` as `(uid, gid)`; `None` off Unix or when unreadable.
fn owner(path: &Path) -> Option<(u32, u32)> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt as _;
        std::fs::metadata(path)
            .ok()
            .map(|metadata| (metadata.uid(), metadata.gid()))
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        None
    }
}

/// Whether `pid` still runs the supervisor named `name`, so a pid the system
/// has since reused for another process is never signalled. When neither
/// `/proc` nor `ps` can tell, the recorded pid is trusted.
fn is_supervisor(pid: u32, name: &str) -> bool {
    if let Ok(command_line) = std::fs::read(format!("/proc/{pid}/cmdline")) {
        return command_line
            .split(|byte| *byte == 0)
            .any(|argument| argument == name.as_bytes());
    }
    match crate::operation_context::process_output(
        crate::operation_context::command("ps")
            .args(["-o", "args=", "-p", &pid.to_string()])
            .stdin(Stdio::null())
            .stderr(Stdio::null()),
    ) {
        Ok(output) if output.status.success() => {
            String::from_utf8_lossy(&output.stdout).contains(name)
        }
        // `ps` exits non-zero when no such process exists.
        Ok(_) => false,
        Err(_) => true,
    }
}

fn output(program: &str, arguments: &[String]) -> Result<String, String> {
    let output = crate::operation_context::process_output(
        crate::operation_context::command(program)
            .args(arguments)
            .stdin(Stdio::null()),
    )
    .map_err(|error| format!("could not run {program}: {error}"))?;
    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        Err(format!(
            "{program} {} failed: {}",
            arguments.first().map_or("", String::as_str),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

fn alive(record: &Record) -> bool {
    match record.via {
        Via::Ssh => record.pid.is_some_and(|pid| {
            is_supervisor(pid, &tunnel_name(&record.server, record.local_port))
                && crate::operation_context::process_output(
                    crate::operation_context::command("kill")
                        .args(["-0", &pid.to_string()])
                        .stderr(Stdio::null()),
                )
                .map(|output| output.status)
                .is_ok_and(|status| status.success())
        }),
        Via::Docker => record.container.as_ref().is_some_and(|name| {
            output(
                "docker",
                &[
                    "inspect".to_string(),
                    "--format".to_string(),
                    "{{.State.Running}}".to_string(),
                    name.clone(),
                ],
            )
            .is_ok_and(|running| running == "true")
        }),
    }
}

fn read_record(path: &Path) -> Option<Record> {
    serde_json::from_slice(&std::fs::read(path).ok()?).ok()
}

fn start(target: &TunnelTarget, name: &str, directory: &Path) -> Result<Record, String> {
    let mut record = Record {
        via: target.via,
        server: target.server.clone(),
        local_port: target.local_port,
        remote_port: target.remote_port,
        pid: None,
        container: None,
    };
    match target.via {
        Via::Docker => {
            let arguments = docker_arguments(target, name)?;
            // A stopped companion of the same name would refuse the run.
            let _ = output(
                "docker",
                &["rm".to_string(), "-f".to_string(), name.to_string()],
            );
            output("docker", &arguments)?;
            record.container = Some(name.to_string());
        }
        Via::Ssh => {
            let arguments = ssh_arguments(target)?;
            let log = std::fs::File::create(directory.join(format!("{name}.log")))
                .map_err(|error| format!("could not open the tunnel log: {error}"))?;
            let mut command = crate::operation_context::command("sh");
            // `$0` names the tunnel, so `down` can recognise the process.
            command
                .args(["-c", SUPERVISOR, name, "ssh"])
                .args(&arguments)
                .stdin(Stdio::null())
                .stdout(Stdio::null())
                .stderr(log);
            #[cfg(unix)]
            std::os::unix::process::CommandExt::process_group(&mut command, 0);
            let child = crate::operation_context::spawn_process(&mut command)
                .map_err(|error| format!("could not start ssh: {error}"))?;
            record.pid = Some(child.id());
        }
    }
    Ok(record)
}

fn stop(record: &Record) {
    match (record.via, record.pid, &record.container) {
        (Via::Ssh, Some(pid), _)
            if is_supervisor(pid, &tunnel_name(&record.server, record.local_port)) =>
        {
            // The supervisor leads its own process group: end it and its ssh.
            let _ = crate::operation_context::process_output(
                crate::operation_context::command("kill")
                    .args(["-TERM", "--", &format!("-{pid}")])
                    .stderr(Stdio::null()),
            )
            .map(|output| output.status);
        }
        (Via::Docker, _, Some(name)) => {
            let _ = output(
                "docker",
                &["rm".to_string(), "-f".to_string(), name.clone()],
            );
        }
        _ => {}
    }
}

/// One HTTP status through the tunnel, or `None` when nothing answered.
async fn probe(port: u16, path: &str, token: Option<&str>) -> Option<u16> {
    let client = reqwest::Client::builder()
        .no_proxy()
        .timeout(Duration::from_secs(10))
        .build()
        .ok()?;
    let mut request = client.get(format!("http://127.0.0.1:{port}{path}"));
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    request
        .send()
        .await
        .ok()
        .map(|response| response.status().as_u16())
}

/// What answered through the tunnel.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Checked {
    /// Health and, with a token, the authorized catalog answered `200`.
    Usable,
    /// The Router answered, but not as expected (a wrong token, say).
    Refused,
    /// Nothing healthy answered before the wait ran out.
    Unreachable,
}

/// Check the Router through the tunnel.
async fn check(port: u16, wait: u64) -> Checked {
    checked_status(port, wait).await.0
}

async fn checked_status(port: u16, wait: u64) -> (Checked, Option<u16>, Option<u16>, bool) {
    let deadline = tokio::time::Instant::now() + Duration::from_secs(wait);
    let health = loop {
        let status = probe(port, "/api/health", None).await;
        if status == Some(200) || tokio::time::Instant::now() >= deadline {
            break status;
        }
        tokio::time::sleep(Duration::from_millis(500)).await;
    };
    println!(
        "health={}",
        health.map_or_else(|| "unreachable".to_string(), |status| status.to_string())
    );
    if health != Some(200) {
        return (Checked::Unreachable, health, None, false);
    }
    let token = crate::operation_context::var(TOKEN_ENV)
        .ok()
        .filter(|token| !token.is_empty());
    let Some(token) = token else {
        println!("models=skipped (set {TOKEN_ENV} to check an authorized /v1/models)");
        return (Checked::Usable, health, None, false);
    };
    let models = probe(port, "/v1/models", Some(&token)).await;
    println!(
        "models={}",
        models.map_or_else(|| "unreachable".to_string(), |status| status.to_string())
    );
    (
        if models == Some(200) {
            Checked::Usable
        } else {
            Checked::Refused
        },
        health,
        models,
        true,
    )
}

/// Run `router tunnel`.
pub async fn run(args: &TunnelArgs) -> ExitCode {
    let (TunnelOp::Up(target) | TunnelOp::Status(target) | TunnelOp::Down(target)) = &args.op;
    let directory = match state_dir() {
        Ok(directory) => directory,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(2);
        }
    };
    let name = tunnel_name(&target.server, target.local_port);
    let path = directory.join(format!("{name}.json"));
    let existing = read_record(&path);
    let described = format!(
        "local=127.0.0.1:{} server={} remote=127.0.0.1:{}",
        target.local_port, target.server, target.remote_port
    );
    match &args.op {
        TunnelOp::Down(_) => {
            if let Some(record) = &existing {
                stop(record);
            }
            let _ = std::fs::remove_file(&path);
            println!("tunnel=down {described}");
            ExitCode::SUCCESS
        }
        TunnelOp::Status(_) => {
            let running = existing.as_ref().is_some_and(alive);
            let via = existing.as_ref().map_or("none", |record| match record.via {
                Via::Ssh => "ssh",
                Via::Docker => "docker",
            });
            println!(
                "tunnel={} via={via} {described}",
                if running { "running" } else { "stopped" }
            );
            let (checked, health_status, models_status, models_checked) = if running {
                checked_status(target.local_port, 0).await
            } else {
                (Checked::Unreachable, None, None, false)
            };
            crate::operation_output::report(crate::operation_reports::TunnelStatusReport {
                running,
                via: via.into(),
                server: target.server.clone(),
                local_port: target.local_port,
                remote_port: target.remote_port,
                health_status,
                models_status,
                models_checked,
                output: Vec::new(),
            });
            if running && checked == Checked::Usable {
                ExitCode::SUCCESS
            } else {
                ExitCode::from(1)
            }
        }
        TunnelOp::Up(_) => up(target, &name, &directory, &path, existing, &described).await,
    }
}

async fn up(
    target: &TunnelTarget,
    name: &str,
    directory: &Path,
    path: &Path,
    existing: Option<Record>,
    described: &str,
) -> ExitCode {
    if let Err(error) = pinned(target) {
        eprintln!("error: {error}");
        return ExitCode::from(2);
    }
    if let Some(record) = existing.filter(alive) {
        if record.via == target.via && record.remote_port == target.remote_port {
            println!("tunnel=running {described} (already up; nothing started)");
            return if check(target.local_port, target.wait).await == Checked::Usable {
                ExitCode::SUCCESS
            } else {
                ExitCode::from(1)
            };
        }
        stop(&record);
    }
    if let Err(error) = std::fs::create_dir_all(directory) {
        eprintln!("error: could not create {}: {error}", directory.display());
        return ExitCode::from(1);
    }
    let record = match start(target, name, directory) {
        Ok(record) => record,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(if error.starts_with("--") { 2 } else { 1 });
        }
    };
    let encoded = serde_json::to_vec_pretty(&record).unwrap_or_default();
    if let Err(error) = crate::durable_file::atomic_write_owner_only(path, &encoded) {
        stop(&record);
        eprintln!(
            "error: {}",
            crate::durable_file::describe_write_failure(path, &error)
        );
        return ExitCode::from(1);
    }
    println!("tunnel=started {described}");
    match check(target.local_port, target.wait).await {
        Checked::Usable => ExitCode::SUCCESS,
        Checked::Refused => {
            eprintln!(
                "error: the Router answered through the tunnel but refused the check; \
                 the tunnel stays up (`router tunnel down` stops it)"
            );
            ExitCode::from(1)
        }
        Checked::Unreachable => {
            // A wrong host key or an unreachable server will not fix itself:
            // do not leave a supervisor retrying it forever.
            stop(&record);
            let _ = std::fs::remove_file(path);
            println!("tunnel=stopped {described}");
            eprintln!(
                "error: nothing answered through the tunnel within {}s, so it was stopped; \
                 see the tunnel log in {}",
                target.wait,
                directory.display()
            );
            ExitCode::from(1)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn target(known: &Path) -> TunnelTarget {
        TunnelTarget {
            server: "router@far.example".to_string(),
            local_port: 18080,
            remote_port: 8080,
            ssh_port: Some(2222),
            ssh_identity: Some(PathBuf::from("/keys/id")),
            ssh_known_hosts: Some(known.to_path_buf()),
            via: Via::Ssh,
            image: DEFAULT_IMAGE.to_string(),
            wait: 0,
        }
    }

    #[test]
    fn the_ssh_forward_binds_loopback_and_pins_the_host_key() {
        let known = tempfile::NamedTempFile::new().unwrap();
        std::fs::write(known.path(), "far.example ssh-ed25519 AAAA\n").unwrap();
        let arguments = ssh_arguments(&target(known.path())).unwrap().join(" ");
        assert!(
            arguments.contains("-L 127.0.0.1:18080:127.0.0.1:8080"),
            "{arguments}"
        );
        assert!(
            arguments.contains("StrictHostKeyChecking=yes"),
            "{arguments}"
        );
        assert!(arguments.contains("GatewayPorts=no"), "{arguments}");
        assert!(!arguments.contains("0.0.0.0") && !arguments.contains("accept-new"));
    }

    #[test]
    fn an_unpinned_host_key_is_refused() {
        let mut target = target(Path::new("/nonexistent/known_hosts"));
        assert!(ssh_arguments(&target).is_err());
        target.ssh_known_hosts = None;
        assert!(
            ssh_arguments(&target)
                .unwrap_err()
                .contains("--ssh-known-hosts")
        );
    }

    #[test]
    fn the_companion_shares_the_host_network_and_publishes_nothing() {
        let known = tempfile::NamedTempFile::new().unwrap();
        std::fs::write(known.path(), "far.example ssh-ed25519 AAAA\n").unwrap();
        let arguments = docker_arguments(&target(known.path()), "router-tunnel-x").unwrap();
        assert!(
            arguments
                .windows(2)
                .any(|pair| pair == ["--network", "host"])
        );
        assert!(!arguments.iter().any(|argument| argument == "-p"));
        assert!(arguments.contains(&"TUNNEL_MODE=forward".to_string()));
        // The identity path is made absolute, which adds a drive on Windows.
        assert!(arguments.iter().any(|argument| {
            argument.ends_with(":/run/secrets/ssh-key:ro") && argument.contains("id")
        }));
    }

    #[test]
    fn tunnel_names_are_safe_file_and_container_names() {
        let name = tunnel_name("deploy@host.example", 8080);
        assert!(
            name.starts_with("router-tunnel-deploy-host-example-") && name.ends_with("-8080"),
            "{name}"
        );
        assert!(name.chars().all(|c| c.is_ascii_alphanumeric() || c == '-'));
        assert_ne!(name, tunnel_name("deploy-host-example", 8080));
    }

    #[test]
    fn a_reused_pid_is_not_taken_for_the_supervisor() {
        // This test process is alive but is no tunnel supervisor.
        assert!(!is_supervisor(
            std::process::id(),
            "router-tunnel-x-00000000-1"
        ));
    }

    #[cfg(unix)]
    #[test]
    fn the_companion_runs_as_the_key_owner() {
        use std::os::unix::fs::MetadataExt as _;
        let known = tempfile::NamedTempFile::new().unwrap();
        std::fs::write(known.path(), "far.example ssh-ed25519 AAAA\n").unwrap();
        let key = tempfile::NamedTempFile::new().unwrap();
        let mut target = target(known.path());
        target.ssh_identity = Some(key.path().to_path_buf());
        let metadata = std::fs::metadata(key.path()).unwrap();
        let arguments = docker_arguments(&target, "router-tunnel-x").unwrap();
        let user = format!("{}:{}", metadata.uid(), metadata.gid());
        assert_eq!(
            arguments
                .windows(2)
                .any(|pair| pair == ["--user", user.as_str()]),
            metadata.uid() != 0,
            "{arguments:?}"
        );
    }
}

//! Serving the router on a unix domain socket.
//!
//! `gh` builds a custom host's REST base as `https://<host>/api/v3/`, so
//! reaching the router means either serving TLS it trusts or avoiding TLS
//! altogether. Which of those is available depends on the platform, and the
//! difference is not cosmetic (issue #270):
//!
//! - **Linux**: `gh` honours `SSL_CERT_FILE`, because Go's `crypto/x509` reads
//!   it in `root_unix.go`. `router tls ca` plus that variable is a complete
//!   answer, with no socket and no trust-store change.
//! - **macOS**: `root_darwin.go` goes to the Security framework instead and
//!   ignores `SSL_CERT_FILE`, and `gh` has no `--cacert` flag, so a self-signed
//!   certificate cannot be handed to it at all.
//!
//! A socket sidesteps the question on both: `gh` honours `http_unix_socket`,
//! and over a socket it speaks plain HTTP — no CA, no trust store (issue #265).
//! It is the recommended path for a local or sidecar deployment, and the only
//! one that works for `gh` on macOS.
//!
//! The socket is owner-only by default, bounding access at least as tightly as
//! the loopback port it replaces. That default is a floor rather than the whole
//! story: a router in its own container serves clients in *other* containers
//! running as a different uid, which owner-only refuses by construction, so the
//! mode and group are configurable for exactly that case (issue #271).

use std::path::{Path, PathBuf};

/// Who may reach the socket once it is bound.
///
/// Owner-only is the default and the safe floor. Widening it is deliberate:
/// the group form is the one that fits containers, because a sidecar and its
/// task containers can agree on a numeric gid and access is then bounded by
/// that gid rather than by "everyone on the host" (issue #271).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SocketAccess {
    /// Permission bits applied after bind.
    pub mode: u32,
    /// Group to own the socket, by name or numeric gid.
    pub group: Option<String>,
}

impl Default for SocketAccess {
    fn default() -> Self {
        Self {
            // The router holds the operator's credentials, so anything that can
            // reach it can act as them.
            mode: 0o600,
            group: None,
        }
    }
}

/// The widest mode an operator may ask for.
///
/// `0o666` still excludes the execute bits and setuid/setgid, which mean
/// nothing on a socket and would only be a way to smuggle in something else.
const WIDEST_MODE: u32 = 0o666;

impl SocketAccess {
    /// Parse the configured mode and group.
    ///
    /// # Errors
    ///
    /// Returns an operator-readable message when the mode is not octal or is
    /// wider than `0666`. A refusal is deliberate: silently narrowing a mode
    /// the operator asked for would present as the socket simply not working,
    /// which is the failure this setting exists to end.
    pub fn parse(mode: Option<&str>, group: Option<&str>) -> Result<Self, String> {
        let group = group
            .map(str::trim)
            .filter(|group| !group.is_empty())
            .map(str::to_string);
        let Some(configured) = mode.map(str::trim).filter(|mode| !mode.is_empty()) else {
            return Ok(Self {
                group,
                ..Self::default()
            });
        };
        // `0660`, `660` and `0o660` all mean the same thing to an operator.
        let digits = configured
            .strip_prefix("0o")
            .or_else(|| configured.strip_prefix("0O"))
            .unwrap_or(configured);
        let mode = u32::from_str_radix(digits, 8)
            .map_err(|_| format!("LISTEN_UNIX_SOCKET_MODE must be octal, got {configured}"))?;
        if mode > WIDEST_MODE {
            return Err(format!(
                "LISTEN_UNIX_SOCKET_MODE {configured} grants more than 0666"
            ));
        }
        Ok(Self { mode, group })
    }

    /// How the applied access reads in a log line.
    #[must_use]
    pub fn describe(&self) -> String {
        self.group.as_ref().map_or_else(
            || format!("mode {:04o}", self.mode),
            |group| format!("mode {:04o}, group {group}", self.mode),
        )
    }
}

/// Where the router should listen, in addition to its TCP port.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SocketSetup {
    /// No socket; the router listens on TCP only, as it always has.
    Disabled,
    /// Serve on this path as well, with this access.
    Enabled { path: PathBuf, access: SocketAccess },
}

impl SocketSetup {
    /// The path this setup serves on, if any.
    #[must_use]
    pub fn path(&self) -> Option<&Path> {
        match self {
            Self::Disabled => None,
            Self::Enabled { path, .. } => Some(path),
        }
    }

    /// The access this setup applies, if it serves at all.
    #[must_use]
    pub const fn access(&self) -> Option<&SocketAccess> {
        match self {
            Self::Disabled => None,
            Self::Enabled { access, .. } => Some(access),
        }
    }
}

/// Resolve the socket setup from the `LISTEN_UNIX_SOCKET` family.
///
/// # Errors
///
/// Returns a message when the configured mode cannot be honoured.
pub fn from_env() -> Result<SocketSetup, String> {
    resolve(
        crate::operation_context::var("LISTEN_UNIX_SOCKET")
            .ok()
            .as_deref(),
        crate::operation_context::var("LISTEN_UNIX_SOCKET_MODE")
            .ok()
            .as_deref(),
        crate::operation_context::var("LISTEN_UNIX_SOCKET_GROUP")
            .ok()
            .as_deref(),
    )
}

/// Decide the setup from already-read settings.
///
/// Split from [`from_env`] so both branches are reachable in a test: this crate
/// forbids `unsafe`, and mutating the process environment is the only other way
/// to drive them.
///
/// # Errors
///
/// Returns a message when the mode is not octal or is wider than `0666`.
pub fn resolve(
    configured: Option<&str>,
    mode: Option<&str>,
    group: Option<&str>,
) -> Result<SocketSetup, String> {
    let Some(path) = configured.map(str::trim).filter(|path| !path.is_empty()) else {
        return Ok(SocketSetup::Disabled);
    };
    Ok(SocketSetup::Enabled {
        path: PathBuf::from(path),
        access: SocketAccess::parse(mode, group)?,
    })
}

/// The `gh` configuration that points at a socket.
///
/// Emitted for the operator to copy, because the setting lives in `gh`'s own
/// config file rather than an environment variable — which is exactly the step
/// the previous documentation left unstated.
#[must_use]
pub fn gh_configuration_hint(path: &Path) -> String {
    format!(
        "gh config set http_unix_socket {}\n\
         export GH_HOST=router.internal\n\
         export GH_ENTERPRISE_TOKEN=<router token>",
        path.display()
    )
}

/// Serve `app` on the configured socket, if one is configured.
///
/// Returns the task serving it so the caller can stop it on shutdown; `None`
/// means no socket was configured and the router listens on TCP only.
///
/// # Errors
///
/// Returns a message when the configured path cannot be bound, since a router
/// that silently skipped the socket it was told to serve would leave `gh` with
/// the certificate problem this exists to avoid.
pub async fn serve_configured(
    app: axum::Router,
    shutdown: impl std::future::Future<Output = ()> + Send + 'static,
) -> Result<Option<tokio::task::JoinHandle<()>>, String> {
    let SocketSetup::Enabled { path, access } = from_env()? else {
        return Ok(None);
    };
    let listener = bind(&path, &access).await?;
    // The access is reported, not just applied: an operator who widened it
    // needs to see what was granted, and one who did not needs to see why a
    // client of another uid cannot connect.
    tracing::info!(
        "Listening on unix socket {} ({})",
        path.display(),
        access.describe()
    );
    tracing::info!("Point gh at it:\n{}", gh_configuration_hint(&path));
    Ok(Some(tokio::spawn(async move {
        // Drained rather than aborted: this socket carries `gh` traffic, and
        // cutting a request that is already upstream is what an orderly stop
        // exists to avoid (issue #334).
        if let Err(error) = axum::serve(listener, app)
            .with_graceful_shutdown(shutdown)
            .await
        {
            tracing::error!("unix socket listener failed: {error}");
        }
    })))
}

/// Serve `app` on `path`, for a caller that already knows where.
///
/// # Errors
///
/// Returns a message when the path cannot be bound.
pub async fn serve_on(
    app: axum::Router,
    path: &Path,
    access: &SocketAccess,
) -> Result<tokio::task::JoinHandle<()>, String> {
    let listener = bind(path, access).await?;
    Ok(tokio::spawn(async move {
        if let Err(error) = axum::serve(listener, app).await {
            tracing::error!("unix socket listener failed: {error}");
        }
    }))
}

/// Bind a unix socket, replacing a stale one left by an earlier run.
///
/// A socket file outlives the process that made it, so a router that crashed
/// leaves a path that `bind` would refuse. Removing it is safe only because
/// nothing is listening: a live socket is detected first and reported, rather
/// than being unlinked out from under a running instance.
///
/// # Errors
///
/// Returns an operator-readable message when the path is in use by a live
/// listener, or when the socket cannot be created.
pub async fn bind(path: &Path, access: &SocketAccess) -> Result<tokio::net::UnixListener, String> {
    if path.exists() {
        if tokio::net::UnixStream::connect(path).await.is_ok() {
            return Err(format!(
                "{} is already served by a running instance",
                path.display()
            ));
        }
        std::fs::remove_file(path)
            .map_err(|error| format!("could not replace {}: {error}", path.display()))?;
    }
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        std::fs::create_dir_all(parent)
            .map_err(|error| format!("could not create {}: {error}", parent.display()))?;
    }
    let listener = tokio::net::UnixListener::bind(path)
        .map_err(|error| format!("could not listen on {}: {error}", path.display()))?;
    apply_access(path, access)?;
    Ok(listener)
}

/// Apply the configured access to a freshly bound socket.
///
/// Group first, then mode. The reverse order would briefly leave a `0660`
/// socket owned by the router's own primary group, which is a window — small,
/// but pointless to leave open when ordering costs nothing.
fn apply_access(path: &Path, access: &SocketAccess) -> Result<(), String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        if let Some(group) = &access.group {
            let gid = resolve_group(group)?;
            std::os::unix::fs::chown(path, None, Some(gid)).map_err(|error| {
                format!("could not set group {group} on {}: {error}", path.display())
            })?;
        }
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(access.mode))
            .map_err(|error| format!("could not restrict {}: {error}", path.display()))?;
    }
    let _ = (path, access);
    Ok(())
}

/// Resolve a group to a gid.
///
/// A numeric gid is taken as-is, which is the form a container deployment
/// uses: the sidecar and the task containers agree on a number, and a name
/// would have to exist identically in both images to mean the same thing.
#[cfg(unix)]
fn resolve_group(group: &str) -> Result<u32, String> {
    if let Ok(gid) = group.parse::<u32>() {
        return Ok(gid);
    }
    group_id_by_name(group)
        .ok_or_else(|| format!("LISTEN_UNIX_SOCKET_GROUP {group} is not a known group"))
}

/// Look a group name up in the local group database.
///
/// Read from `/etc/group` rather than through `getgrnam`, because this crate
/// denies `unsafe` and the safe wrappers for it all mean a new dependency for
/// one lookup. A container image that defines the group in the usual place is
/// served; anything more exotic can give the numeric gid, which is the form
/// that deployment wants anyway.
#[cfg(unix)]
fn group_id_by_name(group: &str) -> Option<u32> {
    let database = std::fs::read_to_string("/etc/group").ok()?;
    database.lines().find_map(|line| {
        let mut fields = line.split(':');
        let name = fields.next()?;
        let _password = fields.next()?;
        let gid = fields.next()?;
        (name == group).then(|| gid.parse().ok())?
    })
}

