//! Upstream usage extraction for per-token spend budgets.
//!
//! # Counting rule
//!
//! A budget is charged for every token the upstream processed: all input
//! tokens, cached or not, plus all output tokens (issue #671).
//!
//! - Anthropic reports cache tokens beside `input_tokens`, so
//!   `cache_creation_input_tokens` and `cache_read_input_tokens` are added to it.
//! - `OpenAI` Chat (`prompt_tokens`), Responses (`input_tokens`) and Gemini
//!   (`promptTokenCount`) already include their cached tokens, which are only
//!   broken out in `*_details` / `cachedContentTokenCount`, so nothing is added.
//! - A vendor `total_tokens` / `totalTokenCount` is used when present.
//!
//! A stream that ends before the upstream's final usage report (a client
//! disconnect, an upstream reset or a stall) is charged at least an estimate of
//! the output it streamed, about four characters per token (issue #668).

use serde_json::Value;

use crate::token::TokenManager;

/// Extract input plus output tokens from one vendor JSON payload.
#[must_use]
pub fn token_count(value: &crate::translation_core::Json) -> crate::translation_core::Maybe<u64> {
    let (total, input, output) = token_parts(value)?;
    total.or_else(|| Some(input.unwrap_or(0).saturating_add(output.unwrap_or(0))))
}

fn token_parts(value: &crate::translation_core::Json) -> crate::translation_core::Maybe<(crate::translation_core::Maybe<u64>, crate::translation_core::Maybe<u64>, crate::translation_core::Maybe<u64>)> {
    if let Some(usage) = value.get("usage") {
        if let Some(total) = usage.get("total_tokens").and_then(crate::translation_core::Json::as_u64) {
            return Some((Some(total), None, None));
        }
        let input = first_u64(usage, &["input_tokens", "prompt_tokens"]).map(|input| {
            ["cache_creation_input_tokens", "cache_read_input_tokens"]
                .iter()
                .filter_map(|field| usage.get(*field).and_then(crate::translation_core::Json::as_u64))
                .fold(input, u64::saturating_add)
        });
        let output = first_u64(usage, &["output_tokens", "completion_tokens"]);
        if input.is_some() || output.is_some() {
            return Some((None, input, output));
        }
    }
    if let Some(usage) = value.get("usageMetadata") {
        if let Some(total) = usage.get("totalTokenCount").and_then(crate::translation_core::Json::as_u64) {
            return Some((Some(total), None, None));
        }
        let input = usage.get("promptTokenCount").and_then(crate::translation_core::Json::as_u64);
        let output = usage.get("candidatesTokenCount").and_then(crate::translation_core::Json::as_u64);
        if input.is_some() || output.is_some() {
            return Some((None, input, output));
        }
    }
    value
        .get("response")
        .or_else(|| value.get("message"))
        .and_then(token_parts)
}

/// Characters of model output streamed by one SSE event, in any dialect.
fn streamed_output_chars(value: &crate::translation_core::Json) -> usize {
    let text_len = |value: Option<&Value>| {
        value
            .and_then(crate::translation_core::Json::as_str)
            .map_or(0, |text| text.chars().count())
    };
    match value.get("type").and_then(crate::translation_core::Json::as_str) {
        // Anthropic Messages.
        Some("content_block_delta") => {
            let delta = value.get("delta");
            ["text", "thinking", "partial_json"]
                .iter()
                .map(|field| text_len(delta.and_then(|delta| delta.get(*field))))
                .sum()
        }
        // OpenAI Responses: output text, reasoning and tool-argument deltas.
        Some(kind) if kind.starts_with("response.") && kind.rsplit('.').next() == Some("delta") => {
            text_len(value.get("delta"))
        }
        Some(_) => 0,
        None => {
            // OpenAI Chat Completions chunks.
            let chat: usize = value
                .get("choices")
                .and_then(crate::translation_core::Json::as_array)
                .into_iter()
                .flatten()
                .filter_map(|choice| choice.get("delta"))
                .map(|delta| {
                    let arguments: usize = delta
                        .get("tool_calls")
                        .and_then(crate::translation_core::Json::as_array)
                        .into_iter()
                        .flatten()
                        .map(|call| text_len(call.pointer("/function/arguments")))
                        .sum();
                    ["content", "reasoning_content", "reasoning"]
                        .iter()
                        .map(|field| text_len(delta.get(*field)))
                        .sum::<usize>()
                        + arguments
                })
                .sum();
            // Gemini, bare or inside the Code Assist `response` envelope.
            let gemini_value = value.get("response").unwrap_or(value);
            let gemini: usize = gemini_value
                .get("candidates")
                .and_then(crate::translation_core::Json::as_array)
                .into_iter()
                .flatten()
                .filter_map(|candidate| {
                    candidate
                        .pointer("/content/parts")
                        .and_then(crate::translation_core::Json::as_array)
                })
                .flatten()
                .map(|part| text_len(part.get("text")))
                .sum();
            chat + gemini
        }
    }
}

/// Whether one SSE event carries the upstream's final usage for the turn.
fn reports_final_usage(value: &crate::translation_core::Json) -> bool {
    match value.get("type").and_then(crate::translation_core::Json::as_str) {
        Some("message_delta") => value.get("usage").is_some_and(crate::translation_core::Json::is_object),
        Some("response.completed" | "response.incomplete" | "response.failed") => true,
        Some(_) => false,
        None => {
            // OpenAI sends a usage object only on the final chunk.
            if value.get("usage").is_some_and(crate::translation_core::Json::is_object) {
                return true;
            }
            let gemini_value = value.get("response").unwrap_or(value);
            gemini_value.get("usageMetadata").is_some()
                && gemini_value
                    .get("candidates")
                    .and_then(crate::translation_core::Json::as_array)
                    .is_some_and(|candidates| {
                        candidates
                            .iter()
                            .any(|candidate| candidate.get("finishReason").is_some())
                    })
        }
    }
}

/// Characters per estimated output token for a stream cut short.
const ESTIMATED_CHARS_PER_TOKEN: u64 = 4;

/// The usage a [`UsageTracker`] settles.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Settlement {
    /// Tokens charged against the budget.
    pub tokens: u64,
    /// Whether the output part was estimated from streamed content because
    /// the stream ended before the upstream reported its final usage.
    pub estimated: bool,
}

fn first_u64(value: &crate::translation_core::Json, fields: &[&crate::translation_core::Str]) -> crate::translation_core::Maybe<u64> {
    fields
        .iter()
        .find_map(|field| value.get(*field).and_then(crate::translation_core::Json::as_u64))
}

/// Incrementally collects usage from JSON or Server-Sent Events.
///
/// The accumulated count is persisted when the response stream completes or
/// the client disconnects and drops it.
pub struct UsageTracker {
    manager: TokenManager,
    token_id: String,
    json_body: Vec<u8>,
    buffer: Vec<u8>,
    total_tokens: u64,
    input_tokens: u64,
    output_tokens: u64,
    saw_sse: bool,
    /// Characters of model output relayed so far.
    streamed_chars: u64,
    /// Whether the upstream reported its final usage for the turn.
    saw_final_usage: bool,
    /// Spend reserved for this request at admission, released on drop.
    reserved_tokens: u64,
}

impl UsageTracker {
    #[must_use]
    pub fn new(manager: TokenManager, token_id: impl Into<String>) -> Self {
        Self::with_reservation(manager, token_id, 0)
    }

    /// Track a request that reserved `reserved_tokens` of spend budget.
    ///
    /// Dropping the tracker releases the reservation whether or not any usage
    /// was reported, so cancelled requests, upstream errors, and responses with
    /// no usage block all return their budget (issue #195).
    #[must_use]
    pub fn with_reservation(
        manager: TokenManager,
        token_id: impl Into<String>,
        reserved_tokens: u64,
    ) -> Self {
        Self {
            manager,
            token_id: token_id.into(),
            json_body: Vec::new(),
            buffer: Vec::new(),
            total_tokens: 0,
            input_tokens: 0,
            output_tokens: 0,
            saw_sse: false,
            streamed_chars: 0,
            saw_final_usage: false,
            reserved_tokens,
        }
    }

    /// Feed the next raw response chunk.
    pub fn feed(&mut self, bytes: &[u8]) {
        if !self.saw_sse {
            self.json_body.extend_from_slice(bytes);
        }
        self.buffer.extend_from_slice(bytes);
        while let Some(newline) = self.buffer.iter().position(|byte| *byte == b'\n') {
            let mut line: Vec<u8> = self.buffer.drain(..=newline).collect();
            while matches!(line.last(), Some(b'\n' | b'\r')) {
                line.pop();
            }
            let Some(data) = line.strip_prefix(b"data:") else {
                continue;
            };
            self.saw_sse = true;
            self.json_body.clear();
            self.add_json(data.strip_prefix(b" ").unwrap_or(data));
        }
    }

    fn add_json(&mut self, bytes: &[u8]) {
        if bytes == b"[DONE]" {
            return;
        }
        let Ok(value) = serde_json::from_slice::<Value>(bytes) else {
            return;
        };
        if self.saw_sse {
            self.streamed_chars = self
                .streamed_chars
                .saturating_add(streamed_output_chars(&value) as u64);
            self.saw_final_usage |= reports_final_usage(&value);
        } else {
            // A complete JSON body carries the final usage by definition.
            self.saw_final_usage = true;
        }
        if let Some((total, input, output)) = token_parts(&value) {
            self.total_tokens = self.total_tokens.max(total.unwrap_or(0));
            self.input_tokens = self.input_tokens.max(input.unwrap_or(0));
            self.output_tokens = self.output_tokens.max(output.unwrap_or(0));
        }
    }

    /// The usage this tracker would settle now.
    ///
    /// When a stream ended before the upstream's final usage report, output
    /// is at least an estimate from the streamed content, so a disconnect
    /// mid-stream is never charged as almost free (issue #668).
    #[must_use]
    pub fn settlement(&self) -> Settlement {
        let estimate = if self.saw_sse && !self.saw_final_usage {
            self.streamed_chars.div_ceil(ESTIMATED_CHARS_PER_TOKEN)
        } else {
            0
        };
        let estimated = estimate > self.output_tokens;
        let output = self.output_tokens.max(estimate);
        let tokens = if estimated {
            // A total reported before the cut cannot include the estimate.
            self.input_tokens
                .saturating_add(output)
                .max(self.total_tokens)
        } else {
            self.total_tokens
                .max(self.input_tokens.saturating_add(self.output_tokens))
        };
        Settlement { tokens, estimated }
    }
}

/// Holds a spend reservation until it is either handed to a [`UsageTracker`] or
/// released.
///
/// A request can leave the handler on many paths — upstream failure, a
/// translation error, a client disconnect — and each one must give the reserved
/// budget back or the cap leaks until restart. Binding the reservation to a
/// guard makes the release automatic: every early return drops it, and the
/// success path calls [`ReservationGuard::into_tracker`] so the reservation is
/// settled together with the real usage instead.
pub struct ReservationGuard {
    manager: TokenManager,
    token_id: String,
    reserved_tokens: u64,
}

impl ReservationGuard {
    #[must_use]
    pub fn new(manager: TokenManager, token_id: impl Into<String>, reserved_tokens: u64) -> Self {
        Self {
            manager,
            token_id: token_id.into(),
            reserved_tokens,
        }
    }

    /// Tokens reserved for this request.
    #[must_use]
    pub const fn reserved(&self) -> u64 {
        self.reserved_tokens
    }

    /// Hand the reservation to a usage tracker, which settles it with the
    /// actual usage once the response completes.
    #[must_use]
    pub fn into_tracker(mut self) -> UsageTracker {
        let reserved = std::mem::take(&mut self.reserved_tokens);
        UsageTracker::with_reservation(self.manager.clone(), self.token_id.clone(), reserved)
    }

    /// Detach the reservation, leaving this guard with nothing left to release.
    ///
    /// Lets a handler that only has a mutable borrow move the reservation into
    /// a tracker while the original guard stays in scope.
    #[must_use]
    pub fn take(&mut self) -> Self {
        Self {
            manager: self.manager.clone(),
            token_id: self.token_id.clone(),
            reserved_tokens: std::mem::take(&mut self.reserved_tokens),
        }
    }

    /// Release the reservation now, recording `actual` usage against it.
    ///
    /// Used by non-streaming paths that already have the complete response.
    pub fn settle(mut self, actual: u64) {
        let reserved = std::mem::take(&mut self.reserved_tokens);
        if let Err(error) = self
            .manager
            .settle_token_usage(&self.token_id, reserved, actual)
        {
            tracing::warn!(token_id = %self.token_id, "failed to persist token usage: {error}");
        }
    }
}

impl Drop for ReservationGuard {
    fn drop(&mut self) {
        if self.reserved_tokens == 0 {
            return;
        }
        let reserved = std::mem::take(&mut self.reserved_tokens);
        if let Err(error) = self.manager.settle_token_usage(&self.token_id, reserved, 0) {
            tracing::warn!(token_id = %self.token_id, "failed to release token reservation: {error}");
        }
    }
}

impl Drop for UsageTracker {
    fn drop(&mut self) {
        if !self.saw_sse {
            let body = std::mem::take(&mut self.json_body);
            self.add_json(&body);
        } else if !self.buffer.is_empty() {
            let remaining = std::mem::take(&mut self.buffer);
            let data = remaining
                .strip_prefix(b"data:")
                .and_then(|value| value.strip_prefix(b" "))
                .unwrap_or(&remaining);
            self.add_json(data);
        }
        let Settlement { tokens, estimated } = self.settlement();
        if estimated {
            tracing::info!(
                token_id = %self.token_id,
                tokens,
                estimated = true,
                "stream ended before the upstream reported final usage; settling an estimate"
            );
        }
        // Settle unconditionally: a request that reported no usage still has to
        // give its reservation back, or the budget leaks until restart.
        if (tokens > 0 || self.reserved_tokens > 0)
            && let Err(error) =
                self.manager
                    .settle_token_usage(&self.token_id, self.reserved_tokens, tokens)
        {
            tracing::warn!(token_id = %self.token_id, "failed to persist token usage: {error}");
        }
    }
}

