//! Cleanup and permission helpers for temporary wrapper directories.

use std::fs::{self, TryLockError};
use std::path::Path;
#[cfg(unix)]
use std::process::Stdio;

pub(super) struct DisposableRunDirectory {
    directory: tempfile::TempDir,
    _lease: fs::File,
}

impl DisposableRunDirectory {
    pub(super) fn create(prefix: &str) -> Result<Self, std::io::Error> {
        let directory = tempfile::Builder::new().prefix(prefix).tempdir()?;
        set_directory_owner_only(directory.path())?;
        let lease_path = directory.path().join(".active.lock");
        let mut options = fs::OpenOptions::new();
        options.read(true).write(true).create(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;
            options.mode(0o600);
        }
        let lease = options.open(lease_path)?;
        lease.lock()?;
        sweep_stale_directories(directory.path());
        Ok(Self {
            directory,
            _lease: lease,
        })
    }

    pub(super) fn path(&self) -> &Path {
        self.directory.path()
    }
}

/// Remove leftovers from runs of *this user* that are no longer alive.
///
/// A pid is not a liveness token across a trust boundary. On a shared `TMPDIR`
/// — the usual `/tmp`, any multi-user host, a build agent running jobs as
/// different users — `kill(pid, 0)` on another user's live process fails with
/// `EPERM`, and treating any failure as "dead" deleted that run's working
/// directory, client configuration and credential while it was in use (issue
/// #313). So ownership is checked first, and a process that exists but is not
/// ours counts as alive.
///
/// `ours` is a directory this run just created, used as the reference for
/// "mine": comparing owners needs no privileged call and no `unsafe`.
/// Only its siblings are candidates. Production creates `ours` in `TMPDIR`;
/// tests can use independent roots without changing the process environment.
pub(super) fn sweep_stale_directories(ours: &Path) {
    const PREFIX: &str = "link-assistant-router-with-";
    let Some(uid) = owner_of(ours) else {
        return;
    };
    let Some(root) = ours.parent() else {
        return;
    };
    let Ok(entries) = fs::read_dir(root) else {
        return;
    };
    for entry in entries.flatten() {
        let name = entry.file_name();
        let name = name.to_string_lossy();
        let Some(rest) = name.strip_prefix(PREFIX) else {
            continue;
        };
        let Some(pid) = rest.split('-').next().and_then(|value| value.parse().ok()) else {
            continue;
        };
        if entry.path() == ours
            || owner_of(&entry.path()) != Some(uid)
            || run_is_active(&entry.path(), pid)
        {
            continue;
        }
        if fs::remove_dir_all(entry.path()).is_ok() {
            eprintln!("note: removed a leftover run directory from process {pid}");
        }
    }
}

fn run_is_active(path: &Path, pid: u32) -> bool {
    let lease = match fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(path.join(".active.lock"))
    {
        Ok(lease) => lease,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return process_alive(pid),
        // A lease that cannot be inspected is not proof that a run is stale.
        Err(_) => return true,
    };
    match lease.try_lock() {
        Ok(()) => {
            let _ = lease.unlock();
            false
        }
        Err(TryLockError::WouldBlock | TryLockError::Error(_)) => true,
    }
}

/// The numeric owner of a path, where the platform has one.
///
/// `None` on non-unix, where every directory compares equal and the liveness
/// check decides alone — there is no shared `TMPDIR` in the same sense.
pub(super) fn owner_of(path: &Path) -> Option<u32> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt as _;

        fs::metadata(path).ok().map(|metadata| metadata.uid())
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        Some(0)
    }
}

/// Whether the process might still be running.
///
/// "Might" is the contract: a check that cannot tell "gone" from "not yours"
/// must answer alive, because the cost of being wrong is deleting a live run's
/// files, and the cost of being right late is one directory swept next time.
pub(super) fn process_alive(pid: u32) -> bool {
    if pid == std::process::id() {
        return true;
    }
    #[cfg(unix)]
    {
        let signalled = crate::operation_context::process_output(
            crate::operation_context::command("kill")
                .args(["-0", &pid.to_string()])
                .stdout(Stdio::null())
                .stderr(Stdio::null()),
        )
        .is_ok_and(|output| output.status.success());
        if signalled {
            return true;
        }
        // `kill -0` fails both for "no such process" and for a live process
        // owned by somebody else. `ps` answers the question that was actually
        // asked — does this pid exist — for any owner, so `EPERM` can no
        // longer read as "dead" (issue #313).
        crate::operation_context::process_output(
            crate::operation_context::command("ps")
                .args(["-p", &pid.to_string()])
                .stdout(Stdio::piped())
                .stderr(Stdio::null()),
        )
        .is_ok_and(|output| {
            String::from_utf8_lossy(&output.stdout)
                .lines()
                .filter(|line| !line.trim().is_empty())
                .count()
                > 1
        })
    }
    #[cfg(windows)]
    {
        crate::operation_context::process_output(
            crate::operation_context::command("tasklist").args([
                "/FI",
                &format!("PID eq {pid}"),
                "/NH",
            ]),
        )
        .is_ok_and(|output| {
            output.status.success()
                && String::from_utf8_lossy(&output.stdout).contains(&pid.to_string())
        })
    }
}

pub(super) fn set_directory_owner_only(path: &Path) -> Result<(), std::io::Error> {
    #[cfg(not(unix))]
    let _ = path;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        fs::set_permissions(path, fs::Permissions::from_mode(0o700))?;
    }
    Ok(())
}

//! Process-local Codex catalog projection for `router with`.

use std::path::{Path, PathBuf};

use serde_json::{Value, json};

use super::AnyError;
use crate::clients::RouterModel;

/// Write the live Router catalog as a complete process-local Codex catalog,
/// preventing foreign model ids without changing the user's configuration.
pub(super) fn write_codex_model_catalog(
    root: &Path,
    models: &[RouterModel],
    configured_effort: Option<&str>,
    selected_model: Option<&str>,
) -> Result<PathBuf, AnyError> {
    if models.is_empty() {
        return Err("the Router advertised no models for Codex".into());
    }
    let mut listed = Vec::with_capacity(models.len());
    let mut omitted = Vec::new();
    for model in models {
        match validate_codex_reasoning_metadata(model) {
            Ok(()) => listed.push(model),
            Err(error) if selected_model == Some(model.id.as_str()) => return Err(error),
            Err(error) => omitted.push((model.id.as_str(), error.to_string())),
        }
    }
    if !omitted.is_empty() {
        let ids = omitted
            .iter()
            .map(|(id, _)| *id)
            .collect::<Vec<_>>()
            .join(", ");
        eprintln!(
            "warning: omitted Codex model(s) with inconsistent reasoning metadata: {ids}; \
             the other models remain available"
        );
    }
    if listed.is_empty() {
        let ids = omitted
            .iter()
            .map(|(id, _)| *id)
            .collect::<Vec<_>>()
            .join(", ");
        return Err(format!(
            "the live Codex catalog has no model with consistent reasoning metadata; \
             omitted: {ids}"
        )
        .into());
    }
    if let (Some(effort), Some(selected)) = (configured_effort, selected_model) {
        let model = listed
            .iter()
            .copied()
            .find(|model| model.id == selected)
            .ok_or_else(|| format!("the Router advertised no Codex model named `{selected}`"))?;
        if !model_may_keep_reasoning_effort(model, effort) {
            return Err(format!(
                "Codex model `{selected}` does not support configured reasoning effort \
                 `{effort}`; choose a supported model or change `model_reasoning_effort`"
            )
            .into());
        }
    }
    let compatible = listed
        .into_iter()
        .filter(|model| {
            configured_effort.is_none_or(|effort| model_may_keep_reasoning_effort(model, effort))
        })
        .collect::<Vec<_>>();
    if compatible.is_empty() {
        let effort = configured_effort.expect("an unfiltered non-empty catalog stays non-empty");
        return Err(format!(
            "the live Codex catalog has no model supporting configured reasoning effort \
             `{effort}`; change `model_reasoning_effort` and retry"
        )
        .into());
    }
    let entries = compatible
        .iter()
        .enumerate()
        .map(|(index, model)| codex_entry(model, configured_effort, index))
        .collect::<Vec<_>>();
    let path = root.join("router-codex-models.json");
    let rendered = format!(
        "{}\n",
        serde_json::to_string_pretty(&json!({"models": entries}))?
    );
    crate::durable_file::atomic_write_owner_only(&path, rendered.as_bytes())?;
    Ok(path)
}

/// One Codex catalog entry for `model`.
///
/// A row whose provider publishes no reasoning metadata (every z.ai row today)
/// is listed rather than refused (issue #628): unknown is not unsupported. It
/// claims no levels, and its default is the user's configured effort, or none.
/// Codex 0.158 keeps an effort across `/model` only when the chosen row lists
/// it and otherwise falls back to that row's default, so this keeps the user's
/// setting on startup and on every switch without inventing a capability.
fn codex_entry(model: &RouterModel, configured_effort: Option<&str>, index: usize) -> Value {
    let Some(supported) = model.supported_reasoning_levels.as_ref() else {
        let mut entry = crate::codex_catalog::model_info(
            &crate::codex_catalog::ModelDescription {
                id: &model.id,
                display_name: &model.id,
                owner: &model.owned_by,
                default_reasoning_level: configured_effort.map(|effort| json!(effort)),
                supported_reasoning_levels: json!([]),
            },
            index,
        );
        entry["description"] = json!(format!(
            "{} via Link.Assistant.Router; reasoning metadata unavailable, so Codex keeps \
             your configured reasoning effort",
            model.owned_by
        ));
        return entry;
    };
    crate::codex_catalog::model_info(
        &crate::codex_catalog::ModelDescription {
            id: &model.id,
            display_name: &model.id,
            owner: &model.owned_by,
            default_reasoning_level: model.default_reasoning_level.clone().map(Value::String),
            supported_reasoning_levels: serde_json::to_value(supported)
                .expect("reasoning metadata serializes"),
        },
        index,
    )
}

/// Refuse metadata that contradicts itself. Absent metadata is not refused.
fn validate_codex_reasoning_metadata(model: &RouterModel) -> Result<(), AnyError> {
    let Some(supported) = model.supported_reasoning_levels.as_ref() else {
        return Ok(());
    };
    if let Some(default) = model.default_reasoning_level.as_deref()
        && !supported.iter().any(|level| level.effort == default)
    {
        return Err(format!(
            "the live Codex catalog reports unsupported default reasoning level `{default}` \
             for model `{}`",
            model.id
        )
        .into());
    }
    Ok(())
}

/// Whether choosing `model` keeps `effort`: a listed level does, and so does a
/// row with unknown levels, which carries the effort as its default.
fn model_may_keep_reasoning_effort(model: &RouterModel, effort: &str) -> bool {
    model
        .supported_reasoning_levels
        .as_ref()
        .is_none_or(|levels| levels.iter().any(|level| level.effort == effort))
}

//! Process-local Claude settings for `router with`.
//!
//! Split from `with_command.rs` to stay inside the repository's per-file line
//! limit.

use std::fs;
use std::path::Path;
use std::process::Command;

use serde_json::{Value, json};

use super::AnyError;
use crate::clients::{ClientKind, RouterModel};

pub(super) struct ClaudeModelSelection {
    pub model: String,
    pub reason: String,
}

/// A built-in Claude family is unavailable when this token has no Anthropic
/// model in its live catalog. Concrete IDs are never classified by spelling;
/// their exact authenticated catalog row decides ownership.
pub(super) fn unavailable_native_claude_model<'a>(
    model: &'a str,
    models: &[RouterModel],
) -> Option<&'a str> {
    let family = model
        .trim()
        .split_once('[')
        .map_or_else(|| model.trim(), |(family, _)| family)
        .to_ascii_lowercase();
    let native = matches!(family.as_str(), "opus" | "sonnet" | "haiku");
    let has_anthropic = crate::clients::usable_models(ClientKind::ClaudeCode, models)
        .iter()
        .any(|candidate| candidate.owned_by == crate::clients::ANTHROPIC_MODEL_OWNER);
    (native && !has_anthropic).then_some(model)
}

pub(super) fn validate_claude_model_selection(
    selection: ClaudeModelSelection,
    models: &[RouterModel],
) -> Result<Option<String>, AnyError> {
    let model = selection.model.trim();
    let catalog_model = model
        .split_once('[')
        .map_or(model, |(model, _)| model)
        .trim();
    let has_anthropic = crate::clients::usable_models(ClientKind::ClaudeCode, models)
        .iter()
        .any(|candidate| candidate.owned_by == crate::clients::ANTHROPIC_MODEL_OWNER);
    // Claude's saved `default` is semantic rather than an upstream ID. On a
    // z.ai-only catalog, Router's main/subagent fallback is how that semantic
    // choice remains usable.
    if model.eq_ignore_ascii_case("default") && !has_anthropic {
        return Ok(None);
    }
    if let Some(unavailable) = unavailable_native_claude_model(model, models) {
        return Err(format!(
            "Claude model `{unavailable}` requires an Anthropic provider, but this client's \
             authorized live catalog contains none; choose one of the visible exact models with \
             /model, configure Anthropic, or clear the stale model selection"
        )
        .into());
    }
    let native_family = ["default", "opus", "sonnet", "haiku"]
        .iter()
        .any(|family| catalog_model.eq_ignore_ascii_case(family));
    let exact = crate::clients::usable_models(ClientKind::ClaudeCode, models)
        .iter()
        .any(|candidate| candidate.id == catalog_model)
        && !model.ends_with("[1m]");
    let context_variant = crate::clients::claude_context_variant_is_authorized(models, model);
    if (native_family && has_anthropic) || exact || context_variant {
        return Ok(Some(selection.reason));
    }
    Err(format!(
        "Claude model `{model}` is not in this client's authorized live catalog; choose one of \
         the visible exact models with /model or clear the stale model selection"
    )
    .into())
}

/// Build the process-local Claude settings a Router-directed launch needs.
///
/// Two things live here: the presentation default that keeps a completed
/// thinking trace visible (issue #560), and the `/model` picker rows for every
/// exact model this client's authorized live catalog can serve (issue #621).
///
/// Claude's own gateway discovery keeps only `claude`/`anthropic`-shaped IDs,
/// so the picker is filled from the Router catalog instead: every usable row,
/// Anthropic's exact IDs included when Anthropic is authorized. A row is
/// `{label, model}`, which Claude Code accepts on its own; `behavesAs` is
/// optional there and is added only when Router holds verified capability
/// metadata for that exact ID. Requiring it made a z.ai-only catalog — whose
/// rows never carry it — refuse to launch at all (issue #620). Nothing is
/// inferred from a model's spelling.
///
/// This is a command-line setting for this process only: neither the
/// Router-owned profile nor the user's profile is rewritten, so the next
/// launch lists whatever the authorized catalog holds then.
pub(super) fn append_claude_model_picker(
    command: &mut Command,
    models: &[RouterModel],
) -> Result<(), AnyError> {
    let (options, has_anthropic) = claude_model_picker_options(models);
    // Keeping a completed thinking trace on screen is a presentation default,
    // and the Router-owned profile starts empty by design (issue #536) — so it
    // carries none of the preferences the user's normal Claude profile has.
    // Genuine thinking was therefore visible while a response streamed and
    // collapsed to `Thought for Ns` the moment it finished, only under a bare
    // `router with claude` (issue #560). This restores the presentation the
    // same user gets from their own profile; it changes nothing about the
    // protocol, so a response that carries no thinking still shows none.
    //
    // Written unconditionally, not only when the picker has rows: a deployment
    // whose catalog needs no extra picker options is exactly as affected.
    let mut settings = serde_json::Map::new();
    settings.insert("verbose".into(), json!(true));
    if !options.is_empty() {
        settings.insert(
            "modelPicker".into(),
            json!({
                "options": options,
                // Native family rows are usable only when this exact client's
                // authorized live catalog contains Anthropic. In a z.ai-only
                // catalog, retaining them sends the next prompt to a provider
                // the token cannot reach (issue #577).
                "replaceBuiltInOptions": !has_anthropic,
            }),
        );
    }
    // Router's own `--settings` goes on before the user's forwarded arguments,
    // so an explicit `--settings` or `--verbose` of their own still wins: the
    // last occurrence is the one Claude applies.
    command
        .arg("--settings")
        .arg(serde_json::to_string(&Value::Object(settings))?);
    Ok(())
}

/// The picker rows for `models`, and whether Anthropic is among them.
///
/// Built-in family names are left to Claude's own rows. Duplicate catalog rows
/// for one exact ID collapse into one picker row; their capability metadata
/// is kept only when every row agrees, since a disagreement is not evidence.
fn claude_model_picker_options(models: &[RouterModel]) -> (Vec<Value>, bool) {
    const BUILT_INS: [&str; 4] = ["default", "opus", "sonnet", "haiku"];

    let usable = crate::clients::usable_models(ClientKind::ClaudeCode, models);
    let has_anthropic = usable
        .iter()
        .any(|model| model.owned_by == crate::clients::ANTHROPIC_MODEL_OWNER);
    let mut candidates = usable
        .into_iter()
        .filter(|model| {
            let folded = model.id.trim().to_ascii_lowercase();
            !folded.is_empty() && !BUILT_INS.contains(&folded.as_str())
        })
        .collect::<Vec<_>>();
    // Anthropic's own models first, then every other provider; each by ID.
    candidates.sort_by(|left, right| {
        let other = |model: &RouterModel| model.owned_by != crate::clients::ANTHROPIC_MODEL_OWNER;
        other(left)
            .cmp(&other(right))
            .then_with(|| left.id.cmp(&right.id))
    });
    let mut rows: Vec<(String, Option<String>)> = Vec::with_capacity(candidates.len());
    let unavailable = candidates
        .iter()
        .filter(|model| !model.is_servable())
        .map(|model| model.id.clone())
        .collect::<Vec<_>>();
    for model in candidates {
        let behaves_as = model
            .client_capabilities
            .claude
            .as_ref()
            .filter(|capability| {
                !capability.behaves_as.trim().is_empty() && !capability.source.trim().is_empty()
            })
            .map(|capability| capability.behaves_as.clone());
        match rows.iter_mut().find(|(id, _)| id == &model.id) {
            Some((_, existing)) if *existing != behaves_as => *existing = None,
            Some(_) => {}
            None => rows.push((model.id.clone(), behaves_as)),
        }
    }
    let options = rows
        .into_iter()
        .map(|(id, behaves_as)| {
            let mut row = serde_json::Map::new();
            // The row stays selectable — z.ai still lists it — but the label
            // says Router cannot serve it right now (issue #657).
            let label = if unavailable.contains(&id) {
                format!("{id} (unavailable)")
            } else {
                id.clone()
            };
            row.insert("label".into(), json!(label));
            row.insert("model".into(), json!(id));
            if let Some(behaves_as) = behaves_as {
                row.insert("behavesAs".into(), json!(behaves_as));
            }
            Value::Object(row)
        })
        .collect();
    (options, has_anthropic)
}

/// A warning for a launch whose model Router cannot serve right now, naming a
/// servable alternative (issue #657).
///
/// The launch is not refused: the request still reaches the provider, which
/// may have been recharged, and is answered with the provider's reason if not.
/// What the user must not get is a silent session on a model that cannot
/// answer.
///
/// The alternative is the user's last working selection when one is recorded
/// and still servable, otherwise the flagship of the servable catalog (issue
/// #684): the alphabetically first row was routinely the smallest model.
pub(super) fn claude_unavailable_model_warning(
    model: Option<&str>,
    models: &[RouterModel],
    last_working: Option<&str>,
) -> Option<String> {
    let model = model?.trim();
    let reason = models
        .iter()
        .filter(|candidate| candidate.id == model)
        .find_map(|candidate| candidate.router_unavailable_reason.as_deref())?;
    let usable = crate::clients::usable_models(ClientKind::ClaudeCode, models);
    let servable: Vec<&RouterModel> = usable
        .iter()
        .filter(|candidate| candidate.is_servable() && candidate.id != model)
        .collect();
    let remembered = last_working
        .map(str::trim)
        .and_then(|last| servable.iter().find(|candidate| candidate.id == last));
    let alternative = remembered
        .copied()
        .or_else(|| {
            servable
                .iter()
                .copied()
                .max_by(|left, right| flagship_order(left, right))
        })
        .map(|candidate| candidate.id.clone());
    let advice = alternative.map_or_else(
        || "no other model in this client's catalog is currently servable".to_string(),
        |alternative| {
            let why = if remembered.is_some() {
                "your last working selection"
            } else {
                "the most capable servable model"
            };
            format!(
                "choose another model with /model or --model, for example `{alternative}` \
                 ({why})"
            )
        },
    );
    Some(format!(
        "warning: Claude model `{model}` cannot be served right now: {reason}; {advice}"
    ))
}

/// Where a Router-owned profile remembers the last model a launch could serve.
const LAST_WORKING_MODEL: &str = "router-last-working-model";

/// The launch warning, reading and maintaining the last working selection in
/// the profile `root` (issue #684). A launch on a servable model records it,
/// so the next exhausted launch suggests what the user last used rather than a
/// model they never chose.
pub(super) fn claude_launch_model_warning(
    root: &Path,
    launched: Option<&str>,
    models: &[RouterModel],
) -> Option<String> {
    let path = root.join(LAST_WORKING_MODEL);
    let last_working = fs::read_to_string(&path).ok();
    let warning = claude_unavailable_model_warning(launched, models, last_working.as_deref());
    if warning.is_none()
        && let Some(launched) = launched.map(str::trim)
        && models
            .iter()
            .any(|candidate| candidate.id == launched && candidate.is_servable())
        && last_working.as_deref().map(str::trim) != Some(launched)
    {
        // Best effort: a profile that cannot be written only loses the hint.
        let _ = fs::write(&path, launched);
    }
    warning
}

/// Claude family rank: the flagship family first.
fn family_rank(id: &str) -> usize {
    let id = id.to_ascii_lowercase();
    ["haiku", "sonnet", "opus"]
        .iter()
        .position(|family| id.contains(family))
        .map_or(0, |position| position + 1)
}

/// The numeric version in a model id, ignoring date stamps such as
/// `20250514`: an id ending in `-4-1-20250805` is version `[4, 1]`.
fn version_of(id: &str) -> Vec<u32> {
    id.split(|character: char| !character.is_ascii_digit())
        .filter(|part| !part.is_empty() && part.len() < 6)
        .filter_map(|part| part.parse().ok())
        .collect()
}

/// Order by family, then version, then the provider's creation time, then id.
pub(super) fn flagship_order(left: &RouterModel, right: &RouterModel) -> std::cmp::Ordering {
    family_rank(&left.id)
        .cmp(&family_rank(&right.id))
        .then_with(|| version_of(&left.id).cmp(&version_of(&right.id)))
        .then_with(|| left.provider_created_at.cmp(&right.provider_created_at))
        .then_with(|| right.id.cmp(&left.id))
}

/// The Claude model the client itself has saved as its default, if any.
///
/// The returned exact model is validated against the authorized live catalog
/// before its human-readable reason is used in Router's note. A wrapper-set
/// `ANTHROPIC_MODEL` outranks the client's own selection for every new session,
/// so pinning over a valid saved `/model` choice silently overrode the
/// documented way to pick a model (issue #563). The environment half of that
/// rule is resolved by the caller.
///
/// The profile consulted is the one this launch actually hands the client — the
/// Router-owned one by default, the user's own under `--extend-global-config`.
/// The Router-owned profile is `CLAUDE_CONFIG_DIR` itself, so Claude keeps its
/// user settings, and a `/model` choice, directly in it. Reading the
/// `.claude/settings.json` a `$HOME`-rooted layout would use saw no choice at
/// all: the pin overrode it, and a choice the catalog no longer authorizes was
/// never refused (issue #630).
pub(super) fn claude_saved_model_selection(
    root: &Path,
    extends_user_configuration: bool,
    user_settings: Option<&Path>,
) -> Option<ClaudeModelSelection> {
    // Under `--extend-global-config` the client reads the user's real profile.
    // The caller resolved the file Claude will actually open from its own
    // environment, so nothing here reads the process environment and a test
    // cannot inherit a real profile (#613).
    let settings = if extends_user_configuration {
        user_settings?.to_path_buf()
    } else {
        root.join("settings.json")
    };
    let saved = fs::read_to_string(settings).ok()?;
    // A profile Claude has not written yet, or one hand-edited into invalid
    // JSON, is not a selection. Failing open here would pin over a choice; the
    // safe reading of "cannot tell" is to leave the pin to the catalog.
    let document: serde_json::Value = serde_json::from_str(&saved).ok()?;
    let model = document.get("model")?.as_str()?.trim();
    (!model.is_empty()).then(|| ClaudeModelSelection {
        model: model.to_string(),
        reason: format!("the model saved in your Claude profile ({model})"),
    })
}

//! Exact model authority established before a wrapped client starts.

use serde_json::json;

use crate::cli::WithArgs;
use crate::clients::ClientKind;
use crate::managed_server::{ResolvedServer, RunCredential};
use crate::model_contract::{
    ModelAccessPolicy, ModelRouteScope, ModelSelectorKind, ModelTruthDescriptor,
};

use super::AnyError;

pub(super) struct ModelRequest {
    forwarded: Option<String>,
    requested_policy: ModelAccessPolicy,
}

pub(super) struct PreparedModel {
    pub credential: RunCredential,
    pub selected: Option<String>,
}

/// Parse every selector before a credential can be minted.
pub(super) fn request(args: &WithArgs) -> Result<ModelRequest, AnyError> {
    let forwarded = crate::client_launch::forwarded_model(&args.client_args)?;
    if let (Some(wrapper), Some(client)) = (args.model.as_deref(), forwarded.as_deref())
        && wrapper != client
    {
        return Err(format!(
            "conflicting model selectors: router --model names `{wrapper}` but the client arguments name `{client}`; no token was minted and no client was launched"
        )
        .into());
    }
    if (!args.allowed_models.is_empty() || args.allow_model_substitution)
        && args.model.is_none()
        && forwarded.is_none()
        && !args.pick_model
    {
        return Err("--allow-model and --allow-model-substitution widen an explicit model grant; use --model, a forwarded client model argument, or --pick-model first; no token was minted and no client was launched".into());
    }
    let mut allowed_models = args
        .model
        .iter()
        .map(|model| crate::thinking::base_model(model).to_string())
        .chain(
            forwarded
                .iter()
                .map(|model| crate::thinking::base_model(model).to_string()),
        )
        .collect::<Vec<_>>();
    allowed_models.extend(
        args.allowed_models
            .iter()
            .map(|model| crate::thinking::base_model(model).to_string()),
    );
    allowed_models.sort();
    allowed_models.dedup();
    let requested_policy = ModelAccessPolicy {
        allowed_models,
        allow_substitution: args.allow_model_substitution,
        substitution_source: args
            .allow_model_substitution
            .then(|| "router with --allow-model-substitution".to_string()),
    };
    requested_policy.validate().map_err(|error| {
        format!("invalid exact-model token policy: {error}; no token was minted and no client was launched")
    })?;
    Ok(ModelRequest {
        forwarded,
        requested_policy,
    })
}

pub(super) async fn prepare(
    args: &WithArgs,
    server: &ResolvedServer,
    label: &str,
    request: ModelRequest,
) -> Result<PreparedModel, AnyError> {
    let ModelRequest {
        forwarded,
        requested_policy,
    } = request;
    // A picker needs the full catalog only until it makes a choice. Its
    // bootstrap credential is revoked and replaced before client launch.
    let mut policy = if args.pick_model {
        ModelAccessPolicy::default()
    } else {
        requested_policy
    };
    let mut credential = crate::managed_server::prepare_run_credential_with_model_policy(
        server,
        args.client,
        label,
        args.run_ttl_hours,
        !args.fixed_run_ttl,
        &policy,
    )
    .await?;
    let selected = match resolve(args, forwarded.as_deref(), &credential) {
        Ok(selected) => selected,
        Err(error) => {
            cleanup_after_setup_failure(credential).await;
            return Err(error);
        }
    };
    if args.pick_model
        && let Some(selected) = selected.as_deref()
        && !policy
            .allowed_models
            .iter()
            .any(|allowed| allowed == selected)
    {
        let mut allowed_models = vec![crate::thinking::base_model(selected).to_string()];
        allowed_models.extend(
            args.allowed_models
                .iter()
                .map(|model| crate::thinking::base_model(model).to_string()),
        );
        allowed_models.sort();
        allowed_models.dedup();
        let pinned = ModelAccessPolicy {
            allowed_models,
            allow_substitution: args.allow_model_substitution,
            substitution_source: args
                .allow_model_substitution
                .then(|| "router with --allow-model-substitution".to_string()),
        };
        let replacement = crate::managed_server::prepare_run_credential_with_model_policy(
            server,
            args.client,
            label,
            args.run_ttl_hours,
            !args.fixed_run_ttl,
            &pinned,
        )
        .await;
        let replacement = match replacement {
            Ok(replacement) => replacement,
            Err(error) => {
                cleanup_after_setup_failure(credential).await;
                return Err(error);
            }
        };
        cleanup_after_setup_failure(credential).await;
        credential = replacement;
        policy = pinned;
    }
    if let Err(error) = validate_selection(args, selected.as_deref(), &credential, &policy) {
        cleanup_after_setup_failure(credential).await;
        return Err(error);
    }
    print_diagnostic(
        args,
        server,
        &credential,
        selected.as_deref(),
        forwarded.as_deref(),
        &policy,
    );
    Ok(PreparedModel {
        credential,
        selected,
    })
}

fn resolve(
    args: &WithArgs,
    forwarded: Option<&str>,
    credential: &RunCredential,
) -> Result<Option<String>, AnyError> {
    if let Some(model) = args.model.clone().or_else(|| forwarded.map(str::to_string)) {
        return Ok(Some(model));
    }
    if !args.pick_model {
        if crate::client_launch::requires_a_model(args.client) {
            return Err(format!(
                "{} requires an explicit model in its Router configuration; pass --model with an exact catalog id, or opt in to Router selection with --pick-model",
                args.client.display_name()
            )
            .into());
        }
        return Ok(None);
    }
    if let Some(model) = crate::clients::select_model(args.client, credential.models()) {
        let owners = args.client.integration().model_owners;
        eprintln!(
            "note: --pick-model chose `{model}`, the first {} model the router advertises; pass --model to choose another",
            if owners.is_empty() {
                "advertised".to_string()
            } else {
                owners.join(" or ")
            }
        );
        return Ok(Some(model.to_string()));
    }
    Err(crate::clients::model_unavailable(args.client, credential.models()).into())
}

fn validate_selection(
    args: &WithArgs,
    selected: Option<&str>,
    credential: &RunCredential,
    policy: &ModelAccessPolicy,
) -> Result<(), AnyError> {
    if let Some(model) = selected
        && args.client == ClientKind::ClaudeCode
        && let Some(unavailable) = super::unavailable_native_claude_model(
            crate::thinking::base_model(model),
            credential.models(),
        )
    {
        return Err(format!(
            "Claude model `{unavailable}` requires an Anthropic provider, but this client's authorized live catalog contains none; choose a visible exact model with --model or configure Anthropic"
        )
        .into());
    }
    for allowed in &policy.allowed_models {
        crate::managed_server::ensure_model_available(credential, args.client, allowed)?;
    }
    if let Some(model) = selected {
        crate::managed_server::ensure_model_available(
            credential,
            args.client,
            crate::thinking::base_model(model),
        )?;
    }
    Ok(())
}

fn print_diagnostic(
    args: &WithArgs,
    server: &ResolvedServer,
    credential: &RunCredential,
    selected: Option<&str>,
    forwarded: Option<&str>,
    policy: &ModelAccessPolicy,
) {
    eprintln!(
        "{}",
        launch_diagnostic(args, server, credential, selected, forwarded, policy)
    );
}

fn launch_diagnostic(
    args: &WithArgs,
    server: &ResolvedServer,
    credential: &RunCredential,
    selected: Option<&str>,
    forwarded: Option<&str>,
    policy: &ModelAccessPolicy,
) -> serde_json::Value {
    let advertised = selected
        .map(crate::thinking::base_model)
        .and_then(|selected| {
            credential.models().iter().find(|model| {
                model.id == selected
                    || selected
                        .strip_suffix("[1m]")
                        .is_some_and(|base| model.id == base)
            })
        });
    let request_source = if args.model.is_some() {
        "with --model"
    } else if forwarded.is_some() {
        "forwarded client model argument"
    } else if args.pick_model {
        "with --pick-model"
    } else {
        "client configuration"
    };
    let evidence_scope = advertised
        .and_then(|model| model.capability_provenance.get("scope"))
        .and_then(serde_json::Value::as_object);
    let scoped_provider = evidence_scope
        .and_then(|scope| scope.get("provider"))
        .and_then(serde_json::Value::as_str);
    let scoped_account = evidence_scope
        .and_then(|scope| scope.get("account"))
        .and_then(serde_json::Value::as_str);
    let scoped_endpoint = evidence_scope
        .and_then(|scope| scope.get("endpoint"))
        .and_then(serde_json::Value::as_str);
    let scoped_protocols = evidence_scope
        .and_then(|scope| scope.get("protocols"))
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let capabilities = advertised
        .and_then(|model| model.capability_provenance.get("fields"))
        .and_then(serde_json::Value::as_object)
        .map(|fields| {
            fields
                .iter()
                .map(|(field, evidence)| {
                    (
                        field.clone(),
                        evidence
                            .get("value")
                            .cloned()
                            .unwrap_or(serde_json::Value::Null),
                    )
                })
                .collect::<serde_json::Map<_, _>>()
        })
        .map_or(serde_json::Value::Null, serde_json::Value::Object);
    let descriptor = ModelTruthDescriptor {
        requested_selector: selected.map(str::to_string),
        selector_kind: advertised.map_or(ModelSelectorKind::Unknown, |model| model.selector_kind),
        route: ModelRouteScope {
            provider: scoped_provider
                .or_else(|| advertised.map(|model| model.owned_by.as_str()))
                .map(str::to_string),
            account: scoped_account
                .or_else(|| Some(credential.principal_id()))
                .map(str::to_string),
            endpoint: scoped_endpoint.map(str::to_string),
            protocols: scoped_protocols
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(serde_json::Value::as_str)
                .map(str::to_string)
                .collect(),
        },
        upstream_request_model: selected
            .map(crate::thinking::base_model)
            .map(str::to_string),
        upstream_served_model: None,
        capabilities,
        capability_provenance: advertised.map_or(serde_json::Value::Null, |model| {
            model.capability_provenance.clone()
        }),
        allow_substitution: policy.allow_substitution,
        substitution_source: policy.substitution_source.clone(),
    };
    json!({
        "router_model_launch": {
            "contract_version": 1,
            "model_descriptor": descriptor,
            "client": args.client.canonical_name(),
            "requested_model": selected,
            "request_source": request_source,
            "token_constraint": if policy.allowed_models.is_empty() {
                json!({"state": "unpinned"})
            } else {
                json!({"state": "exact", "allowed_models": policy.allowed_models})
            },
            "selector_kind": advertised.map(|model| model.selector_kind),
            "provider": scoped_provider.or_else(|| advertised.map(|model| model.owned_by.as_str())),
            "account": scoped_account.or_else(|| Some(credential.principal_id())),
            "provider_endpoint": scoped_endpoint,
            "protocols": scoped_protocols,
            "router_endpoint": server.base_url,
            "substitution_allowed": policy.allow_substitution,
            "switching_setting": (!args.allowed_models.is_empty()).then_some("with --allow-model"),
            "substitution_setting": policy.substitution_source,
        }
    })
}

pub(super) async fn cleanup_after_setup_failure(credential: RunCredential) {
    if let Err(error) = crate::managed_server::cleanup_run_credential(credential).await {
        eprintln!("warning: {error}; the short token TTL remains the cleanup backstop");
    }
}

