//! Launch adapters and explicit Claude profile-reset confirmation.

use std::io::{IsTerminal as _, Write as _};
use std::path::Path;
use std::process::ExitCode;

use super::{AnyError, ClientKind, WithArgs, run_inner};

/// Execute one wrapper invocation and preserve the client's exit status.
pub async fn run(args: &WithArgs) -> ExitCode {
    let verbose = crate::operation_context::var("VERBOSE").is_ok_and(|value| {
        matches!(
            value.trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    });
    run_with_logging(args, None, verbose).await
}

/// Execute a wrapper with a selected diagnostic state root and verbosity.
///
/// Claude launches persist diagnostics under `data_dir/launcher`; `None` uses
/// the same `DATA_DIR`/`HOME` default as the other Router commands.
pub async fn run_with_logging(args: &WithArgs, data_dir: Option<&Path>, verbose: bool) -> ExitCode {
    if args.client == ClientKind::ClaudeCode
        && !args.global
        && !args.undo
        && !crate::launcher_log::is_active()
    {
        let work = Box::pin(run_inner(args));
        return crate::launcher_log::run(args, data_dir, verbose, work).await;
    }
    match run_inner(args).await {
        Ok(code) => code,
        Err(error) => {
            crate::launcher_log::record("launch_failed", &error.to_string());
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

pub(super) fn confirm_claude_profile_reset(yes: bool) -> Result<(), AnyError> {
    if yes {
        return Ok(());
    }
    if !std::io::stdin().is_terminal() {
        return Err(
            "Claude profile reset requires interactive confirmation; rerun with --yes before the client name"
                .into(),
        );
    }
    crate::operation_output::write_passthrough(
        true,
        format_args!("Reset the Router-owned Claude profile and keep a recoverable backup? [y/N] "),
    );
    std::io::stderr().flush()?;
    let mut response = String::new();
    std::io::stdin().read_line(&mut response)?;
    if matches!(response.trim().to_ascii_lowercase().as_str(), "y" | "yes") {
        Ok(())
    } else {
        Err("Claude profile reset cancelled; the previous profile is unchanged".into())
    }
}

pub(super) fn exit_code(status: std::process::ExitStatus) -> ExitCode {
    if let Some(code) = status.code() {
        return ExitCode::from(u8::try_from(code).unwrap_or(1));
    }
    #[cfg(unix)]
    {
        use std::os::unix::process::ExitStatusExt as _;
        ExitCode::from(
            status
                .signal()
                .and_then(|signal| u8::try_from(128 + signal).ok())
                .unwrap_or(1),
        )
    }
    #[cfg(not(unix))]
    ExitCode::from(1)
}

//! Policy and exact model registry for the experimental z.ai GLM Coding Plan.
//!
//! Coding Plan is deliberately not treated as a generic OpenAI-compatible
//! credential. Its personal subscription is bound to one subscriber and to
//! named end-user tools; use through Router remains disabled until the
//! operator acknowledges the intermediary-proxy risk (issue #390).

use crate::client_policy::ClientProtocol;
use crate::clients::ClientKind;
use crate::providers::{CachedProviderCatalog, LiveProviderModel};
use crate::providers::{ProviderKind, ResolvedProvider};
use sha2::{Digest as _, Sha256};
use std::collections::HashSet;
use std::time::{Duration, Instant};

/// Documented base path for native Anthropic Messages traffic.
pub const ANTHROPIC_BASE_PATH: &crate::translation_core::Str = "/api/anthropic";
/// Documented base path for `OpenAI Chat Completions` traffic.
pub const CHAT_BASE_PATH: &crate::translation_core::Str = "/api/coding/paas/v4";
/// Documented base path for `OpenAI Responses` traffic.
pub const RESPONSES_BASE_PATH: &crate::translation_core::Str = "/api/v1";
/// Documented, non-inference quota operation used for health checks.
pub const HEALTH_PATH: &crate::translation_core::Str = "/api/monitor/usage/quota/limit";
/// Authenticated non-inference catalog used as the model source of truth.
pub const CATALOG_PATH: &crate::translation_core::Str = "/api/anthropic/v1/models";

const CATALOG_TTL: Duration = Duration::from_secs(5 * 60);
const FAILED_REFRESH_RETRY: Duration = Duration::from_secs(15);
const MAX_CATALOG_BODY: usize = 1024 * 1024;

/// Stable disposition of a non-inference z.ai credential probe.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ZaiProbeFailureKind {
    CredentialRejected,
    RateLimited,
    Unverified,
}

/// Secret-free failure from the shared z.ai acceptance rule.
#[derive(Debug)]
pub struct ZaiProbeFailure {
    kind: ZaiProbeFailureKind,
    message: &'static str,
}

impl ZaiProbeFailure {
    const fn new(kind: ZaiProbeFailureKind, message: &'static crate::translation_core::Str) -> Self {
        Self { kind, message }
    }

    #[must_use]
    pub const fn kind(&self) -> ZaiProbeFailureKind {
        self.kind
    }
}

impl std::fmt::Display for ZaiProbeFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(self.message)
    }
}

impl std::error::Error for ZaiProbeFailure {}

/// One exact client-visible model mapping.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RegistryEntry {
    pub exposed_id: String,
    pub canonical_id: String,
    pub owner: &'static str,
    pub display_name: Option<String>,
    pub protocol: ClientProtocol,
}

/// Runtime policy for one personal Coding Plan credential.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ZaiCodingPlanPolicy {
    subscriber_id: String,
    intermediary_risk_acknowledged: bool,
    unsupported_clients: Vec<ClientKind>,
}

impl ZaiCodingPlanPolicy {
    /// Build a fail-closed policy from persisted operator acknowledgements.
    pub fn new(
        subscriber_id: &crate::translation_core::Str,
        intermediary_risk_acknowledged: bool,
        unsupported_clients: &[String],
    ) -> crate::translation_core::Outcome<Self, String> {
        let subscriber_id = subscriber_id.trim();
        if subscriber_id.is_empty() {
            return Err("z.ai Coding Plan requires one subscriber_id".into());
        }
        let mut parsed = Vec::new();
        for value in unsupported_clients {
            let client = ClientKind::from_str_opt(value).ok_or_else(|| {
                format!("unknown z.ai unsupported-client acknowledgement: {value}")
            })?;
            if !matches!(
                client,
                ClientKind::GeminiCli | ClientKind::GrokCli | ClientKind::QwenCode
            ) {
                return Err(format!(
                    "{} cannot be enabled for z.ai Coding Plan; only gemini, grok, or qwen may be individually risk-accepted",
                    client.canonical_name()
                ));
            }
            if value != client.canonical_name() {
                return Err(format!(
                    "z.ai unsupported-client acknowledgement must use canonical name '{}'",
                    client.canonical_name()
                ));
            }
            if !parsed.contains(&client) {
                parsed.push(client);
            }
        }
        if parsed.len() > 1 {
            return Err(
                "z.ai Coding Plan permits at most one risk-accepted unsupported client".into(),
            );
        }
        Ok(Self {
            subscriber_id: subscriber_id.to_string(),
            intermediary_risk_acknowledged,
            unsupported_clients: parsed,
        })
    }

    /// Authorize exactly one signed client/principal pair.
    pub fn authorize(&self, client: ClientKind, principal_id: &crate::translation_core::Str) -> crate::translation_core::Outcome<(), String> {
        if !self.intermediary_risk_acknowledged {
            return Err("z.ai Coding Plan intermediary-proxy risk is not acknowledged".into());
        }
        if principal_id != self.subscriber_id {
            return Err(
                "Router token principal does not match the z.ai Coding Plan subscriber".into(),
            );
        }
        if matches!(
            client,
            ClientKind::ClaudeCode | ClientKind::Codex | ClientKind::Opencode
        ) || self.unsupported_clients.contains(&client)
        {
            return Ok(());
        }
        Err(format!(
            "{} is not permitted to use z.ai Coding Plan",
            client.canonical_name()
        ))
    }

    #[must_use]
    pub fn is_unsupported_override(&self, client: ClientKind) -> bool {
        self.unsupported_clients.contains(&client)
    }
}

/// Construct an exact-id registry for a recognized adapter.
pub fn registry_for_client(
    client: ClientKind,
    configured_models: &[impl AsRef<str>],
) -> Result<Vec<RegistryEntry>, String> {
    let protocol = match client {
        ClientKind::ClaudeCode => ClientProtocol::AnthropicMessages,
        ClientKind::Codex => ClientProtocol::OpenAIResponses,
        ClientKind::Opencode | ClientKind::GrokCli | ClientKind::QwenCode => {
            ClientProtocol::OpenAIChat
        }
        ClientKind::GeminiCli => ClientProtocol::GeminiNative,
        ClientKind::Cursor | ClientKind::Agent => {
            return Err(format!(
                "{} has no z.ai Coding Plan adapter",
                client.canonical_name()
            ));
        }
    };
    let mut registry = Vec::new();
    for configured in configured_models {
        let canonical = configured.as_ref().trim();
        if canonical.is_empty() {
            return Err("z.ai Coding Plan model identifiers cannot be empty".into());
        }
        registry.push(RegistryEntry {
            exposed_id: canonical.to_string(),
            canonical_id: canonical.to_string(),
            owner: "z.ai",
            display_name: Some(format!("z.ai Coding Plan — {canonical}")),
            protocol,
        });
    }
    Ok(registry)
}

/// Find one mapping by exact exposed identity. No prefix is interpreted.
#[must_use]
pub fn mapping_for_client(
    client: ClientKind,
    models: &[String],
    exposed_id: &crate::translation_core::Str,
    protocol: ClientProtocol,
) -> crate::translation_core::Maybe<RegistryEntry> {
    registry_for_client(client, models)
        .ok()?
        .into_iter()
        .find(|entry| entry.exposed_id == exposed_id && entry.protocol == protocol)
}

/// Whether any supported adapter registry contains this exact exposed id.
#[must_use]
pub fn canonical_for_any_client(models: &[String], exposed_id: &crate::translation_core::Str) -> crate::translation_core::Maybe<String> {
    [
        ClientKind::ClaudeCode,
        ClientKind::Codex,
        ClientKind::Opencode,
        ClientKind::GeminiCli,
        ClientKind::GrokCli,
        ClientKind::QwenCode,
    ]
    .into_iter()
    .filter_map(|client| registry_for_client(client, models).ok())
    .flatten()
    .find(|entry| entry.exposed_id == exposed_id)
    .map(|entry| entry.canonical_id)
}

fn catalog_fingerprint(provider: &ResolvedProvider) -> String {
    let mut digest = Sha256::new();
    digest.update(provider.name.as_bytes());
    digest.update([0]);
    digest.update(provider.base_url.as_bytes());
    digest.update([0]);
    digest.update(provider.api_key.as_deref().unwrap_or_default().as_bytes());
    hex::encode(digest.finalize())
}

fn cache_failure(
    state: &crate::app_state::AppState,
    provider: &ResolvedProvider,
    fingerprint: String,
    detail: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<Vec<LiveProviderModel>, String> {
    tracing::warn!(provider = %provider.name, "z.ai catalog refresh failed: {detail}");
    let previous = state
        .provider_store
        .cached_provider_catalog(&provider.name)
        .ok()
        .flatten()
        .filter(|entry| entry.fingerprint == fingerprint);
    let _ = state.provider_store.cache_provider_catalog(
        &provider.name,
        CachedProviderCatalog {
            fingerprint,
            models: previous
                .as_ref()
                .map_or_else(Vec::new, |entry| entry.models.clone()),
            last_success: previous.and_then(|entry| entry.last_success),
            last_attempt: Instant::now(),
            error: Some("z.ai catalog refresh failed".into()),
        },
    );
    Err("z.ai catalog refresh failed".into())
}

/// Fetch the exact current z.ai catalog without calling an inference endpoint.
pub(crate) async fn live_catalog(
    state: &crate::app_state::AppState,
    provider: &ResolvedProvider,
) -> crate::translation_core::Outcome<Vec<LiveProviderModel>, String> {
    let fingerprint = catalog_fingerprint(provider);
    if let Some(cached) = state
        .provider_store
        .cached_provider_catalog(&provider.name)
        .map_err(|error| error.to_string())?
        .filter(|entry| entry.fingerprint == fingerprint)
    {
        if cached.error.is_none()
            && cached
                .last_success
                .is_some_and(|at| at.elapsed() < CATALOG_TTL)
        {
            return Ok(cached.models);
        }
        if cached.error.is_some() && cached.last_attempt.elapsed() < FAILED_REFRESH_RETRY {
            return Err("z.ai catalog refresh failed".into());
        }
    }

    let models = match fetch_catalog(&state.client, provider).await {
        Ok(models) => models,
        Err(error) => {
            return cache_failure(state, provider, fingerprint, &error.to_string());
        }
    };
    let now = Instant::now();
    state
        .provider_store
        .cache_provider_catalog(
            &provider.name,
            CachedProviderCatalog {
                fingerprint,
                models: models.clone(),
                last_success: Some(now),
                last_attempt: now,
                error: None,
            },
        )
        .map_err(|error| error.to_string())?;
    Ok(models)
}

/// Validate a z.ai Coding Plan key through the live non-inference catalog.
pub(crate) async fn fetch_catalog(
    client: &reqwest::Client,
    provider: &ResolvedProvider,
) -> crate::translation_core::Outcome<Vec<LiveProviderModel>, ZaiProbeFailure> {
    let key = provider
        .api_key
        .as_deref()
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            ZaiProbeFailure::new(
                ZaiProbeFailureKind::CredentialRejected,
                "z.ai Coding Plan API key is unavailable",
            )
        })?;
    let response = client
        .get(format!(
            "{}{}",
            provider.base_url.trim_end_matches('/'),
            CATALOG_PATH
        ))
        .bearer_auth(key)
        .send()
        .await
        .map_err(|_| {
            ZaiProbeFailure::new(
                ZaiProbeFailureKind::Unverified,
                "z.ai Coding Plan catalog could not be verified",
            )
        })?;
    let status = response.status();
    if matches!(
        status,
        reqwest::StatusCode::UNAUTHORIZED | reqwest::StatusCode::FORBIDDEN
    ) {
        return Err(ZaiProbeFailure::new(
            ZaiProbeFailureKind::CredentialRejected,
            "z.ai Coding Plan credential was rejected",
        ));
    }
    if status == reqwest::StatusCode::TOO_MANY_REQUESTS {
        return Err(ZaiProbeFailure::new(
            ZaiProbeFailureKind::RateLimited,
            "z.ai Coding Plan acceptance was rate limited",
        ));
    }
    if !status.is_success() {
        return Err(ZaiProbeFailure::new(
            ZaiProbeFailureKind::Unverified,
            "z.ai Coding Plan catalog could not be verified",
        ));
    }
    let bytes = response.bytes().await.map_err(|_| {
        ZaiProbeFailure::new(
            ZaiProbeFailureKind::Unverified,
            "z.ai Coding Plan catalog could not be read",
        )
    })?;
    if bytes.len() > MAX_CATALOG_BODY {
        return Err(ZaiProbeFailure::new(
            ZaiProbeFailureKind::Unverified,
            "z.ai Coding Plan catalog exceeded the response limit",
        ));
    }
    let payload = serde_json::from_slice(&bytes).map_err(|_| {
        ZaiProbeFailure::new(
            ZaiProbeFailureKind::Unverified,
            "z.ai Coding Plan catalog response was malformed",
        )
    })?;
    let payload = accepted_non_inference_payload(payload)?;
    let entries = payload.as_array().ok_or_else(|| {
        ZaiProbeFailure::new(
            ZaiProbeFailureKind::Unverified,
            "z.ai Coding Plan catalog response had no model array",
        )
    })?;
    if entries.is_empty() {
        return Err(ZaiProbeFailure::new(
            ZaiProbeFailureKind::CredentialRejected,
            "z.ai Coding Plan catalog did not prove an active subscription",
        ));
    }
    let source_url = format!(
        "{}{}",
        provider.base_url.trim_end_matches('/'),
        CATALOG_PATH
    );
    let fetched_at = crate::operation_context::now().to_rfc3339();
    let mut seen = HashSet::new();
    let mut models = Vec::with_capacity(entries.len());
    for entry in entries {
        let mut raw = entry.as_object().cloned().ok_or_else(|| {
            ZaiProbeFailure::new(
                ZaiProbeFailureKind::Unverified,
                "z.ai Coding Plan catalog contained an invalid model record",
            )
        })?;
        let id = raw
            .get("id")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|id| !id.is_empty())
            .ok_or_else(|| {
                ZaiProbeFailure::new(
                    ZaiProbeFailureKind::Unverified,
                    "z.ai Coding Plan catalog contained a model without an exact id",
                )
            })?
            .to_string();
        if !seen.insert(id.clone()) {
            // A provider can repeat an exact record across catalog pages or
            // compatibility families. Preserve the first record so metadata
            // selection is stable while publishing the exact id only once.
            continue;
        }
        raw.insert(
            "router_source_url".into(),
            serde_json::Value::String(source_url.clone()),
        );
        raw.insert(
            "router_endpoint".into(),
            serde_json::Value::String(provider.base_url.clone()),
        );
        raw.insert(
            "router_account".into(),
            serde_json::Value::String(
                provider
                    .subscriber_id
                    .clone()
                    .unwrap_or_else(|| provider.name.clone()),
            ),
        );
        raw.insert(
            "router_fetched_at".into(),
            serde_json::Value::String(fetched_at.clone()),
        );
        raw.insert(
            "router_health_generation".into(),
            serde_json::Value::String(fetched_at.clone()),
        );
        models.push(LiveProviderModel { id, raw });
    }
    Ok(models)
}

/// Apply the body-level success contract shared by catalog, health, and usage.
pub(crate) fn accepted_non_inference_payload(
    value: crate::translation_core::Json,
) -> crate::translation_core::Outcome<crate::translation_core::Json, ZaiProbeFailure> {
    let code = value.get("code").and_then(serde_json::Value::as_i64);
    if value.get("success").and_then(serde_json::Value::as_bool) == Some(false) {
        let kind = if code == Some(429) {
            ZaiProbeFailureKind::RateLimited
        } else {
            ZaiProbeFailureKind::CredentialRejected
        };
        return Err(ZaiProbeFailure::new(
            kind,
            "z.ai Coding Plan non-inference response rejected the credential",
        ));
    }
    if code.is_some_and(|code| !matches!(code, 0 | 200)) {
        let kind = if code == Some(429) {
            ZaiProbeFailureKind::RateLimited
        } else if matches!(code, Some(401 | 1001)) {
            ZaiProbeFailureKind::CredentialRejected
        } else {
            ZaiProbeFailureKind::Unverified
        };
        return Err(ZaiProbeFailure::new(
            kind,
            "z.ai Coding Plan non-inference response was not accepted",
        ));
    }
    Ok(value.get("data").cloned().unwrap_or(value))
}

pub(crate) fn live_registry_for_client(
    client: ClientKind,
    models: &[LiveProviderModel],
) -> crate::translation_core::Outcome<Vec<RegistryEntry>, String> {
    let mut registry = registry_for_client(
        client,
        &models.iter().map(|model| &model.id).collect::<Vec<_>>(),
    )?;
    for (entry, model) in registry.iter_mut().zip(models) {
        entry.display_name = model
            .raw
            .get("display_name")
            .or_else(|| model.raw.get("name"))
            .and_then(crate::translation_core::Json::as_str)
            .map(str::to_string);
    }
    Ok(registry)
}

/// Resolve one exact current z.ai id for automatic routing.
pub(crate) async fn live_provider_for_model(
    state: &crate::app_state::AppState,
    model: &crate::translation_core::Str,
    client: crate::translation_core::Maybe<ClientKind>,
    authorized: bool,
) -> crate::translation_core::Outcome<crate::translation_core::Maybe<ResolvedProvider>, crate::model_routing::ModelRouteError> {
    if !authorized {
        return Ok(None);
    }
    let provider = resolve(state).map_err(crate::model_routing::ModelRouteError::NotFound)?;
    let Some(provider) = provider else {
        return Ok(None);
    };
    if client.is_some_and(|client| !provider.supports_client(client)) {
        return Ok(None);
    }
    let Ok(models) = live_catalog(state, &provider).await else {
        return Ok(None);
    };
    Ok(models
        .iter()
        .any(|candidate| candidate.id == model)
        .then_some(provider))
}

/// Explain why a model the z.ai catalog lists was not routed to z.ai.
///
/// Automatic routing consults z.ai only for a request carrying its bound
/// client's own evidence, while `/api/models` lists GLM for weaker catalog
/// evidence. Without this the same token saw GLM listed and then "not
/// advertised by any subscription" (issue #657). Local only: it reads the
/// catalog Router already cached and never contacts z.ai.
pub(crate) fn unproven_request_for_listed_model(
    state: &crate::app_state::AppState,
    model: &crate::translation_core::Str,
    client: crate::translation_core::Maybe<ClientKind>,
) -> crate::translation_core::Maybe<String> {
    let provider = resolve(state).ok().flatten()?;
    let client = client?;
    // A client the plan does not permit is never shown its models, so for it
    // the model stays unknown (404), as `/api/models` says.
    let policy = provider_policy(&provider).ok()?;
    policy.authorize(client, &policy.subscriber_id).ok()?;
    let cached = state
        .provider_store
        .cached_provider_catalog(&provider.name)
        .ok()
        .flatten()
        .filter(|cached| cached.fingerprint == catalog_fingerprint(&provider))?;
    if !cached.models.iter().any(|candidate| candidate.id == model) {
        return None;
    }
    let client = client.canonical_name();
    Some(format!(
        "model '{model}' is served by the z.ai Coding Plan, which Router uses only for requests \
         whose headers match the token's {client} client binding and subscriber; this request \
         did not, so it was not sent to z.ai. Send it from that client (for example through \
         `router with`)"
    ))
}

/// Decide whether an automatic request may consult the z.ai catalog.
///
/// This is intentionally local-only: subscriber, client, protocol, and real
/// request evidence are checked before catalog discovery can contact z.ai.
pub(crate) fn authorize_automatic_discovery(
    state: &crate::app_state::AppState,
    claims: &crate::token::TokenClaims,
    headers: &axum::http::HeaderMap,
    protocol: ClientProtocol,
    path: &crate::translation_core::Str,
) -> bool {
    resolve(state).ok().flatten().is_some_and(|provider| {
        authorize_client_request(&provider, claims, headers, protocol, path).is_ok()
    })
}

/// Resolve the selected enabled Coding Plan provider from runtime state.
pub fn resolve(state: &crate::app_state::AppState) -> crate::translation_core::Outcome<crate::translation_core::Maybe<ResolvedProvider>, String> {
    let providers = state
        .provider_store
        .list()
        .map_err(|error| error.to_string())?;
    let mut enabled = providers
        .into_iter()
        .filter(|record| record.enabled && record.kind == ProviderKind::ZaiCodingPlan);
    let Some(record) = enabled.next() else {
        return Ok(None);
    };
    if enabled.next().is_some() {
        return Err("multiple personal z.ai Coding Plan credentials are enabled".into());
    }
    state
        .provider_store
        .resolve(&record.name)
        .map_err(|error| error.to_string())
}

fn client_claims(claims: &crate::token::TokenClaims) -> crate::translation_core::Outcome<(ClientKind, &crate::translation_core::Str), String> {
    crate::client_policy::bound_client(claims)
}

fn provider_policy(provider: &ResolvedProvider) -> crate::translation_core::Outcome<ZaiCodingPlanPolicy, String> {
    if provider.kind != ProviderKind::ZaiCodingPlan {
        return Err("selected credential is not z.ai Coding Plan".into());
    }
    ZaiCodingPlanPolicy::new(
        provider
            .subscriber_id
            .as_deref()
            .ok_or("z.ai Coding Plan has no subscriber")?,
        provider.intermediary_risk_acknowledged,
        &provider.unsupported_clients,
    )
}

fn authorize_client_request<'a>(
    provider: &ResolvedProvider,
    claims: &'a crate::token::TokenClaims,
    headers: &axum::http::HeaderMap,
    protocol: ClientProtocol,
    path: &str,
) -> Result<(ClientKind, &'a str, bool), String> {
    let (client, principal) = client_claims(claims)?;
    if !crate::client_policy::request_evidence(client, protocol, path, headers) {
        return Err(format!(
            "request evidence does not match the token's {} client binding",
            client.canonical_name()
        ));
    }
    let policy = provider_policy(provider)?;
    policy.authorize(client, principal)?;
    let overridden = policy.is_unsupported_override(client);
    Ok((client, principal, overridden))
}

/// Authorize catalog discovery, returning the caller-specific exact registry.
pub fn authorize_catalog(
    provider: &ResolvedProvider,
    claims: &crate::token::TokenClaims,
    headers: &axum::http::HeaderMap,
    path: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<(ClientKind, bool), String> {
    let (client, _, overridden) =
        authorize_client_request(provider, claims, headers, ClientProtocol::Catalog, path)?;
    Ok((client, overridden))
}

/// Authorize final dispatch and map the exact exposed id to its canonical id.
pub(crate) fn authorize_model(
    provider: &ResolvedProvider,
    live_models: &[LiveProviderModel],
    claims: &crate::token::TokenClaims,
    headers: &axum::http::HeaderMap,
    protocol: ClientProtocol,
    path: &crate::translation_core::Str,
    exposed_id: &crate::translation_core::Str,
) -> crate::translation_core::Outcome<(ClientKind, RegistryEntry, bool), String> {
    let (client, _, overridden) =
        authorize_client_request(provider, claims, headers, protocol, path)?;
    let mapping = live_registry_for_client(client, live_models)?
        .into_iter()
        .find(|entry| entry.exposed_id == exposed_id && entry.protocol == protocol)
        .ok_or_else(|| format!("model '{exposed_id}' is not permitted for {client}"))?;
    Ok((client, mapping, overridden))
}

/// Check the documented quota endpoint without consuming inference tokens.
pub async fn credential_healthy(
    client: &reqwest::Client,
    provider: &ResolvedProvider,
) -> crate::translation_core::Outcome<(), String> {
    fetch_catalog(client, provider)
        .await
        .map(|_| ())
        .map_err(|error| error.to_string())
}

/// Live health for the enabled personal Coding Plan credential, when present.
///
/// The same authenticated non-inference live catalog gates catalogs and
/// dispatch, so every health surface reports the routing source of truth.
pub(crate) async fn configured_health(state: &crate::app_state::AppState) -> crate::translation_core::Maybe<bool> {
    let configured = match state.provider_store.list() {
        Ok(providers) => providers
            .iter()
            .any(|record| record.enabled && record.kind == ProviderKind::ZaiCodingPlan),
        Err(_) => {
            return (state.upstream_provider == crate::config::UpstreamProvider::ZaiCodingPlan)
                .then_some(false);
        }
    };
    if !configured {
        return None;
    }
    let Ok(Some(provider)) = resolve(state) else {
        return Some(false);
    };
    // z.ai keeps listing models for an account it refuses to serve (#657).
    if state.provider_store.exhaustion(&provider.name).is_some() {
        return Some(false);
    }
    Some(live_catalog(state, &provider).await.is_ok())
}

/// The refusal that marks the configured Coding Plan exhausted, recorded from
/// the last inference z.ai refused and cleared by the next one it serves.
pub(crate) fn recorded_exhaustion(
    state: &crate::app_state::AppState,
) -> crate::translation_core::Maybe<crate::zai_upstream_error::ZaiExhaustion> {
    let provider = resolve(state).ok().flatten()?;
    state.provider_store.exhaustion(&provider.name)
}

fn policy_error(surface: crate::metrics::Surface, message: &crate::translation_core::Str) -> axum::response::Response {
    crate::api_error::error_response_for_surface(
        surface,
        axum::http::StatusCode::FORBIDDEN,
        "permission_error",
        message,
    )
}

fn unavailable_error(surface: crate::metrics::Surface, message: &crate::translation_core::Str) -> axum::response::Response {
    crate::api_error::error_response_for_surface(
        surface,
        axum::http::StatusCode::SERVICE_UNAVAILABLE,
        "api_error",
        message,
    )
}

/// Enforce Coding Plan policy immediately before forwarding one request.
pub async fn forward(
    state: &crate::app_state::AppState,
    headers: &axum::http::HeaderMap,
    mut body: crate::translation_core::Json,
    incoming_path: &crate::translation_core::Str,
    protocol: ClientProtocol,
    surface: crate::metrics::Surface,
) -> axum::response::Response {
    let claims = match crate::proxy::authenticate_client(state, headers) {
        Ok(claims) => claims,
        Err(response) => return *response,
    };
    let Some(exposed_id) = body
        .get("model")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
    else {
        return crate::api_error::error_response_for_surface(
            surface,
            axum::http::StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "model is required for z.ai Coding Plan",
        );
    };
    if let Err(response) = crate::proxy::authorize_model_for_claims(
        state,
        &claims,
        &exposed_id,
        if protocol == ClientProtocol::AnthropicMessages {
            crate::api_error::ApiDialect::Anthropic
        } else {
            crate::api_error::ApiDialect::OpenAi
        },
    ) {
        return response;
    }
    let provider = match resolve(state) {
        Ok(Some(provider)) => provider,
        Ok(None) => return unavailable_error(surface, "z.ai Coding Plan is not enabled"),
        Err(error) => return unavailable_error(surface, &error),
    };
    if let Err(error) =
        authorize_client_request(&provider, &claims, headers, protocol, incoming_path)
    {
        return policy_error(surface, &error);
    }
    let live_models = match live_catalog(state, &provider).await {
        Ok(models) => models,
        Err(error) => return unavailable_error(surface, &error),
    };
    let (_, mapping, _) = match authorize_model(
        &provider,
        &live_models,
        &claims,
        headers,
        protocol,
        incoming_path,
        &exposed_id,
    ) {
        Ok(decision) => decision,
        Err(error) => return policy_error(surface, &error),
    };
    let routing_body = body.clone();
    let collect_anthropic = protocol == ClientProtocol::AnthropicMessages
        && !body
            .get("stream")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
        && body
            .pointer("/thinking/type")
            .and_then(serde_json::Value::as_str)
            == Some("enabled");
    if collect_anthropic {
        body["stream"] = serde_json::Value::Bool(true);
    }
    body["model"] = serde_json::Value::String(mapping.canonical_id);
    let upstream_path = match protocol {
        ClientProtocol::AnthropicMessages => {
            format!("{ANTHROPIC_BASE_PATH}/v1/messages")
        }
        ClientProtocol::OpenAIChat | ClientProtocol::GeminiNative => {
            format!("{CHAT_BASE_PATH}/chat/completions")
        }
        ClientProtocol::OpenAIResponses => format!("{RESPONSES_BASE_PATH}/responses"),
        ClientProtocol::Catalog => {
            return policy_error(surface, "z.ai Coding Plan protocol adapter is unavailable");
        }
    };
    let response = crate::provider_proxy::forward_provider_at_routed(
        state,
        headers,
        body,
        &routing_body,
        crate::provider_proxy::ProviderForwardOptions {
            path: incoming_path,
            upstream_path: &upstream_path,
            surface,
            copy_anthropic_headers: protocol == ClientProtocol::AnthropicMessages,
            protocol,
            native_protocol: !matches!(
                protocol,
                ClientProtocol::GeminiNative | ClientProtocol::Catalog
            ),
        },
    )
    .await;
    if collect_anthropic {
        crate::anthropic_nonstream::collect_response(response, surface).await
    } else {
        response
    }
}

/// Enforce the Messages policy boundary, then fail closed because no exact,
/// non-inference z.ai counter is currently available.
pub fn count_tokens(
    state: &crate::app_state::AppState,
    headers: &axum::http::HeaderMap,
    path: &crate::translation_core::Str,
    body: &crate::translation_core::Json,
) -> axum::response::Response {
    let claims = match crate::proxy::authenticate_client(state, headers) {
        Ok(claims) => claims,
        Err(response) => return *response,
    };
    let Some(model) = body.get("model").and_then(crate::translation_core::Json::as_str) else {
        return crate::api_error::error_response(
            axum::http::StatusCode::BAD_REQUEST,
            "invalid_request_error",
            "model is required for z.ai Coding Plan",
        );
    };
    if let Err(response) = crate::proxy::authorize_model_for_claims(
        state,
        &claims,
        model,
        crate::api_error::ApiDialect::Anthropic,
    ) {
        return response;
    }
    let provider = match resolve(state) {
        Ok(Some(provider)) => provider,
        Ok(None) => {
            return unavailable_error(
                crate::metrics::Surface::Anthropic,
                "z.ai Coding Plan is not enabled",
            );
        }
        Err(error) => return unavailable_error(crate::metrics::Surface::Anthropic, &error),
    };
    let Some(live_models) = state
        .provider_store
        .cached_provider_catalog(&provider.name)
        .ok()
        .flatten()
        .filter(|cached| {
            cached.fingerprint == catalog_fingerprint(&provider)
                && cached.error.is_none()
                && cached
                    .last_success
                    .is_some_and(|at| at.elapsed() < CATALOG_TTL)
        })
        .map(|cached| cached.models)
    else {
        return unavailable_error(
            crate::metrics::Surface::Anthropic,
            "z.ai model catalog must be refreshed before token counting",
        );
    };
    if let Err(error) = authorize_model(
        &provider,
        &live_models,
        &claims,
        headers,
        ClientProtocol::AnthropicMessages,
        path,
        model,
    ) {
        return policy_error(crate::metrics::Surface::Anthropic, &error);
    }
    crate::audit::record_authorised_request(
        state,
        &claims,
        crate::metrics::Surface::Anthropic,
        path,
        Some(body),
    );
    unavailable_error(
        crate::metrics::Surface::Anthropic,
        "exact token counting is unavailable for the selected route",
    )
}

//! z.ai inference refusals that are not rate limits (issue #657).
//!
//! z.ai answers an exhausted Coding Plan with HTTP 429 and an Anthropic-shaped
//! `rate_limit_error`, so a client that honours the protocol retries forever:
//!
//! ```json
//! {"error":{"code":"1113","message":"[1113][Insufficient balance or no resource package. Please recharge.][<request id>]","type":"rate_limit_error"},"type":"error"}
//! ```
//!
//! The business code says what the status does not. Codes for an empty
//! balance, an expired or missing package, or a model the plan does not
//! include are rewritten into a non-retryable `402` naming the reason, the code
//! and the upstream request id, and the account is recorded as exhausted so
//! usage, health and catalog surfaces report it. Codes that are genuinely
//! temporary (`1302`, `1305`, `1308`, `1313`) are relayed unchanged.
//!
//! Codes from <https://docs.z.ai/api-reference/api-code>.

use std::fmt::Write as _;
use std::time::SystemTime;

use axum::http::{HeaderValue, StatusCode};
use axum::response::{IntoResponse, Response};
use serde_json::{Value, json};

/// Business codes meaning the account cannot serve until the operator acts or
/// a weekly/monthly period ends: no balance or resource package (1113), an
/// expired package (1309, 1314), an exhausted weekly or monthly limit (1310),
/// a plan that excludes the model or scenario (1311, 1315), and an
/// insufficient balance or spend limit (1316–1321). 1302, 1305, 1308 and 1313
/// are request-rate or short-window limits and stay retryable.
const EXHAUSTED_CODES: &[u32] = &[
    1113, 1309, 1310, 1311, 1314, 1315, 1316, 1317, 1318, 1319, 1320, 1321,
];

/// Upper bound on an error body Router reads to classify it. z.ai error bodies
/// are a few hundred bytes; anything larger is relayed without inspection.
pub(crate) const MAX_CLASSIFIED_BODY: usize = 16 * 1024;

/// One classified non-retryable z.ai refusal.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ZaiExhaustion {
    /// The z.ai business code, e.g. `1113`.
    pub code: u32,
    /// z.ai's own reason, without the code and request-id brackets.
    pub reason: String,
    /// The upstream request id, when z.ai supplied one.
    pub request_id: Option<String>,
    /// When Router observed it.
    pub observed_at: SystemTime,
}

impl ZaiExhaustion {
    /// The operator-facing sentence every surface uses.
    ///
    /// z.ai's reason usually ends with its own full stop; it is trimmed so the
    /// summary can be followed by another sentence without `..` (issue #664).
    #[must_use]
    pub fn summary(&self) -> String {
        format!(
            "z.ai Coding Plan cannot serve requests (code {}): {}",
            self.code,
            self.reason.trim_end().trim_end_matches(['.', '。'])
        )
    }

    /// Seconds since the Unix epoch at which it was observed.
    #[must_use]
    pub fn observed_unix(&self) -> u64 {
        self.observed_at
            .duration_since(SystemTime::UNIX_EPOCH)
            .map_or(0, |elapsed| elapsed.as_secs())
    }

    /// The fields surfaces publish, without anything secret.
    #[must_use]
    pub fn to_json(&self) -> crate::translation_core::Json {
        json!({
            "state": "exhausted",
            "code": self.code.to_string(),
            "reason": self.reason,
            "request_id": self.request_id,
            "observed_at_unix": self.observed_unix(),
            "summary": self.summary(),
        })
    }
}

/// The business code in a z.ai error body, as a string or a number, under
/// `error.code` (inference) or a top-level `code` (non-inference).
fn business_code(value: &crate::translation_core::Json) -> crate::translation_core::Maybe<u32> {
    let code = value.pointer("/error/code").or_else(|| value.get("code"))?;
    match code {
        crate::translation_core::Json::String(text) => text.trim().parse().ok(),
        crate::translation_core::Json::Number(number) => number.as_u64().and_then(|n| u32::try_from(n).ok()),
        _ => None,
    }
}

/// Split `[1113][reason][request id]` into its reason and request id.
fn bracketed(message: &crate::translation_core::Str) -> (crate::translation_core::Maybe<String>, crate::translation_core::Maybe<String>) {
    let parts = message
        .split(']')
        .filter_map(|part| part.trim().strip_prefix('['))
        .map(str::to_string)
        .collect::<Vec<_>>();
    match parts.as_slice() {
        [_, reason, request_id, ..] => (Some(reason.clone()), Some(request_id.clone())),
        [_, reason] => (Some(reason.clone()), None),
        _ => (None, None),
    }
}

/// Classify a z.ai error body; `Some` only for a non-retryable account state.
#[must_use]
pub fn classify(body: &[u8]) -> crate::translation_core::Maybe<ZaiExhaustion> {
    let value = serde_json::from_slice::<Value>(body).ok()?;
    let code = business_code(&value)?;
    if !EXHAUSTED_CODES.contains(&code) {
        return None;
    }
    let message = value
        .pointer("/error/message")
        .or_else(|| value.get("msg"))
        .or_else(|| value.get("message"))
        .and_then(crate::translation_core::Json::as_str)
        .unwrap_or_default();
    let (reason, request_id) = bracketed(message);
    let reason = reason
        .filter(|reason| !reason.is_empty())
        .or_else(|| (!message.is_empty()).then(|| message.to_string()))
        .unwrap_or_else(|| "the account has no usable balance or resource package".into());
    let request_id = request_id
        .or_else(|| {
            value
                .get("request_id")
                .or_else(|| value.pointer("/error/request_id"))
                .and_then(crate::translation_core::Json::as_str)
                .map(str::to_string)
        })
        .filter(|id| !id.is_empty());
    Some(ZaiExhaustion {
        code,
        reason,
        request_id,
        observed_at: crate::operation_context::system_time(),
    })
}

/// The non-retryable client response for an exhausted account.
///
/// `402` is outside every client's retry set (Anthropic and `OpenAI` SDKs, Claude
/// Code and Codex retry 408, 409, 429 and 5xx), so the client stops and shows
/// the message. The Anthropic surface uses Anthropic's `billing_error`; the
/// `OpenAI` surfaces use `insufficient_quota`, the type their clients already
/// treat as terminal.
#[must_use]
pub fn client_response(surface: crate::metrics::Surface, exhaustion: &ZaiExhaustion) -> Response {
    let message = format!(
        "{}. Recharge the z.ai plan or choose another model (for example with /model).",
        exhaustion.summary()
    );
    let code = exhaustion.code.to_string();
    let body = match surface {
        crate::metrics::Surface::Anthropic => json!({
            "type": "error",
            "error": {
                "type": "billing_error",
                "message": message,
                "upstream_code": code,
                "upstream_request_id": exhaustion.request_id,
            },
            "request_id": exhaustion.request_id,
        }),
        crate::metrics::Surface::OpenAIChat | crate::metrics::Surface::OpenAIResponses => json!({
            "error": {
                "type": "insufficient_quota",
                "code": "insufficient_quota",
                "message": message,
                "param": null,
                "upstream_code": code,
                "upstream_request_id": exhaustion.request_id,
            }
        }),
    };
    let mut response = (StatusCode::PAYMENT_REQUIRED, axum::Json(body)).into_response();
    if let Ok(value) = HeaderValue::from_str(&code) {
        response
            .headers_mut()
            .insert("x-router-upstream-error-code", value);
    }
    response
}

/// Whether the provider answers with z.ai business codes: the Coding Plan, or
/// an OpenAI-compatible provider pointed at a z.ai or Zhipu endpoint.
pub(crate) fn speaks_zai_business_codes(provider: &crate::providers::ResolvedProvider) -> bool {
    provider.kind == crate::providers::ProviderKind::ZaiCodingPlan
        || reqwest::Url::parse(&provider.base_url)
            .ok()
            .and_then(|url| url.host_str().map(str::to_ascii_lowercase))
            .is_some_and(|host| {
                ["z.ai", "bigmodel.cn"]
                    .iter()
                    .any(|domain| host == *domain || host.ends_with(&format!(".{domain}")))
            })
}

/// Clear a recorded exhaustion when z.ai serves again, and say whether this
/// response is a z.ai 4xx that [`relay_refusal`] must classify.
pub(crate) fn is_refusal_to_classify(
    state: &crate::proxy::AppState,
    provider: &crate::providers::ResolvedProvider,
    status: StatusCode,
) -> bool {
    if !speaks_zai_business_codes(provider) {
        return false;
    }
    if status.is_success() {
        state.provider_store.clear_exhaustion(&provider.name);
    }
    status.is_client_error()
}

/// Relay a z.ai 4xx, rewriting an exhausted account into a non-retryable
/// error and recording it (issue #657). Any other refusal, including a genuine
/// rate limit, is relayed with its status, headers and body unchanged.
pub(crate) async fn relay_refusal(
    state: &crate::proxy::AppState,
    provider: &crate::providers::ResolvedProvider,
    surface: crate::metrics::Surface,
    upstream_resp: reqwest::Response,
    correlation_id: &crate::translation_core::Str,
) -> Response {
    let status = StatusCode::from_u16(upstream_resp.status().as_u16())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let mut headers = crate::proxy::relay_response_headers(upstream_resp.headers());
    let content_type = upstream_resp
        .headers()
        .get("content-type")
        .cloned()
        .unwrap_or_else(|| HeaderValue::from_static("application/json"));
    // The upstream status was already counted; a failed read is not counted twice.
    let body = match upstream_resp.bytes().await {
        Ok(bytes) => bytes,
        Err(e) => {
            return crate::proxy::error_response(
                StatusCode::BAD_GATEWAY,
                "api_error",
                &format!("z.ai upstream body read failed: {e}"),
            );
        }
    };
    state
        .request_log
        .record_upstream_body(correlation_id, &body);
    let exhaustion = (body.len() <= MAX_CLASSIFIED_BODY)
        .then(|| classify(&body))
        .flatten();
    if let Some(exhaustion) = exhaustion {
        tracing::warn!(
            provider = %provider.name,
            code = exhaustion.code,
            "{}; answering 402 instead of relaying z.ai's 429",
            exhaustion.summary()
        );
        let response = client_response(surface, &exhaustion);
        state
            .provider_store
            .record_exhaustion(&provider.name, exhaustion);
        return response;
    }
    headers.insert("content-type", content_type);
    let mut response = Response::new(axum::body::Body::from(body));
    *response.status_mut() = status;
    *response.headers_mut() = headers;
    response
}

/// The data-directory file that keeps recorded exhaustions.
///
/// A restart, `router doctor` and `deploy --status` thereby see what the
/// serving process learned. It holds codes and z.ai's public reason, never a
/// secret.
pub const STATE_FILE: &crate::translation_core::Str = "provider-exhaustion.json";

/// The exhaustions recorded under `data_dir`, by provider name. A missing or
/// unreadable file means none were recorded.
#[must_use]
pub fn load(data_dir: &std::path::Path) -> std::collections::HashMap<String, ZaiExhaustion> {
    let Ok(text) = std::fs::read_to_string(data_dir.join(STATE_FILE)) else {
        return std::collections::HashMap::new();
    };
    let Ok(Value::Object(entries)) = serde_json::from_str::<Value>(&text) else {
        return std::collections::HashMap::new();
    };
    entries
        .into_iter()
        .filter_map(|(name, entry)| {
            let code = business_code(&crate::translation_core::json!({ "code": entry.get("code")? }))?;
            let observed = entry.get("observed_at_unix").and_then(Value::as_u64)?;
            Some((
                name,
                ZaiExhaustion {
                    code,
                    reason: entry.get("reason")?.as_str()?.to_string(),
                    request_id: entry
                        .get("request_id")
                        .and_then(Value::as_str)
                        .map(str::to_string),
                    observed_at: SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(observed),
                },
            ))
        })
        .collect()
}

/// Replace the recorded exhaustions under `data_dir`; an empty map removes the
/// file. Failures are logged, not fatal: the in-memory state still answers.
pub(crate) fn save(
    data_dir: &std::path::Path,
    exhaustions: &std::collections::HashMap<String, ZaiExhaustion>,
) {
    let path = data_dir.join(STATE_FILE);
    let result = if exhaustions.is_empty() {
        match std::fs::remove_file(&path) {
            Err(error) if error.kind() != std::io::ErrorKind::NotFound => Err(error),
            _ => Ok(()),
        }
    } else {
        let entries = exhaustions
            .iter()
            .map(|(name, exhaustion)| (name.clone(), exhaustion.to_json()))
            .collect::<serde_json::Map<_, _>>();
        crate::durable_file::atomic_write_owner_only(
            &path,
            Value::Object(entries).to_string().as_bytes(),
        )
    };
    if let Err(error) = result {
        tracing::warn!(path = %path.display(), "could not persist provider exhaustion: {error}");
    }
}

/// One newline-terminated `key=value` line per recorded exhaustion under
/// `data_dir`, for `deploy --status` and `router doctor`; empty when none.
#[must_use]
pub fn status_report(data_dir: &std::path::Path) -> String {
    let mut lines = load(data_dir)
        .into_iter()
        .map(|(name, exhaustion)| {
            format!(
                "provider_exhausted provider={name} upstream_code={} observed_at_unix={} reason={}",
                exhaustion.code,
                exhaustion.observed_unix(),
                serde_json::to_string(&exhaustion.summary()).unwrap_or_default()
            )
        })
        .collect::<Vec<_>>();
    lines.sort();
    lines.into_iter().map(|line| line + "\n").collect()
}

/// The exhaustion section of `router doctor`, and whether any was recorded.
///
/// `doctor` runs as a separate process with its own `DATA_DIR`, while a local
/// deployment keeps its state under `<root>/data`. It reported nothing for an
/// exhausted plan that a host deployment had recorded (issue #664), so it now
/// inspects each candidate directory and names every one it read.
#[must_use]
pub fn doctor_report(data_dirs: &[std::path::PathBuf]) -> (String, bool) {
    let mut report = String::new();
    let mut seen = std::collections::HashSet::new();
    let mut found = false;
    for data_dir in data_dirs.iter().filter(|dir| seen.insert(dir.as_path())) {
        let lines = status_report(data_dir);
        let result = if lines.is_empty() {
            "none recorded"
        } else {
            found = true;
            "recorded"
        };
        let _ = write!(
            report,
            "provider exhaustion     : {result} in {}\n{lines}",
            data_dir.display()
        );
    }
    if !found {
        report.push_str(
            "note: a deployment started with --root DIR records it in DIR/data; run doctor \
             with DATA_DIR=DIR/data to inspect that deployment\n",
        );
    }
    (report, found)
}

#[cfg(test)]
mod tests {
    use super::*;

    const EXHAUSTED: &str = r#"{"error":{"code":"1113","message":"[1113][Insufficient balance or no resource package. Please recharge.][20261004-abc]","type":"rate_limit_error"},"type":"error"}"#;

    #[test]
    fn the_exact_1113_body_is_exhaustion_with_reason_and_request_id() {
        let exhaustion = classify(EXHAUSTED.as_bytes()).expect("1113 is exhaustion");
        assert_eq!(exhaustion.code, 1113);
        assert_eq!(
            exhaustion.reason,
            "Insufficient balance or no resource package. Please recharge."
        );
        assert_eq!(exhaustion.request_id.as_deref(), Some("20261004-abc"));
    }

    #[test]
    fn genuine_rate_limits_and_other_bodies_are_not_exhaustion() {
        for code in ["1302", "1305", "1308", "1313"] {
            let body = format!(
                r#"{{"error":{{"code":"{code}","message":"[{code}][slow down][id]","type":"rate_limit_error"}},"type":"error"}}"#
            );
            assert_eq!(classify(body.as_bytes()), None, "{code}");
        }
        assert_eq!(classify(b"not json"), None);
        assert_eq!(classify(br#"{"error":{"type":"rate_limit_error"}}"#), None);
    }

    #[test]
    fn numeric_and_top_level_codes_are_recognised() {
        let exhaustion =
            classify(br#"{"code":1311,"msg":"plan does not include this model","success":false}"#)
                .expect("1311 is exhaustion");
        assert_eq!(exhaustion.code, 1311);
        assert_eq!(exhaustion.reason, "plan does not include this model");
        assert_eq!(exhaustion.request_id, None);
    }

    #[tokio::test]
    async fn the_anthropic_response_is_a_non_retryable_billing_error() {
        let exhaustion = classify(EXHAUSTED.as_bytes()).expect("exhaustion");
        let response = client_response(crate::metrics::Surface::Anthropic, &exhaustion);
        assert_eq!(response.status(), StatusCode::PAYMENT_REQUIRED);
        assert_eq!(response.headers()["x-router-upstream-error-code"], "1113");
        let body = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        let value: Value = serde_json::from_slice(&body).expect("json");
        assert_eq!(value["type"], "error");
        assert_eq!(value["error"]["type"], "billing_error");
        assert_eq!(value["error"]["upstream_code"], "1113");
        assert_eq!(value["error"]["upstream_request_id"], "20261004-abc");
        let message = value["error"]["message"].as_str().expect("message");
        assert!(message.contains("code 1113"), "{message}");
        assert!(message.contains("Insufficient balance"), "{message}");
        assert!(
            !message.contains(".."),
            "issue #664 double period: {message}"
        );
        assert!(
            message.contains("Please recharge. Recharge the z.ai plan"),
            "{message}"
        );
    }

    #[tokio::test]
    async fn the_openai_response_is_insufficient_quota() {
        let exhaustion = classify(EXHAUSTED.as_bytes()).expect("exhaustion");
        let response = client_response(crate::metrics::Surface::OpenAIResponses, &exhaustion);
        assert_eq!(response.status(), StatusCode::PAYMENT_REQUIRED);
        let body = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        let value: Value = serde_json::from_slice(&body).expect("json");
        assert_eq!(value["error"]["code"], "insufficient_quota");
        assert_eq!(value["error"]["upstream_code"], "1113");
    }

    #[test]
    fn a_recorded_exhaustion_survives_a_restart_and_reaches_offline_status() {
        let data = tempfile::tempdir().unwrap();
        let store = crate::providers::ProviderStore::open(data.path(), "secret").unwrap();
        store.record_exhaustion("z-ai", classify(EXHAUSTED.as_bytes()).unwrap());

        let reopened = crate::providers::ProviderStore::open(data.path(), "secret").unwrap();
        let recorded = reopened.exhaustion("z-ai").unwrap();
        assert_eq!(recorded.code, 1113);
        assert_eq!(recorded.request_id.as_deref(), Some("20261004-abc"));
        let report = status_report(data.path());
        assert!(
            report.starts_with("provider_exhausted provider=z-ai upstream_code=1113 "),
            "{report}"
        );
        assert!(report.contains("Insufficient balance"), "{report}");

        reopened.clear_exhaustion("z-ai");
        assert!(!data.path().join(STATE_FILE).exists());

        assert_eq!(status_report(data.path()), "");
        let restarted = crate::providers::ProviderStore::open(data.path(), "secret").unwrap();
        assert!(restarted.exhaustion("z-ai").is_none());
    }

    #[test]
    fn doctor_names_every_data_dir_it_inspected_and_finds_a_deployment_record() {
        let own = tempfile::tempdir().unwrap();
        let deployment = tempfile::tempdir().unwrap();
        let (report, found) = doctor_report(&[own.path().into(), deployment.path().into()]);
        assert!(!found, "{report}");
        assert!(report.contains(&format!("none recorded in {}", own.path().display())));
        assert!(report.contains("DATA_DIR=DIR/data"), "{report}");

        let store = crate::providers::ProviderStore::open(deployment.path(), "secret").unwrap();
        store.record_exhaustion("z-ai", classify(EXHAUSTED.as_bytes()).unwrap());
        let (report, found) = doctor_report(&[
            own.path().into(),
            deployment.path().into(),
            deployment.path().into(),
        ]);
        assert!(found, "{report}");
        assert!(report.contains(&format!("recorded in {}", deployment.path().display())));
        assert_eq!(
            report.matches("provider_exhausted provider=z-ai").count(),
            1,
            "{report}"
        );
        assert!(!report.contains("DATA_DIR=DIR/data"), "{report}");
    }
}

//! Native Anthropic SSE assembly for clients that requested one JSON message.

use std::collections::BTreeMap;

use axum::body::{Body, to_bytes};
use axum::http::header::{CONTENT_LENGTH, CONTENT_TYPE, TRANSFER_ENCODING};
use axum::http::{HeaderValue, StatusCode};
use axum::response::Response;
use serde_json::{Map, Value};

const MAX_BUFFERED_RESPONSE: usize = 64 * 1024 * 1024;

/// Collapse a successful native Anthropic event stream into one Messages response.
pub async fn collect_response(response: Response, surface: crate::metrics::Surface) -> Response {
    if !response.status().is_success() || !is_event_stream(response.headers().get(CONTENT_TYPE)) {
        return response;
    }
    let (mut parts, body) = response.into_parts();
    let body = match to_bytes(body, MAX_BUFFERED_RESPONSE).await {
        Ok(body) => body,
        Err(error) => {
            return upstream_error(
                surface,
                &format!("z.ai response could not be buffered: {error}"),
            );
        }
    };
    let payload = match assemble(&body) {
        Ok(payload) => payload,
        Err(error) => {
            return upstream_error(surface, &format!("invalid z.ai event stream: {error}"));
        }
    };
    let body = match serde_json::to_vec(&payload) {
        Ok(body) => body,
        Err(error) => {
            return upstream_error(
                surface,
                &format!("z.ai response could not be encoded: {error}"),
            );
        }
    };
    parts.headers.remove(CONTENT_LENGTH);
    parts.headers.remove(TRANSFER_ENCODING);
    parts
        .headers
        .insert(CONTENT_TYPE, HeaderValue::from_static("application/json"));
    Response::from_parts(parts, Body::from(body))
}

fn upstream_error(surface: crate::metrics::Surface, message: &crate::translation_core::Str) -> Response {
    crate::api_error::error_response_for_surface(
        surface,
        StatusCode::BAD_GATEWAY,
        "api_error",
        message,
    )
}

fn is_event_stream(content_type: crate::translation_core::Maybe<&HeaderValue>) -> bool {
    content_type
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(';').next())
        .is_some_and(|value| value.trim().eq_ignore_ascii_case("text/event-stream"))
}

fn assemble(body: &[u8]) -> crate::translation_core::Outcome<crate::translation_core::Json, String> {
    let mut buffer = Vec::new();
    let mut message = None;
    let mut blocks = BTreeMap::<u64, Value>::new();
    let mut partial_inputs = BTreeMap::<u64, String>::new();
    let mut stopped = false;

    for block in crate::sse::push_blocks(&mut buffer, body) {
        let data = crate::openai::extract_sse_data(&block);
        if data.is_empty() {
            continue;
        }
        let event: Value = serde_json::from_str(&data)
            .map_err(|error| format!("event contains invalid JSON: {error}"))?;
        match event.get("type").and_then(Value::as_str) {
            Some("message_start") => {
                let started = event
                    .get("message")
                    .and_then(Value::as_object)
                    .ok_or("message_start omitted message")?;
                message = Some(Value::Object(started.clone()));
                if let Some(content) = started.get("content").and_then(Value::as_array) {
                    blocks.extend(
                        content
                            .iter()
                            .enumerate()
                            .map(|(index, value)| (index as u64, value.clone())),
                    );
                }
            }
            Some("content_block_start") => {
                let index = event_index(&event)?;
                let content = event
                    .get("content_block")
                    .and_then(Value::as_object)
                    .ok_or("content_block_start omitted content_block")?;
                blocks.insert(index, Value::Object(content.clone()));
            }
            Some("content_block_delta") => {
                apply_delta(
                    event_index(&event)?,
                    event
                        .get("delta")
                        .ok_or("content_block_delta omitted delta")?,
                    &mut blocks,
                    &mut partial_inputs,
                )?;
            }
            Some("content_block_stop") => {
                finish_input(event_index(&event)?, &mut blocks, &mut partial_inputs)?;
            }
            Some("message_delta") => {
                let current = message
                    .as_mut()
                    .ok_or("message_delta preceded message_start")?;
                merge_object(current, event.get("delta"));
                merge_named_object(current, "usage", event.get("usage"));
            }
            Some("message_stop") => stopped = true,
            Some("error") => {
                let detail = event
                    .pointer("/error/message")
                    .and_then(Value::as_str)
                    .unwrap_or("upstream emitted an error event");
                return Err(detail.to_string());
            }
            Some("ping") => {}
            Some(other) => return Err(format!("unsupported Anthropic event type {other}")),
            None => return Err("event omitted type".to_string()),
        }
    }
    if !buffer.iter().all(u8::is_ascii_whitespace) {
        return Err("event stream ended with an incomplete frame".to_string());
    }
    if !stopped {
        return Err("event stream omitted message_stop".to_string());
    }
    let mut message = message.ok_or("event stream omitted message_start")?;
    while let Some(index) = partial_inputs.keys().next().copied() {
        finish_input(index, &mut blocks, &mut partial_inputs)?;
    }
    message["content"] = Value::Array(blocks.into_values().collect());
    Ok(message)
}

fn event_index(event: &crate::translation_core::Json) -> crate::translation_core::Outcome<u64, String> {
    event
        .get("index")
        .and_then(crate::translation_core::Json::as_u64)
        .ok_or_else(|| "content event omitted index".to_string())
}

fn apply_delta(
    index: u64,
    delta: &Value,
    blocks: &mut BTreeMap<u64, Value>,
    partial_inputs: &mut BTreeMap<u64, String>,
) -> Result<(), String> {
    let kind = delta
        .get("type")
        .and_then(Value::as_str)
        .ok_or("content delta omitted type")?;
    let content = blocks
        .get_mut(&index)
        .ok_or_else(|| format!("content delta preceded block {index}"))?;
    match kind {
        "thinking_delta" => append_string(content, "thinking", delta.get("thinking"))?,
        "signature_delta" => append_string(content, "signature", delta.get("signature"))?,
        "text_delta" => append_string(content, "text", delta.get("text"))?,
        "input_json_delta" => {
            let fragment = delta
                .get("partial_json")
                .and_then(Value::as_str)
                .ok_or("input_json_delta omitted partial_json")?;
            partial_inputs.entry(index).or_default().push_str(fragment);
        }
        "citations_delta" => {
            let citation = delta
                .get("citation")
                .ok_or("citations_delta omitted citation")?;
            let object = content
                .as_object_mut()
                .ok_or("content block is not an object")?;
            object
                .entry("citations")
                .or_insert_with(|| Value::Array(Vec::new()))
                .as_array_mut()
                .ok_or("content citations is not an array")?
                .push(citation.clone());
        }
        other => return Err(format!("unsupported Anthropic delta type {other}")),
    }
    Ok(())
}

fn append_string(content: &mut Value, field: &str, addition: Option<&Value>) -> Result<(), String> {
    let addition = addition.and_then(Value::as_str).unwrap_or_default();
    let object = content
        .as_object_mut()
        .ok_or("content block is not an object")?;
    let current = object
        .get(field)
        .and_then(Value::as_str)
        .unwrap_or_default();
    object.insert(
        field.to_string(),
        Value::String(format!("{current}{addition}")),
    );
    Ok(())
}

fn finish_input(
    index: u64,
    blocks: &mut BTreeMap<u64, Value>,
    partial_inputs: &mut BTreeMap<u64, String>,
) -> Result<(), String> {
    let Some(input) = partial_inputs.remove(&index) else {
        return Ok(());
    };
    let parsed = serde_json::from_str(&input)
        .map_err(|error| format!("tool input for block {index} is invalid: {error}"))?;
    let block = blocks
        .get_mut(&index)
        .ok_or_else(|| format!("tool input preceded block {index}"))?;
    block
        .as_object_mut()
        .ok_or("content block is not an object")?
        .insert("input".to_string(), parsed);
    Ok(())
}

fn merge_object(target: &mut Value, source: Option<&Value>) {
    let (Some(target), Some(source)) = (target.as_object_mut(), source.and_then(Value::as_object))
    else {
        return;
    };
    target.extend(
        source
            .iter()
            .map(|(key, value)| (key.clone(), value.clone())),
    );
}

fn merge_named_object(target: &mut Value, name: &str, source: Option<&Value>) {
    let Some(source) = source.and_then(Value::as_object) else {
        return;
    };
    let target = target
        .as_object_mut()
        .expect("Anthropic message is an object")
        .entry(name)
        .or_insert_with(|| Value::Object(Map::new()));
    merge_object(target, Some(&Value::Object(source.clone())));
}

