//! Foreground provider authorization commands.

use std::process::ExitCode;

use link_assistant_router::cli::{AuthFlow, AuthOp, CLAUDE_AUTH_FLOWS, CODEX_AUTH_FLOWS};
use link_assistant_router::config::Config;
use link_assistant_router::login::{LoginManager, LoginStatus};
use link_assistant_router::subscription::{SubscriptionProvider, SubscriptionReader};

#[path = "auth_cli_status.rs"]
mod status_report;
use status_report::status;

pub async fn run(config: &Config, op: &AuthOp, names_local_state: bool) -> ExitCode {
    // Withdrawal is local by construction: it removes files this machine holds,
    // and there is no remote verb for it. Handled before the server dispatch so
    // `auth claude --clear` with a server selected cannot fall through to a
    // remote *authorize*, which is the opposite of what was asked (issue #268).
    if let Some(exit) = run_clear(config, op) {
        return exit;
    }
    // Import acts on the machine running it: it reads a directory here and
    // writes this deployment's credential home. Dispatched before the server
    // selection so `--from-claude-home` with a server selected cannot fall
    // through to a remote *authorize* (issue #274) — and `run_import` refuses
    // outright when a different router is the target, rather than answering
    // about the local home as though it were the one asked about (#291).
    if let Some(exit) = crate::auth_import::run_import(config, op).await {
        return exit;
    }
    // `auth` follows the selected server the way `with` does. Writing a local
    // credential while a server is selected made the obvious `server use` →
    // `auth` → `with` sequence silently authorize the wrong router (#246).
    match remote_target(op, names_local_state).await {
        Ok(Some(server)) => return run_remote(config, &server, op).await,
        Ok(None) => {}
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    }
    match op {
        AuthOp::Claude {
            code, flow, mode, ..
        } => {
            let mode = match mode.as_deref() {
                Some(value) => {
                    match link_assistant_router::claude_auth::ClaudeAuthMode::parse(value) {
                        Ok(mode) => mode,
                        Err(message) => {
                            eprintln!("error: {message}");
                            return ExitCode::from(2);
                        }
                    }
                }
                None => configured_mode(&config.login),
            };
            run_claude(config, code.clone(), *flow, mode).await
        }
        AuthOp::Codex { flow, port, .. } => run_codex(config, *flow, *port).await,
        AuthOp::Gh {
            from_gh_config,
            token_stdin,
            status,
            ..
        } => run_gh(config, from_gh_config.as_deref(), *token_stdin, *status),
        AuthOp::Status { .. } => status(config).await,
        // `run_clear` and `run_import` above return for every `Clear` and
        // `Import`, so reaching here means clap accepted a shape that dispatch
        // does not know about.
        AuthOp::Clear { .. } => {
            eprintln!("error: nothing to clear; name a provider or pass --all");
            ExitCode::from(2)
        }
        AuthOp::Import { .. } => {
            eprintln!("error: nothing to import; name a provider or pass --all");
            ExitCode::from(2)
        }
    }
}

/// Store, or report, the GitHub credential the proxy presents upstream.
///
/// The router acts on a caller's behalf against GitHub, so it holds an
/// operator credential of its own. Reading it from a mounted `gh` config lets
/// a deployment reuse an existing login instead of minting a second token
/// (issue #263).
fn run_gh(
    config: &link_assistant_router::config::Config,
    from_gh_config: Option<&str>,
    token_stdin: bool,
    status: bool,
) -> ExitCode {
    use link_assistant_router::github_proxy;

    let stored = github_proxy::stored_credential_path(std::path::Path::new(&config.data_dir));
    if status {
        let source = if stored.is_file() {
            format!("stored at {}", stored.display())
        } else if configured_github_credential(config) {
            "configured from the environment".to_string()
        } else {
            "absent".to_string()
        };
        println!("github credential: {source}");
        return ExitCode::SUCCESS;
    }

    let token = if token_stdin {
        match link_assistant_router::server_command::read_token() {
            Ok(token) => token,
            Err(error) => {
                eprintln!("error: {error}");
                return ExitCode::from(1);
            }
        }
    } else {
        let directory = from_gh_config
            .map(std::path::PathBuf::from)
            .or_else(github_proxy::gh_config_directory);
        let Some(directory) = directory else {
            eprintln!("error: no gh configuration directory; pass --from-gh-config <DIR>");
            return ExitCode::from(1);
        };
        let Some(host) = github_proxy::configured_credential_host() else {
            eprintln!("error: GITHUB_PROXY_BASE_URL does not name a valid GitHub host");
            return ExitCode::from(1);
        };
        let Some(token) = github_proxy::token_from_gh_config(&directory, &host) else {
            eprintln!(
                "error: no GitHub credential for {host} in {}; run `gh auth login --hostname {host}` there first",
                directory.display(),
            );
            return ExitCode::from(1);
        };
        token
    };

    match github_proxy::store_credential(std::path::Path::new(&config.data_dir), &token) {
        Ok(path) => {
            println!("stored the GitHub credential in {}", path.display());
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

/// Withdraw stored credentials, when this invocation asked to.
///
/// `None` means no `--clear` was requested and the ordinary path should run.
///
/// Each provider reports what was removed and what remains, because a
/// withdrawal that quietly left a credential readable somewhere else is worse
/// than one that never ran: the operator believes the deployment holds no
/// identity when it still does.
fn run_clear(config: &link_assistant_router::config::Config, op: &AuthOp) -> Option<ExitCode> {
    use link_assistant_router::cli::ImportProvider;

    // A name `auth` does not know as a built-in may still be a provider added
    // through `providers add`. Resolved before the match below, because those
    // names are free-form and must not be read as a malformed built-in
    // (issue #561).
    let requested = match op {
        AuthOp::Clear {
            provider: Some(name),
            ..
        } => Some(name.as_str()),
        _ => None,
    };
    let named = requested.and_then(ImportProvider::from_name);
    // Not a built-in: withdraw it from the provider store instead, but only
    // after the target refusal below has had its say. A withdrawal aimed at
    // another deployment must refuse here exactly as it does for a
    // subscription (issue #305).
    let named_api_key = requested.filter(|_| named.is_none());

    let (providers, clears_github): (&[SubscriptionProvider], bool) = match (op, named) {
        (AuthOp::Claude { clear: true, .. }, _)
        | (AuthOp::Clear { .. }, Some(ImportProvider::Claude)) => {
            (&[SubscriptionProvider::Claude], false)
        }
        (AuthOp::Codex { clear: true, .. }, _)
        | (AuthOp::Clear { .. }, Some(ImportProvider::Codex)) => {
            (&[SubscriptionProvider::Codex], false)
        }
        (AuthOp::Clear { .. }, Some(ImportProvider::Gemini)) => {
            (&[SubscriptionProvider::Gemini], false)
        }
        (AuthOp::Clear { .. }, Some(ImportProvider::Qwen)) => {
            (&[SubscriptionProvider::Qwen], false)
        }
        (AuthOp::Gh { clear: true, .. }, _) | (AuthOp::Clear { .. }, Some(ImportProvider::Gh)) => {
            (&[], true)
        }
        (
            AuthOp::Status {
                clear_all: true, ..
            }
            | AuthOp::Clear { all: true, .. },
            _,
        ) => (&SubscriptionProvider::ALL, true),
        // A named API-key provider withdraws nothing from the built-in set; the
        // work happens after the target refusal below.
        (AuthOp::Clear { .. }, None) if named_api_key.is_some() => (&[], false),
        _ => return None,
    };

    // Withdrawal removes files on the machine it runs on, and no router
    // accepts one over HTTP. Naming a server was parsed, accepted and thrown
    // away, so the report read exactly as it would have if the named
    // deployment had been cleared (issue #305). The #283/#291 refusal shape
    // sat on the path this short-circuits past, so it could never fire.
    let target = clear_target(op);
    // The selection counts, not only the flag. Every other command on this
    // path resolves the router this machine is pointed at; checking `--server`
    // alone meant `server use https://prod` then `auth clear --all` withdrew
    // five local credentials while the operator, the persisted selection and
    // this command's own help all said `prod` (issue #305). `--local` is the
    // way to say "this machine" out loud, so it opts out.
    let selected = if target.local {
        None
    } else if let Some(server) = target.server.as_deref() {
        match link_assistant_router::managed_server::canonical_server_origin(server) {
            Ok(server) => Some(server),
            Err(error) => {
                eprintln!("error: {error}");
                return Some(ExitCode::from(1));
            }
        }
    } else {
        match link_assistant_router::managed_server::selected_server() {
            Ok(server) => server,
            Err(error) => {
                eprintln!("error: {error}");
                return Some(ExitCode::from(1));
            }
        }
    };
    if let Some(server) = selected.as_deref() {
        eprintln!(
            "error: clearing a credential removes files on the machine it runs on, so it cannot \
             clear {server} from here."
        );
        eprintln!(
            "note: run the same command on that deployment; `router auth status --server {server}` \
             reports its credentials from here."
        );
        eprintln!("note: pass --local to clear this machine instead.");
        return Some(ExitCode::from(1));
    }

    // The target is settled, so a named API-key provider can now be withdrawn.
    if let Some(name) = named_api_key {
        return Some(clear_named_api_key_provider(config, name));
    }

    // `--all` promises "every login this deployment holds", so it must reach
    // the API-key providers too: a stored key authorizes this deployment
    // against an upstream vendor exactly as an OAuth login does, and leaving
    // them behind reported a clean deployment that could still serve live
    // inference (issue #561).
    let clears_api_keys = matches!(
        op,
        AuthOp::Status {
            clear_all: true,
            ..
        } | AuthOp::Clear { all: true, .. }
    );
    let api_key_providers = if clears_api_keys {
        stored_api_key_providers(config)
    } else {
        Vec::new()
    };

    // More than one credential in one call, and an OAuth login cannot be put
    // back without a browser. `--clear-all` made that the widest blast radius
    // in the tool and asked nothing.
    let affected = providers.len() + usize::from(clears_github) + api_key_providers.len();
    if affected > 1 && !clear_confirmed(op) {
        eprintln!(
            "error: this removes {affected} credentials from this machine and an OAuth login \
             cannot be restored without a browser."
        );
        eprintln!("note: pass --yes to proceed, or name one provider: `router auth clear claude`.");
        return Some(ExitCode::from(1));
    }

    let mut failed = false;
    for provider in providers {
        if let Err(error) = clear_provider(config, *provider) {
            eprintln!("error: {error}");
            failed = true;
        }
    }
    if clears_github && let Err(error) = clear_github(config) {
        eprintln!("error: {error}");
        failed = true;
    }
    for provider in &api_key_providers {
        if let Err(error) = clear_api_key_provider(config, provider) {
            eprintln!("error: {error}");
            failed = true;
        }
    }
    // Deleting a local file does not revoke anything upstream, and an operator
    // who believes it did has a false sense of cleanup.
    println!(
        "note: this removes local credentials only; a token minted for this \
         deployment is still valid upstream and should be revoked there."
    );
    Some(if failed {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    })
}

/// Remove one provider's credential files, reporting what went and what stayed.
fn clear_provider(
    config: &link_assistant_router::config::Config,
    provider: SubscriptionProvider,
) -> Result<(), String> {
    let user_home = config.client_home.to_string_lossy().into_owned();
    let reader = SubscriptionReader::new(
        provider,
        crate::auth_import::provider_home(config, provider, &user_home),
    );
    let removed = reader.clear_credentials()?;
    if removed.is_empty() {
        println!("{provider:<8} absent");
    } else {
        for path in removed {
            println!("{provider:<8} removed {}", path.display());
        }
    }
    // The vendor CLI's own store is not the router's to delete: removing it
    // would log the user out of a client the router does not own. Naming it is
    // the honest middle, since the router will still read a credential from
    // there and report the provider as usable.
    if let Some(service) =
        link_assistant_router::platform_keychain::service_name(provider).map(|base| {
            if provider == SubscriptionProvider::Claude {
                link_assistant_router::platform_keychain::claude_service_for(
                    crate::operation_context::var_os("CLAUDE_CONFIG_DIR").as_deref(),
                )
            } else {
                base.to_owned()
            }
        })
        && link_assistant_router::platform_keychain::has_entry(&service)
    {
        println!(
            "{provider:<8} note: the {service:?} keychain entry still holds a credential; \
             it belongs to the vendor CLI, so remove it there (or with `security \
             delete-generic-password -s {service:?}`) if this deployment should hold none"
        );
    }
    Ok(())
}

/// Open the provider store for a withdrawal or a report.
///
/// `auth` must run without a `TOKEN_SECRET` — recovering a subscription cannot
/// be made to depend on an unrelated secret — and neither listing nor deleting
/// a record decrypts its key. Only `resolve`, which this path never calls,
/// needs a real secret, so whatever the config carries is enough here.
fn open_provider_store(
    config: &link_assistant_router::config::Config,
) -> Option<link_assistant_router::providers::ProviderStore> {
    link_assistant_router::providers::ProviderStore::open(&config.data_dir, &config.token_secret)
        .ok()
}

/// The API-key providers this deployment holds a credential for.
///
/// A provider with neither a stored key nor an environment key names no
/// credential to withdraw, so it is left out rather than reported as removed.
fn stored_api_key_providers(
    config: &link_assistant_router::config::Config,
) -> Vec<link_assistant_router::providers::RedactedProviderRecord> {
    let Some(store) = open_provider_store(config) else {
        return Vec::new();
    };
    store
        .list_redacted()
        .unwrap_or_default()
        .into_iter()
        .filter(|record| record.has_encrypted_api_key || record.api_key_env.is_some())
        .collect()
}

/// Withdraw one API-key provider's stored credential.
///
/// The record is removed rather than merely disabled: `auth clear` withdraws a
/// credential, and a disabled row still holds the key the operator believes
/// they took away.
fn clear_api_key_provider(
    config: &link_assistant_router::config::Config,
    record: &link_assistant_router::providers::RedactedProviderRecord,
) -> Result<(), String> {
    let store = open_provider_store(config)
        .ok_or_else(|| format!("cannot open the provider store to clear {}", record.name))?;
    let name = &record.name;
    if store.delete(name).map_err(|error| error.to_string())? {
        println!("{name:<8} removed the stored API key and provider entry");
    } else {
        println!("{name:<8} absent");
    }
    // An environment-supplied key outlives the record: the router reads it from
    // the process environment, so removing the row does not withdraw it.
    if let Some(variable) = record.api_key_env.as_deref()
        && crate::operation_context::var(variable).is_ok_and(|value| !value.is_empty())
    {
        println!(
            "{name:<8} note: {variable} still holds a key in this environment; unset it there \
             if this deployment should hold none"
        );
    }
    Ok(())
}

/// Withdraw a credential named by a provider the operator configured.
///
/// Reached only when the name is not one of the built-in credentials, so an
/// unknown name must say so rather than report a clean withdrawal of nothing.
fn clear_named_api_key_provider(
    config: &link_assistant_router::config::Config,
    name: &str,
) -> ExitCode {
    let Some(store) = open_provider_store(config) else {
        eprintln!("error: cannot open the provider store to clear {name}");
        return ExitCode::from(1);
    };
    let record = match store.get(name) {
        Ok(Some(record)) => record.redacted(),
        Ok(None) => {
            eprintln!(
                "error: no credential named {name}; `router auth status` lists what this \
                 deployment holds"
            );
            return ExitCode::from(1);
        }
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    };
    if let Err(error) = clear_api_key_provider(config, &record) {
        eprintln!("error: {error}");
        return ExitCode::from(1);
    }
    println!(
        "note: this removes local credentials only; a key minted for this \
         deployment is still valid upstream and should be revoked there."
    );
    ExitCode::SUCCESS
}

/// Whether a GitHub credential is configured for *this* deployment.
///
/// Resolved against `config.data_dir` rather than `DATA_DIR`, so a credential
/// stored through `--data-dir` is seen here exactly as the server sees it at
/// startup (issue #282).
fn configured_github_credential(config: &link_assistant_router::config::Config) -> bool {
    link_assistant_router::github_proxy::GitHubProxyConfig::from_env_with_data_dir(Some(
        config.data_dir.as_path(),
    ))
    .is_ok_and(|github| github.enabled())
}

/// Remove the stored GitHub credential, naming any that remains configured.
fn clear_github(config: &link_assistant_router::config::Config) -> Result<(), String> {
    use link_assistant_router::github_proxy;

    let data_dir = std::path::Path::new(&config.data_dir);
    let path = github_proxy::stored_credential_path(data_dir);
    if github_proxy::clear_credential(data_dir)? {
        println!("github   removed {}", path.display());
    } else {
        println!("github   absent");
    }
    // The proxy resolves a credential from several places, and only one of them
    // is the router's. Saying so prevents "I cleared it and the routes are
    // still mounted" from looking like a bug.
    if configured_github_credential(config) {
        println!(
            "github   note: a credential is still configured from the environment or a \
             mounted gh config, so the GitHub routes stay enabled"
        );
    }
    println!("github   note: the GitHub routes are mounted at startup; restart to withdraw them");
    Ok(())
}

/// The router this `auth` invocation acts on, or `None` for the local one.
/// The target a withdrawal names, whichever spelling asked for it.
const fn clear_target(op: &AuthOp) -> &link_assistant_router::cli::AuthTarget {
    match op {
        AuthOp::Claude { target, .. }
        | AuthOp::Codex { target, .. }
        | AuthOp::Gh { target, .. }
        | AuthOp::Status { target, .. }
        | AuthOp::Clear { target, .. }
        | AuthOp::Import { target, .. } => target,
    }
}

/// Whether the operator confirmed a multi-credential removal.
const fn clear_confirmed(op: &AuthOp) -> bool {
    match op {
        AuthOp::Clear { yes, .. } | AuthOp::Status { yes, .. } => *yes,
        _ => false,
    }
}

async fn remote_target(
    op: &AuthOp,
    names_local_state: bool,
) -> Result<Option<link_assistant_router::managed_server::ResolvedServer>, String> {
    let target = match op {
        AuthOp::Claude { target, .. }
        | AuthOp::Codex { target, .. }
        | AuthOp::Gh { target, .. }
        | AuthOp::Clear { target, .. }
        | AuthOp::Status { target, .. } => target,
        // Never reached: `run_import` returns for every `Import`, either having
        // performed a local import or having refused a remote one (#291).
        AuthOp::Import { .. } => return Ok(None),
    };
    // `--claude-code-home` and `--data-dir` name *this machine's* state, so a
    // router *discovered* here must not answer for them: that reports about a
    // different deployment than the one the operator pointed at (issue #294).
    //
    // Only for the verb that reports. `auth claude`/`codex`/`gh` *store* a
    // credential, and letting a local-state flag suppress the refusal would
    // leave the workstation holding a token aimed at a deployment — the leak
    // issue #268 exists to prevent, and one an environment-set `DATA_DIR`
    // would trigger without anybody passing a flag.
    let reports_rather_than_stores = matches!(op, AuthOp::Status { .. });
    if names_local_state && reports_rather_than_stores && target.server.is_none() {
        return Ok(None);
    }
    link_assistant_router::auth_remote::target_for(
        target.local,
        target.managed,
        target.server.as_deref(),
        target.management_server.as_deref(),
    )
    .await
}

async fn run_remote(
    config: &Config,
    server: &link_assistant_router::managed_server::ResolvedServer,
    op: &AuthOp,
) -> ExitCode {
    match op {
        AuthOp::Claude { code, mode, .. } => {
            link_assistant_router::auth_remote::authorize(
                server,
                "claude",
                mode.as_deref(),
                code.clone(),
            )
            .await
        }
        AuthOp::Codex { .. } => {
            link_assistant_router::auth_remote::authorize(server, "codex", None, None).await
        }
        AuthOp::Status { .. } => link_assistant_router::auth_remote::status(server).await,
        // What `auth gh` may do remotely is decided by `AuthOp::remote_gh`,
        // beside the flags it reads, so the rule is unit-testable rather than
        // reachable only by spawning the binary (issue #283).
        AuthOp::Gh { .. } => {
            if matches!(
                op.remote_gh(),
                Some(link_assistant_router::cli::RemoteGh::DescribeLocal)
            ) {
                println!(
                    "note: describing this machine's credential; {} keeps its own, which \
                     `auth gh` cannot read from here",
                    server.base_url
                );
                run_gh(config, None, false, true)
            } else {
                eprintln!(
                    "error: a GitHub credential is read from the router's own data directory \
                     at startup, so it cannot be stored on {} from here.\n\
                     note: run `router auth gh` on that deployment (or set GITHUB_PROXY_TOKEN \
                     there), then restart it. Pass --local to act on this machine's data \
                     directory instead.",
                    server.base_url
                );
                ExitCode::from(1)
            }
        }
        // Never reached: `remote_target` keeps import on the local path.
        // Unreachable: `run_clear` and `run_import` return before dispatch.
        AuthOp::Clear { .. } | AuthOp::Import { .. } => ExitCode::from(1),
    }
}

fn claude_supports_flow(flow: AuthFlow) -> bool {
    CLAUDE_AUTH_FLOWS.contains(&flow)
}

fn codex_supports_flow(flow: AuthFlow) -> bool {
    CODEX_AUTH_FLOWS.contains(&flow)
}

/// The login mode `LOGIN_CLI_ARGS` selects, mirroring
/// [`link_assistant_router::login::LoginManager::configured_mode`] for the
/// foreground command.
fn configured_mode(
    login: &link_assistant_router::login::LoginConfig,
) -> link_assistant_router::claude_auth::ClaudeAuthMode {
    if login.args.iter().any(|argument| argument == "setup-token") {
        link_assistant_router::claude_auth::ClaudeAuthMode::SetupToken
    } else {
        link_assistant_router::claude_auth::ClaudeAuthMode::Full
    }
}

async fn run_claude(
    config: &Config,
    code: Option<String>,
    flow: AuthFlow,
    mode: link_assistant_router::claude_auth::ClaudeAuthMode,
) -> ExitCode {
    if !claude_supports_flow(flow) {
        eprintln!("error: Claude does not support {flow:?}; use --flow code or --flow cli");
        return ExitCode::from(1);
    }
    let mut login_config = config.login.clone();
    // Disabling HTTP login routes must not disable this local CLI command.
    login_config.enabled = true;
    if flow == AuthFlow::Cli {
        if code.is_some() {
            eprintln!("error: --code requires --flow code; the CLI fallback starts its own login");
            return ExitCode::from(2);
        }
        return run_claude_cli_fallback(config, login_config, code).await;
    }
    let has_code = code.is_some();
    match complete_native_claude(config, code, mode).await {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) if flow == AuthFlow::Auto && !has_code => {
            eprintln!("native Claude OAuth failed: {error}");
            eprintln!("Trying a disposable Claude Code CLI fallback…");
            run_claude_cli_fallback(config, login_config, None).await
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

async fn complete_native_claude(
    config: &Config,
    code: Option<String>,
    mode: link_assistant_router::claude_auth::ClaudeAuthMode,
) -> Result<(), String> {
    let auth_config = link_assistant_router::claude_auth::ClaudeAuthConfig::for_mode(
        config.login.claude_code_home.clone(),
        mode,
    );
    let submitted = if let Some(code) = code {
        code
    } else {
        let login = link_assistant_router::claude_auth::ClaudeLogin::begin_persisted(
            auth_config.clone(),
            config.login.session_ttl,
        )?;
        println!("Open this URL:\n{}", login.authorization_url());
        read_code().await?
    };
    if submitted.trim().is_empty() {
        return Err(
            "no authorization code was supplied; the pending login was kept for `router auth claude --flow code --code <CODE>`"
                .to_string(),
        );
    }
    let login = link_assistant_router::claude_auth::ClaudeLogin::resume(auth_config)?;
    login
        .complete_with_data_dir(submitted.trim(), &config.data_dir)
        .await?;
    println!(
        "Claude authorization saved in {}",
        config.login.claude_code_home.display()
    );
    Ok(())
}

async fn complete_claude_cli(
    config: &Config,
    manager: &LoginManager,
    code: Option<String>,
) -> Result<(), String> {
    let begun = match manager.begin().await {
        Ok(view) => view,
        Err(error) => return Err(error.to_string()),
    };
    println!("Open this URL:\n{}", begun.url.as_deref().unwrap_or(""));
    let submitted = match code {
        Some(code) => code,
        None => match read_code().await {
            Ok(code) => code,
            Err(error) => return Err(error),
        },
    };
    match manager.submit_code(&begun.login_id, submitted.trim()).await {
        Ok(view) if view.status == LoginStatus::Authorized => {
            println!(
                "Claude authorization saved in {}",
                config.login.claude_code_home.display()
            );
            Ok(())
        }
        Ok(view) => Err(view
            .error
            .unwrap_or_else(|| "authorization failed".to_string())),
        Err(error) => Err(error.to_string()),
    }
}

async fn run_claude_cli_fallback(
    config: &Config,
    login_config: link_assistant_router::login::LoginConfig,
    code: Option<String>,
) -> ExitCode {
    let (_disposable, fallback_config) =
        match link_assistant_router::on_demand_cli::DisposableCli::claude(&login_config) {
            Ok(value) => value,
            Err(error) => {
                eprintln!("error: {error}");
                return ExitCode::from(1);
            }
        };
    let manager = LoginManager::new_with_data_dir(fallback_config, config.data_dir.clone());
    match complete_claude_cli(config, &manager, code).await {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

async fn read_code() -> Result<String, String> {
    println!("Paste authorization code:");
    tokio::task::spawn_blocking(|| {
        let mut line = String::new();
        std::io::stdin()
            .read_line(&mut line)
            .map(|_| line)
            .map_err(|error| format!("could not read authorization code: {error}"))
    })
    .await
    .map_err(|error| format!("authorization prompt failed: {error}"))?
}

async fn run_codex(config: &Config, flow: AuthFlow, port: u16) -> ExitCode {
    if !codex_supports_flow(flow) {
        eprintln!("error: Codex does not support {flow:?}; use --flow device or --flow loopback");
        return ExitCode::from(1);
    }
    if matches!(flow, AuthFlow::Auto | AuthFlow::Device) {
        return run_codex_device(config, port).await;
    }
    if !matches!(port, 1455 | 1457) {
        eprintln!("error: Codex OAuth registers loopback ports 1455 and 1457 only");
        return ExitCode::from(2);
    }
    let mut settings = link_assistant_router::auth::CodexAuthConfig::production(
        config.login.codex_home.clone(),
        port,
        config.login.session_ttl,
    );
    settings.issuer.clone_from(&config.login.codex_issuer);
    let login = match link_assistant_router::auth::CodexLogin::bind(settings).await {
        Ok(login) => login,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    };
    println!("Open this URL:\n{}", login.authorization_url());
    println!("Waiting for the browser callback on port {}…", login.port());
    match login.complete_with_data_dir(&config.data_dir).await {
        Ok(path) => {
            println!("Codex authorization saved in {}", path.display());
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

async fn run_codex_device(config: &Config, port: u16) -> ExitCode {
    let mut settings = link_assistant_router::auth::CodexAuthConfig::production(
        config.login.codex_home.clone(),
        port,
        config.login.session_ttl,
    );
    settings.issuer.clone_from(&config.login.codex_issuer);
    let login = match link_assistant_router::auth::CodexDeviceLogin::begin(settings).await {
        Ok(login) => login,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(1);
        }
    };
    println!(
        "Open this URL:\n{}\nEnter this one-time code:\n{}",
        login.verification_url(),
        login.user_code()
    );
    println!("Waiting for device authorization…");
    match login.complete_with_data_dir(&config.data_dir).await {
        Ok(path) => {
            println!("Codex authorization saved in {}", path.display());
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[cfg(target_os = "macos")]
    #[test]
    fn clear_note_checks_only_scoped_keychain_presence() {
        use crate::operation_context::{OperationContext, ProcessRunner};
        use std::os::unix::process::ExitStatusExt as _;
        use std::process::{Command, Output};
        use std::sync::{Arc, Mutex};
        use std::time::Duration;

        #[derive(Default)]
        struct Presence(Mutex<Vec<Vec<String>>>);
        impl ProcessRunner for Presence {
            fn output(&self, command: &mut Command, _: Duration) -> std::io::Result<Output> {
                assert_eq!(command.get_program(), "/usr/bin/security");
                let args: Vec<_> = command
                    .get_args()
                    .map(|a| a.to_string_lossy().into_owned())
                    .collect();
                assert!(!args.iter().any(|a| a == "-w" || a == "-g"));
                self.0.lock().unwrap().push(args);
                Ok(Output {
                    status: std::process::ExitStatus::from_raw(256),
                    stdout: Vec::new(),
                    stderr: Vec::new(),
                })
            }
        }
        let root = tempfile::tempdir().unwrap();
        let profile = root.path().join("selected-profile");
        let runner = Arc::new(Presence::default());
        let mut context = OperationContext::isolated(root.path());
        context.set_env("CLAUDE_CONFIG_DIR", profile.as_os_str());
        context.set_env("TOKEN_SECRET", "clear-presence-fixture");
        context.process_runner = Some(runner.clone());
        context.scope(|| {
            clear_provider(
                &crate::config::Config::from_env().unwrap(),
                SubscriptionProvider::Claude,
            )
            .unwrap()
        });
        assert_eq!(
            *runner.0.lock().unwrap(),
            [vec![
                "find-generic-password".to_owned(),
                "-s".to_owned(),
                crate::platform_keychain::claude_service_for(Some(profile.as_os_str()))
            ]]
        );
    }

    /// A duration an operator reads at a glance, at each boundary.
    ///
    /// Truncating to whole hours reported 119 minutes as "1 hours", which
    /// understates a credential enough to matter when the question is whether
    /// to re-authenticate now.
    #[test]
    fn a_remaining_lifetime_reads_in_the_largest_useful_unit() {
        assert_eq!(crate::auth_import::humanize_minutes(0), "0 minutes");
        assert_eq!(crate::auth_import::humanize_minutes(45), "45 minutes");
        // Below the hour threshold minutes stay minutes, so a credential with
        // an hour left is not rounded into sounding like a day.
        assert_eq!(crate::auth_import::humanize_minutes(89), "89 minutes");
        assert_eq!(crate::auth_import::humanize_minutes(90), "1 hours");
        assert_eq!(crate::auth_import::humanize_minutes(60 * 47), "47 hours");
        assert_eq!(crate::auth_import::humanize_minutes(60 * 48), "2 days");
        assert_eq!(
            crate::auth_import::humanize_minutes(60 * 24 * 30),
            "30 days"
        );
    }

    /// The import report says the two things that decide what to do next: how
    /// long the credential lasts, and whether it can be renewed at all.
    #[test]
    fn an_imported_credential_describes_its_lifetime_and_renewability() {
        let now = crate::operation_context::now().timestamp_millis();
        let renewable = link_assistant_router::subscription::SubscriptionToken {
            access_token: "a".into(),
            refresh_token: Some("r".into()),
            expires_at_ms: Some(now + 6 * 3_600_000),
            account_id: None,
            resource_url: None,
        };
        let described = crate::auth_import::describe_credential(&renewable);
        assert!(described.contains("expires in"), "{described}");
        assert!(described.contains("refresh token present"), "{described}");

        // Without a refresh token the credential dies at expiry and no recovery
        // rung can save it, which is worth saying rather than implying.
        let terminal = link_assistant_router::subscription::SubscriptionToken {
            refresh_token: None,
            expires_at_ms: Some(now - 3_600_000),
            ..renewable.clone()
        };
        let described = crate::auth_import::describe_credential(&terminal);
        assert!(described.contains("EXPIRED"), "{described}");
        assert!(described.contains("cannot be renewed"), "{described}");

        let undated = link_assistant_router::subscription::SubscriptionToken {
            expires_at_ms: None,
            ..renewable
        };
        assert!(
            crate::auth_import::describe_credential(&undated).contains("no recorded expiry"),
            "an unknown expiry must not be reported as an expired one"
        );
    }

    #[test]
    fn provider_flow_support_matrix_matches_the_oauth_implementations() {
        let cases = [
            (AuthFlow::Auto, true, true),
            (AuthFlow::Device, false, true),
            (AuthFlow::Code, true, false),
            (AuthFlow::Loopback, false, true),
            (AuthFlow::Cli, true, false),
        ];

        for (flow, claude_supported, codex_supported) in cases {
            assert_eq!(claude_supports_flow(flow), claude_supported, "{flow:?}");
            assert_eq!(codex_supports_flow(flow), codex_supported, "{flow:?}");
        }
    }

    /// Recovering a subscription must not require an unrelated secret
    /// (issue #205). The rule is now stated once, for every command that does
    /// not serve (issues #300, #308), so this pins `auth` against it.
    #[test]
    fn auth_runs_without_a_token_secret_but_other_commands_still_need_one() {
        use link_assistant_router::cli::Cli;
        use lino_arguments::Parser as _;

        let relaxed = link_assistant_router::remote_command::relax_token_secret_for_cli(
            Cli::try_parse_from(["bin", "auth", "status"]).expect("parses auth"),
        );
        assert!(
            relaxed.into_config().is_ok(),
            "auth must not demand TOKEN_SECRET"
        );

        // A secret the operator did supply is never overwritten.
        let supplied = link_assistant_router::remote_command::relax_token_secret_for_cli(
            Cli::try_parse_from(["bin", "--token-secret", "real-secret", "auth", "status"])
                .expect("parses auth"),
        );
        assert_eq!(supplied.token_secret.as_deref(), Some("real-secret"));

        // Serving still requires a real secret.
        let serving = link_assistant_router::remote_command::relax_token_secret_for_cli(
            Cli::try_parse_from(["bin", "serve"]).expect("parses serve"),
        );
        assert!(
            serving.into_config().is_err(),
            "serve must still demand TOKEN_SECRET"
        );
    }
}

//! `auth status`: what each credential is, and which store is real.
//!
//! Split from `auth_cli.rs` to keep that file within the repository's 1000-line
//! limit. The table is two questions an operator asks together: is this
//! credential accepted by the vendor, and is this deployment following the
//! vendor client's own store or holding a copy that will drift (issue #574).

use std::process::ExitCode;

use link_assistant_router::config::Config;
use link_assistant_router::subscription::{SubscriptionProvider, SubscriptionReader};

use super::stored_api_key_providers;

/// Report each provider credential's state, verified against the vendor.
///
/// The verdict used to come entirely from the stored `exp` claim, so a
/// credential the vendor had already invalidated printed `usable` while every
/// request through it returned `401` (issue #205). A local timestamp cannot
/// answer this question: only the vendor can. Each credential is therefore
/// probed, and the answer says plainly whether it was checked or merely read.
pub(super) async fn status(config: &Config) -> ExitCode {
    let user_home = config.client_home.to_string_lossy().into_owned();
    let client = reqwest::Client::new();
    let readers: Vec<_> = SubscriptionProvider::ALL
        .into_iter()
        .map(|provider| {
            SubscriptionReader::new(
                provider,
                crate::auth_import::provider_home(config, provider, &user_home),
            )
        })
        .collect();
    let token_cache =
        link_assistant_router::refresh::TokenCache::registered_for(&readers, &config.data_dir);
    let reports =
        link_assistant_router::credential_status::evaluate(&client, &token_cache, &readers, None)
            .await;
    let refresh_failed = reports.iter().any(|report| {
        report.state
            == link_assistant_router::credential_status::CredentialAcceptanceState::RefreshFailed
    });
    // Which store is real. Two holders of one rotating chain is the failure in
    // issue #574, and an operator could not previously tell "following, current"
    // from "a copy taken at time T" — nor see that a followed home had been
    // removed, which is the state that looks healthy and is not.
    let sources = link_assistant_router::credential_source::report(&readers);
    crate::operation_output::report(crate::operation_reports::AuthStatusReport {
        server: None,
        credentials: reports.clone(),
        sources: sources.clone(),
        api_key_providers: stored_api_key_providers(config),
        output: Vec::new(),
    });
    for report in reports {
        if let Some(detail) = report.detail.as_deref() {
            eprintln!(
                "error: {} refresh failed: {detail}; credential state was not reported usable",
                report.provider
            );
        }
        let source = sources
            .iter()
            .find(|entry| entry.provider == report.provider)
            .map(|entry| &entry.source);
        println!(
            "{:<8} {:<14} {:<12} {}",
            report.provider,
            report.state.as_str(),
            source.map_or("copy", |source| source.as_str()),
            report.home
        );
        // A followed source that has gone missing is not a detail: the
        // deployment has no usable credential, however healthy the rest of the
        // row looks. Named on stderr so it survives a piped table.
        if let Some(
            source @ link_assistant_router::credential_source::CredentialSource::Followed {
                present: false,
                ..
            },
        ) = source
        {
            eprintln!("warning: {} {}", report.provider, source.explain());
        }
    }
    // The API-key providers authorize this deployment against an upstream
    // vendor exactly as the subscriptions above do. Reporting only the
    // OAuth-style set printed an all-absent table on a deployment that could
    // still reach two vendors, which is the surprise issue #561 is about.
    for record in stored_api_key_providers(config) {
        let held = if record.has_encrypted_api_key {
            "stored"
        } else {
            "from-env"
        };
        let state = if record.enabled { held } else { "disabled" };
        // An API key is a value, not a rotating chain, so no follow state
        // applies; the column is filled in rather than left ragged.
        println!(
            "{:<8} {state:<14} {:<12} {}",
            record.name, "api-key", record.base_url
        );
    }
    if refresh_failed {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

//! `router auth import` — adopt a login this machine already has.
//!
//! Split from `auth_cli.rs` to keep that file within the repository's
//! 1000-line limit.
//!
//! Authorizing and importing are different operations, not variations of one:
//! authorizing goes and gets a new credential interactively, importing adopts
//! one that already exists. They differ in prerequisites, side effects, and
//! whether a human has to be present — which decides whether a headless
//! deployment can be provisioned at all (issue #278).

use std::process::ExitCode;

use link_assistant_router::cli::{AuthOp, ImportProvider};
use link_assistant_router::credential_acceptance::AcceptedCredential as ValidatedCandidate;
#[cfg(test)]
use link_assistant_router::credential_acceptance::catalog_base_for_candidate;
use link_assistant_router::subscription::{
    ImportSource, InstallDocumentResult, InstallMode, SubscriptionProvider, SubscriptionReader,
};

#[path = "auth_import_result.rs"]
mod import_result;
#[path = "auth_import_resume.rs"]
mod import_resume;

use import_result::{ImportExecution, ImportFailure, ImportOutcome, ImportPhase, finish};

/// Vendor evidence gathered before an import may touch its destination.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[allow(dead_code)]
enum CredentialProbe {
    Accepted,
    Rejected,
    Unverified,
}

/// Destination and rejection policy selected by the public import flags.
#[derive(Debug, Clone, Copy, Default)]
struct ImportPolicy {
    if_absent: bool,
    /// Whether the caller explicitly asserted the safe-flow capability. This
    /// is diagnostic only and never bypasses candidate validation.
    capability_asserted: bool,
    /// A retained acceptance transaction contains a Router-owned successor
    /// whose refresh chain may be advanced during recovery. Fresh imports keep
    /// this false because the source remains owned by the vendor client.
    router_owned_candidate: bool,
    /// Whether the credential is followed, copied, or followed-or-refused.
    sharing: CredentialSharing,
}

/// How the imported credential relates to the vendor client's own store.
///
/// One three-state choice rather than two flags, so "follow *and* snapshot" —
/// which clap already rejects at the command line — cannot be constructed here
/// either (issue #574).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum CredentialSharing {
    /// Follow the vendor's file where possible; copy where it is not, saying so.
    ///
    /// The historical default: following keeps one refresh chain with one
    /// refresher, and a copy still beats refusing to provision at all.
    #[default]
    PreferFollow,
    /// Follow or refuse. A copy that will drift is not an acceptable outcome.
    RequireFollow,
    /// Copy deliberately, for a caller that wants the credential frozen.
    Snapshot,
}

/// Adopt an existing vendor login, when this invocation asked to.
///
/// `None` means no import was requested and the ordinary path should run.
pub async fn run_import(
    config: &link_assistant_router::config::Config,
    op: &AuthOp,
) -> Option<ExitCode> {
    let json = matches!(op, AuthOp::Import { json: true, .. });
    // Import writes this machine's credential home. When another router is the
    // target, doing that anyway produced an error naming the *local* home as
    // though it were the one asked about — a wrong-target action wearing an
    // answer that looks coherent (issue #291). Refuse before any local work.
    if let Some(failure) = refuse_a_remote_import(op).await {
        return Some(finish(&[ImportExecution::failed(None, failure)], json));
    }
    let policy = match op {
        AuthOp::Import {
            if_absent,
            force,
            follow,
            snapshot,
            ..
        } => ImportPolicy {
            if_absent: *if_absent,
            capability_asserted: *force,
            router_owned_candidate: false,
            sharing: match (*follow, *snapshot) {
                (true, _) => CredentialSharing::RequireFollow,
                (_, true) => CredentialSharing::Snapshot,
                _ => CredentialSharing::PreferFollow,
            },
        },
        _ => ImportPolicy::default(),
    };
    let requested: Vec<(
        ImportProvider,
        String,
        Option<import_resume::ResumeCandidate>,
    )> = match op {
        AuthOp::Claude {
            from_claude_home: Some(source),
            ..
        } => vec![(ImportProvider::Claude, source.clone(), None)],
        AuthOp::Codex {
            from_codex_home: Some(source),
            ..
        } => vec![(ImportProvider::Codex, source.clone(), None)],
        AuthOp::Import {
            resume: Some(transaction_id),
            ..
        } => match import_resume::resolve_claimed(&config.data_dir, transaction_id).await {
            Ok(candidate) => vec![(
                candidate.provider,
                candidate.source.clone(),
                Some(candidate),
            )],
            Err(failure) => {
                return Some(finish(&[ImportExecution::failed(None, failure)], json));
            }
        },
        AuthOp::Import { all: true, .. } => [
            ImportProvider::Claude,
            ImportProvider::Codex,
            ImportProvider::Gemini,
            ImportProvider::Qwen,
            ImportProvider::Gh,
        ]
        .into_iter()
        .map(|provider| (provider, String::new(), None))
        .collect(),
        AuthOp::Import {
            provider: Some(provider),
            dir,
            ..
        } => vec![(*provider, dir.clone().unwrap_or_default(), None)],
        _ => return None,
    };
    // `--all` adopts what is there and reports what is not, rather than failing
    // on the first provider this machine never logged in to: a workstation with
    // two of five logins is the ordinary case, not an error.
    let adopting_everything = matches!(op, AuthOp::Import { all: true, .. });
    let mut executions = Vec::with_capacity(requested.len());
    for (provider, source, resumed) in requested {
        let outcome = match provider {
            ImportProvider::Gh if policy.if_absent => Err(ImportFailure::not_attempted(
                "--if-absent is supported only for Claude, Codex, Gemini, and Qwen; GitHub import keeps its existing replacement behavior",
            )),
            ImportProvider::Gh => import_github(&config.data_dir, &source)
                .map(|messages| ImportExecution::promoted("github", messages))
                .map_err(ImportFailure::not_attempted),
            other => {
                let Some(subscription) = subscription_of(other) else {
                    continue;
                };
                let mut provider_policy = policy;
                provider_policy.router_owned_candidate = resumed.is_some();
                if resumed.as_ref().is_some_and(|candidate| {
                    destination_has_receipt(config, subscription, &candidate.transaction_id)
                }) {
                    Ok(ImportExecution::promoted(
                        subscription.to_string(),
                        vec![format!(
                            "{subscription:<8} promotion was already committed; completing retained transaction cleanup"
                        )],
                    ))
                } else {
                    import_provider(
                        config,
                        subscription,
                        &source,
                        provider_policy,
                        resumed
                            .as_ref()
                            .map(|candidate| candidate.transaction_id.as_str()),
                    )
                    .await
                }
            }
        };
        let outcome = if let Some(candidate) = resumed.as_ref() {
            reconcile_resumed_import(candidate, outcome)
        } else {
            outcome
        };
        let execution = match outcome {
            Ok(execution) => execution,
            Err(failure) => {
                let absent = adopting_everything && failure.error.starts_with("no ");
                let message = absent.then(|| {
                    format!(
                        "{}: nothing to adopt ({})",
                        provider_label(provider),
                        failure.error
                    )
                });
                let execution = ImportExecution::failed(Some(provider_label(provider)), failure);
                if let Some(message) = message {
                    execution.ignore_failure(message)
                } else {
                    execution
                }
            }
        };
        executions.push(execution);
    }
    Some(finish(&executions, json))
}

/// A resume begins with an already uncertain transaction. Only promotion can
/// retire that uncertainty. A fresh uncertain retry replaces the predecessor
/// transaction; every other result keeps the original recovery ID authoritative.
fn reconcile_resumed_import(
    candidate: &import_resume::ResumeCandidate,
    outcome: Result<ImportExecution, ImportFailure>,
) -> Result<ImportExecution, ImportFailure> {
    match outcome {
        Ok(mut execution) if execution.is_promoted() => {
            if let Err(warning) = import_resume::retire(candidate) {
                execution.mark_cleanup_pending(
                    candidate.transaction_id.clone(),
                    format!("{warning}; retry this transaction ID to complete cleanup"),
                );
            }
            Ok(execution)
        }
        Ok(_) => Err(ImportFailure::retained(
            ImportPhase::Preflight,
            candidate.transaction_id.clone(),
            format!(
                "the destination is already present; retained import transaction {} still requires recovery",
                candidate.transaction_id
            ),
        )),
        Err(failure)
            if matches!(
                failure.outcome,
                ImportOutcome::ExchangeUncertain
                    | ImportOutcome::PersistenceUncertain
                    | ImportOutcome::SuccessorRetained
            ) =>
        {
            let _retired_predecessor = import_resume::retire(candidate);
            Err(failure)
        }
        Err(failure) => Err(ImportFailure::retained(
            failure.phase,
            candidate.transaction_id.clone(),
            format!(
                "{}; retained import transaction {} still requires recovery",
                failure.error, candidate.transaction_id
            ),
        )),
    }
}

/// Refuse an import aimed at a router other than this machine.
///
/// A credential can only be installed where the process running the import can
/// write, and a router reads its subscription credentials from its own home at
/// startup. Nothing accepts a credential document over HTTP — `/api/management/login`
/// begins an interactive OAuth flow and `submit_code` takes a short-lived
/// code, neither of which adopts a credential that already exists. So there is
/// no remote import to perform, and the honest move is to say so.
///
/// The alternative is what shipped: `--server` parsed and was discarded, and
/// the command answered about the local home. `error: claude is already read
/// from /Users/me/.claude` reads as a coherent reply to a question about the
/// selected server, which is worse than a plain refusal — the operator cannot
/// tell the target was never consulted (issue #291).
///
/// `--local` is the way to ask for this machine, and `--managed` is a local
/// disposable container, so both keep the ordinary path.
async fn refuse_a_remote_import(op: &AuthOp) -> Option<ImportFailure> {
    // Decided from the flags alone, so `--local` never contacts a server and
    // never fails because one is unreachable. The per-provider
    // `--from-*-home` flags carry no target and stay local, as they always
    // were.
    if !op.may_be_remote() {
        return None;
    }
    let AuthOp::Import { target, .. } = op else {
        return None;
    };
    let server = match link_assistant_router::auth_remote::target_for(
        target.local,
        target.managed,
        target.server.as_deref(),
        target.management_server.as_deref(),
    )
    .await
    {
        Ok(Some(server)) => server,
        Ok(None) => return None,
        Err(error) => {
            // An unreachable *named* target is an error in its own right;
            // falling back to a local import is the surprise being fixed.
            return Some(ImportFailure::not_attempted(error));
        }
    };
    // Name the directory the credential would have to land in, when the router
    // will say. "Not from here" alone leaves the operator to guess the next
    // step; the path is the instruction.
    let destination = match op {
        AuthOp::Import {
            provider: Some(provider),
            ..
        } => {
            link_assistant_router::auth_remote::credential_home(&server, provider_label(*provider))
                .await
        }
        _ => None,
    };
    let error = link_assistant_router::auth_remote::remote_import_refusal(
        &server.base_url,
        destination.as_deref(),
    )
    .join("\n");
    Some(ImportFailure::not_attempted(error))
}

/// The subscription an import target names, when it names one.
const fn subscription_of(provider: ImportProvider) -> Option<SubscriptionProvider> {
    match provider {
        ImportProvider::Claude => Some(SubscriptionProvider::Claude),
        ImportProvider::Codex => Some(SubscriptionProvider::Codex),
        ImportProvider::Gemini => Some(SubscriptionProvider::Gemini),
        ImportProvider::Qwen => Some(SubscriptionProvider::Qwen),
        ImportProvider::Gh => None,
    }
}

/// How an import target names itself in a report.
const fn provider_label(provider: ImportProvider) -> &'static str {
    match provider {
        ImportProvider::Claude => "claude",
        ImportProvider::Codex => "codex",
        ImportProvider::Gemini => "gemini",
        ImportProvider::Qwen => "qwen",
        ImportProvider::Gh => "github",
    }
}

/// Adopt the GitHub credential a `gh` login already holds.
///
/// Shares `run_gh`'s reader so the two spellings cannot drift, and reports in
/// the same column format the subscription imports use.
fn import_github(data_dir: &std::path::Path, source: &str) -> Result<Vec<String>, String> {
    use link_assistant_router::github_proxy;

    let directory = Some(source)
        .filter(|source| !source.trim().is_empty())
        .map(std::path::PathBuf::from)
        .or_else(github_proxy::gh_config_directory)
        .ok_or_else(|| {
            String::from("no gh configuration directory; name one, or set GH_CONFIG_DIR")
        })?;
    let host = github_proxy::configured_credential_host()
        .ok_or_else(|| String::from("GITHUB_PROXY_BASE_URL does not name a valid GitHub host"))?;
    let token = github_proxy::token_from_gh_config(&directory, &host).ok_or_else(|| {
        format!(
            "no GitHub credential for {host} in {}; run `gh auth login --hostname {host}` there first",
            directory.display(),
        )
    })?;
    let path = github_proxy::store_credential(data_dir, &token)?;
    let mut messages = vec![format!(
        "github   imported {} from {}",
        path.display(),
        directory.display()
    )];
    // The GitHub routes are decided at startup from whether a credential
    // exists, so adopting one mid-run does not mount them.
    messages.push(
        "github   note: the GitHub routes are mounted at startup; restart to serve them"
            .to_string(),
    );
    Ok(messages)
}

/// Adopt a vendor credential into this deployment's home, and say what it is.
async fn import_provider(
    config: &link_assistant_router::config::Config,
    provider: SubscriptionProvider,
    source: &str,
    policy: ImportPolicy,
    resumed_transaction_id: Option<&str>,
) -> Result<ImportExecution, ImportFailure> {
    let user_home = config.client_home.to_string_lossy().into_owned();
    let destination_home = provider_home(config, provider, &user_home);
    let catalog_base_url_override = import_catalog_base_url_override();
    import_provider_with_paths(
        &config.data_dir,
        &user_home,
        &destination_home,
        provider,
        source,
        policy,
        resumed_transaction_id,
        catalog_base_url_override.as_deref(),
    )
    .await
}

fn import_catalog_base_url_override() -> Option<String> {
    #[cfg(debug_assertions)]
    {
        crate::operation_context::var("LINK_ASSISTANT_ROUTER_TEST_CATALOG_BASE_URL")
            .ok()
            .filter(|value| !value.trim().is_empty())
    }
    #[cfg(not(debug_assertions))]
    {
        None
    }
}

#[allow(clippy::too_many_arguments)]
async fn import_provider_with_paths(
    data_dir: &std::path::Path,
    user_home: &str,
    destination_home: &std::path::Path,
    provider: SubscriptionProvider,
    source: &str,
    policy: ImportPolicy,
    resumed_transaction_id: Option<&str>,
    catalog_base_url_override: Option<&str>,
) -> Result<ImportExecution, ImportFailure> {
    // An empty value asks for the vendor's own default location.
    //
    // Deliberately not `resolve_home`, which honours `CLAUDE_CODE_HOME` and
    // friends — in a deployment those name the router's *destination*, so
    // resolving the source that way makes every unqualified import refuse
    // itself as a self-import (issue #278). The vendor's conventional home is
    // the thing an operator means by "the login this machine already has".
    let source_home = if source.trim().is_empty() {
        provider.conventional_home(user_home)
    } else {
        std::path::PathBuf::from(source)
    };
    if same_credential_home(&source_home, destination_home) {
        // A deployment that reads the vendor's own home already holds whatever
        // is there; there is nothing to copy, and copying a file onto itself
        // would truncate it.
        return Err(ImportFailure::not_attempted(format!(
            "{provider} is already read from {}, so there is nothing to adopt",
            destination_home.display()
        )));
    }

    let destination = SubscriptionReader::new(provider, destination_home);
    // Conditional provisioning must win without even reading a malformed or
    // externally owned source. Installation repeats the same check after the
    // catalog request while holding the destination transaction lock.
    if policy.if_absent && destination.has_platform_store_credential() {
        return Ok(ImportExecution::already_present(
            provider.to_string(),
            vec![format!(
                "{provider:<8} already present in the platform credential store; the candidate was not read, validated, or installed"
            )],
        ));
    }
    if policy.if_absent
        && let Some(path) = destination
            .existing_document_locked(
                data_dir,
                link_assistant_router::credential_recovery_store::PRIMARY_ACCOUNT,
            )
            .await
            .map_err(ImportFailure::not_attempted)?
    {
        return Ok(ImportExecution::already_present(
            provider.to_string(),
            vec![format!(
                "{provider:<8} already present at {}; the candidate was not read, validated, or installed",
                path.display()
            )],
        ));
    }

    let from = SubscriptionReader::new(provider, &source_home);
    // One selection yields the bytes, their verdict, and their origin. Reading
    // the source a second time to describe it is what let the report and the
    // installed credential name different things (issue #280).
    let source_credential = from.read_document_for_import().map_err(|error| {
        ImportFailure::not_attempted(match error {
            link_assistant_router::subscription::SubscriptionError::NoCredentials(message) => {
                format!("no {provider} credential to import: {message}")
            }
            other => format!("invalid {provider} candidate credential: {other}"),
        })
    })?;
    let ImportSource {
        document,
        token: _,
        origin,
        path,
    } = source_credential;
    let where_from = match origin {
        link_assistant_router::platform_keychain::Origin::Keychain => {
            link_assistant_router::platform_keychain::service_name(provider).map_or_else(
                || String::from("the platform keychain"),
                |service| format!("keychain {service:?}"),
            )
        }
        link_assistant_router::platform_keychain::Origin::File
        | link_assistant_router::platform_keychain::Origin::ExternalFile
        | link_assistant_router::platform_keychain::Origin::AdoptedFile => {
            path.as_ref().map_or_else(
                || source_home.display().to_string(),
                |path| path.display().to_string(),
            )
        }
    };
    // Following is the default and always was: a reference keeps one refresh
    // chain with one refresher, so the deployment and the vendor client cannot
    // spend each other's tokens. What `--follow` adds is a *requirement* — the
    // fallback to a drifting copy becomes a refusal that names the obstacle —
    // and `--snapshot` asks for that copy on purpose (issue #574).
    let external_source =
        if policy.router_owned_candidate || policy.sharing == CredentialSharing::Snapshot {
            None
        } else {
            match prepare_external_source(provider, origin, path.as_deref(), &destination) {
                Ok(source) => Some(source),
                // Without `--follow` an unreferenceable source still imports as a
                // copy, exactly as before; the operator is told it will drift.
                Err(failure) if policy.sharing != CredentialSharing::RequireFollow => {
                    eprintln!(
                        "warning: {provider} is imported as a copy rather than followed: {}. \
                     The vendor client will rotate past this copy, and it will then need \
                     re-importing; `--follow` refuses instead of copying.",
                        failure.error
                    );
                    None
                }
                Err(failure) => return Err(failure),
            }
        };

    // A fresh import validates only the current access token. Redeeming its
    // refresh token would invalidate the vendor client's copy before Router
    // had installed anything. Only a claimed Router-owned recovery transaction
    // may advance its own chain here.
    let validated = validate_candidate_at(
        data_dir,
        provider,
        &document,
        policy.router_owned_candidate,
        None,
        catalog_base_url_override,
    )
    .await?;
    let report = describe_credential(validated.token());
    if (policy.if_absent && destination.has_platform_store_credential())
        || (!policy.if_absent
            && destination.candidate_is_shadowed_by_platform_store(validated.token()))
    {
        let error = format!(
            "the {provider} platform credential remains authoritative; the external source was not installed"
        );
        if policy.router_owned_candidate {
            return Err(retain_validated_candidate(
                validated,
                ImportPhase::Promotion,
                error,
            ));
        }
        drop(validated);
        return Err(ImportFailure::safe_failure(ImportPhase::Promotion, error));
    }
    let receipt_id = resumed_transaction_id
        .unwrap_or_else(|| validated.transaction_id())
        .to_string();
    let promotion_document = match external_source.as_ref().map_or_else(
        || {
            link_assistant_router::subscription::mark_promotion_receipt(
                validated.document(),
                &receipt_id,
            )
        },
        |source| {
            link_assistant_router::subscription::reference_external_credential(source, &receipt_id)
        },
    ) {
        Ok(document) => document,
        Err(error) => {
            if policy.router_owned_candidate {
                return Err(retain_validated_candidate(
                    validated,
                    ImportPhase::Promotion,
                    error,
                ));
            }
            drop(validated);
            return Err(ImportFailure::safe_failure(ImportPhase::Promotion, error));
        }
    };
    let promotion = install_candidate(
        &destination,
        data_dir,
        &promotion_document,
        CredentialProbe::Accepted,
        policy,
    )
    .await;
    let installed = match promotion {
        Ok(installed) => installed,
        Err(_error) if destination_has_receipt_at(&destination, &receipt_id) => {
            let path = destination.discover_credential_path().ok_or_else(|| {
                ImportFailure::safe_failure(
                    ImportPhase::Promotion,
                    format!("the committed {provider} credential could not be located"),
                )
            })?;
            InstallDocumentResult::Installed(path)
        }
        Err(error) => {
            if policy.router_owned_candidate {
                return Err(retain_validated_candidate(
                    validated,
                    ImportPhase::Promotion,
                    error,
                ));
            }
            drop(validated);
            return Err(ImportFailure::safe_failure(ImportPhase::Promotion, error));
        }
    };
    let execution = match installed {
        InstallDocumentResult::Installed(path) => {
            let messages = vec![
                format!(
                    "{provider:<8} imported {} from {where_from}",
                    path.display()
                ),
                external_source.as_ref().map_or_else(
                    || format!(
                        "{provider:<8} candidate {report}, Router-owned refresh chain validated and promoted"
                    ),
                    |source| format!(
                        "{provider:<8} candidate {report}, current access accepted without OAuth exchange; Router and the vendor client share the authoritative file at {}",
                        source.display()
                    ),
                ),
            ];
            // The isolated validation copy is never authoritative. A fresh
            // import leaves the complete bytes at the vendor source; a resumed
            // transaction has copied them into the destination above.
            drop(validated);
            ImportExecution::promoted(provider.to_string(), messages)
        }
        InstallDocumentResult::AlreadyPresent(path) => {
            if !policy.router_owned_candidate {
                drop(validated);
                return Ok(ImportExecution::already_present(
                    provider.to_string(),
                    vec![format!(
                        "{provider:<8} already present at {}; the external candidate from {where_from} was validated but not installed",
                        path.display()
                    )],
                ));
            }
            return Err(retain_validated_candidate(
                validated,
                ImportPhase::Promotion,
                format!(
                    "a credential appeared at {}; the validated {provider} successor from {where_from} was retained for recovery",
                    path.display()
                ),
            ));
        }
    };
    Ok(execution)
}

fn prepare_external_source(
    provider: SubscriptionProvider,
    origin: link_assistant_router::platform_keychain::Origin,
    path: Option<&std::path::Path>,
    destination: &SubscriptionReader,
) -> Result<std::path::PathBuf, ImportFailure> {
    if origin == link_assistant_router::platform_keychain::Origin::Keychain {
        return Err(ImportFailure::not_attempted(format!(
            "the selected {provider} credential exists only in the platform keychain; let the vendor client expose a current writable credential file before import"
        )));
    }
    if origin == link_assistant_router::platform_keychain::Origin::ExternalFile {
        return Err(ImportFailure::not_attempted(format!(
            "the selected {provider} credential is externally owned but does not identify its authoritative writable source"
        )));
    }
    let path = path.ok_or_else(|| {
        ImportFailure::not_attempted(format!(
            "the selected {provider} credential has no authoritative writable source file"
        ))
    })?;
    let source = std::fs::canonicalize(path).map_err(|_| {
        ImportFailure::not_attempted(format!(
            "the selected {provider} credential source is not a readable file"
        ))
    })?;
    if destination
        .credential_paths()
        .iter()
        .filter_map(|candidate| std::fs::canonicalize(candidate).ok())
        .any(|candidate| candidate == source)
    {
        return Err(ImportFailure::not_attempted(format!(
            "the selected {provider} source is also a Router destination credential"
        )));
    }
    let parent = source.parent().ok_or_else(|| {
        ImportFailure::not_attempted(format!(
            "the selected {provider} credential source has no writable directory"
        ))
    })?;
    let probe = tempfile::Builder::new()
        .prefix(".router-import-write-check-")
        .tempfile_in(parent)
        .map_err(|_| {
            ImportFailure::not_attempted(format!(
                "the selected {provider} credential source cannot be replaced atomically; make its directory writable before import"
            ))
        })?;
    probe.as_file().sync_all().map_err(|_| {
        ImportFailure::not_attempted(format!(
            "the selected {provider} credential source cannot be persisted durably"
        ))
    })?;
    probe.close().map_err(|_| {
        ImportFailure::not_attempted(format!(
            "the selected {provider} credential source write check could not be cleaned up"
        ))
    })?;
    Ok(source)
}

fn destination_has_receipt(
    config: &link_assistant_router::config::Config,
    provider: SubscriptionProvider,
    transaction_id: &str,
) -> bool {
    let user_home = config.client_home.to_string_lossy().into_owned();
    let destination =
        SubscriptionReader::new(provider, provider_home(config, provider, &user_home));
    destination_has_receipt_at(&destination, transaction_id)
}

fn destination_has_receipt_at(destination: &SubscriptionReader, transaction_id: &str) -> bool {
    destination
        .discover_credential_path()
        .and_then(|path| std::fs::read_to_string(path).ok())
        .is_some_and(|document| {
            link_assistant_router::subscription::has_promotion_receipt(&document, transaction_id)
        })
}

async fn validate_candidate_at(
    data_dir: &std::path::Path,
    provider: SubscriptionProvider,
    document: &str,
    rotate_candidate: bool,
    token_url_override: Option<&str>,
    catalog_base_url_override: Option<&str>,
) -> Result<ValidatedCandidate, ImportFailure> {
    let accepted = if rotate_candidate {
        link_assistant_router::credential_acceptance::accept_candidate(
            data_dir,
            provider,
            document,
            token_url_override,
            catalog_base_url_override,
        )
        .await
    } else {
        link_assistant_router::credential_acceptance::accept_external_candidate(
            data_dir,
            provider,
            document,
            catalog_base_url_override,
        )
        .await
    };
    accepted.map_err(|failure| ImportFailure::from_acceptance(&failure))
}

fn retain_validated_candidate(
    validated: ValidatedCandidate,
    phase: ImportPhase,
    error: String,
) -> ImportFailure {
    let transaction_id = validated.transaction_id().to_string();
    std::mem::forget(validated);
    ImportFailure::retained(phase, transaction_id, error)
}

fn same_credential_home(source: &std::path::Path, destination: &std::path::Path) -> bool {
    if source == destination {
        return true;
    }
    match (
        std::fs::canonicalize(source),
        std::fs::canonicalize(destination),
    ) {
        (Ok(source), Ok(destination)) => source == destination,
        _ => false,
    }
}

/// Validate a credential in a Router-owned store that is isolated from the
/// serving destination.
///
/// Endpoint overrides exist only so the unit matrix can exercise the exact
/// four vendor layouts and request order against a loopback vendor. Production
/// always uses the provider's public OAuth endpoint and a Router-validated
/// catalog origin; a candidate-controlled `resource_url` can therefore never
/// send the refreshed bearer token outside the vendor allowlist.
#[cfg(test)]
async fn validate_candidate_with(
    data_dir: &std::path::Path,
    provider: SubscriptionProvider,
    document: &str,
    token_url_override: Option<&str>,
    catalog_base_url_override: Option<&str>,
) -> Result<ValidatedCandidate, ImportFailure> {
    validate_candidate_at(
        data_dir,
        provider,
        document,
        true,
        token_url_override,
        catalog_base_url_override,
    )
    .await
}

/// Enforce candidate acceptance policy, then enter the shared writer boundary.
async fn install_candidate(
    destination: &SubscriptionReader,
    data_dir: &std::path::Path,
    document: &str,
    probe: CredentialProbe,
    policy: ImportPolicy,
) -> Result<InstallDocumentResult, String> {
    if policy.capability_asserted {
        tracing::debug!("caller asserted safe-refresh-chain-import-v1");
    }
    let refusal = (probe != CredentialProbe::Accepted).then(|| {
        format!(
            "{} candidate was not accepted by the vendor and cannot be installed",
            destination.provider()
        )
    });
    if !policy.if_absent
        && let Some(error) = refusal
    {
        return Err(error);
    }
    let mode = if policy.if_absent {
        InstallMode::IfAbsent
    } else {
        InstallMode::Replace
    };
    destination
        .install_document_locked_with_refusal(
            data_dir,
            link_assistant_router::credential_recovery_store::PRIMARY_ACCOUNT,
            document,
            mode,
            refusal,
        )
        .await
}

/// What an operator needs to know about a credential at import time.
#[must_use]
pub fn describe_credential(
    token: &link_assistant_router::subscription::SubscriptionToken,
) -> String {
    let now = crate::operation_context::now().timestamp_millis();
    let expiry = token.expires_at_ms.map_or_else(
        || String::from("no recorded expiry"),
        |expires_at| {
            let minutes = (expires_at - now) / 60_000;
            if expires_at <= now {
                format!("EXPIRED {} ago", humanize_minutes(-minutes))
            } else {
                format!("expires in {}", humanize_minutes(minutes))
            }
        },
    );
    // Without a refresh token the credential cannot be rotated, so it stops
    // working at expiry and no recovery rung can save it. Worth saying plainly.
    let refresh = if token.refresh_token.is_some() {
        "refresh token present"
    } else {
        "NO refresh token, so it cannot be renewed"
    };
    format!("{expiry}, {refresh}")
}

/// A duration an operator reads at a glance.
///
/// Truncating to whole hours reported a credential with 119 minutes left as
/// "1 hours", which understates it enough to matter when the question being
/// asked is whether to re-authenticate now.
#[must_use]
pub fn humanize_minutes(minutes: i64) -> String {
    if minutes < 90 {
        return format!("{minutes} minutes");
    }
    let hours = minutes / 60;
    if hours < 48 {
        return format!("{hours} hours");
    }
    format!("{} days", hours / 24)
}

/// The credential home this deployment reads `provider` from.
#[must_use]
pub fn provider_home(
    config: &link_assistant_router::config::Config,
    provider: SubscriptionProvider,
    _user_home: &str,
) -> std::path::PathBuf {
    config.credential_home(provider)
}

