//! Stable machine-readable results for `router auth import`.

use std::process::ExitCode;

#[cfg(test)]
use link_assistant_router::refresh::ImportRefreshFailureKind;
use serde::Serialize;

/// Public import outcomes. These serialized spellings are a compatibility
/// contract for automation and must not be inferred from diagnostic prose.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub(super) enum ImportOutcome {
    NotAttempted,
    ExchangeRejected,
    ExchangeUncertain,
    PersistenceUncertain,
    SuccessorRetained,
    Promoted,
    PromotionCleanupPending,
    AlreadyPresent,
}

/// The last import phase reached before the reported outcome.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub(super) enum ImportPhase {
    Preflight,
    Exchange,
    Persistence,
    Catalog,
    Promotion,
}

/// The only fields emitted as JSON. Deliberately excludes diagnostic strings,
/// paths, source documents, and tokens.
#[derive(Debug, PartialEq, Eq, Serialize, schemars::JsonSchema)]
pub(super) struct ImportReport {
    pub(super) provider: Option<String>,
    pub(super) outcome: ImportOutcome,
    pub(super) phase: ImportPhase,
    pub(super) previous_credential_safe: bool,
    pub(super) transaction_id: Option<String>,
}

#[derive(Serialize, schemars::JsonSchema)]
pub(super) struct ImportEnvelope<'a> {
    schema_version: u8,
    results: Vec<&'a ImportReport>,
}

/// Internal failure with human diagnostic text kept outside the JSON report.
#[derive(Debug)]
pub(super) struct ImportFailure {
    pub(super) outcome: ImportOutcome,
    pub(super) phase: ImportPhase,
    pub(super) previous_credential_safe: bool,
    pub(super) transaction_id: Option<String>,
    pub(super) error: String,
}

impl ImportFailure {
    pub(super) fn not_attempted(error: impl Into<String>) -> Self {
        Self::safe_failure(ImportPhase::Preflight, error)
    }

    pub(super) fn safe_failure(phase: ImportPhase, error: impl Into<String>) -> Self {
        Self {
            outcome: ImportOutcome::NotAttempted,
            phase,
            previous_credential_safe: true,
            transaction_id: None,
            error: error.into(),
        }
    }

    pub(super) fn retained(
        phase: ImportPhase,
        transaction_id: String,
        error: impl Into<String>,
    ) -> Self {
        Self {
            outcome: ImportOutcome::SuccessorRetained,
            phase,
            previous_credential_safe: false,
            transaction_id: Some(transaction_id),
            error: error.into(),
        }
    }

    /// Convert the shared acceptance classification without parsing its
    /// redacted human diagnostic. Only uncertain failures retain a transaction.
    pub(super) fn from_acceptance(
        failure: &link_assistant_router::credential_acceptance::AcceptanceFailure,
    ) -> Self {
        use link_assistant_router::credential_acceptance::{
            AcceptanceFailureKind, AcceptancePhase,
        };
        let phase = match failure.phase() {
            AcceptancePhase::Preflight => ImportPhase::Preflight,
            AcceptancePhase::Exchange => ImportPhase::Exchange,
            AcceptancePhase::Persistence => ImportPhase::Persistence,
            AcceptancePhase::Catalog => ImportPhase::Catalog,
            AcceptancePhase::Promotion => ImportPhase::Promotion,
        };
        let error = failure.to_string();
        match failure.kind() {
            AcceptanceFailureKind::NotAttempted => Self::safe_failure(phase, error),
            AcceptanceFailureKind::ExchangeRejected => Self {
                outcome: ImportOutcome::ExchangeRejected,
                phase,
                previous_credential_safe: true,
                transaction_id: None,
                error,
            },
            AcceptanceFailureKind::ExchangeUncertain => Self {
                outcome: ImportOutcome::ExchangeUncertain,
                phase,
                previous_credential_safe: false,
                transaction_id: None,
                error,
            },
            AcceptanceFailureKind::PersistenceUncertain => Self {
                outcome: ImportOutcome::PersistenceUncertain,
                phase,
                previous_credential_safe: false,
                transaction_id: None,
                error,
            },
            AcceptanceFailureKind::SuccessorRetained => Self {
                outcome: ImportOutcome::SuccessorRetained,
                phase,
                previous_credential_safe: false,
                transaction_id: failure.transaction_id().map(str::to_string),
                error,
            },
        }
    }

    #[cfg(test)]
    fn from_refresh_kind(
        kind: ImportRefreshFailureKind,
        error: String,
        _transaction_id: &str,
    ) -> Self {
        match kind {
            ImportRefreshFailureKind::NotAttempted => Self::not_attempted(error),
            ImportRefreshFailureKind::ExchangeRejected => Self {
                outcome: ImportOutcome::ExchangeRejected,
                phase: ImportPhase::Exchange,
                previous_credential_safe: true,
                transaction_id: None,
                error,
            },
            ImportRefreshFailureKind::ExchangeUncertain => Self {
                outcome: ImportOutcome::ExchangeUncertain,
                phase: ImportPhase::Exchange,
                previous_credential_safe: false,
                transaction_id: None,
                error,
            },
            ImportRefreshFailureKind::PersistenceUncertain => Self {
                outcome: ImportOutcome::PersistenceUncertain,
                phase: ImportPhase::Persistence,
                previous_credential_safe: false,
                transaction_id: None,
                error,
            },
        }
    }

    #[cfg(test)]
    pub(super) fn from_refresh_kind_for_test(
        kind: ImportRefreshFailureKind,
        transaction_id: &str,
    ) -> Self {
        Self::from_refresh_kind(kind, "redacted failure".to_string(), transaction_id)
    }

    #[cfg(test)]
    pub(super) fn contains(&self, pattern: &str) -> bool {
        self.error.contains(pattern)
    }
}

impl std::fmt::Display for ImportFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(&self.error)
    }
}

/// One provider's structured result plus human-only presentation details.
pub(super) struct ImportExecution {
    report: ImportReport,
    messages: Vec<String>,
    error: Option<String>,
    failed: bool,
}

impl ImportExecution {
    pub(super) fn promoted(provider: impl Into<String>, messages: Vec<String>) -> Self {
        Self::success(
            provider,
            ImportOutcome::Promoted,
            ImportPhase::Promotion,
            false,
            messages,
        )
    }

    pub(super) fn already_present(provider: impl Into<String>, messages: Vec<String>) -> Self {
        Self::success(
            provider,
            ImportOutcome::AlreadyPresent,
            ImportPhase::Preflight,
            true,
            messages,
        )
    }

    fn success(
        provider: impl Into<String>,
        outcome: ImportOutcome,
        phase: ImportPhase,
        previous_credential_safe: bool,
        messages: Vec<String>,
    ) -> Self {
        Self {
            report: ImportReport {
                provider: Some(provider.into()),
                outcome,
                phase,
                previous_credential_safe,
                transaction_id: None,
            },
            messages,
            error: None,
            failed: false,
        }
    }

    pub(super) fn failed(provider: Option<&str>, failure: ImportFailure) -> Self {
        Self {
            report: ImportReport {
                provider: provider.map(str::to_string),
                outcome: failure.outcome,
                phase: failure.phase,
                previous_credential_safe: failure.previous_credential_safe,
                transaction_id: failure.transaction_id,
            },
            messages: Vec::new(),
            error: Some(failure.error),
            failed: true,
        }
    }

    pub(super) fn ignore_failure(mut self, message: String) -> Self {
        self.messages.push(message);
        self.error = None;
        self.failed = false;
        self
    }

    pub(super) const fn is_promoted(&self) -> bool {
        matches!(self.report.outcome, ImportOutcome::Promoted)
    }

    pub(super) fn mark_cleanup_pending(&mut self, transaction_id: String, error: String) {
        self.report.outcome = ImportOutcome::PromotionCleanupPending;
        self.report.phase = ImportPhase::Promotion;
        self.report.transaction_id = Some(transaction_id);
        self.error = Some(error);
        self.failed = true;
    }
}

/// Render all providers exactly once and return the aggregate process status.
pub(super) fn finish(executions: &[ImportExecution], json: bool) -> ExitCode {
    if json {
        let reports = executions
            .iter()
            .map(|execution| &execution.report)
            .collect::<Vec<_>>();
        let envelope = ImportEnvelope {
            schema_version: 1,
            results: reports,
        };
        println!(
            "{}",
            serde_json::to_string(&envelope).expect("fixed import result schema must serialize")
        );
    } else {
        for execution in executions {
            for message in &execution.messages {
                println!("{message}");
            }
            if let Some(error) = &execution.error {
                eprintln!("error: {error}");
            }
        }
    }
    if executions.iter().any(|execution| execution.failed) {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

#[cfg(test)]
pub(super) fn json_value(executions: &[ImportExecution]) -> serde_json::Value {
    let reports = executions
        .iter()
        .map(|execution| &execution.report)
        .collect::<Vec<_>>();
    serde_json::to_value(ImportEnvelope {
        schema_version: 1,
        results: reports,
    })
    .expect("fixed import result schema must serialize")
}

//! Resolve opaque credential-import transaction IDs without exposing paths.

use std::path::{Path, PathBuf};

use link_assistant_router::cli::ImportProvider;
use link_assistant_router::subscription::SubscriptionProvider;

use super::import_result::ImportFailure;

fn validate_transaction_id(transaction_id: &str) -> Result<(), ImportFailure> {
    if transaction_id.is_empty()
        || transaction_id.len() > 128
        || !transaction_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err(ImportFailure::not_attempted(
            "the retained import transaction ID is invalid",
        ));
    }
    Ok(())
}

#[derive(Debug)]
pub(super) struct ResumeCandidate {
    pub(super) provider: ImportProvider,
    pub(super) source: String,
    pub(super) transaction_root: PathBuf,
    pub(super) transaction_id: String,
    _claim: Option<link_assistant_router::durable_file::FileLockGuard>,
}

/// Find exactly one owner-only candidate transaction by its reported opaque ID.
pub(super) fn resolve(
    data_dir: &Path,
    transaction_id: &str,
) -> Result<ResumeCandidate, ImportFailure> {
    validate_transaction_id(transaction_id)?;
    let root = data_dir.join("auth-import-candidates");
    let entries = std::fs::read_dir(&root).map_err(|_| {
        ImportFailure::not_attempted("the retained import transaction was not found")
    })?;
    let prefix = format!("{transaction_id}-");
    let mut matches = entries
        .filter_map(Result::ok)
        .filter(|entry| {
            entry
                .file_type()
                .is_ok_and(|file_type| file_type.is_dir() && !file_type.is_symlink())
                && entry.file_name().to_string_lossy().starts_with(&prefix)
        })
        .map(|entry| entry.path())
        .collect::<Vec<_>>();
    if matches.len() != 1 {
        return Err(ImportFailure::not_attempted(if matches.is_empty() {
            "the retained import transaction was not found"
        } else {
            "the retained import transaction ID is ambiguous"
        }));
    }
    let transaction_root = matches.pop().expect("one transaction was checked");
    let providers = SubscriptionProvider::ALL
        .into_iter()
        .filter(|provider| {
            std::fs::symlink_metadata(transaction_root.join(provider.as_str()))
                .is_ok_and(|metadata| metadata.file_type().is_dir())
        })
        .collect::<Vec<_>>();
    let [subscription] = providers.as_slice() else {
        return Err(ImportFailure::not_attempted(
            "the retained import transaction has no unique provider candidate",
        ));
    };
    let provider = match subscription {
        SubscriptionProvider::Claude => ImportProvider::Claude,
        SubscriptionProvider::Codex => ImportProvider::Codex,
        SubscriptionProvider::Gemini => ImportProvider::Gemini,
        SubscriptionProvider::Qwen => ImportProvider::Qwen,
    };
    let source = transaction_root
        .join(subscription.as_str())
        .to_string_lossy()
        .into_owned();
    Ok(ResumeCandidate {
        provider,
        source,
        transaction_root,
        transaction_id: transaction_id.to_string(),
        _claim: None,
    })
}

/// Resolve and exclusively claim one retained transaction for the complete
/// validation/promotion/retirement attempt. The lock lives outside the
/// transaction directory so successful retirement works on Windows too.
pub(super) async fn resolve_claimed(
    data_dir: &Path,
    transaction_id: &str,
) -> Result<ResumeCandidate, ImportFailure> {
    // Validate before interpolating caller input into a path. Otherwise a
    // traversal-shaped ID creates a lock outside the private transaction root
    // even though resolution later rejects it (issues #413, #424).
    validate_transaction_id(transaction_id)?;
    let lock_path = data_dir
        .join("auth-import-candidates")
        .join(format!(".resume-{transaction_id}.lock"));
    let claim = link_assistant_router::durable_file::lock_exclusive_async(
        &lock_path,
        std::time::Duration::from_secs(1),
    )
    .await
    .map_err(|_| {
        ImportFailure::not_attempted("the retained import transaction is already being resumed")
    })?;
    let candidate = resolve(data_dir, transaction_id)?;
    Ok(ResumeCandidate {
        provider: candidate.provider,
        source: candidate.source,
        transaction_root: candidate.transaction_root,
        transaction_id: candidate.transaction_id,
        _claim: Some(claim),
    })
}

/// Remove the predecessor transaction after a newer durable candidate replaces
/// it. A failed cleanup never changes the already reported credential outcome.
pub(super) fn retire(candidate: &ResumeCandidate) -> Result<(), String> {
    std::fs::remove_dir_all(&candidate.transaction_root)
        .map_err(|_| "could not retire the resumed import transaction".to_string())
}

//! The `doctor` report: what this deployment is and whether it can work.
//!
//! Split from `main.rs` to keep that file within the repository's 1000-line
//! limit.

use crate::operation_reports::{Check, DeploymentHealth, DoctorReport, ModelRecommendation};
use link_assistant_router::config::{Config, StoragePolicy};
use link_assistant_router::subscription::SubscriptionReader;
use std::process::ExitCode;

pub async fn run_doctor(config: &Config) -> ExitCode {
    println!("Link.Assistant.Router v{}", link_assistant_router::VERSION);
    println!("listen_addr            : {}", config.listen_addr);
    println!("upstream_base_url      : {}", config.upstream_base_url);
    println!("upstream_provider      : {:?}", config.upstream_provider);
    println!(
        "openai_provider        : {} ({})",
        config.openai_compatible.provider_name, config.openai_compatible.base_url
    );
    println!(
        "crater_inbox           : {}",
        config.crater.inbox.as_deref().unwrap_or("<unset>")
    );
    println!("crater_actor           : {}", config.crater.actor);
    println!("claude_code_home       : {}", config.claude_code_home);
    println!("routing_mode           : {:?}", config.routing_mode);
    println!("storage_policy         : {:?}", config.storage_policy);
    println!("data_dir               : {}", config.data_dir.display());
    println!("enable_openai_api      : {}", config.enable_openai_api);
    println!("enable_anthropic_api   : {}", config.enable_anthropic_api);
    println!("enable_metrics         : {}", config.enable_metrics);
    println!(
        "additional_account_dirs: {} configured",
        config.additional_account_dirs.len()
    );
    println!(
        "account_routing_strategy: {:?}",
        config.account_routing_strategy
    );
    println!("account_cooldown_secs   : {}", config.account_cooldown_secs);
    println!(
        "account_request_limits  : {:?}",
        config.account_request_limits
    );
    println!(
        "session_affinity_ttl   : {}",
        config.session_affinity_ttl_secs
    );
    println!(
        "admin_key              : {}",
        if config.admin_key.is_some() {
            "set"
        } else {
            "<unset>"
        }
    );
    println!(
        "admin_ui               : {}",
        if config.admin_ui.enabled {
            crate::translation_core::format!("enabled on {}", config.admin_ui.listen_addr)
        } else {
            "disabled".to_string()
        }
    );
    {
        let claim = link_assistant_router::admin::AdminClaim::load(
            config.admin_key.clone(),
            &config.data_dir,
            config.admin_ui.candidate_ttl,
        );
        let status = claim.status();
        println!(
            "admin_credential       : {}",
            match status.credential_kind {
                link_assistant_router::admin::CredentialKind::Environment =>
                    "provisioned by environment".to_string(),
                link_assistant_router::admin::CredentialKind::Jwt => crate::translation_core::format!(
                    "claimed admin JWT {} (first-visitor bootstrap closed)",
                    status.token_id.as_deref().unwrap_or("<unknown>")
                ),
                link_assistant_router::admin::CredentialKind::LegacyOpaque =>
                    "claimed (first-visitor bootstrap closed)".to_string(),
                link_assistant_router::admin::CredentialKind::None =>
                    "UNCLAIMED (bootstrap open)".to_string(),
            }
        );
        if status.credential_kind == link_assistant_router::admin::CredentialKind::LegacyOpaque {
            println!(
                "admin_credential_warning: WARNING legacy opaque `la_admin_` credential; \
                 it carries no expiry, scope or revocation. Rotate it into an admin JWT \
                 with POST /api/management/admin/rotate (or /rotate in the chat admin bot)."
            );
        }
    }
    println!(
        "admin_endpoints        : {}",
        if config.allow_anonymous_admin {
            "OPEN (--allow-anonymous-admin)"
        } else {
            "closed (admin key or admin-scoped token required)"
        }
    );
    if config.emergency_auth.enabled {
        println!(
            "emergency_auth         : WARNING ON for {} min (--emergency-accept-any-token): \
             client routes accept any non-empty Router token; management routes stay closed",
            config.emergency_auth.duration_minutes
        );
    } else {
        println!("emergency_auth         : off");
    }
    println!(
        "telegram_admin_bot     : {}",
        if config.chat_admin.telegram_enabled() {
            "enabled (private chats only)"
        } else {
            "disabled"
        }
    );
    println!(
        "vk_admin_bot           : {}",
        if config.chat_admin.vk_enabled() {
            "enabled (private chats only)"
        } else {
            "disabled"
        }
    );
    println!(
        "login_api              : {}",
        if config.login.enabled {
            "enabled (POST /api/management/login)"
        } else {
            "disabled"
        }
    );
    println!(
        "login_cli              : {} {}",
        config.login.command,
        config.login.args.join(" ")
    );
    // Whether each auth mode can run here, before any login is attempted.
    for line in link_assistant_router::doctor::login_mode_report(&config.login) {
        println!("{line}");
    }
    // What this deployment discloses upstream, so the property can be checked
    // without reading the source or the request store (issue #332).
    for line in link_assistant_router::doctor::forwarded_header_report() {
        println!("{line}");
    }
    println!(
        "mpp_openai_charge      : {}",
        if config.mpp.is_configured() {
            "enabled"
        } else {
            "disabled"
        }
    );

    // Probe the active pool with its vendor-specific credential layout.
    let (active_provider, primary_home) = config.subscription_pool();
    let primary = SubscriptionReader::new(active_provider, &primary_home);
    match primary.discover_credential_path() {
        Some(path) => {
            let status = primary.read_token().map_or("found, NO TOKEN", |token| {
                if token.is_expired(crate::operation_context::now().timestamp_millis()) {
                    "found, token EXPIRED on disk"
                } else {
                    "found, token OK"
                }
            });
            println!("primary credentials    : {} ({})", path.display(), status);
        }
        None => println!(
            "primary credentials    : {} (MISSING)",
            primary_home.display()
        ),
    }
    for (i, dir) in config.additional_account_dirs.iter().enumerate() {
        let reader = SubscriptionReader::new(active_provider, dir);
        match reader.discover_credential_path() {
            Some(path) => println!(
                "extra account {}        : {} (found)",
                i + 1,
                path.display()
            ),
            None => println!(
                "extra account {}        : {} (MISSING)",
                i + 1,
                dir.display()
            ),
        }
    }

    let (catalog_error, providers) = link_assistant_router::doctor::subscription_catalog_report(
        config.subscription_readers(),
        Some(&config.data_dir),
    )
    .await;

    // Probe data dir.
    if config.data_dir.exists() {
        println!("data_dir                : present");
    } else {
        println!("data_dir                : will be created on first write");
    }

    if matches!(
        config.storage_policy,
        StoragePolicy::Text | StoragePolicy::Both
    ) {
        let p = config.data_dir.join("tokens.lino");
        println!(
            "lino store              : {} ({})",
            p.display(),
            if p.exists() { "present" } else { "<empty>" }
        );
    }
    if matches!(
        config.storage_policy,
        StoragePolicy::Binary | StoragePolicy::Both
    ) {
        let p = config.data_dir.join("tokens.bin");
        println!(
            "binary store            : {} ({})",
            p.display(),
            if p.exists() { "present" } else { "<empty>" }
        );
    }
    let p = config.data_dir.join("providers.lenv");
    println!(
        "provider store         : {} ({})",
        p.display(),
        if p.exists() { "present" } else { "<empty>" }
    );

    // A z.ai plan the serving process saw refused as exhausted (issue #657).
    // A local deployment at the default root records it under its own data
    // directory, not this process's (issue #664).
    // Every deployment `router deploy` registered is inspected too, so one
    // started with `--root DIR` is no longer invisible here (issue #684).
    let (registered, unseen) = link_assistant_router::deploy::registry::doctor_targets(
        &link_assistant_router::deploy::registry::path(&config.data_dir),
    );
    let data_dirs: Vec<std::path::PathBuf> = [
        config.data_dir.clone(),
        crate::deploy_cli::default_root(&config.data_dir).join("data"),
    ]
    .into_iter()
    .chain(registered)
    .collect();
    print!("{unseen}");
    let (exhausted, found) = link_assistant_router::zai_upstream_error::doctor_report(&data_dirs);
    print!("{exhausted}");

    // Pool failover and vendor rate-limit state (issues #676, #677). A cooling
    // or paused account is the pool working as configured, not a fault, so it
    // does not change the exit code.
    print!("{}", config.pool.doctor_lines());
    let (limits, _) = link_assistant_router::account_limits::doctor_report(&data_dirs);
    print!("{limits}");
    println!(
        "management_allow_remote: {}",
        config.management.allow_remote
    );
    println!(
        "management_lockout     : failures={} secs={} exempt_loopback={}",
        config.management.lockout_failures,
        config.management.lockout_secs,
        config.management.exempt_loopback
    );
    let management_bans = link_assistant_router::management_access::doctor_report(&data_dirs);
    print!("{management_bans}");

    let failed = catalog_error || found;
    let deployments =
        crate::deploy::registry::read(&crate::deploy::registry::path(&config.data_dir))
            .into_iter()
            .map(|deployment| DeploymentHealth {
                present: deployment.root.join("data").is_dir(),
                deployment,
            })
            .collect();
    let recommended_models = providers
        .iter()
        .filter(|provider| provider.state == "usable")
        .filter_map(|provider| {
            provider.models.first().map(|model| ModelRecommendation {
                provider: provider.provider,
                model: model.clone(),
                reason: "first exact model returned by the accepted live provider catalog".into(),
            })
        })
        .collect();
    crate::operation_output::report(DoctorReport {
        status: if failed { "unhealthy" } else { "healthy" }.into(),
        version: crate::VERSION.into(),
        data_dir: config.data_dir.clone(),
        listen_addr: config.listen_addr.to_string(),
        forwarded_headers: crate::proxy::forwarded_client_headers()
            .iter()
            .map(|name| (*name).to_owned())
            .collect(),
        checks: vec![
            Check {
                name: "management-lockout".into(),
                state: if management_bans.is_empty() {
                    "inactive"
                } else {
                    "active"
                }
                .into(),
                detail: (!management_bans.is_empty()).then_some(management_bans),
            },
            Check {
                name: "subscription-catalogs".into(),
                state: if catalog_error { "failed" } else { "passed" }.into(),
                detail: None,
            },
            Check {
                name: "provider-exhaustion".into(),
                state: if found { "failed" } else { "passed" }.into(),
                detail: None,
            },
            Check {
                name: "data-directory".into(),
                state: if config.data_dir.exists() {
                    "present"
                } else {
                    "absent"
                }
                .into(),
                detail: None,
            },
        ],
        providers,
        deployments,
        recommended_models,
        output: Vec::new(),
    });
    if failed {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

//! `router deploy` command surface.
//!
//! Split from `main.rs` to keep that file within the repository's 1000-line
//! limit. This file resolves defaults and dispatches to either the local
//! transactional coordinator or the remote deployment agent.

use std::path::{Path, PathBuf};
use std::process::ExitCode;

use clap::ValueEnum as _;
use link_assistant_router::cli::{ClaudeCredentials, DeployArgs, DeployMode};
use link_assistant_router::config::Config;
use link_assistant_router::deploy_config::{Merged, merge};

/// Default image for a local deployment: this binary's own version.
///
/// A deployment of a *different* version than the CLI driving it is the exact
/// disagreement the immutable-reference rule exists to prevent, so the default is
/// pinned to the version that is running rather than to a moving tag.
fn default_image() -> String {
    format!(
        "ghcr.io/link-assistant/router:{}",
        link_assistant_router::VERSION
    )
}

/// Where a local deployment keeps its credential and data directories.
///
/// With `--instance NAME` the default is `deploy-NAME`, so two instances on
/// one host never share state. Without one it is the historical `deploy`.
#[must_use]
pub fn default_root(data_dir: &Path) -> PathBuf {
    data_dir.join(link_assistant_router::deploy::instance::qualify("deploy"))
}

fn resolved_root(args: &DeployArgs, data_dir: &Path) -> crate::translation_core::Outcome<PathBuf, String> {
    let root = match args.root.as_deref() {
        Some(root) => link_assistant_router::deploy_config::expand_home(root)?,
        None => default_root(data_dir),
    };
    if root.is_absolute() {
        Ok(root)
    } else {
        crate::operation_context::current_dir()
            .map(|directory| directory.join(root))
            .map_err(|error| format!("could not resolve deployment root: {error}"))
    }
}

/// Why a run cannot proceed with the secret it was given, if it cannot.
///
/// A deployment signs its own tokens, so it needs a real secret. Without this
/// check the stand-in installed for non-serving commands reaches the container's
/// environment, where its NUL prefix surfaces as an opaque `nul byte found in
/// provided data` from the process API — and if it ever stopped doing so, the
/// deployment would sign tokens nothing can validate. Removal is exempt: it
/// names a container and deletes it, signing nothing.
fn secret_refusal(token_secret: &crate::translation_core::Str, does_not_sign: bool) -> crate::translation_core::Maybe<String> {
    if does_not_sign {
        return None;
    }
    link_assistant_router::token_secret::ensure_real(token_secret)
        .err()
        .map(|error| {
            format!(
                "error: {error}\nnote: the deployment signs its own tokens, so pass \
                 TOKEN_SECRET in the environment."
            )
        })
}

/// Fill flags the operator omitted from `--config`, then check the
/// combinations clap can no longer check because a value may come from it.
fn apply_section(args: &mut DeployArgs, merged: &Merged, remote: bool) -> Result<(), String> {
    let section = &merged.section;
    if remote && args.server.is_none() {
        args.server.clone_from(&section.server);
        if args.server.is_none() {
            return Err("--remote needs `server` in [remote] or [deploy] of --config".to_string());
        }
    }
    args.port = args.port.or(section.port);
    args.public_port = args.public_port.or(section.public_port);
    if args.image.is_none() {
        args.image.clone_from(&section.image);
    }
    if args.build.is_none() {
        args.build.clone_from(&section.build);
    }
    if args.root.is_none() {
        args.root.clone_from(&section.root);
    }
    if !remote {
        if args.mode.is_none()
            && let Some(mode) = &section.mode
        {
            args.mode = Some(DeployMode::from_str(mode, true).map_err(|_| {
                format!("--config: mode must be `container` or `host`, not `{mode}`")
            })?);
        }
        if args.claude_credentials.is_none()
            && !args.down
            && let Some(value) = &section.claude_credentials
        {
            args.claude_credentials =
                Some(ClaudeCredentials::from_str(value, true).map_err(|_| {
                    format!(
                        "--config: claude_credentials must be `isolated` or `share`, not `{value}`"
                    )
                })?);
        }
    }
    Ok(())
}

/// Refuse combinations of flags that only make sense for one target.
fn check_target(args: &DeployArgs, remote: bool) -> crate::translation_core::Outcome<(), String> {
    if remote && (args.install_service || args.uninstall_service) {
        return Err(
            "--install-service supervises a local host deployment; it needs no --server"
                .to_string(),
        );
    }
    if !remote && args.public_port.is_some() {
        return Err("--public-port needs --server or --remote".to_string());
    }
    if !remote {
        if !args.settings.provider_key.is_empty() || args.settings.provider_key_mode.is_some() {
            return Err(
                "--provider-key is verified in a remote candidate; it needs --server or --remote"
                    .to_string(),
            );
        }
        if args.settings.verification_profile.is_some() {
            return Err("--verification-profile needs --server or --remote".to_string());
        }
        if !args.settings.seed_credential.is_empty() {
            return Err(
                "--seed-credential hands a login to a remote deployment; it needs --server or \
                 --remote (a local deployment reads this machine's login directly)"
                    .to_string(),
            );
        }
        let ssh = &args.settings;
        if ssh.ssh_port.is_some()
            || ssh.ssh_identity.is_some()
            || ssh.ssh_known_hosts.is_some()
            || ssh.ssh_keepalive.is_some()
            || ssh.deadline.is_some()
        {
            return Err("SSH settings need --server or --remote".to_string());
        }
    }
    Ok(())
}

/// Merge `--config` with the flags into the arguments a run uses.
pub(crate) fn resolve(args: &DeployArgs) -> crate::translation_core::Outcome<(DeployArgs, Merged, bool), String> {
    let remote = args.server.is_some() || args.settings.remote;
    let merged = merge(&args.settings, remote)?;
    let mut resolved = args.clone();
    apply_section(&mut resolved, &merged, remote)?;
    check_target(&resolved, remote)?;
    if !remote
        && (!merged.provider_keys.is_empty()
            || merged.verification.is_some()
            || !merged.seed_credentials.is_empty())
    {
        eprintln!(
            "note: provider keys, seed credentials and the verification profile in --config \
             apply to remote deployments only; this local run ignores them."
        );
    }
    Ok((resolved, merged, remote))
}

pub fn run(config: &Config, args: &DeployArgs) -> ExitCode {
    if args.staging.is_some() && args.settings.any() {
        eprintln!(
            "error: --staging takes no deploy settings; a staging namespace never shares a \
             configuration with the deployment it rehearses"
        );
        return ExitCode::from(2);
    }
    if args.staging.is_some() {
        let root = match args.root.as_deref() {
            Some(root) => match link_assistant_router::deploy_config::expand_home(root) {
                Ok(root) => root,
                Err(error) => {
                    eprintln!("error: {error}");
                    return ExitCode::from(2);
                }
            },
            None => config
                .data_dir
                .join("staging")
                .join(args.staging.as_deref().expect("namespace")),
        };
        let image = args.image.clone().unwrap_or_else(default_image);
        return crate::deploy_local::staging::run(args, &root, &image);
    }
    let (args, merged, remote) = match resolve(args) {
        Ok(resolved) => resolved,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(2);
        }
    };
    if let Some(instance) = &merged.instance
        && let Err(error) = link_assistant_router::deploy::instance::select(instance)
    {
        eprintln!("error: {error}");
        return ExitCode::from(2);
    }
    let args = &args;
    let deploying = !args.down && !args.status && !args.uninstall_service;
    if remote {
        return crate::deploy_remote::run(args, &config.token_secret, &merged);
    }
    if let Some(refusal) = secret_refusal(
        &config.token_secret,
        args.down || args.status || args.uninstall_service,
    ) {
        eprintln!("{refusal}");
        return ExitCode::from(2);
    }
    if deploying {
        match merged.read_values() {
            Ok(values) if args.install_service && !values.env.is_empty() => {
                eprintln!(
                    "error: --install-service cannot carry --env values into a unit without \
                     writing them to disk; deploy without --env, or supervise the Router yourself"
                );
                return ExitCode::from(2);
            }
            Ok(values) => crate::deploy_local::runtime_env::configure(
                crate::deploy_local::runtime_env::LocalSettings {
                    env: values.env,
                    tokens: values.tokens,
                },
            ),
            Err(error) => {
                eprintln!("error: {error}");
                return ExitCode::from(2);
            }
        }
    }

    let root = match resolved_root(args, &config.data_dir) {
        Ok(root) => root,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(2);
        }
    };
    let image = args.image.clone().unwrap_or_else(default_image);
    if let Some(code) = image_preflight(args, &root, &image) {
        return code;
    }
    if let Some(code) = service_before(args, &root) {
        return code;
    }
    let code = crate::deploy_local::run(args, &root, &image, &config.token_secret);
    if code == ExitCode::SUCCESS && !args.status {
        record_in_registry(args, &root, &config.data_dir);
    }
    if code == ExitCode::SUCCESS && args.install_service {
        return match crate::deploy_local::service::install(&root, &config.token_secret) {
            Ok(_) => ExitCode::SUCCESS,
            Err(error) => {
                eprintln!(
                    "error: the host deployment serves, but its service was not installed: {error}"
                );
                ExitCode::from(1)
            }
        };
    }
    code
}

/// A missing default image cannot yield an executable container plan.
fn image_preflight(args: &DeployArgs, root: &Path, image: &crate::translation_core::Str) -> crate::translation_core::Maybe<ExitCode> {
    let host = args.mode == Some(DeployMode::Host)
        || (args.mode.is_none() && root.join("state/host").exists());
    if args.image.is_some()
        || args.build.is_some()
        || host
        || args.down
        || args.uninstall_service
        || args.restore_state.is_some()
    {
        return None;
    }
    if let Some(code) = crate::deploy_local::credential_preflight(args, root) {
        return Some(code);
    }
    crate::deploy_image::ensure_default(image, link_assistant_router::VERSION)
        .err()
        .map(|error| {
            eprintln!("error: {error}");
            ExitCode::from(2)
        })
}

/// The service steps that come before the deployment runs (issue #684):
/// `--uninstall-service` alone, removal on `--down`, and stopping a
/// service-started Router so the deploy can bind the stable port.
fn service_before(args: &DeployArgs, root: &Path) -> crate::translation_core::Maybe<ExitCode> {
    use crate::deploy_local::service;
    if args.uninstall_service {
        return Some(match service::uninstall(root) {
            Ok(true) => ExitCode::SUCCESS,
            Ok(false) => {
                println!("host_service=absent root={}", root.display());
                ExitCode::SUCCESS
            }
            Err(error) => {
                eprintln!("error: {error}");
                ExitCode::from(1)
            }
        });
    }
    let installed = service::installed(root);
    if args.install_service
        && args.mode != Some(DeployMode::Host)
        && !root.join("state").join("host").exists()
    {
        eprintln!("error: --install-service supervises a host deployment; add --mode host");
        return Some(ExitCode::from(2));
    }
    let record = installed?;
    if args.status {
        println!(
            "host_service=installed name={} unit={}",
            record.name,
            record.unit.display()
        );
    } else if args.down {
        if !args.yes {
            return None;
        }
        if let Err(error) = service::uninstall(root) {
            eprintln!("error: {error}");
            return Some(ExitCode::from(1));
        }
    } else {
        service::stop(&record);
    }
    None
}

/// Keep the registry `router doctor` reads in step with this run (#684).
///
/// A failure to record is reported but never fails a deployment that is
/// already serving: doctor then names the default root only, as before.
fn record_in_registry(args: &DeployArgs, root: &Path, data_dir: &Path) {
    use link_assistant_router::deploy::registry;
    let path = registry::path(data_dir);
    let result = if args.down {
        registry::unregister(&path, root)
    } else {
        let host = root.join("state").join("host").exists();
        registry::register(
            &path,
            registry::Entry {
                root: root.to_path_buf(),
                mode: if host { "host" } else { "container" }.to_string(),
                port: args.port(),
                instance: link_assistant_router::deploy::instance::selected_name(),
                registered_at: crate::operation_context::now().timestamp(),
            },
        )
    };
    if let Err(error) = result {
        eprintln!("warning: the deployment registry was not updated: {error}");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn args() -> DeployArgs {
        DeployArgs {
            restore_state: None,
            replace_state: false,
            staging: None,
            verify: false,
            json: false,
            server: None,
            status: false,
            down: false,
            yes: false,
            force_update: false,
            accept_access_loss: false,
            port: Some(8080),
            public_port: None,
            image: None,
            build: None,
            root: None,
            claude_credentials: None,
            mode: None,
            install_service: false,
            uninstall_service: false,
            settings: link_assistant_router::cli::DeploySettingsArgs::default(),
        }
    }

    #[test]
    fn the_default_image_is_this_binarys_own_version_not_a_moving_tag() {
        let image = default_image();

        // Defaulting to `latest` would make every unqualified run fail the
        // immutable-reference check — or worse, deploy a container that disagrees
        // with the CLI about the API contract.
        assert!(image.ends_with(link_assistant_router::VERSION), "{image}");
        link_assistant_router::deploy::immutable_ref(&image).expect("the default is deployable");
    }

    #[test]
    fn a_relative_root_is_made_stable_before_it_becomes_an_ownership_label() {
        let mut args = args();
        args.root = Some("router-state".to_string());

        let root = resolved_root(&args, Path::new("/tmp/state")).unwrap();

        assert!(root.is_absolute());
        assert!(root.ends_with("router-state"));
    }

    #[test]
    fn the_default_root_lives_under_the_data_directory() {
        let data_dir = crate::operation_context::current_dir()
            .unwrap()
            .join("var")
            .join("lib")
            .join("router");
        let root = resolved_root(&args(), &data_dir).unwrap();

        // Under the data directory rather than beside it, so a deployment's own
        // state is not scattered across the filesystem.
        assert_eq!(root, data_dir.join("deploy"));
        // Separate paths: the credential mount is read-only and the request log
        // cannot live on it.
        assert_ne!(root.join("credentials"), root.join("data"));
    }

    #[test]
    fn a_stand_in_secret_is_refused_before_a_container_is_created() {
        let stand_in = link_assistant_router::token_secret::placeholder("cli-command");

        let refusal = secret_refusal(&stand_in, false).expect("a stand-in is refused");

        // The stand-in carries a NUL so it can never be supplied deliberately,
        // which means it reaches the process API and fails there with `nul byte
        // found in provided data` — a message that describes the mechanism and
        // not the mistake. It is caught here instead, and a deployment is never
        // created that would sign tokens nothing can validate.
        assert!(refusal.contains("TOKEN_SECRET"), "{refusal}");
        assert!(
            !refusal.contains("nul byte"),
            "the operator is told what to do, not what the process API said: {refusal}"
        );
        assert!(
            !refusal.contains(&stand_in),
            "the refusal does not echo the secret it rejected"
        );
    }

    #[test]
    fn a_real_secret_passes_and_removal_needs_none() {
        assert!(secret_refusal("a-real-operator-secret", false).is_none());
        // `--down` names a container and deletes it. Demanding a signing secret
        // to tear down a deployment would make a broken one unremovable by the
        // operator who most needs to remove it.
        assert!(
            secret_refusal(
                &link_assistant_router::token_secret::placeholder("cli-command"),
                true
            )
            .is_none()
        );
    }
}

//! Read-only default image preflight before a deployment plan (#687).

use std::ffi::OsStr;
use std::time::Duration;

/// Verify a cached default image or registry manifest before deployment planning.
pub fn ensure_default(image: &crate::translation_core::Str, version: &crate::translation_core::Str) -> crate::translation_core::Outcome<(), String> {
    inspect_with(OsStr::new("docker"), image, version)
}

fn inspect_with(docker: &OsStr, image: &crate::translation_core::Str, version: &crate::translation_core::Str) -> crate::translation_core::Outcome<(), String> {
    // An immutable image already cached on the target is usable offline.
    let local = crate::operation_context::bounded_output(
        crate::operation_context::command(docker).args(["image", "inspect", image]),
        Duration::from_secs(30),
    );
    if local.as_ref().is_ok_and(|output| output.status.success()) {
        return Ok(());
    }
    let output = crate::operation_context::bounded_output(
        crate::operation_context::command(docker).args(["manifest", "inspect", image]),
        Duration::from_secs(30),
    )
        .map_err(|error| format!("image-unavailable: could not check default image {image}: {error}; pass --image RELEASE_TAG_OR_DIGEST or --build DIR"))?;
    if output.status.success() {
        return Ok(());
    }
    let reason = String::from_utf8_lossy(&output.stderr);
    let lower = reason.to_ascii_lowercase();
    if [
        "manifest unknown",
        "no such manifest",
        "not found",
        "name unknown",
    ]
    .iter()
    .any(|missing| lower.contains(missing))
    {
        Err(format!(
            "image-unpublished: image for {version} is not published ({image}); pass --image RELEASE_TAG_OR_DIGEST or --build DIR"
        ))
    } else {
        Err(format!(
            "image-unavailable: could not verify default image {image}: {}; pass --image RELEASE_TAG_OR_DIGEST or --build DIR",
            reason.trim()
        ))
    }
}

#[cfg(all(test, unix))]
mod tests {
    use super::*;
    use std::os::unix::fs::PermissionsExt as _;

    fn inspect(body: &str) -> Result<(), String> {
        let directory = tempfile::tempdir().unwrap();
        let docker = directory.path().join("docker");
        std::fs::write(&docker, format!("#!/bin/sh\n{body}\n")).unwrap();
        std::fs::set_permissions(&docker, std::fs::Permissions::from_mode(0o700)).unwrap();
        inspect_with(
            docker.as_os_str(),
            "ghcr.io/link-assistant/router:1.16.0",
            "1.16.0",
        )
    }

