    }
}

//! Connection-preserving local deployment coordinator (issue #598).

use std::fs::OpenOptions;
use std::path::Path;
use std::process::ExitCode;
use std::thread;
use std::time::Duration;

use link_assistant_router::cli::DeployArgs;
use link_assistant_router::deploy::instance::InstanceName;

mod checkpoint;
mod claude_share;
pub use checkpoint::capture_checkpoint;
mod data_backup;
mod deploy_token;
mod diagnose;
mod docker;
mod host;
mod host_runtime;
mod inventory;
mod operation_lock;
mod preservation;
mod relay_rotation;
pub mod runtime_env;
mod secret;
pub mod service;
pub mod staging;
mod state;
mod status_report;
#[cfg(test)]
#[path = "deploy_local_tests.rs"]
mod tests;

use claude_share::Provision;
pub use claude_share::preflight as credential_preflight;
use docker::Docker;
use inventory::Inventory;
use operation_lock::OperationLock;
use state::{Active, Phase, PreviousKind, Recovery, State, Transaction};

/// Relay container name; carries `--instance` (issue #679).
pub static RELAY: InstanceName = InstanceName::new(link_assistant_router::deploy::RELAY);
/// Network name; carries `--instance`.
pub static NETWORK: InstanceName = InstanceName::new(link_assistant_router::deploy::NETWORK);
pub const LABEL_KEY: &crate::translation_core::Str = link_assistant_router::deploy::LABEL_KEY;
const LEGACY: &crate::translation_core::Str = link_assistant_router::deploy::CONTAINER;
pub const SPEC_VERSION: &crate::translation_core::Str = "local-v1";
#[cfg(not(test))]
const READY_ATTEMPTS: usize = 300;
#[cfg(test)]
const READY_ATTEMPTS: usize = 2;

#[derive(Debug)]
enum Existing {
    Absent,
    Legacy,
    Managed(Active),
}

struct Coordinator<'a> {
    docker: Docker,
    state: State,
    root: &'a Path,
    image: &'a str,
    build: Option<&'a str>,
    port: u16,
    token_secret: &'a str,
    force: bool,
    accept_access_loss: bool,
    claude: Provision,
}

impl Coordinator<'_> {
    fn existing(&self) -> Result<Existing, String> {
        if let Some(active) = self.state.active()? {
            if self.state.current()?.as_deref() != Some(&active.backend) {
                return Err("active deployment disagrees with the relay pointer".to_string());
            }
            if !self.docker.owned(&active.backend, self.root, "backend") {
                return Err(format!(
                    "active backend {} is absent or not owned by this root",
                    active.backend
                ));
            }
            if self.docker.image_ref(&active.backend)? != active.image_ref
                || self.docker.container_image_id(&active.backend)? != active.image_id
                || self
                    .docker
                    .label(&active.backend, &format!("{LABEL_KEY}.spec"))
                    .as_deref()
                    != Some(SPEC_VERSION)
            {
                return Err(format!(
                    "backend {} launch specification differs from its active record",
                    active.backend
                ));
            }
            let expected_port = active.port.to_string();
            if self.docker.exists(&RELAY.value())
                && (!self.docker.owned(&RELAY.value(), self.root, "relay")
                    || self
                        .docker
                        .label(&RELAY.value(), &format!("{LABEL_KEY}.spec"))
                        .as_deref()
                        != Some(SPEC_VERSION)
                    || self
                        .docker
                        .label(&RELAY.value(), &format!("{LABEL_KEY}.port"))
                        .as_deref()
                        != Some(expected_port.as_str()))
            {
                return Err("relay launch specification differs from its active record".to_string());
            }
            return Ok(Existing::Managed(active));
        }
        if self.docker.exists(&RELAY.value()) {
            return Err(format!(
                "{RELAY} exists without a durable active deployment record"
            ));
        }
        if self.docker.exists(LEGACY) {
            if self.docker.legacy_owned(LEGACY, self.root) {
                return Ok(Existing::Legacy);
            }
            return Err(format!("refusing unowned container {LEGACY}"));
        }
        Ok(Existing::Absent)
    }

    fn inventory(&self, backend: &str) -> Result<Inventory, String> {
        let rendered = self.docker.token_inventory(backend).map_err(|error| {
            format!("could not inventory run credentials in {backend}: {error}")
        })?;
        Inventory::from_json(&rendered, crate::operation_context::now().timestamp())
    }

    fn connection_count(&self, backend: &str) -> Result<u64, String> {
        let value = self.docker.relay_connection_count(backend)?;
        value
            .trim()
            .parse()
            .map_err(|error| format!("relay connection count for {backend} is invalid: {error}"))
    }

    fn preflight(&self, existing: &Existing) -> Result<Option<Inventory>, String> {
        let relay = RELAY.value();
        let allowed_holder = match existing {
            Existing::Legacy => Some(LEGACY),
            Existing::Managed(active) if active.port == self.port => Some(relay.as_str()),
            Existing::Absent | Existing::Managed(_) => None,
        };
        let foreign = self
            .docker
            .listeners_on(self.port)?
            .into_iter()
            .filter(|name| Some(name.as_str()) != allowed_holder)
            .collect::<Vec<_>>();
        if !foreign.is_empty() {
            return Err(format!(
                "port {} is already published by {}",
                self.port,
                foreign.join(", ")
            ));
        }
        match existing {
            Existing::Absent => {
                self.print_status(existing)?;
                Ok(None)
            }
            Existing::Legacy => {
                let inventory = self.inventory(LEGACY)?;
                self.print_status(existing)?;
                if !self.force {
                    return Err(
                        "legacy local deployment cannot prove established connections are idle; rerun with --force-update after reviewing force_impact"
                            .to_string(),
                    );
                }
                println!("force_update accepted impact=legacy-direct-front-door");
                self.secret_preflight(LEGACY)?;
                Ok(Some(inventory))
            }
            Existing::Managed(active) => {
                let inventory = self.inventory(&active.backend)?;
                self.print_status(existing)?;
                let blockers = inventory.blockers().collect::<Vec<_>>();
                if active.port != self.port && !self.force {
                    return Err(
                        "changing the stable listener can interrupt clients; rerun with --force-update after reviewing the status report"
                            .to_string(),
                    );
                }
                if !blockers.is_empty() && !self.force {
                    return Err(
                        "legacy-unpinned run credentials cannot be presented as exact-model protected; let them expire or rerun with --force-update"
                            .to_string(),
                    );
                }
                self.secret_preflight(&active.backend)?;
                if self.force {
                    for blocker in blockers {
                        println!(
                            "force_update accepted run_id={} label={} state=legacy-unpinned",
                            blocker.id,
                            serde_json::to_string(&blocker.label).unwrap_or_else(|_| "null".into())
                        );
                    }
                    if active.port != self.port {
                        println!(
                            "force_update accepted stable_listener={}->{} connections={}",
                            active.port,
                            self.port,
                            self.connection_count(&active.backend)?
                        );
                    }
                }
                Ok(Some(inventory))
            }
        }
    }

    fn create_directories(&self) -> Result<(), String> {
        for path in [
            self.root.join("credentials"),
            self.root.join("data"),
            self.root.join("state"),
        ] {
            std::fs::create_dir_all(&path)
                .map_err(|error| format!("could not create {}: {error}", path.display()))?;
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt as _;
                let _ = std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o700));
            }
        }
        Ok(())
    }

    fn acquire_lock(&self) -> Result<OperationLock, String> {
        let path = self.state.directory().join("update.lock");
        let file = OpenOptions::new()
            .create(true)
            .read(true)
            .write(true)
            .truncate(false)
            .open(&path)
            .map_err(|error| {
                format!("could not open deployment lock {}: {error}", path.display())
            })?;
        file.try_lock()
            .map_err(|error| format!("pending lifecycle operation owns the deployment lock; no recovery or mutation attempted: {error}"))?;
        Ok(OperationLock(file))
    }

    fn wait_healthy(&self, container: &str, origin: &str) -> Result<(), String> {
        for _ in 0..READY_ATTEMPTS {
            if self.docker.health(container, origin) {
                return Ok(());
            }
            #[cfg(not(test))]
            thread::sleep(Duration::from_secs(1));
        }
        Err(format!("{container} did not become healthy"))
    }

    fn drain(&self, backend: &str) -> Result<(), String> {
        let mut last = u64::MAX;
        let mut zero_observations = 0_u8;
        loop {
            let count = self.connection_count(backend)?;
            if count != last {
                println!("draining backend={backend} connections={count}");
                last = count;
            }
            if count == 0 {
                zero_observations = zero_observations.saturating_add(1);
                if zero_observations == 2 {
                    return Ok(());
                }
            } else {
                zero_observations = 0;
            }
            thread::sleep(Duration::from_secs(1));
        }
    }

    fn remove_backend(&self, backend: &str) -> Result<(), String> {
        if !self.docker.exists(backend) {
            return Ok(());
        }
        if !self.docker.owned(backend, self.root, "backend") {
            return Err(format!("refusing to remove unowned backend {backend}"));
        }
        self.docker.remove(backend)
    }

    fn remove_relay(&self) -> Result<(), String> {
        if !self.docker.exists(&RELAY.value()) {
            return Ok(());
        }
        if !self.docker.owned(&RELAY.value(), self.root, "relay") {
            return Err(format!("refusing to remove unowned relay {RELAY}"));
        }
        self.docker.remove(&RELAY.value())
    }

    fn finish_accepted(&self, transaction: &Transaction) -> Result<(), String> {
        if !self
            .docker
            .owned(&transaction.candidate, self.root, "backend")
        {
            return Err("accepted candidate is absent or not owned by this deployment".to_string());
        }
        if let Some(previous) = transaction.previous.as_deref() {
            if transaction.previous_kind == PreviousKind::Managed {
                self.drain(previous)?;
                self.remove_backend(previous)?;
            } else if transaction.previous_kind == PreviousKind::Legacy {
                if previous != LEGACY || !self.docker.legacy_owned(previous, self.root) {
                    return Err("refusing to remove an unowned legacy deployment".to_string());
                }
                self.docker.remove(previous)?;
            }
        }
        let active = Active {
            version: 1,
            backend: transaction.candidate.clone(),
            image_ref: transaction.image_ref.clone(),
            image_id: transaction.image_id.clone(),
            port: transaction.port,
        };
        self.state.write_active(&active)?;
        let mut complete = transaction.clone();
        complete.phase = Phase::Complete;
        self.state.write_transaction(&complete)
    }

    fn rollback(&self, transaction: &Transaction) -> Result<(), String> {
        match transaction.previous_kind {
            PreviousKind::Managed => {
                let previous = transaction
                    .previous
                    .as_deref()
                    .ok_or("managed rollback has no previous backend")?;
                if !self.docker.owned(previous, self.root, "backend") {
                    return Err(format!("cannot restore unowned backend {previous}"));
                }
                self.state.set_current(previous)?;
                if transaction.previous_port != Some(transaction.port) {
                    self.remove_relay()?;
                    self.docker.run_relay(
                        &self.docker.image_ref(previous)?,
                        self.root,
                        transaction.previous_port.unwrap_or(transaction.port),
                    )?;
                }
                self.drain(&transaction.candidate)?;
            }
            PreviousKind::Legacy => {
                let previous = transaction
                    .previous
                    .as_deref()
                    .filter(|previous| *previous == LEGACY)
                    .ok_or("legacy rollback has no valid legacy backend")?;
                if self.docker.exists(previous) && !self.docker.legacy_owned(previous, self.root) {
                    return Err("cannot restore an unowned legacy deployment".to_string());
                }
                self.remove_relay()?;
                self.state.clear_current()?;
                if self.docker.exists(previous) && !self.docker.running(previous)? {
                    self.docker.start(previous)?;
                }
            }
            PreviousKind::None => {
                self.remove_relay()?;
                self.state.clear_current()?;
            }
        }
        self.remove_backend(&transaction.candidate)?;
        let mut complete = transaction.clone();
        complete.phase = Phase::Complete;
        self.state.write_transaction(&complete)
    }

    fn recover(&self) -> Result<(), String> {
        match self.state.recovery()? {
            Recovery::None => Ok(()),
            Recovery::RollBack(transaction) => {
                println!("recovering interrupted pre-acceptance candidate");
                self.rollback(&transaction)
            }
            Recovery::FinishAccepted(transaction) => {
                println!("finishing interrupted accepted cutover");
                self.finish_accepted(&transaction)
            }
        }
    }

    /// The credential an existing backend was started with; backends from
    /// before issue #622 carry no label and always used `<root>/credentials`.
    fn claude_label(&self, backend: &str) -> String {
        self.docker
            .label(
                backend,
                &format!("{LABEL_KEY}.{}", claude_share::LABEL_SUFFIX),
            )
            .unwrap_or_else(|| Provision::Isolated.label())
    }

    /// An update without `--claude-credentials` keeps the active mode, so a
    /// routine image update never silently drops a shared login.
    fn active_claude_mode(&self) -> link_assistant_router::cli::ClaudeCredentials {
        // Without a readable record, the pointer still names the serving
        // backend whose mode an adoption must keep (issue #631).
        let shared = self
            .state
            .active()
            .ok()
            .flatten()
            .map(|active| active.backend)
            .or_else(|| self.state.current().ok().flatten())
            .is_some_and(|backend| self.claude_label(&backend).starts_with("shared:"));
        if shared {
            link_assistant_router::cli::ClaudeCredentials::Share
        } else {
            link_assistant_router::cli::ClaudeCredentials::Isolated
        }
    }

    fn no_op(&self, active: &Active) -> Result<bool, String> {
        if self.build.is_some()
            || active.image_ref != self.image
            || active.port != self.port
            || self.claude_label(&active.backend) != self.claude.label()
            || self.state.current()?.as_deref() != Some(&active.backend)
            || !self.docker.owned(&active.backend, self.root, "backend")
            || self.secret_match(&active.backend) != secret::SecretMatch::Matches
            || !runtime_env::matches(
                self.runtime_env_label(&active.backend).as_deref(),
                self.token_secret,
            )
        {
            return Ok(false);
        }
        Ok(true)
    }

    fn restore_topology(&self, active: &Active) -> Result<bool, String> {
        let mut changed = if self.docker.running(&active.backend)? {
            false
        } else {
            self.docker.start(&active.backend)?;
            println!("restored backend={}", active.backend);
            true
        };
        if !self.docker.exists(&RELAY.value()) {
            self.docker
                .run_relay(&active.image_ref, self.root, active.port)?;
            println!("restored relay={RELAY}");
            changed = true;
        } else if !self.docker.owned(&RELAY.value(), self.root, "relay") {
            return Err(format!("refusing unowned relay {RELAY}"));
        } else if !self.docker.running(&RELAY.value())? {
            self.docker.start(&RELAY.value())?;
            println!("restored relay={RELAY}");
            changed = true;
        }
        self.wait_healthy(&active.backend, &format!("http://{RELAY}:8080"))?;
        Ok(changed)
    }

    fn topology_needs_repair(&self, active: &Active) -> Result<bool, String> {
        Ok(!self.docker.running(&active.backend)?
            || !self.docker.exists(&RELAY.value())
            || !self.docker.running(&RELAY.value())?)
    }

    fn deploy(&self, existing: &Existing) -> Result<(), String> {
        let candidate =
            link_assistant_router::deploy::instance::backend_name(uuid::Uuid::new_v4())?;
        let baseline = self.preservation_baseline(existing)?;
        let image_id = self.docker.ensure_image(self.image, self.build)?;
        self.docker.create_network(self.root)?;
        let (previous, previous_kind, previous_port) = match &existing {
            Existing::Absent => (None, PreviousKind::None, None),
            Existing::Legacy => (
                Some(LEGACY.to_string()),
                PreviousKind::Legacy,
                Some(self.port),
            ),
            Existing::Managed(active) => (
                Some(active.backend.clone()),
                PreviousKind::Managed,
                Some(active.port),
            ),
        };
        let mut transaction = Transaction {
            version: 1,
            phase: Phase::Prepared,
            previous,
            previous_kind,
            previous_port,
            candidate: candidate.clone(),
            image_ref: self.image.to_string(),
            image_id,
            port: self.port,
        };
        self.state.write_transaction(&transaction)?;
        if let Err(error) = self.docker.run_backend(
            &candidate,
            self.image,
            self.root,
            self.token_secret,
            &self.claude,
        ) {
            self.rollback(&transaction)?;
            return Err(format!("could not start candidate: {error}"));
        }
        if let Err(error) = self.wait_healthy(&candidate, "http://127.0.0.1:8080") {
            self.rollback(&transaction)?;
            return Err(error);
        }
        if let Err(error) = self.preservation_candidate(&candidate, &baseline) {
            self.rollback(&transaction)?;
            return Err(format!(
                "access preservation refused before cutover: {error}; previous deployment retained"
            ));
        }
        self.ensure_deploy_token(&candidate);
        println!("candidate_backend={candidate} verified=true");

        match &existing {
            Existing::Absent => {
                self.state.set_current(&candidate)?;
                if let Err(error) = self
                    .docker
                    .run_relay(self.image, self.root, self.port)
                    .and_then(|()| self.wait_healthy(&candidate, &format!("http://{RELAY}:8080")))
                {
                    self.rollback(&transaction)?;
                    return Err(format!("first cutover failed and was rolled back: {error}"));
                }
            }
            Existing::Legacy => {
                if let Err(error) = self.probe_candidate(&candidate, LEGACY) {
                    self.rollback(&transaction)?;
                    return Err(format!("token probe failed and was rolled back: {error}"));
                }
                self.docker.stop(LEGACY)?;
                self.state.set_current(&candidate)?;
                if let Err(error) = self
                    .docker
                    .run_relay(self.image, self.root, self.port)
                    .and_then(|()| self.wait_healthy(&candidate, &format!("http://{RELAY}:8080")))
                {
                    self.rollback(&transaction)?;
                    return Err(format!(
                        "legacy migration failed and was rolled back: {error}"
                    ));
                }
            }
            Existing::Managed(active) => {
                if let Err(error) = self.probe_candidate(&candidate, &active.backend) {
                    self.rollback(&transaction)?;
                    return Err(format!("token probe failed and was rolled back: {error}"));
                }
                self.state.set_current(&candidate)?;
                if active.port != self.port {
                    self.remove_relay()?;
                    if let Err(error) = self.docker.run_relay(self.image, self.root, self.port) {
                        self.rollback(&transaction)?;
                        return Err(format!(
                            "listener update failed and was rolled back: {error}"
                        ));
                    }
                }
                if let Err(error) = self.wait_healthy(&candidate, &format!("http://{RELAY}:8080")) {
                    self.rollback(&transaction)?;
                    return Err(format!(
                        "post-cutover verification failed and rolled back: {error}"
                    ));
                }
            }
        }

        transaction.phase = Phase::Accepted;
        self.state.write_transaction(&transaction)?;
        self.finish_accepted(&transaction)?;
        if let Some(active) = self.state.active()? {
            self.converge_relay(&active)?;
        }
        println!(
            "deployment is ready: relay={RELAY} backend={candidate} port={}",
            self.port
        );
        println!(
            "next: `router with claude --server http://127.0.0.1:{}`",
            self.port
        );
        Ok(())
    }

    fn down(&self) -> Result<(), String> {
        if !self.root.exists()
            && self.docker.owned_containers(self.root)?.is_empty()
            && !(self.docker.exists(LEGACY) && self.docker.legacy_owned(LEGACY, self.root))
        {
            println!("deployment is already absent");
            return Ok(());
        }
        self.create_directories()?;
        let _lock = self.acquire_lock()?;
        for container in self.docker.owned_containers(self.root)? {
            if self.docker.owned(&container, self.root, "backend")
                || self.docker.owned(&container, self.root, "relay")
            {
                self.docker.remove(&container)?;
                println!("removed {container}");
            }
        }
        if self.docker.exists(LEGACY) && self.docker.legacy_owned(LEGACY, self.root) {
            self.docker.remove(LEGACY)?;
            println!("removed {LEGACY}");
        }
        self.docker.remove_network(self.root)?;
        self.state.clear_deployment_records()?;
        println!(
            "deployment is down; retained credentials and data at {}",
            self.root.display()
        );
        Ok(())
    }
}

#[must_use]
pub fn run(args: &DeployArgs, root: &Path, image: &crate::translation_core::Str, token_secret: &crate::translation_core::Str) -> ExitCode {
    run_with_docker(args, root, image, token_secret, Docker::default())
}

fn run_with_docker(
    args: &DeployArgs,
    root: &Path,
    image: &crate::translation_core::Str,
    token_secret: &crate::translation_core::Str,
    docker: Docker,
) -> ExitCode {
    let host = host_runtime::System::default();
    run_assessed(
        args,
        root,
        image,
        token_secret,
        docker,
        &Provision::assess,
        &host,
    )
}

fn run_assessed(
    args: &DeployArgs,
    root: &Path,
    image: &str,
    token_secret: &str,
    docker: Docker,
    assess: &dyn Fn(link_assistant_router::cli::ClaudeCredentials, &Path) -> Provision,
    host: &dyn host_runtime::HostRuntime,
) -> ExitCode {
    let mut coordinator = Coordinator {
        docker,
        state: State::new(root),
        root,
        image,
        build: args.build.as_deref(),
        port: args.port(),
        token_secret,
        force: args.force_update,
        accept_access_loss: args.accept_access_loss,
        claude: Provision::Isolated,
    };
    if let Some(snapshot) = &args.restore_state {
        return result_code(coordinator.restore_state(snapshot, args.replace_state, host));
    }
    if let Some(code) = host::dispatch(&coordinator, args, host) {
        return code;
    }
    if !args.down {
        let mode = args
            .claude_credentials
            .unwrap_or_else(|| coordinator.active_claude_mode());
        coordinator.claude = assess(mode, &root.join("data"));
        // A refusal needs no container runtime to explain itself.
        if !args.status
            && let Some(code) = claude_share::refusal(&coordinator.claude, root)
        {
            return code;
        }
    }
    if let Err(error) = coordinator.docker.available() {
        eprintln!("error: container runtime unavailable: {error}");
        return ExitCode::from(1);
    }
    if args.down {
        if !args.yes {
            eprintln!("error: deploy --down removes serving containers; rerun with --yes");
            return ExitCode::from(2);
        }
        return result_code(coordinator.down());
    }
    if let Err(error) = link_assistant_router::deploy::immutable_ref(image) {
        eprintln!("error: image-ref: {error}");
        return ExitCode::from(2);
    }
    let transaction = match coordinator.state.transaction() {
        Ok(transaction) => transaction,
        Err(error) if args.status => return coordinator.diagnose(&error),
        Err(error) => return result_code(Err(error)),
    };
    let interrupted = transaction
        .as_ref()
        .filter(|transaction| transaction.phase != Phase::Complete);
    if args.status
        && let Some(transaction) = interrupted
    {
        return match coordinator.print_interrupted(transaction) {
            Ok(()) => ExitCode::from(1),
            Err(error) => result_code(Err(error)),
        };
    }
    if interrupted.is_some() && !args.status {
        if let Err(error) = coordinator.create_directories() {
            return result_code(Err(error));
        }
        let _recovery_lock = match coordinator.acquire_lock() {
            Ok(lock) => lock,
            Err(error) => return result_code(Err(error)),
        };
        if let Err(error) = coordinator.recover() {
            return result_code(Err(error));
        }
    }
    let existing = match coordinator.existing() {
        Ok(existing) => existing,
        Err(error) if args.status => return coordinator.diagnose(&error),
        Err(error) => match coordinator.adopt(&error) {
            Ok(existing) => existing,
            Err(error) => return result_code(Err(error)),
        },
    };
    if args.status {
        return match coordinator.print_status(&existing) {
            Ok(true) => ExitCode::SUCCESS,
            Ok(false) => ExitCode::from(1),
            Err(error) => result_code(Err(error)),
        };
    }
    if !matches!(&existing, Existing::Managed(_))
        && let Err(error) = coordinator.preflight(&existing)
    {
        eprintln!("update refused before deployment mutation: {error}");
        return ExitCode::from(2);
    }
    if let Err(error) = coordinator.create_directories() {
        return result_code(Err(error));
    }
    let _lock = match coordinator.acquire_lock() {
        Ok(lock) => lock,
        Err(error) => return result_code(Err(error)),
    };
    if let Err(error) = coordinator.recover() {
        return result_code(Err(error));
    }
    let existing = match coordinator.existing() {
        Ok(existing) => existing,
        Err(error) => return result_code(Err(error)),
    };
    let mut preflight_complete = false;
    if let Existing::Managed(active) = &existing {
        if let Err(error) = coordinator.print_status(&existing) {
            return result_code(Err(error));
        }
        // Even a repair starts serving processes. Refuse that mutation when
        // the old backend cannot provide the complete run inventory first.
        if let Err(error) = coordinator.inventory(&active.backend) {
            return result_code(Err(format!(
                "refusing topology mutation without a run inventory: {error}"
            )));
        }
        let specification_matches = match coordinator.no_op(active) {
            Ok(matches) => matches,
            Err(error) => return result_code(Err(error)),
        };
        let needs_repair = match coordinator.topology_needs_repair(active) {
            Ok(needs_repair) => needs_repair,
            Err(error) => return result_code(Err(error)),
        };
        // A healthy exact no-op does not interrupt anything and therefore does
        // not require force even if its inventory contains a legacy record.
        // Repair and replacement do mutate serving state, so classify and
        // refuse unsafe runs before either operation.
        if (!specification_matches || needs_repair)
            && let Err(error) = coordinator.preflight(&existing)
        {
            eprintln!("update refused before serving-state mutation: {error}");
            return ExitCode::from(2);
        }
        preflight_complete = true;
        let restored = match coordinator.restore_topology(active) {
            Ok(restored) => restored,
            Err(error) => return result_code(Err(error)),
        };
        if specification_matches {
            let rotation = match coordinator.converge_relay(active) {
                Ok(rotation) => rotation,
                Err(error) => return result_code(Err(error)),
            };
            if rotation == relay_rotation::Rotation::Rotated {
                println!(
                    "deployment specification already matched; relay moved to the backend image"
                );
            } else if restored {
                println!("deployment specification already matched; serving topology restored");
            } else {
                println!(
                    "deployment is already converged; no container, pointer, token, or credential changed"
                );
            }
            return ExitCode::SUCCESS;
        }
    }
    if !preflight_complete && let Err(error) = coordinator.preflight(&existing) {
        eprintln!("update refused before serving-state mutation: {error}");
        return ExitCode::from(2);
    }
    result_code(coordinator.deploy(&existing))
}

fn result_code(result: crate::translation_core::Outcome<(), String>) -> ExitCode {
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

//! Scoped checkpoint capture shared by native and library callers.
use super::data_backup;
use std::path::Path;

/// Capture a logical checkpoint, excluding OAuth credentials and preserving token records.
/// Individual files are consistent; callers needing a quiescent snapshot must stop writers.
/// ```no_run
/// # fn example() -> std::io::Result<()> {
/// let snapshot = link_assistant_router::deploy::checkpoint::capture(&Default::default(), "/tmp/router-deploy".as_ref(), &[], "signing-secret")?;
/// assert!(snapshot.join("manifest.json").exists());
/// # Ok(()) }
/// ```
pub fn capture_checkpoint(
    context: &crate::operation_context::OperationContext,
    root: &Path,
    records: &[crate::storage::TokenRecord],
    secret: &crate::translation_core::Str,
) -> std::io::Result<std::path::PathBuf> {
    context.scope(|| data_backup::capture(root, records, secret))
}

//! Opt-in use of this machine's Claude Code login by a local deployment
//! (issue #622).
//!
//! The backend used to see only `<root>/credentials`, which nothing fills, so
//! Anthropic was silently absent while other providers kept `/api/health`
//! green. A snapshot copy is no answer: the refresh token rotates, and two
//! holders of one chain fork it on the first refresh (#574). `share` therefore
//! mounts the vendor's own directory — a directory, because Router and Claude
//! Code both replace the file by rename — and runs the backend as the file's
//! owner. A rotation by either side is then the other's next read, and the host
//! CLI can still open what Router rewrote.
//!
//! Only a login that lives in that file can be shared. On macOS Claude Code
//! keeps the live credential in the login Keychain, and the file beside it is a
//! snapshot nothing rotates (#249). A container can reach neither, so that case
//! is refused with the reason instead of deploying a credential that dies
//! within hours.
//!
//! Only paths and reasons are printed; credential bytes never are.

use std::path::{Path, PathBuf};

use link_assistant_router::cli::{ClaudeCredentials, DeployArgs};
use link_assistant_router::env_paths::from_value;

/// Claude Code's own credential file inside its home.
const CREDENTIAL_FILE: &str = ".credentials.json";

/// Preserve credential refusals before checking a default container image.
#[must_use]
pub fn preflight(args: &DeployArgs, root: &Path) -> Option<std::process::ExitCode> {
    let mode = args.claude_credentials?;
    if args.status || args.down {
        return None;
    }
    refusal(&Provision::assess(mode, &root.join("data")), root)
}

pub(super) fn refusal(provision: &Provision, root: &Path) -> Option<std::process::ExitCode> {
    let Provision::Refused(reason) = provision else {
        return None;
    };
    println!("{}", provision.status_line(root));
    eprintln!("error: --claude-credentials share refused before deployment mutation: {reason}");
    Some(std::process::ExitCode::from(2))
}

/// Backend label recording the credential a container was started with.
pub(super) const LABEL_SUFFIX: &str = "claude-credentials";

/// What the candidate backend will use for Anthropic.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum Provision {
    /// The deployment's own `<root>/credentials`, read-only.
    Isolated,
    /// The host's Claude Code home, mounted read-write as `owner`.
    Shared {
        home: PathBuf,
        owner: Option<(u32, u32)>,
    },
    /// `share` was requested but cannot be honoured, and why.
    Refused(String),
}

impl Provision {
    /// Decide from the operator's choice and this machine's Claude Code home.
    pub(super) fn assess(mode: ClaudeCredentials, data: &Path) -> Self {
        Self::assess_in(
            mode,
            crate::operation_context::var_os("CLAUDE_CONFIG_DIR"),
            crate::operation_context::var_os("HOME"),
            data,
            link_assistant_router::platform_keychain::has_entry,
        )
    }

    /// [`Self::assess`] for a given environment and Keychain presence probe.
    ///
    /// The probe is asked about the entry of the home being shared — the one
    /// Claude Code itself would use for that `CLAUDE_CONFIG_DIR` — so another
    /// profile's Keychain login does not condemn a file-backed home (#653).
    pub(super) fn assess_in(
        mode: ClaudeCredentials,
        config_dir: Option<std::ffi::OsString>,
        user_home: Option<std::ffi::OsString>,
        data: &Path,
        has_entry: impl FnOnce(&str) -> bool,
    ) -> Self {
        match mode {
            ClaudeCredentials::Isolated => Self::Isolated,
            ClaudeCredentials::Share => {
                let config_dir = from_value(config_dir);
                let service = link_assistant_router::platform_keychain::claude_service_for(
                    config_dir.as_deref().map(Path::as_os_str),
                );
                let home =
                    config_dir.or_else(|| from_value(user_home).map(|home| home.join(".claude")));
                share(home.as_deref(), || has_entry(&service), data)
            }
        }
    }

    /// The label value that makes a mode change a new launch specification.
    pub(super) fn label(&self) -> String {
        match self {
            Self::Isolated => "isolated".to_string(),
            Self::Shared { home, .. } => format!("shared:{}", home.display()),
            Self::Refused(_) => "refused".to_string(),
        }
    }

    /// The operator-facing `anthropic_credential=` status line.
    pub(super) fn status_line(&self, root: &Path) -> String {
        match self {
            Self::Isolated => {
                let credentials = root.join("credentials");
                let empty = std::fs::read_dir(&credentials)
                    .map_or(true, |mut entries| entries.next().is_none());
                format!(
                    "anthropic_credential=skipped source={} reason={}the host Claude Code login \
                     was not requested; pass --claude-credentials share to use it",
                    credentials.display(),
                    if empty {
                        "the directory is empty and "
                    } else {
                        ""
                    }
                )
            }
            Self::Shared { home, owner } => format!(
                "anthropic_credential=imported method=shared-mount source={} user={} \
                 refresh_tokens_copied=0",
                home.display(),
                owner.map_or_else(
                    || "container-default".to_string(),
                    |(uid, gid)| format!("{uid}:{gid}")
                )
            ),
            Self::Refused(reason) => format!("anthropic_credential=refused reason={reason}"),
        }
    }
}

pub(super) fn share(
    home: Option<&Path>,
    keychain: impl FnOnce() -> bool,
    data: &Path,
) -> Provision {
    let Some(home) = home else {
        return Provision::Refused(
            "HOME and CLAUDE_CONFIG_DIR are unset, so there is no Claude Code home".to_string(),
        );
    };
    let home = match home.canonicalize() {
        Ok(home) if home.is_dir() => home,
        Ok(_) | Err(_) => {
            return Provision::Refused(format!(
                "there is no Claude Code home at {}; run `claude` and log in first",
                home.display()
            ));
        }
    };
    if keychain() {
        return Provision::Refused(format!(
            "Claude Code keeps this login in the macOS Keychain, which a container can neither \
             read nor update; {} holds a snapshot nothing rotates, and copying the Keychain \
             entry would fork its rotating refresh chain. Run `router deploy --mode host` to move this \
             deployment to a host Router that reads the Keychain in place",
            home.join(CREDENTIAL_FILE).display()
        ));
    }
    let file = home.join(CREDENTIAL_FILE);
    let bytes = match std::fs::read(&file) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Provision::Refused(format!(
                "{} holds no Claude Code login ({CREDENTIAL_FILE} is absent); run `claude` and \
                 log in first",
                home.display()
            ));
        }
        Err(error) => {
            return Provision::Refused(format!(
                "{} cannot be read: {}",
                file.display(),
                error.kind()
            ));
        }
    };
    if let Err(reason) = oauth_login(&bytes) {
        return Provision::Refused(format!("{} {reason}", file.display()));
    }
    if let Err(error) = tempfile::NamedTempFile::new_in(&home) {
        return Provision::Refused(format!(
            "{} is not writable ({}); the credential is replaced by rename beside it",
            home.display(),
            error.kind()
        ));
    }
    let owner = owner(&file);
    if let Some((uid, gid)) = owner
        && let Some(stranger) = foreign_entry(data, uid)
    {
        return Provision::Refused(format!(
            "{} belongs to another user (an earlier backend ran as root); the shared backend \
             runs as {uid}:{gid} and could not write it. Run `sudo chown -R {uid}:{gid} {}` first",
            stranger.display(),
            data.display()
        ));
    }
    Provision::Shared { home, owner }
}

/// Accept Claude Code's own OAuth login; the reason names what is missing.
fn oauth_login(bytes: &[u8]) -> Result<(), &'static str> {
    // Parse errors are replaced by a fixed reason: serde's message can quote
    // the input, and the input is a credential.
    let value: serde_json::Value = serde_json::from_slice(bytes).map_err(|_| "is not JSON")?;
    if value.get("_link_assistant_router").is_some() {
        return Err("is a Router pointer, not Claude Code's own login");
    }
    let oauth = value
        .get("claudeAiOauth")
        .ok_or("holds no Claude.ai OAuth login")?;
    let present = |key: &str| {
        oauth
            .get(key)
            .and_then(serde_json::Value::as_str)
            .is_some_and(|value| !value.is_empty())
    };
    if !present("refreshToken") {
        return Err("holds no refresh token, so it would stop working at its first expiry");
    }
    if !present("accessToken") {
        return Err("holds no access token");
    }
    Ok(())
}

#[cfg(unix)]
fn owner(file: &Path) -> Option<(u32, u32)> {
    use std::os::unix::fs::MetadataExt as _;
    std::fs::metadata(file)
        .ok()
        .map(|metadata| (metadata.uid(), metadata.gid()))
}

#[cfg(not(unix))]
const fn owner(_file: &Path) -> Option<(u32, u32)> {
    None
}

/// The first entry under `data` another user owns, if any.
#[cfg(unix)]
pub(super) fn foreign_entry(data: &Path, uid: u32) -> Option<PathBuf> {
    use std::os::unix::fs::MetadataExt as _;
    let mut pending = vec![data.to_path_buf()];
    while let Some(path) = pending.pop() {
        let Ok(metadata) = std::fs::symlink_metadata(&path) else {
            continue;
        };
        if metadata.uid() != uid {
            return Some(path);
        }
        if metadata.is_dir()
            && let Ok(entries) = std::fs::read_dir(&path)
        {
            pending.extend(entries.flatten().map(|entry| entry.path()));
        }
    }
    None
}

#[cfg(not(unix))]
pub(super) const fn foreign_entry(_data: &Path, _uid: u32) -> Option<PathBuf> {
    None
}

