//! The client token a local deployment issues, and its limits (issue #679).
//!
//! Every accepted candidate carries one unrevoked `deploy`-labelled client
//! token. `--token-*` flags (or `[tokens]` in `--config`) bound it: lifetime,
//! request and token caps, rate and the exact models it may request. Without
//! them it is issued exactly as before. The value is never printed.

use super::{Coordinator, LABEL_KEY, runtime_env};

impl Coordinator<'_> {
    pub(super) fn ensure_deploy_token(&self, backend: &str) {
        let present = self
            .docker
            .token_inventory(backend)
            .ok()
            .and_then(|rendered| {
                crate::operations::decode_token_inventory(rendered.as_bytes()).ok()
            })
            .is_some_and(|records| {
                records
                    .iter()
                    .any(|record| record.label == "deploy" && !record.revoked)
            });
        if !present {
            let policy = runtime_env::current().tokens.issue_arguments();
            let mut arguments = vec!["router", "tokens", "issue", "--label", "deploy"];
            arguments.extend(policy.iter().map(String::as_str));
            match self.docker.exec(backend, &arguments) {
                Ok(_) => println!("issued deploy client token (value withheld)"),
                Err(error) => println!("deploy client token skipped: {error}"),
            }
        }
    }

    /// The runtime environment fingerprint a backend was launched with.
    pub(super) fn runtime_env_label(&self, backend: &str) -> Option<String> {
        self.docker.label(
            backend,
            &format!("{LABEL_KEY}.{}", runtime_env::LABEL_SUFFIX),
        )
    }
}

//! Read-only diagnosis and explicit adoption of an inconsistent local
//! deployment (issue #631).
//!
//! A running relay and backend whose durable `active` record is missing or
//! unparseable still serve clients. Status describes that topology instead
//! of stopping at the first disagreement, and the next ordinary `router
//! deploy` records the running topology without touching a container, so
//! established streams and issued tokens survive the repair.

use std::process::ExitCode;

use super::state::{Active, ActiveRecord};
use super::{Coordinator, Existing, LABEL_KEY, RELAY, SPEC_VERSION};

impl Coordinator<'_> {
    /// The record the running topology proves, or why it proves none.
    pub(super) fn adoptable(&self) -> Result<Active, String> {
        match self.state.active_record() {
            ActiveRecord::Absent | ActiveRecord::Corrupt(_) => {}
            ActiveRecord::Valid(active) => {
                return Err(format!(
                    "the active record names {} and disagrees with the running topology",
                    active.backend
                ));
            }
            ActiveRecord::Unsupported(reason) => {
                return Err(format!(
                    "the active record is not ours to replace: {reason}"
                ));
            }
        }
        let backend = self
            .state
            .current()?
            .ok_or("the relay pointer names no backend")?;
        if !self.docker.owned(&backend, self.root, "backend") {
            return Err(format!(
                "pointer backend {backend} is absent or not owned by this root"
            ));
        }
        if self.label(&backend, "spec").as_deref() != Some(SPEC_VERSION) {
            return Err(format!(
                "pointer backend {backend} has an unknown launch specification"
            ));
        }
        if !self.docker.owned(&RELAY.value(), self.root, "relay")
            || self.label(&RELAY.value(), "spec").as_deref() != Some(SPEC_VERSION)
        {
            return Err(format!("{RELAY} is absent or not owned by this root"));
        }
        let port = self
            .label(&RELAY.value(), "port")
            .and_then(|port| port.parse().ok())
            .ok_or_else(|| format!("{RELAY} has no published port label"))?;
        Ok(Active {
            version: 1,
            image_ref: self.docker.image_ref(&backend)?,
            image_id: self.docker.container_image_id(&backend)?,
            backend,
            port,
        })
    }

    fn label(&self, container: &str, suffix: &str) -> Option<String> {
        self.docker
            .label(container, &format!("{LABEL_KEY}.{suffix}"))
    }

    /// Print the diagnosis for a status run; never a success.
    pub(super) fn diagnose(&self, error: &str) -> ExitCode {
        let mut report = self.status_report("container", "inconsistent");
        report["blockers"] = serde_json::json!([super::status_report::blocker(
            "inconsistent-state",
            error,
            false
        )]);
        crate::operation_output::record(report);
        eprintln!("warning: local deployment state is inconsistent: {error}");
        for line in self.diagnosis(error) {
            println!("{line}");
        }
        ExitCode::from(1)
    }

    /// Describe every fact status can read, then the safe recovery plan.
    /// Only inspections and read-only `exec`s run here.
    pub(super) fn diagnosis(&self, error: &str) -> Vec<String> {
        let mut lines = vec![
            format!("deployment_root={}", self.root.display()),
            format!("candidate_image={}", self.image),
            self.claude.status_line(self.root),
            format!("consistency=inconsistent reason={error:?}"),
            format!("active_record={}", self.state.active_record().describe()),
        ];
        let pointer = self.state.current();
        lines.push(match &pointer {
            Ok(Some(backend)) => format!("relay_pointer={backend}"),
            Ok(None) => "relay_pointer=absent".to_string(),
            Err(reason) => format!("relay_pointer=unreadable reason={reason:?}"),
        });
        lines.push(match self.state.transaction() {
            Ok(Some(transaction)) => format!("transaction={:?}", transaction.phase),
            Ok(None) => "transaction=absent".to_string(),
            Err(reason) => format!("transaction=unreadable reason={reason:?}"),
        });
        let mut containers = self.docker.owned_containers(self.root).unwrap_or_default();
        containers.sort();
        let pointer = pointer.ok().flatten();
        for container in &containers {
            lines.push(self.describe_container(container, pointer.as_deref()));
        }
        if self.docker.exists(&RELAY.value())
            && !containers.iter().any(|name| name == &RELAY.value())
        {
            lines.push(format!(
                "container={RELAY} owner=foreign root={}",
                self.label(&RELAY.value(), "root")
                    .as_deref()
                    .unwrap_or("unlabelled")
            ));
        }
        if let Some(backend) = pointer.as_deref().filter(|backend| {
            containers.iter().any(|name| name == backend)
                && self.docker.running(backend).unwrap_or(false)
        }) {
            lines.push(match self.connection_count(backend) {
                Ok(count) => format!("connections={count}"),
                Err(reason) => format!("connections=unknown reason={reason:?}"),
            });
            lines.push(match self.inventory(backend) {
                Ok(inventory) => format!(
                    "run_inventory runs={} blockers={}",
                    inventory.runs.len(),
                    inventory.blockers().count()
                ),
                Err(reason) => format!("run_inventory=unknown reason={reason:?}"),
            });
        }
        match self.adoptable() {
            Ok(active) => {
                lines.push(format!(
                    "recovery_plan=adopt backend={} image={} port={} mutation=active-record-only containers_unchanged=true",
                    active.backend, active.image_ref, active.port
                ));
                lines.push(
                    "next: rerun `router deploy` without --status; it records the running topology, keeps established streams and issued tokens, and then converges normally"
                        .to_string(),
                );
            }
            Err(reason) => {
                lines.push(format!("recovery_plan=manual reason={reason:?}"));
                lines.push(
                    "next: `router deploy --down --yes` removes only this root's containers and retains credentials, data and issued tokens; then rerun `router deploy`"
                        .to_string(),
                );
            }
        }
        lines.push("status_is_read_only=true".to_string());
        lines
    }

    fn describe_container(&self, container: &str, pointer: Option<&str>) -> String {
        let role = self.label(container, "role");
        let mut line = format!(
            "container={container} role={} running={} image={} spec={}",
            role.as_deref().unwrap_or("unlabelled"),
            self.docker
                .running(container)
                .map_or_else(|_| "unknown".to_string(), |running| running.to_string()),
            self.docker
                .image_ref(container)
                .unwrap_or_else(|_| "unknown".to_string()),
            self.label(container, "spec")
                .as_deref()
                .unwrap_or("unknown"),
        );
        let detail = match role.as_deref() {
            Some("relay") => format!(
                " port={}",
                self.label(container, "port")
                    .as_deref()
                    .unwrap_or("unknown")
            ),
            Some("backend") => format!(
                " claude_credentials={} pointer={}",
                self.claude_label(container),
                pointer == Some(container)
            ),
            _ => String::new(),
        };
        line.push_str(&detail);
        line
    }

    /// Record the running topology under the update lock. No container is
    /// started, stopped or replaced; a corrupt record is kept beside it.
    pub(super) fn adopt(&self, error: &str) -> Result<Existing, String> {
        self.adoptable().map_err(|reason| {
            format!(
                "{error}; automatic recovery refused: {reason}; inspect with `router deploy --status`"
            )
        })?;
        self.create_directories()?;
        let _lock = self.acquire_lock()?;
        let active = self.adoptable()?;
        if matches!(self.state.active_record(), ActiveRecord::Corrupt(_)) {
            let aside = self.state.set_aside_active()?;
            println!("set_aside_active_record={}", aside.display());
        }
        self.state.write_active(&active)?;
        println!(
            "recovery=adopted backend={} image={} port={} containers_unchanged=true",
            active.backend, active.image_ref, active.port
        );
        self.existing()
    }
}

//! Auditable Docker command boundary for the local rolling coordinator.

use std::path::Path;

use super::claude_share::{LABEL_SUFFIX, Provision};
use super::secret::{self, fingerprint};
use super::{LABEL_KEY, NETWORK, RELAY, SPEC_VERSION};

pub(super) struct CommandOutput {
    pub success: bool,
    pub stdout: Vec<u8>,
    pub stderr: Vec<u8>,
}

pub(super) trait CommandRunner: Send + Sync {
    fn run(
        &self,
        arguments: &[String],
        environment: &[(&str, &str)],
    ) -> Result<CommandOutput, String>;
}

struct ProcessRunner;

impl CommandRunner for ProcessRunner {
    fn run(
        &self,
        arguments: &[String],
        environment: &[(&str, &str)],
    ) -> Result<CommandOutput, String> {
        let mut command = crate::operation_context::command("docker");
        command.args(arguments).envs(environment.iter().copied());
        let seconds = if arguments
            .first()
            .is_some_and(|arg| arg == "build" || arg == "pull")
        {
            900
        } else {
            30
        };
        let output = crate::operation_context::bounded_output(
            &mut command,
            std::time::Duration::from_secs(seconds),
        )
        .map_err(|error| match error.kind() {
            std::io::ErrorKind::NotFound => "Docker is not installed".to_string(),
            _ => error.to_string(),
        })?;
        Ok(CommandOutput {
            success: output.status.success(),
            stdout: output.stdout,
            stderr: output.stderr,
        })
    }
}

pub(super) struct Docker {
    runner: Box<dyn CommandRunner>,
}

impl Default for Docker {
    fn default() -> Self {
        Self {
            runner: Box::new(ProcessRunner),
        }
    }
}

#[cfg(test)]
impl Docker {
    pub(super) fn with_runner(runner: impl CommandRunner + 'static) -> Self {
        Self {
            runner: Box::new(runner),
        }
    }
}

fn compact(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes)
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

impl Docker {
    pub(super) fn command(
        &self,
        arguments: &[String],
        environment: &[(&crate::translation_core::Str, &crate::translation_core::Str)],
    ) -> Result<CommandOutput, String> {
        self.runner.run(arguments, environment)
    }

    pub(super) fn output(&self, arguments: &[String]) -> Result<String, String> {
        let output = self.command(arguments, &[])?;
        if output.success {
            Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
        } else {
            Err(compact(&output.stderr))
        }
    }

    pub(super) fn available(&self) -> Result<String, String> {
        self.output(&[
            "info".into(),
            "--format".into(),
            "{{.ServerVersion}}".into(),
        ])
    }

    pub(super) fn exists(&self, name: &crate::translation_core::Str) -> bool {
        self.output(&["inspect".into(), name.into()]).is_ok()
    }

    pub(super) fn running(&self, name: &crate::translation_core::Str) -> Result<bool, String> {
        self.output(&[
            "inspect".into(),
            "--format".into(),
            "{{.State.Running}}".into(),
            name.into(),
        ])
        .map(|answer| answer == "true")
    }

    pub(super) fn label(&self, name: &crate::translation_core::Str, key: &crate::translation_core::Str) -> Option<String> {
        self.output(&[
            "inspect".into(),
            "--format".into(),
            format!("{{{{index .Config.Labels {key:?}}}}}"),
            name.into(),
        ])
        .ok()
        .filter(|value| !value.is_empty() && value != "<no value>")
    }

    pub(super) fn image_ref(&self, name: &crate::translation_core::Str) -> Result<String, String> {
        self.output(&[
            "inspect".into(),
            "--format".into(),
            "{{.Config.Image}}".into(),
            name.into(),
        ])
    }

    pub(super) fn mount_source(&self, name: &crate::translation_core::Str, destination: &crate::translation_core::Str) -> Option<String> {
        self.output(&[
            "inspect".into(),
            "--format".into(),
            format!(
                "{{{{range .Mounts}}}}{{{{if eq .Destination {destination:?}}}}}{{{{.Source}}}}{{{{end}}}}{{{{end}}}}"
            ),
            name.into(),
        ])
        .ok()
        .filter(|source| !source.is_empty())
    }

    pub(super) fn container_image_id(&self, name: &crate::translation_core::Str) -> Result<String, String> {
        self.output(&[
            "inspect".into(),
            "--format".into(),
            "{{.Image}}".into(),
            name.into(),
        ])
    }

    pub(super) fn image_id(&self, image: &crate::translation_core::Str) -> Result<String, String> {
        self.output(&[
            "image".into(),
            "inspect".into(),
            "--format".into(),
            "{{.Id}}".into(),
            image.into(),
        ])
    }

    pub(super) fn ensure_image(&self, image: &crate::translation_core::Str, build: Option<&crate::translation_core::Str>) -> Result<String, String> {
        if let Some(context) = build {
            self.output(&["build".into(), "-t".into(), image.into(), context.into()])?;
        } else if self.image_id(image).is_err() {
            self.output(&["pull".into(), image.into()])?;
        }
        self.image_id(image)
    }

    pub(super) fn start(&self, name: &crate::translation_core::Str) -> Result<(), String> {
        self.output(&["start".into(), name.into()]).map(|_| ())
    }

    pub(super) fn stop(&self, name: &crate::translation_core::Str) -> Result<(), String> {
        self.output(&["stop".into(), name.into()]).map(|_| ())
    }

    pub(super) fn remove(&self, name: &crate::translation_core::Str) -> Result<(), String> {
        if self.exists(name) {
            self.output(&["rm".into(), "-f".into(), name.into()])?;
        }
        Ok(())
    }

    pub(super) fn exec(&self, name: &crate::translation_core::Str, arguments: &[&crate::translation_core::Str]) -> Result<String, String> {
        let mut command = vec!["exec".to_string(), name.to_string()];
        command.extend(arguments.iter().map(|value| (*value).to_string()));
        self.output(&command)
    }

    /// `docker exec -e NAME`: each value reaches the container through this
    /// process's environment, never through argv.
    pub(super) fn exec_with_env(
        &self,
        name: &crate::translation_core::Str,
        environment: &[(&crate::translation_core::Str, &crate::translation_core::Str)],
        arguments: &[&crate::translation_core::Str],
    ) -> Result<String, String> {
        let mut command = vec!["exec".to_string()];
        for (key, _) in environment {
            command.extend(["-e".to_string(), (*key).to_string()]);
        }
        command.push(name.to_string());
        command.extend(arguments.iter().map(|value| (*value).to_string()));
        let output = self.command(&command, environment)?;
        if output.success {
            Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
        } else {
            Err(compact(&output.stderr))
        }
    }

    /// One variable of a container's launch environment, held in memory
    /// only; the caller must not print it.
    pub(super) fn env_value(&self, name: &crate::translation_core::Str, key: &crate::translation_core::Str) -> Option<String> {
        let rendered = self
            .output(&[
                "inspect".into(),
                "--format".into(),
                "{{range .Config.Env}}{{println .}}{{end}}".into(),
                name.into(),
            ])
            .ok()?;
        rendered
            .lines()
            .find_map(|line| line.strip_prefix(key)?.strip_prefix('='))
            .map(str::to_string)
    }

    pub(super) fn token_inventory(&self, name: &crate::translation_core::Str) -> Result<String, String> {
        self.exec(name, &["router", "tokens", "list", "--json"])
    }

    pub(super) fn relay_connection_count(&self, backend: &crate::translation_core::Str) -> Result<String, String> {
        if !self.exists(&RELAY.value()) || !self.running(&RELAY.value())? {
            // Restarting or stopping the relay necessarily closes all of the
            // TCP connections it owned, even if its last durable count was
            // nonzero.
            return Ok("0".to_string());
        }
        let path = format!("/deploy-state/connections/{backend}");
        self.exec(
            &RELAY.value(),
            &[
                "sh",
                "-c",
                "if [ -e \"$1\" ]; then cat \"$1\"; else printf 0; fi",
                "relay-count",
                &path,
            ],
        )
    }

    pub(super) fn listeners_on(&self, port: u16) -> Result<Vec<String>, String> {
        let answer = self.output(&[
            "ps".into(),
            "--filter".into(),
            format!("publish={port}"),
            "--format".into(),
            "{{.Names}}".into(),
        ])?;
        Ok(answer
            .lines()
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(str::to_string)
            .collect())
    }

    pub(super) fn health(&self, from: &crate::translation_core::Str, origin: &crate::translation_core::Str) -> bool {
        let script = format!(
            "const r=await fetch({origin:?}+'/api/health',{{signal:AbortSignal.timeout(5000)}});process.exit(r.status===200?0:1)"
        );
        self.exec(from, &["bun", "-e", &script]).is_ok()
    }

    pub(super) fn create_network(&self, root: &Path) -> Result<(), String> {
        if self
            .output(&["network".into(), "inspect".into(), NETWORK.to_string()])
            .is_ok()
        {
            if self.network_owned(root) {
                return Ok(());
            }
            return Err(format!("refusing unowned Docker network {NETWORK}"));
        }
        self.output(&[
            "network".into(),
            "create".into(),
            "--label".into(),
            format!("{LABEL_KEY}=1"),
            "--label".into(),
            format!("{LABEL_KEY}.root={}", root.display()),
            "--label".into(),
            format!("{LABEL_KEY}.spec={SPEC_VERSION}"),
            NETWORK.to_string(),
        ])?;
        Ok(())
    }

    pub(super) fn remove_network(&self, root: &Path) -> Result<(), String> {
        if self.network_owned(root) {
            self.output(&["network".into(), "rm".into(), NETWORK.to_string()])?;
        }
        Ok(())
    }

    fn network_owned(&self, root: &Path) -> bool {
        let inspect_label = |key: &str| {
            self.output(&[
                "network".into(),
                "inspect".into(),
                "--format".into(),
                format!("{{{{index .Labels {key:?}}}}}"),
                NETWORK.to_string(),
            ])
            .ok()
        };
        inspect_label(LABEL_KEY).as_deref() == Some("1")
            && inspect_label(&format!("{LABEL_KEY}.root")).as_deref()
                == Some(root.display().to_string().as_str())
            && inspect_label(&format!("{LABEL_KEY}.spec")).as_deref() == Some(SPEC_VERSION)
    }

    pub(super) fn run_backend(
        &self,
        name: &crate::translation_core::Str,
        image: &crate::translation_core::Str,
        root: &Path,
        token_secret: &crate::translation_core::Str,
        claude: &Provision,
    ) -> Result<(), String> {
        let mut arguments =
            backend_arguments(name, image, root, claude, &fingerprint(token_secret));
        let runtime = super::runtime_env::current();
        super::runtime_env::insert(&mut arguments, &runtime, token_secret);
        let output = self.command(
            &arguments,
            &super::runtime_env::environment(&runtime, token_secret),
        )?;
        if output.success {
            Ok(())
        } else {
            Err(compact(&output.stderr))
        }
    }

    pub(super) fn run_relay(&self, image: &crate::translation_core::Str, root: &Path, port: u16) -> Result<(), String> {
        self.output(&[
            "run".into(),
            "-d".into(),
            "--name".into(),
            RELAY.to_string(),
            "--network".into(),
            NETWORK.to_string(),
            "--restart".into(),
            "unless-stopped".into(),
            "--label".into(),
            format!("{LABEL_KEY}=1"),
            "--label".into(),
            format!("{LABEL_KEY}.root={}", root.display()),
            "--label".into(),
            format!("{LABEL_KEY}.role=relay"),
            "--label".into(),
            format!("{LABEL_KEY}.port={port}"),
            "--label".into(),
            format!("{LABEL_KEY}.spec={SPEC_VERSION}"),
            "-p".into(),
            format!("127.0.0.1:{port}:8080"),
            "-v".into(),
            format!("{}:/deploy-state", root.join("state").display()),
            "-e".into(),
            "ROUTER_DEPLOY_RELAY_STATE=/deploy-state/current".into(),
            "-e".into(),
            "ROUTER_DEPLOY_RELAY_LISTENERS=0.0.0.0:8080,8080".into(),
            image.into(),
            "serve".into(),
        ])?;
        Ok(())
    }

    pub(super) fn owned(&self, name: &crate::translation_core::Str, root: &Path, role: &crate::translation_core::Str) -> bool {
        self.label(name, LABEL_KEY).as_deref() == Some("1")
            && self.label(name, &format!("{LABEL_KEY}.root")).as_deref()
                == Some(root.display().to_string().as_str())
            && self.label(name, &format!("{LABEL_KEY}.role")).as_deref() == Some(role)
    }

    pub(super) fn legacy_owned(&self, name: &crate::translation_core::Str, root: &Path) -> bool {
        let credential_home = root.join("credentials").display().to_string();
        let data_home = root.join("data").display().to_string();
        self.label(name, LABEL_KEY).as_deref() == Some("1")
            && self.label(name, &format!("{LABEL_KEY}.role")).is_none()
            && self.mount_source(name, "/data/claude").as_deref() == Some(credential_home.as_str())
            && self.mount_source(name, "/data/router").as_deref() == Some(data_home.as_str())
    }

    pub(super) fn owned_containers(&self, root: &Path) -> Result<Vec<String>, String> {
        let answer = self.output(&[
            "ps".into(),
            "-a".into(),
            "--filter".into(),
            format!("label={LABEL_KEY}=1"),
            "--filter".into(),
            format!("label={LABEL_KEY}.root={}", root.display()),
            "--format".into(),
            "{{.Names}}".into(),
        ])?;
        Ok(answer
            .lines()
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(str::to_string)
            .collect())
    }
}

fn backend_arguments(
    name: &crate::translation_core::Str,
    image: &crate::translation_core::Str,
    root: &Path,
    claude: &Provision,
    secret_fingerprint: &crate::translation_core::Str,
) -> Vec<String> {
    let mut arguments: Vec<String> = vec![
        "run".into(),
        "-d".into(),
        "--name".into(),
        name.into(),
        "--network".into(),
        NETWORK.to_string(),
        "--restart".into(),
        "unless-stopped".into(),
        "--label".into(),
        format!("{LABEL_KEY}=1"),
        "--label".into(),
        format!("{LABEL_KEY}.root={}", root.display()),
        "--label".into(),
        format!("{LABEL_KEY}.role=backend"),
        "--label".into(),
        format!("{LABEL_KEY}.image-ref={image}"),
        "--label".into(),
        format!("{LABEL_KEY}.spec={SPEC_VERSION}"),
        "--label".into(),
        format!("{LABEL_KEY}.{LABEL_SUFFIX}={}", claude.label()),
        "--label".into(),
        format!("{LABEL_KEY}.{}={secret_fingerprint}", secret::LABEL_SUFFIX),
    ];
    if let Provision::Shared { home, owner } = claude {
        // Read-write and the whole directory: both Router and Claude Code
        // replace the credential by rename. As the file's owner, so the host
        // CLI can still read what Router rewrote (issue #622).
        arguments.extend(["-v".into(), format!("{}:/data/claude", home.display())]);
        if let Some((uid, gid)) = owner {
            arguments.extend([
                "--user".into(),
                format!("{uid}:{gid}"),
                "-e".into(),
                "HOME=/data/router".into(),
            ]);
        }
    } else {
        arguments.extend([
            "-v".into(),
            format!("{}:/data/claude:ro", root.join("credentials").display()),
        ]);
    }
    arguments.extend([
        "-v".into(),
        format!("{}:/data/router", root.join("data").display()),
        "-e".into(),
        "TOKEN_SECRET".into(),
        "-e".into(),
        "DATA_DIR=/data/router".into(),
        "-e".into(),
        "STORAGE_POLICY=text".into(),
        "-e".into(),
        "CLAUDE_CODE_HOME=/data/claude".into(),
        image.into(),
        "serve".into(),
    ]);
    arguments
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn old_and_candidate_use_one_durable_state_and_never_put_the_secret_in_argv() {
        let root = Path::new("/srv/router");
        let arguments = backend_arguments(
            "candidate",
            "router:1.2.3",
            root,
            &Provision::Isolated,
            &fingerprint("a-secret-value"),
        );
        let joined = arguments.join(" ");

        assert!(joined.contains(&format!("{}:/data/router", root.join("data").display())));
        assert!(joined.contains(&format!(
            "{}:/data/claude:ro",
            root.join("credentials").display()
        )));
        assert!(joined.contains("-e TOKEN_SECRET"));
        assert!(!joined.contains("a-secret-value"));
        assert!(joined.contains(&format!(
            "{LABEL_KEY}.token-secret={}",
            fingerprint("a-secret-value")
        )));
        assert!(!joined.contains("releases/"));
        assert!(joined.contains(&format!("{LABEL_KEY}.{LABEL_SUFFIX}=isolated")));
        assert!(!joined.contains("--user"));
    }

    #[test]
    fn a_shared_login_mounts_the_vendor_home_writable_as_its_owner() {
        let root = Path::new("/srv/router");
        let claude = Provision::Shared {
            home: "/home/operator/.claude".into(),
            owner: Some((1000, 1000)),
        };
        let arguments = backend_arguments("candidate", "router:1.2.3", root, &claude, "fp");
        let joined = arguments.join(" ");

        assert!(joined.contains("-v /home/operator/.claude:/data/claude -"));
        assert!(!joined.contains(":/data/claude:ro"));
        assert!(!joined.contains(&root.join("credentials").display().to_string()));
        assert!(joined.contains("--user 1000:1000"));
        assert!(joined.contains(&format!(
            "{LABEL_KEY}.{LABEL_SUFFIX}=shared:/home/operator/.claude"
        )));
        assert_eq!(arguments[arguments.len() - 2..], ["router:1.2.3", "serve"]);
    }
}

//! Serve a local deployment from the host instead of containers (issue #626).
//!
//! On macOS Claude Code keeps its live, rotating login in the Keychain, which
//! no container can read or update, so `--claude-credentials share` is
//! refused and a container deployment cannot expose Anthropic. Host mode runs
//! this Router binary on the host, where the Keychain is read in place, with
//! the deployment's own data directory (token store, request logs, provider
//! configuration), the same signing secret, and the same loopback port, so
//! issued client tokens and every client profile pointing at that endpoint
//! keep working and exactly one local endpoint exists.
//!
//! The migration is candidate-first. A host candidate on an ephemeral
//! loopback port must become healthy and accept a token signed with the
//! running deployment's secret before anything changes. Only then is the
//! relay stopped and the host process started on the stable port and
//! validated again; any failure restarts the relay, so the container
//! deployment keeps serving. The containers are stopped, not removed, and
//! `router deploy --mode container` restores them. OAuth bytes are never read
//! by this command: the Keychain is consulted for presence only, and the host
//! Router reads it itself.

use std::path::{Path, PathBuf};
use std::process::ExitCode;

use link_assistant_router::cli::{DeployArgs, DeployMode};

use super::host_runtime::{ClaudeLogin, HostRuntime};
use super::inventory::{Inventory, RunState};
use super::secret::{SecretMatch, fingerprint};
use super::state::{Active, Host, Phase};

use super::{Coordinator, Existing, RELAY, result_code};

/// The one command that returns a host deployment to its containers.
pub(super) const ROLLBACK_COMMAND: &str = "router deploy --mode container";

struct Blocker {
    name: &'static str,
    reason: String,
    forceable: bool,
}

/// What a host migration starts from, gathered without changing anything.
struct Plan {
    executable: PathBuf,
    router_version: String,
    login: ClaudeLogin,
    /// The managed container deployment host mode replaces.
    from: Option<Active>,
    record: Option<Host>,
    /// The recorded host process is alive and answers its health check.
    record_serving: bool,
    secret: SecretMatch,
    inventory: Option<Inventory>,
    converged: bool,
    /// Serving this executable, version and port, but `TOKEN_SECRET` was
    /// not supplied, so whether it signs with the same secret is unknown.
    secret_unknown: bool,
    /// The predicted pre-move data checkpoint, when it fits.
    checkpoint: Option<String>,
    blockers: Vec<Blocker>,
}

impl Plan {
    /// The mutating steps a deploy would take; none when nothing is known
    /// to need changing.
    fn steps(&self, port: u16) -> Vec<String> {
        if self.converged
            || self.secret_unknown
            || self.blockers.iter().any(|blocker| !blocker.forceable)
        {
            return Vec::new();
        }
        let mut steps = Vec::new();
        if self.from.is_some() {
            steps.push(
                "action=validate-host-candidate listener=127.0.0.1:ephemeral token_probe=required"
                    .to_string(),
            );
            steps.push(format!("action=stop-relay container={RELAY} retained=true"));
        }
        steps.push(format!(
            "action=start-host listener=127.0.0.1:{port} validate=health,token_probe"
        ));
        if let Some(active) = &self.from {
            steps.push(format!(
                "action=stop-backend container={} retained=true",
                active.backend
            ));
        }
        steps
    }

    fn convergence(&self) -> String {
        if self.secret_unknown {
            "converged=unknown reason=\"TOKEN_SECRET was not supplied; the host Router serves this executable, version and port, but its signing secret cannot be compared\"".to_string()
        } else {
            format!("converged={}", self.converged)
        }
    }

    fn block(&mut self, name: &'static str, reason: impl Into<String>, forceable: bool) {
        self.blockers.push(Blocker {
            name,
            reason: reason.into(),
            forceable,
        });
    }
}

/// Route a run that requests host mode or finds it in effect; `None`
/// continues with the container coordinator.
pub(super) fn dispatch(
    coordinator: &Coordinator<'_>,
    args: &DeployArgs,
    runtime: &dyn HostRuntime,
) -> Option<ExitCode> {
    let record = match coordinator.state.host() {
        Ok(record) => record,
        Err(error) => return Some(result_code(Err(error))),
    };
    if args.down {
        return coordinator.host_down(&record?, args.yes, runtime);
    }
    match (args.mode, record) {
        (Some(DeployMode::Host), record) | (None, record @ Some(_)) => {
            Some(coordinator.host_mode(args, record, runtime))
        }
        (Some(DeployMode::Container), Some(record)) => {
            coordinator.leave_host(args, &record, runtime)
        }
        (Some(DeployMode::Container) | None, None) => None,
    }
}

impl Coordinator<'_> {
    fn host_mode(
        &self,
        args: &DeployArgs,
        record: Option<Host>,
        runtime: &dyn HostRuntime,
    ) -> ExitCode {
        if args.claude_credentials.is_some() {
            eprintln!(
                "error: --claude-credentials selects a container backend's login; host mode \
                 reads this machine's Claude Code login in place, including the macOS Keychain"
            );
            return ExitCode::from(2);
        }
        let plan = match self.host_plan(record, runtime) {
            Ok(plan) => plan,
            Err(error) => return result_code(Err(error)),
        };
        self.print_host_plan(&plan);
        if args.status {
            let ready = plan.converged || plan.blockers.is_empty();
            return if ready {
                ExitCode::SUCCESS
            } else {
                ExitCode::from(1)
            };
        }
        if plan.converged {
            println!(
                "host deployment is already converged; no process, container, token, or credential changed"
            );
            return ExitCode::SUCCESS;
        }
        for blocker in &plan.blockers {
            if !blocker.forceable {
                eprintln!(
                    "host mode refused before deployment mutation: {}",
                    blocker.reason
                );
                return ExitCode::from(2);
            }
        }
        if let Some(blocker) = plan.blockers.first() {
            if !self.force {
                eprintln!(
                    "host mode refused before deployment mutation: {}; rerun with --force-update after reviewing the plan",
                    blocker.reason
                );
                return ExitCode::from(2);
            }
            for blocker in &plan.blockers {
                println!("force_update accepted {}", blocker.name);
            }
        }
        if plan.secret == SecretMatch::NotSupplied {
            eprintln!("{}", link_assistant_router::token_secret::refusal());
            return ExitCode::from(2);
        }
        result_code(self.migrate_to_host(&plan, runtime))
    }

    fn host_plan(&self, record: Option<Host>, runtime: &dyn HostRuntime) -> Result<Plan, String> {
        let executable = runtime.executable()?;
        let router_version = runtime.version(&executable)?;
        let data = self.root.join("data");
        let mut plan = Plan {
            executable,
            router_version,
            login: runtime.claude_login(),
            from: None,
            record_serving: record.as_ref().is_some_and(|record| {
                runtime.serving(record.pid, Path::new(&record.executable))
                    && runtime.status(record.port, "/api/health", None) == Some(200)
            }),
            record,
            secret: SecretMatch::Matches,
            inventory: None,
            converged: false,
            secret_unknown: false,
            checkpoint: None,
            blockers: Vec::new(),
        };
        let docker = self.docker.available().is_ok();
        if docker {
            match self.state.transaction() {
                Ok(Some(transaction)) if transaction.phase != Phase::Complete => plan.block(
                    "pending-transaction",
                    format!(
                        "an interrupted container update must be recovered first; run `{ROLLBACK_COMMAND}`"
                    ),
                    false,
                ),
                Err(error) => plan.block("inconsistent-state", error, false),
                Ok(_) => {}
            }
        }
        if plan.record.is_none() {
            if docker {
                match self.existing() {
                    Ok(Existing::Absent) => {}
                    Ok(Existing::Legacy) => plan.block(
                        "legacy-direct-front-door",
                        "the legacy direct container cannot prove it is idle; migrate it with `router deploy` first",
                        false,
                    ),
                    Ok(Existing::Managed(active)) => plan.from = Some(active),
                    // The relay name is machine-wide; another root's relay is
                    // not this deployment and only matters if it holds the port.
                    Err(_)
                        if self.state.active()?.is_none()
                            && !self.docker.owned(&RELAY.value(), self.root, "relay") => {}
                    Err(error) => plan.block("inconsistent-state", error, false),
                }
            } else if self.state.current()?.is_some()
                || self.state.active().ok().flatten().is_some()
            {
                plan.block(
                    "container-runtime-unavailable",
                    "the container deployment cannot be stopped without its container runtime",
                    false,
                );
            }
        }
        self.assess_source(&mut plan, runtime)?;
        if let Some(uid) = runtime.user_id()
            && data.exists()
            && let Some(stranger) = super::claude_share::foreign_entry(&data, uid)
        {
            plan.block(
                "foreign-owned-data",
                format!(
                    "{} belongs to another user (a container backend ran as root), so the host Router could not write it. Run `sudo chown -R {uid} {}` first",
                    stranger.display(),
                    data.display()
                ),
                false,
            );
        }
        // Every move or update checkpoints first; predict it so the plan names
        // the blocker the real run would hit (issue #658).
        match super::data_backup::checkpoint_status(self.root) {
            Ok(line) => plan.checkpoint = Some(line),
            Err(reason) => plan.block("data-checkpoint", reason, false),
        }
        let fingerprint = fingerprint(self.token_secret);
        let serving_this = plan.from.is_none()
            && plan.record_serving
            && plan.record.as_ref().is_some_and(|record| {
                Path::new(&record.executable) == plan.executable
                    && record.router_version == plan.router_version
                    && record.port == self.port
            });
        plan.converged = serving_this
            && plan.record.as_ref().is_some_and(|record| {
                record.token_secret == fingerprint
                    && record.runtime_env == super::runtime_env::fingerprint(self.token_secret)
            });
        // Without the secret, status reports what it can prove and invents
        // no restart for a host that already serves this build (issue #659).
        plan.secret_unknown = serving_this && plan.secret == SecretMatch::NotSupplied;
        Ok(plan)
    }

    /// The plan steps and convergence line `--status` would print.
    #[cfg(test)]
    pub(super) fn host_status_summary(
        &self,
        runtime: &dyn HostRuntime,
    ) -> Result<(Vec<String>, String), String> {
        let plan = self.host_plan(self.state.host()?, runtime)?;
        Ok((plan.steps(self.port), plan.convergence()))
    }

    /// Secret, listener, connections and runs of whatever serves now.
    fn assess_source(&self, plan: &mut Plan, runtime: &dyn HostRuntime) -> Result<(), String> {
        let placeholder = link_assistant_router::token_secret::is_placeholder(self.token_secret);
        if let Some(active) = plan.from.clone() {
            plan.secret = self.secret_match(&active.backend);
            if matches!(plan.secret, SecretMatch::Changed | SecretMatch::Unknown) {
                plan.block(
                    "token-secret-change",
                    format!(
                        "{} verifies tokens with another or unknown TOKEN_SECRET; its issued client tokens would be rejected with HTTP 401",
                        active.backend
                    ),
                    true,
                );
            }
            if active.port != self.port {
                plan.block(
                    "stable-listener-change",
                    format!(
                        "host mode keeps the stable listener; pass --port {}",
                        active.port
                    ),
                    false,
                );
            }
            let foreign = self
                .docker
                .listeners_on(self.port)?
                .into_iter()
                .filter(|name| name != &RELAY.value())
                .collect::<Vec<_>>();
            if !foreign.is_empty() {
                plan.block(
                    "port-in-use",
                    format!("port {} is published by {}", self.port, foreign.join(", ")),
                    false,
                );
            }
            let connections = self.connection_count(&active.backend)?;
            if connections > 0 {
                plan.block(
                    "established-connections",
                    format!(
                        "{connections} established connection(s) through {RELAY} would be cut when the listener moves"
                    ),
                    true,
                );
            }
            let rendered = if self.docker.running(&active.backend)? {
                self.docker.token_inventory(&active.backend)
            } else {
                runtime.token_inventory(&plan.executable, &self.root.join("data"))
            };
            Self::assess_runs(plan, rendered);
        } else if let Some(record) = plan.record.clone() {
            plan.secret = if placeholder {
                SecretMatch::NotSupplied
            } else if record.token_secret == fingerprint(self.token_secret) {
                SecretMatch::Matches
            } else {
                plan.block(
                    "token-secret-change",
                    "the host Router verifies tokens with another TOKEN_SECRET; its issued client tokens would be rejected with HTTP 401",
                    true,
                );
                SecretMatch::Changed
            };
            if record.port != self.port {
                plan.block(
                    "port-mismatch",
                    format!(
                        "host mode keeps the stable listener; pass --port {}",
                        record.port
                    ),
                    false,
                );
            }
            let outdated = Path::new(&record.executable) != plan.executable
                || record.router_version != plan.router_version;
            if plan.record_serving && outdated {
                plan.block(
                    "host-restart",
                    format!(
                        "replacing the running host Router {} with {} closes its open connections",
                        record.router_version, plan.router_version
                    ),
                    true,
                );
            }
            if plan.record_serving && (outdated || plan.secret != SecretMatch::Matches) {
                let rendered = runtime.token_inventory(&plan.executable, &self.root.join("data"));
                Self::assess_runs(plan, rendered);
            }
            if !plan.record_serving && runtime.status(self.port, "/api/health", None).is_some() {
                plan.block(
                    "port-in-use",
                    format!(
                        "another process answers on 127.0.0.1:{}, not the recorded host Router",
                        self.port
                    ),
                    false,
                );
            }
        } else {
            plan.secret = if placeholder {
                SecretMatch::NotSupplied
            } else {
                SecretMatch::Matches
            };
            if runtime.status(self.port, "/api/health", None).is_some() {
                plan.block(
                    "port-in-use",
                    format!("another process answers on 127.0.0.1:{}", self.port),
                    false,
                );
            }
        }
        Ok(())
    }

    /// A live run's next request would meet a closed listener during the
    /// swap, so live runs refuse the move unless it is forced.
    fn assess_runs(plan: &mut Plan, rendered: Result<String, String>) {
        let inventory = rendered.and_then(|rendered| {
            Inventory::from_json(&rendered, crate::operation_context::now().timestamp())
        });
        match inventory {
            Ok(inventory) => {
                for run in &inventory.runs {
                    let label = serde_json::to_string(&run.label).unwrap_or_else(|_| "null".into());
                    // Only a renewed lease proves a wrapper is alive; an
                    // expired one no longer blocks, pinned or not (#663).
                    if run.state.live() {
                        plan.block(
                            "live-run",
                            format!(
                                "run {} ({label}) is {} and would be interrupted",
                                run.id,
                                run.state.as_str()
                            ),
                            true,
                        );
                    } else if run.state == RunState::LegacyUnpinned {
                        plan.block(
                            "unleased-run",
                            format!(
                                "run {} ({label}) is {} and has no run lease, so Router cannot tell whether it is still running",
                                run.id,
                                run.state.as_str()
                            ),
                            true,
                        );
                    }
                }
                plan.inventory = Some(inventory);
            }
            Err(error) => plan.block(
                "run-inventory-unknown",
                format!("refusing to move the listener without a run inventory: {error}"),
                false,
            ),
        }
    }

    fn print_host_plan(&self, plan: &Plan) {
        let mut report = self.status_report("host", "planned");
        report["host_router"] =
            serde_json::json!({"executable": plan.executable, "version": plan.router_version});
        report["host_process"] = plan
            .record
            .as_ref()
            .map_or(serde_json::Value::Null, |record| {
                serde_json::json!({
                    "pid": record.pid, "port": record.port, "version": record.router_version,
                    "executable": record.executable, "serving": plan.record_serving,
                })
            });
        report["converged"] = if plan.secret_unknown {
            serde_json::Value::Null
        } else {
            plan.converged.into()
        };
        report["token_secret"] = plan.secret.as_str().into();
        report["rollback_command"] = ROLLBACK_COMMAND.into();
        report["runs"] = plan
            .inventory
            .as_ref()
            .map_or(serde_json::Value::Null, |inventory| {
                serde_json::json!(inventory.runs)
            });
        report["blockers"] = serde_json::json!(
            plan.blockers
                .iter()
                .map(|blocker| super::status_report::blocker(
                    blocker.name,
                    &blocker.reason,
                    blocker.forceable
                ))
                .collect::<Vec<_>>()
        );
        report["force_update_interrupts"] =
            plan.blockers.iter().any(|blocker| blocker.forceable).into();
        println!("mode=host");
        println!("deployment_root={}", self.root.display());
        println!(
            "host_router={} version={}",
            plan.executable.display(),
            plan.router_version
        );
        println!(
            "data_dir={} preserved=token-store,signing-secret,request-logs,provider-configuration",
            self.root.join("data").display()
        );
        println!(
            "listener=127.0.0.1:{} client_profiles_unchanged=true",
            self.port
        );
        println!(
            "claude_login={} read_in_place=true oauth_bytes_copied=0",
            plan.login.as_str()
        );
        println!("token_secret={}", plan.secret.as_str());
        match &plan.from {
            Some(active) => {
                let backend_running = self.docker.running(&active.backend).unwrap_or(false);
                let relay_running = self.docker.running(&RELAY.value()).unwrap_or(false);
                let connections = self.connection_count(&active.backend).ok();
                report["backend"] = serde_json::json!({"name": active.backend, "image": active.image_ref, "running": backend_running});
                report["relay"] = serde_json::json!({"name": RELAY.value(), "port": active.port, "running": relay_running});
                report["connections"] = serde_json::json!(connections);
                println!(
                    "container_backend={} image={} running={}",
                    active.backend, active.image_ref, backend_running
                );
                println!(
                    "relay={RELAY} running={} port={}",
                    relay_running, active.port
                );
                println!(
                    "connections={}",
                    connections.map_or_else(|| "unknown".to_string(), |count| count.to_string())
                );
            }
            None => println!(
                "container_backend={}",
                plan.record
                    .as_ref()
                    .and_then(|record| record.previous_backend.as_deref())
                    .map_or_else(
                        || "absent".to_string(),
                        |backend| format!("{backend} stopped=retained-for-rollback")
                    )
            ),
        }
        if let Some(inventory) = &plan.inventory {
            inventory.print();
        }
        match &plan.record {
            Some(record) => println!(
                "host_process=pid:{} port={} version={} serving={}",
                record.pid, record.port, record.router_version, plan.record_serving
            ),
            None => println!("host_process=absent"),
        }
        for (step, action) in plan.steps(self.port).iter().enumerate() {
            println!("plan step={} {action}", step + 1);
        }
        if plan.from.is_some() {
            println!("on_failure=restart {RELAY}; the container deployment keeps serving");
        }
        println!("rollback_command=\"{ROLLBACK_COMMAND}\"");
        if let Some(line) = &plan.checkpoint {
            println!("{line}");
        }
        for blocker in &plan.blockers {
            println!(
                "blocker={} forceable={} reason={}",
                blocker.name,
                blocker.forceable,
                serde_json::to_string(&blocker.reason).unwrap_or_default()
            );
        }
        println!(
            "force_update_interrupts={}",
            plan.blockers.iter().any(|blocker| blocker.forceable)
        );
        println!("{}", plan.convergence());
        self.print_provider_exhaustion();
        println!("status_is_read_only=true");
        crate::operation_output::record(report);
    }

    /// One `provider_exhausted` line per z.ai plan the serving process saw
    /// refused as exhausted (issue #657), then one line per pooled account in
    /// a vendor cooldown or pause (issue #677); nothing when there is none.
    pub(super) fn print_provider_exhaustion(&self) {
        let data = self.root.join("data");
        print!(
            "{}{}",
            link_assistant_router::zai_upstream_error::status_report(&data),
            link_assistant_router::account_limits::status_report(&data)
        );
    }
}

