//! Moving the stable listener between the containers and the host Router.

use std::path::Path;
use std::process::ExitCode;
#[cfg(not(test))]
use std::thread;
#[cfg(not(test))]
use std::time::Duration;

use link_assistant_router::cli::DeployArgs;

use super::super::host_runtime::{HostRuntime, Launch};
use super::super::secret::{SecretMatch, fingerprint, probe_accepted};
use super::super::state::Host;
use super::super::{Coordinator, RELAY, result_code};
use super::{Plan, ROLLBACK_COMMAND};

#[cfg(not(test))]
const HOST_READY_ATTEMPTS: usize = 60;
#[cfg(test)]
const HOST_READY_ATTEMPTS: usize = 2;

impl Coordinator<'_> {
    pub(super) fn migrate_to_host(
        &self,
        plan: &Plan,
        runtime: &dyn HostRuntime,
    ) -> Result<(), String> {
        self.create_directories()?;
        let _lock = self.acquire_lock()?;
        let probe = plan.secret == SecretMatch::Matches;
        let serving = plan.from.is_some() || plan.record_serving;
        let all_records: Vec<link_assistant_router::storage::TokenRecord> = if serving {
            let rendered = if let Some(active) = &plan.from {
                self.docker.token_inventory(&active.backend)?
            } else {
                runtime.token_inventory(&plan.executable, &self.root.join("data"))?
            };
            crate::operations::decode_token_inventory(rendered.as_bytes())
                .map_err(|_| "old token inventory is invalid")?
        } else {
            let store = link_assistant_router::storage::build_token_store_read_only(
                link_assistant_router::config::StoragePolicy::Both,
                &self.root.join("data"),
            )
            .map_err(|_| "preexisting token store cannot be read")?;
            store
                .list()
                .map_err(|_| "preexisting token inventory unavailable")?
        };
        let records: Vec<_> = all_records
            .iter()
            .filter(|record| {
                link_assistant_router::deployment_preservation::usable(
                    record,
                    crate::operation_context::now().timestamp(),
                )
            })
            .cloned()
            .collect();
        if records.len() > 512 {
            return Err(
                "issued-token catalog inventory exceeds bounded verification budget".into(),
            );
        }
        let previous = if let Some(active) = &plan.from {
            self.preservation_catalogs(&active.backend, &records)?
        } else if let Some(record) = plan.record.as_ref().filter(|_| plan.record_serving) {
            host_catalogs(self, runtime, record.port, &records)?
        } else {
            Vec::new()
        };
        if let Some(active) = &plan.from {
            let source_secret = self
                .docker
                .env_value(&active.backend, "TOKEN_SECRET")
                .ok_or("previous signing-secret identity unavailable for data checkpoint")?;
            self.preservation_checkpoint_using(&all_records, &source_secret)?;
        } else {
            if plan.record_serving && plan.secret != SecretMatch::Matches {
                return Err("previous host signing-secret identity unavailable for a recoverable data checkpoint; no candidate started".into());
            }
            self.preservation_checkpoint(&all_records)?;
        }
        if serving {
            // Nothing changes until a host Router with this data and secret
            // has proven it accepts the deployment's tokens.
            let port = runtime.free_port()?;
            let log = self.state.directory().join("host-candidate.log");
            let pid = self.launch(runtime, &plan.executable, port, &log)?;
            let validated = self
                .validate_host(runtime, plan, pid, port, probe)
                .and_then(|()| {
                    let candidate = host_catalogs(self, runtime, port, &records)?;
                    link_assistant_router::deployment_preservation::compare(&previous, &candidate)
                });
            let stopped = runtime.terminate(pid);
            validated.map_err(|error| {
                format!(
                    "host candidate failed validation: {error}; nothing was changed and the current deployment keeps serving (log: {})",
                    log.display()
                )
            })?;
            stopped?;
            println!("host_candidate=validated listener=127.0.0.1:{port}");
        }
        if let Some(active) = &plan.from {
            let connections = self.connection_count(&active.backend)?;
            if connections > 0 && !self.force {
                return Err(format!(
                    "{connections} connection(s) opened during validation; nothing was changed, rerun when idle"
                ));
            }
            self.docker.stop(&RELAY.value())?;
            println!("relay={RELAY} stopped=true retained=true");
            if let Err(error) = self.start_host(plan, runtime, Some(&active.backend), probe) {
                let restored = self.docker.start(&RELAY.value()).and_then(|()| {
                    self.wait_healthy(&active.backend, &format!("http://{RELAY}:8080"))
                });
                return Err(match restored {
                    Ok(()) => format!(
                        "{error}; {RELAY} was restarted and the container deployment keeps serving"
                    ),
                    Err(restore) => format!(
                        "{error}; restarting {RELAY} also failed: {restore}. Run `{ROLLBACK_COMMAND}`"
                    ),
                });
            }
            match self.docker.stop(&active.backend) {
                Ok(()) => println!(
                    "container_backend={} stopped=true retained-for-rollback=true",
                    active.backend
                ),
                Err(error) => eprintln!(
                    "warning: {} keeps running without traffic: {error}",
                    active.backend
                ),
            }
        } else {
            let previous = plan
                .record
                .as_ref()
                .and_then(|record| record.previous_backend.clone());
            if let Some(record) = plan.record.as_ref().filter(|_| plan.record_serving) {
                runtime.terminate(record.pid)?;
            }
            self.start_host(plan, runtime, previous.as_deref(), probe)?;
        }
        println!(
            "host deployment ready on 127.0.0.1:{}; restore the containers with `{ROLLBACK_COMMAND}`",
            self.port
        );
        Ok(())
    }

    fn launch(
        &self,
        runtime: &dyn HostRuntime,
        executable: &Path,
        port: u16,
        log: &Path,
    ) -> Result<u32, String> {
        let source = self
            .state
            .active()?
            .and_then(|active| self.docker.mount_source(&active.backend, "/data/claude"))
            .map(std::path::PathBuf::from);
        // A file-backed source remains the same directory and lock owner.
        // Empty isolated sources permit the host's additional native login.
        let source = source.filter(|path| path.join(".credentials.json").is_file());
        runtime.spawn(&Launch {
            executable,
            port,
            data_dir: &self.root.join("data"),
            token_secret: self.token_secret,
            log,
            claude_home: source.as_deref(),
        })
    }

    /// Start the host Router on the stable port and record it before it is
    /// validated, so an interrupted run still knows which process to stop.
    fn start_host(
        &self,
        plan: &Plan,
        runtime: &dyn HostRuntime,
        previous_backend: Option<&str>,
        probe: bool,
    ) -> Result<(), String> {
        let log = self.state.directory().join("host.log");
        let pid = self.launch(runtime, &plan.executable, self.port, &log)?;
        self.state.write_host(&Host {
            version: 1,
            pid,
            port: self.port,
            executable: plan.executable.display().to_string(),
            router_version: plan.router_version.clone(),
            token_secret: fingerprint(self.token_secret),
            runtime_env: super::super::runtime_env::fingerprint(self.token_secret),
            previous_backend: previous_backend.map(str::to_string),
            started_at: crate::operation_context::now().timestamp(),
        })?;
        if let Err(error) = self.validate_host(runtime, plan, pid, self.port, probe) {
            let _ = runtime.terminate(pid);
            self.state.clear_host()?;
            return Err(format!(
                "host Router failed validation on 127.0.0.1:{}: {error} (log: {})",
                self.port,
                log.display()
            ));
        }
        println!("host_process=pid:{pid} listener=127.0.0.1:{}", self.port);
        Ok(())
    }

    fn validate_host(
        &self,
        runtime: &dyn HostRuntime,
        plan: &Plan,
        pid: u32,
        port: u16,
        probe: bool,
    ) -> Result<(), String> {
        let mut healthy = false;
        for _ in 0..HOST_READY_ATTEMPTS {
            if !runtime.serving(pid, &plan.executable) {
                return Err(format!("host Router process {pid} exited"));
            }
            if runtime.status(port, "/api/health", None) == Some(200) {
                healthy = true;
                break;
            }
            #[cfg(not(test))]
            thread::sleep(Duration::from_secs(1));
        }
        if !healthy {
            return Err("host Router did not become healthy".to_string());
        }
        if !probe {
            println!("token_probe=skipped reason=forced TOKEN_SECRET rotation");
            return Ok(());
        }
        let token = self.probe_token()?;
        let status = runtime
            .status(port, "/api/models", Some(&token))
            .ok_or_else(|| "token probe got no HTTP answer".to_string())?;
        if !probe_accepted(status) {
            return Err(format!(
                "it rejected a token signed with the deployment's secret (HTTP {status}); issued client tokens would stop working"
            ));
        }
        println!("token_probe=accepted status={status}");
        Ok(())
    }

    /// `--down` with a host deployment: stop the host Router, then let the
    /// container teardown continue when a container runtime exists.
    pub(super) fn host_down(
        &self,
        record: &Host,
        yes: bool,
        runtime: &dyn HostRuntime,
    ) -> Option<ExitCode> {
        if !yes {
            eprintln!("error: deploy --down stops the serving host Router; rerun with --yes");
            return Some(ExitCode::from(2));
        }
        let stopped = (|| {
            let _lock = self.acquire_lock()?;
            if runtime.serving(record.pid, Path::new(&record.executable)) {
                runtime.terminate(record.pid)?;
            }
            self.state.clear_host()?;
            println!("host_process=pid:{} stopped=true", record.pid);
            Ok(())
        })();
        if stopped.is_err() || self.docker.available().is_err() {
            return Some(result_code(stopped));
        }
        None
    }

    /// `--mode container` with a host deployment: restore the containers,
    /// then continue with the container coordinator.
    pub(super) fn leave_host(
        &self,
        args: &DeployArgs,
        record: &Host,
        runtime: &dyn HostRuntime,
    ) -> Option<ExitCode> {
        let serving = runtime.serving(record.pid, Path::new(&record.executable));
        if args.status {
            println!("mode=host requested=container");
            println!(
                "host_process=pid:{} port={} serving={serving}",
                record.pid, record.port
            );
            if let Some(backend) = &record.previous_backend {
                println!("plan step=1 action=start-backend container={backend}");
                println!("plan step=2 action=stop-host pid={}", record.pid);
                println!("plan step=3 action=start-relay container={RELAY}");
                println!("on_failure=restart the host Router; it keeps serving");
            } else {
                println!("plan step=1 action=stop-host pid={}", record.pid);
                println!("plan step=2 action=deploy-containers");
            }
            println!("status_is_read_only=true");
            return Some(ExitCode::SUCCESS);
        }
        if let Err(error) = self.docker.available() {
            eprintln!("error: container runtime unavailable: {error}");
            return Some(ExitCode::from(1));
        }
        match self.restore_containers(record, runtime, serving) {
            Ok(()) => None,
            Err(error) => Some(result_code(Err(error))),
        }
    }

    fn restore_containers(
        &self,
        record: &Host,
        runtime: &dyn HostRuntime,
        serving: bool,
    ) -> Result<(), String> {
        let _lock = self.acquire_lock()?;
        let Some(backend) = &record.previous_backend else {
            if serving && !self.accept_access_loss {
                return Err("host deployment has no retained container candidate; refusing to stop it without an access-preserving candidate".into());
            }
            if serving {
                println!(
                    "{}",
                    serde_json::json!({"schema":"link-assistant-router/preservation/v1","status":"loss-accepted","reason":"host credential-store access cannot be proven in a new container","data_restore_proven":false})
                );
                runtime.terminate(record.pid)?;
            }
            return self.state.clear_host();
        };
        let records = if serving {
            let rendered =
                runtime.token_inventory(Path::new(&record.executable), &self.root.join("data"))?;
            crate::operations::decode_token_inventory(rendered.as_bytes())
                .map_err(|_| "host token inventory is invalid")?
                .into_iter()
                .filter(|record| {
                    link_assistant_router::deployment_preservation::usable(
                        record,
                        crate::operation_context::now().timestamp(),
                    )
                })
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        if records.len() > 512 {
            return Err(
                "issued-token catalog inventory exceeds bounded verification budget".into(),
            );
        }
        let previous = host_catalogs(self, runtime, record.port, &records)?;
        self.docker.start(backend)?;
        self.wait_healthy(backend, "http://127.0.0.1:8080")?;
        let candidate = self.preservation_catalogs(backend, &records)?;
        link_assistant_router::deployment_preservation::compare(&previous, &candidate).map_err(
            |error| {
                format!("container rollback candidate loses access: {error}; host remains serving")
            },
        )?;
        if serving {
            runtime.terminate(record.pid)?;
        }
        let relayed = self
            .docker
            .start(&RELAY.value())
            .and_then(|()| self.wait_healthy(backend, &format!("http://{RELAY}:8080")));
        if let Err(error) = relayed {
            let _ = self.docker.stop(&RELAY.value());
            if serving {
                self.respawn(record, runtime)?;
            }
            return Err(format!(
                "{RELAY} did not become healthy: {error}; the host Router keeps serving"
            ));
        }
        self.state.clear_host()?;
        println!("host_process=pid:{} stopped=true", record.pid);
        println!("container deployment restored: {RELAY} -> {backend}");
        Ok(())
    }

    fn respawn(&self, record: &Host, runtime: &dyn HostRuntime) -> Result<(), String> {
        let log = self.state.directory().join("host.log");
        let pid = self.launch(runtime, Path::new(&record.executable), record.port, &log)?;
        self.state.write_host(&Host {
            pid,
            started_at: crate::operation_context::now().timestamp(),
            runtime_env: super::super::runtime_env::fingerprint(self.token_secret),
            ..record.clone()
        })
    }
}

fn host_catalogs(
    coordinator: &Coordinator<'_>,
    runtime: &dyn HostRuntime,
    port: u16,
    records: &[link_assistant_router::storage::TokenRecord],
) -> Result<Vec<link_assistant_router::deployment_preservation::Catalog>, String> {
    records
        .iter()
        .map(|record| {
            let token = link_assistant_router::deployment_preservation::probe_token(
                record,
                coordinator.token_secret,
            )?;
            let models = runtime.catalog(port, &token)?;
            Ok(link_assistant_router::deployment_preservation::Catalog {
                token_id: record.id.clone(),
                client_kind: record.client_kind.clone().expect("usable binding"),
                models,
            })
        })
        .collect()
}

//! The host process behind `router deploy --mode host` (issue #626).
//!
//! Separated behind [`HostRuntime`] so the migration, its refusals and its
//! rollback are tested without starting processes or reading a Keychain.

use std::io::{Read as _, Write as _};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::Mutex;
use std::time::{Duration, Instant};

/// How a host Router process is started.
pub(super) struct Launch<'a> {
    pub executable: &'a Path,
    pub port: u16,
    pub data_dir: &'a Path,
    /// Passed through the environment only, never argv.
    pub token_secret: &'a str,
    pub log: &'a Path,
    /// Original file credential source, when a container used a live file.
    pub claude_home: Option<&'a Path>,
}

/// Where the host login lives; presence only, never its bytes.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum ClaudeLogin {
    Keychain,
    File,
    Absent,
}

impl ClaudeLogin {
    pub(super) const fn as_str(self) -> &'static str {
        match self {
            Self::Keychain => "keychain",
            Self::File => "file",
            Self::Absent => "absent",
        }
    }
}

pub(super) trait HostRuntime {
    /// The explicitly selected Router daemon binary.
    fn executable(&self) -> Result<PathBuf, String>;
    fn version(&self, executable: &Path) -> Result<String, String>;
    fn spawn(&self, launch: &Launch<'_>) -> Result<u32, String>;
    /// Whether `pid` is still a `serve` process of `executable`, so a reused
    /// pid is never mistaken for the deployment or signalled.
    fn serving(&self, pid: u32, executable: &Path) -> bool;
    fn terminate(&self, pid: u32) -> Result<(), String>;
    /// The HTTP status of `GET path` on the loopback `port`, if it answers.
    fn status(&self, port: u16, path: &str, bearer: Option<&str>) -> Option<u16>;
    fn free_port(&self) -> Result<u16, String>;
    fn user_id(&self) -> Option<u32>;
    fn claude_login(&self) -> ClaudeLogin;
    /// `router tokens list --json` over the host's view of the data.
    fn token_inventory(&self, executable: &Path, data_dir: &Path) -> Result<String, String>;
    /// Read a bound token's model set without issuing tokens or copying OAuth.
    fn catalog(
        &self,
        port: u16,
        bearer: &str,
    ) -> Result<std::collections::BTreeSet<String>, String> {
        // `router deploy` runs inside the `#[tokio::main]` runtime, where
        // building and blocking on a second runtime panics (issue #662). The
        // probe gets a thread of its own, so it works from both contexts.
        std::thread::scope(|scope| {
            scope
                .spawn(|| catalog_on_own_runtime(port, bearer))
                .join()
                .unwrap_or_else(|_| Err("catalog probe failed".into()))
        })
    }
}

/// The body of [`HostRuntime::catalog`], on a thread with no runtime.
fn catalog_on_own_runtime(
    port: u16,
    bearer: &str,
) -> Result<std::collections::BTreeSet<String>, String> {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .map_err(|_| "catalog runtime unavailable")?;
    runtime.block_on(async {
        let client = reqwest::Client::builder()
            .no_proxy()
            .timeout(Duration::from_secs(10))
            .build()
            .map_err(|_| "catalog client unavailable")?;
        let response = client
            .get(format!("http://127.0.0.1:{port}/api/models"))
            .bearer_auth(bearer)
            .send()
            .await
            .map_err(|_| "issued-token catalog request failed")?;
        if !response.status().is_success() {
            return Err("issued-token catalog was rejected".into());
        }
        let body: serde_json::Value = response.json().await.map_err(|_| "catalog JSON invalid")?;
        let rows = body["data"].as_array().ok_or("catalog models absent")?;
        rows.iter()
            .map(|row| {
                let id = row["id"].as_str().ok_or("catalog model ID absent")?;
                Ok(format!(
                    "{}/{id}",
                    row["owned_by"].as_str().unwrap_or_default()
                ))
            })
            .collect()
    })
}

/// The real host: processes, loopback HTTP and the platform secret store.
pub(super) struct System {
    /// Children started by this run, reaped on termination so a stopped
    /// candidate does not linger as a zombie that still answers `kill -0`.
    children: Mutex<Vec<(Child, bool)>>,
    keychain_presence: fn(&str) -> bool,
}

impl Default for System {
    fn default() -> Self {
        Self {
            children: Mutex::default(),
            keychain_presence: link_assistant_router::platform_keychain::has_entry,
        }
    }
}

impl HostRuntime for System {
    fn executable(&self) -> Result<PathBuf, String> {
        let selected = crate::operation_context::current()
            .and_then(|context| context.daemon_executable)
            .or_else(|| crate::operation_context::var_os("ROUTER_BIN").map(PathBuf::from))
            // Validate the CLI contract below, rather than assuming a filename:
            // installed Router binaries can be renamed by their users.
            .or_else(|| std::env::current_exe().ok())
            .ok_or("host deployment requires OperationContext.daemon_executable or ROUTER_BIN pointing to a Router CLI binary")?;
        let selected = if selected.is_absolute() {
            selected
        } else {
            crate::operation_context::current().map_or_else(
                || selected.clone(),
                |context| context.working_directory.join(&selected),
            )
        };
        selected
            .canonicalize()
            .map_err(|error| format!("could not resolve the Router executable: {error}"))
    }

    fn version(&self, executable: &Path) -> Result<String, String> {
        let output = crate::operation_context::process_output(
            crate::operation_context::command(executable).arg("--version"),
        )
        .map_err(|error| format!("could not validate Router executable: {error}"))?;
        let text = String::from_utf8_lossy(&output.stdout);
        let mut words = text.split_whitespace();
        let name = words.next();
        let version = words.next().unwrap_or_default();
        let core = version.split(['-', '+']).next().unwrap_or_default();
        let components: Vec<_> = core.split('.').collect();
        if !output.status.success()
            || !matches!(name, Some("router" | "link-assistant-router"))
            || words.next().is_some()
            || components.len() != 3
            || components.iter().any(|part| part.parse::<u64>().is_err())
        {
            return Err(
                "selected daemon executable is not a Router CLI (`--version` validation failed); set OperationContext.daemon_executable or ROUTER_BIN"
                    .into(),
            );
        }
        Ok(version.to_owned())
    }

    fn spawn(&self, launch: &Launch<'_>) -> Result<u32, String> {
        let log = open_log(launch.log)?;
        let error_log = log
            .try_clone()
            .map_err(|error| format!("could not open {}: {error}", launch.log.display()))?;
        let mut command = crate::operation_context::command(launch.executable);
        command
            .arg("serve")
            .current_dir(launch.data_dir)
            .env("ROUTER_HOST", "127.0.0.1")
            .env("ROUTER_PORT", launch.port.to_string())
            .env("DATA_DIR", launch.data_dir)
            .env("STORAGE_POLICY", "text")
            .env("TOKEN_SECRET", launch.token_secret)
            // One loopback listener, exactly where the relay published.
            .env_remove("LISTENERS")
            .stdin(Stdio::null())
            .stdout(log)
            .stderr(error_log);
        // The deployed server inherits this shell. An emergency any-token
        // switch exported for a local incident must not ride along into a
        // deployment (issue #645): it is enabled only by an explicit flag.
        for name in link_assistant_router::emergency_auth::ENV_VARS {
            command.env_remove(name);
        }
        // `--env` passthrough (issue #679); reserved names are refused earlier.
        for (name, value) in &super::runtime_env::current().env {
            command.env(name, value);
        }
        if let Some(home) = launch.claude_home {
            command
                .env("CLAUDE_CODE_HOME", home)
                .env("CLAUDE_CONFIG_DIR", home);
        }
        detach(&mut command);
        let child = crate::operation_context::spawn_process(&mut command).map_err(|error| {
            format!(
                "could not start {} serve: {error}",
                launch.executable.display()
            )
        })?;
        let pid = child.id();
        self.children
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .push((child, false));
        Ok(pid)
    }

    fn serving(&self, pid: u32, executable: &Path) -> bool {
        if self.exited(pid) {
            return false;
        }
        crate::operation_context::process_output(crate::operation_context::command("ps").args([
            "-p",
            &pid.to_string(),
            "-o",
            "command=",
        ]))
        .is_ok_and(|output| {
            let command = String::from_utf8_lossy(&output.stdout);
            output.status.success()
                && command.contains(&executable.display().to_string())
                && command.split_whitespace().any(|word| word == "serve")
        })
    }

    fn terminate(&self, pid: u32) -> Result<(), String> {
        signal("TERM", pid);
        let deadline = Instant::now() + Duration::from_secs(15);
        while Instant::now() < deadline {
            if self.exited(pid) || !alive(pid) {
                return Ok(());
            }
            std::thread::sleep(Duration::from_millis(100));
        }
        signal("KILL", pid);
        std::thread::sleep(Duration::from_millis(200));
        if self.exited(pid) || !alive(pid) {
            Ok(())
        } else {
            Err(format!("host Router process {pid} did not stop"))
        }
    }

    fn status(&self, port: u16, path: &str, bearer: Option<&str>) -> Option<u16> {
        let mut stream = std::net::TcpStream::connect(("127.0.0.1", port)).ok()?;
        stream
            .set_read_timeout(Some(Duration::from_secs(10)))
            .ok()?;
        stream
            .set_write_timeout(Some(Duration::from_secs(5)))
            .ok()?;
        let authorization = bearer.map_or_else(String::new, |token| {
            format!("Authorization: Bearer {token}\r\n")
        });
        write!(
            stream,
            "GET {path} HTTP/1.1\r\nHost: localhost\r\n{authorization}Connection: close\r\n\r\n"
        )
        .ok()?;
        let mut head = [0_u8; 64];
        let read = stream.read(&mut head).ok()?;
        String::from_utf8_lossy(&head[..read])
            .split_whitespace()
            .nth(1)?
            .parse()
            .ok()
    }

    fn free_port(&self) -> Result<u16, String> {
        std::net::TcpListener::bind(("127.0.0.1", 0))
            .and_then(|listener| listener.local_addr())
            .map(|address| address.port())
            .map_err(|error| format!("no free loopback port for the host candidate: {error}"))
    }

    fn user_id(&self) -> Option<u32> {
        let output = crate::operation_context::process_output(
            crate::operation_context::command("id").arg("-u"),
        )
        .ok()?;
        String::from_utf8_lossy(&output.stdout).trim().parse().ok()
    }

    fn claude_login(&self) -> ClaudeLogin {
        claude_login_in(
            crate::operation_context::var_os("CLAUDE_CONFIG_DIR"),
            crate::operation_context::var_os("HOME"),
            self.keychain_presence,
        )
    }

    fn token_inventory(&self, executable: &Path, data_dir: &Path) -> Result<String, String> {
        let output = crate::operation_context::process_output(
            crate::operation_context::command(executable)
                .args(["tokens", "list", "--json"])
                .env("DATA_DIR", data_dir)
                .env("STORAGE_POLICY", "text")
                .stdin(Stdio::null()),
        )
        .map_err(|error| format!("could not list tokens: {error}"))?;
        if !output.status.success() {
            return Err(format!(
                "`router tokens list` failed: {}",
                String::from_utf8_lossy(&output.stderr).trim()
            ));
        }
        Ok(String::from_utf8_lossy(&output.stdout).into_owned())
    }
}

/// Classify the selected login without retrieving any credential bytes.
fn claude_login_in(
    config_dir: Option<std::ffi::OsString>,
    user_home: Option<std::ffi::OsString>,
    has_entry: impl FnOnce(&str) -> bool,
) -> ClaudeLogin {
    use link_assistant_router::{env_paths::from_value, platform_keychain::claude_service_for};
    let service = claude_service_for(config_dir.as_deref());
    let home =
        from_value(config_dir).or_else(|| from_value(user_home).map(|home| home.join(".claude")));
    if has_entry(&service) {
        ClaudeLogin::Keychain
    } else if home.is_some_and(|home| home.join(".credentials.json").is_file()) {
        ClaudeLogin::File
    } else {
        ClaudeLogin::Absent
    }
}

#[cfg(test)]
#[path = "host_login_tests.rs"]
mod login_tests;

impl System {
    /// Fixture host processes never consult the workstation's Keychain.
    #[cfg(test)]
    pub(super) fn fixture() -> Self {
        Self {
            keychain_presence: |_| false,
            ..Self::default()
        }
    }
    /// Whether a child this run started has exited, reaping it if so.
    fn exited(&self, pid: u32) -> bool {
        let mut children = self
            .children
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        children
            .iter_mut()
            .find(|(child, _)| child.id() == pid)
            .is_some_and(|(child, recorded)| {
                if let Ok(Some(status)) = child.try_wait() {
                    if !*recorded {
                        crate::logging::child_exit("host_router", Some(pid), status);
                        *recorded = true;
                    }
                    true
                } else {
                    false
                }
            })
    }
}

fn open_log(path: &Path) -> Result<std::fs::File, String> {
    let mut options = std::fs::OpenOptions::new();
    options.create(true).append(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let mut file = options
        .open(path)
        .map_err(|error| format!("could not open {}: {error}", path.display()))?;
    let _ = writeln!(
        file,
        "--- router deploy --mode host {}",
        crate::operation_context::now().to_rfc3339()
    );
    Ok(file)
}

/// Its own process group: closing the terminal that ran `router deploy`
/// signals that terminal's jobs, not the deployment.
#[cfg(unix)]
fn detach(command: &mut Command) {
    use std::os::unix::process::CommandExt as _;
    command.process_group(0);
}

#[cfg(not(unix))]
const fn detach(_command: &mut Command) {}

fn signal(name: &str, pid: u32) {
    #[cfg(unix)]
    let _ = crate::operation_context::process_output(
        crate::operation_context::command("kill")
            .args([&format!("-{name}"), &pid.to_string()])
            .stdout(Stdio::null())
            .stderr(Stdio::null()),
    )
    .map(|output| output.status);
    #[cfg(windows)]
    let _ = (
        name,
        crate::operation_context::process_output(
            crate::operation_context::command("taskkill").args(["/PID", &pid.to_string(), "/F"]),
        )
        .map(|output| output.status),
    );
}

fn alive(pid: u32) -> bool {
    // A stopped process whose parent (not this command, which may have
    // exited long ago) has not reaped it yet is a zombie: `kill -0` still
    // succeeds for it, `ps` reports state `Z`.
    #[cfg(unix)]
    {
        crate::operation_context::process_output(crate::operation_context::command("ps").args([
            "-p",
            &pid.to_string(),
            "-o",
            "stat=",
        ]))
        .is_ok_and(|output| {
            let state = String::from_utf8_lossy(&output.stdout);
            let state = state.trim();
            output.status.success() && !state.is_empty() && !state.starts_with('Z')
        })
    }
    #[cfg(windows)]
    {
        crate::operation_context::process_output(
            &mut crate::operation_context::command("tasklist").args([
                "/FI",
                &format!("PID eq {pid}"),
                "/NH",
            ]),
        )
        .is_ok_and(|output| String::from_utf8_lossy(&output.stdout).contains(&pid.to_string()))
    }
}

