//! A deployment lifecycle lock owned by the operation's scope.

pub(super) struct OperationLock(pub(super) std::fs::File);

impl Drop for OperationLock {
    fn drop(&mut self) {
        // Closing one descriptor does not release a Unix lock while an
        // unrelated child still has a copy between fork and exec. Release
        // ownership explicitly when the operation and its awaited work end.
        let _ = self.0.unlock();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn inherited_descriptors_do_not_keep_a_finished_operation_locked() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("operation.lock");
        let open = || {
            std::fs::OpenOptions::new()
                .create(true)
                .truncate(false)
                .read(true)
                .write(true)
                .open(&path)
                .unwrap()
        };
        let file = open();
        file.try_lock().unwrap();
        let operation = OperationLock(file);
        // A duplicated descriptor shares the lock, just as one inherited by
        // an unrelated child between fork and exec does on Unix.
        let inherited = operation.0.try_clone().unwrap();
        let next = open();
        assert!(
            next.try_lock().is_err(),
            "the active operation owns its lock"
        );
        drop(operation);
        next.try_lock()
            .expect("finishing the operation releases its lock even while a descriptor survives");
        next.unlock().unwrap();
        drop(inherited);
    }
}

//! Issued-token catalog and credential-source continuity before local cutover.

use std::path::Path;

use link_assistant_router::deployment_preservation::{Catalog, compare, probe_token, usable};
use link_assistant_router::storage::TokenRecord;
use serde_json::json;

use super::claude_share::Provision;
use super::{Coordinator, Existing, LEGACY};

const CATALOG_ENV: &crate::translation_core::Str = "ROUTER_PRESERVATION_TOKEN";
const CATALOG_SCRIPT: &crate::translation_core::Str = "const r=await fetch('http://127.0.0.1:8080/api/models',{signal:AbortSignal.timeout(5000),headers:{authorization:'Bearer '+process.env.ROUTER_PRESERVATION_TOKEN}});if(r.status!==200)process.exit(2);const b=await r.json();if(!Array.isArray(b.data))process.exit(3);console.log(JSON.stringify(b.data.map(m=>String(m.owned_by||'')+'/'+m.id).sort()))";

pub(super) struct Baseline {
    pub records: Vec<TokenRecord>,
    pub catalogs: Vec<Catalog>,
}

fn same_directory(actual: &crate::translation_core::Str, expected: &Path) -> bool {
    let actual = Path::new(actual);
    match (actual.canonicalize(), expected.canonicalize()) {
        (Ok(actual), Ok(expected)) => actual == expected,
        _ => actual == expected,
    }
}

impl Coordinator<'_> {
    fn preservation_failure(&self, reason: &str) -> Result<(), String> {
        println!(
            "{}",
            json!({"schema":"link-assistant-router/preservation/v1","status":if self.accept_access_loss {"loss-accepted"} else {"refused"},"reason":reason,"access_loss_explicitly_accepted":self.accept_access_loss,"credentials_copied":false,"data_restore_proven":false})
        );
        if self.accept_access_loss {
            Ok(())
        } else {
            Err(format!(
                "{reason}; use --accept-access-loss only to authorize this reported loss"
            ))
        }
    }

    pub(super) fn preservation_baseline(&self, existing: &Existing) -> Result<Baseline, String> {
        let backend = match existing {
            Existing::Absent => {
                let data = self.root.join("data");
                if std::fs::read_dir(&data).is_ok_and(|mut entries| entries.next().is_some()) {
                    let store = link_assistant_router::storage::build_token_store_read_only(
                        link_assistant_router::config::StoragePolicy::Both,
                        &data,
                    )
                    .map_err(|_| "preexisting token store cannot be read")?;
                    let records = store
                        .list()
                        .map_err(|_| "preexisting token inventory unavailable")?;
                    self.preservation_checkpoint(&records)?;
                }
                return Ok(Baseline {
                    records: Vec::new(),
                    catalogs: Vec::new(),
                });
            }
            Existing::Legacy => LEGACY,
            Existing::Managed(active) => &active.backend,
        };
        // These source paths select the live refresh owner, not credential bytes.
        let expected = match &self.claude {
            Provision::Shared { home, .. } => home.clone(),
            Provision::Isolated => self.root.join("credentials"),
            Provision::Refused(reason) => return Err(reason.clone()),
        };
        for (destination, expected) in [
            ("/data/router", self.root.join("data")),
            ("/data/claude", expected),
        ] {
            let actual = self.docker.mount_source(backend, destination);
            // An empty isolated credential directory has no connection to
            // lose; selecting a live source is an additive change.
            let adding_source = destination == "/data/claude"
                && actual.as_deref().is_some_and(|source| {
                    std::fs::read_dir(source).is_ok_and(|mut entries| entries.next().is_none())
                });
            if !adding_source && !actual.is_some_and(|actual| same_directory(&actual, &expected)) {
                self.preservation_failure(&format!("credential/data source differs or is unavailable at {destination}; preserving bytes elsewhere does not preserve the source connection"))?;
            }
        }
        let all_records: Vec<TokenRecord> = crate::operations::decode_token_inventory(
            self.docker.token_inventory(backend)?.as_bytes(),
        )
        .map_err(|_| "previous issued-token inventory is invalid")?;
        let records: Vec<_> = all_records
            .iter()
            .filter(|record| usable(record, crate::operation_context::now().timestamp()))
            .cloned()
            .collect();
        if records.len() > 512 {
            return Err(
                "issued-token catalog inventory exceeds the bounded 512-token verification budget"
                    .into(),
            );
        }
        let catalogs = match self.preservation_catalogs(backend, &records) {
            Ok(catalogs) => catalogs,
            Err(reason) => {
                self.preservation_failure(&reason)?;
                Vec::new()
            }
        };
        let source_secret = self.docker.env_value(backend, "TOKEN_SECRET")
            .ok_or("previous signing-secret identity unavailable for data checkpoint; no candidate started")?;
        let checkpoint = self.preservation_checkpoint_using(&all_records, &source_secret)?;
        println!(
            "{}",
            json!({"schema":"link-assistant-router/preservation/v1","status":"baseline","catalogs":catalogs,"checkpoint":checkpoint,"checkpoint_scope":"logical token state, encrypted static provider configuration and registered project/session files (request logs stay in place); individual-file/export boundaries","credential_source":"shared-original-directory","credentials_copied":false,"profiles_projects_sessions":"external client homes remain outside deployment mutation scope","rollback_scope":"previous backend and relay; offline additive/replacement checkpoint restore; OAuth is never replayed"})
        );
        Ok(Baseline { records, catalogs })
    }

    pub(super) fn preservation_checkpoint(
        &self,
        records: &[TokenRecord],
    ) -> Result<Option<std::path::PathBuf>, String> {
        self.preservation_checkpoint_using(records, self.token_secret)
    }

    pub(super) fn preservation_checkpoint_using(
        &self,
        records: &[TokenRecord],
        source_secret: &str,
    ) -> Result<Option<std::path::PathBuf>, String> {
        match super::data_backup::capture(self.root, records, source_secret) {
            Ok(path) => {
                println!(
                    "{}",
                    json!({"schema":"link-assistant-router/preservation/v1","status":"data-checkpoint","checkpoint":path,"oauth_copied":false,"global_atomic_snapshot":false})
                );
                Ok(Some(path))
            }
            Err(error) => {
                // Keep the cause: an operator cannot act on "failed" (issue #658).
                let reason = super::data_backup::checkpoint_remedy(&error);
                println!(
                    "{}",
                    json!({"schema":"link-assistant-router/preservation/v1","status":"refused","blocker":"data-checkpoint","reason":format!("{reason}; no candidate started"),"oauth_copied":false})
                );
                Err(format!(
                    "{reason}; provider access-loss permission does not authorize losing state"
                ))
            }
        }
    }

    pub(super) fn preservation_catalogs(
        &self,
        backend: &str,
        records: &[TokenRecord],
    ) -> Result<Vec<Catalog>, String> {
        records
            .iter()
            .map(|record| {
                let token = probe_token(record, self.token_secret)?;
                let rendered = self
                    .docker
                    .exec_with_env(
                        backend,
                        &[(CATALOG_ENV, &token)],
                        &["bun", "-e", CATALOG_SCRIPT],
                    )
                    .map_err(|_| {
                        format!("token-authorized catalog unavailable for {}", record.id)
                    })?;
                let models = serde_json::from_str(&rendered)
                    .map_err(|_| "token-authorized catalog response is invalid")?;
                Ok(Catalog {
                    token_id: record.id.clone(),
                    client_kind: record.client_kind.clone().expect("usable binding"),
                    models,
                })
            })
            .collect()
    }

    pub(super) fn preservation_candidate(
        &self,
        candidate: &str,
        baseline: &Baseline,
    ) -> Result<(), String> {
        let result = self
            .preservation_catalogs(candidate, &baseline.records)
            .and_then(|catalogs| compare(&baseline.catalogs, &catalogs));
        let preserved = result.is_ok();
        if let Err(reason) = result {
            self.preservation_failure(&reason)?;
        }
        println!(
            "{}",
            json!({"schema":"link-assistant-router/preservation/v1","status":if preserved {"candidate-checked"} else {"loss-accepted"},"issued_bound_tokens":baseline.records.len(),"credentials_copied":false,"catalog_comparison":if preserved {"per-token subset"} else {"failed"},"data_restore_proven":false})
        );
        Ok(())
    }
}

//! Keep the front-door relay on the deployed Router image (issue #627).
//!
//! The relay runs the same image as the backend, so a backend update that
//! kept the old relay left relay protocol and security fixes behind while
//! status called the deployment converged. Docker cannot hand a published
//! port from one container to another, so the relay is rotated only when it
//! carries no established connection: waiting preserves every stream, and
//! exactly one relay ever publishes the listener. A connection attempted in
//! the sub-second gap between removal and the new relay's listener is refused
//! and retried by the client; it never reaches a second endpoint.

use super::state::Active;
use super::{Coordinator, RELAY};

#[cfg(not(test))]
const RELAY_IDLE_ATTEMPTS: usize = 120;
#[cfg(test)]
const RELAY_IDLE_ATTEMPTS: usize = 3;

#[derive(Debug, Eq, PartialEq)]
pub(super) enum Rotation {
    /// The relay already runs the active backend's image.
    Current,
    Rotated,
    /// Clients kept connections open for the whole idle window.
    Deferred {
        connections: u64,
    },
}

impl Coordinator<'_> {
    /// The relay's image reference when it runs other code than the active
    /// backend. Image ids decide: a second tag of the same image is not skew.
    pub(super) fn relay_skew(&self, active: &Active) -> Result<Option<String>, String> {
        if !self.docker.exists(&RELAY.value()) {
            return Ok(None);
        }
        let relay_id = self.docker.container_image_id(&RELAY.value())?;
        if relay_id == active.image_id {
            return Ok(None);
        }
        self.docker.image_ref(&RELAY.value()).map(Some)
    }

    /// Print both versions so mixed images are never reported as converged.
    pub(super) fn print_versions(&self, active: &Active) -> Result<bool, String> {
        println!(
            "backend_image={} image_id={}",
            active.image_ref, active.image_id
        );
        if self.docker.exists(&RELAY.value()) {
            println!(
                "relay_image={} image_id={}",
                self.docker.image_ref(&RELAY.value())?,
                self.docker.container_image_id(&RELAY.value())?
            );
        } else {
            println!("relay_image=absent");
        }
        let skew = self.relay_skew(active)?.is_some();
        println!("version_skew={skew}");
        Ok(!skew)
    }

    /// Wait for two consecutive zero observations, like a backend drain,
    /// but bounded: an always-busy relay defers instead of hanging.
    fn relay_idle(&self, backend: &str) -> Result<Result<(), u64>, String> {
        let mut zero_observations = 0_u8;
        let mut last = 0;
        for _ in 0..RELAY_IDLE_ATTEMPTS {
            last = self.connection_count(backend)?;
            if last == 0 {
                zero_observations = zero_observations.saturating_add(1);
                if zero_observations == 2 {
                    return Ok(Ok(()));
                }
            } else {
                zero_observations = 0;
            }
            #[cfg(not(test))]
            std::thread::sleep(std::time::Duration::from_secs(1));
        }
        Ok(Err(last))
    }

    /// Replace the relay with one on the active image once it is idle. A
    /// failed replacement restores the previous relay image.
    pub(super) fn rotate_relay(&self, active: &Active) -> Result<Rotation, String> {
        let Some(previous) = self.relay_skew(active)? else {
            return Ok(Rotation::Current);
        };
        if !self.docker.owned(&RELAY.value(), self.root, "relay") {
            return Err(format!("refusing to rotate unowned relay {RELAY}"));
        }
        println!(
            "relay_rotation=pending relay_image={previous} backend_image={}",
            active.image_ref
        );
        if let Err(connections) = self.relay_idle(&active.backend)? {
            if !self.force {
                println!(
                    "relay_rotation=deferred connections={connections} reason=established connections were never idle"
                );
                return Ok(Rotation::Deferred { connections });
            }
            println!("force_update accepted relay_rotation connections={connections}");
        }
        self.remove_relay()?;
        let origin = format!("http://{RELAY}:8080");
        let replaced = self
            .docker
            .run_relay(&active.image_ref, self.root, active.port)
            .and_then(|()| self.wait_healthy(&active.backend, &origin));
        if let Err(error) = replaced {
            self.remove_relay()?;
            self.docker.run_relay(&previous, self.root, active.port)?;
            self.wait_healthy(&active.backend, &origin)?;
            return Err(format!(
                "relay rotation failed and relay image {previous} was restored: {error}"
            ));
        }
        println!("relay_rotation=complete relay_image={}", active.image_ref);
        Ok(Rotation::Rotated)
    }

    /// Converge the relay after a backend change or on a no-op run.
    pub(super) fn converge_relay(&self, active: &Active) -> Result<Rotation, String> {
        let rotation = self.rotate_relay(active)?;
        if let Rotation::Deferred { connections } = rotation {
            return Err(format!(
                "{RELAY} still runs an older image because {connections} established connection(s) never became idle; rerun `router deploy` when clients are idle, or pass --force-update to interrupt them"
            ));
        }
        Ok(rotation)
    }
}

//! Runtime environment and token policy for local deployments (issue #679).
//!
//! `router deploy --env NAME` passes a variable to the backend by name: the
//! value travels in the `docker run` (or host process) environment, never in
//! argv, and an HMAC fingerprint of every name and value becomes part of the
//! launch specification, so a changed value reconciles the deployment the
//! way a changed image does. Without `--env` the specification is exactly
//! what it was before passthrough existed.
//!
//! Library settings belong to the operation context. Native CLI settings are
//! selected once by `deploy_cli`, before the coordinator runs.

use std::sync::OnceLock;

use link_assistant_router::deploy_config::{TokenPolicy, env_fingerprint};

use super::LABEL_KEY;

/// The backend label holding the runtime environment fingerprint.
pub(super) const LABEL_SUFFIX: &str = "runtime-env";

/// Local settings from `--config` and the deploy flags.
#[derive(Clone, Debug, Default)]
pub struct LocalSettings {
    /// Runtime variables, sorted by name. Values are never printed.
    pub env: Vec<(String, String)>,
    /// Limits for the client token deploy issues.
    pub tokens: TokenPolicy,
}

static SETTINGS: OnceLock<LocalSettings> = OnceLock::new();

/// Choose this process's local settings. Later calls are ignored.
pub fn configure(settings: LocalSettings) {
    if let Some(context) = crate::operation_context::current() {
        *context
            .deployment_settings
            .lock()
            .expect("deployment settings lock") = settings;
    } else {
        let _ = SETTINGS.set(settings);
    }
}

pub(super) fn current() -> LocalSettings {
    crate::operation_context::current().map_or_else(
        || SETTINGS.get().cloned().unwrap_or_default(),
        |context| {
            context
                .deployment_settings
                .lock()
                .expect("deployment settings lock")
                .clone()
        },
    )
}

/// The fingerprint a backend launched now would carry, if any.
pub(super) fn fingerprint(token_secret: &str) -> Option<String> {
    env_fingerprint(token_secret, &current().env)
}

/// Insert `-e NAME` for every variable and the fingerprint label before the
/// image reference (the last two `docker run` arguments: image and `serve`).
pub(super) fn insert(arguments: &mut Vec<String>, settings: &LocalSettings, token_secret: &str) {
    let mut extra = Vec::new();
    for (name, _) in &settings.env {
        extra.extend(["-e".to_string(), name.clone()]);
    }
    if let Some(fingerprint) = env_fingerprint(token_secret, &settings.env) {
        extra.extend([
            "--label".to_string(),
            format!("{LABEL_KEY}.{LABEL_SUFFIX}={fingerprint}"),
        ]);
    }
    let at = arguments.len().saturating_sub(2);
    arguments.splice(at..at, extra);
}

/// Name/value pairs for the `docker run` process environment.
pub(super) fn environment<'a>(
    settings: &'a LocalSettings,
    token_secret: &'a str,
) -> Vec<(&'a str, &'a str)> {
    let mut environment = vec![("TOKEN_SECRET", token_secret)];
    environment.extend(
        settings
            .env
            .iter()
            .map(|(name, value)| (name.as_str(), value.as_str())),
    );
    environment
}

/// Whether a running backend was launched with the current environment.
///
/// A backend without the label and a run without `--env` agree, so a
/// deployment that never used passthrough still converges as before.
pub(super) fn matches(label: Option<&str>, token_secret: &str) -> bool {
    label == fingerprint(token_secret).as_deref()
}

#[cfg(test)]
mod tests {
