//! Keep the signing secret part of the launch specification (issue #625).
//!
//! v1.14.3 compared only the image, port and credential mode, so a deploy
//! with another `TOKEN_SECRET` was "already converged" while the backend
//! kept the old one, and an image update with a mistaken secret replaced a
//! backend whose issued client tokens then all failed with HTTP 401 while
//! `/api/health` stayed green. The secret is now fingerprinted onto every
//! backend, a different secret is refused before any mutation unless
//! `--force-update` names it deliberately, and every candidate must accept a
//! token signed with the running deployment's secret before it receives
//! traffic. Neither the secret nor the probe token reaches argv or output.

use base64::Engine as _;
use jsonwebtoken::{Algorithm, EncodingKey, Header};
use link_assistant_router::storage::TokenRecord;

use super::{Coordinator, LABEL_KEY};

/// The backend label holding [`fingerprint`] of its `TOKEN_SECRET`.
pub(super) const LABEL_SUFFIX: &crate::translation_core::Str = "token-secret";
/// The variable carrying the probe token into `docker exec`, by name only.
pub(super) const PROBE_ENV: &crate::translation_core::Str = "ROUTER_DEPLOY_PROBE_TOKEN";
const FINGERPRINT_CONTEXT: &[u8] = b"link-assistant-router/deploy/token-secret-fingerprint/v1";
const PROBE_SCRIPT: &crate::translation_core::Str = "const r=await fetch('http://127.0.0.1:8080/api/models',{signal:AbortSignal.timeout(5000),headers:{authorization:'Bearer '+process.env.ROUTER_DEPLOY_PROBE_TOKEN}});console.log(r.status)";

fn hmac_sha256(key: &[u8], message: &[u8]) -> Vec<u8> {
    let signature =
        jsonwebtoken::crypto::sign(message, &EncodingKey::from_secret(key), Algorithm::HS256)
            .expect("HMAC-SHA256 accepts any key");
    base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(signature)
        .expect("jsonwebtoken returns base64url")
}

/// A keyed, truncated digest that identifies a secret without revealing it:
/// HMAC-SHA256 keyed by the secret over a fixed context, first 128 bits.
pub(super) fn fingerprint(secret: &crate::translation_core::Str) -> String {
    let digest = hmac_sha256(secret.as_bytes(), FINGERPRINT_CONTEXT);
    format!("hmac-sha256:{}", hex::encode(&digest[..16]))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum SecretMatch {
    Matches,
    Changed,
    /// Neither a fingerprint label nor a readable environment.
    Unknown,
    /// A read-only command was run without a signing secret.
    NotSupplied,
}

impl SecretMatch {
    pub(super) const fn as_str(self) -> &'static crate::translation_core::Str {
        match self {
            Self::Matches => "matches",
            Self::Changed => "changed",
            Self::Unknown => "unknown",
            Self::NotSupplied => "not-supplied",
        }
    }
}

/// The probe outcome rule: authentication passed unless the candidate said
/// 401 or failed outright. `/api/models` answers 403 for a token without a
/// managed-client binding, which still proves the signature was accepted.
pub(super) const fn probe_accepted(status: u16) -> bool {
    status != 401 && status < 500
}

impl Coordinator<'_> {
    /// Compare the supplied secret with the one `backend` was started with.
    /// Backends from before issue #625 carry no label; their environment is
    /// read into memory only to be fingerprinted.
    pub(super) fn secret_match(&self, backend: &str) -> SecretMatch {
        if link_assistant_router::token_secret::is_placeholder(self.token_secret) {
            return SecretMatch::NotSupplied;
        }
        let running = self
            .docker
            .label(backend, &format!("{LABEL_KEY}.{LABEL_SUFFIX}"))
            .or_else(|| {
                self.docker
                    .env_value(backend, "TOKEN_SECRET")
                    .map(|secret| fingerprint(&secret))
            });
        match running {
            None => SecretMatch::Unknown,
            Some(running) if running == fingerprint(self.token_secret) => SecretMatch::Matches,
            Some(_) => SecretMatch::Changed,
        }
    }

    /// Status lines for the secret; true when an update would need force.
    pub(super) fn print_secret(&self, backend: &str) -> bool {
        let matched = self.secret_match(backend);
        println!("token_secret={}", matched.as_str());
        match matched {
            SecretMatch::Changed => {
                println!(
                    "blocker=token-secret-change reason=\"{backend} verifies tokens with a different TOKEN_SECRET; its issued client tokens would be rejected with HTTP 401\""
                );
                true
            }
            SecretMatch::Unknown => {
                println!(
                    "blocker=token-secret-unknown reason=\"the TOKEN_SECRET {backend} was started with cannot be established\""
                );
                true
            }
            SecretMatch::Matches | SecretMatch::NotSupplied => false,
        }
    }

    fn issued_client_tokens(&self, backend: &str) -> Option<usize> {
        let now = crate::operation_context::now().timestamp();
        let rendered = self.docker.token_inventory(backend).ok()?;
        let records: Vec<TokenRecord> =
            crate::operations::decode_token_inventory(rendered.as_bytes()).ok()?;
        Some(
            records
                .iter()
                .filter(|record| !record.revoked && record.expires_at > now)
                .count(),
        )
    }

    /// Refuse a secret change before any mutation unless it is forced.
    pub(super) fn secret_preflight(&self, backend: &str) -> Result<(), String> {
        let matched = self.secret_match(backend);
        let reason = match matched {
            SecretMatch::Matches => return Ok(()),
            SecretMatch::NotSupplied => {
                return Err(link_assistant_router::token_secret::refusal());
            }
            SecretMatch::Changed => format!(
                "the supplied TOKEN_SECRET differs from the one {backend} verifies tokens with: every issued client token would be rejected with HTTP 401 and provider keys encrypted at rest could not be read. Rerun with the saved secret; if {backend} itself was started with a wrong secret, rerun with the correct one and --force-update"
            ),
            SecretMatch::Unknown => format!(
                "the TOKEN_SECRET {backend} was started with cannot be established, so token continuity cannot be proven; rerun with --force-update after confirming the secret"
            ),
        };
        if !self.force {
            return Err(reason);
        }
        println!(
            "force_update accepted token_secret_rotation token_secret={} issued_client_tokens={}",
            matched.as_str(),
            self.issued_client_tokens(backend)
                .map_or_else(|| "unknown".to_string(), |count| count.to_string())
        );
        Ok(())
    }

    /// Before cutover, show the candidate a short-lived token signed with the
    /// running deployment's secret. It has no durable record, so no store is
    /// written, and it reaches the candidate only through the environment.
    pub(super) fn probe_candidate(&self, candidate: &str, previous: &str) -> Result<(), String> {
        if self.secret_match(previous) != SecretMatch::Matches {
            println!("token_probe=skipped reason=forced TOKEN_SECRET rotation");
            return Ok(());
        }
        let token = self.probe_token()?;
        let answer = self
            .docker
            .exec_with_env(
                candidate,
                &[(PROBE_ENV, token.as_str())],
                &["bun", "-e", PROBE_SCRIPT],
            )
            .map_err(|error| format!("token probe could not reach {candidate}: {error}"))?;
        let status = answer
            .lines()
            .last()
            .and_then(|line| line.trim().parse::<u16>().ok())
            .ok_or_else(|| format!("token probe returned no HTTP status from {candidate}"))?;
        if !probe_accepted(status) {
            return Err(format!(
                "{candidate} rejected a token signed with the running deployment's secret (HTTP {status}); issued client tokens would stop working"
            ));
        }
        println!("token_probe=accepted status={status}");
        Ok(())
    }

    pub(super) fn probe_token(&self) -> Result<String, String> {
        let now = crate::operation_context::now().timestamp();
        let claims = link_assistant_router::token::TokenClaims {
            sub: format!("deploy-probe-{}", uuid::Uuid::new_v4().simple()),
            iat: now,
            exp: now + 300,
            label: "deploy-probe".to_string(),
            scope: String::new(),
            github_repos: Vec::new(),
            client_kind: None,
            principal_id: None,
        };
        let jwt = jsonwebtoken::encode(
            &Header::default(),
            &claims,
            &EncodingKey::from_secret(self.token_secret.as_bytes()),
        )
        .map_err(|error| format!("could not sign the token probe: {error}"))?;
        Ok(format!(
            "{}{jwt}",
            link_assistant_router::token::TOKEN_PREFIX
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// RFC 4231, test case 2.
    #[test]
    fn hmac_matches_the_published_vector() {
        assert_eq!(
            hex::encode(hmac_sha256(b"Jefe", b"what do ya want for nothing?")),
            "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843"
        );
    }

    #[test]
    fn a_fingerprint_distinguishes_secrets_without_containing_them() {
        let first = fingerprint("secret-a");
        assert_eq!(first, fingerprint("secret-a"));
        assert_ne!(first, fingerprint("secret-b"));
        assert!(first.starts_with("hmac-sha256:"));
        assert_eq!(first.len(), "hmac-sha256:".len() + 32);
        assert!(!first.contains("secret-a"));
    }

    #[test]
    fn only_a_rejected_signature_or_a_failure_fails_the_probe() {
        assert!(probe_accepted(200));
        assert!(probe_accepted(403));
        assert!(!probe_accepted(401));
        assert!(!probe_accepted(500));
        assert!(!probe_accepted(503));
    }
}

//! `router deploy --mode host --install-service` (issue #684).
//!
//! A host deployment is a detached process: it does not survive a reboot or a
//! logout, and nothing restarts it after a crash. `--install-service` writes a
//! launchd agent (`~/Library/LaunchAgents`) or a systemd user unit
//! (`~/.config/systemd/user`) that starts the same executable on the same
//! data directory and port at login, and restarts it when it fails.
//!
//! The signing secret is written to a `0600` file under the deployment's
//! state directory and reaches the Router through `TOKEN_SECRET_FILE`, so it
//! is never in the unit, in the service manager's view of it, or in argv.
//! `launchctl` and `systemctl` are found on `PATH`.
//!
//! The unit is enabled, not started: the process the deploy just started
//! keeps serving, and the service manager takes over at the next login or
//! boot. A later deploy stops a service-started process before it starts its
//! own on the stable port, then rewrites the unit for what it deployed.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

/// Overrides the platform's service manager (`systemd` or `launchd`).
pub const MANAGER_ENV: &str = "LINK_ASSISTANT_ROUTER_SERVICE_MANAGER";

const RECORD: &str = "service.json";
const SECRET: &str = "token-secret";

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum Manager {
    Systemd,
    Launchd,
}

impl Manager {
    fn detect() -> Result<Self, String> {
        match crate::operation_context::var(MANAGER_ENV).ok().as_deref() {
            Some("systemd") => Ok(Self::Systemd),
            Some("launchd") => Ok(Self::Launchd),
            Some(other) => Err(format!(
                "{MANAGER_ENV} must be `systemd` or `launchd`, not `{other}`"
            )),
            None if cfg!(target_os = "macos") => Ok(Self::Launchd),
            None => Ok(Self::Systemd),
        }
    }

    const fn as_str(self) -> &'static str {
        match self {
            Self::Systemd => "systemd",
            Self::Launchd => "launchd",
        }
    }
}

/// What `--install-service` wrote, so it can be replaced or removed.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct Record {
    pub manager: Manager,
    /// The systemd unit name or the launchd label.
    pub name: String,
    pub unit: PathBuf,
    pub secret: PathBuf,
}

/// Everything a unit says, none of it secret.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Unit {
    pub root: PathBuf,
    pub executable: PathBuf,
    pub port: u16,
    pub data_dir: PathBuf,
    pub secret_file: PathBuf,
    pub log: PathBuf,
}

fn home() -> Result<PathBuf, String> {
    crate::operation_context::var_os("HOME")
        .filter(|home| !home.is_empty())
        .map(PathBuf::from)
        .ok_or_else(|| "HOME is not set; the service location is unknown".to_string())
}

fn names(manager: Manager) -> (String, String) {
    let qualify = link_assistant_router::deploy::instance::qualify;
    match manager {
        Manager::Systemd => {
            let name = format!("{}.service", qualify("link-assistant-router"));
            (name.clone(), name)
        }
        Manager::Launchd => {
            let label = qualify("com.link-assistant.router");
            (label.clone(), format!("{label}.plist"))
        }
    }
}

fn unit_path(manager: Manager, file: &str) -> Result<PathBuf, String> {
    Ok(match manager {
        Manager::Systemd => crate::operation_context::var_os("XDG_CONFIG_HOME")
            .filter(|path| !path.is_empty())
            .map_or_else(
                || home().map(|home| home.join(".config")),
                |path| Ok(PathBuf::from(path)),
            )?
            .join("systemd")
            .join("user")
            .join(file),
        Manager::Launchd => home()?.join("Library").join("LaunchAgents").join(file),
    })
}

/// The marker naming the root a unit belongs to, so another root's unit of
/// the same name is never overwritten.
fn marker(root: &Path) -> String {
    format!("root={}", root.display())
}

/// Escape a path for a systemd setting that takes a bare path, such as
/// `WorkingDirectory=` or `StandardOutput=append:`: those do not unquote, so
/// only specifiers are escaped.
fn systemd_path(path: &Path) -> String {
    path.display().to_string().replace('%', "%%")
}

/// Whether a unit file was written for `root`. The marker is matched with its
/// closing parenthesis, so `/srv/r` does not claim the unit of `/srv/r2`.
fn written_for(existing: &str, root: &Path) -> bool {
    existing.contains(&format!("({})", marker(root)))
        || existing.contains(&format!("({})", xml(&marker(root)).replace("--", "- -")))
}

/// Quote a value for a systemd `Environment=` or `ExecStart=` word.
fn systemd_quote(value: &str) -> String {
    format!(
        "\"{}\"",
        value
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('%', "%%")
    )
}

fn xml(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

fn environment(unit: &Unit) -> [(&'static str, String); 5] {
    [
        ("ROUTER_HOST", "127.0.0.1".to_string()),
        ("ROUTER_PORT", unit.port.to_string()),
        ("DATA_DIR", unit.data_dir.display().to_string()),
        ("STORAGE_POLICY", "text".to_string()),
        (
            link_assistant_router::token_secret::FILE_ENV,
            unit.secret_file.display().to_string(),
        ),
    ]
}

/// The systemd user unit for `unit`.
#[must_use]
pub fn systemd_unit(unit: &Unit) -> String {
    let mut text = format!(
        "# Written by `router deploy --install-service` ({}).\n\
         # The signing secret is read from TOKEN_SECRET_FILE; it is not in this file.\n\
         [Unit]\n\
         Description=Link.Assistant.Router host deployment\n\
         After=network-online.target\n\n\
         [Service]\n\
         Type=simple\n\
         WorkingDirectory={}\n",
        marker(&unit.root),
        systemd_path(&unit.data_dir),
    );
    for (name, value) in environment(unit) {
        let _ = writeln!(
            text,
            "Environment={}",
            systemd_quote(&format!("{name}={value}"))
        );
    }
    let log = systemd_path(&unit.log);
    let _ = write!(
        text,
        "ExecStart={} serve\n\
         Restart=on-failure\n\
         RestartSec=5\n\
         StandardOutput=append:{log}\n\
         StandardError=append:{log}\n\n\
         [Install]\n\
         WantedBy=default.target\n",
        systemd_quote(&unit.executable.display().to_string()),
    );
    text
}

/// The launchd agent for `unit`, labelled `label`.
#[must_use]
pub fn launchd_plist(unit: &Unit, label: &str) -> String {
    let mut environment_entries = String::new();
    for (name, value) in environment(unit) {
        let _ = writeln!(
            environment_entries,
            "      <key>{name}</key>\n      <string>{}</string>",
            xml(&value)
        );
    }
    let log = xml(&unit.log.display().to_string());
    format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\
         <!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n\
         <!-- Written by router deploy install-service ({}). The signing secret is read from TOKEN_SECRET_FILE. -->\n\
         <plist version=\"1.0\">\n\
         <dict>\n\
         \x20 <key>Label</key>\n  <string>{}</string>\n\
         \x20 <key>ProgramArguments</key>\n  <array>\n    <string>{}</string>\n    <string>serve</string>\n  </array>\n\
         \x20 <key>WorkingDirectory</key>\n  <string>{}</string>\n\
         \x20 <key>EnvironmentVariables</key>\n  <dict>\n{environment_entries}  </dict>\n\
         \x20 <key>RunAtLoad</key>\n  <true/>\n\
         \x20 <key>KeepAlive</key>\n  <dict>\n    <key>SuccessfulExit</key>\n    <false/>\n  </dict>\n\
         \x20 <key>StandardOutPath</key>\n  <string>{log}</string>\n\
         \x20 <key>StandardErrorPath</key>\n  <string>{log}</string>\n\
         </dict>\n\
         </plist>\n",
        xml(&marker(&unit.root)).replace("--", "- -"),
        xml(label),
        xml(&unit.executable.display().to_string()),
        xml(&unit.data_dir.display().to_string()),
    )
}

fn run(program: &str, args: &[&str]) -> Result<(), String> {
    let output = crate::operation_context::process_output(
        crate::operation_context::command(program).args(args),
    )
    .map_err(|error| format!("could not run {program}: {error}"))?;
    if output.status.success() {
        Ok(())
    } else {
        Err(format!(
            "`{program} {}` failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

fn launchd_domain() -> Result<String, String> {
    let output =
        crate::operation_context::process_output(crate::operation_context::command("id").arg("-u"))
            .map_err(|error| format!("could not run id -u: {error}"))?;
    let uid = String::from_utf8_lossy(&output.stdout).trim().to_string();
    if uid.is_empty() || !uid.bytes().all(|byte| byte.is_ascii_digit()) {
        return Err("could not determine the user id for launchctl".to_string());
    }
    Ok(format!("gui/{uid}"))
}

fn record_path(root: &Path) -> PathBuf {
    root.join("state").join(RECORD)
}

/// The installed service of `root`, if any.
#[must_use]
pub fn installed(root: &Path) -> Option<Record> {
    let bytes = std::fs::read(record_path(root)).ok()?;
    serde_json::from_slice(&bytes).ok()
}

/// Write the unit and the secret file for the host deployment of `root`, and
/// enable the unit with its service manager.
///
/// # Errors
///
/// When the deployment is not in host mode, another root owns the unit name,
/// a file cannot be written, or the service manager refuses.
pub fn install(root: &Path, token_secret: &str) -> Result<Record, String> {
    link_assistant_router::token_secret::ensure_real(token_secret)?;
    let host = super::state::State::new(root)
        .host()?
        .ok_or("--install-service supervises a host deployment; deploy with --mode host first")?;
    let manager = Manager::detect()?;
    let (name, file) = names(manager);
    let path = unit_path(manager, &file)?;
    if let Ok(existing) = std::fs::read_to_string(&path)
        && !written_for(&existing, root)
    {
        return Err(format!(
            "{} belongs to another deployment; remove it with `router deploy --uninstall-service --root DIR` for that root, or use --instance",
            path.display()
        ));
    }
    let state = root.join("state");
    let secret = state.join(SECRET);
    let unit = Unit {
        root: root.to_path_buf(),
        executable: PathBuf::from(&host.executable),
        port: host.port,
        data_dir: root.join("data"),
        secret_file: secret.clone(),
        log: state.join("host.log"),
    };
    for value in [&unit.executable, &unit.data_dir, &unit.secret_file] {
        if value.to_string_lossy().contains(['\n', '\r', '\0']) {
            return Err(format!("{} cannot be written into a unit", value.display()));
        }
    }
    let write = |path: &Path, bytes: &[u8]| {
        link_assistant_router::durable_file::atomic_write_owner_only(path, bytes).map_err(|error| {
            link_assistant_router::durable_file::describe_write_failure(path, &error)
        })
    };
    write(&secret, format!("{token_secret}\n").as_bytes())?;
    let text = match manager {
        Manager::Systemd => systemd_unit(&unit),
        Manager::Launchd => launchd_plist(&unit, &name),
    };
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|error| format!("could not create {}: {error}", parent.display()))?;
    }
    write(&path, text.as_bytes())?;
    let record = Record {
        manager,
        name: name.clone(),
        unit: path.clone(),
        secret,
    };
    let encoded = serde_json::to_vec_pretty(&record).map_err(|error| error.to_string())?;
    write(&record_path(root), &encoded)?;
    match manager {
        Manager::Systemd => {
            run("systemctl", &["--user", "daemon-reload"])?;
            run("systemctl", &["--user", "enable", &name])?;
        }
        Manager::Launchd => {
            let domain = launchd_domain()?;
            run("launchctl", &["enable", &format!("{domain}/{name}")])?;
        }
    }
    println!(
        "host_service=installed manager={} name={name} unit={}",
        manager.as_str(),
        path.display()
    );
    if manager == Manager::Systemd {
        println!(
            "note: a systemd user unit starts at login; run `loginctl enable-linger` to start it at boot without one"
        );
    }
    Ok(record)
}

/// Stop a service-started Router so a deploy can start its own on the port.
/// A service that is not running is not an error.
pub fn stop(record: &Record) {
    let _ = match record.manager {
        Manager::Systemd => run("systemctl", &["--user", "stop", &record.name]),
        Manager::Launchd => launchd_domain().and_then(|domain| {
            run(
                "launchctl",
                &["bootout", &format!("{domain}/{}", record.name)],
            )
        }),
    };
}

/// Disable and remove the service of `root`; `Ok(false)` when none was
/// installed.
///
/// # Errors
///
/// When a file cannot be removed or the service manager refuses to disable.
pub fn uninstall(root: &Path) -> Result<bool, String> {
    let Some(record) = installed(root) else {
        return Ok(false);
    };
    stop(&record);
    match record.manager {
        Manager::Systemd => run("systemctl", &["--user", "disable", &record.name])?,
        Manager::Launchd => {
            let domain = launchd_domain()?;
            run(
                "launchctl",
                &["disable", &format!("{domain}/{}", record.name)],
            )?;
        }
    }
    for path in [&record.unit, &record.secret, &record_path(root)] {
        match std::fs::remove_file(path) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(format!("could not remove {}: {error}", path.display())),
        }
    }
    if record.manager == Manager::Systemd {
        run("systemctl", &["--user", "daemon-reload"])?;
    }
    println!(
        "host_service=uninstalled manager={} name={}",
        record.manager.as_str(),
        record.name
    );
    Ok(true)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn unit() -> Unit {
        Unit {
