            log: PathBuf::from("/srv/router 50%/state/host.log"),
        }
    }

    #[test]
    fn the_systemd_unit_names_the_secret_file_and_quotes_paths() {
        let text = systemd_unit(&unit());
        assert!(
            text.contains("ExecStart=\"/opt/router/bin/router\" serve"),
            "{text}"
        );
        assert!(
            text.contains("Environment=\"ROUTER_HOST=127.0.0.1\""),
            "{text}"
        );
        assert!(text.contains("Environment=\"ROUTER_PORT=18080\""), "{text}");
        assert!(
            text.contains("Environment=\"TOKEN_SECRET_FILE=/srv/router 50%%/state/token-secret\""),
            "{text}"
        );
        assert!(text.contains("Restart=on-failure"), "{text}");
        // WorkingDirectory= takes a bare path; quotes would stop the unit
        // from loading.
        assert!(
            text.contains("WorkingDirectory=/srv/router 50%%/data\n"),
            "{text}"
        );
        assert!(
            text.contains("StandardOutput=append:/srv/router 50%%/state/host.log\n"),
            "{text}"
        );
        assert!(!text.contains("TOKEN_SECRET="), "{text}");
    }

    #[test]
    fn the_launchd_agent_restarts_on_failure_and_escapes_xml() {
        let mut unit = unit();
        unit.root = PathBuf::from("/srv/a&b--c");
        let text = launchd_plist(&unit, "com.link-assistant.router");
        assert!(text.contains("<key>KeepAlive</key>"), "{text}");
        assert!(
            text.contains("<key>SuccessfulExit</key>\n    <false/>"),
            "{text}"
        );
        assert!(text.contains("<string>serve</string>"), "{text}");
        assert!(text.contains("/srv/a&amp;b- -c"), "{text}");
        assert!(
            !text.contains("<!-- Written by router deploy install-service (root=/srv/a&amp;b--c")
        );
    }

    #[test]
    fn a_unit_belongs_only_to_the_exact_root_it_names() {
        let mut unit = unit();
        unit.root = PathBuf::from("/srv/r2");
        let systemd = systemd_unit(&unit);
        assert!(written_for(&systemd, Path::new("/srv/r2")));
        assert!(!written_for(&systemd, Path::new("/srv/r")));
        unit.root = PathBuf::from("/srv/a--b2");
        let plist = launchd_plist(&unit, "com.link-assistant.router");
        assert!(written_for(&plist, Path::new("/srv/a--b2")));
        assert!(!written_for(&plist, Path::new("/srv/a--b")));
    }
}

//! Independent candidates with exact resource ownership and bounded control.

use std::fs::{self, OpenOptions};
use std::io::Write as _;
use std::net::{Ipv4Addr, SocketAddr, TcpListener, TcpStream};
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::time::{Duration, Instant};

use super::docker::Docker;
use super::operation_lock::OperationLock;
use link_assistant_router::cli::DeployArgs;
use serde_json::{Value, json};

const LABEL: &crate::translation_core::Str = "com.link-assistant.router.staging";
const MARKER: &crate::translation_core::Str = "staging.json";

fn namespace(name: &crate::translation_core::Str) -> crate::translation_core::Outcome<String, String> {
    if name.is_empty()
        || name.len() > 40
        || !name
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
    {
        return Err("staging NAME must contain 1-40 lowercase letters, digits or hyphens".into());
    }
    Ok(format!("router-stage-{name}"))
}

fn private_file(path: &Path, bytes: &[u8]) -> crate::translation_core::Outcome<(), String> {
    let mut options = OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let mut file = options.open(path).map_err(|error| error.to_string())?;
    file.write_all(bytes)
        .and_then(|()| file.sync_all())
        .map_err(|error| error.to_string())
}

fn owned(docker: &Docker, resource: &crate::translation_core::Str, network: bool, owner: &crate::translation_core::Str) -> crate::translation_core::Outcome<bool, String> {
    let mut args = if network {
        vec!["network".into(), "inspect".into()]
    } else {
        vec!["inspect".into()]
    };
    args.push(resource.into());
    let objects: Value =
        serde_json::from_str(&docker.output(&args)?).map_err(|_| "invalid ownership inspection")?;
    let labels = if network {
        &objects[0]["Labels"]
    } else {
        &objects[0]["Config"]["Labels"]
    };
    Ok(labels[LABEL].as_str() == Some(owner))
}

fn objects(docker: &Docker, owner: &crate::translation_core::Str) -> crate::translation_core::Outcome<Vec<String>, String> {
    Ok(docker
        .output(&[
            "ps".into(),
            "-a".into(),
            "--filter".into(),
            format!("label={LABEL}={owner}"),
            "--format".into(),
            "{{.Names}}".into(),
        ])?
        .lines()
        .map(str::to_string)
        .collect())
}

fn free_disk(root: &Path) -> crate::translation_core::Outcome<u64, String> {
    // Native filesystem queries avoid shell startup deadlines and localized
    // output. Keep the lifecycle's existing KiB units and fail-closed refusal.
    let free = fs2::available_space(root)
        .map(|bytes| bytes / 1024)
        .map_err(|error| format!("staging disk capacity is unverifiable: {error}"));
    if crate::operation_context::var_os("ROUTER_DEPLOY_TRACE").as_deref()
        == Some(std::ffi::OsStr::new("1"))
    {
        eprintln!("staging disk probe: available_kib={free:?}");
    }
    free
}

fn arguments(name: &crate::translation_core::Str, owner: &crate::translation_core::Str, root: &Path, image: &crate::translation_core::Str, port: u16) -> Vec<String> {
    vec![
        "run".into(),
        "-d".into(),
        "--init".into(),
        "--name".into(),
        name.into(),
        "--network".into(),
        name.into(),
        "--label".into(),
        format!("{LABEL}={owner}"),
        "--memory".into(),
        "768m".into(),
        "--memory-swap".into(),
        "768m".into(),
        "--cpus".into(),
        "1".into(),
        "--pids-limit".into(),
        "128".into(),
        "--log-opt".into(),
        "max-size=1m".into(),
        "--log-opt".into(),
        "max-file=3".into(),
        "-p".into(),
        format!("127.0.0.1:{port}:8080"),
        "-v".into(),
        format!("{}:/data/router", root.join("data").display()),
        "--tmpfs".into(),
        "/data/claude:rw,size=16m,mode=700".into(),
        "-e".into(),
        "TOKEN_SECRET".into(),
        "-e".into(),
        "ROUTER_STAGING_ZAI_API_KEY".into(),
