//! Durable local cutover identity and hard-kill recovery decisions.

use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum PreviousKind {
    None,
    Managed,
    Legacy,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(super) struct Active {
    pub version: u8,
    pub backend: String,
    pub image_ref: String,
    pub image_id: String,
    pub port: u16,
}

/// The Router process serving this root from the host (issue #626). Its
/// containers stay stopped, not removed, so returning is one command.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(super) struct Host {
    pub version: u8,
    pub pid: u32,
    pub port: u16,
    pub executable: String,
    pub router_version: String,
    /// [`super::secret::fingerprint`] of the secret it was started with.
    pub token_secret: String,
    /// Runtime environment fingerprint (`--env`, issue #679), when any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub runtime_env: Option<String>,
    /// The container backend it replaced, retained stopped for rollback.
    pub previous_backend: Option<String>,
    pub started_at: i64,
}

/// What the durable active record says, classified without failing, so a
/// read-only status can describe a damaged record instead of stopping at it
/// (issue #631).
#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) enum ActiveRecord {
    Absent,
    Valid(Active),
    /// Unparseable bytes or an unsafe backend name; safe to set aside.
    Corrupt(String),
    /// Unreadable, or written by a newer Router; never overwritten.
    Unsupported(String),
}

impl ActiveRecord {
    pub(super) fn describe(&self) -> String {
        match self {
            Self::Absent => "absent".to_string(),
            Self::Valid(active) => format!("present backend={}", active.backend),
            Self::Corrupt(reason) => format!("corrupt reason={reason:?}"),
            Self::Unsupported(reason) => format!("unsupported reason={reason:?}"),
        }
    }
}

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub(super) enum Phase {
    Prepared,
    Accepted,
    Complete,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(super) struct Transaction {
    pub version: u8,
    pub phase: Phase,
    pub previous: Option<String>,
    pub previous_kind: PreviousKind,
    pub previous_port: Option<u16>,
    pub candidate: String,
    pub image_ref: String,
    pub image_id: String,
    pub port: u16,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) enum Recovery {
    None,
    RollBack(Transaction),
    FinishAccepted(Transaction),
}

pub(super) struct State {
    directory: PathBuf,
}

impl State {
    pub(super) fn new(root: &Path) -> Self {
        Self {
            directory: root.join("state"),
        }
    }

    pub(super) fn directory(&self) -> &Path {
        &self.directory
    }

    pub(super) fn current_path(&self) -> PathBuf {
        self.directory.join("current")
    }

    pub(super) fn current(&self) -> Result<Option<String>, String> {
        let path = self.current_path();
        match std::fs::read_to_string(&path) {
            Ok(value) => {
                let backend = value.trim();
                valid_backend(backend)?;
                Ok(Some(backend.to_string()))
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(error) => Err(format!("could not read {}: {error}", path.display())),
        }
    }

    pub(super) fn set_current(&self, backend: &str) -> Result<(), String> {
        valid_backend(backend)?;
        link_assistant_router::durable_file::atomic_write_owner_only(
            &self.current_path(),
            format!("{backend}\n").as_bytes(),
        )
        .map_err(|error| format!("could not publish the relay pointer: {error}"))
    }

    pub(super) fn clear_current(&self) -> Result<(), String> {
        remove_if_present(&self.current_path())
    }

    pub(super) fn active(&self) -> Result<Option<Active>, String> {
        let active: Option<Active> = read_json(&self.directory.join("active"))?;
        if let Some(active) = &active {
            if active.version != 1 {
                return Err(format!(
                    "unsupported local deployment state v{}",
                    active.version
                ));
            }
            valid_backend(&active.backend)?;
        }
        Ok(active)
    }

    pub(super) fn active_record(&self) -> ActiveRecord {
        let path = self.directory.join("active");
        let bytes = match std::fs::read(&path) {
            Ok(bytes) => bytes,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return ActiveRecord::Absent;
            }
            Err(error) => return ActiveRecord::Unsupported(format!("unreadable: {error}")),
        };
        let active = match serde_json::from_slice::<Active>(&bytes) {
            Ok(active) => active,
            Err(error) => {
                // A newer record may add fields but keeps `version`; only a
                // record that says it is v1 (or says nothing) is ours to judge.
                let version = serde_json::from_slice::<serde_json::Value>(&bytes)
                    .ok()
                    .and_then(|value| value.get("version").and_then(serde_json::Value::as_u64));
                return match version {
                    Some(version) if version != 1 => ActiveRecord::Unsupported(format!(
                        "unsupported local deployment state v{version}"
                    )),
                    _ => ActiveRecord::Corrupt(format!("could not parse: {error}")),
                };
            }
        };
        if active.version != 1 {
            return ActiveRecord::Unsupported(format!(
                "unsupported local deployment state v{}",
                active.version
            ));
        }
        match valid_backend(&active.backend) {
            Ok(()) => ActiveRecord::Valid(active),
            Err(error) => ActiveRecord::Corrupt(error),
        }
    }

    /// Keep a damaged record for inspection instead of deleting it.
    pub(super) fn set_aside_active(&self) -> Result<PathBuf, String> {
        let path = self.directory.join("active");
        let aside = self.directory.join(format!(
            "active.corrupt-{}",
            crate::operation_context::now().format("%Y%m%dT%H%M%S%.fZ")
        ));
        std::fs::rename(&path, &aside)
            .map_err(|error| format!("could not set aside {}: {error}", path.display()))?;
        Ok(aside)
    }

    pub(super) fn write_active(&self, active: &Active) -> Result<(), String> {
        write_json(&self.directory.join("active"), active)
    }

    pub(super) fn host(&self) -> Result<Option<Host>, String> {
        let host: Option<Host> = read_json(&self.directory.join("host"))?;
        if let Some(host) = &host
            && host.version != 1
        {
            return Err(format!("unsupported host-mode record v{}", host.version));
        }
        Ok(host)
    }

    pub(super) fn write_host(&self, host: &Host) -> Result<(), String> {
        write_json(&self.directory.join("host"), host)
    }

    pub(super) fn clear_host(&self) -> Result<(), String> {
        remove_if_present(&self.directory.join("host"))
    }

    pub(super) fn transaction(&self) -> Result<Option<Transaction>, String> {
        let transaction: Option<Transaction> = read_json(&self.directory.join("transaction"))?;
        if let Some(transaction) = &transaction {
            validate_transaction(transaction)?;
        }
        Ok(transaction)
    }

    pub(super) fn write_transaction(&self, transaction: &Transaction) -> Result<(), String> {
        write_json(&self.directory.join("transaction"), transaction)
    }

    pub(super) fn clear_deployment_records(&self) -> Result<(), String> {
        for name in ["current", "active", "transaction"] {
            remove_if_present(&self.directory.join(name))?;
        }
        Ok(())
    }

    pub(super) fn recovery(&self) -> Result<Recovery, String> {
        let Some(transaction) = self.transaction()? else {
            return Ok(Recovery::None);
        };
        match transaction.phase {
            Phase::Prepared => {
                let current = self.current()?;
                let expected_previous = match transaction.previous_kind {
                    PreviousKind::Managed => transaction.previous.as_ref(),
                    PreviousKind::None | PreviousKind::Legacy => None,
                };
                if current.as_ref() != Some(&transaction.candidate)
                    && current.as_ref() != expected_previous
                {
                    return Err(
                        "interrupted transaction disagrees with the durable relay pointer"
                            .to_string(),
                    );
                }
                Ok(Recovery::RollBack(transaction))
            }
            Phase::Accepted => {
                if self.current()?.as_deref() != Some(&transaction.candidate) {
                    return Err(
                        "accepted transaction has no matching candidate relay pointer".to_string(),
                    );
                }
                Ok(Recovery::FinishAccepted(transaction))
            }
            Phase::Complete => Ok(Recovery::None),
        }
    }
}

fn valid_backend(backend: &str) -> Result<(), String> {
    if !backend.is_empty()
        && backend.len() <= 128
        && backend
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
    {
        Ok(())
    } else {
        Err("deployment state contains an unsafe backend name".to_string())
    }
}

fn validate_transaction(transaction: &Transaction) -> Result<(), String> {
    if transaction.version != 1 {
        return Err(format!(
            "unsupported local deployment transaction v{}",
            transaction.version
        ));
    }
    valid_backend(&transaction.candidate)?;
    if let Some(previous) = &transaction.previous {
        valid_backend(previous)?;
    }
    let shape_is_valid = match transaction.previous_kind {
        PreviousKind::None => transaction.previous.is_none() && transaction.previous_port.is_none(),
        PreviousKind::Managed => {
            transaction.previous.is_some() && transaction.previous_port.is_some()
        }
        PreviousKind::Legacy => {
            transaction.previous.as_deref() == Some(super::LEGACY)
                && transaction.previous_port.is_some()
        }
    };
    if !shape_is_valid {
        return Err("local deployment transaction has inconsistent previous state".to_string());
    }
    Ok(())
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> Result<Option<T>, String> {
    let bytes = match std::fs::read(path) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(format!("could not read {}: {error}", path.display())),
    };
    serde_json::from_slice(&bytes)
        .map(Some)
        .map_err(|error| format!("could not parse {}: {error}", path.display()))
}

fn write_json(path: &Path, value: &impl Serialize) -> Result<(), String> {
    let mut bytes = serde_json::to_vec_pretty(value)
        .map_err(|error| format!("could not encode {}: {error}", path.display()))?;
    bytes.push(b'\n');
    link_assistant_router::durable_file::atomic_write_owner_only(path, &bytes)
        .map_err(|error| format!("could not write {}: {error}", path.display()))
}

fn remove_if_present(path: &Path) -> Result<(), String> {
    match std::fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(format!("could not remove {}: {error}", path.display())),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn transaction(phase: Phase, previous_kind: PreviousKind) -> Transaction {
        Transaction {
            version: 1,
            phase,
            previous: (previous_kind != PreviousKind::None).then(|| "old".to_string()),
            previous_kind,
            previous_port: Some(8080),
            candidate: "candidate".into(),
            image_ref: "router:1.2.3".into(),
            image_id: "sha256:new".into(),
            port: 8080,
        }
    }

    #[test]
    fn a_hard_kill_on_either_side_of_pointer_switch_has_one_safe_answer() {
        let root = tempfile::tempdir().unwrap();
        let state = State::new(root.path());
        std::fs::create_dir_all(state.directory()).unwrap();
        let prepared = transaction(Phase::Prepared, PreviousKind::Managed);
        state.write_transaction(&prepared).unwrap();

        state.set_current("old").unwrap();
        assert_eq!(
            state.recovery().unwrap(),
            Recovery::RollBack(prepared.clone())
        );

        // Simulates SIGKILL after atomic pointer rename but before the next
        // transaction write. The still-prepared record restores the old side.
        state.set_current("candidate").unwrap();
        assert_eq!(state.recovery().unwrap(), Recovery::RollBack(prepared));

        let mut accepted = transaction(Phase::Accepted, PreviousKind::Managed);
        state.write_transaction(&accepted).unwrap();
        assert_eq!(
            state.recovery().unwrap(),
            Recovery::FinishAccepted(accepted.clone())
        );

        accepted.phase = Phase::Complete;
        state.write_transaction(&accepted).unwrap();
        assert_eq!(state.recovery().unwrap(), Recovery::None);
    }

    #[test]
    fn malformed_or_future_transactions_are_refused_before_recovery() {
        let root = tempfile::tempdir().unwrap();
        let state = State::new(root.path());
        std::fs::create_dir_all(state.directory()).unwrap();
        let mut record = transaction(Phase::Prepared, PreviousKind::Managed);
        record.version = 2;
        state.write_transaction(&record).unwrap();
        assert!(state.transaction().unwrap_err().contains("transaction v2"));

        record.version = 1;
        record.previous = None;
        state.write_transaction(&record).unwrap();
        assert!(
            state
                .transaction()
                .unwrap_err()
                .contains("inconsistent previous state")
        );
    }
}

//! Structured local status facts, recorded alongside the existing human report.
use serde_json::{Value, json};

use super::{
    Coordinator, Existing, LEGACY, RELAY, data_backup,
    state::{PreviousKind, Transaction},
};

impl Coordinator<'_> {
    pub(super) fn status_report(&self, mode: &str, status: &str) -> Value {
        json!({
            "schema": "link-assistant-router/local-deployment/v1",
            "mode": mode,
            "status": status,
            "deployment_root": self.root,
            "candidate_image": self.image,
            "listener": {"host": "127.0.0.1", "port": self.port},
            "host_router": null,
            "host_process": null,
            "backend": null,
            "relay": null,
            "converged": null,
            "connections": null,
            "runs": null,
            "blockers": [],
            "force_update_interrupts": false,
            "token_secret": null,
            "rollback_command": null,
            "transaction": null,
            "status_is_read_only": true,
        })
    }
}

pub(super) fn blocker(name: &crate::translation_core::Str, reason: &crate::translation_core::Str, forceable: bool) -> Value {
    crate::translation_core::json!({"name": name, "reason": reason, "forceable": forceable})
}

impl Coordinator<'_> {
    pub(super) fn print_status(&self, existing: &Existing) -> Result<bool, String> {
        let mut report = self.status_report("container", "absent");
        println!("deployment_root={}", self.root.display());
        println!("candidate_image={}", self.image);
        println!("listener=127.0.0.1:{}", self.port);
        println!(
            "credential_ownership=shared-data durable-per-credential-locks single-refresh-writer"
        );
        println!("{}", self.claude.status_line(self.root));
        self.print_provider_exhaustion();
        match data_backup::checkpoint_status(self.root) {
            Ok(line) => println!("{line}"),
            Err(reason) => println!(
                "blocker=data-checkpoint forceable=false reason={}",
                serde_json::to_string(&reason).unwrap_or_default()
            ),
        }
        match existing {
            Existing::Absent => {
                println!("old_backend=absent");
                println!("candidate_backend=not-started image={}", self.image);
                println!("connections=0");
                println!("run_inventory live=0 stale=0 blockers=0");
                println!("force_update_interrupts=false");
                report["converged"] = false.into();
                report["connections"] = 0.into();
                report["runs"] = serde_json::json!([]);
                crate::operation_output::record(report);
                Ok(false)
            }
            Existing::Legacy => {
                println!("old_backend={LEGACY} topology=legacy-direct");
                println!("candidate_backend=not-started image={}", self.image);
                println!("connections=unknown");
                let inventory = self.inventory(LEGACY);
                let inventory_known = inventory.is_ok();
                if let Ok(inventory) = &inventory {
                    inventory.print();
                } else if let Err(error) = &inventory {
                    println!("run_inventory=unknown blockers=unknown reason={error}");
                }
                println!("blocker=legacy-direct-front-door has unknown established connections");
                self.print_secret(LEGACY);
                if let Ok(inventory) = inventory {
                    report["runs"] = serde_json::json!(inventory.runs);
                    for run in &inventory.runs {
                        println!(
                            "force_impact run_id={} label={} state={}",
                            run.id,
                            serde_json::to_string(&run.label).unwrap_or_else(|_| "null".into()),
                            run.state.as_str()
                        );
                    }
                }
                println!("force_update_interrupts=true");
                let running = self.docker.running(LEGACY)?;
                report["status"] = "legacy".into();
                report["backend"] =
                    serde_json::json!({"name": LEGACY, "image": null, "running": running});
                report["blockers"] = serde_json::json!([blocker(
                    "legacy-direct-front-door",
                    "established connections are unknown",
                    false
                )]);
                report["force_update_interrupts"] = true.into();
                crate::operation_output::record(report);
                Ok(running && inventory_known)
            }
            Existing::Managed(active) => {
                let backend_running = self.docker.running(&active.backend)?;
                let relay_running = self.docker.running(&RELAY.value()).unwrap_or(false);
                println!("old_backend={} image={}", active.backend, active.image_ref);
                println!(
                    "old_backend_claude_credentials={}",
                    self.claude_label(&active.backend)
                );
                println!("candidate_backend=not-started image={}", self.image);
                let connections = self.connection_count(&active.backend)?;
                println!("connections={connections}");
                println!("backend_running={backend_running}");
                println!("relay={RELAY} running={relay_running} port={}", active.port);
                let inventory = self.inventory(&active.backend);
                let force_interrupts = match &inventory {
                    Ok(inventory) => {
                        inventory.print();
                        for blocker in inventory.blockers() {
                            println!(
                                "blocker=legacy-unpinned run_id={} label={}",
                                blocker.id,
                                serde_json::to_string(&blocker.label)
                                    .unwrap_or_else(|_| "null".into())
                            );
                        }
                        inventory.blockers().next().is_some() || active.port != self.port
                    }
                    Err(error) => {
                        println!("run_inventory=unknown blockers=unknown reason={error}");
                        true
                    }
                };
                if active.port != self.port {
                    println!(
                        "blocker=stable-listener-change old_port={} candidate_port={}",
                        active.port, self.port
                    );
                }
                let force_interrupts = self.print_secret(&active.backend) || force_interrupts;
                println!("force_update_interrupts={force_interrupts}");
                // Mixed images are never reported as converged (issue #627).
                let versions_match = self.print_versions(active)?;
                let converged = backend_running && relay_running && versions_match;
                println!("converged={converged}");
                report["status"] = "managed".into();
                report["backend"] = serde_json::json!({"name": active.backend, "image": active.image_ref, "running": backend_running});
                report["relay"] = serde_json::json!({"name": RELAY.value(), "port": active.port, "running": relay_running});
                report["connections"] = connections.into();
                report["converged"] = converged.into();
                report["force_update_interrupts"] = force_interrupts.into();
                report["runs"] = inventory
                    .as_ref()
                    .ok()
                    .map_or(serde_json::Value::Null, |inventory| {
                        serde_json::json!(inventory.runs)
                    });
                let mut blockers = Vec::new();
                match &inventory {
                    Ok(inventory) => {
                        for run in inventory.blockers() {
                            blockers.push(blocker(
                                "legacy-unpinned",
                                &format!("run {} has no lease", run.id),
                                true,
                            ));
                        }
                    }
                    Err(error) => blockers.push(blocker("run-inventory-unknown", error, false)),
                }
                if active.port != self.port {
                    blockers.push(blocker(
                        "stable-listener-change",
                        "the candidate listener changes the active port",
                        true,
                    ));
                }
                if !versions_match {
                    blockers.push(blocker(
                        "version-mismatch",
                        "serving components have different versions",
                        false,
                    ));
                }
                report["blockers"] = serde_json::json!(blockers);
                crate::operation_output::record(report);
                Ok(converged && inventory.is_ok())
            }
        }
    }

    pub(super) fn print_interrupted(&self, transaction: &Transaction) -> Result<(), String> {
        let mut report = self.status_report("container", "interrupted");
        report["transaction"] = serde_json::json!(transaction);
        report["blockers"] = serde_json::json!([blocker(
            "pending-transaction",
            "an interrupted update requires recovery",
            false
        )]);
        crate::operation_output::record(report);
        println!("deployment_root={}", self.root.display());
        println!("transaction_phase={:?}", transaction.phase);
        println!(
            "old_backend={}",
            transaction.previous.as_deref().unwrap_or("absent")
        );
        println!("candidate_backend={}", transaction.candidate);
        println!("candidate_image={}", transaction.image_ref);
        println!(
            "relay_pointer={}",
            self.state.current()?.as_deref().unwrap_or("absent")
        );
        if transaction.previous_kind == PreviousKind::Managed
            && let Some(previous) = transaction.previous.as_deref()
        {
            println!("old_connections={}", self.connection_count(previous)?);
        } else if transaction.previous_kind == PreviousKind::Legacy {
            println!("old_connections=unknown");
        }
        println!(
            "candidate_connections={}",
            self.connection_count(&transaction.candidate)?
        );
        let inventory_backend = self
            .state
            .current()?
            .or_else(|| transaction.previous.clone())
            .unwrap_or_else(|| transaction.candidate.clone());
        match self.inventory(&inventory_backend) {
            Ok(inventory) => inventory.print(),
            Err(error) => println!("run_inventory=unknown blockers=unknown reason={error}"),
        }
        println!(
            "credential_ownership=shared-data durable-per-credential-locks single-refresh-writer"
        );
        println!("recovery_required=true status_is_read_only=true");
        Ok(())
    }
}

//! SSH transport for `router deploy --server`.
//!
//! The coordinator deliberately sends one target-side program through one SSH
//! session. The session owns the target lease for its whole lifetime, while a
//! random cookie inherited through the agent's environment identifies every
//! child which may still be changing deployment state.

use std::ffi::OsStr;
use std::io::Write as _;
use std::process::{ExitCode, Stdio};

use base64::Engine as _;
use link_assistant_router::cli::DeployArgs;
use link_assistant_router::deploy_config::{Merged, ResolvedDeploy};

mod seeding;
mod session;

static AGENT: std::sync::LazyLock<String> = std::sync::LazyLock::new(|| {
    include_str!("deploy/remote_agent.sh")
        .replace(
            "@@DEPLOY_SETTINGS@@",
            include_str!("deploy/remote_settings.sh"),
        )
        .replace(
            "@@PROVIDER_KEY_PLAN@@",
            include_str!("deploy/provider_key_plan.js"),
        )
        .replace(
            "@@PROVIDER_KEY_CHECK@@",
            include_str!("deploy/provider_key_check.js"),
        )
        .replace(
            "@@VERIFY_PROFILE@@",
            include_str!("deploy/verify_profile.js"),
        )
        .replace("@@REMOVED_ROUTES@@", &removed_routes_json())
        .replace(
            "@@DATA_CHECKPOINT@@",
            include_str!("deploy/data_checkpoint.js"),
        )
});

/// The removed-route list the verification profile probes, as a JS literal.
fn removed_routes_json() -> String {
    let routes: Vec<[&str; 2]> = link_assistant_router::route_contract::REMOVED_ROUTES
        .iter()
        .map(|(method, path)| [*method, *path])
        .collect();
    serde_json::to_string(&routes).unwrap_or_else(|_| "[]".to_string())
}
const AGENT_LEASE_EXIT: i32 = 73;
const TRANSPORT_EXIT: u8 = 10;
const LEASE_EXIT: u8 = 11;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RemoteMode {
    Deploy,
    Status,
    Down,
}

impl RemoteMode {
    const fn as_str(self) -> &'static crate::translation_core::Str {
        match self {
            Self::Deploy => "deploy",
            Self::Status => "status",
            Self::Down => "down",
        }
    }
}

fn mode(args: &DeployArgs) -> crate::translation_core::Outcome<RemoteMode, String> {
    if args.down {
        if !args.yes {
            return Err(
                "`deploy --server --down` removes serving containers; rerun with --yes".to_string(),
            );
        }
        Ok(RemoteMode::Down)
    } else if args.status {
        Ok(RemoteMode::Status)
    } else {
        Ok(RemoteMode::Deploy)
    }
}

fn default_image() -> String {
    format!(
        "link-assistant-router-deploy:{}",
        link_assistant_router::VERSION
    )
}

fn shell_quote(value: &crate::translation_core::Str) -> String {
    format!("'{}'", value.replace('\'', "'\"'\"'"))
}

fn public_name(target: &crate::translation_core::Str) -> String {
    let target = target.strip_prefix("ssh://").unwrap_or(target);
    let host = target.rsplit_once('@').map_or(target, |(_, host)| host);
    if let Some(host) = host
        .strip_prefix('[')
        .and_then(|host| host.split_once(']').map(|(host, _)| host))
    {
        return host.to_string();
    }
    if host.matches(':').count() > 1 {
        return host.to_string();
    }
    host.split_once(':')
        .map_or(host, |(host, _)| host)
        .to_string()
}

fn remote_command(arguments: &[String], with_payload: bool) -> String {
    let wrapper = concat!(
        "umask 077; ",
        "IFS= read -r router_secret_b64 || exit 64; ",
        // The sentinel prevents command substitution from stripping newline
        // bytes which are legitimately part of the configured secret.
        "TOKEN_SECRET=$({ printf %s \"$router_secret_b64\" | base64 -d || exit 64; printf x; }) || exit 64; ",
        "TOKEN_SECRET=${TOKEN_SECRET%x}; ",
        "export TOKEN_SECRET; ",
        "exec sh -s -- \"$@\""
    );
    // Deploy settings (issue #679) travel as a second stdin line, so that
    // runtime values and provider keys never reach the remote argv either.
    let wrapper = if with_payload {
        wrapper.replace(
            "exec sh -s",
            "IFS= read -r ROUTER_DEPLOY_PAYLOAD || exit 64; export ROUTER_DEPLOY_PAYLOAD; exec sh -s",
        )
    } else {
        wrapper.to_string()
    };
    let mut command = format!("sh -c {} sh", shell_quote(&wrapper));
    for argument in arguments {
        command.push(' ');
        command.push_str(&shell_quote(argument));
    }
    command
}

fn agent_arguments(args: &DeployArgs, mode: RemoteMode, cookie: &crate::translation_core::Str) -> Vec<String> {
    let (build_mode, build_value) = args.build.as_ref().map_or_else(
        || {
            if args.image.is_some() {
                ("pull", "")
            } else {
                ("release", "")
            }
        },
        |context| ("path", context.as_str()),
    );
    vec![
        mode.as_str().to_string(),
        cookie.to_string(),
        link_assistant_router::VERSION.to_string(),
        args.image.clone().unwrap_or_else(default_image),
        build_mode.to_string(),
        build_value.to_string(),
        args.root.clone().unwrap_or_default(),
        args.port().to_string(),
        args.public_port
            .map_or_else(String::new, |port| port.to_string()),
        public_name(args.server.as_deref().unwrap_or_default()),
    ]
}

fn mapped_exit_code(code: crate::translation_core::Maybe<i32>) -> ExitCode {
    match code {
        Some(0) => ExitCode::SUCCESS,
        Some(255) | None => ExitCode::from(TRANSPORT_EXIT),
        Some(AGENT_LEASE_EXIT) => ExitCode::from(LEASE_EXIT),
        Some(_) => ExitCode::from(1),
    }
}

fn mapped_exit(status: std::process::ExitStatus) -> ExitCode {
    mapped_exit_code(status.code())
}

const fn transported_secret(mode: RemoteMode, token_secret: &crate::translation_core::Str) -> &crate::translation_core::Str {
    if matches!(mode, RemoteMode::Deploy) {
        token_secret
    } else {
        ""
    }
}

fn validate(args: &DeployArgs, mode: RemoteMode) -> crate::translation_core::Outcome<(), String> {
    let target = args
        .server
        .as_deref()
        .filter(|target| !target.trim().is_empty())
        .ok_or("an SSH target is required")?;
    if target.contains(['\n', '\r', '\0']) {
        return Err("the SSH target contains an invalid character".to_string());
    }
    if args
        .root
        .as_deref()
        .is_some_and(|root| root.contains(['\n', '\r', '\0']))
        || args
            .build
            .as_deref()
            .is_some_and(|path| path.contains(['\n', '\r', '\0']))
    {
        return Err("a remote path contains an invalid character".to_string());
    }
    if mode == RemoteMode::Deploy {
        link_assistant_router::deploy::immutable_ref(
            args.image.as_deref().unwrap_or(&default_image()),
        )?;
    }
    Ok(())
}

/// Settings resolved for one run: values, the pinned host keys, the payload.
struct Prepared {
    values: Option<ResolvedDeploy>,
    known_hosts: Option<tempfile::NamedTempFile>,
    payload: Option<String>,
    seeds: Vec<link_assistant_router::deploy_seed::Seed>,
}

fn prepare(
    args: &DeployArgs,
    mode: RemoteMode,
    token_secret: &crate::translation_core::Str,
    merged: &Merged,
) -> crate::translation_core::Outcome<Prepared, String> {
    // Only a deploy reads values: `--status` and `--down` must work even
    // when a variable the deploy passes through is unset here.
    let values = if mode == RemoteMode::Deploy {
        Some(merged.read_values()?)
    } else {
        None
    };
    let known_hosts = merged
        .known_hosts()?
        .map(|text| {
            session::pinned_known_hosts(&text)
                .map_err(|error| format!("could not write the pinned known_hosts file: {error}"))
        })
        .transpose()?;
    let seeds = if mode == RemoteMode::Deploy {
        seeding::prepare(
            merged,
            args.server.as_deref().unwrap_or_default(),
            token_secret,
        )?
    } else {
        Vec::new()
    };
    let payload = session::payload(merged, values.as_ref(), args.json, token_secret, &seeds);
    Ok(Prepared {
        values,
        known_hosts,
        payload,
        seeds,
    })
}

/// Run the target-side deployment agent and preserve transport/lease identity.
#[allow(clippy::too_many_lines)]
fn run_with_ssh(args: &DeployArgs, token_secret: &crate::translation_core::Str, ssh: &OsStr, merged: &Merged) -> ExitCode {
    let mode = match mode(args).and_then(|mode| {
        validate(args, mode)?;
        Ok(mode)
    }) {
        Ok(mode) => mode,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(2);
        }
    };
    if mode == RemoteMode::Deploy
        && let Err(error) = link_assistant_router::token_secret::ensure_real(token_secret)
    {
        eprintln!("error: {error}");
        eprintln!(
            "note: the secret is sent through SSH stdin and is never copied into command arguments."
        );
        return ExitCode::from(2);
    }
    let prepared = match prepare(args, mode, token_secret, merged) {
        Ok(prepared) => prepared,
        Err(error) => {
            eprintln!("error: {error}");
            return ExitCode::from(2);
        }
    };
    let target = args.server.as_deref().expect("validated target");
    if let Err(error) = seeding::mark_pending(&prepared.seeds, target) {
        eprintln!("error: {error}");
        return ExitCode::from(2);
    }
    let cookie = uuid::Uuid::new_v4().simple().to_string();
    let remote = remote_command(
        &agent_arguments(args, mode, &cookie),
        prepared.payload.is_some(),
    );
    let mut command = crate::operation_context::command(ssh);
    command
        .args(["-o", "BatchMode=yes", "-o", "StrictHostKeyChecking=yes"])
        .args(session::ssh_options(
            &merged.ssh,
            prepared
                .known_hosts
                .as_ref()
                .map(tempfile::NamedTempFile::path),
        ))
        .args(["--", target, &remote])
        .stdin(Stdio::piped());
    // Seeding reads the target's answer from its event stream, so the
    // session is captured then too; without `--json` its output is echoed.
    if args.json || !prepared.seeds.is_empty() {
        command.stdout(Stdio::piped()).stderr(Stdio::piped());
    }
    let started = std::time::Instant::now();
    let mut child = match crate::operation_context::spawn_process(&mut command) {
        Ok(child) => child,
        Err(error) => {
            eprintln!("transport error: could not start OpenSSH: {error}");
            return ExitCode::from(TRANSPORT_EXIT);
        }
    };
    let collected = std::sync::Arc::new(std::sync::Mutex::new(session::Collected::default()));
    let readers: Vec<_> = [
        child.stdout.take().map(|stream| {
            let echo = if args.json {
                session::Echo::Keep
            } else {
                session::Echo::Stdout
            };
            session::collect(stream, collected.clone(), echo)
        }),
        child
            .stderr
            .take()
            .map(|stream| session::collect(stream, collected.clone(), session::Echo::Stderr)),
    ]
    .into_iter()
    .flatten()
    .collect();
    // Observation and removal do not need the signing secret at all. Besides
    // reducing exposure, this keeps the non-serving placeholder (which may
    // contain NUL) out of a shell variable on those paths.
    let encoded =
        base64::engine::general_purpose::STANDARD.encode(transported_secret(mode, token_secret));
    let payload = prepared.payload.clone();
    // Written from a thread so a session that never connects cannot block
    // the deadline on a full pipe.
    let writer = child.stdin.take().map(|mut stdin| {
        std::thread::spawn(move || -> std::io::Result<()> {
            writeln!(stdin, "{encoded}")?;
            if let Some(payload) = payload {
                writeln!(stdin, "{payload}")?;
            }
            stdin.write_all(AGENT.as_bytes())
        })
    });
    let deadline = merged
        .ssh
        .deadline_secs
        .map(std::time::Duration::from_secs)
        .or_else(|| crate::operation_context::current().map(|context| context.process_deadline));
    let waited = session::wait(&mut child, deadline);
    let write_result = writer.map_or_else(
        || Err(std::io::Error::other("SSH stdin was not available")),
        |writer| {
            writer
                .join()
                .unwrap_or_else(|_| Err(std::io::Error::other("stdin writer panicked")))
        },
    );
    for reader in readers {
        let _ = reader.join();
    }
    let (code, ssh_exit) = match waited {
        Ok(Some(status)) => {
            if let Err(error) = write_result
                && status.code() != Some(0)
            {
                eprintln!("transport error: could not send the deployment agent: {error}");
                (ExitCode::from(TRANSPORT_EXIT), status.code())
            } else {
                (mapped_exit(status), status.code())
            }
        }
        Ok(None) => {
            eprintln!(
                "deadline error: the deployment did not finish within {}s; the session was \
                 closed and the target rolls an unaccepted candidate back",
                merged.ssh.deadline_secs.unwrap_or_default()
            );
            (ExitCode::from(session::DEADLINE_EXIT), None)
        }
        Err(error) => {
            eprintln!("transport error: could not wait for OpenSSH: {error}");
            (ExitCode::from(TRANSPORT_EXIT), None)
        }
    };
    if code == ExitCode::from(TRANSPORT_EXIT) {
        eprintln!("transport error: the SSH connection to {target} failed");
    } else if code == ExitCode::from(LEASE_EXIT) {
        eprintln!("lease error: target ownership could not be proved safely");
    }
    let collected = collected
        .lock()
        .map(|mut collected| std::mem::take(&mut *collected))
        .unwrap_or_default();
    let seeded = seeding::settle(&prepared.seeds, target, &collected.events);
    if args.json {
        let exit_code = exit_number(code);
        let mut document = session::document(
            merged,
            prepared.values.as_ref(),
            token_secret,
            &collected,
            &session::Outcome {
                server: target,
                mode: mode.as_str(),
                exit_code,
                ssh_ms: started.elapsed().as_millis(),
                ssh_exit,
            },
        );
        if let Some(object) = document.as_object_mut() {
            object.insert("seed_credentials".into(), seeded.into());
        }
        println!(
            "{}",
            serde_json::to_string_pretty(&document).unwrap_or_default()
        );
    }
    code
}

fn exit_number(code: ExitCode) -> u8 {
    [0, 1, 2, TRANSPORT_EXIT, LEASE_EXIT, session::DEADLINE_EXIT]
        .into_iter()
        .find(|number| ExitCode::from(*number) == code)
        .unwrap_or(1)
}

/// Run the target-side deployment agent and preserve transport/lease identity.
#[must_use]
pub fn run(args: &DeployArgs, token_secret: &crate::translation_core::Str, merged: &Merged) -> ExitCode {
    run_with_ssh(args, token_secret, OsStr::new("ssh"), merged)
}

