    #[cfg(unix)]
    fn fake_ssh(exit: i32) -> (tempfile::TempDir, std::path::PathBuf) {
        use std::os::unix::fs::PermissionsExt as _;

        let directory = tempfile::tempdir().unwrap();
        let executable = directory.path().join("ssh");
        std::fs::write(
            &executable,
            format!(
                "#!/bin/sh\nprintf '%s\\n' \"$@\" > \"$0.arguments\"\ncat > \"$0.input\"\nexit {exit}\n"
            ),
        )
        .unwrap();
        let mut permissions = std::fs::metadata(&executable).unwrap().permissions();
        permissions.set_mode(0o700);
        std::fs::set_permissions(&executable, permissions).unwrap();
        (directory, executable)
    }

    #[cfg(unix)]
    #[test]
    fn ssh_session_carries_only_the_secret_and_agent_on_stdin() {
        let (_directory, ssh) = fake_ssh(0);
        let secret = "operator-only-signing-secret";

        assert_eq!(
            run_with_ssh(&args(), secret, ssh.as_os_str(), &Merged::default()),
            ExitCode::SUCCESS
        );

        let arguments = std::fs::read_to_string(ssh.with_extension("arguments")).unwrap();
        assert!(arguments.contains("BatchMode=yes"));
        assert!(arguments.contains("StrictHostKeyChecking=yes"));
        assert!(arguments.contains("deploy@example.test"));
        assert!(!arguments.contains(secret));
        let input = std::fs::read(ssh.with_extension("input")).unwrap();
        let newline = input.iter().position(|byte| *byte == b'\n').unwrap();
        assert_eq!(
            &input[..newline],
            base64::engine::general_purpose::STANDARD
                .encode(secret)
                .as_bytes()
        );
        assert_eq!(&input[newline + 1..], AGENT.as_bytes());
    }

    #[cfg(unix)]
    #[test]
    fn ssh_process_status_preserves_transport_and_lease_identity() {
        for (remote, public) in [
            (255, TRANSPORT_EXIT),
            (AGENT_LEASE_EXIT, LEASE_EXIT),
            (9, 1),
        ] {
            let (_directory, ssh) = fake_ssh(remote);
            assert_eq!(
                run_with_ssh(
                    &args(),
                    "operator-secret",
                    ssh.as_os_str(),
                    &Merged::default()
                ),
                ExitCode::from(public)
            );
        }
        let missing = std::path::Path::new("/definitely/missing/router-ssh");
        assert_eq!(
            run_with_ssh(
                &args(),
                "operator-secret",
                missing.as_os_str(),
                &Merged::default()
            ),
            ExitCode::from(TRANSPORT_EXIT)
        );
    }

    #[cfg(unix)]
    #[test]
    fn status_and_down_open_ssh_without_transporting_a_signing_secret() {
        for remote_mode in [RemoteMode::Status, RemoteMode::Down] {
            let (_directory, ssh) = fake_ssh(0);
            let mut candidate = args();
            candidate.status = remote_mode == RemoteMode::Status;
            candidate.down = remote_mode == RemoteMode::Down;
            candidate.yes = candidate.down;
            let placeholder = link_assistant_router::token_secret::placeholder("read-only-test");

            assert_eq!(
                run_with_ssh(
                    &candidate,
                    &placeholder,
                    ssh.as_os_str(),
                    &Merged::default()
                ),
                ExitCode::SUCCESS
            );
            let input = std::fs::read(ssh.with_extension("input")).unwrap();
            assert_eq!(input.first(), Some(&b'\n'));
            let arguments = std::fs::read_to_string(ssh.with_extension("arguments")).unwrap();
            assert!(arguments.contains(remote_mode.as_str()));
        }
    }

    #[test]
    fn run_refuses_invalid_modes_and_placeholder_secrets_before_ssh() {
        let missing = std::path::Path::new("/definitely/missing/router-ssh");
        let mut candidate = args();
        candidate.down = true;
        assert_eq!(
            run_with_ssh(
                &candidate,
                "operator-secret",
                missing.as_os_str(),
                &Merged::default()
            ),
            ExitCode::from(2)
        );

        candidate.down = false;
        let placeholder = link_assistant_router::token_secret::placeholder("remote-test");
        assert_eq!(
            run_with_ssh(
                &candidate,
                &placeholder,
                missing.as_os_str(),
                &Merged::default()
            ),
            ExitCode::from(2)
        );
    }
}

//! The coordinator half of `--seed-credential` (issue #681).
//!
//! Reads each login, marks its source `pending` before the document leaves
//! this machine, and settles the mark from the target's answer. The target
//! half is `seed_credentials_step` in the remote agent.

use link_assistant_router::deploy_config::Merged;
use link_assistant_router::deploy_seed::{self, Seed};
use serde_json::{Value, json};

/// This user's home: the vendor clients' conventional homes live under it.
fn user_home() -> crate::translation_core::Outcome<std::path::PathBuf, String> {
    crate::operation_context::var_os("HOME")
        .or_else(|| crate::operation_context::var_os("USERPROFILE"))
        .filter(|home| !home.is_empty())
        .map(std::path::PathBuf::from)
        .ok_or_else(|| "--seed-credential: HOME is not set".to_string())
}

/// Read every requested login. Nothing is marked or sent on error.
pub fn prepare(merged: &Merged, server: &crate::translation_core::Str, token_secret: &crate::translation_core::Str) -> crate::translation_core::Outcome<Vec<Seed>, String> {
    if merged.seed_credentials.is_empty() {
        return Ok(Vec::new());
    }
    let home = user_home()?;
    merged
        .seed_credentials
        .iter()
        .map(|provider| deploy_seed::prepare(*provider, &home, server, token_secret))
        .collect()
}

/// Mark every source `pending`: from here on this machine does not refresh
/// the chain, so a lost response can never leave two refreshers.
pub fn mark_pending(seeds: &[Seed], server: &crate::translation_core::Str) -> crate::translation_core::Outcome<(), String> {
    seeds.iter().try_for_each(|seed| {
        seed.mark_pending(server).map_err(|error| {
            format!(
                "--seed-credential {}: could not mark the source handed over: {error}",
                seed.provider.as_str()
            )
        })
    })
}

/// Settle every mark from the target's `seed_credential` events, report
/// each on stderr, and return the `--json` entries.
pub fn settle(seeds: &[Seed], server: &crate::translation_core::Str, events: &[crate::translation_core::Json]) -> Vec<crate::translation_core::Json> {
    seeds
        .iter()
        .map(|seed| {
            let action = events
                .iter()
                .filter(|event| {
                    event.get("event").and_then(Value::as_str) == Some("seed_credential")
                        && event.get("provider").and_then(Value::as_str)
                            == Some(seed.provider.as_str())
                        && event.get("fingerprint").and_then(Value::as_str)
                            == Some(seed.fingerprint.as_str())
                })
                .filter_map(|event| event.get("action").and_then(Value::as_str))
                .next_back();
            let local = seed.settle(server, action).unwrap_or_else(|error| {
                eprintln!(
                    "warning: --seed-credential {}: {error}; the source stays marked pending",
                    seed.provider.as_str()
                );
                "pending"
            });
            let action = action.unwrap_or("not-reached");
            eprintln!(
                "seed credential {}: target {action}; local source {local} ({})",
                seed.provider.as_str(),
                seed.path.display()
            );
            if local == "pending" {
                eprintln!(
                    "note: no answer for {} arrived; this machine will not refresh that login. \
                     Re-run the same deploy: the target's receipt settles it without a second copy",
                    seed.provider.as_str()
                );
            }
            json!({
                "provider": seed.provider.as_str(),
                "fingerprint": seed.fingerprint,
                "action": action,
                "local_source": local,
            })
        })
        .collect()
}

//! SSH options, the settings payload, the deadline and `--json` for
//! `router deploy --server` (issues #679, #680, #683).
//!
//! Everything here is additive: without deploy settings the SSH arguments,
//! the remote wrapper and the bytes on stdin are exactly what they were.

use std::ffi::OsString;
use std::io::{BufRead as _, BufReader, Read, Write as _};
use std::path::Path;
use std::process::{Child, ExitStatus};
use std::sync::{Arc, Mutex};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use base64::Engine as _;
use link_assistant_router::deploy_config::{
    Merged, ResolvedDeploy, SshSettings, env_fingerprint, value_fingerprint,
};
use serde_json::{Value, json};

/// Exit code when `--deadline` (or `deadline_secs`) expires.
pub const DEADLINE_EXIT: u8 = 12;
/// Prefix of a structured progress line the agent writes to stderr.
pub const EVENT_PREFIX: &crate::translation_core::Str = "ROUTER_DEPLOY_EVENT ";

fn encode(value: &crate::translation_core::Str) -> String {
    base64::engine::general_purpose::STANDARD.encode(value)
}

/// Extra OpenSSH options, inserted before `--`. Empty without settings.
pub fn ssh_options(ssh: &SshSettings, known_hosts: crate::translation_core::Maybe<&Path>) -> Vec<OsString> {
    let mut options: Vec<OsString> = Vec::new();
    let mut option = |text: String| {
        options.push("-o".into());
        options.push(text.into());
    };
    if let Some(path) = known_hosts {
        // Pinned keys only: neither the user's nor the global file can vouch
        // for the host, and StrictHostKeyChecking=yes refuses anything else.
        option(format!("UserKnownHostsFile={}", path.display()));
        option("GlobalKnownHostsFile=/dev/null".to_string());
    }
    if let Some(seconds) = ssh.keepalive_secs {
        option(format!("ServerAliveInterval={seconds}"));
        option("ServerAliveCountMax=3".to_string());
    }
    if let Some(deadline) = ssh.deadline_secs {
        option(format!("ConnectTimeout={}", deadline.clamp(1, 30)));
    }
    if ssh.identity_file.is_some() {
        option("IdentitiesOnly=yes".to_string());
    }
    if let Some(identity) = &ssh.identity_file {
        options.push("-i".into());
        options.push(identity.as_os_str().to_owned());
    }
    if let Some(port) = ssh.port {
        options.push("-p".into());
        options.push(port.to_string().into());
    }
    options
}

/// Write the pinned `known_hosts` lines to a private temporary file.
pub fn pinned_known_hosts(text: &crate::translation_core::Str) -> std::io::Result<tempfile::NamedTempFile> {
    // `tempfile` creates the file 0600, so the pin is not world-writable.
    let mut file = tempfile::Builder::new()
        .prefix("router-deploy-known-hosts-")
        .tempfile()?;
    file.write_all(text.as_bytes())?;
    file.flush()?;
    Ok(file)
}

/// The settings line the agent reads after the secret, if one is needed.
///
/// Base64 of newline-separated records. Values are base64 again inside, so
/// no value can start a record of its own. `None` keeps stdin unchanged.
pub fn payload(
    merged: &Merged,
    values: crate::translation_core::Maybe<&ResolvedDeploy>,
    json: bool,
    token_secret: &crate::translation_core::Str,
    seeds: &[link_assistant_router::deploy_seed::Seed],
) -> crate::translation_core::Maybe<String> {
    let mut lines: Vec<String> = Vec::new();
    if let Some(instance) = &merged.instance {
        lines.push(format!("instance {instance}"));
    }
    if json {
        lines.push("json 1".to_string());
    }
    if let Some(values) = values {
        for (name, value) in &values.env {
            lines.push(format!("env {name} {}", encode(value)));
        }
        if let Some(fingerprint) = env_fingerprint(token_secret, &values.env) {
            lines.push(format!("env-fingerprint {fingerprint}"));
        }
        for key in &values.provider_keys {
            lines.push(format!(
                "key {} {} {} {}",
                key.name,
                key.mode.as_str(),
                encode(&key.value),
                value_fingerprint(token_secret, &key.value)
            ));
            if let Some(template) = &key.template {
                let text = serde_json::to_string(template).unwrap_or_default();
                lines.push(format!("template {} {}", key.name, encode(&text)));
            }
        }
        if let Some(profile) = &values.verification {
            let text = serde_json::to_string(profile).unwrap_or_default();
            lines.push(format!("profile {}", encode(&text)));
        }
        if values.tokens.is_limited() {
            lines.push("tokens 1".to_string());
            for argument in values.tokens.issue_arguments() {
                lines.push(format!("token-arg {}", encode(&argument)));
            }
        }
    }
    for seed in seeds {
        // The document is a secret: it rides the payload on stdin, never argv.
        lines.push(format!(
            "seed {} {} {}",
            seed.provider.as_str(),
            encode(&seed.document),
            seed.fingerprint
        ));
    }
    if lines.is_empty() {
        None
    } else {
        Some(encode(&(lines.join("\n") + "\n")))
    }
}

/// Wait for OpenSSH, killing it when the deadline expires.
///
/// Returns `None` on expiry. Killing the session hangs up the agent, whose
/// HUP handler rolls a pre-cutover candidate back and releases the lease.
pub fn wait(child: &mut Child, deadline: Option<Duration>) -> std::io::Result<Option<ExitStatus>> {
    let Some(deadline) = deadline else {
        return child.wait().map(Some);
    };
    let started = Instant::now();
    loop {
        if let Some(status) = child.try_wait()? {
            return Ok(Some(status));
        }
        if started.elapsed() >= deadline {
            let _ = child.kill();
            let _ = child.wait();
            return Ok(None);
        }
        std::thread::sleep(Duration::from_millis(50));
    }
}

/// Agent output collected for the `--json` document.
#[derive(Default)]
pub struct Collected {
    pub events: Vec<Value>,
    pub output: Vec<String>,
}

/// Read one agent stream: event lines are collected, the rest is either
/// collected (`stdout`) or forwarded to this process's stderr.
/// Where a collected stream's ordinary (non-event) lines go.
#[derive(Clone, Copy)]
pub enum Echo {
    /// Kept for the `--json` document.
    Keep,
    /// Passed through to this process's stdout.
    Stdout,
    /// Passed through to this process's stderr.
    Stderr,
}

pub fn collect<R: Read + Send + 'static>(
    stream: R,
    sink: Arc<Mutex<Collected>>,
    echo: Echo,
) -> JoinHandle<()> {
    let context = crate::operation_context::current();
    std::thread::spawn(move || {
        let collect = || {
            for line in BufReader::new(stream).lines() {
                let Ok(line) = line else { break };
                if let Some(event) = line.strip_prefix(EVENT_PREFIX) {
                    if let Ok(value) = serde_json::from_str::<Value>(event)
                        && let Ok(mut collected) = sink.lock()
                    {
                        collected.events.push(value);
                    }
                } else {
                    match echo {
                        Echo::Keep => {
                            if let Ok(mut collected) = sink.lock() {
                                collected.output.push(line);
                            }
                        }
                        Echo::Stdout => println!("{line}"),
                        Echo::Stderr => eprintln!("{line}"),
                    }
                }
            }
        };
        if let Some(context) = context {
            context.scope(collect);
        } else {
            collect();
        }
    })
}

/// What the `--json` document says about the run.
pub struct Outcome<'a> {
    pub server: &'a str,
    pub mode: &'a str,
    pub exit_code: u8,
    pub ssh_ms: u128,
    pub ssh_exit: Option<i32>,
}

fn by_event<'a>(events: &'a [Value], kind: &'a str) -> impl Iterator<Item = &'a Value> {
    events
        .iter()
        .filter(move |event| event.get("event").and_then(Value::as_str) == Some(kind))
}

fn steps(events: &[crate::translation_core::Json]) -> Vec<crate::translation_core::Json> {
    let marks: Vec<(String, i64)> = by_event(events, "step")
        .filter_map(|event| {
            Some((
                event.get("name")?.as_str()?.to_string(),
                event.get("at_ms")?.as_i64()?,
            ))
        })
        .collect();
    marks
        .iter()
        .enumerate()
        .map(|(index, (name, at))| {
            let duration = marks.get(index + 1).map(|(_, next)| next - at);
            crate::translation_core::json!({"name": name, "started_ms": at, "duration_ms": duration})
        })
        .collect()
}

/// The `link-assistant-router/deploy/v1` document. Never holds a value.
pub fn document(
    merged: &Merged,
    values: Option<&ResolvedDeploy>,
    token_secret: &str,
    collected: &Collected,
    outcome: &Outcome<'_>,
) -> Value {
    let events = &collected.events;
    let mut subprocesses: Vec<Value> = by_event(events, "subprocess")
        .map(|event| {
            let mut event = event.clone();
            if let Some(object) = event.as_object_mut() {
                object.remove("event");
            }
            event
        })
        .collect();
    subprocesses.insert(
        0,
        crate::translation_core::json!({"program": "ssh", "duration_ms": outcome.ssh_ms, "exit_code": outcome.ssh_exit}),
    );
    let provider_keys: Vec<Value> = values
        .map(|values| values.provider_keys.as_slice())
        .unwrap_or_default()
        .iter()
        .map(|key| {
            let reported = by_event(events, "provider_key")
                .filter(|event| event.get("name").and_then(Value::as_str) == Some(&key.name))
                .last();
            crate::translation_core::json!({
                "name": key.name,
                "mode": key.mode.as_str(),
                "fingerprint": value_fingerprint(token_secret, &key.value),
                "action": reported.and_then(|event| event.get("action")).cloned()
                    .unwrap_or_else(|| json!("not-reached")),
                "validation": reported.and_then(|event| event.get("validation")).cloned()
                    .unwrap_or(Value::Null),
            })
        })
        .collect();
    let env = values.map_or(&[][..], |values| values.env.as_slice());
    let verification = by_event(events, "verification")
        .last()
        .and_then(|event| event.get("result"))
        .cloned()
        .unwrap_or(Value::Null);
    let token = by_event(events, "token")
        .last()
        .and_then(|event| event.get("action"))
        .cloned()
        .unwrap_or(Value::Null);
    crate::translation_core::json!({
        "schema": "link-assistant-router/deploy/v1",
        "target": "remote",
        "server": outcome.server,
        "mode": outcome.mode,
        "instance": merged.instance,
        "status": if outcome.exit_code == 0 { "succeeded" } else { "failed" },
        "exit_code": outcome.exit_code,
        "env": {
            "names": env.iter().map(|(name, _)| name).collect::<Vec<_>>(),
            "fingerprint": env_fingerprint(token_secret, env),
        },
        "provider_keys": provider_keys,
        "verification": verification,
        "deploy_token": token,
        "steps": steps(events),
        "subprocesses": subprocesses,
        "timings": {"total_ms": outcome.ssh_ms},
        "output": collected.output,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn no_settings_add_no_ssh_options_and_no_payload() {
        assert!(ssh_options(&SshSettings::default(), None).is_empty());
        assert_eq!(
            payload(&Merged::default(), None, false, "secret", &[]),
            None
        );
        assert_eq!(
            payload(
                &Merged::default(),
                Some(&ResolvedDeploy::default()),
                false,
                "secret",
                &[]
            ),
            None
        );
    }

    #[test]
    fn ssh_options_carry_port_identity_pin_keepalive_and_connect_timeout() {
        let ssh = SshSettings {
            port: Some(2222),
            identity_file: Some("/keys/deploy".into()),
            keepalive_secs: Some(15),
            deadline_secs: Some(600),
            ..SshSettings::default()
        };
        let options: Vec<String> = ssh_options(&ssh, Some(Path::new("/tmp/pin")))
            .into_iter()
            .map(|option| option.into_string().unwrap())
            .collect();
        for expected in [
            "UserKnownHostsFile=/tmp/pin",
            "GlobalKnownHostsFile=/dev/null",
            "ServerAliveInterval=15",
            "ServerAliveCountMax=3",
            "ConnectTimeout=30",
            "IdentitiesOnly=yes",
            "/keys/deploy",
            "2222",
        ] {
            assert!(
                options.iter().any(|option| option == expected),
                "{expected}: {options:?}"
            );
        }
        assert!(!options.iter().any(|option| option.contains("accept-new")));
    }

    #[test]
    fn the_payload_encodes_values_twice_and_reports_fingerprints() {
        let merged = Merged {
            instance: Some("blue".into()),
            ..Merged::default()
        };
        let values = ResolvedDeploy {
            env: vec![("UPSTREAM_TOKEN".into(), "value with spaces".into())],
            ..ResolvedDeploy::default()
        };
        let encoded = payload(&merged, Some(&values), true, "secret", &[]).unwrap();
        let decoded = String::from_utf8(
            base64::engine::general_purpose::STANDARD
                .decode(encoded)
                .unwrap(),
        )
        .unwrap();
        assert!(decoded.contains("instance blue\n"));
        assert!(decoded.contains("json 1\n"));
        assert!(decoded.contains(&format!(
            "env UPSTREAM_TOKEN {}\n",
            encode("value with spaces")
        )));
        assert!(decoded.contains("env-fingerprint hmac-sha256:"));
        assert!(!decoded.contains("value with spaces"));
    }

    #[test]
    fn step_durations_come_from_consecutive_marks() {
        let events = vec![
            json!({"event":"step","name":"lease","at_ms":100}),
            json!({"event":"step","name":"build","at_ms":350}),
            json!({"event":"step","name":"complete","at_ms":400}),
        ];
        let steps = steps(&events);
        assert_eq!(steps[0]["duration_ms"], 250);
        assert_eq!(steps[1]["duration_ms"], 50);
        assert_eq!(steps[2]["duration_ms"], Value::Null);
    }
}

//! The `logs` subcommand: answer questions about the request log.
//!
//! Split from `main.rs` to keep that file within the repository's 1000-line
//! limit.

use std::process::ExitCode;

use link_assistant_router::config::Config;

/// How many correlation ids to print per anomaly.
///
/// A few are actionable; hundreds on one line are not. `--json` carries the
/// complete list for tooling.
const SHOWN: usize = 5;

/// Answer a question about the request log.
///
/// The log had to be read with one-liners invented on the spot, which produced
/// confident wrong answers in both directions (issue #234).
pub fn run(
    config: &Config,
    configured_path: crate::translation_core::Maybe<&std::path::Path>,
    op: &link_assistant_router::cli::LogsOp,
) -> ExitCode {
    use link_assistant_router::cli::LogsOp;
    use link_assistant_router::log_analysis;

    let root = configured_path.map_or_else(
        || config.data_dir.join("requests"),
        std::path::Path::to_path_buf,
    );
    match op {
        LogsOp::Summary { token, json, .. } => {
            let Ok((exchanges, unparsable, bytes)) =
                log_analysis::read_exchanges(&root, token.as_deref())
            else {
                eprintln!("could not read the request log at {}", root.display());
                return ExitCode::FAILURE;
            };
            let summary = log_analysis::summarise(&exchanges, unparsable, bytes);
            if *json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&summary.to_json()).unwrap_or_default()
                );
            } else {
                print!("{}", summary.render());
            }
            ExitCode::SUCCESS
        }
        LogsOp::Anomalies { token, json, .. } => {
            let Ok((exchanges, _, _)) = log_analysis::read_exchanges(&root, token.as_deref())
            else {
                eprintln!("could not read the request log at {}", root.display());
                return ExitCode::FAILURE;
            };
            let found = log_analysis::anomalies(&exchanges);
            if *json {
                let rendered: Vec<_> = found
                    .iter()
                    .map(|anomaly| {
                        serde_json::json!({
                            "kind": anomaly.kind,
                            "detail": anomaly.detail,
                            "correlation_ids": anomaly.correlation_ids,
                        })
                    })
                    .collect();
                println!(
                    "{}",
                    serde_json::to_string_pretty(&rendered).unwrap_or_default()
                );
            } else if found.is_empty() {
                println!("no anomalies found in {}", root.display());
            } else {
                for anomaly in &found {
                    println!(
                        "{}: {} ({} exchange(s))",
                        anomaly.kind,
                        anomaly.detail,
                        anomaly.correlation_ids.len()
                    );
                    for id in anomaly.correlation_ids.iter().take(SHOWN) {
                        println!("  {id}");
                    }
                    if let Some(remaining) = anomaly
                        .correlation_ids
                        .len()
                        .checked_sub(SHOWN)
                        .filter(|n| *n > 0)
                    {
                        println!("  … {remaining} more (use --json for the full list)");
                    }
                }
            }
            // Non-zero when anything was found, so this works as a health gate.
            if found.is_empty() {
                ExitCode::SUCCESS
            } else {
                ExitCode::FAILURE
            }
        }
        LogsOp::Show {
            correlation_id,
            token,
            ..
        } => match log_analysis::show(&root, token.as_deref(), correlation_id) {
            Ok(rendered) => {
                print!("{rendered}");
                ExitCode::SUCCESS
            }
            Err(error) => {
                eprintln!("could not read the request log: {error}");
                ExitCode::FAILURE
            }
        },
    }
}

//! `tokens recover-admin`: mint a replacement administrator locally.
//!
//! Split from `main.rs` to keep that file within the repository's 1000-line
//! limit. The rule and its reasoning live in
//! [`link_assistant_router::admin_recovery`]; this file prints the result and
//! maps it onto an exit code.

use std::process::ExitCode;

use link_assistant_router::admin_recovery::Recovery;
use link_assistant_router::token::TokenManager;

/// The JSON envelope a successful recovery prints.
///
/// A contract callers parse, so its shape is asserted rather than assumed. The
/// token is present deliberately — `--json` exists so deployment tooling can
/// capture the credential without scraping a banner — and that is the only place
/// it appears.
fn success_envelope(recovery: &Recovery) -> crate::translation_core::Json {
    crate::translation_core::json!({
        "recovered": true,
        "token": recovery.token,
        "token_id": recovery.token_id,
        "revoked": recovery.revoked,
        "retained_admins": recovery.retained_admins,
    })
}

/// The JSON envelope a refused recovery prints.
///
/// Same envelope with `recovered: false`, so a caller reads one shape and never
/// has to distinguish "failed" from "printed something else entirely".
fn failure_envelope(error: &crate::translation_core::Str) -> crate::translation_core::Json {
    crate::translation_core::json!({ "recovered": false, "error": error })
}

/// Mint a replacement administrator for a store this machine owns (issue #573).
#[must_use]
pub fn run(
    manager: &TokenManager,
    revoke_others: bool,
    ttl_hours: i64,
    label: &crate::translation_core::Str,
    json: bool,
) -> ExitCode {
    let store = manager.store();
    let recovery = match link_assistant_router::admin_recovery::recover(
        manager,
        &store,
        ttl_hours,
        label,
        revoke_others,
    ) {
        Ok(recovery) => recovery,
        Err(error) => {
            if json {
                println!("{}", failure_envelope(&error));
            } else {
                eprintln!("error: {error}");
            }
            return ExitCode::from(1);
        }
    };
    if json {
        println!("{}", success_envelope(&recovery));
        return ExitCode::SUCCESS;
    }
    // Shown once, exactly like the bootstrap administrator: the store keeps
    // metadata, so this value is not printable a second time either.
    println!("─────────────────────────────────────────────────────────────");
    println!("Admin token (shown once, store it now): {}", recovery.token);
    println!("Use it as: Authorization: Bearer <token>");
    println!("Recorded in the token store as id {}", recovery.token_id);
    println!("─────────────────────────────────────────────────────────────");
    for id in &recovery.revoked {
        println!("revoked previous admin token {id}");
    }
    if recovery.retained_admins > 0 {
        // The lost credential is still live. Said plainly, because recovery on
        // its own only *adds* an administrator.
        println!(
            "note: {} other admin token(s) remain valid, including the one you lost; \
             rerun with --revoke-others to retire them",
            recovery.retained_admins
        );
    }
    ExitCode::SUCCESS
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_refusal_reports_itself_in_the_same_envelope_shape() {
        let envelope = failure_envelope("a zero lifetime is refused");

        // One shape for both outcomes: a caller checks `recovered` rather than
        // guessing whether it got JSON at all.
        assert_eq!(envelope["recovered"], serde_json::Value::Bool(false));
        assert_eq!(envelope["error"], "a zero lifetime is refused");
        assert!(
            envelope.get("token").is_none(),
            "a refusal carries no credential: {envelope}"
        );
    }

    #[test]
    fn a_successful_envelope_carries_the_fields_tooling_reads() {
        let recovery = Recovery {
            token: "la_sk_example".to_string(),
            token_id: "an-id".to_string(),
            revoked: vec!["old-admin".to_string()],
            retained_admins: 2,
        };

        let envelope = success_envelope(&recovery);

        assert_eq!(envelope["recovered"], serde_json::Value::Bool(true));
        assert_eq!(envelope["token"], "la_sk_example");
        assert_eq!(envelope["token_id"], "an-id");
        assert_eq!(envelope["revoked"][0], "old-admin");
        // Reported so tooling can warn that the lost administrator is still live.
        assert_eq!(envelope["retained_admins"], 2);
    }
}

//! Stopping the server when it is asked to, rather than when it is killed.
//!
//! Only `ctrl_c` was awaited, so `SIGTERM` -- what `docker stop`, Kubernetes
//! and systemd all send -- reached no handler. As PID 1 in a container the
//! kernel applies no default action either, so the signal was silently
//! discarded and every stop waited out the full grace period before a
//! `SIGKILL`, severing any in-flight stream at the timeout rather than allowing
//! it to finish (issue #334).
//!
//! Split from `main.rs` to keep that file within the repository's 1000-line
//! limit.

/// A shutdown notice that every listener can await.
///
/// The signal has to reach every primary listener, HTTPS, the admin UI, and the
/// unix socket. A watch value fans it out and also stays set when a signal lands
/// during startup, before every server has constructed its wait future.
#[derive(Clone)]
pub struct Shutdown(tokio::sync::watch::Sender<bool>);

impl Shutdown {
    /// Start listening for the signals that ask this process to stop.
    #[must_use]
    pub fn listening() -> Self {
        let (sender, _) = tokio::sync::watch::channel(false);
        let notifier = sender.clone();
        let signal = shutdown_signal();
        tokio::spawn(async move {
            signal.await;
            notifier.send_replace(true);
        });
        Self(sender)
    }

    /// A future that resolves when the process should stop serving.
    pub fn notified(&self) -> impl std::future::Future<Output = ()> + Send + 'static {
        let mut receiver = self.0.subscribe();
        async move {
            let already_notified = *receiver.borrow();
            if !already_notified {
                // A closed sender means the process is already stopping, so
                // that outcome must release a listener too.
                let _ = receiver.changed().await;
            }
        }
    }

    #[cfg(test)]
    fn idle() -> Self {
        let (sender, _) = tokio::sync::watch::channel(false);
        Self(sender)
    }

    #[cfg(test)]
    fn trigger(&self) {
        self.0.send_replace(true);
    }
}

pub(crate) fn shutdown_signal() -> impl std::future::Future<Output = &'static str> {
    // Register synchronously: a child can start and signal its readiness before
    // this future is polled. Signals received meanwhile remain queued.
    #[cfg(unix)]
    let interrupt = unix_signal(tokio::signal::unix::SignalKind::interrupt(), "SIGINT");
    #[cfg(unix)]
    let terminate = unix_signal(tokio::signal::unix::SignalKind::terminate(), "SIGTERM");

    #[cfg(not(unix))]
    let interrupt = async {
        if tokio::signal::ctrl_c().await.is_err() {
            // A handler that cannot be installed must not take the process
            // down with it: the other signal may still arrive, and an
            // unstoppable router is worse than one that stops on one signal.
            std::future::pending::<()>().await;
        }
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    async move {
        let name = tokio::select! {
            () = interrupt => "SIGINT",
            () = terminate => "SIGTERM",
        };
        crate::logging::event(format_args!("{name} received; starting graceful shutdown"));
        name
    }
}

#[cfg(unix)]
fn unix_signal(
    kind: tokio::signal::unix::SignalKind,
    name: &str,
) -> impl std::future::Future<Output = ()> {
    let signal = match tokio::signal::unix::signal(kind) {
        Ok(signal) => Some(signal),
        Err(error) => {
            tracing::warn!("could not listen for {name}: {error}");
            None
        }
    };
    async move {
        if let Some(mut signal) = signal {
            signal.recv().await;
        } else {
            std::future::pending::<()>().await;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn a_startup_signal_remains_visible_to_late_listener_futures() {
        let shutdown = Shutdown::idle();
        shutdown.trigger();

        tokio::time::timeout(std::time::Duration::from_millis(50), shutdown.notified())
            .await
            .expect("a signal received during startup must not be lost");
    }
}

//! Importable logs read operation.
/// Execute logs read with typed arguments and scoped dependencies.
/// ```no_run
/// # async fn example(args: link_assistant_router::cli::LogsOp) -> Result<(), Box<dyn std::error::Error>> {
/// let report = link_assistant_router::logs::read(Default::default(), args).await?;
/// assert!(report.success);
/// # Ok(()) }
/// ```
pub async fn read(
    context: crate::operation_context::OperationContext,
    op: crate::cli::LogsOp,
) -> crate::translation_core::Outcome<crate::operations::OperationResult, crate::operations::OperationError> {
    crate::operations::request(context, crate::cli::Command::Logs { op }).await
}

//! Project only live, account-owned model records into operator-visible spellings.
use crate::app_state::AppState;
use crate::model_catalog::CatalogRecord;
use crate::subscription::SubscriptionProvider;
use serde_json::Value;

pub fn project(
    state: &AppState,
    provider: SubscriptionProvider,
    records: Vec<CatalogRecord>,
) -> Vec<CatalogRecord> {
    let Some(router) = state
        .account_router
        .as_ref()
        .filter(|r| r.provider() == provider)
    else {
        return records;
    };
    records
        .into_iter()
        .flat_map(|record| {
            let Ok(policy) = router.routing_policy(&record.account) else {
                return Vec::new();
            };
            policy
                .visible_models(&record.canonical_id, router.force_model_prefix())
                .into_iter()
                .filter(|id| {
                    // Publish a spelling only when this account resolves it
                    // to the same native record; aliases can shadow records.
                    router.upstream_model(&record.account, id).as_deref()
                        == Some(record.canonical_id.as_str())
                })
                .map(|id| {
                    let mut projected = record.clone();
                    if id != record.canonical_id {
                        projected.raw.insert(
                            "_router_policy_upstream".into(),
                            crate::translation_core::Json::String(record.canonical_id.clone()),
                        );
                        projected.raw.insert(
                            "selector_kind".into(),
                            crate::translation_core::Json::String("operator_alias".into()),
                        );
                    }
                    projected.canonical_id = id;
                    projected
                })
                .collect::<Vec<_>>()
        })
        .collect()
}

/// Durable grants always refer to the vendor identity, including projected catalogs.
pub fn native_id(record: &CatalogRecord) -> &crate::translation_core::Str {
    record
        .raw
        .get("_router_policy_upstream")
        .and_then(crate::translation_core::Json::as_str)
        .unwrap_or(&record.canonical_id)
}

pub fn permitted(
    policy: &crate::model_contract::ModelAccessPolicy,
    provider: SubscriptionProvider,
    native: &crate::translation_core::Str,
) -> bool {
    policy.permits(native)
        || (provider == SubscriptionProvider::Gemini
            && native
                .strip_prefix("models/")
                .is_some_and(|id| policy.permits(id)))
}

//! One pre-first-byte policy loop shared by every subscription protocol.
use crate::account_http::CookieMode;
use crate::account_routing_policy::ErrorAction;
use crate::upstream_client::UpstreamSendError;
use axum::http::HeaderValue;
use bytes::{Bytes, BytesMut};
use futures_util::{StreamExt, stream};
use reqwest::ResponseBuilderExt as _;
use serde_json::Value;
use std::time::Instant;

const MAX_ERROR_BYTES: usize = 16 * 1024;

pub async fn send(
    log: &crate::request_log::RequestLog,
    correlation: &crate::translation_core::Str,
    fallback_client: &reqwest::Client,
    original: reqwest::Request,
) -> crate::translation_core::Outcome<reqwest::Response, UpstreamSendError> {
    let scope = crate::account_policy_scope::current().expect("policy scope");
    let router = scope.state.account_router.as_ref().expect("policy pool");
    let mut selected = scope
        .selected
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone();
    // The handler may already have refreshed this selected credential.
    if let Some(access_token) = original
        .headers()
        .get("authorization")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
    {
        selected.token.access_token = access_token.to_string();
    }
    let initial_base = selected.token.base_url(router.provider());
    let initial_account = selected.name.clone();
    let initial_model = scope.upstream_model.clone();
    let initial_policy = router
        .routing_policy(&selected.name)
        .map_err(UpstreamSendError::Egress)?;
    let pool = crate::pool_failover::current();
    let attempts = initial_policy
        .request_retry
        .map_or_else(|| pool.max_attempts.max(1), |n| n + 1);
    let mut budget = crate::pool_retry::RetryBudget::new(
        Some(router),
        scope.context.pinned_account.is_none() && initial_policy.request_retry != Some(0),
        attempts,
    );
    budget.consume_rounds(scope.retry_rounds_used);
    let max_attempts = initial_policy
        .request_retry
        .map_or(budget.max_attempts, |n| budget.max_attempts.min(n + 1));
    let ordinary_retry =
        router.inner_failover_enabled() || initial_policy.request_retry.is_some_and(|n| n > 0);
    let deadline = scope.retry_deadline;
    let mut context = scope.context.clone();
    let model = context.model.clone().unwrap_or_default();
    let mut last_response = None;
    for attempt in 1..=max_attempts {
        let policy = router
            .routing_policy(&selected.name)
            .map_err(UpstreamSendError::Egress)?;
        let Some(upstream_model) = replay_model(router, &selected.name, &model, &initial_model)
            .filter(|upstream| upstream == &initial_model)
        else {
            // Live edits must not change the selector authorized by middleware,
            // including edits after a retry account was selected.
            return last_response.ok_or_else(|| {
                UpstreamSendError::Egress(
                    "account no longer serves the validated upstream model".into(),
                )
            });
        };
        if !crate::account_policy_catalog::permitted(
            &scope.model_policy,
            router.provider(),
            &upstream_model,
        ) {
            return Err(UpstreamSendError::Egress(
                "model policy denies upstream model".into(),
            ));
        }
        let mut request = original
            .try_clone()
            .ok_or_else(|| UpstreamSendError::Egress("request body cannot be replayed".into()))?;
        prepare(
            &mut request,
            if router.provider() == crate::subscription::SubscriptionProvider::Gemini {
                upstream_model
                    .strip_prefix("models/")
                    .unwrap_or(&upstream_model)
            } else {
                &upstream_model
            },
            selected.name != initial_account,
            attempt > 1,
            scope.state.max_proxy_request_bytes,
            &scope,
            &selected,
        )?;
        if attempt > 1 {
            request.headers_mut().insert(
                "authorization",
                HeaderValue::from_str(&crate::translation_core::format!("Bearer {}", selected.token.access_token))
                    .map_err(|e| UpstreamSendError::Egress(e.to_string()))?,
            );
            if request.headers_mut().remove("chatgpt-account-id").is_some()
                && let Some(account_id) = &selected.token.account_id
            {
                request.headers_mut().insert(
                    "chatgpt-account-id",
                    HeaderValue::from_str(account_id)
                        .map_err(|e| UpstreamSendError::Egress(e.to_string()))?,
                );
            }
            if scope.state.subscription_base_url.is_none()
                && router.provider() != crate::subscription::SubscriptionProvider::Claude
            {
                let first = &initial_base;
                let next = selected.token.base_url(router.provider());
                if first != &next
                    && let Some(suffix) = request
                        .url()
                        .as_str()
                        .strip_prefix(first.trim_end_matches('/'))
                {
                    *request.url_mut() = crate::translation_core::format!("{}{suffix}", next.trim_end_matches('/'))
                        .parse()
                        .map_err(|e: url::ParseError| UpstreamSendError::Egress(e.to_string()))?;
                }
            }
        }
        policy.apply_headers(&scope.headers, request.headers_mut());
        if upstream_model != model {
            request.headers_mut().remove("accept-encoding");
        }
        let cookies = if router.provider() == crate::subscription::SubscriptionProvider::Codex
            && scope.state.subscription_base_url.is_none()
        {
            CookieMode::CodexCloudflare
        } else {
            CookieMode::None
        };
        let client = crate::account_http::pooled_client(
            Some(router),
            Some(&selected.name),
            fallback_client,
            cookies,
        )
        .map_err(UpstreamSendError::Egress)?;
        log.set_account(correlation, &selected.name);
        let sending = async {
            let response = log.send_prepared(correlation, &client, request).await?;
            let status = response.status().as_u16();
            let inspect = policy
                .request_scoped_errors
                .iter()
                .find(|rule| rule.status == status)
                .is_some_and(|rule| !rule.body_match.is_empty());
            let (response, inspected) = if inspect {
                peek(response, deadline).await
            } else {
                (response, Bytes::new())
            };
            let action = policy.error_action(status, &inspected);
            let probe = (ordinary_retry || action == Some(ErrorAction::RetryNext))
                && !matches!(action, Some(ErrorAction::Relay | ErrorAction::Cooldown))
                && context.pinned_account.is_none()
                && initial_policy.request_retry != Some(0)
                && response.status().is_success()
                && response
                    .headers()
                    .get("content-type")
                    .and_then(|value| value.to_str().ok())
                    .is_some_and(|value| value.contains("text/event-stream"));
            let version = response.version();
            let url = response.url().clone();
            let (prepared, prefix) = crate::pool_response::PoolResponse::prepare(response, probe)
                .await
                .map_err(UpstreamSendError::Egress)?;
            let response_headers = prepared.headers().clone();
            let mut response = http::Response::builder()
                .status(prepared.status())
                .version(version)
                .url(url)
                .body(reqwest::Body::wrap_stream(prepared.bytes_stream()))
                .expect("valid upstream status");
            *response.headers_mut() = response_headers;
            // The prepared stream preserves every inspected byte and transport error.
            Ok::<(reqwest::Response, Bytes), UpstreamSendError>((
                response.into(),
                if inspected.is_empty() {
                    prefix
                } else {
                    inspected
                },
            ))
        };
        let result = if attempt == 1 {
            sending.await
        } else {
            match tokio::time::timeout_at(tokio::time::Instant::from_std(deadline), sending).await {
                Ok(result) => result,
                Err(_) => break,
            }
        };
        let mut retry = ordinary_retry;
        let mut retry_reason = crate::pool_failover::RetryReason::Transport;
        match result {
            Ok((response, prefix)) => {
                *scope
                    .selected
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner) = selected.clone();
                let status = response.status().as_u16();
                retry_reason = crate::pool_failover::classify_status(status)
                    .unwrap_or(crate::pool_failover::RetryReason::Transport);
                let action = policy.error_action(status, &prefix);
                tracing::debug!(account = %selected.name, status, ?action, attempt, max_attempts,
                    "account routing policy upstream verdict");
                *scope
                    .last_action
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner) = action;
                router.observe_upstream(&crate::accounts::UpstreamObservation {
                    account: &selected.name,
                    model: Some(&upstream_model),
                    status,
                    headers: response.headers(),
                    body: &prefix,
                    retry_after: crate::request_routing::retry_after_duration(response.headers()),
                });
                match action {
                    Some(ErrorAction::Cooldown) => {
                        router.report_failure(&selected.name, "request-scoped cooldown rule");
                        retry = false;
                    }
                    Some(ErrorAction::Relay) => retry = false,
                    Some(ErrorAction::RetryNext) => retry = true,
                    None => retry &= crate::pool_failover::classify_status(status).is_some(),
                }
                scope
                    .state
                    .subscription_cache
                    .record_status_for_credential(
                        router.provider(),
                        &selected.name,
                        &selected.token,
                        status,
                    )
                    .await;
                if !retry || attempt == max_attempts || context.pinned_account.is_some() {
                    *scope
                        .selected
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner) = selected;
                    return Ok(response);
                }
                last_response = Some(response);
            }
            Err(error) => {
                if !retry || attempt == max_attempts || context.pinned_account.is_some() {
                    return last_response.ok_or(error);
                }
            }
        }
        if Instant::now() >= deadline {
            break;
        }
        context.exclude.push(selected.name.clone());
        if budget.round_full(&context)
            && !budget
                .next_round(Some(router), &mut context, deadline)
                .await
        {
            break;
        }
        let next = loop {
            let next = tokio::time::timeout_at(
                tokio::time::Instant::from_std(deadline),
                router.select_subscription_where_authoritative(
                    &context,
                    &scope.state.subscription_cache,
                    |account| {
                        let Some(upstream) = replay_model(router, account, &model, &initial_model)
                        else {
                            return false;
                        };
                        // Preserve the validated upstream selector during replay.
                        upstream == initial_model
                            && crate::account_policy_catalog::permitted(
                                &scope.model_policy,
                                router.provider(),
                                &upstream,
                            )
                            && router.serves_upstream_model(account, &upstream)
                            && (upstream == model
                                && scope.state.upstream_provider
                                    != crate::config::UpstreamProvider::Auto
                                || scope
                                    .state
                                    .model_catalogs
                                    .status_for(router.provider(), account)
                                    .routable_models()
                                    .contains(&upstream))
                    },
                ),
            )
            .await;
            match next {
                Ok(Ok(next)) => break Some(next),
                Ok(Err(_))
                    if budget
                        .next_round(Some(router), &mut context, deadline)
                        .await => {}
                _ => break None,
            }
        };
        let Some(mut next) = next else {
            break;
        };
        let client = router
            .http_client(&next.name, CookieMode::None)
            .map_err(UpstreamSendError::Egress)?;
        let token = tokio::time::timeout_at(
            tokio::time::Instant::from_std(deadline),
            scope.state.subscription_cache.get_fresh_loaded(
                &client,
                router.provider(),
                &next.name,
                next.token.clone(),
                crate::operation_context::now().timestamp_millis(),
            ),
        )
        .await;
        let Ok(Ok(token)) = token else {
            break;
        };
        next.token = token;
        crate::proxy::note_failover(
            &scope.state,
            correlation,
            attempt,
            Some(&selected.name),
            retry_reason,
        );
        selected = next;
    }
    last_response.ok_or_else(|| {
        UpstreamSendError::Egress("no eligible account within the request retry budget".into())
    })
}

fn replay_model(
    router: &crate::accounts::AccountRouter,
    account: &crate::translation_core::Str,
    requested: &crate::translation_core::Str,
    native: &crate::translation_core::Str,
) -> crate::translation_core::Maybe<String> {
    let resolved = router.upstream_model(account, requested)?;
    if resolved == requested && native != requested {
        (!router.routing_policy(account).ok()?.excluded(native)).then(|| native.to_string())
    } else {
        Some(resolved)
    }
}

fn prepare(
    request: &mut reqwest::Request,
    model: &str,
    moved: bool,
    retrying: bool,
    limit: usize,
    scope: &crate::account_policy_scope::PolicyRequest,
    selected: &crate::accounts::SelectedSubscriptionAccount,
) -> Result<(), UpstreamSendError> {
    let Some(bytes) = request.body().and_then(reqwest::Body::as_bytes) else {
        return Ok(());
    };
    let zstd = request
        .headers()
        .get("content-encoding")
        .is_some_and(|v| v == "zstd");
    let decoded = if zstd {
        use std::io::Read as _;
        let reader = zstd::stream::read::Decoder::new(bytes)
            .map_err(|e| UpstreamSendError::Egress(e.to_string()))?;
        let mut decoded = Vec::new();
        reader
            .take(limit as u64 + 1)
            .read_to_end(&mut decoded)
            .map_err(|e| UpstreamSendError::Egress(e.to_string()))?;
        if decoded.len() > limit {
            return Err(UpstreamSendError::Egress(
                "replayed body exceeds request limit".into(),
            ));
        }
        decoded
    } else {
        bytes.to_vec()
    };
    let Ok(mut body) = serde_json::from_slice::<Value>(&decoded) else {
        return Ok(());
    };
    let original = body.clone();
    if body.get("model").is_some() {
        body["model"] = Value::String(model.to_string());
    }
    if moved {
        crate::pool_failover::strip_anthropic_thinking(&mut body);
        crate::pool_failover::strip_codex_encrypted_reasoning(&mut body);
    }
    if retrying {
        crate::thinking::policy::revalidate(scope, selected, &mut body, model).map_err(
            |reason| {
                *scope
                    .thinking_error
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(reason.clone());
                UpstreamSendError::Egress(reason)
            },
        )?;
    }
    if original == body {
        return Ok(());
    }
    let mut bytes =
        serde_json::to_vec(&body).map_err(|e| UpstreamSendError::Egress(e.to_string()))?;
    if zstd {
        bytes = zstd::encode_all(bytes.as_slice(), 0)
            .map_err(|e| UpstreamSendError::Egress(e.to_string()))?;
    }
    *request.body_mut() = Some(bytes.into());
    request.headers_mut().remove("content-length");
    Ok(())
}

/// Inspect only a bounded prefix, preserving every byte and any transport error.
async fn peek(response: reqwest::Response, deadline: Instant) -> (reqwest::Response, Bytes) {
    let status = response.status();
    let headers = response.headers().clone();
    let version = response.version();
    let url = response.url().clone();
    let mut stream = response.bytes_stream().boxed();
    let mut prefix = BytesMut::new();
    let mut rest = Vec::new();
    while prefix.len() < MAX_ERROR_BYTES {
        let Ok(next) =
            tokio::time::timeout_at(tokio::time::Instant::from_std(deadline), stream.next()).await
        else {
            break;
        };
        match next {
            Some(Ok(chunk)) => {
                let take = chunk.len().min(MAX_ERROR_BYTES - prefix.len());
                prefix.extend_from_slice(&chunk[..take]);
                if take < chunk.len() {
                    rest.push(Ok(chunk.slice(take..)));
                }
            }
            Some(Err(error)) => {
                rest.push(Err(error));
                break;
            }
            None => break,
        }
    }
    let prefix = prefix.freeze();
    let body = reqwest::Body::wrap_stream(
        stream::iter([Ok::<_, reqwest::Error>(prefix.clone())])
            .chain(stream::iter(rest))
            .chain(stream),
    );
    let mut response = http::Response::builder()
        .status(status)
        .version(version)
        .url(url)
        .body(body)
        .expect("valid upstream status");
    *response.headers_mut() = headers;
    (response.into(), prefix)
}

//! Admin-only policy reads and atomic replacements for configured accounts.
use crate::account_routing_policy::AccountRoutingPolicy;
use crate::app_state::AppState;
use axum::extract::{Path, State};
use axum::http::{HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};

/// Return a configured account's current routing policy.
pub async fn get_policy(
    State(state): State<AppState>,
    Path(name): Path<String>,
    headers: HeaderMap,
) -> Response {
    if !crate::proxy::is_admin_authorised(&state, &headers) {
        return denied();
    }
    let Some(router) = &state.account_router else {
        return missing();
    };
    match router.routing_policy(&name) {
        Ok(policy) => axum::Json(policy).into_response(),
        Err(error) => {
            crate::proxy::error_response(StatusCode::NOT_FOUND, "routing_policy_error", &error)
        }
    }
}

/// Validate, persist and immediately apply a complete replacement policy.
pub async fn set_policy(
    State(state): State<AppState>,
    Path(name): Path<String>,
    headers: HeaderMap,
    axum::Json(policy): axum::Json<AccountRoutingPolicy>,
) -> Response {
    if !crate::proxy::is_admin_authorised(&state, &headers) {
        return denied();
    }
    let Some(router) = &state.account_router else {
        return missing();
    };
    if !router
        .subscription_readers()
        .iter()
        .any(|(account, _)| account == &name)
    {
        return missing();
    }
    if let Err(error) = policy.validate() {
        return crate::proxy::error_response(
            StatusCode::BAD_REQUEST,
            "routing_policy_error",
            &error,
        );
    }
    match router.set_routing_policy(&name, policy.clone()) {
        Ok(()) => axum::Json(policy).into_response(),
        Err(error) => crate::proxy::error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "routing_policy_error",
            &error,
        ),
    }
}

fn denied() -> Response {
    crate::proxy::error_response(
        StatusCode::UNAUTHORIZED,
        "authentication_error",
        "admin credential required",
    )
}
fn missing() -> Response {
    crate::proxy::error_response(
        StatusCode::NOT_FOUND,
        "not_found_error",
        "account is not configured",
    )
}

/// The same JSON representation for CLI and management account listings.
pub(crate) fn fields(router: &crate::accounts::AccountRouter, account: &crate::translation_core::Str) -> crate::translation_core::Json {
    match router.routing_policy(account) {
        Ok(policy) => crate::translation_core::json!({"routing_policy": policy}),
        Err(error) => crate::translation_core::json!({"routing_policy_error": error}),
    }
}

//! Resolve visible model identities before authorization; retain the selected account for dispatch.
use crate::account_policy_scope::{PolicyRequest, REQUEST};
use crate::app_state::AppState;
use axum::body::Body;
use axum::extract::{Request, State};
use axum::http::{Method, StatusCode};
use axum::middleware::Next;
use axum::response::Response;
use serde_json::Value;
use std::sync::{Arc, Mutex};

pub async fn route(State(state): State<AppState>, request: Request, next: Next) -> Response {
    let Some(router) = state
        .account_router
        .as_ref()
        .filter(|r| r.has_routing_policy())
    else {
        return next.run(request).await;
    };
    if request.method() != Method::POST {
        return next.run(request).await;
    }
    let path = request.uri().path().to_string();
    let dialect = crate::api_error::dialect_for_path(&path);
    let failure = |status, message: &str| failure(status, message, dialect);
    let json_model_path = path.ends_with("/messages")
        || path.ends_with("/messages/count_tokens")
        || path.ends_with("/chat/completions")
        || path.ends_with("/responses")
        || path.ends_with("/responses/compact")
        || path.ends_with("/invoke")
        || path.ends_with("/invoke-with-response-stream");
    let path_model = path
        .split_once("/models/")
        .and_then(|(_, tail)| tail.rsplit_once(':'))
        .filter(|(_, action)| {
            matches!(
                *action,
                "generateContent"
                    | "streamGenerateContent"
                    | "countTokens"
                    | "rawPredict"
                    | "streamRawPredict"
            )
        })
        .map(|(model, _)| {
            model
                .strip_suffix("/count-tokens")
                .unwrap_or(model)
                .to_string()
        });
    if !json_model_path && path_model.is_none() {
        return next.run(request).await;
    }
    if state.upstream_provider != crate::config::UpstreamProvider::Auto
        && state.upstream_provider.subscription_provider() != Some(router.provider())
    {
        return next.run(request).await;
    }
    let claims = match crate::proxy::authenticate_client_error(&state, request.headers()) {
        Ok(claims) => claims,
        Err(error) => return error.render(crate::api_error::dialect_for_path(&path)),
    };
    let protocol = if path.contains("/publishers/anthropic/models/") {
        crate::client_policy::ClientProtocol::AnthropicMessages
    } else if path.contains("/models/") {
        crate::client_policy::ClientProtocol::GeminiNative
    } else if path.ends_with("/chat/completions") {
        crate::client_policy::ClientProtocol::OpenAIChat
    } else if path.contains("/responses") {
        crate::client_policy::ClientProtocol::OpenAIResponses
    } else {
        crate::client_policy::ClientProtocol::AnthropicMessages
    };
    let (mut parts, body) = request.into_parts();
    let parsed = match crate::encoded_request_body::read_native_json(
        &parts.headers,
        body,
        state.max_proxy_request_bytes,
        path.contains("/codex/") && path.ends_with("/responses"),
    )
    .await
    {
        Ok(parsed) => parsed,
        Err(response) => return response,
    };
    let mut body = parsed.value;
    let requested = match path_model.as_deref() {
        Some(model) => match crate::native_service::percent_decode_segment(model) {
            Some(model) => Some(model),
            None => return failure(StatusCode::BAD_REQUEST, "invalid encoded model selector"),
        },
        None => body
            .get("model")
            .and_then(Value::as_str)
            .map(str::to_string),
    };
    let Some(requested_selector) = requested.filter(|m| !m.is_empty()) else {
        let bytes = parsed.native.encode(&body).unwrap_or_default();
        return next
            .run(Request::from_parts(parts, Body::from(bytes)))
            .await;
    };
    let requested = crate::thinking::base_model(&requested_selector).to_string();
    let pin = match state.token_manager.account_for(&claims.sub) {
        Ok(pin) => pin,
        Err(error) => return failure(StatusCode::SERVICE_UNAVAILABLE, &error.to_string()),
    };
    let mut context = crate::request_routing::request_routing_context(&parts.headers, &body, pin);
    context.model = Some(requested.clone());
    let model_policy = match crate::proxy::model_policy_for_claims(&state, &claims) {
        Ok(policy) => policy,
        Err(error) => return failure(StatusCode::SERVICE_UNAVAILABLE, &error.to_string()),
    };
    // A known alias must never fall through to a guessed native spelling on
    // another account. Its live catalog can prove that spelling is real there.
    let configured_alias = router.subscription_readers().iter().any(|(account, _)| {
        router.routing_policy(account).is_ok_and(|policy| {
            let bare = policy
                .prefix
                .as_ref()
                .and_then(|prefix| requested.strip_prefix(&crate::translation_core::format!("{prefix}/")))
                .unwrap_or(&requested);
            policy.model_aliases.iter().any(|alias| alias.alias == bare)
        })
    });
    let candidates: Vec<_> = router
        .subscription_readers()
        .into_iter()
        .filter(|(name, _)| {
            context
                .pinned_account
                .as_ref()
                .is_none_or(|pin| pin == name)
        })
        .filter_map(|(name, _)| {
            let mut model = router.upstream_model(&name, &requested)?;
            // Anthropic ingress can select a different native model at a pinned bridge.
            if protocol == crate::client_policy::ClientProtocol::AnthropicMessages
                && router.provider() != crate::subscription::SubscriptionProvider::Claude
                && state.upstream_provider != crate::config::UpstreamProvider::Auto
                && model == requested
            {
                model =
                    crate::anthropic_bridge::resolve_bridge_model_for_account(&state, Some(&name))
                        .ok()?;
                if router.routing_policy(&name).ok()?.excluded(&model) {
                    return None;
                }
            }
            let catalog = state.model_catalogs.status_for(router.provider(), &name);
            if router.provider() == crate::subscription::SubscriptionProvider::Gemini
                && !model.starts_with("models/")
                && catalog
                    .routable_models()
                    .contains(&crate::translation_core::format!("models/{model}"))
            {
                model = crate::translation_core::format!("models/{model}");
            }
            let alias = model != requested && !requested.ends_with(&crate::translation_core::format!("/{model}"));
            if (state.upstream_provider == crate::config::UpstreamProvider::Auto
                || alias
                || configured_alias)
                && !catalog.routable_models().contains(&model)
            {
                return None;
            }
            Some((name, model))
        })
        .collect();
    // Policies on one subscription must not intercept another provider in auto mode.
    // Unowned selectors continue through ordinary routing, including compatible
    // provider aliases. Their original selector and token policy remain intact.
    if state.upstream_provider == crate::config::UpstreamProvider::Auto
        && candidates.is_empty()
        && (crate::subscription::SubscriptionProvider::ALL
            .into_iter()
            .any(|provider| {
                provider != router.provider()
                    && state.model_catalogs.models(provider).contains(&requested)
            })
            || (!configured_alias
                && !router.subscription_readers().iter().any(|(account, _)| {
                    let catalog = state.model_catalogs.status_for(router.provider(), account);
                    catalog.routable_models().contains(&requested)
                        || (router.provider() == crate::subscription::SubscriptionProvider::Gemini
                            && catalog
                                .routable_models()
                                .contains(&crate::translation_core::format!("models/{requested}")))
                        || router.routing_policy(account).is_ok_and(|policy| {
                            policy
                                .prefix
                                .as_ref()
                                .is_some_and(|prefix| requested.starts_with(&crate::translation_core::format!("{prefix}/")))
                        })
                })))
    {
        let bytes = parsed.native.encode(&body).unwrap_or_default();
        return next
            .run(Request::from_parts(parts, Body::from(bytes)))
            .await;
    }
    if let Err(response) = crate::client_policy::enforce_subscription_for_claims(
        &state,
        &claims,
        &parts.headers,
        router.provider(),
        protocol,
        &path,
    ) {
        return response;
    }
    if candidates.is_empty() {
        return failure(
            StatusCode::NOT_FOUND,
            "model is excluded, has no matching prefix, or is absent from the account catalog",
        );
    }
    if !candidates.iter().any(|(_, model)| {
        crate::account_policy_catalog::permitted(&model_policy, router.provider(), model)
    }) {
        return failure(
            StatusCode::FORBIDDEN,
            "the credential model policy denies the upstream model",
        );
    }
    let pool = crate::pool_failover::current();
    let retry_deadline = pool.deadline(std::time::Instant::now());
    let mut budget = crate::pool_retry::RetryBudget::new(
        Some(router),
        router.inner_failover_enabled() && context.pinned_account.is_none(),
        pool.max_attempts,
    );
    let selected = loop {
        match router
            .select_subscription_where_authoritative(&context, &state.subscription_cache, |name| {
                candidates.iter().any(|(account, model)| {
                    account == name
                        && crate::account_policy_catalog::permitted(
                            &model_policy,
                            router.provider(),
                            model,
                        )
                        && router.serves_upstream_model(account, model)
                })
            })
            .await
        {
            Ok(selected) => break selected,
            Err(_)
                if budget
                    .next_round(Some(router), &mut context, retry_deadline)
                    .await => {}
            Err(error) => return failure(StatusCode::SERVICE_UNAVAILABLE, &error.to_string()),
        }
    };
    let upstream = candidates
        .iter()
        .find(|(name, _)| name == &selected.name)
        .expect("selected model is eligible")
        .1
        .clone();
    // Resolve grants and aliases with the base identity, retaining the suffix
    // for the protocol handler where explicit body controls take precedence.
    let upstream_selector = crate::translation_core::format!("{upstream}{}", &requested_selector[requested.len()..]);
    if body.get("model").is_some() {
        body["model"] = Value::String(upstream_selector.clone());
    }
    // URI model surfaces are rewritten as well as JSON surfaces.
    if path.contains("/models/") {
        let rewritten = path.replacen(
            &crate::translation_core::format!("/models/{}", path_model.as_deref().unwrap_or(&requested)),
            &crate::translation_core::format!("/models/{upstream_selector}"),
            1,
        );
        let uri = parts
            .uri
            .query()
            .map_or_else(|| rewritten.clone(), |q| crate::translation_core::format!("{rewritten}?{q}"));
        if let Ok(uri) = uri.parse() {
            parts.uri = uri;
        }
    }
    let bytes = match parsed.native.encode(&body) {
        Ok(bytes) => bytes,
        Err(error) => return failure(StatusCode::BAD_REQUEST, &error),
    };
    parts.headers.remove("content-length");
    if upstream != requested {
        parts.headers.remove("accept-encoding");
    }
    let scope = Arc::new(PolicyRequest {
        state,
        headers: parts.headers.clone(),
        context,
        upstream_model: upstream.clone(),
        retry_deadline,
        retry_rounds_used: budget.rounds_used(),
        upstream_selector,
        model_policy,
        last_action: Mutex::new(None),
        selected: Mutex::new(selected),
        thinking: Mutex::new(None),
        thinking_error: Mutex::new(None),
    });
    REQUEST
        .scope(Arc::clone(&scope), async {
            let response = next
                .run(Request::from_parts(parts, Body::from(bytes)))
                .await;
            let thinking_error = scope
                .thinking_error
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .take();
            if let Some(message) = thinking_error {
                return crate::api_error::PresentedError {
                    status: StatusCode::BAD_REQUEST,
                    error_type: "invalid_request_error",
                    message: &message,
                }
                .render(dialect);
            }
            if upstream == requested {
                response
            } else {
                crate::account_policy_response::rewrite(response, &upstream, &requested).await
            }
        })
        .await
}

fn failure(status: StatusCode, message: &crate::translation_core::Str, dialect: crate::api_error::ApiDialect) -> Response {
    crate::api_error::PresentedError {
        status,
        error_type: if status == StatusCode::FORBIDDEN {
            "permission_error"
        } else {
            "routing_policy_error"
        },
        message,
    }
    .render(dialect)
}

//! Rewrite model metadata after the provider's response validation and translation.
use axum::body::Body;
use axum::response::Response;
use bytes::Bytes;
use futures_util::StreamExt;
use serde_json::Value;

const MAX_RESPONSE_BYTES: usize = 32 * 1024 * 1024;
const MAX_EVENT_BYTES: usize = 1024 * 1024;

pub fn rewrite_value(value: &mut Value, upstream: &str, visible: &str) {
    for pointer in [
        "/model",
        "/message/model",
        "/response/model",
        "/modelVersion",
        "/response/modelVersion",
    ] {
        if let Some(model) = value.pointer_mut(pointer)
            && (model.as_str() == Some(upstream)
                || upstream
                    .strip_prefix("models/")
                    .is_some_and(|id| model.as_str() == Some(id)))
        {
            *model = Value::String(visible.to_string());
        }
    }
}

pub async fn rewrite(response: Response, upstream: &crate::translation_core::Str, visible: &crate::translation_core::Str) -> Response {
    if !response.status().is_success() {
        return response;
    }
    let streamed = response
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .is_some_and(|v| v.contains("text/event-stream"));
    let (mut parts, body) = response.into_parts();
    parts.headers.remove("content-length");
    parts.headers.remove("etag");
    if parts
        .headers
        .get("content-encoding")
        .is_some_and(|v| v != "identity")
    {
        return crate::proxy::error_response(
            axum::http::StatusCode::BAD_GATEWAY,
            "routing_policy_error",
            "upstream compression prevents model alias rewriting",
        );
    }
    if !streamed {
        let bytes = match axum::body::to_bytes(body, MAX_RESPONSE_BYTES).await {
            Ok(bytes) => bytes,
            Err(error) => {
                return crate::proxy::error_response(
                    axum::http::StatusCode::BAD_GATEWAY,
                    "routing_policy_error",
                    &error.to_string(),
                );
            }
        };
        let bytes = if let Ok(mut value) = serde_json::from_slice::<Value>(&bytes) {
            rewrite_value(&mut value, upstream, visible);
            serde_json::to_vec(&value).map_or(bytes, Bytes::from)
        } else {
            bytes
        };
        return Response::from_parts(parts, Body::from(bytes));
    }
    let upstream = upstream.to_string();
    let visible = visible.to_string();
    let mut buffer = Vec::new();
    // An explicit EOF item preserves trailing bytes even when the vendor omits
    // the final separator. Bound each pending event, rather than a whole chunk.
    let chunks = body
        .into_data_stream()
        .map(|item| item.map(Some).map_err(std::io::Error::other))
        .chain(futures_util::stream::once(async { Ok(None) }));
    let stream = chunks.map(move |chunk| {
        let mut output = String::new();
        if let Some(chunk) = chunk? {
            for piece in chunk.chunks(16 * 1024) {
                for block in crate::sse::push_blocks(&mut buffer, piece) {
                    if block.len() > MAX_EVENT_BYTES {
                        return Err(std::io::Error::other(
                            "model alias SSE event exceeded 1 MiB",
                        ));
                    }
                    output.push_str(&rewrite_block(&block, &upstream, &visible));
                    output.push_str("\n\n");
                }
                if buffer.len() > MAX_EVENT_BYTES {
                    return Err(std::io::Error::other(
                        "model alias SSE buffer exceeded 1 MiB",
                    ));
                }
            }
        } else if !buffer.is_empty() {
            let block = std::str::from_utf8(&buffer).map_err(std::io::Error::other)?;
            output.push_str(&rewrite_block(block, &upstream, &visible));
            buffer.clear();
        }
        Ok::<_, std::io::Error>(Bytes::from(output))
    });
    Response::from_parts(parts, Body::from_stream(stream))
}

fn rewrite_block(block: &crate::translation_core::Str, upstream: &crate::translation_core::Str, visible: &crate::translation_core::Str) -> String {
    let data = block
        .lines()
        .filter_map(|line| line.strip_prefix("data:"))
        .map(str::trim_start)
        .collect::<Vec<_>>()
        .join("\n");
    let Ok(mut value) = serde_json::from_str::<Value>(&data) else {
        return block.to_string();
    };
    rewrite_value(&mut value, upstream, visible);
    let mut emitted = false;
    block
        .lines()
        .filter_map(|line| {
            if line.starts_with("data:") {
                if emitted {
                    None
                } else {
                    emitted = true;
                    Some(format!("data: {value}"))
                }
            } else {
                Some(line.to_string())
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

#[cfg(test)]
mod tests {
    use super::*;
    #[tokio::test]
    async fn sse_rewriting_handles_fragments_multiline_data_and_unterminated_tail() {
        // Multiline JSON, UTF-8 content and an unterminated final event, split into tiny chunks.
        let source = "event: message_start\r\ndata: {\"message\":\r\ndata: {\"model\":\"native\",\"text\":\"é native\"}}\r\n\r\ndata: {\"model\":\"native\"}";
        let split = source
            .as_bytes()
            .chunks(3)
            .map(|b| Ok::<_, std::io::Error>(bytes::Bytes::copy_from_slice(b)))
            .collect::<Vec<_>>();
        let response = Response::builder()
            .header("content-type", "text/event-stream")
            .body(Body::from_stream(futures_util::stream::iter(split)))
            .unwrap();
        let result = crate::account_policy_response::rewrite(response, "native", "friendly").await;
        let bytes = axum::body::to_bytes(result.into_body(), 4096)
            .await
            .unwrap();
        let output = std::str::from_utf8(&bytes).unwrap();
        assert_eq!(output.matches("friendly").count(), 2, "{output}");
    }
}

//! Request-local policy state. No client header can create or change this scope.
use crate::accounts::{RoutingContext, SelectedSubscriptionAccount};
use crate::app_state::AppState;
use std::sync::{Arc, Mutex};

pub struct PolicyRequest {
    pub state: AppState,
    pub headers: axum::http::HeaderMap,
    pub context: RoutingContext,
    pub upstream_model: String,
    pub retry_deadline: std::time::Instant,
    pub retry_rounds_used: u32,
    pub upstream_selector: String,
    pub model_policy: crate::model_contract::ModelAccessPolicy,
    pub last_action: Mutex<Option<crate::account_routing_policy::ErrorAction>>,
    pub selected: Mutex<SelectedSubscriptionAccount>,
    pub(crate) thinking: Mutex<Option<crate::thinking::policy::RetryControls>>,
    pub(crate) thinking_error: Mutex<Option<String>>,
}

tokio::task_local! { pub static REQUEST: Arc<PolicyRequest>; }

pub fn current() -> Option<Arc<PolicyRequest>> {
    REQUEST.try_with(Arc::clone).ok()
}
pub fn active() -> bool {
    REQUEST.try_with(|_| ()).is_ok()
}
pub fn account() -> Option<String> {
    current().map(|s| {
        s.selected
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .name
            .clone()
    })
}
pub fn preselected(context: &RoutingContext) -> Option<String> {
    context.exclude.is_empty().then(account).flatten()
}

pub fn reactive_refresh_allowed(account: &str) -> bool {
    current().is_none_or(|scope| {
        let selected = scope
            .selected
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        selected.name == account
            && scope
                .last_action
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .is_none()
            && scope
                .state
                .account_router
                .as_ref()
                .and_then(|router| router.routing_policy(account).ok())
                .is_some_and(|policy| policy.request_retry != Some(0))
    })
}

/// Retain the complete refreshed credential generation before its upstream attempt.
pub fn credential(account: &str, token: &crate::subscription::SubscriptionToken) {
    if let Some(scope) = current() {
        let mut selected = scope
            .selected
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if selected.name == account {
            selected.token = token.clone();
        }
    }
}

//! Optional routing rules stored beside each account's vendor credential.

use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;

use axum::http::{HeaderMap, HeaderName, HeaderValue};
use serde::{Deserialize, Serialize};

/// Credential-adjacent file, independent of vendor-owned credential formats.
pub const POLICY_FILE: &str = "routing-policy.json";
/// Positive weights are bounded as in `CLIProxyAPI`; non-positive disables weighted selection.
pub const MAX_WEIGHT: i32 = 1_000_000;
/// Upper bound on an account's retry override.
pub const MAX_RETRIES: u32 = 100;

/// One explicitly configured account model alias.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ModelAlias {
    /// Exact upstream model, which must appear in the account's live catalog.
    #[serde(alias = "name")]
    pub model: String,
    /// Client-facing name.
    pub alias: String,
    /// Keep the upstream name visible as well as the alias.
    #[serde(default)]
    pub fork: bool,
}

/// Action of the first matching request-scoped error rule.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "kebab-case")]
pub enum ErrorAction {
    /// Cool this account and relay the response.
    Cooldown,
    /// Try another eligible account before returning any response bytes.
    RetryNext,
    /// Relay unchanged, suppressing automatic cooldown and retry.
    Relay,
}

/// Upstream status and a literal body substring, evaluated in declaration order.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct RequestScopedError {
    pub status: u16,
    #[serde(rename = "match")]
    pub body_match: String,
    pub action: ErrorAction,
}

/// Backward-compatible per-credential traffic policy.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize, schemars::JsonSchema)]
#[serde(default, deny_unknown_fields)]
pub struct AccountRoutingPolicy {
    pub weight: i32,
    pub prefix: Option<String>,
    pub disable_cooling: bool,
    /// Number of retries after the first attempt. Zero disables retries.
    pub request_retry: Option<u32>,
    pub request_scoped_errors: Vec<RequestScopedError>,
    /// Static values, or `$Header-Name` copies from the reviewed allow-list.
    pub headers: BTreeMap<String, String>,
    pub model_aliases: Vec<ModelAlias>,
    /// Case-sensitive glob patterns: `*` matches any sequence, `?` one character.
    pub excluded_models: Vec<String>,
}

impl Default for AccountRoutingPolicy {
    fn default() -> Self {
        Self {
            weight: 1,
            prefix: None,
            disable_cooling: false,
            request_retry: None,
            request_scoped_errors: Vec::new(),
            headers: BTreeMap::new(),
            model_aliases: Vec::new(),
            excluded_models: Vec::new(),
        }
    }
}

/// The only client fields a `$Header` value may read.
pub const COPY_HEADER_ALLOW_LIST: &[&str] = &[
    "x-request-id",
    "x-correlation-id",
    "traceparent",
    "tracestate",
    "x-claude-code-session-id",
    "x-codex-session-id",
    "x-session-id",
    "session-id",
];

fn permitted_destination(name: &str) -> bool {
    !matches!(
        name,
        "authorization"
            | "proxy-authorization"
            | "cookie"
            | "set-cookie"
            | "x-api-key"
            | "x-goog-api-key"
            | "anthropic-auth-token"
            | "chatgpt-account-id"
            | "host"
            | "connection"
            | "content-length"
            | "content-encoding"
            | "transfer-encoding"
            | "upgrade"
            | "te"
            | "trailer"
            | "proxy-authenticate"
            | "keep-alive"
    ) && !name.starts_with("x-router-")
        && !name.starts_with("x-link-assistant-")
}

impl AccountRoutingPolicy {
    /// Validate before saving or using a policy; invalid files fail closed.
    pub fn validate(&self) -> Result<(), String> {
        if self.weight > MAX_WEIGHT {
            return Err(format!("weight must not exceed {MAX_WEIGHT}"));
        }
        if self.request_retry.is_some_and(|n| n > MAX_RETRIES) {
            return Err(format!("request_retry must not exceed {MAX_RETRIES}"));
        }
        if self
            .prefix
            .as_deref()
            .is_some_and(|p| p.is_empty() || p.contains('/') || p.chars().any(char::is_whitespace))
        {
            return Err("prefix must be a non-empty model path segment".into());
        }
        let mut aliases = BTreeSet::new();
        for entry in &self.model_aliases {
            if entry.model.trim().is_empty()
                || entry.alias.trim().is_empty()
                || entry.alias == entry.model
                || !aliases.insert(&entry.alias)
            {
                return Err("model aliases require non-empty models and unique aliases".into());
            }
        }
        for rule in &self.request_scoped_errors {
            if !(100..=599).contains(&rule.status) || rule.body_match.len() > 16 * 1024 {
                return Err(
                    "error rules require a valid HTTP status and a match of at most 16384 bytes"
                        .into(),
                );
            }
        }
        for (destination, value) in &self.headers {
            let name = HeaderName::from_bytes(destination.as_bytes())
                .map_err(|_| "invalid header name")?;
            if !permitted_destination(name.as_str()) {
                return Err(format!("header {name} is protected"));
            }
            if let Some(source) = value.strip_prefix('$') {
                let source = HeaderName::from_bytes(source.as_bytes())
                    .map_err(|_| "invalid copied header name")?;
                if !COPY_HEADER_ALLOW_LIST.contains(&source.as_str()) {
                    return Err(format!("copying client header {source} is not allowed"));
                }
            } else {
                HeaderValue::from_str(value).map_err(|_| "invalid static header value")?;
            }
        }
        Ok(())
    }

    /// Read the sidecar, defaulting only when it is absent.
    pub fn load(home: &Path) -> Result<Self, String> {
        let bytes = match std::fs::read(home.join(POLICY_FILE)) {
            Ok(bytes) => bytes,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Self::default()),
            Err(e) => return Err(e.to_string()),
        };
        let policy: Self = serde_json::from_slice(&bytes).map_err(|e| e.to_string())?;
        policy.validate()?;
        Ok(policy)
    }

    /// Atomically save a validated policy with private file permissions.
    pub fn save(&self, home: &Path) -> Result<(), String> {
        use std::io::Write as _;
        self.validate()?;
        let mut file = tempfile::NamedTempFile::new_in(home).map_err(|e| e.to_string())?;
        serde_json::to_writer_pretty(&mut file, self).map_err(|e| e.to_string())?;
        file.write_all(b"\n").map_err(|e| e.to_string())?;
        file.as_file().sync_all().map_err(|e| e.to_string())?;
        file.persist(home.join(POLICY_FILE))
            .map_err(|e| e.to_string())?;
        Ok(())
    }

    /// Resolve a visible model to its upstream identity, or reject its prefix/exclusion.
    #[must_use]
    pub fn resolve_model(&self, requested: &str, force_prefix: bool) -> Option<String> {
        let model = if let Some(prefix) = &self.prefix {
            if let Some(model) = requested.strip_prefix(&format!("{prefix}/")) {
                model
            } else if force_prefix {
                return None;
            } else {
                requested
            }
        } else {
            requested
        };
        let upstream = self
            .model_aliases
            .iter()
            .find(|a| a.alias == model)
            .map_or(model, |a| a.model.as_str());
        // Retain the original spelling when any alias explicitly forks it.
        if upstream == model
            && self.model_aliases.iter().any(|a| a.model == model)
            && !self
                .model_aliases
                .iter()
                .any(|a| a.model == model && a.fork)
        {
            return None;
        }
        (!model.is_empty()
            && !self.excluded(upstream)
            && !self.excluded(model)
            && !self.excluded(requested))
        .then(|| upstream.to_string())
    }

    /// Visible spellings of a live upstream model; aliases never invent catalog entries.
    #[must_use]
    pub fn visible_models(&self, upstream: &str, force_prefix: bool) -> Vec<String> {
        if self.excluded(upstream) {
            return Vec::new();
        }
        let aliases: Vec<_> = self
            .model_aliases
            .iter()
            .filter(|a| a.model == upstream)
            .collect();
        let mut models = aliases.iter().map(|a| a.alias.clone()).collect::<Vec<_>>();
        if aliases.is_empty() || aliases.iter().any(|a| a.fork) {
            models.push(upstream.to_string());
        }
        let mut visible = Vec::new();
        for model in models {
            if self.excluded(&model) {
                continue;
            }
            if !force_prefix || self.prefix.is_none() {
                visible.push(model.clone());
            }
            if let Some(prefix) = &self.prefix {
                let prefixed = format!("{prefix}/{model}");
                if !self.excluded(&prefixed) {
                    visible.push(prefixed);
                }
            }
        }
        visible
    }

    #[must_use]
    pub fn excluded(&self, model: &str) -> bool {
        self.excluded_models
            .iter()
            .any(|pattern| wildcard_match(pattern, model))
    }

    /// Copy only reviewed fields, after upstream authentication has been installed.
    pub fn apply_headers(&self, incoming: &HeaderMap, outgoing: &mut HeaderMap) {
        for (name, value) in &self.headers {
            let Ok(name) = HeaderName::from_bytes(name.as_bytes()) else {
                continue;
            };
            if !permitted_destination(name.as_str()) {
                continue;
            }
            let value = if let Some(source) = value.strip_prefix('$') {
                let source = source.to_ascii_lowercase();
                if !COPY_HEADER_ALLOW_LIST.contains(&source.as_str()) {
                    continue;
                }
                incoming.get(&source).cloned()
            } else {
                HeaderValue::from_str(value).ok()
            };
            if let Some(value) = value {
                outgoing.insert(name, value);
            }
        }
    }

    /// First rule whose status and literal UTF-8 bytes match the bounded upstream prefix.
    #[must_use]
    pub fn error_action(&self, status: u16, body: &[u8]) -> Option<ErrorAction> {
        self.request_scoped_errors
            .iter()
            .find(|rule| {
                rule.status == status
                    && (rule.body_match.is_empty()
                        || body
                            .windows(rule.body_match.len())
                            .any(|part| part == rule.body_match.as_bytes()))
            })
            .map(|rule| rule.action)
    }
}

/// Linear-space glob matching; finite input and no recursive backtracking.
#[must_use]
pub fn wildcard_match(pattern: &str, value: &str) -> bool {
    let chars: Vec<_> = value.chars().collect();
    let mut previous = vec![false; chars.len() + 1];
    previous[0] = true;
    for token in pattern.chars() {
        let mut next = vec![false; chars.len() + 1];
        next[0] = token == '*' && previous[0];
        for (i, ch) in chars.iter().enumerate() {
            next[i + 1] = match token {
                '*' => previous[i + 1] || next[i],
                '?' => previous[i],
                literal => previous[i] && literal == *ch,
            };
        }
        previous = next;
    }
    previous[chars.len()]
}

//! Configuration loading errors, re-exported by `config`.

/// Errors that can occur during configuration loading.
#[derive(Debug)]
pub enum ConfigError {
    /// `ROUTER_PORT` is not a valid port number.
    InvalidPort,
    /// Management access settings were invalid.
    InvalidManagementSecurity(String),
    /// Operator model catalog configuration was invalid.
    InvalidModelCatalogSources(String),
    /// The listen address could not be parsed.
    InvalidAddress,
    /// `ROUTER_HOST` was neither an IP literal nor a resolvable safe alias.
    InvalidListenHost(String),
    /// `TOKEN_SECRET` environment variable is missing or empty.
    MissingTokenSecret,
    /// `TOKEN_SECRET_FILE` was set and could not supply a secret (issue #684).
    TokenSecretFile(String),
    /// Routing mode was not recognised.
    InvalidRoutingMode,
    /// Upstream API format was not recognised.
    InvalidApiFormat,
    /// Storage policy was not recognised.
    InvalidStoragePolicy,
    /// Upstream provider was not recognised.
    InvalidUpstreamProvider,
    /// The bridge model selection policy was not recognised.
    InvalidBridgeModelPolicy(String),
    /// A consumer-subscription bridge override was not an exact reviewed cell.
    InvalidSubscriptionBridgePolicy(String),
    /// A proxied-client override did not name a reviewed proxy contract.
    InvalidProxiedClientPolicy(String),
    /// An additional primary listener did not use the documented grammar.
    InvalidPrimaryListener(String),
    /// The multi-account strategy was not recognised.
    InvalidAccountRoutingStrategy,
    /// An account request cap was not a non-negative integer.
    InvalidAccountRequestLimits,
    /// Request caps did not align with primary plus additional accounts.
    MismatchedAccountRequestLimits,
    /// Gonka was selected without a broker/API key.
    MissingGonkaApiKey,
    /// Broker/API-key mode was enabled without an explicit broker URL.
    MissingGonkaSourceUrl,
    /// Direct-wallet signing is not implemented according to the official protocol.
    UnsupportedGonkaDirectWallet,
    /// Crater was selected without `CRATER_FORGEFED_INBOX`.
    MissingCraterForgeFedInbox,
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidPort => write!(f, "ROUTER_PORT must be a valid port number (0-65535)"),
            Self::InvalidAddress => write!(f, "Could not parse listen address"),
            Self::InvalidListenHost(host) => write!(
                f,
                "ROUTER_HOST {host:?} did not resolve to a concrete listen address"
            ),
            Self::MissingTokenSecret => {
                write!(f, "TOKEN_SECRET environment variable is required")
            }
            Self::InvalidRoutingMode => {
                write!(f, "ROUTING_MODE must be one of: direct, cli, hybrid")
            }
            Self::InvalidApiFormat => write!(
                f,
                "UPSTREAM_API_FORMAT must be one of: anthropic, bedrock, vertex"
            ),
            Self::InvalidStoragePolicy => write!(
                f,
                "STORAGE_POLICY must be one of: memory, text, binary, both"
            ),
            Self::InvalidUpstreamProvider => write!(
                f,
                "UPSTREAM_PROVIDER must be one of: auto, anthropic, codex, gemini, qwen, gonka, crater, openai-compatible"
            ),
            Self::InvalidManagementSecurity(message)
            | Self::InvalidModelCatalogSources(message)
            | Self::InvalidBridgeModelPolicy(message)
            | Self::InvalidSubscriptionBridgePolicy(message)
            | Self::InvalidProxiedClientPolicy(message)
            | Self::InvalidPrimaryListener(message)
            | Self::TokenSecretFile(message) => write!(f, "{message}"),
            Self::InvalidAccountRoutingStrategy => write!(
                f,
                "ACCOUNT_ROUTING_STRATEGY must be one of: round-robin, weighted-round-robin, fill-first, least-used"
            ),
            Self::InvalidAccountRequestLimits => write!(
                f,
                "ACCOUNT_REQUEST_LIMITS must be comma-separated non-negative integers"
            ),
            Self::MismatchedAccountRequestLimits => write!(
                f,
                "ACCOUNT_REQUEST_LIMITS must contain one entry for primary and each additional account"
            ),
            Self::MissingGonkaApiKey => write!(f, "Gonka broker mode requires GONKA_API_KEY"),
            Self::MissingGonkaSourceUrl => write!(
                f,
                "Gonka broker mode requires an explicit GONKA_SOURCE_URL; official direct-wallet node endpoints are not API-key broker defaults"
            ),
            Self::UnsupportedGonkaDirectWallet => write!(
                f,
                "GONKA_PRIVATE_KEY direct-wallet mode is unsupported because Router does not implement Gonka's official endpoint-resolution and secp256k1 signing protocol; configure a broker with GONKA_API_KEY instead"
            ),
            Self::MissingCraterForgeFedInbox => {
                write!(f, "Crater provider requires CRATER_FORGEFED_INBOX")
            }
        }
    }
}

impl std::error::Error for ConfigError {}

//! Bounded, instance-wide failed-management-authentication tracking.
use std::collections::BTreeMap;
use std::net::IpAddr;
use std::path::{Path, PathBuf};
use std::sync::{Mutex, OnceLock};
use std::time::{Duration, Instant};

use crate::management_config::ManagementConfig;

const MAX_CLIENTS: usize = 4096;
const SNAPSHOT: &crate::translation_core::Str = "management-lockouts.lenv";

/// An active ban's diagnostic view. No credential material is retained.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct ManagementBan {
    /// Canonical socket peer address.
    pub client_ip: IpAddr,
    /// Wall-clock expiry for diagnostics; enforcement uses monotonic time.
    pub expires_at: u64,
}

#[derive(Debug)]
struct Attempt {
    failures: u32,
    last_failure: Instant,
    banned_at: Option<Instant>,
    expires_at: u64,
}

impl Attempt {
    fn remaining(&self, now: Instant, window: Duration) -> crate::translation_core::Maybe<u64> {
        let elapsed = now.saturating_duration_since(self.banned_at?);
        let remaining = window.checked_sub(elapsed)?;
        (!remaining.is_zero()).then(|| {
            remaining
                .as_secs()
                .saturating_add(u64::from(remaining.subsec_nanos() > 0))
        })
    }

    fn expired(&self, now: Instant, window: Duration) -> bool {
        self.banned_at.map_or_else(
            || now.saturating_duration_since(self.last_failure) >= window,
            |_| self.remaining(now, window).is_none(),
        )
    }
}

/// Consecutive failures and bans shared by every management listener.
#[derive(Debug)]
pub struct ManagementAccess {
    config: OnceLock<ManagementConfig>,
    attempts: Mutex<BTreeMap<IpAddr, Attempt>>,
    snapshot: Option<PathBuf>,
}

impl ManagementAccess {
    /// Initialize inert state; reading an admin claim never changes diagnostics.
    #[must_use]
    pub fn new(data_dir: &Path) -> Self {
        Self {
            config: OnceLock::new(),
            attempts: Mutex::new(BTreeMap::new()),
            snapshot: Some(data_dir.join(SNAPSHOT)),
        }
    }

    /// An in-memory tracker with no diagnostic file writes.
    #[must_use]
    pub const fn in_memory() -> Self {
        Self {
            config: OnceLock::new(),
            attempts: Mutex::new(BTreeMap::new()),
            snapshot: None,
        }
    }

    /// Select the instance's policy once, before serving its listeners.
    pub fn configure(&self, config: ManagementConfig) {
        if self.config.set(config).is_ok() {
            self.save(&BTreeMap::new());
        }
    }

    /// Current policy, defaulting to local-only management and local recovery.
    #[must_use]
    pub fn config(&self) -> ManagementConfig {
        self.config.get().copied().unwrap_or_default()
    }

    fn exempt(&self, ip: IpAddr) -> bool {
        let config = self.config();
        config.lockout_failures == 0
            || config.lockout_secs == 0
            || (config.exempt_loopback && ip.is_loopback())
    }

    /// Remaining ban seconds, or a capacity backoff for a new untracked IP.
    pub fn check(&self, ip: IpAddr) -> crate::translation_core::Maybe<u64> {
        self.check_at(normalize_ip(ip), Instant::now())
    }

    fn check_at(&self, ip: IpAddr, now: Instant) -> crate::translation_core::Maybe<u64> {
        if self.exempt(ip) {
            return None;
        }
        let window = Duration::from_secs(self.config().lockout_secs);
        let mut attempts = self
            .attempts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if attempts
            .get(&ip)
            .is_some_and(|entry| entry.expired(now, window))
        {
            let was_banned = attempts
                .remove(&ip)
                .is_some_and(|entry| entry.banned_at.is_some());
            if was_banned {
                self.save(&attempts);
            }
        }
        if let Some(entry) = attempts.get(&ip) {
            return entry.remaining(now, window);
        }
        if attempts.len() >= MAX_CLIENTS {
            let previous_len = attempts.len();
            attempts.retain(|_, entry| !entry.expired(now, window));
            if attempts.len() != previous_len {
                self.save(&attempts);
            }
            if attempts.len() >= MAX_CLIENTS {
                return Some(1);
            }
        }
        None
    }

    /// Record a failed credential. Returns a newly-created ban for auditing.
    pub fn failure(&self, ip: IpAddr) -> crate::translation_core::Maybe<ManagementBan> {
        self.failure_at(normalize_ip(ip), Instant::now())
    }

    fn failure_at(&self, ip: IpAddr, now: Instant) -> crate::translation_core::Maybe<ManagementBan> {
        if self.exempt(ip) {
            return None;
        }
        let config = self.config();
        let window = Duration::from_secs(config.lockout_secs);
        let mut attempts = self
            .attempts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if !attempts.contains_key(&ip) && attempts.len() >= MAX_CLIENTS {
            return None;
        }
        let entry = attempts.entry(ip).or_insert(Attempt {
            failures: 0,
            last_failure: now,
            banned_at: None,
            expires_at: 0,
        });
        if entry.expired(now, window) {
            entry.failures = 0;
            entry.banned_at = None;
        }
        if entry.banned_at.is_some() {
            return None;
        }
        entry.failures = entry.failures.saturating_add(1);
        entry.last_failure = now;
        if entry.failures < config.lockout_failures {
            return None;
        }
        entry.banned_at = Some(now);
        entry.expires_at = unix_now().saturating_add(config.lockout_secs);
        let ban = ManagementBan {
            client_ip: ip,
            expires_at: entry.expires_at,
        };
        self.save(&attempts);
        drop(attempts);
        Some(ban)
    }

    /// Successful authentication clears failures, never an active ban.
    pub fn success(&self, ip: IpAddr) {
        let mut attempts = self
            .attempts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let ip = normalize_ip(ip);
        if attempts
            .get(&ip)
            .is_some_and(|entry| entry.banned_at.is_none())
        {
            attempts.remove(&ip);
        }
    }

    /// Snapshot currently active bans from the authoritative in-memory state.
    pub fn active_bans(&self) -> Vec<ManagementBan> {
        let mut attempts = self
            .attempts
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let now = Instant::now();
        let window = Duration::from_secs(self.config().lockout_secs);
        attempts.retain(|_, entry| !entry.expired(now, window));
        let bans = Self::bans(&attempts);
        drop(attempts);
        bans
    }

    fn bans(attempts: &BTreeMap<IpAddr, Attempt>) -> Vec<ManagementBan> {
        attempts
            .iter()
            .filter(|(_, entry)| entry.banned_at.is_some())
            .map(|(&client_ip, entry)| ManagementBan {
                client_ip,
                expires_at: entry.expires_at,
            })
            .collect()
    }

    fn save(&self, attempts: &BTreeMap<IpAddr, Attempt>) {
        let Some(snapshot) = &self.snapshot else {
            return;
        };
        let bans = Self::bans(attempts);
        let result = if bans.is_empty() {
            std::fs::remove_file(snapshot).or_else(|error| {
                if error.kind() == std::io::ErrorKind::NotFound {
                    Ok(())
                } else {
                    Err(error)
                }
            })
        } else {
            crate::lino_json::encode(&bans)
                .map_err(std::io::Error::other)
                .and_then(|text| {
                    crate::durable_file::atomic_write_owner_only(snapshot, text.as_bytes())
                })
        };
        if let Err(error) = result {
            tracing::warn!("could not write management ban diagnostics: {error}");
        }
    }
}

/// Normalize IPv4-mapped IPv6 so one client cannot gain a second identity.
#[must_use]
pub fn normalize_ip(ip: IpAddr) -> IpAddr {
    match ip {
        IpAddr::V6(ip) => ip.to_ipv4_mapped().map_or(IpAddr::V6(ip), IpAddr::V4),
        ip @ IpAddr::V4(_) => ip,
    }
}

fn unix_now() -> u64 {
    u64::try_from(crate::operation_context::now().timestamp()).unwrap_or(0)
}

/// Report unexpired diagnostic snapshots in every selected deployment root.
#[must_use]
pub fn doctor_report(data_dirs: &[PathBuf]) -> String {
    use std::fmt::Write as _;
    let mut report = String::new();
    for dir in data_dirs {
        let bans: Vec<ManagementBan> = std::fs::read_to_string(dir.join(SNAPSHOT))
            .ok()
            .and_then(|text| crate::lino_json::decode(&text).ok())
            .unwrap_or_default();
        for ban in bans.into_iter().filter(|ban| ban.expires_at > unix_now()) {
            let _ = writeln!(
                report,
                "management_ban         : ip={} retry_after={}s data_dir={}",
                ban.client_ip,
                ban.expires_at.saturating_sub(unix_now()),
                dir.display()
            );
        }
    }
    report
}

